--
-- Name: accrue_salary_paid_on_approve(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.accrue_salary_paid_on_approve() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_take_home numeric;
  v_period date;
  v_sm_id uuid;
begin
  -- Chỉ quan tâm phiếu CHI LƯƠNG (gắn nhân viên hưởng lương).
  if new.salary_staff_id is null then
    return new;
  end if;

  -- ── Trở thành APPROVED ──────────────────────────────────────────────
  if new.approval_status = 'APPROVED'
     and coalesce(old.approval_status,'') is distinct from 'APPROVED' then

    -- "Tiền thực nhận": ưu tiên dòng item có tên đó (phiếu tách 2 dòng khi gạch
    -- nợ tiền phòng); không có → tổng phiếu.
    select coalesce(
             (select sum(it.amount) from public.income_expense_items it
               where it.income_expense_id = new.id
                 and it.description = 'Tiền thực nhận'),
             new.total_amount, 0)
      into v_take_home;

    -- KỲ LƯƠNG — nguồn đúng là DẤU payout_voucher_id do writer đóng lúc submit
    -- (chi-trước lương tháng sau: voucher_date KHÔNG suy ra được kỳ — bug bắt được
    -- test B2 2026-07-19: phiếu kỳ 08 trả ngày 19/07 bị gạch nhầm kỳ 06).
    -- Fallback heuristic theo voucher_date CHỈ cho phiếu legacy (không có dấu).
    select id into v_sm_id from public.salary_monthly
     where payout_voucher_id = new.id limit 1;
    if v_sm_id is null then
      select id into v_sm_id
        from public.salary_monthly
       where staff_id = new.salary_staff_id
         and period_month <= date_trunc('month', new.voucher_date)::date
       order by period_month desc
       limit 1;
    end if;

    if v_sm_id is not null then
      -- Chuyển-trạng-thái thuần: mỗi lần VÀO APPROVED cộng đúng 1 lần (WHEN đã
      -- chặn APPROVED→APPROVED). Stamp chỉ bổ sung khi trống (phiếu legacy).
      update public.salary_monthly
         set paid = coalesce(paid,0) + coalesce(v_take_home,0),
             payout_voucher_id = coalesce(payout_voucher_id, new.id)
       where id = v_sm_id;
    end if;
    return new;
  end if;

  -- ── Rời APPROVED (bỏ duyệt / huỷ): trừ lại — đối xứng với nhánh cộng ──
  if coalesce(old.approval_status,'') = 'APPROVED'
     and new.approval_status is distinct from 'APPROVED' then
    select coalesce(
             (select sum(it.amount) from public.income_expense_items it
               where it.income_expense_id = new.id
                 and it.description = 'Tiền thực nhận'),
             new.total_amount, 0)
      into v_take_home;
    -- Trừ trên CÙNG row nhánh cộng đã chọn: ưu tiên DẤU, fallback heuristic.
    -- KHÔNG xoá dấu (writer sở hữu linkage; trigger chỉ mirror tiền) — nhờ đó
    -- duyệt lại sau khi bỏ duyệt vẫn tìm đúng kỳ.
    select id into v_sm_id from public.salary_monthly
     where payout_voucher_id = new.id limit 1;
    if v_sm_id is null then
      select id into v_sm_id
        from public.salary_monthly
       where staff_id = new.salary_staff_id
         and period_month <= date_trunc('month', new.voucher_date)::date
       order by period_month desc
       limit 1;
    end if;
    if v_sm_id is not null then
      update public.salary_monthly
         set paid = greatest(coalesce(paid,0) - coalesce(v_take_home,0), 0)
       where id = v_sm_id;
    end if;
    return new;
  end if;

  return new;
end;
$$;








--
-- Name: all_allowed_keys_v3(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.all_allowed_keys_v3() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  with mem as (
    select m.id, m.organization_id
      from public.organization_memberships m
      join public.organizations o
        on o.id = m.organization_id and o.status = 'ACTIVE'
     where m.user_id = (select auth.uid())
       and m.status = 'ACTIVE'
       and coalesce(m.valid_from, '-infinity'::timestamptz) <= now()
       and (m.valid_to is null or m.valid_to > now())
  ),
  -- Cạnh CHO từ vai trò
  role_allow as (
    select rp.permission_key, s.scope_type, s.cashbook_id, m.id as membership_id
      from mem m
      join public.role_bindings rb
        on rb.membership_id = m.id
       and coalesce(rb.valid_from, '-infinity'::timestamptz) <= now()
       and (rb.valid_to is null or rb.valid_to > now())
      join public.organization_roles orl
        on orl.id = rb.role_id and coalesce(orl.status, 'ACTIVE') = 'ACTIVE'
      join public.role_permissions rp
        on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
       and rp.effect = 'ALLOW'
      join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
      join public.authorization_scopes s on s.id = rbs.scope_id
  ),
  -- Cạnh CHO từ ngoại lệ riêng
  ov_allow as (
    select o.permission_key, s.scope_type, s.cashbook_id, m.id as membership_id
      from mem m
      join public.member_permission_overrides o
        on o.membership_id = m.id and o.revoked_at is null and o.effect = 'ALLOW'
       and (o.expires_at is null or o.expires_at > now())
      join public.member_override_scopes mos on mos.override_id = o.id
      join public.authorization_scopes s on s.id = mos.scope_id
  ),
  allow_edge as (
    select * from role_allow union all select * from ov_allow
  ),
  -- CẤM ở phạm vi toàn tổ chức thì triệt tiêu hoàn toàn khoá đó
  deny_org as (
    select rp.permission_key
      from mem m
      join public.role_bindings rb on rb.membership_id = m.id and rb.valid_to is null
      join public.role_permissions rp
        on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
       and rp.effect = 'DENY'
      join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
      join public.authorization_scopes s
        on s.id = rbs.scope_id and s.scope_type = 'ORGANIZATION'
    union
    select o.permission_key
      from mem m
      join public.member_permission_overrides o
        on o.membership_id = m.id and o.revoked_at is null and o.effect = 'DENY'
       and (o.expires_at is null or o.expires_at > now())
      join public.member_override_scopes mos on mos.override_id = o.id
      join public.authorization_scopes s
        on s.id = mos.scope_id and s.scope_type = 'ORGANIZATION'
  ),
  cam_khan_cap as (
    select d.permission_key
      from app_private.tenant_emergency_denies d
      join mem m on m.organization_id = d.organization_id
     where d.active_from <= now()
       and (d.expires_at is null or d.expires_at > now())
  )
  select coalesce(array_agg(distinct pd.key), '{}'::text[])
    from public.permission_definitions pd
    join allow_edge e on e.permission_key = pd.key
   where pd.permission_domain = 'TENANT'
     and pd.is_active
     and e.scope_type = any (pd.scope_kinds)
     -- Quyền cần giữ sổ: chỉ cạnh CASHBOOK mà mình đang thực sự giữ mới tính
     and (not pd.requires_cashbook_possession
          or (e.scope_type = 'CASHBOOK' and exists (
                select 1 from public.cashbook_possession_bindings cp
                 where cp.membership_id = e.membership_id
                   and cp.cashbook_id = e.cashbook_id
                   and cp.possession_kind = any (pd.accepted_possession_kinds)
                   and cp.valid_from <= now()
                   and (cp.valid_to is null or cp.valid_to > now()))))
     and pd.key not in (select permission_key from deny_org)
     and not exists (select 1 from cam_khan_cap c
                      where c.permission_key is null or c.permission_key = pd.key);
$$;








--
-- Name: allocate_finance_collection_components_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.allocate_finance_collection_components_v1(p_collection_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_collection record;
  v_manifest record;
  v_prior_applied numeric := 0;
  v_prior_allocated numeric := 0;
  v_positive_component_count integer := 0;
  v_remaining_capacity numeric := 0;
  v_left numeric := 0;
  v_component record;
  v_already_allocated numeric;
  v_amount numeric;
BEGIN
  IF p_collection_id IS NULL THEN
    RETURN;
  END IF;

  SELECT collection_row.id,
         collection_row.organization_id,
         collection_row.invoice_id,
         collection_row.applied_amount,
         collection_row.status,
         collection_row.created_at
    INTO v_collection
  FROM public.invoice_payment_collections collection_row
  WHERE collection_row.id = p_collection_id
  FOR SHARE;
  IF NOT FOUND OR v_collection.status <> 'ACTIVE' THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('invoice-component-allocation:' || v_collection.invoice_id::text, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.finance_invoice_component_allocations allocation
    WHERE allocation.collection_id = p_collection_id
  ) THEN
    RETURN;
  END IF;

  SELECT manifest.id,
         manifest.component_status,
         manifest.finalized_at
    INTO v_manifest
  FROM public.finance_invoice_component_manifests manifest
  WHERE manifest.invoice_id = v_collection.invoice_id
  FOR SHARE;
  IF NOT FOUND
     OR v_manifest.component_status <> 'COMPLETE'
     OR v_manifest.finalized_at IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*)::integer
    INTO v_positive_component_count
  FROM public.finance_invoice_components component
  WHERE component.manifest_id = v_manifest.id
    AND component.amount > 0;

  SELECT COALESCE(sum(prior.applied_amount), 0)
    INTO v_prior_applied
  FROM public.invoice_payment_collections prior
  WHERE prior.invoice_id = v_collection.invoice_id
    AND prior.status = 'ACTIVE'
    AND (prior.created_at, prior.id) < (v_collection.created_at, v_collection.id);

  SELECT COALESCE(sum(allocation.amount), 0)
    INTO v_prior_allocated
  FROM public.finance_invoice_component_allocations allocation
  JOIN public.invoice_payment_collections prior
    ON prior.id = allocation.collection_id
   AND prior.status = 'ACTIVE'
  WHERE allocation.invoice_id = v_collection.invoice_id;

  -- Oldest carried invoice debt -> current charges -> deposit debt -> internal.
  -- If a historical multi-component payment has no ledger allocation, preserve
  -- allocation_unknown instead of guessing how the old money was distributed.
  IF v_positive_component_count > 1
     AND abs(v_prior_applied - v_prior_allocated) >= 0.01 THEN
    RETURN;
  END IF;

  SELECT COALESCE(sum(GREATEST(component.amount - COALESCE(active_allocated.amount, 0), 0)), 0)
    INTO v_remaining_capacity
  FROM public.finance_invoice_components component
  LEFT JOIN LATERAL (
    SELECT sum(allocation.amount) AS amount
    FROM public.finance_invoice_component_allocations allocation
    JOIN public.invoice_payment_collections active_collection
      ON active_collection.id = allocation.collection_id
     AND active_collection.status = 'ACTIVE'
    WHERE allocation.component_id = component.id
  ) active_allocated ON true
  WHERE component.manifest_id = v_manifest.id;

  IF v_collection.applied_amount <= 0
     OR v_remaining_capacity + 0.01 < v_collection.applied_amount THEN
    RETURN;
  END IF;

  v_left := v_collection.applied_amount;
  FOR v_component IN
    SELECT component.id, component.amount, component.component_order
    FROM public.finance_invoice_components component
    WHERE component.manifest_id = v_manifest.id
    ORDER BY component.component_order, component.id
  LOOP
    SELECT COALESCE(sum(allocation.amount), 0)
      INTO v_already_allocated
    FROM public.finance_invoice_component_allocations allocation
    JOIN public.invoice_payment_collections active_collection
      ON active_collection.id = allocation.collection_id
     AND active_collection.status = 'ACTIVE'
    WHERE allocation.component_id = v_component.id;

    v_amount := LEAST(v_left, GREATEST(v_component.amount - v_already_allocated, 0));
    IF v_amount > 0 THEN
      INSERT INTO public.finance_invoice_component_allocations (
        organization_id,
        collection_id,
        invoice_id,
        component_id,
        amount,
        allocation_version
      ) VALUES (
        v_collection.organization_id,
        v_collection.id,
        v_collection.invoice_id,
        v_component.id,
        v_amount,
        1
      );
      v_left := v_left - v_amount;
    END IF;
    EXIT WHEN v_left < 0.01;
  END LOOP;
END;
$$;








--
-- Name: allowed_keys_for_membership_v3(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.allowed_keys_for_membership_v3(p_membership uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  with mem as (
    select m.id, m.organization_id
      from public.organization_memberships m
      join public.organizations o
        on o.id = m.organization_id and o.status = 'ACTIVE'
     where m.id = p_membership
       and m.status = 'ACTIVE'
       and coalesce(m.valid_from, '-infinity'::timestamptz) <= now()
       and (m.valid_to is null or m.valid_to > now())
  ),
  role_allow as (
    select rp.permission_key, s.scope_type, s.cashbook_id, m.id as membership_id
      from mem m
      join public.role_bindings rb
        on rb.membership_id = m.id
       and coalesce(rb.valid_from, '-infinity'::timestamptz) <= now()
       and (rb.valid_to is null or rb.valid_to > now())
      join public.organization_roles orl
        on orl.id = rb.role_id and coalesce(orl.status, 'ACTIVE') = 'ACTIVE'
      join public.role_permissions rp
        on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
       and rp.effect = 'ALLOW'
      join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
      join public.authorization_scopes s on s.id = rbs.scope_id
  ),
  ov_allow as (
    select o.permission_key, s.scope_type, s.cashbook_id, m.id as membership_id
      from mem m
      join public.member_permission_overrides o
        on o.membership_id = m.id and o.revoked_at is null and o.effect = 'ALLOW'
       and (o.expires_at is null or o.expires_at > now())
      join public.member_override_scopes mos on mos.override_id = o.id
      join public.authorization_scopes s on s.id = mos.scope_id
  ),
  allow_edge as (select * from role_allow union all select * from ov_allow),
  deny_org as (
    select rp.permission_key
      from mem m
      join public.role_bindings rb on rb.membership_id = m.id and rb.valid_to is null
      join public.role_permissions rp
        on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
       and rp.effect = 'DENY'
      join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
      join public.authorization_scopes s
        on s.id = rbs.scope_id and s.scope_type = 'ORGANIZATION'
    union
    select o.permission_key
      from mem m
      join public.member_permission_overrides o
        on o.membership_id = m.id and o.revoked_at is null and o.effect = 'DENY'
       and (o.expires_at is null or o.expires_at > now())
      join public.member_override_scopes mos on mos.override_id = o.id
      join public.authorization_scopes s
        on s.id = mos.scope_id and s.scope_type = 'ORGANIZATION'
  ),
  cam_khan_cap as (
    select d.permission_key
      from app_private.tenant_emergency_denies d
      join mem m on m.organization_id = d.organization_id
     where d.active_from <= now()
       and (d.expires_at is null or d.expires_at > now())
  )
  select coalesce(array_agg(distinct pd.key), '{}'::text[])
    from public.permission_definitions pd
    join allow_edge e on e.permission_key = pd.key
   where pd.permission_domain = 'TENANT'
     and pd.is_active
     and e.scope_type = any (pd.scope_kinds)
     and (not pd.requires_cashbook_possession
          or (e.scope_type = 'CASHBOOK' and exists (
                select 1 from public.cashbook_possession_bindings cp
                 where cp.membership_id = e.membership_id
                   and cp.cashbook_id = e.cashbook_id
                   and cp.possession_kind = any (pd.accepted_possession_kinds)
                   and cp.valid_from <= now()
                   and (cp.valid_to is null or cp.valid_to > now()))))
     and pd.key not in (select permission_key from deny_org)
     and not exists (select 1 from cam_khan_cap c
                      where c.permission_key is null or c.permission_key = pd.key);
$$;








--
-- Name: append_authz_audit_v1(uuid, text, text, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.append_authz_audit_v1(p_organization_id uuid, p_event_type text, p_resource_type text, p_resource_id uuid, p_old_state jsonb DEFAULT NULL::jsonb, p_new_state jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private', 'extensions'
    AS $$
declare
  v_id        uuid := gen_random_uuid();
  v_actor     uuid := (select auth.uid());
  v_membership uuid;
  v_prev      text;
  v_at        timestamptz := clock_timestamp();
  v_payload   text;
  v_hash      text;
begin
  if p_organization_id is null then
    raise exception 'Thiếu tổ chức khi ghi nhật ký phân quyền' using errcode = '22023';
  end if;
  if p_event_type is null or btrim(p_event_type) = '' then
    raise exception 'Thiếu loại sự kiện khi ghi nhật ký phân quyền' using errcode = '22023';
  end if;

  -- Tuần tự hoá theo tổ chức để chuỗi hash không rẽ nhánh.
  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text, 0));

  select m.id into v_membership
    from public.organization_memberships m
   where m.user_id = v_actor
     and m.organization_id = p_organization_id
     and m.status = 'ACTIVE'
   limit 1;

  -- Mắt xích trước trong CÙNG tổ chức. Dòng đầu tiên có prev_hash = NULL.
  select a.event_hash into v_prev
    from public.authorization_audit_events a
   where a.organization_id = p_organization_id
   order by a.occurred_at desc, a.id desc
   limit 1;

  -- Nội dung băm: gắn chặt vào mọi trường có ý nghĩa audit, kèm mắt xích trước.
  v_payload :=
       coalesce(v_prev, '')
    || '|' || p_organization_id::text
    || '|' || v_at::text
    || '|' || coalesce(v_actor::text, '')
    || '|' || coalesce(v_membership::text, '')
    || '|' || p_event_type
    || '|' || coalesce(p_resource_type, '')
    || '|' || coalesce(p_resource_id::text, '')
    || '|' || coalesce(p_old_state::text, '')
    || '|' || coalesce(p_new_state::text, '')
    || '|' || coalesce(p_reason, '');

  v_hash := encode(extensions.digest(v_payload, 'sha256'), 'hex');

  insert into public.authorization_audit_events (
    id, organization_id, occurred_at, actor_user_id, actor_membership_id,
    event_type, resource_type, resource_id, old_state, new_state, reason,
    prev_hash, event_hash
  ) values (
    v_id, p_organization_id, v_at, v_actor, v_membership,
    p_event_type, p_resource_type, p_resource_id, p_old_state, p_new_state, p_reason,
    v_prev, v_hash
  );

  return v_id;
end
$$;








--
-- Name: FUNCTION append_authz_audit_v1(p_organization_id uuid, p_event_type text, p_resource_type text, p_resource_id uuid, p_old_state jsonb, p_new_state jsonb, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.append_authz_audit_v1(p_organization_id uuid, p_event_type text, p_resource_type text, p_resource_id uuid, p_old_state jsonb, p_new_state jsonb, p_reason text) IS 'Ghi một dòng nhật ký phân quyền và nối vào chuỗi hash của tổ chức. Dùng chung cho mọi RPC quản trị — đừng INSERT thẳng vào authorization_audit_events.';








--
-- Name: append_income_expense_event_v1(uuid, uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.append_income_expense_event_v1(p_organization_id uuid, p_income_expense_id uuid, p_action text, p_actor_id uuid, p_actor_name text, p_old_status text, p_new_status text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_head app_private.income_expense_audit_chain_heads;
  v_seq bigint;
  v_canonical text;
  v_hash text;
  v_id uuid;
  v_now timestamptz := clock_timestamp();
begin
  if p_organization_id is null or p_income_expense_id is null
     or p_action is null or p_actor_id is null then
    raise exception 'append_income_expense_event_v1: required argument NULL'
      using errcode = '22004';
  end if;

  -- F5: bootstrap + lock. Head is the last lock taken before the INSERT.
  insert into app_private.income_expense_audit_chain_heads (organization_id)
  values (p_organization_id)
  on conflict (organization_id) do nothing;

  select * into v_head
    from app_private.income_expense_audit_chain_heads
   where organization_id = p_organization_id
   for update;

  v_seq := v_head.last_sequence_no + 1;

  -- F2/F3 canonical serialization (byte-level pinned):
  --   fields joined by \x1f, timestamps rendered UTC ISO-8601 fixed format,
  --   NULLs rendered as empty string, preimage prefixed with org + seq +
  --   prev hash. No jsonb round-trip → no numeric/TZ instability.
  v_canonical := concat_ws(chr(31),
    'PG_SHA256_CANONICAL_V1',
    p_organization_id::text,
    v_seq::text,
    v_head.last_event_hash,
    p_income_expense_id::text,
    p_action,
    p_actor_id::text,
    coalesce(p_actor_name, ''),
    coalesce(p_old_status, ''),
    coalesce(p_new_status, ''),
    coalesce(p_note, ''),
    to_char(v_now at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));

  v_hash := encode(sha256(convert_to(v_canonical, 'UTF8')), 'hex');

  insert into public.income_expense_audit_log (
    income_expense_id, action, actor_id, actor_name,
    old_status, new_status, note, organization_id,
    sequence_no, prev_event_hash, event_hash, hash_scheme, created_at)
  values (
    p_income_expense_id, p_action, p_actor_id, p_actor_name,
    p_old_status, p_new_status, p_note, p_organization_id,
    v_seq, v_head.last_event_hash, v_hash, 'PG_SHA256_CANONICAL_V1', v_now)
  returning id into v_id;

  update app_private.income_expense_audit_chain_heads
     set last_sequence_no = v_seq,
         last_event_hash = v_hash,
         updated_at = v_now
   where organization_id = p_organization_id;

  return v_id;
end;
$$;








--
-- Name: append_openclaw_audit_v1(uuid, text, uuid, text, uuid, uuid, jsonb, bytea); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.append_openclaw_audit_v1(p_organization_id uuid, p_event_type text, p_actor_id uuid, p_workload_principal text, p_request_id uuid, p_correlation_id uuid, p_redacted_evidence jsonb, p_redacted_evidence_bytes bytea) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_sequence bigint;
  v_previous_hash text;
  v_evidence_hash text;
  v_event_hash text;
begin
  if p_actor_id is null and p_workload_principal is null then
    raise exception 'audit actor or workload principal is required' using errcode = '23514';
  end if;
  if jsonb_typeof(p_redacted_evidence) <> 'object'
     or p_redacted_evidence_bytes is null
     or octet_length(p_redacted_evidence_bytes) = 0
     or convert_from(p_redacted_evidence_bytes, 'UTF8')::jsonb <> p_redacted_evidence
  then
    raise exception 'invalid audit evidence' using errcode = '23514';
  end if;
  v_evidence_hash := encode(
    extensions.digest(p_redacted_evidence_bytes, 'sha256'),
    'hex'
  );

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_organization_id::text, 0));
  select e.organization_sequence + 1, e.event_hash
    into v_sequence, v_previous_hash
    from public.openclaw_audit_events e
   where e.organization_id = p_organization_id
   order by e.organization_sequence desc
   limit 1
   for update;

  v_sequence := coalesce(v_sequence, 1);
  v_previous_hash := coalesce(v_previous_hash, repeat('0', 64));
  v_event_hash := encode(extensions.digest(
    convert_to(v_previous_hash, 'UTF8') || decode('00', 'hex')
      || convert_to(v_sequence::text, 'UTF8') || decode('00', 'hex')
      || convert_to(p_event_type, 'UTF8') || decode('00', 'hex')
      || convert_to(v_evidence_hash, 'UTF8'),
    'sha256'
  ), 'hex');

  insert into public.openclaw_audit_events (
    id, organization_id, organization_sequence, event_type, actor_id,
    workload_principal, request_id, correlation_id, redacted_evidence,
    redacted_evidence_bytes, evidence_hash, previous_hash, event_hash
  ) values (
    v_id, p_organization_id, v_sequence, p_event_type, p_actor_id,
    p_workload_principal, p_request_id, p_correlation_id, p_redacted_evidence,
    p_redacted_evidence_bytes, v_evidence_hash, v_previous_hash, v_event_hash
  );
  return v_id;
end
$$;








--
-- Name: apply_customer_credit_fifo_v1(uuid, uuid, numeric, uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.apply_customer_credit_fifo_v1(p_actor uuid, p_contract_id uuid, p_amount numeric, p_invoice_id uuid, p_application_kind text, p_description text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_kind text := upper(btrim(COALESCE(p_application_kind, '')));
  v_description text := NULLIF(btrim(COALESCE(p_description, '')), '');
  v_org uuid;
  v_building_id uuid;
  v_owner uuid;
  v_authz boolean;
  v_route text;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_available numeric(15,2) := 0;
  v_ledger_balance numeric(15,2) := 0;
  v_requested numeric(15,2);
  v_remaining numeric(15,2);
  v_take numeric(15,2);
  v_new_remaining numeric(15,2);
  v_lot public.customer_credit_lots%ROWTYPE;
  v_excess_id uuid;
  v_application_id uuid;
  v_applications jsonb := '[]'::jsonb;
  v_response jsonb;
BEGIN
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Invalid credit actor' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF v_kind NOT IN ('INVOICE_DISCOUNT', 'MOVE_OUT', 'FORFEIT', 'MANUAL') THEN
    RAISE EXCEPTION 'Invalid customer credit application kind'
      USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NOT NULL AND (
    p_amount = 'NaN'::numeric OR p_amount <= 0
    OR p_amount IS DISTINCT FROM round(p_amount, 2)
  ) THEN
    RAISE EXCEPTION 'Credit amount must be positive with at most two decimals'
      USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL AND v_kind <> 'FORFEIT' THEN
    RAISE EXCEPTION 'Only FORFEIT may consume the full balance'
      USING ERRCODE = '22023';
  END IF;

  SELECT contract_row.organization_id, room_row.building_id, contract_row.user_id
    INTO v_org, v_building_id, v_owner
  FROM public.contracts contract_row
  JOIN public.rooms room_row
    ON room_row.id = contract_row.room_id AND room_row.deleted_at IS NULL
  JOIN public.buildings building_row
    ON building_row.id = room_row.building_id
   AND building_row.deleted_at IS NULL
   AND building_row.organization_id = contract_row.organization_id
  JOIN public.organizations organization_row
    ON organization_row.id = contract_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE OF contract_row;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Contract is outside an active organization'
      USING ERRCODE = '42501';
  END IF;

  IF p_invoice_id IS NOT NULL THEN
    PERFORM 1
    FROM public.invoices invoice_row
    WHERE invoice_row.id = p_invoice_id
      AND invoice_row.contract_id = p_contract_id
      AND invoice_row.organization_id = v_org
      AND invoice_row.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Credit target invoice does not belong to the contract'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    p_actor, v_org, 'excess_amounts.edit', v_building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Missing permission to apply customer credit'
      USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'organization_id', v_org,
    'contract_id', p_contract_id,
    'amount', p_amount,
    'invoice_id', p_invoice_id,
    'application_kind', v_kind,
    'description', v_description
  )::text);

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, 'customer.credit.apply.v1',
    p_contract_id::text || '|' || v_kind || '|' || COALESCE(p_invoice_id::text, '-'),
    p_actor, v_key, v_hash
  ) ON CONFLICT (
    organization_id, operation, subject_scope, actor_id, idempotency_key
  ) DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'customer.credit.apply.v1'
    AND operation_row.subject_scope =
      p_contract_id::text || '|' || v_kind || '|' || COALESCE(p_invoice_id::text, '-')
    AND operation_row.actor_id = p_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key was reused with a different payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  v_route := app_private.evaluate_feature_route('customer.credit.apply.v1', v_org);
  IF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Customer credit writer is not enabled'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.excess_amounts excess
    WHERE excess.contract_id = p_contract_id
      AND excess.credit_lot_id IS NULL
      AND excess.amount <> 0
  ) THEN
    RAISE EXCEPTION 'Legacy customer credit requires manual reconciliation'
      USING ERRCODE = '55000';
  END IF;

  PERFORM 1
  FROM public.customer_credit_lots lot
  WHERE lot.organization_id = v_org
    AND lot.contract_id = p_contract_id
    AND lot.status = 'ACTIVE'
    AND lot.remaining_amount > 0
  ORDER BY lot.created_at, lot.id
  FOR UPDATE;

  SELECT COALESCE(sum(lot.remaining_amount), 0)::numeric(15,2)
    INTO v_available
  FROM public.customer_credit_lots lot
  WHERE lot.organization_id = v_org
    AND lot.contract_id = p_contract_id
    AND lot.status = 'ACTIVE'
    AND lot.remaining_amount > 0;

  SELECT COALESCE(sum(excess.amount), 0)::numeric(15,2)
    INTO v_ledger_balance
  FROM public.excess_amounts excess
  WHERE excess.organization_id = v_org
    AND excess.contract_id = p_contract_id
    AND excess.credit_lot_id IS NOT NULL;

  IF abs(v_available - v_ledger_balance) >= 0.01 THEN
    RAISE EXCEPTION 'Credit lot balance does not match the compatibility ledger'
      USING ERRCODE = '55000';
  END IF;

  v_requested := CASE
    WHEN p_amount IS NULL THEN v_available
    ELSE round(p_amount, 2)
  END;

  IF v_requested > v_available THEN
    RAISE EXCEPTION 'Insufficient customer credit: requested %, available %',
      v_requested, v_available USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.claim_feature_operation_v1(
    'customer.credit.apply.v1',
    v_org,
    p_contract_id::text || '|' || v_kind || '|' || COALESCE(p_invoice_id::text, '-'),
    p_actor,
    v_key,
    v_requested
  );

  IF v_requested = 0 THEN
    v_response := jsonb_build_object(
      'contract_id', p_contract_id,
      'invoice_id', p_invoice_id,
      'application_kind', v_kind,
      'applied_amount', 0,
      'remaining_amount', v_available,
      'applications', '[]'::jsonb
    );
    UPDATE app_private.canonical_write_operations
       SET subject_id = COALESCE(p_invoice_id, p_contract_id),
           completed_at = clock_timestamp(),
           response_payload = v_response
     WHERE organization_id = v_org
       AND operation = 'customer.credit.apply.v1'
       AND subject_scope =
         p_contract_id::text || '|' || v_kind || '|' || COALESCE(p_invoice_id::text, '-')
       AND actor_id = p_actor
       AND idempotency_key = v_key;
    RETURN v_response;
  END IF;

  PERFORM app_private.begin_accounting_chain_write_v1();
  v_remaining := v_requested;

  FOR v_lot IN
    SELECT *
    FROM public.customer_credit_lots lot
    WHERE lot.organization_id = v_org
      AND lot.contract_id = p_contract_id
      AND lot.status = 'ACTIVE'
      AND lot.remaining_amount > 0
    ORDER BY lot.created_at, lot.id
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_lot.remaining_amount, v_remaining);
    v_new_remaining := v_lot.remaining_amount - v_take;

    INSERT INTO public.excess_amounts (
      organization_id, user_id, contract_id, amount, description,
      source_invoice_id, source_payment_id, credit_lot_id
    ) VALUES (
      v_org, v_owner, p_contract_id, -v_take,
      COALESCE(v_description, 'Customer credit application'),
      p_invoice_id, NULL, v_lot.id
    ) RETURNING id INTO v_excess_id;

    INSERT INTO public.customer_credit_applications (
      organization_id, credit_lot_id, invoice_id, excess_amount_id,
      amount, applied_by, application_kind, idempotency_key, description
    ) VALUES (
      v_org, v_lot.id, p_invoice_id, v_excess_id,
      v_take, p_actor, v_kind, v_key, v_description
    ) RETURNING id INTO v_application_id;

    UPDATE public.customer_credit_lots
       SET remaining_amount = v_new_remaining,
           status = CASE WHEN v_new_remaining = 0 THEN 'CONSUMED' ELSE 'ACTIVE' END
     WHERE id = v_lot.id;

    v_applications := v_applications || jsonb_build_array(jsonb_build_object(
      'application_id', v_application_id,
      'credit_lot_id', v_lot.id,
      'excess_amount_id', v_excess_id,
      'amount', v_take
    ));
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'FIFO credit allocation did not balance'
      USING ERRCODE = '55000';
  END IF;

  v_response := jsonb_build_object(
    'contract_id', p_contract_id,
    'invoice_id', p_invoice_id,
    'application_kind', v_kind,
    'applied_amount', v_requested,
    'remaining_amount', v_available - v_requested,
    'applications', v_applications
  );

  UPDATE app_private.canonical_write_operations
     SET subject_id = COALESCE(p_invoice_id, p_contract_id),
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'customer.credit.apply.v1'
     AND subject_scope =
       p_contract_id::text || '|' || v_kind || '|' || COALESCE(p_invoice_id::text, '-')
     AND actor_id = p_actor
     AND idempotency_key = v_key;

  PERFORM app_private.end_accounting_chain_write_v1();
  RETURN v_response;
END;
$_$;








--
-- Name: assert_accounting_feature_activation_v1(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_accounting_feature_activation_v1(p_feature_key text, p_mode text, p_organization_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_open integer;
  v_bad_reversals integer;
BEGIN
  IF p_feature_key NOT IN (
    'contract.create.v2',
    'invoice.collection.v5',
    'customer.credit.apply.v1',
    'shareholder_profit.distribute.v2'
  ) THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_open
  FROM public.accounting_integrity_exceptions exception
  WHERE exception.status = 'OPEN';
  IF v_open <> 0 THEN
    RAISE EXCEPTION 'Accounting activation blocked by % open integrity exceptions', v_open;
  END IF;

  SELECT app_private.count_invalid_payment_reversals_v1()
    INTO v_bad_reversals;
  IF v_bad_reversals <> 0 THEN
    RAISE EXCEPTION 'Accounting activation blocked by % invalid reversal vouchers',
      v_bad_reversals;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_payout_exceptions exception
    WHERE exception.resolved_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Accounting activation blocked by unresolved payout exceptions';
  END IF;

  IF p_feature_key = 'shareholder_profit.distribute.v2' AND (
    (
      p_mode = 'ON'
      AND EXISTS (
        SELECT 1
        FROM public.profit_monthly profit
        WHERE profit.status = 'LOCKED'
          AND (
            profit.is_stale
            OR NOT app_private.profit_monthly_source_is_current_v1(profit.id)
          )
      )
    )
    OR (
      p_mode = 'CANARY'
      AND EXISTS (
        SELECT 1
        FROM public.profit_monthly profit
        WHERE profit.status = 'LOCKED'
          AND (
            profit.is_stale
            OR NOT app_private.profit_monthly_source_is_current_v1(profit.id)
          )
          AND (
            (
              p_organization_id IS NOT NULL
              AND profit.organization_id = p_organization_id
            )
            OR (
              p_organization_id IS NULL
              AND EXISTS (
                SELECT 1
                FROM app_private.server_feature_flag_canary_orgs canary
                WHERE canary.feature_key = p_feature_key
                  AND canary.organization_id = profit.organization_id
              )
            )
          )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Profit distribution activation blocked by stale locked profit periods';
  END IF;
END;
$$;








--
-- Name: assert_cashbook_access_v2(uuid, uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_cashbook_access_v2(p_org uuid, p_cashbook uuid, p_kind text, p_membership uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_keys text[] := ARRAY['cashbooks.post','income_expenses.create',
                         'income_expenses.reverse','income_expenses.cancel'];
BEGIN
  IF p_kind NOT IN ('CUSTODIAN','KNOWER') THEN
    RAISE EXCEPTION 'assert_cashbook_access_v2: invalid possession kind %', p_kind
      USING ERRCODE = '22023';
  END IF;

  -- Membership must be active and in this tenant.
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
    WHERE m.id = p_membership
      AND m.organization_id = p_org
      AND m.status = 'ACTIVE'
      AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
      AND (m.valid_to IS NULL OR m.valid_to > now())
  ) THEN
    RAISE EXCEPTION 'assert_cashbook_access_v2: membership inactive or cross-tenant'
      USING ERRCODE = '42501';
  END IF;

  -- Target cashbook must exist in tenant and not be deleted.
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts a
    WHERE a.id = p_cashbook AND a.organization_id = p_org AND a.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'assert_cashbook_access_v2: cashbook % not found in organization', p_cashbook
      USING ERRCODE = '42501';
  END IF;

  -- Covering DENY wins over any binding.
  IF app_private.finance_v2_has_covering_deny(p_org, p_membership, p_cashbook, v_keys) THEN
    RAISE EXCEPTION 'assert_cashbook_access_v2: access denied by covering DENY on cashbook %', p_cashbook
      USING ERRCODE = '42501';
  END IF;

  -- Positive grant: open possession binding of the required kind on the exact cashbook.
  IF NOT EXISTS (
    SELECT 1 FROM public.cashbook_possession_bindings b
    WHERE b.organization_id = p_org
      AND b.cashbook_id = p_cashbook
      AND b.membership_id = p_membership
      AND b.possession_kind = p_kind
      AND b.valid_from <= now()
      AND (b.valid_to IS NULL OR b.valid_to > now())
  ) THEN
    RAISE EXCEPTION 'assert_cashbook_access_v2: no % possession of cashbook %', p_kind, p_cashbook
      USING ERRCODE = '42501';
  END IF;
END
$$;








--
-- Name: FUNCTION assert_cashbook_access_v2(p_org uuid, p_cashbook uuid, p_kind text, p_membership uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.assert_cashbook_access_v2(p_org uuid, p_cashbook uuid, p_kind text, p_membership uuid) IS 'Plan §6.4/§7.1: possession-derived positive grant after covering DENY; RAISE 42501 on failure.';








