--
-- Name: assert_finance_v2_canary_enrollment_v1(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_finance_v2_canary_enrollment_v1(p_feature_key text, p_organization_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_config_version bigint;
BEGIN
  IF p_feature_key NOT IN (
    'income_expense.workflow.v2',
    'income_expense.posting.v2',
    'cashbook.access.v2',
    'income_expense.profit_close.v2',
    'income_expense.read_semantics.v2',
    'contract.commission.settlement.v2',
    'salary.settlement.v2'
  ) THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Finance V2 canary enrollment requires an organization'
      USING ERRCODE = '22023';
  END IF;

  SELECT feature.config_version INTO v_config_version
  FROM app_private.server_feature_flags feature
  WHERE feature.feature_key = p_feature_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Finance V2 feature % is not configured', p_feature_key
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_finance_v2_feature_rollout_v1(p_feature_key);

  -- Org-scoped attestation for the target config version is mandatory.
  IF NOT EXISTS (
    SELECT 1
    FROM app_private.finance_v2_activation_attestations attestation
    WHERE attestation.feature_key = p_feature_key
      AND attestation.config_version = v_config_version
      AND attestation.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION
      'Finance V2 canary enrollment of % for org % blocked: missing org-scoped attestation (config_version %)',
      p_feature_key, p_organization_id, v_config_version
      USING ERRCODE = '55000';
  END IF;

  -- Commission/salary settlement additionally require a business-policy decision.
  IF p_feature_key IN (
    'contract.commission.settlement.v2', 'salary.settlement.v2'
  ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM app_private.finance_business_policy_decisions decision
      WHERE decision.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION
        'Finance V2 canary enrollment of % for org % blocked: missing business-policy decision',
        p_feature_key, p_organization_id
        USING ERRCODE = '55000';
    END IF;
  END IF;
END;
$$;








--
-- Name: assert_finance_v2_feature_activation_v1(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_finance_v2_feature_activation_v1(p_feature_key text, p_mode text, p_organization_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_config_version bigint;
BEGIN
  IF p_feature_key NOT IN (
    'income_expense.workflow.v2',
    'income_expense.posting.v2',
    'cashbook.access.v2',
    'income_expense.profit_close.v2',
    'income_expense.read_semantics.v2',
    'contract.commission.settlement.v2',
    'salary.settlement.v2'
  ) THEN
    RETURN;
  END IF;

  -- Only CANARY/ON transitions are gated; OFF/SHADOW require no attestation.
  IF p_mode NOT IN ('CANARY', 'ON') THEN
    RETURN;
  END IF;

  -- Row-lock the flag first (current config_version), then take the advisory lock.
  SELECT feature.config_version INTO v_config_version
  FROM app_private.server_feature_flags feature
  WHERE feature.feature_key = p_feature_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Finance V2 feature % is not configured', p_feature_key
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_finance_v2_feature_rollout_v1(p_feature_key);

  IF NOT EXISTS (
    SELECT 1
    FROM app_private.finance_v2_activation_attestations attestation
    WHERE attestation.feature_key = p_feature_key
      AND attestation.config_version = v_config_version
      AND attestation.organization_id IS NOT DISTINCT FROM p_organization_id
  ) THEN
    RAISE EXCEPTION
      'Finance V2 activation of % blocked: missing attestation for config_version % (scope %)',
      p_feature_key, v_config_version, COALESCE(p_organization_id::text, 'GLOBAL')
      USING ERRCODE = '55000';
  END IF;

  -- Commission/salary settlement additionally require a business-policy decision.
  IF p_feature_key IN (
    'contract.commission.settlement.v2', 'salary.settlement.v2'
  ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM app_private.finance_business_policy_decisions decision
      WHERE p_organization_id IS NULL
         OR decision.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION
        'Finance V2 activation of % blocked: missing business-policy decision (scope %)',
        p_feature_key, COALESCE(p_organization_id::text, 'GLOBAL')
        USING ERRCODE = '55000';
    END IF;
  END IF;
END;
$$;








--
-- Name: FUNCTION assert_finance_v2_feature_activation_v1(p_feature_key text, p_mode text, p_organization_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.assert_finance_v2_feature_activation_v1(p_feature_key text, p_mode text, p_organization_id uuid) IS '§10.4 fail-closed activation gate for the 7 Finance V2 keys (attestation + policy).';








--
-- Name: assert_income_expense_flow_owner_v2(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_income_expense_flow_owner_v2(p_voucher uuid, p_expected_owner text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_flow_kind text;
BEGIN
  SELECT o.flow_kind INTO v_flow_kind
  FROM app_private.income_expense_flow_ownership o
  WHERE o.income_expense_id = p_voucher;

  -- No ownership row: not claimed by any system writer -> manual RPC allowed.
  IF v_flow_kind IS NULL THEN
    RETURN;
  END IF;

  IF v_flow_kind IS DISTINCT FROM p_expected_owner THEN
    RAISE EXCEPTION 'assert_income_expense_flow_owner_v2: voucher % owned by system flow % (manual RPC expects %)',
      p_voucher, v_flow_kind, p_expected_owner
      USING ERRCODE = '42501';
  END IF;
END
$$;








--
-- Name: FUNCTION assert_income_expense_flow_owner_v2(p_voucher uuid, p_expected_owner text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.assert_income_expense_flow_owner_v2(p_voucher uuid, p_expected_owner text) IS 'Plan §7.1: manual lifecycle RPC refuses subjects owned by a system writer flow.';








--
-- Name: assert_invoice_credit_cancellable_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_invoice_credit_cancellable_v1(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.excess_amounts excess
    WHERE excess.source_invoice_id = p_invoice_id
      AND excess.credit_lot_id IS NULL
      AND excess.amount <> 0
  ) THEN
    RAISE EXCEPTION 'Invoice has unreconciled legacy customer credit'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.customer_credit_lots lot
    JOIN public.excess_amounts source_excess
      ON source_excess.id = lot.source_excess_amount_id
    WHERE source_excess.source_invoice_id = p_invoice_id
      AND lot.status <> 'REVERSED'
  ) THEN
    RAISE EXCEPTION 'Reverse the payment credit source before cancelling this invoice'
      USING ERRCODE = '55000';
  END IF;
END;
$$;








--
-- Name: assert_manual_voucher_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_manual_voucher_v1(p_voucher uuid, p_action text DEFAULT 'huỷ'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_flow text;
BEGIN
  SELECT * INTO v FROM public.income_expenses WHERE id = p_voucher;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002'; END IF;

  SELECT o.flow_kind INTO v_flow
  FROM app_private.income_expense_flow_ownership o WHERE o.income_expense_id = p_voucher;

  -- Đọc flow_kind TRỰC TIẾP: assert_income_expense_flow_owner_v2 trả về im
  -- lặng khi KHÔNG có dòng sở hữu, nên nó không phải là hàng rào.
  IF v_flow IS NOT NULL AND v_flow <> 'CANONICAL_INCOME_EXPENSE' THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu thuộc luồng % — phải % ở đúng màn hình nguồn.', v_flow, p_action
      USING ERRCODE = '42501';
  END IF;

  IF v.payment_id IS NOT NULL OR v.payment_collection_id IS NOT NULL OR v.invoice_id IS NOT NULL THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu gắn với hoá đơn/thanh toán — dùng chức năng hoàn tác thu tiền.'
      USING ERRCODE = '42501';
  END IF;
  IF v.salary_staff_id IS NOT NULL THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu gắn lương nhân sự — sửa ở màn hình lương, nếu không hệ thống sẽ cộng lương lần nữa.'
      USING ERRCODE = '42501';
  END IF;
  IF v.shareholder_id IS NOT NULL OR v.profit_manager_id IS NOT NULL THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu chia lợi nhuận — xử lý ở màn hình phân bổ lợi nhuận.'
      USING ERRCODE = '42501';
  END IF;
  IF v.reversal_of_income_expense_id IS NOT NULL THEN
    RAISE EXCEPTION '[NOT_MANUAL] Đây là bút toán đối ứng — không huỷ riêng.' USING ERRCODE = '42501';
  END IF;
  IF v.handover_transfer_id IS NOT NULL THEN
    RAISE EXCEPTION '[HANDOVER_LOCKED] Đây là phiếu chuyển của một phiên bàn giao — huỷ phiên trước.'
      USING ERRCODE = '42501';
  END IF;
  IF v.handover_id IS NOT NULL THEN
    RAISE EXCEPTION '[HANDOVER_LOCKED] Phiếu nằm trong phiên bàn giao — huỷ phiên trước.' USING ERRCODE = '42501';
  END IF;
  IF v.system_source IS NOT NULL THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu do hệ thống sinh (%) — xử lý ở luồng nguồn.', v.system_source
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profit_payout_reservations r WHERE r.payout_voucher_id = p_voucher) THEN
    RAISE EXCEPTION '[NOT_MANUAL] Phiếu đang giữ chỗ chi trả lợi nhuận.' USING ERRCODE = '42501';
  END IF;
END
$$;








--
-- Name: assert_no_engine_request_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_no_engine_request_v1(p_voucher_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
begin
  if exists (
    select 1 from public.approval_requests ar
     where ar.subject_type = 'FINANCIAL_VOUCHER'
       and ar.subject_id = p_voucher_id
       and ar.state in ('PENDING_APPROVAL', 'POSTED')
  ) then
    raise exception 'Phiếu thuộc luồng duyệt engine (lương/lợi nhuận/chi cần duyệt) — xử lý tại màn hình "Chờ duyệt", không duyệt/huỷ duyệt trực tiếp'
      using errcode = '55000';
  end if;
end;
$$;








--
-- Name: assert_notes_markers_unchanged_v1(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_notes_markers_unchanged_v1(p_old text, p_new text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF app_private.ie_notes_money_markers_v1(p_old)
     IS DISTINCT FROM app_private.ie_notes_money_markers_v1(p_new) THEN
    RAISE EXCEPTION
      'Ghi chú chứa dấu hiệu hạch toán ([Hoàn trả thanh lý] / [CẤN CỌC BỎ CỌC]) — không được thêm hoặc gỡ qua sửa phiếu. Dùng đúng luồng nghiệp vụ.'
      USING ERRCODE = '55000';
  END IF;
END
$$;








--
-- Name: assert_notification_membership_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_notification_membership_v1(p_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_uid uuid;
  v_now timestamptz := clock_timestamp();
  v_ok  boolean;
begin
  v_uid := (select auth.uid());
  if v_uid is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  if p_org is null then
    raise exception 'Thiếu tổ chức.' using errcode = '22023';
  end if;

  select exists (
    select 1
      from public.organization_memberships m
      join public.organizations o
        on o.id = m.organization_id and o.status = 'ACTIVE'
     where m.organization_id = p_org
       and m.user_id = v_uid
       and m.status = 'ACTIVE'
       and coalesce(m.valid_from, '-infinity'::timestamptz) <= v_now
       and (m.valid_to is null or m.valid_to > v_now)
  ) into v_ok;

  if not v_ok then
    raise exception 'Bạn không thuộc tổ chức này.' using errcode = '42501';
  end if;
end
$$;








--
-- Name: assert_override_scope_shape(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_override_scope_shape() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_override_id uuid;
  v_bad record;
begin
  -- Branch on table BEFORE touching record fields: member_override_scopes has
  -- no `id` column and plpgsql raises on missing record fields at runtime.
  if tg_table_name = 'member_override_scopes' then
    if tg_op = 'DELETE' then
      v_override_id := old.override_id;
    else
      v_override_id := new.override_id;
    end if;
  else
    if tg_op = 'DELETE' then
      v_override_id := old.id;
    else
      v_override_id := new.id;
    end if;
  end if;

  select o.id, o.scope_mode, o.permission_key, o.organization_id,
         count(mos.scope_id) as edge_count,
         count(*) filter (where s.scope_type = 'ORGANIZATION') as org_edges,
         count(*) filter (
           where s.scope_type is not null
             and not (s.scope_type = any(pd.scope_kinds))
         ) as illegal_kind_edges
    into v_bad
    from public.member_permission_overrides o
    left join public.member_override_scopes mos
      on mos.organization_id = o.organization_id and mos.override_id = o.id
    left join public.authorization_scopes s
      on s.organization_id = o.organization_id and s.id = mos.scope_id
    left join public.permission_definitions pd on pd.key = o.permission_key
   where o.id = v_override_id
     and o.revoked_at is null
   group by o.id, o.scope_mode, o.permission_key, o.organization_id;

  if v_bad.id is null then
    return null; -- row deleted or already revoked; nothing to assert
  end if;

  if v_bad.scope_mode = 'ORGANIZATION'
     and not (v_bad.edge_count = 1 and v_bad.org_edges = 1) then
    raise exception 'override %: ORGANIZATION mode requires exactly one ORGANIZATION edge (has % edges, % org)',
      v_bad.id, v_bad.edge_count, v_bad.org_edges using errcode = '23514';
  end if;
  if v_bad.scope_mode = 'SCOPED'
     and not (v_bad.edge_count >= 1 and v_bad.org_edges = 0) then
    raise exception 'override %: SCOPED mode requires >=1 non-ORGANIZATION edge (has % edges, % org)',
      v_bad.id, v_bad.edge_count, v_bad.org_edges using errcode = '23514';
  end if;
  if v_bad.illegal_kind_edges > 0 then
    raise exception 'override %: % edge(s) outside permitted scope_kinds of %',
      v_bad.id, v_bad.illegal_kind_edges, v_bad.permission_key using errcode = '23514';
  end if;
  return null;
end;
$$;








--
-- Name: assert_period_open_for_edit_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_period_open_for_edit_v1(p_voucher uuid, p_action text DEFAULT 'sửa'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_row public.income_expenses%ROWTYPE;
  v_acct uuid;
  v_lock date;
  v_name text;
  v_handover text;
  v_month date;
  -- WP2_PERIOD_ALL_THREE
  v_billing text;
  v_billing_building uuid;
  v_billing_month date;
  v_item_month date;
BEGIN
  SELECT * INTO v_row FROM public.income_expenses WHERE id = p_voucher;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  -- 1) SỔ QUỸ ĐÃ CHỐT & BÀN GIAO. Xét cả sổ chính, sổ thối và sổ làm tròn vì
  --    tồn quỹ cộng theo account của từng dòng bút toán.
  FOREACH v_acct IN ARRAY ARRAY[v_row.account_id, v_row.change_account_id, v_row.rounding_account_id] LOOP
    CONTINUE WHEN v_acct IS NULL;
    v_lock := app_private.cashbook_closed_through_v1(v_acct);
    IF v_lock IS NOT NULL AND v_row.voucher_date <= v_lock THEN
      SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = v_acct;
      RAISE EXCEPTION
        '[CASHBOOK_CLOSED] Sổ quỹ "%" đã chốt & bàn giao tới ngày % — phiếu trong kỳ này không % được nữa. Muốn điều chỉnh, hãy lập phiếu mới ở kỳ hiện tại.',
        COALESCE(v_name, 'không rõ'), to_char(v_lock, 'DD/MM/YYYY'), p_action
        USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  -- 2) PHIÊN BÀN GIAO TIỀN MẶT còn sống. Trigger ie_handover_guard cũng chặn,
  --    nhưng nó chỉ nói "[HANDOVER_LOCKED]" — ở đây nêu rõ mã phiên để người
  --    dùng biết phải huỷ phiên nào.
  IF v_row.handover_transfer_id IS NOT NULL THEN
    SELECT h.code INTO v_handover FROM public.cash_handovers h
     WHERE h.id = v_row.handover_transfer_id AND h.status <> 'CANCELLED';
    IF v_handover IS NOT NULL THEN
      RAISE EXCEPTION
        '[HANDOVER_LOCKED] Đây là phiếu chuyển của phiên bàn giao % — muốn % thì phải huỷ phiên đó trước (cần cả hai bên đồng ý).',
        v_handover, p_action USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_row.handover_id IS NOT NULL THEN
    SELECT h.code INTO v_handover
    FROM public.cash_handovers h
    WHERE h.id = v_row.handover_id AND h.status <> 'CANCELLED';
    IF v_handover IS NOT NULL THEN
      RAISE EXCEPTION
        '[HANDOVER_LOCKED] Phiếu nằm trong phiên bàn giao % đã xác nhận — muốn % thì phải huỷ phiên đó trước (cần cả hai bên đồng ý).',
        v_handover, p_action
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- 3) THÁNG LỢI NHUẬN ĐÃ CHỐT. Bỏ qua phiếu cố ý nằm ngoài KQKD (điều chỉnh
  --    số dư, chuyển nội bộ, cấn cọc…) vì chúng không góp vào con số đã chia.
  IF COALESCE(v_row.business_result_accounting, true) THEN
    v_month := date_trunc('month', v_row.voucher_date)::date;
    IF EXISTS (
      SELECT 1 FROM public.profit_monthly pm
      WHERE pm.building_id = v_row.building_id
        AND pm.period_month = v_month
        AND pm.locked_at IS NOT NULL
    ) THEN
      RAISE EXCEPTION
        '[PROFIT_LOCKED] Lợi nhuận tháng % của toà này đã chốt và đã chia cho cổ đông — không % phiếu của tháng đó. Hãy lập phiếu điều chỉnh ở tháng hiện tại.',
        to_char(v_month, 'MM/YYYY'), p_action
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- 4) WP2_PERIOD_ALL_THREE — THÁNG HOÁ ĐƠN đã chốt lợi nhuận.
  --    Phiếu thu của hoá đơn tháng 05 hoàn toàn có thể mang voucher_date
  --    tháng 07. Doanh thu nằm ở 05; chốt lợi nhuận 05 rồi thì huỷ phiếu
  --    này vẫn rút tiền ra khỏi con số đã chia.
  IF v_row.invoice_id IS NOT NULL AND COALESCE(v_row.business_result_accounting, true) THEN
    SELECT invoice_row.billing_month, invoice_row.building_id
      INTO v_billing, v_billing_building
    FROM public.invoices invoice_row WHERE invoice_row.id = v_row.invoice_id;

    IF v_billing ~ '^[0-9]{4}-[0-9]{2}$' THEN
      v_billing_month := to_date(v_billing || '-01', 'YYYY-MM-DD');
      IF v_billing_month IS DISTINCT FROM date_trunc('month', v_row.voucher_date)::date
         AND EXISTS (
           SELECT 1 FROM public.profit_monthly pm
           WHERE pm.building_id = COALESCE(v_billing_building, v_row.building_id)
             AND pm.period_month = v_billing_month
             AND pm.locked_at IS NOT NULL
         ) THEN
        RAISE EXCEPTION
          '[PROFIT_LOCKED] Phiếu này gắn với hoá đơn kỳ % — lợi nhuận tháng đó đã chốt và đã chia cho cổ đông, nên không % được. Hãy lập phiếu điều chỉnh ở tháng hiện tại.',
          to_char(v_billing_month, 'MM/YYYY'), p_action
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  -- 5) WP2_PERIOD_ALL_THREE — KỲ DỊCH VỤ CỦA HẠNG MỤC đã chốt lợi nhuận.
  --    start_date/end_date của item là cách thứ ba hệ thống gán tiền vào
  --    tháng (tiền thuê 15/05→14/06, điện nước theo chu kỳ…). Một item bắc
  --    qua tháng đã khoá thì phiếu phải bị chặn dù ngày lập còn trong kỳ mở.
  IF COALESCE(v_row.business_result_accounting, true) THEN
    SELECT pm.period_month INTO v_item_month
    FROM public.income_expense_items item_row
    JOIN public.profit_monthly pm
      ON pm.building_id = v_row.building_id
     AND pm.locked_at IS NOT NULL
     AND pm.period_month >= date_trunc('month', LEAST(
           COALESCE(item_row.start_date, item_row.end_date),
           COALESCE(item_row.end_date, item_row.start_date)))::date
     AND pm.period_month <= date_trunc('month', GREATEST(
           COALESCE(item_row.start_date, item_row.end_date),
           COALESCE(item_row.end_date, item_row.start_date)))::date
    WHERE item_row.income_expense_id = p_voucher
      AND COALESCE(item_row.start_date, item_row.end_date) IS NOT NULL
      AND pm.period_month IS DISTINCT FROM date_trunc('month', v_row.voucher_date)::date
    ORDER BY pm.period_month
    LIMIT 1;

    IF v_item_month IS NOT NULL THEN
      RAISE EXCEPTION
        '[PROFIT_LOCKED] Phiếu có hạng mục thuộc kỳ % — lợi nhuận tháng đó đã chốt và đã chia cho cổ đông, nên không % được. Hãy lập phiếu điều chỉnh ở tháng hiện tại.',
        to_char(v_item_month, 'MM/YYYY'), p_action
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
END
$_$;








--
-- Name: FUNCTION assert_period_open_for_edit_v1(p_voucher uuid, p_action text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.assert_period_open_for_edit_v1(p_voucher uuid, p_action text) IS 'Kỳ của phiếu có còn mở để đụng vào tiền không? Ném lỗi có tiền tố [CASHBOOK_CLOSED] / [HANDOVER_LOCKED] / [PROFIT_LOCKED] để giao diện dịch sang câu người dùng hiểu được.';








--
-- Name: assert_profit_payout_fresh_v2(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_profit_payout_fresh_v2(p_voucher_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  PERFORM app_private.lock_profit_payout_sources_v2();

  PERFORM 1
  FROM public.profit_payout_reservations reservation
  JOIN public.profit_allocations allocation
    ON allocation.id = reservation.profit_allocation_id
   AND allocation.organization_id = reservation.organization_id
  JOIN public.profit_monthly profit
    ON profit.id = allocation.profit_monthly_id
   AND profit.organization_id = reservation.organization_id
  WHERE reservation.payout_voucher_id = p_voucher_id
  ORDER BY profit.period_month, profit.building_id, allocation.id
  FOR UPDATE OF reservation, allocation, profit;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profit payout has no lockable allocation reservations'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    JOIN public.profit_allocations allocation
      ON allocation.id = reservation.profit_allocation_id
     AND allocation.organization_id = reservation.organization_id
    JOIN public.profit_monthly profit
      ON profit.id = allocation.profit_monthly_id
     AND profit.organization_id = reservation.organization_id
    JOIN public.income_expenses voucher
      ON voucher.id = reservation.payout_voucher_id
    WHERE reservation.payout_voucher_id = p_voucher_id
      AND (
        profit.status IS DISTINCT FROM 'LOCKED'
        OR profit.is_stale
        OR profit.period_month >
           date_trunc('month', voucher.voucher_date)::date
        OR NOT app_private.profit_monthly_source_is_current_v1(profit.id)
      )
  ) THEN
    RAISE EXCEPTION 'Profit payout approval blocked by stale locked allocations'
      USING ERRCODE = '55000';
  END IF;
END
$$;








--
-- Name: assert_profit_payout_linkage_v2(uuid, boolean, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_profit_payout_linkage_v2(p_voucher_id uuid, p_allow_provisional boolean DEFAULT false, p_require_fully_reserved boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_voucher public.income_expenses%ROWTYPE;
  v_request public.approval_requests%ROWTYPE;
  v_reservation_count integer;
  v_canonical_count integer;
  v_legacy_count integer;
  v_null_request_count integer;
  v_distinct_request_count integer;
  v_identity_mismatch_count integer;
  v_hash_mismatch_count integer;
  v_reservation_total numeric;
  v_exception_total numeric;
  v_request_count integer;
  v_request_id uuid;
  v_item_count integer;
  v_bad_item_count integer;
  v_item_total numeric;
BEGIN
  SELECT voucher.* INTO v_voucher
  FROM public.income_expenses voucher
  WHERE voucher.id = p_voucher_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profit payout voucher is missing'
      USING ERRCODE = '55000';
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (
      WHERE reservation.reservation_source = 'CANONICAL_V1'
    )::integer,
    count(*) FILTER (
      WHERE reservation.reservation_source = 'LEGACY_BACKFILL'
    )::integer,
    count(*) FILTER (
      WHERE reservation.approval_request_id IS NULL
    )::integer,
    count(DISTINCT reservation.approval_request_id)::integer,
    count(*) FILTER (
      WHERE reservation.organization_id IS DISTINCT FROM
              v_voucher.organization_id
         OR reservation.shareholder_id IS DISTINCT FROM
              v_voucher.shareholder_id
    )::integer,
    count(*) FILTER (
      WHERE reservation.reservation_source = 'CANONICAL_V1'
        AND reservation.source_payload_hash IS DISTINCT FROM
            v_voucher.source_payload_hash
    )::integer,
    COALESCE(sum(reservation.amount), 0),
    (array_agg(
      reservation.approval_request_id
      ORDER BY reservation.approval_request_id
    ) FILTER (
      WHERE reservation.approval_request_id IS NOT NULL
    ))[1]
    INTO
      v_reservation_count,
      v_canonical_count,
      v_legacy_count,
      v_null_request_count,
      v_distinct_request_count,
      v_identity_mismatch_count,
      v_hash_mismatch_count,
      v_reservation_total,
      v_request_id
  FROM public.profit_payout_reservations reservation
  WHERE reservation.payout_voucher_id = p_voucher_id;

  SELECT count(*)::integer,
         (array_agg(
           request_row.id
           ORDER BY request_row.submitted_at DESC, request_row.id DESC
         ))[1]
    INTO v_request_count, v_request_id
  FROM public.approval_requests request_row
  WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
    AND request_row.subject_id = p_voucher_id
    AND request_row.system_source = 'profit.distribution'
    AND (
      v_request_id IS NULL
      OR request_row.id = v_request_id
    );

  IF v_reservation_count = 0 AND v_request_count = 0 THEN
    RETURN;
  END IF;
  IF v_reservation_count = 0 THEN
    RAISE EXCEPTION 'Profit payout request has no allocation reservations'
      USING ERRCODE = '55000';
  END IF;
  IF v_voucher.deleted_at IS NOT NULL
     OR v_voucher.type IS DISTINCT FROM 'EXPENSE'
     OR v_voucher.shareholder_id IS NULL
     OR v_voucher.account_id IS NULL
     OR v_voucher.building_id IS NULL
     OR v_voucher.organization_id IS NULL
     OR v_voucher.voucher_date IS NULL
     OR v_voucher.total_amount IS NULL
     OR v_voucher.total_amount = 'NaN'::numeric
     OR v_voucher.total_amount <= 0
     OR v_identity_mismatch_count <> 0 THEN
    RAISE EXCEPTION 'Profit payout voucher identity no longer matches reservations'
      USING ERRCODE = '55000';
  END IF;

  IF v_canonical_count = v_reservation_count THEN
    PERFORM 1
    FROM public.buildings building_row
    JOIN public.organizations organization
      ON organization.id = building_row.organization_id
     AND organization.status = 'ACTIVE'
    WHERE building_row.id = v_voucher.building_id
      AND building_row.organization_id = v_voucher.organization_id
      AND building_row.deleted_at IS NULL
      AND building_row.is_virtual
    FOR SHARE OF building_row, organization;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Profit payout posting building is no longer active and virtual'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  PERFORM 1
  FROM public.accounts account_row
  WHERE account_row.id = v_voucher.account_id
    AND account_row.organization_id = v_voucher.organization_id
    AND account_row.deleted_at IS NULL
    AND NOT account_row.is_virtual
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profit payout cashbook is no longer an active real account'
      USING ERRCODE = '55000';
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (
      WHERE item.organization_id IS DISTINCT FROM v_voucher.organization_id
         OR (
           v_canonical_count = v_reservation_count
           AND item.accounting_class IS DISTINCT FROM 'INTERNAL'
         )
    )::integer,
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
    INTO v_item_count, v_bad_item_count, v_item_total
  FROM public.income_expense_items item
  WHERE item.income_expense_id = p_voucher_id;
  IF v_item_count < 1
     OR v_bad_item_count <> 0
     OR abs(v_item_total - v_voucher.total_amount) >= 0.01 THEN
    RAISE EXCEPTION 'Profit payout items no longer match the voucher amount'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(sum(exception.amount), 0)
    INTO v_exception_total
  FROM public.profit_payout_exceptions exception
  WHERE exception.payout_voucher_id = p_voucher_id
    AND exception.resolved_at IS NULL;

  IF p_require_fully_reserved AND (
    v_exception_total <> 0
    OR abs(v_reservation_total - v_voucher.total_amount) >= 0.01
  ) THEN
    RAISE EXCEPTION 'Profit payout cannot post without full live reservations'
      USING ERRCODE = '55000';
  END IF;

  IF v_canonical_count = v_reservation_count THEN
    IF v_legacy_count <> 0
       OR v_voucher.system_source IS DISTINCT FROM 'profit.distribution'
       OR v_voucher.source_payload_hash IS NULL
       OR v_voucher.source_payload_hash !~ '^[0-9a-f]{32}$'
       OR v_hash_mismatch_count <> 0
       OR v_exception_total <> 0
       OR abs(v_reservation_total - v_voucher.total_amount) >= 0.01 THEN
      RAISE EXCEPTION 'Canonical profit payout reservation payload is inconsistent'
        USING ERRCODE = '55000';
    END IF;

    IF v_null_request_count = v_reservation_count
       AND p_allow_provisional THEN
      SELECT count(*)::integer,
             (array_agg(
               request_row.id
               ORDER BY request_row.submitted_at DESC, request_row.id DESC
             ))[1]
        INTO v_request_count, v_request_id
      FROM public.approval_requests request_row
      WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
        AND request_row.subject_id = p_voucher_id
        AND request_row.system_source = 'profit.distribution';
      IF v_request_count <> 1 THEN
        RAISE EXCEPTION 'Provisional profit payout must have exactly one request'
          USING ERRCODE = '55000';
      END IF;
    ELSIF v_null_request_count <> 0 OR v_distinct_request_count <> 1 THEN
      RAISE EXCEPTION 'Canonical profit payout reservations disagree on request'
        USING ERRCODE = '55000';
    END IF;

    SELECT request_row.* INTO v_request
    FROM public.approval_requests request_row
    WHERE request_row.id = v_request_id
      AND request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = p_voucher_id;
    IF NOT FOUND
       OR v_request.organization_id IS DISTINCT FROM v_voucher.organization_id
       OR v_request.system_source IS DISTINCT FROM 'profit.distribution'
       OR v_request.payload_hash IS DISTINCT FROM v_voucher.source_payload_hash
       OR v_request.amount IS DISTINCT FROM v_voucher.total_amount
       OR v_request.cashbook_id IS DISTINCT FROM v_voucher.account_id
       OR v_request.building_id IS DISTINCT FROM v_voucher.building_id
       OR v_request.payload_snapshot->>'subject_id' IS DISTINCT FROM
            v_voucher.id::text
       OR (v_request.payload_snapshot->>'amount')::numeric IS DISTINCT FROM
            v_voucher.total_amount
       OR v_request.payload_snapshot->>'account_id' IS DISTINCT FROM
            v_voucher.account_id::text
       OR v_request.payload_snapshot->>'building_id' IS DISTINCT FROM
            v_voucher.building_id::text
       OR v_request.payload_snapshot->>'type' IS DISTINCT FROM
            v_voucher.type::text
       OR v_request.payload_snapshot->>'source_payload_hash' IS DISTINCT FROM
            v_voucher.source_payload_hash THEN
      RAISE EXCEPTION 'Profit payout approval request payload is inconsistent'
        USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM app_private.income_expense_flow_ownership ownership
      WHERE ownership.income_expense_id = p_voucher_id
        AND ownership.organization_id = v_voucher.organization_id
        AND ownership.writer_operation = 'shareholder_profit.distribute.v2'
        AND ownership.payload_hash_scheme = 'PG_MD5_JSONB_TEXT_V1'
        AND ownership.payload_hash_value = v_voucher.source_payload_hash
    ) THEN
      RAISE EXCEPTION 'Canonical profit payout is not flow-owned'
        USING ERRCODE = '55000';
    END IF;
  ELSIF v_legacy_count = v_reservation_count THEN
    IF v_canonical_count <> 0
       OR v_null_request_count <> v_reservation_count
       OR v_request_count <> 0
       OR abs(
         v_reservation_total + v_exception_total - v_voucher.total_amount
       ) >= 0.01 THEN
      RAISE EXCEPTION 'Legacy profit payout reservation coverage is inconsistent'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    RAISE EXCEPTION 'Profit payout mixes canonical and legacy reservations'
      USING ERRCODE = '55000';
  END IF;
END
$_$;








--
-- Name: authorize_income_expense_on_building(uuid, uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.authorize_income_expense_on_building(p_actor uuid, p_organization_id uuid, p_action text, p_building_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_action NOT IN ('create', 'restricted_create') THEN
    RETURN false;
  END IF;

  -- Acquire the complete candidate witness graph in a deterministic order. A
  -- permission row inserted after this point cannot be used by this statement;
  -- revocations/edits of existing witnesses wait until it commits.
  PERFORM 1
    FROM public.organization_memberships grantor
   WHERE grantor.organization_id = p_organization_id
     AND grantor.member_type = 'OWNER'
     AND grantor.user_id IN (
       SELECT sa.user_id
         FROM public.staff_assignments sa
        WHERE sa.staff_id = p_actor
          AND sa.organization_id = p_organization_id
     )
   ORDER BY grantor.id
   FOR SHARE;
  PERFORM 1
    FROM public.staff_assignments sa
   WHERE sa.staff_id = p_actor
     AND sa.organization_id = p_organization_id
   ORDER BY sa.id
   FOR SHARE;
  PERFORM 1
    FROM public.roles r
   WHERE r.id IN (
     SELECT sa.role_id
       FROM public.staff_assignments sa
      WHERE sa.staff_id = p_actor
        AND sa.organization_id = p_organization_id
   )
   ORDER BY r.id
   FOR SHARE;
  PERFORM 1
    FROM public.areas a
   WHERE a.id IN (
     SELECT sa.area_id
       FROM public.staff_assignments sa
      WHERE sa.staff_id = p_actor
        AND sa.organization_id = p_organization_id
        AND sa.area_id IS NOT NULL
   )
   ORDER BY a.id
   FOR SHARE;
  PERFORM 1
    FROM public.area_buildings ab
   WHERE ab.building_id = p_building_id
     AND ab.area_id IN (
       SELECT sa.area_id
         FROM public.staff_assignments sa
        WHERE sa.staff_id = p_actor
          AND sa.organization_id = p_organization_id
          AND sa.area_id IS NOT NULL
     )
   ORDER BY ab.area_id, ab.building_id
   FOR SHARE;

  RETURN EXISTS (
    SELECT 1
      FROM public.staff_assignments sa
      JOIN public.roles r
        ON r.id = sa.role_id
       AND r.organization_id = p_organization_id
       AND r.user_id = sa.user_id
      JOIN public.organization_memberships grantor
        ON grantor.organization_id = p_organization_id
       AND grantor.user_id = sa.user_id
       AND grantor.member_type = 'OWNER'
       AND grantor.status = 'ACTIVE'
       AND grantor.valid_from <= clock_timestamp()
       AND (grantor.valid_to IS NULL OR clock_timestamp() < grantor.valid_to)
     WHERE sa.staff_id = p_actor
       AND sa.organization_id = p_organization_id
       AND jsonb_extract_path(
             COALESCE(sa.permissions, r.permissions),
             'income_expenses',
             p_action
           ) = 'true'::jsonb
       AND (
         sa.building_id = p_building_id
         OR (sa.building_id IS NULL AND sa.area_id IS NULL)
         OR jsonb_extract_path(
              COALESCE(sa.permissions, r.permissions),
              'income_expenses',
              'all_buildings'
            ) = 'true'::jsonb
         OR EXISTS (
           SELECT 1
             FROM public.area_buildings ab
             JOIN public.areas a
               ON a.id = ab.area_id
              AND a.organization_id = p_organization_id
              AND a.status = 'ACTIVE'
              AND a.deleted_at IS NULL
            WHERE ab.area_id = sa.area_id
              AND ab.building_id = p_building_id
              AND ab.organization_id = p_organization_id
         )
       )
  );
END;
$$;








--
-- Name: authorize_tenant_action_v3(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.authorize_tenant_action_v3(p_actor uuid, p_organization_id uuid, p_permission_key text, p_building_id uuid DEFAULT NULL::uuid, p_cashbook_id uuid DEFAULT NULL::uuid) RETURNS TABLE(allowed boolean, authorization_version bigint, nearest_deadline timestamp with time zone, evaluated_at timestamp with time zone, decision_reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
with
at as materialized (
  select clock_timestamp() as evaluated_at
),
-- Caller contract: app_private.lock_org_for_decision_v1() was called in a
-- PRIOR statement of this transaction. The FOR SHARE here is then a no-wait
-- re-entrant lock and this statement's snapshot postdates the lock wait.
locked_org as materialized (
  select o.id, o.authorization_version
    from public.organizations o
   where o.id = p_organization_id
     and o.status = 'ACTIVE'
   for share
),
permission as materialized (
  select pd.*
    from public.permission_definitions pd
    join locked_org lo on true
   where pd.key = p_permission_key
     and pd.permission_domain = 'TENANT'
     and pd.is_active
),
-- Fix #4: required dimensions must be supplied.
dimensions as materialized (
  select
    not exists (
      select 1 from permission pd
       where ('BUILDING' = any(pd.required_dimensions) and p_building_id is null)
          or ('CASHBOOK' = any(pd.required_dimensions) and p_cashbook_id is null)
    ) as satisfied
),
membership as materialized (
  select m.*
    from public.organization_memberships m
    join locked_org lo on lo.id = m.organization_id
    cross join at
   where m.user_id = p_actor
     and m.status = 'ACTIVE'
     and coalesce(m.valid_from, '-infinity') <= at.evaluated_at
     and (m.valid_to is null or m.valid_to > at.evaluated_at)
),
target as materialized (
  select
    (p_building_id is null or exists (
       select 1 from public.buildings b
        where b.id = p_building_id and b.organization_id = p_organization_id))
    and
    (p_cashbook_id is null or exists (
       select 1 from public.accounts a
        where a.id = p_cashbook_id and a.organization_id = p_organization_id
          and a.deleted_at is null)) as valid
),
-- Open member overrides for this key: malformed (zero-edge) witnesses raise.
member_overrides as materialized (
  select o.id, o.effect, o.scope_mode, o.expires_at
    from membership m
    join public.member_permission_overrides o
      on o.organization_id = m.organization_id
     and o.membership_id = m.id
     and o.permission_key = p_permission_key
    cross join at
   where o.revoked_at is null
     and (o.expires_at is null or o.expires_at > at.evaluated_at)
),
malformed_guard as materialized (
  select case when exists (
    select 1 from member_overrides mo
     where not exists (
       select 1 from public.member_override_scopes mos
        where mos.organization_id = p_organization_id
          and mos.override_id = mo.id)
  ) then app_private.raise_malformed_override(p_organization_id, p_permission_key)
  else 0 end as ok
),
-- Scope edges of member overrides.
member_edges as materialized (
  select mo.id, mo.effect, mo.scope_mode, s.scope_type,
         s.building_id, s.cashbook_id, s.area_id
    from member_overrides mo
    join public.member_override_scopes mos
      on mos.organization_id = p_organization_id and mos.override_id = mo.id
    join public.authorization_scopes s
      on s.organization_id = p_organization_id and s.id = mos.scope_id
),
-- Role statements: bindings valid now (NULL valid_from = always active, fix #5)
role_edges as materialized (
  select rp.effect, s.scope_type, s.building_id, s.cashbook_id, s.area_id
    from membership m
    join public.role_bindings rb
      on rb.organization_id = m.organization_id and rb.membership_id = m.id
    join public.organization_roles r
      on r.organization_id = rb.organization_id and r.id = rb.role_id
     and coalesce(r.status, 'ACTIVE') = 'ACTIVE'
    join public.role_permissions rp
      on rp.organization_id = rb.organization_id
     and rp.role_id = rb.role_id
     and rp.permission_key = p_permission_key
    join public.role_binding_scopes rbs
      on rbs.organization_id = rb.organization_id and rbs.role_binding_id = rb.id
    join public.authorization_scopes s
      on s.organization_id = rbs.organization_id and s.id = rbs.scope_id
    cross join at
   where coalesce(rb.valid_from, '-infinity') <= at.evaluated_at
     and (rb.valid_to is null or rb.valid_to > at.evaluated_at)
),
-- Fix #2: DENY matches any scope COVERING the target (broad).
-- A scope covers the target when:
--   ORGANIZATION: always
--   BUILDING: p_building_id matches
--   AREA: p_building_id inside the area
--   CASHBOOK: p_cashbook_id matches
scope_cover as materialized (
  select
    exists (
      select 1 from member_edges e
       where e.effect = 'DENY' and (
         e.scope_type = 'ORGANIZATION'
         or (e.scope_type = 'BUILDING' and e.building_id = p_building_id)
         or (e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id)
         or (e.scope_type = 'AREA' and p_building_id is not null and exists (
              select 1 from public.area_buildings ab
               where ab.organization_id = p_organization_id
                 and ab.area_id = e.area_id and ab.building_id = p_building_id)))
    ) as member_deny,
    exists (
      select 1 from role_edges e
       where e.effect = 'DENY' and (
         e.scope_type = 'ORGANIZATION'
         or (e.scope_type = 'BUILDING' and e.building_id = p_building_id)
         or (e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id)
         or (e.scope_type = 'AREA' and p_building_id is not null and exists (
              select 1 from public.area_buildings ab
               where ab.organization_id = p_organization_id
                 and ab.area_id = e.area_id and ab.building_id = p_building_id)))
    ) as role_deny,
    -- ALLOW: possession-required keys need the exact CASHBOOK edge; other keys
    -- accept any covering edge whose kind the registry permits (ANY_MATCH).
    exists (
      select 1 from member_edges e, permission pd
       where e.effect = 'ALLOW'
         and e.scope_type = any(pd.scope_kinds)
         and case
           when pd.requires_cashbook_possession then
             e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id
           else
             e.scope_type = 'ORGANIZATION'
             or (e.scope_type = 'BUILDING' and e.building_id = p_building_id)
             or (e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id)
             or (e.scope_type = 'AREA' and p_building_id is not null and exists (
                  select 1 from public.area_buildings ab
                   where ab.organization_id = p_organization_id
                     and ab.area_id = e.area_id and ab.building_id = p_building_id))
         end
    ) as member_allow,
    exists (
      select 1 from role_edges e, permission pd
       where e.effect = 'ALLOW'
         and e.scope_type = any(pd.scope_kinds)
         and case
           when pd.requires_cashbook_possession then
             e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id
           else
             e.scope_type = 'ORGANIZATION'
             or (e.scope_type = 'BUILDING' and e.building_id = p_building_id)
             or (e.scope_type = 'CASHBOOK' and e.cashbook_id = p_cashbook_id)
             or (e.scope_type = 'AREA' and p_building_id is not null and exists (
                  select 1 from public.area_buildings ab
                   where ab.organization_id = p_organization_id
                     and ab.area_id = e.area_id and ab.building_id = p_building_id))
         end
    ) as role_allow
),
emergency as materialized (
  select exists (
    select 1 from app_private.tenant_emergency_denies d
      join locked_org lo on lo.id = d.organization_id
      cross join at
     where (d.permission_key is null or d.permission_key = p_permission_key)
       and d.active_from <= at.evaluated_at
       and (d.expires_at is null or d.expires_at > at.evaluated_at)
  ) as denied
),
-- Fix #7: possession is fail-closed on missing permission too.
possession as materialized (
  select case
    when not exists (select 1 from permission) then false
    when not (select requires_cashbook_possession from permission) then true
    when p_cashbook_id is null then false
    else exists (
      select 1
        from public.cashbook_possession_bindings cp
        join membership m
          on m.organization_id = cp.organization_id and m.id = cp.membership_id
        join permission pd
          on cp.possession_kind = any(pd.accepted_possession_kinds)
        cross join at
       where cp.organization_id = p_organization_id
         and cp.cashbook_id = p_cashbook_id
         and cp.valid_from <= at.evaluated_at
         and (cp.valid_to is null or cp.valid_to > at.evaluated_at))
  end as accepted
),
-- Fix #8: all arms org-filtered. Activation AND expiry boundaries.
boundaries as materialized (
  select min(x.boundary) as nearest_deadline
    from (
      select m0.valid_from as boundary
        from public.organization_memberships m0
       where m0.organization_id = p_organization_id and m0.user_id = p_actor
      union all
      select m0.valid_to
        from public.organization_memberships m0
       where m0.organization_id = p_organization_id and m0.user_id = p_actor
      union all
      select rb.valid_from
        from public.role_bindings rb
        join public.organization_memberships m0
          on m0.organization_id = rb.organization_id and m0.id = rb.membership_id
       where m0.user_id = p_actor and rb.organization_id = p_organization_id
      union all
      select rb.valid_to
        from public.role_bindings rb
        join public.organization_memberships m0
          on m0.organization_id = rb.organization_id and m0.id = rb.membership_id
       where m0.user_id = p_actor and rb.organization_id = p_organization_id
      union all
      select o.expires_at
        from public.member_permission_overrides o
        join public.organization_memberships m0
          on m0.organization_id = o.organization_id and m0.id = o.membership_id
       where m0.user_id = p_actor
         and o.organization_id = p_organization_id
         and o.permission_key = p_permission_key
         and o.revoked_at is null
      union all
      select cp.valid_from
        from public.cashbook_possession_bindings cp
        join public.organization_memberships m0
          on m0.organization_id = cp.organization_id and m0.id = cp.membership_id
       where m0.user_id = p_actor
         and cp.organization_id = p_organization_id
         and cp.cashbook_id = p_cashbook_id
      union all
      select cp.valid_to
        from public.cashbook_possession_bindings cp
        join public.organization_memberships m0
          on m0.organization_id = cp.organization_id and m0.id = cp.membership_id
       where m0.user_id = p_actor
         and cp.organization_id = p_organization_id
         and cp.cashbook_id = p_cashbook_id
      union all
      select d.active_from from app_private.tenant_emergency_denies d
       where d.organization_id = p_organization_id
         and (d.permission_key is null or d.permission_key = p_permission_key)
      union all
      select d.expires_at from app_private.tenant_emergency_denies d
       where d.organization_id = p_organization_id
         and (d.permission_key is null or d.permission_key = p_permission_key)
    ) x, at
   where x.boundary is not null and x.boundary > at.evaluated_at
)
select
  case
    when not exists (select 1 from locked_org) then false
    when not exists (select 1 from permission) then false
    when not (select satisfied from dimensions) then false
    when not exists (select 1 from membership) then false
    when not coalesce((select valid from target), false) then false
    when (select denied from emergency) then false
    when (select ok from malformed_guard) < 0 then false -- never taken; forces eval
    when (select member_deny from scope_cover) then false
    when (select role_deny from scope_cover) then false
    when not (select accepted from possession) then false
    when (select member_allow from scope_cover) then true
    when (select role_allow from scope_cover) then true
    else false
  end as allowed,
  (select lo.authorization_version from locked_org lo),
  (select b.nearest_deadline from boundaries b),
  (select a.evaluated_at from at a),
  case
    when not exists (select 1 from locked_org) then 'ORGANIZATION_INACTIVE_OR_MISSING'
    when not exists (select 1 from permission) then 'PERMISSION_INACTIVE_OR_MISSING'
    when not (select satisfied from dimensions) then 'REQUIRED_DIMENSION_MISSING'
    when not exists (select 1 from membership) then 'MEMBERSHIP_INACTIVE_OR_MISSING'
    when not coalesce((select valid from target), false) then 'TARGET_CROSS_ORG_OR_MISSING'
    when (select denied from emergency) then 'EMERGENCY_DENY'
    when (select member_deny from scope_cover) then 'MEMBER_DENY'
    when (select role_deny from scope_cover) then 'ROLE_DENY'
    when not (select accepted from possession) then 'POSSESSION_MISSING'
    when (select member_allow from scope_cover) then 'MEMBER_ALLOW'
    when (select role_allow from scope_cover) then 'ROLE_ALLOW'
    else 'DEFAULT_DENY'
  end as decision_reason
from (select 1) _;
$$;








--
-- Name: authorized_scope_all_v3(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.authorized_scope_all_v3(p_permission_key text) RETURNS TABLE(org_wide boolean, building_ids uuid[], cashbook_ids uuid[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  with per_org as (
    select s.org_wide, s.building_ids, s.cashbook_ids
      from unnest(public.my_org_ids()) as o(org)
      cross join lateral app_private.authorized_scope_v3(p_permission_key, o.org) s
  )
  select
    (select coalesce(bool_or(p.org_wide), false) from per_org p),
    (select coalesce(array_agg(distinct t.b), '{}'::uuid[])
       from per_org p cross join lateral unnest(p.building_ids) as t(b)),
    (select coalesce(array_agg(distinct t.c), '{}'::uuid[])
       from per_org p cross join lateral unnest(p.cashbook_ids) as t(c));
$$;








--
-- Name: authorized_scope_v3(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.authorized_scope_v3(p_permission_key text, p_org uuid) RETURNS TABLE(org_wide boolean, building_ids uuid[], cashbook_ids uuid[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
with
-- now() STABLE (bản ghi dùng clock_timestamp() VOLATILE — khác biệt có chủ đích).
at as (select now() as ts),

org_ok as (
  select o.id
    from public.organizations o
   where o.id = p_org
     and o.status = 'ACTIVE'
),

permission as (
  select pd.*
    from public.permission_definitions pd
    join org_ok on true
   where pd.key = p_permission_key
     and pd.permission_domain = 'TENANT'
     and pd.is_active
),

membership as (
  select m.id, m.organization_id
    from public.organization_memberships m
    join org_ok o on o.id = m.organization_id
   cross join at
   where m.user_id = (select auth.uid())
     and m.status = 'ACTIVE'
     and coalesce(m.valid_from, '-infinity'::timestamptz) <= at.ts
     and (m.valid_to is null or m.valid_to > at.ts)
),

-- Lệnh cấm khẩn cấp cấp tổ chức: chặn tất cả.
emergency as (
  select exists (
    select 1
      from app_private.tenant_emergency_denies d
     cross join at
     where d.organization_id = p_org
       and (d.permission_key is null or d.permission_key = p_permission_key)
       and d.active_from <= at.ts
       and (d.expires_at is null or d.expires_at > at.ts)
  ) as denied
),

-- Cạnh phạm vi từ NGOẠI LỆ riêng của thành viên.
-- Khác bản ghi: override không có cạnh scope nào thì ở đây BỎ QUA (không raise).
-- Bản ghi raise để bắt dữ liệu hỏng lúc ghi; bản đọc phải trả rỗng chứ không
-- được làm gãy câu SELECT. Việc phát hiện override dị dạng do CI/gate lo.
member_edges as (
  select o.effect, s.scope_type, s.building_id, s.cashbook_id, s.area_id
    from membership m
    join public.member_permission_overrides o
      on o.organization_id = m.organization_id
     and o.membership_id   = m.id
     and o.permission_key  = p_permission_key
    join public.member_override_scopes mos
      on mos.organization_id = p_org and mos.override_id = o.id
    join public.authorization_scopes s
      on s.organization_id = p_org and s.id = mos.scope_id
   cross join at
   where o.revoked_at is null
     and (o.expires_at is null or o.expires_at > at.ts)
),

-- Cạnh phạm vi từ VAI TRÒ.
role_edges as (
  select rp.effect, s.scope_type, s.building_id, s.cashbook_id, s.area_id
    from membership m
    join public.role_bindings rb
      on rb.organization_id = m.organization_id and rb.membership_id = m.id
    join public.organization_roles r
      on r.organization_id = rb.organization_id and r.id = rb.role_id
     and coalesce(r.status, 'ACTIVE') = 'ACTIVE'
    join public.role_permissions rp
      on rp.organization_id = rb.organization_id
     and rp.role_id         = rb.role_id
     and rp.permission_key  = p_permission_key
    join public.role_binding_scopes rbs
      on rbs.organization_id = rb.organization_id and rbs.role_binding_id = rb.id
    join public.authorization_scopes s
      on s.organization_id = rbs.organization_id and s.id = rbs.scope_id
   cross join at
   where coalesce(rb.valid_from, '-infinity'::timestamptz) <= at.ts
     and (rb.valid_to is null or rb.valid_to > at.ts)
),

edges as (
  select * from member_edges
  union all
  select * from role_edges
),

-- Nở AREA → BUILDING cho cả DENY lẫn ALLOW (giống bản ghi).
edge_buildings as (
  select e.effect, b.building_id
    from edges e
    join lateral (
      select e.building_id as building_id where e.scope_type = 'BUILDING'
      union all
      select ab.building_id
        from public.area_buildings ab
       where e.scope_type = 'AREA'
         and ab.organization_id = p_org
         and ab.area_id = e.area_id
    ) b on true
   where b.building_id is not null
),

deny_org as (
  select exists (select 1 from edges where effect = 'DENY' and scope_type = 'ORGANIZATION') as v
),
deny_b as (
  select coalesce(array_agg(distinct building_id), '{}'::uuid[]) as v
    from edge_buildings where effect = 'DENY'
),
deny_c as (
  select coalesce(array_agg(distinct cashbook_id), '{}'::uuid[]) as v
    from edges where effect = 'DENY' and scope_type = 'CASHBOOK' and cashbook_id is not null
),

-- ALLOW phải nằm trong scope_kinds mà registry cho phép với quyền này.
-- Quyền yêu cầu possession: CHỈ cạnh CASHBOOK mới cấp (giống bản ghi).
allow_org as (
  select exists (
    select 1 from edges e, permission pd
     where e.effect = 'ALLOW'
       and e.scope_type = 'ORGANIZATION'
       and e.scope_type = any(pd.scope_kinds)
       and not pd.requires_cashbook_possession
  ) as v
),
allow_b as (
  select coalesce(array_agg(distinct eb.building_id), '{}'::uuid[]) as v
    from edge_buildings eb, permission pd
   where eb.effect = 'ALLOW'
     and not pd.requires_cashbook_possession
     and ('BUILDING' = any(pd.scope_kinds) or 'AREA' = any(pd.scope_kinds))
),
allow_c as (
  select coalesce(array_agg(distinct e.cashbook_id), '{}'::uuid[]) as v
    from edges e, permission pd
   where e.effect = 'ALLOW'
     and e.scope_type = 'CASHBOOK'
     and e.cashbook_id is not null
     and 'CASHBOOK' = any(pd.scope_kinds)
),

-- Sổ quỹ mà tôi đang thực sự GIỮ, với loại giữ mà quyền này chấp nhận.
possessed as (
  select coalesce(array_agg(distinct cp.cashbook_id), '{}'::uuid[]) as v
    from public.cashbook_possession_bindings cp
    join membership m
      on m.organization_id = cp.organization_id and m.id = cp.membership_id
    join permission pd
      on cp.possession_kind = any(pd.accepted_possession_kinds)
   cross join at
   where cp.organization_id = p_org
     and cp.valid_from <= at.ts
     and (cp.valid_to is null or cp.valid_to > at.ts)
),

-- Toàn bộ toà của tổ chức — dùng khi ALLOW ở mức ORGANIZATION.
all_buildings as (
  select coalesce(array_agg(b.id), '{}'::uuid[]) as v
    from public.buildings b
   where b.organization_id = p_org and b.deleted_at is null
),
all_cashbooks as (
  select coalesce(array_agg(a.id), '{}'::uuid[]) as v
    from public.accounts a
   where a.organization_id = p_org and a.deleted_at is null
),

gates as (
  select
    exists (select 1 from org_ok)     as org_active,
    exists (select 1 from permission) as perm_ok,
    exists (select 1 from membership) as member_ok,
    (select denied from emergency)    as emergency_denied,
    coalesce((select 'BUILDING' = any(pd.required_dimensions) from permission pd), false) as needs_building,
    coalesce((select 'CASHBOOK' = any(pd.required_dimensions) from permission pd), false) as needs_cashbook,
    coalesce((select pd.requires_cashbook_possession from permission pd), false)          as needs_possession
),

resolved as (
  select
    g.org_active and g.perm_ok and g.member_ok and not g.emergency_denied as pass,
    g.needs_building, g.needs_cashbook, g.needs_possession,
    (select v from deny_org)      as d_org,
    (select v from deny_b)        as d_b,
    (select v from deny_c)        as d_c,
    (select v from allow_org)     as a_org,
    (select v from allow_b)       as a_b,
    (select v from allow_c)       as a_c,
    (select v from possessed)     as poss,
    (select v from all_buildings) as all_b,
    (select v from all_cashbooks) as all_c
  from gates g
),

-- Tập toà hiệu lực: nguồn ALLOW (org-wide ⇒ mọi toà) trừ đi DENY.
--
-- ⚠ `needs_cashbook`: quyền khai required_dimensions=['CASHBOOK'] (vd cashbooks.post)
--   thì MỌI câu hỏi phải kèm sổ quỹ. Hỏi "được làm ở toà X không" (không kèm sổ)
--   luôn bị bản GHI từ chối ở tầng dimensions ⇒ bản ĐỌC phải trả rỗng cho trục toà,
--   nếu không đường đọc sẽ nới hơn đường ghi.
eff_b as (
  select coalesce(array_agg(distinct t.b), '{}'::uuid[]) as v
    from resolved r
   cross join lateral unnest(case when r.a_org then r.all_b else r.a_b end) as t(b)
   where r.pass and not r.d_org and not r.needs_possession and not r.needs_cashbook
     and not (t.b = any(r.d_b))
),

-- Tập sổ quỹ hiệu lực. Quyền cần giữ sổ: phải có cạnh ALLOW CASHBOOK **và**
-- đang thực sự giữ sổ đó (bản ghi cũng đòi đúng hai điều kiện này).
--
-- ⚠ `needs_building`: đối xứng với trên — quyền khai required_dimensions=['BUILDING']
--   (income_expenses.create/edit/approve/cancel, reports_finance.analysis) thì câu hỏi
--   chỉ-kèm-sổ luôn bị bản GHI từ chối ⇒ trục sổ phải rỗng.
--   Bỏ sót điều này từng làm đường đọc nới hơn đường ghi 105 cặp (owner) và 42 cặp (partner).
eff_c_src as (
  select r.pass, r.d_org, r.d_c, r.needs_building,
         case
           when r.needs_possession then array(select x from unnest(r.a_c) as u(x) where x = any(r.poss))
           when r.a_org            then r.all_c
           else r.a_c
         end as src
    from resolved r
),
eff_c as (
  select coalesce(array_agg(distinct t.c), '{}'::uuid[]) as v
    from eff_c_src s
   cross join lateral unnest(s.src) as t(c)
   where s.pass and not s.d_org and not s.needs_building
     and not (t.c = any(s.d_c))
)

select
  -- org_wide: hỏi KHÔNG kèm chiều nào mà vẫn được phép.
  -- Quyền có required_dimensions thì câu hỏi trống luôn thất bại (giống bản ghi).
  case
    when not r.pass then false
    when r.needs_building or r.needs_cashbook then false
    when r.d_org then false
    else r.a_org
  end as org_wide,
  (select v from eff_b) as building_ids,
  (select v from eff_c) as cashbook_ids
from resolved r;
$$;








--
-- Name: FUNCTION authorized_scope_v3(p_permission_key text, p_org uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.authorized_scope_v3(p_permission_key text, p_org uuid) IS 'Bản ĐỌC của authorize_tenant_action_v3: trả TẬP phạm vi (org_wide, buildings, cashbooks) thay vì 1 quyết định. STABLE, không khoá, không raise — an toàn dùng trong RLS.';








--
-- Name: autofill_pre_invoice_audit_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.autofill_pre_invoice_audit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
begin
  if new.organization_id is null and new.invoice_id is not null then
    select i.organization_id into new.organization_id from public.invoices i where i.id = new.invoice_id;
  end if;
  return new;
end $$;








--
-- Name: autofill_pre_notification_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.autofill_pre_notification_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
begin
  if new.organization_id is null then
    if new.invoice_id is not null then
      select i.organization_id into new.organization_id from public.invoices i where i.id = new.invoice_id;
    end if;
    if new.organization_id is null and new.contract_id is not null then
      select c.organization_id into new.organization_id from public.contracts c where c.id = new.contract_id;
    end if;
    if new.organization_id is null and new.user_id is not null then
      new.organization_id := app_private.single_org_of_user_v1(new.user_id);
    end if;
  end if;
  return new;
end $$;








--
-- Name: autofill_pre_room_event_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.autofill_pre_room_event_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
begin
  if new.organization_id is null and new.building_id is not null then
    select b.organization_id into new.organization_id from public.buildings b where b.id = new.building_id;
  end if;
  return new;
end $$;








--
-- Name: begin_accounting_chain_write_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.begin_accounting_chain_write_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private'
    AS $$
BEGIN
  INSERT INTO app_private.accounting_chain_writer_xids (
    transaction_id, backend_pid, opened_at
  ) VALUES (
    txid_current(), pg_backend_pid(), clock_timestamp()
  ) ON CONFLICT (transaction_id, backend_pid)
    DO UPDATE SET opened_at = EXCLUDED.opened_at;
END;
$$;








--
-- Name: begin_contract_termination_write_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.begin_contract_termination_write_v1(p_termination uuid, p_scope text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF p_termination IS NULL OR p_scope IS NULL THEN
    RAISE EXCEPTION 'begin_contract_termination_write_v1: thiếu tham số' USING ERRCODE = '22023';
  END IF;
  INSERT INTO app_private.contract_termination_writer_xids
    (transaction_id, backend_pid, termination_id, scope)
  VALUES
    (pg_current_xact_id(), pg_backend_pid(), p_termination, p_scope)
  ON CONFLICT (transaction_id, backend_pid, termination_id)
  DO UPDATE SET scope = excluded.scope, opened_at = now();
END
$$;








--
-- Name: begin_ie_flex_write_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.begin_ie_flex_write_v1(p_voucher uuid, p_scope text) RETURNS void
