--
-- Name: building_org_visible_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.building_org_visible_v1(p_building uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT NOT EXISTS (
    SELECT 1
      FROM public.buildings b
     WHERE b.id = p_building
       AND (
         -- Bản sao/sandbox: super admin KHÔNG được thấy.
         (public.is_super_admin() AND b.organization_id = ANY(public.sandbox_org_ids()))
         -- Toà của tài khoản demo: admin và super admin KHÔNG được thấy.
         OR ((public.is_super_admin() OR public.is_admin())
             AND b.user_id = ANY(public.demo_user_ids()))
       )
  );
$$;








--
-- Name: FUNCTION building_org_visible_v1(p_building uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.building_org_visible_v1(p_building uuid) IS 'Toà này có được hiện cho người đang đăng nhập không. Nói lại ĐÚNG hai policy RESTRICTIVE của RLS trên public.buildings, để các RPC SECURITY DEFINER (vốn đi vòng qua RLS) áp cùng một luật. Sửa luật thì phải sửa cả hai chỗ.';








--
-- Name: buildings_for_v3(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.buildings_for_v3(p_permission_key text) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  with raw as (
    select case when s.org_wide
             then (select coalesce(array_agg(b.id), '{}'::uuid[])
                     from public.buildings b
                    where b.organization_id = any(public.my_org_ids())
                      and b.deleted_at is null)
             else s.building_ids
           end as ids
      from app_private.authorized_scope_all_v3(p_permission_key) s
  ),
  -- Trải mảng ra thành hàng rồi JOIN. Viết `b.id = any((select ids from raw))`
  -- KHÔNG chạy được: Postgres hiểu `any(<subquery>)` là dạng tập hợp chứ không
  -- phải dạng mảng, nên ném 42883 "uuid = uuid[]".
  scope as (
    select unnest(r.ids) as id from raw r
  )
  select coalesce(
    (select array_agg(b.id)
       from public.buildings b
       join scope s2 on s2.id = b.id
      where b.deleted_at is null
        -- ORG_ISOLATION_V1: nói lại đúng hai policy RESTRICTIVE của RLS trên
        -- public.buildings, để nhánh SECURITY DEFINER (vốn đi vòng qua RLS)
        -- không còn rộng hơn nhánh đọc thẳng bảng.
        and not (public.is_super_admin()
                 and b.organization_id = any(public.sandbox_org_ids()))
        and not ((public.is_super_admin() or public.is_admin())
                 and b.user_id = any(public.demo_user_ids()))),
    '{}'::uuid[]);
$$;








--
-- Name: FUNCTION buildings_for_v3(p_permission_key text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.buildings_for_v3(p_permission_key text) IS 'Danh sách toà người đang đăng nhập được thao tác với một quyền. Từ 01/08/2026 lọc thêm ĐÚNG hai mệnh đề RESTRICTIVE của RLS trên public.buildings (ẩn org sandbox khỏi super admin, ẩn toà của tài khoản demo khỏi admin) — trước đó nhánh DEFINER rộng hơn nhánh đọc bảng nên dữ liệu nhiều tổ chức trộn vào nhau.';








--
-- Name: bump_org_authorization_version(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.bump_org_authorization_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_org uuid;
begin
  if tg_op = 'DELETE' then v_org := (to_jsonb(old)->>'organization_id')::uuid;
  else v_org := (to_jsonb(new)->>'organization_id')::uuid; end if;
  if v_org is not null then
    update public.organizations set authorization_version = authorization_version + 1 where id = v_org;
  end if;
  return coalesce(new, old);
end;
$$;








--
-- Name: business_performance_analysis_decision_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.business_performance_analysis_decision_v1(p_actor uuid, p_organization_id uuid, p_building_id uuid) RETURNS TABLE(allowed boolean, authorization_version bigint, analysis_provenance jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_primary_allowed boolean;
  v_primary_version bigint;
  v_primary_reason text;
  v_fallback_allowed boolean;
  v_fallback_version bigint;
  v_fallback_reason text;
  v_legacy_detail_deny boolean := false;
  v_legacy_detail_allow boolean := false;
  v_legacy_view_deny boolean := false;
  v_legacy_view_allow boolean := false;
BEGIN
  IF p_actor IS NULL OR p_organization_id IS NULL OR p_building_id IS NULL THEN
    RETURN QUERY
    SELECT false, NULL::bigint, jsonb_build_object(
      'permission_key', 'reports_finance.analysis',
      'decision_reason', 'INVALID_DECISION_INPUT',
      'fallback_used', false
    );
    RETURN;
  END IF;

  SELECT decision.allowed, decision.authorization_version, decision.decision_reason
    INTO v_primary_allowed, v_primary_version, v_primary_reason
  FROM app_private.authorize_tenant_action_v3(
    p_actor => p_actor,
    p_organization_id => p_organization_id,
    p_permission_key => 'reports_finance.analysis',
    p_building_id => p_building_id,
    p_cashbook_id => NULL
  ) AS decision;

  -- Only DEFAULT_DENY represents a rollout gap. Missing or inactive definitions
  -- and every other canonical denial remain authoritative hard denials.
  IF NOT COALESCE(v_primary_allowed, false)
     AND v_primary_reason IS DISTINCT FROM 'DEFAULT_DENY' THEN
    RETURN QUERY
    SELECT false, v_primary_version, jsonb_build_object(
      'permission_key', 'reports_finance.analysis',
      'decision_reason', 'CANONICAL_DETAIL_DENY',
      'canonical_decision_reason', COALESCE(v_primary_reason, 'NO_RESULT'),
      'fallback_used', false
    );
    RETURN;
  END IF;

  WITH applicable_detail_assignments AS (
    SELECT COALESCE(sa.permissions, r.permissions) AS permissions
    FROM public.staff_assignments sa
    LEFT JOIN public.roles r
      ON r.id = sa.role_id
     AND r.organization_id = p_organization_id
    WHERE sa.staff_id = p_actor
      AND sa.organization_id = p_organization_id
      AND (
        sa.building_id = p_building_id
        OR (
          sa.area_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public.area_buildings ab
            WHERE ab.organization_id = p_organization_id
              AND ab.area_id = sa.area_id
              AND ab.building_id = p_building_id
          )
        )
        OR (sa.building_id IS NULL AND sa.area_id IS NULL)
      )
  )
  SELECT
    COALESCE(bool_or(
      (permissions -> 'reports_finance') ? 'analysis'
      AND permissions -> 'reports_finance' -> 'analysis' IS DISTINCT FROM 'true'::jsonb
    ), false),
    COALESCE(bool_or(
      (permissions -> 'reports_finance') ? 'analysis'
      AND permissions -> 'reports_finance' -> 'analysis' = 'true'::jsonb
    ), false)
    INTO v_legacy_detail_deny, v_legacy_detail_allow
  FROM applicable_detail_assignments;

  IF v_legacy_detail_deny THEN
    RETURN QUERY
    SELECT false, v_primary_version, jsonb_build_object(
      'permission_key', 'reports_finance.analysis',
      'decision_reason', 'LEGACY_DETAIL_DENY',
      'canonical_decision_reason', v_primary_reason,
      'fallback_used', false
    );
    RETURN;
  END IF;

  IF COALESCE(v_primary_allowed, false) THEN
    RETURN QUERY
    SELECT true, v_primary_version, jsonb_build_object(
      'permission_key', 'reports_finance.analysis',
      'decision_reason', 'CANONICAL_DETAIL_ALLOW',
      'canonical_decision_reason', v_primary_reason,
      'fallback_used', false
    );
    RETURN;
  END IF;

  IF v_legacy_detail_allow THEN
    RETURN QUERY
    SELECT true, v_primary_version, jsonb_build_object(
      'permission_key', 'reports_finance.analysis',
      'decision_reason', 'LEGACY_DETAIL_ALLOW',
      'canonical_decision_reason', v_primary_reason,
      'fallback_used', false
    );
    RETURN;
  END IF;

  SELECT decision.allowed, decision.authorization_version, decision.decision_reason
    INTO v_fallback_allowed, v_fallback_version, v_fallback_reason
  FROM app_private.authorize_tenant_action_v3(
    p_actor => p_actor,
    p_organization_id => p_organization_id,
    p_permission_key => 'reports_finance.view',
    p_building_id => p_building_id,
    p_cashbook_id => NULL
  ) AS decision;

  IF NOT COALESCE(v_fallback_allowed, false)
     AND v_fallback_reason IS DISTINCT FROM 'DEFAULT_DENY' THEN
    RETURN QUERY
    SELECT false, COALESCE(v_fallback_version, v_primary_version), jsonb_build_object(
      'permission_key', 'reports_finance.view',
      'decision_reason', 'CANONICAL_VIEW_DENY',
      'canonical_decision_reason', COALESCE(v_fallback_reason, 'NO_RESULT'),
      'fallback_used', true,
      'primary_decision_reason', v_primary_reason
    );
    RETURN;
  END IF;

  WITH applicable_view_assignments AS (
    SELECT COALESCE(sa.permissions, r.permissions) AS permissions
    FROM public.staff_assignments sa
    LEFT JOIN public.roles r
      ON r.id = sa.role_id
     AND r.organization_id = p_organization_id
    WHERE sa.staff_id = p_actor
      AND sa.organization_id = p_organization_id
      AND (
        sa.building_id = p_building_id
        OR (
          sa.area_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public.area_buildings ab
            WHERE ab.organization_id = p_organization_id
              AND ab.area_id = sa.area_id
              AND ab.building_id = p_building_id
          )
        )
        OR (sa.building_id IS NULL AND sa.area_id IS NULL)
      )
  )
  SELECT
    COALESCE(bool_or(
      (permissions -> 'reports_finance') ? 'view'
      AND permissions -> 'reports_finance' -> 'view' IS DISTINCT FROM 'true'::jsonb
    ), false),
    COALESCE(bool_or(
      (permissions -> 'reports_finance') ? 'view'
      AND permissions -> 'reports_finance' -> 'view' = 'true'::jsonb
    ), false)
    INTO v_legacy_view_deny, v_legacy_view_allow
  FROM applicable_view_assignments;

  IF v_legacy_view_deny THEN
    RETURN QUERY
    SELECT false, COALESCE(v_fallback_version, v_primary_version), jsonb_build_object(
      'permission_key', 'reports_finance.view',
      'decision_reason', 'LEGACY_VIEW_DENY',
      'canonical_decision_reason', v_fallback_reason,
      'fallback_used', true,
      'primary_decision_reason', v_primary_reason
    );
    RETURN;
  END IF;

  IF COALESCE(v_fallback_allowed, false) THEN
    RETURN QUERY
    SELECT true, COALESCE(v_fallback_version, v_primary_version), jsonb_build_object(
      'permission_key', 'reports_finance.view',
      'decision_reason', 'CANONICAL_VIEW_ALLOW',
      'canonical_decision_reason', v_fallback_reason,
      'fallback_used', true,
      'primary_decision_reason', v_primary_reason
    );
    RETURN;
  END IF;

  IF v_legacy_view_allow THEN
    RETURN QUERY
    SELECT true, COALESCE(v_fallback_version, v_primary_version), jsonb_build_object(
      'permission_key', 'reports_finance.view',
      'decision_reason', 'LEGACY_VIEW_ALLOW',
      'canonical_decision_reason', v_fallback_reason,
      'fallback_used', true,
      'primary_decision_reason', v_primary_reason
    );
    RETURN;
  END IF;

  RETURN QUERY
  SELECT false, COALESCE(v_fallback_version, v_primary_version), jsonb_build_object(
    'permission_key', 'reports_finance.view',
    'decision_reason', 'NO_DECISION',
    'canonical_decision_reason', v_fallback_reason,
    'fallback_used', true,
    'primary_decision_reason', v_primary_reason
  );
END;
$$;








--
-- Name: FUNCTION business_performance_analysis_decision_v1(p_actor uuid, p_organization_id uuid, p_building_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.business_performance_analysis_decision_v1(p_actor uuid, p_organization_id uuid, p_building_id uuid) IS 'Private deny-wins analysis decision. Legacy detail/view fallback is considered only for canonical DEFAULT_DENY; inactive or missing permission definitions hard-deny.';








--
-- Name: business_performance_authorized_buildings_v1(uuid, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.business_performance_authorized_buildings_v1(p_organization_id uuid, p_include_restricted boolean DEFAULT true) RETURNS TABLE(building_id uuid, building_name text, restricted_allowed boolean, analysis_provenance jsonb, authorization_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_authorization_version bigint;
  v_analysis_allowed boolean;
  v_analysis_version bigint;
  v_analysis_provenance jsonb;
  v_restricted_allowed boolean := false;
  v_restricted_version bigint;
  v_building record;
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL THEN
    RETURN;
  END IF;

  SELECT app_private.lock_org_for_decision_v1(p_organization_id)
    INTO v_authorization_version;
  IF v_authorization_version IS NULL THEN
    RETURN;
  END IF;

  BEGIN
    SELECT actor.user_id
      INTO v_actor
    FROM app_private.resolve_finance_actor_v2(p_organization_id) AS actor;
  EXCEPTION
    WHEN insufficient_privilege THEN
      RETURN;
  END;

  FOR v_building IN
    SELECT
      b.id,
      COALESCE(NULLIF(btrim(b.name), ''), 'Unnamed building') AS name
    FROM public.buildings b
    WHERE b.organization_id = p_organization_id
      AND b.is_virtual = false
      AND b.deleted_at IS NULL
      AND COALESCE(public.can_access_building(b.id), false)
    ORDER BY lower(COALESCE(NULLIF(btrim(b.name), ''), 'Unnamed building')) COLLATE "C",
             COALESCE(NULLIF(btrim(b.name), ''), 'Unnamed building') COLLATE "C",
             b.id
  LOOP
    SELECT decision.allowed, decision.authorization_version, decision.analysis_provenance
      INTO v_analysis_allowed, v_analysis_version, v_analysis_provenance
    FROM app_private.business_performance_analysis_decision_v1(
      p_actor => v_actor,
      p_organization_id => p_organization_id,
      p_building_id => v_building.id
    ) AS decision;

    CONTINUE WHEN NOT COALESCE(v_analysis_allowed, false)
      OR v_analysis_version IS DISTINCT FROM v_authorization_version;

    v_restricted_allowed := false;
    v_restricted_version := v_authorization_version;
    IF COALESCE(p_include_restricted, false) THEN
      SELECT decision.allowed, decision.authorization_version
        INTO v_restricted_allowed, v_restricted_version
      FROM app_private.authorize_tenant_action_v3(
        p_actor => v_actor,
        p_organization_id => p_organization_id,
        p_permission_key => 'income_expenses.restricted_view',
        p_building_id => v_building.id,
        p_cashbook_id => NULL
      ) AS decision;
    END IF;

    building_id := v_building.id;
    building_name := v_building.name;
    restricted_allowed := COALESCE(v_restricted_allowed, false)
      AND v_restricted_version IS NOT DISTINCT FROM v_authorization_version;
    analysis_provenance := v_analysis_provenance;
    authorization_version := v_authorization_version;
    RETURN NEXT;
  END LOOP;
END;
$$;








--
-- Name: FUNCTION business_performance_authorized_buildings_v1(p_organization_id uuid, p_include_restricted boolean); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.business_performance_authorized_buildings_v1(p_organization_id uuid, p_include_restricted boolean) IS 'Private physical-building roster for an active finance actor. Requires normalized report authorization and legacy can_access_building visibility.';








--
-- Name: business_performance_exact_scope_v1(uuid, uuid[], boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.business_performance_exact_scope_v1(p_organization_id uuid, p_building_ids uuid[], p_require_restricted boolean DEFAULT false) RETURNS TABLE(authorization_version bigint, building_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_roster jsonb;
  v_roster_count bigint;
  v_distinct_roster_count bigint;
  v_min_authorization_version bigint;
  v_max_authorization_version bigint;
  v_building_id uuid;
BEGIN
  IF auth.uid() IS NULL
     OR p_organization_id IS NULL
     OR p_building_ids IS NULL
     OR cardinality(p_building_ids) = 0
     OR array_position(p_building_ids, NULL::uuid) IS NOT NULL THEN
    RAISE EXCEPTION 'Business performance access denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(DISTINCT requested.building_id ORDER BY requested.building_id)
    INTO v_building_ids
  FROM unnest(p_building_ids) AS requested(building_id);

  SELECT
    count(*),
    count(DISTINCT roster.building_id),
    min(roster.authorization_version),
    max(roster.authorization_version),
    COALESCE(
      jsonb_object_agg(
        roster.building_id::text,
        jsonb_build_object('restricted_allowed', roster.restricted_allowed)
      ),
      '{}'::jsonb
    )
    INTO
      v_roster_count,
      v_distinct_roster_count,
      v_min_authorization_version,
      v_max_authorization_version,
      v_roster
  FROM app_private.business_performance_authorized_buildings_v1(
    p_organization_id,
    COALESCE(p_require_restricted, false)
  ) AS roster;

  IF v_roster_count = 0
     OR v_roster_count <> v_distinct_roster_count
     OR v_min_authorization_version IS DISTINCT FROM v_max_authorization_version THEN
    RAISE EXCEPTION 'Business performance access denied'
      USING ERRCODE = '42501';
  END IF;

  FOREACH v_building_id IN ARRAY v_building_ids LOOP
    IF NOT (v_roster ? v_building_id::text)
       OR (
         COALESCE(p_require_restricted, false)
         AND NOT COALESCE(
           (v_roster -> v_building_id::text ->> 'restricted_allowed')::boolean,
           false
         )
       ) THEN
      RAISE EXCEPTION 'Business performance access denied'
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN QUERY
  SELECT v_max_authorization_version, v_building_ids;
END;
$$;








