$$;








--
-- Name: can_read_storage_object_v1(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_read_storage_object_v1(p_bucket text, p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select
    p_bucket not in ('customer-id-cards','customer-images','income-expense-attachments',
                     'job-attachments','payment-receipts','meter-images','document-templates')
    or (select public.is_super_admin())
    or exists (
      select 1 from app_private.storage_object_links l
       where l.bucket_id = p_bucket and l.object_name = p_name
         and ( (l.organization_id is not null and l.organization_id in (select unnest(public.my_org_ids())))
            or (l.organization_id is null and l.owner_user_id = (select auth.uid())) )
    );
$$;








--
-- Name: can_see_cashbook_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_see_cashbook_v1(p_org uuid, p_cashbook uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF public.is_super_admin() THEN RETURN true; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organization_memberships m
                  WHERE m.user_id = auth.uid() AND m.organization_id = p_org
                    AND m.status = 'ACTIVE') THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM app_private.ie_visible_cashbook_ids_v1() v
                  WHERE v.cashbook_id = p_cashbook);
END
$$;








--
-- Name: can_v3(text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_v3(p_permission_key text, p_building uuid DEFAULT NULL::uuid, p_cashbook uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select exists (
    select 1
      from public.permission_definitions pd
      join public.organization_memberships m
        on m.user_id = (select auth.uid())
       and m.status = 'ACTIVE'
       and coalesce(m.valid_from, '-infinity'::timestamptz) <= now()
       and (m.valid_to is null or m.valid_to > now())
      join public.organizations o
        on o.id = m.organization_id and o.status = 'ACTIVE'
     where pd.key = p_permission_key
       and pd.permission_domain = 'TENANT'
       and pd.is_active
       -- chiều bắt buộc phải được cung cấp (giống tầng dimensions của bản ghi)
       and not ('BUILDING' = any(pd.required_dimensions) and p_building is null)
       and not ('CASHBOOK' = any(pd.required_dimensions) and p_cashbook is null)
       -- mục tiêu phải cùng tổ chức
       and (p_building is null or exists (
             select 1 from public.buildings b
              where b.id = p_building and b.organization_id = m.organization_id))
       and (p_cashbook is null or exists (
             select 1 from public.accounts a
              where a.id = p_cashbook and a.organization_id = m.organization_id
                and a.deleted_at is null))
       and not exists (
         select 1 from app_private.tenant_emergency_denies d
          where d.organization_id = m.organization_id
            and (d.permission_key is null or d.permission_key = p_permission_key)
            and d.active_from <= now()
            and (d.expires_at is null or d.expires_at > now()))
       -- CẤM: bất kỳ phạm vi nào PHỦ mục tiêu
       and not exists (
         select 1
           from public.member_permission_overrides ov
           join public.member_override_scopes mos on mos.override_id = ov.id
           join public.authorization_scopes s on s.id = mos.scope_id
          where ov.membership_id = m.id and ov.permission_key = p_permission_key
            and ov.effect = 'DENY' and ov.revoked_at is null
            and (ov.expires_at is null or ov.expires_at > now())
            and app_private.scope_covers_v3(s.scope_type, s.building_id, s.cashbook_id, s.area_id,
                                            m.organization_id, p_building, p_cashbook))
       and not exists (
         select 1
           from public.role_bindings rb
           join public.role_permissions rp
             on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
            and rp.permission_key = p_permission_key and rp.effect = 'DENY'
           join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
           join public.authorization_scopes s on s.id = rbs.scope_id
          where rb.membership_id = m.id and rb.valid_to is null
            and app_private.scope_covers_v3(s.scope_type, s.building_id, s.cashbook_id, s.area_id,
                                            m.organization_id, p_building, p_cashbook))
       -- quyền cần giữ sổ: phải đang giữ đúng sổ đó
       and (not pd.requires_cashbook_possession or (
             p_cashbook is not null and exists (
               select 1 from public.cashbook_possession_bindings cp
                where cp.membership_id = m.id and cp.cashbook_id = p_cashbook
                  and cp.possession_kind = any(pd.accepted_possession_kinds)
                  and cp.valid_from <= now()
                  and (cp.valid_to is null or cp.valid_to > now()))))
       -- CHO
       and (
         exists (
           select 1
             from public.member_permission_overrides ov
             join public.member_override_scopes mos on mos.override_id = ov.id
             join public.authorization_scopes s on s.id = mos.scope_id
            where ov.membership_id = m.id and ov.permission_key = p_permission_key
              and ov.effect = 'ALLOW' and ov.revoked_at is null
              and (ov.expires_at is null or ov.expires_at > now())
              and s.scope_type = any(pd.scope_kinds)
              and case when pd.requires_cashbook_possession
                       then s.scope_type = 'CASHBOOK' and s.cashbook_id = p_cashbook
                       else app_private.scope_covers_v3(s.scope_type, s.building_id, s.cashbook_id,
                              s.area_id, m.organization_id, p_building, p_cashbook) end)
         or exists (
           select 1
             from public.role_bindings rb
             join public.role_permissions rp
               on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
              and rp.permission_key = p_permission_key and rp.effect = 'ALLOW'
             join public.organization_roles orl
               on orl.id = rb.role_id and coalesce(orl.status,'ACTIVE') = 'ACTIVE'
             join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
             join public.authorization_scopes s on s.id = rbs.scope_id
            where rb.membership_id = m.id
              and coalesce(rb.valid_from, '-infinity'::timestamptz) <= now()
              and (rb.valid_to is null or rb.valid_to > now())
              and s.scope_type = any(pd.scope_kinds)
              and case when pd.requires_cashbook_possession
                       then s.scope_type = 'CASHBOOK' and s.cashbook_id = p_cashbook
                       else app_private.scope_covers_v3(s.scope_type, s.building_id, s.cashbook_id,
                              s.area_id, m.organization_id, p_building, p_cashbook) end)
       )
  );
$$;








--
-- Name: can_write_storage_object_v1(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_write_storage_object_v1(p_bucket text, p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select
    -- Bucket không chứa PII: không siết thêm.
    p_bucket not in ('customer-id-cards','customer-images','income-expense-attachments',
                     'job-attachments','payment-receipts','meter-images','document-templates')
    or (select public.is_super_admin())
    -- (a) Thư mục gốc phải là chính người đang upload.
    or (storage.foldername(p_name))[1] = (select auth.uid())::text
    -- (b) Path do server cấp cho chứng từ finance-v2, gắn với intent của caller.
    or exists (
      select 1
        from public.finance_evidence_objects e
       where e.bucket_id   = p_bucket
         and e.object_name = p_name
         and e.uploader_user_id = (select auth.uid())
    );
$$;








--
-- Name: FUNCTION can_write_storage_object_v1(p_bucket text, p_name text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.can_write_storage_object_v1(p_bucket text, p_name text) IS 'Gác GHI storage cho bucket PII: chỉ cho thư mục của chính caller hoặc path do upload-intent finance-v2 cấp. Cặp với can_read_storage_object_v1 (đọc/sửa/xoá).';








--
-- Name: cancel_collection_voucher_in_place_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cancel_collection_voucher_in_place_v1(p_voucher uuid, p_reason text, p_actor uuid, p_membership uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_active public.income_expense_postings%ROWTYPE;
  v_rev uuid;
  v_lines integer;
  v_sum numeric;
BEGIN
  SELECT * INTO v FROM public.income_expenses
   WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu thu gốc % không tồn tại', p_voucher USING ERRCODE = 'P0002';
  END IF;
  IF v.approval_status = 'CANCELLED' THEN
    RETURN NULL;   -- đã huỷ ở vòng trước của cùng transaction
  END IF;

  -- Token: vừa qua được trigger đóng băng, vừa TẮT cầu a85 để nó không đảo
  -- chồng lên bút toán mà hàm này sắp tự viết.
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
  ON CONFLICT (income_expense_id) DO UPDATE
    SET xid = excluded.xid, purpose = excluded.purpose, granted_at = now();

  IF COALESCE(v.posting_status, 'UNPOSTED') <> 'POSTED' THEN
    RAISE EXCEPTION
      'Phiếu thu % chưa ghi sổ (posting_status=%) — không huỷ tại chỗ được, báo quản trị.',
      p_voucher, COALESCE(v.posting_status, 'UNPOSTED') USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_active FROM public.income_expense_postings p
   WHERE p.id = v.active_posting_id_v2 FOR UPDATE;
  IF v_active.id IS NULL THEN
    -- Phiếu POSTED mà con trỏ rỗng là ca thật: nhánh BRIDGE_UNRESOLVED_POSTER
    -- của cầu a85 ghi dòng ngoại lệ rồi trả về mà không tạo posting.
    RAISE EXCEPTION
      'Phiếu thu % đã ghi sổ nhưng không tìm thấy bút toán gốc — báo quản trị trước khi huỷ.',
      p_voucher USING ERRCODE = '55000';
  END IF;
  IF v_active.event_kind <> 'POSTING' THEN
    RAISE EXCEPTION 'Bút toán đang trỏ tới không phải bút toán gốc' USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.income_expense_postings
    (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
     account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
     posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
     event_kind, idempotency_key, source_kind, posting_generation, reversal_of_id, reversal_reason)
  VALUES
    (v_active.organization_id, v_active.voucher_id, v_active.posting_subject_kind,
     v_active.posting_subject_id, v_active.direction, v_active.account_id,
     v_active.gross_amount, v_active.voucher_amount_snapshot, v_active.amount_basis,
     -v_active.net_cash_effect, public.org_today_v1(NULL),
     COALESCE(p_membership, v_active.posted_by_membership_id), p_actor,
     COALESCE(v.approval_version, 1), 'REVERSAL',
     'collinplace:' || v_active.id::text, 'MANUAL', v_active.posting_generation,
     v_active.id, p_reason)
  RETURNING id INTO v_rev;

  -- Soi gương TỪNG DÒNG. Phiếu thu có tiền thối mang hai dòng nằm ở HAI SỔ
  -- khác nhau (MAIN ở sổ thu, CHANGE ở sổ ảo "Thối"); dựng lại từ total_amount
  -- sẽ để sổ Thối lệch vĩnh viễn.
  INSERT INTO public.income_expense_posting_lines
    (organization_id, posting_id, account_id, line_kind, signed_amount)
  SELECT l.organization_id, v_rev, l.account_id, 'REVERSAL', -l.signed_amount
  FROM public.income_expense_posting_lines l
  WHERE l.posting_id = v_active.id;

  GET DIAGNOSTICS v_lines = ROW_COUNT;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'Bút toán gốc của phiếu % không có dòng nào — dừng lại', p_voucher
      USING ERRCODE = '55000';
  END IF;

  -- Hậu điều kiện: mọi bút toán của phiếu này phải triệt tiêu về 0.
  SELECT COALESCE(sum(l.signed_amount), 0) INTO v_sum
  FROM public.income_expense_posting_lines l
  JOIN public.income_expense_postings p ON p.id = l.posting_id
  WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher;
  IF v_sum <> 0 THEN
    RAISE EXCEPTION 'Huỷ phiếu thu % nhưng bút toán không triệt tiêu (còn lệch %) — dừng lại',
      p_voucher, v_sum USING ERRCODE = '55000';
  END IF;

  -- CHỈ các cột nằm trong allowlist của guard đóng băng. Đụng cột ngoài
  -- allowlist là 55000 "authorized transition may only change lifecycle columns".
  UPDATE public.income_expenses SET
    approval_status        = 'CANCELLED',
    review_state           = 'RESOLVED',
    posting_status         = 'REVERSED',
    cancellation_kind      = 'CANCELLED_AFTER_POSTING',
    active_posting_id_v2   = NULL,
    reversed_by_posting_id = v_rev,
    approval_version       = COALESCE(approval_version, 1) + 1,
    posting_version        = COALESCE(posting_version, 1) + 1
  WHERE id = p_voucher;

  DELETE FROM app_private.ie_transition_authorization WHERE income_expense_id = p_voucher;

  INSERT INTO app_private.income_expense_cancellations
    (income_expense_id, organization_id, cancelled_by, cancel_reason, cancellation_kind,
     created_at_snap, approved_at_snap, amount_snap, cashbook_snap)
  VALUES
    (p_voucher, v.organization_id, p_actor, p_reason, 'CANCELLED_AFTER_POSTING',
     v.created_at, v.approved_at, v.total_amount, v.account_id)
  ON CONFLICT (income_expense_id) DO NOTHING;

  PERFORM app_private.append_income_expense_event_v1(
    v.organization_id, p_voucher, 'CANCELLED', p_actor, NULL,
    v.approval_status, 'CANCELLED', p_reason);

  RETURN v_rev;
END
$$;








--
-- Name: cancel_income_voucher_core_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cancel_income_voucher_core_v1(p_voucher uuid, p_reason text, p_actor uuid, p_membership uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_active public.income_expense_postings%ROWTYPE;
  v_rev uuid;
  v_sum numeric;
  v_kind text;
  v_next_posting text;
BEGIN
  SELECT * INTO v FROM public.income_expenses
   WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002';
  END IF;
  IF v.approval_status = 'CANCELLED' THEN
    RETURN jsonb_build_object('id', p_voucher, 'changed', false);
  END IF;

  -- Token: vừa qua trigger đóng băng phiếu flow-owned, vừa TẮT cầu a85 để nó
  -- không đảo chồng lên bút toán mà hàm này sắp tự viết.
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
  ON CONFLICT (income_expense_id) DO UPDATE
    SET xid = excluded.xid, purpose = excluded.purpose, granted_at = now();

  v_kind := 'CANCELLED_UNPOSTED';
  v_next_posting := CASE WHEN v.posting_mode = 'NON_CASH' THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END;

  IF COALESCE(v.posting_status, 'UNPOSTED') = 'POSTED' THEN
    SELECT * INTO v_active FROM public.income_expense_postings p
     WHERE p.id = v.active_posting_id_v2 FOR UPDATE;

    IF v_active.id IS NULL THEN
      RAISE EXCEPTION 'Phiếu ghi nhận đã ghi sổ nhưng không tìm thấy bút toán gốc — báo quản trị trước khi huỷ.'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_active.event_kind <> 'POSTING' THEN
      RAISE EXCEPTION 'Bút toán đang trỏ tới không phải bút toán gốc — báo quản trị.'
        USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.income_expense_postings
      (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
       account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
       posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
       event_kind, idempotency_key, source_kind, posting_generation, reversal_of_id, reversal_reason)
    VALUES
      (v_active.organization_id, v_active.voucher_id, v_active.posting_subject_kind,
       v_active.posting_subject_id, v_active.direction, v_active.account_id,
       v_active.gross_amount, v_active.voucher_amount_snapshot, v_active.amount_basis,
       -v_active.net_cash_effect, public.org_today_v1(NULL),
       COALESCE(p_membership, v_active.posted_by_membership_id), p_actor,
       COALESCE(v.approval_version, 1), 'REVERSAL',
       'inccancel:' || v_active.id::text, 'MANUAL', v_active.posting_generation,
       v_active.id, p_reason)
    RETURNING id INTO v_rev;

    -- Soi gương TỪNG DÒNG: phiếu có tiền thối / làm tròn mang 2-3 dòng nằm ở
    -- các sổ quỹ KHÁC nhau; đảo mỗi dòng chính thì sổ thối vĩnh viễn lệch.
    INSERT INTO public.income_expense_posting_lines
      (organization_id, posting_id, account_id, line_kind, signed_amount)
    SELECT l.organization_id, v_rev, l.account_id, 'REVERSAL', -l.signed_amount
    FROM public.income_expense_posting_lines l
    WHERE l.posting_id = v_active.id;

    SELECT COALESCE(sum(l.signed_amount), 0) INTO v_sum
    FROM public.income_expense_posting_lines l
    JOIN public.income_expense_postings p ON p.id = l.posting_id
    WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher;
    IF v_sum <> 0 THEN
      RAISE EXCEPTION 'Huỷ phiếu nhưng bút toán không triệt tiêu (còn lệch %) — dừng lại', v_sum
        USING ERRCODE = '55000';
    END IF;

    v_kind := 'CANCELLED_AFTER_POSTING';
    v_next_posting := 'REVERSED';
  END IF;

  UPDATE public.income_expenses SET
    approval_status = 'CANCELLED',
    review_state = 'RESOLVED',
    posting_status = v_next_posting,
    cancellation_kind = v_kind,
    active_posting_id_v2 = CASE WHEN v_rev IS NOT NULL THEN NULL ELSE active_posting_id_v2 END,
    reversed_by_posting_id = COALESCE(v_rev, reversed_by_posting_id),
    approval_version = COALESCE(approval_version, 1) + 1,
    posting_version = COALESCE(posting_version, 1) + CASE WHEN v_rev IS NOT NULL THEN 1 ELSE 0 END
  WHERE id = p_voucher;

  DELETE FROM app_private.ie_transition_authorization WHERE income_expense_id = p_voucher;

  INSERT INTO app_private.income_expense_cancellations
    (income_expense_id, organization_id, cancelled_by, cancel_reason, cancellation_kind,
     created_at_snap, approved_at_snap, amount_snap, cashbook_snap)
  VALUES
    (p_voucher, v.organization_id, p_actor, p_reason, v_kind,
     v.created_at, v.approved_at, v.total_amount, v.account_id)
  ON CONFLICT (income_expense_id) DO NOTHING;

  PERFORM app_private.append_income_expense_event_v1(
    v.organization_id, p_voucher, 'CANCELLED', p_actor, NULL,
    v.approval_status, 'CANCELLED', p_reason);

  RETURN jsonb_build_object(
    'id', p_voucher, 'changed', true,
    'cancellation_kind', v_kind,
    'reversal_posting_id', v_rev);
END
$$;








--
-- Name: capture_finance_month_snapshot_v1(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.capture_finance_month_snapshot_v1(p_organization_id uuid, p_as_of_timestamp timestamp with time zone, p_finalize boolean DEFAULT false) RETURNS TABLE(snapshot_run_id uuid, snapshot_status text, captured_room_count integer, captured_contract_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_local_timestamp timestamp;
  v_local_date date;
  v_month date;
  v_month_end date;
  v_scheduled_for timestamptz;
  v_run_id uuid;
  v_existing_status text;
  v_room_count integer;
  v_contract_count integer;
  v_partition_count integer;
  v_final_status text;
  v_is_late boolean;
BEGIN
  IF p_organization_id IS NULL OR p_as_of_timestamp IS NULL THEN
    RAISE EXCEPTION 'Organization and capture timestamp are required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.organizations organization_row
  WHERE organization_row.id = p_organization_id
    AND organization_row.status = 'ACTIVE';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active organization not found'
      USING ERRCODE = '22023';
  END IF;

  v_local_timestamp := p_as_of_timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_local_date := v_local_timestamp::date;
  v_month := date_trunc('month', v_local_date)::date;
  v_month_end := (v_month + interval '1 month - 1 day')::date;
  v_scheduled_for := make_timestamptz(
    extract(year FROM v_local_date)::integer,
    extract(month FROM v_local_date)::integer,
    extract(day FROM v_local_date)::integer,
    23,
    55,
    0,
    'Asia/Ho_Chi_Minh'
  );

  IF COALESCE(p_finalize, false)
     AND (
       v_local_date <> v_month_end
       OR v_local_timestamp::time < time '23:50:00'
     ) THEN
    RAISE EXCEPTION 'Finance snapshot can finalize only in the month-end cutoff window'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':' || v_month::text, 0)
  );

  SELECT run.id, run.status
    INTO v_run_id, v_existing_status
  FROM public.finance_month_snapshot_runs run
  WHERE run.organization_id = p_organization_id
    AND run.snapshot_month = v_month
  FOR UPDATE;

  IF v_existing_status IN ('FINALIZED', 'MISSED') THEN
    RETURN QUERY
    SELECT run.id, run.status, run.room_count, run.contract_count
    FROM public.finance_month_snapshot_runs run
    WHERE run.id = v_run_id;
    RETURN;
  END IF;

  IF v_run_id IS NULL THEN
    INSERT INTO public.finance_month_snapshot_runs (
      organization_id,
      snapshot_month,
      as_of_date,
      as_of_timestamp,
      scheduled_for,
      captured_at,
      status,
      capture_version,
      room_count,
      contract_count,
      validation_summary,
      capture_source
    ) VALUES (
      p_organization_id,
      v_month,
      v_local_date,
      p_as_of_timestamp,
      v_scheduled_for,
      clock_timestamp(),
      'PROVISIONAL',
      0,
      0,
      0,
      '{}'::jsonb,
      'CRON'
    )
    RETURNING id INTO v_run_id;
  END IF;

  DELETE FROM public.finance_contract_month_snapshots detail
  WHERE detail.snapshot_run_id = v_run_id;
  DELETE FROM public.finance_room_month_snapshots detail
  WHERE detail.snapshot_run_id = v_run_id;

  INSERT INTO public.finance_room_month_snapshots (
    snapshot_run_id,
    organization_id,
    snapshot_month,
    building_id,
    building_name,
    room_id,
    room_name,
    room_status,
    listed_rent,
    occupancy_group,
    active_contract_count,
    as_of_timestamp,
    captured_at
  )
  SELECT
    v_run_id,
    p_organization_id,
    v_month,
    building_row.id,
    COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building'),
    room_row.id,
    COALESCE(NULLIF(btrim(room_row.name), ''), 'Unnamed room'),
    room_row.status::text,
    room_row.rent_price,
    CASE
      WHEN contract_count.active_count > 0 THEN 'OCCUPIED'
      WHEN room_row.status::text = 'RESERVED' THEN 'RESERVED'
      WHEN room_row.status::text = 'MAINTENANCE' THEN 'MAINTENANCE'
      WHEN room_row.status::text = 'AVAILABLE' THEN 'AVAILABLE'
      ELSE 'UNAVAILABLE'
    END,
    contract_count.active_count,
    p_as_of_timestamp,
    clock_timestamp()
  FROM public.buildings building_row
  JOIN public.rooms room_row
    ON room_row.building_id = building_row.id
   AND room_row.deleted_at IS NULL
  CROSS JOIN LATERAL (
    SELECT count(*)::integer AS active_count
    FROM public.contracts contract_row
    WHERE contract_row.room_id = room_row.id
      AND contract_row.organization_id = p_organization_id
      AND contract_row.deleted_at IS NULL
      AND contract_row.status::text = 'ACTIVE'
      AND contract_row.start_date <= v_local_date
      AND (
        contract_row.actual_end_date IS NULL
        OR contract_row.actual_end_date >= v_local_date
      )
  ) contract_count
  WHERE building_row.organization_id = p_organization_id
    AND building_row.deleted_at IS NULL
    AND building_row.is_virtual = false;

  INSERT INTO public.finance_contract_month_snapshots (
    snapshot_run_id,
    organization_id,
    snapshot_month,
    building_id,
    building_name,
    room_id,
    room_name,
    contract_id,
    contract_number,
    contract_status,
    rent_price,
    start_date,
    end_date,
    actual_end_date,
    effective_end_date,
    as_of_timestamp,
    captured_at
  )
  SELECT
    v_run_id,
    p_organization_id,
    v_month,
    building_row.id,
    COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building'),
    room_row.id,
    COALESCE(NULLIF(btrim(room_row.name), ''), 'Unnamed room'),
    contract_row.id,
    contract_row.contract_number,
    contract_row.status::text,
    contract_row.rent_price,
    contract_row.start_date,
    contract_row.end_date,
    contract_row.actual_end_date,
    GREATEST(
      contract_row.end_date,
      COALESCE(extension_row.extended_end_date, contract_row.end_date)
    )::date,
    p_as_of_timestamp,
    clock_timestamp()
  FROM public.contracts contract_row
  JOIN public.rooms room_row
    ON room_row.id = contract_row.room_id
   AND room_row.deleted_at IS NULL
  JOIN public.buildings building_row
    ON building_row.id = room_row.building_id
   AND building_row.organization_id = p_organization_id
   AND building_row.deleted_at IS NULL
   AND building_row.is_virtual = false
  LEFT JOIN LATERAL (
    SELECT max(extension_row.new_end_date::date) AS extended_end_date
    FROM public.contract_extensions extension_row
    WHERE extension_row.contract_id = contract_row.id
      AND extension_row.status IN ('APPROVED', 'COMPLETED')
  ) extension_row ON true
  WHERE contract_row.organization_id = p_organization_id
    AND contract_row.deleted_at IS NULL
    AND contract_row.status::text = 'ACTIVE'
    AND contract_row.start_date <= v_local_date
    AND (
      contract_row.actual_end_date IS NULL
      OR contract_row.actual_end_date >= v_local_date
    );

  SELECT count(*)::integer
    INTO v_room_count
  FROM public.finance_room_month_snapshots detail
  WHERE detail.snapshot_run_id = v_run_id;

  SELECT count(*)::integer
    INTO v_contract_count
  FROM public.finance_contract_month_snapshots detail
  WHERE detail.snapshot_run_id = v_run_id;

  SELECT count(*)::integer
    INTO v_partition_count
  FROM public.finance_room_month_snapshots detail
  WHERE detail.snapshot_run_id = v_run_id
    AND detail.occupancy_group IN (
      'OCCUPIED', 'RESERVED', 'MAINTENANCE', 'AVAILABLE', 'UNAVAILABLE'
    );

  IF v_partition_count IS DISTINCT FROM v_room_count
     OR EXISTS (
       SELECT 1
       FROM public.finance_room_month_snapshots detail
       WHERE detail.snapshot_run_id = v_run_id
         AND (
           detail.organization_id <> p_organization_id
           OR detail.snapshot_month <> v_month
         )
     )
     OR EXISTS (
       SELECT 1
       FROM public.finance_contract_month_snapshots detail
       WHERE detail.snapshot_run_id = v_run_id
         AND (
           detail.organization_id <> p_organization_id
           OR detail.snapshot_month <> v_month
         )
     ) THEN
    RAISE EXCEPTION 'snapshot partition validation failed'
      USING ERRCODE = '55000';
  END IF;

  v_final_status := CASE WHEN COALESCE(p_finalize, false)
    THEN 'FINALIZED' ELSE 'PROVISIONAL' END;
  v_is_late := p_as_of_timestamp > v_scheduled_for + interval '5 minutes';

  UPDATE public.finance_month_snapshot_runs run
  SET
    as_of_date = v_local_date,
    as_of_timestamp = p_as_of_timestamp,
    scheduled_for = v_scheduled_for,
    captured_at = clock_timestamp(),
    finalized_at = CASE WHEN v_final_status = 'FINALIZED'
      THEN clock_timestamp() ELSE NULL END,
    status = v_final_status,
    capture_version = run.capture_version + 1,
    is_late = v_is_late,
    late_reason = CASE WHEN v_is_late THEN 'Captured after daily cutoff' ELSE NULL END,
    room_count = v_room_count,
    contract_count = v_contract_count,
    validation_summary = jsonb_build_object(
      'partition_valid', true,
      'room_count', v_room_count,
      'contract_count', v_contract_count,
      'groups', (
        SELECT COALESCE(jsonb_object_agg(group_count.occupancy_group, group_count.row_count), '{}'::jsonb)
        FROM (
          SELECT detail.occupancy_group, count(*)::integer AS row_count
          FROM public.finance_room_month_snapshots detail
          WHERE detail.snapshot_run_id = v_run_id
          GROUP BY detail.occupancy_group
        ) group_count
      )
    ),
    updated_at = clock_timestamp()
  WHERE run.id = v_run_id;

  RETURN QUERY
  SELECT run.id, run.status, run.room_count, run.contract_count
  FROM public.finance_month_snapshot_runs run
  WHERE run.id = v_run_id;
END;
$$;








--
-- Name: cashbook_balance_as_of_v1(uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cashbook_balance_as_of_v1(p_cashbook uuid, p_as_of date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  -- Sao chép NGUYÊN VĂN công thức của public.accounts_with_balance, chỉ thêm
  -- `p.posted_on <= p_as_of`. Lọc theo l.organization_id = a.organization_id
  -- giữ nguyên vì view gốc có — bỏ đi là cộng nhầm dòng xuyên tổ chức.
  SELECT a.initial_amount + COALESCE((
    SELECT sum(l.signed_amount)
    FROM public.income_expense_posting_lines l
    JOIN public.income_expense_postings p ON p.id = l.posting_id
    WHERE l.account_id = a.id
      AND l.organization_id = a.organization_id
      AND p.event_kind IN ('POSTING', 'REVERSAL')
      AND p.posted_on <= p_as_of
  ), 0::numeric)
  FROM public.accounts a
  WHERE a.id = p_cashbook;
$$;








--
-- Name: cashbook_closed_through_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cashbook_closed_through_v1(p_cashbook uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE(current_setting('app_private.demo_reset', true), '') = 'on' THEN NULL
    ELSE GREATEST(
      (SELECT max(c.closed_through) FROM app_private.cashbook_closures c
        WHERE c.cashbook_id = p_cashbook),
      (SELECT a.lock_date FROM public.accounts a WHERE a.id = p_cashbook)
    )
  END;
$$;








--
-- Name: claim_canonical_income_expense_draft_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_canonical_income_expense_draft_v1(p_income_expense_id uuid, p_idempotency_key text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$

declare

  v_row public.income_expenses;

  v_op app_private.canonical_write_operations;

  v_actor uuid;

begin

  if current_user <> 'ie_canonical_writer' then

    raise exception 'canonical claim capability required' using errcode = '42501';

  end if;



  v_actor := app_private.current_uid_v1();  -- DEFINER delegate; role has no auth USAGE

  if v_actor is null then

    raise exception 'authentication required' using errcode = '42501';

  end if;



  v_row := app_private.ie_lock_row_for_claim_v1(p_income_expense_id);



  if v_row.user_id is distinct from v_actor then

    raise exception 'claim actor is not the maker' using errcode = '42501';

  end if;

  -- t5_22: phuong an org = phieu thuong TU DUYET khi tao -> chap nhan them
  -- hinh dang "APPROVED tu luc sinh boi chinh maker" (self-approved-at-birth).
  if (v_row.approval_status is distinct from 'UNAPPROVED'
      and not (v_row.approval_status = 'APPROVED'
               and v_row.approved_by is not distinct from v_actor))
     or v_row.approval_request_id is not null

     or v_row.posting_id is not null

     or v_row.posted_at_v2 is not null

     or v_row.reversed_by_posting_id is not null

     or v_row.system_source is not null then

    raise exception 'row is not claimable as canonical draft' using errcode = '23514';

  end if;

  if v_row.source_payload_hash is null

     or v_row.source_payload_hash !~ '^[0-9a-f]{32}$' then

    raise exception 'row lacks canonical payload hash' using errcode = '23514';

  end if;



  v_op := app_private.ie_lock_operation_for_claim_v1(

    v_row.organization_id, v_row.building_id::text, v_actor,

    p_idempotency_key, v_row.source_payload_hash);



  insert into app_private.income_expense_flow_ownership (

    income_expense_id, organization_id, writer_operation,

    payload_hash_scheme, payload_hash_value,

    maker_user_id, claimed_by_user_id, correlation_id)

  values (

    v_row.id, v_row.organization_id, v_op.operation,

    'PG_MD5_JSONB_TEXT_V1', v_row.source_payload_hash,

    v_row.user_id, v_actor, null);



  insert into app_private.income_expense_flow_ownership_events (

    organization_id, income_expense_id, event_type, actor_user_id, detail)

  values (

    v_row.organization_id, v_row.id, 'FLOW_CLAIMED', v_actor,

    jsonb_build_object('operation', v_op.operation,

                       'idempotency_key', p_idempotency_key));

end;

$_$;








--
-- Name: claim_canonical_income_expense_draft_v1(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_canonical_income_expense_draft_v1(p_income_expense_id uuid, p_idempotency_key text, p_capability_nonce text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$

declare

  v_row public.income_expenses;

  v_op app_private.canonical_write_operations;

  v_actor uuid;

begin

  if not app_private.has_ie_claim_capability_v1(p_capability_nonce) then

    raise exception 'canonical claim capability required' using errcode = '42501';

  end if;



  v_actor := app_private.current_uid_v1();

  if v_actor is null then

    raise exception 'authentication required' using errcode = '42501';

  end if;



  v_row := app_private.ie_lock_row_for_claim_v1(p_income_expense_id);

  if v_row.user_id is distinct from v_actor then

    raise exception 'claim actor is not the maker' using errcode = '42501';

  end if;

  -- t5_22: phuong an org = phieu thuong TU DUYET khi tao -> chap nhan them
  -- hinh dang "APPROVED tu luc sinh boi chinh maker" (self-approved-at-birth).
  if (v_row.approval_status is distinct from 'UNAPPROVED'
      and not (v_row.approval_status = 'APPROVED'
               and v_row.approved_by is not distinct from v_actor))
     or v_row.approval_request_id is not null

     or v_row.posting_id is not null

     or v_row.posted_at_v2 is not null

     or v_row.reversed_by_posting_id is not null

     or v_row.system_source is not null then

    raise exception 'row is not claimable as canonical draft' using errcode = '23514';

  end if;

  if v_row.source_payload_hash is null

     or v_row.source_payload_hash !~ '^[0-9a-f]{32}$' then

    raise exception 'row lacks canonical payload hash' using errcode = '23514';

  end if;



  v_op := app_private.ie_lock_operation_for_claim_v1(

    v_row.organization_id, v_row.building_id::text, v_actor,

    p_idempotency_key, v_row.source_payload_hash);



  insert into app_private.income_expense_flow_ownership (

    income_expense_id, organization_id, writer_operation,

    payload_hash_scheme, payload_hash_value,

    maker_user_id, claimed_by_user_id, correlation_id)

  values (

    v_row.id, v_row.organization_id, v_op.operation,

    'PG_MD5_JSONB_TEXT_V1', v_row.source_payload_hash,

    v_row.user_id, v_actor, null);



  insert into app_private.income_expense_flow_ownership_events (

    organization_id, income_expense_id, event_type, actor_user_id, detail)

  values (

    v_row.organization_id, v_row.id, 'FLOW_CLAIMED', v_actor,

    jsonb_build_object('operation', v_op.operation,

                       'idempotency_key', p_idempotency_key));

end;

$_$;








--
-- Name: claim_feature_operation_v1(text, uuid, text, uuid, text, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_feature_operation_v1(p_feature_key text, p_organization_id uuid, p_subject_scope text, p_actor_id uuid, p_idempotency_key text, p_amount_vnd numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_feature app_private.server_feature_flags%ROWTYPE;
  v_route text;
  v_now timestamptz;
  v_operation_count bigint;
  v_total_amount numeric;
  v_operation_key text;
BEGIN
  IF NULLIF(btrim(COALESCE(p_feature_key, '')), '') IS NULL
     OR p_organization_id IS NULL
     OR NULLIF(btrim(COALESCE(p_subject_scope, '')), '') IS NULL
     OR p_actor_id IS NULL
     OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Invalid feature operation identity'
      USING ERRCODE = '22023';
  END IF;
  IF p_amount_vnd IS NULL
     OR p_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount_vnd < 0
     OR round(p_amount_vnd, 2) <> p_amount_vnd THEN
    RAISE EXCEPTION 'Feature operation amount must be finite, non-negative and have at most two decimals'
      USING ERRCODE = '22023';
  END IF;

  -- Keep release identity/config stable through commit. ON routes do not need
  -- cap accounting; only CANARY buckets are serialized and written here.
  SELECT * INTO v_feature
  FROM app_private.server_feature_flags feature_row
  WHERE feature_row.feature_key = p_feature_key
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Canonical writer is not configured'
      USING ERRCODE = '55000';
  END IF;

  IF v_feature.mode = 'CANARY' THEN
    PERFORM 1
    FROM app_private.server_feature_flag_canary_orgs canary_row
    WHERE canary_row.feature_key = v_feature.feature_key
      AND canary_row.organization_id = p_organization_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Organization is not enrolled in this canary'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF v_feature.mode <> 'CANARY' THEN
    v_route := app_private.evaluate_feature_route(
      v_feature.feature_key, p_organization_id
    );
    IF v_route <> 'CANONICAL' THEN
      RAISE EXCEPTION 'Canonical writer is disabled or frozen for this organization'
        USING ERRCODE = '55000';
    END IF;
    RETURN;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_feature.feature_key || ':' || v_feature.config_version::text,
      0
    )
  );

  v_now := clock_timestamp();
  IF v_feature.force_freeze
     OR NULLIF(btrim(v_feature.commit_sha), '') IS NULL
     OR NULLIF(btrim(v_feature.migration_sha256), '') IS NULL
     OR NULLIF(btrim(v_feature.maintenance_window_id), '') IS NULL
     OR NULLIF(btrim(v_feature.approval_reference), '') IS NULL
     OR v_feature.starts_at IS NULL
     OR v_feature.ends_at IS NULL
     OR NOT isfinite(v_feature.starts_at)
     OR NOT isfinite(v_feature.ends_at)
     OR v_feature.starts_at >= v_feature.ends_at
     OR v_now < v_feature.starts_at
     OR v_now >= v_feature.ends_at THEN
    RAISE EXCEPTION 'Canary window is no longer valid'
      USING ERRCODE = '55000';
  END IF;
  IF v_feature.max_operation_count <= 0
     OR v_feature.max_single_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_feature.max_total_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_feature.max_single_amount_vnd <= 0
     OR v_feature.max_total_amount_vnd <= 0 THEN
    RAISE EXCEPTION 'Canary limits are invalid'
      USING ERRCODE = '55000';
  END IF;
  IF p_amount_vnd > v_feature.max_single_amount_vnd THEN
    RAISE EXCEPTION 'Operation exceeds the canary single-amount limit'
      USING ERRCODE = '54000';
  END IF;

  SELECT count(*), COALESCE(sum(operation_row.amount_vnd), 0)
    INTO v_operation_count, v_total_amount
  FROM app_private.server_feature_flag_operations operation_row
  WHERE operation_row.feature_key = v_feature.feature_key
    AND operation_row.config_version = v_feature.config_version;

  IF v_operation_count >= v_feature.max_operation_count THEN
    RAISE EXCEPTION 'Canary operation-count limit is exhausted'
      USING ERRCODE = '54000';
  END IF;
  IF v_total_amount + p_amount_vnd > v_feature.max_total_amount_vnd THEN
    RAISE EXCEPTION 'Canary total-amount limit is exhausted'
      USING ERRCODE = '54000';
  END IF;

  v_operation_key := md5(concat_ws(
    '|',
    v_feature.feature_key,
    p_organization_id::text,
    p_subject_scope,
    p_actor_id::text,
    p_idempotency_key
  ));

  INSERT INTO app_private.server_feature_flag_operations (
    feature_key, config_version, operation_key, organization_id, amount_vnd
  ) VALUES (
    v_feature.feature_key, v_feature.config_version, v_operation_key,
    p_organization_id, p_amount_vnd
  );
END;
$$;








--
-- Name: FUNCTION claim_feature_operation_v1(p_feature_key text, p_organization_id uuid, p_subject_scope text, p_actor_id uuid, p_idempotency_key text, p_amount_vnd numeric); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.claim_feature_operation_v1(p_feature_key text, p_organization_id uuid, p_subject_scope text, p_actor_id uuid, p_idempotency_key text, p_amount_vnd numeric) IS 'Atomically admits one CANARY money operation and appends its cap-ledger row.';








--
-- Name: classify_termination_payment_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.classify_termination_payment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_core_writer boolean;
  v_invoice_org uuid;
  v_forfeit_voucher_id uuid;
  v_forfeit_authorization app_private.termination_forfeit_authorizations%ROWTYPE;
  v_is_move_out boolean;
  v_is_forfeit boolean;
BEGIN
  v_is_move_out := COALESCE(NEW.notes, '') ~
    '^Quyết toán khi thanh lý [0-9]{2}/[0-9]{2}/[0-9]{4}( \(cấn cọc\))?$';

  IF COALESCE(NEW.notes, '') ~
     '^\[CẤN CỌC BỎ CỌC PAYMENT [0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\]$' THEN
    v_forfeit_voucher_id := substring(
      NEW.notes FROM
      '^\[CẤN CỌC BỎ CỌC PAYMENT ([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\]$'
    )::uuid;
  END IF;
  v_is_forfeit := v_forfeit_voucher_id IS NOT NULL;

  IF NOT v_is_move_out AND NOT v_is_forfeit THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;

  IF NOT v_core_writer THEN
    RAISE EXCEPTION
      'Payment cấn trừ thanh lý phải được tạo bởi writer thanh lý hợp lệ'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.collection_id IS NOT NULL OR NEW.tender_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Payment cấn trừ thanh lý không được gắn collection thu tiền'
      USING ERRCODE = '55000';
  END IF;

  SELECT invoice.organization_id
    INTO v_invoice_org
  FROM public.invoices invoice
  WHERE invoice.id = NEW.invoice_id
    AND invoice.deleted_at IS NULL;

  IF v_invoice_org IS NULL THEN
    RAISE EXCEPTION 'Không xác định được organization của payment thanh lý'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := v_invoice_org;
  ELSIF NEW.organization_id <> v_invoice_org THEN
    RAISE EXCEPTION 'Payment thanh lý lệch organization với hóa đơn'
      USING ERRCODE = '55000';
  END IF;

  IF v_is_move_out AND (
    NEW.payment_method IS DISTINCT FROM 'CT'::public.payment_method
    OR COALESCE(NEW.amount, 0) <= 0
    OR NOT EXISTS (
      SELECT 1
      FROM app_private.termination_move_out_writer_context context_row
      JOIN public.invoices invoice
        ON invoice.id = NEW.invoice_id
       AND invoice.organization_id = context_row.organization_id
       -- 7z: invoice maker relax — hoá đơn nợ có thể do staff lập hộ (70 ca
       -- prod) hoặc mang room lịch sử khác (1 ca); neo an toàn = ĐÚNG HỢP ĐỒNG
       -- trong context per-txn, không phải người lập/phòng của hoá đơn.
       AND invoice.contract_id = context_row.contract_id
       AND invoice.building_id = context_row.building_id
       AND invoice.deleted_at IS NULL
      JOIN public.contracts contract_row
        ON contract_row.id = context_row.contract_id
       AND contract_row.organization_id = context_row.organization_id
       AND contract_row.user_id = context_row.user_id
       AND contract_row.room_id = context_row.room_id
       AND contract_row.deleted_at IS NULL
      JOIN public.rooms room_row
        ON room_row.id = context_row.room_id
       AND room_row.building_id = context_row.building_id
       AND room_row.deleted_at IS NULL
      WHERE context_row.transaction_id = txid_current()
        AND context_row.backend_pid = pg_backend_pid()
        AND NEW.organization_id = context_row.organization_id
        AND NEW.user_id = context_row.user_id
        AND NEW.payment_date = context_row.move_out_date
        AND NEW.amount <= GREATEST(
          COALESCE(invoice.total_amount, 0) - COALESCE(invoice.paid_amount, 0),
          0
        )
    )
  ) THEN
    RAISE EXCEPTION 'Payment move-out does not match the active termination context'
      USING ERRCODE = '55000';
  END IF;

  IF v_is_forfeit AND NOT EXISTS (
    SELECT 1
    FROM public.income_expenses voucher
    WHERE voucher.id = v_forfeit_voucher_id
      AND voucher.organization_id = v_invoice_org
      AND voucher.invoice_id = NEW.invoice_id
      AND voucher.type = 'INCOME'
      AND voucher.system_source = 'termination.forfeit_revenue'
      AND voucher.deleted_at IS NULL
      AND voucher.total_amount = NEW.amount
  ) THEN
    RAISE EXCEPTION 'Không xác minh được phiếu cấn cọc bỏ cọc của payment'
      USING ERRCODE = '55000';
  END IF;

  IF v_is_forfeit THEN
    SELECT validated.*
      INTO v_forfeit_authorization
    FROM app_private.require_termination_forfeit_authorization_v1(
      v_forfeit_voucher_id, true, false
    ) validated;

    IF NEW.organization_id IS DISTINCT FROM v_forfeit_authorization.organization_id
       OR NEW.invoice_id IS DISTINCT FROM v_forfeit_authorization.invoice_id
       OR NEW.amount IS DISTINCT FROM v_forfeit_authorization.amount
       OR NEW.payment_date IS DISTINCT FROM v_forfeit_authorization.voucher_date
       OR NEW.payment_method IS DISTINCT FROM 'CT'::public.payment_method
       OR NOT EXISTS (
         SELECT 1
         FROM public.income_expenses revenue
         JOIN public.contracts contract_row
           ON contract_row.id = v_forfeit_authorization.contract_id
         WHERE revenue.id = v_forfeit_authorization.revenue_voucher_id
           AND NEW.user_id = revenue.user_id
           AND revenue.user_id = contract_row.user_id
       ) THEN
      RAISE EXCEPTION 'Payment does not match the exact authorized forfeit settlement'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  NEW.received_amount := 0;
  NEW.credit_amount := 0;
  NEW.change_amount := 0;
  NEW.rounding_amount := 0;
  RETURN NEW;
END;
$_$;








--
-- Name: FUNCTION classify_termination_payment_v1(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.classify_termination_payment_v1() IS 'Classifies contract-termination A/R offsets as non-cash while preserving payments.amount for debt settlement.';








--
-- Name: commission_autopay_check_v1(uuid, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.commission_autopay_check_v1(p_contract_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_c       public.contracts;
  v_org     uuid;
  v_bld     uuid;
  v_months  int;
  v_rate    numeric;
  v_expect  numeric;
  v_basis   jsonb;
  v_today   date;
BEGIN
  SELECT * INTO v_c FROM public.contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('verdict','NOT_ELIGIBLE','reason','Không tìm thấy hợp đồng');
  END IF;
  v_org := v_c.organization_id;
  SELECT r.building_id INTO v_bld FROM public.rooms r WHERE r.id = v_c.room_id;
  v_today := public.org_today_v1(v_org);

  -- (1) Hợp đồng còn hiệu lực.
  -- `contracts.status` là ENUM, không phải text: COALESCE(x,'') sẽ cố ép ''
  -- vào enum và ném 22P02. Ép sang text trước khi so.
  IF COALESCE(v_c.status::text, '') <> 'ACTIVE' THEN
    RETURN jsonb_build_object('verdict','NOT_ELIGIBLE',
      'reason', 'Hợp đồng đang ở trạng thái ' || COALESCE(v_c.status::text,'(rỗng)') || ', chưa đủ điều kiện tự duyệt');
  END IF;

  -- (2) Đã qua ngày bắt đầu + 7 ngày.
  IF v_c.start_date IS NULL OR v_today < (v_c.start_date + 7) THEN
    RETURN jsonb_build_object('verdict','NOT_ELIGIBLE',
      'reason', 'Chưa qua 7 ngày kể từ ngày bắt đầu hợp đồng ('
                || COALESCE(to_char(v_c.start_date,'DD/MM/YYYY'),'chưa có ngày') || ')');
  END IF;

  -- (3) Đã THỰC THU đủ cọc. Dùng nguồn sự thật dùng chung của Đợt 1 —
  --     KHÔNG dùng contracts.deposit_paid (cột đó gộp cả cọc trên SỔ ẢO).
  BEGIN
    v_basis := app_private.resolve_signed_contract_deposit_basis_v1(v_org, p_contract_id, now());
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('verdict','NOT_ELIGIBLE',
      'reason','Không đọc được tình trạng cọc của hợp đồng');
  END;
  IF COALESCE(v_basis->>'status','') <> 'OK' THEN
    RETURN jsonb_build_object('verdict','NOT_ELIGIBLE',
      'reason', 'Cọc chưa vào két đủ (tình trạng: ' || COALESCE(v_basis->>'status','?') || ')',
      'depositBasis', v_basis);
  END IF;

  -- (4) Đúng bậc chủ đã công bố.
  v_months := GREATEST(0, (EXTRACT(YEAR FROM age(v_c.end_date, v_c.start_date)) * 12
                        +  EXTRACT(MONTH FROM age(v_c.end_date, v_c.start_date)))::int);
  v_rate := app_private.commission_rate_for_v1(v_org, v_bld, v_months, v_today);
  IF v_rate IS NULL THEN
    RETURN jsonb_build_object('verdict','NO_TIER',
      'months', v_months,
      'reason', 'Chủ chưa công bố bậc hoa hồng cho hợp đồng ' || v_months || ' tháng ở toà này');
  END IF;

  v_expect := round(COALESCE(v_c.rent_price,0) * v_rate / 100);
  IF round(COALESCE(p_amount,0)) <> v_expect THEN
    RETURN jsonb_build_object('verdict','AMOUNT_MISMATCH',
      'months', v_months, 'ratePercent', v_rate, 'expected', v_expect,
      'reason', 'Bậc đã công bố là ' || v_rate || '% tiền thuê = '
                || replace(to_char(v_expect,'FM999G999G999G999'), ',', '.') || 'đ, số đang chi là '
                || replace(to_char(round(COALESCE(p_amount,0)),'FM999G999G999G999'), ',', '.') || 'đ');
  END IF;

  RETURN jsonb_build_object('verdict','VALID',
    'months', v_months, 'ratePercent', v_rate, 'expected', v_expect);
END;
$$;








--
-- Name: FUNCTION commission_autopay_check_v1(p_contract_id uuid, p_amount numeric); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.commission_autopay_check_v1(p_contract_id uuid, p_amount numeric) IS 'Bốn điều kiện chủ chốt 31/07: hợp đồng ACTIVE, qua start_date+7, thực thu đủ cọc (theo resolve_signed_contract_deposit_basis_v1, KHÔNG theo deposit_paid), và số tiền khớp bậc đã công bố. Thiếu một điều ⇒ phiếu chờ duyệt như cũ.';








--
-- Name: commission_rate_for_v1(uuid, uuid, integer, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.commission_rate_for_v1(p_org uuid, p_building uuid, p_months integer, p_month date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT v.rate_percent
    FROM app_private.commission_tier_versions v
   WHERE v.organization_id = p_org
     AND v.status = 'PUBLISHED'
     AND v.effective_from_month <= date_trunc('month', p_month)::date
     AND (v.building_id = p_building OR v.building_id IS NULL)
     AND p_months BETWEEN v.min_months AND v.max_months
   ORDER BY (v.building_id IS NOT NULL) DESC, v.effective_from_month DESC
   LIMIT 1;
$$;








--
-- Name: contract_customer_credit_balance_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.contract_customer_credit_balance_v1(p_contract_id uuid, p_organization_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_balance numeric(15,2);
  v_ledger_balance numeric(15,2);
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.contracts contract_row
    WHERE contract_row.id = p_contract_id
      AND contract_row.organization_id = p_organization_id
      AND contract_row.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Contract tenant chain is invalid'
      USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.excess_amounts excess
    WHERE excess.organization_id = p_organization_id
      AND excess.contract_id = p_contract_id
      AND excess.credit_lot_id IS NULL
      AND excess.amount <> 0
  ) THEN
    RAISE EXCEPTION 'Legacy customer credit requires manual reconciliation'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(sum(lot.remaining_amount), 0)::numeric(15,2)
    INTO v_balance
  FROM public.customer_credit_lots lot
  WHERE lot.organization_id = p_organization_id
    AND lot.contract_id = p_contract_id
    AND lot.status = 'ACTIVE'
    AND lot.remaining_amount > 0;

  SELECT COALESCE(sum(excess.amount), 0)::numeric(15,2)
    INTO v_ledger_balance
  FROM public.excess_amounts excess
  WHERE excess.organization_id = p_organization_id
    AND excess.contract_id = p_contract_id
    AND excess.credit_lot_id IS NOT NULL;

  IF v_ledger_balance IS DISTINCT FROM v_balance THEN
    RAISE EXCEPTION 'Credit lot balance does not match the compatibility ledger'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_balance;
END;
$$;








--
-- Name: contract_deposit_sources_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.contract_deposit_sources_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(voucher_id uuid, code text, direction text, bucket text, exclude_reason text, amount numeric, signed_amount numeric, account_id uuid, is_virtual boolean, system_source text, voucher_date date, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT ie.id, ie.code,
         CASE WHEN ie.type = 'INCOME' THEN 'IN' ELSE 'OUT' END,
         CASE
           WHEN ie.deleted_at IS NOT NULL              THEN 'EXCLUDED'
           WHEN ie.approval_status = 'CANCELLED'       THEN 'EXCLUDED'
           WHEN ie.approval_status <> 'APPROVED'       THEN 'EXCLUDED'
           WHEN ie.posting_status = 'REVERSED'         THEN 'EXCLUDED'
           WHEN COALESCE(a.is_virtual, false)          THEN 'RECOGNIZED_HISTORICAL'
           WHEN ie.posting_status = 'POSTED'           THEN 'REAL_CASH'
           ELSE 'EXCLUDED'
         END,
         CASE
           WHEN ie.deleted_at IS NOT NULL        THEN 'đã xoá'
           WHEN ie.approval_status = 'CANCELLED' THEN 'đã huỷ'
           WHEN ie.approval_status <> 'APPROVED' THEN 'chưa duyệt'
           WHEN ie.posting_status = 'REVERSED'   THEN 'đã đảo bút toán'
           WHEN COALESCE(a.is_virtual,false)     THEN NULL
           WHEN ie.posting_status <> 'POSTED'    THEN 'chưa ghi sổ'
           ELSE NULL
         END,
         ie.total_amount,
         CASE
           WHEN ie.deleted_at IS NOT NULL
             OR ie.approval_status = 'CANCELLED'
             OR ie.approval_status <> 'APPROVED'
             OR ie.posting_status = 'REVERSED'
             OR (NOT COALESCE(a.is_virtual,false) AND ie.posting_status <> 'POSTED')
           THEN 0
           WHEN ie.type = 'INCOME' THEN ie.total_amount
           ELSE -ie.total_amount
         END,
         ie.account_id, COALESCE(a.is_virtual, false), ie.system_source,
         ie.voucher_date, ie.created_at
    FROM public.income_expenses ie
    LEFT JOIN public.accounts a ON a.id = ie.account_id
   WHERE ie.organization_id = p_organization_id
     AND ie.contract_id = p_contract_id
     AND ie.created_at <= p_as_of
     -- Hạng mục CỌC. Nhận theo TÊN LOẠI (nrm_vn) chứ không theo system_source:
     -- đo thật cho thấy cọc đến từ 12 nguồn khác nhau, kể cả NULL, nên khoá theo
     -- nguồn là bỏ sót ngay.
     AND EXISTS (
       SELECT 1 FROM public.income_expense_items it
       JOIN public.income_expense_types t ON t.id = it.income_expense_type_id
        WHERE it.income_expense_id = ie.id
          AND public.nrm_vn(t.name) LIKE '%coc%')
   -- Thứ tự ỔN ĐỊNH: hai lần gọi phải cho cùng một danh sách.
   ORDER BY ie.created_at, ie.id;
$$;








--
-- Name: FUNCTION contract_deposit_sources_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.contract_deposit_sources_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone) IS 'Các dòng nguồn cọc của một hợp đồng, đã phân rổ REAL_CASH / RECOGNIZED_HISTORICAL / EXCLUDED kèm lý do loại. Nhận diện cọc theo TÊN LOẠI (cọc đến từ 12 nguồn khác nhau kể cả system_source NULL). Thứ tự ổn định theo (created_at, id).';








--
-- Name: count_invalid_payment_reversals_counter_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.count_invalid_payment_reversals_counter_v1(p_payment_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT count(*)::integer
  FROM app_private.payment_reversals reversal
  LEFT JOIN public.payments payment
    ON payment.id = reversal.original_payment_id
  LEFT JOIN public.invoices invoice
    ON invoice.id = payment.invoice_id
  LEFT JOIN public.contracts contract_row
    ON contract_row.id = invoice.contract_id
  LEFT JOIN public.rooms room_row
    ON room_row.id = invoice.room_id
  LEFT JOIN public.buildings building_row
    ON building_row.id = invoice.building_id
  LEFT JOIN public.income_expenses voucher
    ON voucher.id = reversal.reversal_voucher_id
  LEFT JOIN public.income_expenses source_voucher
    ON source_voucher.id = voucher.reversal_of_income_expense_id
  LEFT JOIN public.accounts account_row
    ON account_row.id = voucher.account_id
  LEFT JOIN public.invoice_payment_collections collection
    ON collection.id = payment.collection_id
  LEFT JOIN public.invoice_payment_tenders tender
    ON tender.id = payment.tender_id
  LEFT JOIN LATERAL (
    SELECT
      count(*)::integer AS item_count,
      count(*) FILTER (
        WHERE item.organization_id IS DISTINCT FROM reversal.organization_id
           OR item.accounting_class NOT IN (
             'PNL', 'DEPOSIT', 'CUSTOMER_CREDIT', 'INTERNAL'
           )
      )::integer AS invalid_item_count,
      COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
        AS item_total,
      COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
        WHERE item.accounting_class = 'PNL'
      ), 0) AS pnl_total,
      COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
        WHERE item.accounting_class = 'DEPOSIT'
      ), 0) AS deposit_total,
      COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
        WHERE item.accounting_class = 'CUSTOMER_CREDIT'
      ), 0) AS credit_total,
      COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
        WHERE item.accounting_class = 'INTERNAL'
      ), 0) AS internal_total
    FROM public.income_expense_items item
    WHERE item.income_expense_id = voucher.id
  ) reversal_items ON true
  LEFT JOIN LATERAL (
    WITH raw_sources AS (
      SELECT
        source_row.id, source_row.user_id, source_row.organization_id,
        source_row.type, source_row.account_id, source_row.invoice_id,
        source_row.contract_id, source_row.building_id, source_row.room_id,
        source_row.payment_id, source_row.payment_collection_id,
        source_row.approval_status, source_row.deleted_at,
        source_row.system_source, source_row.notes, source_row.total_amount,
        source_row.created_at, 0 AS source_rank
      FROM public.income_expenses source_row
      WHERE source_row.payment_id = payment.id

      UNION ALL

      SELECT
        source_row.id, source_row.user_id, source_row.organization_id,
        source_row.type, source_row.account_id, source_row.invoice_id,
        source_row.contract_id, source_row.building_id, source_row.room_id,
        source_row.payment_id, source_row.payment_collection_id,
        source_row.approval_status, source_row.deleted_at,
        source_row.system_source, source_row.notes, source_row.total_amount,
        source_row.created_at, 1 AS source_rank
      FROM public.income_expenses source_row
      WHERE source_row.payment_id IS NULL
        AND source_row.notes = '[THU TACH COC ' || payment.id::text || ']'

      UNION ALL

      SELECT
        source_row.id, source_row.user_id, source_row.organization_id,
        source_row.type, source_row.account_id, source_row.invoice_id,
        source_row.contract_id, source_row.building_id, source_row.room_id,
        source_row.payment_id, source_row.payment_collection_id,
        source_row.approval_status, source_row.deleted_at,
        source_row.system_source, source_row.notes, source_row.total_amount,
        source_row.created_at, 2 AS source_rank
      FROM public.income_expenses source_row
      WHERE payment.id = '5b32cb16-b579-4427-bebf-108c5195a279'::uuid
        AND source_row.id = '2ea26ca0-92c6-4896-a7b5-a5ee7031b2cc'::uuid

      UNION ALL

      SELECT
        source_row.id, source_row.user_id, source_row.organization_id,
        source_row.type, source_row.account_id, source_row.invoice_id,
        source_row.contract_id, source_row.building_id, source_row.room_id,
        source_row.payment_id, source_row.payment_collection_id,
        source_row.approval_status, source_row.deleted_at,
        source_row.system_source, source_row.notes, source_row.total_amount,
        source_row.created_at, 3 AS source_rank
      FROM public.income_expenses source_row
      WHERE payment.id = 'dc490170-8e05-43e5-bcf9-1e6151dbbc5a'::uuid
        AND source_row.id = 'f6eb4b16-c7cc-4912-ad0d-517ed66d7270'::uuid
    ), distinct_sources AS (
      SELECT DISTINCT ON (source.id) source.*
      FROM raw_sources source
      ORDER BY source.id, source.source_rank
    ), source_stats AS (
      SELECT
        count(*)::integer AS source_count,
        count(DISTINCT source.account_id)::integer AS account_count,
        (array_agg(
          source.id ORDER BY source.source_rank, source.created_at, source.id
        ))[1] AS primary_source_id,
        count(*) FILTER (
          WHERE source.organization_id IS DISTINCT FROM reversal.organization_id
             OR source.type IS DISTINCT FROM 'INCOME'
             OR source.approval_status IS DISTINCT FROM 'APPROVED'
             OR source.deleted_at IS NOT NULL
             OR source.account_id IS NULL
             OR source.invoice_id IS DISTINCT FROM payment.invoice_id
             OR source.contract_id IS DISTINCT FROM invoice.contract_id
             OR source.building_id IS DISTINCT FROM invoice.building_id
             OR source.room_id IS DISTINCT FROM invoice.room_id
             OR (
               payment.collection_id IS NULL
               AND source.payment_collection_id IS NOT NULL
             )
             OR (
               payment.collection_id IS NOT NULL
               AND source.payment_collection_id IS DISTINCT FROM payment.collection_id
             )
        )::integer AS invalid_identity_count,
        COALESCE(sum(source.total_amount), 0) AS voucher_total
      FROM distinct_sources source
    ), item_stats AS (
      SELECT
        count(item.id)::integer AS item_count,
        count(item.id) FILTER (
          WHERE item.organization_id IS DISTINCT FROM reversal.organization_id
             OR item.accounting_class NOT IN (
               'PNL', 'DEPOSIT', 'CUSTOMER_CREDIT', 'INTERNAL'
             )
        )::integer AS invalid_item_count,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
          AS item_total,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
          WHERE item.accounting_class = 'PNL'
        ), 0) AS pnl_total,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
          WHERE item.accounting_class = 'DEPOSIT'
        ), 0) AS deposit_total,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
          WHERE item.accounting_class = 'CUSTOMER_CREDIT'
        ), 0) AS credit_total,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)) FILTER (
          WHERE item.accounting_class = 'INTERNAL'
        ), 0) AS internal_total
      FROM distinct_sources source
      LEFT JOIN public.income_expense_items item
        ON item.income_expense_id = source.id
    )
    SELECT source_stats.*, item_stats.*
    FROM source_stats CROSS JOIN item_stats
  ) source_lineage ON true
  WHERE (
    p_payment_id IS NULL
    OR reversal.original_payment_id = p_payment_id
  )
  AND reversal.reversal_kind = 'COUNTER_VOUCHER'
  AND (
     payment.id IS NULL
     OR payment.invoice_id IS NULL
     OR payment.organization_id IS DISTINCT FROM reversal.organization_id
     OR payment.organization_id IS DISTINCT FROM invoice.organization_id
     OR payment.received_amount IS NULL
     OR payment.reversed_at IS NULL
     OR invoice.id IS NULL
     OR invoice.contract_id IS NULL
     OR invoice.building_id IS NULL
     OR invoice.room_id IS NULL
     OR contract_row.id IS NULL
     OR contract_row.organization_id IS DISTINCT FROM reversal.organization_id
     OR contract_row.room_id IS DISTINCT FROM invoice.room_id
     OR room_row.id IS NULL
     OR room_row.building_id IS DISTINCT FROM invoice.building_id
     OR building_row.id IS NULL
     OR building_row.organization_id IS DISTINCT FROM reversal.organization_id
     OR voucher.id IS NULL
     OR voucher.organization_id IS DISTINCT FROM reversal.organization_id
     OR voucher.type IS DISTINCT FROM 'EXPENSE'
     OR voucher.approval_status IS DISTINCT FROM 'APPROVED'
     OR voucher.deleted_at IS NOT NULL
     OR voucher.contract_id IS DISTINCT FROM invoice.contract_id
     OR voucher.building_id IS DISTINCT FROM invoice.building_id
     OR voucher.room_id IS DISTINCT FROM invoice.room_id
     OR (
       voucher.invoice_id IS NOT NULL
       AND voucher.invoice_id IS DISTINCT FROM payment.invoice_id
     )
     OR voucher.account_id IS NULL
     OR account_row.id IS NULL
     OR account_row.organization_id IS DISTINCT FROM reversal.organization_id
     OR account_row.deleted_at IS NOT NULL
     OR (
       account_row.is_virtual
       AND NOT (
         payment.id = 'dc490170-8e05-43e5-bcf9-1e6151dbbc5a'::uuid
         AND source_voucher.id = 'f6eb4b16-c7cc-4912-ad0d-517ed66d7270'::uuid
         AND voucher.id = '26e7a16b-e0d3-44aa-b954-735e0c8f9462'::uuid
         AND payment.received_amount = 0
         AND source_voucher.system_source = 'termination.revenue'
       )
     )
     OR source_voucher.id IS NULL
     OR source_voucher.id IS DISTINCT FROM source_lineage.primary_source_id
     OR source_voucher.organization_id IS DISTINCT FROM reversal.organization_id
     OR source_voucher.type IS DISTINCT FROM 'INCOME'
     OR source_voucher.approval_status IS DISTINCT FROM 'APPROVED'
     OR source_voucher.deleted_at IS NOT NULL
     OR source_voucher.invoice_id IS DISTINCT FROM payment.invoice_id
     OR source_voucher.contract_id IS DISTINCT FROM invoice.contract_id
     OR source_voucher.building_id IS DISTINCT FROM invoice.building_id
     OR source_voucher.room_id IS DISTINCT FROM invoice.room_id
     OR source_voucher.account_id IS DISTINCT FROM voucher.account_id
     OR source_lineage.source_count < 1
     OR source_lineage.account_count <> 1
     OR source_lineage.invalid_identity_count <> 0
     OR source_lineage.invalid_item_count <> 0
     OR source_lineage.item_count < 1
     OR voucher.voucher_date < GREATEST(
       payment.payment_date,
       source_voucher.voucher_date
     )
     OR (
       payment.collection_id IS NULL
       AND (
         payment.tender_id IS NOT NULL
         OR payment.reversed_by_collection_id IS NOT NULL
         OR voucher.payment_collection_id IS NOT NULL
       )
     )
     OR (
       payment.collection_id IS NOT NULL
       AND (
         collection.id IS NULL
         OR collection.organization_id IS DISTINCT FROM reversal.organization_id
         OR collection.invoice_id IS DISTINCT FROM payment.invoice_id
         OR collection.contract_id IS DISTINCT FROM invoice.contract_id
         OR collection.status IS DISTINCT FROM 'REVERSED'
         OR collection.reversed_at IS NULL
         OR tender.id IS NULL
         OR tender.organization_id IS DISTINCT FROM reversal.organization_id
         OR tender.collection_id IS DISTINCT FROM collection.id
         OR tender.payment_id IS DISTINCT FROM payment.id
         OR tender.voucher_id IS DISTINCT FROM source_voucher.id
         OR tender.account_id IS DISTINCT FROM voucher.account_id
         OR payment.reversed_by_collection_id IS DISTINCT FROM collection.id
         OR source_voucher.payment_id IS DISTINCT FROM payment.id
         OR source_voucher.payment_collection_id IS DISTINCT FROM collection.id
         OR voucher.payment_collection_id IS DISTINCT FROM collection.id
         OR voucher.system_source IS DISTINCT FROM 'invoice.collection.reverse.v5'
       )
     )
     OR reversal_items.item_count < 1
     OR reversal_items.invalid_item_count <> 0
     OR abs(reversal_items.item_total - voucher.total_amount) >= 0.01
     OR abs(
       voucher.total_amount
       - CASE
           WHEN payment.received_amount = 0 THEN payment.amount
           ELSE payment.received_amount
         END
     ) >= 0.01
     OR abs(
       source_lineage.voucher_total
       - CASE
           WHEN payment.received_amount = 0 THEN payment.amount
           ELSE payment.received_amount
         END
     ) >= 0.01
     OR abs(source_lineage.item_total - source_lineage.voucher_total) >= 0.01
     OR abs(reversal_items.pnl_total - source_lineage.pnl_total) >= 0.01
     OR abs(reversal_items.deposit_total - source_lineage.deposit_total) >= 0.01
     OR abs(reversal_items.credit_total - source_lineage.credit_total) >= 0.01
     OR abs(reversal_items.internal_total - source_lineage.internal_total) >= 0.01
     OR abs(reversal_items.pnl_total - COALESCE(voucher.kqkd_amount, 0)) >= 0.01
  );
$$;








--
-- Name: count_invalid_payment_reversals_in_place_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.count_invalid_payment_reversals_in_place_v1(p_payment_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT count(*)::integer
  FROM app_private.payment_reversals reversal
  LEFT JOIN public.payments payment
    ON payment.id = reversal.original_payment_id
  LEFT JOIN public.invoices invoice
    ON invoice.id = payment.invoice_id
  LEFT JOIN public.invoice_payment_collections collection
    ON collection.id = payment.collection_id
  LEFT JOIN public.invoice_payment_tenders tender
    ON tender.id = payment.tender_id
  LEFT JOIN public.income_expenses voucher
    ON voucher.id = reversal.reversal_voucher_id
  LEFT JOIN public.accounts account_row
    ON account_row.id = voucher.account_id
  LEFT JOIN LATERAL (
    -- Bút toán của phiếu phải triệt tiêu về 0: đây là hậu điều kiện TIỀN,
    -- thứ duy nhất chứng minh huỷ tại chỗ đã thật sự rút tiền khỏi sổ quỹ.
    SELECT COALESCE(sum(line.signed_amount), 0) AS net,
           count(*) FILTER (WHERE posting.event_kind = 'REVERSAL')::integer AS reversal_count
    FROM public.income_expense_posting_lines line
    JOIN public.income_expense_postings posting ON posting.id = line.posting_id
    WHERE posting.posting_subject_kind = 'VOUCHER'
      AND posting.posting_subject_id = voucher.id
  ) posting_net ON true
  WHERE reversal.reversal_kind = 'IN_PLACE_CANCEL'
    AND (p_payment_id IS NULL OR reversal.original_payment_id = p_payment_id)
    AND (
      -- Danh tính khoản thanh toán
      payment.id IS NULL
      OR payment.invoice_id IS NULL
      OR payment.reversed_at IS NULL
      OR payment.received_amount IS NULL
      OR payment.organization_id IS DISTINCT FROM reversal.organization_id
      OR invoice.id IS NULL
      OR invoice.organization_id IS DISTINCT FROM reversal.organization_id
      -- Huỷ tại chỗ CHỈ tồn tại trên đường collection V5
      OR payment.collection_id IS NULL
      OR collection.id IS NULL
      OR collection.organization_id IS DISTINCT FROM reversal.organization_id
      OR collection.invoice_id IS DISTINCT FROM payment.invoice_id
      OR collection.status IS DISTINCT FROM 'REVERSED'
      OR collection.reversed_at IS NULL
      OR payment.reversed_by_collection_id IS DISTINCT FROM collection.id
      OR tender.id IS NULL
      OR tender.organization_id IS DISTINCT FROM reversal.organization_id
      OR tender.collection_id IS DISTINCT FROM collection.id
      OR tender.payment_id IS DISTINCT FROM payment.id
      -- Dòng audit PHẢI trỏ về CHÍNH phiếu thu gốc, không phải phiếu nào khác
      OR voucher.id IS NULL
      OR tender.voucher_id IS DISTINCT FROM voucher.id
      OR voucher.organization_id IS DISTINCT FROM reversal.organization_id
      OR voucher.type IS DISTINCT FROM 'INCOME'
      OR voucher.deleted_at IS NOT NULL
      OR voucher.payment_id IS DISTINCT FROM payment.id
      OR voucher.payment_collection_id IS DISTINCT FROM collection.id
      OR voucher.invoice_id IS DISTINCT FROM payment.invoice_id
      OR voucher.contract_id IS DISTINCT FROM invoice.contract_id
      OR voucher.building_id IS DISTINCT FROM invoice.building_id
      OR voucher.room_id IS DISTINCT FROM invoice.room_id
      -- Trạng thái sau khi huỷ tại chỗ
      OR voucher.approval_status IS DISTINCT FROM 'CANCELLED'
      OR voucher.posting_status IS DISTINCT FROM 'REVERSED'
      OR voucher.active_posting_id_v2 IS NOT NULL
      OR voucher.reversed_by_posting_id IS NULL
      -- Sổ quỹ
      OR voucher.account_id IS NULL
      OR voucher.account_id IS DISTINCT FROM tender.account_id
      OR account_row.id IS NULL
      OR account_row.organization_id IS DISTINCT FROM reversal.organization_id
      OR account_row.deleted_at IS NOT NULL
      -- Số tiền phiếu phải khớp khoản đã thu
      OR abs(
           voucher.total_amount
           - CASE WHEN payment.received_amount = 0 THEN payment.amount
                  ELSE payment.received_amount END
         ) >= 0.01
      -- KHÔNG được vừa huỷ tại chỗ vừa có phiếu đối ứng còn sống: đảo hai lần
      OR EXISTS (
        SELECT 1 FROM public.income_expenses counter
        WHERE counter.reversal_of_income_expense_id = voucher.id
          AND counter.deleted_at IS NULL
          AND counter.approval_status <> 'CANCELLED'
      )
      -- Hậu điều kiện tiền
      OR posting_net.reversal_count < 1
      OR posting_net.net <> 0
    );
$$;








--
-- Name: count_invalid_payment_reversals_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.count_invalid_payment_reversals_v1(p_payment_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT app_private.count_invalid_payment_reversals_counter_v1(p_payment_id)
       + app_private.count_invalid_payment_reversals_in_place_v1(p_payment_id);
$$;








--
-- Name: current_admin_org_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.current_admin_org_v1() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare v_org uuid;
begin
  if (select auth.uid()) is null then return null; end if;
  select m.organization_id into v_org
    from public.organization_memberships m
    join public.organizations o on o.id = m.organization_id and o.status = 'ACTIVE'
   where m.user_id = (select auth.uid()) and m.status = 'ACTIVE'
   order by coalesce(o.is_demo, false), m.organization_id
   limit 1;
  if v_org is null then return null; end if;
  -- Đọc danh sách thành viên là quyền users.view. Quản trị nền tảng luôn qua.
  if public.is_super_admin() or app_private.has_any_scope_v3('users.view') then
    return v_org;
  end if;
  return null;
end
$$;








--
-- Name: current_profit_building_source_hash_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.current_profit_building_source_hash_v1(p_profit_monthly_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_profit public.profit_monthly%ROWTYPE;
  v_building_ids uuid[];
  v_hash text;
BEGIN
  SELECT profit.* INTO v_profit
  FROM public.profit_monthly profit
  WHERE profit.id = p_profit_monthly_id;
  IF NOT FOUND OR v_profit.status <> 'LOCKED' THEN
    RETURN NULL;
  END IF;

  SELECT array_agg(
           DISTINCT (source_row.value->>'building_id')::uuid
           ORDER BY (source_row.value->>'building_id')::uuid
         )
    INTO v_building_ids
  FROM public.profit_close_revisions revision
  JOIN public.profit_close_runs run ON run.id = revision.run_id
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(run.source_snapshot->'pnl') = 'array'
        THEN run.source_snapshot->'pnl'
      ELSE '[]'::jsonb
    END
  ) source_row(value)
  WHERE revision.profit_monthly_id = v_profit.id
    AND revision.organization_id = v_profit.organization_id
    AND revision.building_id = v_profit.building_id
    AND revision.period_month = v_profit.period_month
    AND revision.revision_number = v_profit.revision_number
    AND revision.operation IN ('CLOSE', 'RECLOSE')
    AND run.organization_id = v_profit.organization_id
    AND run.period_month = v_profit.period_month
    AND run.source_snapshot->>'algorithm_version' = 'profit-close-v2.1';

  IF v_building_ids IS NULL
     OR NOT (v_profit.building_id = ANY(v_building_ids)) THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_building_ids) source_building(building_id)
    LEFT JOIN public.buildings building
      ON building.id = source_building.building_id
    WHERE building.id IS NULL
       OR building.organization_id IS DISTINCT FROM v_profit.organization_id
       OR building.deleted_at IS NOT NULL
       OR building.is_virtual
  ) THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.building_shareholders building_shareholder
    LEFT JOIN public.shareholders shareholder
      ON shareholder.id = building_shareholder.shareholder_id
    WHERE building_shareholder.building_id = ANY(v_building_ids)
      AND (
        building_shareholder.organization_id IS DISTINCT FROM
          v_profit.organization_id
        OR shareholder.id IS NULL
        OR shareholder.organization_id IS DISTINCT FROM
          v_profit.organization_id
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.building_shareholders building_shareholder
    JOIN public.shareholders shareholder
      ON shareholder.id = building_shareholder.shareholder_id
     AND shareholder.organization_id = v_profit.organization_id
     AND shareholder.is_active
     AND shareholder.deleted_at IS NULL
    WHERE building_shareholder.building_id = ANY(v_building_ids)
      AND building_shareholder.organization_id = v_profit.organization_id
    GROUP BY building_shareholder.building_id
    HAVING sum(building_shareholder.percent) > 100
  ) THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_manager_salary_buildings salary_building
    JOIN public.profit_manager_salaries salary
      ON salary.id = salary_building.salary_id
    LEFT JOIN public.profit_managers manager ON manager.id = salary.manager_id
    WHERE salary_building.building_id = ANY(v_building_ids)
      AND salary.is_active
      AND (
        manager.id IS NULL
        OR (
          manager.is_active
          AND manager.deleted_at IS NULL
          AND (
            salary_building.organization_id IS DISTINCT FROM
              v_profit.organization_id
            OR salary.organization_id IS DISTINCT FROM
              v_profit.organization_id
            OR manager.organization_id IS DISTINCT FROM
              v_profit.organization_id
          )
        )
      )
  ) THEN
    RETURN NULL;
  END IF;

  WITH selected AS MATERIALIZED (
    SELECT
      building.id AS building_id,
      building.name AS building_name
    FROM public.buildings building
    WHERE building.id = ANY(v_building_ids)
  ),
  vouchers AS MATERIALIZED (
    SELECT
      voucher.id,
      voucher.type::text AS side,
      voucher.voucher_date,
      selected.building_id,
      selected.building_name,
      voucher.total_amount,
      voucher.business_result_accounting AS override,
      CASE
        WHEN voucher.invoice_id IS NOT NULL
         AND invoice.billing_month ~ '^\d{4}-\d{2}$'
          THEN to_date(invoice.billing_month, 'YYYY-MM')
      END AS invoice_month
    FROM selected
    JOIN public.income_expenses voucher
      ON voucher.building_id = selected.building_id
    LEFT JOIN public.invoices invoice
      ON invoice.id = voucher.invoice_id
     AND invoice.deleted_at IS NULL
    WHERE voucher.deleted_at IS NULL
      AND voucher.approval_status = 'APPROVED'
      AND voucher.business_result_accounting IS DISTINCT FROM false
  ),
  invoice_items AS (
    SELECT
      voucher.invoice_month AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      type_row.id AS type_id,
      type_row.name AS type_name,
      type_row.category,
      COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amount
    FROM vouchers voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
    JOIN public.income_expense_types type_row
      ON type_row.id = item.income_expense_type_id
    WHERE voucher.invoice_month IS NOT NULL
      AND (voucher.override IS TRUE OR item.accounting_class = 'PNL')
  ),
  invoice_no_item AS (
    SELECT
      voucher.invoice_month AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      NULL::uuid AS type_id,
      U&'Kh\00F4ng c\00F3 h\1EA1ng m\1EE5c'::text AS type_name,
      NULL::text AS category,
      voucher.total_amount::numeric AS amount
    FROM vouchers voucher
    WHERE voucher.invoice_month IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.income_expense_items item
        WHERE item.income_expense_id = voucher.id
      )
  ),
  period_items AS (
    SELECT
      (
        date_trunc('month', item.start_date)
        + (series.i || ' month')::interval
      )::date AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      type_row.id AS type_id,
      type_row.name AS type_name,
      type_row.category,
      (
        round(
          COALESCE(item.amount, item.unit_price * item.quantity)
          * (series.i + 1) / month_count.n
        )
        - round(
          COALESCE(item.amount, item.unit_price * item.quantity)
          * series.i / month_count.n
        )
      )::numeric AS amount
    FROM vouchers voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
    JOIN public.income_expense_types type_row
      ON type_row.id = item.income_expense_type_id
    CROSS JOIN LATERAL (
      SELECT GREATEST(
        extract(year FROM item.end_date)::integer * 12
          + extract(month FROM item.end_date)::integer
          - extract(year FROM item.start_date)::integer * 12
          - extract(month FROM item.start_date)::integer
          + 1,
        1
      ) AS n
    ) month_count
    CROSS JOIN LATERAL generate_series(
      0, month_count.n - 1
    ) AS series(i)
    WHERE voucher.invoice_month IS NULL
      AND (voucher.override IS TRUE OR item.accounting_class = 'PNL')
      AND item.start_date IS NOT NULL
      AND item.end_date IS NOT NULL
      AND item.end_date >= item.start_date
  ),
  invalid_period_items AS (
    SELECT
      date_trunc('month', item.start_date)::date AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      type_row.id AS type_id,
      type_row.name AS type_name,
      type_row.category,
      COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amount
    FROM vouchers voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
    JOIN public.income_expense_types type_row
      ON type_row.id = item.income_expense_type_id
    WHERE voucher.invoice_month IS NULL
      AND (voucher.override IS TRUE OR item.accounting_class = 'PNL')
      AND item.start_date IS NOT NULL
      AND item.end_date IS NOT NULL
      AND item.end_date < item.start_date
  ),
  no_period_items AS (
    SELECT
      date_trunc('month', voucher.voucher_date)::date AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      type_row.id AS type_id,
      type_row.name AS type_name,
      type_row.category,
      COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amount
    FROM vouchers voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
    JOIN public.income_expense_types type_row
      ON type_row.id = item.income_expense_type_id
    WHERE voucher.invoice_month IS NULL
      AND (voucher.override IS TRUE OR item.accounting_class = 'PNL')
      AND (item.start_date IS NULL OR item.end_date IS NULL)
  ),
  no_item AS (
    SELECT
      date_trunc('month', voucher.voucher_date)::date AS month,
      voucher.id AS voucher_id,
      voucher.building_id,
      voucher.building_name,
      voucher.side,
      NULL::uuid AS type_id,
      U&'Kh\00F4ng c\00F3 h\1EA1ng m\1EE5c'::text AS type_name,
      NULL::text AS category,
      voucher.total_amount::numeric AS amount
    FROM vouchers voucher
    WHERE voucher.invoice_month IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.income_expense_items item
        WHERE item.income_expense_id = voucher.id
      )
  ),
  source_lines AS MATERIALIZED (
    SELECT * FROM invoice_items
    UNION ALL SELECT * FROM invoice_no_item
    UNION ALL SELECT * FROM period_items
    UNION ALL SELECT * FROM invalid_period_items
    UNION ALL SELECT * FROM no_period_items
    UNION ALL SELECT * FROM no_item
  ),
  period_lines AS MATERIALIZED (
    SELECT *
    FROM source_lines
    WHERE month = v_profit.period_month
  ),
  pnl AS MATERIALIZED (
    SELECT
      line.building_id,
      COALESCE(sum(line.amount) FILTER (
        WHERE line.side = 'INCOME'
      ), 0)::numeric AS revenue,
      COALESCE(sum(line.amount) FILTER (
        WHERE line.side = 'EXPENSE'
      ), 0)::numeric AS expense,
      (
        COALESCE(sum(line.amount) FILTER (
          WHERE line.side = 'INCOME'
        ), 0)
        - COALESCE(sum(line.amount) FILTER (
          WHERE line.side = 'EXPENSE'
        ), 0)
      )::numeric AS net
    FROM period_lines line
    GROUP BY line.building_id
  ),
  base AS MATERIALIZED (
    SELECT
      selected.building_id,
      selected.building_name,
      COALESCE(pnl.revenue, 0)::numeric AS source_revenue,
      COALESCE(pnl.expense, 0)::numeric AS source_expense,
      COALESCE(pnl.net, 0)::numeric AS computed_profit
    FROM selected
    LEFT JOIN pnl ON pnl.building_id = selected.building_id
  ),
  share_config AS MATERIALIZED (
    SELECT
      building_shareholder.building_id,
      building_shareholder.shareholder_id,
      shareholder.name AS shareholder_name,
      building_shareholder.percent::numeric AS percent
    FROM public.building_shareholders building_shareholder
    JOIN public.shareholders shareholder
      ON shareholder.id = building_shareholder.shareholder_id
     AND shareholder.organization_id = v_profit.organization_id
     AND shareholder.is_active
     AND shareholder.deleted_at IS NULL
    WHERE building_shareholder.organization_id = v_profit.organization_id
      AND building_shareholder.building_id = ANY(v_building_ids)
  ),
  pnl_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'building_id', base.building_id,
        'building_name', base.building_name,
        'revenue', base.source_revenue,
        'expense', base.source_expense,
        'net', base.computed_profit
      ) ORDER BY base.building_id
    ), '[]'::jsonb) AS value
    FROM base
  ),
  line_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'month', line.month,
        'voucher_id', line.voucher_id,
        'building_id', line.building_id,
        'building_name', line.building_name,
        'side', line.side,
        'type_id', line.type_id,
        'type_name', line.type_name,
        'category', line.category,
        'amount', line.amount
      ) ORDER BY
        line.building_id, line.voucher_id, line.side,
        line.type_id NULLS FIRST, line.amount
    ), '[]'::jsonb) AS value
    FROM period_lines line
  ),
  share_config_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'building_id', config.building_id,
        'shareholder_id', config.shareholder_id,
        'shareholder_name', config.shareholder_name,
        'percent', config.percent
      ) ORDER BY config.building_id, config.shareholder_id
    ), '[]'::jsonb) AS value
    FROM share_config config
  ),
  manager_rules_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'rule_id', salary.id,
        'manager_id', salary.manager_id,
        'manager_name', manager.name,
        'label', salary.label,
        'form', salary.form,
        'basis', salary.basis,
        'amount', salary.amount,
        'percent', salary.percent,
        'building_ids', COALESCE((
          SELECT jsonb_agg(
            salary_building.building_id
            ORDER BY salary_building.building_id
          )
          FROM public.profit_manager_salary_buildings salary_building
          WHERE salary_building.salary_id = salary.id
            AND salary_building.organization_id = v_profit.organization_id
            AND salary_building.building_id = ANY(v_building_ids)
        ), '[]'::jsonb)
      ) ORDER BY salary.id
    ), '[]'::jsonb) AS value
    FROM public.profit_manager_salaries salary
    JOIN public.profit_managers manager
      ON manager.id = salary.manager_id
     AND manager.organization_id = v_profit.organization_id
     AND manager.is_active
     AND manager.deleted_at IS NULL
    WHERE salary.organization_id = v_profit.organization_id
      AND salary.is_active
      AND EXISTS (
        SELECT 1
        FROM public.profit_manager_salary_buildings salary_building
        WHERE salary_building.salary_id = salary.id
          AND salary_building.organization_id = v_profit.organization_id
          AND salary_building.building_id = ANY(v_building_ids)
      )
  ),
  source_document AS MATERIALIZED (
    SELECT jsonb_build_object(
      'algorithm_version', 'profit-close-v2.1',
      'organization_id', v_profit.organization_id,
      'period_month', v_profit.period_month,
      'pnl', pnl_document.value,
      'accrual_lines', line_document.value,
      'shareholder_config', share_config_document.value,
      'manager_salary_rules', manager_rules_document.value
    ) AS value
    FROM pnl_document
    CROSS JOIN line_document
    CROSS JOIN share_config_document
    CROSS JOIN manager_rules_document
  )
  SELECT md5(jsonb_build_object(
    'algorithm_version', 'profit-close-v2.1',
    'organization_id', v_profit.organization_id,
    'period_month', v_profit.period_month,
    'building_id', base.building_id,
    'source_building_bases', source_document.value->'pnl',
    'pnl', jsonb_build_object(
      'revenue', base.source_revenue,
      'expense', base.source_expense,
      'net', base.computed_profit
    ),
    'accrual_lines', COALESCE((
      SELECT jsonb_agg(
        entry.value ORDER BY
          entry.value->>'voucher_id', entry.value->>'side',
          entry.value->>'type_id', entry.value->>'amount'
      )
      FROM jsonb_array_elements(
        source_document.value->'accrual_lines'
      ) entry(value)
      WHERE entry.value->>'building_id' = base.building_id::text
    ), '[]'::jsonb),
    'shareholder_config', COALESCE((
      SELECT jsonb_agg(
        entry.value ORDER BY entry.value->>'shareholder_id'
      )
      FROM jsonb_array_elements(
        source_document.value->'shareholder_config'
      ) entry(value)
      WHERE entry.value->>'building_id' = base.building_id::text
    ), '[]'::jsonb),
    'manager_salary_rules', COALESCE((
      SELECT jsonb_agg(entry.value ORDER BY entry.value->>'rule_id')
      FROM jsonb_array_elements(
        source_document.value->'manager_salary_rules'
      ) entry(value)
      WHERE entry.value->'building_ids' @>
        to_jsonb(ARRAY[base.building_id])
    ), '[]'::jsonb)
  )::text)
    INTO v_hash
  FROM base
  CROSS JOIN source_document
  WHERE base.building_id = v_profit.building_id;

  RETURN v_hash;
END
$_$;








--
-- Name: current_uid_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.current_uid_v1() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$ select auth.uid() $$;








--
-- Name: decide_financial_request_v1(uuid, bigint, uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.decide_financial_request_v1(p_request_id uuid, p_expected_version bigint, p_actor_membership uuid, p_actor_user uuid, p_decision text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_req public.approval_requests;
  v_ie public.income_expenses;
  v_posting uuid;
  v_step public.approval_request_steps;
  v_next_pending uuid;
BEGIN
  IF p_decision NOT IN ('APPROVE', 'REJECT') THEN
    RAISE EXCEPTION 'invalid decision %', p_decision USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_req
  FROM public.approval_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_req.version <> p_expected_version THEN
    RAISE EXCEPTION 'version conflict' USING ERRCODE = '40001';
  END IF;
  IF v_req.state <> 'PENDING_APPROVAL' THEN
    RAISE EXCEPTION 'request not decidable from %', v_req.state
      USING ERRCODE = '55000';
  END IF;

  IF p_actor_membership = v_req.maker_membership_id
     OR p_actor_user = v_req.maker_user_id THEN
    RAISE EXCEPTION 'maker cannot approve own request' USING ERRCODE = '42501';
  END IF;

  IF p_decision = 'APPROVE'
     AND v_req.system_source = 'profit.distribution' THEN
    PERFORM app_private.lock_profit_payout_sources_v2();
  END IF;

  SELECT * INTO v_ie
  FROM public.income_expenses
  WHERE id = v_req.subject_id
    AND organization_id = v_req.organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subject missing' USING ERRCODE = 'P0002';
  END IF;
  IF v_ie.source_payload_hash IS NULL
     OR v_req.payload_hash IS NULL
     OR v_req.payload_hash <> v_ie.source_payload_hash THEN
    RAISE EXCEPTION 'subject changed or lost its snapshot hash (fail-closed)'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_step
  FROM public.approval_request_steps
  WHERE request_id = p_request_id
    AND status = 'PENDING'
  ORDER BY step_no
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no PENDING step to decide' USING ERRCODE = '55000';
  END IF;

  IF NOT app_private.is_eligible_current_candidate_v1(
    v_step.id, p_actor_membership
  ) THEN
    RAISE EXCEPTION 'actor is not an eligible candidate for this step'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.approval_decisions (
    organization_id, request_id, request_step_id, actor_membership_id,
    actor_user_id, decision, reason, request_version
  ) VALUES (
    v_req.organization_id, p_request_id, v_step.id, p_actor_membership,
    p_actor_user,
    CASE p_decision
      WHEN 'APPROVE' THEN 'CHECKER_APPROVE'
      ELSE 'CHECKER_REJECT'
    END,
    p_reason, v_req.version
  );

  IF p_decision = 'REJECT' THEN
    UPDATE public.approval_request_steps
       SET status = 'REJECTED'
     WHERE id = v_step.id;
    UPDATE public.approval_requests
       SET state = 'REJECTED', version = version + 1
     WHERE id = p_request_id
       AND version = p_expected_version;
    RETURN NULL;
  END IF;

  IF NOT app_private.step_is_satisfied_v1(v_step.id) THEN
    RETURN NULL;
  END IF;
  UPDATE public.approval_request_steps
     SET status = 'APPROVED'
   WHERE id = v_step.id;

  SELECT id INTO v_next_pending
  FROM public.approval_request_steps
  WHERE request_id = p_request_id
    AND status = 'WAITING'
  ORDER BY step_no
  LIMIT 1;
  IF v_next_pending IS NOT NULL THEN
    UPDATE public.approval_request_steps
       SET status = 'PENDING'
     WHERE id = v_next_pending;
    RETURN NULL;
  END IF;

  v_posting := app_private.post_financial_request_v1(
    p_request_id, v_req.version, p_actor_user
  );
  RETURN v_posting;
END
$$;








--
-- Name: derive_uploader_org_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.derive_uploader_org_v1(p_uploader uuid) RETURNS TABLE(org uuid, how text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with owner_org as (
    select m.organization_id
      from public.organization_memberships m
     where m.user_id = p_uploader and m.status = 'ACTIVE' and m.member_type = 'OWNER'
     group by m.organization_id
  ),
  single_owner as (
    select case when (select count(*) from owner_org) = 1
                then (select organization_id from owner_org) end as oid
  ),
  single_mem as (
    select case when (select count(distinct m.organization_id)
                        from public.organization_memberships m
                       where m.user_id = p_uploader and m.status='ACTIVE') = 1
                then (select distinct m.organization_id
                        from public.organization_memberships m
                       where m.user_id = p_uploader and m.status='ACTIVE') end as oid
  )
  select coalesce((select oid from single_owner), (select oid from single_mem)) as org,
         case when (select oid from single_owner) is not null then 'uploader_owner_org'
              when (select oid from single_mem)   is not null then 'uploader_single_org'
              else 'quarantine' end as how;
$$;








--
-- Name: dispatch_finance_decision_v2(uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.dispatch_finance_decision_v2(p_subject_id uuid, p_decision text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_ie public.income_expenses;
  v_own app_private.income_expense_flow_ownership;
  v_owner_key text;
  v_adp app_private.finance_flow_owner_adapters;
  v_org uuid;
BEGIN
  IF p_decision IS NULL OR length(btrim(p_decision)) = 0 THEN
    RAISE EXCEPTION 'dispatch_finance_decision_v2: decision required' USING ERRCODE = '22023';
  END IF;

  -- Lock the subject voucher (composite subjects pass a member/leg voucher id) + its flow-ownership row.
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_subject_id FOR UPDATE;
  IF FOUND THEN
    v_org := v_ie.organization_id;
  END IF;

  SELECT * INTO v_own FROM app_private.income_expense_flow_ownership o
   WHERE o.income_expense_id = p_subject_id FOR UPDATE;

  IF NOT FOUND THEN
    -- No ownership row => MANUAL. Manual subjects are served by the Stage-5 public RPCs, not this router.
    v_owner_key := 'MANUAL';
  ELSE
    v_owner_key := v_own.flow_kind;
    v_org := COALESCE(v_org, v_own.organization_id);
  END IF;

  SELECT * INTO v_adp FROM app_private.finance_flow_owner_adapters a WHERE a.flow_owner = v_owner_key;
  IF NOT FOUND THEN
    -- Unknown / non-decision owner (e.g. a POSTED collection) — fail closed, never fall back to manual.
    RAISE EXCEPTION 'dispatch_finance_decision_v2: unknown flow owner % for subject % (fail closed)', v_owner_key, p_subject_id
      USING ERRCODE = '42501';
  END IF;

  IF NOT (p_decision = ANY (v_adp.supported_decisions)) THEN
    RAISE EXCEPTION 'dispatch_finance_decision_v2: owner % does not support decision %', v_owner_key, p_decision
      USING ERRCODE = '55000';
  END IF;

  IF NOT v_adp.is_system_owned THEN
    RAISE EXCEPTION 'dispatch_finance_decision_v2: subject % is MANUAL; call the Stage-5 manual RPC directly', p_subject_id
      USING ERRCODE = '42501';
  END IF;

  -- §2.6 policy gate for owners that require a business-policy decision.
  PERFORM app_private.finance_v2_require_policy(v_org, v_adp.requires_policy_key);

  -- Route to the registered adapter. Composite adapters read their own keys from p_payload.
  CASE v_adp.adapter_name
    WHEN 'INVOICE_REFUND' THEN
      -- approve-only NEVER touches the reservation ledger / refunded cash (plan §8.1).
      IF p_decision = 'approve' THEN
        PERFORM app_private.finance_v2_transition_owned_approval(p_subject_id, 'APPROVED', 'UNPOSTED');
        RETURN jsonb_build_object('refundVoucherId', p_subject_id, 'approvalStatus', 'APPROVED', 'reservationUnchanged', true);
      ELSIF p_decision IN ('reject','cancel') THEN
        PERFORM app_private.finance_v2_transition_owned_approval(p_subject_id, 'CANCELLED', 'UNPOSTED');
        RETURN app_private.transition_invoice_refund_reservation_v2(
          v_org, (p_payload->>'reservationId')::uuid, 'RELEASED', NULL,
          (p_payload->>'expectedStateVersion')::bigint, p_payload->>'reason');
      ELSE  -- post / reverse consume/release with the posting linkage
        RETURN app_private.transition_invoice_refund_reservation_v2(
          v_org, (p_payload->>'reservationId')::uuid,
          CASE p_decision WHEN 'post' THEN 'CONSUMED' ELSE 'REVERSED' END,
          (p_payload->>'postingId')::uuid, (p_payload->>'expectedStateVersion')::bigint, p_payload->>'reason');
      END IF;
    WHEN 'PROFIT_PAYOUT' THEN
      IF p_decision = 'approve' THEN
        RETURN jsonb_build_object('reservationUnchanged', true, 'decision', 'approve');
      ELSE
        RETURN app_private.transition_profit_payout_reservation_v2(
          v_org, (p_payload->>'reservationId')::uuid,
          CASE p_decision WHEN 'post' THEN 'CONSUMED' WHEN 'reverse' THEN 'REVERSED' ELSE 'RELEASED' END,
          (p_payload->>'postingId')::uuid, (p_payload->>'expectedStateVersion')::bigint, p_payload->>'reason');
      END IF;
    WHEN 'TERMINATION_FORFEIT_PAIR' THEN
      RETURN app_private.transition_termination_forfeit_pair_v2(
        v_org, p_subject_id, p_decision, p_payload->>'reason');
    WHEN 'TERMINATION_MOVE_OUT_PAIR' THEN
      IF p_decision = 'reverse' THEN
        RETURN app_private.reverse_termination_move_out_pair_v2(v_org, (p_payload->>'authorizationId')::uuid, p_payload->>'reason');
      ELSE
        RETURN app_private.transition_termination_move_out_pair_v2(v_org, (p_payload->>'authorizationId')::uuid, p_decision, p_payload->>'reason');
      END IF;
    WHEN 'SALARY_BUNDLE' THEN
      RETURN app_private.transition_salary_settlement_bundle_v2(v_org, (p_payload->>'bundleId')::uuid, p_decision, p_payload->>'reason');
    ELSE
      RAISE EXCEPTION 'dispatch_finance_decision_v2: adapter % not wired for decision routing', v_adp.adapter_name
        USING ERRCODE = '0A000';
  END CASE;
END
$$;








--
-- Name: FUNCTION dispatch_finance_decision_v2(p_subject_id uuid, p_decision text, p_payload jsonb); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.dispatch_finance_decision_v2(p_subject_id uuid, p_decision text, p_payload jsonb) IS 'Plan §7.1/§8: lock flow owner + approval subject, route decision to the registered adapter; unknown owner fails closed (no manual fallback).';








--
-- Name: effective_profit_contributions_v2(uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.effective_profit_contributions_v2(p_org uuid, p_period date) RETURNS TABLE(organization_id uuid, target_period date, contribution_kind text, contribution_id uuid, source_voucher_id uuid, source_approval_status text, source_review_state text, source_version bigint, signed_kqkd_amount numeric, allocation_snapshot jsonb, source_payload_hash text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
  WITH base_v AS (
    SELECT ie.id                       AS voucher_id,
           ie.organization_id          AS org_id,
           ie.type                     AS vtype,
           ie.voucher_date             AS vdate,
           ie.approval_status          AS appr,
           ie.review_state             AS rev,
           ie.approval_version         AS appr_ver,
           ie.recognition_date         AS recog_date,
           ie.source_payload_hash      AS src_hash,
           CASE
             WHEN ie.invoice_id IS NOT NULL AND inv.billing_month ~ '^\d{4}-\d{2}$'
             THEN to_date(inv.billing_month, 'YYYY-MM')
           END                          AS inv_month
    FROM public.income_expenses ie
    LEFT JOIN public.invoices inv
      ON inv.id = ie.invoice_id AND inv.deleted_at IS NULL
    WHERE ie.organization_id = p_org
      AND ie.deleted_at IS NULL
      AND COALESCE(ie.recognition_source_mode, 'BASE') = 'BASE' /* 7aa: null-mode = BASE — writer compat không stamp mode; NULL nghĩa là phiếu thường, không phải ADJUSTMENT_ONLY */
      AND ie.counts_in_business_result = true
      AND ie.approval_status <> 'CANCELLED'
  ),
  pnl_item AS (
    SELECT it.income_expense_id AS voucher_id,
           it.amount            AS amount,
           it.start_date        AS start_date,
           it.end_date          AS end_date
    FROM public.income_expense_items it
    WHERE COALESCE(it.accounting_class, 'PNL') = 'PNL'
  ),
  alloc AS (
    -- A: invoice-linked -> whole PNL item amount into billing month.
    SELECT v.voucher_id, date_trunc('month', v.inv_month)::date AS m, it.amount AS amt
    FROM base_v v
    JOIN pnl_item it ON it.voucher_id = v.voucher_id
    WHERE v.inv_month IS NOT NULL
    UNION ALL
    -- B1: item with a valid period -> progressive-rounding monthly split.
    SELECT v.voucher_id,
           (date_trunc('month', it.start_date) + (gs.i || ' month')::interval)::date AS m,
           (round(it.amount * (gs.i + 1) / n.n) - round(it.amount * gs.i / n.n))::numeric AS amt
    FROM base_v v
    JOIN pnl_item it ON it.voucher_id = v.voucher_id
    CROSS JOIN LATERAL (
      SELECT GREATEST(
        (extract(year FROM it.end_date)::int * 12 + extract(month FROM it.end_date)::int)
      - (extract(year FROM it.start_date)::int * 12 + extract(month FROM it.start_date)::int) + 1,
        1) AS n
    ) n
    CROSS JOIN LATERAL generate_series(0, n.n - 1) AS gs(i)
    WHERE v.inv_month IS NULL
      AND it.start_date IS NOT NULL AND it.end_date IS NOT NULL
      AND it.end_date >= it.start_date
    UNION ALL
    -- B1b: dirty period (end < start) -> gather into start month.
    SELECT v.voucher_id, date_trunc('month', it.start_date)::date AS m, it.amount AS amt
    FROM base_v v
    JOIN pnl_item it ON it.voucher_id = v.voucher_id
    WHERE v.inv_month IS NULL
      AND it.start_date IS NOT NULL AND it.end_date IS NOT NULL
      AND it.end_date < it.start_date
    UNION ALL
    -- B2: item without a period -> whole amount into voucher_date month.
    SELECT v.voucher_id, date_trunc('month', v.vdate)::date AS m, it.amount AS amt
    FROM base_v v
    JOIN pnl_item it ON it.voucher_id = v.voucher_id
    WHERE v.inv_month IS NULL
      AND (it.start_date IS NULL OR it.end_date IS NULL)
  ),
  base_contrib AS (
    SELECT v.org_id, a.m AS tperiod, v.voucher_id, v.vtype,
           v.appr, v.rev, v.appr_ver, v.src_hash,
           SUM(CASE WHEN v.vtype = 'EXPENSE' THEN -a.amt ELSE a.amt END)::numeric AS signed_kqkd
    FROM alloc a
    JOIN base_v v ON v.voucher_id = a.voucher_id
    GROUP BY v.org_id, a.m, v.voucher_id, v.vtype, v.appr, v.rev, v.appr_ver, v.src_hash
  )
  SELECT
    bc.org_id                              AS organization_id,
    bc.tperiod                             AS target_period,
    'BASE_ALLOCATION'::text                AS contribution_kind,
    bc.voucher_id                          AS contribution_id,
    bc.voucher_id                          AS source_voucher_id,
    bc.appr                                AS source_approval_status,
    bc.rev                                 AS source_review_state,
    bc.appr_ver                            AS source_version,
    bc.signed_kqkd                         AS signed_kqkd_amount,
    jsonb_build_object(
      'kind', 'BASE_ALLOCATION',
      'voucher_id', bc.voucher_id,
      'voucher_type', bc.vtype,
      'target_period', bc.tperiod,
      'signed_kqkd_amount', bc.signed_kqkd
    )                                      AS allocation_snapshot,
    bc.src_hash                            AS source_payload_hash
  FROM base_contrib bc
  WHERE (p_period IS NULL OR bc.tperiod = date_trunc('month', p_period)::date)

  UNION ALL

  SELECT
    adj.organization_id                            AS organization_id,
    date_trunc('month', adj.adjustment_period)::date AS target_period,
    'RECOGNITION_ADJUSTMENT'::text                 AS contribution_kind,
    adj.id                                         AS contribution_id,
    adj.voucher_id                                 AS source_voucher_id,
    ie.approval_status                             AS source_approval_status,
    ie.review_state                                AS source_review_state,
    ie.approval_version                            AS source_version,
    adj.signed_amount                              AS signed_kqkd_amount,
    adj.allocation_snapshot                        AS allocation_snapshot,
    adj.source_payload_hash                        AS source_payload_hash
  FROM public.income_expense_recognition_adjustments adj
  JOIN public.income_expenses ie
    ON ie.id = adj.voucher_id AND ie.organization_id = adj.organization_id
  WHERE adj.organization_id = p_org
    AND (p_period IS NULL
         OR date_trunc('month', adj.adjustment_period)::date = date_trunc('month', p_period)::date);
$_$;








--
-- Name: FUNCTION effective_profit_contributions_v2(p_org uuid, p_period date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.effective_profit_contributions_v2(p_org uuid, p_period date) IS 'Plan §11.3: canonical resolver of effective KQKD contributions per target period. BASE_ALLOCATION (active BASE vouchers incl. pending UNAPPROVED, excl. CANCELLED; NOT gated on APPROVED/posting) + RECOGNITION_ADJUSTMENT (adjustment_period, carrying current voucher approval/review state). Single source for P&L/close/counter/blocker; owner-only.';








--
-- Name: emergency_approve_financial_v1(uuid, bigint, uuid, uuid, text, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.emergency_approve_financial_v1(p_request_id uuid, p_expected_version bigint, p_actor_membership uuid, p_actor_user uuid, p_reason text, p_reauth_fresh boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_req public.approval_requests;
  v_member public.organization_memberships;
  v_allowed boolean;
  v_posting uuid;
begin
  if not p_reauth_fresh then
    raise exception 're-authentication required' using errcode='42501';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 20 then
    raise exception 'emergency reason must be >= 20 chars' using errcode='22023';
  end if;

  select * into v_req from public.approval_requests
   where id = p_request_id for update;
  if not found then raise exception 'request not found' using errcode='P0002'; end if;
  if v_req.version <> p_expected_version then
    raise exception 'version conflict' using errcode='40001'; end if;
  if v_req.state <> 'PENDING_APPROVAL' then
    raise exception 'request not pending' using errcode='55000'; end if;

  -- actor must be an ACTIVE OWNER membership
  select * into v_member from public.organization_memberships
   where id = p_actor_membership and organization_id = v_req.organization_id
     and status = 'ACTIVE' and member_type = 'OWNER';
  if not found then
    raise exception 'emergency override requires active OWNER' using errcode='42501';
  end if;
  if v_member.user_id is distinct from p_actor_user then
    raise exception 'membership/user mismatch' using errcode='42501';
  end if;

  -- owner-is-maker cannot use emergency to bypass force-approval
  if p_actor_membership = v_req.maker_membership_id then
    raise exception 'maker cannot self-emergency-approve' using errcode='42501';
  end if;

  -- must hold approvals.emergency_override per the T2 resolver
  perform app_private.lock_org_for_decision_v1(v_req.organization_id);
  select allowed into v_allowed
    from app_private.authorize_tenant_action_v3(
      p_actor_user, v_req.organization_id, 'approvals.emergency_override',
      v_req.building_id, v_req.cashbook_id);
  if not coalesce(v_allowed, false) then
    raise exception 'actor lacks approvals.emergency_override' using errcode='42501';
  end if;

  -- BYPASS all open steps
  update public.approval_request_steps
     set status = 'BYPASSED'
   where request_id = p_request_id and status in ('WAITING','PENDING');

  insert into public.approval_decisions
    (organization_id, request_id, request_step_id, actor_membership_id,
     actor_user_id, decision, reason, request_version)
  select v_req.organization_id, p_request_id, s.id, p_actor_membership,
         p_actor_user, 'EMERGENCY_APPROVE', p_reason, v_req.version
    from public.approval_request_steps s
   where s.request_id = p_request_id
   order by s.step_no limit 1;

  insert into app_private.emergency_override_events
    (organization_id, request_id, actor_membership_id, actor_user_id, reason)
  values (v_req.organization_id, p_request_id, p_actor_membership, p_actor_user, p_reason);

  v_posting := app_private.post_financial_request_v1(
    p_request_id, v_req.version, p_actor_user);
  return v_posting;
end;
$$;








--
-- Name: end_accounting_chain_write_v1(); Type: FUNCTION; Schema: app_private; Owner: -
