--
-- Name: enforce_openclaw_evidence_retention_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_openclaw_evidence_retention_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  v_action text;
  v_hold_version bigint;
  v_inserted integer;
  v_sealed integer := 0;
begin
  for candidate in
    select due.* from (
      select policy.organization_id,policy.policy_version,'KNOWLEDGE'::text subject_kind,
        'openclaw_knowledge_versions'::text source_table,version.id subject_id,
        version.content_hash source_evidence_hash,
        version.archived_at+make_interval(secs=>policy.retain_for_seconds::integer) due_at
      from public.openclaw_retention_policies policy
      join public.openclaw_knowledge_versions version
        on version.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='KNOWLEDGE'
        and version.lifecycle_state='ARCHIVED' and version.archived_at is not null
        and version.archived_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and version.content is distinct from '[REDACTED_BY_RETENTION]'
      union all
      select policy.organization_id,policy.policy_version,'HEALTH',
        'openclaw_health_events',health.id,
        encode(extensions.digest(app_private.openclaw_jcs_bytes_v1(
          jsonb_build_object('fingerprint',health.fingerprint,'metrics',health.content_free_metrics)
        ),'sha256'),'hex'),
        health.observed_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_health_events health
        on health.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='HEALTH'
        and health.observed_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and health.content_free_metrics
          is distinct from jsonb_build_object('marker','REDACTED_BY_RETENTION')
      union all
      select policy.organization_id,policy.policy_version,'QR',
        'openclaw_qr_challenges',challenge.id,
        encode(extensions.digest(convert_to(
          challenge.auth_session_hash||':'||challenge.browser_nonce_hash,'UTF8'
        ),'sha256'),'hex'),
        challenge.issued_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_qr_challenges challenge
        on challenge.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='QR' and challenge.material_version=0
        and challenge.issued_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'AUDIT',
        'openclaw_audit_events',event.id,event.event_hash,
        event.occurred_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_audit_events event
        on event.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='AUDIT'
        and event.occurred_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and exists (
          select 1 from public.openclaw_audit_roots root
          where root.organization_id=event.organization_id and root.anchored_at is not null
            and event.organization_sequence between root.first_sequence and root.last_sequence
        )
      union all
      select policy.organization_id,policy.policy_version,'AUDIT',
        'openclaw_audit_roots',root.id,root.root_hash,
        root.created_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_audit_roots root
        on root.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='AUDIT' and root.anchored_at is not null
        and root.created_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'POLICY',
        'openclaw_policy_versions',version.id,version.payload_hash,
        version.archived_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_policy_versions version
        on version.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='POLICY'
        and version.lifecycle_state='ARCHIVED' and version.archived_at is not null
        and version.archived_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and version.policy_payload
          is distinct from jsonb_build_object('marker','REDACTED_BY_RETENTION')
      union all
      select policy.organization_id,policy.policy_version,'POLICY',
        'openclaw_automation_versions',version.id,
        coalesce(version.dry_run_hash,encode(extensions.digest(
          app_private.openclaw_jcs_bytes_v1(version.configuration),'sha256'),'hex')),
        version.archived_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_automation_versions version
        on version.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='POLICY'
        and version.lifecycle_state='ARCHIVED' and version.archived_at is not null
        and version.archived_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'CONTROL',
        'openclaw_control_states',control.id,
        encode(extensions.digest(app_private.openclaw_jcs_bytes_v1(jsonb_build_object(
          'controlVersion',control.control_version,'reason',control.reason
        )),'sha256'),'hex'),
        control.updated_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_control_states control
        on control.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='CONTROL'
        and not control.feature_enabled and not control.limited_auto_reply_enabled
        and not control.proactive_enabled and not control.sales_groups_enabled
        and not control.first_contact_enabled and control.reason is not null
        and control.updated_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'DELIVERY',
        'openclaw_delivery_attempts',attempt.id,attempt.delivery_evidence_hash,
        attempt.created_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_delivery_attempts attempt
        on attempt.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='DELIVERY'
        and attempt.created_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and attempt.delivery_evidence
          is distinct from jsonb_build_object('marker','REDACTED_BY_RETENTION')
      union all
      select policy.organization_id,policy.policy_version,'UNKNOWN',
        'openclaw_unknown_resolutions',resolution.id,
        resolution.authoritative_evidence_hash,
        resolution.resolved_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_unknown_resolutions resolution
        on resolution.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='UNKNOWN'
        and resolution.resolved_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'SECURITY',
        'openclaw_runtime_credentials',credential.id,credential.credential_hash,
        credential.revoked_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_runtime_credentials credential
        on credential.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='SECURITY'
        and credential.revoked_at is not null
        and credential.revoked_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'SECURITY',
        'openclaw_maintenance_credentials',credential.id,credential.credential_hash,
        credential.revoked_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_maintenance_credentials credential
        on credential.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='SECURITY'
        and credential.revoked_at is not null
        and credential.revoked_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'CONSENT',
        'openclaw_consents',consent.id,consent.evidence_hash,
        coalesce(consent.revoked_at,consent.expires_at)
          +make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_consents consent
        on consent.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='CONSENT'
        and coalesce(consent.revoked_at,consent.expires_at) is not null
        and coalesce(consent.revoked_at,consent.expires_at)<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'CONSENT',
        'openclaw_suppressions',suppression.id,suppression.evidence_hash,
        coalesce(suppression.released_at,suppression.expires_at)
          +make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_suppressions suppression
        on suppression.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='CONSENT'
        and coalesce(suppression.released_at,suppression.expires_at) is not null
        and coalesce(suppression.released_at,suppression.expires_at)<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
      union all
      select policy.organization_id,policy.policy_version,'RISK',
        'openclaw_inbound_automation_decisions',decision.id,decision.frozen_inputs_hash,
        decision.created_at+make_interval(secs=>policy.retain_for_seconds::integer)
      from public.openclaw_retention_policies policy
      join public.openclaw_inbound_automation_decisions decision
        on decision.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='RISK'
        and decision.created_at<=statement_timestamp()
          -make_interval(secs=>policy.retain_for_seconds::integer)
        and decision.frozen_inputs
          is distinct from jsonb_build_object('marker','REDACTED_BY_RETENTION')
    ) due
    where not exists (
      select 1 from public.openclaw_retention_evidence_seals seal
      where seal.organization_id=due.organization_id
        and seal.source_table=due.source_table and seal.subject_id=due.subject_id
        and seal.retention_version=due.policy_version
    )
    order by due.due_at,due.subject_id
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    perform app_private.openclaw_lock_retention_scope_v1(candidate.organization_id);
    if app_private.openclaw_retention_subject_held_v1(
      candidate.organization_id,candidate.subject_kind,candidate.subject_id
    ) then
      continue;
    end if;
    select coalesce(clock.hold_version,0) into v_hold_version
    from (select 1) singleton left join public.openclaw_retention_hold_clocks clock
      on clock.organization_id=candidate.organization_id;

    -- Lock the canonical source after the organization hold lock. SKIP LOCKED
    -- keeps concurrent minute runners non-blocking.
    case candidate.source_table
      when 'openclaw_knowledge_versions' then
        perform version.id from public.openclaw_knowledge_versions version
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_knowledge_versions version set
          content='[REDACTED_BY_RETENTION]',
          metadata=jsonb_build_object('marker','REDACTED_BY_RETENTION'),
          validation_result=null
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id
          and version.content is distinct from '[REDACTED_BY_RETENTION]';
        update public.openclaw_knowledge_chunks chunk set
          chunk_text='[REDACTED_BY_RETENTION]',embedding=null,
          metadata=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where chunk.organization_id=candidate.organization_id
          and chunk.knowledge_version_id=candidate.subject_id
          and chunk.chunk_text is distinct from '[REDACTED_BY_RETENTION]';
        v_action:='REDACTED';
      when 'openclaw_health_events' then
        perform health.id from public.openclaw_health_events health
        where health.organization_id=candidate.organization_id
          and health.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_health_events health
        set content_free_metrics=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where health.organization_id=candidate.organization_id
          and health.id=candidate.subject_id;
        v_action:='REDACTED';
      when 'openclaw_policy_versions' then
        perform version.id from public.openclaw_policy_versions version
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_policy_versions version set
          rate_limits=jsonb_build_object('marker','REDACTED_BY_RETENTION'),
          policy_payload=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id;
        v_action:='REDACTED';
      when 'openclaw_delivery_attempts' then
        perform attempt.id from public.openclaw_delivery_attempts attempt
        where attempt.organization_id=candidate.organization_id
          and attempt.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_delivery_attempts attempt
        set delivery_evidence=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where attempt.organization_id=candidate.organization_id
          and attempt.id=candidate.subject_id;
        v_action:='REDACTED';
      when 'openclaw_inbound_automation_decisions' then
        perform decision.id from public.openclaw_inbound_automation_decisions decision
        where decision.organization_id=candidate.organization_id
          and decision.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_inbound_automation_decisions decision
        set frozen_inputs=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where decision.organization_id=candidate.organization_id
          and decision.id=candidate.subject_id;
        v_action:='REDACTED';
      when 'openclaw_audit_events' then
        perform event.id from public.openclaw_audit_events event
        where event.organization_id=candidate.organization_id
          and event.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        v_action:='EXTERNAL_ANCHOR';
      when 'openclaw_audit_roots' then
        perform root.id from public.openclaw_audit_roots root
        where root.organization_id=candidate.organization_id
          and root.id=candidate.subject_id and root.anchored_at is not null
        for update skip locked;
        if not found then continue; end if;
        v_action:='EXTERNAL_ANCHOR';
      when 'openclaw_qr_challenges' then
        delete from public.openclaw_qr_challenges challenge
        where challenge.organization_id=candidate.organization_id
          and challenge.id=candidate.subject_id and challenge.material_version=0;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_automation_versions' then
        perform version.id from public.openclaw_automation_versions version
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        update public.openclaw_automation_versions version set
          template_body='[REDACTED_BY_RETENTION]',
          allowed_crm_fields='{}'::text[],
          configuration=jsonb_build_object('marker','REDACTED_BY_RETENTION')
        where version.organization_id=candidate.organization_id
          and version.id=candidate.subject_id;
        v_action:='REDACTED';
      when 'openclaw_control_states' then
        perform control.id from public.openclaw_control_states control
        where control.organization_id=candidate.organization_id
          and control.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_unknown_resolutions' then
        perform resolution.id from public.openclaw_unknown_resolutions resolution
        where resolution.organization_id=candidate.organization_id
          and resolution.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_runtime_credentials' then
        perform credential.id from public.openclaw_runtime_credentials credential
        where credential.organization_id=candidate.organization_id
          and credential.id=candidate.subject_id and credential.revoked_at is not null
        for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_maintenance_credentials' then
        perform credential.id from public.openclaw_maintenance_credentials credential
        where credential.organization_id=candidate.organization_id
          and credential.id=candidate.subject_id and credential.revoked_at is not null
        for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_consents' then
        perform consent.id from public.openclaw_consents consent
        where consent.organization_id=candidate.organization_id
          and consent.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      when 'openclaw_suppressions' then
        perform suppression.id from public.openclaw_suppressions suppression
        where suppression.organization_id=candidate.organization_id
          and suppression.id=candidate.subject_id for update skip locked;
        if not found then continue; end if;
        v_action:='HASH_ONLY';
      else
        raise exception 'deny unknown evidence retention source: %',candidate.source_table
          using errcode='55000';
    end case;

    insert into public.openclaw_retention_evidence_seals(
      organization_id,subject_kind,source_table,subject_id,retention_version,
      retention_action,source_evidence_hash,hold_version,due_at
    ) values (
      candidate.organization_id,candidate.subject_kind,candidate.source_table,
      candidate.subject_id,candidate.policy_version,v_action,
      candidate.source_evidence_hash,v_hold_version,candidate.due_at
    ) on conflict (organization_id,source_table,subject_id,retention_version) do nothing;
    get diagnostics v_inserted=row_count;
    v_sealed:=v_sealed+v_inserted;
  end loop;
  return v_sealed;
end;
$$;








--
-- Name: enqueue_deferred_customer_credit_v2(uuid, text, uuid, uuid, uuid, numeric, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enqueue_deferred_customer_credit_v2(p_org uuid, p_source_kind text, p_source_id uuid, p_customer_id uuid, p_invoice_id uuid, p_amount numeric, p_wrapper_idempotency_key text, p_detail jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'enqueue_deferred_customer_credit_v2: amount must be positive' USING ERRCODE = '22023';
  END IF;
  IF p_wrapper_idempotency_key IS NULL OR length(p_wrapper_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'enqueue_deferred_customer_credit_v2: wrapper idempotency key required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO app_private.deferred_customer_credit_queue (
    id, organization_id, source_kind, source_id, customer_id, invoice_id, amount,
    queue_state, wrapper_idempotency_key, detail
  ) VALUES (
    gen_random_uuid(), p_org, p_source_kind, p_source_id, p_customer_id, p_invoice_id, p_amount,
    'PENDING', p_wrapper_idempotency_key, COALESCE(p_detail, '{}'::jsonb)
  )
  ON CONFLICT (organization_id, source_kind, source_id, wrapper_idempotency_key) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT q.id INTO v_id FROM app_private.deferred_customer_credit_queue q
     WHERE q.organization_id = p_org AND q.source_kind = p_source_kind
       AND q.source_id = p_source_id AND q.wrapper_idempotency_key = p_wrapper_idempotency_key;
  END IF;
  RETURN v_id;
END
$$;








--
-- Name: FUNCTION enqueue_deferred_customer_credit_v2(p_org uuid, p_source_kind text, p_source_id uuid, p_customer_id uuid, p_invoice_id uuid, p_amount numeric, p_wrapper_idempotency_key text, p_detail jsonb); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.enqueue_deferred_customer_credit_v2(p_org uuid, p_source_kind text, p_source_id uuid, p_customer_id uuid, p_invoice_id uuid, p_amount numeric, p_wrapper_idempotency_key text, p_detail jsonb) IS 'Plan §8.1: durable remediation row for wrapper deferred=true credit; a PENDING row is NOT applied/refunded; separate resolver namespace.';








--
-- Name: ensure_cash_diff_type_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ensure_cash_diff_type_v1(p_org uuid, p_kind text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_id uuid;
  v_name text := CASE WHEN p_kind = 'income' THEN 'Thừa quỹ khi chốt sổ' ELSE 'Thiếu quỹ khi chốt sổ' END;
  v_user uuid;
BEGIN
  SELECT t.id INTO v_id FROM public.income_expense_types t
   WHERE t.organization_id = p_org AND lower(t.type) = p_kind
     AND lower(btrim(t.name)) = lower(v_name) LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  SELECT m.user_id INTO v_user FROM public.organization_memberships m
   WHERE m.organization_id = p_org AND m.status = 'ACTIVE' LIMIT 1;

  INSERT INTO public.income_expense_types
    (organization_id, user_id, name, type, description, is_default, is_deposit, hide_in_report)
  VALUES (p_org, v_user, v_name, p_kind,
          'Chênh lệch giữa tiền đếm được và sổ khi chốt & bàn giao quỹ', false, false, true)
  RETURNING id INTO v_id;
  RETURN v_id;
END
$$;








--
-- Name: ensure_income_expense_type_v1(uuid, uuid, text, text, text, text, boolean, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ensure_income_expense_type_v1(p_organization_id uuid, p_user_id uuid, p_name text, p_type text, p_category text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_is_default boolean DEFAULT false, p_is_deposit boolean DEFAULT false, p_is_restricted boolean DEFAULT false, p_hide_in_report boolean DEFAULT false, p_force_approval boolean DEFAULT false, p_system_only boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_type_id uuid;
  v_existing_deposit boolean;
  v_side text := lower(btrim(COALESCE(p_type, '')));
  v_normalized_name text := public.normalize_income_expense_type_name(p_name);
BEGIN
  IF p_organization_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'Organization and owner are required for an income/expense type'
      USING ERRCODE = '23502';
  END IF;
  IF v_side NOT IN ('income', 'expense') THEN
    RAISE EXCEPTION 'Invalid income/expense type side: %', p_type
      USING ERRCODE = '23514';
  END IF;
  IF v_normalized_name = '' THEN
    RAISE EXCEPTION 'Income/expense type name cannot be empty'
      USING ERRCODE = '23514';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text || ':' || v_side || ':' || v_normalized_name,
      0
    )
  );

  SELECT type_row.id, type_row.is_deposit
    INTO v_type_id, v_existing_deposit
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = p_organization_id
    AND lower(btrim(type_row.type)) = v_side
    AND public.normalize_income_expense_type_name(type_row.name) =
        v_normalized_name
  FOR UPDATE;

  IF v_type_id IS NOT NULL THEN
    IF v_existing_deposit IS DISTINCT FROM p_is_deposit THEN
      RAISE EXCEPTION 'Existing type % has incompatible is_deposit semantics',
        v_type_id USING ERRCODE = '23514';
    END IF;

    UPDATE public.income_expense_types type_row
    SET
      category = COALESCE(NULLIF(btrim(type_row.category), ''), p_category),
      description = COALESCE(NULLIF(btrim(type_row.description), ''), p_description),
      is_default = COALESCE(type_row.is_default, false) OR p_is_default,
      is_restricted = type_row.is_restricted OR p_is_restricted,
      hide_in_report = type_row.hide_in_report OR p_hide_in_report,
      force_approval = type_row.force_approval OR p_force_approval,
      system_only = type_row.system_only OR p_system_only,
      updated_at = clock_timestamp()
    WHERE type_row.id = v_type_id;

    RETURN v_type_id;
  END IF;

  INSERT INTO public.income_expense_types (
    user_id,
    organization_id,
    name,
    type,
    category,
    description,
    is_default,
    is_deposit,
    is_restricted,
    hide_in_report,
    force_approval,
    system_only
  ) VALUES (
    p_user_id,
    p_organization_id,
    btrim(p_name),
    v_side,
    NULLIF(btrim(p_category), ''),
    NULLIF(btrim(p_description), ''),
    p_is_default,
    p_is_deposit,
    p_is_restricted,
    p_hide_in_report,
    p_force_approval,
    p_system_only
  )
  RETURNING id INTO v_type_id;

  RETURN v_type_id;
END
$$;








--
-- Name: ensure_openclaw_retention_contract_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ensure_openclaw_retention_contract_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_inserted integer;
begin
  with contract(subject_kind,retain_for_seconds) as (
    values
      ('MESSAGE'::text,15552000::bigint),
      ('AI_DRAFT',15552000),
      ('MEDIA',7776000),
      ('KNOWLEDGE',31536000),
      ('HEALTH',7776000),
      ('QR',604800),
      ('AUDIT',31536000),
      ('POLICY',31536000),
      ('CONTROL',31536000),
      ('DELIVERY',31536000),
      ('UNKNOWN',31536000),
      ('SECURITY',31536000),
      ('CONSENT',31536000),
      ('RISK',31536000)
  ), missing as (
    select principal.organization_id,contract.subject_kind,contract.retain_for_seconds,
      coalesce((
        select max(history.policy_version)+1
        from public.openclaw_retention_policies history
        where history.organization_id=principal.organization_id
          and history.subject_kind=contract.subject_kind
      ),1) policy_version
    from public.openclaw_maintenance_principals principal
    cross join contract
    where principal.is_current and principal.revoked_at is null
      and not exists (
        select 1 from public.openclaw_retention_policies active
        where active.organization_id=principal.organization_id
          and active.subject_kind=contract.subject_kind and active.is_active
      )
  )
  insert into public.openclaw_retention_policies(
    organization_id,policy_version,subject_kind,retain_for_seconds,
    is_active,activated_at
  )
  select missing.organization_id,missing.policy_version,missing.subject_kind,
    missing.retain_for_seconds,true,statement_timestamp()
  from missing
  on conflict do nothing;
  get diagnostics v_inserted=row_count;
  return v_inserted;
end;
$$;








--
-- Name: evaluate_feature_route(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.evaluate_feature_route(p_feature_key text, p_organization_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  f app_private.server_feature_flags%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO f
    FROM app_private.server_feature_flags
   WHERE feature_key = p_feature_key;
  IF NOT FOUND THEN RETURN 'LEGACY'; END IF;
  IF f.force_freeze THEN RETURN 'FROZEN'; END IF;
  IF f.mode = 'OFF' THEN RETURN 'LEGACY'; END IF;
  IF f.mode = 'SHADOW' THEN RETURN 'SHADOW'; END IF;
  IF NULLIF(btrim(f.commit_sha), '') IS NULL
     OR NULLIF(btrim(f.migration_sha256), '') IS NULL
     OR NULLIF(btrim(f.maintenance_window_id), '') IS NULL
     OR NULLIF(btrim(f.approval_reference), '') IS NULL THEN
    RETURN 'FROZEN';
  END IF;
  IF f.mode = 'ON' THEN RETURN 'CANONICAL'; END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM app_private.server_feature_flag_canary_orgs c
     WHERE c.feature_key = p_feature_key
       AND c.organization_id = p_organization_id
  ) THEN RETURN 'LEGACY'; END IF;
  IF f.starts_at IS NULL
     OR f.ends_at IS NULL
     OR NOT isfinite(f.starts_at)
     OR NOT isfinite(f.ends_at)
     OR f.starts_at >= f.ends_at THEN
    RETURN 'FROZEN';
  END IF;
  IF v_now < f.starts_at THEN RETURN 'LEGACY'; END IF;
  IF v_now >= f.ends_at THEN RETURN 'FROZEN'; END IF;
  IF f.max_operation_count <= 0
     OR f.max_single_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')
     OR f.max_total_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')
     OR f.max_single_amount_vnd <= 0
     OR f.max_total_amount_vnd <= 0 THEN
    RETURN 'FROZEN';
  END IF;
  IF (
    SELECT count(*)
      FROM app_private.server_feature_flag_operations o
     WHERE o.feature_key = f.feature_key
       AND o.config_version = f.config_version
  ) >= f.max_operation_count THEN
    RETURN 'FROZEN';
  END IF;
  RETURN 'CANONICAL';
END;
$$;








--
-- Name: expire_openclaw_maintenance_leases_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.expire_openclaw_maintenance_leases_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  update public.openclaw_maintenance_leases lease set status='EXPIRED',released_at=statement_timestamp()
  where lease.status='ACTIVE' and lease.expires_at<=statement_timestamp();
  get diagnostics v_count=row_count;
  return v_count;
end;
$$;








--
-- Name: expire_openclaw_qr_challenges_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.expire_openclaw_qr_challenges_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  update public.openclaw_qr_challenges challenge set
    challenge_status='EXPIRED',active_slot=false,ciphertext=null,cipher_iv=null,auth_tag=null,
    material_version=0,material_published_at=null
  where challenge.challenge_status='PENDING' and challenge.expires_at<=statement_timestamp();
  get diagnostics v_count=row_count;
  return v_count;
end;
$$;








--
-- Name: expire_openclaw_runtime_leases_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.expire_openclaw_runtime_leases_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  update public.openclaw_runtime_leases lease set status='EXPIRED',released_at=statement_timestamp()
  where lease.status='ACTIVE' and lease.expires_at<=statement_timestamp();
  get diagnostics v_count=row_count;
  return v_count;
end;
$$;








--
-- Name: finance_v2_append_legacy_posting_v1(uuid, bigint, date, uuid, uuid, bigint); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_append_legacy_posting_v1(p_voucher uuid, p_generation bigint, p_posted_on date, p_membership uuid, p_user uuid, p_seq bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_ie public.income_expenses;
  v_id uuid := gen_random_uuid();
  v_idem text;
  v_existing uuid;
  v_signed numeric(18,2);
  v_net numeric(18,2);
BEGIN
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'finance_v2_append_legacy_posting_v1: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  IF v_ie.total_amount IS NULL OR v_ie.total_amount <= 0 THEN
    RAISE EXCEPTION 'finance_v2_append_legacy_posting_v1: voucher % total must be positive', p_voucher USING ERRCODE = '55000';
  END IF;

  v_idem := 'fin_v2_delta:posting:' || p_voucher::text || ':g' || p_generation::text;
  SELECT p.id INTO v_existing
  FROM public.income_expense_postings p
  WHERE p.organization_id = v_ie.organization_id AND p.idempotency_key = v_idem;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  v_signed := CASE WHEN v_ie.type = 'INCOME' THEN v_ie.total_amount ELSE -v_ie.total_amount END;
  v_net := v_signed
    + (CASE WHEN v_ie.change_account_id   IS NOT NULL AND COALESCE(v_ie.change_amount, 0)   <> 0 THEN v_ie.change_amount   ELSE 0 END)
    + (CASE WHEN v_ie.rounding_account_id IS NOT NULL AND COALESCE(v_ie.rounding_amount, 0) <> 0 THEN v_ie.rounding_amount ELSE 0 END);

  INSERT INTO public.income_expense_postings (
    id, organization_id, voucher_id, posting_subject_kind, posting_subject_id,
    direction, account_id, gross_amount, voucher_amount_snapshot, amount_basis,
    net_cash_effect, posted_on, posted_by_membership_id, posted_by_user_id,
    approval_request_id, approval_version, event_kind, idempotency_key, source_kind,
    posting_generation, evidence_waiver, legacy_provenance, created_at
  ) VALUES (
    v_id, v_ie.organization_id, v_ie.id, 'VOUCHER', v_ie.id,
    v_ie.type, v_ie.account_id, v_ie.total_amount, v_ie.total_amount, 'VOUCHER_TOTAL',
    v_net, p_posted_on, p_membership, p_user,
    v_ie.approval_request_id, COALESCE(v_ie.approval_version, 1), 'POSTING', v_idem, 'LEGACY_DELTA_REPLACEMENT',
    p_generation, 'PRE_V2_HISTORY',
    jsonb_build_object('delta', 'LEGACY_DELTA_REPLACEMENT', 'change_log_seq', p_seq,
                       'voucher_code', v_ie.code, 'generation', p_generation), now()
  )
  ON CONFLICT (organization_id, idempotency_key) DO NOTHING;

  SELECT p.id INTO v_id
  FROM public.income_expense_postings p
  WHERE p.organization_id = v_ie.organization_id AND p.idempotency_key = v_idem;

  -- MAIN (|signed| = gross by direction).
  IF NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines l WHERE l.posting_id = v_id AND l.line_kind = 'MAIN') THEN
    INSERT INTO public.income_expense_posting_lines (id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at)
    VALUES (gen_random_uuid(), v_ie.organization_id, v_id, v_ie.account_id, 'MAIN', v_signed, now());
  END IF;
  -- CHANGE (+change_amount on change_account_id) — legacy sign preserved.
  IF v_ie.change_account_id IS NOT NULL AND COALESCE(v_ie.change_amount, 0) <> 0
     AND NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines l WHERE l.posting_id = v_id AND l.line_kind = 'CHANGE') THEN
    INSERT INTO public.income_expense_posting_lines (id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at)
    VALUES (gen_random_uuid(), v_ie.organization_id, v_id, v_ie.change_account_id, 'CHANGE', v_ie.change_amount, now());
  END IF;
  -- ROUNDING (+rounding_amount on rounding_account_id) — legacy sign preserved.
  IF v_ie.rounding_account_id IS NOT NULL AND COALESCE(v_ie.rounding_amount, 0) <> 0
     AND NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines l WHERE l.posting_id = v_id AND l.line_kind = 'ROUNDING') THEN
    INSERT INTO public.income_expense_posting_lines (id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at)
    VALUES (gen_random_uuid(), v_ie.organization_id, v_id, v_ie.rounding_account_id, 'ROUNDING', v_ie.rounding_amount, now());
  END IF;

  RETURN v_id;
END
$$;








--
-- Name: FUNCTION finance_v2_append_legacy_posting_v1(p_voucher uuid, p_generation bigint, p_posted_on date, p_membership uuid, p_user uuid, p_seq bigint); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_append_legacy_posting_v1(p_voucher uuid, p_generation bigint, p_posted_on date, p_membership uuid, p_user uuid, p_seq bigint) IS 'Plan §6.2/§10.3: append a LEGACY_DELTA_REPLACEMENT POSTING generation + signed MAIN/CHANGE/ROUNDING lines from current legacy fields.';








--
-- Name: finance_v2_append_reversal_v1(uuid, date, uuid, uuid, text, bigint); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_append_reversal_v1(p_orig_id uuid, p_posted_on date, p_membership uuid, p_user uuid, p_reason text, p_seq bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_orig public.income_expense_postings;
  v_rev_id uuid := gen_random_uuid();
  v_idem text;
  v_existing uuid;
  v_line public.income_expense_posting_lines;
BEGIN
  SELECT * INTO v_orig FROM public.income_expense_postings p WHERE p.id = p_orig_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'finance_v2_append_reversal_v1: original posting % not found', p_orig_id USING ERRCODE = 'P0002';
  END IF;
  IF v_orig.event_kind <> 'POSTING' THEN
    RAISE EXCEPTION 'finance_v2_append_reversal_v1: % is not a POSTING event', p_orig_id USING ERRCODE = '55000';
  END IF;

  v_idem := 'fin_v2_delta:reversal:' || p_orig_id::text;

  -- Idempotent: if this original was already reversed by the delta worker, return that reversal.
  SELECT p.id INTO v_existing
  FROM public.income_expense_postings p
  WHERE p.organization_id = v_orig.organization_id AND p.idempotency_key = v_idem;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  INSERT INTO public.income_expense_postings (
    id, organization_id, voucher_id, posting_subject_kind, posting_subject_id,
    direction, account_id, gross_amount, voucher_amount_snapshot, amount_basis,
    net_cash_effect, posted_on, posted_by_membership_id, posted_by_user_id,
    approval_request_id, approval_version, event_kind, idempotency_key, source_kind,
    external_source_kind, external_source_id, external_source_line_id,
    posting_generation, reversal_of_id, reversal_reason, evidence_waiver, legacy_provenance, created_at
  ) VALUES (
    v_rev_id, v_orig.organization_id, v_orig.voucher_id, v_orig.posting_subject_kind, v_orig.posting_subject_id,
    v_orig.direction, v_orig.account_id, v_orig.gross_amount, v_orig.voucher_amount_snapshot, v_orig.amount_basis,
    -v_orig.net_cash_effect, p_posted_on, p_membership, p_user,
    v_orig.approval_request_id, v_orig.approval_version, 'REVERSAL', v_idem, 'LEGACY_DELTA_REPLACEMENT',
    v_orig.external_source_kind, v_orig.external_source_id, v_orig.external_source_line_id,
    v_orig.posting_generation, v_orig.id, p_reason, 'PRE_V2_HISTORY',
    jsonb_build_object('delta_reversal_of', p_orig_id, 'change_log_seq', p_seq), now()
  )
  ON CONFLICT (organization_id, idempotency_key) DO NOTHING;

  SELECT p.id INTO v_existing
  FROM public.income_expense_postings p
  WHERE p.organization_id = v_orig.organization_id AND p.idempotency_key = v_idem;
  v_rev_id := v_existing;

  -- Opposing signed lines for every line of the original (append-only; only if not already present).
  IF NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines l WHERE l.posting_id = v_rev_id) THEN
    FOR v_line IN SELECT * FROM public.income_expense_posting_lines l WHERE l.posting_id = v_orig.id LOOP
      INSERT INTO public.income_expense_posting_lines (
        id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at
      ) VALUES (
        gen_random_uuid(), v_line.organization_id, v_rev_id, v_line.account_id, 'REVERSAL', -v_line.signed_amount, now()
      );
    END LOOP;
  END IF;

  RETURN v_rev_id;
END
$$;








--
-- Name: FUNCTION finance_v2_append_reversal_v1(p_orig_id uuid, p_posted_on date, p_membership uuid, p_user uuid, p_reason text, p_seq bigint); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_append_reversal_v1(p_orig_id uuid, p_posted_on date, p_membership uuid, p_user uuid, p_reason text, p_seq bigint) IS 'Plan §6.2/§10.3: append (idempotently) a REVERSAL event + opposing lines for a POSTING; one per original.';








--
-- Name: finance_v2_apply_voucher_delete_v1(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_apply_voucher_delete_v1(p_run_id uuid, p_org uuid, p_voucher uuid, p_seq bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_ie public.income_expenses;
  v_active public.income_expense_postings;
  v_has_active boolean := false;
  v_mid uuid; v_uid uuid;
  v_posted_on date;
  v_rev_id uuid;
  v_new_post bigint;
BEGIN
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;

  -- Row is truly gone (hard DELETE captured by OLD). Never cascade a delete over a live posting.
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1 FROM public.income_expense_postings p
      WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher
        AND p.event_kind = 'POSTING'
        AND NOT EXISTS (SELECT 1 FROM public.income_expense_postings r WHERE r.reversal_of_id = p.id)
    ) THEN
      INSERT INTO app_private.income_expense_v2_backfill_exceptions (organization_id, voucher_id, reason_code, detail)
      VALUES (COALESCE(p_org, '00000000-0000-0000-0000-000000000000'::uuid), p_voucher, 'HARD_DELETE_WITH_CASH_EFFECT',
              jsonb_build_object('change_log_seq', p_seq, 'note', 'row hard-deleted while a live POSTING references it'))
      ON CONFLICT DO NOTHING;
      RETURN 'EXCEPTION';
    END IF;
    RETURN 'TOMBSTONE_ONLY';  -- deleted row that never posted: nothing to reverse.
  END IF;

  -- Row still exists (compatibility soft-delete / guard-protected). Find the live posting.
  SELECT * INTO v_active
  FROM public.income_expense_postings p
  WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = v_ie.id
    AND p.event_kind = 'POSTING'
    AND NOT EXISTS (SELECT 1 FROM public.income_expense_postings r WHERE r.reversal_of_id = p.id)
  ORDER BY p.posting_generation DESC
  LIMIT 1
  FOR UPDATE;
  v_has_active := FOUND;

  IF NOT v_has_active THEN
    -- No cash effect: pure tombstone. Set deleted_at (compatibility delete guard) idempotently.
    IF v_ie.deleted_at IS NULL THEN
      UPDATE public.income_expenses ie
         SET deleted_at = now(),
             posting_status = CASE WHEN v_ie.posting_mode = 'NON_CASH' THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END,
             updated_at = now()
       WHERE ie.id = v_ie.id;
    END IF;
    RETURN 'TOMBSTONE_ONLY';
  END IF;

  -- Adapter-owned live posting: let the owning adapter reverse it — never here.
  IF v_active.amount_basis <> 'VOUCHER_TOTAL' THEN
    INSERT INTO app_private.income_expense_v2_backfill_exceptions (organization_id, voucher_id, reason_code, detail)
    VALUES (v_ie.organization_id, v_ie.id, 'DELTA_OWNED_DELETE',
            jsonb_build_object('change_log_seq', p_seq, 'amount_basis', v_active.amount_basis,
                               'active_posting_id', v_active.id))
    ON CONFLICT DO NOTHING;
    RETURN 'EXCEPTION';
  END IF;

  -- Reverse in an open period; leave unapplied if the original account's period is locked.
  v_posted_on := v_ie.voucher_date;
  IF NOT app_private.finance_v2_is_cashbook_period_open(v_ie.organization_id, v_active.account_id, v_posted_on) THEN
    INSERT INTO app_private.income_expense_v2_backfill_exceptions (organization_id, voucher_id, reason_code, detail)
    VALUES (v_ie.organization_id, v_ie.id, 'DELTA_LOCKED_PERIOD',
            jsonb_build_object('change_log_seq', p_seq, 'posted_on', v_posted_on,
                               'cashbook_id', v_active.account_id, 'phase', 'delete_reverse'))
    ON CONFLICT DO NOTHING;
    RETURN 'EXCEPTION';
  END IF;

  SELECT om.user_id_out, om.membership_id_out INTO v_uid, v_mid
  FROM LATERAL (
    SELECT COALESCE(v_ie.approved_by, v_ie.user_id) AS user_id_out, m.id AS membership_id_out
    FROM public.organization_memberships m
    WHERE m.organization_id = v_ie.organization_id
      AND m.user_id = COALESCE(v_ie.approved_by, v_ie.user_id)
      AND m.status = 'ACTIVE'
    ORDER BY m.activated_at NULLS LAST, m.id
    LIMIT 1
  ) om;

  v_rev_id := app_private.finance_v2_append_reversal_v1(
    v_active.id, v_posted_on, COALESCE(v_mid, v_active.posted_by_membership_id),
    COALESCE(v_uid, v_active.posted_by_user_id), 'LEGACY delta: compatibility delete (APPROVED + REVERSED)', p_seq);

  -- Compatibility delete: tombstone + REVERSED, approval_status stays APPROVED (§10.3). No CANCELLED.
  v_new_post := COALESCE(v_ie.posting_version, 1) + 1;
  UPDATE public.income_expenses ie
     SET deleted_at = COALESCE(v_ie.deleted_at, now()),
         active_posting_id_v2 = NULL, posting_status = 'REVERSED',
         reversed_by_posting_id = v_rev_id, posting_version = v_new_post, updated_at = now()
   WHERE ie.id = v_ie.id;
  RETURN 'REVERSED_DELETED';
END
$$;








--
-- Name: FUNCTION finance_v2_apply_voucher_delete_v1(p_run_id uuid, p_org uuid, p_voucher uuid, p_seq bigint); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_apply_voucher_delete_v1(p_run_id uuid, p_org uuid, p_voucher uuid, p_seq bigint) IS 'Plan §10.3: DELETE contract — tombstone deleted_at + REVERSAL to APPROVED+REVERSED; hard-delete over a live posting -> exception (never cascade).';








--
-- Name: finance_v2_auto_posting_bridge(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_auto_posting_bridge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_acc public.accounts%ROWTYPE;
  v_active public.income_expense_postings%ROWTYPE;
  v_should boolean := false;
  v_poster uuid;
  v_membership uuid;
  v_gen bigint;
  v_new uuid;
  v_main numeric(18,2);
BEGIN
  -- Lifecycle V2 tự quản posting: approve-only giữ UNPOSTED, post RPC tự tạo event.
  IF EXISTS (SELECT 1 FROM app_private.ie_transition_authorization t
             WHERE t.income_expense_id = NEW.id AND t.xid = pg_current_xact_id()
               AND t.purpose = 'FINANCE_V2_LIFECYCLE') THEN
    RETURN NEW;
  END IF;
  -- Chỉ chạy khi posting route CANONICAL (trước đó legacy semantics giữ nguyên).
  IF app_private.evaluate_feature_route('income_expense.posting.v2', NEW.organization_id) <> 'CANONICAL' THEN
    RETURN NEW;
  END IF;

  -- V2 writer đã tự quản posting trong cùng lệnh (pointer đã set) → bridge không đụng.
  SELECT p.* INTO v_active FROM public.income_expense_postings p WHERE p.id = NEW.active_posting_id_v2;

  -- Voucher này CÓ NÊN có cash posting không (đúng công thức backfill/replay)?
  IF NEW.deleted_at IS NULL AND NEW.approval_status = 'APPROVED' AND NEW.account_id IS NOT NULL
     AND COALESCE(NEW.total_amount, 0) > 0 THEN
    SELECT * INTO v_acc FROM public.accounts WHERE id = NEW.account_id;
    IF FOUND AND COALESCE(v_acc.is_virtual, false) = false AND v_acc.deleted_at IS NULL THEN
      v_should := true;
    END IF;
  END IF;

  -- (a) Active posting nhưng không còn nên có (unapprove/cancel/delete/đổi sổ) → REVERSAL.
  IF v_active.id IS NOT NULL AND (NOT v_should OR v_active.account_id IS DISTINCT FROM NEW.account_id
      OR v_active.gross_amount IS DISTINCT FROM NEW.total_amount) THEN
    INSERT INTO public.income_expense_postings
      (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
       account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
       posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
       event_kind, idempotency_key, source_kind, posting_generation, reversal_of_id, reversal_reason)
    VALUES
      (v_active.organization_id, v_active.voucher_id, 'VOUCHER', v_active.posting_subject_id,
       v_active.direction, v_active.account_id, v_active.gross_amount,
       v_active.voucher_amount_snapshot, v_active.amount_basis, -v_active.net_cash_effect,
       public.org_today_v1(NULL), v_active.posted_by_membership_id, v_active.posted_by_user_id,
       COALESCE(NEW.approval_version, 1), 'REVERSAL',
       'bridge:rev:' || v_active.id::text, 'LEGACY_BRIDGE', v_active.posting_generation,
       v_active.id, 'auto-bridge: legacy writer changed cash projection')
    ON CONFLICT (organization_id, idempotency_key) DO NOTHING;
    INSERT INTO public.income_expense_posting_lines (organization_id, posting_id, account_id, line_kind, signed_amount)
    SELECT l.organization_id,
           (SELECT id FROM public.income_expense_postings
             WHERE organization_id = v_active.organization_id AND idempotency_key = 'bridge:rev:' || v_active.id::text),
           l.account_id, 'REVERSAL', -l.signed_amount
    FROM public.income_expense_posting_lines l
    WHERE l.posting_id = v_active.id
      AND NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines x
        WHERE x.posting_id = (SELECT id FROM public.income_expense_postings
          WHERE organization_id = v_active.organization_id AND idempotency_key = 'bridge:rev:' || v_active.id::text));
    NEW.active_posting_id_v2 := NULL;
    NEW.posting_status := CASE WHEN v_should THEN 'REVERSED' ELSE
      CASE WHEN NEW.approval_status = 'APPROVED' THEN 'REVERSED' ELSE 'UNPOSTED' END END;
    v_active := NULL;
  END IF;

  -- (b) Nên có mà chưa có → POSTING generation mới.
  IF TG_OP = 'UPDATE' AND v_should AND v_active.id IS NULL AND NEW.active_posting_id_v2 IS NULL THEN
    v_poster := COALESCE(NEW.approved_by, NEW.user_id, auth.uid());
    SELECT m.id INTO v_membership FROM public.organization_memberships m
    WHERE m.user_id = v_poster AND m.organization_id = NEW.organization_id AND m.status = 'ACTIVE' LIMIT 1;
    IF v_membership IS NULL THEN
      SELECT m.id, m.user_id INTO v_membership, v_poster FROM public.organization_memberships m
      WHERE m.user_id = auth.uid() AND m.organization_id = NEW.organization_id AND m.status = 'ACTIVE' LIMIT 1;
    END IF;
    IF v_membership IS NULL THEN
      -- Không chặn nghiệp vụ legacy: ghi exception, parity monitor sẽ bắt.
      INSERT INTO app_private.income_expense_v2_backfill_exceptions (organization_id, voucher_id, reason_code, detail)
      VALUES (NEW.organization_id, NEW.id, 'BRIDGE_UNRESOLVED_POSTER',
              jsonb_build_object('approved_by', NEW.approved_by, 'user_id', NEW.user_id));
      RETURN NEW;
    END IF;

    SELECT COALESCE(max(posting_generation), 0) + 1 INTO v_gen
    FROM public.income_expense_postings
    WHERE organization_id = NEW.organization_id AND posting_subject_kind = 'VOUCHER'
      AND posting_subject_id = NEW.id AND event_kind = 'POSTING';
    v_main := CASE WHEN NEW.type = 'INCOME' THEN NEW.total_amount ELSE -NEW.total_amount END;

    INSERT INTO public.income_expense_postings
      (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
       account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
       posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
       event_kind, idempotency_key, source_kind, posting_generation)
    VALUES
      (NEW.organization_id, NEW.id, 'VOUCHER', NEW.id, NEW.type, NEW.account_id,
       NEW.total_amount, NEW.total_amount, 'VOUCHER_TOTAL',
       v_main + COALESCE(NEW.change_amount, 0) + COALESCE(NEW.rounding_amount, 0),
       COALESCE(NEW.voucher_date, public.org_today_v1(NULL)), v_membership, v_poster,
       COALESCE(NEW.approval_version, 1), 'POSTING',
       'bridge:gen:' || NEW.id::text || ':' || v_gen::text, 'LEGACY_BRIDGE', v_gen)
    ON CONFLICT (organization_id, idempotency_key) DO NOTHING
    RETURNING id INTO v_new;
    IF v_new IS NULL THEN
      SELECT id INTO v_new FROM public.income_expense_postings
      WHERE organization_id = NEW.organization_id
        AND idempotency_key = 'bridge:gen:' || NEW.id::text || ':' || v_gen::text;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.income_expense_posting_lines WHERE posting_id = v_new) THEN
      INSERT INTO public.income_expense_posting_lines (organization_id, posting_id, account_id, line_kind, signed_amount)
      VALUES (NEW.organization_id, v_new, NEW.account_id, 'MAIN', v_main);
      IF COALESCE(NEW.change_amount, 0) <> 0 AND NEW.change_account_id IS NOT NULL THEN
        INSERT INTO public.income_expense_posting_lines (organization_id, posting_id, account_id, line_kind, signed_amount)
        VALUES (NEW.organization_id, v_new, NEW.change_account_id, 'CHANGE', NEW.change_amount);
      END IF;
      IF COALESCE(NEW.rounding_amount, 0) <> 0 AND NEW.rounding_account_id IS NOT NULL THEN
        INSERT INTO public.income_expense_posting_lines (organization_id, posting_id, account_id, line_kind, signed_amount)
        VALUES (NEW.organization_id, v_new, NEW.rounding_account_id, 'ROUNDING', NEW.rounding_amount);
      END IF;
    END IF;
    NEW.active_posting_id_v2 := v_new;
    NEW.posting_mode := COALESCE(NEW.posting_mode, 'CASHBOOK');
    NEW.posting_status := 'POSTED';
  END IF;

  RETURN NEW;
END
$$;








--
-- Name: finance_v2_auto_posting_bridge_insert(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_auto_posting_bridge_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_acc public.accounts%ROWTYPE;
  v_poster uuid;
  v_membership uuid;
  v_gen bigint;
  v_main numeric(18,2);
  v_new uuid;
BEGIN
  -- Lifecycle V2 tự quản posting trong cùng txn → không đụng.
  IF EXISTS (SELECT 1 FROM app_private.ie_transition_authorization t
             WHERE t.income_expense_id = NEW.id AND t.xid = pg_current_xact_id()
               AND t.purpose = 'FINANCE_V2_LIFECYCLE') THEN
    RETURN NULL;
  END IF;
  IF app_private.evaluate_feature_route('income_expense.posting.v2', NEW.organization_id) <> 'CANONICAL' THEN
    RETURN NULL;
  END IF;
  IF NEW.deleted_at IS NOT NULL OR NEW.approval_status <> 'APPROVED'
     OR NEW.account_id IS NULL OR COALESCE(NEW.total_amount, 0) <= 0
     OR NEW.active_posting_id_v2 IS NOT NULL THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_acc FROM public.accounts WHERE id = NEW.account_id;
  IF NOT FOUND OR COALESCE(v_acc.is_virtual, false) OR v_acc.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  v_poster := COALESCE(NEW.approved_by, NEW.user_id, auth.uid());
  SELECT m.id INTO v_membership FROM public.organization_memberships m
  WHERE m.user_id = v_poster AND m.organization_id = NEW.organization_id AND m.status = 'ACTIVE' LIMIT 1;
  IF v_membership IS NULL THEN
    SELECT m.id, m.user_id INTO v_membership, v_poster FROM public.organization_memberships m
    WHERE m.user_id = auth.uid() AND m.organization_id = NEW.organization_id AND m.status = 'ACTIVE' LIMIT 1;
  END IF;
  IF v_membership IS NULL THEN
    INSERT INTO app_private.income_expense_v2_backfill_exceptions (organization_id, voucher_id, reason_code, detail)
    VALUES (NEW.organization_id, NEW.id, 'BRIDGE_UNRESOLVED_POSTER',
            jsonb_build_object('approved_by', NEW.approved_by, 'user_id', NEW.user_id));
    RETURN NULL;
  END IF;

  SELECT COALESCE(max(posting_generation), 0) + 1 INTO v_gen
  FROM public.income_expense_postings
  WHERE organization_id = NEW.organization_id AND posting_subject_kind = 'VOUCHER'
    AND posting_subject_id = NEW.id AND event_kind = 'POSTING';
  v_main := CASE WHEN NEW.type = 'INCOME' THEN NEW.total_amount ELSE -NEW.total_amount END;

  INSERT INTO public.income_expense_postings
    (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
     account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
     posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
     event_kind, idempotency_key, source_kind, posting_generation)
  VALUES
    (NEW.organization_id, NEW.id, 'VOUCHER', NEW.id, NEW.type, NEW.account_id,
     NEW.total_amount, NEW.total_amount, 'VOUCHER_TOTAL',
     v_main + COALESCE(NEW.change_amount, 0) + COALESCE(NEW.rounding_amount, 0),
     COALESCE(NEW.voucher_date, public.org_today_v1(NULL)), v_membership, v_poster,
     COALESCE(NEW.approval_version, 1), 'POSTING',
     'bridge:gen:' || NEW.id::text || ':' || v_gen::text, 'LEGACY_BRIDGE', v_gen)
  ON CONFLICT (organization_id, idempotency_key) DO NOTHING
  RETURNING id INTO v_new;
  IF v_new IS NULL THEN
    RETURN NULL; -- idempotent replay
  END IF;
  INSERT INTO public.income_expense_posting_lines
    (organization_id, posting_id, account_id, line_kind, signed_amount)
  VALUES (NEW.organization_id, v_new, NEW.account_id, 'MAIN', v_main);
  IF COALESCE(NEW.change_amount, 0) <> 0 AND NEW.change_account_id IS NOT NULL THEN
    INSERT INTO public.income_expense_posting_lines
      (organization_id, posting_id, account_id, line_kind, signed_amount)
    VALUES (NEW.organization_id, v_new, NEW.change_account_id, 'CHANGE', NEW.change_amount);
  END IF;
  IF COALESCE(NEW.rounding_amount, 0) <> 0 AND NEW.rounding_account_id IS NOT NULL THEN
    INSERT INTO public.income_expense_posting_lines
      (organization_id, posting_id, account_id, line_kind, signed_amount)
    VALUES (NEW.organization_id, v_new, NEW.rounding_account_id, 'ROUNDING', NEW.rounding_amount);
  END IF;

  -- Token per-xid để (a) qua freeze-guard phiếu flow-owned, (b) a85 BEFORE
  -- UPDATE thấy token cùng xid → skip (không double-posting).
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (NEW.id, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE');

  UPDATE public.income_expenses
     SET active_posting_id_v2 = v_new, posting_status = 'POSTED',
         posting_id = v_new, posted_at_v2 = now(), updated_at = now()
   WHERE id = NEW.id;
  RETURN NULL;
END
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;







--
-- Name: canonical_write_operations; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.canonical_write_operations (
    organization_id uuid NOT NULL,
    operation text NOT NULL,
    subject_scope text NOT NULL,
    actor_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    payload_hash text NOT NULL,
    subject_id uuid,
    response_payload jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    actor_membership_id uuid,
    transaction_id xid8,
    expected_review_version bigint,
    expected_approval_version bigint,
    expected_posting_version bigint,
    resulting_review_version bigint,
    resulting_approval_version bigint,
    resulting_posting_version bigint,
    outcome_kind text,
    CONSTRAINT canonical_write_operations_completion_check CHECK ((((completed_at IS NULL) = (response_payload IS NULL)) AND ((completed_at IS NULL) = (subject_id IS NULL)))),
    CONSTRAINT canonical_write_operations_idempotency_key_check CHECK ((((char_length(idempotency_key) >= 8) AND (char_length(idempotency_key) <= 200)) AND (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'::text))),
    CONSTRAINT canonical_write_operations_payload_hash_check CHECK ((char_length(payload_hash) = 32))
);








--
-- Name: finance_v2_begin_canonical_op(uuid, text, text, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_begin_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_actor_membership uuid, p_idempotency_key text, p_payload_hash text, p_subject_id uuid) RETURNS app_private.canonical_write_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_op app_private.canonical_write_operations;
BEGIN
  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id, idempotency_key,
    payload_hash, subject_id, actor_membership_id, transaction_id
  ) VALUES (
    p_org, p_operation, p_subject_scope, p_actor, p_idempotency_key,
    p_payload_hash, NULL, p_actor_membership, pg_current_xact_id()
  )
  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
  DO NOTHING;

  SELECT * INTO v_op
  FROM app_private.canonical_write_operations o
  WHERE o.organization_id = p_org
    AND o.operation = p_operation
    AND o.subject_scope = p_subject_scope
    AND o.actor_id = p_actor
    AND o.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'finance_v2_begin_canonical_op: failed to reserve operation %', p_operation
      USING ERRCODE = 'P0002';
  END IF;

  IF v_op.payload_hash IS DISTINCT FROM p_payload_hash THEN
    RAISE EXCEPTION 'finance_v2_begin_canonical_op: idempotency key % reused with a different payload for %',
      p_idempotency_key, p_operation
      USING ERRCODE = '23505';
  END IF;

  -- Token per-transaction cho subject: (a) qua freeze guard trên phiếu canonical,
  -- (b) marker để cầu a85 KHÔNG lấn luồng V2.
  IF p_subject_id IS NOT NULL THEN
    INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
    VALUES (p_subject_id, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
    ON CONFLICT (income_expense_id) DO UPDATE
      SET xid = EXCLUDED.xid, purpose = EXCLUDED.purpose, granted_at = now();
  END IF;

  RETURN v_op;
END
$$;








--
-- Name: FUNCTION finance_v2_begin_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_actor_membership uuid, p_idempotency_key text, p_payload_hash text, p_subject_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_begin_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_actor_membership uuid, p_idempotency_key text, p_payload_hash text, p_subject_id uuid) IS 'Plan §6.1: reserve/lock the canonical idempotency row; conflict on same key/different payload.';








--
-- Name: finance_v2_birth_provenance_bridge(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_birth_provenance_bridge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_txid xid8;
  v_hash text;
BEGIN
  IF NEW.approval_status = 'UNAPPROVED' AND NEW.birth_operation_id IS NULL THEN
    IF NEW.id IS NULL THEN
      NEW.id := gen_random_uuid();
    END IF;
    -- 7w: writer cũ quên organization_id → suy từ toà/sổ.
    IF NEW.organization_id IS NULL AND NEW.building_id IS NOT NULL THEN
      SELECT b.organization_id INTO NEW.organization_id
      FROM public.buildings b WHERE b.id = NEW.building_id;
    END IF;
    IF NEW.organization_id IS NULL AND NEW.account_id IS NOT NULL THEN
      SELECT a.organization_id INTO NEW.organization_id
      FROM public.accounts a WHERE a.id = NEW.account_id;
    END IF;
    IF NEW.organization_id IS NULL THEN
      RAISE EXCEPTION 'Phiếu chờ duyệt thiếu organization (toà/sổ không xác định) — liên hệ quản trị'
        USING ERRCODE = '23502';
    END IF;
    SELECT b.birth_txid, b.payload_hash INTO v_txid, v_hash
    FROM app_private.finance_v2_register_birth_v1(
      NEW.organization_id, NEW.id, COALESCE(auth.uid(), NEW.user_id),
      'BIRTH_BRIDGE', NEW.source_payload_hash) b;
    NEW.birth_operation_id := NEW.id;
    NEW.birth_txid := v_txid;
    NEW.source_payload_hash := COALESCE(NEW.source_payload_hash, v_hash);
  END IF;
  RETURN NEW;
END
$$;








--
-- Name: finance_v2_bypass_monitor_v1(timestamp with time zone, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_bypass_monitor_v1(p_since timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(organization_id uuid, voucher_id uuid, updated_at timestamp with time zone, approval_status text, posting_mode text, posting_status text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT
    ie.organization_id,
    ie.id                AS voucher_id,
    ie.updated_at,
    ie.approval_status,
    ie.posting_mode,
    ie.posting_status,
    'RECENT_WRITE_NO_V2_EVENT'::text AS reason
  FROM public.income_expenses ie
  JOIN public.accounts a ON a.id = ie.account_id AND a.is_virtual = false
  WHERE ie.deleted_at IS NULL
    AND ie.updated_at >= p_since
    AND (p_org IS NULL OR ie.organization_id = p_org)
    -- No V2_WRITE semantic event was appended for this voucher (would prove a V2-pipeline write).
    AND NOT EXISTS (
      SELECT 1 FROM app_private.finance_v2_semantic_event_log e
      WHERE e.source_id = ie.id
        AND e.source_kind = 'V2_WRITE'
        AND e.created_at >= p_since
    )
    -- No posting event was created for this voucher inside the window (cash writes must post).
    AND NOT EXISTS (
      SELECT 1 FROM public.income_expense_postings p
      WHERE p.posting_subject_id = ie.id
        AND p.posting_subject_kind = 'VOUCHER'
        AND p.organization_id = ie.organization_id
        AND p.created_at >= p_since
    )
    -- Not attributable to the backfill change-capture bridge either.
    AND NOT EXISTS (
      SELECT 1 FROM app_private.finance_v2_backfill_change_log cl
      WHERE cl.source_table = 'public.income_expenses'
        AND cl.source_pk = ie.id
        AND cl.changed_at >= p_since
    )
  ORDER BY ie.updated_at DESC;
$$;








--
-- Name: FUNCTION finance_v2_bypass_monitor_v1(p_since timestamp with time zone, p_org uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_bypass_monitor_v1(p_since timestamp with time zone, p_org uuid) IS 'Plan §10.4: best-effort bypass-writer alerting — recent real-account income_expenses writes since p_since with no matching V2_WRITE semantic event, no posting event, and no backfill change-capture row. Heuristic (pass p_since = SHADOW cutover time to avoid flagging backfill header stamps). Owner-only; read-only.';








--
-- Name: finance_v2_can_read_posting_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_can_read_posting_v1(p_organization_id uuid, p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT app_private.finance_v2_route_pure_v1('income_expense.read_semantics.v2', p_organization_id)
           IN ('CANONICAL', 'FROZEN')
     AND EXISTS (
       SELECT 1
       FROM public.cashbook_possession_bindings b
       JOIN public.organization_memberships m ON m.id = b.membership_id
       WHERE b.organization_id = p_organization_id
         AND b.cashbook_id = p_account_id
         AND b.possession_kind = 'CUSTODIAN'
         AND b.valid_to IS NULL
         AND m.user_id = auth.uid()
         AND m.status = 'ACTIVE'
     );
$$;








--
-- Name: finance_v2_capture_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_capture_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row record;
  v_json jsonb;
  v_pk uuid;
  v_org uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;
  v_json := to_jsonb(v_row);

  BEGIN
    v_pk := (v_json ->> 'id')::uuid;
  EXCEPTION WHEN others THEN
    v_pk := NULL;
  END;
  BEGIN
    v_org := (v_json ->> 'organization_id')::uuid;
  EXCEPTION WHEN others THEN
    v_org := NULL;
  END;

  INSERT INTO app_private.finance_v2_backfill_change_log (
    organization_id, source_table, source_pk, operation,
    source_version_or_hash, txid, changed_at
  ) VALUES (
    v_org,
    TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
    v_pk,
    TG_OP,
    COALESCE(v_json ->> 'updated_at', v_json ->> 'content_hash'),
    pg_current_xact_id(),
    clock_timestamp()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION finance_v2_capture_change(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_capture_change() IS '§10.0 change-capture trigger fn; attach to source tables in Stage-4 (NOT attached here).';








--
-- Name: finance_v2_close_request_on_voucher_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_close_request_on_voucher_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_state text;
BEGIN
  IF NEW.approval_status = OLD.approval_status
     AND COALESCE(NEW.posting_status,'') = COALESCE(OLD.posting_status,'') THEN
    RETURN NEW;
  END IF;
  IF NEW.approval_status = 'UNAPPROVED' THEN
    RETURN NEW; -- quay về chờ duyệt (huỷ duyệt) — request do engine quản.
  END IF;

  v_state := CASE
    WHEN NEW.approval_status = 'CANCELLED' THEN 'CANCELLED'
    WHEN NEW.posting_status = 'POSTED' THEN 'POSTED'
    ELSE 'APPROVED'
  END;

  UPDATE public.approval_requests ar
     SET state = v_state,
         outcome_kind = COALESCE(ar.outcome_kind, 'V2_LIFECYCLE_SYNC'),
         posted_at = CASE WHEN v_state = 'POSTED' THEN now() ELSE ar.posted_at END,
         closed_at = now(),
         version = ar.version + 1
   WHERE ar.subject_type = 'FINANCIAL_VOUCHER'
     AND ar.subject_id = NEW.id
     AND ar.state = 'PENDING_APPROVAL';

  RETURN NEW;
END
$$;








--
-- Name: finance_v2_cutover_readiness_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_cutover_readiness_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_ie_exc        bigint := 0;
  v_cb_exc        bigint := 0;
  v_shared        bigint := 0;
  v_cand_pending  bigint := 0;
  v_cand_ambig    bigint := 0;
  v_cand_op_open  bigint := 0;
  v_open_operator bigint := 0;
  v_delta         bigint;
  v_delta_src     text;
  v_bal_parity    bigint;
  v_pnl_parity    bigint;
  v_parity_src    text;
  v_default       text;
  v_default_appr  boolean;
  v_notvalid      bigint := 0;
  v_failed        bigint := 0;
  v_routes        jsonb  := '{}'::jsonb;
  v_key           text;
  v_mode          text;
  v_freeze        boolean;
  v_route         text;
  v_p             jsonb;
  v_keys text[] := ARRAY[
    'income_expense.workflow.v2',
    'income_expense.posting.v2',
    'cashbook.access.v2',
    'income_expense.profit_close.v2',
    'income_expense.read_semantics.v2',
    'contract.commission.settlement.v2',
    'salary.settlement.v2'
  ];
  v_known text[] := ARRAY[
    'fk_ie_postings_replaces','fk_ie_postings_reversal_of','fk_ie_postings_voucher',
    'fk_ie_postings_account','fk_ie_postings_approval_request','fk_ie_posting_lines_account',
    'income_expense_posting_evidence_inherited_from_fkey','income_expense_posting_evidence_posting_fkey',
    'finance_execution_scopes_assigned_cashbook_fk','finance_execution_scopes_parent_voucher_fk',
    'income_expenses_active_posting_id_v2_fkey',
    'income_expense_recognition_adjustments_voucher_fkey','income_expense_recognition_adjustments_close_run_fkey',
    'salary_settlement_tranches_active_posting_fk',
    'profit_payout_reservations_consumed_posting_fk','profit_payout_reservations_reversed_posting_fk',
    'salary_settlement_bundles_parent_voucher_fk',
    'termination_move_out_authorizations_revenue_voucher_fk','termination_move_out_authorizations_offset_voucher_fk',
    'income_expenses_posting_status_v2_check','income_expenses_posting_mode_v2_check',
    'income_expenses_recognition_source_mode_v2_check'
  ];
  fn_gate CONSTANT text := 'gate';
BEGIN
  -- (1) Backfill exceptions must be zero (plan §6.5/§10.1/§10.2).
  IF to_regclass('app_private.income_expense_v2_backfill_exceptions') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM app_private.income_expense_v2_backfill_exceptions' INTO v_ie_exc;
  END IF;
  IF to_regclass('app_private.cashbook_access_v2_backfill_exceptions') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM app_private.cashbook_access_v2_backfill_exceptions' INTO v_cb_exc;
  END IF;

  -- (2) Legacy account_shared_users must be drained to zero (plan §3.2/§10.2).
  IF to_regclass('public.account_shared_users') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.account_shared_users' INTO v_shared;
  END IF;

  -- (3) Possession candidates still needing disposition; OPERATOR-proposed must be zero (§4.1).
  IF to_regclass('app_private.cashbook_possession_candidates') IS NOT NULL THEN
    EXECUTE $q$
      SELECT count(*) FILTER (WHERE status = 'PENDING_REVIEW'),
             count(*) FILTER (WHERE status = 'AMBIGUOUS'),
             count(*) FILTER (WHERE status IN ('PENDING_REVIEW','AMBIGUOUS') AND proposed_kind = 'OPERATOR')
      FROM app_private.cashbook_possession_candidates
    $q$ INTO v_cand_pending, v_cand_ambig, v_cand_op_open;
  END IF;

  -- (3b) Open OPERATOR possession bindings must be zero (target is CUSTODIAN/KNOWER only, §4.1).
  IF to_regclass('public.cashbook_possession_bindings') IS NOT NULL THEN
    EXECUTE $q$
      SELECT count(*) FROM public.cashbook_possession_bindings
      WHERE valid_to IS NULL AND possession_kind = 'OPERATOR'
    $q$ INTO v_open_operator;
  END IF;

  -- (4) Delta lag (Stage-8). Prefer a dedicated fn; else count unapplied change-log rows.
  IF to_regprocedure('app_private.finance_v2_delta_lag_v1()') IS NOT NULL THEN
    BEGIN
      EXECUTE 'SELECT app_private.finance_v2_delta_lag_v1()' INTO v_delta;
      v_delta_src := 'fn:finance_v2_delta_lag_v1';
    EXCEPTION WHEN OTHERS THEN
      v_delta := NULL; v_delta_src := NULL;
    END;
  ELSIF to_regclass('app_private.finance_v2_backfill_change_log') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM app_private.finance_v2_backfill_change_log WHERE applied_at IS NULL'
      INTO v_delta;
    v_delta_src := 'change_log_unapplied';
  ELSE
    v_delta := NULL; v_delta_src := NULL;
  END IF;

  -- (5) Balance / P&L parity (Stage-9 shadow reconcile). NULL until that stage lands.
  IF to_regprocedure('app_private.finance_v2_shadow_parity_summary_v1()') IS NOT NULL THEN
    BEGIN
      EXECUTE 'SELECT app_private.finance_v2_shadow_parity_summary_v1()' INTO v_p;
      v_bal_parity := NULLIF(v_p->>'balance_mismatch_count','')::bigint;
      v_pnl_parity := NULLIF(v_p->>'pnl_mismatch_count','')::bigint;
      v_parity_src := 'fn:finance_v2_shadow_parity_summary_v1';
    EXCEPTION WHEN OTHERS THEN
      v_bal_parity := NULL; v_pnl_parity := NULL; v_parity_src := NULL;
    END;
  END IF;

  -- (6) Inert constraints still NOT VALID / failed among the Stage-12 known set.
  SELECT count(*) INTO v_notvalid
  FROM pg_catalog.pg_constraint c
  WHERE c.conname = ANY (v_known) AND NOT c.convalidated;

  IF to_regclass('app_private.finance_v2_cutover_readiness_report') IS NOT NULL THEN
    EXECUTE $q$
      SELECT count(*) FROM (
        SELECT DISTINCT ON (constraint_name) constraint_name, outcome
        FROM app_private.finance_v2_cutover_readiness_report
        WHERE entry_kind = 'CONSTRAINT_VALIDATION'
        ORDER BY constraint_name, captured_at DESC
      ) latest
      WHERE outcome = 'VALIDATE_FAILED'
    $q$ INTO v_failed;
  END IF;

  -- (7) approval_status birth default — informational (flip is a separate post-drain step).
  SELECT column_default INTO v_default
  FROM information_schema.columns
  WHERE table_schema='public' AND table_name='income_expenses' AND column_name='approval_status';
  v_default_appr := (v_default IS NOT NULL
                     AND v_default LIKE '%APPROVED%'
                     AND v_default NOT LIKE '%UNAPPROVED%');

  -- (8) Feature routes of the 7 keys (global evaluation, NULL org -> global-effective route).
  FOREACH v_key IN ARRAY v_keys LOOP
    v_mode := NULL; v_freeze := NULL; v_route := NULL;
    IF to_regclass('app_private.server_feature_flags') IS NOT NULL THEN
      EXECUTE 'SELECT mode, force_freeze FROM app_private.server_feature_flags WHERE feature_key = $1'
        INTO v_mode, v_freeze USING v_key;
    END IF;
    IF to_regprocedure('app_private.evaluate_feature_route(text,uuid)') IS NOT NULL THEN
      BEGIN
        EXECUTE 'SELECT app_private.evaluate_feature_route($1, NULL::uuid)' INTO v_route USING v_key;
      EXCEPTION WHEN OTHERS THEN
        v_route := 'ERROR';
      END;
    END IF;
    v_routes := v_routes || jsonb_build_object(
      v_key, jsonb_build_object('mode', v_mode, 'force_freeze', v_freeze, 'global_route', v_route)
    );
  END LOOP;

  -- Assemble the assert-style readout with per-check gates.
  RETURN jsonb_build_object(
    'schema_version', 1,
    'generated_at', now(),
    'note', 'Assert-style readiness readout. Does NOT change any feature mode or enroll an org.',
    'checks', jsonb_build_object(
      'backfill_exceptions', jsonb_build_object(
        'income_expense', v_ie_exc, 'cashbook_access', v_cb_exc,
        'total', v_ie_exc + v_cb_exc,
        fn_gate, CASE WHEN (v_ie_exc + v_cb_exc) = 0 THEN 'PASS' ELSE 'FAIL' END),
      'account_shared_users_drain', jsonb_build_object(
        'remaining', v_shared,
        fn_gate, CASE WHEN v_shared = 0 THEN 'PASS' ELSE 'FAIL' END),
      'possession_candidates_unresolved', jsonb_build_object(
        'pending_review', v_cand_pending, 'ambiguous', v_cand_ambig,
        'operator_proposed_unresolved', v_cand_op_open,
        'total', v_cand_pending + v_cand_ambig,
        fn_gate, CASE WHEN (v_cand_pending + v_cand_ambig) = 0 THEN 'PASS' ELSE 'FAIL' END),
      'operator_bindings_open', jsonb_build_object(
        'count', v_open_operator,
        fn_gate, CASE WHEN v_open_operator = 0 THEN 'PASS' ELSE 'FAIL' END),
      'inert_constraints', jsonb_build_object(
        'known', cardinality(v_known),
        'not_valid_remaining', v_notvalid,
        'validate_failed_latest', v_failed,
        fn_gate, CASE WHEN v_notvalid = 0 THEN 'PASS' ELSE 'FAIL' END),
      'delta_lag', jsonb_build_object(
        'value', v_delta, 'source', v_delta_src,
        fn_gate, CASE WHEN v_delta IS NULL THEN 'UNVERIFIABLE'
                      WHEN v_delta = 0 THEN 'PASS' ELSE 'FAIL' END),
      'parity', jsonb_build_object(
        'balance_mismatch', v_bal_parity, 'pnl_mismatch', v_pnl_parity, 'source', v_parity_src,
        fn_gate, CASE WHEN v_bal_parity IS NULL OR v_pnl_parity IS NULL THEN 'UNVERIFIABLE'
                      WHEN v_bal_parity = 0 AND v_pnl_parity = 0 THEN 'PASS' ELSE 'FAIL' END),
      'approval_status_default', jsonb_build_object(
        'value', v_default, 'is_APPROVED', v_default_appr,
        'note', 'Expected APPROVED until the operator applies the commented post-drain flip; not a cutover gate.')
    ),
    'feature_routes', v_routes,
    'is_cutover_ready',
      (v_ie_exc + v_cb_exc) = 0
      AND v_shared = 0
      AND (v_cand_pending + v_cand_ambig) = 0
      AND v_open_operator = 0
      AND v_notvalid = 0
      AND v_delta IS NOT NULL AND v_delta = 0
      AND v_bal_parity IS NOT NULL AND v_bal_parity = 0
      AND v_pnl_parity IS NOT NULL AND v_pnl_parity = 0
  );
END
$_$;








--
-- Name: FUNCTION finance_v2_cutover_readiness_v1(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_cutover_readiness_v1() IS 'Plan §13.12: assert-style cutover-readiness readout (backfill exceptions, account_shared_users drain, unresolved/OPERATOR possession candidates, inert-constraint validation state, delta lag, balance/P&L parity, 7 feature-key routes, approval_status default). NEVER throws; returns the report. Owner-only; does not change a mode or enroll an org.';








