--
-- Name: finance_v2_finish_canonical_op(uuid, text, text, uuid, text, uuid, jsonb, text, bigint, bigint, bigint); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_finish_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_idempotency_key text, p_subject_id uuid, p_response jsonb, p_outcome text, p_review_version bigint, p_approval_version bigint, p_posting_version bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  UPDATE app_private.canonical_write_operations o
  SET subject_id = COALESCE(o.subject_id, p_subject_id),
      response_payload = p_response,
      completed_at = now(),
      outcome_kind = p_outcome,
      resulting_review_version = p_review_version,
      resulting_approval_version = p_approval_version,
      resulting_posting_version = p_posting_version
  WHERE o.organization_id = p_org
    AND o.operation = p_operation
    AND o.subject_scope = p_subject_scope
    AND o.actor_id = p_actor
    AND o.idempotency_key = p_idempotency_key;
END
$$;








