-- Name: FUNCTION finance_v2_finish_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_idempotency_key text, p_subject_id uuid, p_response jsonb, p_outcome text, p_review_version bigint, p_approval_version bigint, p_posting_version bigint); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_finish_canonical_op(p_org uuid, p_operation text, p_subject_scope text, p_actor uuid, p_idempotency_key text, p_subject_id uuid, p_response jsonb, p_outcome text, p_review_version bigint, p_approval_version bigint, p_posting_version bigint) IS 'Plan §6.1: complete a reserved canonical op with response + resulting versions + outcome.';








--
-- Name: finance_v2_has_covering_deny(uuid, uuid, uuid, text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_has_covering_deny(p_org uuid, p_membership uuid, p_cashbook uuid, p_keys text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  -- EMERGENCY_DENY: blanket (permission_key NULL) or any of the possession keys.
  IF EXISTS (
    SELECT 1 FROM app_private.tenant_emergency_denies d
    WHERE d.organization_id = p_org
      AND (d.permission_key IS NULL OR d.permission_key = ANY(p_keys))
      AND d.active_from <= now()
      AND (d.expires_at IS NULL OR d.expires_at > now())
  ) THEN
    RETURN true;
  END IF;

  -- Active member DENY covering ORGANIZATION or exact CASHBOOK.
  IF EXISTS (
    SELECT 1
    FROM public.member_permission_overrides o
    JOIN public.member_override_scopes mos
      ON mos.organization_id = o.organization_id AND mos.override_id = o.id
    JOIN public.authorization_scopes s
      ON s.organization_id = mos.organization_id AND s.id = mos.scope_id
    WHERE o.organization_id = p_org
      AND o.membership_id = p_membership
      AND o.permission_key = ANY(p_keys)
      AND o.effect = 'DENY'
      AND o.revoked_at IS NULL
      AND (o.expires_at IS NULL OR o.expires_at > now())
      AND (s.scope_type = 'ORGANIZATION'
           OR (s.scope_type = 'CASHBOOK' AND s.cashbook_id = p_cashbook))
  ) THEN
    RETURN true;
  END IF;

  -- Active role DENY covering ORGANIZATION or exact CASHBOOK.
  IF EXISTS (
    SELECT 1
    FROM public.role_bindings rb
    JOIN public.organization_roles r
      ON r.organization_id = rb.organization_id AND r.id = rb.role_id
     AND COALESCE(r.status, 'ACTIVE') = 'ACTIVE'
    JOIN public.role_permissions rp
      ON rp.organization_id = rb.organization_id
     AND rp.role_id = rb.role_id
     AND rp.permission_key = ANY(p_keys)
     AND rp.effect = 'DENY'
    JOIN public.role_binding_scopes rbs
      ON rbs.organization_id = rb.organization_id AND rbs.role_binding_id = rb.id
    JOIN public.authorization_scopes s
      ON s.organization_id = rbs.organization_id AND s.id = rbs.scope_id
    WHERE rb.organization_id = p_org
      AND rb.membership_id = p_membership
      AND COALESCE(rb.valid_from, '-infinity'::timestamptz) <= now()
      AND (rb.valid_to IS NULL OR rb.valid_to > now())
      AND (s.scope_type = 'ORGANIZATION'
           OR (s.scope_type = 'CASHBOOK' AND s.cashbook_id = p_cashbook))
  ) THEN
    RETURN true;
  END IF;

  RETURN false;
END
$$;








--
-- Name: FUNCTION finance_v2_has_covering_deny(p_org uuid, p_membership uuid, p_cashbook uuid, p_keys text[]); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_has_covering_deny(p_org uuid, p_membership uuid, p_cashbook uuid, p_keys text[]) IS 'Plan §6.4: covering EMERGENCY/member/role DENY (ORGANIZATION/CASHBOOK scope) for possession-money keys; deny wins over binding.';








--
-- Name: finance_v2_is_cashbook_period_open(uuid, uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_is_cashbook_period_open(p_org uuid, p_cashbook uuid, p_posted_on date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.accounts a
    WHERE a.id = p_cashbook
      AND a.organization_id = p_org
      AND a.deleted_at IS NULL
      AND (a.lock_date IS NULL OR p_posted_on > a.lock_date)
  );
$$;








--
-- Name: FUNCTION finance_v2_is_cashbook_period_open(p_org uuid, p_cashbook uuid, p_posted_on date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_is_cashbook_period_open(p_org uuid, p_cashbook uuid, p_posted_on date) IS 'Plan §7.3: cashbook period is open when posted_on post-dates accounts.lock_date.';








--
-- Name: finance_v2_is_recognition_period_open(uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_is_recognition_period_open(p_org uuid, p_period date) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_last text;
BEGIN
  IF p_period IS NULL THEN
    RETURN true;
  END IF;
  SELECT r.operation INTO v_last
  FROM public.profit_close_runs r
  WHERE r.organization_id = p_org
    AND r.period_month = date_trunc('month', p_period::timestamp)::date
  ORDER BY r.created_at DESC
  LIMIT 1;
  RETURN v_last IS NULL OR v_last NOT IN ('CLOSE','RECLOSE');
END
$$;








--
-- Name: FUNCTION finance_v2_is_recognition_period_open(p_org uuid, p_period date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_is_recognition_period_open(p_org uuid, p_period date) IS 'Plan §5.3: recognition period open unless the latest profit_close run for the month is CLOSE/RECLOSE.';








--
-- Name: finance_v2_log_event(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_log_event(p_org uuid, p_event_kind text, p_voucher uuid, p_actor uuid, p_trace text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  INSERT INTO app_private.finance_v2_semantic_event_log (
    organization_id, event_kind, source_table, source_id, source_kind,
    actor, txid, trace_id
  ) VALUES (
    p_org, p_event_kind, 'public.income_expenses', p_voucher, 'V2_WRITE',
    p_actor, pg_current_xact_id(), p_trace
  );
END
$$;








