--
-- Name: income_expenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.income_expenses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    code text,
    type text NOT NULL,
    name text NOT NULL,
    building_id uuid NOT NULL,
    room_id uuid,
    tenant_id uuid,
    voucher_date date NOT NULL,
    total_amount numeric(15,2) DEFAULT 0 NOT NULL,
    approval_status text DEFAULT 'APPROVED'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    payer_name text,
    account_id uuid,
    contract_id uuid,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    business_result_accounting boolean,
    receive_bank_name text,
    receive_bank_account text,
    creator_name text,
    invoice_id uuid,
    repeat_cycle text DEFAULT 'NONE'::text,
    repeat_infinity boolean DEFAULT false NOT NULL,
    repeat_count integer DEFAULT 0 NOT NULL,
    repeat_remaining integer DEFAULT 0 NOT NULL,
    repeat_next_date date,
    repeat_parent_id uuid,
    payment_id uuid,
    change_amount numeric(15,2) DEFAULT 0 NOT NULL,
    change_account_id uuid,
    rounding_amount numeric(15,2) DEFAULT 0,
    rounding_account_id uuid,
    verified_at timestamp with time zone,
    verified_by uuid,
    verified_by_name text,
    verified_note text,
    counts_in_business_result boolean DEFAULT true NOT NULL,
    shareholder_id uuid,
    handover_id uuid,
    has_restricted_item boolean DEFAULT false NOT NULL,
    handover_transfer_id uuid,
    salary_staff_id uuid,
    salary_role text,
    profit_manager_id uuid,
    collect_lat numeric,
    collect_lng numeric,
    collect_distance_m integer,
    collect_geofence_status text,
    kqkd_amount numeric(15,2) DEFAULT 0 NOT NULL,
    system_source text,
    utility_account_id uuid,
    commission_kind text,
    commission_legacy_dup boolean DEFAULT false NOT NULL,
    repeat_auto_approve boolean DEFAULT true NOT NULL,
    organization_id uuid NOT NULL,
    approval_request_id uuid,
    posting_id uuid,
    posted_at_v2 timestamp with time zone,
    correlation_id uuid,
    idempotency_key text,
    reversed_by_posting_id uuid,
    source_payload_hash text,
    payment_collection_id uuid,
    reversal_of_income_expense_id uuid,
    posting_mode text,
    posting_status text,
    active_posting_id_v2 uuid,
    recognition_date date,
    recognition_source_mode text,
    review_state text,
    review_owner_membership_id uuid,
    review_reason text,
    review_deadline timestamp with time zone,
    change_field_mask jsonb,
    review_version bigint DEFAULT 1 NOT NULL,
    approval_version bigint DEFAULT 1 NOT NULL,
    posting_version bigint DEFAULT 1 NOT NULL,
    cancellation_kind text,
    maker_user_id uuid,
    maker_membership_id uuid,
    birth_operation_id uuid,
    birth_txid xid8,
    CONSTRAINT ie_unapproved_review_state_ck CHECK (((deleted_at IS NOT NULL) OR (approval_status IS DISTINCT FROM 'UNAPPROVED'::text) OR (review_state = ANY (ARRAY['PENDING'::text, 'CHANGES_REQUESTED'::text, 'DISPUTED'::text])))),
    CONSTRAINT income_expenses_approval_status_check CHECK ((approval_status = ANY (ARRAY['UNAPPROVED'::text, 'APPROVED'::text, 'CANCELLED'::text]))),
    CONSTRAINT income_expenses_commission_kind_check CHECK ((commission_kind = ANY (ARRAY['broker'::text, 'sale'::text]))),
    CONSTRAINT income_expenses_name_not_empty CHECK ((char_length(name) > 0)),
    CONSTRAINT income_expenses_posting_mode_v2_check CHECK (((posting_mode IS NULL) OR (posting_mode = ANY (ARRAY['CASHBOOK'::text, 'NON_CASH'::text])))),
    CONSTRAINT income_expenses_posting_status_v2_check CHECK (((posting_status IS NULL) OR (posting_status = ANY (ARRAY['UNPOSTED'::text, 'POSTED'::text, 'REVERSED'::text, 'NOT_APPLICABLE'::text])))),
    CONSTRAINT income_expenses_recognition_source_mode_v2_check CHECK (((recognition_source_mode IS NULL) OR (recognition_source_mode = ANY (ARRAY['BASE'::text, 'ADJUSTMENT_ONLY'::text])))),
    CONSTRAINT income_expenses_repeat_cycle_check CHECK ((repeat_cycle = ANY (ARRAY['NONE'::text, 'WEEK'::text, 'MONTH'::text, 'QUARTER'::text, 'YEAR'::text]))),
    CONSTRAINT income_expenses_salary_role_check CHECK ((salary_role = ANY (ARRAY['ADVANCE'::text, 'CASH_COLLECTION'::text, 'COMMISSION'::text]))),
    CONSTRAINT income_expenses_total_amount_non_negative CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT income_expenses_type_check CHECK ((type = ANY (ARRAY['INCOME'::text, 'EXPENSE'::text])))
);








