--
-- Name: finance_v2_stamp_owned_posting_state(uuid, text, uuid, text, text, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_stamp_owned_posting_state(p_voucher uuid, p_posting_status text, p_active_posting_id uuid, p_review_state text, p_recognition_source_mode text, p_recognition_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher, pg_current_xact_id(), 'finance_v2.owned_posting_stamp')
  ON CONFLICT DO NOTHING;

  UPDATE public.income_expenses ie
     SET posting_status          = COALESCE(p_posting_status, ie.posting_status),
         active_posting_id_v2    = CASE WHEN p_posting_status = 'POSTED' THEN p_active_posting_id
                                        WHEN p_posting_status = 'REVERSED' THEN NULL
                                        ELSE ie.active_posting_id_v2 END,
         review_state            = COALESCE(p_review_state, ie.review_state),
         recognition_source_mode = COALESCE(p_recognition_source_mode, ie.recognition_source_mode),
         recognition_date        = COALESCE(p_recognition_date, ie.recognition_date),
         posting_version         = ie.posting_version + 1,
         updated_at              = now()
   WHERE ie.id = p_voucher;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  DELETE FROM app_private.ie_transition_authorization t
   WHERE t.income_expense_id = p_voucher AND t.xid = pg_current_xact_id();

  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'finance_v2_stamp_owned_posting_state: expected 1 row, affected % for voucher %', v_rows, p_voucher
      USING ERRCODE = '55000';
  END IF;
END
$$;








--
-- Name: FUNCTION finance_v2_stamp_owned_posting_state(p_voucher uuid, p_posting_status text, p_active_posting_id uuid, p_review_state text, p_recognition_source_mode text, p_recognition_date date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_stamp_owned_posting_state(p_voucher uuid, p_posting_status text, p_active_posting_id uuid, p_review_state text, p_recognition_source_mode text, p_recognition_date date) IS 'Plan §7.1: owning-adapter path to stamp a flow-owned voucher posting_status/active pointer using the per-xid ie_transition_authorization token.';








--
-- Name: finance_v2_transition_owned_approval(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_transition_owned_approval(p_voucher uuid, p_new_status text, p_posting_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  IF p_new_status NOT IN ('APPROVED','CANCELLED') THEN
    RAISE EXCEPTION 'finance_v2_transition_owned_approval: unsupported status %', p_new_status USING ERRCODE = '22023';
  END IF;
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher, pg_current_xact_id(), p_new_status)
  ON CONFLICT DO NOTHING;

  UPDATE public.income_expenses ie
     SET approval_status = p_new_status,
         approved_at     = CASE WHEN p_new_status = 'APPROVED' THEN now() ELSE ie.approved_at END,
         review_state    = 'RESOLVED',
         posting_status  = COALESCE(p_posting_status, ie.posting_status),
         approval_version = ie.approval_version + 1,
         updated_at      = now()
   WHERE ie.id = p_voucher;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  DELETE FROM app_private.ie_transition_authorization t
   WHERE t.income_expense_id = p_voucher AND t.xid = pg_current_xact_id();

  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'finance_v2_transition_owned_approval: expected 1 row, affected % for voucher %', v_rows, p_voucher
      USING ERRCODE = '55000';
  END IF;
END
$$;








--
-- Name: FUNCTION finance_v2_transition_owned_approval(p_voucher uuid, p_new_status text, p_posting_status text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.finance_v2_transition_owned_approval(p_voucher uuid, p_new_status text, p_posting_status text) IS 'Plan §7.1: owning-adapter path to approve/cancel a flow-owned system leg (no cash posting), token-guarded.';








--
-- Name: finance_v2_visible_vouchers(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finance_v2_visible_vouchers() RETURNS SETOF public.income_expenses
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  WITH me AS (
    SELECT m.id AS membership_id, m.organization_id
    FROM public.organization_memberships m
    WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE'
  ),
  custodian AS (
    SELECT b.organization_id, b.cashbook_id
    FROM public.cashbook_possession_bindings b
    JOIN me ON me.membership_id = b.membership_id
    WHERE b.possession_kind = 'CUSTODIAN' AND b.valid_to IS NULL
  ),
  knower AS (
    SELECT b.organization_id, b.cashbook_id
    FROM public.cashbook_possession_bindings b
    JOIN me ON me.membership_id = b.membership_id
    WHERE b.possession_kind = 'KNOWER' AND b.valid_to IS NULL
  )
  SELECT ie.*
  FROM public.income_expenses ie
  WHERE ie.deleted_at IS NULL
    AND (
      EXISTS (SELECT 1 FROM custodian c
              WHERE c.organization_id = ie.organization_id
                AND c.cashbook_id IN (ie.account_id, ie.change_account_id, ie.rounding_account_id))
      OR EXISTS (SELECT 1 FROM knower k
                 WHERE k.organization_id = ie.organization_id
                   AND ie.type = 'INCOME'
                   AND ie.maker_user_id = auth.uid()
                   AND ie.account_id = k.cashbook_id)
    );
$$;








--
-- Name: grant_ie_claim_capability_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.grant_ie_claim_capability_v1() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_nonce text := encode(pg_catalog.sha256(
    convert_to(pg_current_xact_id()::text || clock_timestamp()::text, 'UTF8')), 'hex');
begin
  -- local = true → reset at transaction end; cannot outlive the wrapper tx.
  perform set_config('app_private.ie_claim_capability', v_nonce, true);
  return v_nonce;
end;
$$;








--
-- Name: grant_openclaw_owner_permissions_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.grant_openclaw_owner_permissions_v1(p_organization_id uuid, p_role_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.organization_roles r
    where r.organization_id = p_organization_id
      and r.id = p_role_id
      and r.is_system IS TRUE
      and r.status = 'ACTIVE'
      and r.name = 'Chủ sở hữu tổ chức'
  ) then
    return;
  end if;

  insert into public.role_permissions
    (organization_id, role_id, permission_key, effect)
  select p_organization_id, p_role_id, d.key, 'ALLOW'
  from public.permission_definitions d
  where d.resource = 'openclaw_zalo'
    and d.is_active is true
  on conflict (organization_id, role_id, permission_key) do update
  set effect = 'ALLOW';
end
$$;








--
-- Name: guard_accounting_canary_enrollment_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_accounting_canary_enrollment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_mode text;
  v_force_freeze boolean;
BEGIN
  SELECT feature.mode, feature.force_freeze
    INTO v_mode, v_force_freeze
  FROM app_private.server_feature_flags feature
  WHERE feature.feature_key = NEW.feature_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Accounting feature is not configured'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_accounting_feature_rollout_v1(NEW.feature_key);

  IF v_mode = 'CANARY' AND NOT v_force_freeze THEN
    PERFORM app_private.assert_accounting_feature_activation_v1(
      NEW.feature_key, v_mode, NEW.organization_id
    );
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: guard_accounting_feature_activation_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_accounting_feature_activation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  -- UPDATE already owns the feature row lock; take the matching advisory lock
  -- next so enrollment uses the same row -> advisory order without deadlocks.
  PERFORM app_private.lock_accounting_feature_rollout_v1(NEW.feature_key);

  -- A freeze must always be installable. Clearing it re-runs every activation
  -- assertion because force_freeze is part of this trigger's UPDATE columns.
  IF NEW.force_freeze THEN
    RETURN NEW;
  END IF;

  IF NEW.mode IN ('CANARY', 'ON') THEN
    PERFORM app_private.assert_accounting_feature_activation_v1(
      NEW.feature_key, NEW.mode, NULL
    );
  END IF;
  RETURN NEW;
END;
$$;








