--
-- Name: guard_finance_invoice_component_immutability_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_invoice_component_immutability_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_finalized_at timestamptz;
  v_manifest_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'finance_invoice_component_allocations' THEN
    RAISE EXCEPTION 'Finance invoice component allocations are immutable'
      USING ERRCODE = '55000';
  END IF;

  IF TG_TABLE_NAME = 'finance_invoice_component_manifests' THEN
    IF OLD.finalized_at IS NOT NULL THEN
      RAISE EXCEPTION 'Finalized finance invoice component manifest is immutable'
        USING ERRCODE = '55000';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  v_manifest_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.manifest_id ELSE NEW.manifest_id END;
  SELECT manifest.finalized_at
    INTO v_finalized_at
  FROM public.finance_invoice_component_manifests manifest
  WHERE manifest.id = v_manifest_id;
  IF v_finalized_at IS NOT NULL THEN
    RAISE EXCEPTION 'Finalized finance invoice components are immutable'
      USING ERRCODE = '55000';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;








--
-- Name: guard_finance_month_snapshot_immutability_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_month_snapshot_immutability_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_status text;
  v_old_run_id uuid;
  v_new_run_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'finance_month_snapshot_runs' THEN
    IF TG_OP IN ('UPDATE', 'DELETE')
       AND OLD.status IN ('FINALIZED', 'MISSED') THEN
      RAISE EXCEPTION 'Finalized or missed finance snapshot is immutable'
        USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'UPDATE'
       AND (
         NEW.id IS DISTINCT FROM OLD.id
         OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
         OR NEW.snapshot_month IS DISTINCT FROM OLD.snapshot_month
       ) THEN
      RAISE EXCEPTION 'Finance snapshot identity is immutable'
        USING ERRCODE = '55000';
    END IF;

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  v_old_run_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.snapshot_run_id END;
  v_new_run_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.snapshot_run_id END;

  IF v_old_run_id IS NOT NULL THEN
    SELECT run.status
      INTO v_status
    FROM public.finance_month_snapshot_runs run
    WHERE run.id = v_old_run_id;
    IF v_status IN ('FINALIZED', 'MISSED') THEN
      RAISE EXCEPTION 'Finalized or missed finance snapshot detail is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF v_new_run_id IS NOT NULL THEN
    SELECT run.status
      INTO v_status
    FROM public.finance_month_snapshot_runs run
    WHERE run.id = v_new_run_id;
    IF v_status IS DISTINCT FROM 'PROVISIONAL' THEN
      RAISE EXCEPTION 'Finance snapshot detail requires a provisional run'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;








--
-- Name: guard_finance_reporting_role_assignment_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_reporting_role_assignment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_side text;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      NEW.organization_id::text || ':' || NEW.income_expense_type_id::text,
      0
    )
  );

  SELECT upper(type_row.type)
    INTO v_side
  FROM public.income_expense_types type_row
  WHERE type_row.id = NEW.income_expense_type_id
    AND type_row.organization_id = NEW.organization_id
    AND NOT COALESCE(type_row.is_deposit, false);

  IF v_side IS NULL THEN
    RAISE EXCEPTION 'Finance reporting role requires a non-deposit type in the same organization'
      USING ERRCODE = '23514';
  END IF;

  IF (
    v_side = 'INCOME'
    AND NEW.finance_reporting_role NOT IN (
      'ROOM_RENT_REVENUE',
      'OTHER_OPERATING_REVENUE',
      'PASS_THROUGH_REVENUE',
      'OUTSIDE_BREAK_EVEN_MODEL'
    )
  ) OR (
    v_side = 'EXPENSE'
    AND NEW.finance_reporting_role NOT IN (
      'LANDLORD_RENT_FIXED',
      'OTHER_FIXED_COST',
      'ROOM_VARIABLE_COST',
      'OTHER_VARIABLE_COST',
      'PASS_THROUGH_EXPENSE',
      'OUTSIDE_BREAK_EVEN_MODEL'
    )
  ) OR v_side NOT IN ('INCOME', 'EXPENSE') THEN
    RAISE EXCEPTION 'Finance reporting role does not match income/expense side'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.finance_reporting_role_assignments assignment_row
    WHERE assignment_row.organization_id = NEW.organization_id
      AND assignment_row.income_expense_type_id = NEW.income_expense_type_id
      AND assignment_row.id <> NEW.id
      AND daterange(
        assignment_row.effective_from,
        COALESCE(assignment_row.effective_to, 'infinity'::date),
        '[]'
      ) && daterange(
        NEW.effective_from,
        COALESCE(NEW.effective_to, 'infinity'::date),
        '[]'
      )
  ) THEN
    RAISE EXCEPTION 'finance_reporting_role_assignments_no_overlap'
      USING ERRCODE = '23P01';
  END IF;

  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END;
$$;








--
-- Name: guard_finance_v2_canary_enrollment_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_v2_canary_enrollment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_mode text;
  v_force_freeze boolean;
BEGIN
  -- Pass-through for non-Finance keys (a10 accounting enrollment guard owns those).
  IF NEW.feature_key NOT IN (
    'income_expense.workflow.v2',
    'income_expense.posting.v2',
    'cashbook.access.v2',
    'income_expense.profit_close.v2',
    'income_expense.read_semantics.v2',
    'contract.commission.settlement.v2',
    'salary.settlement.v2'
  ) THEN
    RETURN NEW;
  END IF;

  SELECT feature.mode, feature.force_freeze
    INTO v_mode, v_force_freeze
  FROM app_private.server_feature_flags feature
  WHERE feature.feature_key = NEW.feature_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Finance V2 feature is not configured'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_finance_v2_feature_rollout_v1(NEW.feature_key);

  IF v_mode = 'CANARY' AND NOT v_force_freeze THEN
    PERFORM app_private.assert_finance_v2_canary_enrollment_v1(
      NEW.feature_key, NEW.organization_id
    );
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: guard_finance_v2_change_log_applied_stamp(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_v2_change_log_applied_stamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'finance_v2_backfill_change_log is append-only (no DELETE)'
      USING ERRCODE = '55000';
  END IF;

  -- The ONLY permitted UPDATE is a one-time applied-watermark stamp: every immutable column must be
  -- byte-for-byte unchanged, the row must not have been stamped yet, and the new stamp must be set.
  IF OLD.applied_at IS NOT NULL THEN
    RAISE EXCEPTION 'finance_v2_backfill_change_log row % already applied (immutable stamp)', OLD.sequence_id
      USING ERRCODE = '55000';
  END IF;
  IF NEW.sequence_id            IS DISTINCT FROM OLD.sequence_id
     OR NEW.organization_id     IS DISTINCT FROM OLD.organization_id
     OR NEW.source_table        IS DISTINCT FROM OLD.source_table
     OR NEW.source_pk           IS DISTINCT FROM OLD.source_pk
     OR NEW.operation           IS DISTINCT FROM OLD.operation
     OR NEW.source_version_or_hash IS DISTINCT FROM OLD.source_version_or_hash
     OR NEW.txid                IS DISTINCT FROM OLD.txid
     OR NEW.changed_at          IS DISTINCT FROM OLD.changed_at THEN
    RAISE EXCEPTION 'finance_v2_backfill_change_log immutable columns cannot be modified (row %)', OLD.sequence_id
      USING ERRCODE = '55000';
  END IF;
  IF NEW.applied_at IS NULL OR NEW.applied_run_id IS NULL THEN
    RAISE EXCEPTION 'finance_v2_backfill_change_log stamp requires applied_run_id + applied_at (row %)', OLD.sequence_id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;








--
-- Name: FUNCTION guard_finance_v2_change_log_applied_stamp(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.guard_finance_v2_change_log_applied_stamp() IS 'Plan §10.3: append-only change log stays immutable except a one-time applied_run_id/applied_at stamp.';








--
-- Name: guard_finance_v2_feature_activation_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_finance_v2_feature_activation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  -- Pass-through for non-Finance keys so the a10 accounting guard stays authoritative.
  IF NEW.feature_key NOT IN (
    'income_expense.workflow.v2',
    'income_expense.posting.v2',
    'cashbook.access.v2',
    'income_expense.profit_close.v2',
    'income_expense.read_semantics.v2',
    'contract.commission.settlement.v2',
    'salary.settlement.v2'
  ) THEN
    RETURN NEW;
  END IF;

  -- A freeze must always be installable.
  IF NEW.force_freeze THEN
    RETURN NEW;
  END IF;

  IF NEW.mode IN ('CANARY', 'ON') THEN
    PERFORM app_private.assert_finance_v2_feature_activation_v1(
      NEW.feature_key, NEW.mode, NULL
    );
  END IF;
  RETURN NEW;
END;
$$;








