--
-- Name: guard_invoice_credit_lifecycle_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_invoice_credit_lifecycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_lifecycle_change boolean;
BEGIN
  v_lifecycle_change := NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
    OR (NEW.status = 'CANCELLED' AND OLD.status IS DISTINCT FROM 'CANCELLED')
    OR (OLD.status = 'CANCELLED' AND NEW.status IS DISTINCT FROM 'CANCELLED');

  IF v_lifecycle_change AND EXISTS (
    SELECT 1
    FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = OLD.id
  ) AND NOT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) THEN
    RAISE EXCEPTION 'Invoice credit lifecycle changes are core-writer only'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: guard_last_owner(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_last_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_remaining int;
begin
  if old.member_type = 'OWNER' and old.status = 'ACTIVE' then
    select count(*) into v_remaining
      from public.organization_memberships m
     where m.organization_id = old.organization_id
       and m.member_type = 'OWNER' and m.status = 'ACTIVE' and m.id <> old.id;
    if tg_op = 'UPDATE' and new.member_type = 'OWNER' and new.status = 'ACTIVE'
       and (new.valid_to is null or new.valid_to > now()) then
      v_remaining := v_remaining + 1;
    end if;
    if v_remaining < 1
       and exists (select 1 from public.organizations o where o.id = old.organization_id and o.status = 'ACTIVE') then
      raise exception 'Không thể gỡ/tạm ngưng chủ sở hữu CUỐI CÙNG của tổ chức đang hoạt động'
        using errcode = '23514';
    end if;
  end if;
  return coalesce(new, old);
end;
$$;








--
-- Name: guard_openclaw_audit_root_mutation_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_openclaw_audit_root_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (to_jsonb(NEW) - array[
        'signature_hash','gateway_receipt','gateway_receipt_hash','anchored_at'
      ]::text[])
       is distinct from
     (to_jsonb(OLD) - array[
        'signature_hash','gateway_receipt','gateway_receipt_hash','anchored_at'
      ]::text[])
  then
    raise exception 'audit root identity cannot change' using errcode = '55000';
  end if;

  if OLD.anchored_at is not null and to_jsonb(NEW) is distinct from to_jsonb(OLD) then
    raise exception 'audit root can only be anchored once' using errcode = '55000';
  end if;

  if OLD.anchored_at is null and (
    NEW.signature_hash is distinct from OLD.signature_hash
    or NEW.gateway_receipt is distinct from OLD.gateway_receipt
    or NEW.gateway_receipt_hash is distinct from OLD.gateway_receipt_hash
    or NEW.anchored_at is distinct from OLD.anchored_at
  ) and (
    NEW.signature_hash is null or NEW.gateway_receipt is null
    or NEW.gateway_receipt_hash is null or NEW.anchored_at is null
  ) then
    raise exception 'audit root acknowledgement must be atomic' using errcode = '55000';
  end if;

  return NEW;
end
$$;








