--
-- Name: guard_openclaw_client_operation_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_openclaw_client_operation_v1() RETURNS trigger
    LANGUAGE plpgsql
