--
-- Name: guard_profit_payout_item_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_profit_payout_item_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_linked boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id IN (
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.income_expense_id END,
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.income_expense_id END
    )
    UNION ALL
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.system_source = 'profit.distribution'
      AND request_row.subject_id IN (
        CASE WHEN TG_OP <> 'INSERT' THEN OLD.income_expense_id END,
        CASE WHEN TG_OP <> 'DELETE' THEN NEW.income_expense_id END
      )
  ) INTO v_linked;
  IF v_linked THEN
    RAISE EXCEPTION 'Items of a linked profit payout are immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;








--
-- Name: guard_profit_payout_linked_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_profit_payout_linked_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_linked boolean;
  v_transition_authorized boolean;
  v_core_writer boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id = OLD.id
    UNION ALL
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = OLD.id
      AND request_row.system_source = 'profit.distribution'
  ) INTO v_linked;
  IF NOT v_linked THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Linked profit payout vouchers cannot be deleted'
      USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.ie_transition_authorization transition_row
    WHERE transition_row.income_expense_id = OLD.id
      AND transition_row.xid = pg_current_xact_id()
  ) INTO v_transition_authorized;
  IF NOT v_transition_authorized THEN
    RAISE EXCEPTION 'Linked profit payout payload is immutable outside approval transitions'
      USING ERRCODE = '55000';
  END IF;

  IF (
    to_jsonb(OLD) - ARRAY[
      'approval_status', 'posting_id', 'posted_at_v2',
      'reversed_by_posting_id', 'updated_at', 'approved_by', 'approved_at',
      'verified_at', 'verified_by', 'verified_by_name', 'verified_note'
    ]::text[]
  ) IS DISTINCT FROM (
    to_jsonb(NEW) - ARRAY[
      'approval_status', 'posting_id', 'posted_at_v2',
      'reversed_by_posting_id', 'updated_at', 'approved_by', 'approved_at',
      'verified_at', 'verified_by', 'verified_by_name', 'verified_note'
    ]::text[]
  ) THEN
    RAISE EXCEPTION 'Profit payout transition may only change lifecycle columns'
      USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;

  PERFORM app_private.assert_profit_payout_linkage_v2(
    OLD.id,
    v_core_writer,
    NEW.approval_status = 'APPROVED'
      AND OLD.approval_status IS DISTINCT FROM 'APPROVED'
  );
  RETURN NEW;
END
$$;








--
-- Name: guard_profit_payout_scope_compat_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_profit_payout_scope_compat_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_is_payout boolean := false;
BEGIN
  v_is_payout := NEW.shareholder_id IS NOT NULL
    OR NEW.profit_manager_id IS NOT NULL
    OR COALESCE(
      NEW.system_source IN ('profit.distribution', 'profit.manager_salary'),
      false
    );

  IF TG_OP = 'UPDATE' THEN
    v_is_payout := v_is_payout
      OR OLD.shareholder_id IS NOT NULL
      OR OLD.profit_manager_id IS NOT NULL
      OR COALESCE(
        OLD.system_source IN ('profit.distribution', 'profit.manager_salary'),
        false
      );
  END IF;

  v_is_payout := v_is_payout OR EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id = NEW.id
  ) OR EXISTS (
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = NEW.id
      AND request_row.system_source = 'profit.distribution'
  );

  IF NOT v_is_payout THEN
    RETURN NEW;
  END IF;
  IF NEW.shareholder_id IS NOT NULL AND NEW.profit_manager_id IS NOT NULL THEN
    RAISE EXCEPTION 'Profit payout cannot target both a shareholder and a manager'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.account_id IS NULL THEN
    RAISE EXCEPTION 'Profit payout requires a real cashbook account'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.accounts account_row
  WHERE account_row.id = NEW.account_id
    AND account_row.organization_id = NEW.organization_id
    AND account_row.deleted_at IS NULL
    AND NOT account_row.is_virtual
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profit payout account must be active, real and in the same organization'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.shareholder_id IS NOT NULL THEN
    PERFORM 1
    FROM public.shareholders shareholder_row
    WHERE shareholder_row.id = NEW.shareholder_id
      AND shareholder_row.organization_id = NEW.organization_id
      AND shareholder_row.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Profit payout shareholder must belong to the same organization'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.profit_manager_id IS NOT NULL THEN
    PERFORM 1
    FROM public.profit_managers manager_row
    WHERE manager_row.id = NEW.profit_manager_id
      AND manager_row.organization_id = NEW.organization_id
      AND manager_row.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Manager payout target must belong to the same organization'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'Profit payout cannot clear its shareholder/manager identity'
      USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id = NEW.id
      AND (
        reservation.organization_id IS DISTINCT FROM NEW.organization_id
        OR reservation.shareholder_id IS DISTINCT FROM NEW.shareholder_id
      )
  ) THEN
    RAISE EXCEPTION 'Historical payout no longer matches its reservation identity'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = NEW.id
      AND request_row.system_source = 'profit.distribution'
      AND (
        request_row.organization_id IS DISTINCT FROM NEW.organization_id
        OR request_row.cashbook_id IS DISTINCT FROM NEW.account_id
      )
  ) THEN
    RAISE EXCEPTION 'Historical payout no longer matches its approval request'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: guard_published_rule_set(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_published_rule_set() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_status text;
begin
  if tg_table_name = 'approval_rule_sets' then
    -- H6 fix: ALLOWLIST. Once published (ACTIVE/RETIRED), the ONLY legal changes
    -- are the retire transition (status ACTIVE→RETIRED + effective_to) driven by
    -- publish_rule_set_v1. Everything else — including resurrecting RETIRED→ACTIVE,
    -- moving effective_from, editing config — is rejected. We compare the whole
    -- row minus the retire-transition columns.
    if tg_op = 'UPDATE' and old.status in ('ACTIVE','RETIRED') then
      -- forbid resurrecting a RETIRED set to ACTIVE
      if old.status = 'RETIRED' and new.status <> 'RETIRED' then
        raise exception 'RETIRED rule set cannot be resurrected' using errcode='55000';
      end if;
      -- ACTIVE may only go to RETIRED; nothing else may change except the
      -- retire bookkeeping columns.
      if old.status = 'ACTIVE' and new.status not in ('ACTIVE','RETIRED') then
        raise exception 'published rule set status transition illegal' using errcode='55000';
      end if;
      if (to_jsonb(old) - array['status','effective_to'])
         is distinct from (to_jsonb(new) - array['status','effective_to']) then
        raise exception 'published rule set content is immutable' using errcode='55000';
      end if;
    end if;
    if tg_op = 'DELETE' and old.status in ('ACTIVE','RETIRED') then
      raise exception 'published rule set cannot be deleted' using errcode='55000';
    end if;
    return case when tg_op='DELETE' then old else new end;
  end if;

  -- approval_rules: frozen once their rule set is published
  select status into v_status from public.approval_rule_sets
   where id = coalesce(new.rule_set_id, old.rule_set_id);
  if v_status in ('ACTIVE','RETIRED') then
    raise exception 'rules of a published rule set are immutable' using errcode='55000';
  end if;
  return case when tg_op='DELETE' then old else new end;
end;
$$;








