--
-- Name: guard_system_role_identity(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_system_role_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'Không được xoá vai trò hệ thống "%" (system_key=%). '
                      'Vai trò này là cửa phân quyền của chủ sở hữu.',
                      OLD.name, OLD.system_key
        USING ERRCODE = 'P0001', HINT = 'SYSTEM_ROLE_IMMUTABLE';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.is_system AND NEW.system_key IS DISTINCT FROM OLD.system_key THEN
    RAISE EXCEPTION 'Không được đổi system_key của vai trò hệ thống "%" (% -> %).',
                    OLD.name, OLD.system_key, NEW.system_key
      USING ERRCODE = 'P0001', HINT = 'SYSTEM_ROLE_IMMUTABLE';
  END IF;

  IF OLD.is_system AND NEW.is_system = false THEN
    RAISE EXCEPTION 'Không được bỏ cờ is_system của vai trò "%" (system_key=%).',
                    OLD.name, OLD.system_key
      USING ERRCODE = 'P0001', HINT = 'SYSTEM_ROLE_IMMUTABLE';
  END IF;

  -- ĐỔI TÊN CŨNG CHẶN — và đây là chỗ bản nháp nói SAI (sửa 30/07 sau rà vòng 2).
  -- Bản nháp cho đổi tên với lý do "cửa phân quyền đã neo vào system_key ở trên
  -- nên đổi tên không còn làm sập quyền nữa". Câu đó KHÔNG ĐÚNG: neo lại chỉ mới
  -- làm cho app_private.is_org_owner_v1. Quét pg_proc trên prod 30/07 vẫn còn
  -- NĂM hàm khác tự so chuỗi tên vai trò, không đi qua helper:
  --     public._termination_ensure_type(uuid,text,text)        ← nằm trên đường TIỀN
  --                                                             (pay_utility_bill gọi)
  --     public.get_ie_auto_approve_threshold_v1()
  --     public.set_ie_auto_approve_threshold_v1(numeric)       ← ngưỡng tự duyệt (D3)
  --     public.set_ie_accounting_standard_v1(uuid,boolean,text)
  --     public.set_membership_status_v1(uuid,text,text)
  -- Đổi nhãn vai trò TENANT_OWNER là ÂM THẦM tước của chính chủ quyền đặt ngưỡng
  -- tự duyệt và quyền đổi trạng thái thành viên. Vì vậy: khoá luôn cái tên cho tới
  -- khi cả năm hàm đó được neo sang system_key (việc của slice sau, KHÔNG làm ở đây
  -- — mỗi hàm là một CREATE OR REPLACE trên hàm tiền/phân quyền đang chạy, phải đọc
  -- pg_get_functiondef từng cái rồi vá, không thuộc phạm vi Slice −1).
  --
  -- MẤT GÌ: chủ không đổi được NHÃN tiếng Việt của 2 vai trò hệ thống. Hôm nay
  -- đường đó vốn đã không tồn tại trong sản phẩm — `authenticated` chỉ có SELECT
  -- trên public.organization_roles, và writer duy nhất
  -- public.upsert_organization_role_v1 đã RAISE 'Vai trò hệ thống "%" không sửa
  -- được' với mọi dòng is_system. Nên trigger này chỉ bịt đường postgres/service_role
  -- (migration hoặc script) — đúng cái đường mà bản nháp để hở.
  IF OLD.is_system AND NEW.name IS DISTINCT FROM OLD.name THEN
    RAISE EXCEPTION 'Không được đổi tên vai trò hệ thống "%" (system_key=%) thành "%". '
                    'Vẫn còn hàm phân quyền so theo TÊN vai trò (vd set_ie_auto_approve_threshold_v1), '
                    'nên đổi nhãn là âm thầm tước quyền của chính chủ tổ chức.',
                    OLD.name, OLD.system_key, NEW.name
      USING ERRCODE = 'P0001', HINT = 'SYSTEM_ROLE_IMMUTABLE';
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION guard_system_role_identity(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.guard_system_role_identity() IS 'Slice −1 §−1.10: vai trò is_system không được xoá, không được đổi/bỏ system_key, và KHÔNG được đổi tên. Chặn cả tên vì ngoài is_org_owner_v1 (đã neo vào system_key) còn 5 hàm khác vẫn so theo chuỗi ''Chủ sở hữu tổ chức'' — trong đó có set_ie_auto_approve_threshold_v1 (ngưỡng tự duyệt) và _termination_ensure_type (đường tiền). Mở lại vế tên CHỈ SAU KHI cả 5 hàm đó neo sang system_key.';








--
-- Name: guard_tenant_role_permission_domain(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_tenant_role_permission_domain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1 from public.permission_definitions pd
     where pd.key = new.permission_key
       and pd.permission_domain = 'TENANT'
  ) then
    raise exception 'role_permissions: % is not a TENANT permission', new.permission_key
      using errcode = '23514';
  end if;
  return new;
end;
$$;








--
-- Name: guard_termination_forfeit_item_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_termination_forfeit_item_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_writer boolean;
  v_protected boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.income_expenses voucher
    WHERE voucher.id IN (
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.income_expense_id END,
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.income_expense_id END
    )
      AND voucher.system_source IN (
        'termination.forfeit_revenue', 'termination.forfeit_offset'
      )
  ) INTO v_protected;
  IF NOT v_protected THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_writer;
  IF NOT v_writer THEN
    RAISE EXCEPTION 'Hạng mục bỏ cọc chỉ được sửa bởi writer thanh lý'
      USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;








--
-- Name: guard_termination_forfeit_voucher_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_termination_forfeit_voucher_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_protected boolean;
  v_writer boolean;
  v_status_only boolean;
  v_transition_authorized boolean;
BEGIN
  v_protected := COALESCE(NEW.system_source, '') IN (
    'termination.forfeit_revenue', 'termination.forfeit_offset'
  ) OR (
    TG_OP = 'UPDATE'
    AND COALESCE(OLD.system_source, '') IN (
      'termination.forfeit_revenue', 'termination.forfeit_offset'
    )
  );
  IF NOT v_protected THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.approval_status = 'CANCELLED'
     AND NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    RAISE EXCEPTION 'Cancelled forfeit vouchers are terminal'
      USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_writer;
  IF NOT v_writer THEN
    RAISE EXCEPTION 'Bút toán bỏ cọc chỉ được tạo hoặc sửa bởi writer thanh lý'
      USING ERRCODE = '55000';
  END IF;

  v_status_only := TG_OP = 'UPDATE'
    AND (
      to_jsonb(NEW) - ARRAY[
        'approval_status', 'approved_by', 'approved_at', 'updated_at'
      ]::text[]
    ) IS NOT DISTINCT FROM (
      to_jsonb(OLD) - ARRAY[
        'approval_status', 'approved_by', 'approved_at', 'updated_at'
      ]::text[]
    );

  -- FIX 20260722: chỉ đòi authorized-transition RPC khi approval_status THỰC SỰ
  -- đổi. Trước đây guard coi mọi update "chỉ khác cột status/updated_at" là chuyển
  -- trạng thái, kể cả no-op touch chỉ bump updated_at (auto_recalc_total_amount ghi
  -- total_amount = giá trị cũ khi INSERT income_expense_items lúc thanh lý) -> 42501
  -- sai ngay bước tạo phiếu. Transition thật luôn đổi approval_status nên bảo vệ vẫn
  -- đầy đủ.
  IF v_status_only
     AND NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    SELECT EXISTS (
      SELECT 1
      FROM app_private.ie_transition_authorization transition_row
      WHERE transition_row.income_expense_id = NEW.id
        AND transition_row.xid = pg_current_xact_id()
        AND transition_row.purpose = NEW.approval_status
    ) INTO v_transition_authorized;
    IF NOT v_transition_authorized THEN
      RAISE EXCEPTION 'Forfeit voucher status must be changed by its authorized transition RPC'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: guard_termination_non_cash_payment_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_termination_non_cash_payment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_protected boolean;
  v_writer boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM app_private.termination_forfeit_authorizations auth_row
    WHERE auth_row.payment_id = OLD.id
  ) OR (
    OLD.received_amount = 0
    AND (
      COALESCE(OLD.notes, '') ~
        '^Quyết toán khi thanh lý [0-9]{2}/[0-9]{2}/[0-9]{4}( \(cấn cọc\))?$'
      OR COALESCE(OLD.notes, '') ~
        '^\[CẤN CỌC BỎ CỌC PAYMENT [0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\]$'
    )
  ) INTO v_protected;

  IF NOT v_protected THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_writer;
  IF NOT v_writer THEN
    RAISE EXCEPTION 'Termination non-cash payment is immutable outside its trusted writer'
      USING ERRCODE = '55000';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$_$;








--
-- Name: has_any_scope_v3(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_any_scope_v3(p_permission_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select exists (
    select 1
      from public.permission_definitions pd
      join public.organization_memberships m
        on m.user_id = (select auth.uid())
       and m.status = 'ACTIVE'
       and coalesce(m.valid_from, '-infinity'::timestamptz) <= now()
       and (m.valid_to is null or m.valid_to > now())
      join public.organizations o
        on o.id = m.organization_id and o.status = 'ACTIVE'
     where pd.key = p_permission_key
       and pd.permission_domain = 'TENANT'
       and pd.is_active
       -- (1) không bị cấm khẩn cấp
       and not exists (
         select 1 from app_private.tenant_emergency_denies d
          where d.organization_id = m.organization_id
            and (d.permission_key is null or d.permission_key = p_permission_key)
            and d.active_from <= now()
            and (d.expires_at is null or d.expires_at > now()))
       -- (2) không có CẤM ở phạm vi toàn tổ chức (cấm hẹp hơn vẫn còn chỗ khác)
       and not exists (
         select 1
           from public.member_permission_overrides ov
           join public.member_override_scopes mos on mos.override_id = ov.id
           join public.authorization_scopes s on s.id = mos.scope_id
          where ov.membership_id = m.id and ov.permission_key = p_permission_key
            and ov.effect = 'DENY' and ov.revoked_at is null
            and (ov.expires_at is null or ov.expires_at > now())
            and s.scope_type = 'ORGANIZATION')
       and not exists (
         select 1
           from public.role_bindings rb
           join public.role_permissions rp
             on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
            and rp.permission_key = p_permission_key and rp.effect = 'DENY'
           join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
           join public.authorization_scopes s on s.id = rbs.scope_id
          where rb.membership_id = m.id and rb.valid_to is null
            and s.scope_type = 'ORGANIZATION')
       -- (3) có ít nhất một cạnh CHO khớp loại phạm vi mà quyền này chấp nhận
       and (
         exists (
           select 1
             from public.member_permission_overrides ov
             join public.member_override_scopes mos on mos.override_id = ov.id
             join public.authorization_scopes s on s.id = mos.scope_id
            where ov.membership_id = m.id and ov.permission_key = p_permission_key
              and ov.effect = 'ALLOW' and ov.revoked_at is null
              and (ov.expires_at is null or ov.expires_at > now())
              and s.scope_type = any(pd.scope_kinds)
              and (not pd.requires_cashbook_possession or (
                    s.scope_type = 'CASHBOOK' and exists (
                      select 1 from public.cashbook_possession_bindings cp
                       where cp.membership_id = m.id and cp.cashbook_id = s.cashbook_id
                         and cp.possession_kind = any(pd.accepted_possession_kinds)
                         and cp.valid_from <= now()
                         and (cp.valid_to is null or cp.valid_to > now())))))
         or exists (
           select 1
             from public.role_bindings rb
             join public.role_permissions rp
               on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
              and rp.permission_key = p_permission_key and rp.effect = 'ALLOW'
             join public.organization_roles orl
               on orl.id = rb.role_id and coalesce(orl.status,'ACTIVE') = 'ACTIVE'
             join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
             join public.authorization_scopes s on s.id = rbs.scope_id
            where rb.membership_id = m.id
              and coalesce(rb.valid_from, '-infinity'::timestamptz) <= now()
              and (rb.valid_to is null or rb.valid_to > now())
              and s.scope_type = any(pd.scope_kinds)
              and (not pd.requires_cashbook_possession or (
                    s.scope_type = 'CASHBOOK' and exists (
                      select 1 from public.cashbook_possession_bindings cp
                       where cp.membership_id = m.id and cp.cashbook_id = s.cashbook_id
                         and cp.possession_kind = any(pd.accepted_possession_kinds)
                         and cp.valid_from <= now()
                         and (cp.valid_to is null or cp.valid_to > now())))))
       )
  );
$$;








--
-- Name: has_ie_claim_capability_v1(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_ie_claim_capability_v1(p_nonce text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  -- Strictly boolean, fail-closed: a NULL nonce, an unset GUC, or a mismatch all
  -- return false (never NULL — an IF NOT on NULL would silently skip the guard).
  select coalesce(
    p_nonce = nullif(current_setting('app_private.ie_claim_capability', true), ''),
    false);
$$;








--
-- Name: ie_accounting_strict_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_accounting_strict_v1(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT COALESCE(
    (SELECT m.strict_mode
       FROM app_private.org_accounting_mode m
      WHERE m.organization_id = p_org
        AND m.effective_from <= now()
      ORDER BY m.effective_from DESC, m.id DESC
      LIMIT 1),
    true  -- KHÔNG có dòng nào ⇒ CHUẨN KẾ TOÁN. Org mới, org lạ, lỗi đọc:
          -- tất cả đều rơi về hành vi chặt hiện hành.
  );
$$;








--
-- Name: ie_actor_display_name_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_actor_display_name_v1(p_actor uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
  select coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.email), ''),
                  u.email, 'Người dùng')
    from auth.users u
    left join public.profiles p on p.id = u.id
   where u.id = p_actor;
$$;








--
-- Name: ie_approver_ids_v1(uuid, uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_approver_ids_v1(p_org uuid, p_building uuid, p_exclude uuid[] DEFAULT '{}'::uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v  uuid[];
  ex uuid[];
begin
  -- 🔴 LỌC PHẦN TỬ NULL khỏi p_exclude trước khi dùng.
  -- `coalesce(p_exclude,'{}')` chỉ chống MẢNG null, KHÔNG chống PHẦN TỬ null: với
  -- p_exclude = array[NULL, maker] thì `m.user_id = any(...)` trả NULL, `not NULL` = NULL,
  -- và WHERE loại sạch mọi dòng ⇒ hàm trả '{}' IM LẶNG, không lỗi. Đúng bẫy §0.3 điểm 2.
  -- Nơi gọi hôm nay dùng array_remove(...) nên may mắn an toàn, nhưng §B.4 của đặc tả viết
  -- nguyên văn `array[v_actor, v_maker]` — vá ở đây là chỗ rẻ nhất và chống được cả hai.
  ex := coalesce(
          array(select x from unnest(coalesce(p_exclude, '{}'::uuid[])) x where x is not null),
          '{}'::uuid[]);

  select coalesce(array_agg(distinct m.user_id), '{}'::uuid[]) into v
    from public.organization_memberships m
   where m.organization_id = p_org
     and m.status = 'ACTIVE'
     and not (m.user_id = any(ex))
     and (select a.allowed from app_private.authorize_tenant_action_v3(
            m.user_id, p_org, 'income_expenses.approve', p_building, null) a);
  return v;
end
$$;








--
-- Name: FUNCTION ie_approver_ids_v1(p_org uuid, p_building uuid, p_exclude uuid[]); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.ie_approver_ids_v1(p_org uuid, p_building uuid, p_exclude uuid[]) IS 'Trả về user_id của những thành viên ACTIVE có income_expenses.approve trong phạm vi toà nhà. Dùng để chọn người nhận thông báo E1/E3. Không lock org, không nhánh super admin (§B.1a).';








--
-- Name: ie_attachments_remove_v1(jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_attachments_remove_v1(p_old jsonb, p_remove jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(
    (SELECT jsonb_agg(e.value ORDER BY e.ordinality)
       FROM jsonb_array_elements(COALESCE(p_old, '[]'::jsonb)) WITH ORDINALITY AS e(value, ordinality)
      WHERE NOT COALESCE(p_remove, '[]'::jsonb) @> jsonb_build_array(e.value)),
    '[]'::jsonb);
$$;








--
-- Name: ie_attachments_union_v1(jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_attachments_union_v1(p_old jsonb, p_new jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(p_old, '[]'::jsonb) || COALESCE((
    SELECT jsonb_agg(DISTINCT e.value)
    FROM jsonb_array_elements(COALESCE(p_new, '[]'::jsonb)) AS e
    WHERE NOT COALESCE(p_old, '[]'::jsonb) @> jsonb_build_array(e.value)
  ), '[]'::jsonb);
$$;








--
