--
-- Name: ie_lock_operation_for_claim_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_lock_operation_for_claim_v1(p_organization_id uuid, p_subject_scope text, p_actor uuid, p_idempotency_key text, p_payload_hash text) RETURNS app_private.canonical_write_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private'
    AS $$
declare
  v_op app_private.canonical_write_operations;
begin
  select * into v_op
    from app_private.canonical_write_operations o
   where o.organization_id = p_organization_id
     and o.operation = 'income_expense.create_draft.v1'
     and o.subject_scope = p_subject_scope
     and o.actor_id = p_actor
     and o.idempotency_key = p_idempotency_key
     and o.subject_id is null
     and o.response_payload is null
     and o.completed_at is null
     and o.payload_hash = p_payload_hash
   for update;
  if not found then
    raise exception 'no matching in-progress canonical operation'
      using errcode = 'P0002';
  end if;
  return v_op;
end;
$$;








--
-- Name: ie_lock_row_for_claim_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_lock_row_for_claim_v1(p_id uuid) RETURNS public.income_expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_row public.income_expenses;
begin
  select * into v_row from public.income_expenses
   where id = p_id and deleted_at is null
   for update; -- TOCTOU fix: concurrent UPDATE waits, then sees the marker
  if not found then
    raise exception 'income expense not found' using errcode = 'P0002';
  end if;
  return v_row;
end;
$$;








--
-- Name: ie_normalize_lifecycle_columns(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_normalize_lifecycle_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_virtual boolean := false;
BEGIN
  IF NEW.posting_mode IS NULL THEN
    IF NEW.account_id IS NOT NULL THEN
      SELECT COALESCE(a.is_virtual, false) INTO v_virtual
      FROM public.accounts a WHERE a.id = NEW.account_id;
    END IF;
    NEW.posting_mode := CASE WHEN v_virtual THEN 'NON_CASH' ELSE 'CASHBOOK' END;
  END IF;

  IF NEW.posting_status IS NULL THEN
    NEW.posting_status := CASE WHEN NEW.posting_mode = 'NON_CASH'
                               THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END;
  END IF;

  IF NEW.review_state IS NULL THEN
    NEW.review_state := CASE WHEN NEW.approval_status = 'UNAPPROVED'
                             THEN 'PENDING' ELSE 'RESOLVED' END;
  END IF;

  RETURN NEW;
END
$$;








--
-- Name: ie_notes_append_only_v1(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ie_notes_append_only_v1(p_old text, p_new text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN btrim(COALESCE(p_old, '')) = '' THEN true
    WHEN p_new IS NULL THEN false
    -- left() thay vì LIKE: notes thật có chứa '%' và '_' (số tiền, đường
    -- dẫn), LIKE sẽ hiểu chúng là ký tự đại diện và cho lọt.
    ELSE left(btrim(p_new), length(btrim(p_old))) = btrim(COALESCE(p_old, ''))
  END;
$$;








--
-- Name: FUNCTION ie_notes_append_only_v1(p_old text, p_new text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.ie_notes_append_only_v1(p_old text, p_new text) IS 'Ghi chú mới có GIỮ NGUYÊN ghi chú cũ ở đầu không (tức chỉ nối thêm)? So trên bản btrim vì giao diện gửi lại chuỗi đã trim.';








