--
-- Name: is_org_owner_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.is_org_owner_v1(p_org uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.role_bindings rb
    JOIN public.organization_memberships m
      ON m.id = rb.membership_id
     AND m.organization_id = rb.organization_id
     AND m.user_id = p_user
     AND m.status = 'ACTIVE'
     AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
     AND (m.valid_to IS NULL OR m.valid_to > now())
    JOIN public.organization_roles r
      ON r.id = rb.role_id
     -- Slice −1 §−1.10: neo vào system_key bền thay cho tên tự do.
     AND (
           r.system_key = 'TENANT_OWNER'
        OR (r.system_key IS NULL AND r.name = 'Chủ sở hữu tổ chức')
     )
    WHERE rb.organization_id = p_org
      -- Cửa sổ hiệu lực của CHÍNH binding: đây là cách duy nhất repo thu hồi vai trò.
      AND COALESCE(rb.valid_from, '-infinity'::timestamptz) <= now()
      AND (rb.valid_to IS NULL OR rb.valid_to > now())
  );
$$;








--
-- Name: FUNCTION is_org_owner_v1(p_org uuid, p_user uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.is_org_owner_v1(p_org uuid, p_user uuid) IS 'Chủ sở hữu tổ chức = có role binding còn hiệu lực tới vai trò system_key=TENANT_OWNER (Slice −1 §−1.10: trước đây so theo organization_roles.name — text tự do, đổi tên trong Cài đặt là sập cửa chủ sở hữu). Vế name chỉ còn là fallback cho org chưa gắn system_key. Đã chứng minh chọn đúng cùng tập 4 (org,user) trên prod 30/07: lost 0, gained 0.';








