--
-- Name: lock_org_for_decision_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.lock_org_for_decision_v1(p_organization_id uuid) RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  -- Statement 1 of the writer protocol: take the org lock FIRST so the witness
  -- statement that follows runs on a snapshot taken AFTER any waiting.
  --
  -- FOR NO KEY UPDATE, *không phải* FOR SHARE (sửa 30/07/2026, deadlock 40P01):
  -- trigger a10_bump_authz_version làm `UPDATE organizations SET
  -- authorization_version = …` khi writer chạm authorization_scopes /
  -- member_permission_overrides / member_override_scopes. Nếu ở đây chỉ giữ
  -- share thì hai phiên cùng org đều phải NÂNG khoá lên độc quyền và chờ chéo
  -- nhau ⇒ deadlock (đã tái hiện: 6 worker song song đỏ 1/4). NO KEY UPDATE là
  -- đúng mode mà câu UPDATE kia cần, nên lấy sẵn từ đầu là hết phải nâng.
  -- KHÔNG dùng FOR UPDATE: mạnh quá mức và chặn luôn cả FK check (FOR KEY SHARE).
  select o.authorization_version
    from public.organizations o
   where o.id = p_organization_id
     and o.status = 'ACTIVE'
     for no key update;
$$;








--
-- Name: FUNCTION lock_org_for_decision_v1(p_organization_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.lock_org_for_decision_v1(p_organization_id uuid) IS 'Bước 1 của giao thức ghi canonical: khoá dòng organizations bằng FOR NO KEY UPDATE để mọi quyết định sau đó chạy trên snapshot lấy SAU khi đã chờ. Phải là NO KEY UPDATE chứ không phải FOR SHARE: trigger a10_bump_authz_version làm UPDATE organizations khi writer chạm bảng phân quyền, nên giữ share rồi mới xin độc quyền là bẫy nâng khoá — hai phiên cùng org chờ chéo nhau và chết 40P01 (tái hiện được với 6 phiên song song, 30/07/2026). 41 hàm gọi hàm này.';








--
-- Name: lock_profit_payout_sources_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.lock_profit_payout_sources_v2() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  -- Item DML takes the child table first, then its total-recalculation trigger
  -- updates the parent voucher. Source readers must use that same order.
  LOCK TABLE public.income_expense_items,
             public.income_expenses,
             public.income_expense_types,
             public.invoices,
             public.building_shareholders,
             public.shareholders,
             public.profit_managers,
             public.profit_manager_salaries,
             public.profit_manager_salary_buildings,
             public.staff_assignments,
             public.roles,
             public.area_buildings,
             public.super_admins,
             public.buildings,
             public.profit_monthly,
             public.profit_allocations
    IN SHARE ROW EXCLUSIVE MODE;
END
$$;








--
-- Name: log_income_expense_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.log_income_expense_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_noise text[] := ARRAY[
    'updated_at', 'created_at', 'approval_version', 'posting_version',
    'source_payload_hash', 'birth_txid', 'birth_operation_id',
    'active_posting_id_v2', 'posting_id', 'posted_at_v2', 'reversed_by_posting_id',
    'sequence_no', 'prev_event_hash', 'event_hash'
  ];
  v_before jsonb;
  v_after  jsonb;
  v_cols   text[];
  v_id     uuid;
  v_org    uuid;
BEGIN
  IF TG_TABLE_NAME = 'income_expenses' THEN
    v_id  := COALESCE(NEW.id, OLD.id);
    v_org := COALESCE(NEW.organization_id, OLD.organization_id);
  ELSE
    v_id  := COALESCE(NEW.income_expense_id, OLD.income_expense_id);
    v_org := COALESCE(NEW.organization_id, OLD.organization_id);
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT COALESCE(array_agg(key ORDER BY key), '{}')
      INTO v_cols
    FROM jsonb_each(to_jsonb(NEW)) n
    WHERE NOT (key = ANY (v_noise))
      AND n.value IS DISTINCT FROM (to_jsonb(OLD) -> n.key);
    IF cardinality(v_cols) = 0 THEN
      RETURN NULL;   -- chỉ nhiễu, không ghi
    END IF;
    SELECT jsonb_object_agg(k, to_jsonb(OLD) -> k) INTO v_before FROM unnest(v_cols) k;
    SELECT jsonb_object_agg(k, to_jsonb(NEW) -> k) INTO v_after  FROM unnest(v_cols) k;
  ELSIF TG_OP = 'DELETE' THEN
    v_before := to_jsonb(OLD);
    v_after  := NULL;
    v_cols   := ARRAY['*deleted*'];
  ELSE
    v_before := NULL;
    v_after  := to_jsonb(NEW);
    v_cols   := ARRAY['*created*'];
  END IF;

  INSERT INTO app_private.income_expense_change_log
    (income_expense_id, organization_id, actor_id, db_role, scope, op,
     changed_cols, before, after)
  VALUES
    (v_id, v_org, auth.uid(), current_user,
     CASE WHEN TG_TABLE_NAME = 'income_expenses' THEN 'VOUCHER' ELSE 'ITEM' END,
     TG_OP, v_cols, v_before, v_after);

  RETURN NULL;   -- AFTER trigger
END
$$;








--
-- Name: maintenance_rule_check_v1(uuid, uuid, uuid, text, date, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.maintenance_rule_check_v1(p_org uuid, p_building uuid, p_room uuid, p_kind text, p_when date, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_r      record;
  v_last   date;
  v_gapm   int;
  v_price  text := 'OK';
  v_cad    text := 'OK';
  v_reason text := NULL;
BEGIN
  SELECT * INTO v_r FROM app_private.maintenance_rule_versions v
   WHERE v.organization_id = p_org AND v.status = 'PUBLISHED'
     AND v.service_kind = p_kind
     AND v.effective_from_month <= date_trunc('month', p_when)::date
     AND (v.building_id = p_building OR v.building_id IS NULL)
   ORDER BY (v.building_id IS NOT NULL) DESC, v.effective_from_month DESC
   LIMIT 1;

  IF v_r.id IS NULL THEN
    RETURN jsonb_build_object('verdict','NO_RULE',
      'reason','Chủ chưa công bố luật bảo trì cho hạng mục này — giữ nguyên hành vi cũ');
  END IF;

  -- ── Giá ──
  IF v_r.ceiling_amount IS NOT NULL AND round(COALESCE(p_amount,0)) > round(v_r.ceiling_amount) THEN
    v_price := 'OVER_CEILING';
    v_reason := 'Giá ' || replace(to_char(round(COALESCE(p_amount,0)),'FM999G999G999G999'),',','.')
             || 'đ vượt trần ' || replace(to_char(round(v_r.ceiling_amount),'FM999G999G999G999'),',','.') || 'đ';
  ELSIF v_r.standard_amount IS NOT NULL AND round(COALESCE(p_amount,0)) > round(v_r.standard_amount) THEN
    v_price := 'OVER_STANDARD';
    v_reason := 'Giá cao hơn mức chuẩn '
             || replace(to_char(round(v_r.standard_amount),'FM999G999G999G999'),',','.') || 'đ';
  END IF;

  -- ── Giãn cách ──
  -- Máy lạnh tính theo PHÒNG; máy giặt theo TOÀ. Không có phòng thì luật theo
  -- phòng KHÔNG áp được — nói thẳng thay vì âm thầm cho qua.
  IF v_r.min_months_between IS NOT NULL THEN
    IF p_kind = 'AIR_CONDITIONER' AND p_room IS NULL THEN
      v_cad := 'NO_ROOM';
      v_reason := COALESCE(v_reason || ' · ', '')
               || 'Phiếu không gắn phòng nên không kiểm được luật giãn cách theo phòng';
    ELSE
      SELECT max(ie.voucher_date) INTO v_last
        FROM public.income_expenses ie
        JOIN public.income_expense_items it ON it.income_expense_id = ie.id
        JOIN public.income_expense_types t  ON t.id = it.income_expense_type_id
       WHERE ie.organization_id = p_org
         AND ie.deleted_at IS NULL
         AND ie.approval_status <> 'CANCELLED'
         AND ie.type = 'EXPENSE'
         AND ie.voucher_date < p_when
         AND public.nrm_vn(t.category) LIKE 'bao tri%'
         AND (CASE WHEN p_kind = 'AIR_CONDITIONER'
                   THEN public.nrm_vn(t.category) LIKE '%may lanh%'
                   ELSE public.nrm_vn(t.category) LIKE '%may giat%' END)
         AND (CASE WHEN p_kind = 'AIR_CONDITIONER'
                   THEN ie.room_id = p_room
                   ELSE ie.building_id = p_building END)
         -- Mặc định CHỈ tính các lần từ ngày công bố luật trở đi.
         AND (v_r.counts_history OR ie.voucher_date >= v_r.effective_from_month);

      IF v_last IS NOT NULL THEN
        v_gapm := (EXTRACT(YEAR FROM age(p_when, v_last))*12
                 + EXTRACT(MONTH FROM age(p_when, v_last)))::int;
        IF v_gapm < v_r.min_months_between THEN
          v_cad := 'TOO_SOON';
          v_reason := COALESCE(v_reason || ' · ', '')
                   || 'Lần bảo trì gần nhất là ' || to_char(v_last,'DD/MM/YYYY')
                   || ' (cách ' || v_gapm || ' tháng, luật đòi tối thiểu '
                   || v_r.min_months_between || ' tháng)';
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN v_price = 'OK' AND v_cad = 'OK' THEN 'OK' ELSE 'FLAGGED' END,
    'price', v_price, 'cadence', v_cad,
    'enforcement', v_r.enforcement,
    'lastServicedAt', v_last,
    'standardAmount', v_r.standard_amount,
    'ceilingAmount', v_r.ceiling_amount,
    'minMonthsBetween', v_r.min_months_between,
    'countsHistory', v_r.counts_history,
    'reason', v_reason);
END;
$$;








--
-- Name: materialize_openclaw_audit_root_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_openclaw_audit_root_v1(p_limit integer DEFAULT 31) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  day record;
  binding record;
  v_root uuid;
  v_payload jsonb;
  v_bytes bytea;
  v_hash text;
  v_previous_root_hash text;
  v_merkle_root_hash text;
  v_root_hash text;
  v_inserted integer;
  v_created integer := 0;
begin
  for day in
    select event.organization_id,(event.occurred_at at time zone 'UTC')::date root_date,
      min(event.organization_sequence) first_sequence,
      max(event.organization_sequence) last_sequence,count(*) event_count,
      array_agg(event.organization_sequence order by event.organization_sequence) sequences,
      array_agg(event.event_hash order by event.organization_sequence) event_hashes,
      config.signing_key_generation,config.public_key_hash audit_signing_public_key_hash
    from public.openclaw_audit_events event
    join public.openclaw_audit_signing_configs config
      on config.organization_id=event.organization_id and config.is_active
     and config.retired_at is null
    where (event.occurred_at at time zone 'UTC')::date
      < (statement_timestamp() at time zone 'UTC')::date
      and not exists (select 1 from public.openclaw_audit_roots root
        where root.organization_id=event.organization_id
          and root.root_date=(event.occurred_at at time zone 'UTC')::date)
      and not exists (
        select 1 from public.openclaw_audit_events earlier
        where earlier.organization_id=event.organization_id
          and (earlier.occurred_at at time zone 'UTC')::date
            < (event.occurred_at at time zone 'UTC')::date
          and (earlier.occurred_at at time zone 'UTC')::date
            < (statement_timestamp() at time zone 'UTC')::date
          and not exists (
            select 1 from public.openclaw_audit_roots earlier_root
            where earlier_root.organization_id=earlier.organization_id
              and earlier_root.root_date=(earlier.occurred_at at time zone 'UTC')::date
          )
      )
    group by event.organization_id,(event.occurred_at at time zone 'UTC')::date,
      config.signing_key_generation,config.public_key_hash
    order by root_date,event.organization_id
    limit greatest(1,least(coalesce(p_limit,31),366))
  loop
    perform pg_advisory_xact_lock(hashtextextended(day.organization_id::text,0));
    if exists (select 1 from public.openclaw_audit_roots root
      where root.organization_id=day.organization_id and root.root_date=day.root_date) then
      continue;
    end if;
    select root.root_hash into v_previous_root_hash
    from public.openclaw_audit_roots root
    where root.organization_id=day.organization_id and root.root_date<day.root_date
    order by root.root_date desc limit 1;
    v_merkle_root_hash:=app_private.openclaw_audit_merkle_root_v1(
      day.sequences,day.event_hashes
    );
    v_root_hash:=app_private.openclaw_audit_lineage_root_v1(
      day.organization_id,day.root_date,day.first_sequence,day.last_sequence,
      day.event_count,v_previous_root_hash,v_merkle_root_hash
    );
    select principal.id maintenance_principal_id,credential.credential_generation,
      lease.lease_generation,lease.fencing_token
    into binding
    from public.openclaw_maintenance_principals principal
    join public.openclaw_maintenance_credentials credential
      on credential.organization_id=principal.organization_id
     and credential.maintenance_principal_id=principal.id and credential.revoked_at is null
    join public.openclaw_maintenance_leases lease
      on lease.organization_id=principal.organization_id
     and lease.maintenance_principal_id=principal.id
     and lease.status='ACTIVE' and lease.expires_at>statement_timestamp()
    where principal.organization_id=day.organization_id
      and principal.is_current and principal.revoked_at is null
    order by lease.lease_generation desc,credential.credential_generation desc limit 1;
    if binding.maintenance_principal_id is null then continue; end if;
    v_root:=gen_random_uuid();
    insert into public.openclaw_audit_roots(
      id,organization_id,root_date,first_sequence,last_sequence,previous_root_hash,
      merkle_root_hash,root_hash,event_count,signing_key_generation,r2_anchor_key
    ) values (
      v_root,day.organization_id,day.root_date,day.first_sequence,day.last_sequence,
      v_previous_root_hash,v_merkle_root_hash,v_root_hash,day.event_count,day.signing_key_generation,
      'v1/org/'||day.organization_id||'/audit/'||day.root_date||'/'||v_root||'.json'
    ) on conflict (organization_id,root_date) do nothing returning id into v_root;
    if v_root is null then continue; end if;
    v_payload := jsonb_build_object(
      'kind','AUDIT_ANCHOR','auditRootId',v_root,
      'rootDate',day.root_date,'firstSequence',day.first_sequence,
      'lastSequence',day.last_sequence,'eventCount',day.event_count,
      'previousRootHash',v_previous_root_hash,'merkleRootHash',v_merkle_root_hash,
      'rootHash',v_root_hash,
      'auditSigningKeyGeneration',day.signing_key_generation,
      'auditSigningPublicKeyHash',day.audit_signing_public_key_hash,
      'anchorKey','v1/org/'||day.organization_id||'/audit/'||day.root_date||'/'||v_root||'.json'
    );
    v_bytes := app_private.openclaw_jcs_bytes_v1(v_payload);
    v_hash := encode(extensions.digest(v_bytes,'sha256'),'hex');
    insert into public.openclaw_maintenance_work_items(
      organization_id,maintenance_principal_id,work_kind,work_phase,source_id,
      source_version,source_key,source_hash,payload,payload_hash,state,claim_generation,
      maintenance_lease_generation,fencing_token,credential_generation
    ) values (
      day.organization_id,binding.maintenance_principal_id,'AUDIT_ANCHOR','ANCHOR',v_root,
      day.signing_key_generation::text,'audit:'||v_root||':'||day.signing_key_generation,
      v_hash,v_payload,v_hash,'QUEUED',1,binding.lease_generation,
      binding.fencing_token,binding.credential_generation
    ) on conflict (organization_id,source_key) where source_key is not null do nothing;
    get diagnostics v_inserted=row_count;
    v_created:=v_created+v_inserted;
  end loop;
  return v_created;
end;
$$;








--
-- Name: materialize_openclaw_crm_work_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_openclaw_crm_work_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  item record;
  v_now timestamptz := statement_timestamp();
  v_cell uuid;
  v_credential bigint;
  v_lease bigint;
  v_fence bigint;
  v_session bigint;
  v_payload jsonb;
  v_payload_bytes bytea;
  v_source_hash text;
  v_inserted integer;
  v_created integer := 0;
begin
  for item in
    select occurrence.id crm_occurrence_id,occurrence.organization_id,
      occurrence.event_type,occurrence.event_subtype,occurrence.source_snapshot,
      occurrence.snapshot_hash source_envelope_hash,subscription.id subscription_id,
      subscription.account_id,subscription.subscription_version,
      subscription.automation_version_id,subscription.destination_target_id,
      snapshot.snapshot_hash subscription_snapshot_hash,snapshot.field_mapping_hash,
      target.target_version,target.directory_refreshed_at,
      automation.content_version_id template_version_id,
      automation.knowledge_version_ids
    from public.openclaw_crm_event_occurrences occurrence
    join public.openclaw_crm_event_subscriptions subscription
      on subscription.organization_id=occurrence.organization_id
     and subscription.event_type=occurrence.event_type and subscription.is_active
    join public.openclaw_crm_event_subscription_snapshots snapshot
      on snapshot.organization_id=subscription.organization_id
     and snapshot.account_id=subscription.account_id and snapshot.subscription_id=subscription.id
      and snapshot.subscription_version=subscription.subscription_version
    join public.openclaw_targets target
      on target.organization_id=subscription.organization_id
     and target.account_id=subscription.account_id
     and target.id=subscription.destination_target_id and target.is_active
    join public.openclaw_automation_versions automation
      on automation.organization_id=subscription.organization_id
     and automation.account_id=subscription.account_id
     and automation.id=subscription.automation_version_id
    join public.openclaw_control_states control
      on control.organization_id=subscription.organization_id and control.control_key='GLOBAL_STOP'
     and control.feature_enabled and control.proactive_enabled and not control.global_stop
    where not exists (
      select 1 from public.openclaw_send_work_items work
      where work.organization_id=occurrence.organization_id and work.work_kind='CRM_EVENT'
        and work.subscription_id=subscription.id
        and work.subscription_version=subscription.subscription_version
        and work.crm_occurrence_id=occurrence.id
        and work.target_id=subscription.destination_target_id
    )
    order by occurrence.created_at,occurrence.id,subscription.id
    for update of occurrence,subscription skip locked
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    select cell.id,credential.credential_generation,lease.lease_generation,
      lease.fencing_token,account.session_generation
    into v_cell,v_credential,v_lease,v_fence,v_session
    from public.openclaw_accounts account
    join public.openclaw_runtime_cells cell
      on cell.organization_id=account.organization_id and cell.account_id=account.id
     and cell.is_current and cell.state='READY'
    join public.openclaw_runtime_leases lease
      on lease.organization_id=cell.organization_id and lease.account_id=cell.account_id
     and lease.cell_id=cell.id and lease.status='ACTIVE' and lease.expires_at>v_now
    join public.openclaw_runtime_credentials credential
      on credential.organization_id=cell.organization_id and credential.account_id=cell.account_id
     and credential.cell_id=cell.id and credential.revoked_at is null
    where account.organization_id=item.organization_id and account.id=item.account_id
      and account.is_active
    order by lease.lease_generation desc,credential.credential_generation desc
    limit 1;
    if v_cell is null then continue; end if;
    v_payload := jsonb_build_object(
      'kind','CRM_EVENT','subscriptionId',item.subscription_id,
      'subscriptionVersion',item.subscription_version,'occurrenceId',item.crm_occurrence_id,
      'automationVersionId',item.automation_version_id,
      'templateVersionId',item.template_version_id,
      'knowledgeVersionIds',to_jsonb(item.knowledge_version_ids),
      'targetId',item.destination_target_id,'targetVersion',item.target_version,
      'targetDirectoryRefreshedAt',item.directory_refreshed_at,
      'fieldMappingHash',item.field_mapping_hash,
      'sourceEnvelope',item.source_snapshot,
      'sourceEnvelopeHash',item.source_envelope_hash
    );
    v_payload_bytes := app_private.openclaw_jcs_bytes_v1(v_payload);
    v_source_hash := encode(extensions.digest(
      convert_to('ihome-openclaw-crm-work-source-v1','UTF8')||decode('00','hex')
        ||app_private.openclaw_jcs_bytes_v1(jsonb_build_object(
          'subscriptionSnapshotHash',item.subscription_snapshot_hash,
          'sourceEnvelopeHash',item.source_envelope_hash
        )),'sha256'),'hex');
    insert into public.openclaw_send_work_items(
      organization_id,account_id,cell_id,work_kind,source_id,source_version,source_key,
      source_hash,payload,payload_hash,state,claim_generation,fencing_token,
      session_generation,target_id,credential_generation,runtime_lease_generation,
      subscription_id,subscription_version,crm_occurrence_id
    ) values (
      item.organization_id,item.account_id,v_cell,'CRM_EVENT',item.crm_occurrence_id,
      item.subscription_version::text,
      'crm:'||item.subscription_id||':'||item.subscription_version||':'
        ||item.crm_occurrence_id||':'||item.destination_target_id,
      v_source_hash,v_payload,
      encode(extensions.digest(v_payload_bytes,'sha256'),'hex'),'QUEUED',1,
      v_fence,v_session,item.destination_target_id,v_credential,v_lease,
      item.subscription_id,item.subscription_version,item.crm_occurrence_id
    ) on conflict (organization_id,subscription_id,subscription_version,crm_occurrence_id,target_id)
      where work_kind='CRM_EVENT' do nothing;
    get diagnostics v_inserted=row_count;
    v_created := v_created+v_inserted;
  end loop;
  return v_created;
end;
$$;








--
-- Name: materialize_openclaw_retention_final_delete_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_openclaw_retention_final_delete_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tombstone record;
  binding record;
  v_payload jsonb;
  v_bytes bytea;
  v_hash text;
  v_inserted integer;
  v_created integer := 0;
begin
  for v_tombstone in
    select candidate.* from public.openclaw_retention_tombstones candidate
    where candidate.subject_kind='MEDIA'
      and candidate.final_delete_not_before<=statement_timestamp()
      and candidate.object_key is not null
      and not app_private.openclaw_retention_subject_held_v1(
        candidate.organization_id,'MEDIA',candidate.subject_id)
      and not exists (select 1 from public.openclaw_retention_delete_tickets ticket
        where ticket.organization_id=candidate.organization_id
          and ticket.tombstone_id=candidate.id)
      and not exists (select 1 from public.openclaw_maintenance_work_items work
        where work.organization_id=candidate.organization_id
          and work.source_key='retention:final:'||candidate.id||':'||candidate.quarantine_version)
    order by candidate.final_delete_not_before,candidate.id
    for update of candidate skip locked
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    select principal.id maintenance_principal_id,credential.credential_generation,
      lease.lease_generation,lease.fencing_token
    into binding
    from public.openclaw_maintenance_principals principal
    join public.openclaw_maintenance_credentials credential
      on credential.organization_id=principal.organization_id
     and credential.maintenance_principal_id=principal.id and credential.revoked_at is null
    join public.openclaw_maintenance_leases lease
      on lease.organization_id=principal.organization_id
     and lease.maintenance_principal_id=principal.id
     and lease.status='ACTIVE' and lease.expires_at>statement_timestamp()
    where principal.organization_id=v_tombstone.organization_id
      and principal.is_current and principal.revoked_at is null
    order by lease.lease_generation desc,credential.credential_generation desc limit 1;
    if binding.maintenance_principal_id is null then continue; end if;
    v_payload := jsonb_build_object(
      'kind','RETENTION_DELETE','deletePhase','FINAL_DELETE','subjectKind','MEDIA',
      'subjectId',v_tombstone.subject_id,'objectKey',v_tombstone.object_key,
      'retentionVersion',v_tombstone.retention_version,
      'holdVersion',coalesce((select clock.hold_version
        from public.openclaw_retention_hold_clocks clock
        where clock.organization_id=v_tombstone.organization_id),0),
      'quarantineVersion',v_tombstone.quarantine_version,
      'finalDeleteNotBefore',v_tombstone.final_delete_not_before
    );
    v_bytes := app_private.openclaw_jcs_bytes_v1(v_payload);
    v_hash := encode(extensions.digest(v_bytes,'sha256'),'hex');
    insert into public.openclaw_maintenance_work_items(
      organization_id,maintenance_principal_id,work_kind,work_phase,source_id,
      source_version,source_key,source_hash,payload,payload_hash,state,claim_generation,
      maintenance_lease_generation,fencing_token,credential_generation
    ) values (
      v_tombstone.organization_id,binding.maintenance_principal_id,'RETENTION_DELETE','FINAL_DELETE',
      v_tombstone.id,v_tombstone.quarantine_version::text,
      'retention:final:'||v_tombstone.id||':'||v_tombstone.quarantine_version,
      v_hash,v_payload,v_hash,'QUEUED',1,binding.lease_generation,
      binding.fencing_token,binding.credential_generation
    ) on conflict (organization_id,source_key) where source_key is not null do nothing;
    get diagnostics v_inserted=row_count;
    v_created:=v_created+v_inserted;
  end loop;
  return v_created;
end;
$$;








--
-- Name: materialize_openclaw_retention_quarantine_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_openclaw_retention_quarantine_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  binding record;
  v_payload jsonb;
  v_bytes bytea;
  v_hash text;
  v_inserted integer;
  v_created integer := 0;
begin
  for candidate in
    with subjects as (
      select policy.organization_id,policy.policy_version,policy.subject_kind,
        message.id subject_id,message.created_at subject_created_at
      from public.openclaw_retention_policies policy
      join public.openclaw_messages message on message.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='MESSAGE'
        and message.created_at<=statement_timestamp()-make_interval(secs=>policy.retain_for_seconds::integer)
        and message.text_content is distinct from '[REDACTED_BY_RETENTION]'
      union all
      select policy.organization_id,policy.policy_version,policy.subject_kind,
        draft.id,draft.created_at
      from public.openclaw_retention_policies policy
      join public.openclaw_ai_drafts draft on draft.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='AI_DRAFT'
        and draft.created_at<=statement_timestamp()-make_interval(secs=>policy.retain_for_seconds::integer)
        and draft.draft_text is distinct from '[REDACTED_BY_RETENTION]'
      union all
      select policy.organization_id,policy.policy_version,policy.subject_kind,
        media.id,media.created_at
      from public.openclaw_retention_policies policy
      join public.openclaw_message_media media on media.organization_id=policy.organization_id
      where policy.is_active and policy.subject_kind='MEDIA'
        and media.created_at<=statement_timestamp()-make_interval(secs=>policy.retain_for_seconds::integer)
        and media.object_key is not null and media.byte_state in ('CACHED','AVAILABLE')
    )
    select subject.*,coalesce(clock.hold_version,0) scope_version
    from subjects subject
    left join public.openclaw_retention_hold_clocks clock
      on clock.organization_id=subject.organization_id
    where not app_private.openclaw_retention_subject_held_v1(
      subject.organization_id,subject.subject_kind,subject.subject_id)
      and not exists (select 1 from public.openclaw_maintenance_work_items work
        where work.organization_id=subject.organization_id
          and work.source_key='retention:quarantine:'||subject.subject_kind||':'
            ||subject.subject_id||':'||subject.policy_version||':'
            ||coalesce(clock.hold_version,0))
    order by subject.subject_created_at,subject.subject_id
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    select principal.id maintenance_principal_id,credential.credential_generation,
      lease.lease_generation,lease.fencing_token
    into binding
    from public.openclaw_maintenance_principals principal
    join public.openclaw_maintenance_credentials credential
      on credential.organization_id=principal.organization_id
     and credential.maintenance_principal_id=principal.id and credential.revoked_at is null
    join public.openclaw_maintenance_leases lease
      on lease.organization_id=principal.organization_id
     and lease.maintenance_principal_id=principal.id
     and lease.status='ACTIVE' and lease.expires_at>statement_timestamp()
    where principal.organization_id=candidate.organization_id
      and principal.is_current and principal.revoked_at is null
    order by lease.lease_generation desc,credential.credential_generation desc
    limit 1;
    if binding.maintenance_principal_id is null then continue; end if;
    v_payload := jsonb_build_object(
      'kind','RETENTION_DELETE','deletePhase','QUARANTINE',
      'subjectKind',candidate.subject_kind,'subjectId',candidate.subject_id,
      'retentionVersion',candidate.policy_version,'holdVersion',candidate.scope_version
    );
    v_bytes := app_private.openclaw_jcs_bytes_v1(v_payload);
    v_hash := encode(extensions.digest(v_bytes,'sha256'),'hex');
    insert into public.openclaw_maintenance_work_items(
      organization_id,maintenance_principal_id,work_kind,work_phase,source_id,
      source_version,source_key,source_hash,payload,payload_hash,state,claim_generation,
      maintenance_lease_generation,fencing_token,credential_generation
    ) values (
      candidate.organization_id,binding.maintenance_principal_id,'RETENTION_DELETE','QUARANTINE',
      candidate.subject_id,candidate.policy_version||':'||candidate.scope_version,
      'retention:quarantine:'||candidate.subject_kind||':'||candidate.subject_id||':'
        ||candidate.policy_version||':'||candidate.scope_version,
      v_hash,v_payload,v_hash,'QUEUED',1,binding.lease_generation,
      binding.fencing_token,binding.credential_generation
    ) on conflict do nothing;
    get diagnostics v_inserted=row_count;
    v_created:=v_created+v_inserted;
  end loop;
  return v_created;
end;
$$;








--
-- Name: materialize_openclaw_schedule_work_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_openclaw_schedule_work_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := statement_timestamp();
  schedule record;
  v_occurrence_id uuid;
  v_status text;
  v_evidence jsonb;
  v_bytes bytea;
  v_hash text;
  v_next_local timestamp;
  v_next record;
  v_cell uuid;
  v_credential bigint;
  v_lease bigint;
  v_fence bigint;
  v_session bigint;
  v_snapshot_hash text;
  v_target_version bigint;
  v_target_directory_refreshed_at timestamptz;
  v_template_version uuid;
  v_knowledge_version_ids uuid[];
  v_payload jsonb;
  v_payload_bytes bytea;
  v_inserted integer;
  v_created integer := 0;
begin
  for schedule in
    select candidate_schedule.*
    from public.openclaw_schedules candidate_schedule
    where candidate_schedule.status='ACTIVE'
      and candidate_schedule.next_run_at is not null
      and candidate_schedule.next_run_at<=v_now
    order by candidate_schedule.next_run_at,candidate_schedule.id
    for update of candidate_schedule skip locked
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    if schedule.campaign_id is null or schedule.campaign_version_id is null
       or schedule.target_id is null then
      update public.openclaw_schedules set binding_defer_reason='CAMPAIGN_VERSION_REQUIRED',
        status='PAUSED',updated_at=v_now
      where organization_id=schedule.organization_id and id=schedule.id;
      continue;
    end if;

    v_status := case when v_now>schedule.next_run_at
      + make_interval(secs=>schedule.occurrence_grace_seconds)
      then 'SKIPPED_MISSED' else 'MATERIALIZED' end;
    v_cell:=null; v_credential:=null; v_lease:=null; v_fence:=null; v_session:=null;
    if v_status='MATERIALIZED' then
      select cell.id,credential.credential_generation,lease.lease_generation,
        lease.fencing_token,account.session_generation
      into v_cell,v_credential,v_lease,v_fence,v_session
      from public.openclaw_accounts account
      join public.openclaw_runtime_cells cell
        on cell.organization_id=account.organization_id and cell.account_id=account.id
       and cell.is_current and cell.state='READY'
      join public.openclaw_runtime_leases lease
        on lease.organization_id=cell.organization_id and lease.account_id=cell.account_id
       and lease.cell_id=cell.id and lease.status='ACTIVE' and lease.expires_at>v_now
      join public.openclaw_runtime_credentials credential
        on credential.organization_id=cell.organization_id and credential.account_id=cell.account_id
       and credential.cell_id=cell.id and credential.revoked_at is null
      where account.organization_id=schedule.organization_id and account.id=schedule.account_id
        and account.is_active
      order by lease.lease_generation desc,credential.credential_generation desc
      limit 1 for share of credential,lease;
      if v_cell is null then
        update public.openclaw_schedules set binding_defer_reason='NO_CURRENT_CHANNEL_BINDING',
          updated_at=v_now
        where organization_id=schedule.organization_id and id=schedule.id;
        continue;
      end if;
    end if;
    select snapshot.snapshot_hash,target.target_version,target.directory_refreshed_at,
      automation.content_version_id,automation.knowledge_version_ids
    into strict v_snapshot_hash,v_target_version,v_target_directory_refreshed_at,
      v_template_version,v_knowledge_version_ids
    from public.openclaw_schedule_snapshots snapshot
    join public.openclaw_targets target
      on target.organization_id=snapshot.organization_id and target.account_id=snapshot.account_id
     and target.id=snapshot.target_id
    join public.openclaw_automation_versions automation
      on automation.organization_id=snapshot.organization_id
     and automation.account_id=snapshot.account_id
     and automation.id=snapshot.automation_version_id
    where snapshot.organization_id=schedule.organization_id
      and snapshot.account_id=schedule.account_id and snapshot.schedule_id=schedule.id
      and snapshot.schedule_version=schedule.schedule_version
      and snapshot.campaign_version_id=schedule.campaign_version_id;
    v_evidence := jsonb_build_object(
      'version',1,'scheduleId',schedule.id,'scheduleVersion',schedule.schedule_version,
      'targetId',schedule.target_id,'plannedLocal',schedule.next_nominal_local,
      'resolvedLocal',schedule.next_resolved_local,'plannedFor',schedule.next_run_at,
      'utcOffsetSeconds',schedule.next_utc_offset_seconds,'resolution',schedule.next_resolution,
      'occurrenceStatus',v_status,'databaseTime',v_now
    );
    v_bytes := app_private.openclaw_jcs_bytes_v1(v_evidence);
    v_hash := encode(extensions.digest(
      convert_to('ihome-openclaw-schedule-occurrence-v1','UTF8')||decode('00','hex')||v_bytes,
      'sha256'),'hex');
    insert into public.openclaw_schedule_occurrences(
      organization_id,account_id,schedule_id,schedule_version,target_id,planned_local,
      resolved_local,planned_for,utc_offset_seconds,resolution,occurrence_status,
      occurrence_evidence,occurrence_evidence_bytes,occurrence_evidence_hash
    ) values (
      schedule.organization_id,schedule.account_id,schedule.id,schedule.schedule_version,
      schedule.target_id,schedule.next_nominal_local,schedule.next_resolved_local,
      schedule.next_run_at,schedule.next_utc_offset_seconds,schedule.next_resolution,
      v_status,v_evidence,v_bytes,v_hash
    ) on conflict (organization_id,account_id,schedule_id,schedule_version,planned_local)
      do nothing returning id into v_occurrence_id;
    if v_occurrence_id is null then
      select occurrence.id into strict v_occurrence_id
      from public.openclaw_schedule_occurrences occurrence
      where occurrence.organization_id=schedule.organization_id
        and occurrence.account_id=schedule.account_id and occurrence.schedule_id=schedule.id
        and occurrence.schedule_version=schedule.schedule_version
        and occurrence.planned_local=schedule.next_nominal_local;
    end if;

    if v_status='MATERIALIZED' then
        v_payload:=jsonb_build_object('kind','SCHEDULE_OCCURRENCE','scheduleId',schedule.id,
          'scheduleVersion',schedule.schedule_version,'occurrenceId',v_occurrence_id,
          'campaignVersionId',schedule.campaign_version_id,
          'automationVersionId',schedule.automation_version_id,'targetId',schedule.target_id,
          'targetVersion',v_target_version,
          'targetDirectoryRefreshedAt',v_target_directory_refreshed_at,
          'templateVersionId',v_template_version,
          'knowledgeVersionIds',to_jsonb(v_knowledge_version_ids),
          'eligibilityDecisionHash',v_hash);
        v_payload_bytes:=app_private.openclaw_jcs_bytes_v1(v_payload);
        insert into public.openclaw_send_work_items(
          organization_id,account_id,cell_id,work_kind,source_id,source_version,source_key,
          source_hash,payload,payload_hash,state,claim_generation,fencing_token,
          session_generation,target_id,credential_generation,runtime_lease_generation,
          schedule_id,schedule_version,schedule_occurrence_id,campaign_version_id
        ) values (
          schedule.organization_id,schedule.account_id,v_cell,'SCHEDULE_OCCURRENCE',
          v_occurrence_id,schedule.schedule_version::text,
          'schedule:'||schedule.id||':'||schedule.schedule_version||':'||v_occurrence_id||':'||schedule.target_id,
          v_snapshot_hash,v_payload,
          encode(extensions.digest(v_payload_bytes,'sha256'),'hex'),'QUEUED',1,v_fence,v_session,
          schedule.target_id,v_credential,v_lease,schedule.id,schedule.schedule_version,
          v_occurrence_id,schedule.campaign_version_id
        ) on conflict (organization_id,schedule_id,schedule_version,schedule_occurrence_id,target_id)
          where work_kind='SCHEDULE_OCCURRENCE' do nothing;
        get diagnostics v_inserted=row_count;
        v_created := v_created+v_inserted;
    end if;

    v_next_local := app_private.openclaw_next_schedule_occurrence_v1(
      schedule.local_recurrence_rule,schedule.next_nominal_local);
    if v_status='SKIPPED_MISSED' then
      while v_next_local is not null loop
        select * into strict v_next from app_private.openclaw_resolve_local_occurrence_v1(
          v_next_local,schedule.timezone,schedule.dst_fold_policy);
        exit when v_next.planned_for>v_now;
        v_evidence:=jsonb_build_object(
          'version',1,'scheduleId',schedule.id,'scheduleVersion',schedule.schedule_version,
          'targetId',schedule.target_id,'plannedLocal',v_next_local,
          'resolvedLocal',v_next.resolved_local,'plannedFor',v_next.planned_for,
          'utcOffsetSeconds',v_next.utc_offset_seconds,'resolution',v_next.resolution,
          'occurrenceStatus','SKIPPED_MISSED','databaseTime',v_now
        );
        v_bytes:=app_private.openclaw_jcs_bytes_v1(v_evidence);
        v_hash:=encode(extensions.digest(
          convert_to('ihome-openclaw-schedule-occurrence-v1','UTF8')||decode('00','hex')||v_bytes,
          'sha256'),'hex');
        insert into public.openclaw_schedule_occurrences(
          organization_id,account_id,schedule_id,schedule_version,target_id,planned_local,
          resolved_local,planned_for,utc_offset_seconds,resolution,occurrence_status,
          occurrence_evidence,occurrence_evidence_bytes,occurrence_evidence_hash
        ) values (
          schedule.organization_id,schedule.account_id,schedule.id,schedule.schedule_version,
          schedule.target_id,v_next_local,v_next.resolved_local,v_next.planned_for,
          v_next.utc_offset_seconds,v_next.resolution,'SKIPPED_MISSED',v_evidence,v_bytes,v_hash
        ) on conflict (organization_id,account_id,schedule_id,schedule_version,planned_local)
          do nothing;
        v_next_local := app_private.openclaw_next_schedule_occurrence_v1(
          schedule.local_recurrence_rule,v_next_local);
      end loop;
    elsif v_next_local is not null then
      select * into strict v_next from app_private.openclaw_resolve_local_occurrence_v1(
        v_next_local,schedule.timezone,schedule.dst_fold_policy);
    end if;
    if v_next_local is null then
      update public.openclaw_schedules current_schedule set
        next_nominal_local=null,next_resolved_local=null,next_run_at=null,
        next_utc_offset_seconds=null,next_resolution=null,
        cursor_version=current_schedule.cursor_version+1,
        binding_defer_reason=null,status='COMPLETE',updated_at=v_now
      where current_schedule.organization_id=schedule.organization_id
        and current_schedule.id=schedule.id
        and current_schedule.schedule_version=schedule.schedule_version;
    else
      update public.openclaw_schedules current_schedule set
        next_nominal_local=v_next_local,
        next_resolved_local=v_next.resolved_local,
        next_run_at=v_next.planned_for,
        next_utc_offset_seconds=v_next.utc_offset_seconds,
        next_resolution=v_next.resolution,
        cursor_version=current_schedule.cursor_version+1,
        binding_defer_reason=null,updated_at=v_now
      where current_schedule.organization_id=schedule.organization_id
        and current_schedule.id=schedule.id
        and current_schedule.schedule_version=schedule.schedule_version;
    end if;
  end loop;
  return v_created;
end;
$$;








--
-- Name: materialize_step_candidates_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.materialize_step_candidates_v1(p_request_step_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_step public.approval_request_steps;
  v_req public.approval_requests;
  v_gen integer;
  v_count integer;
  v_rule_step_id uuid;
begin
  select * into v_step from public.approval_request_steps
   where id = p_request_step_id for update;
  if not found then raise exception 'step not found' using errcode='P0002'; end if;

  select * into v_req from public.approval_requests
   where id = v_step.request_id;

  -- the approver spec is attached to the source rule step; the request step's
  -- snapshot carries that id.
  v_rule_step_id := nullif(v_step.rule_step_snapshot->>'rule_step_id','')::uuid;
  v_gen := v_step.current_generation + 1;

  -- F12 fix: take the org share-lock in a PRIOR statement before the resolver is
  -- evaluated as a scalar subquery below, so PERMISSION-type candidate matching
  -- reads a witness snapshot taken after any concurrent mutation's lock wait.
  perform app_private.lock_org_for_decision_v1(v_req.organization_id);

  -- close prior generation (valid_to set; history preserved)
  update public.approval_request_step_candidates
     set valid_to = clock_timestamp()
   where request_step_id = p_request_step_id
     and generation = v_step.current_generation
     and valid_to is null;

  -- materialize the union of all approver specs into distinct memberships,
  -- excluding the maker (a maker can never be their own checker candidate).
  insert into public.approval_request_step_candidates
    (organization_id, request_step_id, membership_id, generation,
     source_kind, source_id, eligible_at_submit, valid_from)
  select distinct on (m.id)
    v_req.organization_id, p_request_step_id, m.id, v_gen,
    sa.approver_type, sa.id, true, clock_timestamp()
  from public.approval_step_approvers sa
  join public.organization_memberships m
    on m.organization_id = v_req.organization_id and m.status = 'ACTIVE'
  where sa.step_id = v_rule_step_id
    -- M10 fix: exclude the maker by BOTH membership AND user_id (a maker with a
    -- second ACTIVE membership must not inflate candidate_count or self-approve).
    and m.id <> v_req.maker_membership_id
    and m.user_id <> v_req.maker_user_id
    and (
      -- MEMBER: the exact membership
      (sa.approver_type = 'MEMBER' and sa.membership_id = m.id)
      -- ROLE: any member bound to the role (nonlegacy binding, active)
      or (sa.approver_type = 'ROLE' and exists (
        select 1 from public.role_bindings rb
         where rb.organization_id = v_req.organization_id
           and rb.membership_id = m.id and rb.role_id = sa.role_id
           and coalesce(rb.valid_from,'-infinity') <= clock_timestamp()
           and (rb.valid_to is null or rb.valid_to > clock_timestamp())))
      -- PERMISSION: any member the T2 resolver would ALLOW for the permission
      or (sa.approver_type = 'PERMISSION' and (
        select allowed from app_private.authorize_tenant_action_v3(
          m.user_id, v_req.organization_id, sa.permission_key,
          v_req.building_id, v_req.cashbook_id)))
      -- CASHBOOK_APPROVER: holds possession on the request cashbook
      or (sa.approver_type = 'CASHBOOK_APPROVER' and v_req.cashbook_id is not null
          and exists (
        select 1 from public.cashbook_possession_bindings cp
         where cp.organization_id = v_req.organization_id
           and cp.cashbook_id = v_req.cashbook_id and cp.membership_id = m.id
           and cp.valid_from <= clock_timestamp()
           and (cp.valid_to is null or cp.valid_to > clock_timestamp())))
      -- BUILDING_APPROVER: role binding scoped to the request building
      or (sa.approver_type = 'BUILDING_APPROVER' and v_req.building_id is not null
          and exists (
        select 1 from public.role_bindings rb
         join public.role_binding_scopes rbs
           on rbs.organization_id = rb.organization_id and rbs.role_binding_id = rb.id
         join public.authorization_scopes s
           on s.organization_id = rbs.organization_id and s.id = rbs.scope_id
         where rb.organization_id = v_req.organization_id and rb.membership_id = m.id
           and s.scope_type = 'BUILDING' and s.building_id = v_req.building_id))
      -- AREA_APPROVER: role binding scoped to an area covering the building
      or (sa.approver_type = 'AREA_APPROVER' and v_req.building_id is not null
          and exists (
        select 1 from public.role_bindings rb
         join public.role_binding_scopes rbs
           on rbs.organization_id = rb.organization_id and rbs.role_binding_id = rb.id
         join public.authorization_scopes s
           on s.organization_id = rbs.organization_id and s.id = rbs.scope_id
         join public.area_buildings ab
           on ab.organization_id = s.organization_id and ab.area_id = s.area_id
         where rb.organization_id = v_req.organization_id and rb.membership_id = m.id
           and s.scope_type = 'AREA' and ab.building_id = v_req.building_id))
    );
  get diagnostics v_count = row_count;

  update public.approval_request_steps
     set current_generation = v_gen, candidate_count = v_count
   where id = p_request_step_id;

  -- fail-closed: no candidate, or quorum impossible
  if v_count = 0 then
    raise exception 'step % has zero eligible candidates', p_request_step_id
      using errcode='55000';
  end if;
  if v_step.mode = 'ALL' and v_step.min_approvals <> v_count then
    -- ALL requires min = candidate_count; adjust or fail. We fail-closed so
    -- the rule author must reconcile min_approvals with the ALL semantics.
    raise exception 'ALL-mode step % min_approvals % <> candidate_count %',
      p_request_step_id, v_step.min_approvals, v_count using errcode='55000';
  end if;
  if v_step.mode = 'QUORUM' and v_step.min_approvals > v_count then
    raise exception 'QUORUM step % needs % approvals but only % candidates',
      p_request_step_id, v_step.min_approvals, v_count using errcode='55000';
  end if;

  return v_count;
end;
$$;








--
-- Name: my_possessed_cashbook_ids_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.my_possessed_cashbook_ids_v1() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT b.cashbook_id
  FROM public.cashbook_possession_bindings b
  JOIN public.organization_memberships m ON m.id = b.membership_id
  WHERE m.user_id = auth.uid()
    AND m.status = 'ACTIVE'
    AND b.valid_from <= now()
    AND (b.valid_to IS NULL OR b.valid_to > now());
$$;








--
-- Name: network_center_append_user_audit_v1(uuid, uuid, uuid, text, text, uuid, jsonb, text, jsonb, jsonb, text, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_append_user_audit_v1(p_organization_id uuid, p_building_id uuid, p_actor_id uuid, p_action text, p_target_type text, p_target_id uuid, p_target_display jsonb, p_reason text, p_validation jsonb, p_result jsonb, p_outcome text, p_command_id uuid, p_request_id uuid, p_request_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.network_audit_events (
    organization_id, building_id, actor_type, actor_id, action, target_type,
    target_id, target_display, reason, validation, result, outcome, command_id,
    request_id, request_hash
  ) VALUES (
    p_organization_id, p_building_id, 'USER', p_actor_id, p_action,
    p_target_type, p_target_id, p_target_display, p_reason,
    coalesce(p_validation, '{}'::jsonb), coalesce(p_result, '{}'::jsonb),
    p_outcome, p_command_id, p_request_id, p_request_hash
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;








--
-- Name: network_center_aruba_retention_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_aruba_retention_v1(p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_organization record;
  v_router record;
  v_count bigint;
  v_stale bigint := 0;
  v_inactive bigint := 0;
  v_pinned bigint := 0;
  v_purged bigint := 0;
  v_candidates bigint := 0;
  v_aliases_tombstoned bigint := 0;
  v_aliases bigint := 0;
  v_quarantine bigint := 0;
  v_runs bigint := 0;
BEGIN
  IF p_now IS NULL THEN
    RAISE EXCEPTION 'Aruba retention timestamp is required'
      USING ERRCODE = '22023';
  END IF;

  FOR v_organization IN
    SELECT DISTINCT device.organization_id
    FROM public.network_devices device
    WHERE device.device_kind = 'ARUBA'
    UNION
    SELECT candidate.organization_id
    FROM app_private.network_aruba_discovery_candidates candidate
    UNION
    SELECT alias.organization_id
    FROM app_private.network_aruba_aliases alias
    UNION
    SELECT quarantine.organization_id
    FROM app_private.network_aruba_quarantine quarantine
    UNION
    SELECT run.organization_id
    FROM app_private.network_aruba_discovery_runs run
    ORDER BY organization_id
  LOOP
    WITH victims AS MATERIALIZED (
      SELECT device.id
      FROM public.network_devices device
      WHERE device.organization_id = v_organization.organization_id
        AND device.device_kind = 'ARUBA'
        AND device.is_active
        AND device.lifecycle_status <> 'STALE'
        AND device.aruba_discovery_last_seen_at < p_now - INTERVAL '24 hours'
      ORDER BY device.aruba_discovery_last_seen_at, device.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    UPDATE public.network_devices device
    SET lifecycle_status = 'STALE', updated_at = clock_timestamp()
    FROM victims
    WHERE device.id = victims.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_stale := v_stale + v_count;

    WITH victims AS MATERIALIZED (
      SELECT device.id
      FROM public.network_devices device
      WHERE device.organization_id = v_organization.organization_id
        AND device.device_kind = 'ARUBA'
        AND device.is_active
        AND device.aruba_discovery_last_seen_at < p_now - INTERVAL '7 days'
      ORDER BY device.aruba_discovery_last_seen_at, device.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    UPDATE public.network_devices device
    SET is_active = false, lifecycle_status = 'STALE',
        updated_at = clock_timestamp()
    FROM victims
    WHERE device.id = victims.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_inactive := v_inactive + v_count;

    UPDATE public.network_devices device
    SET aruba_discovery_state = 'PINNED', updated_at = clock_timestamp()
    WHERE device.organization_id = v_organization.organization_id
      AND device.device_kind = 'ARUBA'
      AND device.aruba_discovery_state = 'DISCOVERED'
      AND (
        EXISTS (
          SELECT 1 FROM public.network_devices child
          WHERE child.parent_device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_device_connections connection
          WHERE connection.device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_desired_state_versions desired
          WHERE desired.router_device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_client_sessions session
          WHERE session.device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_incidents incident
          WHERE incident.device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_commands command
          WHERE command.device_id = device.id
        )
        OR EXISTS (
          SELECT 1 FROM public.network_config_snapshots snapshot
          WHERE snapshot.device_id = device.id
        )
      );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_pinned := v_pinned + v_count;

    WITH victims AS MATERIALIZED (
      SELECT alias.router_device_id, alias.stable_key, alias.alias
      FROM app_private.network_aruba_aliases alias
      WHERE alias.organization_id = v_organization.organization_id
        AND alias.tombstoned_at IS NULL
        AND alias.last_seen_at < p_now - INTERVAL '30 days'
        AND NOT EXISTS (
          SELECT 1
          FROM public.network_devices device
          WHERE device.parent_device_id = alias.router_device_id
            AND device.device_kind = 'ARUBA'
            AND device.aruba_stable_key = alias.stable_key
            AND device.aruba_discovery_last_seen_at >=
              p_now - INTERVAL '30 days'
        )
        AND NOT EXISTS (
          SELECT 1
          FROM app_private.network_aruba_discovery_candidates candidate
          WHERE candidate.router_device_id = alias.router_device_id
            AND candidate.stable_key = alias.stable_key
            AND candidate.last_seen_at >= p_now - INTERVAL '30 days'
        )
      ORDER BY alias.last_seen_at, alias.router_device_id,
               alias.stable_key, alias.alias
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    UPDATE app_private.network_aruba_aliases alias
    SET tombstoned_at = p_now
    FROM victims
    WHERE alias.router_device_id = victims.router_device_id
      AND alias.stable_key = victims.stable_key
      AND alias.alias = victims.alias;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_aliases_tombstoned := v_aliases_tombstoned + v_count;

    WITH victims AS MATERIALIZED (
      SELECT candidate.router_device_id, candidate.stable_key
      FROM app_private.network_aruba_discovery_candidates candidate
      WHERE candidate.organization_id = v_organization.organization_id
        AND candidate.last_seen_at < p_now - INTERVAL '30 days'
      ORDER BY candidate.last_seen_at, candidate.router_device_id,
               candidate.stable_key
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM app_private.network_aruba_discovery_candidates candidate
    USING victims
    WHERE candidate.router_device_id = victims.router_device_id
      AND candidate.stable_key = victims.stable_key;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_candidates := v_candidates + v_count;

    WITH victims AS MATERIALIZED (
      SELECT device.id
      FROM public.network_devices device
      WHERE device.organization_id = v_organization.organization_id
        AND device.device_kind = 'ARUBA'
        AND device.aruba_discovery_state = 'DISCOVERED'
        AND device.aruba_discovery_last_seen_at < p_now - INTERVAL '30 days'
      ORDER BY device.aruba_discovery_last_seen_at, device.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM public.network_devices device
    USING victims
    WHERE device.id = victims.id
      AND device.aruba_discovery_state = 'DISCOVERED';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_purged := v_purged + v_count;

    WITH victims AS MATERIALIZED (
      SELECT alias.router_device_id, alias.stable_key, alias.alias
      FROM app_private.network_aruba_aliases alias
      WHERE alias.organization_id = v_organization.organization_id
        AND alias.tombstoned_at < p_now - INTERVAL '90 days'
      ORDER BY alias.tombstoned_at, alias.router_device_id,
               alias.stable_key, alias.alias
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM app_private.network_aruba_aliases alias
    USING victims
    WHERE alias.router_device_id = victims.router_device_id
      AND alias.stable_key = victims.stable_key
      AND alias.alias = victims.alias;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_aliases := v_aliases + v_count;

    WITH victims AS MATERIALIZED (
      SELECT quarantine.id
      FROM app_private.network_aruba_quarantine quarantine
      WHERE quarantine.organization_id = v_organization.organization_id
        AND quarantine.observed_at < p_now - INTERVAL '7 days'
      ORDER BY quarantine.observed_at, quarantine.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM app_private.network_aruba_quarantine quarantine
    USING victims
    WHERE quarantine.id = victims.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_quarantine := v_quarantine + v_count;

    FOR v_router IN
      SELECT DISTINCT quarantine.router_device_id
      FROM app_private.network_aruba_quarantine quarantine
      WHERE quarantine.organization_id = v_organization.organization_id
      ORDER BY quarantine.router_device_id
    LOOP
      WITH bounded AS MATERIALIZED (
        SELECT quarantine.id, quarantine.observed_at
        FROM app_private.network_aruba_quarantine quarantine
        WHERE quarantine.router_device_id = v_router.router_device_id
        ORDER BY quarantine.observed_at DESC, quarantine.id DESC
        LIMIT 2000
      ), ranked AS MATERIALIZED (
        SELECT bounded.id,
               row_number() OVER (
                 ORDER BY bounded.observed_at DESC, bounded.id DESC
               ) AS keep_rank
        FROM bounded
      ), victims AS (
        SELECT ranked.id
        FROM ranked
        WHERE ranked.keep_rank > 1000
        ORDER BY ranked.keep_rank DESC
        LIMIT 1000
      )
      DELETE FROM app_private.network_aruba_quarantine quarantine
      USING victims
      WHERE quarantine.id = victims.id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      v_quarantine := v_quarantine + v_count;
    END LOOP;

    WITH victims AS MATERIALIZED (
      SELECT run.discovery_run_id
      FROM app_private.network_aruba_discovery_runs run
      WHERE run.organization_id = v_organization.organization_id
        AND run.created_at < p_now - INTERVAL '7 days'
      ORDER BY run.created_at, run.discovery_run_id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM app_private.network_aruba_discovery_runs run
    USING victims
    WHERE run.discovery_run_id = victims.discovery_run_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_runs := v_runs + v_count;
  END LOOP;

  RETURN jsonb_build_object(
    'aruba_stale_marked', v_stale,
    'aruba_inactive_marked', v_inactive,
    'aruba_devices_pinned', v_pinned,
    'aruba_devices_purged', v_purged,
    'aruba_candidates_deleted', v_candidates,
    'aruba_aliases_tombstoned', v_aliases_tombstoned,
    'aruba_aliases_deleted', v_aliases,
    'aruba_quarantine_deleted', v_quarantine,
    'aruba_runs_deleted', v_runs,
    'aruba_stale_hours', 24,
    'aruba_inactive_days', 7,
    'aruba_discovery_retention_days', 30,
    'aruba_candidate_retention_days', 30,
    'aruba_alias_retention_days', 90,
    'aruba_quarantine_retention_days', 7,
    'aruba_quarantine_per_router', 1000
  );
END;
$$;








--
-- Name: network_center_assert_safe_json_v1(jsonb, text, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_assert_safe_json_v1(p_value jsonb, p_context text DEFAULT 'Network Center payload'::text, p_depth integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_key text;
  v_child jsonb;
  v_text text;
  v_sensitive_key boolean;
  v_redacted boolean;
BEGIN
  IF p_value IS NULL THEN
    RETURN;
  END IF;
  IF p_depth > 32 THEN
    RAISE EXCEPTION 'Unsafe or over-nested %', left(coalesce(p_context, 'Network Center payload'), 80)
      USING ERRCODE = '22023';
  END IF;

  CASE jsonb_typeof(p_value)
    WHEN 'object' THEN
      FOR v_key, v_child IN SELECT entry.key, entry.value FROM jsonb_each(p_value) entry
      LOOP
        v_sensitive_key := lower(v_key) ~
          '(^|[^a-z0-9])(password|passwd|secret|private.?key|preshared.?key|authorization|cookie|credential(ref)?|access.?token|refresh.?token|service.?role|lease.?token|artifact.?key)($|[^a-z0-9])';
        v_redacted := jsonb_typeof(v_child) = 'string'
          AND (v_child #>> '{}') ~* '^(\[?redacted\]?|<redacted>|\*{3,})$';
        IF v_sensitive_key AND NOT v_redacted THEN
          RAISE EXCEPTION 'Sensitive key is not redacted in %',
            left(coalesce(p_context, 'Network Center payload'), 80)
            USING ERRCODE = '22023';
        END IF;
        PERFORM app_private.network_center_assert_safe_json_v1(
          v_child, p_context, p_depth + 1
        );
      END LOOP;
    WHEN 'array' THEN
      FOR v_child IN SELECT element.value FROM jsonb_array_elements(p_value) element
      LOOP
        PERFORM app_private.network_center_assert_safe_json_v1(
          v_child, p_context, p_depth + 1
        );
      END LOOP;
    WHEN 'string' THEN
      v_text := p_value #>> '{}';
      IF v_text ~* '-----BEGIN[[:space:]][A-Z0-9 _-]*PRIVATE KEY-----'
         OR v_text ~* '(^|[^A-Za-z0-9_-])Bearer[[:space:]]+[A-Za-z0-9._~+/=-]{16,}'
         OR v_text ~ '(^|[^A-Za-z0-9_-])eyJ[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{8,}'
         OR (
           v_text ~* '(password|passwd|secret|private[-_ ]?key|preshared[-_ ]?key|token)[[:space:]]*[:=]'
           AND v_text !~* '(password|passwd|secret|private[-_ ]?key|preshared[-_ ]?key|token)[[:space:]]*[:=][[:space:]]*"?((\[?redacted\]?)|(<redacted>)|(\*{3,}))"?'
         ) THEN
        RAISE EXCEPTION 'Sensitive value is not redacted in %',
          left(coalesce(p_context, 'Network Center payload'), 80)
          USING ERRCODE = '22023';
      END IF;
    ELSE
      NULL;
  END CASE;
END;
$_$;








--
-- Name: network_center_authenticate_worker_v2(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_authenticate_worker_v2(p_secret_digest text) RETURNS TABLE(worker_id uuid, worker_key text, worker_status text, capabilities text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_credential_id uuid;
BEGIN
  IF p_secret_digest IS NULL
     OR p_secret_digest !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Worker authentication failed' USING ERRCODE = '28000';
  END IF;

  SELECT
    worker.id,
    worker.worker_key,
    worker.status,
    worker.capabilities,
    credential.id
  INTO
    worker_id,
    worker_key,
    worker_status,
    capabilities,
    v_credential_id
  FROM public.network_worker_credentials credential
  JOIN public.network_workers worker ON worker.id = credential.worker_id
  WHERE credential.secret_digest = p_secret_digest::character(64)
    AND credential.revoked_at IS NULL
    AND credential.not_before <= v_now
    AND credential.expires_at > v_now
    AND worker.status IN ('ACTIVE', 'DRAINING');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker authentication failed' USING ERRCODE = '28000';
  END IF;

  UPDATE public.network_worker_credentials credential
  SET last_used_at = v_now
  WHERE credential.id = v_credential_id
    AND (
      credential.last_used_at IS NULL
      OR credential.last_used_at < v_now - INTERVAL '5 minutes'
    );

  RETURN NEXT;
END;
$_$;








--
-- Name: network_center_bind_managed_interface_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_bind_managed_interface_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_immutable_key text;
  v_resource_id uuid;
  v_safe_access boolean;
  v_role text;
  v_protected boolean;
  v_state text;
BEGIN
  v_immutable_key := nullif(btrim(
    coalesce(NEW.display_metadata->>'immutableKey', '')
  ), '');
  IF v_immutable_key IS NULL THEN
    IF (TG_OP = 'UPDATE' AND OLD.managed_resource_id IS NOT NULL)
       OR NEW.managed_resource_id IS NOT NULL THEN
      RAISE EXCEPTION 'Managed interface immutable identity cannot be removed'
        USING ERRCODE = '55000';
    END IF;
    NEW.is_managed := false;
    RETURN NEW;
  END IF;
  IF v_immutable_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'
     OR NOT EXISTS (
       SELECT 1
       FROM public.network_devices device
       WHERE device.organization_id = NEW.organization_id
         AND device.building_id = NEW.building_id
         AND device.id = NEW.device_id
         AND device.device_kind = 'MIKROTIK'
     ) THEN
    RAISE EXCEPTION 'Invalid managed interface identity'
      USING ERRCODE = '22023';
  END IF;
  IF NEW.interface_key IS DISTINCT FROM v_immutable_key
     OR (
       TG_OP = 'UPDATE'
       AND OLD.managed_resource_id IS NOT NULL
       AND (
         OLD.interface_key IS DISTINCT FROM v_immutable_key
         OR NEW.managed_resource_id IS DISTINCT FROM OLD.managed_resource_id
       )
     ) THEN
    RAISE EXCEPTION 'Managed interface immutable identity cannot be rebound'
      USING ERRCODE = '55000';
  END IF;

  IF lower(v_immutable_key) = 'ether1' THEN
    NEW.interface_role := 'WAN';
    NEW.is_protected := true;
  END IF;
  -- =====================================================================
  -- ELIGIBILITY MUST NOT READ THIS TRIGGER'S OWN OUTPUT (20260729148000).
  --
  -- The rule is unchanged in intent and is deliberately NOT relaxed: a
  -- physical ethernet access port, ether2..N, that the worker does NOT
  -- report as protected. What changes is where the last term is read from.
  --
  -- It used to compare NEW.is_protected against false. On the INSERT pass
  -- that is the worker's report and the test is right; but this trigger runs
  -- TWICE per interface per inventory cycle, because ON CONFLICT fires the
  -- BEFORE INSERT trigger before it detects the conflict and then uses the
  -- row that trigger returned as EXCLUDED. The last statement of this
  -- function forces NEW.is_protected true for every DISCOVERED resource, so
  -- on the UPDATE pass the test was reading back the value it had itself
  -- just produced, and metadata.eligibleAccess went false on the second poll
  -- cycle and stayed false forever -- destroying the one precondition
  -- app_private.network_center_enroll_access_interface_v1 needs. Measured in
  -- production 2026-08-03: eligibleAccess = 'false' on all five managed
  -- resources, refreshed every 60 seconds. The act of discovering a port
  -- destroyed the precondition for enrolling it.
  --
  -- observedProtection is stamped into display_metadata by the ingest,
  -- straight from the payload, and nothing in this function writes it -- so
  -- it survives both passes unchanged and still carries the signal that
  -- matters: the worker marks a port protected when an owned `:lan-recovery`
  -- firewall rule names it (routerOsRecoveryInterfaceNames), and such a port
  -- must not become enrollable however ordinary its shape looks. The
  -- coalesce keeps the previous behaviour for any row not written by the
  -- ingest, which is fail-closed on an UPDATE because NEW.is_protected is
  -- true there.
  -- =====================================================================
  v_safe_access := NEW.interface_kind = 'ETHERNET'
    AND NEW.interface_role = 'ACCESS'
    AND NOT coalesce(
      (NEW.display_metadata->>'observedProtection')::boolean,
      NEW.is_protected
    )
    AND v_immutable_key ~* '^ether([2-9]|[1-9][0-9])$';
  v_role := NEW.interface_role;
  v_protected := true;
  v_state := CASE WHEN lower(v_immutable_key) = 'ether1'
    THEN 'ENROLLED' ELSE 'DISCOVERED' END;

  INSERT INTO public.network_managed_resources (
    organization_id, building_id, device_id, resource_kind,
    stable_key, display_name, enrolled_role, protected,
    ownership_marker, enrollment_state, last_verified_at,
    metadata
  ) VALUES (
    NEW.organization_id, NEW.building_id, NEW.device_id, 'INTERFACE',
    v_immutable_key, NEW.display_name, v_role, v_protected,
    'routeros-default-name', v_state, clock_timestamp(),
    jsonb_build_object(
      'source', 'routeros-inventory',
      'eligibleAccess', v_safe_access
    )
  )
  ON CONFLICT (device_id, resource_kind, stable_key) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    enrolled_role = CASE
      WHEN public.network_managed_resources.enrollment_state = 'DISCOVERED'
        THEN EXCLUDED.enrolled_role
      ELSE public.network_managed_resources.enrolled_role
    END,
    protected = CASE
      WHEN public.network_managed_resources.enrollment_state = 'ENROLLED'
        THEN public.network_managed_resources.protected
          OR coalesce((EXCLUDED.metadata->>'eligibleAccess')::boolean, false) = false
      ELSE public.network_managed_resources.protected OR EXCLUDED.protected
    END,
    enrollment_state = CASE
      WHEN public.network_managed_resources.enrollment_state = 'REVOKED'
        THEN 'REVOKED'
      ELSE public.network_managed_resources.enrollment_state
    END,
    last_verified_at = EXCLUDED.last_verified_at,
    metadata = public.network_managed_resources.metadata
      || EXCLUDED.metadata
  RETURNING id, enrolled_role, protected, enrollment_state
  INTO v_resource_id, v_role, v_protected, v_state;

  NEW.interface_key := v_immutable_key;
  NEW.managed_resource_id := v_resource_id;
  NEW.is_managed := true;
  NEW.is_protected := NEW.is_protected OR v_protected;
  NEW.interface_role := v_role;
  NEW.display_metadata := NEW.display_metadata
    || jsonb_build_object('immutableKey', v_immutable_key);
  RETURN NEW;
END;
$_$;








--
-- Name: network_center_claim_commands_v1(text, integer, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_claim_commands_v1(p_worker_id text, p_limit integer DEFAULT 5, p_lease_seconds integer DEFAULT 90) RETURNS TABLE(command_id uuid, organization_id uuid, building_id uuid, device_id uuid, interface_id uuid, action_type text, reason text, sanitized_parameters jsonb, attempt_no integer, lease_token uuid, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  -- An attempt still has to record PRE_ACTION, drive the router and record
  -- POST_ACTION. Claiming a command whose window closes inside this margin
  -- guarantees a real router mutation whose result can never be written down.
  c_claim_min_remaining constant interval := INTERVAL '5 seconds';
  v_now timestamptz := clock_timestamp();
BEGIN
  p_worker_id := btrim(coalesce(p_worker_id, ''));
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_limit NOT BETWEEN 1 AND 20
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid command claim request' USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.network_center_reclaim_expired_commands_v1(v_now);
  PERFORM app_private.network_center_sweep_expired_commands_v1(v_now);

  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT
      command.id,
      command.organization_id,
      command.building_id,
      command.device_id,
      gen_random_uuid() AS token
    FROM public.network_commands command
    WHERE command.status IN ('QUEUED', 'RETRY_WAIT')
      AND command.available_at <= v_now
      AND command.attempt_count < command.max_attempts
      AND command.observation_deadline > v_now + c_claim_min_remaining
      AND NOT app_private.network_center_org_mutations_paused_v1(
        command.organization_id
      )
      AND (
        command.action_type = 'CAPTURE_SNAPSHOT'
        OR EXISTS (
          SELECT 1
          FROM public.network_site_settings settings
          WHERE settings.organization_id = command.organization_id
            AND settings.building_id = command.building_id
            AND NOT settings.changes_paused
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_device_leases lease
        WHERE lease.device_id = command.device_id
          AND lease.expires_at > v_now
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_commands unresolved
        WHERE unresolved.device_id = command.device_id
          AND unresolved.status = 'UNCERTAIN'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_commands earlier
        WHERE earlier.device_id = command.device_id
          AND earlier.status IN ('QUEUED', 'RETRY_WAIT')
          AND earlier.available_at <= v_now
          AND earlier.attempt_count < earlier.max_attempts
          AND earlier.observation_deadline > v_now + c_claim_min_remaining
          AND (
            earlier.priority > command.priority
            OR (
              earlier.priority = command.priority
              AND ROW(earlier.available_at, earlier.created_at, earlier.id)
                  < ROW(command.available_at, command.created_at, command.id)
            )
          )
      )
    ORDER BY
      command.priority DESC, command.available_at, command.created_at,
      command.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  leased AS (
    INSERT INTO public.network_device_leases (
      device_id, organization_id, building_id, command_id, lease_token,
      lease_owner, acquired_at, heartbeat_at, expires_at, generation
    )
    SELECT
      candidate.device_id,
      candidate.organization_id,
      candidate.building_id,
      candidate.id,
      candidate.token,
      p_worker_id,
      v_now,
      v_now,
      v_now + make_interval(secs => p_lease_seconds),
      1
    FROM candidates candidate
    ON CONFLICT ON CONSTRAINT network_device_leases_pkey DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      building_id = EXCLUDED.building_id,
      command_id = EXCLUDED.command_id,
      lease_token = EXCLUDED.lease_token,
      lease_owner = EXCLUDED.lease_owner,
      acquired_at = EXCLUDED.acquired_at,
      heartbeat_at = EXCLUDED.heartbeat_at,
      expires_at = EXCLUDED.expires_at,
      generation = public.network_device_leases.generation + 1
    WHERE public.network_device_leases.expires_at <= v_now
    RETURNING
      public.network_device_leases.device_id,
      public.network_device_leases.command_id,
      public.network_device_leases.lease_token,
      public.network_device_leases.expires_at
  ),
  claimed AS (
    UPDATE public.network_commands command
    SET
      status = 'LEASED',
      lease_token = lease.lease_token,
      lease_owner = p_worker_id,
      lease_expires_at = lease.expires_at,
      attempt_count = command.attempt_count + 1,
      started_at = coalesce(command.started_at, v_now),
      updated_at = v_now
    FROM leased lease
    WHERE command.id = lease.command_id
    RETURNING command.*
  ),
  attempts AS (
    INSERT INTO public.network_command_attempts (
      organization_id, building_id, command_id, device_id, attempt_no,
      worker_id, lease_token, outcome, started_at
    )
    SELECT
      claimed.organization_id,
      claimed.building_id,
      claimed.id,
      claimed.device_id,
      claimed.attempt_count,
      p_worker_id,
      claimed.lease_token,
      'STARTED',
      v_now
    FROM claimed
    RETURNING
      public.network_command_attempts.id,
      public.network_command_attempts.organization_id,
      public.network_command_attempts.building_id,
      public.network_command_attempts.command_id
  ),
  events AS (
    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    )
    SELECT
      attempts.organization_id,
      attempts.building_id,
      attempts.command_id,
      attempts.id,
      coalesce((
        SELECT max(existing_event.event_seq) + 1
        FROM public.network_command_events existing_event
        WHERE existing_event.command_id = attempts.command_id
      ), 1),
      'LEASED',
      v_now,
      p_worker_id,
      jsonb_build_object(
        'attemptNo', claimed.attempt_count,
        'leaseExpiresAt', claimed.lease_expires_at
      )
    FROM claimed
    JOIN attempts ON attempts.command_id = claimed.id
    RETURNING public.network_command_events.command_id
  )
  SELECT
    claimed.id,
    claimed.organization_id,
    claimed.building_id,
    claimed.device_id,
    claimed.interface_id,
    claimed.action_type,
    claimed.reason,
    claimed.sanitized_parameters,
    claimed.attempt_count,
    claimed.lease_token,
    claimed.lease_expires_at
  FROM claimed
  JOIN attempts ON attempts.command_id = claimed.id
  JOIN events ON events.command_id = claimed.id
  ORDER BY claimed.priority DESC, claimed.created_at, claimed.id;
END;
$_$;








--
-- Name: network_center_claim_reconciliation_v1(text, integer, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_claim_reconciliation_v1(p_worker_id text, p_limit integer DEFAULT 5, p_lease_seconds integer DEFAULT 90) RETURNS TABLE(command_id uuid, organization_id uuid, building_id uuid, device_id uuid, interface_id uuid, action_type text, reason text, sanitized_parameters jsonb, attempt_no integer, lease_token uuid, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  c_claim_min_remaining constant interval := INTERVAL '5 seconds';
  c_max_reconciliation_attempts constant integer := 3;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_limit NOT BETWEEN 1 AND 20
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid reconciliation claim request'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT command.*, gen_random_uuid() AS new_token
    FROM public.network_commands command
    WHERE command.status = 'UNCERTAIN'
      AND command.reconciliation_state = 'REQUIRED'
      AND command.observation_deadline > v_now + c_claim_min_remaining
      AND command.reconciliation_attempt_count < c_max_reconciliation_attempts
      AND NOT app_private.network_center_org_mutations_paused_v1(
        command.organization_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_device_leases lease
        WHERE lease.device_id = command.device_id
          AND lease.expires_at > v_now
      )
    ORDER BY command.updated_at, command.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  leases AS (
    INSERT INTO public.network_device_leases (
      device_id, organization_id, building_id, command_id, lease_token,
      lease_owner, acquired_at, heartbeat_at, expires_at, generation
    )
    SELECT
      candidate.device_id, candidate.organization_id, candidate.building_id,
      candidate.id, candidate.new_token, p_worker_id, v_now, v_now,
      v_now + make_interval(secs => p_lease_seconds), 1
    FROM candidates candidate
    ON CONFLICT ON CONSTRAINT network_device_leases_pkey DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      building_id = EXCLUDED.building_id,
      command_id = EXCLUDED.command_id,
      lease_token = EXCLUDED.lease_token,
      lease_owner = EXCLUDED.lease_owner,
      acquired_at = EXCLUDED.acquired_at,
      heartbeat_at = EXCLUDED.heartbeat_at,
      expires_at = EXCLUDED.expires_at,
      generation = public.network_device_leases.generation + 1
    WHERE public.network_device_leases.expires_at <= v_now
    RETURNING public.network_device_leases.*
  ),
  claimed AS (
    UPDATE public.network_commands command
    SET
      status = 'RECONCILING',
      reconciliation_state = 'IN_PROGRESS',
      reconciliation_attempt_count = command.reconciliation_attempt_count + 1,
      lease_token = lease.lease_token,
      lease_owner = p_worker_id,
      lease_expires_at = lease.expires_at,
      updated_at = v_now
    FROM leases lease
    WHERE command.id = lease.command_id
    RETURNING command.*
  ),
  events AS (
    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    )
    SELECT
      claimed.organization_id, claimed.building_id, claimed.id,
      (
        SELECT attempt.id
        FROM public.network_command_attempts attempt
        WHERE attempt.command_id = claimed.id
        ORDER BY attempt.attempt_no DESC
        LIMIT 1
      ),
      coalesce((
        SELECT max(event.event_seq) + 1
        FROM public.network_command_events event
        WHERE event.command_id = claimed.id
      ), 1),
      'RECONCILIATION_STARTED', v_now, p_worker_id,
      jsonb_build_object(
        'leaseExpiresAt', claimed.lease_expires_at,
        'reconciliationAttempt', claimed.reconciliation_attempt_count
      )
    FROM claimed
    RETURNING public.network_command_events.command_id
  )
  SELECT
    claimed.id, claimed.organization_id, claimed.building_id,
    claimed.device_id, claimed.interface_id, claimed.action_type,
    claimed.reason, claimed.sanitized_parameters, claimed.attempt_count,
    claimed.lease_token, claimed.lease_expires_at
  FROM claimed
  JOIN events ON events.command_id = claimed.id;
END;
$_$;








--
-- Name: network_center_compact_client_history_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_compact_client_history_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_entry jsonb;
  v_result jsonb := '[]'::jsonb;
  v_count integer := 0;
BEGIN
  IF NEW.address_history IS NULL
     OR jsonb_typeof(NEW.address_history) <> 'array' THEN
    RAISE EXCEPTION 'Client address history must be an array'
      USING ERRCODE = '22023';
  END IF;

  FOR v_entry IN
    SELECT item.value
    FROM jsonb_array_elements(NEW.address_history)
      WITH ORDINALITY AS item(value, ordinal)
    ORDER BY item.ordinal DESC
  LOOP
    EXIT WHEN v_count >= 16;
    IF NOT v_result @> jsonb_build_array(v_entry) THEN
      v_result := jsonb_build_array(v_entry) || v_result;
      v_count := v_count + 1;
    END IF;
  END LOOP;

  NEW.address_history := v_result;
  RETURN NEW;
END;
$$;








--
-- Name: network_center_compatibility_can_access_device_v1(uuid, uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_compatibility_can_access_device_v1(p_worker_id uuid, p_organization_id uuid, p_building_id uuid, p_device_id uuid, p_required_capability text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM 1
  FROM app_private.network_worker_compatibility_state state
  JOIN public.network_worker_assignments assignment
    ON assignment.worker_id = state.worker_id
  WHERE state.singleton
    AND state.worker_id = p_worker_id
    AND state.finalized_at IS NULL
    AND state.expires_at > p_now
    AND assignment.organization_id = p_organization_id
    AND assignment.building_id = p_building_id
    AND assignment.device_id = p_device_id
    AND assignment.active_from <= p_now
    AND assignment.active_until > p_now
    AND CASE p_required_capability
      WHEN 'can_poll' THEN assignment.can_poll
      WHEN 'can_inventory' THEN assignment.can_inventory
      WHEN 'can_execute' THEN assignment.can_execute
      ELSE false
    END
    AND state.assignment_snapshot @> jsonb_build_array(jsonb_build_object(
      'assignmentId', assignment.id,
      'organizationId', assignment.organization_id,
      'buildingId', assignment.building_id,
      'deviceId', assignment.device_id
    ))
  FOR UPDATE OF state, assignment;
  RETURN FOUND;
END;
$$;








--
-- Name: network_center_compatibility_worker_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_compatibility_worker_v1() RETURNS TABLE(worker_id uuid, worker_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  SELECT worker.id, worker.worker_key
  INTO worker_id, worker_key
  FROM app_private.network_worker_compatibility_state state
  JOIN public.network_workers worker ON worker.id = state.worker_id
  WHERE state.singleton
    AND state.finalized_at IS NULL
    AND state.expires_at > clock_timestamp()
    AND worker.status = 'ACTIVE'
    AND worker.capabilities @> ARRAY['POLL', 'INVENTORY']::text[]
  FOR UPDATE OF state, worker;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Legacy worker compatibility is disabled or expired'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEXT;
END;
$$;








--
-- Name: network_center_complete_command_internal_v2(text, uuid, uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_complete_command_internal_v2(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb DEFAULT NULL::jsonb, p_retry_delay_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_command public.network_commands%ROWTYPE;
  v_outcome text := upper(btrim(coalesce(p_outcome, '')));
  v_result jsonb := coalesce(p_result, '{}'::jsonb);
  v_rollback jsonb := p_rollback;
  v_attempt_id uuid;
  v_status text;
  v_event text;
  v_attempt_outcome text;
  v_reconciliation text;
  v_seq bigint;
  v_response jsonb;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_command_id IS NULL
     OR p_lease_token IS NULL
     OR v_outcome NOT IN (
       'SUCCEEDED', 'RETRYABLE_FAILURE', 'FAILED', 'UNCERTAIN',
       'CANCELLED_BY_KILL_SWITCH'
     )
     OR jsonb_typeof(v_result) <> 'object'
     OR octet_length(v_result::text) > 65536
     OR (
       v_rollback IS NOT NULL
       AND (
         jsonb_typeof(v_rollback) <> 'object'
         OR octet_length(v_rollback::text) > 65536
       )
     )
     OR p_retry_delay_seconds NOT BETWEEN 5 AND 3600 THEN
    RAISE EXCEPTION 'Invalid command completion' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    v_result, 'command result'
  );
  PERFORM app_private.network_center_assert_safe_json_v1(
    v_rollback, 'command rollback'
  );

  SELECT command.*
  INTO v_command
  FROM public.network_commands command
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = p_worker_id
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active command lease not found' USING ERRCODE = '55000';
  END IF;

  v_status := CASE
    WHEN v_command.status = 'RECONCILING'
      AND v_outcome = 'RETRYABLE_FAILURE' THEN 'UNCERTAIN'
    ELSE CASE v_outcome
      WHEN 'SUCCEEDED' THEN 'SUCCEEDED'
      WHEN 'RETRYABLE_FAILURE' THEN CASE
        WHEN v_command.attempt_count < v_command.max_attempts
          THEN 'RETRY_WAIT'
        ELSE 'FAILED'
      END
      WHEN 'FAILED' THEN 'FAILED'
      WHEN 'UNCERTAIN' THEN 'UNCERTAIN'
      ELSE 'CANCELLED_BY_KILL_SWITCH'
    END
  END;
  v_event := CASE
    WHEN v_status = 'RETRY_WAIT' THEN 'RETRY_SCHEDULED'
    WHEN v_status = 'CANCELLED_BY_KILL_SWITCH' THEN 'CANCELLED_BY_KILL_SWITCH'
    WHEN v_status = 'UNCERTAIN' THEN 'UNCERTAIN'
    WHEN v_status = 'SUCCEEDED' THEN 'SUCCEEDED'
    ELSE 'FAILED'
  END;
  v_attempt_outcome := CASE
    WHEN v_status = 'SUCCEEDED' THEN 'SUCCEEDED'
    WHEN v_status = 'RETRY_WAIT' THEN 'RETRYABLE_FAILURE'
    WHEN v_status = 'UNCERTAIN' THEN 'UNCERTAIN'
    WHEN v_status = 'CANCELLED_BY_KILL_SWITCH' THEN 'ABANDONED'
    ELSE 'PERMANENT_FAILURE'
  END;
  v_reconciliation := CASE
    WHEN v_status = 'UNCERTAIN' THEN 'REQUIRED'
    WHEN v_command.status = 'RECONCILING' AND v_status = 'SUCCEEDED'
      THEN 'CONFIRMED'
    WHEN v_command.status = 'RECONCILING' AND v_status = 'FAILED'
      THEN 'FAILED'
    ELSE v_command.reconciliation_state
  END;

  SELECT attempt.id
  INTO v_attempt_id
  FROM public.network_command_attempts attempt
  WHERE attempt.command_id = p_command_id
    AND attempt.lease_token = p_lease_token
  ORDER BY attempt.attempt_no DESC
  LIMIT 1;
  IF v_attempt_id IS NOT NULL THEN
    UPDATE public.network_command_attempts
    SET outcome = v_attempt_outcome,
        retryable = (v_status = 'RETRY_WAIT'),
        result = v_result,
        error_code = CASE
          WHEN v_status IN ('SUCCEEDED', 'RETRY_WAIT') THEN NULL
          ELSE v_result->>'code'
        END,
        error_message = CASE
          WHEN v_status = 'SUCCEEDED' THEN NULL
          ELSE left(v_result->>'message', 2000)
        END,
        finished_at = v_now
    WHERE id = v_attempt_id;
  END IF;

  SELECT coalesce(max(event.event_seq) + 1, 1)
  INTO v_seq
  FROM public.network_command_events event
  WHERE event.command_id = p_command_id;
  INSERT INTO public.network_command_events (
    organization_id,
    building_id,
    command_id,
    attempt_id,
    event_seq,
    event_kind,
    occurred_at,
    worker_id,
    payload
  ) VALUES (
    v_command.organization_id,
    v_command.building_id,
    p_command_id,
    v_attempt_id,
    v_seq,
    v_event,
    v_now,
    p_worker_id,
    jsonb_build_object('outcome', v_outcome, 'result', v_result)
  );

  DELETE FROM public.network_device_leases lease
  WHERE lease.command_id = p_command_id
    AND lease.lease_token = p_lease_token
    AND lease.lease_owner = p_worker_id;
  UPDATE public.network_commands command
  SET status = v_status,
      available_at = CASE
        WHEN v_status = 'RETRY_WAIT'
          THEN v_now + make_interval(secs => p_retry_delay_seconds)
        ELSE command.available_at
      END,
      lease_token = NULL,
      lease_owner = NULL,
      lease_expires_at = NULL,
      result = v_result,
      rollback = v_rollback,
      reconciliation_state = v_reconciliation,
      finished_at = CASE
        WHEN v_status IN ('SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH')
          THEN v_now
        ELSE NULL
      END,
      updated_at = v_now
  WHERE command.id = p_command_id;

  v_response := jsonb_build_object(
    'commandId', p_command_id,
    'status', v_status,
    'result', v_result,
    'rollback', v_rollback,
    'reconciliationState', v_reconciliation
  );
  INSERT INTO public.network_audit_events (
    organization_id,
    building_id,
    actor_type,
    worker_id,
    action,
    target_type,
    target_id,
    target_display,
    reason,
    validation,
    result,
    outcome,
    command_id
  ) VALUES (
    v_command.organization_id,
    v_command.building_id,
    'WORKER',
    p_worker_id,
    lower(v_command.action_type),
    'device',
    v_command.device_id,
    v_command.target_display,
    v_command.reason,
    jsonb_build_object('attemptCount', v_command.attempt_count),
    v_response,
    CASE v_status
      WHEN 'SUCCEEDED' THEN 'SUCCEEDED'
      WHEN 'UNCERTAIN' THEN 'UNCERTAIN'
      ELSE 'FAILED'
    END,
    p_command_id
  );
  INSERT INTO public.network_outbox_events (
    organization_id,
    building_id,
    event_type,
    aggregate_type,
    aggregate_id,
    payload,
    occurred_at
  ) VALUES (
    v_command.organization_id,
    v_command.building_id,
    'network.command.completed',
    'command',
    p_command_id,
    jsonb_build_object('status', v_status),
    v_now
  );
  RETURN v_response;
END;
$_$;








--
-- Name: FUNCTION network_center_complete_command_internal_v2(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb, p_retry_delay_seconds integer); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_complete_command_internal_v2(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb, p_retry_delay_seconds integer) IS 'Private authoritative completion sink reached only after v2 worker authentication, final assignment and fenced transition checks.';








--
-- Name: network_center_derive_device_lifecycle_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_derive_device_lifecycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  UPDATE public.network_devices device
  SET lifecycle_status = CASE
        WHEN NEW.reachable THEN 'ONLINE' ELSE 'OFFLINE'
      END,
      updated_at = clock_timestamp()
  WHERE device.id = NEW.device_id
    AND device.device_kind = 'MIKROTIK'
    AND device.is_active
    AND device.lifecycle_status <> 'DISABLED'
    AND device.lifecycle_status IS DISTINCT FROM (
      CASE WHEN NEW.reachable THEN 'ONLINE' ELSE 'OFFLINE' END
    );
  RETURN NULL;
END;
$$;








--
-- Name: FUNCTION network_center_derive_device_lifecycle_v1(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_derive_device_lifecycle_v1() IS 'Derives public.network_devices.lifecycle_status for a MikroTik from the telemetry row just accepted: ONLINE when the poll reached the router, OFFLINE when it did not. Fires only for rows the ingest actually wrote, so a stale payload moves nothing. Never touches DISABLED devices or ARUBA children. The demotion for evidence that stops arriving at all lives in app_private.network_center_reconcile_device_lifecycle_v1.';








--
-- Name: network_center_enqueue_command_v1(uuid, uuid, uuid, uuid, text, text, jsonb, jsonb, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_enqueue_command_v1(p_organization_id uuid, p_building_id uuid, p_device_id uuid, p_interface_id uuid, p_action_type text, p_reason text, p_parameters jsonb, p_target_display jsonb, p_requested_by uuid, p_request_hash text, p_idempotency_key text, p_available_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public', 'extensions'
    AS $_$
DECLARE
  v_now timestamptz;
  v_existing public.network_commands%ROWTYPE;
  v_command_id uuid;
  v_count bigint;
  v_semantic_material text;
  v_semantic_fingerprint character(64);
  v_cooldown interval;
  v_nonterminal text[] := ARRAY[
    'QUEUED', 'LEASED', 'RUNNING', 'RETRY_WAIT', 'UNCERTAIN', 'RECONCILING'
  ]::text[];
BEGIN
  IF p_organization_id IS NULL OR p_building_id IS NULL OR p_device_id IS NULL
     OR p_requested_by IS NULL OR p_available_at IS NULL THEN
    RAISE EXCEPTION 'Missing command identity' USING ERRCODE = '22023';
  END IF;
  p_action_type := upper(btrim(coalesce(p_action_type, '')));
  p_reason := btrim(coalesce(p_reason, ''));
  p_idempotency_key := btrim(coalesce(p_idempotency_key, ''));
  p_request_hash := lower(btrim(coalesce(p_request_hash, '')));
  p_parameters := coalesce(p_parameters, '{}'::jsonb);

  IF p_action_type NOT IN (
       'FLUSH_DNS_CACHE', 'RENEW_DHCP_LEASE', 'CYCLE_ACCESS_PORT',
       'REBOOT_ROUTER', 'CAPTURE_SNAPSHOT'
     )
     OR char_length(p_reason) NOT BETWEEN 8 AND 1000
     OR p_request_hash !~ '^[a-f0-9]{64}$'
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
     OR jsonb_typeof(p_parameters) <> 'object'
     OR p_target_display IS NULL
     OR jsonb_typeof(p_target_display) <> 'object' THEN
    RAISE EXCEPTION 'Invalid command request' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.network_devices device
    WHERE device.organization_id = p_organization_id
      AND device.building_id = p_building_id
      AND device.id = p_device_id
      AND device.device_kind = 'MIKROTIK'
      AND device.is_active
      AND device.write_capability
  ) THEN
    RAISE EXCEPTION 'Command target is not an active writable MikroTik'
      USING ERRCODE = '22023';
  END IF;

  IF p_action_type <> 'CAPTURE_SNAPSHOT' AND EXISTS (
    SELECT 1
    FROM public.network_site_settings settings
    WHERE settings.organization_id = p_organization_id
      AND settings.building_id = p_building_id
      AND settings.changes_paused
  ) THEN
    RAISE EXCEPTION 'Network changes are paused for this building'
      USING ERRCODE = '55000';
  END IF;

  IF p_action_type = 'CYCLE_ACCESS_PORT' THEN
    IF p_interface_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.network_interfaces interface
      WHERE interface.organization_id = p_organization_id
        AND interface.building_id = p_building_id
        AND interface.device_id = p_device_id
        AND interface.id = p_interface_id
        AND interface.interface_role = 'ACCESS'
        AND NOT interface.is_protected
        AND interface.is_enabled
    ) THEN
      RAISE EXCEPTION 'Access-port target is invalid or protected'
        USING ERRCODE = '22023';
    END IF;
  ELSIF p_interface_id IS NOT NULL THEN
    RAISE EXCEPTION 'This action does not accept an interface target'
      USING ERRCODE = '22023';
  END IF;

  v_semantic_material := concat_ws(
    E'\x1f',
    p_organization_id::text,
    p_building_id::text,
    p_device_id::text,
    coalesce(p_interface_id::text, ''),
    p_action_type,
    p_parameters::text
  );
  v_semantic_fingerprint := encode(
    extensions.digest(convert_to(v_semantic_material, 'UTF8'), 'sha256'),
    'hex'
  );
  v_cooldown := CASE p_action_type
    WHEN 'REBOOT_ROUTER' THEN INTERVAL '10 minutes'
    WHEN 'CYCLE_ACCESS_PORT' THEN INTERVAL '2 minutes'
    WHEN 'FLUSH_DNS_CACHE' THEN INTERVAL '30 seconds'
    WHEN 'RENEW_DHCP_LEASE' THEN INTERVAL '30 seconds'
    WHEN 'CAPTURE_SNAPSHOT' THEN INTERVAL '60 seconds'
  END;

  -- Deterministic lock order serializes organization, actor and device budgets.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('network-center:org:' || p_organization_id::text, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('network-center:actor:' || p_requested_by::text, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('network-center:device:' || p_device_id::text, 0)
  );

  -- Cooldown/rate timestamps start only after all admission waits finish.
  v_now := clock_timestamp();

  SELECT command.*
  INTO v_existing
  FROM public.network_commands command
  WHERE command.organization_id = p_organization_id
    AND command.requested_by = p_requested_by
    AND command.idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash IS DISTINCT FROM p_request_hash THEN
      RAISE EXCEPTION 'Idempotency key reused with different command input'
        USING ERRCODE = '23505';
    END IF;
    RETURN v_existing.id;
  END IF;

  SELECT command.*
  INTO v_existing
  FROM public.network_commands command
  WHERE command.semantic_fingerprint = v_semantic_fingerprint
    AND command.created_at >= v_now - v_cooldown
  ORDER BY command.created_at DESC, command.id DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RAISE EXCEPTION 'Equivalent command intent already exists'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', CASE
            WHEN v_existing.requested_by = p_requested_by
              THEN 'NETWORK_CENTER_COOLDOWN'
            ELSE 'NETWORK_CENTER_DUPLICATE_INTENT'
          END,
          'commandId', v_existing.id,
          'actionType', p_action_type,
          'cooldownSeconds', extract(epoch FROM v_cooldown)::integer
        )::text;
  END IF;

  IF p_action_type IN ('CYCLE_ACCESS_PORT', 'REBOOT_ROUTER') THEN
    SELECT count(*) INTO v_count
    FROM public.network_commands command
    WHERE command.device_id = p_device_id
      AND command.status = ANY(v_nonterminal)
      AND command.action_type IN ('CYCLE_ACCESS_PORT', 'REBOOT_ROUTER');
    IF v_count >= 1 THEN
      RAISE EXCEPTION 'A disruptive command is already active for this device'
        USING ERRCODE = 'P0001',
          DETAIL = jsonb_build_object(
            'code', 'NETWORK_CENTER_DEVICE_BUSY',
            'budget', 'disruptive',
            'limit', 1
          )::text;
    END IF;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.device_id = p_device_id
    AND command.status = ANY(v_nonterminal);
  IF v_count >= 2 THEN
    RAISE EXCEPTION 'Device command queue is full'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_DEVICE_BUSY',
          'budget', 'device',
          'limit', 2
        )::text;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.requested_by = p_requested_by
    AND command.status = ANY(v_nonterminal);
  IF v_count >= 8 THEN
    RAISE EXCEPTION 'Actor command queue is full'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_ACTOR_QUEUE_LIMIT',
          'budget', 'actor',
          'limit', 8
        )::text;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.organization_id = p_organization_id
    AND command.status = ANY(v_nonterminal);
  IF v_count >= 30 THEN
    RAISE EXCEPTION 'Organization command queue is full'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_ORG_QUEUE_LIMIT',
          'budget', 'organization',
          'limit', 30
        )::text;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.device_id = p_device_id
    AND command.created_at >= v_now - INTERVAL '1 hour';
  IF v_count >= 12 THEN
    RAISE EXCEPTION 'Device hourly command rate exceeded'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_RATE_LIMIT',
          'budget', 'device_hour',
          'limit', 12
        )::text;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.requested_by = p_requested_by
    AND command.created_at >= v_now - INTERVAL '1 hour';
  IF v_count >= 30 THEN
    RAISE EXCEPTION 'Actor hourly command rate exceeded'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_RATE_LIMIT',
          'budget', 'actor_hour',
          'limit', 30
        )::text;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.network_commands command
  WHERE command.organization_id = p_organization_id
    AND command.created_at >= v_now - INTERVAL '1 hour';
  IF v_count >= 120 THEN
    RAISE EXCEPTION 'Organization hourly command rate exceeded'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_RATE_LIMIT',
          'budget', 'organization_hour',
          'limit', 120
        )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.network_commands command
    WHERE command.device_id = p_device_id
      AND command.action_type = p_action_type
      AND (
        p_action_type <> 'CYCLE_ACCESS_PORT'
        OR command.interface_id = p_interface_id
      )
      AND command.created_at >= v_now - v_cooldown
  ) THEN
    RAISE EXCEPTION 'Command action is cooling down for this device'
      USING ERRCODE = 'P0001',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_COOLDOWN',
          'actionType', p_action_type,
          'cooldownSeconds', extract(epoch FROM v_cooldown)::integer
        )::text;
  END IF;

  INSERT INTO public.network_commands (
    organization_id, building_id, device_id, interface_id, action_type, reason,
    sanitized_parameters, target_display, requested_by, request_hash,
    idempotency_key, semantic_fingerprint, available_at, created_at, updated_at
  ) VALUES (
    p_organization_id, p_building_id, p_device_id, p_interface_id, p_action_type,
    p_reason, p_parameters, p_target_display, p_requested_by, p_request_hash,
    p_idempotency_key, v_semantic_fingerprint, p_available_at, v_now, v_now
  )
  RETURNING id INTO v_command_id;

  RETURN v_command_id;
END;
$_$;








--
-- Name: network_center_enroll_access_interface_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_enroll_access_interface_v1(p_resource_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_interface_id uuid;
BEGIN
  SELECT interface.id INTO v_interface_id
  FROM public.network_managed_resources resource
  JOIN public.network_interfaces interface
    ON interface.organization_id = resource.organization_id
   AND interface.building_id = resource.building_id
   AND interface.device_id = resource.device_id
   AND interface.managed_resource_id = resource.id
  WHERE resource.id = p_resource_id
    AND resource.resource_kind = 'INTERFACE'
    AND resource.enrollment_state = 'DISCOVERED'
    AND resource.enrolled_role = 'ACCESS'
    AND resource.protected
    AND resource.metadata->>'eligibleAccess' = 'true'
    AND resource.stable_key ~* '^ether([2-9]|[1-9][0-9])$'
    AND interface.interface_kind = 'ETHERNET'
    AND interface.interface_role = 'ACCESS'
    AND interface.is_protected
    AND interface.is_managed
    AND interface.is_enabled
    AND interface.interface_key = resource.stable_key
  FOR UPDATE OF resource, interface;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Physical access resource is not eligible for enrollment'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.network_managed_resources
  SET enrollment_state = 'ENROLLED', protected = false,
      last_verified_at = clock_timestamp()
  WHERE id = p_resource_id;

  UPDATE public.network_interfaces
  SET is_protected = false
  WHERE id = v_interface_id;
END;
$_$;








--
-- Name: network_center_ensure_raw_partitions_v1(date, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_ensure_raw_partitions_v1(p_from date, p_through date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_day date;
  v_next date;
  v_name text;
BEGIN
  IF p_from IS NULL OR p_through IS NULL OR p_through < p_from THEN
    RAISE EXCEPTION 'Invalid Network Center partition range' USING ERRCODE = '22023';
  END IF;
  IF p_through > p_from + 62 THEN
    RAISE EXCEPTION 'Network Center partition range exceeds 63 days' USING ERRCODE = '22023';
  END IF;

  v_day := p_from;
  WHILE v_day <= p_through LOOP
    v_next := v_day + 1;

    v_name := 'network_device_samples_' || to_char(v_day, 'YYYYMMDD');
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.network_device_samples FOR VALUES FROM (%L) TO (%L)',
      v_name,
      v_day,
      v_next
    );
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_name);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', v_name);

    v_name := 'network_interface_samples_' || to_char(v_day, 'YYYYMMDD');
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.network_interface_samples FOR VALUES FROM (%L) TO (%L)',
      v_name,
      v_day,
      v_next
    );
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_name);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', v_name);

    v_day := v_next;
  END LOOP;
END;
$$;








--
-- Name: network_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    interface_id uuid,
    action_type text NOT NULL,
    reason text NOT NULL,
    sanitized_parameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    target_display jsonb NOT NULL,
    requested_by uuid NOT NULL,
    request_hash text NOT NULL,
    idempotency_key text NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    priority smallint DEFAULT 50 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_token uuid,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    result jsonb,
    rollback jsonb,
    reconciliation_state text DEFAULT 'NONE'::text NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    semantic_fingerprint character(64) NOT NULL,
    managed_target jsonb NOT NULL,
    intent_type text NOT NULL,
    pre_observation jsonb,
    expected_postcondition jsonb NOT NULL,
    observation_deadline timestamp with time zone NOT NULL,
    transition_version bigint DEFAULT 1 NOT NULL,
    reconciliation_attempt_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT network_commands_action_check CHECK ((action_type = ANY (ARRAY['FLUSH_DNS_CACHE'::text, 'RENEW_DHCP_LEASE'::text, 'CYCLE_ACCESS_PORT'::text, 'REBOOT_ROUTER'::text, 'CAPTURE_SNAPSHOT'::text]))),
    CONSTRAINT network_commands_active_lease_check CHECK (((lease_token IS NOT NULL) = (status = ANY (ARRAY['LEASED'::text, 'RUNNING'::text, 'RECONCILING'::text])))),
    CONSTRAINT network_commands_attempt_check CHECK ((((attempt_count >= 0) AND (attempt_count <= max_attempts)) AND ((max_attempts >= 1) AND (max_attempts <= 10)))),
    CONSTRAINT network_commands_finish_check CHECK ((((status = ANY (ARRAY['SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED_BY_KILL_SWITCH'::text])) = (finished_at IS NOT NULL)) AND ((started_at IS NULL) OR (started_at >= created_at)) AND ((finished_at IS NULL) OR ((started_at IS NOT NULL) AND (finished_at >= started_at))))),
    CONSTRAINT network_commands_hash_check CHECK ((request_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT network_commands_idempotency_check CHECK ((idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'::text)),
    CONSTRAINT network_commands_interface_target_check CHECK (((action_type = 'CYCLE_ACCESS_PORT'::text) = (interface_id IS NOT NULL))),
    CONSTRAINT network_commands_lease_check CHECK ((((lease_token IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_token IS NOT NULL) AND (lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT network_commands_parameters_check CHECK (((jsonb_typeof(sanitized_parameters) = 'object'::text) AND (octet_length((sanitized_parameters)::text) <= 16384))),
    CONSTRAINT network_commands_priority_check CHECK (((priority >= 0) AND (priority <= 100))),
    CONSTRAINT network_commands_reason_check CHECK (((char_length(btrim(reason)) >= 8) AND (char_length(btrim(reason)) <= 1000))),
    CONSTRAINT network_commands_reconciliation_attempt_check CHECK (((reconciliation_attempt_count >= 0) AND (reconciliation_attempt_count <= 50))),
    CONSTRAINT network_commands_reconciliation_check CHECK ((reconciliation_state = ANY (ARRAY['NONE'::text, 'REQUIRED'::text, 'IN_PROGRESS'::text, 'CONFIRMED'::text, 'FAILED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT network_commands_result_check CHECK (((result IS NULL) OR ((jsonb_typeof(result) = 'object'::text) AND (octet_length((result)::text) <= 65536)))),
    CONSTRAINT network_commands_rollback_check CHECK (((rollback IS NULL) OR ((jsonb_typeof(rollback) = 'object'::text) AND (octet_length((rollback)::text) <= 65536)))),
    CONSTRAINT network_commands_semantic_fingerprint_check CHECK ((semantic_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT network_commands_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'LEASED'::text, 'RUNNING'::text, 'RETRY_WAIT'::text, 'UNCERTAIN'::text, 'RECONCILING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED_BY_KILL_SWITCH'::text]))),
    CONSTRAINT network_commands_target_display_check CHECK (((jsonb_typeof(target_display) = 'object'::text) AND (octet_length((target_display)::text) <= 16384))),
    CONSTRAINT network_commands_typed_intent_check CHECK (((intent_type = action_type) AND (jsonb_typeof(managed_target) = 'object'::text) AND (octet_length((managed_target)::text) <= 16384) AND ((pre_observation IS NULL) OR ((jsonb_typeof(pre_observation) = 'object'::text) AND (octet_length((pre_observation)::text) <= 65536))) AND (jsonb_typeof(expected_postcondition) = 'object'::text) AND (octet_length((expected_postcondition)::text) <= 16384) AND (observation_deadline >= created_at) AND (transition_version > 0)))
);








--
-- Name: TABLE network_commands; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_commands IS 'Immediate allowlisted Network Center command queue. No approval state; confirmation input is validated by the public RPC and discarded.';








--
-- Name: COLUMN network_commands.semantic_fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.network_commands.semantic_fingerprint IS 'SHA-256 of canonical tenant, target, action and sanitized parameters; excludes reason and browser idempotency key.';








--
-- Name: COLUMN network_commands.reconciliation_attempt_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.network_commands.reconciliation_attempt_count IS 'Bounded reconciliation attempts; past the cap the command waits for the deadline sweeper or an operator instead of re-leasing its device.';








--
-- Name: network_center_evaluate_postcondition_v1(public.network_commands, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_evaluate_postcondition_v1(p_command public.network_commands, p_before jsonb, p_after jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_before_expiry numeric;
  v_after_expiry numeric;
  v_before_uptime numeric;
  v_after_uptime numeric;
  v_before_at timestamptz;
  v_after_at timestamptz;
  v_live_disable boolean;
  v_recorded_disable boolean;
  v_disable_source text;
BEGIN
  p_before := coalesce(p_before, '{}'::jsonb);
  p_after := coalesce(p_after, '{}'::jsonb);
  BEGIN
    v_before_at := nullif(p_before->>'observedAt', '')::timestamptz;
    v_after_at := nullif(p_after->>'observedAt', '')::timestamptz;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object(
      'outcome', 'UNCERTAIN', 'code', 'INVALID_OBSERVATION_TIME'
    );
  END;
  IF v_before_at IS NULL OR v_after_at IS NULL
     OR v_after_at < v_before_at
     OR v_after_at > p_command.observation_deadline THEN
    RETURN jsonb_build_object(
      'outcome', 'UNCERTAIN', 'code', 'OBSERVATION_DEADLINE_EXCEEDED'
    );
  END IF;

  IF p_command.action_type = 'FLUSH_DNS_CACHE' THEN
    IF p_after #>> '{dns,commandAck}' = 'true' THEN
      RETURN jsonb_build_object(
        'outcome', 'SUCCEEDED', 'dnsAck', true,
        'expected', p_command.expected_postcondition
      );
    END IF;
  ELSIF p_command.action_type = 'RENEW_DHCP_LEASE' THEN
    IF p_before #>> '{dhcp,notApplicable}' = 'true'
       OR p_after #>> '{dhcp,notApplicable}' = 'true' THEN
      RETURN jsonb_build_object(
        'outcome', 'FAILED', 'code', 'DHCP_RENEW_NOT_APPLICABLE',
        'notApplicable', true
      );
    END IF;
    IF coalesce(p_before #>> '{dhcp,expiresInSeconds}', '') ~ '^\d+(?:\.\d+)?$'
       AND coalesce(p_after #>> '{dhcp,expiresInSeconds}', '') ~ '^\d+(?:\.\d+)?$' THEN
      v_before_expiry := (p_before #>> '{dhcp,expiresInSeconds}')::numeric;
      v_after_expiry := (p_after #>> '{dhcp,expiresInSeconds}')::numeric;
      IF lower(coalesce(p_before #>> '{dhcp,status}', '')) = 'bound'
         AND lower(coalesce(p_after #>> '{dhcp,status}', '')) = 'bound'
         AND p_before #>> '{dhcp,leaseKey}' = p_after #>> '{dhcp,leaseKey}'
         AND v_after_expiry > v_before_expiry THEN
        RETURN jsonb_build_object(
          'outcome', 'SUCCEEDED',
          'leaseExpiresInSeconds', v_after_expiry,
          'previousLeaseExpiresInSeconds', v_before_expiry
        );
      END IF;
    END IF;
  ELSIF p_command.action_type = 'CYCLE_ACCESS_PORT' THEN
    -- `disabledObserved` is produced by the worker process that drove the
    -- disable half. A reconciliation attempt builds a fresh connector, usually
    -- on a different host, and can therefore never re-observe it - which made
    -- the postcondition unsatisfiable for a genuinely healthy port. An earlier
    -- attempt's POST_ACTION observation on THIS command and THIS managed
    -- resource is durable, tenant-scoped, append-only evidence of the same fact,
    -- so it is accepted in place of the live half.
    --
    -- What is deliberately NOT relaxed: `enabledObserved` and `enabled` must
    -- still come from p_after. A recorded disable can never on its own produce
    -- SUCCEEDED, because a port left administratively down would then be
    -- reported as a healthy cycle.
    v_live_disable := p_after #>> '{accessInterface,disabledObserved}' = 'true';
    v_recorded_disable := EXISTS (
      SELECT 1
      FROM public.network_command_observations observation
      WHERE observation.command_id = p_command.id
        AND observation.organization_id = p_command.organization_id
        AND observation.building_id = p_command.building_id
        AND observation.device_id = p_command.device_id
        AND observation.observation_kind = 'POST_ACTION'
        AND observation.observed_at <= p_command.observation_deadline
        AND observation.evidence #>> '{accessInterface,managedResourceId}'
          = p_command.managed_target->>'managedResourceId'
        AND observation.evidence #>> '{accessInterface,immutableKey}'
          = p_command.managed_target->>'immutableKey'
        AND observation.evidence #>> '{accessInterface,disabledObserved}' = 'true'
    );
    v_disable_source := CASE
      WHEN v_live_disable THEN 'LIVE'
      WHEN v_recorded_disable THEN 'RECORDED_POST_ACTION'
      ELSE NULL
    END;
    IF p_after #>> '{accessInterface,managedResourceId}' =
         p_command.managed_target->>'managedResourceId'
       AND p_after #>> '{accessInterface,immutableKey}' =
         p_command.managed_target->>'immutableKey'
       AND v_disable_source IS NOT NULL
       AND p_after #>> '{accessInterface,enabledObserved}' = 'true'
       AND p_after #>> '{accessInterface,enabled}' = 'true' THEN
      RETURN jsonb_build_object(
        'outcome', 'SUCCEEDED',
        'managedResourceId', p_command.managed_target->>'managedResourceId',
        'immutableKey', p_command.managed_target->>'immutableKey',
        'disabledObserved', true, 'enabledObserved', true,
        'disabledObservedSource', v_disable_source
      );
    END IF;
  ELSIF p_command.action_type = 'REBOOT_ROUTER' THEN
    IF coalesce(p_before #>> '{boot,uptimeSeconds}', '') ~ '^\d+(?:\.\d+)?$'
       AND coalesce(p_after #>> '{boot,uptimeSeconds}', '') ~ '^\d+(?:\.\d+)?$' THEN
      v_before_uptime := (p_before #>> '{boot,uptimeSeconds}')::numeric;
      v_after_uptime := (p_after #>> '{boot,uptimeSeconds}')::numeric;
      IF nullif(p_before #>> '{boot,bootId}', '') IS NOT NULL
         AND nullif(p_after #>> '{boot,bootId}', '') IS NOT NULL
         AND p_before #>> '{boot,bootId}' <> p_after #>> '{boot,bootId}'
         AND v_after_uptime >= 0
         AND v_after_uptime < v_before_uptime THEN
        RETURN jsonb_build_object(
          'outcome', 'SUCCEEDED',
          'bootId', p_after #>> '{boot,bootId}',
          'uptimeSeconds', v_after_uptime,
          'previousBootId', p_before #>> '{boot,bootId}',
          'previousUptimeSeconds', v_before_uptime
        );
      END IF;
    END IF;
  ELSIF p_command.action_type = 'CAPTURE_SNAPSHOT' THEN
    IF coalesce(p_after #>> '{snapshot,redactedContentHash}', '') ~ '^[a-f0-9]{64}$'
       AND coalesce(p_after #>> '{snapshot,encryptedArtifactHash}', '') ~ '^[a-f0-9]{64}$'
       AND EXISTS (
         SELECT 1
         FROM public.network_config_snapshots snapshot
         WHERE snapshot.organization_id = p_command.organization_id
           AND snapshot.building_id = p_command.building_id
           AND snapshot.device_id = p_command.device_id
           AND snapshot.command_id = p_command.id
           AND snapshot.content_hash =
             p_after #>> '{snapshot,redactedContentHash}'
           AND snapshot.encrypted_artifact_hash =
             p_after #>> '{snapshot,encryptedArtifactHash}'
       ) THEN
      RETURN jsonb_build_object(
        'outcome', 'SUCCEEDED',
        'redactedContentHash', p_after #>> '{snapshot,redactedContentHash}',
        'encryptedArtifactHash', p_after #>> '{snapshot,encryptedArtifactHash}'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'outcome', 'UNCERTAIN',
    'code', 'POSTCONDITION_NOT_PROVEN',
    'expected', p_command.expected_postcondition
  );
END;
$_$;








--
-- Name: network_center_get_building_base_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_get_building_base_v1(p_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_result jsonb;
BEGIN
  SELECT * INTO v_scope FROM app_private.network_center_require_view_v1(p_building_id);

  SELECT jsonb_build_object(
    'buildingId', p_building_id,
    'buildingName', v_scope.building_name,
    'roomsCount', coalesce(building.total_rooms, 0),
    'router', CASE WHEN router.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', router.id,
      'identity', coalesce(current_state.identity_name, router.display_name),
      'externalKey', router.external_key,
      'model', router.model,
      'firmware', current_state.routeros_version,
      'targetFirmware', router.desired_firmware,
      'lifecycleStatus', router.lifecycle_status,
      'reachable', coalesce(current_state.reachable, false),
      'healthStatus', coalesce(current_state.health_status, 'UNKNOWN'),
      'lastSeenAt', current_state.last_seen_at,
      'cpuPercent', current_state.cpu_pct,
      'memoryUsedBytes', current_state.memory_used_bytes,
      'memoryTotalBytes', current_state.memory_total_bytes,
      'diskUsedBytes', current_state.disk_used_bytes,
      'diskTotalBytes', current_state.disk_total_bytes,
      'temperatureC', current_state.temperature_c,
      'voltageV', current_state.voltage_v,
      'pppoeState', current_state.pppoe_state,
      'connectionCount', current_state.connection_count
    ) END,
    'interfaces', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', interface.id, 'name', interface.display_name,
        'key', interface.interface_key, 'role', interface.interface_role,
        'protected', interface.is_protected, 'enabled', interface.is_enabled,
        'linkState', interface_state.link_state, 'rxBps', interface_state.rx_bps,
        'txBps', interface_state.tx_bps,
        'utilizationPercent', interface_state.utilization_pct,
        'errors', interface_state.error_count, 'discards', interface_state.discard_count,
        'queueDrops', interface_state.queue_drop_count
      ) ORDER BY interface.sort_order, interface.id)
      FROM public.network_interfaces interface
      LEFT JOIN public.network_interface_current interface_state ON interface_state.interface_id = interface.id
      WHERE interface.organization_id = v_scope.organization_id
        AND interface.building_id = p_building_id
        AND interface.device_id = router.id
    ), '[]'::jsonb),
    'incidents', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', incident.id, 'title', incident.title, 'detail', incident.summary,
        'severity', incident.severity, 'status', incident.status,
        'openedAt', incident.opened_at, 'acknowledgedAt', incident.acknowledged_at
      ) ORDER BY incident.opened_at DESC, incident.id DESC)
      FROM public.network_incidents incident
      WHERE incident.organization_id = v_scope.organization_id
        AND incident.building_id = p_building_id
        AND incident.status <> 'RESOLVED'
    ), '[]'::jsonb),
    'maintenance', (
      SELECT jsonb_build_object(
        'id', maintenance.id, 'reason', maintenance.reason,
        'startsAt', maintenance.starts_at, 'endsAt', maintenance.ends_at,
        'status', maintenance.status
      )
      FROM public.network_maintenance_windows maintenance
      WHERE maintenance.organization_id = v_scope.organization_id
        AND maintenance.building_id = p_building_id
        AND maintenance.status IN ('SCHEDULED', 'ACTIVE')
      ORDER BY maintenance.starts_at LIMIT 1
    ),
    'revisions', coalesce((
      SELECT jsonb_agg(revision.row ORDER BY revision.created_at DESC, revision.id DESC)
      FROM (
        SELECT snapshot.id, snapshot.created_at,
          jsonb_build_object(
            'id', snapshot.id, 'capturedAt', snapshot.created_at,
            'label', initcap(replace(snapshot.source, '_', ' ')),
            'hash', snapshot.content_hash, 'source', snapshot.source,
            'schemaVersion', snapshot.schema_version
          ) AS row
        FROM public.network_config_snapshots snapshot
        WHERE snapshot.organization_id = v_scope.organization_id
          AND snapshot.building_id = p_building_id
        ORDER BY snapshot.created_at DESC, snapshot.id DESC
        LIMIT 50
      ) revision
    ), '[]'::jsonb),
    'settings', jsonb_build_object(
      'pollingSeconds', settings.poll_interval_seconds,
      'backupHour', to_char(settings.backup_time_local, 'HH24:MI'),
      'alertSensitivity', lower(settings.alert_sensitivity),
      'dependencyGrouping', settings.dependency_grouping,
      'changesPaused', settings.changes_paused,
      'version', settings.version
    )
  ) INTO v_result
  FROM public.buildings building
  LEFT JOIN public.network_devices router
    ON router.organization_id = building.organization_id
   AND router.building_id = building.id
   AND router.device_kind = 'MIKROTIK' AND router.is_active
  LEFT JOIN public.network_device_current current_state ON current_state.device_id = router.id
  LEFT JOIN public.network_site_settings settings
    ON settings.organization_id = building.organization_id AND settings.building_id = building.id
  WHERE building.id = p_building_id;

  RETURN v_result;
END;
$$;








--
-- Name: network_center_guard_aruba_parent_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_aruba_parent_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF NEW.device_kind = 'ARUBA' AND NOT EXISTS (
    SELECT 1
    FROM public.network_devices parent
    WHERE parent.organization_id = NEW.organization_id
      AND parent.building_id = NEW.building_id
      AND parent.id = NEW.parent_device_id
      AND parent.device_kind = 'MIKROTIK'
  ) THEN
    RAISE EXCEPTION 'Aruba parent must be a MikroTik in the same building'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: network_center_guard_command_events_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_command_events_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting(
       'app_private.network_center_command_retention', true
     ) = 'on'
     AND EXISTS (
       SELECT 1
       FROM app_private.network_center_command_retention_contexts context
       WHERE context.backend_pid = pg_backend_pid()
         AND context.transaction_id = txid_current()
     ) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Network Center command events are append-only'
    USING ERRCODE = '55000';
END;
$$;








--
-- Name: network_center_guard_command_evidence_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_command_evidence_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND current_setting(
       'app_private.network_center_command_retention', true
     ) = 'on'
     AND EXISTS (
       SELECT 1
       FROM app_private.network_center_command_retention_contexts context
       WHERE context.backend_pid = pg_backend_pid()
         AND context.transaction_id = txid_current()
     )
     AND OLD.command_id IS NOT NULL
     AND NEW.command_id IS NULL
     AND (to_jsonb(NEW) - 'command_id') IS NOT DISTINCT FROM
         (to_jsonb(OLD) - 'command_id') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Network Center evidence is append-only'
    USING ERRCODE = '55000';
END;
$$;








--
-- Name: network_center_guard_command_immutable_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_command_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF ROW(
    NEW.organization_id, NEW.building_id, NEW.device_id, NEW.interface_id,
    NEW.action_type, NEW.reason, NEW.sanitized_parameters, NEW.target_display,
    NEW.requested_by, NEW.request_hash, NEW.idempotency_key,
    NEW.semantic_fingerprint, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.organization_id, OLD.building_id, OLD.device_id, OLD.interface_id,
    OLD.action_type, OLD.reason, OLD.sanitized_parameters, OLD.target_display,
    OLD.requested_by, OLD.request_hash, OLD.idempotency_key,
    OLD.semantic_fingerprint, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Immutable Network Center command fields cannot change'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: network_center_guard_command_observations_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_command_observations_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting(
       'app_private.network_center_command_retention', true
     ) = 'on'
     AND EXISTS (
       SELECT 1
       FROM app_private.network_center_command_retention_contexts context
       WHERE context.backend_pid = pg_backend_pid()
         AND context.transaction_id = txid_current()
     ) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Network Center command observations are append-only'
    USING ERRCODE = '55000';
END;
$$;








--
-- Name: network_center_guard_command_success_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_command_success_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_transition_authority text := current_setting(
    'app.network_center_transition_authority', true
  );
  v_success_authority text := current_setting(
    'app.network_center_success_authority', true
  );
BEGIN
  IF ROW(
    NEW.managed_target, NEW.intent_type,
    NEW.expected_postcondition, NEW.observation_deadline
  ) IS DISTINCT FROM ROW(
    OLD.managed_target, OLD.intent_type,
    OLD.expected_postcondition, OLD.observation_deadline
  ) THEN
    RAISE EXCEPTION 'Typed command intent fields cannot change'
      USING ERRCODE = '55000';
  END IF;
  IF (
    NEW.pre_observation IS DISTINCT FROM OLD.pre_observation
    OR NEW.transition_version IS DISTINCT FROM OLD.transition_version
  ) AND v_transition_authority IS DISTINCT FROM OLD.id::text THEN
    RAISE EXCEPTION 'Command observation state requires fenced SQL transition'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.status = 'SUCCEEDED'
     AND OLD.status IS DISTINCT FROM 'SUCCEEDED'
     AND v_success_authority IS DISTINCT FROM OLD.id::text THEN
    RAISE EXCEPTION 'Only typed SQL postcondition evaluation may write SUCCEEDED'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: network_center_guard_compatibility_state_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_compatibility_state_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.finalized_at IS NOT NULL AND NEW.finalized_at IS DISTINCT FROM OLD.finalized_at THEN
    RAISE EXCEPTION 'Worker compatibility finalization is permanent'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.expires_at > OLD.expires_at
     OR NEW.assignment_snapshot IS DISTINCT FROM OLD.assignment_snapshot
     OR NEW.worker_id IS DISTINCT FROM OLD.worker_id
     OR NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN
    RAISE EXCEPTION 'Worker compatibility snapshot cannot be expanded'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: network_center_guard_managed_command_target_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_managed_command_target_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_resource public.network_managed_resources%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.pre_observation := NULL;
    NEW.transition_version := 1;
  END IF;
  NEW.intent_type := NEW.action_type;
  NEW.managed_target := jsonb_strip_nulls(jsonb_build_object(
    'deviceId', NEW.device_id,
    'interfaceId', NEW.interface_id
  ));
  NEW.expected_postcondition := CASE NEW.action_type
    WHEN 'FLUSH_DNS_CACHE' THEN jsonb_build_object('kind', 'DNS_COMMAND_ACK')
    WHEN 'RENEW_DHCP_LEASE' THEN jsonb_build_object(
      'kind', 'DHCP_BOUND_LEASE_NEWER_EXPIRY',
      'notApplicableCode', 'DHCP_RENEW_NOT_APPLICABLE'
    )
    WHEN 'CYCLE_ACCESS_PORT' THEN jsonb_build_object(
      'kind', 'IMMUTABLE_ACCESS_INTERFACE_CYCLE'
    )
    WHEN 'REBOOT_ROUTER' THEN jsonb_build_object(
      'kind', 'NEW_BOOT_IDENTITY_AND_UPTIME'
    )
    ELSE jsonb_build_object(
      'kind', 'REDACTED_AND_ENCRYPTED_SNAPSHOT_HASHES'
    )
  END;
  NEW.observation_deadline := coalesce(NEW.observation_deadline, NEW.created_at +
    CASE NEW.action_type
      WHEN 'REBOOT_ROUTER' THEN INTERVAL '10 minutes'
      WHEN 'CYCLE_ACCESS_PORT' THEN INTERVAL '3 minutes'
      WHEN 'CAPTURE_SNAPSHOT' THEN INTERVAL '10 minutes'
      ELSE INTERVAL '2 minutes'
    END
  );

  IF NEW.action_type <> 'CYCLE_ACCESS_PORT' THEN RETURN NEW; END IF;

  SELECT resource.* INTO v_resource
    FROM public.network_interfaces interface
    JOIN public.network_managed_resources resource
      ON resource.organization_id = interface.organization_id
     AND resource.building_id = interface.building_id
     AND resource.device_id = interface.device_id
     AND resource.id = interface.managed_resource_id
    WHERE interface.organization_id = NEW.organization_id
      AND interface.building_id = NEW.building_id
      AND interface.device_id = NEW.device_id
      AND interface.id = NEW.interface_id
      AND interface.is_managed
      AND interface.is_enabled
      AND interface.interface_kind = 'ETHERNET'
      AND interface.interface_role = 'ACCESS'
      AND interface.is_protected = false
      AND resource.resource_kind = 'INTERFACE'
      AND resource.stable_key = interface.interface_key
      AND resource.stable_key ~* '^ether([2-9]|[1-9][0-9])$'
      AND resource.enrollment_state = 'ENROLLED'
      AND resource.enrolled_role = 'ACCESS'
      AND resource.protected = false
    FOR KEY SHARE OF resource
  ;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Managed access interface is required'
      USING ERRCODE = '42501';
  END IF;
  NEW.managed_target := NEW.managed_target || jsonb_build_object(
    'managedResourceId', v_resource.id,
    'immutableKey', v_resource.stable_key
  );
  NEW.expected_postcondition := NEW.expected_postcondition || jsonb_build_object(
    'managedResourceId', v_resource.id,
    'immutableKey', v_resource.stable_key
  );
  RETURN NEW;
END;
$_$;








--
-- Name: network_center_guard_managed_resource_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_guard_managed_resource_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (
      SELECT 1
      FROM public.network_devices device
      WHERE device.organization_id = OLD.organization_id
        AND device.building_id = OLD.building_id
        AND device.id = OLD.device_id
    ) THEN
      RAISE EXCEPTION 'Managed resource cannot be deleted while its device exists'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF ROW(
    NEW.organization_id, NEW.building_id, NEW.device_id,
    NEW.resource_kind, NEW.stable_key, NEW.ownership_marker
  ) IS DISTINCT FROM ROW(
    OLD.organization_id, OLD.building_id, OLD.device_id,
    OLD.resource_kind, OLD.stable_key, OLD.ownership_marker
  ) THEN
    RAISE EXCEPTION 'Managed resource stable_key and ownership cannot change'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.enrollment_state = 'REVOKED'
     AND NEW.enrollment_state <> 'REVOKED' THEN
    RAISE EXCEPTION 'Managed resource enrollment_state REVOKED is terminal'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.enrollment_state = 'ENROLLED'
     AND NEW.enrolled_role IS DISTINCT FROM OLD.enrolled_role THEN
    RAISE EXCEPTION 'Managed resource enrolled role cannot change'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.protected AND NOT NEW.protected AND NOT (
    OLD.resource_kind = 'INTERFACE'
    AND OLD.enrollment_state = 'DISCOVERED'
    AND NEW.enrollment_state = 'ENROLLED'
    AND OLD.enrolled_role = 'ACCESS'
    AND NEW.enrolled_role = 'ACCESS'
    AND OLD.stable_key ~* '^ether([2-9]|[1-9][0-9])$'
  ) THEN
    RAISE EXCEPTION 'Managed resource protection cannot be downgraded'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.enrollment_state = OLD.enrollment_state
    OR (
      OLD.enrollment_state = 'DISCOVERED'
      AND NEW.enrollment_state IN ('ENROLLED', 'REVOKED')
    )
    OR (
      OLD.enrollment_state = 'ENROLLED'
      AND NEW.enrollment_state = 'REVOKED'
    )
  ) THEN
    RAISE EXCEPTION 'Managed resource enrollment_state transition is invalid'
      USING ERRCODE = '55000';
  END IF;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END;
$_$;








--
-- Name: network_center_list_fleet_base_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_list_fleet_base_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  WITH allowed AS (
    SELECT building.id, building.organization_id, building.name,
           coalesce(building.total_rooms, 0) AS total_rooms
    FROM public.buildings building
    WHERE building.deleted_at IS NULL
      AND building.is_virtual = false
      AND public.can_do_on_building('network_center', 'view', building.id)
  ), rows AS (
    SELECT allowed.*,
      router.id AS router_id,
      router.display_name AS router_name,
      router.model AS router_model,
      router.desired_firmware,
      router.lifecycle_status,
      current_state.reachable,
      current_state.health_status,
      current_state.last_seen_at,
      current_state.routeros_version,
      current_state.cpu_pct,
      current_state.memory_used_bytes,
      current_state.memory_total_bytes,
      current_state.pppoe_state,
      current_state.connection_count,
      (SELECT count(*) FROM public.network_devices aruba
        WHERE aruba.organization_id = allowed.organization_id
          AND aruba.building_id = allowed.id
          AND aruba.device_kind = 'ARUBA' AND aruba.is_active) AS aruba_count,
      (SELECT count(*) FROM public.network_incidents incident
        WHERE incident.organization_id = allowed.organization_id
          AND incident.building_id = allowed.id
          AND incident.status <> 'RESOLVED') AS open_incidents,
      (SELECT count(*) FROM public.network_client_current client
        WHERE client.organization_id = allowed.organization_id
          AND client.building_id = allowed.id
          AND client.expires_at > statement_timestamp()) AS active_clients,
      (SELECT max(snapshot.created_at) FROM public.network_config_snapshots snapshot
        WHERE snapshot.organization_id = allowed.organization_id
          AND snapshot.building_id = allowed.id) AS last_backup_at,
      (SELECT sla.uptime_pct FROM public.network_sla_daily sla
        WHERE sla.organization_id = allowed.organization_id
          AND sla.building_id = allowed.id
        ORDER BY sla.sla_day DESC LIMIT 1) AS uptime_pct,
      (SELECT sla.mttr_seconds FROM public.network_sla_daily sla
        WHERE sla.organization_id = allowed.organization_id
          AND sla.building_id = allowed.id
        ORDER BY sla.sla_day DESC LIMIT 1) AS mttr_seconds,
      EXISTS (SELECT 1 FROM public.network_maintenance_windows maintenance
        WHERE maintenance.organization_id = allowed.organization_id
          AND maintenance.building_id = allowed.id
          AND maintenance.status IN ('SCHEDULED', 'ACTIVE')
          AND maintenance.starts_at <= statement_timestamp()
          AND maintenance.ends_at > statement_timestamp()) AS maintenance_active
    FROM allowed
    LEFT JOIN public.network_devices router
      ON router.organization_id = allowed.organization_id
     AND router.building_id = allowed.id
     AND router.device_kind = 'MIKROTIK' AND router.is_active
    LEFT JOIN public.network_device_current current_state ON current_state.device_id = router.id
  )
  SELECT jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'buildingId', rows.id,
      'buildingName', rows.name,
      'roomsCount', rows.total_rooms,
      'routerId', rows.router_id,
      'routerIdentity', rows.router_name,
      'routerModel', rows.router_model,
      'targetFirmware', rows.desired_firmware,
      'lifecycleStatus', rows.lifecycle_status,
      'reachable', coalesce(rows.reachable, false),
      'healthStatus', coalesce(rows.health_status, 'UNKNOWN'),
      'lastSeenAt', rows.last_seen_at,
      'routerosVersion', rows.routeros_version,
      'cpuPercent', rows.cpu_pct,
      'memoryUsedBytes', rows.memory_used_bytes,
      'memoryTotalBytes', rows.memory_total_bytes,
      'pppoeState', rows.pppoe_state,
      'connectionCount', rows.connection_count,
      'arubaCount', rows.aruba_count,
      'openIncidents', rows.open_incidents,
      'activeClients', rows.active_clients,
      'lastBackupAt', rows.last_backup_at,
      'uptimePercent', rows.uptime_pct,
      'mttrSeconds', rows.mttr_seconds,
      'maintenanceActive', rows.maintenance_active
    ) ORDER BY rows.name, rows.id), '[]'::jsonb)
  ) FROM rows;
$$;








--
-- Name: network_center_managed_interface_mapping_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_managed_interface_mapping_v1(p_device_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'managedResourceId', resource.id,
    'id', interface.id,
    'interfaceKey', interface.interface_key,
    'currentName', interface.display_name,
    'immutableKey', resource.stable_key,
    'enrolledRole', coalesce(resource.enrolled_role, 'UNKNOWN'),
    'protected', interface.is_protected OR coalesce(resource.protected, true),
    'enrollmentState', coalesce(resource.enrollment_state, 'DISCOVERED')
  ) ORDER BY interface.interface_key, interface.id), '[]'::jsonb)
  FROM public.network_interfaces interface
  LEFT JOIN public.network_managed_resources resource
    ON resource.organization_id = interface.organization_id
   AND resource.building_id = interface.building_id
   AND resource.device_id = interface.device_id
   AND resource.id = interface.managed_resource_id
  WHERE interface.device_id = p_device_id
$$;








--
-- Name: network_center_org_mutations_paused_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_org_mutations_paused_v1(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT p_organization_id IS NULL OR EXISTS (
    SELECT 1
    FROM public.network_org_mutation_gates gate
    WHERE gate.organization_id = p_organization_id
      AND gate.mutations_paused
  );
$$;








--
-- Name: FUNCTION network_center_org_mutations_paused_v1(p_organization_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_org_mutations_paused_v1(p_organization_id uuid) IS 'Fail-closed organization mutation gate predicate; an unresolvable tenant counts as paused.';








--
-- Name: network_center_pause_building_after_failure_v1(public.network_commands, text, text, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_pause_building_after_failure_v1(p_command public.network_commands, p_actor_worker_id text, p_incident_type text, p_title text, p_summary text, p_detail jsonb, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_fingerprint text;
  v_incident_id uuid;
  v_paused boolean := false;
  v_detail jsonb := coalesce(p_detail, '{}'::jsonb);
BEGIN
  IF p_command.id IS NULL
     OR p_command.organization_id IS NULL
     OR p_command.building_id IS NULL
     OR p_command.device_id IS NULL
     OR p_actor_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_incident_type !~ '^[A-Z][A-Z0-9_]{2,63}$'
     OR char_length(btrim(coalesce(p_title, ''))) NOT BETWEEN 3 AND 200
     OR char_length(btrim(coalesce(p_summary, ''))) NOT BETWEEN 3 AND 2000
     OR jsonb_typeof(v_detail) <> 'object'
     OR octet_length(v_detail::text) > 16384
     OR p_now IS NULL THEN
    RAISE EXCEPTION 'Invalid Network Center failure escalation'
      USING ERRCODE = '22023';
  END IF;

  v_fingerprint := 'network-center:' || lower(p_incident_type) || ':'
    || p_command.id::text;

  INSERT INTO public.network_incidents (
    organization_id, building_id, device_id, interface_id, fingerprint,
    incident_type, severity, status, title, summary, availability_impact,
    opened_at, last_observed_at, occurrence_count, observed_values
  ) VALUES (
    p_command.organization_id, p_command.building_id, p_command.device_id,
    p_command.interface_id, v_fingerprint, p_incident_type, 'CRITICAL', 'OPEN',
    btrim(p_title), btrim(p_summary), true, p_now, p_now, 1, v_detail
  )
  ON CONFLICT (organization_id, building_id, fingerprint)
    WHERE status <> 'RESOLVED'
  DO UPDATE SET
    severity = 'CRITICAL',
    last_observed_at = greatest(
      public.network_incidents.last_observed_at, EXCLUDED.last_observed_at
    ),
    occurrence_count = public.network_incidents.occurrence_count + 1,
    observed_values = EXCLUDED.observed_values,
    version = public.network_incidents.version + 1
  RETURNING id INTO v_incident_id;

  INSERT INTO public.network_incident_events (
    organization_id, building_id, incident_id, event_seq, event_kind,
    severity, occurred_at, worker_id, details
  ) VALUES (
    p_command.organization_id, p_command.building_id, v_incident_id,
    coalesce((
      SELECT max(event.event_seq) + 1
      FROM public.network_incident_events event
      WHERE event.incident_id = v_incident_id
    ), 1),
    'OPENED', 'CRITICAL', p_now, p_actor_worker_id,
    v_detail || jsonb_build_object('commandId', p_command.id)
  );

  UPDATE public.network_site_settings settings
  SET changes_paused = true,
      version = settings.version + 1,
      updated_at = p_now
  WHERE settings.organization_id = p_command.organization_id
    AND settings.building_id = p_command.building_id
    AND NOT settings.changes_paused;
  v_paused := FOUND;

  INSERT INTO public.network_audit_events (
    organization_id, building_id, actor_type, action, target_type, target_id,
    target_display, reason, validation, result, outcome, command_id, occurred_at
  ) VALUES (
    p_command.organization_id, p_command.building_id, 'SYSTEM',
    'system.pause_after_failed_check', 'building', p_command.building_id,
    jsonb_build_object(
      'deviceId', p_command.device_id,
      'actionType', p_command.action_type
    ),
    btrim(p_summary),
    v_detail,
    jsonb_build_object(
      'incidentId', v_incident_id,
      'changesPaused', true,
      'pausedByThisTransition', v_paused
    ),
    'FAILED', p_command.id, p_now
  );

  INSERT INTO public.network_outbox_events (
    organization_id, building_id, event_type, aggregate_type, aggregate_id,
    payload, occurred_at
  ) VALUES (
    p_command.organization_id, p_command.building_id,
    'network.building.changes_paused', 'building', p_command.building_id,
    jsonb_build_object(
      'incidentId', v_incident_id,
      'commandId', p_command.id,
      'incidentType', p_incident_type
    ),
    p_now
  );

  RETURN jsonb_build_object(
    'incidentId', v_incident_id,
    'changesPaused', true,
    'pausedByThisTransition', v_paused
  );
END;
$_$;








--
-- Name: FUNCTION network_center_pause_building_after_failure_v1(p_command public.network_commands, p_actor_worker_id text, p_incident_type text, p_title text, p_summary text, p_detail jsonb, p_now timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_pause_building_after_failure_v1(p_command public.network_commands, p_actor_worker_id text, p_incident_type text, p_title text, p_summary text, p_detail jsonb, p_now timestamp with time zone) IS 'Implements design §5 invariant 14: opens a CRITICAL incident and sets changes_paused for the building in the failing transition''s own transaction.';








--
-- Name: network_center_reclaim_expired_commands_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_reclaim_expired_commands_v1(p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_attempt_id uuid;
  v_next_status text;
  v_event_kind text;
  v_reclaimed integer := 0;
BEGIN
  IF p_now IS NULL THEN
    RAISE EXCEPTION 'Reclaim timestamp is required' USING ERRCODE = '22023';
  END IF;

  FOR v_command IN
    SELECT command.*
    FROM public.network_commands command
    WHERE command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
      AND command.lease_expires_at <= p_now
    ORDER BY command.lease_expires_at, command.id
    FOR UPDATE SKIP LOCKED
  LOOP
    v_next_status := CASE
      WHEN v_command.status = 'LEASED'
       AND v_command.attempt_count < v_command.max_attempts THEN 'RETRY_WAIT'
      WHEN v_command.status = 'LEASED' THEN 'FAILED'
      ELSE 'UNCERTAIN'
    END;
    v_event_kind := CASE
      WHEN v_next_status = 'RETRY_WAIT' THEN 'RETRY_SCHEDULED'
      WHEN v_next_status = 'FAILED' THEN 'FAILED'
      ELSE 'UNCERTAIN'
    END;

    UPDATE public.network_command_attempts attempt
    SET
      outcome = CASE
        WHEN v_next_status = 'UNCERTAIN' THEN 'UNCERTAIN'
        ELSE 'ABANDONED'
      END,
      retryable = (v_next_status = 'RETRY_WAIT'),
      error_code = 'LEASE_EXPIRED',
      error_message = CASE
        WHEN v_next_status = 'UNCERTAIN'
          THEN 'Worker lease expired after execution may have started; reconciliation is required.'
        ELSE 'Worker lease expired before completion.'
      END,
      result = jsonb_build_object('leaseExpiredAt', v_command.lease_expires_at),
      finished_at = p_now
    WHERE attempt.command_id = v_command.id
      AND attempt.lease_token = v_command.lease_token
      AND attempt.finished_at IS NULL
    RETURNING attempt.id INTO v_attempt_id;

    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    ) VALUES (
      v_command.organization_id,
      v_command.building_id,
      v_command.id,
      v_attempt_id,
      coalesce((
        SELECT max(existing_event.event_seq) + 1
        FROM public.network_command_events existing_event
        WHERE existing_event.command_id = v_command.id
      ), 1),
      v_event_kind,
      p_now,
      v_command.lease_owner,
      jsonb_build_object(
        'previousStatus', v_command.status,
        'leaseExpiredAt', v_command.lease_expires_at,
        'nextStatus', v_next_status
      )
    );

    DELETE FROM public.network_device_leases device_lease
    WHERE device_lease.device_id = v_command.device_id
      AND device_lease.command_id = v_command.id
      AND device_lease.lease_token = v_command.lease_token
      AND device_lease.expires_at <= p_now;

    UPDATE public.network_commands command
    SET
      status = CASE
        WHEN v_command.status = 'LEASED'
         AND v_command.attempt_count < v_command.max_attempts THEN 'RETRY_WAIT'
        WHEN v_command.status = 'LEASED' THEN 'FAILED'
        ELSE 'UNCERTAIN'
      END,
      available_at = CASE
        WHEN v_next_status = 'RETRY_WAIT' THEN p_now + INTERVAL '5 seconds'
        ELSE command.available_at
      END,
      lease_token = NULL,
      lease_owner = NULL,
      lease_expires_at = NULL,
      reconciliation_state = CASE
        WHEN v_next_status = 'UNCERTAIN' THEN 'REQUIRED'
        ELSE command.reconciliation_state
      END,
      result = CASE
        WHEN v_next_status = 'FAILED'
          THEN jsonb_build_object('code', 'LEASE_EXPIRED', 'retryExhausted', true)
        ELSE command.result
      END,
      finished_at = CASE WHEN v_next_status = 'FAILED' THEN p_now ELSE NULL END,
      updated_at = p_now
    WHERE command.id = v_command.id;

    v_reclaimed := v_reclaimed + 1;
  END LOOP;

  RETURN v_reclaimed;
END;
$$;








--
-- Name: network_center_reclaim_expired_commands_v2(uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_reclaim_expired_commands_v2(p_worker_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_attempt_id uuid;
  v_next_status text;
  v_event_kind text;
  v_reclaimed integer := 0;
BEGIN
  IF p_worker_id IS NULL OR p_now IS NULL THEN
    RAISE EXCEPTION 'Scoped reclaim identity and timestamp are required'
      USING ERRCODE = '22023';
  END IF;

  FOR v_command IN
    SELECT command.*
    FROM public.network_commands command
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = p_worker_id
     AND assignment.organization_id = command.organization_id
     AND assignment.building_id = command.building_id
     AND assignment.device_id = command.device_id
     AND assignment.can_execute
     AND assignment.active_from <= p_now
     AND (assignment.active_until IS NULL OR assignment.active_until > p_now)
    JOIN public.network_workers worker
      ON worker.id = assignment.worker_id
     AND worker.status IN ('ACTIVE', 'DRAINING')
     AND 'EXECUTE' = ANY(worker.capabilities)
    WHERE command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
      AND command.lease_expires_at <= p_now
    ORDER BY command.lease_expires_at, command.id
    FOR UPDATE OF command, assignment, worker SKIP LOCKED
  LOOP
    v_next_status := CASE
      WHEN v_command.status = 'LEASED'
       AND v_command.attempt_count < v_command.max_attempts THEN 'RETRY_WAIT'
      WHEN v_command.status = 'LEASED' THEN 'FAILED'
      ELSE 'UNCERTAIN'
    END;
    v_event_kind := CASE
      WHEN v_next_status = 'RETRY_WAIT' THEN 'RETRY_SCHEDULED'
      WHEN v_next_status = 'FAILED' THEN 'FAILED'
      ELSE 'UNCERTAIN'
    END;

    UPDATE public.network_command_attempts attempt
    SET outcome = CASE WHEN v_next_status = 'UNCERTAIN'
          THEN 'UNCERTAIN' ELSE 'ABANDONED' END,
        retryable = (v_next_status = 'RETRY_WAIT'),
        error_code = 'LEASE_EXPIRED',
        error_message = CASE WHEN v_next_status = 'UNCERTAIN'
          THEN 'Worker lease expired after execution may have started; reconciliation is required.'
          ELSE 'Worker lease expired before completion.' END,
        result = jsonb_build_object('leaseExpiredAt', v_command.lease_expires_at),
        finished_at = p_now
    WHERE attempt.command_id = v_command.id
      AND attempt.lease_token = v_command.lease_token
      AND attempt.finished_at IS NULL
    RETURNING attempt.id INTO v_attempt_id;

    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    ) VALUES (
      v_command.organization_id, v_command.building_id, v_command.id,
      v_attempt_id, coalesce((
        SELECT max(existing_event.event_seq) + 1
        FROM public.network_command_events existing_event
        WHERE existing_event.command_id = v_command.id
      ), 1), v_event_kind, p_now, v_command.lease_owner,
      jsonb_build_object(
        'previousStatus', v_command.status,
        'leaseExpiredAt', v_command.lease_expires_at,
        'nextStatus', v_next_status
      )
    );

    DELETE FROM public.network_device_leases device_lease
    WHERE device_lease.device_id = v_command.device_id
      AND device_lease.command_id = v_command.id
      AND device_lease.lease_token = v_command.lease_token
      AND device_lease.expires_at <= p_now;

    UPDATE public.network_commands command
    SET status = v_next_status,
        available_at = CASE WHEN v_next_status = 'RETRY_WAIT'
          THEN p_now + INTERVAL '5 seconds' ELSE command.available_at END,
        lease_token = NULL,
        lease_owner = NULL,
        lease_expires_at = NULL,
        reconciliation_state = CASE WHEN v_next_status = 'UNCERTAIN'
          THEN 'REQUIRED' ELSE command.reconciliation_state END,
        result = CASE WHEN v_next_status = 'FAILED'
          THEN jsonb_build_object(
            'code', 'LEASE_EXPIRED', 'retryExhausted', true
          ) ELSE command.result END,
        finished_at = CASE WHEN v_next_status = 'FAILED' THEN p_now ELSE NULL END,
        updated_at = p_now
    WHERE command.id = v_command.id;

    v_reclaimed := v_reclaimed + 1;
  END LOOP;
  RETURN v_reclaimed;
END;
$$;








--
-- Name: network_center_reconcile_device_lifecycle_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_reconcile_device_lifecycle_v1(p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_now timestamptz := p_now;
  v_demoted integer := 0;
BEGIN
  IF v_now IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - v_now))) > 3600 THEN
    RAISE EXCEPTION 'Invalid Network Center lifecycle reconciliation request'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.network_devices device
  SET lifecycle_status = 'OFFLINE',
      updated_at = clock_timestamp()
  WHERE device.device_kind = 'MIKROTIK'
    AND device.is_active
    -- Only ONLINE falls. UNPROVISIONED means "never observed", which is a fact
    -- about history and is not un-observed by silence; DISABLED is the
    -- operator's; OFFLINE is already where this would put it.
    AND device.lifecycle_status = 'ONLINE'
    AND NOT EXISTS (
      SELECT 1
      FROM public.network_device_current current_state
      WHERE current_state.device_id = device.id
        AND current_state.observed_at > v_now - make_interval(secs => GREATEST(
          3 * coalesce((
            SELECT max(connection.poll_interval_seconds)
            FROM public.network_device_connections connection
            WHERE connection.device_id = device.id
              AND connection.is_enabled
          ), 60), 300))
    );
  GET DIAGNOSTICS v_demoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'schemaVersion', 1,
    'job', 'DEVICE_LIFECYCLE',
    'at', v_now,
    'demotedToOffline', v_demoted
  );
END;
$$;








--
-- Name: FUNCTION network_center_reconcile_device_lifecycle_v1(p_now timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_reconcile_device_lifecycle_v1(p_now timestamp with time zone) IS 'Out-of-band demotion of a MikroTik whose telemetry stopped arriving: ONLINE -> OFFLINE after three missed poll intervals (floor five minutes). The counterpart to the promotion in the ingest, which cannot observe its own absence. Never touches UNPROVISIONED, DISABLED or ARUBA.';








--
-- Name: network_center_record_command_observation_v1(text, uuid, uuid, bigint, bigint, uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_record_command_observation_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_transition_version bigint, p_observation_id uuid, p_observation_kind text, p_observed_at timestamp with time zone, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public', 'extensions'
    AS $_$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_existing public.network_command_observations%ROWTYPE;
  v_attempt_id uuid;
  v_evidence_hash character(64);
  v_first_pre_at timestamptz;
BEGIN
  p_worker_id := btrim(coalesce(p_worker_id, ''));
  p_observation_kind := upper(btrim(coalesce(p_observation_kind, '')));
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_command_id IS NULL OR p_lease_token IS NULL
     OR p_fencing_generation < 1 OR p_transition_version < 1
     OR p_observation_id IS NULL
     OR p_observation_kind NOT IN (
       'PRE_ACTION', 'POST_ACTION', 'RECONCILIATION'
     )
     OR p_observed_at IS NULL
     OR p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'object'
     OR octet_length(p_evidence::text) > 65536 THEN
    RAISE EXCEPTION 'Invalid typed command observation' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    p_evidence, 'typed command observation'
  );
  v_evidence_hash := encode(
    extensions.digest(convert_to(p_evidence::text, 'UTF8'), 'sha256'), 'hex'
  );

  SELECT observation.* INTO v_existing
  FROM public.network_command_observations observation
  WHERE observation.id = p_observation_id;
  IF FOUND THEN
    IF v_existing.command_id IS DISTINCT FROM p_command_id
       OR v_existing.lease_token IS DISTINCT FROM p_lease_token
       OR v_existing.fencing_generation IS DISTINCT FROM p_fencing_generation
       OR v_existing.transition_version_before IS DISTINCT FROM p_transition_version
       OR v_existing.observation_kind IS DISTINCT FROM p_observation_kind
       OR v_existing.observed_at IS DISTINCT FROM p_observed_at
       OR v_existing.worker_id IS DISTINCT FROM p_worker_id
       OR v_existing.evidence_hash IS DISTINCT FROM v_evidence_hash THEN
      RAISE EXCEPTION 'Command observation idempotency conflict'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'accepted', true, 'duplicate', true,
      'commandId', p_command_id,
      'transitionVersion', p_transition_version + 1
    );
  END IF;

  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.organization_id = command.organization_id
   AND lease.building_id = command.building_id
   AND lease.device_id = command.device_id
   AND lease.command_id = command.id
   AND lease.lease_token = p_lease_token
   AND lease.lease_owner = p_worker_id
   AND lease.generation = p_fencing_generation
   AND lease.expires_at > clock_timestamp()
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = p_worker_id
    AND command.lease_expires_at > clock_timestamp()
    AND command.transition_version = p_transition_version
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stale command observation fencing or transition version'
      USING ERRCODE = '55000',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_STALE_TRANSITION',
          'commandId', p_command_id,
          'fencingGeneration', p_fencing_generation,
          'transitionVersion', p_transition_version
        )::text;
  END IF;
  IF p_observed_at < v_command.created_at - INTERVAL '5 minutes'
     OR p_observed_at > clock_timestamp() + INTERVAL '5 minutes'
     OR p_observed_at > v_command.observation_deadline THEN
    RAISE EXCEPTION 'Command observation is outside its trusted time window'
      USING ERRCODE = '22023';
  END IF;

  SELECT attempt.id INTO v_attempt_id
  FROM public.network_command_attempts attempt
  WHERE attempt.organization_id = v_command.organization_id
    AND attempt.building_id = v_command.building_id
    AND attempt.command_id = v_command.id
    AND attempt.attempt_no = v_command.attempt_count
    AND attempt.lease_token = p_lease_token
    AND attempt.worker_id = p_worker_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Command attempt does not match active fence'
      USING ERRCODE = '55000';
  END IF;

  SELECT min(observation.observed_at) INTO v_first_pre_at
  FROM public.network_command_observations observation
  WHERE observation.command_id = v_command.id
    AND observation.observation_kind = 'PRE_ACTION';
  IF p_observation_kind = 'PRE_ACTION' AND v_first_pre_at IS NOT NULL THEN
    RAISE EXCEPTION 'Command pre-observation is already frozen'
      USING ERRCODE = '55000';
  END IF;
  IF p_observation_kind IN ('POST_ACTION', 'RECONCILIATION')
     AND (v_first_pre_at IS NULL OR p_observed_at < v_first_pre_at) THEN
    RAISE EXCEPTION 'Post-observation requires an earlier durable pre-observation'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.network_command_observations (
    id, organization_id, building_id, command_id, attempt_id, device_id,
    attempt_no, lease_token, fencing_generation, transition_version_before,
    observation_kind, evidence, evidence_hash, observed_at, worker_id
  ) VALUES (
    p_observation_id, v_command.organization_id, v_command.building_id,
    v_command.id, v_attempt_id, v_command.device_id, v_command.attempt_count,
    p_lease_token, p_fencing_generation, p_transition_version,
    p_observation_kind, p_evidence, v_evidence_hash, p_observed_at, p_worker_id
  );

  PERFORM set_config(
    'app.network_center_transition_authority', v_command.id::text, true
  );
  UPDATE public.network_commands command
  SET
    pre_observation = CASE
      WHEN p_observation_kind = 'PRE_ACTION'
        THEN p_evidence || jsonb_build_object('observedAt', p_observed_at)
      ELSE command.pre_observation
    END,
    transition_version = command.transition_version + 1
  WHERE command.id = p_command_id
    AND command.transition_version = p_transition_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stale command observation compare-and-swap'
      USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'accepted', true, 'duplicate', false,
    'commandId', p_command_id,
    'status', v_command.status,
    'transitionVersion', p_transition_version + 1
  );
END;
$_$;








--
-- Name: network_center_reject_append_only_mutation_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_reject_append_only_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Network Center history is append-only'
    USING ERRCODE = '55000';
END;
$$;








--
-- Name: network_center_replace_worker_assignments_v1(uuid, jsonb, boolean, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_replace_worker_assignments_v1(p_worker_id uuid, p_assignments jsonb, p_allow_empty boolean, p_actor text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_item jsonb;
  v_organization_id uuid;
  v_building_id uuid;
  v_device_id uuid;
  v_can_poll boolean;
  v_can_inventory boolean;
  v_can_execute boolean;
  v_seen_devices uuid[] := '{}'::uuid[];
  v_count integer := 0;
BEGIN
  IF p_worker_id IS NULL OR p_actor IS NULL
     OR char_length(p_actor) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'Invalid worker assignment request' USING ERRCODE = '22023';
  END IF;
  IF p_assignments IS NULL
     OR jsonb_typeof(p_assignments) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_assignments) > 100
     OR (NOT p_allow_empty AND jsonb_array_length(p_assignments) = 0) THEN
    RAISE EXCEPTION 'Worker assignments must be a bounded array'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.network_workers worker
  WHERE worker.id = p_worker_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker not found' USING ERRCODE = 'P0002';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_assignments)
  LOOP
    IF jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'Each worker assignment must be an object'
        USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_object_keys(v_item) AS key_name
      WHERE key_name NOT IN (
        'organizationId', 'buildingId', 'deviceId',
        'canPoll', 'canInventory', 'canExecute'
      )
    ) THEN
      RAISE EXCEPTION 'Worker assignment contains an unsupported field'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_organization_id := (v_item->>'organizationId')::uuid;
      v_building_id := (v_item->>'buildingId')::uuid;
      v_device_id := (v_item->>'deviceId')::uuid;
      v_can_poll := coalesce((v_item->>'canPoll')::boolean, false);
      v_can_inventory := coalesce((v_item->>'canInventory')::boolean, false);
      v_can_execute := coalesce((v_item->>'canExecute')::boolean, false);
    EXCEPTION
      WHEN invalid_text_representation OR datetime_field_overflow THEN
        RAISE EXCEPTION 'Worker assignment contains an invalid field'
          USING ERRCODE = '22023';
    END;

    IF v_organization_id IS NULL OR v_building_id IS NULL OR v_device_id IS NULL THEN
      RAISE EXCEPTION 'Worker assignment target or interval is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF v_device_id = ANY(v_seen_devices) THEN
      RAISE EXCEPTION 'Worker assignment contains a duplicate device'
        USING ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM public.network_devices device
    WHERE device.organization_id = v_organization_id
      AND device.building_id = v_building_id
      AND device.id = v_device_id
      AND device.device_kind = 'MIKROTIK'
      AND device.is_active;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Worker assignment target is not an active MikroTik'
        USING ERRCODE = '23503';
    END IF;

    v_seen_devices := array_append(v_seen_devices, v_device_id);
  END LOOP;

  UPDATE public.network_worker_assignments assignment
  SET
    active_until = greatest(v_now, assignment.active_from + INTERVAL '1 microsecond'),
    assignment_version = assignment.assignment_version + 1,
    updated_by = p_actor,
    updated_at = v_now
  WHERE assignment.worker_id = p_worker_id
    AND assignment.active_until IS NULL;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_assignments)
  LOOP
    v_organization_id := (v_item->>'organizationId')::uuid;
    v_building_id := (v_item->>'buildingId')::uuid;
    v_device_id := (v_item->>'deviceId')::uuid;
    v_can_poll := coalesce((v_item->>'canPoll')::boolean, false);
    v_can_inventory := coalesce((v_item->>'canInventory')::boolean, false);
    v_can_execute := coalesce((v_item->>'canExecute')::boolean, false);

    INSERT INTO public.network_worker_assignments (
      worker_id,
      organization_id,
      building_id,
      device_id,
      device_kind,
      can_poll,
      can_inventory,
      can_execute,
      active_from,
      active_until,
      created_by,
      updated_by
    ) VALUES (
      p_worker_id,
      v_organization_id,
      v_building_id,
      v_device_id,
      'MIKROTIK',
      v_can_poll,
      v_can_inventory,
      v_can_execute,
      v_now,
      NULL,
      p_actor,
      p_actor
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;








--
-- Name: network_center_request_replay_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_request_replay_v1(p_organization_id uuid, p_actor_id uuid, p_request_id uuid, p_request_hash text, p_action text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_existing public.network_audit_events%ROWTYPE;
BEGIN
  SELECT audit.* INTO v_existing
  FROM public.network_audit_events audit
  WHERE audit.organization_id = p_organization_id
    AND audit.actor_type = 'USER'
    AND audit.actor_id = p_actor_id
    AND audit.request_id = p_request_id
  LIMIT 1;

  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_existing.action IS DISTINCT FROM p_action
     OR v_existing.request_hash IS DISTINCT FROM p_request_hash THEN
    RAISE EXCEPTION 'Idempotency key reused with different Network Center input'
      USING ERRCODE = '23505';
  END IF;
  RETURN v_existing.result;
END;
$$;








--
-- Name: network_center_require_execute_permission_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_require_execute_permission_v1(p_building_id uuid) RETURNS TABLE(organization_id uuid, building_name text, actor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  actor_id := (SELECT auth.uid());
  IF actor_id IS NULL OR p_building_id IS NULL THEN
    RAISE EXCEPTION 'Network Center execute permission is required'
      USING ERRCODE = '42501';
  END IF;

  SELECT building.organization_id, building.name
  INTO organization_id, building_name
  FROM public.buildings building
  WHERE building.id = p_building_id
    AND building.deleted_at IS NULL
    AND building.is_virtual = false
  FOR UPDATE;

  IF organization_id IS NULL
     OR NOT public.can_do_on_building(
       'network_center', 'execute', p_building_id
     ) THEN
    RAISE EXCEPTION 'Network Center execute permission is required'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEXT;
END;
$$;








--
-- Name: FUNCTION network_center_require_execute_permission_v1(p_building_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_require_execute_permission_v1(p_building_id uuid) IS 'Identity and permission half of the execute guard, without the organization gate or rollout state, so the fleet kill switch stays operable while engaged.';








--
-- Name: network_center_require_execute_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_require_execute_v1(p_building_id uuid) RETURNS TABLE(organization_id uuid, building_name text, actor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_state text;
  -- Locals, not the OUT parameters: `organization_id` is also a column of
  -- public.network_site_settings, and an unqualified reference to it inside the
  -- rollout query would be an ambiguous name under plpgsql.variable_conflict.
  v_organization_id uuid;
  v_building_name text;
  v_actor_id uuid;
BEGIN
  SELECT scope.organization_id, scope.building_name, scope.actor_id
  INTO v_organization_id, v_building_name, v_actor_id
  FROM app_private.network_center_require_execute_permission_v1(
    p_building_id
  ) scope;
  IF v_organization_id IS NULL OR v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Network Center execute permission is required'
      USING ERRCODE = '42501';
  END IF;

  IF app_private.network_center_org_mutations_paused_v1(v_organization_id) THEN
    RAISE EXCEPTION 'NETWORK_CENTER_ORG_PAUSED' USING ERRCODE = '42501';
  END IF;

  SELECT settings.rollout_state
  INTO v_state
  FROM public.network_site_settings settings
  WHERE settings.organization_id = v_organization_id
    AND settings.building_id = p_building_id
  FOR UPDATE;

  IF v_state = 'READ_ONLY' THEN
    RAISE EXCEPTION 'NETWORK_CENTER_READ_ONLY' USING ERRCODE = '42501';
  END IF;
  IF v_state IS DISTINCT FROM 'EXECUTE' THEN
    RAISE EXCEPTION 'NETWORK_CENTER_OFF' USING ERRCODE = '42501';
  END IF;

  organization_id := v_organization_id;
  building_name := v_building_name;
  actor_id := v_actor_id;
  RETURN NEXT;
END;
$$;








--
-- Name: FUNCTION network_center_require_execute_v1(p_building_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_require_execute_v1(p_building_id uuid) IS 'Single server-side execute guard: identity, per-building permission, organization mutation gate, then rollout state.';








