$$;








--
-- Name: network_center_retention_pre_observations_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_retention_pre_observations_v1(p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
  v_cutoff_day date;
  v_partition record;
  v_partition_day date;
  v_organization record;
  v_command_ids uuid[];
  v_dropped integer := 0;
  v_hourly_deleted bigint := 0;
  v_daily_deleted bigint := 0;
  v_sessions_deleted bigint := 0;
  v_commands_deleted bigint := 0;
  v_count bigint;
  v_aruba_report jsonb;
BEGIN
  IF p_now IS NULL THEN
    RAISE EXCEPTION 'Retention timestamp is required' USING ERRCODE = '22023';
  END IF;

  v_cutoff_day := ((p_now - INTERVAL '14 days') AT TIME ZONE 'UTC')::date;

  FOR v_partition IN
    SELECT child.relname AS partition_name
    FROM pg_catalog.pg_inherits i
    JOIN pg_catalog.pg_class parent ON parent.oid = i.inhparent
    JOIN pg_catalog.pg_namespace parent_ns ON parent_ns.oid = parent.relnamespace
    JOIN pg_catalog.pg_class child ON child.oid = i.inhrelid
    JOIN pg_catalog.pg_namespace child_ns ON child_ns.oid = child.relnamespace
    WHERE parent_ns.nspname = 'public'
      AND child_ns.nspname = 'public'
      AND parent.relname IN (
        'network_device_samples', 'network_interface_samples'
      )
      AND child.relname ~ '^network_(device|interface)_samples_[0-9]{8}$'
  LOOP
    v_partition_day := to_date(
      right(v_partition.partition_name, 8), 'YYYYMMDD'
    );
    IF v_partition_day < v_cutoff_day THEN
      EXECUTE format(
        'DROP TABLE IF EXISTS public.%I', v_partition.partition_name
      );
      v_dropped := v_dropped + 1;
    END IF;
  END LOOP;

  FOR v_organization IN
    SELECT DISTINCT metric.organization_id
    FROM public.network_metric_hourly metric
    WHERE metric.bucket_hour <
      date_trunc('hour', p_now - INTERVAL '13 months')
    ORDER BY metric.organization_id
  LOOP
    WITH victims AS MATERIALIZED (
      SELECT
        metric.organization_id, metric.building_id, metric.series_kind,
        metric.series_id, metric.metric_name, metric.bucket_hour
      FROM public.network_metric_hourly metric
      WHERE metric.organization_id = v_organization.organization_id
        AND metric.bucket_hour <
          date_trunc('hour', p_now - INTERVAL '13 months')
      ORDER BY
        metric.bucket_hour, metric.building_id, metric.series_kind,
        metric.series_id, metric.metric_name
      FOR UPDATE SKIP LOCKED
      LIMIT 5000
    )
    DELETE FROM public.network_metric_hourly metric
    USING victims
    WHERE metric.organization_id = victims.organization_id
      AND metric.building_id = victims.building_id
      AND metric.series_kind = victims.series_kind
      AND metric.series_id = victims.series_id
      AND metric.metric_name = victims.metric_name
      AND metric.bucket_hour = victims.bucket_hour;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_hourly_deleted := v_hourly_deleted + v_count;
  END LOOP;

  FOR v_organization IN
    SELECT DISTINCT daily.organization_id
    FROM public.network_sla_daily daily
    WHERE daily.sla_day <
      ((p_now - INTERVAL '36 months') AT TIME ZONE 'UTC')::date
    ORDER BY daily.organization_id
  LOOP
    WITH victims AS MATERIALIZED (
      SELECT daily.organization_id, daily.building_id, daily.sla_day
      FROM public.network_sla_daily daily
      WHERE daily.organization_id = v_organization.organization_id
        AND daily.sla_day <
          ((p_now - INTERVAL '36 months') AT TIME ZONE 'UTC')::date
      ORDER BY daily.sla_day, daily.building_id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM public.network_sla_daily daily
    USING victims
    WHERE daily.organization_id = victims.organization_id
      AND daily.building_id = victims.building_id
      AND daily.sla_day = victims.sla_day;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_daily_deleted := v_daily_deleted + v_count;
  END LOOP;

  FOR v_organization IN
    SELECT DISTINCT session.organization_id
    FROM public.network_client_sessions session
    WHERE session.last_seen_at < p_now - INTERVAL '90 days'
    ORDER BY session.organization_id
  LOOP
    WITH victims AS MATERIALIZED (
      SELECT session.id
      FROM public.network_client_sessions session
      WHERE session.organization_id = v_organization.organization_id
        AND session.last_seen_at < p_now - INTERVAL '90 days'
      ORDER BY session.last_seen_at, session.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1000
    )
    DELETE FROM public.network_client_sessions session
    USING victims
    WHERE session.id = victims.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_sessions_deleted := v_sessions_deleted + v_count;
  END LOOP;

  FOR v_organization IN
    SELECT DISTINCT command.organization_id
    FROM public.network_commands command
    WHERE command.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH'
      )
      AND command.finished_at < p_now - INTERVAL '180 days'
    ORDER BY command.organization_id
  LOOP
    SELECT array_agg(candidate.id ORDER BY candidate.finished_at, candidate.id)
    INTO v_command_ids
    FROM (
      SELECT command.id, command.finished_at
      FROM public.network_commands command
      WHERE command.organization_id = v_organization.organization_id
        AND command.status IN (
          'SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH'
        )
        AND command.finished_at < p_now - INTERVAL '180 days'
      ORDER BY command.finished_at, command.id
      FOR UPDATE SKIP LOCKED
      LIMIT 100
    ) candidate;

    IF coalesce(cardinality(v_command_ids), 0) = 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.network_audit_events (
      organization_id, building_id, actor_type, action, target_type,
      target_id, target_display, reason, validation, result, outcome,
      occurred_at
    )
    SELECT
      command.organization_id,
      command.building_id,
      'SYSTEM',
      'command.retention_summary',
      'command',
      command.id,
      jsonb_build_object(
        'deviceId', command.device_id,
        'actionType', command.action_type
      ),
      'Sanitized terminal command summary retained before lifecycle deletion.',
      jsonb_build_object(
        'attemptCount', command.attempt_count,
        'reconciliationState', command.reconciliation_state
      ),
      jsonb_build_object(
        'terminalStatus', command.status,
        'startedAt', command.started_at,
        'finishedAt', command.finished_at
      ),
      'OBSERVED',
      p_now
    FROM public.network_commands command
    WHERE command.id = ANY(v_command_ids)
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_audit_events audit
        WHERE audit.organization_id = command.organization_id
          AND audit.building_id = command.building_id
          AND audit.actor_type = 'SYSTEM'
          AND audit.action = 'command.retention_summary'
          AND audit.target_type = 'command'
          AND audit.target_id = command.id
          AND audit.outcome = 'OBSERVED'
          AND audit.reason =
            'Sanitized terminal command summary retained before lifecycle deletion.'
          AND audit.validation->>'attemptCount' = command.attempt_count::text
          AND audit.validation->>'reconciliationState' =
            command.reconciliation_state
          AND audit.result->>'terminalStatus' = command.status
      );

    IF EXISTS (
      SELECT 1
      FROM public.network_commands command
      WHERE command.id = ANY(v_command_ids)
        AND NOT EXISTS (
          SELECT 1
          FROM public.network_audit_events audit
          WHERE audit.organization_id = command.organization_id
            AND audit.building_id = command.building_id
            AND audit.actor_type = 'SYSTEM'
            AND audit.action = 'command.retention_summary'
            AND audit.target_type = 'command'
            AND audit.target_id = command.id
            AND audit.outcome = 'OBSERVED'
            AND audit.reason =
              'Sanitized terminal command summary retained before lifecycle deletion.'
            AND audit.validation->>'attemptCount' = command.attempt_count::text
            AND audit.validation->>'reconciliationState' =
              command.reconciliation_state
            AND audit.result->>'terminalStatus' = command.status
        )
    ) THEN
      RAISE EXCEPTION 'Canonical command retention summary is missing'
        USING ERRCODE = '55000';
    END IF;

    INSERT INTO app_private.network_center_command_retention_contexts (
      backend_pid, transaction_id
    ) VALUES (
      pg_backend_pid(), txid_current()
    )
    ON CONFLICT (backend_pid, transaction_id) DO NOTHING;

    PERFORM set_config(
      'app_private.network_center_command_retention', 'on', true
    );

    DELETE FROM public.network_device_leases lease
    WHERE lease.command_id = ANY(v_command_ids);

    DELETE FROM public.network_command_events event
    WHERE event.command_id = ANY(v_command_ids);

    DELETE FROM public.network_command_attempts attempt
    WHERE attempt.command_id = ANY(v_command_ids);

    DELETE FROM public.network_commands command
    WHERE command.id = ANY(v_command_ids)
      AND command.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH'
      );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_commands_deleted := v_commands_deleted + v_count;

    DELETE FROM app_private.network_center_command_retention_contexts context
    WHERE context.backend_pid = pg_backend_pid()
      AND context.transaction_id = txid_current();

    PERFORM set_config(
      'app_private.network_center_command_retention', 'off', true
    );
  END LOOP;

  PERFORM app_private.network_center_ensure_raw_partitions_v1(
    (p_now AT TIME ZONE 'UTC')::date - 1,
    (p_now AT TIME ZONE 'UTC')::date + 31
  );

  v_aruba_report := app_private.network_center_aruba_retention_v1(p_now);

  RETURN jsonb_build_object(
    'raw_partitions_dropped', v_dropped,
    'hourly_rows_deleted', v_hourly_deleted,
    'daily_rows_deleted', v_daily_deleted,
    'client_sessions_deleted', v_sessions_deleted,
    'terminal_commands_deleted', v_commands_deleted,
    'raw_retention_days', 14,
    'hourly_retention_months', 13,
    'daily_retention_months', 36,
    'client_session_retention_days', 90,
    'terminal_command_retention_days', 180
  ) || v_aruba_report;
END;
$_$;








--
-- Name: FUNCTION network_center_retention_pre_observations_v1(p_now timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_retention_pre_observations_v1(p_now timestamp with time zone) IS 'Bounded repeat-safe retention for telemetry, client history and summarized terminal command data.';








--
-- Name: network_center_retention_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_retention_v1(p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_organization record;
  v_command_ids uuid[];
  v_count bigint;
  v_observations_deleted bigint := 0;
  v_report jsonb;
BEGIN
  IF p_now IS NULL THEN
    RAISE EXCEPTION 'Retention timestamp is required' USING ERRCODE = '22023';
  END IF;

  FOR v_organization IN
    SELECT DISTINCT command.organization_id
    FROM public.network_commands command
    WHERE command.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH'
      )
      AND command.finished_at < p_now - INTERVAL '180 days'
    ORDER BY command.organization_id
  LOOP
    SELECT array_agg(candidate.id ORDER BY candidate.finished_at, candidate.id)
    INTO v_command_ids
    FROM (
      SELECT command.id, command.finished_at
      FROM public.network_commands command
      WHERE command.organization_id = v_organization.organization_id
        AND command.status IN (
          'SUCCEEDED', 'FAILED', 'CANCELLED_BY_KILL_SWITCH'
        )
        AND command.finished_at < p_now - INTERVAL '180 days'
      ORDER BY command.finished_at, command.id
      FOR UPDATE SKIP LOCKED
      LIMIT 100
    ) candidate;

    IF coalesce(cardinality(v_command_ids), 0) = 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO app_private.network_center_command_retention_contexts (
      backend_pid, transaction_id
    ) VALUES (
      pg_backend_pid(), txid_current()
    ) ON CONFLICT (backend_pid, transaction_id) DO NOTHING;
    PERFORM set_config(
      'app_private.network_center_command_retention', 'on', true
    );

    DELETE FROM public.network_command_observations observation
    WHERE observation.command_id = ANY(v_command_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_observations_deleted := v_observations_deleted + v_count;
  END LOOP;

  v_report := app_private.network_center_retention_pre_observations_v1(p_now);

  DELETE FROM app_private.network_center_command_retention_contexts context
  WHERE context.backend_pid = pg_backend_pid()
    AND context.transaction_id = txid_current();
  PERFORM set_config(
    'app_private.network_center_command_retention', 'off', true
  );

  RETURN v_report || jsonb_build_object(
    'command_observations_deleted', v_observations_deleted
  );
END;
$$;








--
-- Name: network_center_rollup_hourly_v1(timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_rollup_hourly_v1(p_hour timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_hour timestamptz;
  v_rows integer;
BEGIN
  IF p_hour IS NULL THEN
    RAISE EXCEPTION 'Rollup hour is required' USING ERRCODE = '22023';
  END IF;
  v_hour := date_trunc('hour', p_hour);

  WITH points AS (
    SELECT
      s.organization_id,
      s.building_id,
      'DEVICE'::text AS series_kind,
      s.device_id AS series_id,
      m.metric_name,
      m.metric_value,
      m.unit
    FROM public.network_device_samples s
    CROSS JOIN LATERAL (
      VALUES
        ('reachable_pct'::text, (CASE WHEN s.reachable THEN 100 ELSE 0 END)::numeric, 'percent'::text),
        ('latency_ms'::text, s.latency_ms::numeric, 'ms'::text),
        ('packet_loss_pct'::text, s.packet_loss_pct::numeric, 'percent'::text),
        ('cpu_pct'::text, s.cpu_pct::numeric, 'percent'::text),
        ('memory_used_pct'::text, s.memory_used_pct::numeric, 'percent'::text),
        ('temperature_c'::text, s.temperature_c::numeric, 'celsius'::text),
        ('voltage_v'::text, s.voltage_v::numeric, 'volt'::text),
        ('connection_count'::text, s.connection_count::numeric, 'count'::text)
    ) AS m(metric_name, metric_value, unit)
    WHERE s.observed_at >= v_hour
      AND s.observed_at < v_hour + INTERVAL '1 hour'
      AND m.metric_value IS NOT NULL

    UNION ALL

    SELECT
      s.organization_id,
      s.building_id,
      'INTERFACE'::text AS series_kind,
      s.interface_id AS series_id,
      m.metric_name,
      m.metric_value,
      m.unit
    FROM public.network_interface_samples s
    JOIN public.network_interfaces interface
      ON interface.organization_id = s.organization_id
     AND interface.building_id = s.building_id
     AND interface.device_id = s.device_id
     AND interface.id = s.interface_id
     AND interface.interface_role IN ('WAN', 'UPLINK')
    CROSS JOIN LATERAL (
      VALUES
        ('link_up_pct'::text, (CASE WHEN s.link_up THEN 100 ELSE 0 END)::numeric, 'percent'::text),
        ('rx_bps'::text, s.rx_bps::numeric, 'bps'::text),
        ('tx_bps'::text, s.tx_bps::numeric, 'bps'::text),
        ('utilization_pct'::text, s.utilization_pct::numeric, 'percent'::text),
        ('error_delta'::text, s.error_delta::numeric, 'count'::text),
        ('discard_delta'::text, s.discard_delta::numeric, 'count'::text),
        ('queue_drop_delta'::text, s.queue_drop_delta::numeric, 'count'::text)
    ) AS m(metric_name, metric_value, unit)
    WHERE s.observed_at >= v_hour
      AND s.observed_at < v_hour + INTERVAL '1 hour'
      AND m.metric_value IS NOT NULL
  ),
  aggregated AS (
    SELECT
      organization_id,
      building_id,
      series_kind,
      series_id,
      metric_name,
      unit,
      count(*)::bigint AS sample_count,
      min(metric_value) AS min_value,
      max(metric_value) AS max_value,
      avg(metric_value) AS avg_value,
      percentile_cont(0.95) WITHIN GROUP (ORDER BY metric_value)::numeric AS p95_value
    FROM points
    GROUP BY organization_id, building_id, series_kind, series_id, metric_name, unit
  )
  INSERT INTO public.network_metric_hourly (
    organization_id,
    building_id,
    series_kind,
    series_id,
    metric_name,
    bucket_hour,
    unit,
    sample_count,
    min_value,
    max_value,
    avg_value,
    p95_value,
    updated_at
  )
  SELECT
    organization_id,
    building_id,
    series_kind,
    series_id,
    metric_name,
    v_hour,
    unit,
    sample_count,
    min_value,
    max_value,
    avg_value,
    p95_value,
    now()
  FROM aggregated
  ON CONFLICT (organization_id, building_id, series_kind, series_id, metric_name, bucket_hour)
  DO UPDATE SET
    unit = EXCLUDED.unit,
    sample_count = EXCLUDED.sample_count,
    min_value = EXCLUDED.min_value,
    max_value = EXCLUDED.max_value,
    avg_value = EXCLUDED.avg_value,
    p95_value = EXCLUDED.p95_value,
    updated_at = now();

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;








--
-- Name: network_center_rollup_sla_daily_v1(date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_rollup_sla_daily_v1(p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
  v_start timestamptz;
  v_end timestamptz;
  v_rows integer;
BEGIN
  IF p_day IS NULL THEN
    RAISE EXCEPTION 'SLA day is required' USING ERRCODE = '22023';
  END IF;
  v_start := p_day::timestamp AT TIME ZONE 'UTC';
  v_end := (p_day + 1)::timestamp AT TIME ZONE 'UTC';

  WITH reachability AS (
    SELECT
      s.organization_id,
      s.building_id,
      count(*)::bigint AS sample_count,
      avg(CASE WHEN s.reachable THEN 1::numeric ELSE 0::numeric END) AS uptime_ratio
    FROM public.network_device_samples s
    JOIN public.network_devices d
      ON d.organization_id = s.organization_id
     AND d.building_id = s.building_id
     AND d.id = s.device_id
     AND d.device_kind = 'MIKROTIK'
     AND d.is_active
    WHERE s.observed_at >= v_start
      AND s.observed_at < v_end
    GROUP BY s.organization_id, s.building_id
  )
  INSERT INTO public.network_sla_daily (
    organization_id,
    building_id,
    sla_day,
    sample_count,
    total_seconds,
    excluded_maintenance_seconds,
    eligible_seconds,
    uptime_seconds,
    outage_seconds,
    uptime_pct,
    incident_count,
    mttr_seconds,
    updated_at
  )
  SELECT
    r.organization_id,
    r.building_id,
    p_day,
    r.sample_count,
    86400,
    0,
    86400,
    round(86400::numeric * r.uptime_ratio)::bigint,
    86400 - round(86400::numeric * r.uptime_ratio)::bigint,
    round(100::numeric * r.uptime_ratio, 4),
    0,
    NULL,
    now()
  FROM reachability r
  ON CONFLICT (organization_id, building_id, sla_day)
  DO UPDATE SET
    sample_count = EXCLUDED.sample_count,
    total_seconds = EXCLUDED.total_seconds,
    excluded_maintenance_seconds = 0,
    eligible_seconds = EXCLUDED.total_seconds,
    uptime_seconds = EXCLUDED.uptime_seconds,
    outage_seconds = EXCLUDED.outage_seconds,
    uptime_pct = EXCLUDED.uptime_pct,
    incident_count = 0,
    mttr_seconds = NULL,
    updated_at = now();

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF to_regclass('public.network_maintenance_windows') IS NOT NULL THEN
    -- FORWARD FIX: the NOT EXISTS probe below aliased
    -- public.network_maintenance_windows as `window`, a reserved keyword that
    -- the parser reads as the start of a WINDOW clause, so this whole statement
    -- died with 42601 on every execution. The alias is now
    -- `maintenance_window`, an ordinary identifier. Nothing else changed.
    EXECUTE $sql$
      WITH maintenance AS (
        SELECT
          organization_id,
          building_id,
          least(
            86400::bigint,
            greatest(
              0::bigint,
              round(sum(extract(epoch FROM (
                least(ends_at, $3) - greatest(starts_at, $2)
              ))))::bigint
            )
          ) AS excluded_seconds
        FROM public.network_maintenance_windows
        WHERE status <> 'CANCELLED'
          AND starts_at < $3
          AND ends_at > $2
        GROUP BY organization_id, building_id
      ),
      effective_reachability AS (
        SELECT
          sample.organization_id,
          sample.building_id,
          count(*)::bigint AS sample_count,
          avg(CASE WHEN sample.reachable THEN 1::numeric ELSE 0::numeric END) AS uptime_ratio
        FROM public.network_device_samples sample
        JOIN public.network_devices device
          ON device.organization_id = sample.organization_id
         AND device.building_id = sample.building_id
         AND device.id = sample.device_id
         AND device.device_kind = 'MIKROTIK'
         AND device.is_active
        WHERE sample.observed_at >= $2
          AND sample.observed_at < $3
          AND NOT EXISTS (
            SELECT 1
            FROM public.network_maintenance_windows maintenance_window
            WHERE maintenance_window.organization_id = sample.organization_id
              AND maintenance_window.building_id = sample.building_id
              AND maintenance_window.status <> 'CANCELLED'
              AND sample.observed_at >= maintenance_window.starts_at
              AND sample.observed_at < maintenance_window.ends_at
          )
        GROUP BY sample.organization_id, sample.building_id
      ),
      recalculated AS (
        SELECT
          daily.organization_id,
          daily.building_id,
          maintenance.excluded_seconds,
          coalesce(effective.sample_count, daily.sample_count) AS sample_count,
          coalesce(effective.uptime_ratio, daily.uptime_pct / 100) AS uptime_ratio,
          86400 - maintenance.excluded_seconds AS eligible_seconds
        FROM public.network_sla_daily daily
        JOIN maintenance
          ON maintenance.organization_id = daily.organization_id
         AND maintenance.building_id = daily.building_id
        LEFT JOIN effective_reachability effective
          ON effective.organization_id = daily.organization_id
         AND effective.building_id = daily.building_id
        WHERE daily.sla_day = $1
      )
      UPDATE public.network_sla_daily s
      SET
        sample_count = r.sample_count,
        excluded_maintenance_seconds = r.excluded_seconds,
        eligible_seconds = r.eligible_seconds,
        uptime_seconds = CASE
          WHEN r.eligible_seconds = 0 THEN 0
          ELSE round(r.eligible_seconds::numeric * r.uptime_ratio)::bigint
        END,
        outage_seconds = CASE
          WHEN r.eligible_seconds = 0 THEN 0
          ELSE r.eligible_seconds - round(r.eligible_seconds::numeric * r.uptime_ratio)::bigint
        END,
        uptime_pct = CASE
          WHEN r.eligible_seconds = 0 THEN 100
          ELSE round(100::numeric * r.uptime_ratio, 4)
        END,
        updated_at = now()
      FROM recalculated r
      WHERE s.sla_day = $1
        AND s.organization_id = r.organization_id
        AND s.building_id = r.building_id
    $sql$ USING p_day, v_start, v_end;
  END IF;

  IF to_regclass('public.network_incidents') IS NOT NULL THEN
    EXECUTE $sql$
      WITH incident_stats AS (
        SELECT
          organization_id,
          building_id,
          count(*)::integer AS incident_count,
          avg(extract(epoch FROM (resolved_at - opened_at)))
            FILTER (WHERE resolved_at IS NOT NULL AND resolved_at >= opened_at) AS mttr_seconds
        FROM public.network_incidents
        WHERE availability_impact
          AND opened_at < $3
          AND (resolved_at IS NULL OR resolved_at >= $2)
        GROUP BY organization_id, building_id
      )
      UPDATE public.network_sla_daily s
      SET
        incident_count = i.incident_count,
        mttr_seconds = i.mttr_seconds,
        updated_at = now()
      FROM incident_stats i
      WHERE s.sla_day = $1
        AND s.organization_id = i.organization_id
        AND s.building_id = i.building_id
    $sql$ USING p_day, v_start, v_end;
  END IF;

  RETURN v_rows;
END;
$_$;








--
-- Name: FUNCTION network_center_rollup_sla_daily_v1(p_day date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_rollup_sla_daily_v1(p_day date) IS 'Repeat-safe daily building SLA rollup. Owner-only; the trusted scheduler reaches it through public.network_center_watchdog_maintenance_v1. Its maintenance-window correction is dynamic SQL, so it is parsed only when executed - the reason a reserved-keyword table alias survived apply and every catalog audit until pg_cron ran it.';








--
-- Name: network_center_sweep_expired_commands_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_sweep_expired_commands_v1(p_now timestamp with time zone DEFAULT clock_timestamp(), p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  c_sweeper_id constant text := 'network-center:deadline-sweeper';
  v_command public.network_commands%ROWTYPE;
  v_attempt_id uuid;
  v_result jsonb;
  v_queued_expired integer := 0;
  v_uncertain_expired integer := 0;
BEGIN
  IF p_now IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'Invalid Network Center expiry sweep request'
      USING ERRCODE = '22023';
  END IF;

  FOR v_command IN
    SELECT command.*
    FROM public.network_commands command
    WHERE command.status IN ('QUEUED', 'RETRY_WAIT', 'UNCERTAIN')
      AND command.observation_deadline <= p_now
      AND NOT EXISTS (
        SELECT 1
        FROM public.network_device_leases lease
        WHERE lease.device_id = command.device_id
          AND lease.expires_at > p_now
      )
    ORDER BY command.observation_deadline, command.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  LOOP
    v_result := jsonb_build_object(
      'code', CASE WHEN v_command.status = 'UNCERTAIN'
        THEN 'RECONCILIATION_WINDOW_EXPIRED'
        ELSE 'OBSERVATION_DEADLINE_EXPIRED_BEFORE_DISPATCH' END,
      'observationDeadline', v_command.observation_deadline,
      'previousStatus', v_command.status,
      'sweptAt', p_now
    );

    SELECT attempt.id INTO v_attempt_id
    FROM public.network_command_attempts attempt
    WHERE attempt.command_id = v_command.id
    ORDER BY attempt.attempt_no DESC
    LIMIT 1;

    UPDATE public.network_command_attempts attempt
    SET outcome = 'PERMANENT_FAILURE',
        retryable = false,
        error_code = v_result->>'code',
        error_message = 'Observation window closed before the command could be '
          || 'proven.',
        result = v_result,
        finished_at = p_now
    WHERE attempt.id = v_attempt_id
      AND attempt.finished_at IS NULL;

    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    ) VALUES (
      v_command.organization_id, v_command.building_id, v_command.id,
      v_attempt_id,
      coalesce((
        SELECT max(event.event_seq) + 1
        FROM public.network_command_events event
        WHERE event.command_id = v_command.id
      ), 1),
      'FAILED', p_now, c_sweeper_id, v_result
    );

    UPDATE public.network_commands command
    SET status = 'FAILED',
        reconciliation_state = CASE
          WHEN v_command.status = 'UNCERTAIN' THEN 'UNKNOWN'
          ELSE command.reconciliation_state
        END,
        result = coalesce(command.result, '{}'::jsonb) || v_result,
        started_at = coalesce(command.started_at, p_now),
        finished_at = p_now,
        updated_at = p_now
    WHERE command.id = v_command.id;

    INSERT INTO public.network_audit_events (
      organization_id, building_id, actor_type, action, target_type, target_id,
      target_display, reason, validation, result, outcome, command_id,
      occurred_at
    ) VALUES (
      v_command.organization_id, v_command.building_id, 'SYSTEM',
      'system.expire_command', 'command', v_command.id,
      jsonb_build_object(
        'deviceId', v_command.device_id,
        'actionType', v_command.action_type
      ),
      'Observation window closed before the command could be proven',
      jsonb_build_object('previousStatus', v_command.status),
      v_result, 'FAILED', v_command.id, p_now
    );

    IF v_command.status = 'UNCERTAIN' THEN
      PERFORM app_private.network_center_pause_building_after_failure_v1(
        v_command,
        c_sweeper_id,
        'RECONCILIATION_WINDOW_EXPIRED',
        'Network Center reconciliation window expired',
        'A command stayed UNCERTAIN past its observation deadline, so its effect '
          || 'on the router can no longer be proven. Changes are paused for this '
          || 'building until an operator resumes them.',
        v_result,
        p_now
      );
      v_uncertain_expired := v_uncertain_expired + 1;
    ELSE
      v_queued_expired := v_queued_expired + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'queuedExpired', v_queued_expired,
    'uncertainExpired', v_uncertain_expired,
    'sweptAt', p_now
  );
END;
$$;








--
-- Name: FUNCTION network_center_sweep_expired_commands_v1(p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_sweep_expired_commands_v1(p_now timestamp with time zone, p_limit integer) IS 'Settles commands whose observation window closed while queued or unresolved into an honest terminal state; an expired UNCERTAIN also opens a critical incident and pauses its building.';








--
-- Name: network_center_transition_command_v1(text, uuid, uuid, bigint, bigint, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_transition_command_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_transition_version bigint, p_outcome text, p_result jsonb, p_rollback jsonb DEFAULT NULL::jsonb, p_retry_delay_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_decision jsonb;
  v_database_outcome text;
  v_result jsonb := coalesce(p_result, '{}'::jsonb) - 'reconciliationDecision';
  v_response jsonb;
  v_escalation jsonb;
  v_post_check_ran boolean;
BEGIN
  p_worker_id := btrim(coalesce(p_worker_id, ''));
  p_outcome := upper(btrim(coalesce(p_outcome, '')));
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_command_id IS NULL OR p_lease_token IS NULL
     OR p_fencing_generation < 1 OR p_transition_version < 1
     OR p_outcome NOT IN (
       'EVALUATE_POSTCONDITION', 'RETRYABLE_FAILURE', 'FAILED',
       'UNCERTAIN', 'CANCELLED_BY_KILL_SWITCH'
     )
     OR jsonb_typeof(v_result) <> 'object'
     OR octet_length(v_result::text) > 65536
     OR (p_rollback IS NOT NULL AND (
       jsonb_typeof(p_rollback) <> 'object'
       OR octet_length(p_rollback::text) > 65536
     ))
     OR p_retry_delay_seconds NOT BETWEEN 5 AND 3600 THEN
    RAISE EXCEPTION 'Invalid typed command transition' USING ERRCODE = '22023';
  END IF;

  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.organization_id = command.organization_id
   AND lease.building_id = command.building_id
   AND lease.device_id = command.device_id
   AND lease.command_id = command.id
   AND lease.lease_token = p_lease_token
   AND lease.lease_owner = p_worker_id
   AND lease.generation = p_fencing_generation
   AND lease.expires_at > clock_timestamp()
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = p_worker_id
    AND command.lease_expires_at > clock_timestamp()
    AND command.transition_version = p_transition_version
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stale command fencing or transition version'
      USING ERRCODE = '55000',
        DETAIL = jsonb_build_object(
          'code', 'NETWORK_CENTER_STALE_TRANSITION',
          'commandId', p_command_id,
          'fencingGeneration', p_fencing_generation,
          'transitionVersion', p_transition_version
        )::text;
  END IF;

  SELECT observation.evidence || jsonb_build_object(
    'observedAt', observation.observed_at
  ) INTO v_before
  FROM public.network_command_observations observation
  WHERE observation.command_id = v_command.id
    AND observation.observation_kind = 'PRE_ACTION'
  ORDER BY observation.transition_version_before, observation.observed_at,
    observation.id
  LIMIT 1;
  v_before := coalesce(v_command.pre_observation, v_before);

  SELECT observation.evidence || jsonb_build_object(
    'observedAt', observation.observed_at
  ) INTO v_after
  FROM public.network_command_observations observation
  WHERE observation.command_id = v_command.id
    AND observation.observation_kind IN ('POST_ACTION', 'RECONCILIATION')
  ORDER BY observation.transition_version_before DESC,
    observation.observed_at DESC, observation.id DESC
  LIMIT 1;

  -- "The post-check ran" is exactly: the worker asked the database to judge what
  -- it observed, or this transition is the verdict of a reconciliation attempt.
  -- Both mean the router was touched and its state is now in question. A plain
  -- transport failure (RETRYABLE_FAILURE / FAILED on a LEASED command that never
  -- got to a post-check) is NOT one of these, and must not pause a building -
  -- an SSH blip on one router would otherwise stop an entire site.
  v_post_check_ran := p_outcome = 'EVALUATE_POSTCONDITION'
    OR v_command.status = 'RECONCILING';

  IF p_outcome = 'EVALUATE_POSTCONDITION' THEN
    v_decision := app_private.network_center_evaluate_postcondition_v1(
      v_command, v_before, v_after
    );
    v_database_outcome := CASE v_decision->>'outcome'
      WHEN 'SUCCEEDED' THEN 'SUCCEEDED'
      WHEN 'FAILED' THEN 'FAILED'
      ELSE 'UNCERTAIN'
    END;
    v_result := v_result || jsonb_build_object(
      'postcondition', v_decision,
      'transitionVersion', p_transition_version + 1
    );
    IF v_database_outcome = 'FAILED'
       AND v_decision ? 'code' AND NOT v_result ? 'code' THEN
      v_result := v_result || jsonb_build_object('code', v_decision->>'code');
    END IF;
  ELSE
    v_database_outcome := p_outcome;
  END IF;

  PERFORM set_config(
    'app.network_center_transition_authority', v_command.id::text, true
  );
  UPDATE public.network_commands command
  SET transition_version = command.transition_version + 1
  WHERE command.id = p_command_id
    AND command.transition_version = p_transition_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stale command transition compare-and-swap'
      USING ERRCODE = '55000';
  END IF;

  IF v_database_outcome = 'SUCCEEDED' THEN
    PERFORM set_config(
      'app.network_center_success_authority', v_command.id::text, true
    );
  END IF;
  v_response := public.network_center_worker_complete_v1(
    p_worker_id, p_command_id, p_lease_token, v_database_outcome,
    v_result, p_rollback, p_retry_delay_seconds
  );

  -- §5 invariant 14, evaluated on the SETTLED status so it also covers a
  -- RETRYABLE_FAILURE that exhausted its attempts, in the transition's own
  -- transaction. A benign "not applicable" (the DHCP renew case) is not a
  -- failed post-check: nothing was changed and nothing is unknown, so it must
  -- never pause a building.
  IF v_post_check_ran
     AND v_response->>'status' = 'FAILED'
     AND NOT coalesce((v_decision->>'notApplicable')::boolean, false) THEN
    v_escalation := app_private.network_center_pause_building_after_failure_v1(
      v_command,
      p_worker_id,
      'COMMAND_POSTCHECK_FAILED',
      'Network Center post-check failed',
      'A Network Center post-check failed, so the device state is not proven. '
        || 'Changes are paused for this building until an operator resumes them.',
      jsonb_build_object(
        'commandId', v_command.id,
        'actionType', v_command.action_type,
        'previousStatus', v_command.status,
        'postcondition', coalesce(v_decision, 'null'::jsonb)
      ),
      clock_timestamp()
    );
  END IF;

  RETURN v_response || jsonb_build_object(
    'transitionVersion', p_transition_version + 1
  ) || CASE
    WHEN v_escalation IS NULL THEN '{}'::jsonb
    ELSE jsonb_build_object('escalation', v_escalation)
  END;
END;
$_$;








--
-- Name: network_center_watchdog_liveness_scan_v1(timestamp with time zone, integer, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_watchdog_liveness_scan_v1(p_now timestamp with time zone, p_stale_after_seconds integer, p_registration_grace_seconds integer) RETURNS TABLE(worker_id uuid, worker_key text, organization_id uuid, building_id uuid, device_id uuid, last_heartbeat_at timestamp with time zone, stale boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  WITH monitored AS (
    SELECT worker.id AS worker_id,
      worker.worker_key AS worker_key,
      worker.created_at AS registered_at,
      assignment.organization_id AS organization_id,
      assignment.building_id AS building_id,
      -- PostgreSQL has no min(uuid); array_agg with an explicit ORDER BY is
      -- the deterministic equivalent, so the incident always names the same
      -- device for a building no matter how the planner orders the scan.
      (array_agg(assignment.device_id ORDER BY assignment.device_id))[1]
        AS device_id
    FROM public.network_workers worker
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = worker.id
    WHERE worker.status IN ('ACTIVE', 'DRAINING')
      AND 'HEARTBEAT' = ANY(worker.capabilities)
      AND assignment.can_poll
      AND assignment.active_from <= p_now
      AND (
        assignment.active_until IS NULL
        OR assignment.active_until > p_now
      )
    GROUP BY worker.id, worker.worker_key, worker.created_at,
      assignment.organization_id, assignment.building_id
  )
  SELECT monitored.worker_id,
    monitored.worker_key,
    monitored.organization_id,
    monitored.building_id,
    monitored.device_id,
    liveness.last_heartbeat_at,
    -- Fail closed on the NULL: a worker that has never reported once is not
    -- "unknown, assume fine", it is exactly the shape of a deploy that never
    -- came up. The registration grace only keeps the minute between provisioning
    -- a principal and the first heartbeat from paging anyone.
    CASE
      WHEN liveness.last_heartbeat_at IS NULL
        THEN monitored.registered_at
          <= p_now - make_interval(secs => p_registration_grace_seconds)
      ELSE liveness.last_heartbeat_at
        < p_now - make_interval(secs => p_stale_after_seconds)
    END AS stale
  FROM monitored
  CROSS JOIN LATERAL (
    SELECT max(heartbeat.heartbeat_at) AS last_heartbeat_at
    FROM app_private.network_worker_release_heartbeats heartbeat
    WHERE heartbeat.worker_id = monitored.worker_id
  ) liveness;
$$;








--
-- Name: network_center_watchdog_record_run_v1(text, timestamp with time zone, integer, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_watchdog_record_run_v1(p_job text, p_ran_at timestamp with time zone, p_duration_ms integer, p_report jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  c_run_log_limit constant integer := 10000;
  c_run_log_max_age constant interval := INTERVAL '14 days';
BEGIN
  IF p_job NOT IN ('LIVENESS', 'MAINTENANCE')
     OR p_ran_at IS NULL
     OR p_duration_ms IS NULL
     OR p_duration_ms < 0
     OR jsonb_typeof(coalesce(p_report, 'null'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'Invalid Network Center watchdog run record'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO app_private.network_center_watchdog_runs (
    job, ran_at, duration_ms, report
  ) VALUES (
    p_job, p_ran_at, least(p_duration_ms, 86400000), p_report
  );

  DELETE FROM app_private.network_center_watchdog_runs run
  WHERE run.job = p_job
    AND run.ran_at < p_ran_at - c_run_log_max_age;

  DELETE FROM app_private.network_center_watchdog_runs run
  WHERE run.job = p_job
    AND run.id IN (
      SELECT ranked.id
      FROM app_private.network_center_watchdog_runs ranked
      WHERE ranked.job = p_job
      ORDER BY ranked.ran_at DESC, ranked.id DESC
      OFFSET c_run_log_limit
    );
END;
$$;








--
-- Name: network_center_worker_can_access_building_v2(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_can_access_building_v2(p_worker_id uuid, p_organization_id uuid, p_building_id uuid, p_required_capability text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF p_worker_id IS NULL OR p_organization_id IS NULL
     OR p_building_id IS NULL
     OR p_required_capability NOT IN (
       'HEARTBEAT', 'POLL', 'TELEMETRY', 'INVENTORY',
       'EXECUTE', 'INCIDENT', 'SNAPSHOT', 'MAINTENANCE'
     ) OR p_now IS NULL THEN
    RETURN false;
  END IF;

  PERFORM 1
  FROM public.network_workers worker
  JOIN public.network_worker_assignments assignment
    ON assignment.worker_id = worker.id
  WHERE worker.id = p_worker_id
    AND worker.status IN ('ACTIVE', 'DRAINING')
    AND p_required_capability = ANY(worker.capabilities)
    AND assignment.worker_id = p_worker_id
    AND assignment.organization_id = p_organization_id
    AND assignment.building_id = p_building_id
    AND assignment.active_from <= p_now
    AND (assignment.active_until IS NULL OR assignment.active_until > p_now)
    AND CASE
      WHEN p_required_capability = 'HEARTBEAT' THEN
        assignment.can_poll OR assignment.can_inventory OR assignment.can_execute
      WHEN p_required_capability IN (
        'POLL', 'TELEMETRY', 'INCIDENT', 'MAINTENANCE'
      ) THEN assignment.can_poll
      WHEN p_required_capability = 'INVENTORY' THEN assignment.can_inventory
      WHEN p_required_capability IN ('EXECUTE', 'SNAPSHOT') THEN assignment.can_execute
      ELSE false
    END
  FOR UPDATE OF worker, assignment;
  RETURN FOUND;
END;
$$;








