--
-- Name: network_center_worker_command_event_legacy_impl_v1(text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_command_event_legacy_impl_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_event_kind text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_attempt_id uuid;
  v_kind text := upper(btrim(coalesce(p_event_kind, '')));
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_seq bigint;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_command_id IS NULL OR p_lease_token IS NULL
     OR v_kind NOT IN (
       'VALIDATED', 'BACKUP_STARTED', 'BACKUP_COMPLETED',
       'EXECUTION_STARTED', 'EXECUTION_COMPLETED', 'POST_CHECK_STARTED',
       'POST_CHECK_COMPLETED', 'RECONCILIATION_STARTED', 'RECONCILIATION_COMPLETED'
     )
     OR jsonb_typeof(v_payload) <> 'object'
     OR octet_length(v_payload::text) > 65536 THEN
    RAISE EXCEPTION 'Invalid command stage event' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    v_payload, 'command event payload'
  );
  SELECT command.* INTO v_command FROM public.network_commands command
  WHERE command.id = p_command_id AND command.lease_token = p_lease_token
    AND command.lease_owner = p_worker_id
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active command lease not found' USING ERRCODE = '55000'; END IF;
  SELECT attempt.id INTO v_attempt_id FROM public.network_command_attempts attempt
  WHERE attempt.command_id = p_command_id
  ORDER BY attempt.attempt_no DESC LIMIT 1;
  SELECT coalesce(max(event.event_seq) + 1, 1) INTO v_seq
  FROM public.network_command_events event WHERE event.command_id = p_command_id;
  INSERT INTO public.network_command_events (
    organization_id, building_id, command_id, attempt_id, event_seq,
    event_kind, occurred_at, worker_id, payload
  ) VALUES (
    v_command.organization_id, v_command.building_id, p_command_id,
    v_attempt_id, v_seq, v_kind, clock_timestamp(), p_worker_id, v_payload
  );
  IF v_kind = 'EXECUTION_STARTED' AND v_command.status = 'LEASED' THEN
    UPDATE public.network_commands SET status = 'RUNNING' WHERE id = p_command_id;
  ELSIF v_kind = 'RECONCILIATION_STARTED' AND v_command.status <> 'RECONCILING' THEN
    UPDATE public.network_commands
    SET status = 'RECONCILING', reconciliation_state = 'IN_PROGRESS'
    WHERE id = p_command_id;
  END IF;
  RETURN jsonb_build_object('commandId', p_command_id, 'eventSeq', v_seq, 'eventKind', v_kind);
END;
$_$;








--
-- Name: network_center_worker_expected_connections_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_expected_connections_v1(p_worker_id uuid, p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_expected integer;
BEGIN
  -- NULL in, NULL out - never 0. A 0 here would read as "this worker has
  -- nothing to poll", which is the one answer that makes the honesty guard
  -- accept a claim it could not check. Both callers pass a non-null worker id
  -- from a join key or an authenticated principal, so this branch is defensive
  -- only; it is written in the fail-closed direction on purpose.
  IF p_worker_id IS NULL OR p_now IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT count(*)::integer
  INTO v_expected
  FROM (
    SELECT DISTINCT connection.id
    FROM public.network_device_connections connection
    JOIN public.network_devices device
      ON device.organization_id = connection.organization_id
     AND device.building_id = connection.building_id
     AND device.id = connection.device_id
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = p_worker_id
     AND assignment.organization_id = connection.organization_id
     AND assignment.building_id = connection.building_id
     AND assignment.device_id = connection.device_id
     AND assignment.can_poll
     AND assignment.active_from <= p_now
     AND (
       assignment.active_until IS NULL
       OR assignment.active_until > p_now
     )
    JOIN public.network_workers worker
      ON worker.id = assignment.worker_id
     AND worker.status IN ('ACTIVE', 'DRAINING')
     AND 'POLL' = ANY(worker.capabilities)
    LEFT JOIN public.network_site_settings settings
      ON settings.organization_id = connection.organization_id
     AND settings.building_id = connection.building_id
    WHERE connection.is_enabled
      AND device.is_active
      AND device.device_kind = 'MIKROTIK'
      AND connection.transport = 'ROUTEROS_SSH'
      AND coalesce(settings.monitoring_enabled, true)
  ) pollable_connections;
  RETURN v_expected;
END;
$$;








--
-- Name: FUNCTION network_center_worker_expected_connections_v1(p_worker_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.network_center_worker_expected_connections_v1(p_worker_id uuid, p_now timestamp with time zone) IS 'Server-derived count of the pollable connections PostgreSQL would serve this worker, under the same predicate network_center_worker_list_connections_v2 uses, narrowed to the MIKROTIK/ROUTEROS_SSH subset the polling cycle attempts. Single source for both the deployment readback and the heartbeat honesty guard.';








--
-- Name: network_center_worker_heartbeat_core_v2(text, text, text[], text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_heartbeat_core_v2(p_credential_digest text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF p_worker_version IS NULL
     OR octet_length(p_worker_version) <> 40
     OR p_worker_version !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'Invalid worker heartbeat' USING ERRCODE = '22023';
  END IF;
  RETURN app_private.network_center_worker_heartbeat_impl_v2(
    p_credential_digest,
    p_worker_version,
    p_capabilities,
    p_status,
    p_queue_age_seconds,
    p_safe_metadata,
    p_started_at
  );
END;
$_$;








--
-- Name: network_center_worker_heartbeat_impl_v2(text, text, text[], text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_heartbeat_impl_v2(p_credential_digest text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_registry_capabilities text[];
  v_now timestamptz := clock_timestamp();
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_building_count integer;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_registry_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;

  IF char_length(btrim(coalesce(p_worker_version, ''))) NOT BETWEEN 1 AND 100
     OR cardinality(coalesce(p_capabilities, ARRAY[]::text[])) > 32
     OR v_status NOT IN ('ONLINE', 'DEGRADED', 'PAUSED', 'STOPPING')
     OR p_queue_age_seconds NOT BETWEEN 0 AND 31536000
     OR p_safe_metadata IS NULL OR jsonb_typeof(p_safe_metadata) <> 'object'
     OR octet_length(p_safe_metadata::text) > 16384
     OR p_started_at IS NULL OR p_started_at > v_now THEN
    RAISE EXCEPTION 'Invalid worker heartbeat' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    p_safe_metadata, 'worker heartbeat metadata'
  );

  WITH authorized_buildings AS MATERIALIZED (
    SELECT DISTINCT assignment.organization_id, assignment.building_id
    FROM public.network_workers worker
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = worker.id
    WHERE worker.id = v_worker_id
      AND worker.status IN ('ACTIVE', 'DRAINING')
      AND 'HEARTBEAT' = ANY(worker.capabilities)
      AND assignment.active_from <= v_now
      AND (
        assignment.active_until IS NULL
        OR assignment.active_until > v_now
      )
      AND (
        assignment.can_poll OR assignment.can_inventory
        OR assignment.can_execute
      )
      AND app_private.network_center_worker_can_access_building_v2(
        v_worker_id, assignment.organization_id,
        assignment.building_id,
        'HEARTBEAT',
        v_now
      )
  ), upserted AS (
    INSERT INTO public.network_worker_building_status (
      organization_id, building_id, status, heartbeat_at,
      queue_age_seconds, started_at, updated_at
    )
    SELECT organization_id, building_id, v_status, v_now,
      p_queue_age_seconds, p_started_at, v_now
    FROM authorized_buildings
    ON CONFLICT (organization_id, building_id) DO UPDATE SET
      status = EXCLUDED.status,
      heartbeat_at = EXCLUDED.heartbeat_at,
      queue_age_seconds = EXCLUDED.queue_age_seconds,
      started_at = EXCLUDED.started_at,
      updated_at = EXCLUDED.updated_at
    RETURNING building_id
  )
  SELECT count(*) INTO v_building_count FROM upserted;

  IF v_building_count = 0 THEN
    RAISE EXCEPTION 'Worker has no active assigned building'
      USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'status', v_status, 'heartbeatAt', v_now,
    'assignedBuildingCount', v_building_count
  );
END;
$$;








--
-- Name: network_center_worker_ingest_legacy_impl_v1(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_ingest_legacy_impl_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_observed_at timestamptz;
  v_devices integer := 0;
  v_interfaces integer := 0;
  v_clients integer := 0;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) > 524288
     OR jsonb_typeof(coalesce(p_payload->'devices', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'interfaces', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'clients', '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(coalesce(p_payload->'devices', '[]'::jsonb)) > 256
     OR jsonb_array_length(coalesce(p_payload->'interfaces', '[]'::jsonb)) > 256
     OR jsonb_array_length(coalesce(p_payload->'clients', '[]'::jsonb)) > 256 THEN
    RAISE EXCEPTION 'Invalid or oversized telemetry payload' USING ERRCODE = '22023';
  END IF;
  v_observed_at := nullif(p_payload->>'observedAt', '')::timestamptz;
  IF v_observed_at IS NULL
     OR abs(extract(epoch FROM (v_now - v_observed_at))) > 600 THEN
    RAISE EXCEPTION 'Telemetry timestamp is outside the accepted window' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_ensure_raw_partitions_v1(
    v_observed_at::date - 1, v_observed_at::date + 2
  );

  WITH input AS (
    SELECT * FROM jsonb_to_recordset(coalesce(p_payload->'devices', '[]'::jsonb)) AS row(
      "deviceId" uuid, "lastSeenAt" timestamptz, reachable boolean,
      "healthStatus" text, identity text, "routerosVersion" text,
      "uptimeSeconds" bigint, "cpuPct" numeric, "memoryUsedBytes" bigint,
      "memoryTotalBytes" bigint, "diskUsedBytes" bigint, "diskTotalBytes" bigint,
      "temperatureC" numeric, "voltageV" numeric, "pppoeState" text,
      "connectionCount" integer, "latencyMs" numeric, "packetLossPct" numeric,
      "lastErrorCode" text
    )
  ), valid AS (
    SELECT input.*, device.organization_id, device.building_id
    FROM input JOIN public.network_devices device ON device.id = input."deviceId"
    WHERE device.is_active
  ), upserted AS (
    INSERT INTO public.network_device_current (
      device_id, organization_id, building_id, observed_at, last_seen_at,
      reachable, health_status, identity_name, routeros_version, uptime_seconds,
      cpu_pct, memory_used_bytes, memory_total_bytes, disk_used_bytes,
      disk_total_bytes, temperature_c, voltage_v, pppoe_state, connection_count,
      latency_ms, packet_loss_pct, last_error_code, update_seq
    )
    SELECT "deviceId", organization_id, building_id, v_observed_at,
      coalesce("lastSeenAt", CASE WHEN reachable THEN v_observed_at ELSE NULL END),
      coalesce(reachable, false), coalesce("healthStatus", 'UNKNOWN'), identity,
      "routerosVersion", "uptimeSeconds", "cpuPct", "memoryUsedBytes",
      "memoryTotalBytes", "diskUsedBytes", "diskTotalBytes", "temperatureC",
      "voltageV", coalesce("pppoeState", 'UNKNOWN'), "connectionCount",
      "latencyMs", "packetLossPct", "lastErrorCode", 1
    FROM valid
    ON CONFLICT (device_id) DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      building_id = EXCLUDED.building_id,
      observed_at = EXCLUDED.observed_at,
      last_seen_at = GREATEST(
        public.network_device_current.last_seen_at,
        EXCLUDED.last_seen_at
      ),
      reachable = EXCLUDED.reachable,
      health_status = EXCLUDED.health_status,
      identity_name = EXCLUDED.identity_name,
      routeros_version = EXCLUDED.routeros_version,
      uptime_seconds = EXCLUDED.uptime_seconds,
      cpu_pct = EXCLUDED.cpu_pct,
      memory_used_bytes = EXCLUDED.memory_used_bytes,
      memory_total_bytes = EXCLUDED.memory_total_bytes,
      disk_used_bytes = EXCLUDED.disk_used_bytes,
      disk_total_bytes = EXCLUDED.disk_total_bytes,
      temperature_c = EXCLUDED.temperature_c,
      voltage_v = EXCLUDED.voltage_v,
      pppoe_state = EXCLUDED.pppoe_state,
      connection_count = EXCLUDED.connection_count,
      latency_ms = EXCLUDED.latency_ms,
      packet_loss_pct = EXCLUDED.packet_loss_pct,
      last_error_code = EXCLUDED.last_error_code,
      update_seq = public.network_device_current.update_seq + 1
    WHERE EXCLUDED.observed_at >= public.network_device_current.observed_at
    RETURNING device_id
  ), sampled AS (
    INSERT INTO public.network_device_samples (
      organization_id, building_id, device_id, observed_at, reachable,
      latency_ms, packet_loss_pct, cpu_pct, memory_used_pct, temperature_c,
      voltage_v, connection_count, sample
    )
    SELECT organization_id, building_id, "deviceId", v_observed_at,
      coalesce(reachable, false), "latencyMs", "packetLossPct", "cpuPct",
      CASE WHEN "memoryTotalBytes" > 0
        THEN round(("memoryUsedBytes"::numeric / "memoryTotalBytes") * 100, 2) END,
      "temperatureC", "voltageV", "connectionCount",
      jsonb_strip_nulls(jsonb_build_object(
        'routerosVersion', "routerosVersion", 'uptimeSeconds', "uptimeSeconds",
        'diskUsedBytes', "diskUsedBytes", 'diskTotalBytes', "diskTotalBytes",
        'pppoeState', "pppoeState"
      ))
    FROM valid ON CONFLICT (device_id, observed_at) DO NOTHING
    RETURNING device_id
  )
  SELECT count(*) INTO v_devices FROM upserted;

  WITH input AS (
    SELECT * FROM jsonb_to_recordset(coalesce(p_payload->'interfaces', '[]'::jsonb)) AS row(
      "interfaceId" uuid, "linkState" text, "rxBps" numeric, "txBps" numeric,
      "utilizationPct" numeric, "rxBytes" bigint, "txBytes" bigint,
      "errorCount" bigint, "discardCount" bigint, "queueDropCount" bigint,
      "errorDelta" bigint, "discardDelta" bigint, "queueDropDelta" bigint
    )
  ), valid AS (
    SELECT input.*, interface.organization_id, interface.building_id, interface.device_id
    FROM input JOIN public.network_interfaces interface ON interface.id = input."interfaceId"
  ), upserted AS (
    INSERT INTO public.network_interface_current (
      interface_id, organization_id, building_id, device_id, observed_at,
      link_state, rx_bps, tx_bps, utilization_pct, rx_bytes, tx_bytes,
      error_count, discard_count, queue_drop_count, update_seq
    )
    SELECT "interfaceId", organization_id, building_id, device_id, v_observed_at,
      coalesce("linkState", 'UNKNOWN'), "rxBps", "txBps", "utilizationPct",
      "rxBytes", "txBytes", "errorCount", "discardCount", "queueDropCount", 1
    FROM valid
    ON CONFLICT (interface_id) DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      building_id = EXCLUDED.building_id,
      device_id = EXCLUDED.device_id,
      observed_at = EXCLUDED.observed_at,
      link_state = EXCLUDED.link_state,
      rx_bps = EXCLUDED.rx_bps,
      tx_bps = EXCLUDED.tx_bps,
      utilization_pct = EXCLUDED.utilization_pct,
      rx_bytes = EXCLUDED.rx_bytes,
      tx_bytes = EXCLUDED.tx_bytes,
      error_count = EXCLUDED.error_count,
      discard_count = EXCLUDED.discard_count,
      queue_drop_count = EXCLUDED.queue_drop_count,
      update_seq = public.network_interface_current.update_seq + 1
    WHERE EXCLUDED.observed_at >= public.network_interface_current.observed_at
    RETURNING interface_id
  ), sampled AS (
    INSERT INTO public.network_interface_samples (
      organization_id, building_id, device_id, interface_id, observed_at,
      link_up, rx_bps, tx_bps, utilization_pct, error_delta, discard_delta,
      queue_drop_delta, sample
    )
    SELECT organization_id, building_id, device_id, "interfaceId", v_observed_at,
      coalesce("linkState", 'UNKNOWN') = 'UP', "rxBps", "txBps", "utilizationPct",
      "errorDelta", "discardDelta", "queueDropDelta",
      -- The counters, which have no column of their own on this table and
      -- were previously DISCARDED here: the literal '{}'::jsonb wrote 128
      -- rows carrying observed_at, link_up and nothing else, so the raw
      -- counters existed only in the _current upsert and the time series
      -- recorded THAT a cycle happened and nothing about throughput.
      -- jsonb_strip_nulls, exactly as the device branch above: a counter
      -- the router did not report is ABSENT, never a fabricated 0. The
      -- object is never empty, because linkState is always present, so a
      -- future '{}' is a defect and not a quiet cycle.
      jsonb_strip_nulls(jsonb_build_object(
        'linkState', coalesce("linkState", 'UNKNOWN'),
        'rxBytes', "rxBytes", 'txBytes', "txBytes",
        'errorCount', "errorCount", 'discardCount', "discardCount",
        'queueDropCount', "queueDropCount"
      ))
    FROM valid ON CONFLICT (interface_id, observed_at) DO NOTHING
    RETURNING interface_id
  )
  SELECT count(*) INTO v_interfaces FROM upserted;

  WITH input AS (
    SELECT * FROM jsonb_to_recordset(coalesce(p_payload->'clients', '[]'::jsonb)) AS row(
      "deviceId" uuid, "interfaceId" uuid, "sessionKey" text,
      "clientFingerprint" text, "observedMac" macaddr, "observedIp" inet,
      hostname text, "connectionType" text, "sessionType" text, "roomHint" text,
      "signalDbm" integer, "rxBytes" bigint, "txBytes" bigint,
      "rxBps" numeric, "txBps" numeric, "firstSeenAt" timestamptz,
      "lastSeenAt" timestamptz, "expiresAt" timestamptz, "randomizedMac" boolean
    )
  ), valid AS (
    SELECT input.*, device.organization_id, device.building_id
    FROM input JOIN public.network_devices device ON device.id = input."deviceId"
    LEFT JOIN public.network_interfaces interface
      ON interface.id = input."interfaceId" AND interface.device_id = device.id
    WHERE input."interfaceId" IS NULL OR interface.id IS NOT NULL
  ), upserted AS (
    INSERT INTO public.network_client_current (
      organization_id, building_id, device_id, interface_id, session_key,
      client_fingerprint, observed_mac, observed_ip, hostname, connection_type,
      session_type, room_hint, signal_dbm, rx_bytes, tx_bytes, rx_bps, tx_bps,
      first_seen_at, last_seen_at, observed_at, expires_at, randomized_mac, update_seq
    )
    SELECT organization_id, building_id, "deviceId", "interfaceId", "sessionKey",
      "clientFingerprint", "observedMac", "observedIp", hostname,
      coalesce("connectionType", 'UNKNOWN'), coalesce("sessionType", 'UNKNOWN'),
      -- NOT coalesce(..., 0). The worker emits no client byte counters at
      -- all (a DHCP lease record carries none -- measured on the demo hEX,
      -- RouterOS 7.20.8: /ip/dhcp-server/lease/get returns 21 keys and not
      -- one of them is a byte or packet count), so every 0 this wrote was
      -- the coalesce and not an observation. NULL is now representable and
      -- means exactly "not observed".
      "roomHint", "signalDbm", "rxBytes", "txBytes",
      "rxBps", "txBps", coalesce("firstSeenAt", v_observed_at),
      coalesce("lastSeenAt", v_observed_at), v_observed_at,
      coalesce("expiresAt", v_observed_at + INTERVAL '3 minutes'),
      coalesce("randomizedMac", false), 1
    FROM valid
    ON CONFLICT (organization_id, building_id, session_key) DO UPDATE SET
      device_id = EXCLUDED.device_id,
      interface_id = EXCLUDED.interface_id,
      client_fingerprint = EXCLUDED.client_fingerprint,
      observed_mac = EXCLUDED.observed_mac,
      observed_ip = EXCLUDED.observed_ip,
      hostname = EXCLUDED.hostname,
      connection_type = EXCLUDED.connection_type,
      session_type = EXCLUDED.session_type,
      room_hint = EXCLUDED.room_hint,
      signal_dbm = EXCLUDED.signal_dbm,
      rx_bytes = EXCLUDED.rx_bytes,
      tx_bytes = EXCLUDED.tx_bytes,
      rx_bps = EXCLUDED.rx_bps,
      tx_bps = EXCLUDED.tx_bps,
      first_seen_at = LEAST(public.network_client_current.first_seen_at, EXCLUDED.first_seen_at),
      last_seen_at = EXCLUDED.last_seen_at,
      observed_at = EXCLUDED.observed_at,
      expires_at = EXCLUDED.expires_at,
      randomized_mac = EXCLUDED.randomized_mac,
      update_seq = public.network_client_current.update_seq + 1
    WHERE EXCLUDED.observed_at >= public.network_client_current.observed_at
    RETURNING id
  ), sessions AS (
    INSERT INTO public.network_client_sessions (
      organization_id, building_id, device_id, interface_id, session_key,
      client_fingerprint, observed_mac, address_history, hostname, connection_type,
      first_seen_at, last_seen_at, rx_bytes, tx_bytes
    )
    SELECT organization_id, building_id, "deviceId", "interfaceId", "sessionKey",
      "clientFingerprint", "observedMac",
      CASE WHEN "observedIp" IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(host("observedIp")) END,
      hostname, coalesce("connectionType", 'UNKNOWN'),
      coalesce("firstSeenAt", v_observed_at), coalesce("lastSeenAt", v_observed_at),
      "rxBytes", "txBytes"
    FROM valid
    ON CONFLICT (organization_id, building_id, session_key) DO UPDATE SET
      interface_id = EXCLUDED.interface_id,
      observed_mac = EXCLUDED.observed_mac,
      address_history = CASE
        WHEN EXCLUDED.address_history = '[]'::jsonb
          OR public.network_client_sessions.address_history @> EXCLUDED.address_history
          THEN public.network_client_sessions.address_history
        ELSE public.network_client_sessions.address_history || EXCLUDED.address_history
      END,
      hostname = EXCLUDED.hostname,
      connection_type = EXCLUDED.connection_type,
      last_seen_at = GREATEST(public.network_client_sessions.last_seen_at, EXCLUDED.last_seen_at),
      rx_bytes = GREATEST(public.network_client_sessions.rx_bytes, EXCLUDED.rx_bytes),
      tx_bytes = GREATEST(public.network_client_sessions.tx_bytes, EXCLUDED.tx_bytes)
    RETURNING id
  )
  SELECT count(*) INTO v_clients FROM upserted;

  DELETE FROM public.network_client_current client WHERE client.expires_at <= v_now;
  RETURN jsonb_build_object(
    'observedAt', v_observed_at, 'devices', v_devices,
    'interfaces', v_interfaces, 'clients', v_clients
  );
END;
$_$;








--
-- Name: network_center_worker_inventory_legacy_impl_v1(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_inventory_legacy_impl_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private', 'extensions'
    AS $_$
DECLARE
  v_router public.network_devices%ROWTYPE;
  v_run app_private.network_aruba_discovery_runs%ROWTYPE;
  v_state app_private.network_aruba_router_state%ROWTYPE;
  v_candidate app_private.network_aruba_discovery_candidates%ROWTYPE;
  v_interfaces jsonb := '[]'::jsonb;
  v_aruba jsonb := '[]'::jsonb;
  v_response jsonb;
  v_item jsonb;
  v_aliases jsonb;
  v_metadata jsonb;
  v_run_id uuid;
  v_observed_at timestamptz;
  v_request_now timestamptz := clock_timestamp();
  v_now timestamptz;
  v_batch_index integer;
  v_batch_count integer;
  v_payload_hash character(64);
  v_existing_hash character(64);
  v_existing_response jsonb;
  v_stable_identity text;
  v_identity_source text;
  v_stable_key text;
  v_external_key text;
  v_display_name text;
  v_model text;
  v_serial_number text;
  v_uplink_interface_key text;
  v_management_address inet;
  v_sort_order integer;
  v_lifecycle_status text;
  v_device_id uuid;
  v_alias_text text;
  v_fingerprint character(64);
  v_quarantine_code text;
  v_quarantined_count integer := 0;
  v_new_today bigint;
  v_enrollment_count bigint;
  v_can_enroll boolean;
  v_seen_stable_keys text[] := ARRAY[]::text[];
  v_inserted integer;
  v_item_invalid boolean;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) > 524288
     OR coalesce(p_payload->>'routerDeviceId', '') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     OR coalesce(p_payload->>'discoveryRunId', '') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     OR coalesce(p_payload->>'batchIndex', '') !~ '^[0-9]{1,4}$'
     OR coalesce(p_payload->>'batchCount', '') !~ '^[0-9]{1,4}$'
     OR jsonb_typeof(coalesce(p_payload->'interfaces', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'aruba', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'quarantine', '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(coalesce(p_payload->'interfaces', '[]'::jsonb)) > 256
     OR jsonb_array_length(coalesce(p_payload->'aruba', '[]'::jsonb)) > 256
     OR jsonb_array_length(coalesce(p_payload->'quarantine', '[]'::jsonb)) > 256 THEN
    RAISE EXCEPTION 'Invalid or oversized inventory payload'
      USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_run_id := (p_payload->>'discoveryRunId')::uuid;
    v_observed_at := (p_payload->>'observedAt')::timestamptz;
    v_batch_index := (p_payload->>'batchIndex')::integer;
    v_batch_count := (p_payload->>'batchCount')::integer;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
    RAISE EXCEPTION 'Invalid inventory run metadata' USING ERRCODE = '22023';
  END;
  IF v_batch_count NOT BETWEEN 1 AND 4096
     OR v_batch_index < 0 OR v_batch_index >= v_batch_count
     OR v_observed_at IS NULL
     OR v_observed_at < v_request_now - INTERVAL '24 hours'
     OR v_observed_at > v_request_now + INTERVAL '5 minutes' THEN
    RAISE EXCEPTION 'Invalid inventory run bounds' USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.network_center_assert_safe_json_v1(
    p_payload, 'inventory discovery payload'
  );
  v_payload_hash := encode(extensions.digest(
    convert_to(p_payload::text, 'UTF8'), 'sha256'
  ), 'hex');

  SELECT router.* INTO v_router
  FROM public.network_devices router
  WHERE router.id = (p_payload->>'routerDeviceId')::uuid
    AND router.device_kind = 'MIKROTIK'
    AND router.is_active
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory router not found' USING ERRCODE = 'P0002';
  END IF;
  v_now := clock_timestamp();

  INSERT INTO app_private.network_aruba_router_state (
    organization_id, building_id, router_device_id,
    enrollment_started_at, last_discovery_at
  ) VALUES (
    v_router.organization_id, v_router.building_id, v_router.id,
    v_now, v_now
  )
  ON CONFLICT (router_device_id) DO UPDATE SET
    last_discovery_at = GREATEST(
      app_private.network_aruba_router_state.last_discovery_at,
      EXCLUDED.last_discovery_at
    ),
    updated_at = clock_timestamp();

  SELECT state.* INTO v_state
  FROM app_private.network_aruba_router_state state
  WHERE state.router_device_id = v_router.id
  FOR UPDATE;

  INSERT INTO app_private.network_aruba_discovery_runs (
    discovery_run_id, organization_id, building_id, router_device_id,
    observed_at, batch_count
  ) VALUES (
    v_run_id, v_router.organization_id, v_router.building_id,
    v_router.id, v_observed_at, v_batch_count
  ) ON CONFLICT (discovery_run_id) DO NOTHING;

  SELECT run.* INTO v_run
  FROM app_private.network_aruba_discovery_runs run
  WHERE run.discovery_run_id = v_run_id
  FOR UPDATE;
  IF v_run.router_device_id IS DISTINCT FROM v_router.id
     OR v_run.observed_at IS DISTINCT FROM v_observed_at
     OR v_run.batch_count IS DISTINCT FROM v_batch_count THEN
    RAISE EXCEPTION 'Discovery run metadata cannot change'
      USING ERRCODE = '23505';
  END IF;

  SELECT batch.payload_hash, batch.response
  INTO v_existing_hash, v_existing_response
  FROM app_private.network_aruba_discovery_batches batch
  WHERE batch.discovery_run_id = v_run_id
    AND batch.batch_index = v_batch_index
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing_hash IS DISTINCT FROM v_payload_hash THEN
      RAISE EXCEPTION 'Discovery batch replay changed payload'
        USING ERRCODE = '23505';
    END IF;
    RETURN v_existing_response;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(
      coalesce(p_payload->'interfaces', '[]'::jsonb)
    ) AS item("interfaceKey" text)
    GROUP BY btrim(item."interfaceKey")
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Interface keys must be unique within a batch'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(
      coalesce(p_payload->'interfaces', '[]'::jsonb)
    ) AS item(
      "interfaceKey" text, "displayName" text, "interfaceKind" text,
      "interfaceRole" text, "macAddress" text, "ifIndex" integer,
      "nominalSpeedBps" bigint, "sortOrder" integer, metadata jsonb
    )
    WHERE char_length(btrim(coalesce(item."interfaceKey", ''))) NOT BETWEEN 1 AND 160
       OR char_length(btrim(coalesce(
         item."displayName", item."interfaceKey", ''
       ))) NOT BETWEEN 1 AND 160
       OR upper(btrim(coalesce(item."interfaceKind", 'OTHER'))) NOT IN (
         'ETHERNET', 'WIRELESS', 'WIREGUARD', 'BRIDGE',
         'VLAN', 'LOOPBACK', 'OTHER'
       )
       OR upper(btrim(coalesce(item."interfaceRole", 'UNKNOWN'))) NOT IN (
         'WAN', 'LAN', 'ACCESS', 'UPLINK', 'MANAGEMENT', 'UNKNOWN'
       )
       OR (
         nullif(btrim(coalesce(item."macAddress", '')), '') IS NOT NULL
         AND btrim(item."macAddress") !~* '^([0-9a-f]{2}:){5}[0-9a-f]{2}$'
       )
       OR (item."ifIndex" IS NOT NULL AND item."ifIndex" < 0)
       OR (item."nominalSpeedBps" IS NOT NULL AND item."nominalSpeedBps" <= 0)
       OR coalesce(item."sortOrder", 0) < 0
       OR jsonb_typeof(coalesce(item.metadata, '{}'::jsonb)) <> 'object'
       OR octet_length(coalesce(item.metadata, '{}'::jsonb)::text) > 16384
  ) THEN
    RAISE EXCEPTION 'Malformed interface inventory item'
      USING ERRCODE = '22023';
  END IF;

  WITH input AS (
    SELECT
      btrim(item."interfaceKey") AS interface_key,
      btrim(coalesce(item."displayName", item."interfaceKey")) AS display_name,
      upper(btrim(coalesce(item."interfaceKind", 'OTHER'))) AS interface_kind,
      upper(btrim(coalesce(item."interfaceRole", 'UNKNOWN'))) AS interface_role,
      nullif(btrim(coalesce(item."macAddress", '')), '')::macaddr AS mac_address,
      item."ifIndex" AS if_index,
      item."nominalSpeedBps" AS nominal_speed_bps,
      coalesce(item."isProtected", false) AS requested_protection,
      coalesce(item."sortOrder", 0) AS sort_order,
      coalesce(item."isEnabled", true) AS is_enabled,
      -- =================================================================
      -- THE WORKER'S PROTECTION REPORT, PRESERVED WHERE THE LATCH CANNOT
      -- REACH IT (20260729148000).
      --
      -- Dropping the sticky OR above is necessary but NOT sufficient,
      -- because of a subtlety in ON CONFLICT: PostgreSQL fires the BEFORE
      -- INSERT trigger BEFORE it detects the conflict, and the row that
      -- trigger returns is what becomes EXCLUDED. So
      -- app_private.network_center_bind_managed_interface_v1 runs TWICE per
      -- interface per cycle, and its own INSERT-pass output --
      -- `NEW.is_protected := NEW.is_protected OR v_protected`, which is true
      -- for every DISCOVERED resource -- arrives back as EXCLUDED.is_protected
      -- and therefore as NEW.is_protected on the UPDATE pass. The trigger was
      -- reading its own output no matter what the ingest did with the stored
      -- value.
      --
      -- display_metadata is the one channel that is NOT rewritten by the
      -- trigger's protection logic, so the worker's report is stamped here,
      -- once, from the payload. `||` is right-biased, so a worker that put an
      -- `observedProtection` key in its own metadata cannot forge this: the
      -- value the server computed always wins.
      --
      -- The role component of the INSERT expression above (WAN/UPLINK/
      -- MANAGEMENT force protection) is deliberately not repeated: the only
      -- consumer requires interface_role = 'ACCESS' already, so those roles
      -- are excluded on their own clause and repeating them here would add a
      -- second place for the two rules to drift apart.
      -- =================================================================
      coalesce(item.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'observedProtection', coalesce(item."isProtected", false)
        ) AS display_metadata
    FROM jsonb_to_recordset(
      coalesce(p_payload->'interfaces', '[]'::jsonb)
    ) AS item(
      "interfaceKey" text, "displayName" text, "interfaceKind" text,
      "interfaceRole" text, "macAddress" text, "ifIndex" integer,
      "nominalSpeedBps" bigint, "isProtected" boolean,
      "sortOrder" integer, "isEnabled" boolean, metadata jsonb
    )
  ), upserted AS (
    INSERT INTO public.network_interfaces (
      organization_id, building_id, device_id, interface_key, display_name,
      interface_kind, interface_role, mac_address, if_index,
      nominal_speed_bps, is_protected, sort_order, is_enabled,
      is_managed, display_metadata
    )
    SELECT
      v_router.organization_id, v_router.building_id, v_router.id,
      input.interface_key, input.display_name, input.interface_kind,
      input.interface_role, input.mac_address, input.if_index,
      input.nominal_speed_bps,
      input.requested_protection OR input.interface_role IN (
        'WAN', 'UPLINK', 'MANAGEMENT'
      ),
      input.sort_order, input.is_enabled, true, input.display_metadata
    FROM input
    ON CONFLICT (device_id, interface_key) DO UPDATE SET
      display_name = EXCLUDED.display_name,
      interface_kind = EXCLUDED.interface_kind,
      interface_role = EXCLUDED.interface_role,
      mac_address = EXCLUDED.mac_address,
      if_index = EXCLUDED.if_index,
      nominal_speed_bps = EXCLUDED.nominal_speed_bps,
      -- =================================================================
      -- THE STICKY OR IS THE WHOLE OF BLOCKER B (20260729148000).
      --
      -- This expression carried the STORED protection forward and OR-ed the
      -- fresh observation into it. Because
      -- app_private.network_center_bind_managed_interface_v1 then fires as a
      -- BEFORE trigger and, for a DISCOVERED resource, forces is_protected
      -- true unconditionally, the stored value was true from the very first
      -- inventory cycle. So from the SECOND cycle onward NEW.is_protected was
      -- true no matter what the router reported, and the trigger's
      -- eligibility test -- which asks whether the port is unprotected -- was
      -- reading back a value this statement had manufactured instead of the
      -- worker's observation. metadata.eligibleAccess went false on cycle two
      -- and stayed false forever, and that is exactly the precondition
      -- app_private.network_center_enroll_access_interface_v1 requires.
      -- Measured in production 2026-08-03: eligibleAccess = 'false' on all
      -- five managed resources of the demo router, refreshed every 60
      -- seconds, ether2..ether5 all is_protected = true, and the enrollment
      -- door with zero callers. The act of discovering a port destroyed the
      -- precondition for enrolling it, so CYCLE_ACCESS_PORT has never been
      -- reachable for any port on any router in this deployment.
      --
      -- EXCLUDED.is_protected is the FRESH observation, already widened by
      -- the INSERT list above to `requested OR role IN (WAN, UPLINK,
      -- MANAGEMENT)`, so a WAN, uplink or management port is re-protected on
      -- every cycle and the table CHECK that requires it still holds.
      --
      -- NOTHING BECOMES CYCLABLE BY DROPPING THE OR. The bind trigger's last
      -- statement is `NEW.is_protected := NEW.is_protected OR v_protected`,
      -- where v_protected is public.network_managed_resources.protected after
      -- its upsert: true for every DISCOVERED resource, and lowered ONLY by
      -- the DISCOVERED -> ENROLLED transition that
      -- app_private.network_center_guard_managed_resource_v1 polices. A port
      -- nobody enrolled is therefore still forced protected on every cycle.
      -- What changes is that the trigger now decides from the router's report
      -- rather than from its own previous output -- including the worker's
      -- `:lan-recovery` firewall-interface flag, which consequently keeps
      -- making a shape-eligible port ineligible, as its regression test
      -- already required.
      -- =================================================================
      is_protected = EXCLUDED.is_protected,
      sort_order = EXCLUDED.sort_order,
      is_enabled = EXCLUDED.is_enabled,
      is_managed = true,
      display_metadata = EXCLUDED.display_metadata,
      updated_at = clock_timestamp()
    RETURNING id, interface_key
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'interfaceKey', upserted.interface_key,
    'id', upserted.id
  ) ORDER BY upserted.interface_key), '[]'::jsonb)
  INTO v_interfaces
  FROM upserted;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(
      coalesce(p_payload->'quarantine', '[]'::jsonb)
    ) AS item(value)
  LOOP
    v_quarantine_code := coalesce(v_item->>'code', '');
    v_fingerprint := lower(coalesce(v_item->>'fingerprint', ''));
    IF v_quarantine_code <> 'ARUBA_STABLE_IDENTITY_INVALID'
       OR v_fingerprint !~ '^[a-f0-9]{64}$' THEN
      v_quarantine_code := 'ARUBA_WORKER_QUARANTINE_INVALID';
      v_fingerprint := encode(extensions.digest(
        convert_to(v_item::text, 'UTF8'), 'sha256'
      ), 'hex');
    END IF;
    INSERT INTO app_private.network_aruba_quarantine (
      organization_id, building_id, router_device_id,
      discovery_run_id, batch_index, reason_code, fingerprint, observed_at
    ) VALUES (
      v_router.organization_id, v_router.building_id, v_router.id,
      v_run_id, v_batch_index, v_quarantine_code, v_fingerprint, v_now
    ) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    v_quarantined_count := v_quarantined_count + v_inserted;
  END LOOP;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(
      coalesce(p_payload->'aruba', '[]'::jsonb)
    ) AS item(value)
  LOOP
    v_item_invalid := jsonb_typeof(v_item) <> 'object';
    v_stable_identity := btrim(coalesce(v_item->>'stableIdentity', ''));
    v_identity_source := upper(btrim(coalesce(v_item->>'identitySource', '')));
    v_external_key := btrim(coalesce(v_item->>'externalKey', ''));
    v_display_name := btrim(coalesce(v_item->>'displayName', ''));
    v_aliases := coalesce(v_item->'aliases', '[]'::jsonb);
    v_metadata := coalesce(v_item->'metadata', '{}'::jsonb);
    v_model := nullif(btrim(coalesce(v_item->>'model', '')), '');
    v_uplink_interface_key := nullif(btrim(coalesce(
      v_item->>'uplinkInterfaceKey', ''
    )), '');
    v_sort_order := CASE
      WHEN coalesce(v_item->>'sortOrder', '') ~ '^[0-9]{1,9}$'
        THEN (v_item->>'sortOrder')::integer
      ELSE 0
    END;
    v_lifecycle_status := upper(btrim(coalesce(
      v_item->>'lifecycleStatus', 'ONLINE'
    )));
    v_serial_number := CASE WHEN v_identity_source = 'SERIAL'
      THEN v_stable_identity ELSE NULL END;
    v_stable_key := CASE v_identity_source
      WHEN 'SERIAL' THEN 'serial:' || v_stable_identity
      WHEN 'HARDWARE_MAC' THEN 'mac:' || lower(v_stable_identity)
      ELSE ''
    END;
    v_management_address := NULL;
    BEGIN
      IF nullif(btrim(coalesce(v_item->>'managementAddress', '')), '')
         IS NOT NULL THEN
        v_management_address := btrim(v_item->>'managementAddress')::inet;
      END IF;
    EXCEPTION WHEN invalid_text_representation THEN
      v_management_address := NULL;
      v_stable_key := '';
    END;

    IF jsonb_typeof(v_aliases) <> 'array' THEN
      v_item_invalid := true;
      v_aliases := '[]'::jsonb;
    END IF;
    IF jsonb_typeof(v_metadata) <> 'object' THEN
      v_item_invalid := true;
      v_metadata := '{}'::jsonb;
    END IF;

    IF v_item_invalid
       OR lower(coalesce(v_item->>'displayOnly', '')) <> 'true'
       OR char_length(v_display_name) NOT BETWEEN 1 AND 160
       OR jsonb_array_length(v_aliases) > 32
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(v_aliases) alias(value)
         WHERE jsonb_typeof(alias.value) <> 'string'
            OR char_length(btrim(alias.value #>> '{}')) NOT BETWEEN 1 AND 160
       )
       OR octet_length(v_metadata::text) > 16384
       OR v_sort_order < 0
       OR v_lifecycle_status NOT IN ('ONLINE', 'OFFLINE')
       OR (
         v_identity_source = 'SERIAL'
         AND v_stable_identity !~ '^[A-Z0-9][A-Z0-9._:-]{0,152}$'
       )
       OR (
         v_identity_source = 'HARDWARE_MAC'
         AND (
           lower(v_stable_identity) !~
             '^[0-9a-f][02468ace](:[0-9a-f]{2}){5}$'
           OR lower(v_stable_identity) IN (
             '00:00:00:00:00:00', 'ff:ff:ff:ff:ff:ff'
           )
         )
       )
       OR v_identity_source NOT IN ('SERIAL', 'HARDWARE_MAC')
       OR v_external_key IS DISTINCT FROM v_stable_key
       OR v_stable_key = ''
       OR v_stable_key = ANY(v_seen_stable_keys) THEN
      v_fingerprint := encode(extensions.digest(
        convert_to(v_item::text, 'UTF8'), 'sha256'
      ), 'hex');
      INSERT INTO app_private.network_aruba_quarantine (
        organization_id, building_id, router_device_id,
        discovery_run_id, batch_index, reason_code, fingerprint, observed_at
      ) VALUES (
        v_router.organization_id, v_router.building_id, v_router.id,
        v_run_id, v_batch_index, 'ARUBA_ITEM_INVALID', v_fingerprint, v_now
      ) ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_quarantined_count := v_quarantined_count + v_inserted;
      CONTINUE;
    END IF;
    v_seen_stable_keys := array_append(v_seen_stable_keys, v_stable_key);
    v_device_id := NULL;

    SELECT device.id INTO v_device_id
    FROM public.network_devices device
    WHERE device.parent_device_id = v_router.id
      AND device.device_kind = 'ARUBA'
      AND device.aruba_stable_key = v_stable_key
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.network_devices device
      SET external_key = v_external_key,
          display_name = v_display_name,
          vendor = 'Aruba',
          model = v_model,
          serial_number = v_serial_number,
          uplink_interface_key = v_uplink_interface_key,
          lifecycle_status = v_lifecycle_status,
          write_capability = false,
          is_active = true,
          credential_ref = NULL,
          inventory_metadata = (v_metadata - 'managementAddress')
            || CASE WHEN v_management_address IS NULL THEN '{}'::jsonb
              ELSE jsonb_build_object(
                'managementAddress', host(v_management_address)
              ) END,
          aruba_discovery_last_seen_at = GREATEST(
            device.aruba_discovery_last_seen_at, v_now
          ),
          updated_at = v_now
      WHERE device.id = v_device_id;
      v_can_enroll := true;
    ELSE
      INSERT INTO app_private.network_aruba_discovery_candidates (
        organization_id, building_id, router_device_id, stable_key,
        identity_source, external_key, display_name, model, serial_number,
        uplink_interface_key, management_address, sort_order, aliases,
        inventory_metadata, first_seen_at, last_seen_at,
        sighting_count, last_discovery_run_id
      ) VALUES (
        v_router.organization_id, v_router.building_id, v_router.id,
        v_stable_key, v_identity_source, v_external_key, v_display_name,
        v_model, v_serial_number, v_uplink_interface_key,
        v_management_address, v_sort_order, v_aliases, v_metadata,
        v_now, v_now, 1, v_run_id
      )
      ON CONFLICT (router_device_id, stable_key) DO UPDATE SET
        external_key = EXCLUDED.external_key,
        display_name = EXCLUDED.display_name,
        model = EXCLUDED.model,
        serial_number = EXCLUDED.serial_number,
        uplink_interface_key = EXCLUDED.uplink_interface_key,
        management_address = EXCLUDED.management_address,
        sort_order = EXCLUDED.sort_order,
        aliases = EXCLUDED.aliases,
        inventory_metadata = EXCLUDED.inventory_metadata,
        last_seen_at = GREATEST(
          app_private.network_aruba_discovery_candidates.last_seen_at,
          EXCLUDED.last_seen_at
        ),
        sighting_count =
          app_private.network_aruba_discovery_candidates.sighting_count
          + CASE WHEN
              app_private.network_aruba_discovery_candidates.last_discovery_run_id
                IS DISTINCT FROM EXCLUDED.last_discovery_run_id
            THEN 1 ELSE 0 END,
        last_discovery_run_id = EXCLUDED.last_discovery_run_id,
        updated_at = clock_timestamp();

      SELECT candidate.* INTO v_candidate
      FROM app_private.network_aruba_discovery_candidates candidate
      WHERE candidate.router_device_id = v_router.id
        AND candidate.stable_key = v_stable_key
      FOR UPDATE;

      SELECT count(*) INTO v_new_today
      FROM public.network_devices device
      WHERE device.parent_device_id = v_router.id
        AND device.device_kind = 'ARUBA'
        AND device.aruba_identity_source IN ('SERIAL', 'HARDWARE_MAC')
        AND device.aruba_discovery_first_seen_at >= v_now - INTERVAL '24 hours';
      SELECT count(*) INTO v_enrollment_count
      FROM public.network_devices device
      WHERE device.parent_device_id = v_router.id
        AND device.device_kind = 'ARUBA'
        AND device.aruba_identity_source IN ('SERIAL', 'HARDWARE_MAC')
        AND device.aruba_discovery_first_seen_at >= v_state.enrollment_started_at;

      v_can_enroll := v_run.new_identity_count < 64 AND (
        (
          v_now < v_state.enrollment_started_at + INTERVAL '24 hours'
          AND v_enrollment_count < 512
        )
        OR (
          v_now >= v_state.enrollment_started_at + INTERVAL '24 hours'
          AND v_new_today < 128
          AND v_candidate.sighting_count >= 3
          AND v_candidate.last_seen_at >=
            v_candidate.first_seen_at + INTERVAL '10 minutes'
        )
      );

      IF v_can_enroll THEN
        INSERT INTO public.network_devices (
          organization_id, building_id, device_kind, external_key,
          display_name, vendor, model, serial_number, parent_device_id,
          uplink_interface_key, sort_order, lifecycle_status,
          write_capability, is_active, credential_ref, inventory_metadata,
          aruba_stable_key, aruba_identity_source,
          aruba_discovery_state, aruba_discovery_first_seen_at,
          aruba_discovery_last_seen_at
        ) VALUES (
          v_router.organization_id, v_router.building_id, 'ARUBA',
          v_external_key, v_display_name, 'Aruba', v_model, v_serial_number,
          v_router.id, v_uplink_interface_key, v_sort_order,
          v_lifecycle_status, false, true, NULL,
          (v_metadata - 'managementAddress')
            || CASE WHEN v_management_address IS NULL THEN '{}'::jsonb
              ELSE jsonb_build_object(
                'managementAddress', host(v_management_address)
              ) END,
          v_stable_key, v_identity_source, 'DISCOVERED', v_now, v_now
        )
        ON CONFLICT (parent_device_id, aruba_stable_key)
          WHERE device_kind = 'ARUBA'
        DO UPDATE SET
          display_name = EXCLUDED.display_name,
          model = EXCLUDED.model,
          serial_number = EXCLUDED.serial_number,
          uplink_interface_key = EXCLUDED.uplink_interface_key,
          lifecycle_status = EXCLUDED.lifecycle_status,
          is_active = true,
          inventory_metadata = EXCLUDED.inventory_metadata,
          aruba_discovery_last_seen_at = GREATEST(
            public.network_devices.aruba_discovery_last_seen_at, v_now
          ),
          updated_at = v_now
        RETURNING id INTO v_device_id;

        UPDATE app_private.network_aruba_discovery_runs run
        SET new_identity_count = run.new_identity_count + 1,
            updated_at = v_now
        WHERE run.discovery_run_id = v_run_id
        RETURNING run.* INTO v_run;
        DELETE FROM app_private.network_aruba_discovery_candidates candidate
        WHERE candidate.router_device_id = v_router.id
          AND candidate.stable_key = v_stable_key;
      ELSE
        v_fingerprint := encode(extensions.digest(
          convert_to(v_stable_key, 'UTF8'), 'sha256'
        ), 'hex');
        INSERT INTO app_private.network_aruba_quarantine (
          organization_id, building_id, router_device_id,
          discovery_run_id, batch_index, reason_code, fingerprint, observed_at
        ) VALUES (
          v_router.organization_id, v_router.building_id, v_router.id,
          v_run_id, v_batch_index, 'ARUBA_IDENTITY_RATE_LIMITED',
          v_fingerprint, v_now
        ) ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        v_quarantined_count := v_quarantined_count + v_inserted;
      END IF;
    END IF;

    FOR v_alias_text IN
      SELECT btrim(alias.value #>> '{}')
      FROM jsonb_array_elements(v_aliases) alias(value)
    LOOP
      INSERT INTO app_private.network_aruba_aliases (
        organization_id, building_id, router_device_id, stable_key,
        alias, first_seen_at, last_seen_at, tombstoned_at
      ) VALUES (
        v_router.organization_id, v_router.building_id, v_router.id,
        v_stable_key, v_alias_text, v_now, v_now, NULL
      )
      ON CONFLICT (router_device_id, stable_key, alias) DO UPDATE SET
        last_seen_at = GREATEST(
          app_private.network_aruba_aliases.last_seen_at,
          EXCLUDED.last_seen_at
        ),
        tombstoned_at = NULL;
    END LOOP;
    UPDATE app_private.network_aruba_aliases alias
    SET tombstoned_at = coalesce(alias.tombstoned_at, v_now)
    WHERE alias.router_device_id = v_router.id
      AND alias.stable_key = v_stable_key
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(v_aliases) current_alias(value)
        WHERE btrim(current_alias.value #>> '{}') = alias.alias
      );

    IF v_can_enroll AND v_device_id IS NOT NULL THEN
      v_aruba := v_aruba || jsonb_build_array(jsonb_build_object(
        'externalKey', v_external_key,
        'id', v_device_id
      ));
    END IF;
  END LOOP;

  WITH victims AS MATERIALIZED (
    SELECT quarantine.id
    FROM app_private.network_aruba_quarantine quarantine
    WHERE quarantine.router_device_id = v_router.id
    ORDER BY quarantine.observed_at DESC, quarantine.id DESC
    OFFSET 1000
    LIMIT 512
  )
  DELETE FROM app_private.network_aruba_quarantine quarantine
  USING victims
  WHERE quarantine.id = victims.id;

  v_response := jsonb_build_object(
    'routerDeviceId', v_router.id,
    'interfaces', v_interfaces,
    'aruba', v_aruba,
    'interfaceCount', jsonb_array_length(v_interfaces),
    'arubaCount', jsonb_array_length(v_aruba),
    'inventoryStatus', CASE WHEN v_quarantined_count > 0
      THEN 'DEGRADED' ELSE 'OK' END,
    'quarantinedCount', v_quarantined_count
  );

  INSERT INTO app_private.network_aruba_discovery_batches (
    discovery_run_id, batch_index, payload_hash, response
  ) VALUES (
    v_run_id, v_batch_index, v_payload_hash, v_response
  );
  RETURN v_response;
END;
$_$;








--
-- Name: network_center_worker_renew_legacy_impl_v1(text, uuid, uuid, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_renew_legacy_impl_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE v_now timestamptz := clock_timestamp(); v_expiry timestamptz;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_command_id IS NULL OR p_lease_token IS NULL
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid lease renewal request' USING ERRCODE = '22023';
  END IF;
  v_expiry := v_now + make_interval(secs => p_lease_seconds);
  UPDATE public.network_device_leases lease
  SET heartbeat_at = v_now, expires_at = v_expiry
  WHERE lease.command_id = p_command_id AND lease.lease_token = p_lease_token
    AND lease.lease_owner = p_worker_id AND lease.expires_at > v_now;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active device lease not found' USING ERRCODE = '55000'; END IF;
  UPDATE public.network_commands command
  SET lease_expires_at = v_expiry, updated_at = v_now
  WHERE command.id = p_command_id AND command.lease_token = p_lease_token
    AND command.lease_owner = p_worker_id
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING');
  IF NOT FOUND THEN RAISE EXCEPTION 'Active command lease not found' USING ERRCODE = '55000'; END IF;
  RETURN jsonb_build_object('commandId', p_command_id, 'leaseExpiresAt', v_expiry);
END;
$_$;








--
-- Name: network_center_worker_snapshot_legacy_impl_v1(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_snapshot_legacy_impl_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_device public.network_devices%ROWTYPE;
  v_command public.network_commands%ROWTYPE;
  v_snapshot public.network_config_snapshots%ROWTYPE;
  v_snapshot_id uuid;
  v_command_id uuid;
  v_source text;
  v_normalized jsonb;
  v_lines jsonb;
  v_hash text;
  v_encrypted_artifact_hash text;
  v_artifact_key text;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) > 2097152 THEN
    RAISE EXCEPTION 'Invalid snapshot payload' USING ERRCODE = '22023';
  END IF;
  v_snapshot_id := (p_payload->>'snapshotId')::uuid;
  v_command_id := nullif(p_payload->>'commandId', '')::uuid;
  v_source := upper(btrim(coalesce(p_payload->>'source', '')));
  v_normalized := p_payload->'normalizedContent';
  v_lines := p_payload->'redactedLines';
  v_hash := lower(btrim(coalesce(p_payload->>'contentHash', '')));
  v_encrypted_artifact_hash := lower(btrim(coalesce(
    p_payload->>'encryptedArtifactHash', ''
  )));
  v_artifact_key := nullif(btrim(coalesce(p_payload->>'artifactKey', '')), '');
  IF v_source NOT IN ('MANUAL', 'SCHEDULED', 'PRE_ACTION', 'POST_ACTION')
     OR jsonb_typeof(v_normalized) <> 'object'
     OR octet_length(v_normalized::text) > 1048576
     OR jsonb_typeof(v_lines) <> 'array'
     OR octet_length(v_lines::text) > 1048576
     OR v_hash !~ '^[a-f0-9]{64}$'
     OR v_encrypted_artifact_hash !~ '^[a-f0-9]{64}$'
     OR (v_artifact_key IS NOT NULL AND (
       char_length(v_artifact_key) NOT BETWEEN 8 AND 500
       OR v_artifact_key !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]+$'
     )) THEN
    RAISE EXCEPTION 'Malformed or unbounded redacted snapshot'
      USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    v_normalized, 'normalized configuration snapshot'
  );
  PERFORM app_private.network_center_assert_safe_json_v1(
    v_lines, 'redacted configuration lines'
  );
  SELECT device.* INTO v_device
  FROM public.network_devices device
  WHERE device.id = (p_payload->>'deviceId')::uuid
    AND device.device_kind = 'MIKROTIK'
    AND device.is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Snapshot device not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_command_id IS NOT NULL THEN
    SELECT command.* INTO v_command
    FROM public.network_commands command
    WHERE command.id = v_command_id
      AND command.organization_id = v_device.organization_id
      AND command.building_id = v_device.building_id
      AND command.device_id = v_device.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Snapshot command not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;
  INSERT INTO public.network_config_snapshots (
    id, organization_id, building_id, device_id, command_id, source,
    schema_version, normalized_content, redacted_lines, content_hash,
    encrypted_artifact_hash, artifact_key, created_by, worker_id
  ) VALUES (
    v_snapshot_id, v_device.organization_id, v_device.building_id, v_device.id,
    v_command_id, v_source, coalesce((p_payload->>'schemaVersion')::integer, 1),
    v_normalized, v_lines, v_hash, v_encrypted_artifact_hash,
    v_artifact_key, v_command.requested_by, p_worker_id
  ) ON CONFLICT (id) DO NOTHING;
  SELECT snapshot.* INTO v_snapshot
  FROM public.network_config_snapshots snapshot
  WHERE snapshot.id = v_snapshot_id
    AND snapshot.organization_id = v_device.organization_id
    AND snapshot.building_id = v_device.building_id
    AND snapshot.device_id = v_device.id;
  IF NOT FOUND
     OR v_snapshot.content_hash IS DISTINCT FROM v_hash
     OR v_snapshot.encrypted_artifact_hash IS DISTINCT FROM
       v_encrypted_artifact_hash THEN
    RAISE EXCEPTION 'Snapshot idempotency conflict' USING ERRCODE = '23505';
  END IF;
  RETURN jsonb_build_object(
    'snapshotId', v_snapshot.id,
    'contentHash', v_snapshot.content_hash,
    'encryptedArtifactHash', v_snapshot.encrypted_artifact_hash,
    'createdAt', v_snapshot.created_at,
    'source', v_snapshot.source
  );
END;
$_$;








--
-- Name: network_center_worker_upsert_incident_legacy_impl_v1(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.network_center_worker_upsert_incident_legacy_impl_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_device public.network_devices%ROWTYPE;
  v_incident public.network_incidents%ROWTYPE;
  v_interface_id uuid;
  v_event_key text;
  v_fingerprint text;
  v_type text;
  v_severity text;
  v_title text;
  v_summary text;
  v_observed_at timestamptz;
  v_values jsonb;
  v_resolved boolean;
  v_event_kind text;
  v_seq bigint;
BEGIN
  IF p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
     OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) > 65536 THEN
    RAISE EXCEPTION 'Invalid incident payload' USING ERRCODE = '22023';
  END IF;
  v_event_key := btrim(coalesce(p_payload->>'eventKey', ''));
  v_fingerprint := btrim(coalesce(p_payload->>'fingerprint', ''));
  v_type := upper(btrim(coalesce(p_payload->>'incidentType', '')));
  v_severity := upper(btrim(coalesce(p_payload->>'severity', '')));
  v_title := btrim(coalesce(p_payload->>'title', ''));
  v_summary := btrim(coalesce(p_payload->>'summary', ''));
  v_observed_at := nullif(p_payload->>'observedAt', '')::timestamptz;
  v_values := coalesce(p_payload->'observedValues', '{}'::jsonb);
  v_resolved := coalesce((p_payload->>'resolved')::boolean, false);
  IF v_event_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
     OR char_length(v_fingerprint) NOT BETWEEN 8 AND 200
     OR v_type !~ '^[A-Z][A-Z0-9_]{2,63}$'
     OR v_severity NOT IN ('INFO', 'WARNING', 'CRITICAL')
     OR char_length(v_title) NOT BETWEEN 3 AND 200
     OR char_length(v_summary) NOT BETWEEN 3 AND 2000
     OR v_observed_at IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - v_observed_at))) > 600
     OR jsonb_typeof(v_values) <> 'object' OR octet_length(v_values::text) > 16384 THEN
    RAISE EXCEPTION 'Malformed incident payload' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    p_payload, 'incident payload'
  );
  SELECT device.* INTO v_device FROM public.network_devices device
  WHERE device.id = (p_payload->>'deviceId')::uuid AND device.is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Incident device not found' USING ERRCODE = 'P0002'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.network_incident_events event
    WHERE event.organization_id = v_device.organization_id
      AND event.external_event_key = v_event_key
  ) THEN
    SELECT incident.* INTO v_incident
    FROM public.network_incidents incident
    JOIN public.network_incident_events event
      ON event.organization_id = incident.organization_id
     AND event.building_id = incident.building_id
     AND event.incident_id = incident.id
    WHERE event.organization_id = v_device.organization_id
      AND event.external_event_key = v_event_key
    LIMIT 1;
    RETURN jsonb_build_object('incidentId', v_incident.id, 'status', v_incident.status);
  END IF;
  IF nullif(p_payload->>'interfaceId', '') IS NOT NULL THEN
    v_interface_id := (p_payload->>'interfaceId')::uuid;
    IF NOT EXISTS (
      SELECT 1 FROM public.network_interfaces interface
      WHERE interface.id = v_interface_id AND interface.device_id = v_device.id
        AND interface.organization_id = v_device.organization_id
        AND interface.building_id = v_device.building_id
    ) THEN RAISE EXCEPTION 'Incident interface not found' USING ERRCODE = 'P0002'; END IF;
  END IF;

  SELECT incident.* INTO v_incident FROM public.network_incidents incident
  WHERE incident.organization_id = v_device.organization_id
    AND incident.building_id = v_device.building_id
    AND incident.fingerprint = v_fingerprint AND incident.status <> 'RESOLVED'
  FOR UPDATE;
  IF v_resolved THEN
    IF NOT FOUND THEN
      RETURN jsonb_build_object('incidentId', NULL, 'status', 'RESOLVED', 'alreadyClosed', true);
    END IF;
    UPDATE public.network_incidents
    SET status = 'RESOLVED', last_observed_at = greatest(last_observed_at, v_observed_at),
        recovered_at = coalesce(recovered_at, v_observed_at), resolved_at = v_observed_at,
        version = version + 1
    WHERE id = v_incident.id RETURNING * INTO v_incident;
    v_event_kind := 'RESOLVED';
  ELSIF NOT FOUND THEN
    INSERT INTO public.network_incidents (
      organization_id, building_id, device_id, interface_id, fingerprint,
      incident_type, severity, status, title, summary, availability_impact,
      opened_at, last_observed_at, observed_values
    ) VALUES (
      v_device.organization_id, v_device.building_id, v_device.id, v_interface_id,
      v_fingerprint, v_type, v_severity, 'OPEN', v_title, v_summary,
      coalesce((p_payload->>'availabilityImpact')::boolean, false),
      v_observed_at, v_observed_at, v_values
    ) RETURNING * INTO v_incident;
    v_event_kind := 'OPENED';
  ELSE
    UPDATE public.network_incidents
    SET severity = v_severity, title = v_title, summary = v_summary,
        last_observed_at = greatest(last_observed_at, v_observed_at),
        occurrence_count = occurrence_count + 1, observed_values = v_values,
        version = version + 1
    WHERE id = v_incident.id RETURNING * INTO v_incident;
    v_event_kind := 'OBSERVED';
  END IF;
  SELECT coalesce(max(event.event_seq) + 1, 1) INTO v_seq
  FROM public.network_incident_events event WHERE event.incident_id = v_incident.id;
  INSERT INTO public.network_incident_events (
    organization_id, building_id, incident_id, event_seq, event_kind, severity,
    occurred_at, worker_id, details, external_event_key
  ) VALUES (
    v_device.organization_id, v_device.building_id, v_incident.id, v_seq,
    v_event_kind, v_severity, v_observed_at, p_worker_id, v_values, v_event_key
  );
  IF v_event_kind IN ('OPENED', 'RESOLVED') THEN
    INSERT INTO public.network_outbox_events (
      organization_id, building_id, event_type, aggregate_type, aggregate_id, payload, occurred_at
    ) VALUES (
      v_device.organization_id, v_device.building_id,
      CASE WHEN v_event_kind = 'OPENED' THEN 'network.incident.opened' ELSE 'network.incident.resolved' END,
      'incident', v_incident.id,
      jsonb_build_object('severity', v_severity, 'title', v_title), v_observed_at
    );
  END IF;
  RETURN jsonb_build_object(
    'incidentId', v_incident.id, 'status', v_incident.status,
    'eventKind', v_event_kind, 'eventSeq', v_seq
  );
END;
$_$;








