--
-- Name: notification_events_normalize_v1(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notification_events_normalize_v1(p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_keys constant text[] := array['E1','E2','E3','E4','E5','E6'];
  v_out  jsonb := '{}'::jsonb;
  v_src  jsonb;
  k       text;
  v       jsonb;
  v_on    boolean;
  v_min   numeric;
begin
  v_src := p_events;
  if v_src is null or jsonb_typeof(v_src) = 'null' then
    v_src := '{}'::jsonb;
  end if;
  if jsonb_typeof(v_src) <> 'object' then
    raise exception 'Cấu hình sự kiện phải là một object JSON.' using errcode = '22023';
  end if;

  -- Khoá lạ là lỗi, không im lặng bỏ qua: im lặng = người dùng tưởng đã tắt mà thực ra chưa.
  for k in select jsonb_object_keys(v_src) loop
    if not (k = any (v_keys)) then
      raise exception 'Sự kiện không hợp lệ: %. Chỉ nhận E1, E2, E3, E4, E5, E6.', k using errcode = '22023';
    end if;
  end loop;

  foreach k in array v_keys loop
    v := v_src -> k;
    if v is null or jsonb_typeof(v) = 'null' then
      v_out := v_out || jsonb_build_object(k, jsonb_build_object('enabled', true, 'min_amount', null));
      continue;
    end if;
    if jsonb_typeof(v) <> 'object' then
      raise exception 'Cấu hình sự kiện % phải là object JSON.', k using errcode = '22023';
    end if;

    if jsonb_exists(v, 'enabled') and jsonb_typeof(v -> 'enabled') <> 'boolean' then
      raise exception 'events.%.enabled phải là true hoặc false.', k using errcode = '22023';
    end if;
    v_on := coalesce((v ->> 'enabled')::boolean, true);

    if jsonb_exists(v, 'min_amount') and jsonb_typeof(v -> 'min_amount') not in ('null', 'number') then
      raise exception 'events.%.min_amount phải là số hoặc null.', k using errcode = '22023';
    end if;
    if jsonb_exists(v, 'min_amount') and jsonb_typeof(v -> 'min_amount') = 'number' then
      v_min := (v ->> 'min_amount')::numeric;
      if v_min < 0 then
        raise exception 'events.%.min_amount không được âm.', k using errcode = '22023';
      end if;
    else
      v_min := null;
    end if;

    v_out := v_out || jsonb_build_object(k, jsonb_build_object('enabled', v_on, 'min_amount', v_min));
  end loop;

  return v_out;
end
$$;








--
-- Name: notification_prefs_normalize_v1(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notification_prefs_normalize_v1(p_prefs jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_keys      constant text[] := array['E1','E2','E3','E4','E5','E6'];
  v_cadences  constant text[] := array['IMMEDIATE','DIGEST','OFF'];
  v_out jsonb := '{}'::jsonb;
  k     text;
  v     jsonb;
  v_cad text;
begin
  if p_prefs is null or jsonb_typeof(p_prefs) = 'null' then
    raise exception 'Thiếu dữ liệu sở thích thông báo.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_prefs) <> 'object' then
    raise exception 'Sở thích thông báo phải là một object JSON.' using errcode = '22023';
  end if;

  for k in select jsonb_object_keys(p_prefs) loop
    if not (k = any (v_keys)) then
      raise exception 'Sự kiện không hợp lệ: %. Chỉ nhận E1, E2, E3, E4, E5, E6.', k using errcode = '22023';
    end if;
    v := p_prefs -> k;
    if jsonb_typeof(v) <> 'object' then
      raise exception 'Sở thích của % phải là object JSON.', k using errcode = '22023';
    end if;
    if jsonb_exists(v, 'in_app') and jsonb_typeof(v -> 'in_app') <> 'boolean' then
      raise exception '%.in_app phải là true hoặc false.', k using errcode = '22023';
    end if;
    if jsonb_exists(v, 'push') and jsonb_typeof(v -> 'push') <> 'boolean' then
      raise exception '%.push phải là true hoặc false.', k using errcode = '22023';
    end if;

    -- 🔴 FIELD VẮNG ⇒ PHÁT JSON `null`, KHÔNG phát mặc định `true/IMMEDIATE`.
    -- Bản nháp điền cứng true/true/IMMEDIATE cho field vắng rồi setter `do update set` ghi đè hết
    -- ⇒ gửi {"E1":{"in_app":false}} là BẬT LẠI push mà người dùng vừa tắt, im lặng, không lỗi.
    -- (Đã đo: {"E1":{"in_app":true,"push":false}} → push=false ✓ ; {"E1":{"in_app":false}} → push=TRUE ✗.)
    -- Setter dưới dùng coalesce(excluded.x, table.x) nên `null` = "giữ nguyên giá trị cũ".
    if jsonb_exists(v, 'cadence') then
      v_cad := upper(v ->> 'cadence');
      if not (v_cad = any (v_cadences)) then
        raise exception 'Nhịp gửi không hợp lệ: %. Chỉ nhận IMMEDIATE, DIGEST, OFF.', v_cad
          using errcode = '22023';
      end if;
    else
      v_cad := null;
    end if;

    v_out := v_out || jsonb_build_object(k, jsonb_build_object(
      'in_app',  case when jsonb_exists(v, 'in_app')  then (v ->> 'in_app')::boolean  else null end,
      'push',    case when jsonb_exists(v, 'push')    then (v ->> 'push')::boolean    else null end,
      'cadence', v_cad));
  end loop;

  if v_out = '{}'::jsonb then
    raise exception 'Không có sự kiện nào để lưu.' using errcode = '22023';
  end if;
  return v_out;
end
$$;








--
-- Name: notification_prefs_read_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notification_prefs_read_v1(p_user uuid, p_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select coalesce(jsonb_object_agg(k.event_key, jsonb_build_object(
           'in_app',  coalesce(np.in_app, true),
           'push',    coalesce(np.push, true),
           'cadence', coalesce(np.cadence, 'IMMEDIATE'),
           'updated_at', np.updated_at)), '{}'::jsonb)
    from (values ('E1'),('E2'),('E3'),('E4'),('E5'),('E6')) as k(event_key)
    left join public.notification_preferences np
      on np.user_id = p_user
     and np.organization_id = p_org
     and np.event_key = k.event_key;
$$;








--
-- Name: notify_claim_push_batch_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_claim_push_batch_v1(p_limit integer DEFAULT 100) RETURNS TABLE(notification_ids uuid[], user_id uuid, idem_key text, title text, body text, url text, tag text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
#variable_conflict use_column
declare
  -- 21→7 giờ VN: mặc định của §C, dùng cho org chưa có dòng config và cho dòng organization_id NULL.
  c_def_quiet_start constant int := 21;
  c_def_quiet_end   constant int := 7;
  v_limit           int  := greatest(1, least(coalesce(p_limit, 100), 500));
  -- 🔴 GIỜ VN, KHÔNG PHẢI UTC. Máy chủ chạy GMT (cron.timezone=GMT); so giờ yên bằng giờ UTC
  -- sẽ lệch đúng 7 tiếng và làm đêm VN thành ban ngày.
  v_hour            int  := extract(hour from (now() at time zone 'Asia/Ho_Chi_Minh'))::int;
  v_quiet_default   boolean;
  v_cfg_orgs        uuid[] := '{}'::uuid[];   -- org CÓ dòng config riêng
  v_cfg_quiet_orgs  uuid[] := '{}'::uuid[];   -- org có config riêng VÀ đang trong giờ yên
begin
  -- ── Bước 1: chống chạy chồng. `return` là BẮT BUỘC — thiếu nó thì advisory lock chỉ là trang
  --    trí, hai lượt drain cùng nhặt một lô. Án lệ: 20260701000001_secdef_code_generators.sql:42.
  --    Khoá xact ⇒ tự nhả khi transaction kết thúc, không cần unlock tay.
  if not pg_try_advisory_xact_lock(hashtext('notify_push_drain_v1')::bigint) then
    raise notice 'notify_push_drain: lượt trước còn đang chạy, bỏ lượt này';
    return;
  end if;

  -- ── Bước 2: dọn dòng treo (SENDING quá 15' không ai settle — edge function timeout/chết giữa chừng).
  --    ⚠ `else n.error_message` là BẮT BUỘC: CASE không ELSE trả NULL và sẽ XOÁ TRẮNG lỗi cũ
  --    (cột error_message đã lộ ra TS ở useNotifications.ts:47).
  --    coalesce(...,'epoch'): SENDING mà push_leased_at NULL là trạng thái hỏng — cũng phải dọn,
  --    không để nó nằm ngoài mọi mệnh đề rồi kẹt vĩnh viễn.
  update public.notifications n
     set push_state = case when n.push_attempts >= 3 then 'FAILED' else 'QUEUED' end,
         error_message = case when n.push_attempts >= 3
                              then 'push: không nhận được phản hồi sau 3 lần'
                              else n.error_message end,
         push_leased_at = null
   where n.push_state = 'SENDING'
     and coalesce(n.push_leased_at, timestamptz 'epoch') < now() - interval '15 minutes';

  -- ── Bước 3: gán NO_DEVICE cho người KHÔNG có thiết bị nào đang hoạt động.
  --    Đây là câu lệnh bản đặc tả trước THIẾU HẲN. Thiếu nó thì với push_subscriptions rỗng,
  --    100% dòng mới kẹt QUEUED vĩnh viễn, push_attempts không tăng, §H SQL (3) mãi ra 0 SENT.
  --    NO_DEVICE ≠ FAILED: không phải lỗi, không tính lượt thử.
  update public.notifications n
     set push_state = 'NO_DEVICE',
         push_leased_at = now()
   where n.push_state = 'QUEUED'
     and not exists (select 1 from public.push_subscriptions ps
                      where ps.user_id = n.user_id and ps.is_active);

  -- ── Bước 4: giờ yên (SAU bước 2 và 3 — dọn treo và đóng NO_DEVICE vẫn phải chạy 24/7).
  v_quiet_default := case
      when c_def_quiet_start = c_def_quiet_end then false
      when c_def_quiet_start <  c_def_quiet_end
        then v_hour >= c_def_quiet_start and v_hour < c_def_quiet_end
      else v_hour >= c_def_quiet_start or  v_hour < c_def_quiet_end
    end;

  begin
    select coalesce(array_agg(c.organization_id), '{}'::uuid[]),
           coalesce(array_agg(c.organization_id) filter (where
             case
               when c.quiet_start = c.quiet_end then false
               when c.quiet_start <  c.quiet_end then v_hour >= c.quiet_start and v_hour < c.quiet_end
               else v_hour >= c.quiet_start or  v_hour < c.quiet_end
             end), '{}'::uuid[])
      into v_cfg_orgs, v_cfg_quiet_orgs
      from app_private.notification_org_config c;
  exception when undefined_table then
    -- §C chưa apply: mọi org theo khung mặc định 21→7. KHÔNG để drain chết vì thứ tự PR.
    v_cfg_orgs := '{}'::uuid[];
    v_cfg_quiet_orgs := '{}'::uuid[];
  end;

  if v_quiet_default
     and (cardinality(v_cfg_orgs) = 0 or v_cfg_quiet_orgs @> v_cfg_orgs) then
    raise notice 'notify_push_drain: đang giờ yên (giờ VN = %), đã dọn treo + NO_DEVICE rồi dừng', v_hour;
    return;
  end if;

  -- ── Bước 5: claim + lease, GỘP THEO NGƯỜI, for update skip locked.
  return query
  with cand as (
    select n.id, n.user_id, n.subject, n.content,
           n.metadata->>'url' as url,
           n.created_at
      from public.notifications n
     where n.push_state = 'QUEUED'
       and n.push_attempts < 3
       -- debounce 10' cho E1 gộp: phiếu được duyệt trong vòng 10' KHÔNG bao giờ push.
       and (coalesce(n.metadata->>'kind','') <> 'ie_pending'
            or n.created_at < now() - interval '10 minutes')
       -- chỉ người CÓ thiết bị active. Bước 3 đã đóng phần còn lại nên mệnh đề này không bao giờ
       -- bỏ sót dòng lại phía sau.
       and exists (select 1 from public.push_subscriptions ps
                    where ps.user_id = n.user_id and ps.is_active)
       -- giờ yên theo org của chính dòng đó (organization_id NULL → khung mặc định)
       and not (case when n.organization_id = any (v_cfg_orgs)
                     then n.organization_id = any (v_cfg_quiet_orgs)
                     else v_quiet_default end)
     order by n.created_at
     for update skip locked
     limit v_limit
  ),
  grp as (
    select c.user_id                                                   as g_user_id,
           array_agg(c.id order by c.created_at, c.id)                  as ids,
           count(*)::int                                                as cnt,
           min(c.created_at)                                            as first_at,
           (array_agg(c.subject order by c.created_at desc, c.id desc))[1] as last_subject,
           (array_agg(c.content order by c.created_at desc, c.id desc))[1] as last_content,
           (array_agg(c.url     order by c.created_at desc, c.id desc))[1] as last_url
      from cand c
     group by c.user_id
  ),
  keyed as (
    -- Khoá lô = md5(user : mốc-sớm-nhất : số-dòng : vân-tay-danh-sách-id).
    --
    -- Hai chỗ khác công thức §D.4a, cả hai đều là lỗi ĐÃ TÁI HIỆN ĐƯỢC trong dry-run:
    --  · epoch-ms thay cho min(created_at)::text — ::text của timestamptz phụ thuộc TimeZone của
    --    session ⇒ hai session khác múi giờ sinh HAI khoá cho CÙNG một lô, mất sạch tác dụng
    --    khử trùng đúng lúc cần nhất (lượt gửi lại).
    --  · md5(danh sách id) — thiếu nó thì hai lô KHÁC NHAU vẫn có thể trùng khoá: created_at mặc
    --    định là now() = mốc TRANSACTION, nên mọi thông báo sinh trong CÙNG một giao dịch có
    --    created_at BẰNG NHAU. Lô bị p_limit cắt làm đôi ⇒ nửa sau có cùng (user, min, cnt) với
    --    nửa trước ⇒ send-push tra push_send_log thấy trùng, trả DUPLICATE, và settle đánh cả
    --    nửa sau là SENT **trong khi chưa hề gửi**. Dry-run 29/07 đã dựng lại đúng ca này.
    -- Lô gửi lại y hệt vẫn ra cùng khoá (ids không đổi) ⇒ tính khử trùng giữ nguyên.
    select g.*,
           md5(g.g_user_id::text || ':' ||
               (extract(epoch from g.first_at) * 1000)::bigint::text || ':' ||
               g.cnt::text || ':' ||
               md5(array_to_string(g.ids, ','))) as k_idem
      from grp g
  ),
  upd as (
    -- CTE ghi dữ liệu LUÔN chạy tới hết dù câu SELECT chính không đọc nó (PG docs).
    update public.notifications n
       set push_state     = 'SENDING',
           push_leased_at = now(),
           push_attempts  = n.push_attempts + 1,
           push_idem_key  = k.k_idem || ':' || n.id::text   -- xem chỗ lệch (2) ở đầu file
      from keyed k
     where n.id = any (k.ids)
    returning n.id
  )
  select k.ids,
         k.g_user_id,
         k.k_idem,
         -- 1 dòng → chính tiêu đề của nó; nhiều dòng → gộp thành "N thông báo mới"
         case when k.cnt = 1 then coalesce(nullif(btrim(k.last_subject), ''), 'CRM')
              else k.cnt::text || ' thông báo mới' end,
         left(coalesce(k.last_content, ''), 180),
         -- URL dự phòng /my-day (App.tsx:372, KHÔNG bọc RequirePermission).
         -- 🚫 KHÔNG dùng /notifications: route đó có gate, chỉ 7/9 role có notifications.view.
         coalesce(nullif(btrim(k.last_url), ''), '/my-day'),
         -- ⚠ Web Push THAY THẾ thông báo cùng tag. cnt=1 phải lấy tag theo notification, nếu để
         -- tag cố định theo người thì cái sau xoá sạch cái trước khỏi màn hình khoá.
         case when k.cnt = 1 then 'crm-' || k.ids[1]::text
              else 'crm-' || k.g_user_id::text end
    from keyed k
   order by k.first_at;
end
$$;








--
-- Name: FUNCTION notify_claim_push_batch_v1(p_limit integer); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.notify_claim_push_batch_v1(p_limit integer) IS 'Drain push §D.4a: advisory lock → dọn treo 15p → gán NO_DEVICE → giờ yên (Asia/Ho_Chi_Minh) → claim+lease gộp theo NGƯỜI (for update skip locked). Gọi qua public.notify_claim_push_batch_v1.';








--
-- Name: notify_closing_done_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_closing_done_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_name   text;
  v_signer text := 'bên nhận';
  v_diff   numeric;
  v_body   text;
  v_in_app boolean;
  v_push   boolean;
BEGIN
  IF NEW.proposed_by IS NULL OR NEW.organization_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = NEW.cashbook_id;

  BEGIN
    v_signer := coalesce(app_private.notif_actor_label_v1(NEW.confirmed_by), 'bên nhận');
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6c: notif_actor_label_v1 lỗi (closure=%): % %', NEW.id, sqlstate, sqlerrm;
  END;

  v_diff := coalesce(NEW.counted_balance,0) - coalesce(NEW.system_balance,0);
  v_body := v_signer || ' đã ký nhận sổ ' || coalesce(v_name,'—') || ' tới '
            || to_char(NEW.closed_through,'DD/MM/YYYY') || '. ';
  IF v_diff = 0 THEN
    v_body := v_body || 'Số đếm khớp sổ. Xem biên bản.';
  ELSE
    v_body := v_body || case when v_diff > 0 then 'Thừa quỹ ' else 'Thiếu quỹ ' end
              || replace(to_char(abs(v_diff),'FM999,999,999,999'), ',', '.')
              || ' đ đã được lập phiếu điều chỉnh ngoài KQKD. Xem biên bản.';
  END IF;

  BEGIN
    SELECT g.g_in_app, g.g_push INTO v_in_app, v_push
      FROM app_private.notify_gate_v1(NEW.proposed_by, NEW.organization_id, 'E6c',
                                      NEW.counted_balance) g;

    IF coalesce(v_in_app, true) THEN
      INSERT INTO public.notifications
        (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
      VALUES (NEW.proposed_by, NEW.organization_id, 'APPROVAL_RESULT', 'IN_APP', 'PENDING',
              'Đã chốt sổ ' || coalesce(v_name,'—'),
              v_body,
              jsonb_build_object(
                'event','E6c',
                'closure_id', NEW.id::text,
                'cashbook_id', NEW.cashbook_id::text,
                'amount', NEW.counted_balance,
                'url','/finance/cashbooks/closure/' || NEW.id::text,
                'actor_id', NEW.confirmed_by),
              case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
      ON CONFLICT (user_id, (metadata->>'closure_id'))
        WHERE (metadata->>'event') = 'E6c'
      DO NOTHING;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6c: bỏ qua người nhận % (closure=%): % %',
      NEW.proposed_by, NEW.id, sqlstate, sqlerrm;
  END;

  RETURN NULL;
END
$$;








--
-- Name: notify_closing_nudge_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_closing_nudge_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_org    uuid;
  v_book   record;
  v_ct     date;
  v_recv   text := 'người nhận';
  v_amount text;
  v_in_app boolean;
  v_push   boolean;
BEGIN
  -- SUY ORG, ĐỪNG TIN CỘT: cash_handovers.organization_id nullable, bảng KHÔNG
  -- có trg_autofill_org và create_cash_handover không gán (20260729161000:532-534).
  v_org := coalesce(NEW.organization_id,
                    (select a.organization_id from public.accounts a where a.id = NEW.from_account_id));
  IF v_org IS NULL OR NEW.giver_id IS NULL OR NEW.from_account_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT a.id, a.name, a.is_virtual, a.deleted_at
    INTO v_book
    FROM public.accounts a
   WHERE a.id = NEW.from_account_id;

  -- Sổ ảo (Thối/Làm tròn) không có két ⇒ propose_cashbook_closing_v1 từ chối
  -- thẳng (blocker VIRTUAL_CASHBOOK). Nhắc là dẫn người dùng vào tường.
  IF v_book.id IS NULL OR v_book.deleted_at IS NOT NULL OR COALESCE(v_book.is_virtual,false) THEN
    RETURN NULL;
  END IF;

  -- Đã chốt tới hôm nay rồi thì im. Chống ồn khi một ngày có nhiều phiên.
  v_ct := app_private.cashbook_closed_through_v1(NEW.from_account_id);
  IF v_ct IS NOT NULL AND v_ct >= public.org_today_v1(NULL) THEN
    RETURN NULL;
  END IF;

  BEGIN
    v_recv := coalesce(nullif(NEW.receiver_name,''),
                       app_private.notif_actor_label_v1(NEW.receiver_id), 'người nhận');
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6a: notif_actor_label_v1 lỗi (handover=%): % %', NEW.id, sqlstate, sqlerrm;
    v_recv := coalesce(nullif(NEW.receiver_name,''), 'người nhận');
  END;
  v_amount := replace(to_char(coalesce(NEW.total_amount,0),'FM999,999,999,999'), ',', '.');

  BEGIN
    SELECT g.g_in_app, g.g_push INTO v_in_app, v_push
      FROM app_private.notify_gate_v1(NEW.giver_id, v_org, 'E6a', NEW.total_amount) g;

    IF coalesce(v_in_app, true) THEN
      INSERT INTO public.notifications
        (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
      VALUES (NEW.giver_id, v_org, 'ACTION_REQUIRED', 'IN_APP', 'PENDING',
              'Đã bàn giao xong — chốt sổ ' || v_book.name || '?',
              v_recv || ' đã nhận ' || v_amount || ' đ (' || coalesce(NEW.code,'—')
                || '). Đếm số còn lại trong két và chốt sổ ' || v_book.name
                || ' để khoá kỳ, kẻo cuối tháng phải dò lại.',
              jsonb_build_object(
                'event','E6a',
                'handover_id', NEW.id::text,
                'cashbook_id', NEW.from_account_id::text,
                'amount', NEW.total_amount,
                'url','/finance/cashbooks?close=' || NEW.from_account_id::text,
                'actor_id', v_actor),
              case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
      ON CONFLICT (user_id, (metadata->>'handover_id'))
        WHERE (metadata->>'event') = 'E6a' and status is distinct from 'READ'
      DO NOTHING;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6a: bỏ qua người nhận % (handover=%): % %',
      NEW.giver_id, NEW.id, sqlstate, sqlerrm;
  END;

  RETURN NULL;
END
$$;








--
-- Name: notify_closing_request_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_closing_request_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_name   text;
  v_who    text := 'người giữ sổ';
  v_amount text;
  v_diff   numeric;
  v_extra  text := '';
  v_in_app boolean;
  v_push   boolean;
BEGIN
  IF NEW.confirmer_user_id IS NULL OR NEW.organization_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = NEW.cashbook_id;

  BEGIN
    v_who := coalesce(app_private.notif_actor_label_v1(NEW.proposed_by), 'người giữ sổ');
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6b: notif_actor_label_v1 lỗi (request=%): % %', NEW.id, sqlstate, sqlerrm;
  END;

  v_amount := replace(to_char(coalesce(NEW.counted_balance,0),'FM999,999,999,999'), ',', '.');
  v_diff   := coalesce(NEW.counted_balance,0) - coalesce(NEW.system_balance,0);
  IF v_diff <> 0 THEN
    v_extra := ' · ' || case when v_diff > 0 then 'THỪA ' else 'THIẾU ' end
               || replace(to_char(abs(v_diff),'FM999,999,999,999'), ',', '.') || ' đ so với sổ';
  END IF;

  BEGIN
    SELECT g.g_in_app, g.g_push INTO v_in_app, v_push
      FROM app_private.notify_gate_v1(NEW.confirmer_user_id, NEW.organization_id, 'E6b',
                                      NEW.counted_balance) g;

    IF coalesce(v_in_app, true) THEN
      INSERT INTO public.notifications
        (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
      VALUES (NEW.confirmer_user_id, NEW.organization_id, 'ACTION_REQUIRED', 'IN_APP', 'PENDING',
              'Chờ bạn ký chốt sổ ' || coalesce(v_name,'—'),
              v_who || ' đề nghị chốt sổ ' || coalesce(v_name,'—') || ' tới '
                || to_char(NEW.closed_through,'DD/MM/YYYY') || ' — đã đếm ' || v_amount || ' đ'
                || v_extra || '. Ký là kỳ này khoá VĨNH VIỄN.',
              jsonb_build_object(
                'event','E6b',
                'request_id', NEW.id::text,
                'cashbook_id', NEW.cashbook_id::text,
                'amount', NEW.counted_balance,
                'url','/finance/cashbooks?confirm=' || NEW.id::text,
                'actor_id', v_actor),
              case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
      ON CONFLICT (user_id, (metadata->>'request_id'))
        WHERE (metadata->>'event') = 'E6b' and status is distinct from 'READ'
      DO NOTHING;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'notify E6b: bỏ qua người nhận % (request=%): % %',
      NEW.confirmer_user_id, NEW.id, sqlstate, sqlerrm;
  END;

  RETURN NULL;
END
$$;








--
-- Name: notify_gate_v1(uuid, uuid, text, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_gate_v1(p_user uuid, p_org uuid, p_event text, p_amount numeric DEFAULT NULL::numeric) RETURNS TABLE(g_in_app boolean, g_push boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_family  text := case when p_event like 'E2%' then 'E2' when p_event like 'E6%' then 'E6' else p_event end;  -- §B.7 BẮT BUỘC
  v_cfg     jsonb;
  v_min     numeric;
  v_in      boolean := true;
  v_push    boolean := true;
  v_cadence text := 'IMMEDIATE';
begin
  begin
    select c.events -> v_family into v_cfg
      from app_private.notification_org_config c
     where c.organization_id = p_org;

    if v_cfg is not null then
      if coalesce((v_cfg->>'enabled')::boolean, true) = false then
        g_in_app := false; g_push := false; return next; return;
      end if;
      v_min := nullif(v_cfg->>'min_amount','')::numeric;
    end if;

    select coalesce(np.in_app, true), coalesce(np.push, true), coalesce(np.cadence,'IMMEDIATE')
      into v_in, v_push, v_cadence
      from public.notification_preferences np
     where np.user_id = p_user and np.organization_id = p_org and np.event_key = v_family;
  exception when others then
    -- Chưa apply bước 7, hoặc bảng đổi hình dạng: MỞ (thà ồn còn hơn câm), nhưng để lại vết.
    raise warning 'notify_gate_v1: không đọc được cấu hình (user=% org=% event=%): % %',
      p_user, p_org, p_event, sqlstate, sqlerrm;
    v_in := true; v_push := true; v_cadence := 'IMMEDIATE'; v_min := null;
  end;

  if v_cadence = 'OFF' then
    v_in := false; v_push := false;
  elsif v_cadence = 'DIGEST' then
    v_push := false;    -- §D.3: push_state 'SKIPPED' dành cho DIGEST, gom ở đợt 2 (§D.6)
  end if;

  -- min_amount CHỈ áp cho sự kiện mang MỘT số tiền cụ thể (E2*, E3, E5). E1 là dòng GỘP nên số
  -- tiền của nó là TỔNG — lọc theo tổng là vô nghĩa. Mặc định NULL = không lọc (§C: đo thật, nâng
  -- ngưỡng 300k→3tr chỉ hạ đỉnh 15→14 thông báo/ngày ⇒ ngưỡng tiền gần như vô dụng).
  if v_min is not null and p_amount is not null and p_amount < v_min then
    v_in := false; v_push := false;
  end if;

  g_in_app := v_in; g_push := v_push; return next;
end $$;








--
-- Name: notify_handover_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_handover_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_org    uuid;
  v_giver  text := 'hệ thống';
  v_amount text;
  v_in_app boolean;
  v_push   boolean;
begin
  -- SUY ORG, ĐỪNG TIN CỘT: cash_handovers.organization_id nullable, bảng KHÔNG có trg_autofill_org,
  -- create_cash_handover KHÔNG hề gán — dòng mới nhất BG2607004 (22/07) đang NULL thật.
  -- accounts có 70 dòng, organization_id NULL = 0, from_account_id NOT NULL 7/7.
  v_org := coalesce(NEW.organization_id,
                    (select a.organization_id from public.accounts a where a.id = NEW.from_account_id));

  if v_org is null then
    perform app_private.notify_no_recipient_v1(
      null, 'E5', 'CASH_HANDOVER', NEW.id, null, v_actor, 'ORG_UNRESOLVED');
    return null;
  end if;

  -- create_cash_handover đã RAISE nếu p_receiver_id = auth.uid(); chốt thêm ở đây cho đường khác.
  if NEW.receiver_id is null or NEW.receiver_id = v_actor then
    return null;
  end if;

  begin
    v_giver := coalesce(nullif(NEW.giver_name,''),
                        app_private.notif_actor_label_v1(NEW.giver_id), 'hệ thống');
  exception when others then
    raise warning 'notify: notif_actor_label_v1 lỗi (handover=%): % %', NEW.id, sqlstate, sqlerrm;
    v_giver := coalesce(nullif(NEW.giver_name,''), 'hệ thống');
  end;
  v_amount := replace(to_char(coalesce(NEW.total_amount,0),'FM999,999,999,999'), ',', '.');

  begin
    select g.g_in_app, g.g_push into v_in_app, v_push
      from app_private.notify_gate_v1(NEW.receiver_id, v_org, 'E5', NEW.total_amount) g;

    if coalesce(v_in_app, true) then
      insert into public.notifications
        (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
      values (NEW.receiver_id, v_org, 'ACTION_REQUIRED', 'IN_APP', 'PENDING',
              'Bàn giao tiền mặt chờ bạn xác nhận',
              coalesce(NEW.code,'—') || ' · ' || v_amount || ' đ từ ' || v_giver || ' — '
                || coalesce(NEW.voucher_count,0)::text || ' phiếu.',
              jsonb_build_object('event','E5',
                                 'handover_id', NEW.id::text,   -- notifications KHÔNG có cột này
                                 'url','/thu-tien?handover=' || NEW.id::text,
                                 'actor_id', v_actor),
              case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
      on conflict (user_id, (metadata->>'handover_id')) where (metadata->>'event') = 'E5'
      do nothing;
    end if;
  exception when others then
    raise warning 'notify E5: bỏ qua người nhận % (handover=%): % %',
      NEW.receiver_id, NEW.id, sqlstate, sqlerrm;
  end;

  return null;
end $$;








--
-- Name: notify_ie_lifecycle_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_ie_lifecycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_actor    uuid := auth.uid();
  v_maker    uuid := coalesce(NEW.maker_user_id, NEW.user_id);   -- maker_user_id chỉ điền 141/2592
  v_org      uuid := NEW.organization_id;
  v_label    text := 'hệ thống';
  v_amount   text;
  v_ins      boolean := (TG_OP = 'INSERT');
  v_enter    boolean := false;   -- vào (hoặc quay lại) hàng chờ duyệt
  v_approved boolean := false;
  v_cancel   boolean := false;
  v_softdel  boolean := false;
  v_e3       boolean := false;
  v_stale    boolean := false;   -- có cần đếm lại cho người ĐANG giữ dòng E1 mở không
  v_event    text;
  v_subject  text;
  v_content  text;
  v_approvers uuid[] := '{}'::uuid[];
  v_resolved boolean := true;
  v_batch    text;
  v_u        uuid;
  v_in_app   boolean;
  v_push     boolean;
  v_nid      uuid;
  v_ids      jsonb;
  v_cnt      int;
begin
  -- (a) org phải giải được — §L.2 cấm fallback im lặng về NULL.
  if v_org is null then
    perform app_private.notify_no_recipient_v1(
      null, 'E1', 'INCOME_EXPENSE', NEW.id, NEW.building_id, v_actor, 'ORG_UNRESOLVED');
    return null;
  end if;

  -- (b) phiếu thuộc approval engine: đường thông báo này KHÔNG đụng vào (tập ứng viên của engine
  --     KHÁC resolver — đo DEMO 29/07 07:36Z: engine={90450d5f, fb0651bb}, resolver=RỖNG).
  if exists (select 1 from public.approval_requests ar
              where ar.subject_type = 'FINANCIAL_VOUCHER'
                and ar.subject_id = NEW.id
                and ar.state = 'PENDING_APPROVAL') then
    perform app_private.notify_no_recipient_v1(
      v_org, 'E1', 'INCOME_EXPENSE', NEW.id, NEW.building_id, v_actor, 'ENGINE_OWNED');
    return null;
  end if;

  -- (c) phân loại chuyển trạng thái (TG_OP chỉ dùng được TRONG THÂN HÀM, không dùng ở WHEN — 42703)
  if v_ins then
    v_enter := true;
  else
    v_enter    := NEW.approval_status = 'UNAPPROVED'
                  and NEW.approval_status is distinct from OLD.approval_status;
    v_approved := NEW.approval_status = 'APPROVED'  and OLD.approval_status = 'UNAPPROVED';
    v_cancel   := NEW.approval_status = 'CANCELLED' and OLD.approval_status = 'UNAPPROVED';
    v_softdel  := NEW.deleted_at is not null and OLD.deleted_at is null
                  and NEW.approval_status = 'UNAPPROVED';
  end if;
  v_e3    := v_cancel or v_softdel;
  v_stale := (not v_ins) and (v_approved or v_e3);   -- các nhánh làm hàng chờ NGẮN ĐI

  -- nhãn người thao tác chỉ để HIỂN THỊ ⇒ hỏng thì lùi về 'hệ thống', không được làm hỏng phiếu tiền
  begin
    v_label := coalesce(app_private.notif_actor_label_v1(v_actor), 'hệ thống');
  exception when others then
    raise warning 'notify: notif_actor_label_v1 lỗi (ie=%): % %', NEW.id, sqlstate, sqlerrm;
    v_label := 'hệ thống';
  end;
  v_amount := replace(to_char(coalesce(NEW.total_amount,0),'FM999,999,999,999'), ',', '.');

  ----------------------------------------------------------------------------
  -- (d) E2 / E2b / E2c — báo NGƯỜI LẬP PHIẾU. Bỏ nếu v_maker = v_actor.
  --     CHỐT CHẶN THÔNG BÁO KÉP: trg_forfeit_settle_on_approve lan trạng thái sang phiếu đối ứng
  --     của cặp thanh lý bỏ cọc ⇒ 1 thao tác = 2 lần trigger. Chỉ bỏ CHÂN ĐỐI ỨNG
  --     (offset_voucher_id), TUYỆT ĐỐI KHÔNG lọc bằng system_source vì nó chặn CẢ HAI chân.
  ----------------------------------------------------------------------------
  if (v_approved or v_cancel)
     and v_maker is not null
     and v_maker is distinct from v_actor
     and not exists (select 1 from app_private.termination_forfeit_authorizations t
                      where t.offset_voucher_id = NEW.id) then

    if v_approved then
      v_event   := 'E2';
      v_subject := 'Phiếu đã được duyệt';
      v_content := 'Phiếu ' || coalesce(NEW.code,'—') || ' · ' || v_amount
                   || ' đ đã được ' || v_label || ' duyệt.';
    elsif NEW.cancellation_kind = 'REJECTED_INVALID' then
      -- E2b hôm nay CHƯA CÓ ĐƯỜNG PHÁT SINH (reject_invalid_income_expense_v2 tồn tại nhưng 0 file
      -- FE gọi, cancellation_kind='REJECTED_INVALID' có 0 dòng thật). Cài vì rẻ + đúng ngữ nghĩa.
      v_event   := 'E2b';
      v_subject := 'Phiếu bị từ chối';
      v_content := 'Phiếu ' || coalesce(NEW.code,'—') || ' bị ' || v_label || ' từ chối. Lý do: '
                   || coalesce(nullif(NEW.review_reason,''), '(không ghi)');
    elsif v_actor is not null then
      -- v_actor IS NOT NULL BẮT BUỘC: NULL IS DISTINCT FROM v_maker = TRUE ⇒ thiếu nó thì mọi
      -- đường hệ thống/cron bắn "phiếu của bạn bị người khác huỷ".
      -- KHÔNG gọi đây là "từ chối": ie_compat_cancel_v2 chỉ đòi membership ACTIVE.
      v_event   := 'E2c';
      v_subject := 'Phiếu bị huỷ khi đang chờ duyệt';
      v_content := 'Phiếu ' || coalesce(NEW.code,'—') || ' · ' || v_amount
                   || ' đ đã bị ' || v_label || ' huỷ.';
    else
      v_event := null;
    end if;

    if v_event is not null then
      begin
        select g.g_in_app, g.g_push into v_in_app, v_push
          from app_private.notify_gate_v1(v_maker, v_org, v_event, NEW.total_amount) g;

        if coalesce(v_in_app, true) then
          insert into public.notifications
            (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
          values (v_maker, v_org, 'APPROVAL_RESULT', 'IN_APP', 'PENDING', v_subject, v_content,
                  jsonb_build_object(
                    'event', v_event, 'ie_id', NEW.id::text,
                    'code', NEW.code,            -- CHỈ để hiển thị: DEMO có 2 phiếu cùng PC2607039
                    'amount', NEW.total_amount,
                    -- KHÔNG set notifications.contract_id: 7/9 phiếu chờ là hoa hồng có contract_id,
                    -- UI sẽ điều hướng sang trang hợp đồng — SAI ĐÍCH.
                    'url', '/income-expense/voucher/' || NEW.id::text,
                    'actor_id', v_actor),
                  case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
          on conflict (user_id, (metadata->>'ie_id'), (metadata->>'event'))
            where (metadata->>'event') in ('E2','E2b','E2c')
          do nothing;
        end if;
      exception when others then
        raise warning 'notify %: bỏ qua người nhận % (ie=%): % %',
          v_event, v_maker, NEW.id, sqlstate, sqlerrm;
      end;
    end if;
  end if;

  ----------------------------------------------------------------------------
  -- (e) NGƯỜI DUYỆT — resolver. atav3 KHÔNG tham chiếu auth.uid() ở bất kỳ đâu nên dùng được
  --     trong trigger/cron. Bọc riêng: resolver hỏng thì mất thông báo, KHÔNG được mất phiếu tiền.
  ----------------------------------------------------------------------------
  begin
    v_approvers := app_private.ie_approver_ids_v1(
                     v_org, NEW.building_id, array_remove(array[v_actor, v_maker], null));
  exception when others then
    v_resolved  := false;
    v_approvers := '{}'::uuid[];
    raise warning 'notify: ie_approver_ids_v1 lỗi (ie=%): % %', NEW.id, sqlstate, sqlerrm;
  end;

  -- Tập rỗng là ca THẬT (3/17 phiếu chờ) ⇒ KHÔNG im lặng, ghi sổ + RAISE WARNING.
  if v_enter and v_resolved and coalesce(array_length(v_approvers,1),0) = 0 then
    perform app_private.notify_no_recipient_v1(
      v_org, 'E1', 'INCOME_EXPENSE', NEW.id, NEW.building_id, v_actor, 'NO_APPROVER_IN_SCOPE');
  end if;

  v_batch := pg_current_xact_id()::text;   -- gộp E3 theo GIAO DỊCH

  for v_u in
    select distinct x.uid
      from (
        select unnest(v_approvers) as uid
        union
        -- Người ĐANG giữ một dòng E1 mở trong org này cũng phải được đếm lại khi hàng chờ NGẮN ĐI
        -- (kể cả người vừa thao tác — nếu không thì số đếm của họ đứng hình ở giá trị cũ).
        -- Chỉ mở nhánh này ở các nhánh GIẢM (duyệt/huỷ/xoá mềm) nên không bao giờ tự bắn cho mình.
        select n.user_id
          from public.notifications n
         where v_stale
           and n.organization_id = v_org
           and (n.metadata->>'kind') = 'ie_pending'
           and n.status is distinct from 'READ'
      ) x
     where x.uid is not null
  loop
    -- FAIL-OPEN Ở CẤP TỪNG NGƯỜI NHẬN (§B.0 nguyên tắc 2) — KHÔNG bọc cả thân hàm.
    begin
      perform app_private.notify_ie_pending_refresh_v1(v_org, v_u);

      if v_e3 and v_u = any(v_approvers) then
        select g.g_in_app, g.g_push into v_in_app, v_push
          from app_private.notify_gate_v1(v_u, v_org, 'E3', NEW.total_amount) g;

        if coalesce(v_in_app, true) then
          select n.id, n.metadata->'voucher_ids' into v_nid, v_ids
            from public.notifications n
           where n.user_id = v_u
             and (n.metadata->>'event') = 'E3'
             and (n.metadata->>'batch') = v_batch
           limit 1;

          if v_nid is null then
            insert into public.notifications
              (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
            values (v_u, v_org, 'APPROVAL_RESULT', 'IN_APP', 'PENDING',
                    'Không cần duyệt nữa',
                    'Phiếu ' || coalesce(NEW.code,'—') || ' · ' || v_amount
                      || ' đ đã được ' || v_label || ' huỷ, bạn không cần duyệt.',
                    jsonb_build_object(
                      'event','E3', 'batch', v_batch,
                      'code', NEW.code, 'amount', NEW.total_amount,
                      'voucher_ids', jsonb_build_array(NEW.id::text),
                      'url','/income-expense/voucher/' || NEW.id::text,
                      'actor_id', v_actor),
                    case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
            on conflict (user_id, (metadata->>'batch'))
              where (metadata->>'event') = 'E3'
            do nothing;
          elsif not (coalesce(v_ids,'[]'::jsonb) @> to_jsonb(NEW.id::text)) then
            -- cùng batch = cùng transaction ⇒ không có đua; index vẫn giữ làm chốt chặn
            v_ids := coalesce(v_ids,'[]'::jsonb) || to_jsonb(NEW.id::text);
            v_cnt := jsonb_array_length(v_ids);
            update public.notifications n
               set metadata = n.metadata || jsonb_build_object(
                                'voucher_ids', v_ids,
                                'url', '/income-expense'),   -- ≥2 phiếu thì về danh sách
                   content  = v_cnt::text || ' phiếu chờ duyệt vừa bị ' || v_label || ' huỷ.',
                   push_state = case when coalesce(v_push,true) then 'QUEUED' else n.push_state end
             where n.id = v_nid;
          end if;
        end if;
      end if;
    exception when others then
      raise warning 'notify E1/E3: bỏ qua người nhận % (ie=%): % %', v_u, NEW.id, sqlstate, sqlerrm;
    end;
  end loop;

  return null;
end $$;








--
-- Name: notify_ie_pending_refresh_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_ie_pending_refresh_v1(p_org uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_n      bigint  := 0;
  v_sum    numeric := 0;
  v_ids    uuid[]  := '{}'::uuid[];
  v_old    bigint;
  v_up     boolean;
  v_in_app boolean := true;
  v_push   boolean := true;
begin
  if p_org is null or p_user is null then
    return;
  end if;

  select g.g_in_app, g.g_push into v_in_app, v_push
    from app_private.notify_gate_v1(p_user, p_org, 'E1', null) g;

  if coalesce(v_in_app, true) then
    with pend as (
      select ie.id, ie.total_amount, ie.building_id, ie.created_at
        from public.income_expenses ie
       where ie.organization_id = p_org
         and ie.deleted_at is null
         and ie.approval_status = 'UNAPPROVED'
         -- chép ĐÚNG predicate của approve_income_expense_v2 (§0.4A): COALESCE(...,'') nghĩa là
         -- review_state NULL bị coi là KHÔNG duyệt được (DEMO đang có 4 dòng sống như vậy và chúng
         -- KHÔNG tự lành vì a001_ie_lifecycle_normalize chỉ chạy BEFORE INSERT).
         and coalesce(ie.review_state,'') in ('PENDING','CHANGES_REQUESTED')
         -- §B.2 điểm 5: LOẠI TRỪ phiếu đang thuộc approval engine. a001 ép review_state='PENDING'
         -- cho MỌI phiếu UNAPPROVED, còn salary_payout_v1/manager_salary_payout_v1 INSERT đúng
         -- hình dạng đó RỒI MỚI nạp engine ⇒ predicate review_state KHÔNG che gì cả.
         and not exists (select 1 from public.approval_requests ar
                          where ar.subject_type = 'FINANCIAL_VOUCHER'
                            and ar.subject_id = ie.id
                            and ar.state = 'PENDING_APPROVAL')),
    bld as (select distinct p.building_id from pend p),
    -- gọi atav3 MỘT LẦN trên mỗi TOÀ có phiếu chờ, không phải mỗi phiếu
    ok as (select b.building_id from bld b
            where (select a.allowed from app_private.authorize_tenant_action_v3(
                     p_user, p_org, 'income_expenses.approve', b.building_id, null) a))
    select count(*), coalesce(sum(p.total_amount),0),
           coalesce(array_agg(p.id order by p.created_at), '{}'::uuid[])
      into v_n, v_sum, v_ids
      from pend p
     where p.building_id in (select building_id from ok);
  end if;

  -- ĐỌC SỐ ĐẾM CŨ trước khi ghi — v_up quyết định có bump created_at/push_state hay không.
  select coalesce((n.metadata->>'count')::bigint, 0) into v_old
    from public.notifications n
   where n.user_id = p_user and n.organization_id = p_org
     and (n.metadata->>'kind') = 'ie_pending' and n.status is distinct from 'READ'
   limit 1;
  v_old := coalesce(v_old, 0);

  -- v_n = 0 ⇒ XOÁ dòng đang mở. Đây chính là chỗ E3 làm người duyệt "khỏi phải chờ" tự động.
  if coalesce(v_n,0) = 0 then
    delete from public.notifications n
     where n.user_id = p_user and n.organization_id = p_org
       and (n.metadata->>'kind') = 'ie_pending' and n.status is distinct from 'READ';
    return;
  end if;

  v_up := v_n > v_old;

  insert into public.notifications
    (user_id, organization_id, type, channel, status, subject, content, metadata, push_state)
  values (p_user, p_org, 'ACTION_REQUIRED', 'IN_APP', 'PENDING',
          'Phiếu chờ bạn duyệt',
          v_n || ' phiếu đang chờ bạn duyệt · tổng '
            || replace(to_char(v_sum,'FM999,999,999,999'), ',', '.') || ' đ',
          jsonb_build_object(
            'kind','ie_pending', 'event','E1', 'count',v_n, 'amount',v_sum,
            'voucher_ids', to_jsonb(v_ids),
            -- BẮT BUỘC có &layer=PENDING: EMPTY_INCOME_EXPENSE_FILTERS mặc định layer:"CASH" và
            -- applyLayerFilters ép .eq("approval_status","APPROVED"); hai .eq cùng cột KHÔNG ghi đè
            -- nhau (postgrest-js dùng searchParams.append) ⇒ AND ⇒ 0 DÒNG.
            'url','/income-expense?approval_status=UNAPPROVED&layer=PENDING',
            'actor_id', auth.uid()),
          case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
  on conflict (user_id, organization_id)
    where (metadata->>'kind') = 'ie_pending' and status is distinct from 'READ'
  do update set
    content    = excluded.content,
    metadata   = excluded.metadata,
    -- CHỈ bump khi số TĂNG: bump mọi lần thì E3 liên tục reset đồng hồ và push không bao giờ tới.
    created_at = case when v_up then now() else public.notifications.created_at end,
    push_state = case when v_up then excluded.push_state else public.notifications.push_state end;
end $$;








--
-- Name: notify_job_assigned_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_job_assigned_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_org    uuid := NEW.organization_id;
  v_label  text := 'hệ thống';
  v_in_app boolean;
  v_push   boolean;
begin
  if v_org is null then
    perform app_private.notify_no_recipient_v1(
      null, 'E4', 'JOB', NEW.id, NEW.building_id, v_actor, 'ORG_UNRESOLVED');
    return null;
  end if;

  begin
    v_label := coalesce(app_private.notif_actor_label_v1(v_actor), 'hệ thống');
  exception when others then
    raise warning 'notify: notif_actor_label_v1 lỗi (job=%): % %', NEW.id, sqlstate, sqlerrm;
    v_label := 'hệ thống';
  end;

  begin
    select g.g_in_app, g.g_push into v_in_app, v_push
      from app_private.notify_gate_v1(NEW.assignee_id, v_org, 'E4', null) g;

    if coalesce(v_in_app, true) then
      insert into public.notifications
        (user_id, organization_id, type, channel, status, subject, content, job_id, metadata, push_state)
      values (NEW.assignee_id, v_org, 'ACTION_REQUIRED', 'IN_APP', 'PENDING',
              'Việc mới được giao cho bạn',
              coalesce(nullif(NEW.title,''),'(không tiêu đề)') || ' (' || coalesce(NEW.code,'—')
                || ') — do ' || v_label || ' giao.',
              NEW.id,
              jsonb_build_object('event','E4',
                                 'url','/tasks?job=' || NEW.id::text,
                                 'actor_id', v_actor),
              case when coalesce(v_push,true) then 'QUEUED' else 'SKIPPED' end)
      on conflict (user_id, job_id) where (metadata->>'event') = 'E4'
      do nothing;
    end if;
  exception when others then
    raise warning 'notify E4: bỏ qua người nhận % (job=%): % %',
      NEW.assignee_id, NEW.id, sqlstate, sqlerrm;
  end;

  return null;
end $$;








--
-- Name: notify_no_recipient_v1(uuid, text, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_no_recipient_v1(p_org uuid, p_event_key text, p_subject_kind text, p_subject_id uuid, p_building uuid, p_actor uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
begin
  begin
    insert into app_private.notification_no_recipient_log
      (organization_id, event_key, subject_kind, subject_id, building_id, actor_id, reason)
    values (p_org,
            case when p_event_key like 'E2%' then 'E2' else p_event_key end,
            p_subject_kind, p_subject_id, p_building, p_actor, p_reason);

    raise warning '% NO_RECIPIENT subject=%:% org=% building=% actor=% reason=%',
      p_event_key, p_subject_kind, p_subject_id, p_org, p_building, p_actor, p_reason;
  exception when others then
    null;
  end;
end $$;








--
-- Name: notify_settle_push_batch_v1(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_settle_push_batch_v1(p_results jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
#variable_conflict use_column
declare
  v_rows int := 0;
begin
  if p_results is null
     or jsonb_typeof(p_results) <> 'array'
     or jsonb_array_length(p_results) = 0 then
    return 0;
  end if;

  with r as (
    select nullif(btrim(x->>'idem_key'), '') as idem_key,
           upper(coalesce(nullif(btrim(x->>'outcome'), ''), 'PROVIDER_ERROR')) as outcome,
           -- KHÔNG ::boolean: payload rác sẽ ném 22P02 và giết cả lượt settle ⇒ lô treo tới khi
           -- lease hết hạn rồi gửi TRÙNG. So chuỗi thì không bao giờ ném.
           (lower(coalesce(x->>'retryable', 'true')) not in ('false','f','0','no')) as retryable,
           nullif(btrim(coalesce(x->>'error', '')), '') as error
      from jsonb_array_elements(p_results) x
     where jsonb_typeof(x) = 'object'
  ),
  d as (select * from r where r.idem_key is not null),
  upd as (
    update public.notifications n
       set push_state = case
             when d.outcome in ('SENT','PARTIAL','DUPLICATE') then 'SENT'
             when d.outcome = 'NO_DEVICE'                     then 'NO_DEVICE'
             when not d.retryable                             then 'FAILED'
             when n.push_attempts >= 3                        then 'FAILED'
             else 'QUEUED'
           end,
           -- sent_at giữ ĐÚNG một nghĩa: "đã đẩy push thành công lúc nào" (§0.4 B).
           sent_at = case when d.outcome in ('SENT','PARTIAL','DUPLICATE') then now()
                          else n.sent_at end,
           error_message = case when d.outcome in ('SENT','PARTIAL','DUPLICATE') then null
                                else left(concat_ws(' ', 'push', d.outcome, d.error), 300) end,
           push_leased_at = null
           -- 🔴 KHÔNG có `status = ...` ở đây và sẽ KHÔNG BAO GIỜ có. Xem đầu file.
      from d
     where n.push_state = 'SENDING'
       and n.push_idem_key is not null
       and split_part(n.push_idem_key, ':', 1) = d.idem_key
    returning 1 as one
  )
  select count(*)::int into v_rows from upd;

  return v_rows;
end
$$;








--
-- Name: FUNCTION notify_settle_push_batch_v1(p_results jsonb); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.notify_settle_push_batch_v1(p_results jsonb) IS 'Drain push §D.4b: đóng lô theo outcome của send-push (KHÔNG theo HTTP status). Trả về số dòng notifications đã đóng. Không bao giờ ghi cột status (trục ĐỌC).';








--
-- Name: openclaw_ack_audit_anchor_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_ack_audit_anchor_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org uuid := (p_principal->>'organizationId')::uuid;
  v_maintenance uuid := (p_principal->>'maintenancePrincipalId')::uuid;
  v_work public.openclaw_maintenance_work_items%rowtype;
  v_root public.openclaw_audit_roots%rowtype;
  v_ticket public.openclaw_audit_gateway_tickets%rowtype;
  v_receipt jsonb := p_request->'gatewayReceipt';
  v_receipt_hash text;
  v_token text;
  v_attempt integer;
  v_recovery boolean := p_request->>'recoveryKind'='AUDIT_VERIFY_AUTHORIZED';
begin
  if v_recovery then
    perform app_private.openclaw_assert_strict_object_v1(
      p_request,
      array['version','recoveryKind','workItemId','recoveryGeneration','claimToken',
        'verifyTicketJti','gatewayReceipt'],
      array['version','recoveryKind','workItemId','recoveryGeneration','claimToken',
        'verifyTicketJti','gatewayReceipt']
    );
  else
    perform app_private.openclaw_assert_strict_object_v1(
      p_request,
      array['version','workItemId','claimGeneration','claimToken','verifyTicketJti','gatewayReceipt'],
      array['version','workItemId','claimGeneration','claimToken','verifyTicketJti','gatewayReceipt']
    );
  end if;
  perform app_private.openclaw_assert_strict_object_v1(
    v_receipt,
    array['version','receiptKind','receiptId','organizationId','maintenancePrincipalId',
      'workItemId','claimGeneration','credentialGeneration','leaseGeneration','fencingToken',
      'auditRootId','rootHash','anchorKey','signatureHash','auditSigningKeyGeneration',
      'verifyTicketJti','objectVersionOrEtag','verifiedAt','gatewaySigningKeyGeneration','signature'],
    array['version','receiptKind','receiptId','organizationId','maintenancePrincipalId',
      'workItemId','claimGeneration','credentialGeneration','leaseGeneration','fencingToken',
      'auditRootId','rootHash','anchorKey','signatureHash','auditSigningKeyGeneration',
      'verifyTicketJti','objectVersionOrEtag','verifiedAt','gatewaySigningKeyGeneration','signature']
  );
  if p_request->>'version'<>'1' or jsonb_typeof(v_receipt)<>'object'
     or nullif(p_request->>'verifyTicketJti','') is null then
    raise exception 'audit anchor acknowledgement is invalid' using errcode='22023';
  end if;
  v_token:=encode(extensions.digest(convert_to('ihome-openclaw-work-claim-v1','UTF8')
    ||decode('00','hex')||convert_to(p_request->>'claimToken','UTF8'),'sha256'),'hex');
  v_receipt_hash:=encode(extensions.digest(
    convert_to('ihome-openclaw-audit-receipt-v1','UTF8')||decode('00','hex')
      ||app_private.openclaw_jcs_bytes_v1(v_receipt),
    'sha256'),'hex');
  select work.* into v_work from public.openclaw_maintenance_work_items work
  where work.organization_id=v_org and work.id=(p_request->>'workItemId')::uuid
    and work.work_kind='AUDIT_ANCHOR' and work.work_phase='ANCHOR'
  for update;
  if found and v_work.state='AUDIT_VERIFY_AUTHORIZED' then
    if v_recovery then
      if v_work.recovery_maintenance_principal_id<>v_maintenance
        or v_work.recovery_credential_generation<>(p_principal->>'credentialGeneration')::bigint
        or v_work.recovery_lease_generation<>(p_principal->>'leaseGeneration')::bigint
        or v_work.recovery_fencing_token<>(p_principal->>'fencingToken')::bigint
        or v_work.recovery_generation<>(p_request->>'recoveryGeneration')::bigint
        or v_work.claim_token_hash<>v_token
        or v_work.recovery_lease_expires_at<=statement_timestamp() then
        raise exception 'audit recovery ownership CAS failed' using errcode='40001';
      end if;
    elsif v_work.maintenance_principal_id<>v_maintenance
      or v_work.credential_generation<>(p_principal->>'credentialGeneration')::bigint
      or v_work.maintenance_lease_generation<>(p_principal->>'leaseGeneration')::bigint
      or v_work.fencing_token<>(p_principal->>'fencingToken')::bigint
      or v_work.claim_generation<>(p_request->>'claimGeneration')::bigint
      or v_work.claim_token_hash<>v_token or v_work.lease_expires_at<=statement_timestamp() then
      raise exception 'audit original ownership CAS failed' using errcode='40001';
    end if;
  end if;
  if not found then
    raise exception 'audit work claim binding CAS failed' using errcode='40001';
  end if;
  select ticket.* into v_ticket from public.openclaw_audit_gateway_tickets ticket
  where ticket.organization_id=v_org
    and ticket.ticket_jti=(p_request->>'verifyTicketJti')::uuid
    and ticket.work_item_id=v_work.id and ticket.operation='ANCHOR_VERIFY'
  for update;
  if not found then raise exception 'audit verify ticket lineage is unknown' using errcode='42501'; end if;
  if v_work.state='COMPLETE' then
    select root.* into strict v_root from public.openclaw_audit_roots root
    where root.organization_id=v_org and root.id=v_ticket.audit_root_id;
    if v_root.gateway_receipt is distinct from v_receipt
      or v_root.gateway_receipt_hash is distinct from v_receipt_hash
      or v_ticket.gateway_receipt is distinct from v_receipt then
      raise exception 'audit acknowledgement replay mismatch' using errcode='40001';
    end if;
    return jsonb_build_object('version',1,'auditRootId',v_root.id,
      'gatewayReceiptHash',v_receipt_hash,'idempotentReplay',true);
  end if;
  select root.* into v_root from public.openclaw_audit_roots root
  where root.organization_id=v_org and root.id=(v_work.payload->>'auditRootId')::uuid
    and root.root_date=(v_work.payload->>'rootDate')::date
    and root.first_sequence=(v_work.payload->>'firstSequence')::bigint
    and root.last_sequence=(v_work.payload->>'lastSequence')::bigint
    and root.event_count=(v_work.payload->>'eventCount')::bigint
    and root.previous_root_hash is not distinct from nullif(v_work.payload->>'previousRootHash','')
    and root.merkle_root_hash=v_work.payload->>'merkleRootHash'
    and root.root_hash=v_work.payload->>'rootHash'
    and root.r2_anchor_key=v_work.payload->>'anchorKey'
    and root.signing_key_generation=(v_work.payload->>'auditSigningKeyGeneration')::bigint
    and root.anchored_at is null for update;
  if not found then raise exception 'audit root frozen work mismatch' using errcode='40001'; end if;
  if v_receipt->>'version' is distinct from '1'
     or v_receipt->>'receiptKind' is distinct from 'AUDIT_ANCHOR_VERIFY'
     or coalesce(v_receipt->>'receiptId','') !~
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or v_receipt->>'organizationId' is distinct from v_org::text
     or v_receipt->>'maintenancePrincipalId' is distinct from v_ticket.maintenance_principal_id::text
     or v_receipt->>'workItemId' is distinct from v_ticket.work_item_id::text
     or (v_receipt->>'claimGeneration')::bigint is distinct from v_ticket.claim_generation
     or (v_receipt->>'credentialGeneration')::bigint is distinct from v_ticket.credential_generation
     or (v_receipt->>'leaseGeneration')::bigint is distinct from v_ticket.maintenance_lease_generation
     or (v_receipt->>'fencingToken')::bigint is distinct from v_ticket.fencing_token
     or v_receipt->>'auditRootId' is distinct from v_root.id::text
     or v_receipt->>'rootHash' is distinct from v_root.root_hash
     or v_receipt->>'anchorKey' is distinct from v_root.r2_anchor_key
     or v_receipt->>'verifyTicketJti' is distinct from p_request->>'verifyTicketJti'
     or (v_receipt->>'auditSigningKeyGeneration')::bigint is distinct from v_ticket.audit_signing_key_generation
     or nullif(v_receipt->>'objectVersionOrEtag','') is null
     or coalesce(v_receipt->>'verifiedAt','') !~ '^\d{4}-\d{2}-\d{2}T'
     or coalesce(v_receipt->>'signatureHash','') !~ '^[0-9a-f]{64}$'
     or v_receipt->>'signatureHash' is distinct from v_ticket.signature_hash
     or coalesce(v_receipt->>'signature','') !~ '^[A-Za-z0-9_-]{86}$'
     or (v_receipt->>'gatewaySigningKeyGeneration')::bigint
       is distinct from v_ticket.receipt_signing_key_generation then
    raise exception 'audit receipt does not match exact work/root claim' using errcode='42501';
  end if;
  update public.openclaw_audit_roots root set signature_hash=v_receipt->>'signatureHash',
    gateway_receipt=v_receipt,gateway_receipt_hash=v_receipt_hash,anchored_at=statement_timestamp()
  where root.organization_id=v_org and root.id=v_root.id and root.anchored_at is null;
  if not found then raise exception 'audit root completion CAS failed' using errcode='40001'; end if;
  update public.openclaw_audit_gateway_tickets ticket set
    gateway_receipt=v_receipt,gateway_receipt_hash=v_receipt_hash,finalized_at=statement_timestamp()
  where ticket.organization_id=v_org and ticket.id=v_ticket.id and ticket.gateway_receipt is null;
  if not found then raise exception 'audit verify ticket finalization CAS failed' using errcode='40001'; end if;
  v_attempt:=v_work.attempt_count;
  insert into public.openclaw_maintenance_work_attempts(
    organization_id,maintenance_principal_id,work_item_id,claim_generation,
    maintenance_lease_generation,fencing_token,credential_generation,attempt_number,outcome,
    gateway_receipt,receipt_hash,evidence,evidence_hash
  ) values (
    v_org,v_work.maintenance_principal_id,v_work.id,v_work.claim_generation,v_work.maintenance_lease_generation,
    v_work.fencing_token,v_work.credential_generation,v_attempt,'COMPLETE',v_receipt,v_receipt_hash,
    jsonb_build_object('auditRootId',v_root.id,'verifyTicketJti',p_request->>'verifyTicketJti',
      'recoveryGeneration',case when v_recovery then v_work.recovery_generation else null end),
    v_receipt_hash
  );
  update public.openclaw_maintenance_work_items work set state='COMPLETE',claim_token_hash=null,
    lease_expires_at=null,terminal_at=statement_timestamp(),updated_at=statement_timestamp()
  where work.organization_id=v_org and work.id=v_work.id and work.state='AUDIT_VERIFY_AUTHORIZED'
    and work.claim_generation=v_work.claim_generation;
  if not found then raise exception 'audit work completion CAS failed' using errcode='40001'; end if;
  return jsonb_build_object('version',1,'auditRootId',v_root.id,
    'gatewayReceiptHash',v_receipt_hash,'idempotentReplay',false);
end;
$_$;








--
-- Name: openclaw_ack_generation_revocation_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_ack_generation_revocation_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org uuid:=(p_principal->>'organizationId')::uuid;
  v_hash text:=p_request->>'acknowledgementHash';
  v_minimum bigint;
  v_rebind public.openclaw_cell_rebinds%rowtype;
  v_revocation public.openclaw_generation_revocations%rowtype;
  v_result jsonb;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','revocationId','minimumValidGeneration','acknowledgementHash'],
    array['version','revocationId','minimumValidGeneration','acknowledgementHash']
  );
  if p_request->'version' is distinct from '1'::jsonb
     or p_request->>'revocationId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or jsonb_typeof(p_request->'minimumValidGeneration') <> 'number'
     or p_request->>'minimumValidGeneration' !~ '^[1-9][0-9]*$'
     or v_hash !~ '^[0-9a-f]{64}$'
  then raise exception 'generation revocation acknowledgement request invalid' using errcode='22023'; end if;
  begin
    v_minimum:=(p_request->>'minimumValidGeneration')::bigint;
  exception when others then
    raise exception 'generation revocation acknowledgement request invalid' using errcode='22023';
  end;
  select rebind.* into v_rebind
  from public.openclaw_cell_rebinds rebind
  where rebind.organization_id=v_org
    and rebind.revocation_id=(p_request->>'revocationId')::uuid
    and rebind.account_id=(p_principal->>'accountId')::uuid
    and rebind.new_cell_id=(p_principal->>'cellId')::uuid
    and rebind.expected_session_generation=(p_principal->>'sessionGeneration')::bigint
    and rebind.new_lease_generation=(p_principal->>'leaseGeneration')::bigint
    and rebind.new_fencing_token=(p_principal->>'fencingToken')::bigint
    and rebind.status in ('AWAITING_ACK','COMPLETED')
  for update;
  if v_rebind.id is null then
    raise exception 'generation revocation principal binding mismatch' using errcode='42501';
  end if;
  select revocation.* into v_revocation
  from public.openclaw_generation_revocations revocation
  where revocation.organization_id=v_org and revocation.id=v_rebind.revocation_id
    and revocation.principal_kind='CHANNEL'
    and revocation.account_id=v_rebind.account_id and revocation.cell_id=v_rebind.old_cell_id
    and revocation.maintenance_principal_id is null and revocation.revocation_kind='CELL'
    and revocation.revoked_generation=v_rebind.old_fencing_token
    and revocation.minimum_valid_generation=v_rebind.new_fencing_token
    and revocation.minimum_valid_generation=v_minimum
    and revocation.reason_code='CELL_REBIND'
  for update;
  if v_revocation.id is null then
    raise exception 'generation revocation binding mismatch' using errcode='42501';
  end if;
  v_result:=jsonb_build_object(
    'version',1,'revocationId',v_revocation.id,'acknowledged',true
  );
  if v_rebind.status='COMPLETED' then
    if v_revocation.acknowledgement_hash is distinct from v_hash
       or v_rebind.acknowledgement_hash is distinct from v_hash
    then raise exception 'generation revocation acknowledgement CAS failed' using errcode='40001'; end if;
    return v_result;
  end if;
  update public.openclaw_generation_revocations revocation set
    acknowledgement_hash=v_hash,acknowledged_at=statement_timestamp()
  where revocation.organization_id=v_org and revocation.id=v_revocation.id
    and revocation.acknowledgement_hash is null;
  if not found then raise exception 'generation revocation acknowledgement CAS failed' using errcode='40001'; end if;
  update public.openclaw_runtime_cells cell set
    is_current=false,state='FENCED',retired_at=statement_timestamp()
  where cell.organization_id=v_org and cell.account_id=v_rebind.account_id
    and cell.id=v_rebind.old_cell_id and cell.is_current;
  if not found then raise exception 'old CELL cutover CAS failed' using errcode='40001'; end if;
  update public.openclaw_runtime_cells cell set
    is_current=true,state='READY',retired_at=null
  where cell.organization_id=v_org and cell.account_id=v_rebind.account_id
    and cell.id=v_rebind.new_cell_id and not cell.is_current;
  if not found then raise exception 'new CELL cutover CAS failed' using errcode='40001'; end if;
  update public.openclaw_runtime_credentials credential set
    revoked_at=statement_timestamp(),revoked_reason='CELL_REBIND'
  where credential.organization_id=v_org and credential.account_id=v_rebind.account_id
    and credential.cell_id=v_rebind.old_cell_id and credential.revoked_at is null;
  update public.openclaw_runtime_leases lease set
    status='REVOKED',released_at=statement_timestamp()
  where lease.organization_id=v_org and lease.account_id=v_rebind.account_id
    and lease.cell_id=v_rebind.old_cell_id and lease.status='ACTIVE';
  update public.openclaw_cell_rebinds rebind set
    status='COMPLETED',acknowledgement_hash=v_hash,completed_at=statement_timestamp()
  where rebind.organization_id=v_org and rebind.id=v_rebind.id
    and rebind.status='AWAITING_ACK';
  if not found then raise exception 'cell rebind acknowledgement CAS failed' using errcode='40001'; end if;
  return v_result;
end;
$_$;








--
-- Name: openclaw_acquire_cell_lease_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_acquire_cell_lease_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid:=(p_principal->>'organizationId')::uuid;
  v_account uuid:=(p_principal->>'accountId')::uuid;
  v_cell uuid:=(p_principal->>'cellId')::uuid;
  v_generation bigint; v_fencing bigint; v_id uuid:=gen_random_uuid(); v_expires timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended(v_org::text||':'||v_account::text,0));
  select coalesce(max(lease.lease_generation),0)+1,coalesce(max(lease.fencing_token),0)+1
  into v_generation,v_fencing from public.openclaw_runtime_leases lease
  where lease.organization_id=v_org and lease.account_id=v_account;
  update public.openclaw_runtime_leases set status='REVOKED',released_at=statement_timestamp()
  where organization_id=v_org and account_id=v_account and status='ACTIVE';
  v_expires:=statement_timestamp()+least(
    coalesce((p_request->>'ttlSeconds')::integer,60),300)*interval '1 second';
  insert into public.openclaw_runtime_leases(id,organization_id,account_id,cell_id,
    lease_generation,fencing_token,status,acquired_at,expires_at)
  values(v_id,v_org,v_account,v_cell,v_generation,v_fencing,'ACTIVE',statement_timestamp(),v_expires);
  return jsonb_build_object('version',1,'leaseId',v_id,'leaseGeneration',v_generation,
    'fencingToken',v_fencing,'expiresAt',v_expires);
end;
$$;








--
-- Name: openclaw_actor_id_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_actor_id_v1() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
  )::uuid
$$;








--
-- Name: openclaw_advance_rollout_stage_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_advance_rollout_stage_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid := (p_principal ->> 'organizationId')::uuid;
  v_run public.openclaw_rollout_runs%rowtype;
  v_next text := p_request ->> 'nextStage';
  v_now timestamptz := statement_timestamp();
begin
  if p_request ->> 'version' <> '1' then raise exception 'advance rollout version mismatch' using errcode='22023'; end if;
  select run.* into v_run from public.openclaw_rollout_runs run
  where run.organization_id=v_org and run.id=(p_request ->> 'rolloutRunId')::uuid
    and run.stage_version=(p_request ->> 'expectedStageVersion')::bigint
    and run.status='RUNNING' for update;
  if not found then raise exception 'rollout stage CAS failed' using errcode='40001'; end if;
  if not ((v_run.stage='FOUNDATION' and v_next='INFRASTRUCTURE')
    or (v_run.stage='INFRASTRUCTURE' and v_next='WAITING_OWNER_QR')
    or (v_run.stage='WAITING_OWNER_QR' and v_next='CONNECTION')
    or (v_run.stage='CONNECTION' and v_next='SHADOW')
    or (v_run.stage='SHADOW' and v_next='WAITING_OWNER_INBOUND')
    or (v_run.stage='WAITING_OWNER_INBOUND' and v_next='LIMITED_OBSERVING')
    or (v_run.stage='LIMITED_OBSERVING' and v_next='LIMITED_VERIFIED')
    or (v_run.stage='LIMITED_VERIFIED' and v_next='PROACTIVE')
    or (v_run.stage='PROACTIVE' and v_next='SALES_GROUPS')
    or (v_run.stage='SALES_GROUPS' and v_next='COMPLETE')) then
    raise exception 'invalid rollout stage transition' using errcode='22023';
  end if;
  if v_run.stage in ('WAITING_OWNER_QR','WAITING_OWNER_INBOUND') and not exists (
    select 1 from public.openclaw_rollout_checkpoints checkpoint
    where checkpoint.organization_id=v_org and checkpoint.rollout_run_id=v_run.id
      and checkpoint.checkpoint_name=v_run.stage and checkpoint.status='COMPLETE'
      and checkpoint.trusted_evidence_id is not null
  ) then raise exception 'owner checkpoint has no trusted evidence' using errcode='42501'; end if;
  if v_run.stage='SHADOW' and (
    v_run.shadow_started_at is null or v_run.shadow_started_at > v_now-interval '48 hours'
    or v_run.continuous_green_started_at is null
    or v_run.continuous_green_started_at > v_now-interval '48 hours'
  ) then raise exception 'SHADOW requires 48 continuous green hours' using errcode='42501'; end if;
  if v_run.stage='LIMITED_OBSERVING' and (
    v_run.continuous_green_started_at is null
    or v_run.continuous_green_started_at > v_now-interval '72 hours'
  ) then raise exception 'LIMITED_OBSERVING requires 72 continuous green hours' using errcode='42501'; end if;
  update public.openclaw_rollout_runs run
  set stage=v_next,stage_version=run.stage_version+1,stage_entered_at=v_now,
      shadow_started_at=case when v_next='SHADOW' then v_now else run.shadow_started_at end,
      continuous_green_started_at=case
        when v_next in ('SHADOW','LIMITED_OBSERVING') then v_now
        else run.continuous_green_started_at end,
      status=case when v_next='COMPLETE' then 'COMPLETE' else run.status end,
      completed_at=case when v_next='COMPLETE' then v_now end
  where run.organization_id=v_org and run.id=v_run.id and run.stage_version=v_run.stage_version
  returning run.* into v_run;
  if not found then raise exception 'rollout stage CAS failed' using errcode='40001'; end if;
  return jsonb_build_object('version',1,'rolloutRunId',v_run.id,'stage',v_run.stage,
    'stageVersion',v_run.stage_version,'status',v_run.status,'shadowStartedAt',v_run.shadow_started_at,
    'continuousGreenStartedAt',v_run.continuous_green_started_at);
end;
$$;








--
-- Name: openclaw_apply_automation_write_v1(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_apply_automation_write_v1(p_action text, p_organization_id uuid, p_actor_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_automation public.openclaw_automations%rowtype;
  v_current public.openclaw_automation_versions%rowtype;
  v_automation_id uuid := coalesce(nullif(p_request ->> 'automationId', '')::uuid, gen_random_uuid());
  v_version_id uuid := gen_random_uuid();
  v_next_version bigint;
  v_config jsonb;
begin
  if p_action = 'CREATE_DRAFT' then
    v_config := coalesce(p_request -> 'configuration', '{}'::jsonb);
    insert into public.openclaw_automations (
      id, organization_id, account_id, name, automation_kind,
      lifecycle_state, current_version
    ) values (
      v_automation_id, p_organization_id, (p_request ->> 'accountId')::uuid,
      p_request ->> 'name', p_request ->> 'automationKind', 'DRAFT', 1
    );
    insert into public.openclaw_automation_versions (
      id, organization_id, account_id, automation_id, version, lifecycle_state,
      mode, template_body, allowed_crm_fields, missing_value_policy, escaping_mode,
      maximum_rendered_codepoints, policy_version_id, knowledge_version_ids,
      configuration, dry_run_hash, created_by
    ) values (
      v_version_id, p_organization_id, (p_request ->> 'accountId')::uuid,
      v_automation_id, 1, 'DRAFT', p_request ->> 'mode',
      p_request ->> 'templateBody',
      coalesce(array(select jsonb_array_elements_text(p_request -> 'allowedCrmFields')), '{}'::text[]),
      coalesce(p_request ->> 'missingValuePolicy', 'REJECT'),
      coalesce(p_request ->> 'escapingMode', 'CONTROL_SAFE'),
      coalesce((p_request ->> 'maximumRenderedCodepoints')::integer, 40000),
      (p_request ->> 'policyVersionId')::uuid,
      coalesce(array(select value::uuid from jsonb_array_elements_text(p_request -> 'knowledgeVersionIds') value), '{}'::uuid[]),
      v_config, nullif(p_request ->> 'dryRunHash', ''), p_actor_id
    );
    return jsonb_build_object(
      'version', 1, 'automationId', v_automation_id,
      'automationVersionId', v_version_id, 'automationVersion', 1,
      'lifecycleState', 'DRAFT'
    );
  end if;

  select automation.* into strict v_automation from public.openclaw_automations automation
  where automation.organization_id = p_organization_id
    and automation.id = (p_request ->> 'automationId')::uuid for update;
  select version.* into strict v_current from public.openclaw_automation_versions version
  where version.organization_id = p_organization_id
    and version.automation_id = v_automation.id and version.version = v_automation.current_version
  for update;

  if p_action = 'SAVE_STEP' then
    if v_automation.current_version <> (p_request ->> 'expectedAutomationVersion')::bigint then
      raise exception 'automation version mismatch' using errcode = '40001';
    end if;
    v_next_version := v_automation.current_version + 1;
    v_config := v_current.configuration || coalesce(p_request -> 'configurationPatch', '{}'::jsonb);
    insert into public.openclaw_automation_versions (
      id, organization_id, account_id, automation_id, version, lifecycle_state,
      mode, template_body, allowed_crm_fields, missing_value_policy, escaping_mode,
      maximum_rendered_codepoints, policy_version_id, knowledge_version_ids,
      configuration, dry_run_hash, created_by
    ) values (
      v_version_id, p_organization_id, v_automation.account_id, v_automation.id,
      v_next_version, 'DRAFT', coalesce(p_request ->> 'mode', v_current.mode),
      coalesce(p_request ->> 'templateBody', v_current.template_body),
      v_current.allowed_crm_fields, v_current.missing_value_policy, v_current.escaping_mode,
      v_current.maximum_rendered_codepoints, v_current.policy_version_id,
      v_current.knowledge_version_ids, v_config, nullif(p_request ->> 'dryRunHash', ''), p_actor_id
    );
    update public.openclaw_automations set current_version = v_next_version,
      lifecycle_state = 'DRAFT', updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_automation.id;
    return jsonb_build_object(
      'version', 1, 'automationId', v_automation.id,
      'automationVersionId', v_version_id, 'automationVersion', v_next_version,
      'lifecycleState', 'DRAFT'
    );
  elsif p_action = 'PUBLISH' then
    if v_current.lifecycle_state <> 'DRAFT' or v_current.dry_run_hash is null
       or v_automation.current_version <> (p_request ->> 'expectedAutomationVersion')::bigint
    then raise exception 'current dry-run automation draft required' using errcode = '55000'; end if;
    update public.openclaw_automation_versions set lifecycle_state = 'PUBLISHED',
      published_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_current.id;
    update public.openclaw_automations set lifecycle_state = 'PUBLISHED',
      updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_automation.id;
    return jsonb_build_object(
      'version', 1, 'automationId', v_automation.id,
      'automationVersionId', v_current.id, 'automationVersion', v_current.version,
      'lifecycleState', 'PUBLISHED', 'dryRunHash', v_current.dry_run_hash
    );
  elsif p_action = 'PAUSE' then
    if v_automation.current_version <> (p_request ->> 'expectedAutomationVersion')::bigint then
      raise exception 'automation pause version mismatch' using errcode = '40001';
    end if;
    update public.openclaw_automations set lifecycle_state = 'PAUSED',
      updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_automation.id;
    return jsonb_build_object(
      'version', 1, 'automationId', v_automation.id,
      'automationVersion', v_automation.current_version, 'lifecycleState', 'PAUSED'
    );
  end if;
  raise exception 'unsupported automation action' using errcode = '22023';
end;
$$;








--
-- Name: openclaw_apply_capacity_controls_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_apply_capacity_controls_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid := (p_principal ->> 'organizationId')::uuid;
  v_operation uuid;
  v_control text;
  v_reason text;
  v_applied integer := 0;
  v_already integer := 0;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','operationId','controls','reasonFingerprint','requiresManualResume'],
    array['version','operationId','controls','reasonFingerprint','requiresManualResume']
  );
  if p_request ->> 'version' <> '1'
     or jsonb_typeof(p_request -> 'controls') <> 'array'
     or jsonb_array_length(p_request -> 'controls') < 1
     or jsonb_array_length(p_request -> 'controls') > 4
     or jsonb_typeof(p_request -> 'requiresManualResume') <> 'boolean'
  then
    raise exception 'bounded capacity controls required' using errcode = '22023';
  end if;
  v_operation := (p_request ->> 'operationId')::uuid;
  v_reason := p_request ->> 'reasonFingerprint';

  for v_control in select value from jsonb_array_elements_text(p_request -> 'controls') loop
    -- Idempotent by construction: the partial unique index collapses a repeat of
    -- an already-active control, so a retried watchdog tick cannot double-apply.
    insert into public.openclaw_capacity_controls(
      organization_id, control, applied_operation_id, reason_fingerprint,
      requires_manual_resume
    ) values (
      v_org, v_control, v_operation, v_reason,
      (p_request ->> 'requiresManualResume')::boolean
    )
    on conflict (organization_id, control) where released_at is null do nothing;
    if found then v_applied := v_applied + 1; else v_already := v_already + 1; end if;
  end loop;

  return jsonb_build_object(
    'version', 1, 'applied', v_applied, 'alreadyActive', v_already,
    'databaseTime', statement_timestamp()
  );
end;
$$;








--
-- Name: openclaw_apply_knowledge_write_v1(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_apply_knowledge_write_v1(p_action text, p_organization_id uuid, p_actor_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_source public.openclaw_knowledge_sources%rowtype;
  v_version public.openclaw_knowledge_versions%rowtype;
  v_source_id uuid := coalesce(nullif(p_request ->> 'sourceId', '')::uuid, gen_random_uuid());
  v_version_id uuid := gen_random_uuid();
  v_next_version bigint;
  v_content text;
  v_content_hash text;
begin
  if p_action = 'CREATE_DRAFT' then
    v_content := p_request ->> 'content';
    if coalesce(v_content, '') = '' then raise exception 'knowledge content required' using errcode = '22023'; end if;
    v_content_hash := encode(extensions.digest(
      convert_to('ihome-openclaw-knowledge-content-v1', 'UTF8')
        || decode('00', 'hex') || convert_to(v_content, 'UTF8'), 'sha256'
    ), 'hex');
    insert into public.openclaw_knowledge_sources (
      id, organization_id, account_id, title, source_kind, sensitivity,
      lifecycle_state, current_version
    ) values (
      v_source_id, p_organization_id, (p_request ->> 'accountId')::uuid,
      p_request ->> 'title', p_request ->> 'sourceKind', p_request ->> 'sensitivity',
      'DRAFT', 1
    );
    insert into public.openclaw_knowledge_versions (
      id, organization_id, account_id, source_id, version, sensitivity,
      lifecycle_state, content, content_hash, metadata, created_by
    ) values (
      v_version_id, p_organization_id, (p_request ->> 'accountId')::uuid,
      v_source_id, 1, p_request ->> 'sensitivity', 'DRAFT',
      v_content, v_content_hash, coalesce(p_request -> 'metadata', '{}'::jsonb), p_actor_id
    );
    return jsonb_build_object(
      'version', 1, 'sourceId', v_source_id, 'knowledgeVersionId', v_version_id,
      'knowledgeVersion', 1, 'lifecycleState', 'DRAFT', 'contentHash', v_content_hash
    );
  end if;

  select source.* into strict v_source from public.openclaw_knowledge_sources source
  where source.organization_id = p_organization_id
    and source.id = (p_request ->> 'sourceId')::uuid for update;

  if p_action = 'UPDATE_DRAFT' then
    if v_source.current_version <> (p_request ->> 'expectedSourceVersion')::bigint then
      raise exception 'knowledge source version mismatch' using errcode = '40001';
    end if;
    v_next_version := v_source.current_version + 1;
    v_content := p_request ->> 'content';
    v_content_hash := encode(extensions.digest(
      convert_to('ihome-openclaw-knowledge-content-v1', 'UTF8')
        || decode('00', 'hex') || convert_to(v_content, 'UTF8'), 'sha256'
    ), 'hex');
    insert into public.openclaw_knowledge_versions (
      id, organization_id, account_id, source_id, version, sensitivity,
      lifecycle_state, content, content_hash, metadata, created_by
    ) values (
      v_version_id, p_organization_id, v_source.account_id, v_source.id,
      v_next_version, v_source.sensitivity, 'DRAFT', v_content, v_content_hash,
      coalesce(p_request -> 'metadata', '{}'::jsonb), p_actor_id
    );
    update public.openclaw_knowledge_sources set current_version = v_next_version,
      lifecycle_state = 'DRAFT', updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_source.id;
    return jsonb_build_object(
      'version', 1, 'sourceId', v_source.id, 'knowledgeVersionId', v_version_id,
      'knowledgeVersion', v_next_version, 'lifecycleState', 'DRAFT',
      'contentHash', v_content_hash
    );
  end if;

  select version.* into strict v_version from public.openclaw_knowledge_versions version
  where version.organization_id = p_organization_id and version.source_id = v_source.id
    and version.id = (p_request ->> 'knowledgeVersionId')::uuid for update;

  if p_action = 'VALIDATE' then
    if v_version.lifecycle_state <> 'DRAFT' then
      raise exception 'only draft knowledge can be validated' using errcode = '55000';
    end if;
    update public.openclaw_knowledge_versions
    set validation_result = jsonb_build_object(
      'version', 1, 'valid', true, 'validatedAt', statement_timestamp(),
      'contentHash', v_version.content_hash
    )
    where organization_id = p_organization_id and id = v_version.id;
    return jsonb_build_object(
      'version', 1, 'sourceId', v_source.id, 'knowledgeVersionId', v_version.id,
      'valid', true, 'contentHash', v_version.content_hash
    );
  elsif p_action = 'PUBLISH' then
    if v_version.lifecycle_state <> 'DRAFT' or v_version.validation_result is null
       or v_source.current_version <> v_version.version
    then raise exception 'validated current knowledge draft required' using errcode = '55000'; end if;
    update public.openclaw_knowledge_versions set lifecycle_state = 'PUBLISHED',
      published_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_version.id;
    update public.openclaw_knowledge_sources set lifecycle_state = 'PUBLISHED',
      updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_source.id;
    return jsonb_build_object(
      'version', 1, 'sourceId', v_source.id, 'knowledgeVersionId', v_version.id,
      'knowledgeVersion', v_version.version, 'lifecycleState', 'PUBLISHED'
    );
  elsif p_action = 'ARCHIVE' then
    if v_version.lifecycle_state not in ('PUBLISHED','DRAFT') then
      raise exception 'knowledge version cannot be archived' using errcode = '55000';
    end if;
    update public.openclaw_knowledge_versions set lifecycle_state = 'ARCHIVED',
      archived_at = statement_timestamp(), published_at = coalesce(published_at, statement_timestamp())
    where organization_id = p_organization_id and id = v_version.id;
    update public.openclaw_knowledge_sources set lifecycle_state = 'ARCHIVED',
      updated_at = statement_timestamp()
    where organization_id = p_organization_id and id = v_source.id;
    return jsonb_build_object(
      'version', 1, 'sourceId', v_source.id, 'knowledgeVersionId', v_version.id,
      'knowledgeVersion', v_version.version, 'lifecycleState', 'ARCHIVED'
    );
  end if;
  raise exception 'unsupported knowledge action' using errcode = '22023';
end;
$$;








--
-- Name: openclaw_apply_schedule_write_v1(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_apply_schedule_write_v1(p_action text, p_organization_id uuid, p_actor_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_schedule public.openclaw_schedules%rowtype;
  v_campaign_version public.openclaw_campaign_runs%rowtype;
  v_schedule_id uuid := coalesce(nullif(p_request->>'scheduleId','')::uuid,gen_random_uuid());
  v_account uuid := (p_request->>'accountId')::uuid;
  v_version bigint;
  v_status text;
  v_rule text;
  v_timezone text;
  v_nominal timestamp;
  v_resolved record;
  v_grace integer;
  v_fold text;
  v_snapshot jsonb;
  v_snapshot_bytes bytea;
  v_snapshot_hash text;
begin
  if p_action not in ('UPSERT','PAUSE','CANCEL') then
    raise exception 'unsupported schedule action' using errcode='22023';
  end if;
  if p_action='UPSERT' and p_request ? 'nextRunAt' then
    raise exception 'nextRunAt is database-derived and must not be supplied' using errcode='22023';
  end if;
  if p_action='UPSERT' and (
    nullif(p_request->>'targetId','') is null
    or nullif(p_request->>'campaignVersionId','') is null
  ) then
    raise exception 'targetId and immutable campaignVersionId are required'
      using errcode='22023';
  end if;

  if p_action='UPSERT' then
    select campaign_version.* into strict v_campaign_version
    from public.openclaw_campaign_runs campaign_version
    where campaign_version.organization_id=p_organization_id
      and campaign_version.account_id=v_account
      and campaign_version.id=(p_request->>'campaignVersionId')::uuid
      and campaign_version.automation_version_id=(p_request->>'automationVersionId')::uuid
      and campaign_version.status in ('PLANNED','RUNNING')
    for share;
    v_rule := p_request->>'localRecurrenceRule';
    perform app_private.openclaw_parse_local_recurrence_rule_v1(v_rule);
    v_timezone := p_request->>'timezone';
    if not exists (select 1 from pg_catalog.pg_timezone_names zone where zone.name=v_timezone) then
      raise exception 'unknown IANA timezone' using errcode='22023';
    end if;
    v_grace := coalesce((p_request->>'occurrenceGraceSeconds')::integer,300);
    v_fold := coalesce(p_request->>'dstFoldPolicy','EARLIER_OFFSET');
    if v_grace not between 60 and 3600 or v_fold not in ('EARLIER_OFFSET','LATER_OFFSET') then
      raise exception 'invalid occurrence grace or DST fold policy' using errcode='22023';
    end if;
    v_nominal := app_private.openclaw_next_schedule_occurrence_v1(v_rule,null);
    select * into strict v_resolved
    from app_private.openclaw_resolve_local_occurrence_v1(v_nominal,v_timezone,v_fold);
  end if;

  if p_action='UPSERT' and nullif(p_request->>'scheduleId','') is null then
    v_version := 1;
    v_status := 'PAUSED';
    insert into public.openclaw_schedules(
      id,organization_id,account_id,automation_version_id,target_id,campaign_id,
      campaign_version_id,
      schedule_version,status,timezone,local_recurrence_rule,next_run_at,
      occurrence_grace_seconds,dst_fold_policy,next_nominal_local,next_resolved_local,
      next_utc_offset_seconds,next_resolution,cursor_version,binding_defer_reason
    ) values (
      v_schedule_id,p_organization_id,v_account,(p_request->>'automationVersionId')::uuid,
      (p_request->>'targetId')::uuid,v_campaign_version.campaign_id,v_campaign_version.id,
      1,v_status,v_timezone,v_rule,v_resolved.planned_for,
      v_grace,v_fold,v_nominal,v_resolved.resolved_local,v_resolved.utc_offset_seconds,
      v_resolved.resolution,1,null
    );
  else
    select schedule.* into strict v_schedule
    from public.openclaw_schedules schedule
    where schedule.organization_id=p_organization_id
      and schedule.id=(p_request->>'scheduleId')::uuid
    for update;
    if v_schedule.schedule_version<>(p_request->>'expectedScheduleVersion')::bigint then
      raise exception 'schedule version mismatch' using errcode='40001';
    end if;
    v_schedule_id := v_schedule.id;
    v_account := v_schedule.account_id;
    v_version := v_schedule.schedule_version+1;
    v_status := case p_action when 'PAUSE' then 'PAUSED' when 'CANCEL' then 'CANCELLED' else 'PAUSED' end;
    update public.openclaw_schedules schedule set
      automation_version_id=case when p_action='UPSERT' then (p_request->>'automationVersionId')::uuid else schedule.automation_version_id end,
      target_id=case when p_action='UPSERT' then (p_request->>'targetId')::uuid else schedule.target_id end,
      campaign_id=case when p_action='UPSERT' then v_campaign_version.campaign_id else schedule.campaign_id end,
      campaign_version_id=case when p_action='UPSERT' then v_campaign_version.id else schedule.campaign_version_id end,
      schedule_version=v_version,status=v_status,
      timezone=case when p_action='UPSERT' then v_timezone else schedule.timezone end,
      local_recurrence_rule=case when p_action='UPSERT' then v_rule else schedule.local_recurrence_rule end,
      occurrence_grace_seconds=case when p_action='UPSERT' then v_grace else schedule.occurrence_grace_seconds end,
      dst_fold_policy=case when p_action='UPSERT' then v_fold else schedule.dst_fold_policy end,
      next_nominal_local=case when p_action='UPSERT' then v_nominal else schedule.next_nominal_local end,
      next_resolved_local=case when p_action='UPSERT' then v_resolved.resolved_local else schedule.next_resolved_local end,
      next_run_at=case when p_action='UPSERT' then v_resolved.planned_for else schedule.next_run_at end,
      next_utc_offset_seconds=case when p_action='UPSERT' then v_resolved.utc_offset_seconds else schedule.next_utc_offset_seconds end,
      next_resolution=case when p_action='UPSERT' then v_resolved.resolution else schedule.next_resolution end,
      cursor_version=schedule.cursor_version+1,binding_defer_reason=null,
      updated_at=statement_timestamp()
    where schedule.organization_id=p_organization_id and schedule.id=v_schedule.id;
  end if;

  select schedule.* into strict v_schedule from public.openclaw_schedules schedule
  where schedule.organization_id=p_organization_id and schedule.id=v_schedule_id;
  v_snapshot := jsonb_build_object(
    'version',1,'scheduleId',v_schedule.id,'scheduleVersion',v_schedule.schedule_version,
    'automationVersionId',v_schedule.automation_version_id,'targetId',v_schedule.target_id,
    'campaignVersionId',v_schedule.campaign_version_id,
    'status',v_schedule.status,'timezone',v_schedule.timezone,
    'localRecurrenceRule',v_schedule.local_recurrence_rule,
    'missedOccurrencePolicy',v_schedule.missed_occurrence_policy,
    'occurrenceGraceSeconds',v_schedule.occurrence_grace_seconds,
    'dstFoldPolicy',v_schedule.dst_fold_policy
  );
  v_snapshot_bytes := app_private.openclaw_jcs_bytes_v1(v_snapshot);
  v_snapshot_hash := encode(extensions.digest(
    convert_to('ihome-openclaw-schedule-snapshot-v1','UTF8')||decode('00','hex')||v_snapshot_bytes,
    'sha256'),'hex');
  insert into public.openclaw_schedule_snapshots(
    organization_id,account_id,schedule_id,schedule_version,automation_version_id,
    target_id,campaign_id,campaign_version_id,status,timezone,local_recurrence_rule,missed_occurrence_policy,
    occurrence_grace_seconds,dst_fold_policy,snapshot,snapshot_bytes,snapshot_hash,created_by
  ) values (
    p_organization_id,v_schedule.account_id,v_schedule.id,v_schedule.schedule_version,
    v_schedule.automation_version_id,v_schedule.target_id,v_schedule.campaign_id,
    v_schedule.campaign_version_id,v_schedule.status,
    v_schedule.timezone,v_schedule.local_recurrence_rule,v_schedule.missed_occurrence_policy,
    v_schedule.occurrence_grace_seconds,v_schedule.dst_fold_policy,
    v_snapshot,v_snapshot_bytes,v_snapshot_hash,p_actor_id
  );
  return jsonb_build_object('version',1,'scheduleId',v_schedule.id,
    'scheduleVersion',v_schedule.schedule_version,'status',v_schedule.status,
    'nextRunAt',v_schedule.next_run_at,'snapshotHash',v_snapshot_hash);
end;
$$;








--
-- Name: openclaw_assert_strict_object_v1(jsonb, text[], text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_assert_strict_object_v1(p_value jsonb, p_allowed_keys text[], p_required_keys text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_key text;
begin
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'strict JSON object required' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_value) key_name
    where not (key_name = any(p_allowed_keys))
  ) then
    raise exception 'unknown JSON key rejected' using errcode = '22023';
  end if;
  foreach v_key in array p_required_keys loop
    if not (p_value ? v_key) then
      raise exception 'required JSON key % is missing', v_key using errcode = '22023';
    end if;
  end loop;
end;
$$;








--
-- Name: openclaw_audit_lineage_root_v1(uuid, date, bigint, bigint, bigint, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_audit_lineage_root_v1(p_organization_id uuid, p_root_date date, p_first_sequence bigint, p_last_sequence bigint, p_event_count bigint, p_previous_root_hash text, p_merkle_root_hash text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_lineage jsonb;
begin
  if p_first_sequence not between 1 and 9007199254740991
     or p_last_sequence not between p_first_sequence and 9007199254740991
     or p_event_count<>p_last_sequence-p_first_sequence+1
     or p_previous_root_hash is not null and p_previous_root_hash !~ '^[0-9a-f]{64}$'
     or p_merkle_root_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'audit lineage inputs are invalid' using errcode='22023';
  end if;
  v_lineage:=jsonb_build_object(
    'version',1,'organizationId',p_organization_id,'rootDate',p_root_date,
    'firstSequence',p_first_sequence,'lastSequence',p_last_sequence,
    'eventCount',p_event_count,'previousRootHash',p_previous_root_hash,
    'merkleRootHash',p_merkle_root_hash
  );
  return encode(extensions.digest(
    convert_to('ihome-openclaw-audit-lineage-root-v1','UTF8')||decode('00','hex')
      ||app_private.openclaw_jcs_bytes_v1(v_lineage),'sha256'),'hex');
end;
$_$;








--
-- Name: openclaw_audit_merkle_root_v1(bigint[], text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_audit_merkle_root_v1(p_sequences bigint[], p_event_hashes text[]) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_level bytea[] := array[]::bytea[];
  v_next bytea[];
  v_index integer;
  v_length integer := coalesce(array_length(p_sequences,1),0);
begin
  if v_length=0 or v_length<>coalesce(array_length(p_event_hashes,1),0) then
    raise exception 'audit Merkle inputs are invalid' using errcode='22023';
  end if;
  for v_index in 1..v_length loop
    if p_sequences[v_index] not between 1 and 9007199254740991
       or p_event_hashes[v_index] !~ '^[0-9a-f]{64}$' then
      raise exception 'audit Merkle leaf is invalid' using errcode='22023';
    end if;
    v_level:=array_append(v_level,extensions.digest(
      convert_to('ihome-openclaw-audit-merkle-leaf-v1','UTF8')||decode('00','hex')
        ||convert_to(p_sequences[v_index]::text,'UTF8')||decode('00','hex')
        ||decode(p_event_hashes[v_index],'hex'),'sha256'
    ));
  end loop;
  while array_length(v_level,1)>1 loop
    v_next:=array[]::bytea[];
    v_index:=1;
    while v_index<=array_length(v_level,1) loop
      v_next:=array_append(v_next,extensions.digest(
        convert_to('ihome-openclaw-audit-merkle-node-v1','UTF8')||decode('00','hex')
          ||v_level[v_index]
          ||coalesce(v_level[v_index+1],v_level[v_index]),'sha256'
      ));
      v_index:=v_index+2;
    end loop;
    v_level:=v_next;
  end loop;
  return encode(v_level[1],'hex');
end;
$_$;








--
-- Name: openclaw_audit_migration_step_v1(uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_audit_migration_step_v1(p_organization_id uuid, p_step text, p_request jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_evidence jsonb;
  v_actor uuid;
  v_caller text;
  v_run record;
  v_request_id uuid;
begin
  -- ATTRIBUTION IS TAKEN FROM THE SESSION, NEVER FROM THE REQUEST.
  --
  -- A record whose actor is whatever the caller typed proves nothing: the party we
  -- are trying to distinguish - someone holding the service key - writes the
  -- request. Everything recorded below is either set by PostgREST from a verified
  -- JWT, or read from the database itself.
  --
  -- Be clear about what that buys HERE: these facades are granted to
  -- `service_role` only, and a service-key JWT carries no `sub`, so `actorId` is
  -- null on every invocation these functions can currently receive. It is recorded
  -- anyway because the value is free, and because the day a member role is granted
  -- one of these, an unattributed step must look different from an attributed one.
  -- The load-bearing signal is `rolloutRunId` below, not this.
  begin
    v_actor := nullif(
      current_setting('request.jwt.claims', true)::jsonb ->> 'sub', ''
    )::uuid;
  exception when others then
    v_actor := null;
  end;
  -- Who ran it, at three levels, because one of them is uninformative in each of
  -- the two call paths. Over PostgREST the `role` GUC is the answer and reads
  -- `service_role`; over a direct psql connection nothing sets it and it reads the
  -- literal 'none', which is why session_user/current_user are recorded too.
  -- SECURITY DEFINER changes current_user but not the GUC.
  v_caller := coalesce(nullif(current_setting('role', true), ''), 'unset');

  -- The canonical rollout run that AUTHORIZES this step - restricted to RUNNING.
  --
  -- Matching COMPLETE runs too made this worthless: `openclaw_rollout_runs_one_active_uidx`
  -- bounds RUNNING to one per organization, but COMPLETE rows accumulate forever, so
  -- once an organization finished its first rollout EVERY later step - planned or
  -- not - inherited that run's id and `rolloutRunId: null` could never appear again.
  -- A finished rollout authorizes nothing; only a run still in flight does.
  select run.id, run.stage, run.started_at
    into v_run
  from public.openclaw_rollout_runs run
  where run.organization_id = p_organization_id
    and run.status = 'RUNNING'
  order by run.started_at desc, run.id desc
  limit 1;

  -- Correlates the steps of ONE adapter invocation; ignored unless it is a uuid,
  -- because a caller-supplied string must never widen what the audit accepts.
  v_request_id := case
    when coalesce(p_request ->> 'requestId', '')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then (p_request ->> 'requestId')::uuid
  end;

  -- Content-free by construction: the step, the organization, and a digest of the
  -- request. Never the request itself, which can carry cell ids and operator text.
  --
  -- Everything forensic lives in the EVIDENCE, not in the neighbouring columns:
  -- append_openclaw_audit_v1 hashes previous_hash|sequence|event_type|evidence_hash,
  -- so actor_id/request_id/correlation_id sit outside the chain and could be edited
  -- without breaking it. They are still written for indexing, but the copies here
  -- are the tamper-evident ones.
  v_evidence := jsonb_build_object(
    'version', 3,
    'step', p_step,
    'organizationId', p_organization_id,
    'requestDigest', encode(
      extensions.digest(app_private.openclaw_jcs_bytes_v1(p_request), 'sha256'), 'hex'
    ),
    'actorId', v_actor,
    'callerRole', v_caller,
    'sessionUser', session_user,
    'currentUser', current_user,
    'requestId', v_request_id,
    'rolloutRunId', v_run.id,
    'rolloutStage', v_run.stage
  );
  perform app_private.append_openclaw_audit_v1(
    p_organization_id,
    'OPENCLAW_MIGRATION_STEP',
    v_actor,
    'openclaw-migration-adapter',
    v_request_id,
    v_run.id,
    v_evidence,
    convert_to(v_evidence::text, 'UTF8')
  );
end;
$_$;








--
-- Name: openclaw_authorize_outbox_send_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_authorize_outbox_send_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid := (p_principal ->> 'organizationId')::uuid;
  v_account uuid := (p_principal ->> 'accountId')::uuid;
  v_marker jsonb := p_request -> 'authorizationMarker';
  v_authorization public.openclaw_outbound_authorizations%rowtype;
  v_marker_hash text;
  v_claim_token_hash text;
  v_outbox public.openclaw_outbox%rowtype;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','claimToken','authorizationMarker'],
    array['version','claimToken','authorizationMarker']
  );
  perform app_private.openclaw_assert_strict_object_v1(
    v_marker,
    array['version','outboxId','claimGeneration','payloadHash','fencingToken',
      'sessionGeneration','controlVersion','takeoverVersion','markerNonce','expiresAt'],
    array['version','outboxId','claimGeneration','payloadHash','fencingToken',
      'sessionGeneration','controlVersion','takeoverVersion','markerNonce','expiresAt']
  );
  if p_request ->> 'version' <> '1'
     or v_marker ->> 'version' <> '1'
     or nullif(p_request ->> 'claimToken', '') is null
     or nullif(v_marker ->> 'markerNonce', '') is null
  then
    raise exception 'private outbox authorization contract is invalid' using errcode='42501';
  end if;
  v_marker_hash := encode(extensions.digest(convert_to('ihome-openclaw-handoff-marker-v1','UTF8')
    || decode('00','hex') || convert_to(v_marker ->> 'markerNonce','UTF8'),'sha256'),'hex');
  v_claim_token_hash := encode(extensions.digest(convert_to('ihome-openclaw-outbox-claim-v1','UTF8')
    || decode('00','hex') || convert_to(p_request ->> 'claimToken','UTF8'),'sha256'),'hex');
  update public.openclaw_outbound_authorizations handoff
  set consumed_at = statement_timestamp(), authorized_handoff_at = statement_timestamp()
  where handoff.organization_id=v_org and handoff.account_id=v_account
    and handoff.outbox_id=(v_marker ->> 'outboxId')::uuid
    and handoff.claim_generation=(v_marker ->> 'claimGeneration')::bigint
    and handoff.payload_hash=v_marker ->> 'payloadHash'
    and handoff.fencing_token=(v_marker ->> 'fencingToken')::bigint
    and handoff.session_generation=(v_marker ->> 'sessionGeneration')::bigint
    and handoff.control_version=(v_marker ->> 'controlVersion')::bigint
    and handoff.takeover_version=(v_marker ->> 'takeoverVersion')::bigint
    and handoff.marker_nonce_hash=v_marker_hash
    and handoff.expires_at=(v_marker ->> 'expiresAt')::timestamptz
    and handoff.fencing_token=(p_principal ->> 'fencingToken')::bigint
    and handoff.session_generation=(p_principal ->> 'sessionGeneration')::bigint
    and handoff.consumed_at is null and handoff.expires_at > statement_timestamp()
    and handoff.lease_expires_at > statement_timestamp()
    and exists (
      select 1
      from public.openclaw_outbox outbox
      join public.openclaw_control_states control
        on control.organization_id=outbox.organization_id and control.control_key='GLOBAL_STOP'
      where outbox.organization_id=handoff.organization_id
        and outbox.account_id=handoff.account_id and outbox.id=handoff.outbox_id
        and outbox.state='LEASED' and not control.global_stop and control.feature_enabled
        and outbox.claim_token_hash=v_claim_token_hash
        and outbox.claimed_cell_id=(p_principal ->> 'cellId')::uuid
        and outbox.fencing_token=(p_principal ->> 'fencingToken')::bigint
        and outbox.session_generation=(p_principal ->> 'sessionGeneration')::bigint
        and control.control_version=handoff.control_version
        and coalesce((
          select max(takeover.takeover_version)
          from public.openclaw_takeovers takeover
          join public.openclaw_conversations conversation
            on conversation.organization_id=takeover.organization_id
           and conversation.account_id=takeover.account_id
           and conversation.id=takeover.conversation_id
          where takeover.organization_id=outbox.organization_id
            and takeover.account_id=outbox.account_id and conversation.target_id=outbox.target_id
        ),0)=handoff.takeover_version
    )
  returning handoff.* into v_authorization;
  if not found then raise exception 'outbound authorization CAS failed' using errcode='40001'; end if;
  update public.openclaw_outbox outbox
  set state = 'DISPATCHING', dispatching_at = statement_timestamp(), updated_at = statement_timestamp()
  where outbox.organization_id=v_org and outbox.account_id=v_account and outbox.id=v_authorization.outbox_id
    and outbox.state = 'LEASED' and outbox.claim_generation=v_authorization.claim_generation
    and outbox.payload_hash=v_authorization.payload_hash
    and outbox.claim_token_hash=v_claim_token_hash
    and outbox.claimed_cell_id=(p_principal ->> 'cellId')::uuid
    and outbox.fencing_token=(p_principal ->> 'fencingToken')::bigint
    and outbox.session_generation=(p_principal ->> 'sessionGeneration')::bigint
    and outbox.lease_expires_at > statement_timestamp()
  returning outbox.* into v_outbox;
  if not found then raise exception 'outbox authorize transition CAS failed' using errcode='40001'; end if;
  return jsonb_build_object('version',1,'outboxId',v_outbox.id,
    'authorizationId',v_authorization.id,'state',v_outbox.state,
    'authorizedHandoffAt',v_authorization.authorized_handoff_at,
    'canonicalPayload',v_outbox.canonical_payload,'payloadHash',v_outbox.payload_hash);
end;
$$;








--
-- Name: openclaw_authorize_retention_delete_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_authorize_retention_delete_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org uuid := (p_principal->>'organizationId')::uuid;
  v_maintenance uuid := (p_principal->>'maintenancePrincipalId')::uuid;
  v_work public.openclaw_maintenance_work_items%rowtype;
  v_tomb public.openclaw_retention_tombstones%rowtype;
  v_ticket public.openclaw_retention_delete_tickets%rowtype;
  v_token text;
  v_hold_version bigint;
  v_ticket_signing bigint;
  v_receipt_signing bigint;
  v_gateway_key_hash text;
  v_issued timestamptz := date_trunc('milliseconds',statement_timestamp());
  v_expires timestamptz;
  v_ticket_expires timestamptz;
  v_claims jsonb;
  v_payload jsonb;
  v_bytes bytea;
  v_authorization_hash text;
  v_refresh boolean := p_request->>'recoveryKind'='RETENTION_DELETE_AUTHORIZED';
  v_old_lineage public.openclaw_retention_delete_ticket_lineage%rowtype;
  v_existing_lineage public.openclaw_retention_delete_ticket_lineage%rowtype;
  v_new_ticket_jti uuid := gen_random_uuid();
  v_new_authorization_jti uuid := gen_random_uuid();
  v_ticket_payload jsonb;
  v_ticket_bytes bytea;
  v_ticket_hash text;
  v_domain_hash text;
  v_refresh_denial_hash text;
begin
  if v_refresh then
    perform app_private.openclaw_assert_strict_object_v1(
      p_request,
      array['version','recoveryKind','workItemId','recoveryGeneration','claimToken','ticketId',
        'expiredTicketJti','expiredDeleteAuthorizationJti','gatewayDenial'],
      array['version','recoveryKind','workItemId','recoveryGeneration','claimToken','ticketId',
        'expiredTicketJti','expiredDeleteAuthorizationJti','gatewayDenial']
    );
    perform app_private.openclaw_assert_strict_object_v1(
      p_request->'gatewayDenial',array['status','code'],array['status','code']
    );
  else
    perform app_private.openclaw_assert_strict_object_v1(
      p_request,
      array['version','workItemId','claimGeneration','claimToken'],
      array['version','workItemId','claimGeneration','claimToken']
    );
  end if;
  if p_request->>'version'<>'1' then
    raise exception 'retention authorization version mismatch' using errcode='22023';
  end if;
  perform app_private.openclaw_lock_retention_scope_v1(v_org);
  v_token := encode(extensions.digest(convert_to('ihome-openclaw-work-claim-v1','UTF8')
    ||decode('00','hex')||convert_to(p_request->>'claimToken','UTF8'),'sha256'),'hex');
  if v_refresh then
    if p_request->>'recoveryKind'<>'RETENTION_DELETE_AUTHORIZED'
       or p_request->>'expiredTicketJti' !~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or p_request->>'expiredDeleteAuthorizationJti' !~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or p_request->'gatewayDenial' is distinct from
         jsonb_build_object('status',410,'code','TICKET_EXPIRED_NO_WORK') then
      raise exception 'retention recovery refresh evidence invalid' using errcode='22023';
    end if;
    v_refresh_denial_hash:=encode(extensions.digest(
      app_private.openclaw_jcs_bytes_v1(p_request->'gatewayDenial'),'sha256'),'hex');
    select lineage.* into v_existing_lineage
    from public.openclaw_retention_delete_ticket_lineage lineage
    where lineage.organization_id=v_org
      and lineage.logical_ticket_id=(p_request->>'ticketId')::uuid
      and lineage.work_item_id=(p_request->>'workItemId')::uuid
      and lineage.replaces_ticket_jti=(p_request->>'expiredTicketJti')::uuid
      and lineage.replaces_delete_authorization_jti=
        (p_request->>'expiredDeleteAuthorizationJti')::uuid
      and lineage.refresh_gateway_denial=p_request->'gatewayDenial'
      and lineage.refresh_gateway_denial_hash=v_refresh_denial_hash
      and lineage.authorization_claim_token_hash=v_token
      and lineage.authorization_maintenance_principal_id=v_maintenance
      and lineage.authorization_credential_generation=
        (p_principal->>'credentialGeneration')::bigint
      and lineage.authorization_lease_generation=(p_principal->>'leaseGeneration')::bigint
      and lineage.authorization_fencing_token=(p_principal->>'fencingToken')::bigint
      and lineage.recovery_generation=(p_request->>'recoveryGeneration')::bigint;
    if found then
      return jsonb_build_object('version',1,'ticketId',v_existing_lineage.logical_ticket_id,
        'ticketHash',v_existing_lineage.ticket_hash,
        'deleteAuthorizationJti',v_existing_lineage.delete_authorization_jti,
        'expiresAt',v_existing_lineage.authorization_expires_at,
        'state','RECOVERY_REFRESHED','replacesTicketJti',v_existing_lineage.replaces_ticket_jti,
        'replacesDeleteAuthorizationJti',v_existing_lineage.replaces_delete_authorization_jti,
        'ticket',v_existing_lineage.ticket_payload,
        'authorization',v_existing_lineage.authorization_payload);
    end if;
    select ticket.* into v_ticket
    from public.openclaw_retention_delete_tickets ticket
    where ticket.organization_id=v_org and ticket.id=(p_request->>'ticketId')::uuid
      and ticket.work_item_id=(p_request->>'workItemId')::uuid
    for update;
    if not found or v_ticket.state<>'DELETE_AUTHORIZED'
       or v_ticket.ticket_jti<>(p_request->>'expiredTicketJti')::uuid
       or v_ticket.delete_authorization_jti<>
         (p_request->>'expiredDeleteAuthorizationJti')::uuid then
      raise exception 'retention recovery refresh authoritative pointer mismatch'
        using errcode='40001';
    end if;
    select lineage.* into v_old_lineage
    from public.openclaw_retention_delete_ticket_lineage lineage
    where lineage.organization_id=v_org and lineage.logical_ticket_id=v_ticket.id
      and lineage.ticket_jti=v_ticket.ticket_jti
      and lineage.delete_authorization_jti=v_ticket.delete_authorization_jti;
    if not found or (v_old_lineage.expires_at>v_issued
      and v_old_lineage.authorization_expires_at>v_issued) then
      raise exception 'retention recovery refresh requires expired ticket or proof'
        using errcode='40001';
    end if;
    select work.* into v_work from public.openclaw_maintenance_work_items work
    join public.openclaw_maintenance_credentials credential
      on credential.organization_id=work.organization_id
     and credential.maintenance_principal_id=work.recovery_maintenance_principal_id
     and credential.credential_generation=work.recovery_credential_generation
     and credential.revoked_at is null
    join public.openclaw_maintenance_leases lease
      on lease.organization_id=work.organization_id
     and lease.maintenance_principal_id=work.recovery_maintenance_principal_id
     and lease.lease_generation=work.recovery_lease_generation
     and lease.fencing_token=work.recovery_fencing_token
     and lease.status='ACTIVE' and lease.expires_at>v_issued
    where work.organization_id=v_org and work.id=v_ticket.work_item_id
      and work.state='DELETE_AUTHORIZED' and work.work_kind='RETENTION_DELETE'
      and work.work_phase='FINAL_DELETE'
      and work.recovery_maintenance_principal_id=v_maintenance
      and work.recovery_credential_generation=(p_principal->>'credentialGeneration')::bigint
      and work.recovery_lease_generation=(p_principal->>'leaseGeneration')::bigint
      and work.recovery_fencing_token=(p_principal->>'fencingToken')::bigint
      and work.recovery_generation=(p_request->>'recoveryGeneration')::bigint
      and work.claim_token_hash=v_token and work.recovery_lease_expires_at>v_issued
    for update of work;
    if not found then raise exception 'retention recovery refresh ownership CAS failed'
      using errcode='40001'; end if;
    perform app_private.openclaw_lock_retention_tombstone_v1(v_org,v_work.source_id);
    select tombstone.* into v_tomb from public.openclaw_retention_tombstones tombstone
    where tombstone.organization_id=v_org and tombstone.id=v_ticket.tombstone_id
      and tombstone.subject_kind='MEDIA' and tombstone.subject_id=v_ticket.subject_id
      and tombstone.object_key=v_ticket.object_key
      and tombstone.quarantine_version=v_ticket.quarantine_version
      and tombstone.final_delete_not_before<=v_issued;
    if not found then raise exception 'retention recovery refresh tombstone mismatch'
      using errcode='40001'; end if;
    perform scope.id from public.openclaw_retention_hold_scopes scope
    where scope.organization_id=v_org and (scope.scope_kind='ORGANIZATION'
      or (scope.scope_kind='MEDIA' and scope.scope_id=v_tomb.subject_id))
    order by scope.scope_kind,scope.scope_id,scope.id for share;
    if app_private.openclaw_retention_subject_held_v1(v_org,'MEDIA',v_tomb.subject_id) then
      raise exception 'active descendant legal hold blocks retention recovery refresh'
        using errcode='42501';
    end if;
    select coalesce(clock.hold_version,0) into v_hold_version
    from (select 1) singleton left join public.openclaw_retention_hold_clocks clock
      on clock.organization_id=v_org;
    if v_hold_version<>v_old_lineage.hold_version then
      raise exception 'hold_version changed before retention recovery refresh'
        using errcode='40001';
    end if;
    perform app_private.openclaw_lock_retention_gateway_config_v1(v_org);
    select config.ticket_key_generation,config.signing_key_generation,config.public_key_hash
      into v_ticket_signing,v_receipt_signing,v_gateway_key_hash
    from public.openclaw_retention_gateway_configs config
    where config.organization_id=v_org and config.is_active and config.retired_at is null;
    if not found then raise exception 'active retention Gateway generations required'
      using errcode='42501'; end if;
    v_ticket_expires:=least(v_issued+interval '60 seconds',v_work.recovery_lease_expires_at);
    v_expires:=least(v_issued+interval '5 seconds',v_work.recovery_lease_expires_at);
    if v_ticket_expires<=v_issued or v_expires<=v_issued then
      raise exception 'retention recovery refresh lease expired' using errcode='40001';
    end if;
    v_ticket_payload:=jsonb_build_object('version',1,'aud','openclaw-media-gateway',
      'operation','DELETE','subject','MAINTENANCE','jti',v_new_ticket_jti,
      'organizationId',v_org,'accountId',null,'objectKey',v_old_lineage.object_key,
      'sha256',v_old_lineage.sha256,'contentType',v_old_lineage.content_type,
      'contentLength',v_old_lineage.content_length,'sessionGeneration',0,
      'gatewayKeyGeneration',v_ticket_signing,
      'receiptSigningKeyGeneration',v_receipt_signing,
      'iat',extract(epoch from date_trunc('second',v_issued))::bigint,
      'exp',extract(epoch from date_trunc('second',v_ticket_expires))::bigint,
      'maintenancePrincipalId',v_maintenance,'workItemId',v_old_lineage.work_item_id,
      'credentialGeneration',(p_principal->>'credentialGeneration')::bigint,
      'leaseGeneration',(p_principal->>'leaseGeneration')::bigint,
      'fencingToken',(p_principal->>'fencingToken')::bigint,
      'recoveryKind','RETENTION_DELETE_AUTHORIZED',
      'recoveryGeneration',(p_request->>'recoveryGeneration')::bigint,
      'replacesTicketJti',v_old_lineage.ticket_jti,
      'replacesDeleteAuthorizationJti',v_old_lineage.delete_authorization_jti,
      'frozenClaim',jsonb_build_object(
        'maintenancePrincipalId',v_old_lineage.maintenance_principal_id,
        'credentialGeneration',v_old_lineage.credential_generation,
        'leaseGeneration',v_old_lineage.maintenance_lease_generation,
        'fencingToken',v_old_lineage.fencing_token,
        'claimGeneration',v_old_lineage.claim_generation
      ),
      'deletePhase','FINAL_DELETE',
      'holdVersion',v_old_lineage.hold_version,
      'quarantineVersion',v_old_lineage.quarantine_version,
      'finalDeleteNotBefore',v_old_lineage.ticket_payload->'finalDeleteNotBefore');
    v_ticket_bytes:=app_private.openclaw_jcs_bytes_v1(v_ticket_payload);
    v_ticket_hash:=encode(extensions.digest(
      convert_to('ihome-openclaw-retention-delete-ticket-v1','UTF8')||decode('00','hex')
        ||v_ticket_bytes,'sha256'),'hex');
    v_domain_hash:=encode(extensions.digest(
      convert_to('ihome-openclaw-retention-delete-domain-v1','UTF8')||decode('00','hex')
        ||convert_to(v_org::text||':'||v_new_ticket_jti||':'||v_old_lineage.object_key,'UTF8'),
      'sha256'),'hex');
    v_claims:=jsonb_build_object('version',1,'receiptKind','RETENTION_FINAL_DELETE',
      'organizationId',v_org,'maintenancePrincipalId',v_old_lineage.maintenance_principal_id,
      'workItemId',v_old_lineage.work_item_id,'claimGeneration',v_old_lineage.claim_generation,
      'credentialGeneration',v_old_lineage.credential_generation,
      'leaseGeneration',v_old_lineage.maintenance_lease_generation,
      'fencingToken',v_old_lineage.fencing_token,'objectKey',v_old_lineage.object_key,
      'deletePhase','FINAL_DELETE','holdVersion',v_old_lineage.hold_version,
      'quarantineVersion',v_old_lineage.quarantine_version,
      'deleteTicketJti',v_new_ticket_jti,
      'deleteAuthorizationJti',v_new_authorization_jti,'proofJti',v_new_authorization_jti,
      'gatewaySigningKeyGeneration',v_receipt_signing);
    v_payload:=jsonb_build_object('version',1,'authorizationKind','RETENTION_FINAL_DELETE',
      'organizationId',v_org,'maintenancePrincipalId',v_maintenance,
      'workItemId',v_old_lineage.work_item_id,
      'credentialGeneration',(p_principal->>'credentialGeneration')::bigint,
      'leaseGeneration',(p_principal->>'leaseGeneration')::bigint,
      'fencingToken',(p_principal->>'fencingToken')::bigint,
      'recoveryKind','RETENTION_DELETE_AUTHORIZED',
      'recoveryGeneration',(p_request->>'recoveryGeneration')::bigint,
      'replacesTicketJti',v_old_lineage.ticket_jti,
      'replacesDeleteAuthorizationJti',v_old_lineage.delete_authorization_jti,
      'frozenClaim',jsonb_build_object(
        'maintenancePrincipalId',v_old_lineage.maintenance_principal_id,
        'credentialGeneration',v_old_lineage.credential_generation,
        'leaseGeneration',v_old_lineage.maintenance_lease_generation,
        'fencingToken',v_old_lineage.fencing_token,
        'claimGeneration',v_old_lineage.claim_generation
      ),
      'objectKey',v_old_lineage.object_key,
      'deletePhase','FINAL_DELETE','holdVersion',v_old_lineage.hold_version,
      'quarantineVersion',v_old_lineage.quarantine_version,'deleteTicketJti',v_new_ticket_jti,
      'authorizationJti',v_new_authorization_jti,
      'iat',to_char(v_issued at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'exp',to_char(v_expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'gatewaySigningKeyGeneration',v_ticket_signing);
    v_bytes:=app_private.openclaw_jcs_bytes_v1(v_payload);
    v_authorization_hash:=encode(extensions.digest(
      convert_to('ihome-openclaw-retention-authorization-v1','UTF8')||decode('00','hex')
        ||v_bytes,'sha256'),'hex');
    insert into public.openclaw_retention_delete_ticket_lineage(
      organization_id,logical_ticket_id,maintenance_principal_id,work_item_id,tombstone_id,
      subject_id,object_key,sha256,content_type,content_length,ticket_jti,
      delete_authorization_jti,claim_generation,credential_generation,
      maintenance_lease_generation,fencing_token,authorization_claim_token_hash,
      authorization_maintenance_principal_id,authorization_credential_generation,
      authorization_lease_generation,authorization_fencing_token,recovery_generation,
      hold_version,quarantine_version,ticket_signing_key_generation,
      receipt_signing_key_generation,gateway_public_key_hash,domain_hash,ticket_payload,
      ticket_bytes,ticket_hash,expected_receipt_claims,authorization_payload,
      authorization_bytes,authorization_hash,issued_at,expires_at,authorized_at,
      authorization_expires_at,replaces_ticket_jti,replaces_delete_authorization_jti,
      refresh_gateway_denial,refresh_gateway_denial_hash
    ) values (
      v_org,v_ticket.id,v_old_lineage.maintenance_principal_id,v_old_lineage.work_item_id,
      v_old_lineage.tombstone_id,v_old_lineage.subject_id,v_old_lineage.object_key,
      v_old_lineage.sha256,v_old_lineage.content_type,v_old_lineage.content_length,
      v_new_ticket_jti,v_new_authorization_jti,v_old_lineage.claim_generation,
      v_old_lineage.credential_generation,v_old_lineage.maintenance_lease_generation,
      v_old_lineage.fencing_token,v_token,v_maintenance,
      (p_principal->>'credentialGeneration')::bigint,(p_principal->>'leaseGeneration')::bigint,
      (p_principal->>'fencingToken')::bigint,(p_request->>'recoveryGeneration')::bigint,
      v_old_lineage.hold_version,v_old_lineage.quarantine_version,v_ticket_signing,
      v_receipt_signing,v_gateway_key_hash,v_domain_hash,v_ticket_payload,v_ticket_bytes,
      v_ticket_hash,v_claims,v_payload,v_bytes,v_authorization_hash,v_issued,v_ticket_expires,
      v_issued,v_expires,v_old_lineage.ticket_jti,v_old_lineage.delete_authorization_jti,
      p_request->'gatewayDenial',v_refresh_denial_hash
    );
    update public.openclaw_retention_delete_tickets ticket set
      ticket_jti=v_new_ticket_jti,delete_authorization_jti=v_new_authorization_jti,
      claim_token_hash=v_token,signing_key_generation=v_ticket_signing,
      receipt_signing_key_generation=v_receipt_signing,domain_hash=v_domain_hash,
      ticket_payload=v_ticket_payload,ticket_bytes=v_ticket_bytes,ticket_hash=v_ticket_hash,
      expected_receipt_claims=v_claims,authorization_payload=v_payload,
      authorization_bytes=v_bytes,authorization_hash=v_authorization_hash,
      issued_at=v_issued,expires_at=v_ticket_expires,authorized_at=v_issued,
      authorization_expires_at=v_expires
    where ticket.organization_id=v_org and ticket.id=v_ticket.id
      and ticket.state='DELETE_AUTHORIZED'
      and ticket.ticket_jti=v_old_lineage.ticket_jti
      and ticket.delete_authorization_jti=v_old_lineage.delete_authorization_jti;
    if not found then raise exception 'retention recovery refresh pointer CAS failed'
      using errcode='40001'; end if;
    return jsonb_build_object('version',1,'ticketId',v_ticket.id,'ticketHash',v_ticket_hash,
      'deleteAuthorizationJti',v_new_authorization_jti,'expiresAt',v_expires,
      'state','RECOVERY_REFRESHED','replacesTicketJti',v_old_lineage.ticket_jti,
      'replacesDeleteAuthorizationJti',v_old_lineage.delete_authorization_jti,
      'ticket',v_ticket_payload,'authorization',v_payload);
  end if;
  select ticket.* into v_ticket
  from public.openclaw_retention_delete_tickets ticket
  where ticket.organization_id=v_org
    and ticket.work_item_id=(p_request->>'workItemId')::uuid
    and ticket.claim_generation=(p_request->>'claimGeneration')::bigint
  for update;
  if not found then
    raise exception 'retention delete ticket must be issued before authorization' using errcode='40001';
  end if;
  if v_ticket.maintenance_principal_id<>v_maintenance
    or v_ticket.credential_generation<>(p_principal->>'credentialGeneration')::bigint
    or v_ticket.maintenance_lease_generation<>(p_principal->>'leaseGeneration')::bigint
    or v_ticket.fencing_token<>(p_principal->>'fencingToken')::bigint
    or v_ticket.claim_token_hash<>v_token or v_ticket.state='REVOKED' then
    raise exception 'retention authorization ticket binding mismatch' using errcode='42501';
  end if;
  if v_ticket.state in ('DELETE_AUTHORIZED','FINALIZED') then
    return jsonb_build_object('version',1,'ticketId',v_ticket.id,
      'ticketHash',v_ticket.ticket_hash,
      'deleteAuthorizationJti',v_ticket.delete_authorization_jti,
      'expiresAt',v_ticket.authorization_expires_at,'state','DELETE_AUTHORIZED',
      'authorization',v_ticket.authorization_payload);
  end if;
  if v_ticket.state<>'TICKET_ISSUED' or v_ticket.expires_at<=v_issued then
    raise exception 'retention delete ticket is not authorizable' using errcode='40001';
  end if;
  select work.* into v_work from public.openclaw_maintenance_work_items work
  join public.openclaw_maintenance_credentials credential
    on credential.organization_id=work.organization_id
   and credential.maintenance_principal_id=work.maintenance_principal_id
   and credential.credential_generation=work.credential_generation and credential.revoked_at is null
  join public.openclaw_maintenance_leases lease
    on lease.organization_id=work.organization_id
   and lease.maintenance_principal_id=work.maintenance_principal_id
   and lease.lease_generation=work.maintenance_lease_generation
   and lease.fencing_token=work.fencing_token and lease.status='ACTIVE'
  where work.organization_id=v_org and work.maintenance_principal_id=v_maintenance
    and work.id=(p_request->>'workItemId')::uuid and work.work_kind='RETENTION_DELETE'
    and work.work_phase='FINAL_DELETE' and work.state='LEASED'
    and work.claim_generation=(p_request->>'claimGeneration')::bigint
    and work.claim_token_hash=v_token
    and work.credential_generation=(p_principal->>'credentialGeneration')::bigint
    and work.maintenance_lease_generation=(p_principal->>'leaseGeneration')::bigint
    and work.fencing_token=(p_principal->>'fencingToken')::bigint
    and work.lease_expires_at>v_issued and lease.expires_at>v_issued
  for update of work;
  if not found then raise exception 'retention delete authorization binding CAS failed' using errcode='40001'; end if;
  perform app_private.openclaw_lock_retention_tombstone_v1(v_org,v_work.source_id);
  select tombstone.* into v_tomb from public.openclaw_retention_tombstones tombstone
  where tombstone.organization_id=v_org and tombstone.id=v_work.source_id
    and tombstone.id=v_ticket.tombstone_id
    and tombstone.subject_kind='MEDIA'
    and tombstone.subject_id=(v_work.payload->>'subjectId')::uuid
    and tombstone.quarantine_version=(v_work.payload->>'quarantineVersion')::bigint
    and tombstone.final_delete_not_before<=v_issued
    and tombstone.object_key is not null;
  if not found then raise exception 'final_delete_not_before or tombstone CAS failed' using errcode='40001'; end if;
  perform scope.id from public.openclaw_retention_hold_scopes scope
  where scope.organization_id=v_org and (scope.scope_kind='ORGANIZATION'
    or (scope.scope_kind='MEDIA' and scope.scope_id=v_tomb.subject_id))
  order by scope.scope_kind,scope.scope_id,scope.id for share;
  if app_private.openclaw_retention_subject_held_v1(v_org,'MEDIA',v_tomb.subject_id) then
    raise exception 'active descendant legal hold blocks retention delete' using errcode='42501';
  end if;
  select coalesce(clock.hold_version,0) into v_hold_version
  from (select 1) singleton left join public.openclaw_retention_hold_clocks clock
    on clock.organization_id=v_org;
  if v_hold_version<>v_ticket.hold_version then
    raise exception 'hold_version changed before retention authorization' using errcode='40001';
  end if;
  perform app_private.openclaw_lock_retention_gateway_config_v1(v_org);
  select config.ticket_key_generation,config.signing_key_generation,config.public_key_hash
    into v_ticket_signing,v_receipt_signing,v_gateway_key_hash
  from public.openclaw_retention_gateway_configs config
  where config.organization_id=v_org and config.is_active and config.retired_at is null;
  if not found or v_ticket_signing<>v_ticket.signing_key_generation then
    raise exception 'active retention gateway signing generation mismatch' using errcode='42501';
  end if;
  v_expires:=least(v_issued+interval '5 seconds',v_work.lease_expires_at);
  if v_expires<=v_issued then
    raise exception 'retention authorization lease expired' using errcode='40001';
  end if;
  v_claims := jsonb_build_object('version',1,'receiptKind','RETENTION_FINAL_DELETE',
    'organizationId',v_org,'maintenancePrincipalId',v_maintenance,'workItemId',v_work.id,
    'claimGeneration',v_work.claim_generation,'credentialGeneration',v_work.credential_generation,
    'leaseGeneration',v_work.maintenance_lease_generation,'fencingToken',v_work.fencing_token,
    'objectKey',v_tomb.object_key,'deletePhase','FINAL_DELETE','holdVersion',v_hold_version,
    'quarantineVersion',v_tomb.quarantine_version,'deleteTicketJti',v_ticket.ticket_jti,
    'deleteAuthorizationJti',v_ticket.delete_authorization_jti,
    'proofJti',v_ticket.delete_authorization_jti,
    'gatewaySigningKeyGeneration',v_receipt_signing);
  v_payload := jsonb_build_object('version',1,'authorizationKind','RETENTION_FINAL_DELETE',
    'organizationId',v_org,'maintenancePrincipalId',v_maintenance,'workItemId',v_work.id,
    'claimGeneration',v_work.claim_generation,'credentialGeneration',v_work.credential_generation,
    'leaseGeneration',v_work.maintenance_lease_generation,'fencingToken',v_work.fencing_token,
    'objectKey',v_tomb.object_key,'deletePhase','FINAL_DELETE','holdVersion',v_hold_version,
    'quarantineVersion',v_tomb.quarantine_version,'deleteTicketJti',v_ticket.ticket_jti,
    'authorizationJti',v_ticket.delete_authorization_jti,
    'iat',to_char(v_issued at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'exp',to_char(v_expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'gatewaySigningKeyGeneration',v_ticket_signing);
  v_bytes := app_private.openclaw_jcs_bytes_v1(v_payload);
  v_authorization_hash := encode(extensions.digest(
    convert_to('ihome-openclaw-retention-authorization-v1','UTF8')||decode('00','hex')
      ||v_bytes,'sha256'),'hex');
  update public.openclaw_retention_delete_tickets ticket
  set state='DELETE_AUTHORIZED',authorization_payload=v_payload,authorization_bytes=v_bytes,
    authorization_hash=v_authorization_hash,expected_receipt_claims=v_claims,
    receipt_signing_key_generation=v_receipt_signing,authorized_at=v_issued,
    authorization_expires_at=v_expires
  where ticket.organization_id=v_org and ticket.id=v_ticket.id and ticket.state='TICKET_ISSUED';
  if not found then raise exception 'DELETE_AUTHORIZED ticket transition CAS failed' using errcode='40001'; end if;
  insert into public.openclaw_retention_delete_ticket_lineage(
    organization_id,logical_ticket_id,maintenance_principal_id,work_item_id,tombstone_id,
    subject_id,object_key,sha256,content_type,content_length,ticket_jti,
    delete_authorization_jti,claim_generation,credential_generation,
    maintenance_lease_generation,fencing_token,authorization_claim_token_hash,
    authorization_maintenance_principal_id,authorization_credential_generation,
    authorization_lease_generation,authorization_fencing_token,recovery_generation,
    hold_version,quarantine_version,ticket_signing_key_generation,
    receipt_signing_key_generation,gateway_public_key_hash,domain_hash,ticket_payload,
    ticket_bytes,ticket_hash,expected_receipt_claims,authorization_payload,
    authorization_bytes,authorization_hash,issued_at,expires_at,authorized_at,
    authorization_expires_at
  ) values (
    v_org,v_ticket.id,v_ticket.maintenance_principal_id,v_ticket.work_item_id,
    v_ticket.tombstone_id,v_ticket.subject_id,v_ticket.object_key,
    v_ticket.ticket_payload->>'sha256',v_ticket.ticket_payload->>'contentType',
    (v_ticket.ticket_payload->>'contentLength')::bigint,v_ticket.ticket_jti,
    v_ticket.delete_authorization_jti,v_ticket.claim_generation,v_ticket.credential_generation,
    v_ticket.maintenance_lease_generation,v_ticket.fencing_token,v_token,v_maintenance,
    (p_principal->>'credentialGeneration')::bigint,(p_principal->>'leaseGeneration')::bigint,
    (p_principal->>'fencingToken')::bigint,1,v_ticket.hold_version,
    v_ticket.quarantine_version,v_ticket.signing_key_generation,v_receipt_signing,
    v_gateway_key_hash,v_ticket.domain_hash,v_ticket.ticket_payload,v_ticket.ticket_bytes,
    v_ticket.ticket_hash,v_claims,v_payload,v_bytes,v_authorization_hash,
    v_ticket.issued_at,v_ticket.expires_at,v_issued,v_expires
  );
  update public.openclaw_maintenance_work_items work set state='DELETE_AUTHORIZED',
    claim_token_hash=null,lease_expires_at=null,retry_not_before=null,
    recovery_maintenance_principal_id=work.maintenance_principal_id,
    recovery_credential_generation=work.credential_generation,
    recovery_lease_generation=work.maintenance_lease_generation,
    recovery_fencing_token=work.fencing_token,recovery_generation=1,
    recovery_lease_expires_at=v_expires,updated_at=statement_timestamp()
  where work.organization_id=v_org and work.id=v_work.id and work.state='LEASED'
    and work.claim_generation=v_work.claim_generation;
  if not found then raise exception 'DELETE_AUTHORIZED work transition CAS failed' using errcode='40001'; end if;
  return jsonb_build_object('version',1,'ticketId',v_ticket.id,'authorization',v_payload,
    'ticketHash',v_ticket.ticket_hash,'deleteAuthorizationJti',v_ticket.delete_authorization_jti,
    'expiresAt',v_expires,'state','DELETE_AUTHORIZED');
end;
$_$;








--
-- Name: openclaw_authorized_org_ids_v1(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_authorized_org_ids_v1(p_permission_key text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select candidate.organization_id
  from pg_catalog.unnest(public.my_org_ids()) as candidate(organization_id)
  cross join lateral app_private.authorized_scope_v3(
    p_permission_key,
    candidate.organization_id
  ) as scope
  where scope.org_wide
$$;








--
-- Name: openclaw_begin_cell_rebind_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_begin_cell_rebind_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid:=(p_principal->>'organizationId')::uuid;
  v_account uuid:=(p_principal->>'accountId')::uuid;
  v_old uuid:=(p_request->>'oldCellId')::uuid; v_new uuid:=(p_request->>'newCellId')::uuid;
  v_old_lease public.openclaw_runtime_leases%rowtype;
  v_new_lease public.openclaw_runtime_leases%rowtype;
  v_generation bigint; v_command uuid:=gen_random_uuid(); v_rebind uuid:=gen_random_uuid();
  v_payload jsonb; v_bytes bytea;
begin
  select lease.* into strict v_old_lease from public.openclaw_runtime_leases lease
  where lease.organization_id=v_org and lease.account_id=v_account and lease.cell_id=v_old
  order by lease.lease_generation desc limit 1 for update;
  select lease.* into strict v_new_lease from public.openclaw_runtime_leases lease
  where lease.organization_id=v_org and lease.account_id=v_account and lease.cell_id=v_new
    and lease.status='ACTIVE' and lease.expires_at>statement_timestamp() for update;
  select coalesce(max(rebind.rebind_generation),0)+1 into v_generation
  from public.openclaw_cell_rebinds rebind where rebind.organization_id=v_org and rebind.account_id=v_account;
  v_payload:=jsonb_build_object('version',1,'oldCellId',v_old,'newCellId',v_new,
    'rebindGeneration',v_generation); v_bytes:=app_private.openclaw_jcs_bytes_v1(v_payload);
  insert into public.openclaw_runtime_commands(id,organization_id,account_id,cell_id,
    command_key,command_kind,source_session_generation,target_session_generation,
    source_connection_generation,target_connection_generation,
    expected_session_generation,expected_connection_generation,
    expected_fencing_token,payload,payload_bytes,payload_hash)
  select v_command,v_org,v_account,v_new,'rebind:'||v_generation::text,'CELL_REBIND',
    account.session_generation,account.session_generation,
    account.connection_generation,account.connection_generation,
    account.session_generation,account.connection_generation,v_new_lease.fencing_token,
    v_payload,v_bytes,encode(extensions.digest(v_bytes,'sha256'),'hex')
  from public.openclaw_accounts account where account.organization_id=v_org and account.id=v_account;
  insert into public.openclaw_cell_rebinds(id,organization_id,account_id,old_cell_id,new_cell_id,
    runtime_command_id,rebind_generation,expected_session_generation,old_lease_generation,
    old_fencing_token,new_lease_generation,new_fencing_token)
  select v_rebind,v_org,v_account,v_old,v_new,v_command,v_generation,account.session_generation,
    v_old_lease.lease_generation,v_old_lease.fencing_token,
    v_new_lease.lease_generation,v_new_lease.fencing_token
  from public.openclaw_accounts account where account.organization_id=v_org and account.id=v_account;
  return jsonb_build_object('version',1,'rebindId',v_rebind,'runtimeCommandId',v_command,
    'rebindGeneration',v_generation,'status','PREPARED');
end;
$$;








--
-- Name: openclaw_begin_client_operation_v1(uuid, uuid, text, uuid, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_begin_client_operation_v1(p_organization_id uuid, p_actor_id uuid, p_operation_key text, p_client_operation_id uuid, p_request jsonb, p_replay_policy text DEFAULT 'RETURN_SAFE_RESULT'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_hash text;
  v_row public.openclaw_client_operations%rowtype;
  v_inserted boolean := false;
  v_row_count bigint := 0;
begin
  if p_actor_id is null or p_actor_id is distinct from (select app_private.openclaw_actor_id_v1()) then
    raise exception 'authenticated actor mismatch' using errcode = '42501';
  end if;
  v_request_hash := app_private.openclaw_client_request_hash_v1(p_operation_key, p_request);
  insert into public.openclaw_client_operations (
    organization_id, actor_id, operation_key, client_operation_id,
    request_hash, replay_policy
  ) values (
    p_organization_id, p_actor_id, p_operation_key, p_client_operation_id,
    v_request_hash, p_replay_policy
  )
  on conflict (organization_id, actor_id, operation_key, client_operation_id)
  do nothing;
  get diagnostics v_row_count = row_count;
  v_inserted := v_row_count = 1;

  select operation_row.* into strict v_row
  from public.openclaw_client_operations operation_row
  where operation_row.organization_id = p_organization_id
    and operation_row.actor_id = p_actor_id
    and operation_row.operation_key = p_operation_key
    and operation_row.client_operation_id = p_client_operation_id
  for update;

  if v_row.request_hash is distinct from v_request_hash then
    return jsonb_build_object(
      'version', 1, 'conflict', true,
      'reason', 'client operation id reused with a different request'
    );
  end if;
  if v_row.completed_at is not null then
    if v_row.replay_policy = 'SINGLE_USE' then
      return jsonb_build_object('version', 1, 'conflict', true, 'reason', 'single-use operation replayed');
    end if;
    return jsonb_build_object(
      'version', 1, 'conflict', false, 'isReplay', true,
      'requestHash', v_request_hash, 'safeResult', v_row.safe_result
    );
  end if;
  return jsonb_build_object(
    'version', 1, 'conflict', false, 'isReplay', false,
    'requestHash', v_request_hash, 'inserted', v_inserted
  );
end;
$$;








--
-- Name: openclaw_begin_rollout_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_begin_rollout_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid := (p_principal ->> 'organizationId')::uuid;
  v_id uuid;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','reviewedCommitSha','migrationManifestSha256','upstreamSri','upstreamGitHead',
      'patchSeriesSha256','builtTgzSha256','artifactDigests','projectRef'],
    array['version','reviewedCommitSha','migrationManifestSha256','upstreamSri','upstreamGitHead',
      'patchSeriesSha256','builtTgzSha256','artifactDigests','projectRef']
  );
  if p_request ->> 'version' <> '1' then raise exception 'rollout version mismatch' using errcode='22023'; end if;
  insert into public.openclaw_rollout_runs(
    organization_id,reviewed_commit_sha,migration_manifest_sha256,upstream_sri,
    upstream_git_head,patch_series_sha256,built_tgz_sha256,artifact_digests,
    project_ref,stage,stage_version,stage_entered_at,status
  ) values (
    v_org,p_request ->> 'reviewedCommitSha',p_request ->> 'migrationManifestSha256',
    p_request ->> 'upstreamSri',p_request ->> 'upstreamGitHead',
    p_request ->> 'patchSeriesSha256',p_request ->> 'builtTgzSha256',
    p_request -> 'artifactDigests',p_request ->> 'projectRef','FOUNDATION',1,
    statement_timestamp(),'RUNNING'
  ) returning id into v_id;
  return jsonb_build_object('version',1,'rolloutRunId',v_id,'stage','FOUNDATION','stageVersion',1);
end;
$$;








--
-- Name: openclaw_begin_smoke_run_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_begin_smoke_run_v1(p_principal jsonb, p_envelope jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid := (p_principal ->> 'organizationId')::uuid;
  v_run public.openclaw_rollout_runs%rowtype;
  v_scope jsonb := p_request -> 'commandScope';
  v_scope_hash text;
  v_lineage_hash text;
  v_id uuid;
begin
  if p_request ->> 'version' <> '1' or jsonb_typeof(v_scope) <> 'object' then
    raise exception 'smoke run version or command scope invalid' using errcode='22023';
  end if;
  select run.* into v_run from public.openclaw_rollout_runs run
  where run.organization_id=v_org and run.id=(p_request ->> 'rolloutRunId')::uuid
    and run.stage_version=(p_request ->> 'expectedStageVersion')::bigint
    and run.status='RUNNING' for update;
  if not found then raise exception 'smoke rollout identity CAS failed' using errcode='40001'; end if;
  v_scope_hash := encode(extensions.digest(app_private.openclaw_jcs_bytes_v1(v_scope),'sha256'),'hex');
  v_lineage_hash := encode(extensions.digest(convert_to('ihome-openclaw-smoke-lineage-v1','UTF8')
    || decode('00','hex') || app_private.openclaw_jcs_bytes_v1(jsonb_build_object(
      'projectRef',v_run.project_ref,'reviewedCommitSha',v_run.reviewed_commit_sha,
      'rolloutRunId',v_run.id,'rolloutStage',v_run.stage,
      'rolloutStageVersion',v_run.stage_version,'commandScopeHash',v_scope_hash
    )),'sha256'),'hex');
  insert into public.openclaw_smoke_runs(
    organization_id,rollout_run_id,command_scope,command_scope_hash,status,started_at,
    project_ref,reviewed_commit_sha,rollout_stage,rollout_stage_version,lineage_hash
  ) values (
    v_org,v_run.id,v_scope,v_scope_hash,'RUNNING',statement_timestamp(),v_run.project_ref,
    v_run.reviewed_commit_sha,v_run.stage,v_run.stage_version,v_lineage_hash
  ) returning id into v_id;
  return jsonb_build_object('version',1,'smokeRunId',v_id,'lineageHash',v_lineage_hash,
    'commandScopeHash',v_scope_hash,'rolloutStage',v_run.stage,'rolloutStageVersion',v_run.stage_version);
end;
$$;








--
-- Name: openclaw_bind_sales_task_organization_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_bind_sales_task_organization_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_organization_id uuid;
  v_building_id uuid;
  v_actor_id uuid := (select app_private.openclaw_actor_id_v1());
  v_permission_key text := case when TG_OP = 'INSERT' then 'leads.create' else 'leads.edit' end;
  v_allowed boolean;
  v_jwt_role text := pg_catalog.current_setting('request.jwt.claim.role',true);
  v_jwt_claims text := pg_catalog.current_setting('request.jwt.claims',true);
  v_effective_role text;
  v_is_trusted boolean;
begin
  v_effective_role := coalesce(
    nullif(v_jwt_role,''),
    nullif(v_jwt_claims,'')::jsonb ->> 'role',
    ''
  );
  v_is_trusted := v_effective_role = 'service_role'
    or (
      v_effective_role = ''
      and session_user in ('postgres','supabase_admin')
    );
  select lead.organization_id,lead.building_id into v_organization_id,v_building_id
  from public.leads lead
  where lead.id = NEW.lead_id
  for share of lead;
  if not found or v_organization_id is null then
    raise exception 'sales task parent lead organization is unavailable' using errcode = '23503';
  end if;
  if not v_is_trusted then
    if v_actor_id is null then
      raise exception 'sales task organization binding requires a trusted caller'
        using errcode = '42501';
    end if;
    perform app_private.lock_org_for_decision_v1(v_organization_id);
    if v_building_id is not null then
      select decision.allowed into v_allowed
      from app_private.authorize_tenant_action_v3(
        v_actor_id,v_organization_id,v_permission_key,v_building_id,null
      ) decision;
    else
      select coalesce(scope.org_wide,false)
          or coalesce(cardinality(scope.building_ids),0) > 0
      into v_allowed
      from app_private.authorized_scope_v3(v_permission_key,v_organization_id) scope;
    end if;
    if not coalesce(v_allowed,false) then
      raise exception 'sales task parent lead is outside the caller''s authorized scope'
        using errcode = '42501';
    end if;
  end if;
  if NEW.organization_id is null then
    NEW.organization_id := v_organization_id;
  elsif NEW.organization_id is distinct from v_organization_id then
    raise exception 'sales task organization does not match parent lead' using errcode = '42501';
  end if;
  return NEW;
end;
$$;








--
-- Name: openclaw_browser_account_context_v1(jsonb, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_browser_account_context_v1(p_request jsonb, p_permission_key text, p_action_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_context jsonb;
  v_org uuid;
  v_account uuid;
begin
  v_context := app_private.openclaw_browser_context_v1(
    p_request, p_permission_key, p_action_label
  );
  v_org := (v_context ->> 'organizationId')::uuid;
  v_account := (p_request ->> 'accountId')::uuid;
  if not exists (
    select 1
    from public.openclaw_accounts account
    where account.organization_id = v_org
      and account.id = v_account
  ) then
    raise exception 'selected OpenClaw account is unavailable' using errcode = 'P0002';
  end if;
  return v_context || jsonb_build_object('accountId', v_account);
end;
$$;








--
-- Name: openclaw_browser_context_v1(jsonb, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_browser_context_v1(p_request jsonb, p_permission_key text, p_action_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := (select app_private.openclaw_actor_id_v1());
  v_org uuid;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_request ->> 'version' <> '1' then
    raise exception 'request version mismatch' using errcode = '22023';
  end if;
  v_org := (p_request ->> 'organizationId')::uuid;
  perform app_private.lock_org_for_decision_v1(v_org);
  perform app_private.require_perm_v1(v_org, p_permission_key, p_action_label);
  return jsonb_build_object('actorId', v_actor, 'organizationId', v_org);
end;
$$;








--
-- Name: openclaw_bump_lead_assignment_revision_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.openclaw_bump_lead_assignment_revision_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if TG_OP = 'INSERT' then
    if NEW.openclaw_assignment_revision is distinct from 1 then
      raise exception 'openclaw_assignment_revision must start at 1' using errcode = '42501';
    end if;
    return NEW;
  end if;
  if OLD.assigned_staff_id is distinct from NEW.assigned_staff_id then
    NEW.openclaw_assignment_revision := OLD.openclaw_assignment_revision + 1;
  elsif NEW.openclaw_assignment_revision is distinct from OLD.openclaw_assignment_revision then
    raise exception 'openclaw_assignment_revision is system-managed' using errcode = '42501';
  end if;
  return NEW;
end;
$$;








--
