--
-- Name: rebind_openclaw_unclaimed_work_v1(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.rebind_openclaw_unclaimed_work_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := statement_timestamp();
  v_send integer := 0;
  v_maintenance integer := 0;
begin
  with current_binding as (
    select distinct on (account.organization_id,account.id)
      account.organization_id,account.id account_id,account.session_generation,
      cell.id cell_id,credential.credential_generation,
      lease.lease_generation runtime_lease_generation,lease.fencing_token
    from public.openclaw_accounts account
    join public.openclaw_runtime_cells cell
      on cell.organization_id=account.organization_id and cell.account_id=account.id
     and cell.is_current and cell.state='READY'
    join public.openclaw_runtime_credentials credential
      on credential.organization_id=cell.organization_id and credential.account_id=cell.account_id
     and credential.cell_id=cell.id and credential.revoked_at is null
    join public.openclaw_runtime_leases lease
      on lease.organization_id=cell.organization_id and lease.account_id=cell.account_id
     and lease.cell_id=cell.id and lease.status='ACTIVE' and lease.expires_at>v_now
    where account.is_active
    order by account.organization_id,account.id,lease.lease_generation desc,
      credential.credential_generation desc
  ), candidates as (
    select work.id,binding.*
    from public.openclaw_send_work_items work
    join current_binding binding
      on binding.organization_id=work.organization_id and binding.account_id=work.account_id
    where work.state = 'QUEUED' and work.claim_token_hash is null
      and work.lease_expires_at is null and work.terminal_at is null
      and work.claim_generation>0
      and row(work.cell_id,work.credential_generation,work.runtime_lease_generation,
        work.fencing_token,work.session_generation)
        is distinct from row(binding.cell_id,binding.credential_generation,
          binding.runtime_lease_generation,binding.fencing_token,binding.session_generation)
    order by work.created_at,work.id
    for update of work skip locked
    limit greatest(1,least(coalesce(p_limit,100),500))
  )
  update public.openclaw_send_work_items work set
    cell_id=candidate.cell_id,credential_generation=candidate.credential_generation,
    runtime_lease_generation=candidate.runtime_lease_generation,
    fencing_token=candidate.fencing_token,session_generation=candidate.session_generation,
    claim_generation=work.claim_generation+1,binding_defer_reason=null,
    updated_at=v_now
  from candidates candidate
  where work.id=candidate.id and work.organization_id=candidate.organization_id
    and work.state='QUEUED' and work.claim_token_hash is null
    and work.lease_expires_at is null and work.terminal_at is null;
  get diagnostics v_send=row_count;

  with current_binding as (
    select distinct on (principal.organization_id)
      principal.organization_id,principal.id maintenance_principal_id,
      credential.credential_generation,lease.lease_generation,lease.fencing_token
    from public.openclaw_maintenance_principals principal
    join public.openclaw_maintenance_credentials credential
      on credential.organization_id=principal.organization_id
     and credential.maintenance_principal_id=principal.id and credential.revoked_at is null
    join public.openclaw_maintenance_leases lease
      on lease.organization_id=principal.organization_id
     and lease.maintenance_principal_id=principal.id
     and lease.status='ACTIVE' and lease.expires_at>v_now
    where principal.is_current and principal.revoked_at is null
    order by principal.organization_id,lease.lease_generation desc,
      credential.credential_generation desc
  ), candidates as (
    select work.id,binding.*
    from public.openclaw_maintenance_work_items work
    join current_binding binding on binding.organization_id=work.organization_id
    where work.state='QUEUED' and work.claim_token_hash is null
      and work.lease_expires_at is null and work.terminal_at is null
      and work.claim_generation>0
      and row(work.maintenance_principal_id,work.credential_generation,
        work.maintenance_lease_generation,work.fencing_token)
        is distinct from row(binding.maintenance_principal_id,binding.credential_generation,
          binding.lease_generation,binding.fencing_token)
    order by work.created_at,work.id
    for update of work skip locked
    limit greatest(1,least(coalesce(p_limit,100),500))
  )
  update public.openclaw_maintenance_work_items work set
    maintenance_principal_id=candidate.maintenance_principal_id,
    credential_generation=candidate.credential_generation,
    maintenance_lease_generation=candidate.lease_generation,
    fencing_token=candidate.fencing_token,claim_generation=work.claim_generation+1,
    binding_defer_reason=null,updated_at=v_now
  from candidates candidate
  where work.id=candidate.id and work.organization_id=candidate.organization_id
    and work.state='QUEUED' and work.claim_token_hash is null
    and work.lease_expires_at is null and work.terminal_at is null;
  get diagnostics v_maintenance=row_count;
  return v_send+v_maintenance;
end;
$$;








--
-- Name: register_system_evidence_v2(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.register_system_evidence_v2(p_org uuid, p_source_kind text, p_collection_id uuid, p_tender_id uuid, p_payment_id uuid, p_source_snapshot_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_bucket text := 'system-reference';
  v_object text;
  v_evidence uuid;
BEGIN
  IF p_source_kind NOT IN ('INVOICE_COLLECTION_V5','CONTRACT_V2','UTILITY','OTHER_ALLOWLISTED') THEN
    RAISE EXCEPTION 'register_system_evidence_v2: source_kind % not allow-listed', p_source_kind USING ERRCODE = '22023';
  END IF;

  -- Deterministic per-tender identity (plan §480: one SYSTEM_REFERENCE evidence per V5 tender).
  IF p_source_kind = 'INVOICE_COLLECTION_V5' THEN
    IF p_collection_id IS NULL OR p_tender_id IS NULL THEN
      RAISE EXCEPTION 'register_system_evidence_v2: collection_id + tender_id required for INVOICE_COLLECTION_V5' USING ERRCODE = '22023';
    END IF;
    -- Idempotent replay: return the existing evidence for this tender if already registered.
    SELECT s.evidence_id INTO v_evidence
    FROM public.finance_evidence_system_sources s
    WHERE s.organization_id = p_org AND s.source_kind = 'INVOICE_COLLECTION_V5'
      AND s.collection_id = p_collection_id AND s.tender_id = p_tender_id
    FOR UPDATE;
    IF v_evidence IS NOT NULL THEN
      RETURN v_evidence;
    END IF;
  END IF;

  v_object := p_source_kind || ':' || COALESCE(p_collection_id::text, '-') || ':'
              || COALESCE(p_tender_id::text, p_payment_id::text, '-');

  -- FINALIZED SYSTEM_REFERENCE object; NO raw URL from client. Reuse a stale identity idempotently.
  INSERT INTO public.finance_evidence_objects (
    id, organization_id, bucket_id, object_name, provenance_kind, state, sha256, finalized_at, created_at
  ) VALUES (
    gen_random_uuid(), p_org, v_bucket, v_object, 'SYSTEM_REFERENCE', 'FINALIZED', p_source_snapshot_hash, now(), now()
  )
  ON CONFLICT (organization_id, bucket_id, object_name) DO UPDATE
    SET state = 'FINALIZED', finalized_at = COALESCE(public.finance_evidence_objects.finalized_at, now())
  RETURNING id INTO v_evidence;

  INSERT INTO public.finance_evidence_system_sources (
    id, evidence_id, organization_id, source_kind, collection_id, tender_id, payment_id, source_snapshot_hash, created_at
  ) VALUES (
    gen_random_uuid(), v_evidence, p_org, p_source_kind, p_collection_id, p_tender_id, p_payment_id, p_source_snapshot_hash, now()
  )
  ON CONFLICT DO NOTHING;

  RETURN v_evidence;
END
$$;








--
-- Name: FUNCTION register_system_evidence_v2(p_org uuid, p_source_kind text, p_collection_id uuid, p_tender_id uuid, p_payment_id uuid, p_source_snapshot_hash text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.register_system_evidence_v2(p_org uuid, p_source_kind text, p_collection_id uuid, p_tender_id uuid, p_payment_id uuid, p_source_snapshot_hash text) IS 'Plan §6.3/§474/§480: FINALIZED SYSTEM_REFERENCE evidence from a typed source (no raw URL); deterministic per V5 tender.';








--
-- Name: register_termination_forfeit_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.register_termination_forfeit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_offset_id uuid;
  v_offset_count integer;
  v_writer boolean;
BEGIN
  IF NEW.system_source IS DISTINCT FROM 'termination.forfeit_revenue' THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_writer;
  IF NOT v_writer THEN
    RAISE EXCEPTION 'Forfeit authorization requires the trusted termination writer'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.type <> 'INCOME'
     OR NEW.approval_status <> 'UNAPPROVED'
     OR NEW.invoice_id IS NULL
     OR NEW.contract_id IS NULL
     OR NEW.account_id IS NULL
     OR NEW.building_id IS NULL
     OR NEW.room_id IS NULL
     OR NEW.total_amount <= 0
     OR NEW.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Hình dạng phiếu doanh thu bỏ cọc không hợp lệ'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*), (array_agg(offset_voucher.id ORDER BY offset_voucher.id))[1]
    INTO v_offset_count, v_offset_id
  FROM public.income_expenses offset_voucher
  WHERE offset_voucher.organization_id = NEW.organization_id
    AND offset_voucher.user_id = NEW.user_id
    AND offset_voucher.contract_id = NEW.contract_id
    AND offset_voucher.building_id = NEW.building_id
    AND offset_voucher.room_id = NEW.room_id
    AND offset_voucher.system_source = 'termination.forfeit_offset'
    AND offset_voucher.type = 'EXPENSE'
    AND offset_voucher.invoice_id IS NULL
    AND offset_voucher.account_id = NEW.account_id
    AND offset_voucher.voucher_date = NEW.voucher_date
    AND offset_voucher.total_amount = NEW.total_amount
    AND offset_voucher.approval_status = 'UNAPPROVED'
    AND offset_voucher.deleted_at IS NULL;
  IF v_offset_count <> 1 THEN
    RAISE EXCEPTION 'Không xác định duy nhất phiếu đối ứng bỏ cọc'
      USING ERRCODE = '55000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.invoices invoice
    JOIN public.contracts contract_row
      ON contract_row.id = NEW.contract_id
     AND contract_row.organization_id = NEW.organization_id
     AND contract_row.user_id = NEW.user_id
     AND contract_row.room_id = NEW.room_id
     AND contract_row.deleted_at IS NULL
    JOIN public.rooms room_row
      ON room_row.id = NEW.room_id
     AND room_row.building_id = NEW.building_id
     AND room_row.deleted_at IS NULL
    JOIN public.accounts account_row ON account_row.id = NEW.account_id
    WHERE invoice.id = NEW.invoice_id
      AND invoice.organization_id = NEW.organization_id
      AND invoice.user_id = NEW.user_id
      AND invoice.contract_id = NEW.contract_id
      AND invoice.building_id = NEW.building_id
      AND invoice.room_id = NEW.room_id
      AND invoice.kind = 'SETTLEMENT'
      AND invoice.deleted_at IS NULL
      AND invoice.total_amount = NEW.total_amount
      AND account_row.organization_id = NEW.organization_id
      AND account_row.deleted_at IS NULL
      AND account_row.is_virtual
  ) THEN
    RAISE EXCEPTION 'Invoice hoặc sổ nội bộ của bỏ cọc không hợp lệ'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO app_private.termination_forfeit_authorizations (
    revenue_voucher_id, offset_voucher_id, organization_id, contract_id,
    invoice_id, account_id, amount, voucher_date, authorization_source
  ) VALUES (
    NEW.id, v_offset_id, NEW.organization_id, NEW.contract_id,
    NEW.invoice_id, NEW.account_id, NEW.total_amount, NEW.voucher_date,
    'TERMINATION_WRITER'
  );
  RETURN NULL;
END;
$$;








