--
-- Name: reject_openclaw_tenant_identity_update_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reject_openclaw_tenant_identity_update_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old jsonb := to_jsonb(OLD);
  v_new jsonb := to_jsonb(NEW);
begin
  if OLD.organization_id is distinct from NEW.organization_id then
    raise exception 'organization_id cannot change' using errcode = '23514';
  end if;
  if v_old ? 'account_id' and v_old -> 'account_id' is distinct from v_new -> 'account_id' then
    raise exception 'account_id cannot change' using errcode = '23514';
  end if;
  if v_old ? 'cell_id' and v_old -> 'cell_id' is distinct from v_new -> 'cell_id' then
    raise exception 'cell_id cannot change' using errcode = '23514';
  end if;
  if v_old ? 'maintenance_principal_id'
     and v_old -> 'maintenance_principal_id' is distinct from v_new -> 'maintenance_principal_id'
  then
    raise exception 'maintenance_principal_id cannot change' using errcode = '23514';
  end if;
  return NEW;
end
$$;








--
-- Name: reject_openclaw_unknown_state_rewrite_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reject_openclaw_unknown_state_rewrite_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if row(NEW.id,NEW.organization_id,NEW.account_id,NEW.target_id,NEW.source_kind,
    NEW.actor_id,NEW.client_operation_id,NEW.inbound_event_id,NEW.automation_version_id,
    NEW.schedule_id,NEW.schedule_version,NEW.subscription_id,NEW.subscription_version,
    NEW.occurrence_id,NEW.campaign_id,NEW.campaign_version,NEW.idempotency_key,
    NEW.canonical_payload,NEW.canonical_payload_bytes,NEW.payload_hash,NEW.created_at)
    is distinct from row(OLD.id,OLD.organization_id,OLD.account_id,OLD.target_id,OLD.source_kind,
    OLD.actor_id,OLD.client_operation_id,OLD.inbound_event_id,OLD.automation_version_id,
    OLD.schedule_id,OLD.schedule_version,OLD.subscription_id,OLD.subscription_version,
    OLD.occurrence_id,OLD.campaign_id,OLD.campaign_version,OLD.idempotency_key,
    OLD.canonical_payload,OLD.canonical_payload_bytes,OLD.payload_hash,OLD.created_at)
  then raise exception 'outbox intent and canonical payload cannot change' using errcode='55000'; end if;
  if OLD.state in ('SENT','FAILED','UNKNOWN','DEAD_LETTER') and NEW.state<>OLD.state then
    raise exception 'terminal outbox state cannot be rewritten' using errcode='55000';
  end if;
  if NEW.state is distinct from OLD.state and not (
    (OLD.state='QUEUED' and NEW.state in ('LEASED','FAILED','DEAD_LETTER'))
    or (OLD.state='LEASED' and NEW.state in ('QUEUED','DISPATCHING','UNKNOWN','FAILED','DEAD_LETTER'))
    or (OLD.state='DISPATCHING' and NEW.state in ('SENT','FAILED','UNKNOWN','DEAD_LETTER'))
  ) then raise exception 'invalid outbox state transition' using errcode='55000'; end if;
  if OLD.state='UNKNOWN'
    and (to_jsonb(NEW)-array['resolution_version','updated_at']::text[])
      is distinct from
        (to_jsonb(OLD)-array['resolution_version','updated_at']::text[]) then
    raise exception 'historical UNKNOWN evidence cannot be rewritten' using errcode='55000';
  end if;
  if OLD.state='UNKNOWN' and NEW.updated_at is distinct from OLD.updated_at
    and not (
      OLD.state='UNKNOWN' and NEW.state='UNKNOWN'
      and OLD.resolution_version=0 and NEW.resolution_version=1
    ) then
    raise exception 'UNKNOWN timestamp may change only with the resolution CAS'
      using errcode='55000';
  end if;
  if NEW.resolution_version is distinct from OLD.resolution_version and not (
    OLD.state='UNKNOWN' and NEW.state='UNKNOWN'
    and OLD.resolution_version=0 and NEW.resolution_version=1
  ) then raise exception 'invalid UNKNOWN resolution transition' using errcode='55000'; end if;
  return NEW;
end;
$$;








--
-- Name: require_perm_v1(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.require_perm_v1(p_org uuid, p_permission_key text, p_viec text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare v_ok boolean;
begin
  if (select auth.uid()) is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  perform app_private.lock_org_for_decision_v1(p_org);
  select a.allowed into v_ok
    from app_private.authorize_tenant_action_v3(
      (select auth.uid()), p_org, p_permission_key, null, null) a;
  if not coalesce(v_ok, false) then
    raise exception 'Bạn không có quyền %.', p_viec using errcode = '42501';
  end if;
end
$$;








--
-- Name: termination_forfeit_authorizations; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.termination_forfeit_authorizations (
    revenue_voucher_id uuid NOT NULL,
    offset_voucher_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    payment_id uuid,
    account_id uuid NOT NULL,
    amount numeric(15,2) NOT NULL,
    voucher_date date NOT NULL,
    authorization_source text NOT NULL,
    authorized_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT termination_forfeit_authorizations_amount_check CHECK (((amount <> 'NaN'::numeric) AND (amount > (0)::numeric))),
    CONSTRAINT termination_forfeit_authorizations_authorization_source_check CHECK ((authorization_source = ANY (ARRAY['BACKFILL_REVIEWED'::text, 'TERMINATION_WRITER'::text])))
);








--
-- Name: require_termination_forfeit_authorization_v1(uuid, boolean, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.require_termination_forfeit_authorization_v1(p_voucher_id uuid, p_require_approved boolean, p_allow_frozen_cancelled boolean) RETURNS app_private.termination_forfeit_authorizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_authorization app_private.termination_forfeit_authorizations%ROWTYPE;
BEGIN
  SELECT auth_row.*
    INTO v_authorization
  FROM app_private.termination_forfeit_authorizations auth_row
  WHERE auth_row.revenue_voucher_id = p_voucher_id
     OR auth_row.offset_voucher_id = p_voucher_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Missing immutable authorization for termination forfeit voucher'
      USING ERRCODE = '55000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.income_expenses revenue
    JOIN public.income_expenses offset_voucher
      ON offset_voucher.id = v_authorization.offset_voucher_id
    JOIN public.invoices invoice
      ON invoice.id = v_authorization.invoice_id
    JOIN public.contracts contract_row
      ON contract_row.id = v_authorization.contract_id
    JOIN public.rooms room_row
      ON room_row.id = contract_row.room_id
    JOIN public.accounts account_row
      ON account_row.id = v_authorization.account_id
    JOIN LATERAL (
      SELECT
        count(*)::integer AS item_count,
        count(*) FILTER (
          WHERE item.accounting_class IS DISTINCT FROM 'PNL'
             OR item.organization_id IS DISTINCT FROM v_authorization.organization_id
        )::integer AS invalid_count,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
          AS item_total
      FROM public.income_expense_items item
      WHERE item.income_expense_id = revenue.id
    ) revenue_items ON true
    JOIN LATERAL (
      SELECT
        count(*)::integer AS item_count,
        count(*) FILTER (
          WHERE item.accounting_class IS DISTINCT FROM 'DEPOSIT'
             OR item.organization_id IS DISTINCT FROM v_authorization.organization_id
        )::integer AS invalid_count,
        COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
          AS item_total
      FROM public.income_expense_items item
      WHERE item.income_expense_id = offset_voucher.id
    ) offset_items ON true
    WHERE revenue.id = v_authorization.revenue_voucher_id
      AND revenue.organization_id = v_authorization.organization_id
      AND revenue.user_id = contract_row.user_id
      AND revenue.type = 'INCOME'
      AND revenue.system_source = 'termination.forfeit_revenue'
      AND revenue.contract_id = v_authorization.contract_id
      AND revenue.building_id = room_row.building_id
      AND revenue.room_id = contract_row.room_id
      AND revenue.invoice_id = v_authorization.invoice_id
      AND revenue.account_id = v_authorization.account_id
      AND revenue.total_amount = v_authorization.amount
      AND revenue.voucher_date = v_authorization.voucher_date
      AND revenue.payment_id IS NULL
      AND revenue.payment_collection_id IS NULL
      AND revenue.reversal_of_income_expense_id IS NULL
      AND COALESCE(revenue.change_amount, 0) = 0
      AND revenue.change_account_id IS NULL
      AND COALESCE(revenue.rounding_amount, 0) = 0
      AND revenue.rounding_account_id IS NULL
      AND revenue.deleted_at IS NULL
      AND revenue.approval_status IN ('UNAPPROVED', 'APPROVED', 'CANCELLED')
      AND offset_voucher.organization_id = v_authorization.organization_id
      AND offset_voucher.user_id = contract_row.user_id
      AND offset_voucher.type = 'EXPENSE'
      AND offset_voucher.system_source = 'termination.forfeit_offset'
      AND offset_voucher.contract_id = v_authorization.contract_id
      AND offset_voucher.building_id = room_row.building_id
      AND offset_voucher.room_id = contract_row.room_id
      AND offset_voucher.invoice_id IS NULL
      AND offset_voucher.account_id = v_authorization.account_id
      AND offset_voucher.total_amount = v_authorization.amount
      AND offset_voucher.voucher_date = v_authorization.voucher_date
      AND offset_voucher.payment_id IS NULL
      AND offset_voucher.payment_collection_id IS NULL
      AND offset_voucher.reversal_of_income_expense_id IS NULL
      AND COALESCE(offset_voucher.change_amount, 0) = 0
      AND offset_voucher.change_account_id IS NULL
      AND COALESCE(offset_voucher.rounding_amount, 0) = 0
      AND offset_voucher.rounding_account_id IS NULL
      AND offset_voucher.deleted_at IS NULL
      AND offset_voucher.approval_status IN ('UNAPPROVED', 'APPROVED', 'CANCELLED')
      AND invoice.organization_id = v_authorization.organization_id
      AND invoice.user_id = contract_row.user_id
      AND invoice.contract_id = v_authorization.contract_id
      AND invoice.building_id = room_row.building_id
      AND invoice.room_id = contract_row.room_id
      AND invoice.kind = 'SETTLEMENT'
      AND invoice.total_amount = v_authorization.amount
      AND (
        invoice.deleted_at IS NULL
        OR (
          p_allow_frozen_cancelled
          AND revenue.approval_status = 'CANCELLED'
          AND offset_voucher.approval_status = 'CANCELLED'
        )
      )
      AND contract_row.organization_id = v_authorization.organization_id
      AND (
        contract_row.deleted_at IS NULL
        OR (
          p_allow_frozen_cancelled
          AND revenue.approval_status = 'CANCELLED'
          AND offset_voucher.approval_status = 'CANCELLED'
        )
      )
      AND (
        room_row.deleted_at IS NULL
        OR (
          p_allow_frozen_cancelled
          AND revenue.approval_status = 'CANCELLED'
          AND offset_voucher.approval_status = 'CANCELLED'
        )
      )
      AND account_row.organization_id = v_authorization.organization_id
      AND (
        account_row.deleted_at IS NULL
        OR (
          p_allow_frozen_cancelled
          AND revenue.approval_status = 'CANCELLED'
          AND offset_voucher.approval_status = 'CANCELLED'
        )
      )
      AND account_row.is_virtual
      AND revenue_items.item_count > 0
      AND revenue_items.invalid_count = 0
      AND revenue_items.item_total = v_authorization.amount
      AND offset_items.item_count > 0
      AND offset_items.invalid_count = 0
      AND offset_items.item_total = v_authorization.amount
      AND COALESCE(revenue.kqkd_amount, 0) = v_authorization.amount
      AND COALESCE(offset_voucher.kqkd_amount, 0) = 0
      AND (
        NOT p_require_approved
        OR (
          revenue.approval_status = 'APPROVED'
          AND offset_voucher.approval_status = 'APPROVED'
        )
      )
  ) THEN
    RAISE EXCEPTION 'Termination forfeit authorization no longer matches its exact accounting pair'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_authorization;
END;
$$;








--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    receipt_number text,
    amount numeric(15,2) NOT NULL,
    payment_method public.payment_method DEFAULT 'TM'::public.payment_method NOT NULL,
    payment_date date DEFAULT CURRENT_DATE NOT NULL,
    notes text,
    receipt_image_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid NOT NULL,
    collection_id uuid,
    tender_id uuid,
    received_amount numeric(15,2),
    credit_amount numeric(15,2) DEFAULT 0 NOT NULL,
    change_amount numeric(15,2) DEFAULT 0 NOT NULL,
    rounding_amount numeric(15,2) DEFAULT 0 NOT NULL,
    reversed_at timestamp with time zone,
    reversed_by_collection_id uuid,
    CONSTRAINT payments_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT payments_v5_amounts_check CHECK ((((received_amount IS NULL) OR ((received_amount <> 'NaN'::numeric) AND (received_amount >= (0)::numeric))) AND (credit_amount <> 'NaN'::numeric) AND (credit_amount >= (0)::numeric) AND (change_amount <> 'NaN'::numeric) AND (change_amount >= (0)::numeric) AND (rounding_amount <> 'NaN'::numeric) AND (rounding_amount >= (0)::numeric)))
);








