-- Name: TABLE payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payments IS 'Payment records for invoices';








--
-- Name: COLUMN payments.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.user_id IS 'Audit-only: auth.uid() đã tạo row. RBAC dùng building qua invoice_id.';








--
-- Name: require_termination_forfeit_payment_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.require_termination_forfeit_payment_v1(p_revenue_voucher_id uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_payment public.payments%ROWTYPE;
BEGIN
  SELECT payment.*
    INTO v_payment
  FROM app_private.termination_forfeit_authorizations auth_row
  JOIN public.income_expenses revenue
    ON revenue.id = auth_row.revenue_voucher_id
  JOIN public.payments payment
    ON payment.id = auth_row.payment_id
  WHERE auth_row.revenue_voucher_id = p_revenue_voucher_id
    AND payment.organization_id = auth_row.organization_id
    AND payment.user_id = revenue.user_id
    AND payment.invoice_id = auth_row.invoice_id
    AND payment.amount = auth_row.amount
    AND payment.payment_method = 'CT'::public.payment_method
    AND payment.payment_date = auth_row.voucher_date
    AND payment.notes = '[CẤN CỌC BỎ CỌC PAYMENT '
      || auth_row.revenue_voucher_id::text || ']'
    AND payment.received_amount = 0
    AND payment.credit_amount = 0
    AND payment.change_amount = 0
    AND payment.rounding_amount = 0
    AND payment.collection_id IS NULL
    AND payment.tender_id IS NULL
    AND payment.reversed_at IS NULL
    AND payment.reversed_by_collection_id IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM app_private.payment_reversals reversal
      WHERE reversal.original_payment_id = payment.id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.payments other_payment
      WHERE other_payment.invoice_id = auth_row.invoice_id
        AND other_payment.id <> payment.id
        AND other_payment.reversed_at IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM app_private.payment_reversals other_reversal
          WHERE other_reversal.original_payment_id = other_payment.id
        )
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Authorized forfeit payment is missing, duplicated, or has drifted'
      USING ERRCODE = '55000';
  END IF;
  RETURN v_payment;
END;
$$;








--
-- Name: reserve_invoice_refund_obligation_v2(uuid, uuid, uuid, numeric, text, text, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reserve_invoice_refund_obligation_v2(p_org uuid, p_invoice_id uuid, p_building_id uuid, p_amount numeric, p_refund_class text, p_system_source text, p_actor_user uuid, p_actor_membership uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_inv public.invoices;
  v_refundable numeric(18,2);
  v_live numeric(18,2);
  v_voucher uuid := gen_random_uuid();
  v_birth_op uuid := gen_random_uuid();
  v_hash text := md5(jsonb_build_object('i', p_invoice_id, 'a', p_amount, 'c', p_refund_class, 'k', p_idempotency_key)::text);
  v_counts boolean;
  v_kqkd numeric(18,2);
  v_existing app_private.invoice_refund_reservations;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'reserve_invoice_refund_obligation_v2: amount must be positive' USING ERRCODE = '22023';
  END IF;
  IF p_refund_class NOT IN ('DEPOSIT','CUSTOMER_CREDIT','REFUND_CONTRA_REVENUE') THEN
    RAISE EXCEPTION 'reserve_invoice_refund_obligation_v2: invalid refund_class %', p_refund_class USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'reserve_invoice_refund_obligation_v2: idempotency key required' USING ERRCODE = '22023';
  END IF;

  -- Idempotent replay.
  SELECT * INTO v_existing FROM app_private.invoice_refund_reservations r
   WHERE r.organization_id = p_org AND r.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('reservationId', v_existing.id, 'refundVoucherId', v_existing.refund_voucher_id,
                              'reservationState', v_existing.reservation_state, 'stateVersion', v_existing.state_version,
                              'replayed', true);
  END IF;

  -- Lock the invoice + refundable cap (paid_amount less already-live reservations).
  SELECT * INTO v_inv FROM public.invoices i WHERE i.id = p_invoice_id AND i.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reserve_invoice_refund_obligation_v2: invoice % not found', p_invoice_id USING ERRCODE = 'P0002';
  END IF;
  v_refundable := COALESCE(v_inv.paid_amount, 0);

  SELECT COALESCE(sum(r.amount), 0) INTO v_live
  FROM app_private.invoice_refund_reservations r
  WHERE r.organization_id = p_org AND r.invoice_id = p_invoice_id
    AND r.reservation_state IN ('HELD','CONSUMED');

  IF v_live + p_amount > v_refundable THEN
    RAISE EXCEPTION 'reserve_invoice_refund_obligation_v2: refund % exceeds refundable due (live % + new % > paid %)',
      p_amount, v_live, p_amount, v_refundable USING ERRCODE = '55000';
  END IF;

  -- Classification: DEPOSIT/CUSTOMER_CREDIT = no P&L; contra-revenue = negative P&L (blocks close while pending).
  IF p_refund_class = 'REFUND_CONTRA_REVENUE' THEN
    v_counts := true;  v_kqkd := -p_amount;
  ELSE
    v_counts := false; v_kqkd := 0;
  END IF;

  -- Birth ONE pending obligation voucher (UNAPPROVED + UNPOSTED, no cashbook/posting/evidence at source).
  INSERT INTO public.income_expenses (
    id, user_id, type, name, building_id, invoice_id, voucher_date, total_amount,
    approval_status, organization_id, account_id, system_source,
    posting_mode, posting_status, review_state, review_version, approval_version, posting_version,
    maker_user_id, maker_membership_id, birth_operation_id, birth_txid, source_payload_hash,
    counts_in_business_result, kqkd_amount, recognition_date, recognition_source_mode, business_result_accounting
  ) VALUES (
    v_voucher, p_actor_user, 'EXPENSE', 'Hoàn tiền hóa đơn', p_building_id, p_invoice_id, public.org_today_v1(NULL), p_amount,
    'UNAPPROVED', p_org, NULL, COALESCE(p_system_source, 'invoice.refund'),
    'CASHBOOK', 'UNPOSTED', 'PENDING', 1, 1, 1,
    p_actor_user, p_actor_membership, v_birth_op, pg_current_xact_id(), v_hash,
    v_counts, v_kqkd, public.org_today_v1(NULL), 'BASE', v_counts
  );

  INSERT INTO app_private.income_expense_flow_ownership (
    income_expense_id, organization_id, flow_kind, flow_version, lifecycle_owner, lifecycle_state,
    writer_operation, payload_hash_scheme, payload_hash_value, maker_user_id, claimed_by_user_id, correlation_id
  ) VALUES (
    v_voucher, p_org, CASE WHEN COALESCE(p_system_source,'invoice.refund') = 'termination.refund'
                           THEN 'TERMINATION_REFUND' ELSE 'INVOICE_REFUND' END, 2,
    'INVOICE_REFUND', 'UNAPPROVED', 'invoice.refund.reserve.v2', 'PG_MD5_JSONB_TEXT_V1', v_hash, p_actor_user, p_actor_user,
    NULL /* 7ab: correlation uuid + hash scheme — idempotency TEXT đã unique ở invoice_refund_reservations (nhét vào cột uuid gây 42804); scheme 'md5' vi phạm CHECK chỉ nhận PG_MD5_JSONB_TEXT_V1 (23514) */
  );

  INSERT INTO app_private.invoice_refund_reservations (
    id, organization_id, invoice_id, refund_voucher_id, amount, refund_class, reservation_state,
    state_version, idempotency_key, source_payload_hash, created_by_user_id, created_at
  ) VALUES (
    gen_random_uuid(), p_org, p_invoice_id, v_voucher, p_amount, p_refund_class, 'HELD',
    1, p_idempotency_key, v_hash, p_actor_user, now()
  )
  RETURNING id INTO v_existing.id;

  RETURN jsonb_build_object('reservationId', v_existing.id, 'refundVoucherId', v_voucher,
                            'reservationState', 'HELD', 'stateVersion', 1, 'countsInBusinessResult', v_counts, 'replayed', false);
END
$$;








--
-- Name: FUNCTION reserve_invoice_refund_obligation_v2(p_org uuid, p_invoice_id uuid, p_building_id uuid, p_amount numeric, p_refund_class text, p_system_source text, p_actor_user uuid, p_actor_membership uuid, p_idempotency_key text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.reserve_invoice_refund_obligation_v2(p_org uuid, p_invoice_id uuid, p_building_id uuid, p_amount numeric, p_refund_class text, p_system_source text, p_actor_user uuid, p_actor_membership uuid, p_idempotency_key text) IS 'Plan §8.1: birth ONE pending INVOICE_REFUND_OBLIGATION (UNAPPROVED+UNPOSTED) + HELD reservation; concurrent pendings cannot exceed refundable due.';








--
-- Name: resolve_active_rule_set_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_active_rule_set_v1(p_organization_id uuid, p_transaction_domain text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_count int;
  v_id uuid;
begin
  select count(*) into v_count
    from public.approval_rule_sets
   where organization_id = p_organization_id
     and transaction_domain = p_transaction_domain
     and status = 'ACTIVE'
     and effective_from <= clock_timestamp()
     and (effective_to is null or effective_to > clock_timestamp());
  if v_count <> 1 then
    raise exception 'rule resolution not unique: % ACTIVE versions for %/%',
      v_count, p_organization_id, p_transaction_domain using errcode='55000';
  end if;
  select id into v_id
    from public.approval_rule_sets
   where organization_id = p_organization_id
     and transaction_domain = p_transaction_domain
     and status = 'ACTIVE'
     and effective_from <= clock_timestamp()
     and (effective_to is null or effective_to > clock_timestamp());
  return v_id;
end;
$$;








--
-- Name: resolve_approval_actor_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_approval_actor_v2() RETURNS TABLE(organization_id uuid, membership_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT m.organization_id, m.id
  FROM public.organization_memberships m
  WHERE m.user_id = auth.uid()
    AND m.status = 'ACTIVE';
$$;








--
-- Name: FUNCTION resolve_approval_actor_v2(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_approval_actor_v2() IS 'Thu Chi V2 §9.4 containment: resolve (org, membership) ACTIVE của actor cho compat approval RPCs. Internal-only.';








--
-- Name: resolve_business_result_v2(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_business_result_v2(p_voucher uuid) RETURNS TABLE(counts boolean, kqkd numeric, recognition_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_vdate date;
BEGIN
  SELECT ie.organization_id, ie.voucher_date INTO v_org, v_vdate
  FROM public.income_expenses ie
  WHERE ie.id = p_voucher;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'resolve_business_result_v2: voucher % not found', p_voucher
      USING ERRCODE = 'P0002';
  END IF;

  SELECT
    COALESCE(bool_or(it.accounting_class = 'PNL'), false),
    COALESCE(sum(it.amount) FILTER (WHERE it.accounting_class = 'PNL'), 0::numeric),
    v_vdate
  INTO counts, kqkd, recognition_date
  FROM public.income_expense_items it
  WHERE it.income_expense_id = p_voucher;

  recognition_date := v_vdate;
  RETURN NEXT;
END
$$;








--
-- Name: FUNCTION resolve_business_result_v2(p_voucher uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_business_result_v2(p_voucher uuid) IS 'Plan §7.1: server-owned KQKD contribution/amount/recognition_date from voucher items.';








--
-- Name: resolve_finance_actor_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_finance_actor_v2() RETURNS TABLE(user_id uuid, membership_id uuid, organization_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_org uuid;
  v_count integer;
BEGIN
  v_uid := app_private.current_uid_v1();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: authentication required'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(DISTINCT m.organization_id) INTO v_count
  FROM public.organization_memberships m
  WHERE m.user_id = v_uid
    AND m.status = 'ACTIVE'
    AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
    AND (m.valid_to IS NULL OR m.valid_to > now());

  IF v_count = 0 THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: no active membership for actor'
      USING ERRCODE = '42501';
  ELSIF v_count > 1 THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: ambiguous membership; org-scoped resolution required'
      USING ERRCODE = '42501';
  END IF;

  SELECT m.organization_id INTO v_org
  FROM public.organization_memberships m
  WHERE m.user_id = v_uid
    AND m.status = 'ACTIVE'
    AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
    AND (m.valid_to IS NULL OR m.valid_to > now())
  LIMIT 1;

  RETURN QUERY SELECT * FROM app_private.resolve_finance_actor_v2(v_org);
END
$$;








--
-- Name: FUNCTION resolve_finance_actor_v2(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_finance_actor_v2() IS 'Plan §7.1: resolve actor from auth.uid() when exactly one active membership exists.';








--
-- Name: resolve_finance_actor_v2(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_finance_actor_v2(p_organization_id uuid) RETURNS TABLE(user_id uuid, membership_id uuid, organization_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_mid uuid;
BEGIN
  v_uid := app_private.current_uid_v1();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: organization is required'
      USING ERRCODE = '22023';
  END IF;

  SELECT m.id INTO v_mid
  FROM public.organization_memberships m
  WHERE m.user_id = v_uid
    AND m.organization_id = p_organization_id
    AND m.status = 'ACTIVE'
    AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
    AND (m.valid_to IS NULL OR m.valid_to > now())
  ORDER BY m.valid_from DESC
  LIMIT 1;

  IF v_mid IS NULL THEN
    RAISE EXCEPTION 'resolve_finance_actor_v2: no active membership for actor in organization %', p_organization_id
      USING ERRCODE = '42501';
  END IF;

  user_id := v_uid;
  membership_id := v_mid;
  organization_id := p_organization_id;
  RETURN NEXT;
END
$$;








--
-- Name: FUNCTION resolve_finance_actor_v2(p_organization_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_finance_actor_v2(p_organization_id uuid) IS 'Plan §7.1: resolve actor user_id + active membership in a known org from auth.uid(). RAISE 42501 if none.';








--
-- Name: resolve_ie_type_org_for_user_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_ie_type_org_for_user_v1(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_organizations uuid[];
BEGIN
  -- profiles.organization_id is the current organization selected by the
  -- application. Historical buildings or type ownership must not make an
  -- otherwise current owner look ambiguously multi-organization.
  SELECT profile.organization_id
    INTO v_organization_id
  FROM public.profiles profile
  WHERE profile.id = p_user_id
    AND profile.organization_id IS NOT NULL;

  IF v_organization_id IS NOT NULL THEN
    RETURN v_organization_id;
  END IF;

  SELECT array_agg(DISTINCT membership.organization_id
                   ORDER BY membership.organization_id)
    INTO v_organizations
  FROM public.organization_memberships membership
  WHERE membership.user_id = p_user_id
    AND membership.status = 'ACTIVE';

  IF COALESCE(cardinality(v_organizations), 0) = 0 THEN
    RAISE EXCEPTION 'Cannot resolve a current organization for income/expense type owner %',
      p_user_id USING ERRCODE = '23514';
  END IF;
  IF cardinality(v_organizations) <> 1 THEN
    RAISE EXCEPTION 'Income/expense type owner % has multiple active organizations; an explicit organization is required',
      p_user_id USING ERRCODE = '23514';
  END IF;

  RETURN v_organizations[1];
END
$$;








--
-- Name: resolve_signed_contract_deposit_basis_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_signed_contract_deposit_basis_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH s AS (
    SELECT * FROM app_private.contract_deposit_sources_v1(p_organization_id, p_contract_id, p_as_of)
  ),
  agg AS (
    SELECT
      COALESCE(SUM(amount) FILTER (WHERE bucket='REAL_CASH' AND direction='IN'), 0)   AS real_in,
      COALESCE(SUM(amount) FILTER (WHERE bucket='REAL_CASH' AND direction='OUT'), 0)  AS real_out,
      COALESCE(SUM(CASE WHEN direction='IN' THEN amount ELSE -amount END)
               FILTER (WHERE bucket='RECOGNIZED_HISTORICAL'), 0)                      AS hist_in,
      count(*) FILTER (WHERE bucket='REAL_CASH')             AS n_real,
      count(*) FILTER (WHERE bucket='RECOGNIZED_HISTORICAL') AS n_hist,
      count(*) FILTER (WHERE bucket='EXCLUDED')              AS n_excl,
      count(*)                                                AS n_all
    FROM s
  )
  SELECT jsonb_build_object(
    'organizationId',          p_organization_id,
    'contractId',              p_contract_id,
    'asOf',                    p_as_of,
    'realPostedIn',            agg.real_in,
    'postedReleaseOut',        agg.real_out,
    'recognizedHistoricalIn',  agg.hist_in,
    -- netHeld CỐ Ý không cộng rổ ghi nhận: 243/287 phiếu cọc nằm trên sổ ảo, cộng
    -- vào là báo két có gần một tỉ không có thật.
    'netHeld',                 agg.real_in - agg.real_out,
    'counts', jsonb_build_object('realCash', agg.n_real, 'recognized', agg.n_hist,
                                 'excluded', agg.n_excl, 'total', agg.n_all),
    'basisStatus',
      CASE
        WHEN agg.n_all = 0                                 THEN 'NO_SOURCE'
        WHEN agg.real_in - agg.real_out < 0                THEN 'NEGATIVE_HELD'
        WHEN agg.n_real = 0 AND agg.n_hist > 0             THEN 'RECOGNIZED_ONLY'
        ELSE 'OK'
      END,
    'basisReason',
      CASE
        WHEN agg.n_all = 0
          THEN 'Hợp đồng không có phiếu cọc nào.'
        WHEN agg.real_in - agg.real_out < 0
          THEN 'Tiền cọc đã trả ra NHIỀU HƠN tiền đã thu thật — phải rà tay trước khi hoàn tiếp.'
        WHEN agg.n_real = 0 AND agg.n_hist > 0
          THEN 'Cọc chỉ được GHI NHẬN trên sổ ảo, chưa từng vào két thật. Hoàn tiền mặt sẽ là chi tiền chưa hề thu.'
        ELSE NULL
      END,
    -- Vân tay: đổi một dòng nguồn nào là đổi vân tay ⇒ submit phát hiện được
    -- rằng cơ sở đã trôi kể từ lúc preview.
    'fingerprint', (
      SELECT md5(COALESCE(string_agg(
        s.voucher_id::text || ':' || s.bucket || ':' || round(s.signed_amount)::text,
        '|' ORDER BY s.created_at, s.voucher_id), 'EMPTY'))
      FROM s),
    'sources', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'voucherId', s.voucher_id, 'code', s.code, 'direction', s.direction,
               'bucket', s.bucket, 'excludeReason', s.exclude_reason,
               'amount', s.amount, 'signedAmount', s.signed_amount,
               'isVirtual', s.is_virtual, 'systemSource', s.system_source,
               'voucherDate', s.voucher_date)
             ORDER BY s.created_at, s.voucher_id)
      FROM s), '[]'::jsonb)
  )
  FROM agg;
$$;








--
-- Name: FUNCTION resolve_signed_contract_deposit_basis_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_signed_contract_deposit_basis_v1(p_organization_id uuid, p_contract_id uuid, p_as_of timestamp with time zone) IS 'Đợt 1 Step 2c: MỘT nguồn sự thật cho "hợp đồng đang giữ bao nhiêu cọc". Broker và Plan 2 BẮT BUỘC reuse, không chép lại công thức. netHeld = realPostedIn − postedReleaseOut và CỐ Ý không cộng recognizedHistoricalIn — 243/287 phiếu cọc nằm trên SỔ ẢO (backfill 28/07, ~998tr) nên cộng vào là báo két có tiền không có thật. basisStatus cảnh báo NEGATIVE_HELD (trả ra nhiều hơn thu thật) và RECOGNIZED_ONLY (chưa từng vào két — hoàn tiền mặt là chi khoản chưa hề thu). fingerprint đổi khi bất kỳ dòng nguồn nào đổi, để submit biết cơ sở đã trôi kể từ preview. Lõi nội bộ: KHÔNG cấp cho client.';








--
-- Name: reverse_collection_tender_v2(uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reverse_collection_tender_v2(p_org uuid, p_collection_id uuid, p_tender_id uuid, p_reversal_date date, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_orig public.income_expense_postings;
  v_rev_id uuid;
  v_mid uuid;
BEGIN
  SELECT * INTO v_orig FROM public.income_expense_postings p
   WHERE p.organization_id = p_org AND p.external_source_kind = 'COLLECTION_V5'
     AND p.external_source_id = p_collection_id AND p.external_source_line_id = p_tender_id
     AND p.event_kind = 'POSTING'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reverse_collection_tender_v2: no original tender posting for collection %/tender %', p_collection_id, p_tender_id USING ERRCODE = 'P0002';
  END IF;

  SELECT p.id INTO v_rev_id FROM public.income_expense_postings p
   WHERE p.organization_id = p_org AND p.external_source_kind = 'COLLECTION_V5'
     AND p.external_source_id = p_collection_id AND p.external_source_line_id = p_tender_id
     AND p.event_kind = 'REVERSAL';
  IF v_rev_id IS NOT NULL THEN
    RETURN v_rev_id;
  END IF;

  SELECT om.id INTO v_mid FROM public.organization_memberships om
   WHERE om.organization_id = p_org AND om.status = 'ACTIVE'
   ORDER BY om.activated_at NULLS LAST, om.id LIMIT 1;

  v_rev_id := gen_random_uuid();
  INSERT INTO public.income_expense_postings (
    id, organization_id, voucher_id, posting_subject_kind, posting_subject_id,
    direction, account_id, gross_amount, voucher_amount_snapshot, amount_basis,
    net_cash_effect, posted_on, posted_by_membership_id, posted_by_user_id,
    approval_version, event_kind, idempotency_key, source_kind,
    external_source_kind, external_source_id, external_source_line_id, posting_generation,
    reversal_of_id, reversal_reason, created_at
  ) VALUES (
    v_rev_id, p_org, v_orig.voucher_id, v_orig.posting_subject_kind, v_orig.posting_subject_id,
    v_orig.direction, v_orig.account_id, v_orig.gross_amount, v_orig.voucher_amount_snapshot, 'EXTERNAL_TENDER_GROSS',
    -v_orig.net_cash_effect, COALESCE(p_reversal_date, v_orig.posted_on), COALESCE(v_mid, v_orig.posted_by_membership_id), v_orig.posted_by_user_id,
    v_orig.approval_version, 'REVERSAL', 'fin_v2:v5rev:' || p_collection_id::text || ':' || p_tender_id::text,
    'COLLECTION_V5_ADAPTER', 'COLLECTION_V5', p_collection_id, p_tender_id, v_orig.posting_generation,
    v_orig.id, COALESCE(p_reason, 'V5 collection reversal'), now()
  );
  INSERT INTO public.income_expense_posting_lines (id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at)
  VALUES (gen_random_uuid(), p_org, v_rev_id, v_orig.account_id, 'REVERSAL', -v_orig.net_cash_effect, now());

  IF v_orig.voucher_id IS NOT NULL THEN
    PERFORM app_private.finance_v2_stamp_owned_posting_state(v_orig.voucher_id, 'REVERSED', NULL, NULL, NULL, NULL);
  END IF;
  RETURN v_rev_id;
END
$$;








--
-- Name: FUNCTION reverse_collection_tender_v2(p_org uuid, p_collection_id uuid, p_tender_id uuid, p_reversal_date date, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.reverse_collection_tender_v2(p_org uuid, p_collection_id uuid, p_tender_id uuid, p_reversal_date date, p_reason text) IS 'Plan §7.1/§8: REVERSAL event linking the original tender posting (reversal_of_id); wraps reverse_invoice_collection_v5.';








--
-- Name: reverse_customer_credit_application_lifo_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reverse_customer_credit_application_lifo_v1(p_actor uuid, p_application_id uuid, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_contract_id uuid;
  v_org uuid;
  v_building_id uuid;
  v_owner uuid;
  v_authz boolean;
  v_route text;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_application public.customer_credit_applications%ROWTYPE;
  v_lot public.customer_credit_lots%ROWTYPE;
  v_latest_application_id uuid;
  v_ledger_balance numeric(15,2);
  v_new_remaining numeric(15,2);
  v_reversal_excess_id uuid;
  v_response jsonb;
BEGIN
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Invalid credit reversal actor' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'Credit reversal reason must contain 8-1000 characters'
      USING ERRCODE = '22023';
  END IF;

  SELECT lot.contract_id INTO v_contract_id
  FROM public.customer_credit_applications application_row
  JOIN public.customer_credit_lots lot ON lot.id = application_row.credit_lot_id
  WHERE application_row.id = p_application_id;

  IF v_contract_id IS NULL THEN
    RAISE EXCEPTION 'Customer credit application not found' USING ERRCODE = '42501';
  END IF;

  SELECT contract_row.organization_id, room_row.building_id, contract_row.user_id
    INTO v_org, v_building_id, v_owner
  FROM public.contracts contract_row
  JOIN public.rooms room_row
    ON room_row.id = contract_row.room_id AND room_row.deleted_at IS NULL
  JOIN public.buildings building_row
    ON building_row.id = room_row.building_id
   AND building_row.deleted_at IS NULL
   AND building_row.organization_id = contract_row.organization_id
  JOIN public.organizations organization_row
    ON organization_row.id = contract_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE contract_row.id = v_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE OF contract_row;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Contract is outside an active organization'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_application
  FROM public.customer_credit_applications application_row
  WHERE application_row.id = p_application_id
  FOR UPDATE;

  SELECT * INTO v_lot
  FROM public.customer_credit_lots lot
  WHERE lot.id = v_application.credit_lot_id
    AND lot.organization_id = v_org
    AND lot.contract_id = v_contract_id
  FOR UPDATE;

  IF v_lot.id IS NULL OR v_application.organization_id <> v_org THEN
    RAISE EXCEPTION 'Credit application tenant chain is invalid'
      USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    p_actor, v_org, 'excess_amounts.edit', v_building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Missing permission to reverse customer credit'
      USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'application_id', p_application_id,
    'reason', v_reason
  )::text);

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, 'customer.credit.reverse.v1', p_application_id::text,
    p_actor, v_key, v_hash
  ) ON CONFLICT (
    organization_id, operation, subject_scope, actor_id, idempotency_key
  ) DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'customer.credit.reverse.v1'
    AND operation_row.subject_scope = p_application_id::text
    AND operation_row.actor_id = p_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key was reused with a different payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  v_route := app_private.evaluate_feature_route('customer.credit.reverse.v1', v_org);
  IF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Customer credit writer is not enabled'
      USING ERRCODE = '55000';
  END IF;

  IF v_application.reversed_at IS NOT NULL THEN
    IF v_application.reversal_idempotency_key IS DISTINCT FROM v_key THEN
      RAISE EXCEPTION 'Customer credit application was already reversed'
        USING ERRCODE = '23505';
    END IF;

    v_response := jsonb_build_object(
      'application_id', v_application.id,
      'credit_lot_id', v_application.credit_lot_id,
      'reversal_excess_amount_id', v_application.reversal_excess_amount_id,
      'reversed_amount', v_application.amount,
      'remaining_amount', v_lot.remaining_amount,
      'noop', true
    );
    UPDATE app_private.canonical_write_operations
       SET subject_id = v_application.id,
           completed_at = clock_timestamp(),
           response_payload = v_response
     WHERE organization_id = v_org
       AND operation = 'customer.credit.reverse.v1'
       AND subject_scope = p_application_id::text
       AND actor_id = p_actor
       AND idempotency_key = v_key;
    RETURN v_response;
  END IF;

  SELECT application_row.id INTO v_latest_application_id
  FROM public.customer_credit_applications application_row
  JOIN public.customer_credit_lots lot
    ON lot.id = application_row.credit_lot_id
  WHERE lot.organization_id = v_org
    AND lot.contract_id = v_contract_id
    AND application_row.reversed_at IS NULL
  ORDER BY application_row.applied_at DESC, application_row.id DESC
  LIMIT 1
  FOR UPDATE OF application_row;

  IF v_latest_application_id IS DISTINCT FROM p_application_id THEN
    RAISE EXCEPTION 'Customer credit applications must be reversed in LIFO order'
      USING ERRCODE = '55000';
  END IF;
  IF v_lot.status = 'REVERSED'
     OR v_lot.remaining_amount + v_application.amount > v_lot.amount THEN
    RAISE EXCEPTION 'Credit lot cannot absorb the application reversal'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(sum(excess.amount), 0)::numeric(15,2)
    INTO v_ledger_balance
  FROM public.excess_amounts excess
  WHERE excess.organization_id = v_org
    AND excess.credit_lot_id = v_lot.id;
  IF abs(v_ledger_balance - v_lot.remaining_amount) >= 0.01 THEN
    RAISE EXCEPTION 'Credit lot balance does not match the compatibility ledger'
      USING ERRCODE = '55000';
  END IF;

  v_new_remaining := v_lot.remaining_amount + v_application.amount;
  PERFORM app_private.begin_accounting_chain_write_v1();

  INSERT INTO public.excess_amounts (
    organization_id, user_id, contract_id, amount, description,
    source_invoice_id, source_payment_id, credit_lot_id
  ) VALUES (
    v_org, v_owner, v_contract_id, v_application.amount,
    'Reverse customer credit: ' || v_reason,
    v_application.invoice_id, NULL, v_lot.id
  ) RETURNING id INTO v_reversal_excess_id;

  UPDATE public.customer_credit_applications
     SET reversed_at = clock_timestamp(),
         reversed_by = p_actor,
         reversal_excess_amount_id = v_reversal_excess_id,
         reversal_idempotency_key = v_key,
         reversal_reason = v_reason
   WHERE id = v_application.id;

  UPDATE public.customer_credit_lots
     SET remaining_amount = v_new_remaining,
         status = 'ACTIVE'
   WHERE id = v_lot.id;

  v_response := jsonb_build_object(
    'application_id', v_application.id,
    'credit_lot_id', v_lot.id,
    'reversal_excess_amount_id', v_reversal_excess_id,
    'reversed_amount', v_application.amount,
    'remaining_amount', v_new_remaining,
    'noop', false
  );

  UPDATE app_private.canonical_write_operations
     SET subject_id = v_application.id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'customer.credit.reverse.v1'
     AND subject_scope = p_application_id::text
     AND actor_id = p_actor
     AND idempotency_key = v_key;

  PERFORM app_private.end_accounting_chain_write_v1();
  RETURN v_response;
END;
$_$;








--
-- Name: reverse_financial_request_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reverse_financial_request_v1(p_original_request_id uuid, p_actor_membership uuid, p_actor_user uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_orig public.approval_requests;
  v_rev_id uuid;
  v_sub_no int;
begin
  select * into v_orig from public.approval_requests
   where id = p_original_request_id for update;
  if not found then raise exception 'original not found' using errcode='P0002'; end if;
  if v_orig.state <> 'POSTED' then
    raise exception 'only POSTED requests can be reversed' using errcode='55000';
  end if;
  if v_orig.reversed_by_request_id is not null then
    raise exception 'request already reversed' using errcode='55000';
  end if;

  v_sub_no := app_private.next_submission_no_v1(
    v_orig.organization_id, v_orig.subject_type, v_orig.subject_id);

  insert into public.approval_requests
    (organization_id, submission_no, subject_type, subject_id, state,
     maker_membership_id, maker_user_id, rule_set_id, rule_set_version,
     matched_rule_id, rule_effect, payload_snapshot, payload_hash,
     amount, category_id, cashbook_id, building_id, system_source,
     submitted_at, reverses_request_id)
  values
    (v_orig.organization_id, v_sub_no, v_orig.subject_type, v_orig.subject_id,
     'POSTED', p_actor_membership, p_actor_user, v_orig.rule_set_id,
     v_orig.rule_set_version, v_orig.matched_rule_id, 'REVERSAL',
     v_orig.payload_snapshot, v_orig.payload_hash,
     -coalesce(v_orig.amount, 0), v_orig.category_id, v_orig.cashbook_id,
     v_orig.building_id, 'reversal', clock_timestamp(), p_original_request_id)
  returning id into v_rev_id;

  update public.approval_requests
     set state = 'REVERSED', reversed_by_request_id = v_rev_id,
         version = version + 1
   where id = p_original_request_id;

  -- Reversal provenance is the reverses_request_id link + the (chained) audit
  -- event appended by the calling public wrapper; the decision table requires a
  -- step row, and a reversal has no approval step, so we do not write one here.
  -- The full T3 wrapper appends a REVERSAL audit event via the A.5 primitive.

  return v_rev_id;
end;
$$;








--
-- Name: reverse_invoice_customer_credit_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reverse_invoice_customer_credit_v1(p_actor uuid, p_invoice_id uuid, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_application record;
  v_child_key text;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_total numeric(15,2) := 0;
BEGIN
  FOR v_application IN
    SELECT application_row.id, application_row.amount
    FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = p_invoice_id
      AND application_row.reversed_at IS NULL
    ORDER BY application_row.applied_at DESC, application_row.id DESC
  LOOP
    v_child_key := left(p_idempotency_key, 150)
      || ':app:' || replace(v_application.id::text, '-', '');
    v_result := app_private.reverse_customer_credit_application_lifo_v1(
      p_actor, v_application.id, p_reason, v_child_key
    );
    v_total := v_total + v_application.amount;
    v_results := v_results || jsonb_build_array(v_result);
  END LOOP;

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'reversed_amount', v_total,
    'applications', v_results
  );
END;
$$;








--
-- Name: reverse_termination_move_out_pair_v2(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reverse_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_auth public.termination_move_out_authorizations;
BEGIN
  SELECT * INTO v_auth FROM public.termination_move_out_authorizations a
   WHERE a.id = p_authorization_id AND a.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reverse_termination_move_out_pair_v2: authorization % not found', p_authorization_id USING ERRCODE = 'P0002';
  END IF;
  IF v_auth.state <> 'APPROVED' THEN
    RAISE EXCEPTION 'reverse_termination_move_out_pair_v2: only an APPROVED move-out pair can be reversed (%)', v_auth.state USING ERRCODE = '55000';
  END IF;

  IF v_auth.revenue_voucher_id IS NOT NULL THEN
    PERFORM app_private.finance_v2_transition_owned_approval(v_auth.revenue_voucher_id, 'CANCELLED', 'NOT_APPLICABLE');
  END IF;
  IF v_auth.offset_voucher_id IS NOT NULL THEN
    PERFORM app_private.finance_v2_transition_owned_approval(v_auth.offset_voucher_id, 'CANCELLED', 'NOT_APPLICABLE');
  END IF;

  UPDATE public.termination_move_out_authorizations a SET state = 'REVERSED' WHERE a.id = p_authorization_id;
  RETURN jsonb_build_object('authorizationId', p_authorization_id, 'state', 'REVERSED');
END
$$;








--
-- Name: FUNCTION reverse_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.reverse_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_reason text) IS 'Plan §6.9: append-only reverse of one approved move-out pair; both legs CANCELLED, no cash posting created.';








--
-- Name: round_invoice_total_v1(numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.round_invoice_total_v1(p_total numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when p_total is null or p_total <= 0 then p_total
    when mod(p_total, 1000) = 0          then p_total
    when mod(p_total, 1000) >= 900       then ceil(p_total / 1000.0) * 1000
    else                                      floor(p_total / 1000.0) * 1000
  end;
$$;








--
-- Name: run_finance_month_snapshot_job_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.run_finance_month_snapshot_job_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_local_timestamp timestamp := v_now AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_local_date date := v_local_timestamp::date;
  v_current_month date := date_trunc('month', v_local_date)::date;
  v_previous_month date := (date_trunc('month', v_local_date) - interval '1 month')::date;
  v_previous_month_end date := (v_current_month - interval '1 day')::date;
  v_finalize boolean;
  v_organization record;
  v_run_id uuid;
  v_status text;
BEGIN
  v_finalize := v_local_date = (v_current_month + interval '1 month - 1 day')::date
    AND v_local_timestamp::time >= time '23:50:00';

  FOR v_organization IN
    SELECT organization_row.id
    FROM public.organizations organization_row
    WHERE organization_row.status = 'ACTIVE'
    ORDER BY organization_row.id
  LOOP
    BEGIN
      IF v_local_date <= (v_current_month + interval '2 days')::date THEN
        PERFORM pg_advisory_xact_lock(
          hashtextextended(v_organization.id::text || ':' || v_previous_month::text, 0)
        );

        SELECT run.id, run.status
          INTO v_run_id, v_status
        FROM public.finance_month_snapshot_runs run
        WHERE run.organization_id = v_organization.id
          AND run.snapshot_month = v_previous_month
        FOR UPDATE;

        IF v_run_id IS NULL THEN
          INSERT INTO public.finance_month_snapshot_runs (
            organization_id,
            snapshot_month,
            scheduled_for,
            status,
            capture_version,
            capture_source,
            late_reason
          ) VALUES (
            v_organization.id,
            v_previous_month,
            make_timestamptz(
              extract(year FROM v_previous_month_end)::integer,
              extract(month FROM v_previous_month_end)::integer,
              extract(day FROM v_previous_month_end)::integer,
              23,
              55,
              0,
              'Asia/Ho_Chi_Minh'
            ),
            'MISSED',
            1,
            'MONITOR',
            'Month-end cutoff was missed; mutable current data was not backfilled'
          );
        ELSIF v_status = 'PROVISIONAL' THEN
          DELETE FROM public.finance_contract_month_snapshots detail
          WHERE detail.snapshot_run_id = v_run_id;
          DELETE FROM public.finance_room_month_snapshots detail
          WHERE detail.snapshot_run_id = v_run_id;
          UPDATE public.finance_month_snapshot_runs run
          SET
            as_of_date = NULL,
            as_of_timestamp = NULL,
            captured_at = NULL,
            finalized_at = NULL,
            status = 'MISSED',
            room_count = NULL,
            contract_count = NULL,
            validation_summary = NULL,
            capture_source = 'MONITOR',
            late_reason = 'Month-end cutoff was missed; mutable current data was not backfilled',
            updated_at = clock_timestamp()
          WHERE run.id = v_run_id;
        END IF;
      END IF;

      PERFORM 1
      FROM app_private.capture_finance_month_snapshot_v1(
        v_organization.id,
        v_now,
        v_finalize
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Finance snapshot capture failed for organization %: %',
        v_organization.id, SQLERRM;
    END;
  END LOOP;
END;
$$;








--
-- Name: run_openclaw_maintenance_jobs_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.run_openclaw_maintenance_jobs_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lock bigint := pg_catalog.hashtextextended('ihome-openclaw-maintenance-runner-v1',0);
  v_result jsonb;
  v_retention_policies integer;
begin
  if not pg_catalog.pg_try_advisory_xact_lock(v_lock) then
    return jsonb_build_object('version',1,'acquired',false,'databaseTime',statement_timestamp());
  end if;
  v_retention_policies:=app_private.ensure_openclaw_retention_contract_v1();
  v_result := jsonb_build_object(
    'version',1,'acquired',true,
    'retentionPoliciesEnsured',v_retention_policies,
    'qrExpired',app_private.expire_openclaw_qr_challenges_v1(),
    'runtimeLeasesExpired',app_private.expire_openclaw_runtime_leases_v1(),
    'maintenanceLeasesExpired',app_private.expire_openclaw_maintenance_leases_v1(),
    'deliverySweep',app_private.sweep_openclaw_delivery_claims_v1(null,null,null),
    'workRebound',app_private.rebind_openclaw_unclaimed_work_v1(500),
    'salesTasksEmitted',app_private.openclaw_sweep_due_sales_tasks_v1(500),
    'scheduleWork',app_private.materialize_openclaw_schedule_work_v1(500),
    'crmWork',app_private.materialize_openclaw_crm_work_v1(500),
    'retentionQuarantine',app_private.materialize_openclaw_retention_quarantine_v1(500),
    'retentionFinalDelete',app_private.materialize_openclaw_retention_final_delete_v1(500),
    'evidenceRetention',app_private.enforce_openclaw_evidence_retention_v1(500),
    'auditRoots',app_private.materialize_openclaw_audit_root_v1(366),
    'databaseTime',statement_timestamp()
  );
  return v_result;
end;
$$;








--
-- Name: sale_bonus_cap_for_v1(uuid, uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sale_bonus_cap_for_v1(p_org uuid, p_building uuid, p_month date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT v.cap_amount
    FROM app_private.sale_bonus_cap_versions v
   WHERE v.organization_id = p_org
     AND v.status = 'PUBLISHED'
     AND v.effective_from_month <= date_trunc('month', p_month)::date
     AND (v.building_id = p_building OR v.building_id IS NULL)
   -- Trần riêng của toà thắng trần chung; cùng mức thì lấy bản mới nhất.
   ORDER BY (v.building_id IS NOT NULL) DESC, v.effective_from_month DESC
   LIMIT 1;
$$;








--
-- Name: scope_covers_v3(text, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.scope_covers_v3(p_scope_type text, p_scope_building uuid, p_scope_cashbook uuid, p_scope_area uuid, p_org uuid, p_target_building uuid, p_target_cashbook uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  select case p_scope_type
    when 'ORGANIZATION' then true
    when 'BUILDING'     then p_target_building is not null and p_scope_building = p_target_building
    when 'CASHBOOK'     then p_target_cashbook is not null and p_scope_cashbook = p_target_cashbook
    when 'AREA'         then p_target_building is not null and exists (
                              select 1 from public.area_buildings ab
                               where ab.organization_id = p_org
                                 and ab.area_id = p_scope_area
                                 and ab.building_id = p_target_building)
    else false end;
$$;








--
-- Name: scope_label_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.scope_label_v1(p_scope uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  select case s.scope_type
           when 'ORGANIZATION' then 'Toàn tổ chức'
           when 'AREA'         then 'Khu vực: ' || coalesce(a.name, '(đã xoá)')
           when 'BUILDING'     then 'Toà: '     || coalesce(b.name, '(đã xoá)')
           when 'CASHBOOK'     then 'Sổ quỹ: '  || coalesce(c.name, '(đã xoá)')
           else s.scope_type
         end
    from public.authorization_scopes s
    left join public.areas a     on a.id = s.area_id
    left join public.buildings b on b.id = s.building_id
    left join public.accounts c on c.id = s.cashbook_id
   where s.id = p_scope;
$$;








--
-- Name: self_approve_within_limit_v1(uuid, bigint, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.self_approve_within_limit_v1(p_request_id uuid, p_expected_version bigint, p_actor_membership uuid, p_actor_user uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_req public.approval_requests;
  v_limit numeric(15,2);
  v_posting uuid;
  v_holds boolean;
  v_is_force boolean;
  v_batch_total numeric(15,2);
  v_allowed boolean;
begin
  select * into v_req from public.approval_requests
   where id = p_request_id for update;
  if not found then raise exception 'request not found' using errcode='P0002'; end if;
  if v_req.version <> p_expected_version then
    raise exception 'version conflict' using errcode='40001'; end if;
  if v_req.state <> 'PENDING_APPROVAL' then
    raise exception 'not pending' using errcode='55000'; end if;

  -- must be the maker (this is a self-approval)
  if p_actor_membership <> v_req.maker_membership_id then
    raise exception 'self-approve requires maker' using errcode='42501';
  end if;

  -- H3 fix: force-approval class is derived from the SUBJECT'S item types
  -- (schema-owned is_deposit + commission/bonus names), NOT from a client-
  -- settable system_source. Force categories can never self-approve.
  select bool_or(coalesce(t.is_deposit,false)
                 or public.nrm_vn(t.name) in ('hoa hong moi gioi','thuong nong sale'))
    into v_is_force
    from public.income_expense_items i
    join public.income_expense_types t on t.id = i.income_expense_type_id
   where i.income_expense_id = v_req.subject_id;
  if coalesce(v_is_force,false) then
    raise exception 'force-approval class cannot self-approve' using errcode='42501';
  end if;

  -- M8 fix: exact permissions via the T2 resolver (self_approve_within_limit
  -- AND cashbooks.post), not just possession.
  perform app_private.lock_org_for_decision_v1(v_req.organization_id);
  select allowed into v_allowed from app_private.authorize_tenant_action_v3(
    p_actor_user, v_req.organization_id,
    'income_expenses.self_approve_within_limit', v_req.building_id, v_req.cashbook_id);
  if not coalesce(v_allowed,false) then
    raise exception 'actor lacks income_expenses.self_approve_within_limit' using errcode='42501';
  end if;
  select allowed into v_allowed from app_private.authorize_tenant_action_v3(
    p_actor_user, v_req.organization_id, 'cashbooks.post',
    v_req.building_id, v_req.cashbook_id);
  if not coalesce(v_allowed,false) then
    raise exception 'actor lacks cashbooks.post' using errcode='42501';
  end if;

  -- versioned limit (default 0 disables self-approval entirely)
  select max_single_amount_vnd into v_limit
    from app_private.self_approve_limits
   where organization_id = v_req.organization_id
   order by version desc limit 1;
  v_limit := coalesce(v_limit, 0);
  if v_limit = 0 then
    raise exception 'self-approve disabled (limit 0)' using errcode='42501';
  end if;
  -- H4 fix: anti-split. Sum this maker's OTHER self-approved-or-pending requests
  -- for the SAME subject (correlation) plus this one; the aggregate must be
  -- within the limit, so splitting one business event into N vouchers is caught.
  select coalesce(sum(r.amount),0) into v_batch_total
    from public.approval_requests r
   where r.organization_id = v_req.organization_id
     and r.subject_id = v_req.subject_id
     and r.maker_membership_id = v_req.maker_membership_id
     and r.state in ('PENDING_APPROVAL','POSTED')
     and r.id <> v_req.id;
  if coalesce(v_req.amount,0) + v_batch_total > v_limit then
    raise exception 'aggregate self-approve amount exceeds limit (% > %)',
      coalesce(v_req.amount,0) + v_batch_total, v_limit using errcode='42501';
  end if;

  -- must hold the cashbook the request posts to
  if v_req.cashbook_id is null then
    raise exception 'self-approve requires a held cashbook' using errcode='42501';
  end if;
  select exists (
    select 1 from public.cashbook_possession_bindings cp
     where cp.organization_id = v_req.organization_id
       and cp.cashbook_id = v_req.cashbook_id
       and cp.membership_id = p_actor_membership
       and cp.possession_kind in ('CUSTODIAN','OPERATOR')
       and cp.valid_from <= clock_timestamp()
       and (cp.valid_to is null or cp.valid_to > clock_timestamp())
  ) into v_holds;
  if not v_holds then
    raise exception 'maker does not hold the target cashbook' using errcode='42501';
  end if;

  declare v_step uuid;
  begin
    select id into v_step from public.approval_request_steps
     where request_id = p_request_id
     order by (status = 'PENDING') desc, step_no limit 1;
    insert into public.approval_decisions
      (organization_id, request_id, request_step_id, actor_membership_id,
       actor_user_id, decision, reason, request_version)
    values
      (v_req.organization_id, p_request_id, v_step, p_actor_membership,
       p_actor_user, 'SELF_APPROVED_WITHIN_LIMIT', 'within versioned limit',
       v_req.version);
  end;

  v_posting := app_private.post_financial_request_v1(
    p_request_id, v_req.version, p_actor_user);
  return v_posting;
end;
$$;








--
-- Name: set_feature_route_v1(text, bigint, text, timestamp with time zone, timestamp with time zone, integer, numeric, numeric, text, text, text, text, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_feature_route_v1(p_feature_key text, p_expected_config_version bigint, p_mode text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_max_operation_count integer, p_max_single_amount_vnd numeric, p_max_total_amount_vnd numeric, p_commit_sha text, p_migration_sha256 text, p_maintenance_window_id text, p_approval_reference text, p_actor uuid, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private'
    AS $_$
declare
  v_flag app_private.server_feature_flags;
  v_new_version bigint;
begin
  if p_mode not in ('OFF','SHADOW','CANARY','ON') then
    raise exception 'invalid mode %', p_mode using errcode='22023';
  end if;

  select * into v_flag from app_private.server_feature_flags
   where feature_key = p_feature_key for update;
  if not found then
    raise exception 'feature % not found', p_feature_key using errcode='P0002';
  end if;
  -- CAS: caller must present the current config_version
  if v_flag.config_version <> p_expected_config_version then
    raise exception 'config_version conflict (have %, expected %)',
      v_flag.config_version, p_expected_config_version using errcode='40001';
  end if;

  -- release identity required for any active (ON/CANARY) mode
  if p_mode in ('ON','CANARY') then
    if p_commit_sha !~ '^[0-9a-f]{40}$'
       or p_migration_sha256 !~ '^[0-9a-f]{64}$'
       or coalesce(btrim(p_maintenance_window_id), '') = ''
       or coalesce(btrim(p_approval_reference), '') = '' then
      raise exception 'ON/CANARY requires full release identity' using errcode='22023';
    end if;
  end if;
  -- CANARY requires a finite half-open window and positive caps
  if p_mode = 'CANARY' then
    if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
      raise exception 'CANARY requires a finite half-open window' using errcode='22023';
    end if;
    if coalesce(p_max_operation_count,0) <= 0
       or coalesce(p_max_single_amount_vnd,0) <= 0
       or coalesce(p_max_total_amount_vnd,0) <= 0 then
      raise exception 'CANARY requires positive caps' using errcode='22023';
    end if;
  end if;

  v_new_version := v_flag.config_version + 1;

  update app_private.server_feature_flags
     set mode = p_mode,
         config_version = v_new_version,
         starts_at = p_starts_at,
         ends_at = p_ends_at,
         max_operation_count = coalesce(p_max_operation_count, 0),
         max_single_amount_vnd = coalesce(p_max_single_amount_vnd, 0),
         max_total_amount_vnd = coalesce(p_max_total_amount_vnd, 0),
         commit_sha = p_commit_sha,
         migration_sha256 = p_migration_sha256,
         maintenance_window_id = p_maintenance_window_id,
         approval_reference = p_approval_reference,
         reason = p_reason,
         updated_by = p_actor,
         updated_at = clock_timestamp()
   where feature_key = p_feature_key
     and config_version = p_expected_config_version;

  insert into app_private.server_feature_flag_events
    (feature_key, event_type, before_mode, after_mode,
     before_version, after_version, detail, actor, created_at)
  values
    (p_feature_key, 'ROUTE_CHANGED', v_flag.mode, p_mode,
     v_flag.config_version, v_new_version,
     jsonb_build_object('reason', p_reason), p_actor, clock_timestamp());

  return v_new_version;
end;
$_$;








