--
-- Name: FUNCTION set_finance_feature_cohort_v2(p_expected_workflow_version bigint, p_expected_posting_version bigint, p_expected_cashbook_version bigint, p_mode text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_max_operation_count integer, p_max_single_amount_vnd numeric, p_max_total_amount_vnd numeric, p_commit_sha text, p_migration_sha256 text, p_maintenance_window_id text, p_approval_reference text, p_actor uuid, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.set_finance_feature_cohort_v2(p_expected_workflow_version bigint, p_expected_posting_version bigint, p_expected_cashbook_version bigint, p_mode text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_max_operation_count integer, p_max_single_amount_vnd numeric, p_max_total_amount_vnd numeric, p_commit_sha text, p_migration_sha256 text, p_maintenance_window_id text, p_approval_reference text, p_actor uuid, p_reason text) IS '§10.4 cohort CAS for the 3 read/write cohort keys — STUB (0A000) pending later stage.';








--
-- Name: single_org_of_user_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.single_org_of_user_v1(p_uid uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  -- HAVING count=1 → chỉ trả khi user thuộc ĐÚNG 1 org active; else 0 dòng (NULL)
  select (array_agg(distinct organization_id))[1]
    from public.organization_memberships
   where user_id = p_uid and status = 'ACTIVE'
  having count(distinct organization_id) = 1;
$$;








--
-- Name: special_fee_approve_and_post_v1(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.special_fee_approve_and_post_v1(p_voucher_id uuid, p_source_kind text DEFAULT 'SPECIAL_PAGE_FEE'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_ie       public.income_expenses;
  v_acc      public.accounts;
  v_posting  uuid;
  v_actor    uuid := auth.uid();
  v_reversed boolean;
  v_mid      uuid;
BEGIN
  SELECT * INTO v_ie FROM public.income_expenses WHERE id = p_voucher_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu %', p_voucher_id USING ERRCODE = 'P0002';
  END IF;
  IF v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Phiếu % đã huỷ — không ghi sổ', p_voucher_id USING ERRCODE = '55000';
  END IF;

  -- ══ CHỐT LOẠI PHIẾU — hàng rào quan trọng nhất của hàm này ═════════
  -- Hàm này DUYỆT HỘ NGƯỜI DÙNG. Nó tuyệt đối không được chạm vào loại phiếu
  -- mà chủ đã quyết là phải có người duyệt:
  --   • Chủ chốt 31/07: "riêng HOÀN CỌC vẫn chờ duyệt kể cả khi số khớp".
  --   • Phiếu THU (INCOME) không thuộc phạm vi trang đóng phí.
  -- Không có chốt này thì bất kỳ writer nào lỡ gọi nhầm cũng tự duyệt được một
  -- phiếu hoàn cọc — đúng thứ chủ cấm.
  IF v_ie.type IS DISTINCT FROM 'EXPENSE' THEN
    RAISE EXCEPTION
      'Chỉ tự duyệt được phiếu CHI. Phiếu % là loại %.', p_voucher_id, COALESCE(v_ie.type,'(rỗng)')
      USING ERRCODE = '42501';
  END IF;
  IF COALESCE(v_ie.system_source, '') NOT IN ('special_fee.v1', 'fixed_fee', 'utility.bill', 'contract.commission') THEN
    RAISE EXCEPTION
      'Phiếu % không thuộc nhóm phí cố định của trang đóng tiền (nguồn: %) — không tự duyệt.',
      p_voucher_id, COALESCE(v_ie.system_source, '(không rõ)')
      USING ERRCODE = '42501';
  END IF;

  -- ══ (2) REPLAY — phải kiểm bút toán còn SỐNG, không chỉ còn con trỏ ══
  -- Bẫy đã đo được: nếu bút toán cũ ĐÃ BỊ ĐẢO thì trả con trỏ cũ ra rồi đóng
  -- dấu POSTED lên nó = phiếu nói "đã chi" trong khi sổ quỹ nói "chưa" — tiền
  -- biến mất khỏi tồn quỹ mà giao diện vẫn xanh. Phải phân biệt ba trạng thái.
  IF v_ie.active_posting_id_v2 IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.income_expense_postings r
       WHERE r.reversal_of_id = v_ie.active_posting_id_v2 AND r.event_kind = 'REVERSAL'
    ) INTO v_reversed;
    IF v_reversed THEN
      RAISE EXCEPTION
        'Phiếu % đã có bút toán bị ĐẢO — muốn ghi sổ lại phải qua đường ghi sổ lại có kiểm soát, không gọi lại hàm tự duyệt.',
        COALESCE(v_ie.code, p_voucher_id::text)
        USING ERRCODE = '55000';
    END IF;
    RETURN v_ie.active_posting_id_v2;
  END IF;

  -- Bút toán tồn tại theo khoá nguồn nhưng phiếu MẤT con trỏ (a85 xoá con trỏ
  -- khi đảo). Không được ghi đè POSTED lên đó.
  SELECT p.id INTO v_posting
    FROM public.income_expense_postings p
   WHERE p.organization_id = v_ie.organization_id
     AND p.external_source_kind = 'SPECIAL_FEE_VOUCHER'
     AND p.external_source_id   = p_voucher_id
     AND p.event_kind = 'POSTING';
  IF v_posting IS NOT NULL THEN
    RAISE EXCEPTION
      'Phiếu % đã từng được ghi sổ (bút toán %) nhưng con trỏ đã bị gỡ — cần rà tay, không tự ghi lại.',
      COALESCE(v_ie.code, p_voucher_id::text), v_posting
      USING ERRCODE = '55000';
  END IF;

  IF v_ie.account_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu % chưa có sổ quỹ — không tự ghi sổ được', p_voucher_id
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_acc FROM public.accounts WHERE id = v_ie.account_id;
  IF NOT FOUND OR v_acc.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Sổ quỹ của phiếu % không còn hiệu lực', p_voucher_id USING ERRCODE = '22023';
  END IF;
  IF v_acc.organization_id IS DISTINCT FROM v_ie.organization_id THEN
    RAISE EXCEPTION 'Sổ quỹ khác tổ chức của phiếu %', p_voucher_id USING ERRCODE = '42501';
  END IF;

  -- (3) TẮT CẦU a85/a85b cho transaction này. Xem khối chú thích ở trên.
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher_id, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
  ON CONFLICT (income_expense_id) DO UPDATE
    SET xid = EXCLUDED.xid, purpose = EXCLUDED.purpose, granted_at = now();

  -- (4) Lật APPROVED nếu chưa. Trigger khoá kỳ sẽ tự lên tiếng ở đây.
  IF v_ie.approval_status IS DISTINCT FROM 'APPROVED' THEN
    UPDATE public.income_expenses
       SET approval_status = 'APPROVED',
           review_state    = 'RESOLVED',
           approved_by     = COALESCE(approved_by, v_actor, user_id),
           approved_at     = COALESCE(approved_at, now())
     WHERE id = p_voucher_id;
  END IF;

  -- ══ SỔ ẢO: DUYỆT NHƯNG KHÔNG GHI SỔ QUỸ ═══════════════════════════
  -- Sổ ảo (cấn cọc, cấn trừ) không có tiền ra khỏi két nên không có bút toán
  -- sổ quỹ. Bản nháp trước NÉM LỖI ở đây — sai, vì hôm nay đóng phí từ sổ ảo
  -- vẫn chạy được (cầu a85b tự bỏ qua sổ ảo và phiếu vẫn APPROVED). Ném lỗi là
  -- LẤY MẤT một năng lực đang có. Giữ đúng hành vi cũ: duyệt, không ghi sổ.
  IF COALESCE(v_acc.is_virtual, false) THEN
    UPDATE public.income_expenses
       SET posting_status = COALESCE(NULLIF(posting_status, 'UNPOSTED'), 'NOT_APPLICABLE'),
           updated_at = now()
     WHERE id = p_voucher_id;
    DELETE FROM app_private.ie_transition_authorization
     WHERE income_expense_id = p_voucher_id AND xid = pg_current_xact_id();
    RETURN NULL;
  END IF;

  -- Lõi đòi một membership để ghi "ai ghi sổ", và cột đó NOT NULL. Người tạo
  -- phiếu có thể đã rời tổ chức ⇒ lõi ném 23502 trần không ai hiểu. Chặn sớm
  -- bằng câu tiếng Việt.
  SELECT om.id INTO v_mid
    FROM public.organization_memberships om
   WHERE om.organization_id = v_ie.organization_id
     AND om.user_id = COALESCE(v_ie.approved_by, v_ie.user_id, v_actor)
     AND om.status = 'ACTIVE'
   LIMIT 1;
  IF v_mid IS NULL AND v_ie.maker_membership_id IS NULL THEN
    RAISE EXCEPTION
      'Không xác định được người ghi sổ cho phiếu % (người tạo không còn là thành viên đang hoạt động) — phiếu đã duyệt nhưng cần vào sổ tay.',
      COALESCE(v_ie.code, p_voucher_id::text)
      USING ERRCODE = '22023';
  END IF;

  -- (5) Lõi dùng chung. Khoá replay là chính phiếu này.
  v_posting := app_private.finance_v2_post_voucher_with_source_v1(
    p_org             => v_ie.organization_id,
    p_voucher_id      => p_voucher_id,
    p_source_kind     => p_source_kind,
    p_external_kind   => 'SPECIAL_FEE_VOUCHER',
    p_external_id     => p_voucher_id,
    p_external_line_id=> NULL,
    p_posted_on       => v_ie.voucher_date,
    p_amount_basis    => 'VOUCHER_TOTAL',
    p_generation      => 1
  );

  -- (6) Con trỏ posting. Token còn hiệu lực nên cầu vẫn im (và a85 không khai
  --     posting_status trong danh sách cột kích hoạt nên nó cũng không chạy).
  UPDATE public.income_expenses
     SET active_posting_id_v2 = v_posting,
         posting_id           = v_posting,
         posting_status       = 'POSTED',
         posting_mode         = COALESCE(posting_mode, 'CASHBOOK'),
         posted_at_v2         = now(),
         updated_at           = now()
   WHERE id = p_voucher_id;

  -- (7) TRẢ TOKEN. Mọi writer cùng họ đều dọn; để lại thì cầu a85 CÂM cho toàn
  --     bộ phần còn lại của transaction — một lệnh xoá/đổi tiền sau đó sẽ không
  --     sinh bút toán đảo, tiền kẹt lại trong sổ.
  DELETE FROM app_private.ie_transition_authorization
   WHERE income_expense_id = p_voucher_id AND xid = pg_current_xact_id();

  RETURN v_posting;
END;
$$;








--
-- Name: FUNCTION special_fee_approve_and_post_v1(p_voucher_id uuid, p_source_kind text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.special_fee_approve_and_post_v1(p_voucher_id uuid, p_source_kind text) IS 'Duyệt hộ + ghi sổ một phiếu phí cố định đã qua kiểm rule. Đặt token FINANCE_V2_LIFECYCLE để TẮT cầu a85/a85b — thiếu bước đó là tiền vào sổ HAI LẦN. Gọi lại trả đúng bút toán cũ. Chỉ writer definer gọi được.';








--
-- Name: special_fee_price_for_v1(uuid, uuid, text, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.special_fee_price_for_v1(p_org uuid, p_building uuid, p_kind text, p_month date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT v.amount
    FROM app_private.special_fee_price_versions v
   WHERE v.organization_id = p_org
     AND v.building_id     = p_building
     AND v.fee_category    = p_kind
     AND v.status          = 'PUBLISHED'
     AND v.effective_from_month <= date_trunc('month', p_month)::date
   ORDER BY v.effective_from_month DESC
   LIMIT 1;
$$;








--
-- Name: FUNCTION special_fee_price_for_v1(p_org uuid, p_building uuid, p_kind text, p_month date); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.special_fee_price_for_v1(p_org uuid, p_building uuid, p_kind text, p_month date) IS 'Giá công bố có hiệu lực cho THÁNG chỉ định. NULL = chủ chưa khai giá ô này.';








--
-- Name: special_fee_rule_check_v1(uuid, uuid, text, date, date, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.special_fee_rule_check_v1(p_org uuid, p_building uuid, p_kind text, p_period_start date, p_period_end date, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_m        date;
  v_price    numeric;
  v_expected numeric := 0;
  v_months   int := 0;
  v_missing  int := 0;
BEGIN
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RETURN jsonb_build_object('verdict','CONFIG_REQUIRED','reason','Kỳ không hợp lệ');
  END IF;

  -- Giá công bố là mức THEO THÁNG, nên chỉ so được khi kỳ phủ TRỌN các tháng.
  -- Kỳ lẻ (vd 15/06→14/07) không quy ra "mấy tháng" một cách không mập mờ: đếm
  -- theo tháng lịch sẽ ra 2 và đòi gấp đôi tiền cho một kỳ dài 30 ngày.
  -- ⇒ Trả CONFIG_REQUIRED = giữ nguyên hành vi cũ, không tự duyệt, không chặn.
  IF p_period_start <> date_trunc('month', p_period_start)::date
     OR p_period_end <> (date_trunc('month', p_period_end) + interval '1 month - 1 day')::date THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'reason','Kỳ không trọn tháng nên không đối chiếu được với giá công bố (giá công bố tính theo tháng)');
  END IF;

  -- Trần vòng lặp: kỳ nhập sai kiểu 1900→2099 sẽ quay 2.400 vòng trong lúc
  -- đang giữ khoá phiếu. 120 tháng (10 năm) là quá đủ cho mọi kỳ phí thật.
  IF (date_trunc('month', p_period_end)::date - date_trunc('month', p_period_start)::date) > 3700 THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'reason','Kỳ dài bất thường (trên 10 năm) — không đối chiếu tự động');
  END IF;

  v_m := date_trunc('month', p_period_start)::date;
  WHILE v_m <= date_trunc('month', p_period_end)::date LOOP
    v_months := v_months + 1;
    v_price  := app_private.special_fee_price_for_v1(p_org, p_building, p_kind, v_m);
    IF v_price IS NULL THEN
      v_missing := v_missing + 1;
    ELSE
      v_expected := v_expected + v_price;
    END IF;
    v_m := (v_m + interval '1 month')::date;
  END LOOP;

  IF v_missing > 0 THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'months', v_months,
      'missing_months', v_missing,
      'reason','Chưa khai giá ở Cài đặt → Phí cố định cho ' || v_missing || '/' || v_months || ' tháng của kỳ này');
  END IF;

  IF round(COALESCE(p_amount,0), 2) = round(v_expected, 2) THEN
    RETURN jsonb_build_object(
      'verdict','VALID', 'months', v_months, 'expected', round(v_expected,2));
  END IF;

  -- Định dạng số kiểu Việt Nam: dấu CHẤM ngăn nghìn. to_char mặc định theo
  -- lc_numeric của máy chủ (đang là kiểu Anh, cho ra "9,507,910đ") — người Việt
  -- đọc dấu phẩy là dấu thập phân nên câu thông báo sẽ gây hiểu nhầm số tiền.
  RETURN jsonb_build_object(
    'verdict','AMOUNT_MISMATCH',
    'months', v_months,
    'expected', round(v_expected,2),
    'actual',   round(COALESCE(p_amount,0),2),
    'reason', format('Giá đã công bố cho kỳ này là %sđ, số đang chi là %sđ',
                     replace(to_char(round(v_expected), 'FM999G999G999G999'), ',', '.'),
                     replace(to_char(round(COALESCE(p_amount,0)), 'FM999G999G999G999'), ',', '.')));
END;
$$;








--
-- Name: FUNCTION special_fee_rule_check_v1(p_org uuid, p_building uuid, p_kind text, p_period_start date, p_period_end date, p_amount numeric); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.special_fee_rule_check_v1(p_org uuid, p_building uuid, p_kind text, p_period_start date, p_period_end date, p_amount numeric) IS 'Số tiền có khớp giá đã khai cho đúng những tháng của kỳ không? VALID = tự duyệt được; AMOUNT_MISMATCH = phải chờ người duyệt; CONFIG_REQUIRED = chưa khai giá, giữ nguyên hành vi cũ (KHÔNG chặn — 0/21 toà khai đủ, chặn là cả hệ hết chi được).';








--
-- Name: special_page_submit_context_v1(text, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.special_page_submit_context_v1(p_operation text, p_organization_id uuid, p_building_id uuid, p_account_id uuid, p_idempotency_key text, p_subject_scope text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_scope text;
  v_op    app_private.canonical_write_operations%rowtype;
  v_route text;
  v_today date;
  v_acc   record;
  v_bld   record;
BEGIN
  -- 1. Đăng nhập
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(btrim(p_operation),'') = '' THEN
    RAISE EXCEPTION 'submit_context: thiếu operation' USING ERRCODE = '22023';
  END IF;
  -- Cùng luật với create_cashbook_v1 để hai bên không lệch chuẩn key.
  IF p_idempotency_key IS NULL
     OR char_length(btrim(p_idempotency_key)) < 8
     OR char_length(btrim(p_idempotency_key)) > 200
     OR btrim(p_idempotency_key) !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII an toàn' USING ERRCODE = '22023';
  END IF;

  v_org   := p_organization_id;
  v_scope := COALESCE(p_subject_scope, v_org::text);

  -- 2. IDEMPOTENCY LOOKUP TRƯỚC MỌI THỨ.
  -- Thứ tự này là CÓ CHỦ Ý: nếu kiểm quyền/hạn mức/kỳ trước, thì một thao tác ĐÃ
  -- hoàn tất hợp lệ khi gọi lại (mạng chập, người dùng bấm lại) sẽ ăn lỗi mới —
  -- ví dụ "kỳ đã khoá" hoặc "hết hạn mức canary" — dù chẳng có gì cần làm nữa.
  SELECT * INTO v_op FROM app_private.canonical_write_operations o
   WHERE o.organization_id = v_org AND o.operation = p_operation
     AND o.subject_scope = v_scope AND o.actor_id = v_actor
     AND o.idempotency_key = btrim(p_idempotency_key);
  IF FOUND AND v_op.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'replay', true,
      'operation', p_operation,
      'organizationId', v_org,
      'subjectId', v_op.subject_id,
      'response', v_op.response_payload);
  END IF;

  -- 3. Org + membership ACTIVE
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'submit_context: thiếu organization_id' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = v_org AND m.status = 'ACTIVE';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bạn không thuộc tổ chức này' USING ERRCODE = '42501';
  END IF;

  -- 5. Toà (kiểm trước quyền vì quyền theo toà cần biết toà có thật không)
  IF p_building_id IS NOT NULL THEN
    SELECT b.id, b.organization_id INTO v_bld
      FROM public.buildings b WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_bld.id IS NULL THEN
      RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE = '22023';
    END IF;
    IF v_bld.organization_id IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'Toà nhà không thuộc tổ chức này' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 4. Quyền — BA key, vì backend nhóm này thật sự đọc cả ba.
  IF NOT (
        public.is_super_admin() OR public.is_admin()
     OR (p_building_id IS NOT NULL AND public.can_access_building(p_building_id))
     OR (p_building_id IS NOT NULL AND public.ie_all_buildings_scope(p_building_id))
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên toà này' USING ERRCODE = '42501';
  END IF;

  -- 6. Sổ quỹ phải THẬT
  IF p_account_id IS NOT NULL THEN
    SELECT a.id, a.organization_id, COALESCE(a.is_virtual,false) AS is_virtual, a.name
      INTO v_acc
      FROM public.accounts a WHERE a.id = p_account_id AND a.deleted_at IS NULL;
    IF v_acc.id IS NULL THEN
      RAISE EXCEPTION 'Không tìm thấy sổ quỹ' USING ERRCODE = '22023';
    END IF;
    IF v_acc.organization_id IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'Sổ quỹ không thuộc tổ chức này' USING ERRCODE = '42501';
    END IF;
    -- Mắt xích hay bị quên nhất. Trên prod có sổ ẢO (243/287 phiếu cọc nằm trên
    -- đó, ~998tr backfill). Ghi tiền THẬT vào sổ ảo là báo két có tiền không có
    -- thật, và không cách nào phát hiện từ màn hình.
    IF v_acc.is_virtual THEN
      RAISE EXCEPTION
        'Sổ quỹ "%" là SỔ ẢO (chỉ để ghi nhận sổ sách), không nhận được tiền thật. Chọn sổ quỹ thật.',
        v_acc.name USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 7. Feature route — ĐÚNG MỘT LẦN. Trả trong context để writer khỏi gọi lại
  --    (gọi hai lần trong một transaction có thể ra hai kết quả nếu cờ đổi giữa chừng).
  v_route := app_private.evaluate_feature_route(p_operation, v_org);

  -- 8. Ngày nghiệp vụ theo múi giờ TỔ CHỨC, không CURRENT_DATE (server chạy UTC
  --    nên CURRENT_DATE lùi một ngày trong 00:00–07:00 giờ VN).
  v_today := public.org_today_v1(v_org);

  RETURN jsonb_build_object(
    'replay', false,
    'operation', p_operation,
    'organizationId', v_org,
    'actorId', v_actor,
    'buildingId', p_building_id,
    'accountId', p_account_id,
    'accountIsVirtual', COALESCE(v_acc.is_virtual, false),
    'idempotencyKey', btrim(p_idempotency_key),
    'subjectScope', v_scope,
    'featureRoute', v_route,
    'orgToday', v_today,
    'claimExists', (v_op.idempotency_key IS NOT NULL));
END;
$_$;








--
-- Name: FUNCTION special_page_submit_context_v1(p_operation text, p_organization_id uuid, p_building_id uuid, p_account_id uuid, p_idempotency_key text, p_subject_scope text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.special_page_submit_context_v1(p_operation text, p_organization_id uuid, p_building_id uuid, p_account_id uuid, p_idempotency_key text, p_subject_scope text) IS 'Đợt 1: context submit dùng chung cho các trang thanh toán đặc biệt. Thứ tự CÓ CHỦ Ý: idempotency LOOKUP TRƯỚC MỌI THỨ (lần gọi lặp phải trả kết quả cũ ngay, không được ăn lỗi "kỳ đã khoá"/"hết hạn mức" cho thao tác đã hoàn tất) → org + membership → toà → quyền (ba key: admin, can_access_building, ie_all_buildings_scope) → sổ quỹ phải THẬT (chặn sổ ảo — mắt xích hay quên nhất, ghi tiền vào sổ ảo là báo két có tiền không có thật) → feature route evaluate ĐÚNG MỘT LẦN → ngày theo múi giờ tổ chức. CHỈ ĐỌC: việc claim idempotency là của writer. Lõi nội bộ, không cấp cho client.';








--
-- Name: step_is_satisfied_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.step_is_satisfied_v1(p_request_step_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  -- H5 fix: count only DISTINCT approvals by members who are current-generation
  -- candidates of THIS step (a member removed on rematerialize no longer counts,
  -- and non-candidate approvals never counted). candidate_count is recomputed
  -- from live current-generation candidates so ALL cannot be satisfied by a
  -- stale ceiling.
  select case s.mode
    when 'ANY' then approvals >= 1
    when 'ALL' then approvals >= live_candidates and live_candidates > 0
    when 'QUORUM' then approvals >= s.min_approvals
    else false
  end
  from public.approval_request_steps s
  cross join lateral (
    select
      count(distinct d.actor_membership_id) filter (
        where d.decision in ('APPROVE','CHECKER_APPROVE')
          and exists (
            select 1 from public.approval_request_step_candidates c
             where c.request_step_id = s.id
               and c.membership_id = d.actor_membership_id
               and c.generation = s.current_generation
               and c.valid_to is null)) as approvals,
      (select count(*) from public.approval_request_step_candidates c
        where c.request_step_id = s.id
          and c.generation = s.current_generation
          and c.valid_to is null) as live_candidates
      from public.approval_decisions d
     where d.request_step_id = p_request_step_id
  ) a
  where s.id = p_request_step_id;
$$;








--
-- Name: storage_object_link_maintain(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.storage_object_link_maintain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare v_uploader uuid; v_org uuid; v_how text;
begin
  if new.bucket_id not in ('customer-id-cards','customer-images','income-expense-attachments',
                           'job-attachments','payment-receipts','meter-images','document-templates') then
    return new;
  end if;
  v_uploader := coalesce(new.owner_id::uuid, new.owner, nullif(split_part(new.name,'/',1),'')::uuid);
  select org, how into v_org, v_how from app_private.derive_uploader_org_v1(v_uploader);
  insert into app_private.storage_object_links (bucket_id, object_name, organization_id, owner_user_id, derivation)
  values (new.bucket_id, new.name, v_org, v_uploader, coalesce(v_how,'quarantine'))
  on conflict (bucket_id, object_name) do update set organization_id=excluded.organization_id,
    owner_user_id=excluded.owner_user_id, derivation=excluded.derivation;
  return new;
end;
$$;








--
-- Name: submit_financial_request_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.submit_financial_request_v1(p_subject_id uuid, p_actor_membership uuid, p_actor_user uuid, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$

declare

  v_ie public.income_expenses;

  v_org uuid;

  v_rule_set uuid;

  v_rule public.approval_rules;

  v_effect text;

  v_is_force boolean;

  v_sub_no int;

  v_hash text;

  v_snapshot jsonb;

  v_req uuid;

  v_ver bigint;

  v_type record;

  r_step record;

  v_step_id uuid;

  v_posting uuid;

  v_existing uuid;

begin

  -- 1. lock + derive from the subject (never trust client-derived fields)

  select * into v_ie from public.income_expenses

   where id = p_subject_id and deleted_at is null for update;

  if not found then raise exception 'subject not found' using errcode='P0002'; end if;

  v_org := v_ie.organization_id;

  if v_org is null then raise exception 'subject has no organization' using errcode='23514'; end if;



  -- maker attribution must be a real ACTIVE membership of this org matching the

  -- actor user (composite FK on approval_requests enforces this too).

  if not exists (

    select 1 from public.organization_memberships m

     where m.id = p_actor_membership and m.organization_id = v_org

       and m.user_id = p_actor_user and m.status = 'ACTIVE') then

    raise exception 'maker membership/user not active in org' using errcode='42501';

  end if;



  -- idempotent replay: an open request for the same subject with the same key

  -- returns the same request (append-only; one-open-subject guarantees <=1).

  select id into v_existing from public.approval_requests

   where organization_id = v_org and subject_type = 'FINANCIAL_VOUCHER'

     and subject_id = p_subject_id and state = 'PENDING_APPROVAL';

  if v_existing is not null then

    return v_existing; -- already submitted; idempotent

  end if;



  -- 2. resolve the single ACTIVE rule set (fail-closed)

  v_rule_set := app_private.resolve_active_rule_set_v1(

    v_org, app_private.ie_transaction_domain_v1());



  -- classify force categories from the item types of the subject

  select bool_or(coalesce(t.is_deposit,false)

                 or public.nrm_vn(t.name) in ('hoa hong moi gioi','thuong nong sale')
                 or coalesce(t.force_approval,false))

    into v_is_force

    from public.income_expense_items i

    join public.income_expense_types t on t.id = i.income_expense_type_id

   where i.income_expense_id = p_subject_id;

  v_is_force := coalesce(v_is_force, false);



  -- 3. match the highest-priority active rule; else fallback

  select * into v_rule from public.approval_rules r

   where r.rule_set_id = v_rule_set and r.active

     and not r.is_fallback

     and (r.force_match

          or r.transaction_type is null or r.transaction_type = v_ie.type)

     and (r.building_id is null or r.building_id = v_ie.building_id)

     and (r.cashbook_id is null or r.cashbook_id = v_ie.account_id)

     and (r.category_id is null or exists (

       select 1 from public.income_expense_items i

        where i.income_expense_id = p_subject_id

          and i.income_expense_type_id = r.category_id))

     and (r.system_source is null or r.system_source = v_ie.system_source)

     and (r.amount_min is null or v_ie.total_amount >= r.amount_min)

     and (r.amount_max is null or v_ie.total_amount <= r.amount_max)

   order by r.priority asc

   limit 1;

  if not found then

    select * into v_rule from public.approval_rules r

     where r.rule_set_id = v_rule_set and r.is_fallback and r.active

     limit 1;

    if not found then

      raise exception 'no matching or fallback rule (fail-closed)' using errcode='55000';

    end if;

  end if;



  -- force categories can never AUTO_POST

  v_effect := v_rule.effect;

  if v_is_force and v_effect = 'AUTO_POST' then

    v_effect := 'REQUIRE_APPROVAL';

  end if;



  -- 5. submission_no under the subject lock

  select coalesce(max(submission_no),0) + 1 into v_sub_no

    from public.approval_requests

   where organization_id = v_org and subject_type = 'FINANCIAL_VOUCHER'

     and subject_id = p_subject_id;



  -- 6. snapshot + hash (canonical fields only; not client spelling)

  v_snapshot := jsonb_build_object(

    'subject_id', p_subject_id, 'amount', v_ie.total_amount,

    'account_id', v_ie.account_id, 'building_id', v_ie.building_id,

    'type', v_ie.type, 'source_payload_hash', v_ie.source_payload_hash);

  v_hash := coalesce(v_ie.source_payload_hash, md5(v_snapshot::text));



  insert into public.approval_requests

    (organization_id, submission_no, subject_type, subject_id, state,

     maker_membership_id, maker_user_id, rule_set_id, rule_set_version,

     matched_rule_id, rule_effect, payload_snapshot, payload_hash, amount,

     category_id, cashbook_id, building_id, system_source, submitted_at, version)

  select

    v_org, v_sub_no, 'FINANCIAL_VOUCHER', p_subject_id,

    case v_effect when 'AUTO_POST' then 'PENDING_APPROVAL'

                  when 'DENY' then 'DENIED'

                  else 'PENDING_APPROVAL' end,

    p_actor_membership, p_actor_user, rs.id, rs.version,

    v_rule.id, v_effect, v_snapshot, v_hash, v_ie.total_amount,

    v_rule.category_id, v_ie.account_id, v_ie.building_id, v_ie.system_source,

    clock_timestamp(), 1

  from public.approval_rule_sets rs where rs.id = v_rule_set

  returning id, version into v_req, v_ver;



  -- DENY: terminal, no steps

  if v_effect = 'DENY' then

    return v_req;

  end if;



  -- AUTO_POST: post immediately (no approval steps)

  if v_effect = 'AUTO_POST' then

    v_posting := app_private.post_financial_request_v1(v_req, v_ver, p_actor_user);

    return v_req;

  end if;



  -- REQUIRE_APPROVAL: materialize steps from the matched rule's rule steps,

  -- then candidates for each. Fail-closed if the rule has no steps.

  if not exists (select 1 from public.approval_rule_steps

                  where rule_id = v_rule.id) then

    raise exception 'REQUIRE_APPROVAL rule % has no steps', v_rule.id using errcode='55000';

  end if;



  for r_step in

    select * from public.approval_rule_steps

     where rule_id = v_rule.id order by step_no

  loop

    insert into public.approval_request_steps

      (organization_id, request_id, step_no, status, mode, min_approvals,

       current_generation, rule_step_snapshot, candidate_count)

    values

      (v_org, v_req, r_step.step_no,

       case when r_step.step_no = 1 then 'PENDING' else 'WAITING' end,

       r_step.mode, r_step.min_approvals, 1,

       jsonb_build_object('rule_step_id', r_step.id), 0)

    returning id into v_step_id;



    perform app_private.materialize_step_candidates_v1(v_step_id);

  end loop;



  return v_req;

end;

$$;








--
-- Name: supersede_salary_settlement_bundle_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.supersede_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_new_bundle_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_b public.salary_settlement_bundles;
BEGIN
  SELECT * INTO v_b FROM public.salary_settlement_bundles b
   WHERE b.id = p_bundle_id AND b.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supersede_salary_settlement_bundle_v2: bundle % not found', p_bundle_id USING ERRCODE = 'P0002';
  END IF;
  IF v_b.state NOT IN ('PENDING','APPROVED') THEN
    RAISE EXCEPTION 'supersede_salary_settlement_bundle_v2: bundle % not supersedable (%)', p_bundle_id, v_b.state USING ERRCODE = '55000';
  END IF;
  -- §2.6 rent-offset supersession is a policy decision; stub until decided.
  PERFORM app_private.finance_v2_require_policy(p_org, 'salary.settlement.v2');

  -- Release held earnings on the superseded bundle; the replacement bundle re-holds its own.
  UPDATE public.salary_earning_consumptions c
     SET consumption_state = 'RELEASED', state_version = c.state_version + 1
   WHERE c.bundle_id = p_bundle_id AND c.consumption_state = 'HELD';

  UPDATE public.salary_settlement_bundles b SET state = 'SUPERSEDED' WHERE b.id = p_bundle_id;
  RETURN jsonb_build_object('bundleId', p_bundle_id, 'supersededBy', p_new_bundle_id, 'state', 'SUPERSEDED');
END
$$;








--
-- Name: FUNCTION supersede_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_new_bundle_id uuid, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.supersede_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_new_bundle_id uuid, p_reason text) IS 'Plan §6.10/§2.6: supersede a bundle (release held earnings); policy-gated stub for rent-offset supersession.';








--
-- Name: sweep_openclaw_delivery_claims_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sweep_openclaw_delivery_claims_v1(p_organization_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid, p_maintenance_principal_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  item record;
  v_requeued integer := 0;
  v_unknown integer := 0;
  v_work integer := 0;
  v_dead integer := 0;
  v_reason text;
  v_evidence jsonb;
  v_count integer;
begin
  for item in
    select outbox.*,handoff_match.id authorization_id,
      handoff_match.authorized_handoff_at
    from public.openclaw_outbox outbox
    left join lateral (
      select handoff.id,handoff.authorized_handoff_at
      from public.openclaw_outbound_authorizations handoff
      where handoff.organization_id=outbox.organization_id
        and handoff.account_id=outbox.account_id and handoff.outbox_id=outbox.id
        and handoff.claim_generation=outbox.claim_generation
        and handoff.consumed_at is not null
        and handoff.authorized_handoff_at is not null
      order by handoff.issued_at desc limit 1
    ) handoff_match on true
    where (p_organization_id is null or outbox.organization_id=p_organization_id)
      and (p_account_id is null or outbox.account_id=p_account_id)
      and outbox.state in ('LEASED','DISPATCHING')
      and outbox.lease_expires_at<=statement_timestamp()
    order by outbox.organization_id,outbox.account_id,outbox.id
    for update of outbox skip locked
  loop
    if item.authorization_id is null and item.state='LEASED' then
      v_evidence := jsonb_build_object('version',1,'reason','SWEEPER_LEASE_EXPIRED_PRE_HANDOFF',
        'outboxId',item.id,'claimGeneration',item.claim_generation);
      insert into public.openclaw_delivery_attempts(
        organization_id,account_id,outbox_id,authorization_id,claim_generation,
        attempt_number,outcome,reason_code,total_part_count,possible_handoff_prefix_length,
        known_provider_message_ids,evidence_kind,delivery_evidence,delivery_evidence_hash,
        started_at,finished_at
      ) values (
        item.organization_id,item.account_id,item.id,null,item.claim_generation,
        greatest(item.attempt_count,1),'SAFE_RETRY','SWEEPER_LEASE_EXPIRED_PRE_HANDOFF',
        1,0,'{}','OUTBOX_PRE_HANDOFF',v_evidence,
        encode(extensions.digest(app_private.openclaw_jcs_bytes_v1(v_evidence),'sha256'),'hex'),
        coalesce(item.updated_at,item.created_at),statement_timestamp()
      ) on conflict (organization_id,account_id,outbox_id,claim_generation,attempt_number) do nothing;
      update public.openclaw_outbox outbox set state='QUEUED',claim_token_hash=null,
        claimed_cell_id=null,lease_expires_at=null,credential_generation=null,
        runtime_lease_generation=null,claim_generation=outbox.claim_generation+1,
        retry_not_before=statement_timestamp(),updated_at=statement_timestamp()
      where outbox.organization_id=item.organization_id and outbox.id=item.id
        and outbox.state='LEASED' and outbox.claim_generation=item.claim_generation;
      v_requeued:=v_requeued+1;
    else
      v_reason := case when item.state='LEASED'
        then 'SWEEPER_LEASE_EXPIRED_AFTER_HANDOFF'
        else 'SWEEPER_DISPATCHING_WITHOUT_AUTHORIZATION' end;
      v_evidence := jsonb_build_object('version',1,'reason',v_reason,'outboxId',item.id,
        'claimGeneration',item.claim_generation,'authorizationId',item.authorization_id);
      insert into public.openclaw_delivery_attempts(
        organization_id,account_id,outbox_id,authorization_id,claim_generation,
        attempt_number,outcome,reason_code,total_part_count,possible_handoff_prefix_length,
        known_provider_message_ids,evidence_kind,delivery_evidence,delivery_evidence_hash,
        started_at,finished_at
      ) values (
        item.organization_id,item.account_id,item.id,item.authorization_id,item.claim_generation,
        greatest(item.attempt_count,1),'UNKNOWN',v_reason,1,0,'{}','OUTBOX_DELIVERY',v_evidence,
        encode(extensions.digest(app_private.openclaw_jcs_bytes_v1(v_evidence),'sha256'),'hex'),
        coalesce(item.dispatching_at,item.updated_at,item.created_at),statement_timestamp()
      ) on conflict (organization_id,account_id,outbox_id,claim_generation,attempt_number) do nothing;
      update public.openclaw_outbox outbox set state='UNKNOWN',claim_token_hash=null,
        claimed_cell_id=null,lease_expires_at=null,dispatching_at=null,
        credential_generation=null,runtime_lease_generation=null,
        terminal_at=statement_timestamp(),updated_at=statement_timestamp()
      where outbox.organization_id=item.organization_id and outbox.id=item.id
        and outbox.state in ('LEASED','DISPATCHING')
        and outbox.claim_generation=item.claim_generation;
      v_unknown:=v_unknown+1;
    end if;
  end loop;

  with candidates as (
    select work.id,work.organization_id from public.openclaw_send_work_items work
    where (p_organization_id is null or work.organization_id=p_organization_id)
      and (p_account_id is null or work.account_id=p_account_id)
      and work.state='LEASED' and work.lease_expires_at<=statement_timestamp()
    order by work.organization_id,work.account_id,work.id for update skip locked
  ) update public.openclaw_send_work_items work set state='QUEUED',claim_token_hash=null,
    lease_expires_at=null,claim_generation=work.claim_generation+1,
    retry_not_before=statement_timestamp(),updated_at=statement_timestamp()
  from candidates where work.organization_id=candidates.organization_id and work.id=candidates.id;
  get diagnostics v_count=row_count; v_work:=v_work+v_count;
  with candidates as (
    select work.id,work.organization_id from public.openclaw_maintenance_work_items work
    where (p_organization_id is null or work.organization_id=p_organization_id)
      and (p_maintenance_principal_id is null
        or work.maintenance_principal_id=p_maintenance_principal_id)
      and work.state='LEASED' and work.lease_expires_at<=statement_timestamp()
    order by work.organization_id,work.maintenance_principal_id,work.id for update skip locked
  ) update public.openclaw_maintenance_work_items work set state='QUEUED',claim_token_hash=null,
    lease_expires_at=null,claim_generation=work.claim_generation+1,
    retry_not_before=statement_timestamp(),updated_at=statement_timestamp()
  from candidates where work.organization_id=candidates.organization_id and work.id=candidates.id;
  get diagnostics v_count=row_count; v_work:=v_work+v_count;

  for item in select work.* from public.openclaw_send_work_items work
    where (p_organization_id is null or work.organization_id=p_organization_id)
      and (p_account_id is null or work.account_id=p_account_id)
      and work.state='QUEUED' and work.attempt_count>=5
    order by work.organization_id,work.account_id,work.id for update skip locked
  loop
    insert into public.openclaw_dead_letters(
      organization_id,account_id,send_work_item_id,reason_code,payload_hash,evidence
    ) values (item.organization_id,item.account_id,item.id,'WORK_RETRY_EXHAUSTED',
      item.payload_hash,jsonb_build_object('sourceKey',item.source_key,
        'attemptCount',item.attempt_count,'bindingGeneration',item.claim_generation))
    on conflict do nothing;
    update public.openclaw_send_work_items set state='DEAD_LETTER',terminal_at=statement_timestamp(),
      updated_at=statement_timestamp() where organization_id=item.organization_id and id=item.id
      and state='QUEUED';
    v_dead:=v_dead+1;
  end loop;
  return jsonb_build_object('version',1,'outboxRequeued',v_requeued,
    'outboxUnknown',v_unknown,'workReclaimed',v_work,'deadLetters',v_dead,
    'databaseTime',statement_timestamp());
end;
$$;








--
-- Name: sync_finance_invoice_components_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_finance_invoice_components_v1(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $_$
DECLARE
  v_invoice record;
  v_manifest_id uuid;
  v_manifest_finalized_at timestamptz;
  v_previous_invoice numeric := 0;
  v_previous_deposit numeric := 0;
  v_previous_source_total numeric := 0;
  v_invalid_source_count integer := 0;
  v_current_deposit numeric := 0;
  v_internal numeric := 0;
  v_current_charge numeric := 0;
  v_settlement numeric := 0;
  v_unclassified numeric := 0;
  v_component_total numeric := 0;
  v_status text := 'COMPLETE';
  v_anomaly text;
  v_should_finalize boolean;
BEGIN
  IF p_invoice_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    invoice_row.id,
    invoice_row.organization_id,
    invoice_row.kind,
    invoice_row.status::text AS status,
    COALESCE(invoice_row.total_amount, 0)::numeric AS total_amount,
    COALESCE(invoice_row.previous_debt, 0)::numeric AS previous_debt,
    COALESCE(invoice_row.previous_debt_sources, '[]'::jsonb) AS previous_debt_sources,
    invoice_row.updated_at
    INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('invoice-components:' || p_invoice_id::text, 0));

  SELECT manifest.id, manifest.finalized_at
    INTO v_manifest_id, v_manifest_finalized_at
  FROM public.finance_invoice_component_manifests manifest
  WHERE manifest.invoice_id = p_invoice_id
  FOR UPDATE;

  IF v_manifest_finalized_at IS NOT NULL THEN
    RETURN v_manifest_id;
  END IF;

  IF jsonb_typeof(v_invoice.previous_debt_sources) <> 'array' THEN
    v_invalid_source_count := 1;
  ELSE
    SELECT
      COALESCE(sum(
        CASE WHEN source.value->>'type' = 'invoice'
          AND COALESCE(source.value->>'amount', '') ~ '^[-+]?[0-9]+([.][0-9]+)?$'
          THEN (source.value->>'amount')::numeric ELSE 0 END
      ), 0),
      COALESCE(sum(
        CASE WHEN source.value->>'type' = 'deposit'
          AND COALESCE(source.value->>'amount', '') ~ '^[-+]?[0-9]+([.][0-9]+)?$'
          THEN (source.value->>'amount')::numeric ELSE 0 END
      ), 0),
      count(*) FILTER (
        WHERE source.value->>'type' NOT IN ('invoice', 'deposit')
          OR COALESCE(source.value->>'amount', '') !~ '^[-+]?[0-9]+([.][0-9]+)?$'
          OR CASE
            WHEN COALESCE(source.value->>'amount', '') ~ '^[-+]?[0-9]+([.][0-9]+)?$'
              THEN (source.value->>'amount')::numeric < 0
            ELSE false
          END
      )::integer
      INTO v_previous_invoice, v_previous_deposit, v_invalid_source_count
    FROM jsonb_array_elements(v_invoice.previous_debt_sources) source(value);
  END IF;

  v_previous_invoice := GREATEST(COALESCE(v_previous_invoice, 0), 0);
  v_previous_deposit := GREATEST(COALESCE(v_previous_deposit, 0), 0);
  v_previous_source_total := v_previous_invoice + v_previous_deposit;

  SELECT
    COALESCE(sum(item.amount) FILTER (WHERE item.accounting_class = 'DEPOSIT'), 0),
    COALESCE(sum(item.amount) FILTER (WHERE item.accounting_class = 'NON_PNL'), 0)
    INTO v_current_deposit, v_internal
  FROM public.invoice_items item
  WHERE item.invoice_id = p_invoice_id;

  v_current_deposit := GREATEST(COALESCE(v_current_deposit, 0), 0);
  v_internal := GREATEST(COALESCE(v_internal, 0), 0);

  IF v_invoice.kind = 'SETTLEMENT' THEN
    v_settlement := GREATEST(v_invoice.total_amount, 0);
    v_previous_invoice := 0;
    v_previous_deposit := 0;
    v_current_deposit := 0;
    v_internal := 0;
  ELSE
    IF v_invalid_source_count > 0
       OR abs(v_previous_source_total - v_invoice.previous_debt) >= 0.01 THEN
      v_unclassified := GREATEST(v_invoice.previous_debt, 0);
      v_previous_invoice := 0;
      v_previous_deposit := 0;
      v_status := 'ANOMALY';
      v_anomaly := 'PREVIOUS_DEBT_SOURCES_DO_NOT_RECONCILE';
    END IF;

    v_current_charge := v_invoice.total_amount
      - v_invoice.previous_debt
      - v_current_deposit
      - v_internal;
    IF v_current_charge < -0.01 THEN
      v_status := 'ANOMALY';
      v_anomaly := COALESCE(v_anomaly, 'CURRENT_COMPONENTS_EXCEED_INVOICE_TOTAL');
      v_unclassified := GREATEST(v_invoice.total_amount, 0);
      v_current_charge := 0;
      v_previous_invoice := 0;
      v_previous_deposit := 0;
      v_current_deposit := 0;
      v_internal := 0;
    ELSE
      v_current_charge := GREATEST(v_current_charge, 0);
    END IF;
  END IF;

  v_component_total := v_current_charge
    + v_previous_invoice
    + v_previous_deposit
    + v_current_deposit
    + v_internal
    + v_settlement
    + v_unclassified;
  IF abs(v_component_total - v_invoice.total_amount) >= 0.01 THEN
    v_status := 'ANOMALY';
    v_anomaly := COALESCE(v_anomaly, 'COMPONENT_TOTAL_DOES_NOT_RECONCILE');
  END IF;

  v_should_finalize := v_invoice.status IN (
    'APPROVED', 'PARTIAL_PAID', 'PAID', 'OVERDUE', 'CANCELLED'
  );

  IF v_manifest_id IS NULL THEN
    INSERT INTO public.finance_invoice_component_manifests (
      organization_id,
      invoice_id,
      component_status,
      invoice_total,
      component_total,
      component_version,
      anomaly_code,
      source_updated_at,
      captured_at,
      finalized_at
    ) VALUES (
      v_invoice.organization_id,
      p_invoice_id,
      v_status,
      v_invoice.total_amount,
      v_component_total,
      1,
      v_anomaly,
      v_invoice.updated_at,
      clock_timestamp(),
      CASE WHEN v_should_finalize THEN clock_timestamp() ELSE NULL END
    ) RETURNING id INTO v_manifest_id;
  ELSE
    DELETE FROM public.finance_invoice_components component
    WHERE component.manifest_id = v_manifest_id;
    UPDATE public.finance_invoice_component_manifests manifest
    SET
      component_status = v_status,
      invoice_total = v_invoice.total_amount,
      component_total = v_component_total,
      component_version = manifest.component_version + 1,
      anomaly_code = v_anomaly,
      source_updated_at = v_invoice.updated_at,
      captured_at = clock_timestamp(),
      finalized_at = CASE WHEN v_should_finalize THEN clock_timestamp() ELSE NULL END
    WHERE manifest.id = v_manifest_id;
  END IF;

  INSERT INTO public.finance_invoice_components (
    manifest_id, organization_id, invoice_id, component_kind, amount, component_order
  )
  SELECT v_manifest_id, v_invoice.organization_id, p_invoice_id, component.kind, component.amount, component.sort_order
  FROM (
    VALUES
      ('CARRIED_INVOICE_DEBT'::text, v_previous_invoice, 10),
      ('CURRENT_CHARGE'::text, v_current_charge, 20),
      ('CARRIED_DEPOSIT_DEBT'::text, v_previous_deposit, 30),
      ('CURRENT_DEPOSIT'::text, v_current_deposit, 40),
      ('INTERNAL'::text, v_internal, 50),
      ('SETTLEMENT'::text, v_settlement, 60),
      ('UNCLASSIFIED'::text, v_unclassified, 90)
  ) component(kind, amount, sort_order)
  WHERE component.amount > 0;

  RETURN v_manifest_id;
END;
$_$;








--
-- Name: sync_regrant_role_binding_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_regrant_role_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org         uuid;   -- org suy từ binding bị đóng (fallback để bump version)
  v_org_grant   uuid;   -- org khớp (membership ACTIVE + org_role) để cấp lại
  v_membership  uuid;
  v_binding     uuid;
  v_scope       uuid;
begin
  -- 1) REVOKE: đóng mọi binding đang mở gắn với assignment vừa đổi.
  update public.role_bindings rb
     set valid_to = now(), version = rb.version + 1
   where rb.legacy_assignment_id = new.id
     and rb.valid_to is null
  returning rb.organization_id into v_org;

  -- 2) RE-GRANT: dựng binding mới soi trạng thái assignment HIỆN TẠI.
  --    Chỉ cấp khi có membership ACTIVE + org_role tương ứng trong CÙNG org
  --    (giống ánh xạ Sprint 2c). Không có -> bỏ qua (fail-closed: thiếu quyền
  --    là an toàn).
  select m.organization_id, m.id
    into v_org_grant, v_membership
    from public.organization_memberships m
    join public.organization_roles orl
      on orl.organization_id = m.organization_id
     and orl.id = new.role_id
     and coalesce(orl.status, 'ACTIVE') = 'ACTIVE'
   where m.user_id = new.staff_id
     and m.status = 'ACTIVE'
   limit 1;

  if v_membership is not null then
    v_org := v_org_grant;

    v_binding := gen_random_uuid();
    insert into public.role_bindings
      (id, organization_id, membership_id, role_id, legacy_assignment_id,
       valid_from, valid_to, version)
    values
      (v_binding, v_org, v_membership, new.role_id, new.id, now(), null, 1);

    -- Bảo đảm + nối canonical scope theo building / area / full (Sprint 2c bước 5).
    -- Guard theo org để tránh FK lỗi làm gãy thao tác sửa staff của admin;
    -- scope không dựng được -> binding không scope -> deny (fail-closed, không RAISE).
    if new.building_id is not null then
      if exists (select 1 from public.buildings b
                  where b.id = new.building_id and b.organization_id = v_org) then
        insert into public.authorization_scopes (organization_id, scope_type, building_id)
        values (v_org, 'BUILDING', new.building_id)
        on conflict do nothing;
        select s.id into v_scope from public.authorization_scopes s
         where s.organization_id = v_org and s.scope_type = 'BUILDING'
           and s.building_id = new.building_id;
      end if;
    elsif new.area_id is not null then
      if exists (select 1 from public.areas a
                  where a.id = new.area_id and a.organization_id = v_org) then
        insert into public.authorization_scopes (organization_id, scope_type, area_id)
        values (v_org, 'AREA', new.area_id)
        on conflict do nothing;
        select s.id into v_scope from public.authorization_scopes s
         where s.organization_id = v_org and s.scope_type = 'AREA'
           and s.area_id = new.area_id;
      end if;
    else
      insert into public.authorization_scopes (organization_id, scope_type)
      values (v_org, 'ORGANIZATION')
      on conflict do nothing;
      select s.id into v_scope from public.authorization_scopes s
       where s.organization_id = v_org and s.scope_type = 'ORGANIZATION';
    end if;

    if v_scope is not null then
      insert into public.role_binding_scopes (organization_id, role_binding_id, scope_id)
      values (v_org, v_binding, v_scope)
      on conflict do nothing;
    end if;
  end if;

  -- 3) Bump cache quyền của org (kể cả khi chỉ revoke được, để không lỡ nhịp).
  if v_org is not null then
    update public.organizations
       set authorization_version = authorization_version + 1
     where id = v_org;
  end if;

  return null;
end;
$$;








--
-- Name: FUNCTION sync_regrant_role_binding_v1(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.sync_regrant_role_binding_v1() IS '20260722140000: sửa/đổi assignment legacy => đóng binding cũ + CẤP LẠI binding chuẩn hoá soi trạng thái hiện tại (role+scope). Thay revoke-only (t5_27) trên đường UPDATE. DELETE vẫn revoke-only qua sync_revoke_role_binding_v1.';








--
-- Name: sync_revoke_role_binding_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_revoke_role_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid;
begin
  -- Đóng mọi binding chuẩn hoá gắn với assignment vừa bị xoá / đổi vai trò.
  update public.role_bindings rb
     set valid_to = now(), version = rb.version + 1
   where rb.legacy_assignment_id = old.id
     and rb.valid_to is null
  returning rb.organization_id into v_org;

  if v_org is not null then
    update public.organizations
       set authorization_version = authorization_version + 1
     where id = v_org;
  end if;
  return null;
end;
$$;








--
-- Name: FUNCTION sync_revoke_role_binding_v1(); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.sync_revoke_role_binding_v1() IS 't5_27: gỡ/đổi assignment legacy ⇒ đóng role_binding chuẩn hoá tương ứng (fail-closed). Cấp lại quyền phải qua luồng cấp phép.';








--
-- Name: transition_canonical_income_expense_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_canonical_income_expense_v1(p_income_expense_id uuid, p_new_approval_status text, p_posting_id uuid, p_reversed_by_posting_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_rows integer;
  v_linked_profit_payout boolean;
  v_core_writer boolean;
BEGIN
  IF NOT app_private.is_income_expense_flow_owned(p_income_expense_id) THEN
    RAISE EXCEPTION 'not a canonical row: %', p_income_expense_id
      USING ERRCODE = '55000';
  END IF;
  IF p_new_approval_status NOT IN (
    'APPROVED', 'CANCELLED', 'REVERSED', 'DENIED', 'REJECTED'
  ) THEN
    RAISE EXCEPTION 'illegal transition target %', p_new_approval_status
      USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id = p_income_expense_id
    UNION ALL
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = p_income_expense_id
      AND request_row.system_source = 'profit.distribution'
  ) INTO v_linked_profit_payout;

  IF p_new_approval_status = 'APPROVED' AND v_linked_profit_payout THEN
    SELECT EXISTS (
      SELECT 1
      FROM app_private.accounting_chain_writer_xids capability
      WHERE capability.transaction_id = txid_current()
        AND capability.backend_pid = pg_backend_pid()
    ) INTO v_core_writer;

    -- Acquire source locks before linkage row locks and before the voucher write.
    PERFORM app_private.assert_profit_payout_fresh_v2(p_income_expense_id);
    PERFORM app_private.assert_profit_payout_linkage_v2(
      p_income_expense_id, v_core_writer, true
    );
  END IF;

  INSERT INTO app_private.ie_transition_authorization (
    income_expense_id, xid, purpose
  ) VALUES (
    p_income_expense_id, pg_current_xact_id(), p_new_approval_status
  );

  UPDATE public.income_expenses
     SET approval_status = p_new_approval_status,
         posting_id = COALESCE(p_posting_id, posting_id),
         posted_at_v2 = CASE
           WHEN p_new_approval_status = 'APPROVED' THEN clock_timestamp()
           ELSE posted_at_v2
         END,
         reversed_by_posting_id = COALESCE(
           p_reversed_by_posting_id, reversed_by_posting_id
         )
   WHERE id = p_income_expense_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  DELETE FROM app_private.ie_transition_authorization
  WHERE income_expense_id = p_income_expense_id
    AND xid = pg_current_xact_id();

  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'transition affected % rows (expected 1)', v_rows
      USING ERRCODE = '55000';
  END IF;
END
$$;








--
-- Name: transition_invoice_refund_reservation_v2(uuid, uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_invoice_refund_reservation_v2(p_org uuid, p_reservation_id uuid, p_target_state text, p_posting_id uuid, p_expected_state_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_r app_private.invoice_refund_reservations;
  v_new bigint;
BEGIN
  SELECT * INTO v_r FROM app_private.invoice_refund_reservations r
   WHERE r.id = p_reservation_id AND r.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transition_invoice_refund_reservation_v2: reservation % not found', p_reservation_id USING ERRCODE = 'P0002';
  END IF;
  IF v_r.state_version <> p_expected_state_version THEN
    RAISE EXCEPTION 'transition_invoice_refund_reservation_v2: state_version mismatch (expected %, found %)',
      p_expected_state_version, v_r.state_version USING ERRCODE = '55000';
  END IF;
  IF p_target_state NOT IN ('CONSUMED','RELEASED','REVERSED') THEN
    RAISE EXCEPTION 'transition_invoice_refund_reservation_v2: invalid target %', p_target_state USING ERRCODE = '22023';
  END IF;
  -- Legal transitions: HELD->CONSUMED (post), HELD->RELEASED (cancel/reject), CONSUMED->REVERSED (reverse).
  IF NOT (
       (v_r.reservation_state = 'HELD'     AND p_target_state IN ('CONSUMED','RELEASED'))
    OR (v_r.reservation_state = 'CONSUMED' AND p_target_state = 'REVERSED')
  ) THEN
    RAISE EXCEPTION 'transition_invoice_refund_reservation_v2: illegal % -> %', v_r.reservation_state, p_target_state USING ERRCODE = '55000';
  END IF;
  IF p_target_state = 'CONSUMED' AND p_posting_id IS NULL THEN
    RAISE EXCEPTION 'transition_invoice_refund_reservation_v2: CONSUMED requires a posting id' USING ERRCODE = '22023';
  END IF;

  v_new := v_r.state_version + 1;
  UPDATE app_private.invoice_refund_reservations r
     SET reservation_state = p_target_state,
         state_version = v_new,
         consumed_posting_id = CASE WHEN p_target_state = 'CONSUMED' THEN p_posting_id ELSE r.consumed_posting_id END,
         reversed_posting_id = CASE WHEN p_target_state = 'REVERSED' THEN p_posting_id ELSE r.reversed_posting_id END,
         state_changed_at = now(), state_reason = p_reason
   WHERE r.id = p_reservation_id;

  RETURN jsonb_build_object('reservationId', p_reservation_id, 'reservationState', p_target_state, 'stateVersion', v_new);
END
$$;








--
-- Name: FUNCTION transition_invoice_refund_reservation_v2(p_org uuid, p_reservation_id uuid, p_target_state text, p_posting_id uuid, p_expected_state_version bigint, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.transition_invoice_refund_reservation_v2(p_org uuid, p_reservation_id uuid, p_target_state text, p_posting_id uuid, p_expected_state_version bigint, p_reason text) IS 'Plan §8.1: HELD->CONSUMED(post)/RELEASED(cancel), CONSUMED->REVERSED(reverse); approve-only does not touch this ledger.';








--
-- Name: transition_profit_payout_reservation_v2(uuid, uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_profit_payout_reservation_v2(p_org uuid, p_reservation_id uuid, p_target_state text, p_posting_id uuid, p_expected_state_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_r public.profit_payout_reservations;
  v_cur text;
  v_new bigint;
BEGIN
  SELECT * INTO v_r FROM public.profit_payout_reservations r
   WHERE r.id = p_reservation_id AND r.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transition_profit_payout_reservation_v2: reservation % not found', p_reservation_id USING ERRCODE = 'P0002';
  END IF;
  v_cur := COALESCE(v_r.reservation_state, 'HELD');
  IF COALESCE(v_r.state_version, 1) <> p_expected_state_version THEN
    RAISE EXCEPTION 'transition_profit_payout_reservation_v2: state_version mismatch (expected %, found %)',
      p_expected_state_version, COALESCE(v_r.state_version, 1) USING ERRCODE = '55000';
  END IF;
  IF p_target_state NOT IN ('CONSUMED','RELEASED','REVERSED') THEN
    RAISE EXCEPTION 'transition_profit_payout_reservation_v2: invalid target %', p_target_state USING ERRCODE = '22023';
  END IF;
  IF NOT (
       (v_cur = 'HELD'     AND p_target_state IN ('CONSUMED','RELEASED'))
    OR (v_cur = 'CONSUMED' AND p_target_state = 'REVERSED')
  ) THEN
    RAISE EXCEPTION 'transition_profit_payout_reservation_v2: illegal % -> %', v_cur, p_target_state USING ERRCODE = '55000';
  END IF;
  IF p_target_state = 'CONSUMED' AND p_posting_id IS NULL THEN
    RAISE EXCEPTION 'transition_profit_payout_reservation_v2: CONSUMED requires posting id' USING ERRCODE = '22023';
  END IF;

  v_new := COALESCE(v_r.state_version, 1) + 1;
  UPDATE public.profit_payout_reservations r
     SET reservation_state = p_target_state,
         state_version = v_new,
         consumed_posting_id = CASE WHEN p_target_state = 'CONSUMED' THEN p_posting_id ELSE r.consumed_posting_id END,
         reversed_posting_id = CASE WHEN p_target_state = 'REVERSED' THEN p_posting_id ELSE r.reversed_posting_id END,
         state_changed_at = now(), state_reason = p_reason
   WHERE r.id = p_reservation_id;

  RETURN jsonb_build_object('reservationId', p_reservation_id, 'reservationState', p_target_state, 'stateVersion', v_new);
END
$$;








--
