--
-- Name: transition_salary_settlement_bundle_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_decision text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_b public.salary_settlement_bundles;
  v_new_state text;
BEGIN
  IF p_decision NOT IN ('approve','reject','cancel') THEN
    RAISE EXCEPTION 'transition_salary_settlement_bundle_v2: unsupported decision %', p_decision USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_b FROM public.salary_settlement_bundles b
   WHERE b.id = p_bundle_id AND b.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transition_salary_settlement_bundle_v2: bundle % not found', p_bundle_id USING ERRCODE = 'P0002';
  END IF;
  IF v_b.state <> 'PENDING' THEN
    RAISE EXCEPTION 'transition_salary_settlement_bundle_v2: bundle % not PENDING (%)', p_bundle_id, v_b.state USING ERRCODE = '55000';
  END IF;

  -- §2.6: rent-offset / commission policy required before an approve materializes non-cash.
  IF p_decision = 'approve' THEN
    PERFORM app_private.finance_v2_require_policy(p_org, 'salary.settlement.v2');

    -- Approve parent (NON_CASH gross P&L) + the ONE_SHOT/MULTI_TRANCHE authorization birthed earlier.
    IF v_b.parent_voucher_id IS NOT NULL THEN
      PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_b.parent_voucher_id FOR UPDATE;
      PERFORM app_private.finance_v2_transition_owned_approval(v_b.parent_voucher_id, 'APPROVED', 'NOT_APPLICABLE');
    END IF;

    -- Materialize planned rent-offset non-cash exactly ONCE at approve (guarded by earning consumption HELD->CONSUMED).
    UPDATE public.salary_earning_consumptions c
       SET consumption_state = 'CONSUMED', state_version = c.state_version + 1
     WHERE c.bundle_id = p_bundle_id AND c.consumption_state = 'HELD';

    v_new_state := 'APPROVED';
  ELSE
    -- reject/cancel: release held earnings, cancel parent.
    UPDATE public.salary_earning_consumptions c
       SET consumption_state = 'RELEASED', state_version = c.state_version + 1
     WHERE c.bundle_id = p_bundle_id AND c.consumption_state = 'HELD';
    IF v_b.parent_voucher_id IS NOT NULL THEN
      PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_b.parent_voucher_id FOR UPDATE;
      PERFORM app_private.finance_v2_transition_owned_approval(v_b.parent_voucher_id, 'CANCELLED', 'NOT_APPLICABLE');
    END IF;
    v_new_state := 'CANCELLED';
  END IF;

  UPDATE public.salary_settlement_bundles b SET state = v_new_state WHERE b.id = p_bundle_id;
  RETURN jsonb_build_object('bundleId', p_bundle_id, 'decision', p_decision, 'state', v_new_state);
END
$$;








--
-- Name: FUNCTION transition_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_decision text, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.transition_salary_settlement_bundle_v2(p_org uuid, p_bundle_id uuid, p_decision text, p_reason text) IS 'Plan §6.10/§2.6: one request approves parent + child/authorization; rent-offset non-cash materialized ONCE at approve. Policy-gated.';








--
-- Name: transition_termination_forfeit_pair_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_termination_forfeit_pair_v2(p_org uuid, p_revenue_voucher_id uuid, p_decision text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_auth app_private.termination_forfeit_authorizations;
  v_leg1 uuid;
  v_leg2 uuid;
  v_new_status text;
  v_new_posting text;
BEGIN
  IF p_decision NOT IN ('approve','cancel') THEN
    RAISE EXCEPTION 'transition_termination_forfeit_pair_v2: unsupported pair decision % (reverse is append-only elsewhere)', p_decision USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_auth FROM app_private.termination_forfeit_authorizations a
   WHERE a.revenue_voucher_id = p_revenue_voucher_id AND a.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transition_termination_forfeit_pair_v2: no forfeit authorization for revenue voucher %', p_revenue_voucher_id USING ERRCODE = 'P0002';
  END IF;

  -- Lock both legs in id order (deadlock-free); both are NON_CASH / NOT_APPLICABLE, no posting.
  v_leg1 := LEAST(v_auth.revenue_voucher_id, v_auth.offset_voucher_id);
  v_leg2 := GREATEST(v_auth.revenue_voucher_id, v_auth.offset_voucher_id);
  PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_leg1 FOR UPDATE;
  PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_leg2 FOR UPDATE;

  v_new_status  := CASE WHEN p_decision = 'approve' THEN 'APPROVED' ELSE 'CANCELLED' END;
  v_new_posting := 'NOT_APPLICABLE';

  PERFORM app_private.finance_v2_transition_owned_approval(v_auth.revenue_voucher_id, v_new_status, v_new_posting);
  PERFORM app_private.finance_v2_transition_owned_approval(v_auth.offset_voucher_id,  v_new_status, v_new_posting);

  RETURN jsonb_build_object('pair', 'TERMINATION_FORFEIT_PAIR_V2',
                            'revenueVoucherId', v_auth.revenue_voucher_id,
                            'offsetVoucherId', v_auth.offset_voucher_id,
                            'decision', p_decision, 'approvalStatus', v_new_status);
END
$$;








--
-- Name: FUNCTION transition_termination_forfeit_pair_v2(p_org uuid, p_revenue_voucher_id uuid, p_decision text, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.transition_termination_forfeit_pair_v2(p_org uuid, p_revenue_voucher_id uuid, p_decision text, p_reason text) IS 'Plan §6.8: approve/cancel BOTH forfeit legs + non-cash settlement atomically; generic per-leg action is blocked by flow ownership.';








--
-- Name: transition_termination_move_out_pair_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_decision text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_auth public.termination_move_out_authorizations;
  v_leg1 uuid;
  v_leg2 uuid;
  v_bad_funding int;
  v_new_status text;
BEGIN
  IF p_decision NOT IN ('approve','cancel') THEN
    RAISE EXCEPTION 'transition_termination_move_out_pair_v2: unsupported decision %', p_decision USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_auth FROM public.termination_move_out_authorizations a
   WHERE a.id = p_authorization_id AND a.organization_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transition_termination_move_out_pair_v2: authorization % not found', p_authorization_id USING ERRCODE = 'P0002';
  END IF;
  IF v_auth.state <> 'PLANNED' THEN
    RAISE EXCEPTION 'transition_termination_move_out_pair_v2: authorization % not PLANNED (%)', p_authorization_id, v_auth.state USING ERRCODE = '55000';
  END IF;

  -- Settlement funding is restricted to DEPOSIT_OFFSET / CUSTOMER_CREDIT (no CASH_DUE).
  SELECT count(*) INTO v_bad_funding FROM public.termination_move_out_settlement_lines l
   WHERE l.authorization_id = p_authorization_id AND l.funding_kind NOT IN ('DEPOSIT_OFFSET','CUSTOMER_CREDIT');
  IF v_bad_funding > 0 THEN
    RAISE EXCEPTION 'transition_termination_move_out_pair_v2: authorization % has non-offset funding lines', p_authorization_id USING ERRCODE = '55000';
  END IF;

  v_new_status := CASE WHEN p_decision = 'approve' THEN 'APPROVED' ELSE 'CANCELLED' END;

  IF v_auth.revenue_voucher_id IS NOT NULL AND v_auth.offset_voucher_id IS NOT NULL THEN
    v_leg1 := LEAST(v_auth.revenue_voucher_id, v_auth.offset_voucher_id);
    v_leg2 := GREATEST(v_auth.revenue_voucher_id, v_auth.offset_voucher_id);
    PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_leg1 FOR UPDATE;
    PERFORM 1 FROM public.income_expenses ie WHERE ie.id = v_leg2 FOR UPDATE;
    PERFORM app_private.finance_v2_transition_owned_approval(v_auth.revenue_voucher_id, v_new_status, 'NOT_APPLICABLE');
    PERFORM app_private.finance_v2_transition_owned_approval(v_auth.offset_voucher_id,  v_new_status, 'NOT_APPLICABLE');
  END IF;

  UPDATE public.termination_move_out_authorizations a
     SET state = v_new_status
   WHERE a.id = p_authorization_id;

  RETURN jsonb_build_object('authorizationId', p_authorization_id, 'decision', p_decision,
                            'state', v_new_status, 'pairVersion', v_auth.pair_version);
END
$$;








--
-- Name: FUNCTION transition_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_decision text, p_reason text); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.transition_termination_move_out_pair_v2(p_org uuid, p_authorization_id uuid, p_decision text, p_reason text) IS 'Plan §6.9: approve/cancel one move-out pair; materialize DEPOSIT_OFFSET/CUSTOMER_CREDIT settlement only, no cash posting.';








--
-- Name: utility_ceiling_check_v1(uuid, uuid, text, date, numeric, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.utility_ceiling_check_v1(p_org uuid, p_building uuid, p_type text, p_month date, p_amount numeric, p_billed_to_tenants numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE v_r record; v_lim numeric;
BEGIN
  SELECT * INTO v_r FROM app_private.utility_ceiling_versions v
   WHERE v.organization_id = p_org AND v.status = 'PUBLISHED'
     AND v.utility_type = p_type
     AND v.effective_from_month <= date_trunc('month', p_month)::date
     AND (v.building_id = p_building OR v.building_id IS NULL)
   ORDER BY (v.building_id IS NOT NULL) DESC, v.effective_from_month DESC
   LIMIT 1;

  IF v_r.id IS NULL THEN
    RETURN jsonb_build_object('verdict','NO_RULE',
      'reason','Chủ chưa công bố trần cho hạng mục này — giữ nguyên hành vi cũ');
  END IF;

  IF v_r.ceiling_amount IS NOT NULL AND round(COALESCE(p_amount,0)) > round(v_r.ceiling_amount) THEN
    RETURN jsonb_build_object('verdict','OVER_CEILING',
      'ceiling', v_r.ceiling_amount, 'actual', p_amount,
      'reason','Số chi ' || replace(to_char(round(COALESCE(p_amount,0)),'FM999G999G999G999'),',','.')
               || 'đ vượt trần ' || replace(to_char(round(v_r.ceiling_amount),'FM999G999G999G999'),',','.') || 'đ');
  END IF;

  IF v_r.max_ratio_to_billed IS NOT NULL AND COALESCE(p_billed_to_tenants,0) > 0 THEN
    v_lim := round(p_billed_to_tenants * v_r.max_ratio_to_billed);
    IF round(COALESCE(p_amount,0)) > v_lim THEN
      RETURN jsonb_build_object('verdict','OVER_RATIO',
        'limit', v_lim, 'billed', p_billed_to_tenants, 'ratio', v_r.max_ratio_to_billed,
        'reason','Số chi vượt ' || v_r.max_ratio_to_billed || ' lần tiền đã thu của khách ('
                 || replace(to_char(round(p_billed_to_tenants),'FM999G999G999G999'),',','.') || 'đ)');
    END IF;
  END IF;

  -- Mẫu số 0 mà vẫn chi ⇒ đáng ngờ, nhưng không chặn: có toà chưa kịp chốt số khách.
  IF v_r.max_ratio_to_billed IS NOT NULL AND COALESCE(p_billed_to_tenants,0) = 0
     AND COALESCE(p_amount,0) > 0 THEN
    RETURN jsonb_build_object('verdict','WARN_NO_BILLED',
      'reason','Chưa thu đồng nào của khách cho kỳ này mà đã chi nhà cung cấp — nên rà lại');
  END IF;

  RETURN jsonb_build_object('verdict','WITHIN_LIMIT');
END;
$$;








--
-- Name: verify_authz_audit_chain_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.verify_authz_audit_chain_v1(p_organization_id uuid) RETURNS TABLE(event_id uuid, occurred_at timestamp with time zone, van_de text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private', 'extensions'
    AS $$
  with chuoi as (
    select a.*,
           lag(a.event_hash) over (order by a.occurred_at, a.id) as prev_thuc_te
      from public.authorization_audit_events a
     where a.organization_id = p_organization_id
  )
  select c.id, c.occurred_at,
         case
           when c.prev_hash is distinct from c.prev_thuc_te
             then 'Mắt xích trước không khớp — có dòng bị sửa hoặc xoá'
           else 'Hash của chính dòng này không khớp nội dung'
         end
    from chuoi c
   where c.prev_hash is distinct from c.prev_thuc_te
      or c.event_hash is distinct from encode(extensions.digest(
           coalesce(c.prev_thuc_te,'')
        || '|' || c.organization_id::text
        || '|' || c.occurred_at::text
        || '|' || coalesce(c.actor_user_id::text,'')
        || '|' || coalesce(c.actor_membership_id::text,'')
        || '|' || c.event_type
        || '|' || coalesce(c.resource_type,'')
        || '|' || coalesce(c.resource_id::text,'')
        || '|' || coalesce(c.old_state::text,'')
        || '|' || coalesce(c.new_state::text,'')
        || '|' || coalesce(c.reason,''), 'sha256'), 'hex')
   order by c.occurred_at;
$$;








--
-- Name: FUNCTION verify_authz_audit_chain_v1(p_organization_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.verify_authz_audit_chain_v1(p_organization_id uuid) IS 'Soi chuỗi hash nhật ký phân quyền của một tổ chức. Trả rỗng = chưa phát hiện can thiệp.';








--
-- Name: verify_income_expense_audit_chain_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.verify_income_expense_audit_chain_v1(p_organization_id uuid) RETURNS TABLE(valid boolean, checked_events bigint, first_broken_sequence bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  r record;
  v_prev text := repeat('0', 64);
  v_expected text;
  v_count bigint := 0;
begin
  for r in
    select * from public.income_expense_audit_log
     where organization_id = p_organization_id and sequence_no is not null
     order by sequence_no
  loop
    v_expected := encode(sha256(convert_to(concat_ws(chr(31),
      'PG_SHA256_CANONICAL_V1',
      r.organization_id::text,
      r.sequence_no::text,
      v_prev,
      r.income_expense_id::text,
      r.action,
      r.actor_id::text,
      coalesce(r.actor_name, ''),
      coalesce(r.old_status, ''),
      coalesce(r.new_status, ''),
      coalesce(r.note, ''),
      to_char(r.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
      'UTF8')), 'hex');
    if r.prev_event_hash <> v_prev or r.event_hash <> v_expected then
      return query select false, v_count, r.sequence_no;
      return;
    end if;
    v_prev := r.event_hash;
    v_count := v_count + 1;
  end loop;
  return query select true, v_count, null::bigint;
end;
$$;








--
-- Name: verify_openclaw_audit_chain_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.verify_openclaw_audit_chain_v1(p_organization_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous_hash text := repeat('0', 64);
  v_expected_sequence bigint := 1;
  v_expected_hash text;
  v_event record;
begin
  for v_event in
    select organization_sequence, event_type, redacted_evidence_bytes,
           evidence_hash, previous_hash, event_hash
      from public.openclaw_audit_events
     where organization_id = p_organization_id
     order by organization_sequence
  loop
    if v_event.organization_sequence <> v_expected_sequence
       or v_event.previous_hash <> v_previous_hash
    then
      return false;
    end if;
    if encode(extensions.digest(v_event.redacted_evidence_bytes, 'sha256'), 'hex')
         <> v_event.evidence_hash
    then
      return false;
    end if;
    v_expected_hash := encode(extensions.digest(
      convert_to(v_previous_hash, 'UTF8') || decode('00', 'hex')
        || convert_to(v_expected_sequence::text, 'UTF8') || decode('00', 'hex')
        || convert_to(v_event.event_type, 'UTF8') || decode('00', 'hex')
        || convert_to(v_event.evidence_hash, 'UTF8'),
      'sha256'
    ), 'hex');
    if v_event.event_hash <> v_expected_hash then
      return false;
    end if;
    v_previous_hash := v_event.event_hash;
    v_expected_sequence := v_expected_sequence + 1;
  end loop;
  return true;
end
$$;








--
-- Name: do_sync(uuid); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.do_sync(p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'clone_org'
    AS $_$
DECLARE
  v_source uuid := 'aaaa0000-0000-4000-8000-000000000001';
  v_target uuid;
  v_log_id bigint;
  r record;
  v_cols text;
  v_exprs text;
  v_where text;
  v_n bigint;
  v_total bigint := 0;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF current_setting('session_replication_role') <> 'replica' THEN
    RAISE EXCEPTION 'do_sync yêu cầu session_replication_role=replica (xem ghi chú đầu migration)'
      USING ERRCODE = '55000';
  END IF;

  v_target := (public.sandbox_org_ids())[1];
  IF v_target IS NULL OR v_target = v_source THEN
    RAISE EXCEPTION 'TRIPWIRE: org đích không hợp lệ (%)', v_target USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = v_target) THEN
    RAISE EXCEPTION 'Chưa có org TEST' USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM clone_org.user_map) THEN
    RAISE EXCEPTION 'clone_org.user_map rỗng' USING ERRCODE = '55000';
  END IF;

  INSERT INTO clone_org.sync_log (actor) VALUES (p_actor) RETURNING id INTO v_log_id;

  -- 2 trigger ENABLE ALWAYS vẫn chạy trong replica mode → tắt trong transaction.
  ALTER TABLE public.approval_rule_sets DISABLE TRIGGER a00_rule_set_immutable;
  ALTER TABLE public.approval_rules DISABLE TRIGGER a00_rules_immutable;

  CREATE TEMP TABLE _uniq ON COMMIT DROP AS
    SELECT DISTINCT t.relname::text AS tbl, a.attname::text AS col, NOT a.attnotnull AS nullable
    FROM pg_index x
    JOIN pg_class t ON t.oid = x.indrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace AND n.nspname = 'public'
    JOIN unnest(x.indkey) k(attnum) ON true
    JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = k.attnum
    WHERE x.indisunique AND NOT x.indisprimary AND a.atttypid = 'uuid'::regtype
      AND pg_get_indexdef(x.indexrelid) NOT ILIKE '%organization_id%';

  FOR r IN SELECT * FROM clone_org.tables_to_clone() LOOP
    EXECUTE format('DELETE FROM public.%I WHERE organization_id = %L', r.tbl, v_target);
  END LOOP;

  TRUNCATE clone_org.idmap;
  INSERT INTO clone_org.idmap (old_id, new_id)
    SELECT old_user_id, new_user_id FROM clone_org.user_map;

  FOR r IN SELECT * FROM clone_org.tables_to_clone() WHERE has_uuid_id LOOP
    EXECUTE format(
      'INSERT INTO clone_org.idmap (old_id, new_id)
       SELECT id, gen_random_uuid() FROM public.%I WHERE organization_id = %L
       ON CONFLICT (old_id) DO NOTHING', r.tbl, v_source);
  END LOOP;

  FOR i IN 1..3 LOOP
    FOR r IN
      SELECT p.tbl, string_agg(format('%I IN (SELECT old_id FROM clone_org.idmap)', p.col), ' OR ') AS pred
      FROM clone_org.null_org_parent p
      JOIN clone_org.tables_to_clone() t ON t.tbl = p.tbl AND t.has_uuid_id
      WHERE EXISTS (SELECT 1 FROM information_schema.columns c
                    WHERE c.table_schema = 'public' AND c.table_name = p.tbl AND c.column_name = p.col)
      GROUP BY p.tbl
    LOOP
      EXECUTE format(
        'INSERT INTO clone_org.idmap (old_id, new_id)
         SELECT id, gen_random_uuid() FROM public.%I
         WHERE organization_id IS NULL AND (%s) ON CONFLICT (old_id) DO NOTHING', r.tbl, r.pred);
    END LOOP;
  END LOOP;

  FOR r IN SELECT * FROM clone_org.tables_to_clone() LOOP
    SELECT string_agg(quote_ident(z.col), ', ' ORDER BY z.ord),
           string_agg(z.expr, ', ' ORDER BY z.ord)
      INTO v_cols, v_exprs
    FROM (
      SELECT c.column_name AS col, c.ordinal_position AS ord,
        CASE
          WHEN c.column_name = 'organization_id' THEN quote_literal(v_target) || '::uuid'
          WHEN c.udt_name = 'uuid' AND EXISTS (
                 SELECT 1 FROM _uniq u WHERE u.tbl = r.tbl AND u.col = c.column_name AND u.nullable)
            THEN 'clone_org.map_strict(src.' || quote_ident(c.column_name) || ')'
          WHEN c.udt_name = 'uuid' THEN 'clone_org.map(src.' || quote_ident(c.column_name) || ')'
          WHEN c.udt_name = '_uuid' THEN 'clone_org.map_arr(src.' || quote_ident(c.column_name) || ')'
          WHEN c.udt_name IN ('json', 'jsonb')
            THEN 'clone_org.map_text(src.' || quote_ident(c.column_name) || '::text)::' || c.udt_name
          WHEN EXISTS (SELECT 1 FROM clone_org.code_suffix_col s
                       WHERE s.tbl = r.tbl AND s.col = c.column_name)
            THEN 'CASE WHEN src.' || quote_ident(c.column_name) || ' IS NULL THEN NULL ELSE clone_org.map_text(src.'
                 || quote_ident(c.column_name) || ') || ''-T'' END'
          WHEN c.udt_name IN ('text', 'varchar')
            THEN 'clone_org.map_text(src.' || quote_ident(c.column_name) || ')'
          ELSE 'src.' || quote_ident(c.column_name)
        END AS expr
      FROM information_schema.columns c
      WHERE c.table_schema = 'public' AND c.table_name = r.tbl
        AND c.is_generated = 'NEVER' AND c.is_identity = 'NO'
    ) z;

    IF v_cols IS NULL THEN CONTINUE; END IF;

    v_where := CASE WHEN r.has_uuid_id
                    THEN 'src.id IN (SELECT old_id FROM clone_org.idmap)'
                    ELSE format('src.organization_id = %L', v_source) END;
    SELECT v_where || COALESCE(string_agg(
             format(' AND src.%I IN (SELECT old_id FROM clone_org.idmap)', u.col), ''), '')
      INTO v_where
    FROM _uniq u WHERE u.tbl = r.tbl AND NOT u.nullable;

    EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM public.%I src WHERE %s',
                   r.tbl, v_cols, v_exprs, r.tbl, v_where);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      v_total := v_total + v_n;
      v_counts := v_counts || jsonb_build_object(r.tbl, v_n);
    END IF;
  END LOOP;

  -- Làm nhiễu liên hệ: thao tác thử không được nhắn/nhắc nợ trúng khách thật.
  FOR r IN
    SELECT c.table_name AS tbl, c.column_name AS col, (c.column_name ~* 'email') AS is_email
    FROM information_schema.columns c
    JOIN clone_org.tables_to_clone() t ON t.tbl = c.table_name
    WHERE c.table_schema = 'public' AND c.udt_name IN ('text', 'varchar')
      AND c.column_name ~* '(phone|mobile|zalo|email)'
      AND c.column_name !~* '(verified|confirmed|_at$|_id$)'
  LOOP
    EXECUTE format(
      'UPDATE public.%I SET %I = %s WHERE organization_id = %L AND %I IS NOT NULL',
      r.tbl, r.col,
      CASE WHEN r.is_email
        THEN '''test+'' || substr(md5(id::text), 1, 10) || ''@example.invalid'''
        ELSE '''09'' || lpad((abs((''x'' || substr(md5(id::text), 1, 8))::bit(32)::int) % 100000000)::text, 8, ''0'')'
      END, v_target, r.col);
  END LOOP;

  -- Cắt đính kèm thu chi — chỗ DUY NHẤT app có nút xoá file storage.
  EXECUTE format('UPDATE public.income_expenses SET attachments = ''[]''::jsonb
                  WHERE organization_id = %L AND attachments <> ''[]''::jsonb', v_target);
  EXECUTE format('UPDATE public.income_expense_batches SET attachments = ''[]''::jsonb
                  WHERE organization_id = %L AND attachments <> ''[]''::jsonb', v_target);

  ALTER TABLE public.approval_rule_sets ENABLE ALWAYS TRIGGER a00_rule_set_immutable;
  ALTER TABLE public.approval_rules ENABLE ALWAYS TRIGGER a00_rules_immutable;

  UPDATE clone_org.sync_log
     SET finished_at = now(), ok = true, rows_copied = v_total,
         detail = jsonb_build_object('counts', v_counts)
   WHERE id = v_log_id;

  RETURN jsonb_build_object('ok', true, 'rows', v_total,
                            'tables', (SELECT count(*) FROM jsonb_object_keys(v_counts)),
                            'at', now());
END
$_$;








--
-- Name: map(uuid); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.map(p uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'clone_org'
    AS $$
  SELECT COALESCE((SELECT m.new_id FROM clone_org.idmap m WHERE m.old_id = p), p);
$$;








--
-- Name: map_arr(uuid[]); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.map_arr(p uuid[]) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'clone_org'
    AS $$
  SELECT CASE WHEN p IS NULL THEN NULL ELSE
    (SELECT array_agg(clone_org.map(x) ORDER BY o) FROM unnest(p) WITH ORDINALITY t(x, o)) END;
$$;








--
-- Name: map_strict(uuid); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.map_strict(p uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'clone_org'
    AS $$
  SELECT (SELECT m.new_id FROM clone_org.idmap m WHERE m.old_id = p);
$$;








--
-- Name: map_text(text); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.map_text(p text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'clone_org'
    AS $$
DECLARE u text; r text := p; n uuid;
BEGIN
  IF p IS NULL OR p !~ '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-' THEN RETURN p; END IF;
  FOR u IN SELECT DISTINCT m[1] FROM regexp_matches(
      p, '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})', 'g') m
  LOOP
    SELECT i.new_id INTO n FROM clone_org.idmap i WHERE i.old_id = u::uuid;
    IF n IS NOT NULL THEN r := replace(r, u, n::text); END IF;
  END LOOP;
  RETURN r;
END $$;








--
-- Name: run_pending_sync(); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.run_pending_sync() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'clone_org'
    AS $$
DECLARE req record; v_res jsonb;
BEGIN
  -- Không chờ: lượt sau (15 giây nữa) sẽ nhặt tiếp.
  SELECT * INTO req FROM clone_org.sync_request
   WHERE state = 'PENDING' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN RETURN; END IF;

  UPDATE clone_org.sync_request SET state = 'RUNNING', started_at = now() WHERE id = req.id;

  BEGIN
    EXECUTE 'SET LOCAL session_replication_role = replica';
    v_res := clone_org.do_sync(req.requested_by);
    UPDATE clone_org.sync_request
       SET state = 'DONE', finished_at = now(), result = v_res WHERE id = req.id;
  EXCEPTION WHEN OTHERS THEN
    -- Khối con rollback nên bản sao dở dang bị huỷ sạch; chỉ ghi lại lỗi.
    UPDATE clone_org.sync_request
       SET state = 'ERROR', finished_at = now(), error_text = SQLSTATE || ': ' || SQLERRM
     WHERE id = req.id;
  END;
END
$$;








--
-- Name: tables_to_clone(); Type: FUNCTION; Schema: clone_org; Owner: -
--

CREATE FUNCTION clone_org.tables_to_clone() RETURNS TABLE(tbl text, has_uuid_id boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'clone_org'
    AS $$
  SELECT c.relname::text,
         EXISTS (SELECT 1 FROM pg_attribute a
                 WHERE a.attrelid = c.oid AND a.attname = 'id'
                   AND a.atttypid = 'uuid'::regtype AND a.attnum > 0 AND NOT a.attisdropped)
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relispartition
    AND EXISTS (SELECT 1 FROM pg_attribute a
                WHERE a.attrelid = c.oid AND a.attname = 'organization_id'
                  AND a.attnum > 0 AND NOT a.attisdropped)
    AND c.relname NOT LIKE 'network\_%'
    AND NOT EXISTS (SELECT 1 FROM clone_org.skip_table s WHERE s.tbl = c.relname)
  ORDER BY c.relname;
$$;








--
-- Name: _autofill_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._autofill_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  j jsonb := to_jsonb(NEW);
  v uuid;
  n_orgs int;
  PROD constant uuid := 'aaaa0000-0000-4000-8000-000000000001';
BEGIN
  IF NEW.organization_id IS NOT NULL THEN RETURN NEW; END IF;
  IF (j->>'building_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.buildings WHERE id=(j->>'building_id')::uuid; END IF;
  IF v IS NULL AND (j->>'room_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.rooms WHERE id=(j->>'room_id')::uuid; END IF;
  IF v IS NULL AND (j->>'contract_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.contracts WHERE id=(j->>'contract_id')::uuid; END IF;
  IF v IS NULL AND (j->>'invoice_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.invoices WHERE id=(j->>'invoice_id')::uuid; END IF;
  IF v IS NULL AND (j->>'income_expense_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.income_expenses WHERE id=(j->>'income_expense_id')::uuid; END IF;
  IF v IS NULL AND (j->>'account_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.accounts WHERE id=(j->>'account_id')::uuid; END IF;
  IF v IS NULL AND (j->>'customer_id') IS NOT NULL THEN SELECT organization_id INTO v FROM public.customers WHERE id=(j->>'customer_id')::uuid; END IF;
  -- Membership: CHỈ khi user thuộc đúng MỘT org ACTIVE (uuid-safe, không dùng min()).
  IF v IS NULL AND (j->>'user_id') IS NOT NULL THEN
    SELECT (array_agg(DISTINCT organization_id))[1], count(DISTINCT organization_id)
      INTO v, n_orgs
      FROM public.organization_memberships
     WHERE user_id=(j->>'user_id')::uuid AND status='ACTIVE';
    IF n_orgs IS DISTINCT FROM 1 THEN v := NULL; END IF;
  END IF;

  IF v IS NULL THEN
    BEGIN
      INSERT INTO public.authorization_migration_exceptions(table_name, reason, details)
      VALUES (TG_TABLE_NAME, 'PROD_DEFAULT_FALLBACK at insert',
              jsonb_build_object('source', '_autofill_org', 'at', now(),
                                 'new_row_keys', (SELECT jsonb_object_agg(k, j->k)
                                                  FROM unnest(ARRAY['id','user_id','building_id','room_id','contract_id','invoice_id','account_id','customer_id']) AS k
                                                  WHERE j ? k)));
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    v := PROD;
  END IF;

  NEW.organization_id := v;
  RETURN NEW;
END;
$$;








--
-- Name: _chung_building(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._chung_building(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- Tenant thật: toà chung hệ thống = toà ảo không thuộc demo (hiện là
  -- "Kho Văn Phòng Chung"). Không per-user nữa — tránh đẻ nhiều toà "Chung".
  IF NOT (p_user_id = ANY (public.demo_user_ids())) THEN
    SELECT id INTO v_id FROM buildings
     WHERE is_virtual = true AND deleted_at IS NULL
       AND NOT (user_id = ANY (public.demo_user_ids()))
     ORDER BY created_at LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;

  -- Fallback (demo, hoặc tenant chưa có toà chung): hành vi cũ
  SELECT id INTO v_id FROM buildings
   WHERE user_id = p_user_id AND is_virtual = true AND name = 'Chung'
     AND deleted_at IS NULL
   ORDER BY created_at LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO buildings (user_id, name, type, status, province, district, ward, is_virtual)
  VALUES (p_user_id, 'Chung', 'APARTMENT'::building_type, 'ACTIVE'::building_status, '—', '—', '—', true)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;








--
-- Name: _collector_thu_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._collector_thu_account(p_collector uuid) RETURNS uuid
