--
-- Name: _deposit_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._deposit_account(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id
    FROM accounts
   WHERE user_id = p_user_id AND deleted_at IS NULL
     AND name = 'CỌC (giữ hộ khách)'
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO accounts (user_id, name, description, initial_amount)
  VALUES (p_user_id, 'CỌC (giữ hộ khách)',
          'Sổ giữ tiền cọc của khách (mọi toà). Số dư = tổng cọc đang giữ. Thanh lý: chi trả khách + chuyển phần cấn nợ sang sổ vận hành.', 0)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;








--
-- Name: _diff_changed_fields(jsonb, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._diff_changed_fields(p_before jsonb, p_after jsonb, p_ignore text[] DEFAULT ARRAY[]::text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[])
  FROM (
    SELECT key
    FROM jsonb_each(p_after)
    WHERE NOT (key = ANY (p_ignore))
      AND COALESCE(p_before -> key, 'null'::jsonb) IS DISTINCT FROM (p_after -> key)
    UNION
    SELECT key
    FROM jsonb_each(p_before)
    WHERE NOT (key = ANY (p_ignore))
      AND COALESCE(p_after -> key, 'null'::jsonb) IS DISTINCT FROM (p_before -> key)
  ) AS keys;
$$;








--
-- Name: _ensure_initial_deposit_voucher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_initial_deposit_voucher(p_contract_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c RECORD; v_building uuid; v_account uuid; v_type uuid;
  v_amount numeric(15,2); v_date date; v_existing_acc uuid;
BEGIN
  SELECT * INTO v_c FROM contracts WHERE id = p_contract_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- Đã có phiếu thu cọc? → dùng đúng sổ đang chứa cọc.
  SELECT ie.account_id INTO v_existing_acc
    FROM income_expenses ie
   WHERE ie.contract_id = p_contract_id AND ie.type = 'INCOME'
     AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
     AND public.ie_has_deposit_item(ie.id)
   ORDER BY ie.voucher_date LIMIT 1;
  IF v_existing_acc IS NOT NULL THEN RETURN v_existing_acc; END IF;

  v_amount := COALESCE(v_c.deposit_paid, 0);
  v_account := public._deposit_account(v_c.user_id);   -- sổ CỌC
  IF v_amount <= 0 OR v_c.room_id IS NULL THEN RETURN v_account; END IF;

  SELECT building_id INTO v_building FROM rooms WHERE id = v_c.room_id;
  IF v_building IS NULL THEN RETURN v_account; END IF;

  v_date := COALESCE(v_c.signed_date, v_c.start_date, public.org_today_v1(NULL));
  v_type := public._termination_ensure_type(v_c.user_id, 'income', 'Tiền cọc');
  UPDATE income_expense_types SET is_deposit = TRUE WHERE id = v_type AND is_deposit IS DISTINCT FROM TRUE;

  INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, voucher_date, total_amount, approval_status, notes)
  VALUES (v_c.user_id, 'INCOME', 'Cọc giữ phòng (ghi nhận ban đầu) — HĐ ' || COALESCE(v_c.contract_number, p_contract_id::text),
          v_building, v_c.room_id, p_contract_id, v_account, v_date, v_amount, 'APPROVED',
          '[BACKFILL_INITIAL_DEPOSIT] Ghi nhận cọc ban đầu (giả định đã thu đủ) vào sổ CỌC.');
  -- item
  INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
  SELECT ie.id, v_type, 'Tiền cọc giữ phòng (ghi nhận ban đầu)', 1, v_amount, v_date, v_date
    FROM income_expenses ie WHERE ie.contract_id = p_contract_id AND ie.account_id = v_account
      AND ie.notes LIKE '[BACKFILL_INITIAL_DEPOSIT]%' AND ie.deleted_at IS NULL
    ORDER BY ie.created_at DESC LIMIT 1;

  RETURN v_account;
END $$;








--
-- Name: _eval_approval_rule(uuid, numeric, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._eval_approval_rule(p_org uuid, p_amount numeric, p_txn_type text, p_system_source text, p_category uuid, p_cashbook uuid, p_building uuid) RETURNS TABLE(rule_set_id uuid, version integer, rule_id uuid, effect text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH aset AS (
    SELECT id, version FROM public.approval_rule_sets
    WHERE organization_id=p_org AND transaction_domain='FINANCIAL_VOUCHER' AND status='ACTIVE'
      AND effective_from <= now() AND (effective_to IS NULL OR effective_to > now())
    ORDER BY version DESC LIMIT 1
  ),
  matches AS (
    SELECT r.id, r.effect, r.priority, r.is_fallback, s.id AS rs_id, s.version AS rs_ver,
      CASE WHEN r.effect='DENY' THEN 0
           WHEN r.effect='REQUIRE_APPROVAL' AND r.force_match THEN 1
           ELSE 2 END AS eff_rank
    FROM public.approval_rules r JOIN aset s ON r.rule_set_id=s.id
    WHERE r.active AND (
      r.is_fallback OR (
        (r.transaction_type IS NULL OR r.transaction_type=p_txn_type)
        AND (r.system_source IS NULL OR r.system_source=p_system_source)
        AND (r.category_id IS NULL OR r.category_id=p_category)
        AND (r.cashbook_id IS NULL OR r.cashbook_id=p_cashbook)
        AND (r.building_id IS NULL OR r.building_id=p_building)
        AND (r.amount_min IS NULL OR p_amount >= r.amount_min)
        AND (r.amount_max IS NULL OR p_amount <= r.amount_max)
      )
    )
  )
  SELECT rs_id, rs_ver, id, effect FROM matches
  ORDER BY is_fallback ASC, eff_rank ASC, priority ASC LIMIT 1;
$$;








--
-- Name: _guard_ie_financial_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_ie_financial_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF current_user IN ('authenticated','anon') THEN
    IF TG_OP='INSERT' THEN
      IF NEW.approved_by IS NOT NULL AND NEW.approved_by <> v_uid THEN
        RAISE EXCEPTION 'Không được đặt approved_by cho người khác (chống giả mạo audit)' USING ERRCODE='42501';
      END IF;
      IF NEW.posting_id IS NOT NULL OR NEW.approval_request_id IS NOT NULL
         OR NEW.posted_at_v2 IS NOT NULL OR NEW.reversed_by_posting_id IS NOT NULL THEN
        RAISE EXCEPTION 'Posting metadata chỉ được đặt bởi RPC duyệt/hạch toán' USING ERRCODE='42501';
      END IF;
    ELSIF TG_OP='UPDATE' THEN
      IF NEW.approved_by IS DISTINCT FROM OLD.approved_by
         AND NEW.approved_by IS NOT NULL AND NEW.approved_by <> v_uid THEN
        RAISE EXCEPTION 'Không được đổi approved_by sang người khác' USING ERRCODE='42501';
      END IF;
      IF NEW.posting_id IS DISTINCT FROM OLD.posting_id
         OR NEW.approval_request_id IS DISTINCT FROM OLD.approval_request_id
         OR NEW.posted_at_v2 IS DISTINCT FROM OLD.posted_at_v2
         OR NEW.reversed_by_posting_id IS DISTINCT FROM OLD.reversed_by_posting_id THEN
        RAISE EXCEPTION 'Posting metadata bất biến từ phía client' USING ERRCODE='42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: _guard_invoice_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_invoice_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF current_user IN ('authenticated','anon') THEN
    IF TG_OP='INSERT' AND NEW.approved_by IS NOT NULL AND NEW.approved_by <> v_uid THEN
      RAISE EXCEPTION 'Không được đặt approved_by hoá đơn cho người khác' USING ERRCODE='42501';
    ELSIF TG_OP='UPDATE' AND NEW.approved_by IS DISTINCT FROM OLD.approved_by
          AND NEW.approved_by IS NOT NULL AND NEW.approved_by <> v_uid THEN
      RAISE EXCEPTION 'Không được đổi approved_by hoá đơn sang người khác' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: _guard_profit_payout_insert_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_profit_payout_insert_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_core_writer boolean;
  v_has_reservation boolean;
  v_has_request boolean;
  v_is_payout boolean := false;
BEGIN
  IF NEW.shareholder_id IS NOT NULL THEN
    v_is_payout := true;
  END IF;
  IF NEW.system_source = 'profit.distribution' THEN
    v_is_payout := true;
  END IF;
  IF TG_OP = 'UPDATE' AND (
    OLD.shareholder_id IS NOT NULL
    OR OLD.system_source = 'profit.distribution'
  ) THEN
    v_is_payout := true;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.profit_payout_reservations reservation
    WHERE reservation.payout_voucher_id = NEW.id
  ) INTO v_has_reservation;
  SELECT EXISTS (
    SELECT 1
    FROM public.approval_requests request_row
    WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
      AND request_row.subject_id = NEW.id
      AND request_row.system_source = 'profit.distribution'
  ) INTO v_has_request;
  v_is_payout := v_is_payout OR v_has_reservation OR v_has_request;

  IF v_is_payout THEN
    IF NEW.shareholder_id IS NULL THEN
      RAISE EXCEPTION 'Shareholder payout cannot clear its shareholder identity'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.account_id IS NULL THEN
      RAISE EXCEPTION 'Shareholder payout requires a real cashbook account'
        USING ERRCODE = '42501';
    END IF;
    PERFORM 1
    FROM public.accounts account_row
    WHERE account_row.id = NEW.account_id
      AND account_row.organization_id = NEW.organization_id
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Shareholder payout account must be an active real cashbook in the same organization'
        USING ERRCODE = '42501';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.profit_payout_reservations reservation
      WHERE reservation.payout_voucher_id = NEW.id
        AND (
          reservation.organization_id IS DISTINCT FROM NEW.organization_id
          OR reservation.shareholder_id IS DISTINCT FROM NEW.shareholder_id
        )
    ) THEN
      RAISE EXCEPTION 'Shareholder payout no longer matches its reservation identity'
        USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.approval_requests request_row
      WHERE request_row.subject_type = 'FINANCIAL_VOUCHER'
        AND request_row.subject_id = NEW.id
        AND request_row.system_source = 'profit.distribution'
        AND (
          request_row.organization_id IS DISTINCT FROM NEW.organization_id
          OR request_row.cashbook_id IS DISTINCT FROM NEW.account_id
        )
    ) THEN
      RAISE EXCEPTION 'Shareholder payout no longer matches its approval request'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;

  IF v_is_payout
     AND (
       TG_OP = 'INSERT'
       OR NEW.shareholder_id IS DISTINCT FROM OLD.shareholder_id
     )
     AND NOT v_core_writer THEN
    RAISE EXCEPTION 'Shareholder payout must use distribute_shareholder_profit_v1'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;








--
-- Name: _internal_settlement_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._internal_settlement_account(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id
    FROM accounts
   WHERE user_id = p_user_id AND deleted_at IS NULL
     AND name = 'Cấn trừ thanh lý (nội bộ)'
   ORDER BY created_at LIMIT 1;
  IF v_id IS NOT NULL THEN
    UPDATE accounts SET is_virtual = true WHERE id = v_id AND is_virtual IS DISTINCT FROM true;
    RETURN v_id;
  END IF;

  INSERT INTO accounts (user_id, name, description, initial_amount, is_virtual)
  VALUES (p_user_id, 'Cấn trừ thanh lý (nội bộ)',
          'Sổ BÚT TOÁN (không phải tiền thật): cặp cấn cọc → doanh thu khi thanh lý/bỏ cọc chạy cả 2 chân trên sổ này, mỗi thương vụ net 0.',
          0, true)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;








--
-- Name: _invoice_audit_excess_amounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._invoice_audit_excess_amounts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_changed text[];
BEGIN
  IF v_actor IS NOT NULL THEN
    SELECT full_name INTO v_actor_name FROM public.profiles WHERE id = v_actor;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.source_invoice_id IS NULL THEN
      RETURN NEW;
    END IF;
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name, after
    ) VALUES (
      NEW.source_invoice_id, 'excess', NEW.id, 'INSERT',
      v_actor, v_actor_name, to_jsonb(NEW)
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.source_invoice_id IS NULL AND OLD.source_invoice_id IS NULL THEN
      RETURN NEW;
    END IF;
    v_changed := public._diff_changed_fields(to_jsonb(OLD), to_jsonb(NEW));
    IF array_length(v_changed, 1) IS NULL THEN
      RETURN NEW;
    END IF;
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name,
      before, after, changed_fields
    )
    SELECT DISTINCT t.invoice_id, 'excess', NEW.id, 'UPDATE',
      v_actor, v_actor_name, to_jsonb(OLD), to_jsonb(NEW), v_changed
    FROM (VALUES (NEW.source_invoice_id), (OLD.source_invoice_id)) AS t(invoice_id)
    WHERE t.invoice_id IS NOT NULL;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.source_invoice_id IS NULL THEN
      RETURN OLD;
    END IF;
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name, before
    ) VALUES (
      OLD.source_invoice_id, 'excess', OLD.id, 'DELETE',
      v_actor, v_actor_name, to_jsonb(OLD)
    );
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;








--
-- Name: _invoice_audit_income_expenses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._invoice_audit_income_expenses() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_before jsonb;
  v_after jsonb;
  v_changed text[];
  -- updated_at: đổi mỗi lần ghi; has_restricted_item/kqkd_amount: cột dẫn xuất
  -- do trigger khác tính lại khi items đổi — ghi riêng chỉ tạo nhiễu.
  v_ignore CONSTANT text[] := ARRAY[
    'updated_at',
    'has_restricted_item',
    'kqkd_amount'
  ];
BEGIN
  IF v_actor IS NOT NULL THEN
    SELECT full_name INTO v_actor_name FROM public.profiles WHERE id = v_actor;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.invoice_id IS NULL THEN
      RETURN NEW;
    END IF;
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name, after
    ) VALUES (
      NEW.invoice_id, 'receipt', NEW.id, 'INSERT',
      v_actor, COALESCE(v_actor_name, NEW.creator_name), to_jsonb(NEW)
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.invoice_id IS NULL AND OLD.invoice_id IS NULL THEN
      RETURN NEW;
    END IF;
    v_before := to_jsonb(OLD);
    v_after := to_jsonb(NEW);
    v_changed := public._diff_changed_fields(v_before, v_after, v_ignore);
    IF array_length(v_changed, 1) IS NULL THEN
      RETURN NEW;
    END IF;
    -- Phiếu đổi hoá đơn liên kết: ghi vào cả HĐ cũ lẫn HĐ mới.
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name,
      before, after, changed_fields
    )
    SELECT DISTINCT t.invoice_id, 'receipt', NEW.id, 'UPDATE',
      v_actor, COALESCE(v_actor_name, NEW.creator_name),
      v_before, v_after, v_changed
    FROM (VALUES (NEW.invoice_id), (OLD.invoice_id)) AS t(invoice_id)
    WHERE t.invoice_id IS NOT NULL;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.invoice_id IS NULL THEN
      RETURN OLD;
    END IF;
    INSERT INTO public.invoice_audit_log (
      invoice_id, entity, entity_id, action, actor_id, actor_name, before
    ) VALUES (
      OLD.invoice_id, 'receipt', OLD.id, 'DELETE',
      v_actor, COALESCE(v_actor_name, OLD.creator_name), to_jsonb(OLD)
    );
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;








