--
-- Name: _post_financial_voucher(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._post_financial_voucher(p_voucher uuid, p_request uuid, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_posting uuid := gen_random_uuid();
BEGIN
  UPDATE public.income_expenses
     SET approval_status='APPROVED', approved_by=p_actor, approved_at=now(),
         approval_request_id=p_request, posting_id=v_posting, posted_at_v2=now()
   WHERE id=p_voucher AND deleted_at IS NULL;
  UPDATE public.approval_requests
     SET state='POSTED', posted_at=now(), posted_event_id=v_posting, version=version+1
   WHERE id=p_request;
  RETURN v_posting;
END; $$;








--
-- Name: _profit_allocation_reserved_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_allocation_reserved_v2(p_profit_allocation_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE(sum(reservation.amount), 0)::numeric
  FROM public.profit_payout_reservations reservation
  JOIN public.income_expenses voucher
    ON voucher.id = reservation.payout_voucher_id
   AND voucher.organization_id = reservation.organization_id
   AND voucher.deleted_at IS NULL
  LEFT JOIN public.approval_requests request_row
    ON request_row.id = reservation.approval_request_id
  WHERE reservation.profit_allocation_id = p_profit_allocation_id
    AND (
      (
        reservation.reservation_source = 'LEGACY_BACKFILL'
        AND voucher.approval_status IN ('UNAPPROVED', 'APPROVED')
      )
      OR (
        reservation.reservation_source = 'CANONICAL_V1'
        AND request_row.state IN ('PENDING_APPROVAL', 'POSTED')
      )
    );
$$;








--
-- Name: _profit_assert_authorized_v2(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_assert_authorized_v2(p_organization_id uuid, p_permission_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.organizations o
  WHERE o.id = p_organization_id
    AND o.status = 'ACTIVE'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization is missing or inactive' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.organization_memberships m
  WHERE m.organization_id = p_organization_id
    AND m.user_id = v_actor
    AND m.status = 'ACTIVE'
    AND m.valid_from <= clock_timestamp()
    AND (m.valid_to IS NULL OR m.valid_to > clock_timestamp())
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active organization membership required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.authorize_v2(
       p_permission_key, p_organization_id, 'ORGANIZATION', NULL
     ) THEN
    RAISE EXCEPTION 'Permission denied: %', p_permission_key
      USING ERRCODE = '42501';
  END IF;
END
$$;








--
-- Name: _profit_can_read_audit_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_can_read_audit_v2(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.organization_memberships m
      WHERE m.organization_id = p_organization_id
        AND m.user_id = auth.uid()
        AND m.status = 'ACTIVE'
        AND m.valid_from <= clock_timestamp()
        AND (m.valid_to IS NULL OR m.valid_to > clock_timestamp())
    )
    AND (
      public.is_super_admin()
      OR public.authorize_v2(
        'shareholder_profit.lock', p_organization_id, 'ORGANIZATION', NULL
      )
    );
$$;








