--
-- Name: _profit_close_preview_core_v2(uuid, date, uuid[], jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_close_preview_core_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[], p_adjustments jsonb, p_permission_key text, p_lock_sources boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_period_end date;
  v_captured_at timestamptz := clock_timestamp();
  v_result jsonb;
  v_source_consistent boolean;
  v_adj record;
BEGIN
  IF p_period_month IS NULL
     OR p_period_month <> date_trunc('month', p_period_month)::date THEN
    RAISE EXCEPTION 'period_month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;
  v_period_end := (p_period_month + interval '1 month - 1 day')::date;

  PERFORM public._profit_assert_authorized_v2(
    p_organization_id, p_permission_key
  );

  IF p_building_ids IS NULL OR cardinality(p_building_ids) = 0 THEN
    RAISE EXCEPTION 'At least one building is required' USING ERRCODE = '22023';
  END IF;
  IF array_position(p_building_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'building_ids cannot contain NULL' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM unnest(p_building_ids) x)
     <> (SELECT count(DISTINCT x) FROM unnest(p_building_ids) x) THEN
    RAISE EXCEPTION 'building_ids contains duplicates' USING ERRCODE = '22023';
  END IF;

  -- Keep the child-before-parent order introduced by the deadlock fix while
  -- restoring the earlier Profit Close V2 calculation contract.
  IF p_lock_sources THEN
    LOCK TABLE public.income_expense_items,
               public.income_expenses,
               public.income_expense_types,
               public.invoices,
               public.building_shareholders,
               public.shareholders,
               public.profit_managers,
               public.profit_manager_salaries,
               public.profit_manager_salary_buildings,
               public.staff_assignments,
               public.roles,
               public.area_buildings,
               public.super_admins
      IN SHARE MODE;
  END IF;

  PERFORM 1
  FROM public.buildings b
  WHERE b.id = ANY(p_building_ids)
    AND b.organization_id = p_organization_id
    AND b.deleted_at IS NULL
    AND b.is_virtual = false
  FOR SHARE;
  IF (SELECT count(*)
      FROM public.buildings b
      WHERE b.id = ANY(p_building_ids)
        AND b.organization_id = p_organization_id
        AND b.deleted_at IS NULL
        AND b.is_virtual = false)
     <> cardinality(p_building_ids) THEN
    RAISE EXCEPTION 'Every building must be an active real building in the organization'
      USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_super_admin() AND EXISTS (
    SELECT 1
    FROM unnest(p_building_ids) bid
    WHERE NOT public.authorize_v2(
      p_permission_key, p_organization_id, 'BUILDING', bid
    )
  ) THEN
    RAISE EXCEPTION 'Permission does not cover every requested building'
      USING ERRCODE = '42501';
  END IF;

  -- fa_* is the canonical implementation but applies legacy building scope
  -- internally. Fail explicitly instead of silently treating hidden data as 0.
  IF EXISTS (
    SELECT 1
    FROM unnest(p_building_ids) bid
    WHERE NOT COALESCE(public.can_access_building(bid), false)
  ) THEN
    RAISE EXCEPTION
      'Canonical accrual scope denied one or more buildings; no legacy fallback is allowed'
      USING ERRCODE = '42501';
  END IF;

  p_adjustments := COALESCE(p_adjustments, '[]'::jsonb);
  IF jsonb_typeof(p_adjustments) <> 'array' THEN
    RAISE EXCEPTION 'adjustments must be a JSON array' USING ERRCODE = '22023';
  END IF;

  IF (SELECT count(*)
      FROM jsonb_to_recordset(p_adjustments)
        AS a(building_id uuid, adjustment_amount numeric, adjustment_reason text))
     <> (SELECT count(DISTINCT a.building_id)
         FROM jsonb_to_recordset(p_adjustments)
           AS a(building_id uuid, adjustment_amount numeric, adjustment_reason text)) THEN
    RAISE EXCEPTION 'adjustments contains duplicate building_id values'
      USING ERRCODE = '22023';
  END IF;

  FOR v_adj IN
    SELECT *
    FROM jsonb_to_recordset(p_adjustments)
      AS a(building_id uuid, adjustment_amount numeric, adjustment_reason text)
  LOOP
    IF v_adj.building_id IS NULL
       OR NOT (v_adj.building_id = ANY(p_building_ids)) THEN
      RAISE EXCEPTION 'Every adjustment must target a requested building'
        USING ERRCODE = '22023';
    END IF;
    IF v_adj.adjustment_amount IS NULL
       OR v_adj.adjustment_amount::text = 'NaN'
       OR round(v_adj.adjustment_amount, 2) <> v_adj.adjustment_amount
       OR abs(v_adj.adjustment_amount) > 9999999999999.99 THEN
      RAISE EXCEPTION 'adjustment_amount must be a finite numeric with at most 2 decimals'
        USING ERRCODE = '22023';
    END IF;
    IF p_lock_sources AND v_adj.adjustment_amount <> 0
       AND (
         v_adj.adjustment_reason IS NULL
         OR char_length(btrim(v_adj.adjustment_reason)) NOT BETWEEN 8 AND 500
       ) THEN
      RAISE EXCEPTION 'A non-zero adjustment requires a reason of 8..500 characters'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- Legacy mappings to inactive/soft-deleted shareholders are ignored, matching
  -- the established frontend behavior. Missing IDs and cross-org links remain
  -- structural corruption and fail closed.
  IF EXISTS (
    SELECT 1
    FROM public.building_shareholders bs
    LEFT JOIN public.shareholders sh ON sh.id = bs.shareholder_id
    WHERE bs.building_id = ANY(p_building_ids)
      AND (
        bs.organization_id IS DISTINCT FROM p_organization_id
        OR sh.id IS NULL
        OR sh.organization_id IS DISTINCT FROM p_organization_id
      )
  ) THEN
    RAISE EXCEPTION 'Shareholder configuration contains missing or cross-organization rows'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.building_shareholders bs
    JOIN public.shareholders sh
      ON sh.id = bs.shareholder_id
     AND sh.organization_id = p_organization_id
     AND sh.is_active
     AND sh.deleted_at IS NULL
    WHERE bs.building_id = ANY(p_building_ids)
      AND bs.organization_id = p_organization_id
    GROUP BY bs.building_id
    HAVING sum(bs.percent) > 100
  ) THEN
    RAISE EXCEPTION 'Shareholder percentages exceed 100 for a building'
      USING ERRCODE = '23514';
  END IF;

  -- Active rules that reference no manager are structurally corrupt. Rules for
  -- an existing inactive/soft-deleted manager are legacy history and ignored,
  -- including their legacy NULL organization_id fields. A live manager's active
  -- rule and mapping must all be explicitly scoped to this organization.
  IF EXISTS (
    SELECT 1
    FROM public.profit_manager_salary_buildings rb
    JOIN public.profit_manager_salaries s ON s.id = rb.salary_id
    LEFT JOIN public.profit_managers m ON m.id = s.manager_id
    WHERE rb.building_id = ANY(p_building_ids)
      AND s.is_active
      AND (
        m.id IS NULL
        OR (
          m.is_active
          AND m.deleted_at IS NULL
          AND (
            rb.organization_id IS DISTINCT FROM p_organization_id
            OR s.organization_id IS DISTINCT FROM p_organization_id
            OR m.organization_id IS DISTINCT FROM p_organization_id
          )
        )
      )
  ) THEN
    RAISE EXCEPTION
      'Management salary configuration contains a missing manager or live cross/null-organization rows'
      USING ERRCODE = '55000';
  END IF;

  WITH selected AS MATERIALIZED (
    SELECT b.id AS building_id, b.name AS building_name, b.user_id AS owner_user_id
    FROM public.buildings b
    WHERE b.id = ANY(p_building_ids)
      AND b.organization_id = p_organization_id
      AND b.deleted_at IS NULL
      AND b.is_virtual = false
  ),
  adjustments AS MATERIALIZED (
    SELECT
      a.building_id,
      a.adjustment_amount::numeric AS adjustment_amount,
      CASE WHEN a.adjustment_amount <> 0 THEN btrim(a.adjustment_reason) END
        AS adjustment_reason
    FROM jsonb_to_recordset(p_adjustments)
      AS a(building_id uuid, adjustment_amount numeric, adjustment_reason text)
  ),
  pnl AS MATERIALIZED (
    SELECT
      x.building_id,
      sum(x.revenue)::numeric AS revenue,
      sum(x.expense)::numeric AS expense,
      sum(x.net)::numeric AS net
    FROM public.fa_monthly_pnl_accrual(
      p_period_month, v_period_end, p_building_ids
    ) x
    WHERE x.month = p_period_month AND x.is_virtual = false
    GROUP BY x.building_id
  ),
  source_lines AS MATERIALIZED (
    SELECT
      x.month,
      x.voucher_id,
      x.building_id,
      x.building_name,
      x.side,
      x.type_id,
      x.type_name,
      x.category,
      x.amount::numeric AS amount
    FROM public.fa_accrual_allocations(
      p_period_month, v_period_end, p_building_ids
    ) x
    WHERE x.month = p_period_month AND x.is_virtual = false
  ),
  line_totals AS (
    SELECT
      building_id,
      COALESCE(sum(amount) FILTER (WHERE side = 'INCOME'), 0)::numeric AS revenue,
      COALESCE(sum(amount) FILTER (WHERE side = 'EXPENSE'), 0)::numeric AS expense,
      (
        COALESCE(sum(amount) FILTER (WHERE side = 'INCOME'), 0)
        - COALESCE(sum(amount) FILTER (WHERE side = 'EXPENSE'), 0)
      )::numeric AS net
    FROM source_lines
    GROUP BY building_id
  ),
  base AS MATERIALIZED (
    SELECT
      s.building_id,
      s.building_name,
      s.owner_user_id,
      COALESCE(p.revenue, 0)::numeric AS source_revenue,
      COALESCE(p.expense, 0)::numeric AS source_expense,
      COALESCE(p.net, 0)::numeric AS computed_profit,
      COALESCE(a.adjustment_amount, 0)::numeric AS adjustment_amount,
      a.adjustment_reason,
      (COALESCE(p.net, 0) + COALESCE(a.adjustment_amount, 0))::numeric
        AS adjusted_profit
    FROM selected s
    LEFT JOIN pnl p ON p.building_id = s.building_id
    LEFT JOIN adjustments a ON a.building_id = s.building_id
  ),
  management_doc AS MATERIALIZED (
    SELECT public._profit_management_allocations_v2(
      p_organization_id,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object('building_id', building_id, 'base', adjusted_profit)
          ORDER BY building_id
        ) FROM base
      ), '[]'::jsonb)
    ) AS allocations
  ),
  manager_allocations AS MATERIALIZED (
    SELECT x.manager_id, x.building_id, x.amount::numeric AS amount
    FROM management_doc d
    CROSS JOIN LATERAL jsonb_to_recordset(d.allocations)
      AS x(manager_id uuid, building_id uuid, amount numeric)
  ),
  manager_totals AS (
    SELECT building_id, sum(amount)::numeric AS management_salary
    FROM manager_allocations
    GROUP BY building_id
  ),
  with_salary AS MATERIALIZED (
    SELECT
      b.*,
      COALESCE(mt.management_salary, 0)::numeric AS management_salary,
      (b.adjusted_profit - COALESCE(mt.management_salary, 0))::numeric
        AS distributable_profit
    FROM base b
    LEFT JOIN manager_totals mt ON mt.building_id = b.building_id
  ),
  share_config AS MATERIALIZED (
    SELECT
      bs.building_id,
      bs.shareholder_id,
      sh.name AS shareholder_name,
      bs.percent::numeric AS percent
    FROM public.building_shareholders bs
    JOIN public.shareholders sh
      ON sh.id = bs.shareholder_id
     AND sh.organization_id = p_organization_id
     AND sh.is_active
     AND sh.deleted_at IS NULL
    WHERE bs.organization_id = p_organization_id
      AND bs.building_id = ANY(p_building_ids)
  ),
  share_raw AS (
    SELECT
      ws.building_id,
      sc.shareholder_id,
      sc.shareholder_name,
      sc.percent,
      ws.distributable_profit,
      sum(sc.percent) OVER (PARTITION BY ws.building_id) AS total_percent,
      (ws.distributable_profit * sc.percent / 100)::numeric AS raw_amount,
      round(
        ws.distributable_profit
        * sum(sc.percent) OVER (PARTITION BY ws.building_id)
        / 100
      )::numeric AS target_total
    FROM with_salary ws
    JOIN share_config sc ON sc.building_id = ws.building_id
  ),
  share_based AS (
    SELECT
      sr.*,
      CASE
        WHEN sr.target_total >= 0 THEN floor(sr.raw_amount)
        ELSE ceil(sr.raw_amount)
      END::numeric AS base_part
    FROM share_raw sr
  ),
  share_ranked AS (
    SELECT
      sb.*,
      (
        sb.target_total
        - sum(sb.base_part) OVER (PARTITION BY sb.building_id)
      )::numeric AS delta,
      row_number() OVER (
        PARTITION BY sb.building_id
        ORDER BY
          CASE
            WHEN sb.target_total >= 0 THEN sb.raw_amount - floor(sb.raw_amount)
            ELSE ceil(sb.raw_amount) - sb.raw_amount
          END DESC,
          sb.shareholder_id
      ) AS allocation_rank
    FROM share_based sb
  ),
  shareholder_allocations AS MATERIALIZED (
    SELECT
      building_id,
      shareholder_id,
      shareholder_name,
      percent,
      (
        base_part
        + CASE
            WHEN delta > 0 AND allocation_rank <= delta THEN 1
            WHEN delta < 0 AND allocation_rank <= abs(delta) THEN -1
            ELSE 0
          END
      )::numeric AS amount
    FROM share_ranked
  ),
  shareholder_json AS (
    SELECT
      building_id,
      jsonb_agg(
        jsonb_build_object(
          'shareholder_id', shareholder_id,
          'shareholder_name', shareholder_name,
          'percent', percent,
          'amount', amount
        ) ORDER BY shareholder_id
      ) AS allocations,
      sum(percent)::numeric AS total_percent,
      sum(amount)::numeric AS allocated_amount
    FROM shareholder_allocations
    GROUP BY building_id
  ),
  manager_json AS (
    SELECT
      ma.building_id,
      jsonb_agg(
        jsonb_build_object(
          'manager_id', ma.manager_id,
          'manager_name', m.name,
          'amount', ma.amount
        ) ORDER BY ma.manager_id
      ) AS allocations
    FROM manager_allocations ma
    JOIN public.profit_managers m ON m.id = ma.manager_id
    GROUP BY ma.building_id
  ),
  pnl_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'building_id', building_id,
        'building_name', building_name,
        'revenue', source_revenue,
        'expense', source_expense,
        'net', computed_profit
      ) ORDER BY building_id
    ), '[]'::jsonb) AS value
    FROM base
  ),
  line_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'month', month,
        'voucher_id', voucher_id,
        'building_id', building_id,
        'building_name', building_name,
        'side', side,
        'type_id', type_id,
        'type_name', type_name,
        'category', category,
        'amount', amount
      ) ORDER BY building_id, voucher_id, side, type_id NULLS FIRST, amount
    ), '[]'::jsonb) AS value
    FROM source_lines
  ),
  share_config_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'building_id', building_id,
        'shareholder_id', shareholder_id,
        'shareholder_name', shareholder_name,
        'percent', percent
      ) ORDER BY building_id, shareholder_id
    ), '[]'::jsonb) AS value
    FROM share_config
  ),
  manager_rules_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'rule_id', s.id,
        'manager_id', s.manager_id,
        'manager_name', m.name,
        'label', s.label,
        'form', s.form,
        'basis', s.basis,
        'amount', s.amount,
        'percent', s.percent,
        'building_ids', COALESCE((
          SELECT jsonb_agg(rb.building_id ORDER BY rb.building_id)
          FROM public.profit_manager_salary_buildings rb
          WHERE rb.salary_id = s.id
            AND rb.organization_id = p_organization_id
            AND rb.building_id = ANY(p_building_ids)
        ), '[]'::jsonb)
      ) ORDER BY s.id
    ), '[]'::jsonb) AS value
    FROM public.profit_manager_salaries s
    JOIN public.profit_managers m
      ON m.id = s.manager_id
     AND m.organization_id = p_organization_id
     AND m.is_active
     AND m.deleted_at IS NULL
    WHERE s.organization_id = p_organization_id
      AND s.is_active
      AND EXISTS (
        SELECT 1
        FROM public.profit_manager_salary_buildings rb
        WHERE rb.salary_id = s.id
          AND rb.organization_id = p_organization_id
          AND rb.building_id = ANY(p_building_ids)
      )
  ),
  source_document AS MATERIALIZED (
    SELECT jsonb_build_object(
      'algorithm_version', 'profit-close-v2.1',
      'organization_id', p_organization_id,
      'period_month', p_period_month,
      'pnl', p.value,
      'accrual_lines', l.value,
      'shareholder_config', sc.value,
      'manager_salary_rules', mr.value
    ) AS value
    FROM pnl_document p
    CROSS JOIN line_document l
    CROSS JOIN share_config_document sc
    CROSS JOIN manager_rules_document mr
  ),
  source_meta AS (
    SELECT value, md5(value::text) AS source_hash
    FROM source_document
  ),
  building_rows AS MATERIALIZED (
    SELECT
      ws.building_id,
      ws.building_name,
      ws.owner_user_id,
      bh.building_source_hash,
      ws.source_revenue,
      ws.source_expense,
      ws.computed_profit,
      ws.adjustment_amount,
      ws.adjustment_reason,
      ws.adjusted_profit,
      ws.management_salary,
      ws.distributable_profit,
      COALESCE(sj.total_percent, 0)::numeric AS shareholder_percent_total,
      COALESCE(sj.allocated_amount, 0)::numeric AS shareholder_allocated_amount,
      (ws.distributable_profit - COALESCE(sj.allocated_amount, 0))::numeric
        AS unallocated_profit,
      COALESCE(sj.allocations, '[]'::jsonb) AS shareholder_allocations,
      COALESCE(mj.allocations, '[]'::jsonb) AS manager_allocations,
      pm.status AS current_status,
      pm.revision_number AS current_revision_number,
      pm.source_hash AS current_source_hash,
      (pm.id IS NOT NULL AND pm.source_hash IS DISTINCT FROM bh.building_source_hash)
        AS current_hash_mismatch,
      (
        COALESCE(pm.is_stale, false)
        OR (pm.id IS NOT NULL AND pm.source_hash IS DISTINCT FROM bh.building_source_hash)
      ) AS current_is_stale,
      CASE
        WHEN pm.id IS NOT NULL AND pm.source_hash IS DISTINCT FROM bh.building_source_hash
          THEN 'SOURCE_HASH_MISMATCH'
        ELSE pm.stale_reason
      END AS current_stale_reason,
      CASE WHEN pm.id IS NOT NULL THEN to_jsonb(pm) END AS current_snapshot
    FROM with_salary ws
    LEFT JOIN shareholder_json sj ON sj.building_id = ws.building_id
    LEFT JOIN manager_json mj ON mj.building_id = ws.building_id
    CROSS JOIN source_meta sm
    CROSS JOIN LATERAL (
      SELECT md5(jsonb_build_object(
        'algorithm_version', 'profit-close-v2.1',
        'organization_id', p_organization_id,
        'period_month', p_period_month,
        'building_id', ws.building_id,
        -- TOTAL_GROUP salary rules depend on every building in the close set;
        -- include the complete source-base vector, not only this row.
        'source_building_bases', sm.value->'pnl',
        'pnl', jsonb_build_object(
          'revenue', ws.source_revenue,
          'expense', ws.source_expense,
          'net', ws.computed_profit
        ),
        'accrual_lines', COALESCE((
          SELECT jsonb_agg(
            x.value ORDER BY
              x.value->>'voucher_id', x.value->>'side',
              x.value->>'type_id', x.value->>'amount'
          )
          FROM jsonb_array_elements(sm.value->'accrual_lines') x(value)
          WHERE x.value->>'building_id' = ws.building_id::text
        ), '[]'::jsonb),
        'shareholder_config', COALESCE((
          SELECT jsonb_agg(x.value ORDER BY x.value->>'shareholder_id')
          FROM jsonb_array_elements(sm.value->'shareholder_config') x(value)
          WHERE x.value->>'building_id' = ws.building_id::text
        ), '[]'::jsonb),
        'manager_salary_rules', COALESCE((
          SELECT jsonb_agg(x.value ORDER BY x.value->>'rule_id')
          FROM jsonb_array_elements(sm.value->'manager_salary_rules') x(value)
          WHERE x.value->'building_ids' @> to_jsonb(ARRAY[ws.building_id])
        ), '[]'::jsonb)
      )::text) AS building_source_hash
    ) bh
    LEFT JOIN public.profit_monthly pm
      ON pm.organization_id = p_organization_id
     AND pm.building_id = ws.building_id
     AND pm.period_month = p_period_month
  ),
  rows_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'building_id', building_id,
        'building_name', building_name,
        'building_source_hash', building_source_hash,
        'source_revenue', source_revenue,
        'source_expense', source_expense,
        'computed_profit', computed_profit,
        'adjustment_amount', adjustment_amount,
        'adjustment_reason', adjustment_reason,
        'adjusted_profit', adjusted_profit,
        'management_salary', management_salary,
        'distributable_profit', distributable_profit,
        'shareholder_percent_total', shareholder_percent_total,
        'shareholder_allocated_amount', shareholder_allocated_amount,
        'unallocated_profit', unallocated_profit,
        'shareholder_allocations', shareholder_allocations,
        'manager_allocations', manager_allocations,
        'current_status', current_status,
        'current_revision_number', current_revision_number,
        'current_source_hash', current_source_hash,
        'current_hash_mismatch', current_hash_mismatch,
        'current_is_stale', current_is_stale,
        'current_stale_reason', current_stale_reason,
        'current_snapshot', current_snapshot
      ) ORDER BY building_id
    ), '[]'::jsonb) AS value
    FROM building_rows
  ),
  totals_document AS (
    SELECT jsonb_build_object(
      'source_revenue', COALESCE(sum(source_revenue), 0),
      'source_expense', COALESCE(sum(source_expense), 0),
      'computed_profit', COALESCE(sum(computed_profit), 0),
      'adjustment_amount', COALESCE(sum(adjustment_amount), 0),
      'adjusted_profit', COALESCE(sum(adjusted_profit), 0),
      'management_salary', COALESCE(sum(management_salary), 0),
      'distributable_profit', COALESCE(sum(distributable_profit), 0),
      'shareholder_allocated_amount', COALESCE(sum(shareholder_allocated_amount), 0),
      'unallocated_profit', COALESCE(sum(unallocated_profit), 0)
    ) AS value
    FROM building_rows
  ),
  consistency AS (
    SELECT NOT EXISTS (
      SELECT 1
      FROM base b
      LEFT JOIN line_totals lt ON lt.building_id = b.building_id
      WHERE b.source_revenue <> COALESCE(lt.revenue, 0)
         OR b.source_expense <> COALESCE(lt.expense, 0)
         OR b.computed_profit <> COALESCE(lt.net, 0)
    ) AS ok
  )
  SELECT
    jsonb_build_object(
      'algorithm_version', 'profit-close-v2.1',
      'organization_id', p_organization_id,
      'period_month', p_period_month,
      'source_hash', sm.source_hash,
      'source_captured_at', v_captured_at,
      'source_snapshot', sm.value,
      'buildings', rd.value,
      'totals', td.value
    ),
    c.ok
  INTO v_result, v_source_consistent
  FROM source_meta sm
  CROSS JOIN rows_document rd
  CROSS JOIN totals_document td
  CROSS JOIN consistency c;

  IF NOT COALESCE(v_source_consistent, false) THEN
    RAISE EXCEPTION
      'Canonical fa_monthly_pnl_accrual and fa_accrual_allocations totals disagree'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_result;
END
$$;








--
-- Name: FUNCTION _profit_close_preview_core_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[], p_adjustments jsonb, p_permission_key text, p_lock_sources boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._profit_close_preview_core_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[], p_adjustments jsonb, p_permission_key text, p_lock_sources boolean) IS 'Profit Close V2 canonical preview core. Inactive/deleted manager rules and inactive/deleted shareholder mappings are ignored; missing IDs and live cross/null-org configuration fail closed.';








--
-- Name: _profit_current_state_v2(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_current_state_v2(p_organization_id uuid, p_period_month date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH snapshot_rows AS MATERIALIZED (
    SELECT
      pm.*,
      b.name AS building_name,
      COALESCE(b.is_virtual, false) AS building_is_virtual,
      (b.id IS NULL OR b.deleted_at IS NOT NULL) AS building_deleted,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', pa.id,
            'shareholder_id', pa.shareholder_id,
            'percent', pa.percent,
            'amount', pa.amount,
            'created_at', pa.created_at
          ) ORDER BY pa.shareholder_id, pa.id
        )
        FROM public.profit_allocations pa
        WHERE pa.profit_monthly_id = pm.id
      ), '[]'::jsonb) AS shareholder_allocations,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', pma.id,
            'manager_id', pma.manager_id,
            'amount', pma.amount,
            'created_at', pma.created_at
          ) ORDER BY pma.manager_id, pma.id
        )
        FROM public.profit_manager_allocations pma
        WHERE pma.profit_monthly_id = pm.id
      ), '[]'::jsonb) AS manager_allocations
    FROM public.profit_monthly pm
    LEFT JOIN public.buildings b ON b.id = pm.building_id
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
  ),
  before_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'profit_monthly', to_jsonb(sr)
          - 'building_name'
          - 'building_is_virtual'
          - 'building_deleted'
          - 'shareholder_allocations'
          - 'manager_allocations',
        'shareholder_allocations', sr.shareholder_allocations,
        'manager_allocations', sr.manager_allocations
      ) ORDER BY sr.building_id
    ), '[]'::jsonb) AS value
    FROM snapshot_rows sr
  ),
  row_document AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', sr.id,
        'building_id', sr.building_id,
        'building_name', COALESCE(sr.building_name, '[Deleted building]'),
        'is_virtual', sr.building_is_virtual,
        'building_deleted', sr.building_deleted,
        'status', sr.status,
        'computed_profit', sr.computed_profit,
        'adjusted_profit', sr.adjusted_profit,
        'adjustment_amount', sr.adjustment_amount,
        'adjustment_reason', sr.adjustment_reason,
        'management_salary', sr.management_salary,
        'distributable_profit', sr.adjusted_profit - sr.management_salary,
        'source_revenue', sr.source_revenue,
        'source_expense', sr.source_expense,
        'source_hash', sr.source_hash,
        'is_stale', sr.is_stale,
        'stale_reason', sr.stale_reason,
        'revision_number', sr.revision_number,
        'locked_at', sr.locked_at
      ) ORDER BY sr.building_id
    ), '[]'::jsonb) AS value
    FROM snapshot_rows sr
  ),
  snapshot_meta AS (
    SELECT
      COALESCE(array_agg(sr.id ORDER BY sr.id), '{}'::uuid[]) AS snapshot_ids,
      COALESCE(array_agg(sr.building_id ORDER BY sr.building_id), '{}'::uuid[])
        AS building_ids,
      count(*)::integer AS snapshot_count,
      count(*) FILTER (WHERE sr.status = 'LOCKED')::integer AS locked_count,
      count(*) FILTER (WHERE sr.status = 'DRAFT')::integer AS draft_count,
      count(*) FILTER (
        WHERE NOT sr.building_is_virtual AND NOT sr.building_deleted
      )::integer AS active_real_snapshot_count,
      bool_or(sr.building_is_virtual OR sr.building_deleted)
        AS has_out_of_scope_snapshots
    FROM snapshot_rows sr
  ),
  building_meta AS (
    SELECT count(*)::integer AS real_building_count
    FROM public.buildings b
    WHERE b.organization_id = p_organization_id
      AND b.deleted_at IS NULL
      AND b.is_virtual = false
  )
  SELECT jsonb_build_object(
    'organization_id', p_organization_id,
    'period_month', p_period_month,
    'state_hash', md5(bd.value::text),
    'snapshot_ids', to_jsonb(sm.snapshot_ids),
    'building_ids', to_jsonb(sm.building_ids),
    'snapshot_count', sm.snapshot_count,
    'locked_count', sm.locked_count,
    'draft_count', sm.draft_count,
    'real_building_count', bm.real_building_count,
    'active_real_snapshot_count', sm.active_real_snapshot_count,
    'has_out_of_scope_snapshots', COALESCE(sm.has_out_of_scope_snapshots, false),
    'rows', rd.value,
    'before', bd.value
  )
  FROM before_document bd
  CROSS JOIN row_document rd
  CROSS JOIN snapshot_meta sm
  CROSS JOIN building_meta bm;
$$;








--
-- Name: _profit_enrich_state_v3(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_enrich_state_v3(p_document jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_pm public.profit_monthly%ROWTYPE;
BEGIN
  FOR v_row IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(p_document->'rows', '[]'::jsonb)) x(value)
  LOOP
    SELECT * INTO v_pm
    FROM public.profit_monthly pm
    WHERE pm.id = (v_row->>'id')::uuid;

    v_rows := v_rows || jsonb_build_array(
      v_row || jsonb_build_object(
        'shareholder_percent_total', v_pm.shareholder_percent_total,
        'shareholder_allocated_amount', v_pm.shareholder_allocated_amount,
        'unallocated_profit', v_pm.unallocated_profit,
        'unallocated_disposition', v_pm.unallocated_disposition,
        'unallocated_disposition_reason', v_pm.unallocated_disposition_reason
      )
    );
  END LOOP;

  RETURN jsonb_set(COALESCE(p_document, '{}'::jsonb), '{rows}', v_rows, true);
END
$$;








--
-- Name: _profit_enrich_unallocated_v3(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_enrich_unallocated_v3(p_document jsonb, p_adjustments jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_building_id uuid;
  v_disposition text;
  v_reason text;
BEGIN
  FOR v_row IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(p_document->'buildings', '[]'::jsonb)) x(value)
  LOOP
    v_building_id := (v_row->>'building_id')::uuid;

    SELECT
      NULLIF(btrim(a.unallocated_disposition), ''),
      NULLIF(btrim(a.unallocated_disposition_reason), '')
    INTO v_disposition, v_reason
    FROM jsonb_to_recordset(COALESCE(p_adjustments, '[]'::jsonb)) AS a(
      building_id uuid,
      unallocated_disposition text,
      unallocated_disposition_reason text
    )
    WHERE a.building_id = v_building_id
    LIMIT 1;

    v_disposition := COALESCE(
      v_disposition,
      v_row->'current_snapshot'->>'unallocated_disposition'
    );
    v_reason := COALESCE(
      v_reason,
      v_row->'current_snapshot'->>'unallocated_disposition_reason'
    );

    v_rows := v_rows || jsonb_build_array(
      v_row || jsonb_build_object(
        'unallocated_disposition', v_disposition,
        'unallocated_disposition_reason', v_reason
      )
    );
  END LOOP;

  RETURN jsonb_set(COALESCE(p_document, '{}'::jsonb), '{buildings}', v_rows, true);
END
$$;








--
-- Name: _profit_management_allocations_v2(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_management_allocations_v2(p_organization_id uuid, p_building_bases jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH bases AS (
    SELECT x.building_id, x.base::numeric AS base
    FROM jsonb_to_recordset(COALESCE(p_building_bases, '[]'::jsonb))
      AS x(building_id uuid, base numeric)
  ),
  rules AS (
    SELECT
      s.id AS rule_id,
      s.manager_id,
      s.form,
      s.basis,
      s.amount::numeric AS fixed_amount,
      s.percent::numeric AS percent
    FROM public.profit_manager_salaries s
    JOIN public.profit_managers m
      ON m.id = s.manager_id
     AND m.organization_id = p_organization_id
     AND m.is_active
     AND m.deleted_at IS NULL
    WHERE s.organization_id = p_organization_id
      AND s.is_active
  ),
  rule_buildings AS (
    SELECT
      r.*,
      b.building_id,
      b.base,
      count(*) OVER (PARTITION BY r.rule_id) AS building_count,
      sum(GREATEST(b.base, 0)) OVER (PARTITION BY r.rule_id) AS positive_base_sum
    FROM rules r
    JOIN public.profit_manager_salary_buildings rb
      ON rb.salary_id = r.rule_id
     AND rb.organization_id = p_organization_id
    JOIN bases b ON b.building_id = rb.building_id
  ),
  targets AS (
    SELECT
      rb.*,
      CASE
        WHEN rb.basis = 'TOTAL_GROUP' AND rb.form = 'FIXED'
          THEN round(GREATEST(rb.fixed_amount, 0))
        WHEN rb.basis = 'TOTAL_GROUP' AND rb.form = 'PERCENT'
          THEN round(GREATEST(rb.positive_base_sum, 0) * GREATEST(rb.percent, 0) / 100)
        ELSE NULL::numeric
      END AS target_total
    FROM rule_buildings rb
  ),
  raw_amounts AS (
    SELECT
      t.*,
      CASE
        WHEN t.basis = 'PER_BUILDING' AND t.form = 'FIXED'
          THEN round(GREATEST(t.fixed_amount, 0))
        WHEN t.basis = 'PER_BUILDING' AND t.form = 'PERCENT'
          THEN round(GREATEST(t.base, 0) * GREATEST(t.percent, 0) / 100)
        WHEN t.positive_base_sum > 0
          THEN t.target_total * GREATEST(t.base, 0) / t.positive_base_sum
        ELSE t.target_total / t.building_count
      END AS raw_amount
    FROM targets t
  ),
  based AS (
    SELECT
      r.*,
      CASE
        WHEN r.basis = 'PER_BUILDING' THEN r.raw_amount
        ELSE floor(r.raw_amount)
      END AS base_part
    FROM raw_amounts r
  ),
  ranked AS (
    SELECT
      b.*,
      CASE
        WHEN b.basis = 'TOTAL_GROUP'
          THEN b.target_total - sum(b.base_part) OVER (PARTITION BY b.rule_id)
        ELSE 0::numeric
      END AS remainder,
      row_number() OVER (
        PARTITION BY b.rule_id
        ORDER BY (b.raw_amount - floor(b.raw_amount)) DESC, b.building_id
      ) AS remainder_rank
    FROM based b
  ),
  amounts AS (
    SELECT
      manager_id,
      building_id,
      CASE
        WHEN basis = 'TOTAL_GROUP' AND remainder_rank <= remainder
          THEN base_part + 1
        ELSE base_part
      END::numeric AS amount
    FROM ranked
  ),
  grouped AS (
    SELECT manager_id, building_id, sum(amount)::numeric AS amount
    FROM amounts
    GROUP BY manager_id, building_id
    HAVING sum(amount) <> 0
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'manager_id', manager_id,
        'building_id', building_id,
        'amount', amount
      ) ORDER BY building_id, manager_id
    ),
    '[]'::jsonb
  )
  FROM grouped;
$$;








--
-- Name: _profit_state_change_v2(text, uuid, date, text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_state_change_v2(p_operation text, p_organization_id uuid, p_period_month date, p_reason text, p_idempotency_key text, p_building_ids uuid[], p_expected_source_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_expected_hash text := NULLIF(lower(btrim(COALESCE(p_expected_source_hash, ''))), '');
  v_building_ids uuid[] := p_building_ids;
  v_request_payload jsonb;
  v_request_hash text;
  v_existing_run public.profit_close_runs%ROWTYPE;
  v_before jsonb;
  v_state_hash text;
  v_result jsonb;
  v_run_id uuid := gen_random_uuid();
  v_building_id uuid;
  v_pm public.profit_monthly%ROWTYPE;
  v_revision bigint;
  v_shareholder_allocations jsonb;
  v_manager_allocations jsonb;
  v_previous_snapshot jsonb;
  v_current_snapshot jsonb;
  v_affected integer := 0;
BEGIN
  IF p_operation NOT IN ('RESET', 'UNLOCK') THEN
    RAISE EXCEPTION 'Invalid state-change operation' USING ERRCODE = '22023';
  END IF;
  IF p_period_month IS NULL
     OR p_period_month <> date_trunc('month', p_period_month)::date THEN
    RAISE EXCEPTION 'period_month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'reason must contain 8..1000 characters'
      USING ERRCODE = '22023';
  END IF;
  IF char_length(v_key) NOT BETWEEN 8 AND 200 THEN
    RAISE EXCEPTION 'idempotency_key must contain 8..200 characters'
      USING ERRCODE = '22023';
  END IF;
  IF v_expected_hash IS NOT NULL AND v_expected_hash !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'expected_source_hash must be a 32-character MD5'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public._profit_assert_authorized_v2(
    p_organization_id, 'shareholder_profit.unlock'
  );

  v_request_payload := jsonb_build_object(
    'operation', p_operation,
    'organization_id', p_organization_id,
    'period_month', p_period_month,
    'reason', v_reason,
    'building_ids', to_jsonb(p_building_ids),
    'expected_source_hash', v_expected_hash
  );
  v_request_hash := md5(v_request_payload::text);

  PERFORM pg_advisory_xact_lock(
    hashtext(p_organization_id::text), hashtext('profit-key:' || v_key)
  );

  SELECT *
  INTO v_existing_run
  FROM public.profit_close_runs r
  WHERE r.organization_id = p_organization_id
    AND r.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing_run.operation <> p_operation
       OR v_existing_run.period_month <> p_period_month
       OR v_existing_run.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'Idempotency key was already used with a different request'
        USING ERRCODE = '23505';
    END IF;
    RETURN v_existing_run.result_snapshot
      || jsonb_build_object('idempotent_replay', true);
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext(p_organization_id::text), hashtext(p_period_month::text)
  );

  -- NULL intentionally means every current snapshot in the org/period,
  -- including legacy virtual buckets. Close/preview remain real-building-only.
  IF v_building_ids IS NULL THEN
    SELECT array_agg(pm.building_id ORDER BY pm.building_id)
    INTO v_building_ids
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month;
  ELSE
    IF array_position(v_building_ids, NULL) IS NOT NULL THEN
      RAISE EXCEPTION 'building_ids cannot contain NULL' USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*) FROM unnest(v_building_ids) x)
       <> (SELECT count(DISTINCT x) FROM unnest(v_building_ids) x) THEN
      RAISE EXCEPTION 'building_ids contains duplicates' USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*)
        FROM public.profit_monthly pm
        WHERE pm.organization_id = p_organization_id
          AND pm.period_month = p_period_month
          AND pm.building_id = ANY(v_building_ids))
       <> cardinality(v_building_ids) THEN
      RAISE EXCEPTION 'Every requested building must have a current period snapshot'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_building_ids := COALESCE(v_building_ids, '{}'::uuid[]);

  IF NOT public.is_super_admin() AND EXISTS (
    SELECT 1
    FROM unnest(v_building_ids) bid
    WHERE NOT public.authorize_v2(
      'shareholder_profit.unlock', p_organization_id, 'BUILDING', bid
    )
  ) THEN
    RAISE EXCEPTION 'Unlock permission does not cover every requested building'
      USING ERRCODE = '42501';
  END IF;

  IF p_operation = 'UNLOCK' AND EXISTS (
    SELECT 1
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND pm.building_id = ANY(v_building_ids)
      AND pm.status <> 'LOCKED'
  ) THEN
    RAISE EXCEPTION 'UNLOCK requires LOCKED current snapshots'
      USING ERRCODE = '55000';
  END IF;

  IF v_expected_hash IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND pm.building_id = ANY(v_building_ids)
      AND pm.source_hash IS DISTINCT FROM v_expected_hash
  ) THEN
    RAISE EXCEPTION 'PROFIT_SOURCE_CONFLICT current snapshots do not match expected hash'
      USING ERRCODE = '40001';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'profit_monthly', to_jsonb(pm),
      'shareholder_allocations', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', pa.id,
            'shareholder_id', pa.shareholder_id,
            'percent', pa.percent,
            'amount', pa.amount,
            'created_at', pa.created_at
          ) ORDER BY pa.shareholder_id, pa.id
        )
        FROM public.profit_allocations pa
        WHERE pa.profit_monthly_id = pm.id
      ), '[]'::jsonb),
      'manager_allocations', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', pma.id,
            'manager_id', pma.manager_id,
            'amount', pma.amount,
            'created_at', pma.created_at
          ) ORDER BY pma.manager_id, pma.id
        )
        FROM public.profit_manager_allocations pma
        WHERE pma.profit_monthly_id = pm.id
      ), '[]'::jsonb)
    ) ORDER BY pm.building_id
  ), '[]'::jsonb)
  INTO v_before
  FROM public.profit_monthly pm
  WHERE pm.organization_id = p_organization_id
    AND pm.period_month = p_period_month
    AND pm.building_id = ANY(v_building_ids);

  v_state_hash := md5(v_before::text);
  v_affected := cardinality(v_building_ids);
  v_result := jsonb_build_object(
    'run_id', v_run_id,
    'operation', p_operation,
    'organization_id', p_organization_id,
    'period_month', p_period_month,
    'affected_buildings', v_affected,
    'deleted_current_snapshots', p_operation = 'RESET',
    'state_hash', v_state_hash,
    'idempotent_replay', false
  );

  INSERT INTO public.profit_close_runs (
    id, organization_id, period_month, operation, actor_id, reason,
    idempotency_key, request_payload, request_hash, expected_source_hash,
    source_hash, source_captured_at, source_snapshot, allocation_snapshot,
    result_snapshot
  ) VALUES (
    v_run_id,
    p_organization_id,
    p_period_month,
    p_operation,
    v_actor,
    v_reason,
    v_key,
    v_request_payload,
    v_request_hash,
    v_expected_hash,
    v_state_hash,
    clock_timestamp(),
    jsonb_build_object('kind', 'CURRENT_PROFIT_SNAPSHOT', 'rows', v_before),
    v_before,
    v_result
  );

  FOREACH v_building_id IN ARRAY v_building_ids
  LOOP
    SELECT *
    INTO STRICT v_pm
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND pm.building_id = v_building_id
    FOR UPDATE;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', pa.id,
        'shareholder_id', pa.shareholder_id,
        'percent', pa.percent,
        'amount', pa.amount,
        'created_at', pa.created_at
      ) ORDER BY pa.shareholder_id, pa.id
    ), '[]'::jsonb)
    INTO v_shareholder_allocations
    FROM public.profit_allocations pa
    WHERE pa.profit_monthly_id = v_pm.id;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', pma.id,
        'manager_id', pma.manager_id,
        'amount', pma.amount,
        'created_at', pma.created_at
      ) ORDER BY pma.manager_id, pma.id
    ), '[]'::jsonb)
    INTO v_manager_allocations
    FROM public.profit_manager_allocations pma
    WHERE pma.profit_monthly_id = v_pm.id;

    v_previous_snapshot := jsonb_build_object(
      'profit_monthly', to_jsonb(v_pm),
      'shareholder_allocations', v_shareholder_allocations,
      'manager_allocations', v_manager_allocations
    );

    SELECT COALESCE(max(r.revision_number), 0) + 1
    INTO v_revision
    FROM public.profit_close_revisions r
    WHERE r.organization_id = p_organization_id
      AND r.building_id = v_building_id
      AND r.period_month = p_period_month;

    DELETE FROM public.profit_allocations
    WHERE profit_monthly_id = v_pm.id;
    DELETE FROM public.profit_manager_allocations
    WHERE profit_monthly_id = v_pm.id;

    IF p_operation = 'RESET' THEN
      DELETE FROM public.profit_monthly WHERE id = v_pm.id;
      v_current_snapshot := NULL;
    ELSE
      UPDATE public.profit_monthly
      SET status = 'DRAFT',
          management_salary = 0,
          locked_at = NULL,
          locked_by = NULL,
          is_stale = true,
          stale_reason = left('UNLOCKED: ' || v_reason, 1000),
          revision_number = v_revision
      WHERE id = v_pm.id;

      SELECT jsonb_build_object(
        'profit_monthly', to_jsonb(pm),
        'shareholder_allocations', '[]'::jsonb,
        'manager_allocations', '[]'::jsonb
      )
      INTO v_current_snapshot
      FROM public.profit_monthly pm
      WHERE pm.id = v_pm.id;
    END IF;

    INSERT INTO public.profit_close_revisions (
      run_id, organization_id, profit_monthly_id, building_id, period_month,
      revision_number, operation, actor_id, reason, source_hash,
      source_captured_at, source_snapshot, shareholder_allocations,
      manager_allocations, previous_snapshot, current_snapshot
    ) VALUES (
      v_run_id,
      p_organization_id,
      v_pm.id,
      v_building_id,
      p_period_month,
      v_revision,
      p_operation,
      v_actor,
      v_reason,
      v_pm.source_hash,
      v_pm.source_captured_at,
      jsonb_build_object(
        'source_revenue', v_pm.source_revenue,
        'source_expense', v_pm.source_expense,
        'source_net_profit', v_pm.source_net_profit,
        'source_hash', v_pm.source_hash,
        'source_captured_at', v_pm.source_captured_at,
        'was_stale', v_pm.is_stale,
        'stale_reason', v_pm.stale_reason
      ),
      v_shareholder_allocations,
      v_manager_allocations,
      v_previous_snapshot,
      v_current_snapshot
    );
  END LOOP;

  RETURN v_result;
END
$_$;








--
-- Name: _profit_write_close_v2(text, uuid, date, text, text, text, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_write_close_v2(p_operation text, p_organization_id uuid, p_period_month date, p_expected_source_hash text, p_reason text, p_idempotency_key text, p_building_ids uuid[], p_adjustments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
  v_row jsonb;
  v_building_id uuid;
  v_unallocated numeric;
  v_percent numeric;
  v_allocated numeric;
  v_disposition text;
  v_disposition_reason text;
  v_pm_id uuid;
  v_run_id uuid;
BEGIN
  v_result := public._profit_write_close_v2_base(
    p_operation, p_organization_id, p_period_month, p_expected_source_hash,
    p_reason, p_idempotency_key, p_building_ids, p_adjustments
  );
  v_run_id := NULLIF(v_result->>'run_id', '')::uuid;

  FOR v_row IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(v_result->'buildings', '[]'::jsonb)) x(value)
  LOOP
    v_building_id := (v_row->>'building_id')::uuid;
    v_unallocated := COALESCE((v_row->>'unallocated_profit')::numeric, 0);
    v_percent := COALESCE((v_row->>'shareholder_percent_total')::numeric, 0);
    v_allocated := COALESCE((v_row->>'shareholder_allocated_amount')::numeric, 0);

    IF v_unallocated = 'NaN'::numeric
       OR v_percent = 'NaN'::numeric
       OR v_allocated = 'NaN'::numeric
       OR v_percent < 0 OR v_percent > 100 THEN
      RAISE EXCEPTION 'Profit close returned invalid allocation numbers'
        USING ERRCODE = '55000';
    END IF;

    SELECT
      NULLIF(btrim(a.unallocated_disposition), ''),
      NULLIF(btrim(a.unallocated_disposition_reason), '')
    INTO v_disposition, v_disposition_reason
    FROM jsonb_to_recordset(COALESCE(p_adjustments, '[]'::jsonb)) AS a(
      building_id uuid,
      unallocated_disposition text,
      unallocated_disposition_reason text
    )
    WHERE a.building_id = v_building_id
    LIMIT 1;

    IF abs(v_unallocated) >= 0.01 THEN
      IF v_disposition NOT IN ('RETAINED_EARNINGS', 'CARRY_FORWARD') THEN
        RAISE EXCEPTION
          'Building % has unallocated profit %; choose RETAINED_EARNINGS or CARRY_FORWARD',
          v_building_id, v_unallocated
          USING ERRCODE = '22023';
      END IF;
      IF char_length(COALESCE(v_disposition_reason, '')) NOT BETWEEN 8 AND 500 THEN
        RAISE EXCEPTION 'Unallocated disposition reason must contain 8..500 characters'
          USING ERRCODE = '22023';
      END IF;
    ELSE
      v_disposition := NULL;
      v_disposition_reason := NULL;
    END IF;

    UPDATE public.profit_monthly pm
       SET shareholder_percent_total = v_percent,
           shareholder_allocated_amount = v_allocated,
           unallocated_profit = v_unallocated,
           unallocated_disposition = v_disposition,
           unallocated_disposition_reason = v_disposition_reason
     WHERE pm.organization_id = p_organization_id
       AND pm.building_id = v_building_id
       AND pm.period_month = p_period_month
    RETURNING pm.id INTO v_pm_id;

    IF v_pm_id IS NULL THEN
      RAISE EXCEPTION 'Profit close did not persist building %', v_building_id
        USING ERRCODE = '55000';
    END IF;

    IF abs(v_unallocated) >= 0.01 THEN
      INSERT INTO public.profit_unallocated_decisions (
        run_id, organization_id, profit_monthly_id, building_id, period_month,
        unallocated_profit, disposition, reason, decision_source, actor_id
      ) VALUES (
        v_run_id, p_organization_id, v_pm_id, v_building_id, p_period_month,
        v_unallocated, v_disposition, v_disposition_reason,
        CASE WHEN p_operation = 'RECLOSE' THEN 'RECLOSE_V3' ELSE 'CLOSE_V3' END,
        v_actor
      )
      ON CONFLICT (run_id, profit_monthly_id) WHERE run_id IS NOT NULL
      DO NOTHING;
    END IF;
  END LOOP;

  RETURN public._profit_enrich_unallocated_v3(v_result, p_adjustments);
END
$$;








--
-- Name: _profit_write_close_v2_base(text, uuid, date, text, text, text, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._profit_write_close_v2_base(p_operation text, p_organization_id uuid, p_period_month date, p_expected_source_hash text, p_reason text, p_idempotency_key text, p_building_ids uuid[], p_adjustments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_expected_hash text := lower(btrim(COALESCE(p_expected_source_hash, '')));
  v_building_ids uuid[] := p_building_ids;
  v_request_payload jsonb;
  v_request_hash text;
  v_existing_run public.profit_close_runs%ROWTYPE;
  v_preview jsonb;
  v_result jsonb;
  v_allocation_snapshot jsonb;
  v_run_id uuid := gen_random_uuid();
  v_row jsonb;
  v_building_id uuid;
  v_owner_user_id uuid;
  v_pm_id uuid;
  v_revision bigint;
  v_existing_pm public.profit_monthly%ROWTYPE;
  v_has_existing boolean;
  v_previous_snapshot jsonb;
  v_current_snapshot jsonb;
  v_old_shareholder_allocations jsonb;
  v_old_manager_allocations jsonb;
  v_source_snapshot jsonb;
BEGIN
  IF p_operation NOT IN ('CLOSE', 'RECLOSE') THEN
    RAISE EXCEPTION 'Invalid close operation' USING ERRCODE = '22023';
  END IF;
  IF p_period_month IS NULL
     OR p_period_month <> date_trunc('month', p_period_month)::date THEN
    RAISE EXCEPTION 'period_month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;
  IF p_operation = 'CLOSE' AND v_reason = '' THEN
    v_reason := 'Initial monthly profit close';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'reason must contain 8..1000 characters'
      USING ERRCODE = '22023';
  END IF;
  IF char_length(v_key) NOT BETWEEN 8 AND 200 THEN
    RAISE EXCEPTION 'idempotency_key must contain 8..200 characters'
      USING ERRCODE = '22023';
  END IF;
  IF v_expected_hash !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'expected_source_hash must be a 32-character lowercase MD5'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public._profit_assert_authorized_v2(
    p_organization_id, 'shareholder_profit.lock'
  );

  v_request_payload := jsonb_build_object(
    'operation', p_operation,
    'organization_id', p_organization_id,
    'period_month', p_period_month,
    'expected_source_hash', v_expected_hash,
    'reason', v_reason,
    'building_ids', to_jsonb(p_building_ids),
    'adjustments', COALESCE(p_adjustments, '[]'::jsonb)
  );
  v_request_hash := md5(v_request_payload::text);

  PERFORM pg_advisory_xact_lock(
    hashtext(p_organization_id::text), hashtext('profit-key:' || v_key)
  );

  SELECT *
  INTO v_existing_run
  FROM public.profit_close_runs r
  WHERE r.organization_id = p_organization_id
    AND r.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing_run.operation <> p_operation
       OR v_existing_run.period_month <> p_period_month
       OR v_existing_run.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'Idempotency key was already used with a different request'
        USING ERRCODE = '23505';
    END IF;
    RETURN v_existing_run.result_snapshot
      || jsonb_build_object('idempotent_replay', true);
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext(p_organization_id::text), hashtext(p_period_month::text)
  );

  IF v_building_ids IS NULL THEN
    IF p_operation = 'CLOSE' THEN
      SELECT array_agg(b.id ORDER BY b.id)
      INTO v_building_ids
      FROM public.buildings b
      WHERE b.organization_id = p_organization_id
        AND b.deleted_at IS NULL
        AND b.is_virtual = false;
    ELSE
      SELECT array_agg(pm.building_id ORDER BY pm.building_id)
      INTO v_building_ids
      FROM public.profit_monthly pm
      JOIN public.buildings b ON b.id = pm.building_id
      WHERE pm.organization_id = p_organization_id
        AND pm.period_month = p_period_month
        AND pm.status = 'LOCKED'
        AND b.deleted_at IS NULL
        AND b.is_virtual = false;
    END IF;
  END IF;

  IF v_building_ids IS NULL OR cardinality(v_building_ids) = 0 THEN
    RAISE EXCEPTION 'No real buildings are available for %', p_operation
      USING ERRCODE = '22023';
  END IF;

  -- A close is a whole-period decision. Partial arrays would change the base
  -- set of TOTAL_GROUP salary rules and therefore produce non-canonical pay.
  IF cardinality(v_building_ids) <> (
    SELECT count(*)
    FROM public.buildings b
    WHERE b.organization_id = p_organization_id
      AND b.deleted_at IS NULL
      AND b.is_virtual = false
  ) OR EXISTS (
    SELECT 1
    FROM public.buildings b
    WHERE b.organization_id = p_organization_id
      AND b.deleted_at IS NULL
      AND b.is_virtual = false
      AND NOT (b.id = ANY(v_building_ids))
  ) THEN
    RAISE EXCEPTION
      'CLOSE/RECLOSE must include every active real building in the organization; reset mixed legacy state first'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND NOT (pm.building_id = ANY(v_building_ids))
  ) THEN
    RAISE EXCEPTION
      'Period contains legacy virtual/deleted-building snapshots; run profit_reset_v2 before closing'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profit_monthly pm
    WHERE pm.building_id = ANY(v_building_ids)
      AND pm.period_month = p_period_month
      AND pm.organization_id IS DISTINCT FROM p_organization_id
  ) THEN
    RAISE EXCEPTION 'A current snapshot has an invalid organization boundary'
      USING ERRCODE = '55000';
  END IF;

  IF p_operation = 'CLOSE' AND EXISTS (
    SELECT 1
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND pm.building_id = ANY(v_building_ids)
      AND pm.status = 'LOCKED'
  ) THEN
    RAISE EXCEPTION 'One or more buildings are already closed; use profit_reclose_v2'
      USING ERRCODE = '55000';
  END IF;

  IF p_operation = 'RECLOSE' AND (
    SELECT count(*)
    FROM public.profit_monthly pm
    WHERE pm.organization_id = p_organization_id
      AND pm.period_month = p_period_month
      AND pm.building_id = ANY(v_building_ids)
      AND pm.status = 'LOCKED'
  ) <> cardinality(v_building_ids) THEN
    RAISE EXCEPTION 'RECLOSE requires an existing LOCKED snapshot for every building'
      USING ERRCODE = '55000';
  END IF;

  v_preview := public._profit_close_preview_core_v2(
    p_organization_id,
    p_period_month,
    v_building_ids,
    COALESCE(p_adjustments, '[]'::jsonb),
    'shareholder_profit.lock',
    true
  );

  IF v_preview->>'source_hash' <> v_expected_hash THEN
    RAISE EXCEPTION
      'PROFIT_SOURCE_CONFLICT expected %, current %',
      v_expected_hash, v_preview->>'source_hash'
      USING ERRCODE = '40001';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'building_id', x.value->>'building_id',
      'shareholder_allocations', x.value->'shareholder_allocations',
      'manager_allocations', x.value->'manager_allocations'
    ) ORDER BY x.value->>'building_id'
  ), '[]'::jsonb)
  INTO v_allocation_snapshot
  FROM jsonb_array_elements(v_preview->'buildings') x(value);

  v_result := v_preview || jsonb_build_object(
    'run_id', v_run_id,
    'operation', p_operation,
    'affected_buildings', cardinality(v_building_ids),
    'idempotent_replay', false
  );

  INSERT INTO public.profit_close_runs (
    id, organization_id, period_month, operation, actor_id, reason,
    idempotency_key, request_payload, request_hash, expected_source_hash,
    source_hash, source_captured_at, source_snapshot, allocation_snapshot,
    result_snapshot
  ) VALUES (
    v_run_id,
    p_organization_id,
    p_period_month,
    p_operation,
    v_actor,
    v_reason,
    v_key,
    v_request_payload,
    v_request_hash,
    v_expected_hash,
    v_preview->>'source_hash',
    (v_preview->>'source_captured_at')::timestamptz,
    v_preview->'source_snapshot',
    v_allocation_snapshot,
    v_result
  );

  FOR v_row IN
    SELECT value
    FROM jsonb_array_elements(v_preview->'buildings') x(value)
    ORDER BY value->>'building_id'
  LOOP
    v_building_id := (v_row->>'building_id')::uuid;

    SELECT b.user_id
    INTO v_owner_user_id
    FROM public.buildings b
    WHERE b.id = v_building_id
      AND b.organization_id = p_organization_id;

    SELECT *
    INTO v_existing_pm
    FROM public.profit_monthly pm
    WHERE pm.building_id = v_building_id
      AND pm.period_month = p_period_month
    FOR UPDATE;
    v_has_existing := FOUND;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', pa.id,
        'shareholder_id', pa.shareholder_id,
        'percent', pa.percent,
        'amount', pa.amount,
        'created_at', pa.created_at
      ) ORDER BY pa.shareholder_id, pa.id
    ), '[]'::jsonb)
    INTO v_old_shareholder_allocations
    FROM public.profit_allocations pa
    WHERE v_has_existing AND pa.profit_monthly_id = v_existing_pm.id;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', pma.id,
        'manager_id', pma.manager_id,
        'amount', pma.amount,
        'created_at', pma.created_at
      ) ORDER BY pma.manager_id, pma.id
    ), '[]'::jsonb)
    INTO v_old_manager_allocations
    FROM public.profit_manager_allocations pma
    WHERE v_has_existing AND pma.profit_monthly_id = v_existing_pm.id;

    v_previous_snapshot := CASE WHEN v_has_existing THEN
      jsonb_build_object(
        'profit_monthly', to_jsonb(v_existing_pm),
        'shareholder_allocations', v_old_shareholder_allocations,
        'manager_allocations', v_old_manager_allocations
      )
      ELSE NULL
    END;

    SELECT COALESCE(max(r.revision_number), 0) + 1
    INTO v_revision
    FROM public.profit_close_revisions r
    WHERE r.organization_id = p_organization_id
      AND r.building_id = v_building_id
      AND r.period_month = p_period_month;

    v_pm_id := CASE WHEN v_has_existing THEN v_existing_pm.id ELSE gen_random_uuid() END;

    INSERT INTO public.profit_monthly AS pm (
      id, user_id, building_id, period_month, computed_profit,
      adjustment_amount, adjustment_reason, adjustment_by, adjustment_at,
      adjusted_profit, management_salary, status, locked_at, locked_by,
      organization_id, source_revenue, source_expense, source_net_profit,
      source_hash, source_captured_at, is_stale, stale_reason,
      revision_number
    ) VALUES (
      v_pm_id,
      v_owner_user_id,
      v_building_id,
      p_period_month,
      (v_row->>'computed_profit')::numeric,
      (v_row->>'adjustment_amount')::numeric,
      NULLIF(btrim(v_row->>'adjustment_reason'), ''),
      CASE WHEN (v_row->>'adjustment_amount')::numeric <> 0 THEN v_actor END,
      CASE WHEN (v_row->>'adjustment_amount')::numeric <> 0
           THEN (v_preview->>'source_captured_at')::timestamptz END,
      (v_row->>'adjusted_profit')::numeric,
      (v_row->>'management_salary')::numeric,
      'LOCKED',
      (v_preview->>'source_captured_at')::timestamptz,
      v_actor,
      p_organization_id,
      (v_row->>'source_revenue')::numeric,
      (v_row->>'source_expense')::numeric,
      (v_row->>'computed_profit')::numeric,
      v_row->>'building_source_hash',
      (v_preview->>'source_captured_at')::timestamptz,
      false,
      NULL,
      v_revision
    )
    ON CONFLICT (building_id, period_month) DO UPDATE
      SET user_id = EXCLUDED.user_id,
          computed_profit = EXCLUDED.computed_profit,
          adjustment_amount = EXCLUDED.adjustment_amount,
          adjustment_reason = EXCLUDED.adjustment_reason,
          adjustment_by = EXCLUDED.adjustment_by,
          adjustment_at = EXCLUDED.adjustment_at,
          adjusted_profit = EXCLUDED.adjusted_profit,
          management_salary = EXCLUDED.management_salary,
          status = 'LOCKED',
          locked_at = EXCLUDED.locked_at,
          locked_by = EXCLUDED.locked_by,
          organization_id = EXCLUDED.organization_id,
          source_revenue = EXCLUDED.source_revenue,
          source_expense = EXCLUDED.source_expense,
          source_net_profit = EXCLUDED.source_net_profit,
          source_hash = EXCLUDED.source_hash,
          source_captured_at = EXCLUDED.source_captured_at,
          is_stale = false,
          stale_reason = NULL,
          revision_number = EXCLUDED.revision_number
    RETURNING pm.id INTO v_pm_id;

    DELETE FROM public.profit_allocations
    WHERE profit_monthly_id = v_pm_id;
    DELETE FROM public.profit_manager_allocations
    WHERE profit_monthly_id = v_pm_id;

    INSERT INTO public.profit_allocations (
      user_id, profit_monthly_id, shareholder_id, percent, amount,
      organization_id
    )
    SELECT
      v_owner_user_id,
      v_pm_id,
      x.shareholder_id,
      x.percent,
      x.amount,
      p_organization_id
    FROM jsonb_to_recordset(v_row->'shareholder_allocations')
      AS x(shareholder_id uuid, shareholder_name text, percent numeric, amount numeric);

    INSERT INTO public.profit_manager_allocations (
      user_id, profit_monthly_id, manager_id, amount, organization_id
    )
    SELECT
      v_owner_user_id,
      v_pm_id,
      x.manager_id,
      x.amount,
      p_organization_id
    FROM jsonb_to_recordset(v_row->'manager_allocations')
      AS x(manager_id uuid, manager_name text, amount numeric)
    WHERE x.amount <> 0;

    SELECT jsonb_build_object(
      'profit_monthly', to_jsonb(pm),
      'shareholder_allocations', v_row->'shareholder_allocations',
      'manager_allocations', v_row->'manager_allocations'
    )
    INTO v_current_snapshot
    FROM public.profit_monthly pm
    WHERE pm.id = v_pm_id;

    SELECT jsonb_build_object(
      'algorithm_version', v_preview->>'algorithm_version',
      'preview_source_hash', v_preview->>'source_hash',
      'building_source_hash', v_row->>'building_source_hash',
      'source_captured_at', v_preview->'source_captured_at',
      'pnl', COALESCE((
        SELECT x.value
        FROM jsonb_array_elements(v_preview->'source_snapshot'->'pnl') x(value)
        WHERE x.value->>'building_id' = v_building_id::text
        LIMIT 1
      ), '{}'::jsonb),
      'accrual_lines', COALESCE((
        SELECT jsonb_agg(x.value)
        FROM jsonb_array_elements(
          v_preview->'source_snapshot'->'accrual_lines'
        ) x(value)
        WHERE x.value->>'building_id' = v_building_id::text
      ), '[]'::jsonb)
    )
    INTO v_source_snapshot;

    INSERT INTO public.profit_close_revisions (
      run_id, organization_id, profit_monthly_id, building_id, period_month,
      revision_number, operation, actor_id, reason, source_hash,
      source_captured_at, source_snapshot, shareholder_allocations,
      manager_allocations, previous_snapshot, current_snapshot
    ) VALUES (
      v_run_id,
      p_organization_id,
      v_pm_id,
      v_building_id,
      p_period_month,
      v_revision,
      p_operation,
      v_actor,
      v_reason,
      v_row->>'building_source_hash',
      (v_preview->>'source_captured_at')::timestamptz,
      v_source_snapshot,
      v_row->'shareholder_allocations',
      v_row->'manager_allocations',
      v_previous_snapshot,
      v_current_snapshot
    );
  END LOOP;

  RETURN v_result;
END
$_$;








--
-- Name: _record_invoice_payment_v3_legacy(uuid, numeric, public.payment_method, date, text, uuid, text, text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._record_invoice_payment_v3_legacy(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_receipt_image_url text DEFAULT NULL::text, p_voucher jsonb DEFAULT NULL::jsonb, p_items jsonb DEFAULT NULL::jsonb, p_receipt_number text DEFAULT NULL::text, p_voucher_owner_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_inv RECORD; v_payment_id uuid; v_voucher_id uuid; v_owner uuid;
  v_new_paid numeric(15,2); v_status invoice_status; v_paid_date date; v_excess numeric(15,2) := 0;
  v_existing RECORD; it jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Số tiền phải > 0'; END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 THEN RAISE EXCEPTION 'idempotency_key bắt buộc (>=8 ký tự)'; END IF;

  SELECT ie.id AS voucher_id, ie.payment_id INTO v_existing
  FROM income_expenses ie WHERE ie.idempotency_key = p_idempotency_key AND ie.deleted_at IS NULL LIMIT 1;
  IF FOUND THEN RETURN json_build_object('payment_id', v_existing.payment_id, 'voucher_id', v_existing.voucher_id, 'idempotent', true); END IF;

  SELECT id, user_id, building_id, contract_id, total_amount, paid_amount, status
  INTO v_inv FROM invoices WHERE id = p_invoice_id AND deleted_at IS NULL
    AND public.can_do_on_building('invoices','edit', building_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy hoá đơn hoặc không có quyền' USING ERRCODE='42501'; END IF;

  -- Voucher owner: mặc định caller; nếu truyền p_voucher_owner_id phải = invoice owner.
  IF p_voucher_owner_id IS NOT NULL AND p_voucher_owner_id <> v_inv.user_id THEN
    RAISE EXCEPTION 'p_voucher_owner_id phải là chủ hoá đơn' USING ERRCODE='42501';
  END IF;
  v_owner := COALESCE(p_voucher_owner_id, v_caller);

  INSERT INTO payments (invoice_id, amount, payment_method, payment_date, notes, receipt_image_url, receipt_number)
  VALUES (p_invoice_id, p_amount, p_payment_method, p_payment_date, p_notes, p_receipt_image_url, p_receipt_number)
  RETURNING id INTO v_payment_id;

  v_new_paid := COALESCE(v_inv.paid_amount,0) + p_amount;
  IF v_new_paid >= v_inv.total_amount THEN
    v_status := 'PAID'; v_paid_date := p_payment_date; v_excess := v_new_paid - v_inv.total_amount;
    IF v_excess > 0 THEN
      INSERT INTO excess_amounts (contract_id, amount, description, source_invoice_id, source_payment_id)
      VALUES (v_inv.contract_id, v_excess, 'Tiền thừa từ hoá đơn ' || (SELECT invoice_number FROM invoices WHERE id=p_invoice_id), p_invoice_id, v_payment_id);
    END IF;
  ELSE v_status := 'PARTIAL_PAID'; v_paid_date := NULL; END IF;

  UPDATE invoices SET paid_amount=v_new_paid, status=v_status, paid_date=v_paid_date WHERE id=p_invoice_id;

  IF p_account_id IS NOT NULL AND p_voucher IS NOT NULL THEN
    INSERT INTO income_expenses (
      user_id, type, name, building_id, room_id, contract_id, account_id, invoice_id, payment_id,
      voucher_date, payer_name, notes, attachments, approval_status, approved_by, approved_at,
      creator_name, business_result_accounting, change_amount, change_account_id, rounding_amount, rounding_account_id, idempotency_key
    ) VALUES (
      v_owner, 'INCOME', COALESCE(p_voucher->>'name','Thu tiền hoá đơn'),
      v_inv.building_id, NULLIF(p_voucher->>'room_id','')::uuid, v_inv.contract_id,
      p_account_id, p_invoice_id, v_payment_id, p_payment_date,
      p_voucher->>'payer_name', p_voucher->>'notes', COALESCE(p_voucher->'attachments','[]'::jsonb),
      'APPROVED', v_caller, now(), p_voucher->>'creator_name',
      CASE WHEN p_voucher ? 'business_result_accounting' AND jsonb_typeof(p_voucher->'business_result_accounting')='boolean'
           THEN (p_voucher->>'business_result_accounting')::boolean ELSE NULL END,
      COALESCE((p_voucher->>'change_amount')::numeric,0), NULLIF(p_voucher->>'change_account_id','')::uuid,
      COALESCE((p_voucher->>'rounding_amount')::numeric,0), NULLIF(p_voucher->>'rounding_account_id','')::uuid, p_idempotency_key
    ) RETURNING id INTO v_voucher_id;
    IF p_items IS NOT NULL THEN
      FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
        VALUES (v_voucher_id, (it->>'income_expense_type_id')::uuid, it->>'description',
                COALESCE((it->>'quantity')::numeric,1), (it->>'unit_price')::numeric, NULLIF(it->>'start_date','')::date, NULLIF(it->>'end_date','')::date);
      END LOOP;
    END IF;
  END IF;

  RETURN json_build_object('payment_id', v_payment_id, 'voucher_id', v_voucher_id, 'new_paid_amount', v_new_paid, 'new_status', v_status, 'excess_amount', v_excess);
END;
$$;








--
-- Name: _record_invoice_payment_v4_legacy(uuid, numeric, public.payment_method, date, text, uuid, text, text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._record_invoice_payment_v4_legacy(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_receipt_image_url text DEFAULT NULL::text, p_voucher jsonb DEFAULT NULL::jsonb, p_items jsonb DEFAULT NULL::jsonb, p_receipt_number text DEFAULT NULL::text, p_voucher_owner_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_authz record;
  v_inv record;
  v_owner uuid;
  v_key text;
  v_amount numeric(15,2);
  v_payload jsonb;
  v_items jsonb := '[]'::jsonb;
  v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  v_flag app_private.server_feature_flags%rowtype;
  v_payment_id uuid;
  v_voucher_id uuid;
  v_new_paid numeric(15,2);
  v_status text;
  v_paid_date date;
  v_excess numeric(15,2) := 0;
  v_resp json;
  it jsonb; v_idx int := 0; v_type_id uuid;
  v_room uuid; v_chg uuid; v_rnd uuid;
  c_op constant text := 'invoice.record_payment.v1';
  c_max constant numeric := 9999999999999.99;
begin
  -- (0) auth + cheap normalization; NO ledger lookup yet.
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  if p_amount is null or p_amount <= 0 or round(p_amount,2) <> p_amount or p_amount > c_max then
    raise exception 'Số tiền không hợp lệ'; end if;
  v_amount := p_amount;
  if p_payment_date is null or p_payment_date < date '2000-01-01'
     or p_payment_date > date '2100-12-31' then
    raise exception 'Ngày thu không hợp lệ'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if char_length(v_key) < 8 or char_length(v_key) > 200
     or v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;

  -- (1) lock invoice + derive org from its building (invoices.organization_id
  --     untrusted). BEFORE any ledger read.
  select i.id, i.user_id, i.building_id, i.room_id, i.contract_id,
         i.total_amount, i.paid_amount, i.status, i.organization_id, i.invoice_number
    into v_inv from public.invoices i
   where i.id = p_invoice_id and i.deleted_at is null for update;
  if not found then raise exception 'Không tìm thấy hoá đơn' using errcode='42501'; end if;

  select b.organization_id into v_org
    from public.buildings b
    join public.organizations o on o.id = b.organization_id and o.status='ACTIVE'
   where b.id = v_inv.building_id and b.deleted_at is null for share of o, b;
  if not found or v_org is null then
    raise exception 'Toà nhà của hoá đơn không thuộc tổ chức đang hoạt động' using errcode='42501';
  end if;
  if v_inv.organization_id is not null and v_inv.organization_id <> v_org then
    raise exception 'Hoá đơn lệch tổ chức' using errcode='42501';
  end if;

  -- (2) authorize BEFORE idempotency: exact thu_tien.collect, server-derived
  --     org + building scope (+ cashbook when an account is used).
  perform app_private.lock_org_for_decision_v1(v_org);
  select * into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.collect', v_inv.building_id, p_account_id);
  if not coalesce(v_authz.allowed,false) then
    raise exception 'Không có quyền thu tiền (thu_tien.collect)' using errcode='42501';
  end if;

  if p_voucher_owner_id is not null and p_voucher_owner_id <> v_inv.user_id then
    raise exception 'p_voucher_owner_id phải là chủ hoá đơn' using errcode='42501';
  end if;
  v_owner := v_inv.user_id;

  -- (3) validate every foreign resource to the SAME org; build canonical payload.
  if p_account_id is not null then
    perform 1 from public.accounts a
     where a.id = p_account_id and a.deleted_at is null and a.organization_id = v_org for share;
    if not found then raise exception 'Sổ quỹ không thuộc tổ chức của hoá đơn' using errcode='42501'; end if;
  end if;

  perform 1 from public.contracts c
   where c.id = v_inv.contract_id and c.deleted_at is null and c.organization_id = v_org for share;
  if not found then raise exception 'Hợp đồng của hoá đơn không thuộc tổ chức' using errcode='42501'; end if;

  if p_voucher is not null then
    v_room := nullif(p_voucher->>'room_id','')::uuid;
    v_chg  := nullif(p_voucher->>'change_account_id','')::uuid;
    v_rnd  := nullif(p_voucher->>'rounding_account_id','')::uuid;
    if v_room is not null then
      perform 1 from public.rooms r where r.id=v_room and r.deleted_at is null
        and r.building_id=v_inv.building_id and r.organization_id=v_org for share;
      if not found then raise exception 'Phòng của phiếu không thuộc toà/tổ chức' using errcode='42501'; end if;
    end if;
    if v_chg is not null then
      perform 1 from public.accounts a where a.id=v_chg and a.deleted_at is null and a.organization_id=v_org for share;
      if not found then raise exception 'Sổ quỹ tiền thối không thuộc tổ chức' using errcode='42501'; end if;
    end if;
    if v_rnd is not null then
      perform 1 from public.accounts a where a.id=v_rnd and a.deleted_at is null and a.organization_id=v_org for share;
      if not found then raise exception 'Sổ quỹ làm tròn không thuộc tổ chức' using errcode='42501'; end if;
    end if;
  end if;

  if p_items is not null then
    if jsonb_typeof(p_items) <> 'array' then raise exception 'items phải là mảng'; end if;
    for it in select value from jsonb_array_elements(p_items) loop
      v_idx := v_idx + 1;
      v_type_id := nullif(it->>'income_expense_type_id','')::uuid;
      if v_type_id is null then raise exception 'Hạng mục % thiếu loại thu', v_idx; end if;
      perform 1 from public.income_expense_types t
       where t.id=v_type_id and lower(t.type)='income' and t.organization_id=v_org for share;
      if not found then raise exception 'Loại hạng mục % không thuộc tổ chức/sai chiều thu', v_idx using errcode='42501'; end if;
      v_items := v_items || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'income_expense_type_id', v_type_id,
        'description', nullif(btrim(it->>'description'),''),
        'quantity', coalesce((it->>'quantity')::numeric,1),
        'unit_price', round((it->>'unit_price')::numeric,2),
        'start_date', nullif(it->>'start_date','')::date,
        'end_date', nullif(it->>'end_date','')::date)));
    end loop;
  end if;

  v_payload := jsonb_strip_nulls(jsonb_build_object(
    'invoice_id', p_invoice_id, 'organization_id', v_org, 'amount', v_amount,
    'payment_method', p_payment_method::text, 'payment_date', p_payment_date,
    'account_id', p_account_id, 'receipt_number', nullif(btrim(p_receipt_number),''),
    'receipt_image_url', nullif(btrim(p_receipt_image_url),''),
    'notes', nullif(p_notes,''), 'voucher_owner_id', v_owner,
    'room_id', v_room, 'change_account_id', v_chg, 'rounding_account_id', v_rnd,
    'items', v_items));
  v_hash := md5(v_payload::text);

  -- (4) durable idempotency claim = linearization point (AFTER authz).
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_invoice_id::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;

  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_invoice_id::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if not found then raise exception 'Không nhận diện được operation idempotency' using errcode='55000'; end if;

  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505';
  end if;
  if v_op.completed_at is not null then
    return v_op.response_payload::json; -- replay original; survives OFF/freeze
  end if;

  -- (4b) Cross-ledger guard (route-flip race), NEW CLAIMANTS ONLY — phải đứng
  -- SAU replay-return: voucher do chính v4 tạo cũng stamp idempotency_key, nên
  -- đặt guard trước replay sẽ 23505 nhầm chính op đã hoàn tất của v4 (bắt được
  -- nhờ canary live 2026-07-18, t1b_90 replay-không-voucher không lộ). Với claim
  -- MỚI: key đã bị đường LEGACY v3 tiêu thụ (stamp trên income_expenses) mà
  -- re-execute canonical thì retry vắt qua flip sẽ double-pay → 23505 hiển thị.
  -- Residual: v3 không voucher-mirror không stamp key (gap có sẵn của v3).
  if exists (select 1 from public.income_expenses ie
              where ie.idempotency_key = v_key and ie.deleted_at is null) then
    raise exception 'idempotency_key đã dùng ở đường legacy (v3)' using errcode='23505';
  end if;

  -- (5) rollout admission — new claimant only. Default OFF ⇒ blocked.
  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then
    raise exception 'Writer thu tiền chưa bật cho tổ chức này' using errcode='55000';
  end if;

  -- (5b) rollout cap accounting + enforcement. FOR UPDATE serializes concurrent
  -- admits per feature; ops row rolls back with the tx nếu effects fail.
  -- Count-cap enforce ở evaluate_feature_route lần gọi SAU (count >= max →
  -- FROZEN → thông điệp "chưa bật" → client coexistence-fallback về legacy).
  -- Amount-caps enforce tại đây cho mode CANARY; thông điệp giữ cụm "chưa bật"
  -- để adapter route giao dịch vượt hạn mức về legacy thay vì fail user.
  select * into v_flag from app_private.server_feature_flags
   where feature_key = c_op for update;
  if v_flag.mode = 'CANARY' then
    if v_amount > v_flag.max_single_amount_vnd then
      raise exception 'Writer thu tiền chưa bật cho giao dịch này (vượt hạn mức đơn lẻ canary)'
        using errcode='55000';
    end if;
    if coalesce((select sum(o.amount_vnd)
                   from app_private.server_feature_flag_operations o
                  where o.feature_key = c_op
                    and o.config_version = v_flag.config_version), 0) + v_amount
       > v_flag.max_total_amount_vnd then
      raise exception 'Writer thu tiền chưa bật cho giao dịch này (vượt tổng hạn mức canary)'
        using errcode='55000';
    end if;
  end if;
  insert into app_private.server_feature_flag_operations
    (feature_key, config_version, operation_key, organization_id, amount_vnd)
  values (c_op, v_flag.config_version, v_key || ':' || p_invoice_id::text, v_org, v_amount)
  on conflict do nothing;

  -- (6) effects — atomic, all org-stamped (v3 omits org).
  insert into public.payments
    (invoice_id, organization_id, user_id, amount, payment_method, payment_date,
     notes, receipt_image_url, receipt_number)
  values (p_invoice_id, v_org, v_owner, v_amount, p_payment_method, p_payment_date,
          p_notes, p_receipt_image_url, p_receipt_number)
  returning id into v_payment_id;

  v_new_paid := coalesce(v_inv.paid_amount,0) + v_amount;
  if v_new_paid >= v_inv.total_amount then
    v_status := 'PAID'; v_paid_date := p_payment_date; v_excess := v_new_paid - v_inv.total_amount;
    if v_excess > 0 then
      insert into public.excess_amounts
        (contract_id, organization_id, user_id, amount, description, source_invoice_id, source_payment_id)
      values (v_inv.contract_id, v_org, v_owner, v_excess,
              'Tiền thừa từ hoá đơn ' || coalesce(v_inv.invoice_number,''), p_invoice_id, v_payment_id);
    end if;
  else
    v_status := 'PARTIAL_PAID'; v_paid_date := null;
  end if;

  update public.invoices set paid_amount=v_new_paid, status=v_status::invoice_status, paid_date=v_paid_date
   where id = p_invoice_id;

  if p_account_id is not null and p_voucher is not null then
    insert into public.income_expenses (
      user_id, organization_id, type, name, building_id, room_id, contract_id,
      account_id, invoice_id, payment_id, voucher_date, payer_name, notes, attachments,
      approval_status, approved_by, approved_at, idempotency_key)
    values (
      v_owner, v_org, 'INCOME', coalesce(p_voucher->>'name','Thu tiền hoá đơn'),
      v_inv.building_id, v_room, v_inv.contract_id, p_account_id, p_invoice_id, v_payment_id,
      p_payment_date, p_voucher->>'payer_name', p_voucher->>'notes',
      coalesce(p_voucher->'attachments','[]'::jsonb),
      'APPROVED', v_actor, now(), v_key)
    returning id into v_voucher_id;
    insert into public.income_expense_items
      (income_expense_id, organization_id, income_expense_type_id, description,
       quantity, unit_price, start_date, end_date)
    select v_voucher_id, v_org, (x->>'income_expense_type_id')::uuid, x->>'description',
      coalesce((x->>'quantity')::numeric,1), (x->>'unit_price')::numeric,
      nullif(x->>'start_date','')::date, nullif(x->>'end_date','')::date
    from jsonb_array_elements(v_items) as x;
  end if;

  -- (7) complete the operation durably.
  v_resp := json_build_object('payment_id', v_payment_id, 'voucher_id', v_voucher_id,
    'new_paid_amount', v_new_paid, 'new_status', v_status, 'excess_amount', v_excess);
  update app_private.canonical_write_operations
     set subject_id=v_payment_id, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op and subject_scope=p_invoice_id::text
     and actor_id=v_actor and idempotency_key=v_key;

  return v_resp;
end;
$_$;








--
-- Name: _reverse_invoice_payment_v3_legacy(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._reverse_invoice_payment_v3_legacy(p_payment_id uuid, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_authz boolean;
  v_pay record;
  v_inv record;
  v_key text;
  v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  v_refund_voucher uuid;
  v_refund_type uuid;
  v_excess_total numeric(15,2);
  v_resp json;
  c_op constant text := 'invoice.reverse_payment.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if char_length(v_key) < 8 or char_length(v_key) > 200
     or v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if coalesce(length(btrim(p_reason)),0) < 5 then
    raise exception 'Lý do hoàn tác quá ngắn'; end if;

  -- lock the original payment + its invoice; derive org from building.
  select p.id, p.invoice_id, p.amount, p.payment_date
    into v_pay from public.payments p where p.id = p_payment_id for update;
  if not found then raise exception 'Không tìm thấy giao dịch thu' using errcode='42501'; end if;

  select i.id, i.building_id, i.room_id, i.contract_id, i.organization_id
    into v_inv from public.invoices i where i.id = v_pay.invoice_id and i.deleted_at is null for update;
  if not found then raise exception 'Hoá đơn không còn tồn tại' using errcode='42501'; end if;

  select b.organization_id into v_org from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.id=v_inv.building_id and b.deleted_at is null for share of o,b;
  if not found or v_org is null then
    raise exception 'Toà nhà không thuộc tổ chức đang hoạt động' using errcode='42501'; end if;

  -- exact permission thu_tien.undo (NOT a new key), building-scoped.
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.undo', v_inv.building_id, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền hoàn tác thu tiền (thu_tien.undo)' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object('payment_id',p_payment_id,'org',v_org,'amount',v_pay.amount)::text);

  -- durable idempotency claim FIRST — a same-key replay must return the original
  -- response before the anti-double check (otherwise a legitimate retry looks
  -- like a double-reversal).
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_payment_id::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_payment_id::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  -- anti-double (a DIFFERENT key trying to reverse an already-reversed payment).
  if exists (select 1 from app_private.payment_reversals where original_payment_id = p_payment_id) then
    raise exception 'Giao dịch đã được hoàn tác' using errcode='55000'; end if;
  -- cannot reverse a refund voucher's own payment (there is none, but guard the
  -- case where p_payment_id is a reversal target).
  if exists (select 1 from app_private.payment_reversals pr
             where pr.reversal_voucher_id in (
               select ie.id from public.income_expenses ie where ie.payment_id = p_payment_id)) then
    raise exception 'Không thể hoàn tác một bút toán hoàn tác' using errcode='55000'; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then
    raise exception 'Writer hoàn tác chưa bật cho tổ chức này' using errcode='55000'; end if;

  -- Forward-fix: compensating REFUND voucher (EXPENSE, type 'Tiền thối') that
  -- the live recompute_invoice_for_id SUBTRACTS from paid_amount. Original
  -- payment row stays intact. Get-or-create the org's refund type.
  select id into v_refund_type from public.income_expense_types
   where organization_id = v_org and name = 'Tiền thối' and lower(coalesce(type,'expense'))='expense'
   limit 1;
  if v_refund_type is null then
    insert into public.income_expense_types (organization_id, name, type)
    values (v_org, 'Tiền thối', 'expense') returning id into v_refund_type;
  end if;

  insert into public.income_expenses
    (user_id, organization_id, type, name, building_id, room_id, contract_id,
     invoice_id, voucher_date, approval_status, approved_by, approved_at, notes)
  values
    (v_actor, v_org, 'EXPENSE', 'Hoàn tác thu tiền', v_inv.building_id, v_inv.room_id,
     v_inv.contract_id, v_inv.id, v_pay.payment_date, 'APPROVED', v_actor, now(),
     'Hoàn tác: ' || p_reason)
  returning id into v_refund_voucher;
  insert into public.income_expense_items
    (income_expense_id, organization_id, income_expense_type_id, description, quantity, unit_price)
  values (v_refund_voucher, v_org, v_refund_type, 'Hoàn tác thu tiền', 1, v_pay.amount);

  -- recompute needs a nudge (item insert doesn't fire the payments trigger);
  -- touch the invoice's payments to re-run recompute deterministically.
  perform recompute_invoice_for_id(v_inv.id);

  -- record the reversal linkage (anti-double).
  insert into app_private.payment_reversals
    (original_payment_id, reversal_voucher_id, organization_id, actor_id, reason)
  values (p_payment_id, v_refund_voucher, v_org, v_actor, p_reason);

  -- negate any excess credit from the original payment (compensating row).
  select coalesce(sum(amount),0) into v_excess_total from public.excess_amounts
   where source_payment_id = p_payment_id;
  if v_excess_total <> 0 then
    insert into public.excess_amounts
      (contract_id, organization_id, user_id, amount, description, source_invoice_id, source_payment_id)
    values (v_inv.contract_id, v_org, v_actor, -v_excess_total,
            'Hoàn tác tiền thừa', v_inv.id, p_payment_id);
  end if;

  v_resp := json_build_object('reversal_voucher_id', v_refund_voucher,
    'original_payment_id', p_payment_id, 'reversed_amount', v_pay.amount);
  update app_private.canonical_write_operations
     set subject_id=v_refund_voucher, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op and subject_scope=p_payment_id::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: _termination_apply_extra_charges(uuid, jsonb, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._termination_apply_extra_charges(p_invoice_id uuid, p_extra_charges jsonb, p_date date, p_user_id uuid, p_contract_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  rec      RECORD;
  v_total  numeric(15,2) := 0;
  v_sort   integer;
  v_kind   text;
  v_desc   text;
  v_amount numeric(15,2);
  v_prev   numeric(10,2);
  v_curr   numeric(10,2);
  v_unit   numeric(15,2);
  v_meter  uuid;
  v_type   invoice_item_type;
BEGIN
  IF p_invoice_id IS NULL
     OR p_extra_charges IS NULL
     OR jsonb_typeof(p_extra_charges) <> 'array' THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_sort
    FROM invoice_items WHERE invoice_id = p_invoice_id;

  FOR rec IN SELECT j FROM jsonb_array_elements(p_extra_charges) AS t(j) LOOP
    v_amount := NULLIF(rec.j->>'amount', '')::numeric;
    IF v_amount IS NULL OR v_amount <= 0 THEN CONTINUE; END IF;

    v_kind := COALESCE(rec.j->>'kind', 'CUSTOM');
    v_desc := COALESCE(NULLIF(btrim(rec.j->>'description'), ''), 'Khoản thu thêm');
    v_unit := NULLIF(rec.j->>'unit_price', '')::numeric;
    v_prev := NULLIF(rec.j->>'previous_reading', '')::numeric;
    v_curr := NULLIF(rec.j->>'current_reading', '')::numeric;
    v_type := CASE v_kind
                WHEN 'PRORATED' THEN 'RENT'
                WHEN 'ELECTRIC' THEN 'SERVICE'
                ELSE 'OTHER' END::invoice_item_type;

    INSERT INTO invoice_items (invoice_id, type, description, unit_price, quantity, coefficient, amount, previous_reading, current_reading, sort_order)
    VALUES (p_invoice_id, v_type, v_desc, COALESCE(v_unit, v_amount), 1, 1, v_amount, v_prev, v_curr, v_sort);
    v_sort  := v_sort + 1;
    v_total := v_total + v_amount;

    -- Chốt số điện → ghi 1 bản ghi meter_readings đã duyệt. Không chặn thanh lý
    -- nếu chèn lỗi (vd trùng chỉ số tháng) — bọc trong sub-block.
    IF v_kind = 'ELECTRIC' AND v_curr IS NOT NULL THEN
      v_meter := NULLIF(rec.j->>'meter_id', '')::uuid;
      IF v_meter IS NOT NULL THEN
        BEGIN
          -- reading_code unique TOÀN CỤC nhưng generator mặc định đánh số theo
          -- user → đụng mã giữa các user. Cấp mã riêng (prefix TLY = thanh lý)
          -- để bỏ qua trigger auto_generate_reading_code và không đụng độ.
          INSERT INTO meter_readings (user_id, contract_id, meter_id, reading_code, reading_date, previous_reading, current_reading, status, approved_by, approved_at)
          VALUES (p_user_id, p_contract_id, v_meter,
                  'TLY' || to_char(p_date,'YYYYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),
                  p_date, COALESCE(v_prev, 0), v_curr, 'APPROVED', auth.uid(), NOW());
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;
  END LOOP;

  IF v_total > 0 THEN
    UPDATE invoices
       SET subtotal     = COALESCE(subtotal, 0) + v_total,
           total_amount = COALESCE(total_amount, 0) + v_total,
           updated_at   = NOW()
     WHERE id = p_invoice_id;
  END IF;

  RETURN v_total;
END $$;








--
-- Name: _termination_ensure_type(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._termination_ensure_type(p_user_id uuid, p_type text, p_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid; v_org uuid;
begin
  -- org của người thao tác: 1 membership → dùng luôn; nhiều → ưu tiên org
  -- mà user giữ role "Chủ sở hữu tổ chức" (owner thật thuộc cả demo).
  select min(m.organization_id::text)::uuid into v_org
    from organization_memberships m
   where m.user_id = p_user_id and m.status = 'ACTIVE';
  if (select count(distinct m.organization_id) from organization_memberships m
       where m.user_id = p_user_id and m.status = 'ACTIVE') > 1 then
    select rb.organization_id into v_org
      from role_bindings rb
      join organization_memberships m
        on m.id = rb.membership_id and m.organization_id = rb.organization_id
       and m.user_id = p_user_id and m.status = 'ACTIVE'
      join organization_roles r on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
     limit 1;
  end if;

  -- (1) TRA THEO ĐÚNG PHẠM VI MÀ UNIQUE INDEX CHẶN.
  --     income_expense_types_org_side_normalized_name_uq =
  --       (organization_id, lower(btrim(type)), normalize_income_expense_type_name(name))
  --     Tra theo user_id như bản cũ là tra hẹp hơn chỗ bị chặn ⇒ loại phiếu do
  --     người KHÁC trong cùng org đứng tên thì tra không thấy, INSERT xuống là
  --     23505. Đúng lỗi làm confirm_cash_handover chết với mọi người.
  if v_org is not null then
    select t.id into v_id
      from income_expense_types t
     where t.organization_id = v_org
       and lower(btrim(t.type)) = lower(btrim(p_type))
       and normalize_income_expense_type_name(t.name)
           = normalize_income_expense_type_name(p_name)
     limit 1;

    if v_id is not null then
      update income_expense_types
         set force_approval = true
       where id = v_id and force_approval = false;
      return v_id;
    end if;
  end if;

  -- (2) Nhánh cũ, giữ lại cho những dòng còn organization_id IS NULL (chưa được
  --     gắn org) — index không chặn chúng nên vẫn phải tự tìm theo người tạo.
  select id into v_id
    from income_expense_types
   where user_id = p_user_id
     and lower(name) = lower(p_name)
     and lower(type) = lower(p_type)
   limit 1;

  if v_id is not null then
    update income_expense_types
       set force_approval = true,
           organization_id = coalesce(organization_id, v_org)
     where id = v_id and (force_approval = false or organization_id is null);
    return v_id;
  end if;

  insert into income_expense_types (user_id, organization_id, type, name, description, force_approval)
  values (p_user_id, v_org, lower(p_type), p_name,
          'Tự tạo khi thanh lý hợp đồng', true)
  returning id into v_id;

  return v_id;
end;
$$;








--
-- Name: FUNCTION _termination_ensure_type(p_user_id uuid, p_type text, p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._termination_ensure_type(p_user_id uuid, p_type text, p_name text) IS 'Bảo đảm có loại thu/chi hệ thống. Tra theo (organization_id, type, tên chuẩn hoá) — ĐÚNG phạm vi mà income_expense_types_org_side_normalized_name_uq chặn. Bản cũ tra theo user_id nên loại phiếu do người khác trong cùng org đứng tên thì tra không thấy rồi INSERT đâm vào index (23505) — đã làm confirm_cash_handover chết với MỌI người trong org thật.';








--
-- Name: _termination_free_billing_month(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._termination_free_billing_month(p_contract_id uuid, p_start text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE m text := p_start; i int := 0;
BEGIN
  WHILE i < 60 AND EXISTS (
    SELECT 1 FROM invoices
     WHERE contract_id = p_contract_id AND billing_month = m
       AND deleted_at IS NULL AND status <> 'CANCELLED'
  ) LOOP
    m := to_char((to_date(m || '-01','YYYY-MM-DD') + interval '1 month'), 'YYYY-MM');
    i := i + 1;
  END LOOP;
  RETURN m;
END $$;








--
-- Name: _termination_offset_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._termination_offset_account(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id
    FROM accounts
   WHERE user_id = p_user_id
     AND deleted_at IS NULL
     AND name = 'Cấn trừ thanh lý (nội bộ)'
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO accounts (user_id, name, description, initial_amount)
  VALUES (p_user_id, 'Cấn trừ thanh lý (nội bộ)',
          'Sổ kỹ thuật: bút toán đối trừ khi thanh lý (doanh thu cấn cọc). Số dư luôn = 0.', 0)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;








--
-- Name: _termination_pick_account(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._termination_pick_account(p_user_id uuid, p_building_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    -- 1) Sổ tiền mặt cấu hình cho toà (nơi thu tiền thuê).
    (SELECT b.default_account_id_tt FROM buildings b
      WHERE b.id = p_building_id AND b.default_account_id_tt IS NOT NULL
        AND EXISTS (SELECT 1 FROM accounts a WHERE a.id = b.default_account_id_tt AND a.deleted_at IS NULL AND a.is_virtual = false)),
    -- 2) Sổ ngân hàng cấu hình cho toà.
    (SELECT b.default_account_id_tk FROM buildings b
      WHERE b.id = p_building_id AND b.default_account_id_tk IS NOT NULL
        AND EXISTS (SELECT 1 FROM accounts a WHERE a.id = b.default_account_id_tk AND a.deleted_at IS NULL AND a.is_virtual = false)),
    -- 3) Fallback: trùng tên toà → is_default → tạo sớm nhất; né sổ ảo bằng CỜ.
    (SELECT a.id
       FROM accounts a, (SELECT name FROM buildings WHERE id = p_building_id) bld
      WHERE a.user_id = p_user_id
        AND a.deleted_at IS NULL
        AND a.is_virtual = false
        AND a.name NOT IN ('Cấn trừ thanh lý (nội bộ)', 'Làm tròn tiền thiếu')
      ORDER BY (a.name = bld.name) DESC, a.is_default DESC NULLS LAST, a.created_at
      LIMIT 1)
  );
$$;








