--
-- Name: ai_copilot_perms_for(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_copilot_perms_for(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_out jsonb;
begin
  if p_user is null then
    return '{}'::jsonb;
  end if;
  if exists (select 1 from public.super_admins s where s.user_id = p_user) then
    return '{"__superadmin": true}'::jsonb;
  end if;

  select coalesce(jsonb_object_agg(g.resource, g.actions), '{}'::jsonb)
    into v_out
    from (
      select pd.resource, jsonb_object_agg(pd.action, true) as actions
        from public.permission_definitions pd
       where pd.permission_domain = 'TENANT'
         and pd.is_active
         and exists (
           select 1
             from public.organization_memberships m
             join public.organizations o
               on o.id = m.organization_id and o.status = 'ACTIVE'
             join public.role_bindings rb
               on rb.membership_id = m.id and rb.valid_to is null
             join public.organization_roles orl
               on orl.id = rb.role_id and coalesce(orl.status,'ACTIVE') = 'ACTIVE'
             join public.role_permissions rp
               on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
              and rp.permission_key = pd.key and rp.effect = 'ALLOW'
             join public.role_binding_scopes rbs on rbs.role_binding_id = rb.id
             join public.authorization_scopes s
               on s.id = rbs.scope_id and s.scope_type = any (pd.scope_kinds)
            where m.user_id = p_user and m.status = 'ACTIVE')
       group by pd.resource
    ) g;

  return coalesce(v_out, '{}'::jsonb);
end
$$;








--
-- Name: annotate_income_expense_v1(uuid, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.annotate_income_expense_v1(p_voucher uuid, p_add_attachments jsonb DEFAULT NULL::jsonb, p_remove_attachments jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text, p_note_mode text DEFAULT 'REPLACE'::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_row public.income_expenses%ROWTYPE;
  v_actor uuid := auth.uid();
  v_membership uuid;
  v_is_super boolean;
  v_is_owner boolean;
  v_can_edit boolean;
  v_locked boolean;
  v_key text;
  v_prev jsonb;
  v_next_att jsonb;
  v_next_notes text;
  v_url text;
  v_added int := 0;
  v_removed int := 0;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_note_mode NOT IN ('REPLACE', 'APPEND') THEN
    RAISE EXCEPTION 'p_note_mode phải là REPLACE hoặc APPEND' USING ERRCODE = '22023';
  END IF;

  -- WP1 (điểm 5): tham số này trước đây khai rồi bỏ đó, không dòng nào đọc.
  v_key := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  IF v_key IS NOT NULL AND length(v_key) > 200 THEN
    RAISE EXCEPTION 'p_idempotency_key tối đa 200 ký tự' USING ERRCODE = '22023';
  END IF;

  -- FOR UPDATE giữ luôn vai trò hàng rào chống lặp song song: hai lần gọi cùng
  -- key chạy song song sẽ xếp hàng ở đây, lần sau đọc được sổ idempotency.
  SELECT * INTO v_row FROM public.income_expenses
   WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  v_is_super := public.is_super_admin();

  SELECT m.id INTO v_membership
  FROM public.organization_memberships m
  WHERE m.user_id = v_actor AND m.organization_id = v_row.organization_id
    AND m.status = 'ACTIVE'
  LIMIT 1;

  IF v_membership IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  -- Chủ tổ chức / super admin: cửa duy nhất còn gỡ được bằng chứng.
  v_is_owner := v_is_super OR app_private.is_org_owner_v1(v_row.organization_id, v_actor);

  -- Quyền sửa "thật" trên toà (quyết định #4: thêm Chủ tổ chức / Super Admin).
  v_can_edit := v_is_owner
             OR app_private.ie_can_edit_money_axis_v1(v_row.organization_id, v_row.building_id);

  -- Ai được đính ảnh/ghi chú: quyền sửa, HOẶC đang giữ/biết sổ, HOẶC là người
  -- lập phiếu (giữ nguyên tầm với của luồng dán ảnh hiện tại).
  IF NOT (
       v_can_edit
    OR v_row.user_id = v_actor
    OR app_private.ie_has_cashbook_possession_v1(
         v_row.organization_id, v_row.account_id, v_membership)
  ) THEN
    RAISE EXCEPTION 'Không có quyền bổ sung ảnh/ghi chú cho phiếu này'
      USING ERRCODE = '42501';
  END IF;

  -- RPC là SECURITY DEFINER nên không hưởng policy RESTRICTIVE hạng mục hạn chế.
  IF COALESCE(v_row.has_restricted_item, false)
     AND v_row.user_id IS DISTINCT FROM v_actor
     AND NOT public.can_view_restricted_ie()
     AND NOT v_is_super THEN
    RAISE EXCEPTION 'Phiếu chứa hạng mục hạn chế — không có quyền' USING ERRCODE = '42501';
  END IF;

  -- WP1 (điểm 5+6): chống lặp. CỐ Ý đặt SAU cổng quyền — người lạ đoán trúng
  -- một idempotency_key không được phát lại kết quả (trong đó có danh sách ảnh).
  IF v_key IS NOT NULL THEN
    SELECT k.result INTO v_prev
    FROM app_private.ie_annotate_idempotency k
    WHERE k.income_expense_id = p_voucher AND k.idempotency_key = v_key;
    IF v_prev IS NOT NULL THEN
      RETURN v_prev || jsonb_build_object('replayed', true);
    END IF;
  END IF;

  v_locked := app_private.ie_evidence_locked_v1(v_row.approval_status, v_row.posting_status);

  -- ── GỠ ẢNH (điểm 1) ───────────────────────────────────────────────
  -- Bậc 1 (đã có từ Đợt 2): gỡ là hành vi SỬA, đòi quyền sửa thật.
  -- Bậc 2 (WP1): phiếu đã rời bản nháp thì chỉ CHỦ TỔ CHỨC / SUPER ADMIN.
  -- Bậc 3 (WP1): và kỳ phải còn mở — phiếu đã lên sổ trong kỳ ĐÃ CHỐT thì
  --              KHÔNG AI gỡ được, kể cả chủ tổ chức. Đó là hàng rào giữ cho
  --              số đã chốt & đã chia cho cổ đông còn chứng từ đối soát.
  -- DÁN THÊM không đi qua đây: vẫn tự do ở mọi trạng thái, mọi kỳ (quyết định #8).
  IF p_remove_attachments IS NOT NULL
     AND jsonb_array_length(p_remove_attachments) > 0 THEN
    IF NOT v_can_edit THEN
      RAISE EXCEPTION 'Chỉ người có quyền sửa thu chi mới gỡ được ảnh chứng từ'
        USING ERRCODE = '42501';
    END IF;
    IF v_locked THEN
      IF NOT v_is_owner THEN
        RAISE EXCEPTION
          'Phiếu đã duyệt/ghi sổ — ảnh chứng từ là bằng chứng, chỉ chủ tổ chức mới gỡ được. Bạn vẫn dán thêm ảnh và ghi chú giải thích được.'
          USING ERRCODE = '42501';
      END IF;
      PERFORM app_private.assert_period_open_for_edit_v1(p_voucher, 'gỡ ảnh chứng từ của');
    END IF;
  END IF;

  -- Kiểm URL (cùng luật với create_income_expense_v1).
  IF p_add_attachments IS NOT NULL THEN
    FOR v_url IN SELECT jsonb_array_elements_text(p_add_attachments) LOOP
      IF v_url !~ '^https://' OR length(v_url) > 2048 OR v_url ~ '[[:cntrl:]]' THEN
        RAISE EXCEPTION 'Đường dẫn ảnh không hợp lệ' USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END IF;

  v_next_att := COALESCE(v_row.attachments, '[]'::jsonb);
  IF p_remove_attachments IS NOT NULL THEN
    v_next_att := app_private.ie_attachments_remove_v1(v_next_att, p_remove_attachments);
  END IF;
  IF p_add_attachments IS NOT NULL THEN
    -- Hợp nhất phía server: hai người cùng dán ảnh không đè mất của nhau, và
    -- dán lại đúng tấm cũ là no-op (nên không cần sổ idempotency riêng).
    v_next_att := app_private.ie_attachments_union_v1(v_next_att, p_add_attachments);
  END IF;

  IF jsonb_array_length(v_next_att) > 20 THEN
    RAISE EXCEPTION 'Tối đa 20 ảnh chứng từ trên một phiếu' USING ERRCODE = '22023';
  END IF;

  -- ── GHI CHÚ (điểm 3, 6, 7) ────────────────────────────────────────
  v_next_notes := v_row.notes;
  IF p_notes IS NOT NULL THEN
    IF length(p_notes) > 5000 THEN
      RAISE EXCEPTION 'Ghi chú tối đa 5000 ký tự' USING ERRCODE = '22023';
    END IF;

    v_next_notes := CASE
      WHEN p_note_mode = 'APPEND' AND COALESCE(v_row.notes, '') <> ''
        THEN CASE
          -- Nối chuỗi rỗng = không nối gì.
          WHEN btrim(p_notes) = '' THEN v_row.notes
          -- WP1 (điểm 6): đoạn định nối ĐÃ là đoạn cuối hiện tại ⇒ đây là cú
          -- bấm Lưu lần hai, không phải ý định viết trùng. Không nối nữa.
          WHEN right(v_row.notes, length(p_notes) + 1) = chr(10) || p_notes THEN v_row.notes
          ELSE v_row.notes || chr(10) || p_notes
        END
      ELSE p_notes
    END;

    -- WP1 (điểm 7): trần kiểm trên chuỗi KẾT QUẢ. Trước đây chỉ kiểm đầu vào
    -- nên APPEND lặp làm notes phình vô hạn (đo được 9801 ký tự sau 2 lần).
    IF length(COALESCE(v_next_notes, '')) > 5000 THEN
      RAISE EXCEPTION
        'Ghi chú sau khi nối dài % ký tự, vượt trần 5000. Hãy rút gọn nội dung định thêm.',
        length(v_next_notes)
        USING ERRCODE = '22023';
    END IF;

    -- WP1 (điểm 3): phiếu đã rời bản nháp thì ghi chú CHỈ ĐƯỢC NỐI THÊM.
    -- Chọn "nối thêm" thay vì dựng thêm một trục quyền mới, vì người GIỮ SỔ
    -- có nhu cầu chính đáng ghi chú lên phiếu của người khác (đối soát, ghi
    -- rõ đã nhận tiền mặt lúc nào) — cấm họ ghi là hỏng việc thật; cái phải
    -- cấm là XOÁ chữ của người khác. Chủ tổ chức vẫn viết đè được khi kỳ còn
    -- mở (ảnh chụp nhầm CMND, số điện thoại lỡ dán vào ghi chú...), và
    -- app_private.income_expense_change_log giữ nguyên văn bản cũ để đối soát.
    IF v_locked
       AND NOT app_private.ie_notes_append_only_v1(v_row.notes, v_next_notes) THEN
      IF NOT v_is_owner THEN
        RAISE EXCEPTION
          'Phiếu đã duyệt/ghi sổ — ghi chú chỉ được NỐI THÊM, không xoá/sửa phần đã có. Giữ nguyên nội dung cũ rồi viết tiếp ở cuối.'
          USING ERRCODE = '55000';
      END IF;
      PERFORM app_private.assert_period_open_for_edit_v1(p_voucher, 'viết đè ghi chú của');
    END IF;

    -- Dấu hiệu tiền trong ghi chú là LOGIC TIỀN (xem Đợt 0) — cấm thêm/gỡ.
    PERFORM app_private.assert_notes_markers_unchanged_v1(v_row.notes, v_next_notes);
  END IF;

  SELECT count(*) INTO v_added
    FROM jsonb_array_elements(v_next_att) e
   WHERE NOT COALESCE(v_row.attachments, '[]'::jsonb) @> jsonb_build_array(e.value);
  SELECT count(*) INTO v_removed
    FROM jsonb_array_elements(COALESCE(v_row.attachments, '[]'::jsonb)) e
   WHERE NOT v_next_att @> jsonb_build_array(e.value);

  IF v_next_att IS NOT DISTINCT FROM COALESCE(v_row.attachments, '[]'::jsonb)
     AND v_next_notes IS NOT DISTINCT FROM v_row.notes THEN
    v_result := jsonb_build_object('id', p_voucher, 'changed', false);
  ELSE
    PERFORM app_private.begin_ie_flex_write_v1(p_voucher, 'ANNOTATE');
    UPDATE public.income_expenses
       SET attachments = v_next_att,
           notes = v_next_notes
     WHERE id = p_voucher;
    PERFORM app_private.end_ie_flex_write_v1(p_voucher);

    -- Nguyên văn URL bị gỡ nằm ở app_private.income_expense_change_log
    -- (trigger z99_ie_change_log, migration 20260730220000) — ở đây chỉ ghi số
    -- lượng, và GIỮ NGUYÊN tiền tố cũ để mọi bộ lọc LIKE sẵn có vẫn khớp.
    PERFORM app_private.append_income_expense_event_v1(
      v_row.organization_id,
      p_voucher,
      'MANUAL_LOG',
      v_actor,
      NULL,
      v_row.approval_status,
      v_row.approval_status,
      CASE
        WHEN v_added > 0 AND v_removed > 0
          THEN format('Bổ sung/gỡ ảnh chứng từ (thêm %s, gỡ %s)', v_added, v_removed)
        WHEN v_added > 0   THEN format('Bổ sung ảnh chứng từ (%s)', v_added)
        WHEN v_removed > 0 THEN format('Gỡ ảnh chứng từ (%s)', v_removed)
        ELSE 'Sửa ghi chú'
      END
    );

    v_result := jsonb_build_object(
      'id', p_voucher,
      'changed', true,
      'attachments', v_next_att,
      'added', v_added,
      'removed', v_removed
    );
  END IF;

  IF v_key IS NOT NULL THEN
    INSERT INTO app_private.ie_annotate_idempotency
      (income_expense_id, idempotency_key, actor_id, result)
    VALUES (p_voucher, v_key, v_actor, v_result)
    ON CONFLICT (income_expense_id, idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END
$$;








--
-- Name: FUNCTION annotate_income_expense_v1(p_voucher uuid, p_add_attachments jsonb, p_remove_attachments jsonb, p_notes text, p_note_mode text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.annotate_income_expense_v1(p_voucher uuid, p_add_attachments jsonb, p_remove_attachments jsonb, p_notes text, p_note_mode text, p_idempotency_key text) IS 'Bổ sung ảnh chứng từ / ghi chú cho phiếu thu chi ở BẤT KỲ trạng thái nào. DÁN THÊM tự do; GỠ ẢNH chỉ khi phiếu còn là bản nháp, hoặc do chủ tổ chức và kỳ còn mở; GHI CHÚ trên phiếu đã rời bản nháp chỉ được nối thêm. Có sổ idempotency, trần 5000 ký tự tính trên chuỗi kết quả.';








--
-- Name: append_fee_attachment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_fee_attachment(p_voucher_id uuid, p_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bld     uuid;
  v_owner   uuid;
  v_del     timestamptz;
  v_creator uuid;
  v_can     boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_url), '') IS NULL THEN
    RAISE EXCEPTION 'Thiếu ảnh cần đính';
  END IF;

  SELECT ie.building_id, ie.deleted_at, ie.user_id
    INTO v_bld, v_del, v_creator
    FROM income_expenses ie
   WHERE ie.id = p_voucher_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002'; END IF;
  IF v_del IS NOT NULL THEN RAISE EXCEPTION 'Phiếu đã bị hủy'; END IF;

  SELECT b.user_id INTO v_owner FROM buildings b WHERE b.id = v_bld;

  v_can := public.is_admin() OR public.is_super_admin() OR v_owner = auth.uid()
           OR v_creator = auth.uid()
           OR (v_bld IS NOT NULL AND public.can_do_on_building('income_expenses', 'edit', v_bld));
  IF NOT v_can THEN
    RAISE EXCEPTION 'Bạn không có quyền sửa phiếu này' USING ERRCODE = '42501';
  END IF;

  UPDATE income_expenses
     SET attachments = COALESCE(attachments, '[]'::jsonb) || to_jsonb(p_url)
   WHERE id = p_voucher_id;

  RETURN jsonb_build_object('ok', true, 'voucher_id', p_voucher_id);
END;
$$;








--
-- Name: apply_contract_extension_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_contract_extension_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'DRAFT' AND NEW.status = 'APPROVED' THEN
    IF NEW.extension_type = 'UPDATE_EXISTING' THEN
      -- Cập nhật HĐ tại chỗ; KHÔNG đổi status (giữ ACTIVE).
      UPDATE contracts
      SET
        end_date      = NEW.new_end_date,
        rent_price    = COALESCE(NEW.new_rent_price, rent_price),
        total_deposit = COALESCE(NEW.new_deposit, total_deposit),
        updated_at    = NOW()
      WHERE id = NEW.contract_id;

      IF NEW.services_changed AND NEW.new_services IS NOT NULL THEN
        DELETE FROM contract_services WHERE contract_id = NEW.contract_id;
        INSERT INTO contract_services (contract_id, service_id, unit_price)
        SELECT NEW.contract_id, (service->>'service_id')::UUID, (service->>'unit_price')::DECIMAL(15,2)
        FROM jsonb_array_elements(NEW.new_services) AS service;
      END IF;
    END IF;

    NEW.approved_by := auth.uid();
    NEW.approved_at := NOW();
    NEW.status := 'COMPLETED';
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION apply_contract_extension_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_contract_extension_update() IS 'Applies contract extension by updating existing contract (UPDATE_EXISTING type)';








--
-- Name: apply_contract_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_contract_transfer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_bld uuid;
  v_new_bld uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'DRAFT' AND NEW.status = 'APPROVED' THEN

    IF NEW.transfer_type IN ('TENANT_CHANGE', 'BOTH_CHANGE') THEN
      RAISE EXCEPTION 'Nhượng hợp đồng phải đi qua RPC transfer_contract(); không duyệt tay contract_transfers (cột new_tenant_id nay là customers.id, không phải tenants.id)'
        USING ERRCODE = '55000';
    END IF;

    -- ══ FAIL-CLOSED: audit phải ĐỦ trước khi cho áp dụng ═══════════════
    -- Đường A luôn ghi đủ old_room_id/move_out_date/move_in_date. Đường B trước
    -- đây nhận bất cứ gì người duyệt để lại, nên có thể sinh ra dòng transfer
    -- thiếu mốc ⇒ projection segments không dựng được đoạn và phải báo
    -- SEGMENT_HISTORY_INCOMPLETE. Chặn tại gốc thì read model không bao giờ phải
    -- đoán. (Hôm nay 0 dòng đi đường này — đây là forward-guard.)
    IF NEW.transfer_type = 'ROOM_CHANGE' THEN
      IF NEW.new_room_id IS NULL THEN
        RAISE EXCEPTION 'Thiếu phòng mới (new_room_id) — không duyệt được phiếu chuyển phòng'
          USING ERRCODE = '22023';
      END IF;
      IF NEW.old_room_id IS NULL THEN
        RAISE EXCEPTION 'Thiếu phòng cũ (old_room_id) — audit chuyển phòng phải đủ hai đầu, nếu không thì không truy được khách ở phòng nào từ ngày nào'
          USING ERRCODE = '22023';
      END IF;
      IF COALESCE(NEW.move_out_date, NEW.transfer_date) IS NULL
         OR COALESCE(NEW.move_in_date, NEW.transfer_date) IS NULL THEN
        RAISE EXCEPTION 'Thiếu mốc ngày chuyển phòng (move_out_date/move_in_date hoặc transfer_date)'
          USING ERRCODE = '22023';
      END IF;

      -- Cùng toà — cùng mệnh đề như đường A, để hai đường không lệch luật.
      SELECT building_id INTO v_old_bld FROM public.rooms WHERE id = NEW.old_room_id;
      SELECT building_id INTO v_new_bld FROM public.rooms WHERE id = NEW.new_room_id;
      IF v_old_bld IS DISTINCT FROM v_new_bld THEN
        RAISE EXCEPTION 'Phòng mới thuộc toà khác — chuyển phòng chỉ trong cùng một toà'
          USING ERRCODE = '42501';
      END IF;

      -- Điền mốc còn trống bằng transfer_date để audit luôn đủ cột.
      NEW.move_out_date := COALESCE(NEW.move_out_date, NEW.transfer_date);
      NEW.move_in_date  := COALESCE(NEW.move_in_date,  NEW.transfer_date);
    END IF;

    -- ══ KHÔNG đụng kỳ hạn, KHÔNG đổi status hợp đồng ═══════════════════
    -- Trước đây khối này ghi đè start_date/end_date và đặt status='TRANSFERRED'
    -- + parent_contract_id=id cho CẢ ROOM_CHANGE. Đổi phòng KHÔNG phải nhượng
    -- hợp đồng: kỳ hạn không đổi, và hợp đồng vẫn CÒN HIỆU LỰC — đặt TRANSFERRED
    -- là làm nó biến mất khỏi mọi danh sách ACTIVE. Đường A (transfer_room) luôn
    -- giữ ACTIVE/EXTENDED; nay đường B giống hệt.
    UPDATE contracts
    SET
      room_id       = COALESCE(NEW.new_room_id, room_id),
      rent_price    = COALESCE(NEW.new_rent_price, rent_price),
      total_deposit = COALESCE(NEW.new_deposit, total_deposit),
      updated_at    = NOW()
    WHERE id = NEW.contract_id;

    IF NEW.old_room_id IS NOT NULL THEN
      UPDATE rooms
      SET status = 'AVAILABLE', updated_at = NOW()
      WHERE id = NEW.old_room_id
        AND NOT EXISTS (
          SELECT 1 FROM contracts
          WHERE room_id = NEW.old_room_id
            AND id != NEW.contract_id
            AND status IN ('ACTIVE','EXTENDED')
            AND deleted_at IS NULL
        );
    END IF;

    IF NEW.new_room_id IS NOT NULL THEN
      UPDATE rooms
      SET status = 'OCCUPIED', updated_at = NOW()
      WHERE id = NEW.new_room_id;
    END IF;

    IF NEW.new_services IS NOT NULL AND jsonb_array_length(NEW.new_services) > 0 THEN
      DELETE FROM contract_services WHERE contract_id = NEW.contract_id;

      INSERT INTO contract_services (contract_id, service_id, unit_price)
      SELECT
        NEW.contract_id,
        (service->>'service_id')::UUID,
        (service->>'unit_price')::DECIMAL(15,2)
      FROM jsonb_array_elements(NEW.new_services) AS service;
    END IF;

    NEW.approved_by := auth.uid();
    NEW.approved_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION apply_contract_transfer(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_contract_transfer() IS 'Trigger đường B (duyệt tay contract_transfers DRAFT→APPROVED). Đợt 2 Task 0 phương án (A): fail-closed — ROOM_CHANGE phải đủ old_room_id/new_room_id/mốc ngày và cùng toà, nếu không thì từ chối duyệt; và KHÔNG còn ghi đè start_date/end_date, KHÔNG còn đặt status=TRANSFERRED/parent_contract_id cho ROOM_CHANGE (đổi phòng không phải nhượng hợp đồng — đặt TRANSFERRED là làm hợp đồng còn hiệu lực biến mất khỏi danh sách ACTIVE). Hai đường A/B nay sinh cùng một hình dạng dữ liệu để projection segments không phải đoán.';








