--
-- Name: approve_and_post_income_expense_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_and_post_income_expense_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid;
  v_mid uuid;
  v_ie public.income_expenses;
  v_voucher uuid := (input->>'subjectId')::uuid;
  v_cashbook uuid := (input->>'cashbookId')::uuid;
  v_posted_on date := (input->>'postedOn')::date;
  v_idem text := input->>'idempotencyKey';
  v_exp_appr bigint := (input->>'expectedApprovalVersion')::bigint;
  v_exp_post bigint := (input->>'expectedPostingVersion')::bigint;
  v_evidence uuid[] := ARRAY(SELECT jsonb_array_elements_text(COALESCE(input->'evidenceIds','[]'::jsonb))::uuid);
  v_hash text := md5(input::text);
  v_op app_private.canonical_write_operations;
  v_posting_id uuid;
  v_new_appr bigint;
  v_new_post bigint;
  v_resp jsonb;
BEGIN
  IF COALESCE(input->>'subjectKind','VOUCHER') <> 'VOUCHER' THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: only VOUCHER subjects are supported here' USING ERRCODE = '22023';
  END IF;
  IF v_voucher IS NULL OR v_cashbook IS NULL OR v_posted_on IS NULL OR v_idem IS NULL THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: subjectId, cashbookId, postedOn, idempotencyKey are required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = v_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: voucher % not found', v_voucher USING ERRCODE = 'P0002';
  END IF;

  SELECT r.user_id, r.membership_id INTO v_uid, v_mid
  FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.approve_and_post.v2', v_voucher::text, v_uid, v_mid,
    v_idem, v_hash, v_voucher);
  IF v_op.completed_at IS NOT NULL THEN
    RETURN COALESCE(v_op.response_payload, '{}'::jsonb);
  END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(v_voucher, 'CANONICAL_INCOME_EXPENSE');

  -- Approver capability + committed birth boundary.
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: income_expenses.approve required in scope' USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.assert_committed_birth_boundary_v2(v_ie.birth_operation_id, v_voucher);

  -- Lock cashbook + CUSTODIAN of the exact cashbook.
  PERFORM 1 FROM public.accounts a WHERE a.id = v_cashbook AND a.organization_id = v_ie.organization_id
    AND a.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: cashbook % not found', v_cashbook USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.assert_cashbook_access_v2(v_ie.organization_id, v_cashbook, 'CUSTODIAN', v_mid);

  IF v_ie.posting_mode IS DISTINCT FROM 'CASHBOOK' THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: only CASHBOOK vouchers can be posted' USING ERRCODE = '55000';
  END IF;
  IF v_ie.approval_status IS DISTINCT FROM 'UNAPPROVED' OR COALESCE(v_ie.review_state, '') NOT IN ('PENDING','CHANGES_REQUESTED')
     OR v_ie.posting_status IS DISTINCT FROM 'UNPOSTED' THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: voucher not approvable+postable (%, %, %)',
      v_ie.approval_status, v_ie.review_state, v_ie.posting_status USING ERRCODE = '55000';
  END IF;
  IF v_ie.approval_version <> v_exp_appr OR v_ie.posting_version <> v_exp_post THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: version mismatch' USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.finance_v2_is_cashbook_period_open(v_ie.organization_id, v_cashbook, v_posted_on) THEN
    RAISE EXCEPTION 'approve_and_post_income_expense_v2: posted_on % is inside a locked cashbook period', v_posted_on USING ERRCODE = '55000';
  END IF;

  v_new_appr := v_ie.approval_version + 1;
  UPDATE public.income_expenses ie
     SET approval_status = 'APPROVED', approved_by = v_uid, approved_at = now(),
         review_state = 'RESOLVED', approval_version = v_new_appr, updated_at = now()
   WHERE ie.id = v_voucher;
  -- Reload with the fresh approval_version so the posting snapshots it.
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = v_voucher;

  UPDATE public.approval_requests ar
     SET state = 'APPROVED', outcome_kind = 'APPROVED',
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = v_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_posting_id := app_private.finance_v2_post_manual_voucher(
    v_ie, v_uid, v_mid, v_cashbook, v_posted_on, v_evidence, v_idem);

  v_new_post := v_ie.posting_version + 1;
  UPDATE public.income_expenses ie
     SET active_posting_id_v2 = v_posting_id, posting_status = 'POSTED',
         -- 7ah: stamp so quy TIEN THAT SU DI QUA len header (het "-" va het so sai)
         account_id = v_cashbook,
         posting_id = v_posting_id, posted_at_v2 = now(),
         posting_version = v_new_post, updated_at = now()
   WHERE ie.id = v_voucher;

  v_resp := jsonb_build_object('voucherId', v_voucher, 'postingId', v_posting_id,
                               'approvalStatus', 'APPROVED', 'postingStatus', 'POSTED',
                               'approvalVersion', v_new_appr, 'postingVersion', v_new_post);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.approve_and_post.v2', v_voucher::text, v_uid, v_idem, v_voucher,
    v_resp, 'APPROVED_AND_POSTED', v_ie.review_version, v_new_appr, v_new_post);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.approve_and_post.v2', v_voucher, v_uid, v_idem);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION approve_and_post_income_expense_v2(input jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_and_post_income_expense_v2(input jsonb) IS 'Plan §7.2/§7.3: atomic approve + post (approver AND CUSTODIAN); full rollback on any failure.';








--
-- Name: approve_contract_termination_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_contract_termination_v1(p_termination_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_term public.contract_terminations%rowtype;
  v_contract public.contracts%rowtype;
  v_building uuid;
  v_refund numeric;
  v_type_id uuid;
  v_voucher_id uuid;
  v_voucher_kind text;
  v_type_names text[];
  v_desc text;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;

  select * into v_term from public.contract_terminations
   where id = p_termination_id for update;
  if not found then
    raise exception 'Không tìm thấy yêu cầu thanh lý hoặc bạn không có quyền' using errcode = '42501';
  end if;

  select * into v_contract from public.contracts
   where id = v_term.contract_id for update;
  if not found then
    raise exception 'Hợp đồng của yêu cầu thanh lý không còn tồn tại';
  end if;

  -- contracts KHÔNG có cột building_id — toà suy qua phòng (helper chuẩn RLS).
  v_building := public.building_of_contract(v_contract.id);
  if not (public.is_super_admin()
          or public.can_do_on_building('contracts', 'edit', v_building)) then
    raise exception 'Không có quyền duyệt thanh lý hợp đồng này' using errcode = '42501';
  end if;

  if v_term.status = 'COMPLETED' then
    return jsonb_build_object('termination_id', v_term.id, 'status', 'COMPLETED',
                              'voucher_id', null, 'noop', true);
  end if;

  select coalesce(nullif(btrim(full_name), ''), nullif(btrim(email), ''), 'Người dùng')
    into v_actor_name from public.profiles where id = v_actor;

  -- 1-3: chuỗi trạng thái (giữ nguyên thứ tự legacy, nay atomic trong 1 tx)
  update public.contract_terminations
     set status = 'APPROVED', approved_by = v_actor, approved_at = now()
   where id = v_term.id;

  update public.contracts
     set status = 'TERMINATED', updated_at = now()
   where id = v_contract.id;

  update public.contract_terminations
     set status = 'COMPLETED', refund_date = now()
   where id = v_term.id;

  -- 4: bút toán tiền (thay cash_book đã chết) — phiếu NHÁP chờ kế toán
  v_refund := coalesce(v_term.refund_amount, 0);
  if v_refund <> 0 then
    if v_refund > 0 then
      v_voucher_kind := 'EXPENSE';
      v_type_names := array['Hoàn cọc / tiền thừa khi thanh lý',
                            'Hoàn trả thanh lý',
                            'Hoàn cọc thanh lý',
                            'Hoàn tiền thừa thanh lý'];
      v_desc := 'Hoàn cọc thanh lý hợp đồng';
    else
      v_voucher_kind := 'INCOME';
      v_type_names := array['Thu thanh lý (khách trả thêm)',
                            'Doanh thu thanh lý'];
      v_desc := 'Thu thêm từ thanh lý hợp đồng';
    end if;

    -- Resolve hạng mục trong org theo thứ tự ưu tiên; trùng tên → bản cũ nhất.
    select t.id into v_type_id
      from public.income_expense_types t
     where t.organization_id = v_term.organization_id
       and lower(t.type) = lower(v_voucher_kind)
       and t.name = any (v_type_names)
     order by array_position(v_type_names, t.name), t.created_at
     limit 1;
    if v_type_id is null then
      raise exception 'Org chưa có hạng mục "%" cho bút toán thanh lý — tạo hạng mục rồi duyệt lại',
        v_type_names[1];
    end if;

    insert into public.income_expenses (
      user_id, creator_name, type, name,
      building_id, room_id, contract_id, account_id,
      payer_name, approval_status, voucher_date, attachments,
      notes, organization_id
    ) values (
      v_actor, coalesce(v_actor_name, 'Người dùng'), v_voucher_kind,
      v_desc || ' ' || coalesce(v_contract.contract_number, left(v_contract.id::text, 8)),
      v_building, v_contract.room_id, v_contract.id, null,
      null, 'UNAPPROVED', public.org_today_v1(NULL), '[]'::jsonb,
      nullif(btrim(coalesce(p_note, '')), ''), v_term.organization_id
    ) returning id into v_voucher_id;

    insert into public.income_expense_items (
      income_expense_id, income_expense_type_id, description,
      quantity, unit_price, start_date, end_date
    ) values (
      v_voucher_id, v_type_id,
      v_desc || ' (yêu cầu ' || left(v_term.id::text, 8) || ')',
      1, abs(v_refund), public.org_today_v1(NULL), public.org_today_v1(NULL)
    );
  end if;

  -- 5: trả phòng
  if v_contract.room_id is not null then
    update public.rooms set status = 'AVAILABLE' where id = v_contract.room_id;
  end if;

  return jsonb_build_object('termination_id', v_term.id, 'status', 'COMPLETED',
                            'voucher_id', v_voucher_id, 'room_id', v_contract.room_id);
end;
$$;








--
-- Name: approve_device_issue(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_device_issue(p_session uuid, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sess public.inspection_sessions; v_tick JSONB;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ được duyệt sự cố thiết bị'; END IF;
  SELECT * INTO v_sess FROM public.inspection_sessions WHERE id = p_session;
  IF NOT FOUND OR v_sess.device_issue IS NULL THEN RAISE EXCEPTION 'Không có báo cáo sự cố ở phiên này'; END IF;
  UPDATE public.inspection_sessions SET
    device_issue = device_issue || jsonb_build_object('approved', p_approve, 'approved_by', auth.uid(), 'approved_at', now()),
    updated_at = now()
  WHERE id = p_session;
  IF p_approve THEN
    v_tick := public.v5_tick_attendance(v_sess.user_id, v_sess.session_date, 'MANUAL_DEVICE_ISSUE', p_session, 'duyệt sự cố thiết bị');
  END IF;
  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES (v_sess.user_id, 'CUSTOM', 'IN_APP', 'PENDING',
    CASE WHEN p_approve THEN 'Sự cố thiết bị đã duyệt ✅' ELSE 'Sự cố thiết bị chưa được duyệt' END,
    CASE WHEN p_approve THEN 'Ngày công ' || to_char(v_sess.session_date,'DD/MM') || ' đã được ghi nhận (duyệt tay do sự cố thiết bị)'
         ELSE 'Báo cáo sự cố ngày ' || to_char(v_sess.session_date,'DD/MM') || ' chưa được duyệt — trao đổi thêm với chủ nhé' END,
    jsonb_build_object('v5','device_issue_result','session_id', p_session, 'url', '/my-day'));
  RETURN jsonb_build_object('approved', p_approve, 'tick', v_tick);
END; $$;








--
-- Name: approve_income_expense_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_income_expense_v1(p_voucher_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_row public.income_expenses%rowtype;
  v_rows integer;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;

  select * into v_row from public.income_expenses
   where id = p_voucher_id and deleted_at is null
   for update;
  if not found then
    raise exception 'Không thể duyệt phiếu: phiếu không tồn tại hoặc bạn không có quyền duyệt phiếu này'
      using errcode = '42501';
  end if;

  -- Row legacy → tín hiệu fallback (hook chuyển sang approve_voucher legacy).
  if not app_private.is_income_expense_flow_owned(v_row.id) then
    raise exception 'Phiếu chưa thuộc luồng canonical — dùng đường legacy'
      using errcode = '55000';
  end if;

  if v_row.approval_status = 'APPROVED' then
    return; -- idempotent no-op
  end if;

  -- t5_26: phiếu đang chờ engine → chỉ quyết qua màn Chờ duyệt
  perform app_private.assert_no_engine_request_v1(v_row.id);

  if v_row.approval_status = 'CANCELLED' then
    -- Phương án A: phiếu huỷ là terminal — dùng nút "Tạo bản sao".
    raise exception 'Phiếu đã huỷ — không thể duyệt. Hãy dùng "Tạo bản sao" để lập phiếu mới.';
  end if;

  -- Parity legacy: phải có sổ quỹ trước khi duyệt.
  if v_row.account_id is null then
    raise exception 'Phiếu chưa có sổ quỹ — phiếu canonical không sửa được: Huỷ phiếu rồi Tạo bản sao kèm sổ quỹ.';
  end if;

  -- Permission parity với public.approve_voucher.
  if not (
    v_row.user_id = v_actor
    or public.is_super_admin()
    or (v_row.building_id is not null
        and public.can_do_on_building('income_expenses', 'approve', v_row.building_id))
  ) then
    raise exception 'Không thể duyệt phiếu: phiếu không tồn tại hoặc bạn không có quyền duyệt phiếu này'
      using errcode = '42501';
  end if;

  v_actor_name := app_private.ie_actor_display_name_v1(v_actor);

  insert into app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  values (v_row.id, pg_current_xact_id(), 'APPROVED');

  update public.income_expenses
     set approval_status = 'APPROVED',
         approved_by = v_actor,
         approved_at = now()
   where id = v_row.id;
  get diagnostics v_rows = row_count;

  delete from app_private.ie_transition_authorization
   where income_expense_id = v_row.id and xid = pg_current_xact_id();

  if v_rows <> 1 then
    raise exception 'approve transition affected % rows (expected 1)', v_rows
      using errcode = '55000';
  end if;

  perform app_private.append_income_expense_event_v1(
    v_row.organization_id, v_row.id, 'APPROVED', v_actor, v_actor_name,
    v_row.approval_status, 'APPROVED', 'Duyệt qua approve_income_expense_v1');
end;
$$;








--
-- Name: approve_income_expense_v2(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_income_expense_v2(p_voucher uuid, p_expected_approval_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid;
  v_mid uuid;
  v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('voucher', p_voucher, 'eav', p_expected_approval_version)::text);
  v_op app_private.canonical_write_operations;
  v_new_appr bigint;
  v_resp jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'approve_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  -- Fixed lock order: voucher first.
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'approve_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;

  SELECT r.user_id, r.membership_id INTO v_uid, v_mid
  FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.approve.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN
    RETURN COALESCE(v_op.response_payload, '{}'::jsonb);
  END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');

  -- Approver capability in the voucher's building scope.
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'approve_income_expense_v2: income_expenses.approve required in scope' USING ERRCODE = '42501';
  END IF;

  -- Committed birth boundary: create must have committed in a prior transaction.
  PERFORM app_private.assert_committed_birth_boundary_v2(v_ie.birth_operation_id, p_voucher);

  IF v_ie.approval_status IS DISTINCT FROM 'UNAPPROVED'
     OR COALESCE(v_ie.review_state, '') NOT IN ('PENDING','CHANGES_REQUESTED') THEN
    RAISE EXCEPTION 'approve_income_expense_v2: voucher not in an approvable state (%, %)',
      v_ie.approval_status, v_ie.review_state USING ERRCODE = '55000';
  END IF;
  IF v_ie.approval_version <> p_expected_approval_version THEN
    RAISE EXCEPTION 'approve_income_expense_v2: approval_version mismatch (expected %, found %)',
      p_expected_approval_version, v_ie.approval_version USING ERRCODE = '55000';
  END IF;

  v_new_appr := v_ie.approval_version + 1;
  UPDATE public.income_expenses ie
     SET approval_status = 'APPROVED', approved_by = v_uid, approved_at = now(),
         review_state = 'RESOLVED', approval_version = v_new_appr, updated_at = now()
   WHERE ie.id = p_voucher;

  -- Close the open PENDING_APPROVAL request (one-open lives only on PENDING_APPROVAL).
  UPDATE public.approval_requests ar
     SET state = 'APPROVED', outcome_kind = 'APPROVED', outcome_reason = NULL,
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'APPROVED',
                               'reviewState', 'RESOLVED', 'approvalVersion', v_new_appr);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.approve.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'APPROVED', v_ie.review_version, v_new_appr, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.approve.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








