    building_id uuid NOT NULL,
    room_id uuid NOT NULL,
    invoice_number text,
    billing_month text NOT NULL,
    issue_date date DEFAULT CURRENT_DATE NOT NULL,
    due_date date NOT NULL,
    paid_date date,
    status public.invoice_status DEFAULT 'DRAFT'::public.invoice_status NOT NULL,
    subtotal numeric(15,2) DEFAULT 0 NOT NULL,
    discount_amount numeric(15,2) DEFAULT 0 NOT NULL,
    total_amount numeric(15,2) DEFAULT 0 NOT NULL,
    prepaid_amount numeric(15,2) DEFAULT 0 NOT NULL,
    paid_amount numeric(15,2) DEFAULT 0 NOT NULL,
    remaining_amount numeric(15,2) GENERATED ALWAYS AS ((total_amount - COALESCE(paid_amount, (0)::numeric))) STORED,
    previous_debt numeric(15,2) DEFAULT 0 NOT NULL,
    notes text,
    template_id uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    creator_name text,
    discount_notes text,
    electricity_prev_overridden boolean DEFAULT false NOT NULL,
    previous_debt_sources jsonb DEFAULT '[]'::jsonb NOT NULL,
    kind text DEFAULT 'MONTHLY'::text NOT NULL,
    organization_id uuid NOT NULL,
    CONSTRAINT invoices_billing_month_format CHECK ((billing_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT invoices_issue_date_lte_due_date CHECK ((issue_date <= due_date)),
    CONSTRAINT invoices_kind_check CHECK ((kind = ANY (ARRAY['MONTHLY'::text, 'SETTLEMENT'::text])))
);








