--
-- Name: approve_invoice_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_invoice_v1(p_invoice_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.invoices%rowtype;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  select * into v_row from public.invoices
   where id = p_invoice_id and deleted_at is null for update;
  if not found then
    raise exception 'Không tìm thấy hoá đơn hoặc bạn không có quyền' using errcode = '42501';
  end if;
  if not app_private.can_edit_invoice_building_v1(v_row.building_id) then
    raise exception 'Không có quyền duyệt hoá đơn này' using errcode = '42501';
  end if;
  if v_row.status = 'APPROVED' then
    return v_row; -- idempotent no-op
  end if;
  if v_row.status <> 'DRAFT' then
    raise exception 'Chỉ duyệt được hoá đơn Nháp (trạng thái hiện tại: %)', v_row.status;
  end if;
  update public.invoices
     set status = 'APPROVED', approved_at = now(), approved_by = v_actor
   where id = v_row.id
   returning * into v_row;
  return v_row;
end;
$$;








--
-- Name: approve_leave(uuid, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave(p_user uuid, p_date date, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cur TEXT;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ được duyệt phép'; END IF;
  SELECT status INTO v_cur FROM public.salary_attendance_day WHERE user_id = p_user AND work_date = p_date;
  IF v_cur IS DISTINCT FROM 'pending_leave' THEN
    RAISE EXCEPTION 'Ngày này không ở trạng thái chờ duyệt phép';
  END IF;

  UPDATE public.salary_attendance_day SET
    status = CASE WHEN p_approve THEN 'leave_approved' ELSE 'pending' END,
    audit = audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', auth.uid(),
            'action', CASE WHEN p_approve THEN 'approve_leave' ELSE 'decline_leave' END)),
    updated_at = now()
  WHERE user_id = p_user AND work_date = p_date;

  PERFORM public.v5_recompute_streak(p_user, date_trunc('month', p_date)::date);

  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES (p_user, 'CUSTOM', 'IN_APP', 'PENDING',
    CASE WHEN p_approve THEN 'Phép đã duyệt ✅' ELSE 'Phép chưa được duyệt' END,
    CASE WHEN p_approve
      THEN 'Phép ngày ' || to_char(p_date,'DD/MM') || ' đã duyệt ✅ — ngày trung tính, chuỗi được bắc cầu, đơn giá ngày tự điều chỉnh'
      ELSE 'Phép ngày ' || to_char(p_date,'DD/MM') || ' chưa được duyệt — trao đổi thêm với chủ nhé' END,
    jsonb_build_object('v5','leave_result','date', p_date, 'approved', p_approve, 'url', '/my-day'));

  RETURN jsonb_build_object('approved', p_approve, 'date', p_date);
END; $$;








--
-- Name: approve_meter_reading(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_meter_reading(p_reading_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status TEXT;
BEGIN
  -- Look up the reading
  SELECT status INTO v_status
  FROM meter_readings
  WHERE id = p_reading_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy chỉ số hoặc chỉ số đã bị xoá';
  END IF;

  IF v_status = 'APPROVED' THEN
    RAISE EXCEPTION 'Chỉ số đã được duyệt';
  END IF;

  UPDATE meter_readings
  SET status = 'APPROVED',
      approved_by = auth.uid(),
      approved_at = NOW()
  WHERE id = p_reading_id
    AND deleted_at IS NULL;
END;
$$;








