--
-- Name: auto_calculate_termination_financials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_calculate_termination_financials() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_contract RECORD;
  v_days_in_month INTEGER;
  v_daily_rate DECIMAL(15,2);
  v_prorated_days INTEGER;
BEGIN
  SELECT c.start_date, c.end_date, c.rent_price, c.total_deposit
  INTO v_contract
  FROM contracts c
  WHERE c.id = NEW.contract_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract not found: %', NEW.contract_id;
  END IF;

  IF NEW.actual_move_out_date < v_contract.start_date THEN
    RAISE EXCEPTION 'Move-out date (%) cannot be before contract start date (%)',
      NEW.actual_move_out_date, v_contract.start_date;
  END IF;

  -- Các RPC thanh lý cung cấp SẴN số liệu quyết toán thực — trigger chỉ tự tính
  -- khi caller (UI/manual) KHÔNG cung cấp (IS NULL). Trước đây trigger ghi đè
  -- mọi giá trị bằng mô hình prorated cũ → audit sai lệch / vi phạm CHECK.
  IF NEW.outstanding_debt IS NULL THEN
    SELECT COALESCE(SUM(remaining_amount), 0)
    INTO NEW.outstanding_debt
    FROM invoices
    WHERE contract_id = NEW.contract_id
      AND status NOT IN ('PAID', 'CANCELLED');
  END IF;

  v_days_in_month := EXTRACT(DAY FROM (
    DATE_TRUNC('month', NEW.actual_move_out_date) + INTERVAL '1 month - 1 day'
  ));
  v_prorated_days := EXTRACT(DAY FROM NEW.actual_move_out_date);

  IF NEW.prorated_rent IS NULL THEN
    v_daily_rate := v_contract.rent_price / v_days_in_month;
    IF v_prorated_days < v_days_in_month THEN
      NEW.prorated_rent := v_daily_rate * v_prorated_days;
    ELSE
      NEW.prorated_rent := 0;
    END IF;
  END IF;

  IF NEW.prorated_days IS NULL THEN
    IF v_prorated_days < v_days_in_month THEN
      NEW.prorated_days := v_prorated_days;
    ELSE
      NEW.prorated_days := 0;
    END IF;
  END IF;

  IF NEW.total_deposit IS NULL THEN
    NEW.total_deposit := v_contract.total_deposit;
  END IF;

  IF NEW.prorated_services IS NULL THEN
    SELECT COALESCE(SUM(cs.unit_price *
      CASE s.type
        WHEN 'FIXED' THEN (v_prorated_days::DECIMAL / v_days_in_month)
        WHEN 'PER_PERSON' THEN 1
        WHEN 'PER_ROOM' THEN (v_prorated_days::DECIMAL / v_days_in_month)
        ELSE 0
      END
    ), 0)
    INTO NEW.prorated_services
    FROM contract_services cs
    JOIN services s ON s.id = cs.service_id
    WHERE cs.contract_id = NEW.contract_id
      AND s.type != 'METER_READING';
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION auto_calculate_termination_financials(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_calculate_termination_financials() IS 'Auto-calculates outstanding debt, prorated rent, and services when creating termination record';








--
-- Name: auto_calculate_transfer_outstanding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_calculate_transfer_outstanding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_outstanding DECIMAL(15,2);
BEGIN
  -- Only for tenant changes
  IF NEW.transfer_type IN ('TENANT_CHANGE', 'BOTH_CHANGE') THEN
    -- Calculate outstanding from unpaid invoices
    SELECT COALESCE(SUM(remaining_amount), 0)
    INTO v_outstanding
    FROM invoices
    WHERE contract_id = NEW.contract_id
      AND status NOT IN ('PAID', 'CANCELLED')
      AND deleted_at IS NULL;

    NEW.old_tenant_outstanding := v_outstanding;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION auto_calculate_transfer_outstanding(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_calculate_transfer_outstanding() IS 'Auto-calculates outstanding debt for old tenant during transfer';








--
-- Name: auto_generate_meter_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_generate_meter_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_room_name TEXT;
  v_type_label TEXT;
BEGIN
  -- Only generate if name is not already set
  IF NEW.name IS NOT NULL AND NEW.name <> '' THEN
    RETURN NEW;
  END IF;

  -- Look up room name
  IF NEW.room_id IS NOT NULL THEN
    SELECT name INTO v_room_name
    FROM rooms
    WHERE id = NEW.room_id;
  END IF;

  -- Determine Vietnamese label for meter_type
  CASE NEW.meter_type
    WHEN 'ELECTRICITY' THEN v_type_label := 'Điện';
    WHEN 'WATER' THEN v_type_label := 'Nước';
    WHEN 'GAS' THEN v_type_label := 'Gas';
    ELSE v_type_label := NEW.meter_type::TEXT;
  END CASE;

  -- Build name: "{room_name} - {type_label}"
  IF v_room_name IS NOT NULL THEN
    NEW.name := v_room_name || ' - ' || v_type_label;
  ELSE
    NEW.name := v_type_label;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: auto_generate_reading_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_generate_reading_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prefix   TEXT;
  v_next_seq INT;
BEGIN
  IF NEW.reading_code IS NOT NULL AND NEW.reading_code <> '' THEN
    RETURN NEW;
  END IF;

  v_prefix := 'CSS' || TO_CHAR(NEW.reading_date, 'YYMM');

  PERFORM pg_advisory_xact_lock(hashtext(v_prefix));

  SELECT COALESCE(MAX(CAST(substring(reading_code FROM length(v_prefix) + 1) AS INT)), 0) + 1
    INTO v_next_seq
    FROM meter_readings
   WHERE reading_code LIKE v_prefix || '%'
     AND substring(reading_code FROM length(v_prefix) + 1) ~ '^[0-9]+$';

  NEW.reading_code := v_prefix || LPAD(v_next_seq::TEXT, 5, '0');
  RETURN NEW;
END;
$_$;








--
-- Name: FUNCTION auto_generate_reading_code(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_generate_reading_code() IS 'BEFORE INSERT trigger: generate globally-unique reading_code CSS{YYMM}{seq}. Sequence is global per prefix (MAX+1) with a per-prefix advisory lock; idx_meter_readings_code is a global unique index so per-user numbering would collide across owners.';








--
-- Name: auto_generate_voucher_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_generate_voucher_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prefix TEXT;
  v_month TEXT;
  v_sequence INTEGER;
BEGIN
  IF NEW.code IS NOT NULL AND NEW.code != '' THEN
    RETURN NEW;
  END IF;

  IF NEW.type = 'INCOME' THEN
    v_prefix := 'PT';
  ELSE
    v_prefix := 'PC';
  END IF;

  v_month := TO_CHAR(public.org_today_v1(NULL), 'YYMM');

  PERFORM pg_advisory_xact_lock(hashtext(v_prefix || v_month || COALESCE(NEW.user_id::text, '')));

  SELECT COALESCE(MAX(
    CASE
      WHEN code ~ ('^' || v_prefix || '\d{4}\d+$')
        AND SUBSTRING(code FROM 3 FOR 4) = v_month
      THEN CAST(SUBSTRING(code FROM 7) AS INTEGER)
      ELSE 0
    END
  ), 0) + 1
  INTO v_sequence
  FROM income_expenses
  WHERE user_id = NEW.user_id
    AND type = NEW.type
    AND code LIKE v_prefix || v_month || '%';

  NEW.code := v_prefix || v_month || LPAD(v_sequence::TEXT, 3, '0');
  RETURN NEW;
END;
$_$;








--
-- Name: auto_populate_meter_reading_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_populate_meter_reading_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_meter RECORD;
BEGIN
  -- Only populate if meter_id is provided
  IF NEW.meter_id IS NOT NULL THEN
    SELECT building_id, room_id, meter_type, service_id
    INTO v_meter
    FROM meters
    WHERE id = NEW.meter_id;

    IF FOUND THEN
      NEW.building_id := v_meter.building_id;
      NEW.room_id := v_meter.room_id;
      NEW.meter_type := v_meter.meter_type;
      NEW.service_id := v_meter.service_id;
    END IF;
  END IF;

  -- Auto-populate settlement_month from reading_date (YYYY-MM)
  IF NEW.reading_date IS NOT NULL THEN
    NEW.settlement_month := TO_CHAR(NEW.reading_date, 'YYYY-MM');
  END IF;

  -- Auto-populate recorded_by from auth.uid()
  NEW.recorded_by := auth.uid();

  RETURN NEW;
END;
$$;








--
-- Name: auto_populate_previous_reading(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_populate_previous_reading() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_previous DECIMAL(10, 2);
BEGIN
  IF NEW.meter_id IS NOT NULL THEN
    -- Try to get the most recent reading for this meter
    SELECT current_reading
    INTO v_previous
    FROM meter_readings
    WHERE meter_id = NEW.meter_id
      AND deleted_at IS NULL
    ORDER BY reading_date DESC, created_at DESC
    LIMIT 1;

    IF FOUND THEN
      NEW.previous_reading := v_previous;
    ELSE
      -- No previous reading → use initial_reading from meters
      SELECT initial_reading
      INTO v_previous
      FROM meters
      WHERE id = NEW.meter_id;

      IF FOUND AND v_previous IS NOT NULL THEN
        NEW.previous_reading := v_previous;
      ELSE
        NEW.previous_reading := 0;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: auto_recalc_total_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_recalc_total_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_parent_id UUID;
  v_total DECIMAL(15, 2);
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_parent_id := OLD.income_expense_id;
  ELSE
    v_parent_id := NEW.income_expense_id;
  END IF;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_total
  FROM income_expense_items
  WHERE income_expense_id = v_parent_id;

  UPDATE income_expenses
  SET total_amount = v_total
  WHERE id = v_parent_id;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: award_job_bonus(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_job_bonus(p_job_id uuid) RETURNS TABLE(bonus_kind text, amount numeric, label text, note text, place text, content text, icon text, time_context text, notif_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_owner      uuid;
  v_rules      jsonb;
  v_weekend    int[];
  v_wk_day     numeric;
  v_cutoff     time;
  v_photo      boolean;
  v_job        record;
  v_jt         record;
  v_bld        text;
  v_room       text;
  v_place      text;
  v_is_holiday boolean;
  v_is_we      boolean;
  v_time_ctx   text;
  v_amt        numeric;
  v_label      text;
  v_note       text;
  v_content    text;
  v_icon       text;
  v_nid        uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;

  v_owner := (SELECT sa.user_id FROM public.super_admins sa ORDER BY sa.created_at LIMIT 1);

  -- Verify: job COMPLETED + assignee = chinh minh. KHONG loc j.user_id.
  SELECT
    j.id,
    j.title,
    j.job_type_id,
    j.building_id,
    j.room_id,
    public.job_photo_ok(j.completion_attachments, j.attachments) AS photo_ok,
    public.vn_local_date(j.completion_time) AS ld,
    public.vn_local_dow(j.completion_time)  AS dow,
    public.vn_local_time(j.completion_time) AS ltime
  INTO v_job
  FROM public.jobs j
  WHERE j.id = p_job_id
    AND j.status = 'COMPLETED'
    AND j.assignee_id = v_uid;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT
    jt.name,
    COALESCE(jt.bonus_amount, 0)         AS bonus_amount,
    COALESCE(jt.is_repair, false)        AS is_repair,
    COALESCE(jt.is_contract, false)      AS is_contract,
    COALESCE(jt.counts_for_salary, true) AS counts_for_salary
  INTO v_jt
  FROM public.job_types jt
  WHERE jt.id = v_job.job_type_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT r.rules INTO v_rules FROM public.salary_bonus_rules r WHERE r.user_id = v_owner;
  v_rules  := COALESCE(v_rules, '{}'::jsonb);
  v_wk_day := COALESCE((v_rules->>'weekendRepair')::numeric, 20000);
  v_cutoff := COALESCE((v_rules->>'afterHourMark'), '18:00')::time;
  v_photo  := COALESCE((v_rules->>'requirePhoto')::boolean, false);
  SELECT COALESCE(array_agg((e)::int), ARRAY[0]) INTO v_weekend
  FROM jsonb_array_elements_text(COALESCE(v_rules->'weekendDays', '[0]'::jsonb)) e;

  SELECT COALESCE(b.code, b.name) INTO v_bld
  FROM public.buildings b WHERE b.id = v_job.building_id;
  SELECT rm.name INTO v_room
  FROM public.rooms rm WHERE rm.id = v_job.room_id;
  v_place := COALESCE(v_bld, '') || COALESCE(' · ' || v_room, '');

  v_is_holiday := EXISTS (
    SELECT 1 FROM public.salary_holidays h
    WHERE h.user_id = v_owner AND h.holiday_date = v_job.ld
  );
  v_is_we := (v_job.dow = ANY(v_weekend)) OR v_is_holiday;

  -- Ngu canh thoi gian de FE chon skin popup (uu tien Le > CN > ngoai gio > thuong)
  v_time_ctx := CASE
                  WHEN v_is_holiday              THEN 'HOLIDAY'
                  WHEN v_job.dow = ANY(v_weekend) THEN 'SUNDAY'
                  WHEN v_job.ltime >= v_cutoff   THEN 'AFTER_HOURS'
                  ELSE 'NORMAL'
                END;

  -- (A) JOB: thuong theo loai viec; ky HD (is_contract) can sau gio/CN-Le
  IF v_jt.counts_for_salary
     AND v_jt.bonus_amount > 0
     AND (NOT v_photo OR v_job.photo_ok)
     AND (NOT v_jt.is_contract OR v_job.ltime >= v_cutoff OR v_is_we)
     AND NOT EXISTS (
            SELECT 1 FROM public.notifications n
            WHERE n.user_id = v_uid
              AND n.job_id = p_job_id
              AND n.type = 'SALARY_BONUS'
              AND n.metadata->>'bonus_kind' = 'JOB')
  THEN
    v_amt   := v_jt.bonus_amount;
    v_label := v_jt.name;
    v_note  := NULLIF(btrim(COALESCE(v_job.title, '')), '');
    v_icon  := CASE WHEN v_jt.is_repair THEN '🔧'
                    WHEN v_jt.is_contract THEN '📝'
                    ELSE '💰' END;
    v_content := public.fmt_bonus_k(v_amt) || ' ' || COALESCE(v_label, 'Việc')
                 || CASE WHEN v_note IS NOT NULL AND v_note <> v_label THEN ' · ' || v_note ELSE '' END
                 || CASE WHEN v_place <> '' THEN ' · ' || v_place ELSE '' END;
    INSERT INTO public.notifications (user_id, type, channel, status, subject, content, job_id, metadata)
    VALUES (v_uid, 'SALARY_BONUS', 'IN_APP', 'PENDING', 'Thưởng công việc', v_content, p_job_id,
            jsonb_build_object('bonus_kind', 'JOB', 'amount', v_amt, 'label', v_label, 'note', v_note,
                               'place', v_place, 'bonus_date', v_job.ld::text, 'icon', v_icon,
                               'time_context', v_time_ctx))
    RETURNING id INTO v_nid;
    bonus_kind := 'JOB'; amount := v_amt; label := v_label; note := v_note; place := v_place;
    content := v_content; icon := v_icon; time_context := v_time_ctx; notif_id := v_nid;
    RETURN NEXT;
  END IF;

  -- (B) DAY_BONUS: phu cap CN/Le (sua chua HOAC ky HD), 1 lan/ngay
  IF (v_jt.is_repair OR v_jt.is_contract)
     AND v_is_we
     AND NOT EXISTS (
            SELECT 1 FROM public.notifications n
            WHERE n.user_id = v_uid
              AND n.type = 'SALARY_BONUS'
              AND n.metadata->>'bonus_kind' = 'DAY_BONUS'
              AND n.metadata->>'bonus_date' = v_job.ld::text)
  THEN
    v_amt   := v_wk_day;
    v_label := CASE WHEN v_is_holiday THEN 'Phụ cấp ngày Lễ'
                    ELSE 'Phụ cấp Chủ Nhật' END;
    v_note  := NULL;
    v_icon  := '🔥';
    v_content := public.fmt_bonus_k(v_amt) || ' ' || v_label;
    INSERT INTO public.notifications (user_id, type, channel, status, subject, content, job_id, metadata)
    VALUES (v_uid, 'SALARY_BONUS', 'IN_APP', 'PENDING', 'Thưởng công việc', v_content, p_job_id,
            jsonb_build_object('bonus_kind', 'DAY_BONUS', 'amount', v_amt, 'label', v_label, 'note', NULL,
                               'place', '', 'bonus_date', v_job.ld::text, 'icon', v_icon,
                               'time_context', v_time_ctx))
    RETURNING id INTO v_nid;
    bonus_kind := 'DAY_BONUS'; amount := v_amt; label := v_label; note := v_note; place := '';
    content := v_content; icon := v_icon; time_context := v_time_ctx; notif_id := v_nid;
    RETURN NEXT;
  END IF;

  RETURN;
END;
$$;








