--
-- Name: bulk_approve_invoices_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_approve_invoices_v1(p_invoice_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_count integer;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  if p_invoice_ids is null or array_length(p_invoice_ids, 1) is null then
    return 0;
  end if;
  update public.invoices i
     set status = 'APPROVED', approved_at = now(), approved_by = v_actor
   where i.id = any (p_invoice_ids)
     and i.deleted_at is null
     and i.status = 'DRAFT'
     and app_private.can_edit_invoice_building_v1(i.building_id);
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;








--
-- Name: bulk_approve_meter_readings(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_approve_meter_readings(p_reading_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE meter_readings
  SET status = 'APPROVED',
      approved_by = auth.uid(),
      approved_at = NOW()
  WHERE id = ANY(p_reading_ids)
    AND status = 'UNAPPROVED'
    AND deleted_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;








--
-- Name: bulk_approve_meter_readings_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_approve_meter_readings_v1(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid; v_n int := 0;
begin
  foreach v_id in array coalesce(p_ids, array[]::uuid[]) loop
    begin
      perform public.approve_meter_reading_v1(v_id);
      v_n := v_n + 1;
    exception when insufficient_privilege then
      -- bỏ qua item không đủ quyền/không tồn tại; đếm số duyệt thành công
      null;
    end;
  end loop;
  return v_n;
end;
$$;








--
-- Name: bulk_create_meter_readings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_create_meter_readings(p_readings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_results JSONB := '[]'::JSONB;
  v_meter_id UUID;
  v_user_id UUID;
  v_reading_id UUID;
  v_reading_code TEXT;
  v_meter_code TEXT;
  v_reading_date DATE;
  v_current_reading DECIMAL(10, 2);
  v_notes TEXT;
  v_result JSONB;
BEGIN
  v_user_id := auth.uid();

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_readings)
  LOOP
    BEGIN
      -- Extract fields from JSONB element
      v_meter_code := v_item->>'meter_code';
      v_reading_date := (v_item->>'reading_date')::DATE;
      v_current_reading := (v_item->>'current_reading')::DECIMAL(10, 2);
      v_notes := v_item->>'notes';

      -- Look up meter by code + user_id
      SELECT id INTO v_meter_id
      FROM meters
      WHERE code = v_meter_code
        AND user_id = v_user_id
        AND deleted_at IS NULL;

      IF NOT FOUND THEN
        v_result := jsonb_build_object(
          'meter_code', v_meter_code,
          'reading_id', NULL,
          'reading_code', NULL,
          'success', false,
          'error_message', 'Không tìm thấy công tơ với mã: ' || COALESCE(v_meter_code, '(trống)')
        );
        v_results := v_results || v_result;
        CONTINUE;
      END IF;

      -- Insert the meter reading (triggers will auto-populate fields)
      INSERT INTO meter_readings (
        user_id,
        meter_id,
        reading_date,
        current_reading,
        notes,
        status
      ) VALUES (
        v_user_id,
        v_meter_id,
        v_reading_date,
        v_current_reading,
        v_notes,
        'UNAPPROVED'
      )
      RETURNING id, reading_code INTO v_reading_id, v_reading_code;

      v_result := jsonb_build_object(
        'meter_code', v_meter_code,
        'reading_id', v_reading_id,
        'reading_code', v_reading_code,
        'success', true,
        'error_message', NULL
      );
      v_results := v_results || v_result;

    EXCEPTION WHEN OTHERS THEN
      v_result := jsonb_build_object(
        'meter_code', v_meter_code,
        'reading_id', NULL,
        'reading_code', NULL,
        'success', false,
        'error_message', SQLERRM
      );
      v_results := v_results || v_result;
    END;
  END LOOP;

  RETURN v_results;
END;
$$;








--
-- Name: bulk_create_meter_readings_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_create_meter_readings_v1(p_readings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_item jsonb;
  v_row public.meter_readings;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF jsonb_typeof(p_readings) <> 'array' THEN RAISE EXCEPTION 'p_readings phải là mảng'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_readings)
  LOOP
    BEGIN
      v_row := public.create_meter_reading_v1(
        (v_item->>'meter_id')::uuid,
        (v_item->>'reading_date')::date,
        (v_item->>'current_reading')::numeric,
        NULLIF(v_item->>'notes',''),
        NULLIF(v_item->>'meter_image_url','')
      );
      v_results := v_results || jsonb_build_object(
        'success', true, 'reading_id', v_row.id, 'reading_code', v_row.reading_code,
        'meter_id', v_row.meter_id, 'error_message', NULL);
    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_object(
        'success', false, 'reading_id', NULL, 'reading_code', NULL,
        'meter_id', v_item->>'meter_id', 'error_message', SQLERRM);
    END;
  END LOOP;

  RETURN v_results;
END;
$$;








--
-- Name: bulk_delete_meter_readings_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_delete_meter_readings_v1(p_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_id uuid;
  v_deleted jsonb := '[]'::jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;

  FOREACH v_id IN ARRAY COALESCE(p_ids, ARRAY[]::uuid[])
  LOOP
    BEGIN
      PERFORM public.delete_meter_reading_v1(v_id);
      v_deleted := v_deleted || jsonb_build_object('id', v_id, 'success', true);
    EXCEPTION WHEN OTHERS THEN
      v_deleted := v_deleted || jsonb_build_object('id', v_id, 'success', false, 'error_message', SQLERRM);
    END;
  END LOOP;

  RETURN v_deleted;
END;
$$;








--
-- Name: bulk_soft_delete_invoices_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_soft_delete_invoices_v1(p_invoice_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice_id uuid;
  v_count integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_invoice_ids IS NULL OR array_length(p_invoice_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = ANY(p_invoice_ids)
  ) THEN
    RAISE EXCEPTION 'Use bulk_soft_delete_invoices_with_credit_v1 for this request'
      USING ERRCODE = '55000';
  END IF;
  FOR v_invoice_id IN
    SELECT DISTINCT requested.requested_id
    FROM unnest(p_invoice_ids) AS requested(requested_id)
  LOOP
    PERFORM app_private.assert_invoice_credit_cancellable_v1(v_invoice_id);
  END LOOP;
  UPDATE public.invoices invoice_row
     SET deleted_at = clock_timestamp()
   WHERE invoice_row.id = ANY(p_invoice_ids)
     AND invoice_row.deleted_at IS NULL
     AND invoice_row.status = 'DRAFT'
     AND app_private.can_edit_invoice_building_v1(invoice_row.building_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;








--
-- Name: bulk_soft_delete_invoices_with_credit_v1(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_soft_delete_invoices_with_credit_v1(p_invoice_ids uuid[], p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_invoice_id uuid;
  v_child_key text;
  v_result jsonb;
  v_count integer := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF p_invoice_ids IS NULL OR array_length(p_invoice_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('deleted_count', 0, 'invoices', '[]'::jsonb);
  END IF;

  FOR v_invoice_id IN
    SELECT requested.requested_id
    FROM (
      SELECT DISTINCT input_id AS requested_id
      FROM unnest(p_invoice_ids) AS input(input_id)
    ) requested
    LEFT JOIN LATERAL (
      SELECT application_row.applied_at, application_row.id
      FROM public.customer_credit_applications application_row
      WHERE application_row.invoice_id = requested.requested_id
        AND application_row.reversed_at IS NULL
      ORDER BY application_row.applied_at DESC, application_row.id DESC
      LIMIT 1
    ) latest_application ON true
    ORDER BY latest_application.applied_at DESC NULLS LAST,
             latest_application.id DESC NULLS LAST,
             requested.requested_id
  LOOP
    v_child_key := left(v_key, 150)
      || ':inv:' || replace(v_invoice_id::text, '-', '');
    v_result := public.soft_delete_invoice_with_credit_v1(
      v_invoice_id, v_child_key
    );
    IF NOT COALESCE((v_result->>'noop')::boolean, false) THEN
      v_count := v_count + 1;
    END IF;
    v_results := v_results || jsonb_build_array(v_result);
  END LOOP;

  RETURN jsonb_build_object('deleted_count', v_count, 'invoices', v_results);
END;
$_$;








--
-- Name: business_performance_break_even_v1(uuid, text, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_break_even_v1(p_organization_id uuid, p_basis text, p_month date, p_building_ids uuid[]) RETURNS TABLE(building_id uuid, building_name text, analysis_window text, window_start date, window_end date, source_month_count integer, valid_month_count integer, revenue numeric, expense numeric, net numeric, gap_to_zero numeric, r_room numeric, r_other numeric, r_pass numeric, f_landlord numeric, f_other numeric, v_room numeric, v_other numeric, e_pass numeric, mapping_coverage_pct numeric, unmapped_amount numeric, outside_model_amount numeric, missing_landlord_months date[], cmr_core numeric, cmr_room numeric, r_core_be numeric, r_total_be numeric, r_room_be numeric, break_even_revenue_available boolean, break_even_revenue_reason text, room_break_even_revenue_available boolean, room_break_even_revenue_reason text, capacity_current numeric, capacity_blocked numeric, capacity_theory numeric, invalid_rent_room_count integer, break_even_occupancy_current numeric, break_even_occupancy_theory numeric, room_revenue_utilization_pct numeric, break_even_occupancy_available boolean, break_even_occupancy_reason text, capacity_source text, capacity_as_of timestamp with time zone, generated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_start_month date;
  v_end_date date;
  v_current_month date;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_basis IS NULL OR p_basis NOT IN ('ACCRUAL', 'VOUCHER_DATE') THEN
    RAISE EXCEPTION 'Unsupported business performance basis'
      USING ERRCODE = '22023';
  END IF;
  IF p_month IS NULL OR p_month <> date_trunc('month', p_month)::date THEN
    RAISE EXCEPTION 'Break-even month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  v_current_month := date_trunc(
    'month',
    clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh'
  )::date;
  IF p_month > v_current_month THEN
    RAISE EXCEPTION 'Break-even month cannot be in the future'
      USING ERRCODE = '22023';
  END IF;

  v_start_month := (p_month - interval '2 months')::date;
  v_end_date := (p_month + interval '1 month - 1 day')::date;

  -- Formula glossary used in the returned rows:
  -- R_room, R_other, R_pass, F_landlord, F_other, V_room, V_other, E_pass.
  -- CMR_core = (R_room + R_other - V_room - V_other) / (R_room + R_other)
  -- CMR_room = (R_room - V_room) / R_room
  -- R_core_BE = MAX(0, (F_landlord + F_other - (R_pass - E_pass)) / CMR_core)
  -- R_room_BE = MAX(0, (F_landlord + F_other - C_non_room) / CMR_room)
  RETURN QUERY
  WITH requested_buildings AS MATERIALIZED (
    SELECT
      building_row.id,
      COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building') AS name
    FROM public.buildings building_row
    WHERE building_row.organization_id = p_organization_id
      AND building_row.deleted_at IS NULL
      AND building_row.is_virtual = false
      AND building_row.id = ANY(v_building_ids)
  ),
  months AS MATERIALIZED (
    SELECT generate_series(v_start_month, p_month, interval '1 month')::date AS month
  ),
  accrual_rows AS MATERIALIZED (
    SELECT
      allocation_row.month,
      allocation_row.voucher_id,
      allocation_row.building_id,
      upper(allocation_row.side) AS side,
      allocation_row.type_id,
      allocation_row.amount::numeric AS amount
    FROM public.fa_accrual_allocations(
      v_start_month,
      v_end_date,
      v_building_ids
    ) allocation_row
    WHERE p_basis = 'ACCRUAL'
      AND allocation_row.building_id = ANY(v_building_ids)
      AND allocation_row.is_virtual = false
  ),
  voucher_items AS MATERIALIZED (
    SELECT
      voucher_row.id AS voucher_id,
      date_trunc('month', voucher_row.voucher_date)::date AS month,
      voucher_row.building_id,
      upper(voucher_row.type::text) AS side,
      voucher_row.kqkd_amount::numeric AS kqkd_amount,
      item_row.income_expense_type_id AS type_id,
      COALESCE(item_row.amount, item_row.unit_price * item_row.quantity, 0)::numeric AS item_amount,
      sum(COALESCE(item_row.amount, item_row.unit_price * item_row.quantity, 0))
        OVER (PARTITION BY voucher_row.id)::numeric AS eligible_item_total,
      count(item_row.id) OVER (PARTITION BY voucher_row.id)::integer AS eligible_item_count
    FROM public.income_expenses voucher_row
    LEFT JOIN public.income_expense_items item_row
      ON item_row.income_expense_id = voucher_row.id
    LEFT JOIN public.income_expense_types type_row
      ON type_row.id = item_row.income_expense_type_id
    WHERE p_basis = 'VOUCHER_DATE'
      AND voucher_row.organization_id = p_organization_id
      AND voucher_row.building_id = ANY(v_building_ids)
      AND voucher_row.deleted_at IS NULL
      AND voucher_row.approval_status = 'APPROVED'
      AND voucher_row.kqkd_amount > 0
      AND voucher_row.voucher_date >= v_start_month
      AND voucher_row.voucher_date <= v_end_date
      AND (
        item_row.id IS NULL
        OR voucher_row.business_result_accounting IS TRUE
        OR NOT COALESCE(type_row.is_deposit, false)
      )
  ),
  voucher_rows AS MATERIALIZED (
    SELECT
      item_row.month,
      item_row.voucher_id,
      item_row.building_id,
      item_row.side,
      item_row.type_id,
      CASE
        WHEN item_row.eligible_item_count = 0 THEN item_row.kqkd_amount
        WHEN item_row.eligible_item_total > 0
          THEN item_row.kqkd_amount * item_row.item_amount / item_row.eligible_item_total
        ELSE item_row.kqkd_amount / NULLIF(item_row.eligible_item_count, 0)
      END::numeric AS amount
    FROM voucher_items item_row
  ),
  source_rows AS MATERIALIZED (
    SELECT * FROM accrual_rows
    UNION ALL
    SELECT * FROM voucher_rows
  ),
  classified_rows AS MATERIALIZED (
    SELECT
      source_row.month,
      source_row.voucher_id,
      source_row.building_id,
      source_row.side,
      source_row.type_id,
      source_row.amount,
      assignment_row.finance_reporting_role
    FROM source_rows source_row
    LEFT JOIN LATERAL (
      SELECT assignment.finance_reporting_role
      FROM public.finance_reporting_role_assignments assignment
      WHERE assignment.organization_id = p_organization_id
        AND assignment.income_expense_type_id = source_row.type_id
        AND assignment.effective_from <= source_row.month
        AND (
          assignment.effective_to IS NULL
          OR assignment.effective_to >= source_row.month
        )
      ORDER BY assignment.effective_from DESC, assignment.id
      LIMIT 1
    ) assignment_row ON true
  ),
  monthly AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      building_row.name AS building_name,
      month_row.month,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.side = 'INCOME'), 0)::numeric AS revenue,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.side = 'EXPENSE'), 0)::numeric AS expense,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'ROOM_RENT_REVENUE'), 0)::numeric AS r_room,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'OTHER_OPERATING_REVENUE'), 0)::numeric AS r_other,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'PASS_THROUGH_REVENUE'), 0)::numeric AS r_pass,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'LANDLORD_RENT_FIXED'), 0)::numeric AS f_landlord,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'OTHER_FIXED_COST'), 0)::numeric AS f_other,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'ROOM_VARIABLE_COST'), 0)::numeric AS v_room,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'OTHER_VARIABLE_COST'), 0)::numeric AS v_other,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'PASS_THROUGH_EXPENSE'), 0)::numeric AS e_pass,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role IS NULL), 0)::numeric AS unmapped_amount,
      COALESCE(sum(source_row.amount) FILTER (WHERE source_row.finance_reporting_role = 'OUTSIDE_BREAK_EVEN_MODEL'), 0)::numeric AS outside_model_amount
    FROM requested_buildings building_row
    CROSS JOIN months month_row
    LEFT JOIN classified_rows source_row
      ON source_row.building_id = building_row.id
     AND source_row.month = month_row.month
    GROUP BY building_row.id, building_row.name, month_row.month
  ),
  windows AS MATERIALIZED (
    SELECT
      monthly.building_id,
      max(monthly.building_name) AS building_name,
      'SELECTED_MONTH'::text AS analysis_window,
      p_month AS window_start,
      p_month AS window_end,
      1::integer AS source_month_count,
      count(*) FILTER (
        WHERE monthly.revenue + monthly.expense > 0
          AND monthly.unmapped_amount = 0
          AND monthly.outside_model_amount = 0
          AND monthly.f_landlord > 0
      )::integer AS valid_month_count,
      sum(monthly.revenue) FILTER (WHERE monthly.month = p_month)::numeric AS revenue,
      sum(monthly.expense) FILTER (WHERE monthly.month = p_month)::numeric AS expense,
      sum(monthly.r_room) FILTER (WHERE monthly.month = p_month)::numeric AS r_room,
      sum(monthly.r_other) FILTER (WHERE monthly.month = p_month)::numeric AS r_other,
      sum(monthly.r_pass) FILTER (WHERE monthly.month = p_month)::numeric AS r_pass,
      sum(monthly.f_landlord) FILTER (WHERE monthly.month = p_month)::numeric AS f_landlord,
      sum(monthly.f_other) FILTER (WHERE monthly.month = p_month)::numeric AS f_other,
      sum(monthly.v_room) FILTER (WHERE monthly.month = p_month)::numeric AS v_room,
      sum(monthly.v_other) FILTER (WHERE monthly.month = p_month)::numeric AS v_other,
      sum(monthly.e_pass) FILTER (WHERE monthly.month = p_month)::numeric AS e_pass,
      sum(monthly.unmapped_amount) FILTER (WHERE monthly.month = p_month)::numeric AS unmapped_amount,
      sum(monthly.outside_model_amount) FILTER (WHERE monthly.month = p_month)::numeric AS outside_model_amount,
      array_agg(monthly.month ORDER BY monthly.month) FILTER (
        WHERE monthly.month = p_month AND monthly.f_landlord <= 0
      ) AS missing_landlord_months
    FROM monthly
    WHERE monthly.month = p_month
    GROUP BY monthly.building_id

    UNION ALL

    SELECT
      monthly.building_id,
      max(monthly.building_name),
      'THREE_MONTH_AVERAGE'::text,
      v_start_month,
      p_month,
      3::integer,
      count(*) FILTER (
        WHERE monthly.revenue + monthly.expense > 0
          AND monthly.unmapped_amount = 0
          AND monthly.outside_model_amount = 0
          AND monthly.f_landlord > 0
      )::integer,
      (sum(monthly.revenue) / 3.0)::numeric,
      (sum(monthly.expense) / 3.0)::numeric,
      (sum(monthly.r_room) / 3.0)::numeric,
      (sum(monthly.r_other) / 3.0)::numeric,
      (sum(monthly.r_pass) / 3.0)::numeric,
      (sum(monthly.f_landlord) / 3.0)::numeric,
      (sum(monthly.f_other) / 3.0)::numeric,
      (sum(monthly.v_room) / 3.0)::numeric,
      (sum(monthly.v_other) / 3.0)::numeric,
      (sum(monthly.e_pass) / 3.0)::numeric,
      sum(monthly.unmapped_amount)::numeric,
      sum(monthly.outside_model_amount)::numeric,
      array_agg(monthly.month ORDER BY monthly.month) FILTER (WHERE monthly.f_landlord <= 0)
    FROM monthly
    GROUP BY monthly.building_id
  ),
  capacity_live AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      COALESCE(sum(GREATEST(room_row.rent_price, 0)) FILTER (
        WHERE CASE
          WHEN active_contract.active_count > 0 THEN 'OCCUPIED'
          WHEN room_row.status::text = 'RESERVED' THEN 'RESERVED'
          WHEN room_row.status::text = 'MAINTENANCE' THEN 'MAINTENANCE'
          WHEN room_row.status::text = 'AVAILABLE' THEN 'AVAILABLE'
          ELSE 'UNAVAILABLE'
        END IN ('OCCUPIED', 'RESERVED', 'AVAILABLE')
      ), 0)::numeric AS capacity_current,
      COALESCE(sum(GREATEST(room_row.rent_price, 0)) FILTER (
        WHERE CASE
          WHEN active_contract.active_count > 0 THEN 'OCCUPIED'
          WHEN room_row.status::text = 'RESERVED' THEN 'RESERVED'
          WHEN room_row.status::text = 'MAINTENANCE' THEN 'MAINTENANCE'
          WHEN room_row.status::text = 'AVAILABLE' THEN 'AVAILABLE'
          ELSE 'UNAVAILABLE'
        END IN ('MAINTENANCE', 'UNAVAILABLE')
      ), 0)::numeric AS capacity_blocked,
      count(room_row.id) FILTER (
        WHERE room_row.rent_price IS NULL OR room_row.rent_price <= 0
      )::integer AS invalid_rent_room_count,
      clock_timestamp() AS capacity_as_of
    FROM requested_buildings building_row
    LEFT JOIN public.rooms room_row
      ON room_row.building_id = building_row.id
     AND room_row.deleted_at IS NULL
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS active_count
      FROM public.contracts contract_row
      WHERE contract_row.room_id = room_row.id
        AND contract_row.organization_id = p_organization_id
        AND contract_row.deleted_at IS NULL
        AND contract_row.status::text = 'ACTIVE'
        AND contract_row.start_date <= (clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
        AND (
          contract_row.actual_end_date IS NULL
          OR contract_row.actual_end_date >= (clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
        )
    ) active_contract ON true
    WHERE p_month = v_current_month
    GROUP BY building_row.id
  ),
  capacity_snapshot AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      COALESCE(sum(GREATEST(detail.listed_rent, 0)) FILTER (
        WHERE detail.occupancy_group IN ('OCCUPIED', 'RESERVED', 'AVAILABLE')
      ), 0)::numeric AS capacity_current,
      COALESCE(sum(GREATEST(detail.listed_rent, 0)) FILTER (
        WHERE detail.occupancy_group IN ('MAINTENANCE', 'UNAVAILABLE')
      ), 0)::numeric AS capacity_blocked,
      count(detail.id) FILTER (
        WHERE detail.listed_rent IS NULL OR detail.listed_rent <= 0
      )::integer AS invalid_rent_room_count,
      run.as_of_timestamp AS capacity_as_of
    FROM requested_buildings building_row
    JOIN public.finance_month_snapshot_runs run
      ON run.organization_id = p_organization_id
     AND run.snapshot_month = p_month
     AND run.status = 'FINALIZED'
    LEFT JOIN public.finance_room_month_snapshots detail
      ON detail.snapshot_run_id = run.id
     AND detail.building_id = building_row.id
    WHERE p_month < v_current_month
    GROUP BY building_row.id, run.as_of_timestamp
  ),
  capacity AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      COALESCE(live_row.capacity_current, snapshot_row.capacity_current) AS capacity_current,
      COALESCE(live_row.capacity_blocked, snapshot_row.capacity_blocked) AS capacity_blocked,
      COALESCE(live_row.invalid_rent_room_count, snapshot_row.invalid_rent_room_count) AS invalid_rent_room_count,
      CASE
        WHEN live_row.building_id IS NOT NULL THEN 'LIVE'
        WHEN snapshot_row.building_id IS NOT NULL THEN 'FINALIZED_SNAPSHOT'
        ELSE 'UNAVAILABLE'
      END AS capacity_source,
      COALESCE(live_row.capacity_as_of, snapshot_row.capacity_as_of) AS capacity_as_of
    FROM requested_buildings building_row
    LEFT JOIN capacity_live live_row ON live_row.building_id = building_row.id
    LEFT JOIN capacity_snapshot snapshot_row ON snapshot_row.building_id = building_row.id
  ),
  calculated AS MATERIALIZED (
    SELECT
      window_row.*,
      CASE
        WHEN window_row.r_room + window_row.r_other > 0
          THEN (window_row.r_room + window_row.r_other - window_row.v_room - window_row.v_other)
            / (window_row.r_room + window_row.r_other)
        ELSE NULL
      END::numeric AS cmr_core,
      CASE
        WHEN window_row.r_room > 0
          THEN (window_row.r_room - window_row.v_room) / window_row.r_room
        ELSE NULL
      END::numeric AS cmr_room,
      capacity.capacity_current,
      capacity.capacity_blocked,
      capacity.invalid_rent_room_count,
      capacity.capacity_source,
      capacity.capacity_as_of
    FROM windows window_row
    JOIN capacity ON capacity.building_id = window_row.building_id
  ),
  outputs AS MATERIALIZED (
    SELECT
      calculated.*,
      calculated.valid_month_count = calculated.source_month_count
        AND calculated.unmapped_amount = 0
        AND calculated.outside_model_amount = 0
        AND calculated.cmr_core > 0 AS core_available,
      calculated.valid_month_count = calculated.source_month_count
        AND calculated.unmapped_amount = 0
        AND calculated.outside_model_amount = 0
        AND (
          calculated.f_landlord + calculated.f_other
            - ((calculated.r_other - calculated.v_other) + (calculated.r_pass - calculated.e_pass)) <= 0
          OR calculated.cmr_room > 0
        ) AS room_available,
      CASE
        WHEN calculated.valid_month_count = calculated.source_month_count
         AND calculated.unmapped_amount = 0
         AND calculated.outside_model_amount = 0
         AND calculated.cmr_core > 0
          THEN GREATEST(
            0,
            (calculated.f_landlord + calculated.f_other - (calculated.r_pass - calculated.e_pass))
              / calculated.cmr_core
          )
        ELSE NULL
      END::numeric AS r_core_be,
      CASE
        WHEN calculated.valid_month_count = calculated.source_month_count
         AND calculated.unmapped_amount = 0
         AND calculated.outside_model_amount = 0
         AND calculated.f_landlord + calculated.f_other
           - ((calculated.r_other - calculated.v_other) + (calculated.r_pass - calculated.e_pass)) <= 0
          THEN 0
        WHEN calculated.valid_month_count = calculated.source_month_count
         AND calculated.unmapped_amount = 0
         AND calculated.outside_model_amount = 0
         AND calculated.cmr_room > 0
          THEN GREATEST(
            0,
            (
              calculated.f_landlord + calculated.f_other
                - ((calculated.r_other - calculated.v_other) + (calculated.r_pass - calculated.e_pass))
            ) / calculated.cmr_room
          )
        ELSE NULL
      END::numeric AS r_room_be
    FROM calculated
  )
  SELECT
    output_row.building_id,
    output_row.building_name,
    output_row.analysis_window,
    output_row.window_start,
    output_row.window_end,
    output_row.source_month_count,
    output_row.valid_month_count,
    output_row.revenue,
    output_row.expense,
    output_row.revenue - output_row.expense,
    output_row.expense - output_row.revenue,
    output_row.r_room,
    output_row.r_other,
    output_row.r_pass,
    output_row.f_landlord,
    output_row.f_other,
    output_row.v_room,
    output_row.v_other,
    output_row.e_pass,
    CASE
      WHEN output_row.revenue + output_row.expense = 0 THEN NULL
      ELSE round(
        (
          output_row.revenue + output_row.expense
            - output_row.unmapped_amount / output_row.source_month_count
        ) * 100.0 / (output_row.revenue + output_row.expense),
        2
      )
    END,
    output_row.unmapped_amount,
    output_row.outside_model_amount,
    COALESCE(output_row.missing_landlord_months, ARRAY[]::date[]),
    output_row.cmr_core,
    output_row.cmr_room,
    output_row.r_core_be,
    CASE WHEN output_row.r_core_be IS NULL THEN NULL ELSE output_row.r_core_be + output_row.r_pass END,
    output_row.r_room_be,
    output_row.core_available,
    CASE
      WHEN output_row.unmapped_amount > 0 THEN 'UNMAPPED_AMOUNT'
      WHEN output_row.outside_model_amount > 0 THEN 'OUTSIDE_MODEL_AMOUNT'
      WHEN output_row.valid_month_count < output_row.source_month_count THEN 'MISSING_LANDLORD_OR_MONTH'
      WHEN output_row.cmr_core IS NULL OR output_row.cmr_core <= 0 THEN 'CMR_CORE_NOT_POSITIVE'
      ELSE NULL
    END,
    output_row.room_available,
    CASE
      WHEN output_row.unmapped_amount > 0 THEN 'UNMAPPED_AMOUNT'
      WHEN output_row.outside_model_amount > 0 THEN 'OUTSIDE_MODEL_AMOUNT'
      WHEN output_row.valid_month_count < output_row.source_month_count THEN 'MISSING_LANDLORD_OR_MONTH'
      WHEN output_row.r_room_be IS NULL THEN 'CMR_ROOM_NOT_POSITIVE'
      ELSE NULL
    END,
    output_row.capacity_current,
    output_row.capacity_blocked,
    CASE WHEN output_row.capacity_current IS NULL THEN NULL
      ELSE output_row.capacity_current + output_row.capacity_blocked END,
    output_row.invalid_rent_room_count,
    CASE
      WHEN output_row.room_available
       AND output_row.r_room_be IS NOT NULL
       AND output_row.cmr_room > 0
       AND output_row.capacity_current > 0
       AND output_row.invalid_rent_room_count = 0
        THEN output_row.r_room_be * 100.0 / output_row.capacity_current
      ELSE NULL
    END,
    CASE
      WHEN output_row.room_available
       AND output_row.r_room_be IS NOT NULL
       AND output_row.cmr_room > 0
       AND output_row.capacity_current + output_row.capacity_blocked > 0
       AND output_row.invalid_rent_room_count = 0
        THEN output_row.r_room_be * 100.0
          / (output_row.capacity_current + output_row.capacity_blocked)
      ELSE NULL
    END,
    CASE
      WHEN output_row.capacity_current > 0
        THEN output_row.r_room * 100.0 / output_row.capacity_current
      ELSE NULL
    END,
    output_row.room_available
      AND output_row.r_room_be IS NOT NULL
      AND output_row.cmr_room > 0
      AND output_row.capacity_current > 0
      AND output_row.invalid_rent_room_count = 0,
    CASE
      WHEN NOT output_row.room_available THEN 'ROOM_BREAK_EVEN_UNAVAILABLE'
      WHEN output_row.capacity_source = 'UNAVAILABLE' THEN 'SNAPSHOT_UNAVAILABLE'
      WHEN output_row.invalid_rent_room_count > 0 THEN 'INVALID_LISTED_RENT'
      WHEN output_row.capacity_current IS NULL OR output_row.capacity_current <= 0 THEN 'CAPACITY_NOT_POSITIVE'
      WHEN output_row.cmr_room IS NULL OR output_row.cmr_room <= 0 THEN 'CMR_ROOM_NOT_POSITIVE'
      ELSE NULL
    END,
    output_row.capacity_source,
    output_row.capacity_as_of,
    clock_timestamp()
  FROM outputs output_row
  ORDER BY lower(output_row.building_name) COLLATE "C", output_row.building_id,
    CASE output_row.analysis_window WHEN 'SELECTED_MONTH' THEN 0 ELSE 1 END;
END;
$$;








--
-- Name: FUNCTION business_performance_break_even_v1(p_organization_id uuid, p_basis text, p_month date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_break_even_v1(p_organization_id uuid, p_basis text, p_month date, p_building_ids uuid[]) IS 'Fail-closed selected-month and 3-month-average building break-even, with live/finalized capacity provenance.';








--
-- Name: business_performance_cash_received_v1(uuid, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_cash_received_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]) RETURNS TABLE(building_id uuid, building_name text, cash_month date, cash_received numeric, payment_event_count integer, first_payment_date date, last_payment_date date, generated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_month IS NULL OR p_month <> date_trunc('month', p_month)::date THEN
    RAISE EXCEPTION 'Cash received month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH requested_buildings AS MATERIALIZED (
    SELECT building_row.id,
           COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building') AS name
    FROM public.buildings building_row
    WHERE building_row.organization_id = p_organization_id
      AND building_row.deleted_at IS NULL
      AND building_row.is_virtual = false
      AND building_row.id = ANY(v_building_ids)
  ),
  payment_events AS MATERIALIZED (
    SELECT
      receipt_row.id,
      invoice_row.building_id,
      receipt_row.payment_date,
      receipt_row.collected_amount::numeric AS retained_cash
    FROM public.active_payment_receipts receipt_row
    JOIN public.invoices invoice_row ON invoice_row.id = receipt_row.invoice_id
    WHERE receipt_row.organization_id = p_organization_id
      AND invoice_row.organization_id = p_organization_id
      AND invoice_row.building_id = ANY(v_building_ids)
      AND receipt_row.payment_date >= p_month
      AND receipt_row.payment_date < (p_month + interval '1 month')::date
  )
  SELECT
    building_row.id,
    building_row.name,
    p_month,
    COALESCE(sum(event_row.retained_cash), 0)::numeric,
    count(event_row.id)::integer,
    min(event_row.payment_date),
    max(event_row.payment_date),
    clock_timestamp()
  FROM requested_buildings building_row
  LEFT JOIN payment_events event_row ON event_row.building_id = building_row.id
  GROUP BY building_row.id, building_row.name
  ORDER BY lower(building_row.name) COLLATE "C", building_row.id;
END;
$$;








--
-- Name: FUNCTION business_performance_cash_received_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_cash_received_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]) IS 'Actual retained payment events by payment_date, excluding reversals and debt-status cascades.';








--
-- Name: business_performance_category_breakdown_v1(uuid, text, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_category_breakdown_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]) RETURNS TABLE(month date, side text, type_id uuid, type_name text, category text, total_amount numeric, voucher_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_basis IS NULL OR p_basis NOT IN ('ACCRUAL', 'VOUCHER_DATE') THEN
    RAISE EXCEPTION 'Unsupported business performance basis'
      USING ERRCODE = '22023';
  END IF;
  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_end_date < p_start_date
     OR p_end_date - p_start_date > 400 THEN
    RAISE EXCEPTION 'Invalid category breakdown date range'
      USING ERRCODE = '22023';
  END IF;

  IF p_basis = 'ACCRUAL' THEN
    RETURN QUERY
    SELECT
      allocation_row.month,
      upper(allocation_row.side),
      allocation_row.type_id,
      allocation_row.type_name,
      allocation_row.category,
      sum(allocation_row.amount)::numeric,
      count(DISTINCT allocation_row.voucher_id)::bigint
    FROM public.fa_accrual_allocations(
      p_start_date,
      p_end_date,
      v_building_ids
    ) allocation_row
    WHERE allocation_row.building_id = ANY(v_building_ids)
      AND allocation_row.is_virtual = false
    GROUP BY allocation_row.month,
             upper(allocation_row.side),
             allocation_row.type_id,
             allocation_row.type_name,
             allocation_row.category
    ORDER BY allocation_row.month,
             upper(allocation_row.side),
             sum(allocation_row.amount) DESC,
             allocation_row.type_id NULLS LAST;
  ELSE
    RETURN QUERY
    SELECT
      breakdown.month,
      upper(breakdown.side),
      breakdown.type_id,
      breakdown.type_name,
      breakdown.category,
      breakdown.total_amount,
      breakdown.voucher_count
    FROM public.fa_type_breakdown(
      p_start_date,
      p_end_date,
      v_building_ids
    ) breakdown
    ORDER BY breakdown.month,
             upper(breakdown.side),
             breakdown.total_amount DESC,
             breakdown.type_id NULLS LAST;
  END IF;
END;
$$;








--
-- Name: FUNCTION business_performance_category_breakdown_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_category_breakdown_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Org-bound physical KQKD category breakdown for accrual or voucher-date basis.';








--
-- Name: business_performance_inventory_history_v1(uuid, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_inventory_history_v1(p_organization_id uuid, p_start_month date, p_end_month date, p_building_ids uuid[]) RETURNS TABLE(snapshot_month date, building_id uuid, building_name text, snapshot_status text, snapshot_missing boolean, availability_reason text, total integer, occupied integer, reserved integer, maintenance integer, unavailable integer, available integer, occupancy_pct numeric, committed_pct numeric, listed_rent_opportunity numeric, capacity_current numeric, capacity_blocked numeric, capacity_theory numeric, invalid_rent_room_count integer, as_of_date date, as_of_timestamp timestamp with time zone, captured_at timestamp with time zone, is_late boolean, capture_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_current_month date;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => false
  ) AS scope;

  IF p_start_month IS NULL
     OR p_end_month IS NULL
     OR p_start_month <> date_trunc('month', p_start_month)::date
     OR p_end_month <> date_trunc('month', p_end_month)::date
     OR p_end_month < p_start_month
     OR p_end_month > (p_start_month + interval '23 months')::date THEN
    RAISE EXCEPTION 'Invalid finance snapshot month range'
      USING ERRCODE = '22023';
  END IF;

  v_current_month := date_trunc(
    'month',
    clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh'
  )::date;

  RETURN QUERY
  WITH months AS MATERIALIZED (
    SELECT generate_series(p_start_month, p_end_month, interval '1 month')::date AS month
  ),
  requested_buildings AS MATERIALIZED (
    SELECT building_row.id, COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building') AS name
    FROM public.buildings building_row
    WHERE building_row.organization_id = p_organization_id
      AND building_row.deleted_at IS NULL
      AND building_row.is_virtual = false
      AND building_row.id = ANY(v_building_ids)
  ),
  matrix AS MATERIALIZED (
    SELECT
      month_row.month,
      building_row.id AS building_id,
      building_row.name AS building_name,
      run.id AS run_id,
      run.status,
      run.as_of_date,
      run.as_of_timestamp,
      run.captured_at,
      run.is_late,
      run.capture_version,
      CASE
        WHEN run.id IS NULL THEN true
        WHEN run.status = 'MISSED' THEN true
        WHEN run.status = 'FINALIZED' THEN false
        WHEN run.status = 'PROVISIONAL' AND month_row.month = v_current_month THEN false
        ELSE true
      END AS snapshot_missing,
      CASE
        WHEN run.id IS NULL THEN 'NO_SNAPSHOT'
        WHEN run.status = 'MISSED' THEN 'MISSED_CUTOFF'
        WHEN run.status = 'PROVISIONAL' AND month_row.month <> v_current_month
          THEN 'NOT_FINALIZED'
        ELSE NULL
      END AS availability_reason
    FROM months month_row
    CROSS JOIN requested_buildings building_row
    LEFT JOIN public.finance_month_snapshot_runs run
      ON run.organization_id = p_organization_id
     AND run.snapshot_month = month_row.month
  ),
  aggregates AS MATERIALIZED (
    SELECT
      matrix.month,
      matrix.building_id,
      count(detail.id)::integer AS total,
      count(detail.id) FILTER (WHERE detail.occupancy_group = 'OCCUPIED')::integer AS occupied,
      count(detail.id) FILTER (WHERE detail.occupancy_group = 'RESERVED')::integer AS reserved,
      count(detail.id) FILTER (WHERE detail.occupancy_group = 'MAINTENANCE')::integer AS maintenance,
      count(detail.id) FILTER (WHERE detail.occupancy_group = 'UNAVAILABLE')::integer AS unavailable,
      count(detail.id) FILTER (WHERE detail.occupancy_group = 'AVAILABLE')::integer AS available,
      COALESCE(sum(GREATEST(detail.listed_rent, 0))
        FILTER (WHERE detail.occupancy_group = 'AVAILABLE'), 0)::numeric AS listed_rent_opportunity,
      COALESCE(sum(GREATEST(detail.listed_rent, 0))
        FILTER (WHERE detail.occupancy_group IN ('OCCUPIED', 'RESERVED', 'AVAILABLE')), 0)::numeric
        AS capacity_current,
      COALESCE(sum(GREATEST(detail.listed_rent, 0))
        FILTER (WHERE detail.occupancy_group IN ('MAINTENANCE', 'UNAVAILABLE')), 0)::numeric
        AS capacity_blocked,
      count(detail.id) FILTER (
        WHERE detail.listed_rent IS NULL OR detail.listed_rent <= 0
      )::integer AS invalid_rent_room_count
    FROM matrix
    LEFT JOIN public.finance_room_month_snapshots detail
      ON detail.snapshot_run_id = matrix.run_id
     AND detail.building_id = matrix.building_id
     AND NOT matrix.snapshot_missing
    GROUP BY matrix.month, matrix.building_id
  )
  SELECT
    matrix.month,
    matrix.building_id,
    matrix.building_name,
    COALESCE(matrix.status, 'MISSING') AS snapshot_status,
    matrix.snapshot_missing,
    matrix.availability_reason,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.total END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.occupied END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.reserved END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.maintenance END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.unavailable END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.available END,
    CASE
      WHEN matrix.snapshot_missing OR aggregate_row.total = 0 THEN NULL
      ELSE round(aggregate_row.occupied * 100.0 / aggregate_row.total, 1)
    END::numeric AS occupancy_pct,
    CASE
      WHEN matrix.snapshot_missing OR aggregate_row.total = 0 THEN NULL
      ELSE round((aggregate_row.occupied + aggregate_row.reserved) * 100.0 / aggregate_row.total, 1)
    END::numeric AS committed_pct,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.listed_rent_opportunity END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.capacity_current END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.capacity_blocked END,
    CASE WHEN matrix.snapshot_missing THEN NULL
      ELSE aggregate_row.capacity_current + aggregate_row.capacity_blocked END,
    CASE WHEN matrix.snapshot_missing THEN NULL ELSE aggregate_row.invalid_rent_room_count END,
    matrix.as_of_date,
    matrix.as_of_timestamp,
    matrix.captured_at,
    matrix.is_late,
    matrix.capture_version
  FROM matrix
  JOIN aggregates aggregate_row
    ON aggregate_row.month = matrix.month
   AND aggregate_row.building_id = matrix.building_id
  ORDER BY matrix.month, lower(matrix.building_name) COLLATE "C", matrix.building_id;
END;
$$;








--
-- Name: FUNCTION business_performance_inventory_history_v1(p_organization_id uuid, p_start_month date, p_end_month date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_inventory_history_v1(p_organization_id uuid, p_start_month date, p_end_month date, p_building_ids uuid[]) IS 'Scoped room inventory history for analysis users; restricted finance data is not returned.';








--
-- Name: business_performance_invoice_cohort_v1(uuid, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_invoice_cohort_v1(p_organization_id uuid, p_cohort_month date, p_building_ids uuid[]) RETURNS TABLE(building_id uuid, building_name text, cohort_month date, cohort_available boolean, billed_current_charge numeric, collected_current_charge numeric, remaining_current_charge numeric, collection_rate_pct numeric, invoice_count integer, allocation_unknown_count integer, allocation_unknown_amount numeric, component_anomaly_count integer, carried_invoice_debt numeric, carried_deposit_debt numeric, current_deposit numeric, draft_pending_count integer, draft_pending_amount numeric, settlement_count integer, settlement_amount numeric, generated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_cohort_month IS NULL
     OR p_cohort_month <> date_trunc('month', p_cohort_month)::date THEN
    RAISE EXCEPTION 'Invoice cohort month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH requested_buildings AS MATERIALIZED (
    SELECT building_row.id,
           COALESCE(NULLIF(btrim(building_row.name), ''), 'Unnamed building') AS name
    FROM public.buildings building_row
    WHERE building_row.organization_id = p_organization_id
      AND building_row.deleted_at IS NULL
      AND building_row.is_virtual = false
      AND building_row.id = ANY(v_building_ids)
  ),
  issued AS MATERIALIZED (
    SELECT invoice_row.*
    FROM public.invoices invoice_row
    WHERE invoice_row.organization_id = p_organization_id
      AND invoice_row.building_id = ANY(v_building_ids)
      AND invoice_row.deleted_at IS NULL
      AND invoice_row.kind = 'MONTHLY'
      AND invoice_row.billing_month = to_char(p_cohort_month, 'YYYY-MM')
      AND invoice_row.status::text IN ('APPROVED', 'PARTIAL_PAID', 'PAID', 'OVERDUE')
  ),
  component_pivot AS MATERIALIZED (
    SELECT
      invoice_row.id AS invoice_id,
      manifest.component_status,
      manifest.finalized_at,
      count(component.id) FILTER (WHERE component.amount > 0)::integer AS positive_component_count,
      COALESCE(sum(component.amount) FILTER (WHERE component.component_kind = 'CURRENT_CHARGE'), 0)::numeric AS current_charge,
      COALESCE(sum(component.amount) FILTER (WHERE component.component_kind = 'CARRIED_INVOICE_DEBT'), 0)::numeric AS carried_invoice_debt,
      COALESCE(sum(component.amount) FILTER (WHERE component.component_kind = 'CARRIED_DEPOSIT_DEBT'), 0)::numeric AS carried_deposit_debt,
      COALESCE(sum(component.amount) FILTER (WHERE component.component_kind = 'CURRENT_DEPOSIT'), 0)::numeric AS current_deposit
    FROM issued invoice_row
    LEFT JOIN public.finance_invoice_component_manifests manifest
      ON manifest.invoice_id = invoice_row.id
    LEFT JOIN public.finance_invoice_components component
      ON component.manifest_id = manifest.id
    GROUP BY invoice_row.id, manifest.component_status, manifest.finalized_at
  ),
  payment_events AS MATERIALIZED (
    SELECT
      invoice_row.id AS invoice_id,
      COALESCE(sum(payment_row.amount) FILTER (
        WHERE payment_row.reversed_at IS NULL
          AND (payment_row.collection_id IS NULL OR collection_row.status = 'ACTIVE')
      ), 0)::numeric AS paid_event_amount
    FROM issued invoice_row
    LEFT JOIN public.payments payment_row
      ON payment_row.invoice_id = invoice_row.id
    LEFT JOIN public.invoice_payment_collections collection_row
      ON collection_row.id = payment_row.collection_id
    GROUP BY invoice_row.id
  ),
  allocation_facts AS MATERIALIZED (
    SELECT
      invoice_row.id AS invoice_id,
      COALESCE(sum(allocation.amount) FILTER (
        WHERE allocation_collection.status = 'ACTIVE'
      ), 0)::numeric AS allocated_amount,
      COALESCE(sum(allocation.amount) FILTER (
        WHERE allocation_collection.status = 'ACTIVE'
          AND component.component_kind = 'CURRENT_CHARGE'
      ), 0)::numeric AS allocated_current_charge
    FROM issued invoice_row
    LEFT JOIN public.finance_invoice_component_allocations allocation
      ON allocation.invoice_id = invoice_row.id
    LEFT JOIN public.invoice_payment_collections allocation_collection
      ON allocation_collection.id = allocation.collection_id
    LEFT JOIN public.finance_invoice_components component
      ON component.id = allocation.component_id
    GROUP BY invoice_row.id
  ),
  payment_facts AS MATERIALIZED (
    SELECT
      invoice_row.id AS invoice_id,
      COALESCE(payment_row.paid_event_amount, 0)::numeric AS paid_event_amount,
      COALESCE(allocation_row.allocated_amount, 0)::numeric AS allocated_amount,
      COALESCE(allocation_row.allocated_current_charge, 0)::numeric AS allocated_current_charge
    FROM issued invoice_row
    LEFT JOIN payment_events payment_row ON payment_row.invoice_id = invoice_row.id
    LEFT JOIN allocation_facts allocation_row ON allocation_row.invoice_id = invoice_row.id
  ),
  per_invoice AS MATERIALIZED (
    SELECT
      invoice_row.id,
      invoice_row.building_id,
      invoice_row.total_amount,
      invoice_row.paid_amount,
      component_row.component_status,
      component_row.current_charge,
      component_row.carried_invoice_debt,
      component_row.carried_deposit_debt,
      component_row.current_deposit,
      payment_row.paid_event_amount,
      payment_row.allocated_amount,
      CASE
        WHEN component_row.component_status = 'COMPLETE'
         AND component_row.finalized_at IS NOT NULL
         AND abs(payment_row.paid_event_amount - invoice_row.paid_amount) < 0.01
         AND component_row.positive_component_count = 1
         AND component_row.current_charge > 0
          THEN LEAST(payment_row.paid_event_amount, component_row.current_charge)
        WHEN component_row.component_status = 'COMPLETE'
         AND component_row.finalized_at IS NOT NULL
         AND abs(payment_row.paid_event_amount - invoice_row.paid_amount) < 0.01
         AND abs(payment_row.allocated_amount - payment_row.paid_event_amount) < 0.01
          THEN LEAST(payment_row.allocated_current_charge, component_row.current_charge)
        ELSE NULL
      END::numeric AS collected_current_charge,
      component_row.component_status = 'COMPLETE'
        AND component_row.finalized_at IS NOT NULL AS component_complete,
      CASE
        WHEN payment_row.paid_event_amount = 0
          THEN component_row.component_status = 'COMPLETE'
            AND component_row.finalized_at IS NOT NULL
        WHEN component_row.positive_component_count = 1
         AND component_row.current_charge > 0
          THEN abs(payment_row.paid_event_amount - invoice_row.paid_amount) < 0.01
        ELSE abs(payment_row.allocated_amount - payment_row.paid_event_amount) < 0.01
          AND abs(payment_row.paid_event_amount - invoice_row.paid_amount) < 0.01
      END AS allocation_complete
    FROM issued invoice_row
    LEFT JOIN component_pivot component_row ON component_row.invoice_id = invoice_row.id
    LEFT JOIN payment_facts payment_row ON payment_row.invoice_id = invoice_row.id
  ),
  issued_aggregate AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      count(invoice_row.id)::integer AS invoice_count,
      count(invoice_row.id) FILTER (
        WHERE NOT COALESCE(invoice_row.component_complete AND invoice_row.allocation_complete, false)
      )::integer AS allocation_unknown_count,
      COALESCE(sum(COALESCE(invoice_row.current_charge, invoice_row.total_amount)) FILTER (
        WHERE NOT COALESCE(invoice_row.component_complete AND invoice_row.allocation_complete, false)
      ), 0)::numeric AS allocation_unknown_amount,
      count(invoice_row.id) FILTER (
        WHERE invoice_row.component_status IS DISTINCT FROM 'COMPLETE'
      )::integer AS component_anomaly_count,
      bool_and(COALESCE(invoice_row.component_complete AND invoice_row.allocation_complete, false))
        FILTER (WHERE invoice_row.id IS NOT NULL) AS cohort_available,
      sum(invoice_row.current_charge)::numeric AS billed_current_charge,
      sum(invoice_row.collected_current_charge)::numeric AS collected_current_charge,
      sum(invoice_row.carried_invoice_debt)::numeric AS carried_invoice_debt,
      sum(invoice_row.carried_deposit_debt)::numeric AS carried_deposit_debt,
      sum(invoice_row.current_deposit)::numeric AS current_deposit
    FROM requested_buildings building_row
    LEFT JOIN per_invoice invoice_row ON invoice_row.building_id = building_row.id
    GROUP BY building_row.id
  ),
  pending_aggregate AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      count(invoice_row.id)::integer AS pending_count,
      COALESCE(sum(invoice_row.total_amount), 0)::numeric AS pending_amount
    FROM requested_buildings building_row
    LEFT JOIN public.invoices invoice_row
      ON invoice_row.building_id = building_row.id
     AND invoice_row.organization_id = p_organization_id
     AND invoice_row.deleted_at IS NULL
     AND invoice_row.kind = 'MONTHLY'
     AND invoice_row.billing_month = to_char(p_cohort_month, 'YYYY-MM')
     AND invoice_row.status::text IN ('DRAFT', 'PENDING_APPROVAL')
    GROUP BY building_row.id
  ),
  settlement_aggregate AS MATERIALIZED (
    SELECT
      building_row.id AS building_id,
      count(invoice_row.id)::integer AS settlement_count,
      COALESCE(sum(invoice_row.total_amount), 0)::numeric AS settlement_amount
    FROM requested_buildings building_row
    LEFT JOIN public.invoices invoice_row
      ON invoice_row.building_id = building_row.id
     AND invoice_row.organization_id = p_organization_id
     AND invoice_row.deleted_at IS NULL
     AND invoice_row.kind = 'SETTLEMENT'
     AND invoice_row.billing_month = to_char(p_cohort_month, 'YYYY-MM')
    GROUP BY building_row.id
  )
  SELECT
    building_row.id,
    building_row.name,
    p_cohort_month,
    COALESCE(issued_row.cohort_available, true),
    CASE WHEN COALESCE(issued_row.cohort_available, true)
      THEN COALESCE(issued_row.billed_current_charge, 0) ELSE NULL END,
    CASE WHEN COALESCE(issued_row.cohort_available, true)
      THEN COALESCE(issued_row.collected_current_charge, 0) ELSE NULL END,
    CASE WHEN COALESCE(issued_row.cohort_available, true)
      THEN COALESCE(issued_row.billed_current_charge, 0)
        - COALESCE(issued_row.collected_current_charge, 0)
      ELSE NULL END,
    CASE
      WHEN NOT COALESCE(issued_row.cohort_available, true) THEN NULL
      WHEN COALESCE(issued_row.billed_current_charge, 0) = 0 THEN NULL
      ELSE round(
        COALESCE(issued_row.collected_current_charge, 0) * 100.0
          / issued_row.billed_current_charge,
        2
      )
    END,
    issued_row.invoice_count,
    issued_row.allocation_unknown_count,
    issued_row.allocation_unknown_amount,
    issued_row.component_anomaly_count,
    COALESCE(issued_row.carried_invoice_debt, 0),
    COALESCE(issued_row.carried_deposit_debt, 0),
    COALESCE(issued_row.current_deposit, 0),
    pending_row.pending_count,
    pending_row.pending_amount,
    settlement_row.settlement_count,
    settlement_row.settlement_amount,
    clock_timestamp()
  FROM requested_buildings building_row
  JOIN issued_aggregate issued_row ON issued_row.building_id = building_row.id
  JOIN pending_aggregate pending_row ON pending_row.building_id = building_row.id
  JOIN settlement_aggregate settlement_row ON settlement_row.building_id = building_row.id
  ORDER BY lower(building_row.name) COLLATE "C", building_row.id;
END;
$$;








--
-- Name: FUNCTION business_performance_invoice_cohort_v1(p_organization_id uuid, p_cohort_month date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_invoice_cohort_v1(p_organization_id uuid, p_cohort_month date, p_building_ids uuid[]) IS 'MONTHLY issued current-charge cohort. Carry, deposit and settlement are reported separately; incomplete allocation fails closed.';








--
-- Name: business_performance_occupancy_monthly_v1(uuid, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_occupancy_monthly_v1(p_organization_id uuid, p_start_date date, p_end_date date, p_building_ids uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, total_rooms integer, occupied_rooms integer, occupancy_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_max_date_span_days CONSTANT integer := 400;
  v_building_ids uuid[];
  v_row record;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => false
  ) AS scope;

  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_end_date < p_start_date
     OR (p_end_date - p_start_date) > v_max_date_span_days THEN
    RAISE EXCEPTION 'Invalid business performance date range: expected ordered dates spanning at most 400 days'
      USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    SELECT *
    FROM public.fa_occupancy_monthly(
      p_start_date => p_start_date,
      p_end_date => p_end_date,
      p_building_ids => v_building_ids
    )
  LOOP
    IF v_row.building_id IS NULL
       OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false) THEN
      RAISE EXCEPTION 'Business performance access denied'
        USING ERRCODE = '42501';
    END IF;

    month := v_row.month;
    building_id := v_row.building_id;
    building_name := v_row.building_name;
    total_rooms := v_row.total_rooms;
    occupied_rooms := v_row.occupied_rooms;
    occupancy_pct := v_row.occupancy_pct;
    RETURN NEXT;
  END LOOP;
END;
$$;








--
-- Name: FUNCTION business_performance_occupancy_monthly_v1(p_organization_id uuid, p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_occupancy_monthly_v1(p_organization_id uuid, p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Org-bound monthly occupancy trend for an exact authorized physical building set. Date span is limited to 400 days.';








--
-- Name: business_performance_occupancy_snapshot_v1(uuid, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_occupancy_snapshot_v1(p_organization_id uuid, p_as_of_date date, p_building_ids uuid[]) RETURNS TABLE(building_id uuid, building_name text, total integer, occupied integer, reserved integer, maintenance integer, unavailable integer, available integer, occupancy_pct numeric, committed_pct numeric, missed_revenue numeric, generated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_seen_building_ids uuid[] := ARRAY[]::uuid[];
  v_row record;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => false
  ) AS scope;

  IF p_as_of_date IS NULL THEN
    RAISE EXCEPTION 'Invalid business performance as-of date: expected a non-null date'
      USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    WITH allowed AS (
      SELECT b.id, b.name
      FROM public.buildings b
      WHERE b.organization_id = p_organization_id
        AND b.deleted_at IS NULL
        AND b.is_virtual = false
        AND b.id = ANY(v_building_ids)
    ),
    classified AS (
      SELECT
        r.building_id AS bid,
        r.rent_price,
        CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.contracts c
            WHERE c.organization_id = p_organization_id
              AND c.room_id = r.id
              AND c.deleted_at IS NULL
              AND c.status = 'ACTIVE'
              AND c.start_date <= p_as_of_date
              AND (c.actual_end_date IS NULL OR c.actual_end_date >= p_as_of_date)
          ) THEN 'occupied'
          WHEN r.status = 'RESERVED' THEN 'reserved'
          WHEN r.status = 'MAINTENANCE' THEN 'maintenance'
          WHEN r.status = 'AVAILABLE' THEN 'available'
          ELSE 'unavailable'
        END AS grp
      FROM allowed a
      JOIN public.rooms r
        ON r.building_id = a.id
       AND r.organization_id = p_organization_id
      WHERE r.deleted_at IS NULL
    ),
    agg AS (
      SELECT
        bid,
        count(*)::integer AS total,
        count(*) FILTER (WHERE grp = 'occupied')::integer AS occupied,
        count(*) FILTER (WHERE grp = 'reserved')::integer AS reserved,
        count(*) FILTER (WHERE grp = 'maintenance')::integer AS maintenance,
        count(*) FILTER (WHERE grp = 'unavailable')::integer AS unavailable,
        count(*) FILTER (WHERE grp = 'available')::integer AS available,
        COALESCE(
          sum(GREATEST(rent_price, 0)) FILTER (WHERE grp = 'available'),
          0
        )::numeric AS missed_revenue
      FROM classified
      GROUP BY bid
    )
    SELECT
      a.id AS building_id,
      a.name AS building_name,
      COALESCE(g.total, 0) AS total,
      COALESCE(g.occupied, 0) AS occupied,
      COALESCE(g.reserved, 0) AS reserved,
      COALESCE(g.maintenance, 0) AS maintenance,
      COALESCE(g.unavailable, 0) AS unavailable,
      COALESCE(g.available, 0) AS available,
      CASE
        WHEN COALESCE(g.total, 0) = 0 THEN 0
        ELSE round(g.occupied * 100.0 / g.total, 1)
      END::numeric AS occupancy_pct,
      CASE
        WHEN COALESCE(g.total, 0) = 0 THEN 0
        ELSE round((g.occupied + g.reserved) * 100.0 / g.total, 1)
      END::numeric AS committed_pct,
      COALESCE(g.missed_revenue, 0) AS missed_revenue,
      now() AS generated_at
    FROM allowed a
    LEFT JOIN agg g ON g.bid = a.id
    ORDER BY a.name
  LOOP
    IF v_row.building_id IS NULL
       OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false)
       OR COALESCE(v_row.building_id = ANY(v_seen_building_ids), false) THEN
      RAISE EXCEPTION 'Business performance access denied'
        USING ERRCODE = '42501';
    END IF;

    v_seen_building_ids := array_append(v_seen_building_ids, v_row.building_id);
    building_id := v_row.building_id;
    building_name := v_row.building_name;
    total := v_row.total;
    occupied := v_row.occupied;
    reserved := v_row.reserved;
    maintenance := v_row.maintenance;
    unavailable := v_row.unavailable;
    available := v_row.available;
    occupancy_pct := v_row.occupancy_pct;
    committed_pct := v_row.committed_pct;
    missed_revenue := v_row.missed_revenue;
    generated_at := v_row.generated_at;
    RETURN NEXT;
  END LOOP;

  IF cardinality(v_seen_building_ids) <> cardinality(v_building_ids) THEN
    RAISE EXCEPTION 'Business performance access denied'
      USING ERRCODE = '42501';
  END IF;
END;
$$;








--
-- Name: FUNCTION business_performance_occupancy_snapshot_v1(p_organization_id uuid, p_as_of_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_occupancy_snapshot_v1(p_organization_id uuid, p_as_of_date date, p_building_ids uuid[]) IS 'Org-bound occupancy snapshot for an exact authorized physical building set. Rejects a null as-of date with SQLSTATE 22023.';








--
-- Name: business_performance_organizations_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_organizations_v1() RETURNS TABLE(organization_id uuid, organization_name text, authorized_buildings jsonb, authorized_physical_building_count bigint, authorization_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Business performance access denied'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH candidate_organizations AS MATERIALIZED (
    SELECT DISTINCT
      o.id AS organization_id,
      COALESCE(NULLIF(btrim(o.name), ''), NULLIF(btrim(o.slug), ''), 'Unnamed organization') AS organization_name
    FROM public.organizations o
    JOIN public.organization_memberships m
      ON m.organization_id = o.id
     AND m.user_id = auth.uid()
     AND m.status = 'ACTIVE'
     AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= clock_timestamp()
     AND (m.valid_to IS NULL OR m.valid_to > clock_timestamp())
    WHERE o.status = 'ACTIVE'
  ),
  roster_rows AS MATERIALIZED (
    SELECT
      candidate.organization_id,
      candidate.organization_name,
      roster.building_id,
      roster.building_name,
      roster.restricted_allowed,
      roster.analysis_provenance,
      roster.authorization_version
    FROM candidate_organizations candidate
    CROSS JOIN LATERAL app_private.business_performance_authorized_buildings_v1(
      candidate.organization_id,
      true
    ) AS roster
  )
  SELECT
    roster.organization_id,
    roster.organization_name,
    jsonb_agg(
      jsonb_build_object(
        'id', roster.building_id,
        'name', roster.building_name,
        'restricted_allowed', roster.restricted_allowed,
        'analysis_provenance', roster.analysis_provenance
      )
      ORDER BY lower(roster.building_name) COLLATE "C",
               roster.building_name COLLATE "C",
               roster.building_id
    ) AS authorized_buildings,
    count(*)::bigint AS authorized_physical_building_count,
    max(roster.authorization_version) AS authorization_version
  FROM roster_rows roster
  GROUP BY roster.organization_id, roster.organization_name
  HAVING count(*) > 0
     AND count(*) = count(DISTINCT roster.building_id)
     AND min(roster.authorization_version) = max(roster.authorization_version)
  ORDER BY roster.organization_name COLLATE "C", roster.organization_id;
END;
$$;








--
-- Name: FUNCTION business_performance_organizations_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_organizations_v1() IS 'Lists active organizations and canonical physical buildings available to the authenticated Business Performance caller.';








--
-- Name: business_performance_pnl_v1(uuid, text, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_pnl_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, is_virtual boolean, revenue numeric, expense numeric, net numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_max_date_span_days CONSTANT integer := 400;
  v_building_ids uuid[];
  v_row record;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_end_date < p_start_date
     OR (p_end_date - p_start_date) > v_max_date_span_days THEN
    RAISE EXCEPTION 'Invalid business performance date range: expected ordered dates spanning at most 400 days'
      USING ERRCODE = '22023';
  END IF;

  IF p_basis IS NULL OR p_basis NOT IN ('ACCRUAL', 'VOUCHER_DATE') THEN
    RAISE EXCEPTION 'Unsupported business performance basis'
      USING ERRCODE = '22023';
  END IF;

  IF p_basis = 'ACCRUAL' THEN
    FOR v_row IN
      SELECT *
      FROM public.fa_monthly_pnl_accrual(
        p_start_date => p_start_date,
        p_end_date => p_end_date,
        p_building_ids => v_building_ids
      )
    LOOP
      IF v_row.building_id IS NULL
         OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false) THEN
        RAISE EXCEPTION 'Business performance access denied'
          USING ERRCODE = '42501';
      END IF;

      month := v_row.month;
      building_id := v_row.building_id;
      building_name := v_row.building_name;
      is_virtual := v_row.is_virtual;
      revenue := v_row.revenue;
      expense := v_row.expense;
      net := v_row.net;
      RETURN NEXT;
    END LOOP;
  ELSE
    FOR v_row IN
      SELECT *
      FROM public.fa_monthly_pnl(
        p_start_date => p_start_date,
        p_end_date => p_end_date,
        p_building_ids => v_building_ids
      )
    LOOP
      IF v_row.building_id IS NULL
         OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false) THEN
        RAISE EXCEPTION 'Business performance access denied'
          USING ERRCODE = '42501';
      END IF;

      month := v_row.month;
      building_id := v_row.building_id;
      building_name := v_row.building_name;
      is_virtual := v_row.is_virtual;
      revenue := v_row.revenue;
      expense := v_row.expense;
      net := v_row.net;
      RETURN NEXT;
    END LOOP;
  END IF;
END;
$$;








--
-- Name: FUNCTION business_performance_pnl_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_pnl_v1(p_organization_id uuid, p_basis text, p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Org-bound Business Performance P&L for authorized physical buildings. Date span is limited to 400 days and includes the current 13-month UI window.';








--
-- Name: business_performance_reporting_roles_v1(uuid, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_reporting_roles_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]) RETURNS TABLE(income_expense_type_id uuid, type_name text, side text, category text, finance_reporting_role text, effective_from date, effective_to date, confirmed_at timestamp with time zone, confirmed_by uuid, suggested_role text, can_manage boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_actor uuid;
  v_can_manage boolean := false;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  IF p_month IS NULL OR p_month <> date_trunc('month', p_month)::date THEN
    RAISE EXCEPTION 'Finance reporting role month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  SELECT actor.user_id
    INTO v_actor
  FROM app_private.resolve_finance_actor_v2(p_organization_id) actor;

  SELECT decision.allowed
    INTO v_can_manage
  FROM app_private.authorize_tenant_action_v3(
    p_actor => v_actor,
    p_organization_id => p_organization_id,
    p_permission_key => 'categories.edit',
    p_building_id => NULL,
    p_cashbook_id => NULL
  ) decision;

  RETURN QUERY
  SELECT
    type_row.id,
    type_row.name,
    upper(type_row.type),
    type_row.category,
    assignment_row.finance_reporting_role,
    assignment_row.effective_from,
    assignment_row.effective_to,
    assignment_row.confirmed_at,
    assignment_row.confirmed_by,
    CASE
      WHEN upper(type_row.type) = 'EXPENSE'
       AND (
         lower(COALESCE(type_row.category, '')) LIKE '%tiền nhà%'
         OR lower(type_row.name) LIKE '%tiền nhà%'
         OR lower(COALESCE(type_row.category, '')) LIKE '%tien nha%'
         OR lower(type_row.name) LIKE '%tien nha%'
       )
        THEN 'LANDLORD_RENT_FIXED'
      WHEN upper(type_row.type) = 'INCOME'
       AND (
         lower(COALESCE(type_row.category, '')) LIKE '%tiền phòng%'
         OR lower(type_row.name) LIKE '%tiền phòng%'
         OR lower(COALESCE(type_row.category, '')) LIKE '%tien phong%'
         OR lower(type_row.name) LIKE '%tien phong%'
       )
        THEN 'ROOM_RENT_REVENUE'
      ELSE NULL
    END,
    COALESCE(v_can_manage, false)
  FROM public.income_expense_types type_row
  LEFT JOIN LATERAL (
    SELECT assignment.*
    FROM public.finance_reporting_role_assignments assignment
    WHERE assignment.organization_id = p_organization_id
      AND assignment.income_expense_type_id = type_row.id
      AND assignment.effective_from <= p_month
      AND (
        assignment.effective_to IS NULL
        OR assignment.effective_to >= p_month
      )
    ORDER BY assignment.effective_from DESC, assignment.id
    LIMIT 1
  ) assignment_row ON true
  WHERE type_row.organization_id = p_organization_id
    AND upper(type_row.type) IN ('INCOME', 'EXPENSE')
    AND NOT COALESCE(type_row.is_deposit, false)
  ORDER BY upper(type_row.type), lower(type_row.name) COLLATE "C", type_row.id;
END;
$$;








--
-- Name: FUNCTION business_performance_reporting_roles_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_reporting_roles_v1(p_organization_id uuid, p_month date, p_building_ids uuid[]) IS 'Read mapping state and conservative suggestions for the selected organization/month.';








--
-- Name: business_performance_set_reporting_role_v1(uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_set_reporting_role_v1(p_organization_id uuid, p_income_expense_type_id uuid, p_finance_reporting_role text, p_effective_from date) RETURNS TABLE(assignment_id uuid, finance_reporting_role text, effective_from date, effective_to date, confirmed_at timestamp with time zone, confirmed_by uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_allowed boolean;
  v_side text;
  v_existing_id uuid;
  v_next_start date;
  v_assignment_id uuid;
BEGIN
  IF p_organization_id IS NULL
     OR p_income_expense_type_id IS NULL
     OR p_finance_reporting_role IS NULL
     OR p_effective_from IS NULL
     OR p_effective_from <> date_trunc('month', p_effective_from)::date THEN
    RAISE EXCEPTION 'Invalid finance reporting role assignment input'
      USING ERRCODE = '22023';
  END IF;

  SELECT actor.user_id
    INTO v_actor
  FROM app_private.resolve_finance_actor_v2(p_organization_id) actor;

  SELECT decision.allowed
    INTO v_allowed
  FROM app_private.authorize_tenant_action_v3(
    p_actor => v_actor,
    p_organization_id => p_organization_id,
    p_permission_key => 'categories.edit',
    p_building_id => NULL,
    p_cashbook_id => NULL
  ) decision;
  IF NOT COALESCE(v_allowed, false) THEN
    RAISE EXCEPTION 'Business performance mapping access denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT upper(type_row.type)
    INTO v_side
  FROM public.income_expense_types type_row
  WHERE type_row.id = p_income_expense_type_id
    AND type_row.organization_id = p_organization_id
    AND NOT COALESCE(type_row.is_deposit, false)
  FOR SHARE;
  IF v_side IS NULL THEN
    RAISE EXCEPTION 'Income/expense type is outside the selected organization'
      USING ERRCODE = '42501';
  END IF;

  IF (
    v_side = 'INCOME'
    AND p_finance_reporting_role NOT IN (
      'ROOM_RENT_REVENUE',
      'OTHER_OPERATING_REVENUE',
      'PASS_THROUGH_REVENUE',
      'OUTSIDE_BREAK_EVEN_MODEL'
    )
  ) OR (
    v_side = 'EXPENSE'
    AND p_finance_reporting_role NOT IN (
      'LANDLORD_RENT_FIXED',
      'OTHER_FIXED_COST',
      'ROOM_VARIABLE_COST',
      'OTHER_VARIABLE_COST',
      'PASS_THROUGH_EXPENSE',
      'OUTSIDE_BREAK_EVEN_MODEL'
    )
  ) THEN
    RAISE EXCEPTION 'Finance reporting role does not match type side'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text || ':' || p_income_expense_type_id::text,
      0
    )
  );

  SELECT assignment.id
    INTO v_existing_id
  FROM public.finance_reporting_role_assignments assignment
  WHERE assignment.organization_id = p_organization_id
    AND assignment.income_expense_type_id = p_income_expense_type_id
    AND assignment.effective_from = p_effective_from
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.finance_reporting_role_assignments assignment
    SET
      finance_reporting_role = p_finance_reporting_role,
      confirmed_at = clock_timestamp(),
      confirmed_by = v_actor,
      updated_at = clock_timestamp()
    WHERE assignment.id = v_existing_id
    RETURNING assignment.id INTO v_assignment_id;
  ELSE
    UPDATE public.finance_reporting_role_assignments assignment
    SET
      effective_to = p_effective_from - 1,
      updated_at = clock_timestamp()
    WHERE assignment.organization_id = p_organization_id
      AND assignment.income_expense_type_id = p_income_expense_type_id
      AND assignment.effective_from < p_effective_from
      AND (
        assignment.effective_to IS NULL
        OR assignment.effective_to >= p_effective_from
      );

    SELECT min(assignment.effective_from)
      INTO v_next_start
    FROM public.finance_reporting_role_assignments assignment
    WHERE assignment.organization_id = p_organization_id
      AND assignment.income_expense_type_id = p_income_expense_type_id
      AND assignment.effective_from > p_effective_from;

    INSERT INTO public.finance_reporting_role_assignments (
      organization_id,
      income_expense_type_id,
      finance_reporting_role,
      effective_from,
      effective_to,
      confirmed_at,
      confirmed_by
    ) VALUES (
      p_organization_id,
      p_income_expense_type_id,
      p_finance_reporting_role,
      p_effective_from,
      CASE WHEN v_next_start IS NULL THEN NULL ELSE v_next_start - 1 END,
      clock_timestamp(),
      v_actor
    )
    RETURNING id INTO v_assignment_id;
  END IF;

  RETURN QUERY
  SELECT
    assignment.id,
    assignment.finance_reporting_role,
    assignment.effective_from,
    assignment.effective_to,
    assignment.confirmed_at,
    assignment.confirmed_by
  FROM public.finance_reporting_role_assignments assignment
  WHERE assignment.id = v_assignment_id;
END;
$$;








--
-- Name: FUNCTION business_performance_set_reporting_role_v1(p_organization_id uuid, p_income_expense_type_id uuid, p_finance_reporting_role text, p_effective_from date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_set_reporting_role_v1(p_organization_id uuid, p_income_expense_type_id uuid, p_finance_reporting_role text, p_effective_from date) IS 'Confirm or restate a finance role from a month boundary; requires categories.edit.';








--
-- Name: business_performance_snapshot_v1(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_snapshot_v1(p_organization_id uuid, p_building_ids uuid[]) RETURNS TABLE(building_id uuid, building_name text, total_rooms integer, rooms_available integer, rooms_occupied integer, rooms_reserved integer, rooms_maintenance integer, rooms_unavailable integer, vacancy_loss_month numeric, active_contracts bigint, avg_rent numeric, deposit_held numeric, receivable_total numeric, aging_not_due numeric, aging_1_30 numeric, aging_31_60 numeric, aging_61_90 numeric, aging_over_90 numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_building_ids uuid[];
  v_seen_building_ids uuid[] := ARRAY[]::uuid[];
  v_row record;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => true
  ) AS scope;

  FOR v_row IN
    SELECT * FROM public.fa_snapshot_kpis(p_building_ids => v_building_ids)
  LOOP
    IF v_row.building_id IS NULL
       OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false)
       OR COALESCE(v_row.building_id = ANY(v_seen_building_ids), false) THEN
      RAISE EXCEPTION 'Business performance access denied'
        USING ERRCODE = '42501';
    END IF;

    v_seen_building_ids := array_append(v_seen_building_ids, v_row.building_id);
    building_id := v_row.building_id;
    building_name := v_row.building_name;
    total_rooms := v_row.total_rooms;
    rooms_available := v_row.rooms_available;
    rooms_occupied := v_row.rooms_occupied;
    rooms_reserved := v_row.rooms_reserved;
    rooms_maintenance := v_row.rooms_maintenance;
    rooms_unavailable := v_row.rooms_unavailable;
    vacancy_loss_month := v_row.vacancy_loss_month;
    active_contracts := v_row.active_contracts;
    avg_rent := v_row.avg_rent;
    deposit_held := v_row.deposit_held;
    receivable_total := v_row.receivable_total;
    aging_not_due := v_row.aging_not_due;
    aging_1_30 := v_row.aging_1_30;
    aging_31_60 := v_row.aging_31_60;
    aging_61_90 := v_row.aging_61_90;
    aging_over_90 := v_row.aging_over_90;
    RETURN NEXT;
  END LOOP;

  IF cardinality(v_seen_building_ids) <> cardinality(v_building_ids) THEN
    RAISE EXCEPTION 'Business performance access denied'
      USING ERRCODE = '42501';
  END IF;
END;
$$;








--
-- Name: FUNCTION business_performance_snapshot_v1(p_organization_id uuid, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_snapshot_v1(p_organization_id uuid, p_building_ids uuid[]) IS 'Org-bound Business Performance finance snapshot for authorized physical buildings. Requires analysis and restricted-finance access.';








--
-- Name: business_performance_upcoming_vacancy_v1(uuid, date, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_performance_upcoming_vacancy_v1(p_organization_id uuid, p_as_of_date date, p_window_days integer, p_building_ids uuid[]) RETURNS TABLE(contract_id uuid, contract_number text, building_id uuid, building_name text, room_id uuid, room_name text, effective_end_date date, days_remaining integer, rent_price numeric, extension_applied boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_max_window_days CONSTANT integer := 366;
  v_building_ids uuid[];
  v_row record;
BEGIN
  SELECT scope.building_ids
    INTO v_building_ids
  FROM app_private.business_performance_exact_scope_v1(
    p_organization_id => p_organization_id,
    p_building_ids => p_building_ids,
    p_require_restricted => false
  ) AS scope;

  IF p_as_of_date IS NULL THEN
    RAISE EXCEPTION 'Invalid business performance as-of date: expected a non-null date'
      USING ERRCODE = '22023';
  END IF;

  IF p_window_days IS NULL
     OR p_window_days < 0
     OR p_window_days > v_max_window_days THEN
    RAISE EXCEPTION 'Invalid business performance vacancy window: expected 0 to 366 days'
      USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    WITH allowed AS (
      SELECT b.id, b.name
      FROM public.buildings b
      WHERE b.organization_id = p_organization_id
        AND b.deleted_at IS NULL
        AND b.is_virtual = false
        AND b.id = ANY(v_building_ids)
    ),
    allowed_rooms AS (
      SELECT
        r.id AS room_id,
        r.name AS room_name,
        r.rent_price,
        a.id AS building_id,
        a.name AS building_name
      FROM allowed a
      JOIN public.rooms r
        ON r.building_id = a.id
       AND r.organization_id = p_organization_id
      WHERE r.deleted_at IS NULL
    ),
    eff AS (
      SELECT
        c.id AS contract_id,
        c.contract_number,
        room.building_id,
        room.building_name,
        room.room_id,
        room.room_name,
        room.rent_price,
        GREATEST(
          c.end_date,
          COALESCE((
            SELECT max(ce.new_end_date::date)
            FROM public.contract_extensions ce
            WHERE ce.organization_id = p_organization_id
              AND ce.contract_id = c.id
              AND ce.status IN ('APPROVED', 'COMPLETED')
          ), c.end_date)
        )::date AS eff_end,
        EXISTS (
          SELECT 1
          FROM public.contract_extensions ce
          WHERE ce.organization_id = p_organization_id
            AND ce.contract_id = c.id
            AND ce.status IN ('APPROVED', 'COMPLETED')
            AND ce.new_end_date::date > c.end_date
        ) AS ext_applied
      FROM allowed_rooms room
      JOIN public.contracts c
        ON c.room_id = room.room_id
       AND c.organization_id = p_organization_id
      WHERE c.deleted_at IS NULL
        AND c.status = 'ACTIVE'
        AND c.start_date <= p_as_of_date
        AND (c.actual_end_date IS NULL OR c.actual_end_date >= p_as_of_date)
    ),
    per_room AS (
      SELECT DISTINCT ON (e.room_id)
        e.contract_id,
        e.contract_number,
        e.building_id,
        e.building_name,
        e.room_id,
        e.room_name,
        e.rent_price,
        e.eff_end,
        e.ext_applied
      FROM eff e
      ORDER BY e.room_id, e.eff_end DESC, e.contract_id
    )
    SELECT
      vacancy.contract_id,
      vacancy.contract_number,
      vacancy.building_id,
      vacancy.building_name,
      vacancy.room_id,
      vacancy.room_name,
      vacancy.eff_end AS effective_end_date,
      (vacancy.eff_end - p_as_of_date)::integer AS days_remaining,
      vacancy.rent_price::numeric AS rent_price,
      vacancy.ext_applied AS extension_applied
    FROM per_room vacancy
    WHERE (vacancy.eff_end - p_as_of_date)
      BETWEEN 0 AND p_window_days
    ORDER BY vacancy.eff_end, vacancy.building_name, vacancy.room_name
  LOOP
    IF v_row.building_id IS NULL
       OR NOT COALESCE(v_row.building_id = ANY(v_building_ids), false) THEN
      RAISE EXCEPTION 'Business performance access denied'
        USING ERRCODE = '42501';
    END IF;

    contract_id := v_row.contract_id;
    contract_number := v_row.contract_number;
    building_id := v_row.building_id;
    building_name := v_row.building_name;
    room_id := v_row.room_id;
    room_name := v_row.room_name;
    effective_end_date := v_row.effective_end_date;
    days_remaining := v_row.days_remaining;
    rent_price := v_row.rent_price;
    extension_applied := v_row.extension_applied;
    RETURN NEXT;
  END LOOP;
END;
$$;








--
-- Name: FUNCTION business_performance_upcoming_vacancy_v1(p_organization_id uuid, p_as_of_date date, p_window_days integer, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_performance_upcoming_vacancy_v1(p_organization_id uuid, p_as_of_date date, p_window_days integer, p_building_ids uuid[]) IS 'Org-bound upcoming-vacancy rows for an exact authorized physical building set. The window must be between 0 and 366 days.';








--
-- Name: calculate_lead_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_lead_score(lead_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  score INTEGER := 0;
  lead_record RECORD;
BEGIN
  SELECT * INTO lead_record FROM leads WHERE id = lead_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- Budget score (0-30 points)
  IF lead_record.budget_max IS NOT NULL THEN
    score := score + 30;
  ELSIF lead_record.budget_min IS NOT NULL THEN
    score := score + 15;
  END IF;

  -- Appointment date (0-25 points)
  IF lead_record.appointment_date IS NOT NULL THEN
    IF lead_record.appointment_date >= public.org_today_v1(NULL) THEN
      score := score + 25;
    ELSE
      score := score + 10;
    END IF;
  END IF;

  -- Source quality (0-20 points)
  CASE lead_record.source::text
    WHEN 'REFERRAL' THEN score := score + 20;
    WHEN 'WALK_IN' THEN score := score + 18;
    WHEN 'WEBSITE' THEN score := score + 15;
    WHEN 'FACEBOOK' THEN score := score + 12;
    WHEN 'ZALO' THEN score := score + 12;
    WHEN 'PHONE' THEN score := score + 10;
    ELSE score := score + 5;
  END CASE;

  -- Status progression (0-20 points)
  -- Using actual lead_status enum values: B1_LEAD, B2_APPOINTMENT, B3_CONSULTATION, CONVERTED, FAILED
  CASE lead_record.status::text
    WHEN 'CONVERTED' THEN score := score + 20;
    WHEN 'B3_CONSULTATION' THEN score := score + 15;
    WHEN 'B2_APPOINTMENT' THEN score := score + 10;
    WHEN 'B1_LEAD' THEN score := score + 5;
    WHEN 'FAILED' THEN score := score + 0;
    ELSE score := score + 0;
  END CASE;

  -- Email provided (0-5 points)
  IF lead_record.email IS NOT NULL THEN
    score := score + 5;
  END IF;

  -- Move-in date soon (0-5 points)
  IF lead_record.move_in_date IS NOT NULL AND lead_record.move_in_date <= public.org_today_v1(NULL) + INTERVAL '30 days' THEN
    score := score + 5;
  END IF;

  RETURN score;
END;
$$;








--
-- Name: can_access_building(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_building(_building_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  SELECT NOT EXISTS (
           SELECT 1
           FROM public.buildings b
           WHERE b.id = _building_id
             AND COALESCE(b.organization_id = ANY (public.sandbox_org_ids()), false)
             AND NOT COALESCE(b.organization_id = ANY (public.my_org_ids()), false)
         )
     AND (public.is_super_admin() OR app_private.can_v3('buildings.view', _building_id));
$$;








