--
-- Name: cancel_cashbook_closing_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_cashbook_closing_v1(p_request uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  r app_private.cashbook_closure_requests%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT * INTO r FROM app_private.cashbook_closure_requests
   WHERE id = p_request FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy đề nghị' USING ERRCODE = 'P0002'; END IF;
  IF r.status <> 'PENDING' THEN
    RETURN jsonb_build_object('request_id', p_request, 'changed', false, 'status', r.status);
  END IF;
  -- Chỉ hai bên trong cuộc (hoặc super admin) được rút lại.
  IF v_actor NOT IN (r.proposed_by, r.confirmer_user_id) AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Chỉ người đề nghị hoặc người được chỉ định xác nhận mới huỷ được'
      USING ERRCODE = '42501';
  END IF;

  UPDATE app_private.cashbook_closure_requests
     SET status = 'CANCELLED', cancelled_by = v_actor, cancelled_at = now(),
         cancel_reason = nullif(btrim(COALESCE(p_reason, '')), '')
   WHERE id = p_request;

  RETURN jsonb_build_object('request_id', p_request, 'changed', true, 'status', 'CANCELLED');
END
$$;








--
-- Name: cancel_income_expense_flex_v1(uuid, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_income_expense_flex_v1(p_voucher uuid, p_reason text, p_expected_approval_version bigint DEFAULT NULL::bigint, p_expected_posting_version bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_actor uuid := auth.uid();
  v_membership uuid;
  v_is_super boolean;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_active public.income_expense_postings%ROWTYPE;
  v_rev uuid;
  v_sum numeric;
  v_kind text;
  v_next_posting text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  IF char_length(v_reason) < 8 THEN
    RAISE EXCEPTION 'Phải ghi lý do huỷ (ít nhất 8 ký tự) để còn đối soát về sau.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v FROM public.income_expenses WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002'; END IF;

  -- Kiểm THÀNH VIÊN ngay sau khi tìm thấy phiếu: mọi thông điệp phía dưới
  -- (đã huỷ chưa, system_source gì, tên sổ quỹ, ngày chốt) đều là thông tin
  -- của tổ chức sở hữu phiếu — người ngoài không được nghe.
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m0
     WHERE m0.user_id = v_actor AND m0.organization_id = v.organization_id
       AND m0.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  IF v.approval_status = 'CANCELLED' THEN
    RETURN jsonb_build_object('id', p_voucher, 'changed', false, 'reason', 'đã huỷ trước đó');
  END IF;

  IF NOT app_private.ie_flex_mode_enabled_v1(v.organization_id) THEN
    RAISE EXCEPTION '[STRICT_MODE] Tổ chức đang bật Chuẩn kế toán — dùng đường Hoàn tác rồi Huỷ như cũ.'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.assert_manual_voucher_v1(p_voucher, 'huỷ');
  PERFORM app_private.assert_period_open_for_edit_v1(p_voucher, 'huỷ');

  v_is_super := public.is_super_admin();
  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = v.organization_id AND m.status = 'ACTIVE' LIMIT 1;
  IF v_membership IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  -- Quyền: huỷ thu chi trên toà + đang GIỮ đúng sổ. Chủ tổ chức / super admin
  -- được vào thẳng (quyết định #4). Chế độ linh hoạt nới TRẠNG THÁI, không nới
  -- quyền: income_expenses.cancel vẫn là điều kiện như đường cũ.
  -- Người TẠO phiếu được huỷ phiếu của chính mình (yêu cầu của chủ 29/07).
  IF NOT v_is_super AND NOT app_private.is_org_owner_v1(v.organization_id, v_actor)
     AND v.user_id IS DISTINCT FROM v_actor THEN
    DECLARE v_allowed boolean;
    BEGIN
      SELECT allowed INTO v_allowed FROM app_private.authorize_tenant_action_v3(
        v_actor, v.organization_id, 'income_expenses.cancel', v.building_id, v.account_id);
      IF NOT COALESCE(v_allowed, false) THEN
        RAISE EXCEPTION 'Không có quyền huỷ phiếu thu chi trên toà này' USING ERRCODE = '42501';
      END IF;
      IF v.account_id IS NOT NULL THEN
        PERFORM app_private.assert_cashbook_access_v2(
          v.organization_id, v.account_id, 'CUSTODIAN', v_membership);
      END IF;
    END;
  END IF;

  IF COALESCE(v.has_restricted_item, false)
     AND v.user_id IS DISTINCT FROM v_actor
     AND NOT public.can_view_restricted_ie() AND NOT v_is_super THEN
    RAISE EXCEPTION 'Phiếu chứa hạng mục hạn chế — không có quyền huỷ' USING ERRCODE = '42501';
  END IF;

  IF p_expected_approval_version IS NOT NULL
     AND COALESCE(v.approval_version, 1) <> p_expected_approval_version THEN
    RAISE EXCEPTION 'Phiếu vừa được người khác thay đổi — hãy tải lại' USING ERRCODE = '40001';
  END IF;
  IF p_expected_posting_version IS NOT NULL
     AND COALESCE(v.posting_version, 1) <> p_expected_posting_version THEN
    RAISE EXCEPTION 'Phiếu vừa được người khác ghi sổ — hãy tải lại' USING ERRCODE = '40001';
  END IF;

  -- Token: vừa qua được trigger đóng băng, vừa TẮT cầu a85 để nó không đảo
  -- chồng lên bút toán mà hàm này sắp tự viết.
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
  ON CONFLICT (income_expense_id) DO UPDATE
    SET xid = excluded.xid, purpose = excluded.purpose, granted_at = now();

  v_kind := 'CANCELLED_UNPOSTED';
  v_next_posting := CASE WHEN v.posting_mode = 'NON_CASH' THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END;

  IF COALESCE(v.posting_status, 'UNPOSTED') = 'POSTED' THEN
    SELECT * INTO v_active FROM public.income_expense_postings p
     WHERE p.id = v.active_posting_id_v2 FOR UPDATE;

    IF v_active.id IS NULL THEN
      -- Phiếu POSTED mà con trỏ rỗng là ca thật: nhánh BRIDGE_UNRESOLVED_POSTER
      -- của cầu a85 ghi dòng ngoại lệ rồi trả về mà không tạo posting.
      RAISE EXCEPTION 'Phiếu ghi nhận đã ghi sổ nhưng không tìm thấy bút toán gốc — báo quản trị trước khi huỷ.'
        USING ERRCODE = '55000';
    END IF;
    IF v_active.event_kind <> 'POSTING' THEN
      RAISE EXCEPTION 'Bút toán đang trỏ tới không phải bút toán gốc' USING ERRCODE = '55000';
    END IF;

    INSERT INTO public.income_expense_postings
      (organization_id, voucher_id, posting_subject_kind, posting_subject_id, direction,
       account_id, gross_amount, voucher_amount_snapshot, amount_basis, net_cash_effect,
       posted_on, posted_by_membership_id, posted_by_user_id, approval_version,
       event_kind, idempotency_key, source_kind, posting_generation, reversal_of_id, reversal_reason)
    VALUES
      (v_active.organization_id, v_active.voucher_id, v_active.posting_subject_kind,
       v_active.posting_subject_id, v_active.direction, v_active.account_id,
       v_active.gross_amount, v_active.voucher_amount_snapshot, v_active.amount_basis,
       -v_active.net_cash_effect, public.org_today_v1(NULL),
       COALESCE(v_membership, v_active.posted_by_membership_id), v_actor,
       COALESCE(v.approval_version, 1), 'REVERSAL',
       'flexcancel:' || v_active.id::text, 'MANUAL', v_active.posting_generation,
       v_active.id, v_reason)
    RETURNING id INTO v_rev;

    INSERT INTO public.income_expense_posting_lines
      (organization_id, posting_id, account_id, line_kind, signed_amount)
    SELECT l.organization_id, v_rev, l.account_id, 'REVERSAL', -l.signed_amount
    FROM public.income_expense_posting_lines l
    WHERE l.posting_id = v_active.id;

    -- Hậu điều kiện: mọi bút toán của phiếu này phải triệt tiêu về 0.
    SELECT COALESCE(sum(l.signed_amount), 0) INTO v_sum
    FROM public.income_expense_posting_lines l
    JOIN public.income_expense_postings p ON p.id = l.posting_id
    WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher;
    IF v_sum <> 0 THEN
      RAISE EXCEPTION 'Huỷ phiếu nhưng bút toán không triệt tiêu (còn lệch %) — dừng lại', v_sum
        USING ERRCODE = '55000';
    END IF;

    v_kind := 'CANCELLED_AFTER_POSTING';
    v_next_posting := 'REVERSED';
  END IF;

  UPDATE public.income_expenses SET
    approval_status = 'CANCELLED',
    review_state = 'RESOLVED',
    posting_status = v_next_posting,
    cancellation_kind = v_kind,
    active_posting_id_v2 = CASE WHEN v_rev IS NOT NULL THEN NULL ELSE active_posting_id_v2 END,
    reversed_by_posting_id = COALESCE(v_rev, reversed_by_posting_id),
    approval_version = COALESCE(approval_version, 1) + 1,
    posting_version = COALESCE(posting_version, 1) + CASE WHEN v_rev IS NOT NULL THEN 1 ELSE 0 END
  WHERE id = p_voucher;

  DELETE FROM app_private.ie_transition_authorization WHERE income_expense_id = p_voucher;

  INSERT INTO app_private.income_expense_cancellations
    (income_expense_id, organization_id, cancelled_by, cancel_reason, cancellation_kind,
     created_at_snap, approved_at_snap, amount_snap, cashbook_snap)
  VALUES
    (p_voucher, v.organization_id, v_actor, v_reason, v_kind,
     v.created_at, v.approved_at, v.total_amount, v.account_id)
  ON CONFLICT (income_expense_id) DO NOTHING;

  PERFORM app_private.append_income_expense_event_v1(
    v.organization_id, p_voucher, 'CANCELLED', v_actor, NULL,
    v.approval_status, 'CANCELLED', v_reason);

  RETURN jsonb_build_object(
    'id', p_voucher, 'changed', true,
    'cancellation_kind', v_kind,
    'reversal_posting_id', v_rev
  );
END
$$;








--
-- Name: cancel_income_expense_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_income_expense_v1(p_voucher_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_row public.income_expenses%rowtype;
  v_allowed boolean;
  v_rows integer;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;

  select * into v_row from public.income_expenses
   where id = p_voucher_id and deleted_at is null
   for update;
  if not found then
    raise exception 'Không tìm thấy phiếu';
  end if;

  if not app_private.is_income_expense_flow_owned(v_row.id) then
    raise exception 'Phiếu chưa thuộc luồng canonical — dùng đường legacy'
      using errcode = '55000';
  end if;

  -- 7ac: system-flow guard — phiếu do flow HỆ THỐNG sở hữu (refund/pair) không
  -- huỷ ở đây (sẽ bỏ quên reservation); 42501 'owned by system flow' để client
  -- chuyển sang decide_owned_income_expense_v2 (dispatcher §8).
  perform app_private.assert_income_expense_flow_owner_v2(v_row.id, 'CANONICAL_INCOME_EXPENSE');

  -- Defensive: create canonical không bao giờ gắn payment. Nếu có → thuộc domain
  -- payment (hoàn qua reverse_invoice_payment_v3), tuyệt đối không huỷ ở đây.
  if v_row.payment_id is not null then
    raise exception 'Phiếu gắn thanh toán hoá đơn — hãy hoàn tiền qua chức năng hoàn thanh toán';
  end if;

  if v_row.approval_status = 'CANCELLED' then
    return; -- idempotent no-op
  end if;

  -- t5_26: phiếu ĐÃ POSTED qua engine không huỷ trực tiếp (dùng reversal);
  -- request đang PENDING sẽ được TỰ ĐÓNG bên dưới sau khi huỷ phiếu.
  if exists (select 1 from public.approval_requests ar
              where ar.subject_type='FINANCIAL_VOUCHER' and ar.subject_id = v_row.id
                and ar.state = 'POSTED') then
    raise exception 'Phiếu đã được duyệt qua engine — dùng bút toán hoàn/đảo, không huỷ trực tiếp'
      using errcode = '55000';
  end if;

  -- Permission parity với RLS UPDATE legacy:
  --  PERMISSIVE (một trong): super_admin | update_rbac (admin/full-scope/building
  --  permitted 'edit') | owner + all_buildings('edit')
  --  RESTRICTIVE (bắt buộc): restricted-item rule.
  v_allowed :=
    public.is_super_admin()
    or public.is_admin()
    or public.has_perm_full_scope('income_expenses', 'edit')
    or (v_row.building_id is not null and v_row.building_id in
          (select public.permitted_building_ids('income_expenses', 'edit')))
    or (v_row.user_id = v_actor and v_row.building_id in
          (select public.ie_all_buildings_action_ids('edit')));
  if v_allowed and v_row.has_restricted_item then
    v_allowed := (v_row.user_id = v_actor)
      or public.can_view_restricted_ie()
      or public.is_super_admin();
  end if;
  if not v_allowed then
    raise exception 'Không có quyền huỷ phiếu này' using errcode = '42501';
  end if;

  v_actor_name := app_private.ie_actor_display_name_v1(v_actor);

  insert into app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  values (v_row.id, pg_current_xact_id(), 'CANCELLED');

  update public.income_expenses
     set approval_status = 'CANCELLED'
   where id = v_row.id;
  get diagnostics v_rows = row_count;

  delete from app_private.ie_transition_authorization
   where income_expense_id = v_row.id and xid = pg_current_xact_id();

  if v_rows <> 1 then
    raise exception 'cancel transition affected % rows (expected 1)', v_rows
      using errcode = '55000';
  end if;

  -- t5_26: tự đóng approval_request đang mở của phiếu (giải one-open-subject).
  update public.approval_requests ar
     set state = 'CANCELLED', version = ar.version + 1
   where ar.subject_type = 'FINANCIAL_VOUCHER'
     and ar.subject_id = v_row.id
     and ar.state = 'PENDING_APPROVAL';

  perform app_private.append_income_expense_event_v1(
    v_row.organization_id, v_row.id, 'CANCELLED', v_actor, v_actor_name,
    v_row.approval_status, 'CANCELLED',
    nullif(btrim(coalesce(p_reason, '')), ''));
end;
$$;








--
-- Name: cancel_income_voucher_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_income_voucher_v1(p_voucher uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_actor uuid := auth.uid();
  v_is_super boolean;
  v_membership uuid;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_flow text;
  v_coll public.invoice_payment_collections%ROWTYPE;
  v_inv public.invoices%ROWTYPE;
  v_lot public.customer_credit_lots%ROWTYPE;
  v_blocker record;
  v_core jsonb;
  v_counter_code text;
  v_paid numeric;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF char_length(v_reason) < 8 THEN
    RAISE EXCEPTION 'Phải ghi lý do huỷ (ít nhất 8 ký tự) để còn đối soát về sau.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v FROM public.income_expenses
   WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  -- Kiểm THÀNH VIÊN ngay sau khi tìm thấy phiếu: mọi thông điệp phía dưới (tên
  -- sổ quỹ, mã phiên bàn giao, mã phiếu chặn) đều là thông tin của tổ chức sở
  -- hữu phiếu — người ngoài không được nghe. Đọc thẳng bảng membership, KHÔNG
  -- join qua bảng có RLS (nếu không phép đo rò chéo tổ chức sẽ báo sạch nhầm).
  v_is_super := public.is_super_admin();
  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = v.organization_id
     AND m.status = 'ACTIVE' LIMIT 1;
  IF v_membership IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  IF v.type <> 'INCOME' THEN
    RAISE EXCEPTION 'Đây là phiếu CHI — huỷ ở luồng phiếu chi, cửa này chỉ dành cho phiếu thu.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Luật #8 (chủ chốt 01/08/2026, áp cho CẢ trang Thu chi lẫn trang Thu tiền):
  -- chỉ chính người đã thu/lập phiếu, chủ tổ chức, hoặc super admin.
  IF NOT v_is_super
     AND NOT app_private.is_org_owner_v1(v.organization_id, v_actor)
     AND v.user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Chỉ người đã thu khoản này (hoặc chủ tổ chức) mới huỷ được. Nhờ người thu hoặc chủ tổ chức thực hiện.'
      USING ERRCODE = '42501';
  END IF;

  -- Đã huỷ rồi thì không còn gì để làm. Nhánh này đứng SAU khối quyền: ma trận
  -- quyền 02/08/2026 cho thấy đặt trước sẽ trả HTTP 200 cho người KHÔNG có
  -- quyền, lệch với reader (reader nói ALREADY_CANCELLED cho mọi người, nhưng
  -- mã 200 của writer thì nói sai về quyền).
  IF v.approval_status = 'CANCELLED' THEN
    RETURN jsonb_build_object('id', p_voucher, 'changed', false, 'reason', 'đã huỷ trước đó');
  END IF;

  -- Ba khoá thời gian — GIỮ NGUYÊN theo quyết định #2 của chủ.
  PERFORM app_private.assert_period_open_for_edit_v1(p_voucher, 'huỷ');

  SELECT o.flow_kind INTO v_flow
  FROM app_private.income_expense_flow_ownership o
  WHERE o.income_expense_id = p_voucher;

  -- ══ NHÁNH 1: khoản thu hoá đơn V5 (đi theo cả ĐỢT THU) ═════════════
  -- Bộ đếm toàn vẹn count_invalid_payment_reversals_in_place_v1 định nghĩa
  -- bất biến ở mức COLLECTION (collection phải REVERSED, payment phải trỏ về
  -- đúng collection…). Huỷ lẻ MỘT phiếu của đợt thu nhiều phiếu sẽ làm bộ đếm
  -- khác 0 và kẹt vĩnh viễn assert_accounting_feature_activation_v1.
  -- ⇒ luôn đi qua reverse_invoice_collection_v5 nguyên đợt.
  IF v.payment_collection_id IS NOT NULL OR v_flow = 'INVOICE_COLLECTION_V5' THEN
    SELECT * INTO v_coll FROM public.invoice_payment_collections
     WHERE id = v.payment_collection_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Phiếu thu gắn đợt thu hoá đơn nhưng không tìm thấy đợt thu — báo quản trị.'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_coll.status <> 'ACTIVE' THEN
      RAISE EXCEPTION 'Đợt thu của phiếu này đã được hoàn tác trước đó.' USING ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_inv FROM public.invoices WHERE id = v_coll.invoice_id;

    -- LIFO — GIỮ theo quyết định #9. reverse_v5 cũng chặn ở trong, nhưng câu
    -- của nó không nói phải huỷ phiếu NÀO trước; ở đây nêu đích danh.
    IF abs(COALESCE(v_inv.paid_amount, 0)
           - (v_coll.expected_paid_amount + v_coll.applied_amount)) >= 0.01 THEN
      SELECT ie.code, ie.voucher_date INTO v_blocker
      FROM public.invoice_payment_collections c2
      JOIN public.invoice_payment_tenders t2 ON t2.collection_id = c2.id
      JOIN public.income_expenses ie ON ie.id = t2.voucher_id
      WHERE c2.invoice_id = v_coll.invoice_id
        AND c2.status = 'ACTIVE'
        AND c2.id <> v_coll.id
      ORDER BY c2.collection_date DESC, c2.created_at DESC, ie.code DESC
      LIMIT 1;

      IF v_blocker.code IS NOT NULL THEN
        RAISE EXCEPTION 'Phải huỷ khoản thu mới hơn trước: phiếu % ngày %. Hệ thống gỡ khoản thu theo thứ tự ngược thời gian để công nợ của hoá đơn không bị lệch.',
          v_blocker.code, to_char(v_blocker.voucher_date, 'DD/MM/YYYY')
          USING ERRCODE = 'P0001';
      END IF;
      RAISE EXCEPTION 'Hoá đơn còn khoản thu mới hơn phải huỷ trước (thứ tự ngược thời gian).'
        USING ERRCODE = 'P0001';
    END IF;

    -- Tiền thừa đã đem cấn sang hoá đơn khác thì máy không tự gỡ được.
    SELECT * INTO v_lot FROM public.customer_credit_lots
     WHERE source_collection_id = v_coll.id;
    IF FOUND AND v_lot.remaining_amount <> v_lot.amount THEN
      RAISE EXCEPTION 'Tiền thừa của lần thu này đã được cấn vào hoá đơn khác — phải gỡ khoản đã cấn trước rồi mới huỷ được.'
        USING ERRCODE = 'P0001';
    END IF;

    -- Ngày hoàn tác: reverse_v5 chặn cả hai đầu (không sớm hơn ngày thu, không
    -- ở tương lai). Kẹp vào khoảng hợp lệ thay vì để nó ném 22023.
    PERFORM public.reverse_invoice_collection_v5(
      v_coll.id,
      GREATEST(LEAST(public.org_today_v1(v.organization_id), CURRENT_DATE),
               v_coll.collection_date),
      v_reason,
      'inccancel-' || replace(p_voucher::text, '-', '') || '-' || substr(md5(v_reason), 1, 8));

    RETURN jsonb_build_object(
      'id', p_voucher, 'changed', true, 'mode', 'COLLECTION',
      'collection_id', v_coll.id);
  END IF;

  -- ══ NHÁNH 2: cặp phiếu bỏ cọc (thu + chi cấn nhau) ═════════════════
  -- Huỷ một chân mà để chân kia sống thì hai sổ lệch nhau vĩnh viễn; hàm
  -- chuyên trách khoá và lật CẢ CẶP theo đúng thứ tự.
  -- Điều kiện phải HẸP ĐÚNG bằng thứ handler chịu được: set_termination_forfeit_status_v1
  -- mở đầu bằng SELECT … FROM termination_forfeit_authorizations và ném 55000
  -- 'Voucher is not a termination forfeit pair' nếu không có dòng. Bắt theo
  -- system_source/notes như trước làm phiếu forfeit MỒ CÔI (có nhãn nhưng không
  -- có dòng cặp — 8 phiếu như vậy trên org TEST) kẹt vĩnh viễn ở HTTP 500.
  -- Phiếu mồ côi nay rơi xuống nhánh 3 và huỷ được bình thường.
  IF EXISTS (SELECT 1 FROM app_private.termination_forfeit_authorizations f
              WHERE f.revenue_voucher_id = p_voucher OR f.offset_voucher_id = p_voucher) THEN
    PERFORM public.set_termination_forfeit_status_v1(p_voucher, 'CANCELLED');
    RETURN jsonb_build_object('id', p_voucher, 'changed', true, 'mode', 'FORFEIT_PAIR');
  END IF;

  -- ══ NHÁNH 3: mọi phiếu thu còn lại ═════════════════════════════════
  -- Thủ công, thu cọc hợp đồng, thu hoá đơn LEGACY (system_source
  -- 'invoice.payment' — 1542 phiếu, nhóm lớn nhất), thu thanh lý…
  -- Không còn hỏi luồng nào sở hữu phiếu: "huỷ ở đâu cũng là huỷ".
  IF v.reversal_of_income_expense_id IS NOT NULL THEN
    RAISE EXCEPTION 'Đây là bút toán đối ứng của một phiếu khác — huỷ phiếu gốc chứ không huỷ riêng phiếu này.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Đã có phiếu ĐỐI ỨNG còn sống ⇒ tiền đã ra khỏi két bằng đường cũ rồi. Huỷ
  -- tiếp ở đây sẽ đảo bút toán LẦN HAI và rút khỏi sổ quỹ một khoản chưa từng
  -- vào. Hậu điều kiện sum=0 của lõi không thấy được vì nó chỉ cộng bút toán
  -- mang posting_subject_id của CHÍNH phiếu này, còn phiếu đối ứng mang id khác.
  SELECT c.code INTO v_counter_code
  FROM public.income_expenses c
  WHERE c.reversal_of_income_expense_id = p_voucher
    AND c.deleted_at IS NULL
    AND c.approval_status <> 'CANCELLED'
  LIMIT 1;
  IF v_counter_code IS NOT NULL THEN
    RAISE EXCEPTION 'Khoản thu này đã được hoàn tác bằng phiếu chi đối ứng % — huỷ phiếu đối ứng đó thay vì huỷ lại ở đây.',
      v_counter_code USING ERRCODE = 'P0001';
  END IF;

  -- Gắn hoá đơn nhưng KHÔNG có khoản thanh toán liên kết: đảo bút toán được
  -- (tiền rời két) nhưng recompute_invoice_for_id dẫn xuất paid_amount TỪ
  -- payments nên hoá đơn vẫn PAID — sổ quỹ nói "không thu", công nợ nói "đã
  -- thu đủ". Từ chối thay vì để lệch âm thầm.
  IF v.invoice_id IS NOT NULL AND v.payment_id IS NULL THEN
    RAISE EXCEPTION 'Khoản thu này gắn hoá đơn nhưng không có khoản thanh toán liên kết — huỷ ở màn hình hoá đơn/thanh lý để công nợ được tính lại đúng.'
      USING ERRCODE = 'P0001';
  END IF;

  -- begin/end_accounting_chain_write_v1: guard_payment_canonical_link chỉ cho
  -- core-writer đổi payments.reversed_at.
  PERFORM app_private.begin_accounting_chain_write_v1();

  v_core := app_private.cancel_income_voucher_core_v1(p_voucher, v_reason, v_actor, v_membership);

  -- Hoá đơn mở lại nợ (quyết định #4). recompute_invoice_for_id dẫn xuất
  -- paid_amount TỪ payments chứ không đọc trạng thái phiếu, nên phải đánh dấu
  -- khoản thanh toán. Đánh dấu `reversed_at` thay vì xoá — giữ dấu vết, đúng
  -- cách đường thu tiền V5 đang làm (client cũ xoá thẳng payments).
  IF v.payment_id IS NOT NULL THEN
    UPDATE public.payments
       SET reversed_at = COALESCE(reversed_at, clock_timestamp()),
           updated_at = now()
     WHERE id = v.payment_id;
  END IF;

  PERFORM app_private.end_accounting_chain_write_v1();

  -- Trigger trg_payments_recompute_invoice / trg_voucher_recompute_invoice /
  -- trg_ie_recompute_contract_deposit đã tự chạy, nhưng gọi lại tường minh cho
  -- ca phiếu gắn hoá đơn mà KHÔNG có payment (thu cọc ghi thẳng vào hợp đồng).
  IF v.invoice_id IS NOT NULL THEN
    PERFORM public.recompute_invoice_for_id(v.invoice_id);
  END IF;
  IF v.contract_id IS NOT NULL THEN
    PERFORM public.recompute_contract_deposit_paid(v.contract_id);
  END IF;

  RETURN v_core || jsonb_build_object('mode', 'MANUAL');
END
$$;








--
-- Name: FUNCTION cancel_income_voucher_v1(p_voucher uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_income_voucher_v1(p_voucher uuid, p_reason text) IS 'ĐỢT A: cửa DUY NHẤT huỷ phiếu THU (mọi trang). Rẽ nhánh đợt thu V5 / cặp bỏ cọc / thủ công. Quyền: chính người thu ∨ chủ tổ chức ∨ super admin. Giữ 3 khoá thời gian + LIFO.';








--
-- Name: cancel_invoice_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_invoice_v1(p_invoice_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to cancel invoice'
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = p_invoice_id
  ) THEN
    RAISE EXCEPTION 'Use cancel_invoice_with_credit_v1 for this invoice'
      USING ERRCODE = '55000';
  END IF;
  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  IF v_invoice.status = 'CANCELLED' THEN
    RETURN v_invoice;
  END IF;
  UPDATE public.invoices
     SET status = 'CANCELLED'
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  RETURN v_invoice;
END;
$$;








--
-- Name: cancel_invoice_with_credit_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_invoice_with_credit_v1(p_invoice_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_credit jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to cancel invoice'
      USING ERRCODE = '42501';
  END IF;
  IF v_invoice.status = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'invoice', to_jsonb(v_invoice),
      'credit', NULL,
      'noop', true
    );
  END IF;

  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  v_credit := app_private.reverse_invoice_customer_credit_v1(
    v_actor, p_invoice_id, 'Cancel invoice and restore applied customer credit', v_key
  );

  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.invoices
     SET status = 'CANCELLED'
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice', to_jsonb(v_invoice),
    'credit', v_credit,
    'noop', false
  );
END;
$_$;








--
-- Name: cancel_period_fee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_period_fee(p_voucher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bld       uuid;
  v_owner     uuid;
  v_src       text;
  v_del       timestamptz;
  v_creator   uuid;
  v_type_ok   boolean;
  v_in_batch  boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT ie.building_id, ie.system_source, ie.deleted_at, ie.user_id
    INTO v_bld, v_src, v_del, v_creator
    FROM income_expenses ie
   WHERE ie.id = p_voucher_id AND ie.type = 'EXPENSE'
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002'; END IF;
  IF v_del IS NOT NULL THEN RAISE EXCEPTION 'Phiếu đã bị hủy trước đó'; END IF;

  -- Phiếu hợp lệ để hủy từ trang này: tạo từ trang (fixed_fee/utility.bill)
  -- HOẶC phiếu chi có item khớp 1 hạng mục phí cố định (kể cả "(tự động lập)").
  IF v_src IS DISTINCT FROM 'utility.bill' AND v_src IS DISTINCT FROM 'fixed_fee' THEN
    SELECT EXISTS (
      SELECT 1
        FROM income_expense_items it
        JOIN income_expense_types t ON t.id = it.income_expense_type_id AND t.type = 'expense'
       WHERE it.income_expense_id = p_voucher_id
         AND EXISTS (
           SELECT 1 FROM unnest(ARRAY['tien_nha','dien','nuoc','internet','quan_ly','ve_sinh','cong_an','rac','thang_may']) k
            WHERE public.fee_type_matches(k, t.category, t.name)
         )
    ) INTO v_type_ok;
    IF NOT v_type_ok THEN
      RAISE EXCEPTION 'Phiếu này không thuộc hạng mục phí cố định — hủy ở trang Thu chi';
    END IF;
  END IF;

  SELECT EXISTS (SELECT 1 FROM income_expense_batch_items bi WHERE bi.income_expense_id = p_voucher_id)
    INTO v_in_batch;
  IF v_in_batch THEN
    RAISE EXCEPTION 'Phiếu thuộc phiếu tổng — hủy qua chi tiết phiếu tổng ở Thu chi';
  END IF;

  SELECT b.user_id INTO v_owner FROM buildings b WHERE b.id = v_bld;

  IF NOT (v_creator = auth.uid()
          OR public.can_access_building(v_bld)
          OR public.ie_all_buildings_scope(v_bld)
          OR v_owner = auth.uid()
          OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền hủy phiếu này' USING ERRCODE = '42501';
  END IF;

  UPDATE income_expenses SET deleted_at = now()
   WHERE id = p_voucher_id AND deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'voucher_id', p_voucher_id);
END;
$$;








--
-- Name: cancel_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_reconciliation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_r cashbook_reconciliations%ROWTYPE; v_owner uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_r FROM cashbook_reconciliations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy bản đối soát'; END IF;
  IF v_r.status = 'CANCELLED' THEN RAISE EXCEPTION 'Bản đối soát đã hủy'; END IF;
  SELECT user_id INTO v_owner FROM accounts WHERE id = v_r.account_id;
  IF NOT (auth.uid() = v_r.proposed_by OR auth.uid() = v_owner OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Chỉ người tạo hoặc chủ sổ mới hủy được';
  END IF;
  UPDATE cashbook_reconciliations SET status='CANCELLED', cancelled_at=now() WHERE id = p_id;
  RETURN jsonb_build_object('id', p_id, 'status', 'CANCELLED');
END;
$$;








--
-- Name: cancel_special_fee_claim_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_special_fee_claim_v1(p_claim_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_c     public.special_fee_claims;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF COALESCE(length(btrim(p_reason)),0) < 8 THEN
    RAISE EXCEPTION 'Lý do huỷ phải ít nhất 8 ký tự' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_c FROM special_fee_claims WHERE id = p_claim_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy claim' USING ERRCODE='P0002'; END IF;
  IF v_c.status = 'CANCELLED' THEN
    RETURN jsonb_build_object('claimId', p_claim_id, 'alreadyCancelled', true);
  END IF;

  IF NOT (public.can_access_building(v_c.building_id)
       OR public.ie_all_buildings_scope(v_c.building_id)
       OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền trên toà này' USING ERRCODE='42501';
  END IF;

  -- Phiếu đã duyệt thì KHÔNG cho gỡ claim: gỡ xong lượt sau sẽ sinh phiếu thứ hai
  -- cho cùng một ô, tức tự tạo ra trùng lặp. Muốn bỏ thì huỷ PHIẾU trước.
  IF v_c.voucher_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM income_expenses ie
        WHERE ie.id = v_c.voucher_id AND ie.approval_status = 'APPROVED'
          AND ie.deleted_at IS NULL) THEN
    RAISE EXCEPTION
      'Phiếu của ô này ĐÃ ĐƯỢC DUYỆT — huỷ claim bây giờ sẽ khiến lượt sinh sau đẻ phiếu thứ hai cho cùng một ô. Hãy huỷ PHIẾU trước.'
      USING ERRCODE = '55000';
  END IF;

  UPDATE special_fee_claims
     SET status='CANCELLED', cancelled_at=now(), cancelled_by=v_actor,
         cancel_reason=btrim(p_reason)
   WHERE id = p_claim_id;

  RETURN jsonb_build_object('claimId', p_claim_id, 'cancelled', true,
                            'voucherId', v_c.voucher_id);
END;
$$;








--
-- Name: cancel_unposted_income_expense_v2(uuid, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_unposted_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'eav', p_expected_approval_version, 'r', p_reason)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: reason is required' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.cancel_unposted.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.cancel', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: income_expenses.cancel required in scope' USING ERRCODE = '42501';
  END IF;

  IF v_ie.posting_status = 'POSTED' OR v_ie.active_posting_id_v2 IS NOT NULL THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: a posted voucher must be reversed, not cancelled' USING ERRCODE = '55000';
  END IF;
  IF v_ie.approval_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: voucher already cancelled' USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version OR v_ie.approval_version <> p_expected_approval_version THEN
    RAISE EXCEPTION 'cancel_unposted_income_expense_v2: version mismatch' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET approval_status = 'CANCELLED', review_state = 'RESOLVED',
         cancellation_kind = 'CANCELLED_UNPOSTED', review_reason = p_reason,
         posting_status = CASE WHEN v_ie.posting_mode = 'NON_CASH' THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END,
         review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  UPDATE public.approval_requests ar
     SET state = 'CANCELLED', outcome_kind = 'CANCELLED', outcome_reason = p_reason,
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'CANCELLED',
                               'reviewState', 'RESOLVED', 'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.cancel_unposted.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'CANCELLED', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.cancel_unposted.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION cancel_unposted_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_reason text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_unposted_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_reason text, p_idempotency_key text) IS 'Plan §7.2: cancel an unposted voucher with reason/audit; posted vouchers must be reversed.';








--
-- Name: cancel_utility_bill(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_utility_bill(p_voucher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bld     uuid;
  v_owner   uuid;
  v_src     text;
  v_del     timestamptz;
  v_creator uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT ie.building_id, ie.system_source, ie.deleted_at, ie.user_id
    INTO v_bld, v_src, v_del, v_creator
    FROM income_expenses ie
   WHERE ie.id = p_voucher_id
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002'; END IF;
  IF v_del IS NOT NULL THEN RAISE EXCEPTION 'Phiếu đã bị hủy trước đó'; END IF;
  IF v_src IS DISTINCT FROM 'utility.bill' AND v_src IS DISTINCT FROM 'fixed_fee' THEN
    RAISE EXCEPTION 'Phiếu này không phải phiếu Đóng tiền Điện nước';
  END IF;

  SELECT b.user_id INTO v_owner FROM buildings b WHERE b.id = v_bld;

  IF NOT (v_creator = auth.uid()
          OR public.can_access_building(v_bld)
          OR public.ie_all_buildings_scope(v_bld)
          OR v_owner = auth.uid()
          OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền hủy phiếu này' USING ERRCODE = '42501';
  END IF;

  UPDATE income_expenses SET deleted_at = now()
   WHERE id = p_voucher_id AND deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'voucher_id', p_voucher_id);
END;
$$;








--
-- Name: cashbook_balance_as_of_v1(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_balance_as_of_v1(p_cashbook uuid, p_as_of date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_membership uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT a.organization_id INTO v_org FROM public.accounts a WHERE a.id = p_cashbook;
  IF v_org IS NULL THEN RETURN NULL; END IF;

  IF public.is_super_admin() THEN
    RETURN app_private.cashbook_balance_as_of_v1(p_cashbook, COALESCE(p_as_of, public.org_today_v1(NULL)));
  END IF;

  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
   LIMIT 1;
  IF v_membership IS NULL THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của sổ quỹ' USING ERRCODE = '42501';
  END IF;

  -- Doctrine lỗ hổng C (Đợt 0): hàm tổng hợp SECURITY DEFINER phải tự giới hạn
  -- phạm vi nhìn. Dùng ĐÚNG helper mà Đợt 0 đã lập cho việc này —
  -- assert_cashbook_access_v2(...,'KNOWER',...) KHÔNG dùng được ở đây vì nó so
  -- possession_kind CHÍNH XÁC, nên người đang GIỮ sổ (CUSTODIAN) lại trượt.
  IF NOT EXISTS (SELECT 1 FROM app_private.ie_visible_cashbook_ids_v1() v
                  WHERE v.cashbook_id = p_cashbook) THEN
    RAISE EXCEPTION 'Không có quyền xem sổ quỹ này' USING ERRCODE = '42501';
  END IF;
  RETURN app_private.cashbook_balance_as_of_v1(p_cashbook, COALESCE(p_as_of, public.org_today_v1(NULL)));
END
$$;








--
-- Name: cashbook_close_confirmers_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_close_confirmers_v1(p_cashbook uuid) RETURNS TABLE(user_id uuid, full_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT a.organization_id INTO v_org FROM public.accounts a WHERE a.id = p_cashbook;
  IF v_org IS NULL THEN RETURN; END IF;
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
     WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
  ) THEN RETURN; END IF;

  RETURN QUERY
  SELECT m.user_id, COALESCE(p.full_name, '')::text
  FROM public.organization_memberships m
  LEFT JOIN public.profiles p ON p.id = m.user_id
  WHERE m.organization_id = v_org
    AND m.status = 'ACTIVE'
    AND m.user_id <> auth.uid()
    AND COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
          m.user_id, v_org, 'cashbooks.close_confirm', NULL, p_cashbook)), false)
  ORDER BY 2;
END
$$;








--
-- Name: cashbook_closing_blockers_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_closing_blockers_v1(p_cashbook uuid) RETURNS TABLE(code text, blocking boolean, detail text, count_n integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_is_virtual boolean;
  v_closed date;
  v_n integer;
  v_today date := public.org_today_v1(NULL);
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;

  SELECT a.organization_id, COALESCE(a.is_virtual, false)
    INTO v_org, v_is_virtual
  FROM public.accounts a WHERE a.id = p_cashbook AND a.deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy sổ quỹ' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
     WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của sổ quỹ' USING ERRCODE = '42501';
  END IF;

  IF v_is_virtual THEN
    code := 'VIRTUAL_CASHBOOK'; blocking := true; count_n := 0;
    detail := 'Sổ ảo (Thối / Làm tròn) không đếm tiền mặt được nên không chốt riêng. Nó đóng theo sổ mẹ.';
    RETURN NEXT;
  END IF;

  v_closed := app_private.cashbook_closed_through_v1(p_cashbook);
  IF v_closed IS NOT NULL AND v_closed >= v_today THEN
    code := 'ALREADY_CLOSED'; blocking := true; count_n := 0;
    detail := format('Sổ đã chốt tới %s — không chốt lại cùng ngày.', to_char(v_closed, 'DD/MM/YYYY'));
    RETURN NEXT;
  END IF;

  IF EXISTS (SELECT 1 FROM app_private.cashbook_closure_requests r
              WHERE r.cashbook_id = p_cashbook AND r.status = 'PENDING') THEN
    code := 'CLOSURE_PENDING'; blocking := true; count_n := 1;
    detail := 'Sổ này đã có một đề nghị chốt đang chờ xác nhận. Huỷ đề nghị cũ trước.';
    RETURN NEXT;
  END IF;

  -- Phiếu chờ duyệt: duyệt sau khi đã chốt số là đẻ posting NẰM TRONG kỳ vừa
  -- đóng băng ⇒ số đã ký sai. Phải dọn trước.
  SELECT count(*) INTO v_n FROM public.income_expenses ie
   WHERE ie.account_id = p_cashbook AND ie.deleted_at IS NULL
     AND ie.approval_status = 'UNAPPROVED' AND ie.voucher_date <= v_today;
  IF v_n > 0 THEN
    code := 'PENDING_APPROVAL'; blocking := true; count_n := v_n;
    detail := format('%s phiếu còn Chờ duyệt trong kỳ. Duyệt hoặc huỷ hết trước khi chốt.', v_n);
    RETURN NEXT;
  END IF;

  SELECT count(*) INTO v_n FROM public.income_expenses ie
   WHERE ie.account_id = p_cashbook AND ie.deleted_at IS NULL
     AND ie.approval_status = 'APPROVED'
     AND COALESCE(ie.posting_status, 'UNPOSTED') = 'UNPOSTED'
     AND ie.voucher_date <= v_today;
  IF v_n > 0 THEN
    code := 'APPROVED_NOT_POSTED'; blocking := true; count_n := v_n;
    detail := format('%s phiếu đã duyệt nhưng chưa ghi sổ. Ghi sổ hết thì số dư mới đúng.', v_n);
    RETURN NEXT;
  END IF;

  -- Phiên bàn giao tiền mặt PENDING: confirm_cash_handover chèn phiếu vào sổ,
  -- chốt trước là phiên đó kẹt.
  SELECT count(*) INTO v_n FROM public.cash_handovers h
   WHERE (h.from_account_id = p_cashbook OR h.to_account_id = p_cashbook)
     AND h.status = 'PENDING';
  IF v_n > 0 THEN
    code := 'HANDOVER_PENDING'; blocking := true; count_n := v_n;
    detail := format('%s phiên bàn giao tiền mặt đang chờ. Xác nhận hoặc huỷ hết trước khi chốt, nếu không chúng sẽ kẹt.', v_n);
    RETURN NEXT;
  END IF;

  -- CẢNH BÁO, không chặn: phiên CONFIRMED có phiếu gốc trong kỳ sắp khoá sẽ
  -- không huỷ được nữa (confirm_cancel_handover gỡ handover_id trên phiếu gốc,
  -- mà phiếu đó rơi vào kỳ đã đóng).
  SELECT count(DISTINCT h.id) INTO v_n
  FROM public.cash_handovers h
  JOIN public.income_expenses ie ON ie.handover_id = h.id
  WHERE h.status = 'CONFIRMED'
    AND (h.from_account_id = p_cashbook OR h.to_account_id = p_cashbook)
    AND ie.voucher_date <= v_today;
  IF v_n > 0 THEN
    code := 'HANDOVER_BECOMES_FINAL'; blocking := false; count_n := v_n;
    detail := format('%s phiên bàn giao đã xác nhận sẽ KHÔNG huỷ được nữa sau khi chốt.', v_n);
    RETURN NEXT;
  END IF;

  -- CẢNH BÁO: phiếu chưa có ảnh chứng từ. Sau khi chốt vẫn bổ sung ảnh được
  -- (quyết định #8) nên chỉ nhắc.
  SELECT count(*) INTO v_n FROM public.income_expenses ie
   WHERE ie.account_id = p_cashbook AND ie.deleted_at IS NULL
     AND ie.approval_status = 'APPROVED' AND ie.voucher_date <= v_today
     AND (ie.attachments IS NULL OR jsonb_array_length(COALESCE(ie.attachments, '[]'::jsonb)) = 0);
  IF v_n > 0 THEN
    code := 'MISSING_ATTACHMENTS'; blocking := false; count_n := v_n;
    detail := format('%s phiếu chưa có ảnh chứng từ. Sau khi chốt vẫn bổ sung được, nhưng nên chụp trước.', v_n);
    RETURN NEXT;
  END IF;

  -- Không ai đủ quyền xác nhận thì đề nghị sẽ treo vĩnh viễn — nói trước.
  SELECT count(*) INTO v_n
  FROM public.organization_memberships m
  WHERE m.organization_id = v_org AND m.status = 'ACTIVE' AND m.user_id <> auth.uid()
    AND COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
          m.user_id, v_org, 'cashbooks.close_confirm', NULL, p_cashbook)), false);
  IF v_n = 0 THEN
    code := 'NO_CONFIRMER'; blocking := true; count_n := 0;
    detail := 'Chưa có ai khác đủ quyền XÁC NHẬN nhận bàn giao sổ này. Nhờ quản trị cấp quyền "Xác nhận nhận bàn giao" cho người nhận trước.';
    RETURN NEXT;
  END IF;
END
$$;








--
-- Name: cashbook_closing_monthly_status_v1(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_closing_monthly_status_v1(p_organization_id uuid, p_month date) RETURNS TABLE(cashbook_id uuid, cashbook_name text, bank_name text, is_bank boolean, closed_through date, covered boolean, has_pending_request boolean, activity_count bigint, balance_at_month_end numeric, needs_closing boolean, can_be_closed boolean, confirmer_count integer, i_can_propose boolean, i_can_confirm boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_month     date;
  v_month_end date;
BEGIN
  IF v_uid IS NULL OR p_organization_id IS NULL THEN
    RETURN;
  END IF;

  -- my_org_ids() suy từ MEMBERSHIP, không đọc profiles.organization_id
  -- (6/10 profile trên prod trỏ SAI org).
  IF NOT (p_organization_id = ANY (public.my_org_ids())) THEN
    RETURN;
  END IF;

  v_month     := date_trunc('month', COALESCE(p_month, public.org_today_v1(NULL)))::date;
  v_month_end := (v_month + interval '1 month' - interval '1 day')::date;

  RETURN QUERY
  WITH visible AS (
    SELECT v.cashbook_id AS id FROM app_private.ie_visible_cashbook_ids_v1() v
  ), books AS (
    SELECT a.id, a.name, a.bank_name
    FROM public.accounts a
    JOIN visible vi ON vi.id = a.id
    WHERE a.organization_id = p_organization_id
      AND a.deleted_at IS NULL
      AND NOT COALESCE(a.is_virtual, false)   -- sổ ảo (Thối/Làm tròn) không có két
  ), grid AS (
    -- Một lượt quét (sổ × thành viên ACTIVE), hỏi cả hai khoá. Dùng lại cho cả
    -- phép đếm của hệ thống lẫn phép hỏi của người đang xem.
    SELECT
      b.id AS book_id,
      m.user_id,
      COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
        m.user_id, p_organization_id, 'cashbooks.close', NULL, b.id)), false) AS p_ok,
      COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
        m.user_id, p_organization_id, 'cashbooks.close_confirm', NULL, b.id)), false) AS c_ok
    FROM books b
    CROSS JOIN public.organization_memberships m
    WHERE m.organization_id = p_organization_id AND m.status = 'ACTIVE'
  ), two_party AS (
    SELECT
      g.book_id,
      count(*) FILTER (WHERE g.p_ok)                                  AS n_prop,
      count(*) FILTER (WHERE g.c_ok)                                  AS n_conf,
      count(*) FILTER (WHERE g.p_ok AND g.c_ok)                       AS n_both,
      -- có người KHÁC TÔI ký được / đề nghị được
      bool_or(g.c_ok AND g.user_id IS DISTINCT FROM v_uid)            AS other_conf,
      bool_or(g.p_ok AND g.user_id IS DISTINCT FROM v_uid)            AS other_prop,
      bool_or(g.p_ok AND g.user_id = v_uid)                           AS me_prop,
      bool_or(g.c_ok AND g.user_id = v_uid)                           AS me_conf
    FROM grid g
    GROUP BY g.book_id
  ), custody AS (
    -- Đang giữ sổ = điều kiện propose_cashbook_closing_v1 kiểm bằng
    -- assert_cashbook_access_v2(..., 'CUSTODIAN', ...). Hàm đó RAISE nên không
    -- gọi trực tiếp trong truy vấn được; soi thẳng binding (đủ cho gợi ý UI).
    SELECT DISTINCT pb.cashbook_id AS book_id
    FROM public.cashbook_possession_bindings pb
    JOIN public.organization_memberships m
      ON m.id = pb.membership_id AND m.status = 'ACTIVE' AND m.user_id = v_uid
    WHERE pb.organization_id = p_organization_id
      AND pb.possession_kind = 'CUSTODIAN'
      AND pb.valid_from <= now()
      AND (pb.valid_to IS NULL OR pb.valid_to > now())
  ), enriched AS (
    SELECT
      b.id, b.name, b.bank_name,
      app_private.cashbook_closed_through_v1(b.id) AS ct,
      EXISTS (
        SELECT 1 FROM app_private.cashbook_closure_requests r
        WHERE r.cashbook_id = b.id AND r.status = 'PENDING'
      ) AS pending,
      -- Phát sinh trong tháng: đếm theo DÒNG bút toán, không theo phiếu — tồn
      -- quỹ cộng theo account của DÒNG, mà dòng Thối/Làm tròn rơi vào sổ khác.
      (
        SELECT count(*)
        FROM public.income_expense_posting_lines l
        JOIN public.income_expense_postings p ON p.id = l.posting_id
        WHERE l.account_id = b.id
          AND l.organization_id = p_organization_id
          AND p.event_kind IN ('POSTING', 'REVERSAL')
          AND p.posted_on BETWEEN v_month AND v_month_end
      ) AS act,
      app_private.cashbook_balance_as_of_v1(b.id, v_month_end) AS bal,
      COALESCE(tp.n_prop, 0)      AS n_prop,
      COALESCE(tp.n_conf, 0)      AS n_conf,
      COALESCE(tp.n_both, 0)      AS n_both,
      COALESCE(tp.me_prop, false) AS me_prop,
      COALESCE(tp.me_conf, false) AS me_conf,
      COALESCE(tp.other_prop, false) AS other_prop,
      COALESCE(tp.other_conf, false) AS other_conf,
      EXISTS (SELECT 1 FROM custody c WHERE c.book_id = b.id) AS mine_to_hold
    FROM books b
    LEFT JOIN two_party tp ON tp.book_id = b.id
  )
  SELECT
    e.id,
    e.name,
    e.bank_name,
    (e.bank_name IS NOT NULL)                        AS is_bank,
    e.ct,
    (e.ct IS NOT NULL AND e.ct >= v_month_end)       AS covered,
    e.pending,
    e.act,
    e.bal,
    -- Sổ "phải chốt" tháng này: có phát sinh HOẶC còn dư cuối tháng. Sổ chết
    -- (0 phát sinh, dư 0) thì nhắc là ồn vô ích.
    (e.act > 0 OR COALESCE(e.bal, 0) <> 0)           AS needs_closing,
    -- Câu hỏi của HỆ THỐNG: có tồn tại cặp hai người khác nhau?
    (e.n_prop >= 1 AND e.n_conf >= 1
       AND NOT (e.n_prop = 1 AND e.n_conf = 1 AND e.n_both = 1)) AS can_be_closed,
    e.n_conf::int                                    AS confirmer_count,
    -- Câu hỏi của TÔI: tôi giữ sổ, tôi đề nghị được, và có người KHÁC ký được.
    (e.mine_to_hold AND e.me_prop AND e.other_conf)  AS i_can_propose,
    (e.me_conf AND e.other_prop)                     AS i_can_confirm
  FROM enriched e
  ORDER BY (e.ct IS NOT NULL AND e.ct >= v_month_end), e.name;
END
$$;








--
-- Name: FUNCTION cashbook_closing_monthly_status_v1(p_organization_id uuid, p_month date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cashbook_closing_monthly_status_v1(p_organization_id uuid, p_month date) IS 'PA4: mỗi sổ quỹ không-ảo NHÌN ĐƯỢC của tổ chức đã chốt tới đâu so với tháng p_month. covered=đã phủ hết tháng; needs_closing=có phát sinh hoặc còn dư; can_be_closed=HỆ có đủ hai người; i_can_propose/i_can_confirm=NGƯỜI ĐANG XEM làm được gì (propose còn đòi đang giữ sổ). VOLATILE vì gọi authorize_tenant_action_v3 (FOR SHARE).';








--
-- Name: cashbook_opening_balance(date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_opening_balance(p_before_date date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT public.cashbook_opening_balance_v2(p_before_date, p_building_id, p_account_id); $$;








--
-- Name: cashbook_opening_balance_v2(date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_opening_balance_v2(p_before_date date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_result numeric;
BEGIN
  PERFORM app_private.assert_cashbook_readable_v1(p_account_id);

  SELECT COALESCE(SUM(pl.signed_amount), 0)
  INTO v_result
  FROM public.income_expense_posting_lines pl
  JOIN public.income_expense_postings p
    ON p.id = pl.posting_id AND p.organization_id = pl.organization_id
  LEFT JOIN public.income_expenses ie
    ON ie.id = p.voucher_id AND ie.organization_id = p.organization_id
  WHERE pl.organization_id = ANY (public.my_org_ids())
    AND p.event_kind IN ('POSTING', 'REVERSAL')
    AND p.posted_on < p_before_date
    AND (p_building_id IS NULL OR ie.building_id = p_building_id)
    AND (p_account_id IS NULL OR pl.account_id = p_account_id)
    AND pl.account_id IN (SELECT v.cashbook_id FROM app_private.ie_visible_cashbook_ids_v1() v);

  RETURN v_result;
END
$$;








