CREATE FUNCTION public.cashbook_period_totals(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT public.cashbook_period_totals_v2(p_start, p_end, p_building_id, p_account_id); $$;








--
-- Name: cashbook_period_totals_v2(date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_period_totals_v2(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM app_private.assert_cashbook_readable_v1(p_account_id);

  SELECT jsonb_build_object(
    'income',  COALESCE(SUM(pl.signed_amount)  FILTER (WHERE pl.signed_amount > 0), 0),
    'expense', COALESCE(SUM(-pl.signed_amount) FILTER (WHERE pl.signed_amount < 0), 0)
  )
  INTO v_result
  FROM public.income_expense_posting_lines pl
  JOIN public.income_expense_postings p
    ON p.id = pl.posting_id AND p.organization_id = pl.organization_id
  LEFT JOIN public.income_expenses ie
    ON ie.id = p.voucher_id AND ie.organization_id = p.organization_id
  WHERE pl.organization_id = ANY (public.my_org_ids())
    AND p.event_kind IN ('POSTING', 'REVERSAL')
    AND (p_start IS NULL OR p.posted_on >= p_start)
    AND (p_end IS NULL OR p.posted_on <= p_end)
    AND (p_building_id IS NULL OR ie.building_id = p_building_id)
    AND (p_account_id IS NULL OR pl.account_id = p_account_id)
    AND pl.account_id IN (SELECT v.cashbook_id FROM app_private.ie_visible_cashbook_ids_v1() v);

  RETURN v_result;
END
$$;








--
-- Name: FUNCTION cashbook_period_totals_v2(p_start date, p_end date, p_building_id uuid, p_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cashbook_period_totals_v2(p_start date, p_end date, p_building_id uuid, p_account_id uuid) IS 'Plan §11.2: period income/expense from posting lines (SUM signed_amount by sign, window by posted_on, no approval filter), org-scoped. Mirrors legacy cashbook_period_totals.';








--
-- Name: cashbook_settlement_report(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashbook_settlement_report(p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_accounts jsonb;
  v_sessions jsonb;
  v_recons   jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;

  WITH scope AS (
    SELECT a.id, a.name, a.user_id, a.bank_name,
           p.full_name AS owner_name,
           awb.current_amount
    FROM accounts a
    LEFT JOIN profiles p ON p.id = a.user_id
    LEFT JOIN accounts_with_balance awb ON awb.id = a.id
    WHERE a.deleted_at IS NULL
      AND NOT a.is_virtual          -- guard cờ ảo (M1): sổ bút toán không bao giờ vào đối soát két
      AND (public.is_super_admin() OR a.user_id = auth.uid() OR public.same_team(a.user_id))
      -- ORG_ISOLATION_ACCOUNTS: cùng hai luật RLS đang áp trên public.accounts.
      AND NOT (public.is_super_admin()
               AND a.organization_id = ANY(public.sandbox_org_ids()))
      AND NOT ((public.is_super_admin() OR public.is_admin())
               AND a.user_id = ANY(public.demo_user_ids()))
      AND (
        btrim(a.name) LIKE '%Thu'
        OR a.name ILIKE 'tk%'
        OR a.bank_name IS NOT NULL
        OR EXISTS (SELECT 1 FROM cash_handovers ch WHERE ch.from_account_id = a.id)
      )
  )
  SELECT jsonb_agg(jsonb_build_object(
           'account_id', s.id,
           'name', s.name,
           'owner_name', s.owner_name,
           'is_bank', (s.name ILIKE 'tk%' OR s.bank_name IS NOT NULL),
           'current_balance', COALESCE(s.current_amount, 0),
           'period_collected', COALESCE((
              SELECT sum(ie.total_amount) FROM income_expenses ie
               WHERE ie.account_id = s.id AND ie.type='INCOME'
                 AND ie.approval_status='APPROVED' AND ie.deleted_at IS NULL
                 AND ie.handover_transfer_id IS NULL
                 AND ie.voucher_date BETWEEN p_from AND p_to), 0),
           'period_spent', COALESCE((
              SELECT sum(ie.total_amount) FROM income_expenses ie
               WHERE ie.account_id = s.id AND ie.type='EXPENSE'
                 AND ie.approval_status='APPROVED' AND ie.deleted_at IS NULL
                 AND ie.handover_transfer_id IS NULL
                 AND ie.voucher_date BETWEEN p_from AND p_to), 0),
           'period_handed_over', COALESCE((
              SELECT sum(ch.total_amount) FROM cash_handovers ch
               WHERE ch.from_account_id = s.id AND ch.status='CONFIRMED'
                 AND ch.confirmed_at::date BETWEEN p_from AND p_to), 0),
           'last_reconciliation', (
              SELECT jsonb_build_object('as_of_date', r.as_of_date, 'system_balance', r.system_balance,
                       'counted_balance', r.counted_balance, 'diff', r.diff, 'status', r.status,
                       'confirmed_at', r.confirmed_at)
                FROM cashbook_reconciliations r
               WHERE r.account_id = s.id AND r.status='CONFIRMED'
               ORDER BY r.as_of_date DESC, r.confirmed_at DESC LIMIT 1)
         ) ORDER BY (s.name ILIKE 'tk%' OR s.bank_name IS NOT NULL), s.name)
    INTO v_accounts FROM scope s;

  -- Phiên bàn giao trong kỳ mà tôi tham gia (RLS cash_handovers đã lọc; super admin thấy hết)
  SELECT jsonb_agg(jsonb_build_object(
           'code', ch.code, 'giver_name', ch.giver_name, 'receiver_name', ch.receiver_name,
           'gross', ch.gross_amount, 'expense', ch.expense_amount, 'net', ch.total_amount,
           'voucher_count', ch.voucher_count, 'status', ch.status,
           'confirmed_at', ch.confirmed_at, 'created_at', ch.created_at,
           'from_account', fa.name
         ) ORDER BY ch.confirmed_at DESC NULLS LAST, ch.created_at DESC)
    INTO v_sessions
    FROM cash_handovers ch
    LEFT JOIN accounts fa ON fa.id = ch.from_account_id
   WHERE ch.status = 'CONFIRMED'
     AND ch.confirmed_at::date BETWEEN p_from AND p_to
     AND (public.is_super_admin() OR ch.receiver_id = auth.uid() OR ch.giver_id = auth.uid());

  -- Lần chốt đối soát trong kỳ
  SELECT jsonb_agg(jsonb_build_object(
           'account_name', a.name, 'as_of_date', r.as_of_date,
           'system_balance', r.system_balance, 'counted_balance', r.counted_balance,
           'diff', r.diff, 'status', r.status, 'note', r.note, 'confirmed_at', r.confirmed_at
         ) ORDER BY r.as_of_date DESC)
    INTO v_recons
    FROM cashbook_reconciliations r
    JOIN accounts a ON a.id = r.account_id
   WHERE r.status = 'CONFIRMED'
     AND r.as_of_date BETWEEN p_from AND p_to
     AND (public.is_super_admin() OR a.user_id = auth.uid() OR public.same_team(a.user_id)
          OR r.proposed_by = auth.uid() OR r.counterparty_id = auth.uid());

  RETURN jsonb_build_object(
    'from', p_from, 'to', p_to,
    'accounts', COALESCE(v_accounts, '[]'::jsonb),
    'sessions', COALESCE(v_sessions, '[]'::jsonb),
    'reconciliations', COALESCE(v_recons, '[]'::jsonb));
END;
$$;








--
-- Name: cashflow_by_day(date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashflow_by_day(p_start date, p_end date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS TABLE(day date, income numeric, expense numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT * FROM public.cashflow_by_day_v2(p_start, p_end, p_building_id, p_account_id); $$;








--
-- Name: cashflow_by_day_v2(date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashflow_by_day_v2(p_start date, p_end date, p_building_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS TABLE(day date, income numeric, expense numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
BEGIN
  PERFORM app_private.assert_cashbook_readable_v1(p_account_id);

  RETURN QUERY
  SELECT
    p.posted_on AS day,
    COALESCE(SUM(pl.signed_amount)  FILTER (WHERE pl.signed_amount > 0), 0) AS income,
    COALESCE(SUM(-pl.signed_amount) FILTER (WHERE pl.signed_amount < 0), 0) AS expense
  FROM public.income_expense_posting_lines pl
  JOIN public.income_expense_postings p
    ON p.id = pl.posting_id AND p.organization_id = pl.organization_id
  LEFT JOIN public.income_expenses ie
    ON ie.id = p.voucher_id AND ie.organization_id = p.organization_id
  WHERE pl.organization_id = ANY (public.my_org_ids())
    AND p.event_kind IN ('POSTING', 'REVERSAL')
    AND p.posted_on >= p_start
    AND p.posted_on <= p_end
    AND (p_building_id IS NULL OR ie.building_id = p_building_id)
    AND (p_account_id IS NULL OR pl.account_id = p_account_id)
    AND pl.account_id IN (SELECT v.cashbook_id FROM app_private.ie_visible_cashbook_ids_v1() v)
  GROUP BY p.posted_on
  ORDER BY p.posted_on;
END
$$;








