--
-- Name: check_contract_representative(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_contract_representative() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_representative = true THEN
    UPDATE contract_customers
    SET is_representative = false
    WHERE contract_id = NEW.contract_id AND id != NEW.id AND is_representative = true;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: check_sla_breach(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_sla_breach() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Check response SLA breach
  IF NEW.first_response_at IS NOT NULL AND OLD.first_response_at IS NULL THEN
    IF NEW.first_response_at > NEW.created_at + (NEW.sla_response_time_minutes || ' minutes')::INTERVAL THEN
      NEW.sla_response_breached := TRUE;
    END IF;
  END IF;

  -- Check resolution SLA breach
  IF NEW.resolved_at IS NOT NULL AND OLD.resolved_at IS NULL THEN
    IF NEW.resolved_at > NEW.sla_due_date THEN
      NEW.sla_breached := TRUE;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: check_voucher_period_open_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_voucher_period_open_v1(p_ids uuid[]) RETURNS TABLE(id uuid, is_open boolean, reason_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_id uuid;
  v_org uuid;
  v_msg text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  FOREACH v_id IN ARRAY COALESCE(p_ids, ARRAY[]::uuid[]) LOOP
    SELECT ie.organization_id INTO v_org FROM public.income_expenses ie WHERE ie.id = v_id;
    CONTINUE WHEN v_org IS NULL;

    -- Chỉ trả lời về phiếu trong tổ chức mà người gọi đang là thành viên.
    IF NOT public.is_super_admin() AND NOT EXISTS (
      SELECT 1 FROM public.organization_memberships m
       WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
    ) THEN
      CONTINUE;
    END IF;

    BEGIN
      PERFORM app_private.assert_period_open_for_edit_v1(v_id, 'sửa');
      id := v_id; is_open := true; reason_code := NULL; RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      v_msg := SQLERRM;
      id := v_id;
      is_open := false;
      reason_code := CASE
        WHEN v_msg LIKE '%CASHBOOK_CLOSED%'  THEN 'CASHBOOK_CLOSED'
        WHEN v_msg LIKE '%HANDOVER_LOCKED%'  THEN 'HANDOVER_LOCKED'
        WHEN v_msg LIKE '%PROFIT_LOCKED%'    THEN 'PROFIT_LOCKED'
        ELSE 'UNKNOWN'
      END;
      RETURN NEXT;
    END;
  END LOOP;
END
$$;








--
-- Name: clone_org_request_sync_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_org_request_sync_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'clone_org'
    AS $$
DECLARE v_id bigint; v_last timestamptz;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Chỉ super admin được đồng bộ công ty TEST' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (SELECT 1 FROM clone_org.sync_request WHERE state IN ('PENDING', 'RUNNING')) THEN
    RAISE EXCEPTION 'SYNC_IN_PROGRESS' USING ERRCODE = '55000';
  END IF;

  SELECT max(finished_at) INTO v_last FROM clone_org.sync_request WHERE state = 'DONE';
  IF v_last IS NOT NULL AND now() - v_last < interval '2 minutes' THEN
    RAISE EXCEPTION 'COOLDOWN' USING ERRCODE = '55000';
  END IF;

  INSERT INTO clone_org.sync_request (requested_by) VALUES (auth.uid()) RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'request_id', v_id, 'state', 'PENDING');
END
$$;








--
-- Name: clone_org_sync_status_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_org_sync_status_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'clone_org'
    AS $$
  SELECT CASE WHEN NOT public.is_super_admin() THEN NULL::jsonb ELSE
    jsonb_build_object(
      'org_id',   (public.sandbox_org_ids())[1],
      'org_name', (SELECT name FROM public.organizations WHERE id = (public.sandbox_org_ids())[1]),
      'last_sync_at', (SELECT max(finished_at) FROM clone_org.sync_log WHERE ok),
      'rows_copied',  (SELECT rows_copied FROM clone_org.sync_log WHERE ok
                        ORDER BY finished_at DESC LIMIT 1),
      'pending', (SELECT jsonb_build_object('id', r.id, 'state', r.state,
                                            'requested_at', r.requested_at,
                                            'error', r.error_text)
                    FROM clone_org.sync_request r ORDER BY r.id DESC LIMIT 1)
    )
  END;
$$;








--
-- Name: complete_inspection(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_inspection(p_session uuid, p_condition_note text DEFAULT 'OK'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_sess public.inspection_sessions;
  v_reqs JSONB;
  v_missing TEXT[] := '{}';
  v_dwell_total INT;
  v_photos_ok INT;
  v_geo_ok BOOLEAN;
  v_pass BOOLEAN;
  v_tick JSONB := NULL;
  v_spawned UUID := NULL;
  v_pending_b BOOLEAN := false;
  it JSONB;
BEGIN
  SELECT * INTO v_sess FROM public.inspection_sessions WHERE id = p_session;
  IF NOT FOUND OR v_sess.user_id <> v_uid THEN RAISE EXCEPTION 'Phiên không hợp lệ'; END IF;
  IF v_sess.status NOT IN ('open','presence') THEN
    RETURN jsonb_build_object('status', v_sess.status, 'message', 'Phiên đã đóng trước đó');
  END IF;
  -- Ân hạn qua nửa đêm (20260720190000): phiên bắt đầu 23:50 hoàn thành 00:10 KHÔNG
  -- được rơi vào khoảng trống. Ngày công tính theo session_date (ngày nhân viên
  -- thực sự có mặt), miễn là chưa quá 4 giờ kể từ lúc bắt đầu.
  IF v_sess.session_date <> public.vn_local_date(now())
     AND now() - v_sess.started_at > INTERVAL '4 hours' THEN
    UPDATE public.inspection_sessions SET status='expired', ended_at=now(), updated_at=now() WHERE id = p_session;
    RETURN jsonb_build_object('status','expired','message','Phiên đã quá hạn — hôm nay là cơ hội mới');
  END IF;

  v_reqs := public.v5_building_reqs(v_sess.building_id);

  -- Chốt dwell phiên hiện tại = now - started_at (cap 900s) — đồng hồ thật, không cần chụp thêm ảnh
  UPDATE public.inspection_sessions SET
    dwell_seconds = GREATEST(dwell_seconds, LEAST(EXTRACT(EPOCH FROM (now() - started_at))::int, 900)),
    updated_at = now()
  WHERE id = p_session;

  -- Σ dwell các phiên CÙNG NGÀY CÙNG TOÀ (C1 — cộng dồn), mỗi phiên cap 900s
  SELECT COALESCE(SUM(LEAST(GREATEST(dwell_seconds,
           COALESCE(EXTRACT(EPOCH FROM (COALESCE(ended_at, now()) - started_at))::int, 0)), 900)), 0)
  INTO v_dwell_total
  FROM public.inspection_sessions
  WHERE user_id = v_uid AND building_id = v_sess.building_id AND session_date = v_sess.session_date;

  SELECT COUNT(*) INTO v_photos_ok FROM public.inspection_photos WHERE session_id = p_session;
  SELECT EXISTS (SELECT 1 FROM public.inspection_photos WHERE session_id = p_session AND geofence_status = 'ok')
    INTO v_geo_ok;

  IF v_sess.type = 'QUICK' THEN
    v_pass := v_photos_ok >= 2 AND v_geo_ok;
    IF NOT v_pass THEN
      IF v_photos_ok < 2 THEN v_missing := array_append(v_missing, 'Còn ' || (2 - v_photos_ok) || ' ảnh nữa'); END IF;
      IF NOT v_geo_ok THEN v_missing := array_append(v_missing, 'Cần ≥1 ảnh trong bán kính toà'); END IF;
    END IF;
  ELSE
    FOR it IN SELECT * FROM jsonb_array_elements(v_sess.checklist) LOOP
      IF (it->>'required')::boolean AND NOT COALESCE((it->>'done')::boolean, false) THEN
        v_missing := array_append(v_missing, it->>'label');
      END IF;
    END LOOP;
    IF v_photos_ok < (v_reqs->>'photos_min')::int THEN
      v_missing := array_append(v_missing, 'Còn ' || ((v_reqs->>'photos_min')::int - v_photos_ok) || ' ảnh nữa');
    END IF;
    IF v_dwell_total < (v_reqs->>'dwell_min_seconds')::int THEN
      v_missing := array_append(v_missing,
        'Ở lại thêm ' || CEIL(((v_reqs->>'dwell_min_seconds')::int - v_dwell_total) / 60.0) || ' phút nữa');
    END IF;
    IF NOT v_geo_ok THEN v_missing := array_append(v_missing, 'Cần ≥1 ảnh trong bán kính toà'); END IF;
    v_pass := COALESCE(array_length(v_missing, 1), 0) = 0;
  END IF;

  IF v_pass AND v_sess.type = 'FULL' AND p_condition_note IS NOT NULL AND p_condition_note <> 'OK' THEN
    INSERT INTO public.jobs (user_id, title, description, building_id, status, priority, assignee_id)
    VALUES (v_uid, 'Sửa chữa từ kiểm tra nhà', p_condition_note, v_sess.building_id, 'IN_PROGRESS', 'NORMAL', v_uid)
    RETURNING id INTO v_spawned;
  END IF;

  IF v_pass THEN
    UPDATE public.inspection_sessions SET
      status = CASE WHEN type = 'FULL' THEN 'passed' ELSE 'quick_done' END,
      condition_note = p_condition_note, spawned_job_id = v_spawned,
      ended_at = now(), fail_reasons = NULL, updated_at = now()
    WHERE id = p_session;

    IF v_sess.type = 'FULL' THEN
      v_tick := public.v5_tick_attendance(v_uid, v_sess.session_date, 'FULL', p_session, NULL);
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.salary_attendance_day sad
        WHERE sad.user_id = v_uid AND sad.work_date = v_sess.session_date AND sad.status = 'pending_check'
          AND EXISTS (SELECT 1 FROM jsonb_array_elements(sad.evidence) e
                      WHERE e->>'kind' = 'pending_check' AND e->>'building_id' = v_sess.building_id::text)
      ) INTO v_pending_b;
      IF v_pending_b THEN
        v_tick := public.v5_tick_attendance(v_uid, v_sess.session_date, 'PAYMENT', p_session, 'check-sau-thu-tiền');
      END IF;
    END IF;

    RETURN jsonb_build_object('status', CASE WHEN v_sess.type='FULL' THEN 'passed' ELSE 'quick_done' END,
                              'spawned_job_id', v_spawned, 'tick', v_tick,
                              'dwell_total_seconds', v_dwell_total);
  ELSE
    UPDATE public.inspection_sessions SET
      status = 'presence',
      condition_note = p_condition_note, fail_reasons = v_missing, updated_at = now()
    WHERE id = p_session;
    RETURN jsonb_build_object('status', 'presence', 'missing', to_jsonb(v_missing),
      'message', 'Còn ' || COALESCE(array_length(v_missing,1),0) || ' mục nữa là đủ công hôm nay',
      'dwell_total_seconds', v_dwell_total);
  END IF;
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, source_id, error_text, payload)
  VALUES (v_uid, 'complete_inspection', p_session, SQLERRM, NULL);
  RAISE;
END; $$;








--
-- Name: compute_first_billing_month_v2(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_first_billing_month_v2(p_start_date date, p_end_date date) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  WITH bounds AS (
    SELECT LEAST(p_start_date, p_end_date) AS from_date,
           GREATEST(p_start_date, p_end_date) AS to_date
  ), full_months AS (
    SELECT month_start::date
    FROM bounds,
         LATERAL generate_series(
           date_trunc('month', from_date),
           date_trunc('month', to_date),
           interval '1 month'
         ) month_start
    WHERE month_start::date >= from_date
      AND (month_start + interval '1 month - 1 day')::date <= to_date
    ORDER BY month_start DESC
    LIMIT 1
  )
  SELECT to_char(
    COALESCE(
      (SELECT month_start FROM full_months),
      date_trunc('month', p_start_date)::date
    ),
    'YYYY-MM'
  );
$$;








--
-- Name: confirm_cancel_handover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cancel_handover(p_handover_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h     cash_handovers%ROWTYPE;
  v_chain text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_h FROM cash_handovers WHERE id = p_handover_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên bàn giao'; END IF;
  IF v_h.cancel_requested_by IS NULL THEN
    RAISE EXCEPTION 'Phiên % chưa có yêu cầu hủy', v_h.code;
  END IF;
  IF auth.uid() NOT IN (v_h.giver_id, v_h.receiver_id) THEN
    RAISE EXCEPTION 'Chỉ người giao hoặc người nhận mới được xác nhận hủy';
  END IF;
  IF auth.uid() = v_h.cancel_requested_by THEN
    RAISE EXCEPTION 'Hủy phiên cần BÊN KIA xác nhận (bạn là người đã yêu cầu hủy)';
  END IF;
  IF v_h.status NOT IN ('PENDING', 'CONFIRMED') THEN
    RAISE EXCEPTION 'Phiên % đã hủy rồi', v_h.code;
  END IF;

  -- Chain LEGACY: phiếu THU đơn đã được bàn giao tiếp?
  IF v_h.transfer_income_id IS NOT NULL THEN
    SELECT ch.code INTO v_chain
      FROM income_expenses ie
      JOIN cash_handovers ch ON ch.id = ie.handover_id
     WHERE ie.id = v_h.transfer_income_id AND ch.status <> 'CANCELLED';
    IF v_chain IS NOT NULL THEN
      RAISE EXCEPTION 'Tiền của phiên % đã được bàn giao tiếp trong phiên % — hủy phiên đó trước', v_h.code, v_chain;
    END IF;
  END IF;

  -- Chain MỚI (batch): bất kỳ phiếu THU lẻ nào đã được bàn giao tiếp?
  SELECT ch.code INTO v_chain
    FROM income_expenses ie
    JOIN cash_handovers ch ON ch.id = ie.handover_id
   WHERE ie.handover_transfer_id = p_handover_id AND ie.type = 'INCOME'
     AND ch.status <> 'CANCELLED'
   LIMIT 1;
  IF v_chain IS NOT NULL THEN
    RAISE EXCEPTION 'Tiền của phiên % đã được bàn giao tiếp trong phiên % — hủy phiên đó trước', v_h.code, v_chain;
  END IF;

  -- Set CANCELLED TRƯỚC để trigger guard nhả các phiếu liên quan
  UPDATE cash_handovers
     SET status = 'CANCELLED', cancelled_by = auth.uid(), cancelled_at = now()
   WHERE id = p_handover_id;

  IF v_h.status = 'CONFIRMED' THEN
    -- Phiếu chuyển LẺ (mới) → CANCELLED + ẩn 2 phiếu tổng (số dư 2 sổ tự hồi)
    UPDATE income_expenses SET approval_status = 'CANCELLED'
     WHERE handover_transfer_id = p_handover_id;
    UPDATE income_expense_batches SET deleted_at = now()
     WHERE id IN (v_h.transfer_expense_batch_id, v_h.transfer_income_batch_id)
       AND deleted_at IS NULL;
    -- Cặp phiếu LEGACY (phiên cũ) → CANCELLED
    UPDATE income_expenses SET approval_status = 'CANCELLED'
     WHERE id IN (v_h.transfer_expense_id, v_h.transfer_income_id);
  END IF;

  -- Nhả phiếu gốc để có thể bàn giao lại / hoàn tác
  UPDATE income_expenses SET handover_id = NULL WHERE handover_id = p_handover_id;

  RETURN jsonb_build_object('id', p_handover_id, 'code', v_h.code);
END;
$$;








--
-- Name: confirm_cash_handover(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cash_handover(p_handover_id uuid, p_to_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h         cash_handovers%ROWTYPE;
  v_to        uuid;
  v_net       numeric;
  v_cnt       int;
  v_type_exp  uuid;
  v_type_inc  uuid;
  v_bld_giver uuid;
  v_bld_recv  uuid;
  v_caller    text;
  v_recv      text;
  v_giver     text;
  v_exp       uuid;
  v_inc       uuid;
  v_lines_in  text;
  v_lines_ex  text;
  v_lines     text;
  v_item_desc text;
  v_handover_date date;   -- Đợt 6: ngày MỞ đầu tiên chung cho cả hai chân
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_h FROM cash_handovers WHERE id = p_handover_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên bàn giao'; END IF;
  IF v_h.receiver_id <> auth.uid() THEN
    RAISE EXCEPTION 'Chỉ người nhận mới được xác nhận đã nhận tiền';
  END IF;
  IF v_h.status <> 'PENDING' THEN
    RAISE EXCEPTION 'Phiên % không ở trạng thái chờ nhận', v_h.code;
  END IF;
  IF v_h.cancel_requested_by IS NOT NULL THEN
    RAISE EXCEPTION 'Phiên % đang có yêu cầu hủy — xử lý yêu cầu hủy trước', v_h.code;
  END IF;

  -- Sổ đích: truyền vào (phải của receiver) hoặc fallback sổ "…Thu" của receiver
  IF p_to_account_id IS NOT NULL THEN
    SELECT id INTO v_to FROM accounts
     WHERE id = p_to_account_id AND user_id = auth.uid() AND deleted_at IS NULL;
    IF v_to IS NULL THEN
      RAISE EXCEPTION 'Sổ nhận không hợp lệ (phải là sổ quỹ do bạn sở hữu)';
    END IF;
  ELSE
    SELECT id INTO v_to FROM accounts
     WHERE user_id = auth.uid() AND deleted_at IS NULL AND btrim(name) LIKE '%Thu'
     ORDER BY is_default DESC NULLS LAST, name LIMIT 1;
    IF v_to IS NULL THEN
      RAISE EXCEPTION 'Bạn chưa có sổ quỹ nhận — hãy chọn sổ khi xác nhận';
    END IF;
  END IF;

  -- Re-validate: danh sách phiếu còn nguyên, NET (Σthu − Σchi) khớp snapshot
  SELECT COALESCE(sum(CASE WHEN ie.type = 'INCOME' THEN ie.total_amount
                           ELSE -ie.total_amount END), 0),
         count(*)
    INTO v_net, v_cnt
    FROM cash_handover_items it
    JOIN income_expenses ie ON ie.id = it.voucher_id
   WHERE it.handover_id = p_handover_id
     AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
     AND ie.handover_id = p_handover_id
     AND ie.account_id = v_h.from_account_id;
  IF v_cnt <> v_h.voucher_count OR v_net <> v_h.total_amount THEN
    RAISE EXCEPTION 'Danh sách phiếu của phiên % đã thay đổi — hãy hủy phiên và tạo lại', v_h.code;
  END IF;

  -- Loại thu/chi "bàn giao" (ngoài KQKD) + tòa ảo Chung
  v_type_exp := public._termination_ensure_type(v_h.giver_id, 'expense', 'Bàn giao tiền mặt');
  UPDATE income_expense_types SET is_deposit = FALSE
   WHERE id = v_type_exp AND is_deposit IS DISTINCT FROM FALSE;
  v_type_inc := public._termination_ensure_type(v_h.receiver_id, 'income', 'Nhận bàn giao tiền mặt');
  UPDATE income_expense_types SET is_deposit = FALSE
   WHERE id = v_type_inc AND is_deposit IS DISTINCT FROM FALSE;
  v_bld_giver := public._chung_building(v_h.giver_id);
  v_bld_recv  := public._chung_building(v_h.receiver_id);

  SELECT COALESCE(full_name, '') INTO v_caller FROM profiles WHERE id = auth.uid();
  v_recv  := COALESCE(v_h.receiver_name, '');
  v_giver := COALESCE(v_h.giver_name, '');

  -- ── Nhóm THU: phòng · tòa · tiền · kỳ · HĐ ──
  SELECT string_agg(
           '• ' || COALESCE(NULLIF(btrim(it.room_name), ''), '?')
                || ' · ' || COALESCE(NULLIF(btrim(it.building_name), ''), '?')
                || ' · ' || replace(to_char(it.amount::bigint, 'FM999,999,999'), ',', '.') || 'đ'
                || COALESCE(' · kỳ ' || to_char(to_date(inv.billing_month, 'YYYY-MM'), 'MM/YYYY'), '')
                || COALESCE(' · HĐ ' || NULLIF(btrim(inv.invoice_number), ''), ''),
           E'\n' ORDER BY it.building_name, it.room_name)
    INTO v_lines_in
    FROM cash_handover_items it
    LEFT JOIN income_expenses ie ON ie.id = it.voucher_id
    LEFT JOIN invoices inv ON inv.id = ie.invoice_id
   WHERE it.handover_id = p_handover_id AND it.voucher_type = 'INCOME';

  -- ── Nhóm CHI: tên khoản · tiền ──
  SELECT string_agg(
           '• ' || COALESCE(NULLIF(btrim(ie.name), ''), 'Khoản chi')
                || ' · ' || replace(to_char(it.amount::bigint, 'FM999,999,999'), ',', '.') || 'đ',
           E'\n' ORDER BY it.amount DESC)
    INTO v_lines_ex
    FROM cash_handover_items it
    LEFT JOIN income_expenses ie ON ie.id = it.voucher_id
   WHERE it.handover_id = p_handover_id AND it.voucher_type = 'EXPENSE';

  v_lines := 'Đã thu (' || replace(to_char(v_h.gross_amount::bigint, 'FM999,999,999'), ',', '.') || 'đ):'
             || E'\n' || COALESCE(v_lines_in, '—')
             || CASE WHEN v_h.expense_amount > 0
                  THEN E'\n' || 'Đã chi (' || replace(to_char(v_h.expense_amount::bigint, 'FM999,999,999'), ',', '.') || 'đ):'
                       || E'\n' || COALESCE(v_lines_ex, '—')
                  ELSE '' END;

  v_item_desc := 'Bàn giao số dư: thu '
                 || replace(to_char(v_h.gross_amount::bigint, 'FM999,999,999'), ',', '.') || 'đ'
                 || CASE WHEN v_h.expense_amount > 0
                      THEN ' − chi ' || replace(to_char(v_h.expense_amount::bigint, 'FM999,999,999'), ',', '.') || 'đ'
                      ELSE '' END;

  -- Đợt 6: kỳ đã chốt thì cặp phiếu bàn giao rơi vào ngày MỞ đầu tiên.
  -- MỘT ngày chung cho cả hai chân, nếu không sẽ có cửa sổ "tiền trên đường".
  v_handover_date := GREATEST(
    public.org_today_v1(NULL),
    app_private.cashbook_closed_through_v1(v_h.from_account_id) + 1,
    app_private.cashbook_closed_through_v1(v_to) + 1);
  IF v_handover_date > public.org_today_v1(NULL) + 31 THEN
    RAISE EXCEPTION '[CASHBOOK_CLOSED] Sổ quỹ đã chốt tới % — phiên bàn giao này phải xử lý tay, hệ thống không lập phiếu ở ngày quá xa.',
      v_handover_date - 1 USING ERRCODE = 'P0001';
  END IF;

  -- ── 1 phiếu CHI tổng (sổ người giao) = NET ──
  INSERT INTO income_expenses
    (user_id, type, name, building_id, account_id, voucher_date,
     total_amount, approval_status, business_result_accounting, notes, creator_name)
  VALUES
    (v_h.giver_id, 'EXPENSE',
     'Bàn giao tiền mặt → ' || v_recv || ' — ' || v_h.code,
     v_bld_giver, v_h.from_account_id, v_handover_date,
     v_h.total_amount, 'APPROVED', FALSE,
     '[BÀN GIAO] Nộp tiền sang sổ ' || v_recv || ' (phiên ' || v_h.code || '):' || E'\n' || v_lines,
     v_caller)
  RETURNING id INTO v_exp;

  -- ── 1 phiếu THU tổng (sổ người nhận) = NET ──
  INSERT INTO income_expenses
    (user_id, type, name, building_id, account_id, voucher_date,
     total_amount, approval_status, business_result_accounting, notes, creator_name)
  VALUES
    (v_h.receiver_id, 'INCOME',
     'Nhận bàn giao tiền mặt ← ' || v_giver || ' — ' || v_h.code,
     v_bld_recv, v_to, v_handover_date,
     v_h.total_amount, 'APPROVED', FALSE,
     '[BÀN GIAO] Nhận tiền từ ' || v_giver || ' (phiên ' || v_h.code || '):' || E'\n' || v_lines,
     v_caller)
  RETURNING id INTO v_inc;

  -- ── 1 hạng mục GỘP = net trên mỗi phiếu (auto_recalc giữ total = net) ──
  INSERT INTO income_expense_items
    (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
  VALUES (v_exp, v_type_exp, v_item_desc, 1, v_h.total_amount, NULL, NULL);
  INSERT INTO income_expense_items
    (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
  VALUES (v_inc, v_type_inc, v_item_desc, 1, v_h.total_amount, NULL, NULL);

  -- Khoá cặp phiếu chuyển bằng handover_transfer_id (SAU khi nạp hạng mục)
  UPDATE income_expenses
     SET handover_transfer_id = p_handover_id
   WHERE id IN (v_exp, v_inc);

  UPDATE cash_handovers
     SET status = 'CONFIRMED', to_account_id = v_to, confirmed_at = now()
   WHERE id = p_handover_id;

  RETURN jsonb_build_object('id', p_handover_id, 'code', v_h.code,
                            'total_amount', v_h.total_amount, 'to_account_id', v_to,
                            'voucher_count', v_h.voucher_count);
END;
$$;








--
-- Name: confirm_cashbook_closing_v1(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cashbook_closing_v1(p_request uuid, p_counted_balance numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  r app_private.cashbook_closure_requests%ROWTYPE;
  v_membership uuid;
  v_system numeric;
  v_blockers text;
  v_closure bigint;
  v_after numeric;
  v_diff numeric;
  v_type uuid;
  v_bld uuid;
  v_adj uuid;
  -- WP2_PROXY_SIGNATURE
  v_on_behalf boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;

  SELECT * INTO r FROM app_private.cashbook_closure_requests
   WHERE id = p_request FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy đề nghị' USING ERRCODE = 'P0002'; END IF;
  IF r.status <> 'PENDING' THEN
    RAISE EXCEPTION 'Đề nghị này đã % rồi', lower(r.status) USING ERRCODE = '23505';
  END IF;

  IF v_actor = r.proposed_by THEN
    RAISE EXCEPTION 'Người đề nghị không tự xác nhận được — phải là người nhận bàn giao.'
      USING ERRCODE = '42501';
  END IF;
  IF v_actor <> r.confirmer_user_id AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Đề nghị này được gửi cho người khác xác nhận' USING ERRCODE = '42501';
  END IF;
  -- Tới đây, ký-khác-người-được-chỉ-định chỉ còn một khả năng: super admin.
  v_on_behalf := (v_actor <> r.confirmer_user_id);

  PERFORM 1 FROM public.accounts a WHERE a.id = r.cashbook_id FOR UPDATE;
  PERFORM app_private.lock_org_for_decision_v1(r.organization_id);

  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = r.organization_id AND m.status = 'ACTIVE' LIMIT 1;

  IF NOT public.is_super_admin()
     AND NOT COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
       v_actor, r.organization_id, 'cashbooks.close_confirm', NULL, r.cashbook_id)), false) THEN
    RAISE EXCEPTION 'Không có quyền xác nhận nhận bàn giao' USING ERRCODE = '42501';
  END IF;

  -- Chạy lại blockers, fail cứng. Loại hai mã vô nghĩa ở phía người ký:
  -- CLOSURE_PENDING chính là cái sắp ký; NO_CONFIRMER đếm người KHÁC người đang
  -- hỏi nên người ký duy nhất sẽ tự chặn chính mình.
  SELECT string_agg(b.detail, ' | ') INTO v_blockers
  FROM public.cashbook_closing_blockers_v1(r.cashbook_id) b
  WHERE b.blocking AND b.code NOT IN ('CLOSURE_PENDING', 'NO_CONFIRMER');
  IF v_blockers IS NOT NULL THEN
    RAISE EXCEPTION 'Không xác nhận được, sổ đã đổi kể từ lúc đề nghị: %', v_blockers
      USING ERRCODE = '55000';
  END IF;

  v_system := round(app_private.cashbook_balance_as_of_v1(r.cashbook_id, r.closed_through), 2);
  IF v_system <> r.system_balance THEN
    RAISE EXCEPTION
      'Số dư hệ thống đã đổi từ % thành % kể từ lúc đề nghị — huỷ đề nghị và đếm lại.',
      r.system_balance, v_system USING ERRCODE = '40001';
  END IF;
  IF p_counted_balance IS NULL OR p_counted_balance = 'NaN'::numeric
     OR round(p_counted_balance, 2) <> r.counted_balance THEN
    RAISE EXCEPTION
      'Số tiền bạn đếm (%) khác số người giao khai (%) — hai bên phải đếm lại cùng nhau.',
      round(COALESCE(p_counted_balance, 0), 2), r.counted_balance USING ERRCODE = '22023';
  END IF;

  -- ── PHIẾU CHÊNH LỆCH (plan Đợt 6) ────────────────────────────────
  -- Đếm được nhiều hơn sổ ⇒ THỪA quỹ ⇒ phiếu THU. Ít hơn ⇒ THIẾU ⇒ phiếu CHI.
  -- Ngoài KQKD để không đụng vào số đã chia cho cổ đông.
  -- Lập TRƯỚC khi ghi biên bản: lúc này kỳ chưa đóng nên trigger khoá cho qua.
  v_diff := round(r.counted_balance - v_system, 2);
  IF v_diff <> 0 THEN
    SELECT a.quick_default_building_id INTO v_bld FROM public.accounts a WHERE a.id = r.cashbook_id;
    IF v_bld IS NULL THEN
      SELECT b.id INTO v_bld FROM public.buildings b
       WHERE b.organization_id = r.organization_id AND b.deleted_at IS NULL
       ORDER BY b.created_at LIMIT 1;
    END IF;
    IF v_bld IS NULL THEN
      RAISE EXCEPTION 'Không tìm được toà để ghi phiếu chênh lệch — không chốt được sổ lệch.'
        USING ERRCODE = '55000';
    END IF;

    v_type := app_private.ensure_cash_diff_type_v1(
      r.organization_id, CASE WHEN v_diff > 0 THEN 'income' ELSE 'expense' END);

    INSERT INTO public.income_expenses
      (user_id, organization_id, type, name, building_id, account_id, voucher_date,
       total_amount, approval_status, approved_by, approved_at,
       business_result_accounting, creator_name, system_source, notes)
    VALUES
      (v_actor, r.organization_id,
       CASE WHEN v_diff > 0 THEN 'INCOME' ELSE 'EXPENSE' END,
       CASE WHEN v_diff > 0 THEN 'Thừa quỹ khi chốt sổ' ELSE 'Thiếu quỹ khi chốt sổ' END,
       v_bld, r.cashbook_id, r.closed_through, abs(v_diff), 'APPROVED', v_actor, clock_timestamp(),
       false, 'Chốt sổ & bàn giao quỹ', 'cashbook.closing.diff',
       'Chênh lệch kiểm quỹ khi chốt & bàn giao (đếm ' || r.counted_balance ||
       ' / sổ ' || v_system || ').')
    RETURNING id INTO v_adj;

    INSERT INTO public.income_expense_items
      (income_expense_id, organization_id, income_expense_type_id, description,
       quantity, unit_price, amount, start_date, end_date)
    VALUES (v_adj, r.organization_id, v_type,
            CASE WHEN v_diff > 0 THEN 'Thừa quỹ khi chốt sổ' ELSE 'Thiếu quỹ khi chốt sổ' END,
            1, abs(v_diff), abs(v_diff), r.closed_through, r.closed_through);
  END IF;

  -- HẬU ĐIỀU KIỆN: số dư as-of PHẢI đúng bằng số hai bên đã đếm và ký.
  v_after := round(app_private.cashbook_balance_as_of_v1(r.cashbook_id, r.closed_through), 2);
  IF v_after <> r.counted_balance THEN
    RAISE EXCEPTION
      'Sau khi lập phiếu chênh lệch, số dư sổ (%) vẫn khác số đã đếm (%) — DỪNG, không đóng băng con số sai.',
      v_after, r.counted_balance USING ERRCODE = '55000';
  END IF;

  INSERT INTO app_private.cashbook_closures
    (organization_id, cashbook_id, closed_through, counted_balance, system_balance,
     basis, proposed_by, confirmed_by,
     signed_by_super_admin, designated_confirmer, signer_note)
  VALUES
    (r.organization_id, r.cashbook_id, r.closed_through, r.counted_balance, v_system,
     r.basis, r.proposed_by, v_actor,
     v_on_behalf, r.confirmer_user_id,
     CASE WHEN v_on_behalf THEN format(
       'KÝ THAY BỞI SUPER ADMIN — người được chỉ định nhận bàn giao (%s) KHÔNG ký biên bản này.',
       r.confirmer_user_id) END)
  RETURNING id INTO v_closure;

  UPDATE app_private.cashbook_closure_requests
     SET status = 'CONFIRMED', confirmed_by = v_actor, confirmed_at = now(),
         closure_id = v_closure
   WHERE id = p_request;

  IF app_private.cashbook_closed_through_v1(r.cashbook_id) IS DISTINCT FROM r.closed_through
     AND app_private.cashbook_closed_through_v1(r.cashbook_id) < r.closed_through THEN
    RAISE EXCEPTION 'Ghi biên bản xong nhưng kỳ chưa đóng — dừng lại' USING ERRCODE = '55000';
  END IF;

  UPDATE public.accounts
     SET lock_date = GREATEST(COALESCE(lock_date, r.closed_through), r.closed_through)
   WHERE id = r.cashbook_id;

  RETURN jsonb_build_object(
    'request_id', p_request,
    'closure_id', v_closure,
    'cashbook_id', r.cashbook_id,
    'closed_through', r.closed_through,
    'counted_balance', r.counted_balance,
    'system_balance', v_system,
    'difference', v_diff,
    'difference_voucher_id', v_adj,
    'basis', r.basis,
    'signed_by_super_admin', v_on_behalf,
    'designated_confirmer', r.confirmer_user_id,
    'status', 'CONFIRMED'
  );
END
$$;








--
-- Name: confirm_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_reconciliation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_r cashbook_reconciliations%ROWTYPE; v_owner uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_r FROM cashbook_reconciliations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy bản đối soát'; END IF;
  IF v_r.status <> 'PENDING' THEN RAISE EXCEPTION 'Bản đối soát không ở trạng thái chờ'; END IF;
  SELECT user_id INTO v_owner FROM accounts WHERE id = v_r.account_id;
  IF NOT (auth.uid() = v_r.counterparty_id OR auth.uid() = v_owner OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Chỉ người đối ứng hoặc chủ sổ mới xác nhận được';
  END IF;
  UPDATE cashbook_reconciliations
     SET status='CONFIRMED', confirmed_by=auth.uid(), confirmed_at=now()
   WHERE id = p_id;
  RETURN jsonb_build_object('id', p_id, 'status', 'CONFIRMED');
END;
$$;








--
-- Name: contract_deposit_paid_derived(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_deposit_paid_derived(p_contract_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(
           COALESCE(SUM(
             CASE WHEN voucher.type = 'EXPENSE' THEN -1 ELSE 1 END
             * COALESCE(item.amount, item.unit_price * item.quantity)
           ) FILTER (
             WHERE voucher.approval_status = 'APPROVED'
               AND voucher.deleted_at IS NULL
           ), 0),
           0
         )::numeric(15,2)
    FROM public.income_expenses voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
     AND item.accounting_class = 'DEPOSIT'
    LEFT JOIN public.contract_deposit_links link_row
      ON link_row.income_expense_id = voucher.id
     AND link_row.contract_id = p_contract_id
   WHERE p_contract_id IS NOT NULL
     AND (voucher.contract_id = p_contract_id OR link_row.id IS NOT NULL);
$$;








--
-- Name: FUNCTION contract_deposit_paid_derived(p_contract_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_deposit_paid_derived(p_contract_id uuid) IS 'Số "Cọc đã thu" DẪN XUẤT của hợp đồng: tổng item accounting_class=DEPOSIT trên
các phiếu ĐÃ DUYỆT gắn hợp đồng (trực tiếp hoặc qua contract_deposit_links), THU
cộng / CHI trừ, chặn dưới 0. Nguồn sự thật dùng chung cho
recompute_contract_deposit_paid (ghi cột) và hậu kiểm của create_income_expense_v1.';








--
-- Name: create_cash_handover(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cash_handover(p_receiver_id uuid, p_voucher_ids uuid[], p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_ids         uuid[];
  v_cnt         int;
  v_from_acc    uuid;
  v_acc_owner   uuid;
  v_gross       numeric;
  v_expense     numeric;
  v_net         numeric;
  v_recv_name   text;
  v_recv_active boolean;
  v_giver_name  text;
  v_month       text;
  v_seq         int;
  v_code        text;
  v_id          uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_receiver_id IS NULL OR p_receiver_id = auth.uid() THEN
    RAISE EXCEPTION 'Người nhận không hợp lệ (không thể tự bàn giao cho chính mình)';
  END IF;

  SELECT full_name, is_active INTO v_recv_name, v_recv_active
    FROM profiles WHERE id = p_receiver_id;
  IF NOT FOUND OR v_recv_active IS FALSE THEN
    RAISE EXCEPTION 'Người nhận không tồn tại hoặc đã bị khoá';
  END IF;

  -- Cho bàn giao trong đội HOẶC nộp cho CHỦ (super admin) — quản lý nộp cho chủ
  -- dù không cùng đội.
  IF NOT (public.is_super_admin()
          OR public.same_team(p_receiver_id)
          OR EXISTS (SELECT 1 FROM public.super_admins sa WHERE sa.user_id = p_receiver_id)) THEN
    RAISE EXCEPTION 'Người nhận không cùng đội với bạn';
  END IF;

  v_ids := ARRAY(SELECT DISTINCT unnest(p_voucher_ids));
  IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Chưa chọn phiếu nào để bàn giao';
  END IF;

  -- Khoá các phiếu chống race 2 phiên cùng lúc
  PERFORM 1 FROM income_expenses WHERE id = ANY(v_ids) FOR UPDATE;

  -- Hợp lệ: phiếu THU hoặc CHI đã duyệt, chưa bàn giao, có sổ.
  -- Loại phiếu CHI chuyển (handover_transfer_id IS NOT NULL, type=EXPENSE) — đó
  -- là phiếu "Bàn giao tiền mặt →" do confirm sinh ra, KHÔNG được quét lại (sẽ
  -- trừ trùng). Phiếu THU chuyển ("Nhận bàn giao") VẪN cho quét để bàn giao tiếp.
  SELECT count(*) INTO v_cnt
    FROM income_expenses
   WHERE id = ANY(v_ids)
     AND type IN ('INCOME', 'EXPENSE') AND approval_status = 'APPROVED'
     AND deleted_at IS NULL AND handover_id IS NULL AND account_id IS NOT NULL
     AND (handover_transfer_id IS NULL OR type = 'INCOME');
  IF v_cnt <> array_length(v_ids, 1) THEN
    RAISE EXCEPTION 'Có phiếu không hợp lệ (đã xoá / đã nằm trong phiên bàn giao khác / chưa duyệt)';
  END IF;

  SELECT count(DISTINCT account_id) INTO v_cnt FROM income_expenses WHERE id = ANY(v_ids);
  IF v_cnt <> 1 THEN
    RAISE EXCEPTION 'Các phiếu bàn giao phải cùng MỘT sổ quỹ';
  END IF;

  SELECT account_id,
         COALESCE(sum(total_amount) FILTER (WHERE type = 'INCOME'), 0),
         COALESCE(sum(total_amount) FILTER (WHERE type = 'EXPENSE'), 0)
    INTO v_from_acc, v_gross, v_expense
    FROM income_expenses WHERE id = ANY(v_ids) GROUP BY account_id;
  v_net := v_gross - v_expense;
  IF v_net < 0 THEN
    RAISE EXCEPTION 'Phần đã chi lớn hơn phần đã thu — không thể bàn giao số âm. Thêm phiếu thu hoặc bớt phiếu chi.';
  END IF;

  SELECT user_id INTO v_acc_owner FROM accounts
   WHERE id = v_from_acc AND deleted_at IS NULL;
  IF v_acc_owner IS NULL OR v_acc_owner <> auth.uid() THEN
    RAISE EXCEPTION 'Chỉ bàn giao được phiếu nằm trong sổ quỹ do chính bạn sở hữu';
  END IF;

  SELECT COALESCE(full_name, '') INTO v_giver_name FROM profiles WHERE id = auth.uid();

  -- Mã BG{YYMM}{seq3} — advisory lock chống trùng khi 2 phiên tạo song song
  PERFORM pg_advisory_xact_lock(hashtext('cash_handover_code'));
  v_month := to_char(public.org_today_v1(NULL), 'YYMM');
  SELECT COALESCE(MAX(
           CASE WHEN code ~ ('^BG' || v_month || '\d+$')
                THEN substring(code FROM 7)::int ELSE 0 END
         ), 0) + 1
    INTO v_seq
    FROM cash_handovers WHERE code LIKE 'BG' || v_month || '%';
  v_code := 'BG' || v_month || lpad(v_seq::text, 3, '0');

  INSERT INTO cash_handovers
    (code, giver_id, receiver_id, giver_name, receiver_name, from_account_id,
     total_amount, gross_amount, expense_amount, voucher_count, note)
  VALUES
    (v_code, auth.uid(), p_receiver_id, v_giver_name, v_recv_name, v_from_acc,
     v_net, v_gross, v_expense, array_length(v_ids, 1), NULLIF(btrim(p_note), ''))
  RETURNING id INTO v_id;

  INSERT INTO cash_handover_items
    (handover_id, voucher_id, amount, voucher_code, voucher_date, room_name, building_name, voucher_type)
  SELECT v_id, ie.id, ie.total_amount, ie.code, ie.voucher_date, r.name, b.name, ie.type
    FROM income_expenses ie
    LEFT JOIN rooms r     ON r.id = ie.room_id
    LEFT JOIN buildings b ON b.id = ie.building_id
   WHERE ie.id = ANY(v_ids);

  UPDATE income_expenses SET handover_id = v_id WHERE id = ANY(v_ids);

  RETURN jsonb_build_object(
    'id', v_id, 'code', v_code, 'total_amount', v_net,
    'gross_amount', v_gross, 'expense_amount', v_expense,
    'voucher_count', array_length(v_ids, 1));
END;
$_$;








--
-- Name: create_cashbook_v1(text, numeric, date, text, text, uuid, text, text, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cashbook_v1(p_name text, p_initial_amount numeric, p_initial_date date, p_bank_name text, p_account_number text, p_quick_default_building_id uuid, p_idempotency_key text, p_description text DEFAULT NULL::text, p_is_default boolean DEFAULT false, p_owner_user_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid(); v_org uuid; v_authz boolean; v_owner uuid;
  v_key text; v_hash text; v_op app_private.canonical_write_operations%rowtype;
  v_route text; v_id uuid; v_resp json;
  v_memb uuid; v_scope uuid; v_ovr uuid;
  v_org_count int;
  c_op constant text := 'cashbook.create.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if char_length(v_key) < 8 or char_length(v_key) > 200
     or v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if coalesce(length(btrim(p_name)),0)=0 then raise exception 'Tên sổ quỹ trống'; end if;
  if p_initial_amount is null or round(p_initial_amount,2) <> p_initial_amount then
    raise exception 'Số dư đầu không hợp lệ'; end if;
  if p_initial_date is null then raise exception 'Ngày đầu kỳ trống'; end if;

  -- Org của sổ mới — xem đầu file. Không nhánh nào được chọn bừa.
  select count(distinct m.organization_id) into v_org_count
    from public.organization_memberships m
   where m.user_id=v_actor and m.status='ACTIVE';
  if coalesce(v_org_count,0) = 0 then
    raise exception 'Người dùng không thuộc tổ chức nào đang hoạt động' using errcode='42501'; end if;

  if p_organization_id is not null then
    v_org := p_organization_id;
  elsif v_org_count = 1 then
    select distinct m.organization_id into v_org
      from public.organization_memberships m
     where m.user_id=v_actor and m.status='ACTIVE';
  else
    -- Nhiều org: chỉ profiles.organization_id được phá thế hoà, và phải khớp
    -- một membership ACTIVE — profile org sai/mốc thì coi như không có.
    select p.organization_id into v_org
      from public.profiles p
     where p.id=v_actor
       and p.organization_id is not null
       and exists (select 1 from public.organization_memberships m
                    where m.user_id=v_actor and m.status='ACTIVE'
                      and m.organization_id=p.organization_id);
    if v_org is null then
      raise exception 'Bạn thuộc % tổ chức đang hoạt động; phải chỉ rõ tổ chức tạo sổ quỹ (p_organization_id)',
        v_org_count using errcode='42501'; end if;
  end if;

  -- Chốt chặn chung: dù org đến từ nhánh nào, actor phải là member ACTIVE của nó.
  -- Đây là thứ khiến p_organization_id không thành đường ghi chéo tổ chức.
  perform 1 from public.organization_memberships m
   where m.user_id=v_actor and m.organization_id=v_org and m.status='ACTIVE';
  if not found then
    raise exception 'Bạn không thuộc tổ chức được chỉ định' using errcode='42501'; end if;

  -- owner: admin có thể gán người phụ trách khác, phải là member ACTIVE cùng org.
  v_owner := coalesce(p_owner_user_id, v_actor);
  if v_owner <> v_actor then
    perform 1 from public.organization_memberships m
      where m.user_id=v_owner and m.organization_id=v_org and m.status='ACTIVE';
    if not found then raise exception 'Người phụ trách không thuộc tổ chức' using errcode='42501'; end if;
  end if;

  if p_quick_default_building_id is not null then
    perform 1 from public.buildings b where b.id=p_quick_default_building_id
      and b.deleted_at is null and b.organization_id=v_org for share;
    if not found then raise exception 'Toà nhà mặc định không thuộc tổ chức' using errcode='42501'; end if;
  end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'cashbooks.create', null, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền tạo sổ quỹ (cashbooks.create)' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object('name',p_name,'org',v_org,'init',p_initial_amount,'date',p_initial_date,'owner',v_owner)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, v_org::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=v_org::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer sổ quỹ chưa bật' using errcode='55000'; end if;

  -- default duy nhất: nếu tạo sổ default, bỏ default các sổ khác cùng org.
  if coalesce(p_is_default,false) then
    update public.accounts set is_default=false
     where organization_id=v_org and is_default=true and deleted_at is null;
  end if;

  insert into public.accounts
    (user_id, organization_id, name, description, initial_amount, initial_date,
     is_default, is_virtual, bank_name, account_number, quick_default_building_id)
  values (v_owner, v_org, btrim(p_name), nullif(btrim(p_description),''),
          p_initial_amount, p_initial_date, coalesce(p_is_default,false), false,
          nullif(btrim(p_bank_name),''), nullif(btrim(p_account_number),''),
          p_quick_default_building_id)
  returning id into v_id;

  -- t5_20 auto-bind: người phụ trách sổ = CUSTODIAN + edge CASHBOOK (mở khoá
  -- cashbooks.post/điều chỉnh đầu kỳ cho sổ MỚI mà không cần seed tay).
  select m.id into v_memb from public.organization_memberships m
   where m.user_id=v_owner and m.organization_id=v_org and m.status='ACTIVE' limit 1;
  if v_memb is not null then
    insert into public.authorization_scopes (organization_id, scope_type, cashbook_id)
    values (v_org, 'CASHBOOK', v_id) returning id into v_scope;

    select o.id into v_ovr from public.member_permission_overrides o
     where o.organization_id=v_org and o.membership_id=v_memb
       and o.permission_key='cashbooks.post' and o.effect='ALLOW' and o.revoked_at is null
     limit 1;
    if v_ovr is null then
      insert into public.member_permission_overrides
        (organization_id, membership_id, permission_key, effect, scope_mode, reason)
      values (v_org, v_memb, 'cashbooks.post', 'ALLOW', 'SCOPED',
              'auto-bind khi tạo sổ quỹ (người phụ trách)')
      returning id into v_ovr;
    end if;
    insert into public.member_override_scopes (organization_id, override_id, scope_id)
    select v_org, v_ovr, v_scope
     where not exists (select 1 from public.member_override_scopes x
                        where x.organization_id=v_org and x.override_id=v_ovr and x.scope_id=v_scope);

    insert into public.cashbook_possession_bindings
      (organization_id, cashbook_id, membership_id, possession_kind, valid_from, granted_by, reason)
    values (v_org, v_id, v_memb, 'CUSTODIAN', now(), v_actor, 'auto-bind khi tạo sổ quỹ');
  end if;

  v_resp := json_build_object('cashbook_id', v_id);
  update app_private.canonical_write_operations
     set completed_at=now(), subject_id=v_id, response_payload=v_resp::jsonb
   where organization_id=v_org and operation=c_op and subject_scope=v_org::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: create_commission_voucher(uuid, text, numeric, date, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_commission_voucher(p_contract_id uuid, p_kind text, p_amount numeric, p_voucher_date date, p_account_id uuid DEFAULT NULL::uuid, p_payer_name text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_recipient_bank text DEFAULT NULL::text, p_recipient_account text DEFAULT NULL::text, p_item_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_contract record;
  v_existing record;
  v_type_id uuid;
  v_type_name text;
  v_kind_label text;
  v_creator text;
  v_name text;
  v_id uuid;
  v_code text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_kind NOT IN ('broker', 'sale') THEN
    RAISE EXCEPTION 'Loại hoa hồng không hợp lệ: %', COALESCE(p_kind, 'null')
      USING ERRCODE = '23514';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Số tiền hoa hồng phải lớn hơn 0'
      USING ERRCODE = '23514';
  END IF;
  IF p_voucher_date IS NULL THEN
    RAISE EXCEPTION 'Thiếu ngày chi' USING ERRCODE = '23502';
  END IF;

  SELECT
    contract_row.id,
    contract_row.contract_number,
    room_row.id AS room_id,
    building_row.id AS building_id,
    building_row.user_id AS owner_id,
    COALESCE(contract_row.organization_id, building_row.organization_id)
      AS organization_id
  INTO v_contract
  FROM public.contracts contract_row
  JOIN public.rooms room_row ON room_row.id = contract_row.room_id
  JOIN public.buildings building_row ON building_row.id = room_row.building_id
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy hợp đồng' USING ERRCODE = 'P0002';
  END IF;
  IF v_contract.organization_id IS NULL THEN
    RAISE EXCEPTION 'Hợp đồng chưa thuộc tổ chức'
      USING ERRCODE = '23514';
  END IF;

  IF NOT (
    public.can_access_building(v_contract.building_id)
    OR public.ie_all_buildings_scope(v_contract.building_id)
    OR v_contract.owner_id = v_uid
    OR public.is_admin()
    OR public.is_super_admin()
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền chi hoa hồng cho tòa nhà này'
      USING ERRCODE = '42501';
  END IF;

  v_kind_label := CASE p_kind
    WHEN 'broker' THEN 'hoa hồng môi giới'
    ELSE 'thưởng nóng Sale'
  END;

  PERFORM pg_advisory_xact_lock(
    hashtext('commission:' || p_contract_id::text || ':' || p_kind)
  );

  SELECT voucher.code
    INTO v_existing
  FROM public.income_expenses voucher
  WHERE voucher.contract_id = p_contract_id
    AND voucher.commission_kind = p_kind
    AND voucher.deleted_at IS NULL
    AND voucher.approval_status <> 'CANCELLED'
  ORDER BY voucher.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'HĐ % đã có phiếu % (mã %). Mỗi hợp đồng chỉ chi 1 lần — không thể tạo thêm. Nếu phiếu cũ sai, hãy hủy phiếu đó trước.',
      COALESCE(v_contract.contract_number, ''),
      v_kind_label,
      v_existing.code
      USING ERRCODE = 'P0001';
  END IF;

  -- SALE_BONUS_SEES_DEPOSIT_CLAIM: phiếu thưởng Sale có thể đã sinh từ PHIẾU CỌC lúc
  -- hợp đồng chưa tồn tại. Phiếu đó contract_id NULL nên VÔ HÌNH với cả
  -- advisory lock, pre-check P0001 lẫn unique index ở trên. Không có chốt
  -- này thì mở luồng "thưởng từ phiếu cọc" là mở toang khoá chống chi trùng.
  IF p_kind = 'sale' THEN
    DECLARE v_prev uuid; v_prev_code text;
    BEGIN
      SELECT bon.id, bon.code INTO v_prev, v_prev_code
        FROM app_private.sale_bonus_claims sbc
        JOIN public.income_expenses dep ON dep.id = sbc.deposit_voucher_id
        JOIN public.income_expenses bon ON bon.id = sbc.bonus_voucher_id
       WHERE dep.contract_id = p_contract_id
         AND bon.deleted_at IS NULL
         AND bon.approval_status <> 'CANCELLED'
       LIMIT 1;
      IF v_prev IS NOT NULL THEN
        RAISE EXCEPTION 'Hợp đồng này đã được thưởng Sale từ phiếu cọc rồi (phiếu %)',
          COALESCE(v_prev_code, v_prev::text) USING ERRCODE = 'P0001';
      END IF;
    END;
  END IF;

  v_type_name := CASE p_kind
    WHEN 'broker' THEN 'Hoa hồng môi giới'
    ELSE 'Thưởng nóng Sale'
  END;

  SELECT t.id
    INTO v_type_id
  FROM public.income_expense_types AS t
  WHERE t.organization_id = v_contract.organization_id
    AND lower(btrim(t.type)) = 'expense'
    AND public.normalize_income_expense_type_name(t.name) =
        public.normalize_income_expense_type_name(v_type_name)
  ORDER BY COALESCE(t.is_default, false) DESC, t.created_at, t.id
  LIMIT 1;

  IF v_type_id IS NULL THEN
    v_type_id := app_private.ensure_income_expense_type_v1(
      p_organization_id => v_contract.organization_id,
      p_user_id => v_contract.owner_id,
      p_name => v_type_name,
      p_type => 'expense',
      p_description => CASE p_kind
        WHEN 'broker' THEN 'Tự động tạo khi tạo hợp đồng — % tiền phòng theo bậc tháng cấu hình ở tòa nhà.'
        ELSE 'Thưởng cho Sale khi tạo hợp đồng — số tiền do người dùng nhập.'
      END,
      p_force_approval => true,
      p_system_only => true
    );
  END IF;

  SELECT COALESCE(
           NULLIF(profile.full_name, ''),
           NULLIF(profile.email, ''),
           auth_user.email,
           'Người dùng'
         )
    INTO v_creator
  FROM auth.users auth_user
  LEFT JOIN public.profiles profile ON profile.id = auth_user.id
  WHERE auth_user.id = v_uid;

  v_name := btrim(
    CASE p_kind
      WHEN 'broker' THEN 'Hoa hồng môi giới HĐ '
      ELSE 'Thưởng nóng Sale HĐ '
    END || COALESCE(v_contract.contract_number, '')
  );

  INSERT INTO public.income_expenses (
    user_id,
    organization_id,
    creator_name,
    type,
    approval_status,
    name,
    building_id,
    room_id,
    tenant_id,
    contract_id,
    voucher_date,
    account_id,
    payer_name,
    receive_bank_name,
    receive_bank_account,
    notes,
    attachments,
    business_result_accounting,
    repeat_cycle,
    repeat_infinity,
    repeat_count,
    repeat_remaining,
    commission_kind,
    system_source
  ) VALUES (
    v_uid,
    v_contract.organization_id,
    v_creator,
    'EXPENSE',
    'UNAPPROVED',
    v_name,
    v_contract.building_id,
    v_contract.room_id,
    NULL,
    p_contract_id,
    p_voucher_date,
    p_account_id,
    p_payer_name,
    p_recipient_bank,
    p_recipient_account,
    CASE
      WHEN COALESCE(p_recipient_name, '') <> ''
        THEN 'Người nhận: ' || p_recipient_name
      ELSE NULL
    END,
    '[]'::jsonb,
    NULL,
    'NONE',
    false,
    0,
    0,
    p_kind,
    'contract.commission'
  )
  RETURNING id, code INTO v_id, v_code;

  INSERT INTO public.income_expense_items (
    income_expense_id,
    income_expense_type_id,
    organization_id,
    description,
    quantity,
    unit_price,
    start_date,
    end_date
  ) VALUES (
    v_id,
    v_type_id,
    v_contract.organization_id,
    COALESCE(NULLIF(p_item_description, ''), v_name),
    1,
    p_amount,
    p_voucher_date,
    p_voucher_date
  );

  -- COMMISSION_AUTOPAY_V1: hoa hồng môi giới đủ bốn điều kiện chủ chốt 31/07 thì
  -- máy duyệt hộ và ghi sổ luôn. Thiếu một điều ⇒ để nguyên chờ duyệt (hành
  -- vi cũ). Bảng bậc rỗng ⇒ luôn rơi vào NO_TIER ⇒ không phiếu nào tự duyệt.
  IF p_kind = 'broker' AND v_id IS NOT NULL THEN
    DECLARE v_chk jsonb; v_acc_ok boolean;
    BEGIN
      v_chk := app_private.commission_autopay_check_v1(p_contract_id, p_amount);
      SELECT (a.id IS NOT NULL AND NOT COALESCE(a.is_virtual,false)) INTO v_acc_ok
        FROM public.accounts a
       WHERE a.id = (SELECT account_id FROM public.income_expenses WHERE id = v_id);
      IF (v_chk->>'verdict') = 'VALID' AND COALESCE(v_acc_ok,false) THEN
        PERFORM app_private.special_fee_approve_and_post_v1(v_id, 'BROKER_COMMISSION');
      END IF;
    END;
  END IF;

  RETURN jsonb_build_object('id', v_id, 'code', v_code);
END
$$;








--
-- Name: create_contract_v1(uuid, uuid[], date, date, date, numeric, numeric, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_contract_v1(p_room_id uuid, p_customer_ids uuid[], p_signed_date date, p_start_date date, p_end_date date, p_rent_price numeric, p_total_deposit numeric, p_services jsonb, p_first_invoice jsonb, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_building uuid;
  v_authz boolean; v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype; v_route text;
  v_contract uuid; v_cust uuid; v_svc jsonb; v_inv json := null;
  v_resp json;
  c_op constant text := 'contract.create.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_start_date is null or p_end_date is null or p_start_date > p_end_date then
    raise exception 'Ngày hợp đồng không hợp lệ'; end if;
  if p_rent_price is null or p_rent_price < 0 then raise exception 'Giá thuê không hợp lệ'; end if;
  if p_customer_ids is null or array_length(p_customer_ids,1) is null then
    raise exception 'Cần ít nhất một khách hàng'; end if;

  -- room → building → org; room locked FOR NO KEY UPDATE.
  select r.building_id into v_building from public.rooms r
   where r.id=p_room_id and r.deleted_at is null for no key update;
  if not found then raise exception 'Không tìm thấy phòng' using errcode='42501'; end if;
  select b.organization_id into v_org from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.id=v_building and b.deleted_at is null for share of o,b;
  if v_org is null then raise exception 'Toà nhà không thuộc tổ chức đang hoạt động' using errcode='42501'; end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'contracts.create', v_building, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền tạo hợp đồng (contracts.create)' using errcode='42501'; end if;

  -- validate customers same-org.
  foreach v_cust in array p_customer_ids loop
    perform 1 from public.customers cu where cu.id=v_cust
      and (cu.organization_id is null or cu.organization_id=v_org) for share;
    if not found then raise exception 'Khách hàng không thuộc tổ chức' using errcode='42501'; end if;
  end loop;

  v_hash := md5(jsonb_build_object('room',p_room_id,'org',v_org,'start',p_start_date,
    'rent',p_rent_price)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_room_id::text || '|' || p_start_date::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op
     and o.subject_scope=p_room_id::text || '|' || p_start_date::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  -- idempotency replay BEFORE the business guard, so a legitimate retry returns
  -- the original contract instead of tripping "room already has a contract".
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  -- guard: room must not already be OCCUPIED by an ACTIVE contract (a NEW claim).
  if exists (select 1 from public.contracts c
             where c.room_id=p_room_id and c.deleted_at is null and c.status='ACTIVE') then
    raise exception 'Phòng đã có hợp đồng đang hiệu lực' using errcode='55000'; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer hợp đồng chưa bật' using errcode='55000'; end if;

  -- create the contract (org auto-fills via trigger; public_code auto).
  insert into public.contracts
    (user_id, organization_id, room_id, signed_date, start_date, end_date,
     rent_price, total_deposit, status)
  values (v_actor, v_org, p_room_id, coalesce(p_signed_date,p_start_date),
          p_start_date, p_end_date, p_rent_price, coalesce(p_total_deposit,0), 'ACTIVE')
  returning id into v_contract;

  foreach v_cust in array p_customer_ids loop
    insert into public.contract_customers (contract_id, customer_id)
    values (v_contract, v_cust) on conflict do nothing;
  end loop;

  if p_services is not null and jsonb_typeof(p_services)='array' then
    for v_svc in select value from jsonb_array_elements(p_services) loop
      insert into public.contract_services (contract_id, service_id, unit_price)
      values (v_contract, (v_svc->>'service_id')::uuid, coalesce((v_svc->>'unit_price')::numeric,0));
    end loop;
  end if;

  -- optional first invoice via the canonical invoice writer (reuse t5_02).
  if p_first_invoice is not null then
    v_inv := public.create_invoice_v1(
      v_contract, v_building, p_room_id,
      p_first_invoice->>'billing_month',
      coalesce(nullif(p_first_invoice->>'issue_date','')::date, public.org_today_v1(NULL)),
      coalesce(nullif(p_first_invoice->>'due_date','')::date, public.org_today_v1(NULL) + 15),
      'MONTHLY',
      coalesce((p_first_invoice->>'subtotal')::numeric,0), 0,
      coalesce((p_first_invoice->>'total_amount')::numeric,0), 0,
      coalesce(p_first_invoice->'items','[]'::jsonb),
      v_key || '-inv');
  end if;

  -- consume any live 24h hold on the room (link it to the contract).
  update public.room_reservation_holds
     set status='APPROVED', contract_id=v_contract
   where room_id=p_room_id and status='PENDING_APPROVAL';

  -- room OCCUPIED as the LAST mutation (dominates recompute_room_reservation).
  update public.rooms set status='OCCUPIED' where id=p_room_id;

  v_resp := json_build_object('contract_id', v_contract, 'first_invoice', v_inv);
  update app_private.canonical_write_operations
     set subject_id=v_contract, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op
     and subject_scope=p_room_id::text || '|' || p_start_date::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: create_contract_v2(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_contract_v2(p_payload jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_json jsonb := COALESCE(p_payload->'contract', '{}'::jsonb);
  v_customers jsonb := COALESCE(p_payload->'customers', '[]'::jsonb);
  v_services jsonb := COALESCE(p_payload->'services', '[]'::jsonb);
  v_receipts jsonb := COALESCE(p_payload->'deposit_receipts', '[]'::jsonb);
  v_existing_deposits jsonb := COALESCE(p_payload->'existing_deposit_voucher_ids', '[]'::jsonb);
  v_first_invoice jsonb := p_payload->'first_invoice';
  v_room_id uuid;
  v_building_id uuid;
  v_org uuid;
  v_owner uuid;
  v_authz boolean;
  v_route text;
  v_payload_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_contract_id uuid;
  v_invoice_id uuid;
  v_customer jsonb;
  v_service jsonb;
  v_receipt jsonb;
  v_item jsonb;
  v_voucher_id uuid;
  v_deposit_type_id uuid;
  v_account_id uuid;
  v_total_deposit numeric;
  v_deposit_paid numeric := 0;
  v_new_deposit_receipts numeric := 0;
  v_deposit_shortfall numeric := 0;
  v_debt_mode text;
  v_debt_reason text;
  v_debt_due date;
  v_start_date date;
  v_end_date date;
  v_signed_date date;
  v_start_billing date;
  v_end_billing date;
  v_billing_month text;
  v_issue_date date;
  v_due_date date;
  v_subtotal numeric := 0;
  v_revenue_subtotal numeric := 0;
  v_deposit_invoice_total numeric := 0;
  v_discount numeric := 0;
  v_revenue_after_discount numeric := 0;
  v_rounded_revenue numeric := 0;
  v_total_amount numeric := 0;
  v_remainder numeric := 0;
  v_rep_count integer;
  v_customer_count integer;
  v_distinct_customer_count integer;
  v_locked_customer_count integer;
  v_deposit_item_count integer := 0;
  v_contract_row jsonb;
  v_invoice_row jsonb := NULL;
  v_response jsonb;
  v_idx integer := 0;
  v_amount numeric;
  v_qty numeric;
  v_unit numeric;
  v_item_from date;
  v_item_to date;
  v_class text;
  v_type text;
  v_service_id uuid;
  v_room_name text;
  v_building_name text;
  v_room_status public.room_status;
  v_contract_template_id uuid;
  v_invoice_template_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_payload) <> 'object'
     OR jsonb_typeof(v_customers) <> 'array'
     OR jsonb_typeof(v_services) <> 'array'
     OR jsonb_typeof(v_receipts) <> 'array'
     OR jsonb_typeof(v_existing_deposits) <> 'array' THEN
    RAISE EXCEPTION 'Payload contract V2 không hợp lệ' USING ERRCODE = '22023';
  END IF;

  v_room_id := NULLIF(v_contract_json->>'room_id', '')::uuid;
  v_start_date := NULLIF(v_contract_json->>'start_date', '')::date;
  v_end_date := NULLIF(v_contract_json->>'end_date', '')::date;
  v_signed_date := COALESCE(NULLIF(v_contract_json->>'signed_date', '')::date, v_start_date);
  v_start_billing := COALESCE(NULLIF(v_contract_json->>'start_billing_date', '')::date, v_start_date);
  v_end_billing := COALESCE(NULLIF(v_contract_json->>'end_billing_date', '')::date, v_start_billing);
  v_total_deposit := COALESCE((v_contract_json->>'total_deposit')::numeric, 0);
  v_debt_mode := NULLIF(v_contract_json->>'deposit_debt_mode', '');
  v_debt_reason := NULLIF(btrim(v_contract_json->>'deposit_debt_reason'), '');
  v_debt_due := NULLIF(v_contract_json->>'deposit_topup_due_date', '')::date;
  v_contract_template_id := NULLIF(v_contract_json->>'contract_template_id', '')::uuid;
  v_invoice_template_id := NULLIF(v_contract_json->>'invoice_template_id', '')::uuid;

  IF v_room_id IS NULL OR v_start_date IS NULL OR v_end_date IS NULL OR v_start_date > v_end_date THEN
    RAISE EXCEPTION 'Phòng hoặc ngày hợp đồng không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF v_start_billing IS NULL OR v_end_billing IS NULL OR v_start_billing > v_end_billing THEN
    RAISE EXCEPTION 'Kỳ tính tiền đầu không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF v_start_billing < v_start_date OR v_end_billing > v_end_date THEN
    RAISE EXCEPTION 'Kỳ tính tiền đầu phải nằm trong thời hạn hợp đồng'
      USING ERRCODE = '22023';
  END IF;
  IF COALESCE((v_contract_json->>'rent_price')::numeric, -1)::text
       IN ('NaN', 'Infinity', '-Infinity')
     OR v_total_deposit::text IN ('NaN', 'Infinity', '-Infinity')
     OR COALESCE((v_contract_json->>'rent_price')::numeric, -1) < 0
     OR v_total_deposit < 0 THEN
    RAISE EXCEPTION 'Giá thuê hoặc tiền cọc không hợp lệ' USING ERRCODE = '22023';
  END IF;

  SELECT room_row.building_id, building_row.organization_id, building_row.user_id,
         room_row.name, building_row.name, room_row.status
    INTO v_building_id, v_org, v_owner, v_room_name, v_building_name, v_room_status
  FROM public.rooms room_row
  JOIN public.buildings building_row ON building_row.id = room_row.building_id
  JOIN public.organizations org_row
    ON org_row.id = building_row.organization_id AND org_row.status = 'ACTIVE'
  WHERE room_row.id = v_room_id
    AND room_row.deleted_at IS NULL
    AND building_row.deleted_at IS NULL
  FOR UPDATE OF room_row;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy phòng trong tổ chức đang hoạt động'
      USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'contracts.create', v_building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Không có quyền tạo hợp đồng' USING ERRCODE = '42501';
  END IF;

  v_payload_hash := md5(jsonb_build_object('organization_id', v_org, 'payload', p_payload)::text);
  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash
  ) VALUES (
    v_org, 'contract.create.v2', v_room_id::text || '|' || v_start_date::text,
    v_actor, v_key, v_payload_hash
  )
  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
  DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'contract.create.v2'
    AND operation_row.subject_scope = v_room_id::text || '|' || v_start_date::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_payload_hash THEN
    RAISE EXCEPTION 'idempotency_key đã dùng với nội dung khác' USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  IF v_room_status NOT IN ('AVAILABLE', 'RESERVED') THEN
    RAISE EXCEPTION 'Trạng thái phòng không cho phép tạo hợp đồng: %', v_room_status
      USING ERRCODE = '55000';
  END IF;

  v_route := app_private.evaluate_feature_route('contract.create.v2', v_org);
  IF v_route = 'FROZEN' THEN
    RAISE EXCEPTION 'Writer contract.create.v2 đang bị đóng băng'
      USING ERRCODE = '55000';
  ELSIF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Writer contract.create.v2 chưa bật' USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.contracts contract_row
    WHERE contract_row.room_id = v_room_id
      AND contract_row.deleted_at IS NULL
      AND contract_row.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Phòng đã có hợp đồng đang hiệu lực' USING ERRCODE = '23505';
  END IF;

  UPDATE public.room_reservation_holds
     SET status = 'EXPIRED'
   WHERE room_id = v_room_id
     AND status = 'PENDING_APPROVAL'
     AND expires_at <= clock_timestamp();

  IF EXISTS (
    SELECT 1 FROM public.room_reservation_holds hold_row
    WHERE hold_row.room_id = v_room_id
      AND hold_row.status = 'PENDING_APPROVAL'
      AND hold_row.expires_at > clock_timestamp()
      AND hold_row.held_by <> v_actor
  ) THEN
    RAISE EXCEPTION 'Phòng đang được người khác giữ chỗ' USING ERRCODE = '55P03';
  END IF;

  SELECT count(*), count(DISTINCT customer_row->>'customer_id'),
         count(*) FILTER (WHERE COALESCE((customer_row->>'is_representative')::boolean, false))
    INTO v_customer_count, v_distinct_customer_count, v_rep_count
  FROM jsonb_array_elements(v_customers) customer_row;

  IF v_customer_count = 0 OR v_customer_count <> v_distinct_customer_count OR v_rep_count <> 1 THEN
    RAISE EXCEPTION 'Hợp đồng cần danh sách khách không trùng và đúng một người đại diện'
      USING ERRCODE = '22023';
  END IF;

  -- Preserve tenant/deletion validation while concurrent contract creates share
  -- customer locks acquired in one deterministic UUID order.
  WITH requested_customers AS MATERIALIZED (
    SELECT (requested.value->>'customer_id')::uuid AS customer_id
    FROM jsonb_array_elements(v_customers) AS requested(value)
  ), locked_customers AS MATERIALIZED (
    SELECT customer_row.id
    FROM public.customers customer_row
    JOIN requested_customers requested
      ON requested.customer_id = customer_row.id
    WHERE customer_row.deleted_at IS NULL
      AND customer_row.organization_id = v_org
    ORDER BY customer_row.id
    FOR SHARE OF customer_row
  )
  SELECT count(*)
    INTO v_locked_customer_count
  FROM locked_customers;

  IF v_locked_customer_count <> v_customer_count THEN
    RAISE EXCEPTION 'Khách hàng không thuộc tổ chức' USING ERRCODE = '42501';
  END IF;

  FOR v_service IN SELECT value FROM jsonb_array_elements(v_services) LOOP
    IF COALESCE((v_service->>'unit_price')::numeric, -1)::text
         IN ('NaN', 'Infinity', '-Infinity')
       OR COALESCE(NULLIF(v_service->>'initial_reading', '')::numeric, 0)::text
         IN ('NaN', 'Infinity', '-Infinity')
       OR COALESCE((v_service->>'unit_price')::numeric, -1) < 0 THEN
      RAISE EXCEPTION 'Đơn giá dịch vụ không hợp lệ' USING ERRCODE = '22023';
    END IF;
    PERFORM 1
    FROM public.services service_row
    WHERE service_row.id = (v_service->>'service_id')::uuid
      AND service_row.organization_id = v_org
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Dịch vụ không thuộc tổ chức' USING ERRCODE = '42501';
    END IF;
  END LOOP;

  IF v_contract_template_id IS NOT NULL THEN
    PERFORM 1 FROM public.document_templates template_row
    WHERE template_row.id = v_contract_template_id
      AND template_row.organization_id = v_org
      AND template_row.category = 'CONTRACT_NEW'
      AND COALESCE(template_row.is_active, true)
      AND template_row.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Mẫu hợp đồng không thuộc tổ chức hoặc không còn hiệu lực'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_invoice_template_id IS NOT NULL THEN
    PERFORM 1 FROM public.document_templates template_row
    WHERE template_row.id = v_invoice_template_id
      AND template_row.organization_id = v_org
      AND template_row.category = 'INVOICE'
      AND COALESCE(template_row.is_active, true)
      AND template_row.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Mẫu hóa đơn không thuộc tổ chức hoặc không còn hiệu lực'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT type_row.id INTO v_deposit_type_id
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'income'
    AND type_row.is_deposit
  ORDER BY CASE WHEN lower(btrim(type_row.name)) = 'tiền cọc' THEN 0 ELSE 1 END,
           type_row.created_at
  LIMIT 1
  FOR SHARE;

  IF (jsonb_array_length(v_receipts) > 0 OR jsonb_array_length(v_existing_deposits) > 0)
     AND v_deposit_type_id IS NULL THEN
    RAISE EXCEPTION 'Tổ chức chưa có loại thu cọc is_deposit' USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('app.contract_create_v2', 'on', true);

  INSERT INTO public.contracts (
    user_id, organization_id, tenant_id, room_id, status,
    signed_date, start_date, end_date, rent_price, payment_cycle,
    total_deposit, deposit_paid, start_billing_date, end_billing_date,
    contract_template_id, invoice_template_id, notes, discounts,
    deposit_debt_acknowledged, deposit_debt_mode, deposit_debt_reason,
    deposit_topup_due_date
  ) VALUES (
    v_owner, v_org, NULL, v_room_id, 'ACTIVE',
    v_signed_date, v_start_date, v_end_date,
    (v_contract_json->>'rent_price')::numeric,
    COALESCE(NULLIF(v_contract_json->>'payment_cycle', '')::public.payment_cycle, 'MONTHLY'),
    v_total_deposit, 0, v_start_billing, v_end_billing,
    v_contract_template_id,
    v_invoice_template_id,
    NULLIF(v_contract_json->>'notes', ''),
    COALESCE(v_contract_json->'discounts', '[]'::jsonb),
    false, NULL, NULL, NULL
  ) RETURNING id INTO v_contract_id;

  FOR v_customer IN SELECT value FROM jsonb_array_elements(v_customers) LOOP
    INSERT INTO public.contract_customers (
      organization_id, contract_id, customer_id, is_representative, notes
    ) VALUES (
      v_org, v_contract_id, (v_customer->>'customer_id')::uuid,
      COALESCE((v_customer->>'is_representative')::boolean, false),
      NULLIF(v_customer->>'notes', '')
    );
  END LOOP;

  FOR v_service IN SELECT value FROM jsonb_array_elements(v_services) LOOP
    INSERT INTO public.contract_services (
      organization_id, contract_id, service_id, unit_price, initial_reading
    ) VALUES (
      v_org, v_contract_id, (v_service->>'service_id')::uuid,
      (v_service->>'unit_price')::numeric,
      NULLIF(v_service->>'initial_reading', '')::numeric
    );
  END LOOP;

  IF jsonb_array_length(v_existing_deposits) <> (
    SELECT count(DISTINCT value #>> '{}') FROM jsonb_array_elements(v_existing_deposits)
  ) THEN
    RAISE EXCEPTION 'Danh sách phiếu cọc có ID trùng' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_existing_deposits) LOOP
    SELECT voucher.id INTO v_voucher_id
    FROM public.income_expenses voucher
    WHERE voucher.id = (v_item #>> '{}')::uuid
      AND voucher.organization_id = v_org
      AND voucher.room_id = v_room_id
      AND voucher.contract_id IS NULL
      AND voucher.type = 'INCOME'
      AND voucher.approval_status = 'APPROVED'
      AND voucher.deleted_at IS NULL
      AND EXISTS (
        SELECT 1 FROM public.income_expense_items item
        WHERE item.income_expense_id = voucher.id
          AND item.accounting_class = 'DEPOSIT'
      )
    FOR SHARE;

    IF v_voucher_id IS NULL THEN
      RAISE EXCEPTION 'Phiếu cọc được chọn không hợp lệ hoặc đã được dùng'
        USING ERRCODE = '55000';
    END IF;

    INSERT INTO public.contract_deposit_links (
      organization_id, contract_id, income_expense_id, link_source, linked_by
    ) VALUES (
      v_org, v_contract_id, v_voucher_id, 'EXPLICIT_V2', v_actor
    );

    -- Keep the legacy lifecycle field in sync so linked reservation deposits
    -- immediately leave orphan/holding-deposit queries as well as the link table.
    PERFORM app_private.begin_ie_flex_write_v1(v_voucher_id, 'LINK_CONTRACT');
    UPDATE public.income_expenses
       SET contract_id = v_contract_id,
           updated_at = now()
     WHERE id = v_voucher_id
       AND contract_id IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Phiếu cọc đã đổi trạng thái trong lúc tạo hợp đồng'
        USING ERRCODE = '40001';
    END IF;
    PERFORM app_private.end_ie_flex_write_v1(v_voucher_id);
    v_voucher_id := NULL;
  END LOOP;

  FOR v_receipt IN SELECT value FROM jsonb_array_elements(v_receipts) LOOP
    v_amount := COALESCE((v_receipt->>'amount')::numeric, 0);
    IF v_amount::text IN ('NaN', 'Infinity', '-Infinity') OR v_amount <= 0 THEN
      RAISE EXCEPTION 'Số tiền cọc phải lớn hơn 0' USING ERRCODE = '22023';
    END IF;
    v_new_deposit_receipts := v_new_deposit_receipts + v_amount;

    v_account_id := NULLIF(v_receipt->>'account_id', '')::uuid;
    IF v_account_id IS NULL THEN
      SELECT account_row.id INTO v_account_id
      FROM public.accounts account_row
      WHERE account_row.organization_id = v_org
        AND account_row.user_id = v_actor
        AND account_row.deleted_at IS NULL
        AND NOT account_row.is_virtual
      ORDER BY account_row.is_default DESC,
               CASE WHEN account_row.name ILIKE '%thu' THEN 0 ELSE 1 END,
               account_row.created_at
      LIMIT 1
      FOR SHARE;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'Chưa chọn sổ quỹ nhận cọc trong tổ chức'
          USING ERRCODE = '22023';
      END IF;
    END IF;
    PERFORM 1 FROM public.accounts account_row
    WHERE account_row.id = v_account_id
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sổ quỹ cọc không thuộc tổ chức' USING ERRCODE = '42501';
    END IF;

    SELECT allowed INTO v_authz
    FROM app_private.authorize_tenant_action_v3(
      v_actor, v_org, 'thu_tien.collect', v_building_id, v_account_id
    );
    IF NOT COALESCE(v_authz, false) THEN
      RAISE EXCEPTION 'Không có quyền ghi tiền cọc vào sổ đã chọn' USING ERRCODE = '42501';
    END IF;

    INSERT INTO public.income_expenses (
      user_id, organization_id, type, name, building_id, room_id, contract_id,
      account_id, voucher_date, total_amount, approval_status, approved_by,
      approved_at, attachments, business_result_accounting, creator_name,
      system_source, idempotency_key
    ) VALUES (
      v_owner, v_org, 'INCOME',
      'Cọc giữ phòng ' || COALESCE(v_room_name, '') || ' ' || COALESCE(v_building_name, ''),
      v_building_id, v_room_id, v_contract_id, v_account_id,
      COALESCE(NULLIF(v_receipt->>'received_date', '')::date, v_signed_date),
      v_amount, 'APPROVED', v_actor, clock_timestamp(),
      COALESCE(v_receipt->'attachments', '[]'::jsonb), NULL,
      COALESCE(NULLIF(v_receipt->>'creator_name', ''), 'Contract V2'),
      'contract.create.v2', v_key || ':deposit:' || v_idx
    ) RETURNING id INTO v_voucher_id;

    INSERT INTO public.income_expense_items (
      income_expense_id, organization_id, income_expense_type_id, description,
      quantity, unit_price, amount, start_date, end_date, accounting_class
    ) VALUES (
      v_voucher_id, v_org, v_deposit_type_id, 'Tiền cọc hợp đồng',
      1, v_amount, v_amount,
      COALESCE(NULLIF(v_receipt->>'received_date', '')::date, v_signed_date),
      COALESCE(NULLIF(v_receipt->>'received_date', '')::date, v_signed_date),
      'DEPOSIT'
    );
    v_idx := v_idx + 1;
  END LOOP;

  PERFORM public.recompute_contract_deposit_paid(v_contract_id);
  SELECT COALESCE(contract_row.deposit_paid, 0)
    INTO v_deposit_paid
  FROM public.contracts contract_row
  WHERE contract_row.id = v_contract_id
  FOR UPDATE;

  v_deposit_shortfall := GREATEST(v_total_deposit - v_deposit_paid, 0);
  IF v_deposit_paid - v_total_deposit >= 0.01 THEN
    RAISE EXCEPTION 'Tiền cọc đã nhận vượt số cọc của hợp đồng'
      USING ERRCODE = '22023';
  END IF;
  IF v_deposit_shortfall >= 0.01 THEN
    IF v_debt_mode NOT IN ('DEBT', 'FIRST_INVOICE') THEN
      RAISE EXCEPTION 'Thiếu cọc: phải chọn DEBT hoặc FIRST_INVOICE'
        USING ERRCODE = '22023';
    END IF;
    IF v_debt_mode = 'DEBT' AND (v_debt_reason IS NULL OR v_debt_due IS NULL) THEN
      RAISE EXCEPTION 'Nợ cọc cần lý do và hạn bổ sung' USING ERRCODE = '22023';
    END IF;
    IF v_debt_mode = 'FIRST_INVOICE' AND v_first_invoice IS NULL THEN
      RAISE EXCEPTION 'FIRST_INVOICE cần hóa đơn đầu' USING ERRCODE = '22023';
    END IF;

    UPDATE public.contracts
       SET deposit_debt_acknowledged = true,
           deposit_debt_mode = v_debt_mode,
           deposit_debt_reason = CASE WHEN v_debt_mode = 'DEBT' THEN v_debt_reason END,
           deposit_topup_due_date = CASE WHEN v_debt_mode = 'DEBT' THEN v_debt_due END
     WHERE id = v_contract_id;
  ELSE
    v_debt_mode := NULL;
  END IF;

  IF v_first_invoice IS NOT NULL THEN
    IF jsonb_typeof(COALESCE(v_first_invoice->'items', '[]'::jsonb)) <> 'array'
       OR jsonb_array_length(COALESCE(v_first_invoice->'items', '[]'::jsonb)) = 0 THEN
      RAISE EXCEPTION 'Hóa đơn đầu cần ít nhất một hạng mục' USING ERRCODE = '22023';
    END IF;

    v_subtotal := 0;
    v_revenue_subtotal := 0;
    v_deposit_invoice_total := 0;
    v_deposit_item_count := 0;

    FOR v_item IN SELECT value FROM jsonb_array_elements(v_first_invoice->'items') LOOP
      v_type := COALESCE(NULLIF(v_item->>'type', ''), 'OTHER');
      v_class := COALESCE(NULLIF(v_item->>'accounting_class', ''), 'REVENUE');
      v_unit := COALESCE((v_item->>'unit_price')::numeric, -1);
      v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
      v_service_id := NULLIF(v_item->>'service_id', '')::uuid;
      v_item_from := NULLIF(v_item->>'from_date', '')::date;
      v_item_to := NULLIF(v_item->>'to_date', '')::date;

      IF v_type NOT IN ('RENT', 'SERVICE', 'PENALTY', 'DISCOUNT', 'OTHER')
         OR v_class NOT IN ('REVENUE', 'DEPOSIT')
         OR v_unit::text IN ('NaN', 'Infinity', '-Infinity')
         OR v_qty::text IN ('NaN', 'Infinity', '-Infinity')
         OR v_unit < 0 OR v_qty <= 0 THEN
        RAISE EXCEPTION 'Hạng mục hóa đơn đầu không hợp lệ' USING ERRCODE = '22023';
      END IF;
      IF (v_item_from IS NULL) <> (v_item_to IS NULL) THEN
        RAISE EXCEPTION 'Kỳ hạng mục hóa đơn phải có đủ từ ngày và đến ngày'
          USING ERRCODE = '22023';
      END IF;
      IF v_item_from IS NOT NULL AND v_item_from > v_item_to THEN
        RAISE EXCEPTION 'Kỳ hạng mục hóa đơn bị đảo ngày' USING ERRCODE = '22023';
      END IF;
      IF v_class = 'REVENUE'
         AND (
           COALESCE(v_item_from, v_start_billing) < v_start_billing
           OR COALESCE(v_item_to, v_end_billing) > v_end_billing
         ) THEN
        RAISE EXCEPTION 'Kỳ hạng mục doanh thu phải nằm trong kỳ tính tiền đầu'
          USING ERRCODE = '22023';
      END IF;
      IF v_class = 'DEPOSIT' AND v_type <> 'OTHER' THEN
        RAISE EXCEPTION 'Hạng mục cọc phải có type OTHER' USING ERRCODE = '22023';
      END IF;
      IF v_service_id IS NOT NULL THEN
        PERFORM 1 FROM public.services service_row
        WHERE service_row.id = v_service_id AND service_row.organization_id = v_org;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'Dịch vụ trong hóa đơn không thuộc tổ chức' USING ERRCODE = '42501';
        END IF;
      END IF;

      v_amount := round(v_unit * v_qty, 2);
      v_subtotal := v_subtotal + v_amount;
      IF v_class = 'DEPOSIT' THEN
        v_deposit_invoice_total := v_deposit_invoice_total + v_amount;
        v_deposit_item_count := v_deposit_item_count + 1;
      ELSE
        v_revenue_subtotal := v_revenue_subtotal + v_amount;
      END IF;
    END LOOP;

    IF v_debt_mode = 'FIRST_INVOICE' THEN
      IF v_deposit_item_count <> 1
         OR abs(v_deposit_invoice_total - v_deposit_shortfall) >= 0.01 THEN
        RAISE EXCEPTION 'Dòng cọc hóa đơn đầu phải đúng bằng phần cọc còn thiếu'
          USING ERRCODE = '22023';
      END IF;
    ELSIF v_deposit_item_count <> 0 THEN
      RAISE EXCEPTION 'Chỉ mode FIRST_INVOICE mới được có dòng cọc'
        USING ERRCODE = '22023';
    END IF;

    v_discount := COALESCE((v_first_invoice->>'discount_amount')::numeric, 0);
    IF v_discount::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_discount < 0 OR v_discount > v_revenue_subtotal THEN
      RAISE EXCEPTION 'Giảm trừ không được vượt phần doanh thu không-cọc'
        USING ERRCODE = '22023';
    END IF;

    v_revenue_after_discount := GREATEST(v_revenue_subtotal - v_discount, 0);
    v_remainder := mod(v_revenue_after_discount, 1000);
    v_rounded_revenue := CASE
      WHEN v_revenue_after_discount <= 0 THEN 0
      WHEN v_remainder >= 900 THEN ceil(v_revenue_after_discount / 1000) * 1000
      ELSE floor(v_revenue_after_discount / 1000) * 1000
    END;
    v_total_amount := v_deposit_invoice_total + v_rounded_revenue;

    v_billing_month := public.compute_first_billing_month_v2(v_start_billing, v_end_billing);
    v_due_date := COALESCE(NULLIF(v_first_invoice->>'due_date', '')::date, v_end_billing);
    v_issue_date := COALESCE(NULLIF(v_first_invoice->>'issue_date', '')::date, v_signed_date);
    IF v_due_date < v_start_billing OR v_due_date > v_end_billing THEN
      RAISE EXCEPTION 'Hạn trả hóa đơn đầu phải nằm trong kỳ tính tiền đầu'
        USING ERRCODE = '22023';
    END IF;
    IF v_issue_date < v_signed_date OR v_issue_date > v_due_date THEN
      RAISE EXCEPTION 'Ngày phát hành hóa đơn đầu phải từ ngày ký đến hạn trả'
        USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.invoices (
      user_id, organization_id, contract_id, building_id, room_id,
      invoice_number, billing_month, issue_date, due_date, status,
      subtotal, discount_amount, discount_notes, total_amount,
      prepaid_amount, paid_amount, previous_debt, notes, template_id,
      approved_at, approved_by, kind
    ) VALUES (
      v_owner, v_org, v_contract_id, v_building_id, v_room_id,
      NULL, v_billing_month, v_issue_date, v_due_date, 'APPROVED',
      v_subtotal, v_discount, NULLIF(v_first_invoice->>'discount_notes', ''),
      v_total_amount, 0, 0, 0, NULLIF(v_first_invoice->>'notes', ''),
      v_invoice_template_id,
      clock_timestamp(), v_actor, 'MONTHLY'
    ) RETURNING id INTO v_invoice_id;

    v_idx := 0;
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_first_invoice->'items') LOOP
      v_unit := (v_item->>'unit_price')::numeric;
      v_qty := (v_item->>'quantity')::numeric;
      v_class := COALESCE(NULLIF(v_item->>'accounting_class', ''), 'REVENUE');
      INSERT INTO public.invoice_items (
        organization_id, invoice_id, service_id, type, description,
        unit_price, quantity, coefficient, amount, previous_reading,
        current_reading, from_date, to_date, sort_order, accounting_class
      ) VALUES (
        v_org, v_invoice_id, NULLIF(v_item->>'service_id', '')::uuid,
        COALESCE(NULLIF(v_item->>'type', ''), 'OTHER')::public.invoice_item_type,
        COALESCE(NULLIF(v_item->>'description', ''), 'Hạng mục'),
        v_unit, v_qty, 1, round(v_unit * v_qty, 2), NULL, NULL,
        CASE WHEN v_class = 'REVENUE'
          THEN COALESCE(NULLIF(v_item->>'from_date', '')::date, v_start_billing)
          ELSE NULLIF(v_item->>'from_date', '')::date
        END,
        CASE WHEN v_class = 'REVENUE'
          THEN COALESCE(NULLIF(v_item->>'to_date', '')::date, v_end_billing)
          ELSE NULLIF(v_item->>'to_date', '')::date
        END,
        v_idx,
        v_class
      );
      v_idx := v_idx + 1;
    END LOOP;

    SELECT to_jsonb(invoice_row) INTO v_invoice_row
    FROM public.invoices invoice_row WHERE invoice_row.id = v_invoice_id;
  END IF;

  PERFORM app_private.claim_feature_operation_v1(
    'contract.create.v2',
    v_org,
    v_room_id::text || '|' || v_start_date::text,
    v_actor,
    v_key,
    round(v_new_deposit_receipts + COALESCE(v_total_amount, 0), 2)
  );

  UPDATE public.room_reservation_holds
     SET status = 'APPROVED', contract_id = v_contract_id
   WHERE room_id = v_room_id
     AND held_by = v_actor
     AND status = 'PENDING_APPROVAL'
     AND expires_at > clock_timestamp();

  UPDATE public.rooms SET status = 'OCCUPIED' WHERE id = v_room_id;

  SELECT to_jsonb(contract_row) INTO v_contract_row
  FROM public.contracts contract_row WHERE contract_row.id = v_contract_id;

  v_response := jsonb_build_object(
    'contract', v_contract_row,
    'invoice', v_invoice_row,
    'deposit_paid', v_deposit_paid,
    'deposit_shortfall', v_deposit_shortfall
  );

  UPDATE app_private.canonical_write_operations
     SET subject_id = v_contract_id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'contract.create.v2'
     AND subject_scope = v_room_id::text || '|' || v_start_date::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;

  RETURN v_response;
END;
$_$;








--
-- Name: create_finance_evidence_upload_intent_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_finance_evidence_upload_intent_v2(p_organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid := p_organization_id;
  v_actor record;
  v_id uuid;
  v_object text;
BEGIN
  IF v_org IS NULL THEN
    SELECT m.organization_id INTO v_org FROM public.organization_memberships m
    WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE' LIMIT 1;
  END IF;
  SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_org);
  IF v_actor.membership_id IS NULL THEN
    RAISE EXCEPTION 'Không có membership active trong organization' USING ERRCODE = '42501';
  END IF;

  v_object := 'v2/' || v_org::text || '/' || v_actor.membership_id::text || '/' || gen_random_uuid()::text;
  INSERT INTO public.finance_evidence_objects
    (organization_id, bucket_id, object_name, uploader_membership_id, uploader_user_id,
     provenance_kind, state)
  VALUES (v_org, 'income-expense-attachments', v_object, v_actor.membership_id, v_actor.user_id,
          'UPLOAD', 'UPLOAD_INTENT')
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('evidence_id', v_id,
                            'bucket_id', 'income-expense-attachments',
                            'object_name', v_object);
END
$$;








--
-- Name: create_income_expense_v1(text, text, uuid, uuid, uuid, uuid, text, text, text, uuid, jsonb, boolean, text, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_income_expense_v1(p_type text, p_name text, p_building_id uuid, p_room_id uuid, p_tenant_id uuid, p_contract_id uuid, p_payer_name text, p_receive_bank_account text, p_receive_bank_name text, p_account_id uuid, p_attachments jsonb, p_business_result_accounting boolean, p_notes text, p_voucher_date date, p_items jsonb, p_idempotency_key text) RETURNS public.income_expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$



DECLARE

  -- t5_23/24: trạng thái sinh theo phương án org (cờ hạng mục + ngưỡng chi)
  v_birth_status text;
  v_birth_by uuid;
  v_birth_at timestamptz;
  v_force_cat boolean;
  v_auto_threshold numeric;
  v_maker_can_approve boolean := false;




  v_actor uuid := app_private.current_uid_v1();



  v_claim_cap text;



  v_actor_name text;



  v_name text;



  v_org uuid;



  v_membership_id uuid;



  v_room_id uuid := p_room_id;



  v_tenant_id uuid := p_tenant_id;



  v_contract_room_id uuid;



  v_contract_tenant_id uuid;



  v_contract_deposit_paid_before public.contracts.deposit_paid%TYPE;



  v_contract_updated_at_before public.contracts.updated_at%TYPE;



  v_room_status_before public.rooms.status%TYPE;



  v_room_updated_at_before public.rooms.updated_at%TYPE;



  v_account_owner_id uuid;



  v_account_lock_date date;



  v_account_is_shared boolean := false;



  v_can_create_on_building boolean := false;



  v_can_create_restricted boolean := false;



  v_requires_restricted boolean := false;



  v_row public.income_expenses;



  v_operation app_private.canonical_write_operations%ROWTYPE;



  v_feature app_private.server_feature_flags%ROWTYPE;



  v_feature_route text;



  v_feature_operation_key text;



  v_feature_evaluated_at timestamptz;



  v_item jsonb;



  v_item_count integer;



  v_accrual_bucket_count integer := 0;



  v_index integer := 0;



  v_type_id uuid;



  v_type_is_restricted boolean;



  v_type_is_deposit boolean;



  v_type_normalized_name text;
  v_type_system_only boolean;



  v_quantity numeric;



  v_unit_price_raw numeric;



  v_unit_price numeric;



  v_start_date date;



  v_end_date date;



  v_description text;



  v_expected_type text;



  v_canonical_items jsonb := '[]'::jsonb;



  v_canonical_payload jsonb;



  v_payload_hash text;



  v_idempotency_key text;



  v_total_amount numeric := 0;



  v_feature_operation_count bigint;



  v_feature_total_amount numeric;



  v_stored_item_count bigint;



  v_stored_total_amount numeric;



  v_stored_has_restricted boolean;



  v_stored_counts_in_business_result boolean;



  v_stored_kqkd_amount numeric;
  v_stored_pnl_sum numeric;
  v_stored_has_deposit_item boolean;
  v_room_status_after public.rooms.status%TYPE;
  v_room_updated_at_after public.rooms.updated_at%TYPE;
  v_contract_deposit_paid_after public.contracts.deposit_paid%TYPE;
  v_contract_updated_at_after public.contracts.updated_at%TYPE;



  v_attachments jsonb := COALESCE(p_attachments, '[]'::jsonb);



  c_max_money constant numeric := 9999999999999.99;



  c_max_attachments constant integer := 20;



  c_max_attachment_length constant integer := 2048;



  c_max_name_length constant integer := 500;



  c_max_short_text_length constant integer := 255;



  c_max_notes_length constant integer := 5000;



  c_max_item_description_length constant integer := 1000;



  c_max_item_period_days constant integer := 3660;



  c_max_accrual_buckets constant integer := 2400;



  c_extra_whitespace constant text :=



    chr(160) || chr(173) || chr(5760)



    || chr(8192) || chr(8193) || chr(8194) || chr(8195) || chr(8196)



    || chr(8197) || chr(8198) || chr(8199) || chr(8200) || chr(8201)



    || chr(8202) || chr(8203) || chr(8232) || chr(8233) || chr(8239)



    || chr(8287) || chr(8288) || chr(12288) || chr(65279);



BEGIN



  IF v_actor IS NULL THEN



    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';



  END IF;







  -- A.9 smallest-shape: actor display name via postgres-owned DEFINER delegate



  -- (auth.users/profiles RLS is not part of the writer role's capability set).



  v_actor_name := app_private.ie_actor_display_name_v1(v_actor);



  IF v_actor_name IS NULL THEN



    RAISE EXCEPTION 'Không tìm thấy người dùng hiện tại' USING ERRCODE = '42501';



  END IF;







  -- Platform administration is not tenant business authority. A platform actor



  -- must also hold an active tenant membership and normalized tenant permission;



  -- emergency platform operations belong to a separate, audited endpoint.



  IF p_type NOT IN ('INCOME', 'EXPENSE') THEN



    RAISE EXCEPTION 'Loại phiếu không hợp lệ';



  END IF;



  v_name := btrim(p_name, E' \t\n\r\f\v' || c_extra_whitespace);



  IF p_name IS NULL OR v_name = '' THEN



    RAISE EXCEPTION 'Tên phiếu không được trống';



  END IF;



  IF char_length(v_name) > c_max_name_length THEN



    RAISE EXCEPTION 'Tên phiếu vượt quá % ký tự', c_max_name_length;



  END IF;



  IF p_building_id IS NULL THEN



    RAISE EXCEPTION 'Thiếu building_id';



  END IF;



  IF p_voucher_date IS NULL



     OR NOT isfinite(p_voucher_date)



     OR p_voucher_date < DATE '2000-01-01'



     OR p_voucher_date > DATE '2100-12-31' THEN



    RAISE EXCEPTION 'Ngày phiếu phải nằm trong khoảng 2000-01-01 đến 2100-12-31';



  END IF;



  v_idempotency_key := btrim(p_idempotency_key);



  IF v_idempotency_key IS NULL



     OR char_length(v_idempotency_key) < 8



     OR char_length(v_idempotency_key) > 200



     OR v_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN



    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII và chỉ chứa A-Z, a-z, 0-9, ., _, :, -';



  END IF;



  IF p_payer_name IS NOT NULL



     AND char_length(btrim(p_payer_name)) > c_max_short_text_length THEN



    RAISE EXCEPTION 'Tên người nộp/nhận vượt quá % ký tự', c_max_short_text_length;



  END IF;



  IF p_receive_bank_account IS NOT NULL



     AND char_length(btrim(p_receive_bank_account)) > c_max_short_text_length THEN



    RAISE EXCEPTION 'Số tài khoản nhận vượt quá % ký tự', c_max_short_text_length;



  END IF;



  IF p_receive_bank_name IS NOT NULL



     AND char_length(btrim(p_receive_bank_name)) > c_max_short_text_length THEN



    RAISE EXCEPTION 'Tên ngân hàng nhận vượt quá % ký tự', c_max_short_text_length;



  END IF;



  IF p_notes IS NOT NULL AND char_length(p_notes) > c_max_notes_length THEN



    RAISE EXCEPTION 'Ghi chú vượt quá % ký tự', c_max_notes_length;



  END IF;



  IF jsonb_typeof(v_attachments) <> 'array'



     OR jsonb_array_length(v_attachments) > c_max_attachments



     OR EXISTS (



       SELECT 1



         FROM jsonb_array_elements(v_attachments) x(value)



        WHERE jsonb_typeof(value) <> 'string'



           OR char_length(value #>> '{}') < 1



           OR char_length(value #>> '{}') > c_max_attachment_length



           OR value #>> '{}' ~ '[[:cntrl:]]'



           OR value #>> '{}' !~



                '^https://[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?(?::[0-9]{1,5})?(?:[/?#][^[:space:]\\]*)?$'



     ) THEN



    RAISE EXCEPTION 'attachments phải là mảng tối đa % HTTPS URL an toàn, mỗi URL dài 1-% ký tự',



      c_max_attachments, c_max_attachment_length;



  END IF;



  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN



    RAISE EXCEPTION 'items phải là mảng';



  END IF;



  v_item_count := jsonb_array_length(p_items);



  IF v_item_count < 1 OR v_item_count > 200 THEN



    RAISE EXCEPTION 'Phiếu phải có từ 1 đến 200 hạng mục';



  END IF;







  -- Lock order: organization/building → membership → staff/role scope → room →



  -- tenant → contract/contract_tenant → account/share → item types → feature row.



  SELECT b.organization_id



    INTO v_org



    FROM public.buildings b



    JOIN public.organizations o



      ON o.id = b.organization_id



     AND o.status = 'ACTIVE'



   WHERE b.id = p_building_id



     AND b.deleted_at IS NULL



   FOR SHARE OF o, b;



  IF NOT FOUND OR v_org IS NULL THEN



    RAISE EXCEPTION 'Không tìm thấy toà nhà trong tổ chức đang hoạt động'



      USING ERRCODE = '42501';



  END IF;







  SELECT m.id



    INTO v_membership_id



    FROM public.organization_memberships m



   WHERE m.user_id = v_actor



     AND m.organization_id = v_org



     AND m.status = 'ACTIVE'



     AND m.valid_from <= clock_timestamp()



     AND (m.valid_to IS NULL OR clock_timestamp() < m.valid_to)



   ORDER BY m.id



   LIMIT 1



   FOR SHARE;



  IF NOT FOUND THEN



    RAISE EXCEPTION 'Không còn là thành viên đang hoạt động của tổ chức'



      USING ERRCODE = '42501';



  END IF;







  v_can_create_on_building :=



    app_private.authorize_income_expense_on_building(



      v_actor, v_org, 'create', p_building_id



    );







  v_can_create_restricted :=



    app_private.authorize_income_expense_on_building(



      v_actor, v_org, 'restricted_create', p_building_id



    );







  IF p_room_id IS NOT NULL THEN



    PERFORM 1



      FROM public.rooms r



     WHERE r.id = p_room_id



       AND r.deleted_at IS NULL



       AND r.building_id = p_building_id



       AND r.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Phòng không thuộc toà/tổ chức của phiếu'



        USING ERRCODE = '42501';



    END IF;



  END IF;







  IF p_tenant_id IS NOT NULL THEN



    PERFORM 1



      FROM public.tenants t



     WHERE t.id = p_tenant_id



       AND t.deleted_at IS NULL



       AND t.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Khách thuê không thuộc tổ chức của phiếu'



        USING ERRCODE = '42501';



    END IF;



  END IF;







  IF p_contract_id IS NOT NULL THEN



    SELECT c.room_id, c.tenant_id, c.deposit_paid, c.updated_at



      INTO v_contract_room_id, v_contract_tenant_id,



           v_contract_deposit_paid_before, v_contract_updated_at_before



      FROM public.contracts c



      JOIN public.rooms r



        ON r.id = c.room_id



       AND r.deleted_at IS NULL



       AND r.building_id = p_building_id



       AND r.organization_id = v_org



     WHERE c.id = p_contract_id



       AND c.deleted_at IS NULL



       AND c.organization_id = v_org



     FOR SHARE OF c, r;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Hợp đồng không thuộc toà/tổ chức của phiếu'



        USING ERRCODE = '42501';



    END IF;



    IF p_room_id IS NOT NULL AND p_room_id IS DISTINCT FROM v_contract_room_id THEN



      RAISE EXCEPTION 'Hợp đồng không khớp phòng của phiếu'



        USING ERRCODE = '42501';



    END IF;







    IF v_contract_tenant_id IS NOT NULL THEN



      PERFORM 1



        FROM public.tenants t



       WHERE t.id = v_contract_tenant_id



         AND t.deleted_at IS NULL



         AND t.organization_id = v_org



       FOR SHARE;



      IF NOT FOUND THEN



        RAISE EXCEPTION 'Khách thuê đại diện của hợp đồng không còn hợp lệ'



          USING ERRCODE = '42501';



      END IF;



      IF p_tenant_id IS NOT NULL



         AND p_tenant_id IS DISTINCT FROM v_contract_tenant_id THEN



        RAISE EXCEPTION 'Hợp đồng không khớp khách thuê của phiếu'



          USING ERRCODE = '42501';



      END IF;



      v_tenant_id := v_contract_tenant_id;



    ELSIF p_tenant_id IS NOT NULL THEN



      -- contracts.tenant_id is a nullable legacy representative. Only the legacy



      -- contract_tenants relation can prove a supplied tenants.id; contract_customers



      -- references public.customers and must never be used as a tenant bridge.



      PERFORM 1



        FROM public.contract_tenants ct



       WHERE ct.contract_id = p_contract_id



         AND ct.tenant_id = p_tenant_id



         AND (ct.organization_id IS NULL OR ct.organization_id = v_org)



       FOR SHARE;



      IF NOT FOUND THEN



        RAISE EXCEPTION 'Khách thuê không thuộc hợp đồng'



          USING ERRCODE = '42501';



      END IF;



      v_tenant_id := p_tenant_id;



    ELSE



      v_tenant_id := NULL;



    END IF;







    v_room_id := v_contract_room_id;



  END IF;







  IF NOT v_can_create_on_building THEN



    RAISE EXCEPTION 'Không có quyền tạo phiếu thu/chi cho toà này'



      USING ERRCODE = '42501';



  END IF;







  IF v_room_id IS NOT NULL THEN



    SELECT r.status, r.updated_at



      INTO v_room_status_before, v_room_updated_at_before



      FROM public.rooms r



     WHERE r.id = v_room_id



       AND r.deleted_at IS NULL



       AND r.building_id = p_building_id



       AND r.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Phòng hiệu lực không thuộc toà/tổ chức của phiếu'



        USING ERRCODE = '42501';



    END IF;



  END IF;







  IF p_account_id IS NOT NULL THEN



    SELECT a.user_id, a.lock_date



      INTO v_account_owner_id, v_account_lock_date



      FROM public.accounts a



     WHERE a.id = p_account_id



       AND a.deleted_at IS NULL



       AND a.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Sổ quỹ không thuộc tổ chức của phiếu'



        USING ERRCODE = '42501';



    END IF;







    -- Possession thay cho account_shared_users (cutover 02/08/2026). KHÔNG khoá
    -- dòng binding: hệ possession bất biến theo thời gian (thu hồi = đóng valid_to,
    -- không xoá dòng), nên hậu kiểm dưới đây đã đủ chặn revoke chạy song song.
    -- §9.2: CUSTODIAN/OPERATOR làm mọi loại phiếu, KNOWER chỉ Phiếu thu.
    SELECT EXISTS (
      SELECT 1
        FROM public.cashbook_possession_bindings b
        JOIN public.organization_memberships m ON m.id = b.membership_id
       WHERE b.cashbook_id = p_account_id
         AND b.organization_id = v_org
         AND m.user_id = v_actor
         AND m.status = 'ACTIVE'
         AND b.valid_to IS NULL
         AND (b.possession_kind IN ('CUSTODIAN','OPERATOR')
              OR (b.possession_kind = 'KNOWER' AND p_type = 'INCOME'))
    ) INTO v_account_is_shared;







    -- Cashbook ownership/sharing remains semantically authoritative until the



    -- normalized cashbooks.post resolver is complete. Building permission never



    -- implies use of an arbitrary same-organization cashbook, while account



    -- ownership/sharing never implies permission to create on the building.



    IF NOT (



      v_account_owner_id = v_actor



      OR v_account_is_shared



    ) THEN



      RAISE EXCEPTION 'Không có quyền sử dụng sổ quỹ này'



        USING ERRCODE = '42501';



    END IF;







  END IF;







  v_expected_type := CASE p_type WHEN 'INCOME' THEN 'income' ELSE 'expense' END;







  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)



  LOOP



    v_index := v_index + 1;



    IF jsonb_typeof(v_item) <> 'object' THEN



      RAISE EXCEPTION 'Hạng mục % phải là object', v_index;



    END IF;



    IF (v_item - ARRAY[



      'income_expense_type_id', 'description', 'quantity', 'unit_price', 'start_date', 'end_date'



    ]) <> '{}'::jsonb THEN



      RAISE EXCEPTION 'Hạng mục % chứa trường không được phép', v_index;



    END IF;



    IF NOT (v_item ? 'income_expense_type_id')



       OR jsonb_typeof(v_item->'income_expense_type_id') <> 'string' THEN



      RAISE EXCEPTION 'Loại thu/chi hạng mục % phải là UUID dạng chuỗi', v_index;



    END IF;



    IF NOT (v_item ? 'quantity')



       OR jsonb_typeof(v_item->'quantity') <> 'number' THEN



      RAISE EXCEPTION 'Số lượng hạng mục % phải là JSON number', v_index;



    END IF;



    IF NOT (v_item ? 'unit_price')



       OR jsonb_typeof(v_item->'unit_price') <> 'number' THEN



      RAISE EXCEPTION 'Đơn giá hạng mục % phải là JSON number', v_index;



    END IF;



    IF NOT (v_item ? 'start_date')



       OR jsonb_typeof(v_item->'start_date') <> 'string'



       OR v_item->>'start_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN



      RAISE EXCEPTION 'Ngày bắt đầu hạng mục % phải là YYYY-MM-DD', v_index;



    END IF;



    IF NOT (v_item ? 'end_date')



       OR jsonb_typeof(v_item->'end_date') <> 'string'



       OR v_item->>'end_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN



      RAISE EXCEPTION 'Ngày kết thúc hạng mục % phải là YYYY-MM-DD', v_index;



    END IF;



    IF v_item ? 'description'



       AND jsonb_typeof(v_item->'description') NOT IN ('string', 'null') THEN



      RAISE EXCEPTION 'Mô tả hạng mục % phải là chuỗi', v_index;



    END IF;







    BEGIN



      v_type_id := NULLIF(v_item->>'income_expense_type_id', '')::uuid;



      v_quantity := (v_item->>'quantity')::numeric;



      v_unit_price_raw := (v_item->>'unit_price')::numeric;



      v_unit_price := round(v_unit_price_raw, 2);



      v_start_date := (v_item->>'start_date')::date;



      v_end_date := (v_item->>'end_date')::date;



      v_description := NULLIF(btrim(v_item->>'description'), '');



    EXCEPTION



      WHEN invalid_text_representation



        OR invalid_datetime_format



        OR numeric_value_out_of_range



        OR datetime_field_overflow THEN



        RAISE EXCEPTION 'Hạng mục % có dữ liệu không hợp lệ', v_index;



    END;







    IF v_type_id IS NULL THEN



      RAISE EXCEPTION 'Hạng mục % thiếu loại thu/chi', v_index;



    END IF;



    IF v_description IS NOT NULL



       AND char_length(v_description) > c_max_item_description_length THEN



      RAISE EXCEPTION 'Mô tả hạng mục % vượt quá % ký tự',



        v_index, c_max_item_description_length;



    END IF;



    IF v_quantity IS NULL



       OR v_quantity::text IN ('NaN', 'Infinity', '-Infinity')



       OR v_quantity < 1



       OR v_quantity > 2147483647



       OR v_quantity <> trunc(v_quantity) THEN



      RAISE EXCEPTION 'Số lượng hạng mục % phải là số nguyên hợp lệ >= 1', v_index;



    END IF;



    -- Quantity is stored as integer; normalize numeric spelling before hashing.



    v_quantity := trunc(v_quantity);



    IF v_unit_price_raw IS NULL



       OR v_unit_price_raw::text IN ('NaN', 'Infinity', '-Infinity')



       OR v_unit_price_raw < 0



       OR v_unit_price < 0



       OR v_unit_price > c_max_money THEN



      RAISE EXCEPTION 'Đơn giá hạng mục % không hợp lệ', v_index;



    END IF;



    IF v_quantity * v_unit_price > c_max_money THEN



      RAISE EXCEPTION 'Thành tiền hạng mục % vượt giới hạn', v_index;



    END IF;



    IF v_start_date IS NULL



       OR v_end_date IS NULL



       OR NOT isfinite(v_start_date)



       OR NOT isfinite(v_end_date)



       OR v_start_date < DATE '2000-01-01'



       OR v_end_date > DATE '2100-12-31'



       OR v_start_date > v_end_date



       OR v_end_date - v_start_date > c_max_item_period_days THEN



      RAISE EXCEPTION 'Kỳ áp dụng hạng mục % phải nằm trong 2000-01-01..2100-12-31 và không quá % ngày',



        v_index, c_max_item_period_days;



    END IF;



    v_accrual_bucket_count := v_accrual_bucket_count



      + (



          extract(year FROM v_end_date)::integer * 12



          + extract(month FROM v_end_date)::integer



          - extract(year FROM v_start_date)::integer * 12



          - extract(month FROM v_start_date)::integer



          + 1



        );



    IF v_accrual_bucket_count > c_max_accrual_buckets THEN



      RAISE EXCEPTION 'Tổng số bucket dồn tích vượt giới hạn %', c_max_accrual_buckets



        USING ERRCODE = '54000';



    END IF;







    SELECT t.is_restricted, t.is_deposit, public.nrm_vn(t.name), t.system_only
      INTO v_type_is_restricted, v_type_is_deposit, v_type_normalized_name, v_type_system_only



      FROM public.income_expense_types t



     WHERE t.id = v_type_id



       AND lower(t.type) = v_expected_type



       AND t.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Loại hạng mục % không thuộc tổ chức hoặc sai chiều thu/chi', v_index



        USING ERRCODE = '42501';



    END IF;



    -- Chốt chặn tạo tay: đọc CỜ `system_only` trên hạng mục thay vì so khớp TÊN.
    -- Cờ đã được bật cho đúng 36 dòng bằng chính hai vị từ cũ (is_deposit +
    -- tên hoa hồng/thưởng), nên hành vi KHÔNG đổi — chỉ hết mong manh khi đổi tên.
    -- Chủ sở hữu bật/tắt được từng hạng mục ở Cài đặt mà không cần sửa hàm.
    IF coalesce(v_type_system_only, false) THEN
      RAISE EXCEPTION 'Hạng mục "%" chỉ được sinh từ hệ thống (hợp đồng/cọc/thanh lý/hoa hồng), không tạo tay từ màn Thu/Chi',
        (SELECT name FROM public.income_expense_types WHERE id = v_type_id)
        USING ERRCODE = '0A000';
    END IF;



    



    IF v_type_is_restricted THEN



      v_requires_restricted := true;



      IF NOT v_can_create_restricted THEN



        RAISE EXCEPTION 'Không có quyền tạo hạng mục thu/chi hạn chế'



          USING ERRCODE = '42501';



      END IF;



    END IF;







    v_total_amount := v_total_amount + (v_quantity * v_unit_price);



    IF v_total_amount > c_max_money THEN



      RAISE EXCEPTION 'Tổng tiền phiếu vượt giới hạn';



    END IF;







    -- Build the equality token from typed values, not caller UUID/date spelling.



    v_canonical_items := v_canonical_items || jsonb_build_array(



      jsonb_strip_nulls(jsonb_build_object(



        'income_expense_type_id', v_type_id,



        'description', v_description,



        'quantity', v_quantity,



        'unit_price', v_unit_price,



        'start_date', v_start_date,



        'end_date', v_end_date



      ))



    );



  END LOOP;







  v_canonical_payload := jsonb_strip_nulls(jsonb_build_object(



    'type', p_type,



    'name', v_name,



    'building_id', p_building_id,



    'room_id', v_room_id,



    'tenant_id', v_tenant_id,



    'contract_id', p_contract_id,



    'payer_name', NULLIF(btrim(p_payer_name), ''),



    'receive_bank_account', NULLIF(btrim(p_receive_bank_account), ''),



    'receive_bank_name', NULLIF(btrim(p_receive_bank_name), ''),



    'account_id', p_account_id,



    'attachments', v_attachments,



    'business_result_accounting', p_business_result_accounting,



    'notes', NULLIF(p_notes, ''),



    'voucher_date', p_voucher_date,



    'items', v_canonical_items



  ));



  -- md5(jsonb::text) is deterministic for PostgreSQL jsonb canonical key ordering;



  -- payload_hash is an equality token, not a password/signature.



  v_payload_hash := md5(v_canonical_payload::text);







  -- The unconditional unique claim is the linearization point. ON CONFLICT waits



  -- for an in-flight claimant: if it aborts this transaction becomes the claimant;



  -- if it commits the locked reread observes its immutable completion. Rollout state



  -- is deliberately not consulted until after that outcome is known.



  INSERT INTO app_private.canonical_write_operations (



    organization_id, operation, subject_scope, actor_id,



    idempotency_key, payload_hash



  ) VALUES (



    v_org, 'income_expense.create_draft.v1', p_building_id::text, v_actor,



    v_idempotency_key, v_payload_hash



  )



  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)



  DO NOTHING;







  SELECT *



    INTO v_operation



    FROM app_private.canonical_write_operations o



   WHERE o.organization_id = v_org



     AND o.operation = 'income_expense.create_draft.v1'



     AND o.subject_scope = p_building_id::text



     AND o.actor_id = v_actor



     AND o.idempotency_key = v_idempotency_key



   FOR UPDATE;



  IF NOT FOUND THEN



    RAISE EXCEPTION 'Không thể nhận diện operation idempotency đã claim'



      USING ERRCODE = '55000';



  END IF;



  IF v_operation.payload_hash <> v_payload_hash THEN



    RAISE EXCEPTION 'idempotency_key đã được dùng với payload khác'



      USING ERRCODE = '23505';



  END IF;







  -- Completed replay still requires current tenant authority, but it must not depend



  -- on mutable rollout admission, canary enrollment/caps, or the cashbook lock date.



  -- Platform-super status is intentionally irrelevant to tenant business authority.



  IF NOT EXISTS (



    SELECT 1



      FROM public.organization_memberships m



     WHERE m.id = v_membership_id



       AND m.organization_id = v_org



       AND m.user_id = v_actor



       AND m.status = 'ACTIVE'



       AND m.valid_from <= clock_timestamp()



       AND (m.valid_to IS NULL OR clock_timestamp() < m.valid_to)



  ) THEN



    RAISE EXCEPTION 'Tư cách thành viên đã hết hiệu lực'



      USING ERRCODE = '42501';



  END IF;



  IF NOT app_private.authorize_income_expense_on_building(



    v_actor, v_org, 'create', p_building_id



  ) THEN



    RAISE EXCEPTION 'Quyền tạo phiếu trên toà đã bị thu hồi'



      USING ERRCODE = '42501';



  END IF;



  IF v_requires_restricted



     AND NOT app_private.authorize_income_expense_on_building(



       v_actor, v_org, 'restricted_create', p_building_id



     ) THEN



    RAISE EXCEPTION 'Quyền tạo hạng mục hạn chế đã bị thu hồi'



      USING ERRCODE = '42501';



  END IF;



  IF p_account_id IS NOT NULL



     AND v_account_owner_id IS DISTINCT FROM v_actor



     AND NOT EXISTS (
         SELECT 1
           FROM public.cashbook_possession_bindings b
           JOIN public.organization_memberships m ON m.id = b.membership_id
          WHERE b.cashbook_id = p_account_id
            AND b.organization_id = v_org
            AND m.user_id = v_actor
            AND m.status = 'ACTIVE'
            AND b.valid_to IS NULL
            AND (b.possession_kind IN ('CUSTODIAN','OPERATOR')
                 OR (b.possession_kind = 'KNOWER' AND p_type = 'INCOME'))
       ) THEN



    RAISE EXCEPTION 'Quyền sử dụng sổ quỹ đã bị thu hồi'



      USING ERRCODE = '42501';



  END IF;







  IF v_operation.completed_at IS NOT NULL THEN



    SELECT *



      INTO v_row



      FROM jsonb_populate_record(



        NULL::public.income_expenses,



        v_operation.response_payload



      );



    IF v_row.id IS NULL OR v_row.id IS DISTINCT FROM v_operation.subject_id THEN



      RAISE EXCEPTION 'Kết quả idempotency không còn nhất quán';



    END IF;



    RETURN v_row;



  END IF;







  -- Only a new/pending claimant enters rollout admission. A completed operation above



  -- can therefore replay after OFF/freeze, enrollment removal, or window closure.



  SELECT *



    INTO v_feature



    FROM app_private.server_feature_flags f



   WHERE f.feature_key = 'income_expense.create_draft.v1'



   FOR SHARE;



  IF NOT FOUND THEN



    RAISE EXCEPTION 'Canonical writer chưa được cấu hình' USING ERRCODE = '55000';



  END IF;







  -- A CANARY enrollment used for admission must survive through commit. The shared



  -- feature lock freezes the release identity/configuration for this transaction.



  IF v_feature.mode = 'CANARY' THEN



    PERFORM 1



      FROM app_private.server_feature_flag_canary_orgs c



     WHERE c.feature_key = v_feature.feature_key



       AND c.organization_id = v_org



     FOR SHARE;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Tổ chức không còn trong canary'



        USING ERRCODE = '55000';



    END IF;



  END IF;







  v_feature_route := app_private.evaluate_feature_route(



    v_feature.feature_key, v_org



  );



  IF v_feature_route <> 'CANONICAL' THEN



    RAISE EXCEPTION 'Canonical writer chưa được bật hoặc đang đóng băng cho tổ chức này'



      USING ERRCODE = '55000';



  END IF;







  IF v_feature.mode = 'CANARY' THEN



    -- Serialize only one feature/config cap bucket; do not upgrade the shared row



    -- lock, which would deadlock concurrent readers and globally serialize ON mode.



    PERFORM pg_catalog.pg_advisory_xact_lock(



      pg_catalog.hashtextextended(



        v_feature.feature_key || ':' || v_feature.config_version::text,



        0



      )



    );



    v_feature_evaluated_at := clock_timestamp();



    IF v_feature.starts_at IS NULL



       OR v_feature.ends_at IS NULL



       OR NOT isfinite(v_feature.starts_at)



       OR NOT isfinite(v_feature.ends_at)



       OR v_feature.starts_at >= v_feature.ends_at



       OR v_feature_evaluated_at < v_feature.starts_at



       OR v_feature_evaluated_at >= v_feature.ends_at THEN



      RAISE EXCEPTION 'Cửa sổ canary không còn hiệu lực'



        USING ERRCODE = '55000';



    END IF;



    IF v_feature.max_single_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')



       OR v_feature.max_total_amount_vnd::text IN ('NaN', 'Infinity', '-Infinity')



       OR v_feature.max_operation_count <= 0



       OR v_feature.max_single_amount_vnd <= 0



       OR v_feature.max_total_amount_vnd <= 0 THEN



      RAISE EXCEPTION 'Hạn mức canary không hợp lệ'



        USING ERRCODE = '55000';



    END IF;



    IF v_total_amount > v_feature.max_single_amount_vnd THEN



      RAISE EXCEPTION 'Số tiền vượt cap canary cho một phiếu'



        USING ERRCODE = '54000';



    END IF;







    SELECT count(*), COALESCE(sum(o.amount_vnd), 0)



      INTO v_feature_operation_count, v_feature_total_amount



      FROM app_private.server_feature_flag_operations o



     WHERE o.feature_key = v_feature.feature_key



       AND o.config_version = v_feature.config_version;



    IF v_feature_operation_count >= v_feature.max_operation_count THEN



      RAISE EXCEPTION 'Đã hết số lượt canary' USING ERRCODE = '54000';



    END IF;



    IF v_feature_total_amount + v_total_amount > v_feature.max_total_amount_vnd THEN



      RAISE EXCEPTION 'Đã hết tổng hạn mức tiền canary' USING ERRCODE = '54000';



    END IF;



  END IF;







  -- Recheck expiring tenant authority after every idempotency, rollout, enrollment,



  -- and advisory-lock wait. Account lock_date is an effect-only rule: it is applied



  -- here for a new effect but was intentionally skipped by completed replay above.



  IF NOT EXISTS (



    SELECT 1



      FROM public.organization_memberships m



     WHERE m.id = v_membership_id



       AND m.organization_id = v_org



       AND m.user_id = v_actor



       AND m.status = 'ACTIVE'



       AND m.valid_from <= clock_timestamp()



       AND (m.valid_to IS NULL OR clock_timestamp() < m.valid_to)



  ) THEN



    RAISE EXCEPTION 'Tư cách thành viên đã hết hiệu lực'



      USING ERRCODE = '42501';



  END IF;



  IF NOT app_private.authorize_income_expense_on_building(



    v_actor, v_org, 'create', p_building_id



  ) THEN



    RAISE EXCEPTION 'Quyền tạo phiếu trên toà đã bị thu hồi'



      USING ERRCODE = '42501';



  END IF;



  IF v_requires_restricted



     AND NOT app_private.authorize_income_expense_on_building(



       v_actor, v_org, 'restricted_create', p_building_id



     ) THEN



    RAISE EXCEPTION 'Quyền tạo hạng mục hạn chế đã bị thu hồi'



      USING ERRCODE = '42501';



  END IF;



  IF p_account_id IS NOT NULL THEN



    IF v_account_owner_id IS DISTINCT FROM v_actor



       AND NOT EXISTS (
         SELECT 1
           FROM public.cashbook_possession_bindings b
           JOIN public.organization_memberships m ON m.id = b.membership_id
          WHERE b.cashbook_id = p_account_id
            AND b.organization_id = v_org
            AND m.user_id = v_actor
            AND m.status = 'ACTIVE'
            AND b.valid_to IS NULL
            AND (b.possession_kind IN ('CUSTODIAN','OPERATOR')
                 OR (b.possession_kind = 'KNOWER' AND p_type = 'INCOME'))
       ) THEN



      RAISE EXCEPTION 'Quyền sử dụng sổ quỹ đã bị thu hồi'



        USING ERRCODE = '42501';



    END IF;



    IF v_account_lock_date IS NOT NULL AND p_voucher_date <= v_account_lock_date THEN



      RAISE EXCEPTION 'Sổ quỹ đã khoá tại ngày phiếu';



    END IF;



  END IF;







  IF v_feature.mode = 'CANARY' THEN



    v_feature_operation_key := md5(concat_ws(



      '|',



      'income_expense.create_draft.v1',



      v_org::text,



      p_building_id::text,



      v_actor::text,



      v_idempotency_key



    ));



    INSERT INTO app_private.server_feature_flag_operations (



      feature_key, config_version, operation_key, organization_id, amount_vnd



    ) VALUES (



      v_feature.feature_key, v_feature.config_version, v_feature_operation_key,



      v_org, v_total_amount



    );



  END IF;







  -- Deliberately unresolved: the final T3 containment contract must supply a



  -- server-owned canonical-flow marker that exists at draft creation time. Neither



  -- approval_request_id (NULL before submit) nor the private idempotency ledger is an



  -- acceptable provenance marker. Keep this function revoked until the replacement



  -- source writes that marker atomically with the header and legacy transition guards



  -- reject marked rows.



    -- t5_23/24: chọn trạng thái sinh — auto-duyệt TRỪ hạng mục đặc biệt (cờ
  -- force_approval, gồm hoàn cọc/thanh lý/lương/LN/HH/thưởng...) và TRỪ phiếu
  -- CHI từ ngưỡng cài đặt trở lên (app_private.ie_auto_approve_config; chưa
  -- đặt ngưỡng = tự duyệt như cũ). Phiếu không tự duyệt sinh ở NHÁP chờ duyệt tay.
  SELECT bool_or(coalesce(t.force_approval, false))
    INTO v_force_cat
    FROM jsonb_array_elements(p_items) AS it
    JOIN public.income_expense_types t
      ON t.id = (it->>'income_expense_type_id')::uuid;
  SELECT c.threshold INTO v_auto_threshold
    FROM app_private.ie_auto_approve_config c
   WHERE c.organization_id = v_org;
  -- Chủ sở hữu chốt 2026-07-25: NGƯỜI LẬP PHIẾU MÀ CÓ QUYỀN DUYỆT thì phiếu
  -- tự duyệt ngay lúc tạo, không qua Nháp và không chờ ai. Kiểm bằng mô hình
  -- quyền canonical (app_private.can_v3) — không đọc JSONB legacy.
  -- income_expenses.approve khai required_dimensions=['BUILDING'] nên phiếu không
  -- gắn toà phải hỏi dạng "có quyền ở bất kỳ đâu".
  v_maker_can_approve := CASE
    WHEN p_building_id IS NOT NULL
      THEN app_private.can_v3('income_expenses.approve', p_building_id)
    ELSE app_private.has_any_scope_v3('income_expenses.approve')
  END;

  IF coalesce(v_maker_can_approve, false) THEN
    v_birth_status := 'APPROVED';
  ELSIF p_type = 'INCOME' THEN
    -- Chủ sở hữu chốt 2026-07-27: MỌI phiếu THU tự duyệt + ghi sổ ngay khi
    -- tạo, kể cả hạng mục Tiền Cọc bên thu. Cờ force_approval và ngưỡng
    -- chi chỉ còn áp cho phiếu CHI (hoàn cọc, thanh lý, hoa hồng, lương…).
    v_birth_status := 'APPROVED';
  ELSIF coalesce(v_force_cat, false) THEN
    v_birth_status := 'UNAPPROVED';
  ELSIF p_type = 'EXPENSE' AND v_auto_threshold IS NOT NULL
        AND v_total_amount >= v_auto_threshold THEN
    v_birth_status := 'UNAPPROVED';
  ELSE
    v_birth_status := 'APPROVED';
  END IF;
  IF v_birth_status = 'APPROVED' THEN
    v_birth_by := v_actor; v_birth_at := now();
  ELSE
    v_birth_by := NULL; v_birth_at := NULL;
  END IF;

  INSERT INTO public.income_expenses (



    user_id, creator_name, organization_id,



    type, name, building_id, room_id, tenant_id, contract_id,



    payer_name, receive_bank_account, receive_bank_name, account_id,



    attachments, business_result_accounting, notes,



    repeat_cycle, repeat_infinity, repeat_count, repeat_auto_approve,



    repeat_remaining, repeat_next_date,



    voucher_date, approval_status, approved_by, approved_at,



    source_payload_hash, system_source



  ) VALUES (



    v_actor, v_actor_name, v_org,



    p_type, v_name, p_building_id, v_room_id, v_tenant_id, NULL,



    NULLIF(btrim(p_payer_name), ''), NULLIF(btrim(p_receive_bank_account), ''),



    NULLIF(btrim(p_receive_bank_name), ''), p_account_id,



    v_attachments, p_business_result_accounting, NULLIF(p_notes, ''),



    'NONE', false, 0, false,



    0, NULL,



    p_voucher_date, v_birth_status, v_birth_by, v_birth_at,



    v_payload_hash, NULL



  )



  RETURNING * INTO v_row;







  INSERT INTO public.income_expense_items (



    income_expense_id, income_expense_type_id, description,



    quantity, unit_price, start_date, end_date, organization_id



  )



  SELECT



    v_row.id,



    (item->>'income_expense_type_id')::uuid,



    item->>'description',



    (item->>'quantity')::integer,



    (item->>'unit_price')::numeric,



    (item->>'start_date')::date,



    (item->>'end_date')::date,



    v_org



  FROM jsonb_array_elements(v_canonical_items) AS x(item);







  -- Keep the parent detached while non-deposit/non-commission items are inserted.



  -- The legacy item trigger otherwise recomputes any historical approved deposit on



  -- the contract and churns contracts.updated_at even though this draft has no deposit.



  -- Commission flows are excluded above and retain their specialized writer because



  -- their invariants require contract_id on the header before item insertion.



  IF p_contract_id IS NOT NULL THEN



    UPDATE public.income_expenses



       SET contract_id = p_contract_id



     WHERE id = v_row.id



       AND contract_id IS NULL;



    IF NOT FOUND THEN



      RAISE EXCEPTION 'Không thể gắn hợp đồng đã xác thực vào phiếu nháp'



        USING ERRCODE = '23514';



    END IF;



  END IF;







  SELECT * INTO v_row FROM public.income_expenses WHERE id = v_row.id;







  SELECT count(*), COALESCE(sum(it.amount), 0),
         COALESCE(bool_or(t.is_restricted), false),
         COALESCE(sum(COALESCE(it.amount, it.unit_price * it.quantity))
           FILTER (WHERE it.accounting_class = 'PNL'), 0),
         COALESCE(bool_or(t.is_deposit), false)
    INTO v_stored_item_count, v_stored_total_amount, v_stored_has_restricted,
         v_stored_pnl_sum, v_stored_has_deposit_item



    FROM public.income_expense_items it



    JOIN public.income_expense_types t ON t.id = it.income_expense_type_id



   WHERE it.income_expense_id = v_row.id;



  -- Kỳ vọng phải MIRROR public.recompute_ie_business_result: khi caller không
  -- ép business_result_accounting, KQKD suy từ hạng mục (item accounting_class),
  -- KHÔNG mặc định là toàn bộ số tiền. Công thức cũ giả định NULL => (true, total)
  -- nên MỌI phiếu có hạng mục cọc (accounting_class='DEPOSIT') đều văng 23514 —
  -- đó là lý do phiếu thu tiền cọc chưa bao giờ đi qua được writer canonical.
  v_stored_kqkd_amount := CASE
    WHEN p_business_result_accounting IS TRUE THEN v_total_amount
    WHEN p_business_result_accounting IS FALSE THEN 0
    WHEN v_item_count = 0 THEN v_total_amount
    ELSE GREATEST(LEAST(v_stored_pnl_sum, v_total_amount), 0)
  END;
  v_stored_counts_in_business_result := (v_stored_kqkd_amount > 0);



  IF v_stored_item_count <> v_item_count



     OR v_stored_total_amount IS DISTINCT FROM v_total_amount



     OR v_row.total_amount IS DISTINCT FROM v_total_amount



     OR v_row.has_restricted_item IS DISTINCT FROM v_stored_has_restricted



     OR v_row.counts_in_business_result IS DISTINCT FROM v_stored_counts_in_business_result



     OR v_row.kqkd_amount IS DISTINCT FROM v_stored_kqkd_amount THEN



    RAISE EXCEPTION 'Trigger thu/chi không tạo đúng các trường tài chính suy diễn'



      USING ERRCODE = '23514';



  END IF;







  -- Generic non-deposit drafts must not reconcile pre-existing deposit or room



  -- reservation state. The earlier row locks make any difference attributable to



  -- this statement; aborting here rolls back the complete writer transaction.



  IF p_contract_id IS NOT NULL THEN
    SELECT c.deposit_paid, c.updated_at
      INTO v_contract_deposit_paid_after, v_contract_updated_at_after
      FROM public.contracts c
     WHERE c.id = p_contract_id;

    -- NỚI ĐÚNG MỘT KHE (án 29/07/2026): phiếu MANG item hạng mục cọc thì
    -- recompute_contract_deposit_paid CHẠY LÀ ĐÚNG THIẾT KẾ — cấm nó tức là cấm
    -- luôn lớp phiếu mà 20260727120000 vừa mở cửa cho writer canonical. Vẫn bắt
    -- writer chứng minh: giá trị sau cùng phải bằng SỐ DẪN XUẤT chuẩn, không
    -- phải số tuỳ ý. Phiếu KHÔNG có item cọc vẫn cấm tuyệt đối như cũ.
    IF (
      v_contract_deposit_paid_after IS DISTINCT FROM v_contract_deposit_paid_before
      OR v_contract_updated_at_after IS DISTINCT FROM v_contract_updated_at_before
    ) AND NOT (
      v_stored_has_deposit_item
      AND v_contract_deposit_paid_after
            IS NOT DISTINCT FROM public.contract_deposit_paid_derived(p_contract_id)
    ) THEN
      RAISE EXCEPTION 'Writer phiếu nháp tổng quát đã tác động trạng thái tiền cọc hợp đồng'
        USING ERRCODE = '23514';
    END IF;
  END IF;



  IF v_room_id IS NOT NULL THEN
    SELECT r.status, r.updated_at
      INTO v_room_status_after, v_room_updated_at_after
      FROM public.rooms r
     WHERE r.id = v_room_id;

    -- Cùng một án với hậu kiểm hợp đồng ở trên: phiếu THU cọc GIỮ CHỖ (có item
    -- hạng mục cọc, CHƯA gắn HĐ) có NHIỆM VỤ khoá phòng — recompute_room_reservation
    -- lật AVAILABLE -> RESERVED. Nới đúng khe đó, và vẫn bắt writer chứng minh
    -- trạng thái mới khớp predicate chuẩn room_has_holding_deposit. Mọi chuyển
    -- dịch khác (RESERVED -> AVAILABLE, đụng OCCUPIED/MAINTENANCE, hay chỉ bump
    -- updated_at) vẫn là writer đụng nhầm state có sẵn => abort như cũ.
    IF (
      v_room_status_after IS DISTINCT FROM v_room_status_before
      OR v_room_updated_at_after IS DISTINCT FROM v_room_updated_at_before
    ) AND NOT (
      v_stored_has_deposit_item
      AND v_row.type = 'INCOME'
      AND v_row.contract_id IS NULL
      AND v_room_status_before = 'AVAILABLE'
      AND v_room_status_after = 'RESERVED'
      AND public.room_has_holding_deposit(v_room_id)
    ) THEN
      RAISE EXCEPTION 'Writer phiếu nháp tổng quát đã tác động trạng thái giữ phòng'
        USING ERRCODE = '23514';
    END IF;
  END IF;







  -- The shared feature-row lock and, for CANARY, shared enrollment lock keep the



  -- admitted rollout identity stable. Re-evaluate only the time boundary here:



  -- counting the reservation we just inserted as a new admission would reject the



  -- exact final permitted count slot (count = max) after its effects were built.



  IF v_feature.mode = 'CANARY' AND (



    clock_timestamp() < v_feature.starts_at



    OR clock_timestamp() >= v_feature.ends_at



  ) THEN



    RAISE EXCEPTION 'Cửa sổ canary đã đóng trước khi hoàn tất'



      USING ERRCODE = '55000';



  END IF;







  -- =========================================================================



  -- T3 CLAIM (A.2 integration point): after construction + invariants +



  -- canary time recheck; before audit append and operation completion.



  -- A.9 smallest-shape: this wrapper is SECURITY DEFINER owned by postgres (so



  -- auth access + INVOKER triggers resolve on Supabase). Capability is proven by



  -- a transaction-local token stamped by a postgres-owned DEFINER setter that no



  -- app role can call, then echoed to the claim. (Replaces the unreachable



  -- current_user='ie_canonical_writer' gate — see t3_12.)



  -- =========================================================================



  v_claim_cap := app_private.grant_ie_claim_capability_v1();



  PERFORM app_private.claim_canonical_income_expense_draft_v1(



    v_row.id, v_idempotency_key, v_claim_cap);



  SELECT * INTO v_row FROM public.income_expenses WHERE id = v_row.id;







  -- A.5: canonical audit goes through the single hash-chain primitive; the



  -- audit-log writer-monopoly guard rejects any direct unchained INSERT.



  PERFORM app_private.append_income_expense_event_v1(



    v_org, v_row.id, 'CREATED_DRAFT', v_actor, v_actor_name,



    NULL, v_birth_status,
    CASE WHEN v_birth_status = 'APPROVED'
         THEN 'Tạo phiếu TỰ DUYỆT (ngoài hạng mục đặc biệt, dưới ngưỡng)'
         ELSE 'Tạo phiếu NHÁP chờ duyệt (hạng mục đặc biệt hoặc chi vượt ngưỡng)' END);







  UPDATE app_private.canonical_write_operations



     SET subject_id = v_row.id,



         response_payload = to_jsonb(v_row),



         completed_at = now()



   WHERE organization_id = v_org



     AND operation = 'income_expense.create_draft.v1'



     AND subject_scope = p_building_id::text



     AND actor_id = v_actor



     AND idempotency_key = v_idempotency_key;







  RETURN v_row;



END;



$_$;








--
-- Name: FUNCTION create_income_expense_v1(p_type text, p_name text, p_building_id uuid, p_room_id uuid, p_tenant_id uuid, p_contract_id uuid, p_payer_name text, p_receive_bank_account text, p_receive_bank_name text, p_account_id uuid, p_attachments jsonb, p_business_result_accounting boolean, p_notes text, p_voucher_date date, p_items jsonb, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_income_expense_v1(p_type text, p_name text, p_building_id uuid, p_room_id uuid, p_tenant_id uuid, p_contract_id uuid, p_payer_name text, p_receive_bank_account text, p_receive_bank_name text, p_account_id uuid, p_attachments jsonb, p_business_result_accounting boolean, p_notes text, p_voucher_date date, p_items jsonb, p_idempotency_key text) IS 'BLOCKED design artifact for manually-entered, non-recurring, non-deposit UNAPPROVED income/expense drafts. Local nullable-account, generic trigger sequencing, tenant-only authority, validation, and claim-before-admission fixes are not activation evidence. Canonical T2 resolver/cashbook possession, a T3 canonical-draft marker plus legacy-transition containment, immutable replay semantics, rollout governance, and durable audit remain prerequisites. Keep OFF, revoked, unrouted, and unapplied.';








--
-- Name: create_income_expense_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_income_expense_v2(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid;
  v_mid uuid;
  v_org uuid;
  v_building uuid := (payload->>'buildingId')::uuid;
  v_type text := payload->>'type';
  v_name text := payload->>'name';
  v_vdate date := (payload->>'voucherDate')::date;
  v_total numeric(18,2) := COALESCE((payload->>'totalAmount')::numeric, 0);
  v_notes text := payload->>'notes';
  v_payer text := payload->>'payerName';
  v_mode text := COALESCE(payload->>'postingMode', 'CASHBOOK');
  v_cashbook uuid := (payload->>'cashbookId')::uuid;
  v_idem text := payload->>'idempotencyKey';
  v_hash text := md5(payload::text);
  v_posting_status text;
  v_is_custodian boolean;
  v_is_knower boolean;
  v_keys text[] := ARRAY['cashbooks.post','income_expenses.create',
                         'income_expenses.reverse','income_expenses.cancel'];
  v_voucher_id uuid := gen_random_uuid();
  v_birth_op uuid := gen_random_uuid();
  v_counts boolean;
  v_kqkd numeric;
  v_recog date;
  v_op app_private.canonical_write_operations;
  v_item jsonb;
  v_class text;
  v_resp jsonb;
BEGIN
  IF v_building IS NULL THEN
    RAISE EXCEPTION 'create_income_expense_v2: buildingId is required' USING ERRCODE = '22023';
  END IF;
  IF v_type NOT IN ('INCOME','EXPENSE') THEN
    RAISE EXCEPTION 'create_income_expense_v2: type must be INCOME or EXPENSE' USING ERRCODE = '22023';
  END IF;
  IF v_name IS NULL OR length(btrim(v_name)) = 0 THEN
    RAISE EXCEPTION 'create_income_expense_v2: name is required' USING ERRCODE = '22023';
  END IF;
  IF v_vdate IS NULL THEN
    RAISE EXCEPTION 'create_income_expense_v2: voucherDate is required' USING ERRCODE = '22023';
  END IF;
  IF v_total <= 0 THEN
    RAISE EXCEPTION 'create_income_expense_v2: totalAmount must be positive' USING ERRCODE = '22023';
  END IF;
  IF v_mode NOT IN ('CASHBOOK','NON_CASH') THEN
    RAISE EXCEPTION 'create_income_expense_v2: postingMode must be CASHBOOK or NON_CASH' USING ERRCODE = '22023';
  END IF;
  IF v_idem IS NULL OR length(v_idem) = 0 THEN
    RAISE EXCEPTION 'create_income_expense_v2: idempotencyKey is required' USING ERRCODE = '22023';
  END IF;

  -- Resolve tenant from the building, then the actor's active membership.
  SELECT b.organization_id INTO v_org
  FROM public.buildings b WHERE b.id = v_building;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'create_income_expense_v2: building % not found', v_building USING ERRCODE = '42501';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid
  FROM app_private.resolve_finance_actor_v2(v_org) r;

  -- Idempotency reservation (subject_scope = building; subject_id filled on completion).
  v_op := app_private.finance_v2_begin_canonical_op(
    v_org, 'income_expense.create.v2', v_building::text, v_uid, v_mid, v_idem, v_hash, NULL);
  IF v_op.completed_at IS NOT NULL THEN
    RETURN COALESCE(v_op.response_payload, '{}'::jsonb);
  END IF;

  v_posting_status := CASE WHEN v_mode = 'CASHBOOK' THEN 'UNPOSTED' ELSE 'NOT_APPLICABLE' END;

  -- Possession-derived create permission (CASHBOOK mode only).
  IF v_mode = 'CASHBOOK' THEN
    IF v_cashbook IS NULL THEN
      RAISE EXCEPTION 'create_income_expense_v2: cashbookId is required for a CASHBOOK voucher' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.accounts a
                   WHERE a.id = v_cashbook AND a.organization_id = v_org AND a.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'create_income_expense_v2: cashbook % not found', v_cashbook USING ERRCODE = '42501';
    END IF;
    IF app_private.finance_v2_has_covering_deny(v_org, v_mid, v_cashbook, v_keys) THEN
      RAISE EXCEPTION 'create_income_expense_v2: create denied by covering DENY on cashbook %', v_cashbook USING ERRCODE = '42501';
    END IF;
    v_is_custodian := EXISTS (
      SELECT 1 FROM public.cashbook_possession_bindings b
      WHERE b.organization_id = v_org AND b.cashbook_id = v_cashbook AND b.membership_id = v_mid
        AND b.possession_kind = 'CUSTODIAN' AND b.valid_from <= now()
        AND (b.valid_to IS NULL OR b.valid_to > now()));
    v_is_knower := EXISTS (
      SELECT 1 FROM public.cashbook_possession_bindings b
      WHERE b.organization_id = v_org AND b.cashbook_id = v_cashbook AND b.membership_id = v_mid
        AND b.possession_kind = 'KNOWER' AND b.valid_from <= now()
        AND (b.valid_to IS NULL OR b.valid_to > now()));
    IF v_type = 'EXPENSE' AND NOT v_is_custodian THEN
      RAISE EXCEPTION 'create_income_expense_v2: only a CUSTODIAN may create an EXPENSE on cashbook %', v_cashbook USING ERRCODE = '42501';
    END IF;
    IF v_type = 'INCOME' AND NOT (v_is_custodian OR v_is_knower) THEN
      RAISE EXCEPTION 'create_income_expense_v2: CUSTODIAN or KNOWER possession required to create INCOME on cashbook %', v_cashbook USING ERRCODE = '42501';
    END IF;
  ELSE
    -- NON_CASH manual obligation requires the plain create capability at the building.
    IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(v_uid, v_org, 'income_expenses.create', v_building, NULL)) THEN
      RAISE EXCEPTION 'create_income_expense_v2: income_expenses.create required for a NON_CASH voucher' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Birth the header UNAPPROVED / PENDING, server-owned provenance. Never accept
  -- approved_*/posting/payment fields from the client payload.
  INSERT INTO public.income_expenses (
    id, user_id, type, name, building_id, room_id, tenant_id, voucher_date,
    total_amount, approval_status, notes, payer_name, account_id, organization_id,
    posting_mode, posting_status, review_state, review_version, approval_version,
    posting_version, maker_user_id, maker_membership_id, birth_operation_id,
    birth_txid, source_payload_hash, counts_in_business_result, kqkd_amount,
    recognition_date, recognition_source_mode
  ) VALUES (
    v_voucher_id, v_uid, v_type, v_name, v_building,
    (payload->>'roomId')::uuid, (payload->>'tenantId')::uuid, v_vdate,
    v_total, 'UNAPPROVED', v_notes, v_payer,
    CASE WHEN v_mode = 'CASHBOOK' THEN v_cashbook ELSE NULL END, v_org,
    v_mode, v_posting_status, 'PENDING', 1, 1,
    1, v_uid, v_mid, v_birth_op,
    pg_current_xact_id(), v_hash, true, 0,
    v_vdate, 'BASE'
  );

  -- Items (server classifies accounting_class; default PNL).
  IF jsonb_typeof(payload->'items') = 'array' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP
      v_class := COALESCE(v_item->>'accountingClass', 'PNL');
      IF v_class NOT IN ('PNL','INTERNAL','CUSTOMER_CREDIT','DEPOSIT') THEN
        RAISE EXCEPTION 'create_income_expense_v2: invalid accountingClass %', v_class USING ERRCODE = '22023';
      END IF;
      IF (v_item->>'typeId') IS NULL THEN
        RAISE EXCEPTION 'create_income_expense_v2: each item requires typeId' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.income_expense_items (
        id, income_expense_id, income_expense_type_id, description, quantity,
        unit_price, amount, notes, start_date, end_date, organization_id, accounting_class
      ) VALUES (
        gen_random_uuid(), v_voucher_id, (v_item->>'typeId')::uuid, v_item->>'description',
        COALESCE((v_item->>'quantity')::integer, 1), COALESCE((v_item->>'unitPrice')::numeric, 0),
        COALESCE((v_item->>'amount')::numeric, 0), v_item->>'notes',
        (v_item->>'startDate')::date, (v_item->>'endDate')::date, v_org, v_class
      );
    END LOOP;
  END IF;

  -- Server-owned business result (refresh header from resolver).
  SELECT br.counts, br.kqkd, br.recognition_date INTO v_counts, v_kqkd, v_recog
  FROM app_private.resolve_business_result_v2(v_voucher_id) br;
  UPDATE public.income_expenses
     SET counts_in_business_result = v_counts, kqkd_amount = v_kqkd, recognition_date = v_recog
   WHERE id = v_voucher_id;

  v_resp := jsonb_build_object(
    'voucherId', v_voucher_id, 'approvalStatus', 'UNAPPROVED',
    'reviewState', 'PENDING', 'postingMode', v_mode, 'postingStatus', v_posting_status,
    'reviewVersion', 1, 'approvalVersion', 1, 'postingVersion', 1);

  PERFORM app_private.finance_v2_finish_canonical_op(
    v_org, 'income_expense.create.v2', v_building::text, v_uid, v_idem, v_voucher_id,
    v_resp, 'CREATED', 1, 1, 1);
  PERFORM app_private.finance_v2_log_event(v_org, 'income_expense.create.v2', v_voucher_id, v_uid, v_idem);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION create_income_expense_v2(payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_income_expense_v2(payload jsonb) IS 'Plan §7.2: create a manual voucher (UNAPPROVED/PENDING, posting_status per mode), server-owned maker + birth provenance.';








--
-- Name: create_invoice_refund_obligation_v2(uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_refund_obligation_v2(p_invoice_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_refund_class text DEFAULT 'REFUND_CONTRA_REVENUE'::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid; v_building uuid; v_actor record; v_result jsonb;
BEGIN
  SELECT i.organization_id, i.building_id INTO v_org, v_building
  FROM public.invoices i WHERE i.id = p_invoice_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Invoice không tồn tại' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_org);
  IF v_actor.membership_id IS NULL THEN
    RAISE EXCEPTION 'Không có membership active trong organization invoice' USING ERRCODE='42501';
  END IF;
  v_result := app_private.reserve_invoice_refund_obligation_v2(
    v_org, p_invoice_id, v_building, p_amount, p_refund_class, 'invoice.refund',
    v_actor.user_id, v_actor.membership_id,
    COALESCE(p_idempotency_key, 'refund:' || p_invoice_id::text || ':' || md5(p_amount::text || COALESCE(p_reason,''))));
  IF p_reason IS NOT NULL AND (v_result ? 'voucher_id') THEN
    UPDATE public.income_expenses SET notes = COALESCE(notes,'') || E'\n[Lý do hoàn] ' || p_reason
    WHERE id = (v_result->>'voucher_id')::uuid;
  END IF;
  RETURN v_result;
END
$$;








--
-- Name: create_invoice_v1(uuid, uuid, uuid, text, date, date, text, numeric, numeric, numeric, numeric, jsonb, text, numeric, text, boolean, jsonb, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_v1(p_contract_id uuid, p_building_id uuid, p_room_id uuid, p_billing_month text, p_issue_date date, p_due_date date, p_kind text, p_subtotal numeric, p_discount_amount numeric, p_total_amount numeric, p_previous_debt numeric, p_items jsonb, p_idempotency_key text, p_prepaid_amount numeric DEFAULT 0, p_discount_notes text DEFAULT NULL::text, p_electricity_prev_overridden boolean DEFAULT false, p_previous_debt_sources jsonb DEFAULT '[]'::jsonb, p_template_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_applied_credit numeric DEFAULT 0, p_creator_name text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_authz boolean;
  v_auto boolean;
  v_status text;
  v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  v_invoice uuid;
  v_invoice_number text;
  v_resp json;
  it jsonb; v_idx int := 0;
  v_total_calc numeric(15,2);
  v_applied numeric(15,2);
  c_op constant text := 'invoice.create.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if char_length(v_key) < 8 or char_length(v_key) > 200
     or v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_total_amount is null or p_total_amount < 0 then raise exception 'Tổng tiền không hợp lệ'; end if;
  if p_items is not null and jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items phải là JSON array'; end if;

  -- derive + lock: building → org; contract same-org; room same-building/org.
  select b.organization_id into v_org from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.id=p_building_id and b.deleted_at is null for share of o,b;
  if not found or v_org is null then
    raise exception 'Toà nhà không thuộc tổ chức đang hoạt động' using errcode='42501'; end if;
  -- contracts link to a building via their room, not a direct building_id column.
  perform 1 from public.contracts c where c.id=p_contract_id and c.deleted_at is null
    and c.organization_id=v_org for share;
  if not found then raise exception 'Hợp đồng không thuộc tổ chức' using errcode='42501'; end if;
  if p_room_id is not null then
    perform 1 from public.rooms r where r.id=p_room_id and r.deleted_at is null
      and r.building_id=p_building_id and r.organization_id=v_org for share;
    if not found then raise exception 'Phòng không thuộc toà/tổ chức' using errcode='42501'; end if;
  end if;

  -- exact permission invoices.create, building-scoped.
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'invoices.create', p_building_id, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền tạo hoá đơn (invoices.create)' using errcode='42501'; end if;

  -- server decides APPROVED vs DRAFT from org settings; missing row = abort.
  select auto_approve_invoice into v_auto from public.organization_invoice_settings
   where organization_id = v_org;
  if v_auto is null then
    raise exception 'Thiếu cấu hình auto_approve_invoice cho tổ chức' using errcode='55000'; end if;
  v_status := case when v_auto then 'APPROVED' else 'DRAFT' end;

  v_hash := md5(jsonb_build_object('contract',p_contract_id,'month',p_billing_month,
    'total',p_total_amount,'org',v_org)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_contract_id::text || '|' || p_billing_month, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op
     and o.subject_scope=p_contract_id::text || '|' || p_billing_month
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then
    raise exception 'Writer hoá đơn chưa bật cho tổ chức này' using errcode='55000'; end if;

  -- ---- PARITY: làm tròn server mirror roundInvoiceTotal + ASSERT khớp total ----
  -- total = round(p_subtotal − discount + nợ cũ) TRÊN SUBTOTAL CLIENT GỬI (KHÔNG
  -- re-sum items — giữ giả định item-shape của mọi caller, gồm create_contract_v1).
  -- KHÔNG clamp ≥0 (mirror useCreateInvoice; KHÁC clamp hiển thị Math.max(0,…) của
  -- GenerateInvoiceDialog). Guard p_total_amount<0 ở trên vẫn chặn tổng âm.
  v_total_calc := app_private.round_invoice_total_v1(
    coalesce(p_subtotal,0) - coalesce(p_discount_amount,0) + coalesce(p_previous_debt,0));

  if v_total_calc is distinct from p_total_amount then
    raise exception
      'Tổng tiền client (%) khác tổng server làm tròn (%) [subtotal=%, discount=%, nợ cũ=%]',
      p_total_amount, v_total_calc, coalesce(p_subtotal,0),
      coalesce(p_discount_amount,0), coalesce(p_previous_debt,0)
      using errcode='22000';
  end if;

  -- create the invoice; the live partial-unique (contract_id, billing_month)
  -- WHERE deleted_at IS NULL AND status<>'CANCELLED' AND kind='MONTHLY'
  -- enforces one-per-period. invoice_number BỎ TRỐNG → trigger
  -- generate_invoice_number_v2 (BEFORE INSERT) tự sinh.
  insert into public.invoices
    (user_id, organization_id, contract_id, building_id, room_id, billing_month,
     issue_date, due_date, kind, status, subtotal, discount_amount, discount_notes,
     electricity_prev_overridden, total_amount, prepaid_amount, paid_amount,
     previous_debt, previous_debt_sources, notes, template_id, creator_name,
     approved_by, approved_at)
  values
    (v_actor, v_org, p_contract_id, p_building_id, p_room_id, p_billing_month,
     p_issue_date, p_due_date, coalesce(p_kind,'MONTHLY'), v_status::invoice_status,
     coalesce(p_subtotal,0), coalesce(p_discount_amount,0), p_discount_notes,
     coalesce(p_electricity_prev_overridden,false), p_total_amount,
     coalesce(p_prepaid_amount,0), 0,
     coalesce(p_previous_debt,0),
     coalesce(p_previous_debt_sources,'[]'::jsonb), p_notes, p_template_id,
     p_creator_name,
     case when v_auto then v_actor else null end,
     case when v_auto then now() else null end)
  returning id, invoice_number into v_invoice, v_invoice_number;

  -- ---- PARITY: bước tiêu credit (mirror useCreateInvoice:639-652) ----
  -- Áp credit vào Giảm trừ HĐ → ghi excess_amounts ÂM CÙNG TX. amount đã cộng vào
  -- discount_amount ở client nên KHÔNG trừ 2 lần; row âm chỉ hạ số dư credit HĐ.
  v_applied := coalesce(p_applied_credit,0);
  if v_applied > 0 and p_contract_id is not null then
    insert into public.excess_amounts
      (user_id, organization_id, contract_id, amount, description,
       source_invoice_id, source_payment_id)
    values
      (v_actor, v_org, p_contract_id, -v_applied,
       'Áp credit vào Giảm trừ HĐ ' || coalesce(v_invoice_number, v_invoice::text),
       v_invoice, null);
  end if;

  -- ---- PARITY: items whitelist 12 field client ----
  -- amount = amount client gửi (1 trong 12 field, giữ hành vi writer cũ), fallback
  -- tính unit_price*quantity*coefficient nếu vắng. sort_order lấy client, fallback
  -- thứ tự xuất hiện.
  if p_items is not null then
    for it in select value from jsonb_array_elements(p_items) loop
      v_idx := v_idx + 1;
      insert into public.invoice_items
        (invoice_id, organization_id, service_id, type, description, unit_price,
         quantity, coefficient, amount, previous_reading, current_reading,
         from_date, to_date, sort_order)
      values (
        v_invoice, v_org,
        nullif(it->>'service_id','')::uuid,
        coalesce(nullif(it->>'type','')::invoice_item_type, 'OTHER'::invoice_item_type),
        it->>'description',
        coalesce((it->>'unit_price')::numeric,0),
        coalesce((it->>'quantity')::numeric,1),
        coalesce((it->>'coefficient')::numeric,1),
        coalesce((it->>'amount')::numeric,
          coalesce((it->>'unit_price')::numeric,0)
          * coalesce((it->>'quantity')::numeric,1)
          * coalesce((it->>'coefficient')::numeric,1)),
        nullif(it->>'previous_reading','')::numeric,
        nullif(it->>'current_reading','')::numeric,
        nullif(it->>'from_date','')::date,
        nullif(it->>'to_date','')::date,
        coalesce((it->>'sort_order')::int, v_idx)
      );
    end loop;
  end if;

  v_resp := json_build_object('invoice_id', v_invoice, 'status', v_status,
                              'invoice_number', v_invoice_number);
  update app_private.canonical_write_operations
     set subject_id=v_invoice, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op
     and subject_scope=p_contract_id::text || '|' || p_billing_month
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: create_invoice_with_credit_v1(uuid, uuid, uuid, text, date, date, text, numeric, numeric, numeric, numeric, jsonb, text, numeric, text, boolean, jsonb, uuid, text, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_with_credit_v1(p_contract_id uuid, p_building_id uuid, p_room_id uuid, p_billing_month text, p_issue_date date, p_due_date date, p_kind text, p_subtotal numeric, p_discount_amount numeric, p_total_amount numeric, p_previous_debt numeric, p_items jsonb, p_idempotency_key text, p_prepaid_amount numeric DEFAULT 0, p_discount_notes text DEFAULT NULL::text, p_electricity_prev_overridden boolean DEFAULT false, p_previous_debt_sources jsonb DEFAULT '[]'::jsonb, p_template_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_applied_credit numeric DEFAULT 0, p_non_credit_discount_amount numeric DEFAULT 0, p_creator_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_invoice_result json;
  v_invoice_id uuid;
  v_credit_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF p_applied_credit IS NULL OR p_applied_credit = 'NaN'::numeric
     OR p_applied_credit <= 0
     OR p_applied_credit IS DISTINCT FROM round(p_applied_credit, 2) THEN
    RAISE EXCEPTION 'Applied credit must be positive' USING ERRCODE = '22023';
  END IF;
  IF p_non_credit_discount_amount IS NULL
     OR p_non_credit_discount_amount = 'NaN'::numeric
     OR p_non_credit_discount_amount < 0
     OR p_non_credit_discount_amount IS DISTINCT FROM round(
       p_non_credit_discount_amount, 2
     )
     OR p_discount_amount IS NULL
     OR p_discount_amount IS DISTINCT FROM round(p_discount_amount, 2)
     OR round(p_discount_amount, 2) IS DISTINCT FROM round(
       p_non_credit_discount_amount + p_applied_credit, 2
     ) THEN
    RAISE EXCEPTION
      'Invoice discount must equal non-credit discount plus applied credit'
      USING ERRCODE = '22023';
  END IF;

  IF round(p_applied_credit, 2) > GREATEST(
       round(
         COALESCE(p_subtotal, 0)
         + COALESCE(p_previous_debt, 0)
         - COALESCE(p_non_credit_discount_amount, 0),
         2
       ),
       0
     ) THEN
    RAISE EXCEPTION
      'Applied credit exceeds invoice amount after non-credit discounts'
      USING ERRCODE = '22023';
  END IF;

  v_invoice_result := public.create_invoice_v1(
    p_contract_id, p_building_id, p_room_id, p_billing_month,
    p_issue_date, p_due_date, p_kind, p_subtotal, p_discount_amount,
    p_total_amount, p_previous_debt, p_items, v_key, p_prepaid_amount,
    p_discount_notes, p_electricity_prev_overridden,
    p_previous_debt_sources, p_template_id, p_notes, 0, p_creator_name
  );
  v_invoice_id := NULLIF(v_invoice_result->>'invoice_id', '')::uuid;
  IF v_invoice_id IS NULL THEN
    RAISE EXCEPTION 'create_invoice_v1 returned no invoice_id'
      USING ERRCODE = '55000';
  END IF;

  v_credit_result := app_private.apply_customer_credit_fifo_v1(
    v_actor, p_contract_id, round(p_applied_credit, 2), v_invoice_id,
    'INVOICE_DISCOUNT',
    'Apply customer credit to invoice ' ||
      COALESCE(v_invoice_result->>'invoice_number', v_invoice_id::text),
    v_key
  );

  RETURN to_jsonb(v_invoice_result) || jsonb_build_object('credit', v_credit_result);
END;
$_$;








--
-- Name: create_meter_reading_v1(uuid, date, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_meter_reading_v1(p_meter_id uuid, p_reading_date date, p_current_reading numeric, p_notes text DEFAULT NULL::text, p_meter_image_url text DEFAULT NULL::text) RETURNS public.meter_readings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_meter RECORD;
  v_row public.meter_readings;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_meter_id IS NULL THEN RAISE EXCEPTION 'Thiếu meter_id'; END IF;
  IF p_reading_date IS NULL THEN RAISE EXCEPTION 'Thiếu ngày ghi'; END IF;
  IF p_current_reading IS NULL OR p_current_reading < 0 THEN RAISE EXCEPTION 'Chỉ số không hợp lệ'; END IF;

  SELECT id, building_id, room_id, organization_id INTO v_meter
  FROM public.meters WHERE id = p_meter_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy đồng hồ' USING ERRCODE='42501'; END IF;
  IF v_meter.building_id IS NULL THEN RAISE EXCEPTION 'Đồng hồ chưa gắn toà nhà'; END IF;

  -- Defense-in-depth org boundary: definer bypass RLS nên phải tự kiểm org membership
  -- (mirror policy meter_readings_org_boundary NULL-tolerant) NGOÀI building-RBAC.
  IF NOT (v_meter.organization_id IS NULL
          OR public.is_super_admin()
          OR v_meter.organization_id = ANY(public.my_org_ids())) THEN
    RAISE EXCEPTION 'Đồng hồ thuộc tổ chức khác' USING ERRCODE='42501';
  END IF;
  IF NOT public.can_do_on_building('meter_readings','create', v_meter.building_id) THEN
    RAISE EXCEPTION 'Không có quyền tạo chỉ số cho toà này' USING ERRCODE='42501';
  END IF;

  BEGIN
    INSERT INTO public.meter_readings
      (meter_id, reading_date, current_reading, notes, meter_image_url, status, approved_by, approved_at)
    VALUES
      (p_meter_id, p_reading_date, p_current_reading, p_notes, p_meter_image_url, 'APPROVED', v_caller, now())
    RETURNING * INTO v_row;
  EXCEPTION WHEN check_violation THEN
    RAISE EXCEPTION 'Chỉ số mới không hợp lệ (phải ≥ chỉ số kỳ trước)' USING ERRCODE='23514';
  END;

  RETURN v_row;
END;
$$;








--
-- Name: create_new_contract_extension(uuid, integer, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_new_contract_extension(p_contract_id uuid, p_extension_months integer, p_new_rent_price numeric DEFAULT NULL::numeric, p_new_deposit numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_old_contract public.contracts%ROWTYPE;
  v_new_contract_id uuid;
  v_extension_id uuid;
  v_new_end_date date;
  v_new_start_date date;
  v_building_id uuid;
  v_authz boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_extension_months IS NULL OR p_extension_months <= 0 THEN
    RAISE EXCEPTION 'extension_months must be positive' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_new_rent_price::text, '') IN ('NaN', 'Infinity', '-Infinity')
     OR COALESCE(p_new_deposit::text, '') IN ('NaN', 'Infinity', '-Infinity')
     OR COALESCE(p_new_rent_price, 0) < 0
     OR COALESCE(p_new_deposit, 0) < 0 THEN
    RAISE EXCEPTION 'New rent/deposit is not a finite non-negative amount'
      USING ERRCODE = '22023';
  END IF;

  SELECT contract_row.*
    INTO v_old_contract
  FROM public.contracts contract_row
  JOIN public.rooms room_row ON room_row.id = contract_row.room_id
  JOIN public.organizations org_row
    ON org_row.id = contract_row.organization_id AND org_row.status = 'ACTIVE'
  WHERE contract_row.id = p_contract_id
    AND contract_row.status = 'ACTIVE'
    AND contract_row.deleted_at IS NULL
  FOR UPDATE OF contract_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract not found or not active' USING ERRCODE = '42501';
  END IF;

  SELECT room_row.building_id INTO v_building_id
  FROM public.rooms room_row
  WHERE room_row.id = v_old_contract.room_id
    AND room_row.deleted_at IS NULL
  FOR SHARE;
  IF v_building_id IS NULL THEN
    RAISE EXCEPTION 'Contract room is unavailable' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_old_contract.organization_id);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_old_contract.organization_id, 'contracts.renew', v_building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Not authorized to renew this contract' USING ERRCODE = '42501';
  END IF;

  v_new_start_date := v_old_contract.end_date + 1;
  v_new_end_date := (
    v_new_start_date + (p_extension_months || ' months')::interval - interval '1 day'
  )::date;

  UPDATE public.contracts
     SET status = 'EXPIRED', updated_at = now()
   WHERE id = p_contract_id;

  INSERT INTO public.contracts (
    user_id, organization_id, tenant_id, room_id, contract_number, status,
    signed_date, start_date, end_date, rent_price, payment_cycle,
    total_deposit, deposit_paid, parent_contract_id, notes,
    start_billing_date, end_billing_date, contract_template_id, invoice_template_id
  ) VALUES (
    v_old_contract.user_id, v_old_contract.organization_id, v_old_contract.tenant_id,
    v_old_contract.room_id, NULL, 'ACTIVE', public.org_today_v1(NULL),
    v_new_start_date, v_new_end_date,
    COALESCE(p_new_rent_price, v_old_contract.rent_price),
    v_old_contract.payment_cycle,
    COALESCE(p_new_deposit, v_old_contract.total_deposit),
    LEAST(
      v_old_contract.deposit_paid,
      COALESCE(p_new_deposit, v_old_contract.total_deposit)
    ),
    p_contract_id,
    COALESCE(p_notes, 'Gia hạn từ HĐ: ' || COALESCE(v_old_contract.contract_number, p_contract_id::text)),
    v_new_start_date, v_new_end_date,
    v_old_contract.contract_template_id, v_old_contract.invoice_template_id
  ) RETURNING id INTO v_new_contract_id;

  INSERT INTO public.contract_customers (
    organization_id, contract_id, customer_id, is_representative, notes
  )
  SELECT organization_id, v_new_contract_id, customer_id, is_representative, notes
  FROM public.contract_customers
  WHERE contract_id = p_contract_id;

  INSERT INTO public.contract_services (
    organization_id, contract_id, service_id, unit_price, initial_reading
  )
  SELECT organization_id, v_new_contract_id, service_id, unit_price, initial_reading
  FROM public.contract_services
  WHERE contract_id = p_contract_id;

  INSERT INTO public.contract_extensions (
    user_id, contract_id, extension_type, old_end_date, extension_months,
    new_end_date, new_rent_price, rent_price_changed, new_deposit,
    deposit_changed, new_contract_id, notes, status
  ) VALUES (
    v_actor, p_contract_id, 'CREATE_NEW', v_old_contract.end_date,
    p_extension_months, v_new_end_date, p_new_rent_price,
    p_new_rent_price IS NOT NULL AND p_new_rent_price <> v_old_contract.rent_price,
    p_new_deposit,
    p_new_deposit IS NOT NULL AND p_new_deposit <> v_old_contract.total_deposit,
    v_new_contract_id, p_notes, 'COMPLETED'
  ) RETURNING id INTO v_extension_id;

  RETURN v_new_contract_id;
END;
$$;








--
-- Name: FUNCTION create_new_contract_extension(p_contract_id uuid, p_extension_months integer, p_new_rent_price numeric, p_new_deposit numeric, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_new_contract_extension(p_contract_id uuid, p_extension_months integer, p_new_rent_price numeric, p_new_deposit numeric, p_notes text) IS 'Creates a brand new contract as extension (CREATE_NEW type) - preserves full history';








--
-- Name: org_today_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_today_v1(p_organization_id uuid DEFAULT NULL::uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT (pg_catalog.now() AT TIME ZONE
            app_private.org_timezone_v1(
              COALESCE(
                p_organization_id,
                -- Không truyền org: suy ra từ membership ACTIVE của người gọi.
                -- CỐ Ý để membership THẮNG profiles.organization_id — án lệ đã ghi:
                -- 6/10 profile trỏ SAI org. Nhiều org mà không truyền tham số thì
                -- KHÔNG đoán: `min(...) FILTER (count = 1)` trả NULL ⇒ rơi về mặc
                -- định, chứ không chọn bừa một org.
                -- `min(uuid)` KHÔNG tồn tại trong Postgres ⇒ gộp qua text rồi cast lại.
                (SELECT CASE WHEN count(DISTINCT m.organization_id) = 1
                             THEN min(m.organization_id::text)::uuid END
                   FROM public.organization_memberships m
                  WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE')
              )
            ))::date;
$$;








--
-- Name: FUNCTION org_today_v1(p_organization_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.org_today_v1(p_organization_id uuid) IS '"Hôm nay" theo múi giờ NGHIỆP VỤ của tổ chức — dùng thay CURRENT_DATE. Server chạy UTC nên CURRENT_DATE trả NGÀY HÔM QUA trong 00:00–07:00 giờ VN, tức bảy giờ mỗi ngày; bug đó vô hình nếu chỉ thử vào giờ hành chính. Không truyền org thì suy từ membership ACTIVE duy nhất của người gọi (membership THẮNG profiles.organization_id — 6/10 profile trỏ sai org); nhiều org thì KHÔNG đoán, rơi về mặc định. ⚠ Đợt 1 CHỈ dựng primitive: 36 hàm khác vẫn đang dùng CURRENT_DATE và phải chuyển theo từng nhóm có review, chưa làm.';








--
-- Name: create_opening_adjustment(uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_opening_adjustment(p_account_id uuid, p_counted_balance numeric, p_as_of date DEFAULT public.org_today_v1(NULL::uuid)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc        accounts%ROWTYPE;
  v_system     numeric;
  v_diff       numeric;
  v_type_id    uuid;
  v_voucher_id uuid;
  v_kind       text;
BEGIN
  SELECT * INTO v_acc FROM accounts WHERE id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy sổ quỹ';
  END IF;
  IF v_acc.user_id <> auth.uid() AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Bạn không có quyền chốt sổ này';
  END IF;
  IF COALESCE(v_acc.is_virtual, FALSE) THEN
    RAISE EXCEPTION 'Sổ theo dõi (ảo) không kiểm kê tiền thật — không cần điều chỉnh';
  END IF;
  IF p_as_of > public.org_today_v1(NULL) THEN
    RAISE EXCEPTION 'Ngày chốt không được ở tương lai';
  END IF;
  IF v_acc.lock_date IS NOT NULL AND v_acc.lock_date > p_as_of THEN
    RAISE EXCEPTION 'Sổ đã khoá tới % — không thể chốt lùi về %',
      v_acc.lock_date, p_as_of;
  END IF;

  SELECT current_amount INTO v_system
  FROM accounts_with_balance WHERE id = p_account_id;
  v_diff := COALESCE(p_counted_balance, 0) - COALESCE(v_system, 0);

  IF abs(v_diff) >= 1 THEN
    -- Trigger khoá sổ chặn phiếu có ngày ≤ lock_date — phiếu điều chỉnh ngày D
    -- chính là ngày khoá, nên TẠM GỠ lock trong transaction (row đã FOR UPDATE)
    -- rồi khoá lại ở cuối. Chốt lại lần 2 cùng ngày cũng đi đường này.
    IF v_acc.lock_date IS NOT NULL THEN
      UPDATE accounts SET lock_date = NULL WHERE id = p_account_id;
    END IF;
    v_kind := CASE WHEN v_diff > 0 THEN 'income' ELSE 'expense' END;
    -- Hạng mục "Điều chỉnh số dư" (get-or-create) — ẩn khỏi báo cáo P&L.
    v_type_id := public._termination_ensure_type(
      v_acc.user_id, v_kind, 'Điều chỉnh số dư');
    UPDATE income_expense_types
       SET hide_in_report = TRUE
     WHERE id = v_type_id AND hide_in_report IS DISTINCT FROM TRUE;

    INSERT INTO income_expenses (
      user_id, type, name, building_id, account_id, voucher_date,
      total_amount, approval_status, business_result_accounting,
      system_source, notes
    ) VALUES (
      v_acc.user_id,
      CASE WHEN v_diff > 0 THEN 'INCOME' ELSE 'EXPENSE' END,
      'Điều chỉnh số dư đầu kỳ — ' || v_acc.name || ' (kiểm kê ' ||
        to_char(p_as_of, 'DD/MM/YYYY') || ')',
      public._chung_building(v_acc.user_id),
      p_account_id,
      p_as_of,
      abs(v_diff),
      'APPROVED',
      FALSE,  -- ép ngoài-KQKD: kqkd_amount = 0, không lọt Phân bổ LN
      'adjustment.opening_balance',
      '[ĐIỀU CHỈNH SỐ DƯ ĐẦU KỲ] Đếm thực tế ' || p_counted_balance ||
        ' − hệ thống ' || COALESCE(v_system, 0) || ' = ' || v_diff ||
        '. Kiểm kê ngày ' || to_char(p_as_of, 'DD/MM/YYYY') ||
        ' theo quy trình chuẩn hoá két (không tính vào lợi nhuận).'
    ) RETURNING id INTO v_voucher_id;

    INSERT INTO income_expense_items (
      income_expense_id, income_expense_type_id, description,
      quantity, unit_price
    ) VALUES (
      v_voucher_id, v_type_id,
      'Chênh lệch kiểm kê ' || to_char(p_as_of, 'DD/MM/YYYY'),
      1, abs(v_diff)
    );
  END IF;

  UPDATE accounts SET lock_date = p_as_of WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'account_id', p_account_id,
    'system_balance', COALESCE(v_system, 0),
    'counted_balance', COALESCE(p_counted_balance, 0),
    'diff', v_diff,
    'voucher_id', v_voucher_id,
    'locked_to', p_as_of
  );
END;
$$;








--
-- Name: create_profit_payout_compat_v1(text, uuid, numeric, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_profit_payout_compat_v1(p_target_kind text, p_target_id uuid, p_amount numeric, p_account_id uuid, p_voucher_date date, p_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_kind text := upper(btrim(COALESCE(p_target_kind, '')));
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_org uuid;
  v_building uuid;
  v_owner uuid;
  v_subject_name text;
  v_permission text;
  v_operation_name text;
  v_type_name text;
  v_category text := 'Chia lợi nhuận';
  v_system_source text;
  v_authz boolean;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_type uuid;
  v_voucher uuid;
  v_voucher_name text;
  v_response jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF v_kind NOT IN ('SHAREHOLDER', 'MANAGER') THEN
    RAISE EXCEPTION 'Unsupported profit payout target' USING ERRCODE = '22023';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency key' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount = 'NaN'::numeric
     OR p_amount <= 0 OR round(p_amount, 2) <> p_amount THEN
    RAISE EXCEPTION 'Invalid payout amount' USING ERRCODE = '22023';
  END IF;
  IF p_account_id IS NULL OR p_voucher_date IS NULL THEN
    RAISE EXCEPTION 'Payout account and date are required' USING ERRCODE = '22023';
  END IF;

  IF v_kind = 'SHAREHOLDER' THEN
    SELECT target.organization_id,
           COALESCE(NULLIF(btrim(target.name), ''), 'Cổ đông')
      INTO v_org, v_subject_name
    FROM public.shareholders target
    WHERE target.id = p_target_id
      AND target.deleted_at IS NULL
      AND target.is_active
    FOR SHARE;
    v_permission := 'shareholder_profit.distribute';
    v_operation_name := 'shareholder_profit.distribute.compat.v1';
    v_type_name := 'Chia lợi nhuận cổ đông';
    v_system_source := 'profit.distribution';
  ELSE
    SELECT target.organization_id,
           COALESCE(NULLIF(btrim(target.name), ''), 'Quản lý')
      INTO v_org, v_subject_name
    FROM public.profit_managers target
    WHERE target.id = p_target_id
      AND target.deleted_at IS NULL
      AND target.is_active
    FOR SHARE;
    v_permission := 'shareholder_profit.pay_manager';
    v_operation_name := 'shareholder_profit.pay_manager.compat.v1';
    v_type_name := 'Lương điều hành';
    v_system_source := 'profit.manager_salary';
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Payout target does not belong to an active organization'
      USING ERRCODE = '42501';
  END IF;

  SELECT building_row.id, building_row.user_id
    INTO v_building, v_owner
  FROM public.buildings building_row
  JOIN public.organizations organization_row
    ON organization_row.id = building_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE building_row.organization_id = v_org
    AND building_row.is_virtual
    AND building_row.deleted_at IS NULL
  ORDER BY building_row.created_at, building_row.id
  LIMIT 1
  FOR SHARE OF building_row, organization_row;
  IF v_building IS NULL OR v_owner IS NULL THEN
    RAISE EXCEPTION 'Organization has no virtual accounting building'
      USING ERRCODE = '55000';
  END IF;

  PERFORM 1
  FROM public.accounts account_row
  WHERE account_row.id = p_account_id
    AND account_row.organization_id = v_org
    AND account_row.deleted_at IS NULL
    AND NOT account_row.is_virtual
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payout account must be real and in the same organization'
      USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, v_permission, v_building, p_account_id
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Not authorized to create this payout'
      USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'target_kind', v_kind,
    'target_id', p_target_id,
    'amount', round(p_amount, 2),
    'account_id', p_account_id,
    'voucher_date', p_voucher_date,
    'note', NULLIF(btrim(COALESCE(p_note, '')), ''),
    'organization_id', v_org
  )::text);
  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, v_operation_name, v_kind || ':' || p_target_id::text,
    v_actor, v_key, v_hash
  )
  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
  DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = v_operation_name
    AND operation_row.subject_scope = v_kind || ':' || p_target_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'Idempotency key reused with a different payout payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('profit-payout-type:' || v_org::text, 0)
  );

  SELECT COALESCE(
           NULLIF(btrim(profile.full_name), ''),
           NULLIF(btrim(profile.email), ''),
           'Người dùng'
         )
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_actor;

  SELECT type_row.id INTO v_type
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'expense'
    AND lower(btrim(type_row.name)) = lower(v_type_name)
  ORDER BY type_row.created_at, type_row.id
  LIMIT 1;
  IF v_type IS NULL THEN
    INSERT INTO public.income_expense_types (
      user_id, organization_id, name, type, category,
      is_default, is_deposit, description
    ) VALUES (
      v_owner, v_org, v_type_name, 'expense', v_category,
      false, false, 'Legacy-compatible profit payout; excluded from P&L'
    ) RETURNING id INTO v_type;
  END IF;

  v_voucher_name := COALESCE(
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    CASE WHEN v_kind = 'SHAREHOLDER'
      THEN 'Chia lợi nhuận: ' || v_subject_name
      ELSE 'Lương điều hành: ' || v_subject_name
    END
  );

  PERFORM app_private.begin_accounting_chain_write_v1();
  INSERT INTO public.income_expenses (
    user_id, organization_id, creator_name, type, name,
    building_id, account_id, shareholder_id, profit_manager_id,
    business_result_accounting, approval_status, voucher_date,
    attachments, repeat_cycle, repeat_infinity, repeat_count, repeat_remaining,
    source_payload_hash, system_source, idempotency_key
  ) VALUES (
    v_owner, v_org, COALESCE(v_actor_name, 'Người dùng'), 'EXPENSE', v_voucher_name,
    v_building, p_account_id,
    CASE WHEN v_kind = 'SHAREHOLDER' THEN p_target_id ELSE NULL END,
    CASE WHEN v_kind = 'MANAGER' THEN p_target_id ELSE NULL END,
    false, 'UNAPPROVED', p_voucher_date,
    '[]'::jsonb, 'NONE', false, 0, 0,
    v_hash, v_system_source, v_key
  ) RETURNING id INTO v_voucher;

  INSERT INTO public.income_expense_items (
    income_expense_id, organization_id, income_expense_type_id,
    description, quantity, unit_price, amount, start_date, end_date,
    accounting_class
  ) VALUES (
    v_voucher, v_org, v_type,
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    1, round(p_amount, 2), round(p_amount, 2),
    p_voucher_date, p_voucher_date, 'INTERNAL'
  );
  PERFORM public.recompute_ie_business_result(v_voucher);
  PERFORM app_private.end_accounting_chain_write_v1();

  v_response := jsonb_build_object(
    'voucher_id', v_voucher,
    'target_kind', v_kind,
    'target_id', p_target_id,
    'state', 'UNAPPROVED'
  );
  UPDATE app_private.canonical_write_operations
     SET subject_id = v_voucher,
         response_payload = v_response,
         completed_at = clock_timestamp()
   WHERE organization_id = v_org
     AND operation = v_operation_name
     AND subject_scope = v_kind || ':' || p_target_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;
  RETURN v_response;
END;
$_$;








--
-- Name: public_room_share_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.public_room_share_tokens (
    token text NOT NULL,
    owner_id uuid NOT NULL,
    label text,
    revoked boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid
);








--
-- Name: TABLE public_room_share_tokens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.public_room_share_tokens IS 'Token chia s? c�ng khai cho trang "Ph�ng tr?ng" (/r/:token). owner_id = ch? data
du?c l? ra (ch? ph�a server, KH�NG g?i ra client). revoked=true d? thu h?i link.
B� danh c�ng owner du?c ph�p: "demo" v� "dsphongtrong" tr? chung m?t d? li?u.';








--
-- Name: create_public_room_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_public_room_token(p_label text DEFAULT NULL::text) RETURNS public.public_room_share_tokens
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner     uuid := auth.uid();
  candidate   text;
  tries       int := 0;
  v_row       public.public_room_share_tokens;
BEGIN
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Không xác định được người dùng (auth.uid is null)';
  END IF;

  LOOP
    candidate := public.gen_contract_public_code(6);
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.public_room_share_tokens WHERE token = candidate
    );
    tries := tries + 1;
    IF tries >= 10 THEN
      candidate := public.gen_contract_public_code(8);
      EXIT;
    END IF;
  END LOOP;

  INSERT INTO public.public_room_share_tokens (token, owner_id, label)
  VALUES (candidate, v_owner, NULLIF(btrim(coalesce(p_label, '')), ''))
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;








--
-- Name: FUNCTION create_public_room_token(p_label text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_public_room_token(p_label text) IS 'Tạo 1 token chia sẻ /r/:token cho owner hiện tại (auth.uid). Mã base-57 6 ký tự
(retry chống trùng, bump 8). Trả về dòng vừa tạo. Chỉ authenticated gọi được.';








--
-- Name: create_reservation_deposit_v1(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_reservation_deposit_v1(p_room_id uuid, p_amount numeric, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_building uuid;
  v_authz boolean; v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype; v_route text;
  v_hold uuid; v_resp json;
  c_op constant text := 'deposit.hold.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_amount is null or p_amount <= 0 or round(p_amount,2) <> p_amount then
    raise exception 'Số tiền cọc không hợp lệ'; end if;

  -- room → building → org; lock the room FOR NO KEY UPDATE (avoid the reconcile
  -- lock-upgrade deadlock).
  select r.building_id into v_building from public.rooms r
   where r.id=p_room_id and r.deleted_at is null for no key update;
  if not found then raise exception 'Không tìm thấy phòng' using errcode='42501'; end if;
  select b.organization_id into v_org from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.id=v_building and b.deleted_at is null for share of o,b;
  if v_org is null then raise exception 'Toà nhà không thuộc tổ chức đang hoạt động' using errcode='42501'; end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'deposits.create', v_building, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền đặt cọc giữ chỗ (deposits.create)' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object('room',p_room_id,'org',v_org,'amount',p_amount)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_room_id::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_room_id::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer cọc giữ chỗ chưa bật' using errcode='55000'; end if;

  -- the exclusion constraint enforces no-double-hold; a concurrent live hold on
  -- the same room raises 23P01 (exclusion_violation) → surface as "đã có cọc giữ".
  begin
    insert into public.room_reservation_holds
      (organization_id, building_id, room_id, amount, held_by, expires_at)
    values (v_org, v_building, p_room_id, p_amount, v_actor,
            clock_timestamp() + interval '24 hours')
    returning id into v_hold;
  exception when exclusion_violation then
    raise exception 'Phòng đang có cọc giữ chỗ còn hiệu lực' using errcode='55000';
  end;

  v_resp := json_build_object('hold_id', v_hold, 'room_id', p_room_id,
    'expires_at', (clock_timestamp() + interval '24 hours'));
  update app_private.canonical_write_operations
     set subject_id=v_hold, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op and subject_scope=p_room_id::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: create_sale_bonus_from_deposit_v1(uuid, numeric, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sale_bonus_from_deposit_v1(p_deposit_voucher_id uuid, p_amount numeric, p_recipient text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_bank text DEFAULT NULL::text, p_voucher_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_dep   public.income_expenses;
  v_org   uuid;
  v_bld   uuid;
  v_room  uuid;
  v_cap   numeric;
  v_type  uuid;
  v_ie    uuid;
  v_code  text;
  v_exist uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Số tiền thưởng phải lớn hơn 0' USING ERRCODE = '22023';
  END IF;

  -- Khoá phiếu cọc: hai người cùng bấm thưởng cho một phiếu cọc phải xếp hàng.
  SELECT * INTO v_dep FROM public.income_expenses
   WHERE id = p_deposit_voucher_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu cọc' USING ERRCODE = 'P0002';
  END IF;
  IF v_dep.deleted_at IS NOT NULL OR v_dep.approval_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Phiếu cọc đã huỷ — không thưởng được' USING ERRCODE = '55000';
  END IF;
  IF v_dep.type IS DISTINCT FROM 'INCOME' THEN
    RAISE EXCEPTION 'Phiếu này không phải phiếu thu cọc' USING ERRCODE = '22023';
  END IF;

  v_org  := v_dep.organization_id;
  v_bld  := v_dep.building_id;
  v_room := v_dep.room_id;

  IF NOT (public.can_access_building(v_bld) OR public.ie_all_buildings_scope(v_bld)
       OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền tạo phiếu trên toà này' USING ERRCODE = '42501';
  END IF;

  -- ══ CHỐNG CHI TRÙNG — hai hướng ═══════════════════════════════════
  -- (a) Chính phiếu cọc này đã thưởng chưa.
  SELECT sbc.bonus_voucher_id INTO v_exist
    FROM app_private.sale_bonus_claims sbc
    JOIN public.income_expenses bon ON bon.id = sbc.bonus_voucher_id
   WHERE sbc.deposit_voucher_id = p_deposit_voucher_id
     AND bon.deleted_at IS NULL AND bon.approval_status <> 'CANCELLED';
  IF v_exist IS NOT NULL THEN
    SELECT code INTO v_code FROM public.income_expenses WHERE id = v_exist;
    RAISE EXCEPTION 'Phiếu cọc này đã được thưởng Sale rồi (phiếu %)', COALESCE(v_code, v_exist::text)
      USING ERRCODE = 'P0001';
  END IF;

  -- (b) Phiếu cọc đã gắn hợp đồng, mà hợp đồng đó đã thưởng qua đường khác.
  IF v_dep.contract_id IS NOT NULL THEN
    SELECT ie.id INTO v_exist FROM public.income_expenses ie
     WHERE ie.contract_id = v_dep.contract_id AND ie.commission_kind = 'sale'
       AND ie.deleted_at IS NULL AND ie.approval_status <> 'CANCELLED'
       AND NOT COALESCE(ie.commission_legacy_dup, false)
     LIMIT 1;
    IF v_exist IS NOT NULL THEN
      SELECT code INTO v_code FROM public.income_expenses WHERE id = v_exist;
      RAISE EXCEPTION 'Hợp đồng của phiếu cọc này đã được thưởng Sale rồi (phiếu %)',
        COALESCE(v_code, v_exist::text) USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- ══ TRẦN — chỉ áp khi chủ đã công bố ══════════════════════════════
  v_cap := app_private.sale_bonus_cap_for_v1(v_org, v_bld, public.org_today_v1(v_org));
  IF v_cap IS NOT NULL AND p_amount > v_cap THEN
    RAISE EXCEPTION
      'Thưởng % vượt trần % của toà này. Muốn chi cao hơn thì chủ phải nâng trần ở Cài đặt.',
      replace(to_char(round(p_amount), 'FM999G999G999G999'), ',', '.') || 'đ',
      replace(to_char(round(v_cap),   'FM999G999G999G999'), ',', '.') || 'đ'
      USING ERRCODE = '55000';
  END IF;

  v_type := app_private.ensure_income_expense_type_v1(
              v_org, v_actor, 'Thưởng nóng Sale', 'expense',
              NULL, NULL, false, false, false, false, false, false);

  -- Cấp phát UUID TRƯỚC để mở được cửa `SALE_BONUS_DEPOSIT` cho đúng phiếu này:
  -- `trigger_ie_commission_guard` chạy BEFORE INSERT nên cửa phải mở trước đó,
  -- mà bảng cửa khoá theo id phiếu. Đóng cửa ngay sau lệnh INSERT.
  v_ie := gen_random_uuid();
  PERFORM app_private.begin_ie_flex_write_v1(v_ie, 'SALE_BONUS_DEPOSIT');

  INSERT INTO public.income_expenses
    (id, user_id, organization_id, type, name, building_id, room_id, contract_id,
     voucher_date, total_amount, approval_status, commission_kind, system_source, notes)
  VALUES
    (v_ie, v_actor, v_org, 'EXPENSE',
     'Thưởng nóng Sale' || COALESCE(' — ' || NULLIF(btrim(p_recipient), ''), ''),
     v_bld, v_room,
     -- Cố ý GIỮ NGUYÊN contract_id của phiếu cọc (thường là NULL lúc này).
     -- Không tự bịa hợp đồng: quan hệ nằm ở sổ claim bên dưới.
     v_dep.contract_id,
     COALESCE(p_voucher_date, public.org_today_v1(v_org)),
     p_amount, 'UNAPPROVED', 'sale', 'contract.commission',
     'Thưởng Sale theo phiếu cọc ' || COALESCE(v_dep.code, left(v_dep.id::text, 8))
       || COALESCE(' — ' || NULLIF(btrim(p_recipient), ''), '')
       || COALESCE(' — STK ' || NULLIF(btrim(p_account_number), ''), '')
       || COALESCE(' — ' || NULLIF(btrim(p_bank), ''), ''))
  RETURNING code INTO v_code;

  PERFORM app_private.end_ie_flex_write_v1(v_ie);

  INSERT INTO public.income_expense_items
    (income_expense_id, income_expense_type_id, accounting_class,
     description, quantity, unit_price, amount)
  VALUES (v_ie, v_type, 'PNL',
          'Thưởng nóng Sale — phiếu cọc ' || COALESCE(v_dep.code, left(v_dep.id::text, 8)),
          1, p_amount, p_amount);

  INSERT INTO app_private.sale_bonus_claims
    (organization_id, deposit_voucher_id, contract_id, bonus_voucher_id, amount, created_by)
  VALUES (v_org, p_deposit_voucher_id, v_dep.contract_id, v_ie, p_amount, v_actor);

  RETURN jsonb_build_object(
    'voucherId', v_ie, 'code', v_code, 'amount', p_amount,
    'depositVoucherId', p_deposit_voucher_id,
    'note', 'Phiếu thưởng đã tạo và đang CHỜ DUYỆT. Khi hợp đồng của phiếu cọc này được ký, hệ thống sẽ tự biết là đã thưởng rồi.');
END;
$$;








--
