--
-- Name: customer_in_my_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_in_my_scope(_owner uuid, _customer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.uid() = _owner
    OR public.is_admin()
    OR EXISTS (
      SELECT 1 FROM public.staff_assignments
      WHERE staff_id = auth.uid()
        AND user_id = _owner
        AND building_id IS NULL
        AND area_id IS NULL
    )
    -- Khách chưa có hợp đồng còn sống → không có building để check,
    -- để staff có quyền role 'customers.edit' vẫn quản lý được.
    OR NOT EXISTS (
      SELECT 1
      FROM public.contract_customers cc
      JOIN public.contracts c ON c.id = cc.contract_id
      WHERE cc.customer_id = _customer_id
        AND c.deleted_at IS NULL
    )
    -- ÍT NHẤT một hợp đồng còn sống nằm ở toà caller quản lý
    -- (toà lẻ trực tiếp HOẶC toà thuộc khu được gán — live).
    OR EXISTS (
      SELECT 1
      FROM public.contract_customers cc
      JOIN public.contracts c ON c.id = cc.contract_id
      JOIN public.rooms r ON r.id = c.room_id
      JOIN public.staff_assignments sa
        ON sa.staff_id = auth.uid()
       AND sa.user_id = _owner
       AND (
         sa.building_id = r.building_id
         OR (sa.area_id IS NOT NULL AND EXISTS (
               SELECT 1 FROM public.area_buildings ab
               WHERE ab.area_id = sa.area_id
                 AND ab.building_id = r.building_id
            ))
       )
      WHERE cc.customer_id = _customer_id
        AND c.deleted_at IS NULL
    );
$$;








--
-- Name: decide_financial_request_v2(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_financial_request_v2(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_memb uuid; v_ver bigint; v_state text;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  if p_decision not in ('APPROVE','REJECT') then
    raise exception 'Quyết định không hợp lệ (APPROVE/REJECT)' using errcode='22023';
  end if;

  -- Tôi phải là ỨNG VIÊN hiện hành của bước PENDING (engine sẽ re-check lần nữa).
  select c.membership_id, ar.version into v_memb, v_ver
    from public.approval_requests ar
    join public.approval_request_steps s
      on s.request_id = ar.id and s.status = 'PENDING'
    join public.approval_request_step_candidates c
      on c.request_step_id = s.id
     and c.generation = s.current_generation
     and c.valid_to is null
    join public.organization_memberships m
      on m.id = c.membership_id and m.status = 'ACTIVE' and m.user_id = v_actor
   where ar.id = p_request_id and ar.state = 'PENDING_APPROVAL'
   limit 1;
  if v_memb is null then
    raise exception 'Bạn không nằm trong danh sách người duyệt của yêu cầu này'
      using errcode = '42501';
  end if;

  perform app_private.decide_financial_request_v1(
    p_request_id, v_ver, v_memb, v_actor, p_decision,
    nullif(btrim(coalesce(p_reason,'')),''));

  select ar.state into v_state from public.approval_requests ar where ar.id = p_request_id;
  return json_build_object('request_id', p_request_id, 'state', v_state);
end;
$$;








--
-- Name: decide_financial_voucher(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_financial_voucher(p_request uuid, p_decision text, p_reason text DEFAULT NULL::text, p_expected_version bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  r public.approval_requests; st public.approval_request_steps;
  v_mem uuid; v_cand uuid; v_approvals int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_decision NOT IN ('APPROVE','REJECT') THEN RAISE EXCEPTION 'decision không hợp lệ'; END IF;
  SELECT * INTO r FROM public.approval_requests WHERE id=p_request FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy request' USING ERRCODE='P0002'; END IF;
  IF r.state <> 'PENDING_APPROVAL' THEN RAISE EXCEPTION 'Request không ở trạng thái chờ duyệt (%).', r.state; END IF;
  IF p_expected_version IS NOT NULL AND r.version <> p_expected_version THEN
    RAISE EXCEPTION 'Xung đột phiên bản (CAS)' USING ERRCODE='40001'; END IF;

  SELECT id INTO v_mem FROM public.organization_memberships
   WHERE user_id=v_uid AND organization_id=r.organization_id AND status='ACTIVE' LIMIT 1;
  IF v_mem IS NULL THEN RAISE EXCEPTION 'Bạn không thuộc tổ chức' USING ERRCODE='42501'; END IF;

  -- Maker-checker: người tạo KHÔNG tự duyệt.
  IF v_mem = r.maker_membership_id OR v_uid = r.maker_user_id THEN
    RAISE EXCEPTION 'Người tạo phiếu không được tự duyệt (maker-checker)' USING ERRCODE='42501';
  END IF;

  SELECT * INTO st FROM public.approval_request_steps
   WHERE request_id=p_request AND status='PENDING' ORDER BY step_no LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không có bước đang chờ'; END IF;

  -- Actor phải là candidate hiện tại.
  SELECT id INTO v_cand FROM public.approval_request_step_candidates
   WHERE request_step_id=st.id AND membership_id=v_mem AND generation=st.current_generation
     AND (valid_to IS NULL OR valid_to > now());
  IF v_cand IS NULL THEN RAISE EXCEPTION 'Bạn không nằm trong danh sách người duyệt bước này' USING ERRCODE='42501'; END IF;

  INSERT INTO public.approval_decisions (organization_id, request_id, request_step_id, candidate_id,
      candidate_generation, actor_membership_id, actor_user_id, decision, reason, request_version)
  VALUES (r.organization_id, p_request, st.id, v_cand, st.current_generation, v_mem, v_uid, p_decision, p_reason, r.version);

  IF p_decision='REJECT' THEN
    UPDATE public.approval_request_steps SET status='REJECTED' WHERE id=st.id;
    UPDATE public.approval_request_steps SET status='CANCELLED' WHERE request_id=p_request AND status='WAITING';
    UPDATE public.approval_requests SET state='REJECTED', version=version+1 WHERE id=p_request;
    RETURN jsonb_build_object('ok',true,'state','REJECTED');
  END IF;

  -- APPROVE: đếm quorum của step (normal APPROVE, current generation).
  SELECT count(*) INTO v_approvals FROM public.approval_decisions d
   WHERE d.request_step_id=st.id AND d.decision='APPROVE' AND d.candidate_generation=st.current_generation;
  IF v_approvals >= st.min_approvals THEN
    UPDATE public.approval_request_steps SET status='APPROVED' WHERE id=st.id;
    -- promote next WAITING step, else post.
    IF EXISTS(SELECT 1 FROM public.approval_request_steps WHERE request_id=p_request AND status='WAITING') THEN
      UPDATE public.approval_request_steps SET status='PENDING'
       WHERE id=(SELECT id FROM public.approval_request_steps WHERE request_id=p_request AND status='WAITING' ORDER BY step_no LIMIT 1);
      UPDATE public.approval_requests SET version=version+1 WHERE id=p_request;
      RETURN jsonb_build_object('ok',true,'state','PENDING_APPROVAL','promoted',true);
    ELSE
      PERFORM public._post_financial_voucher(r.subject_id, p_request, v_uid);
      RETURN jsonb_build_object('ok',true,'state','POSTED');
    END IF;
  END IF;
  UPDATE public.approval_requests SET version=version+1 WHERE id=p_request;
  RETURN jsonb_build_object('ok',true,'state','PENDING_APPROVAL','approvals',v_approvals);
END; $$;








--
-- Name: decide_owned_income_expense_v2(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_owned_income_expense_v2(p_voucher uuid, p_decision text, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid;
  v_mid uuid;
  v_ie public.income_expenses;
  v_flow text;
  v_res record;
  v_payload jsonb := '{}'::jsonb;
  v_hash text := md5(jsonb_build_object('voucher', p_voucher, 'decision', p_decision)::text);
  v_op app_private.canonical_write_operations;
  v_resp jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;
  IF p_decision NOT IN ('approve', 'cancel') THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: decision % not exposed (approve|cancel)', p_decision
      USING ERRCODE = '22023';
  END IF;

  -- Fixed lock order: voucher first (như approve v2).
  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;

  SELECT o.flow_kind INTO v_flow
  FROM app_private.income_expense_flow_ownership o WHERE o.income_expense_id = p_voucher;
  IF v_flow IS NULL THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: voucher % is MANUAL — dùng RPC thường', p_voucher
      USING ERRCODE = '42501';
  END IF;
  IF v_flow NOT IN ('INVOICE_REFUND', 'TERMINATION_REFUND') THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: flow % không đi cửa này (fail closed)', v_flow
      USING ERRCODE = '42501';
  END IF;

  SELECT r.user_id, r.membership_id INTO v_uid, v_mid
  FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.owned_decision.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN
    RETURN COALESCE(v_op.response_payload, '{}'::jsonb);
  END IF;

  -- Approver capability trong scope toà của phiếu (đồng bộ approve v2).
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: income_expenses.approve required in scope' USING ERRCODE = '42501';
  END IF;

  -- 7ac(c): txid birth check — refund birth đăng ký op 'invoice.refund.reserve.v2'
  -- (không có row create.v2) nên assert_committed_birth_boundary_v2 luôn fail;
  -- bất biến cần giữ là "create đã COMMIT ở txn trước" = birth_txid ≠ txid này.
  IF v_ie.birth_txid IS NULL OR v_ie.birth_txid = pg_current_xact_id() THEN
    RAISE EXCEPTION 'decide_owned_income_expense_v2: birth chưa commit ở transaction trước (voucher %)', p_voucher
      USING ERRCODE = '55000';
  END IF;

  -- cancel: dựng payload reservation (adapter cần reservationId + expectedStateVersion).
  IF p_decision = 'cancel' THEN
    SELECT r.id, r.state_version INTO v_res
    FROM app_private.invoice_refund_reservations r
    WHERE r.refund_voucher_id = p_voucher AND r.reservation_state = 'HELD'
    ORDER BY r.created_at DESC LIMIT 1;
    IF v_res.id IS NULL THEN
      RAISE EXCEPTION 'decide_owned_income_expense_v2: không tìm thấy reservation HELD của phiếu %', p_voucher
        USING ERRCODE = 'P0002';
    END IF;
    v_payload := jsonb_build_object(
      'reservationId', v_res.id, 'expectedStateVersion', v_res.state_version,
      'reason', COALESCE(p_reason, 'Huỷ nghĩa vụ hoàn tiền'));
  END IF;

  v_resp := app_private.dispatch_finance_decision_v2(p_voucher, p_decision, v_payload);

  -- 7ac(d): finish signature — khớp finish_canonical_op 11 tham số.
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.owned_decision.v2', p_voucher::text, v_uid,
    p_idempotency_key, p_voucher, v_resp, upper(p_decision), NULL, NULL, NULL);
  RETURN v_resp;
END
$$;








--
-- Name: delete_meter_reading_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_meter_reading_v1(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_r RECORD;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;

  SELECT id, building_id, organization_id INTO v_r
  FROM public.meter_readings WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  -- Idempotent: xoá row không tồn tại / đã xoá = success im lặng (parity đường cũ,
  -- chống double-click / concurrent delete báo lỗi thừa).
  IF NOT FOUND THEN RETURN; END IF;
  IF v_r.building_id IS NULL THEN RAISE EXCEPTION 'Chỉ số chưa gắn toà nhà'; END IF;

  IF NOT (v_r.organization_id IS NULL
          OR public.is_super_admin()
          OR v_r.organization_id = ANY(public.my_org_ids())) THEN
    RAISE EXCEPTION 'Chỉ số thuộc tổ chức khác' USING ERRCODE='42501';
  END IF;
  IF NOT public.can_do_on_building('meter_readings','delete', v_r.building_id) THEN
    RAISE EXCEPTION 'Không có quyền xoá chỉ số cho toà này' USING ERRCODE='42501';
  END IF;

  UPDATE public.meter_readings SET deleted_at = now()
  WHERE id = p_id AND deleted_at IS NULL;
END;
$$;








--
-- Name: delete_room_pass_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_room_pass_listing(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.room_pass_listings;
BEGIN
  SELECT * INTO v_row FROM public.room_pass_listings WHERE id = p_id;
  IF v_row.id IS NULL THEN
    RETURN;
  END IF;
  IF NOT public.can_manage_pass_listing(v_row.building_id, v_row.user_id) THEN
    RAISE EXCEPTION 'Không có quyền quản lý phòng khách nhờ sale cho tòa này';
  END IF;

  DELETE FROM public.room_pass_listings WHERE id = p_id;
END;
$$;








--
-- Name: delete_staff_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_staff_member(p_staff_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'app_private'
    AS $$
declare
  v_sa int := 0; v_memb int := 0;
begin
  if auth.uid() is null then
    raise exception 'Bạn chưa đăng nhập' using errcode = '42501';
  end if;
  if p_staff_id = auth.uid() then
    raise exception 'Không thể tự xoá tài khoản của chính bạn' using errcode = '42501';
  end if;
  if not public.is_super_admin() and not exists (
    select 1 from public.staff_assignments
     where staff_id = p_staff_id and user_id = auth.uid()
  ) then
    raise exception 'Bạn không có quyền xoá nhân viên này' using errcode = '42501';
  end if;

  -- 1) gỡ phân công legacy (trigger a80 đóng role_binding chuẩn hoá)
  delete from public.staff_assignments where staff_id = p_staff_id;
  get diagnostics v_sa = row_count;

  -- 2) thu hồi tư cách thành viên (giữ danh tính + lịch sử tiền)
  update public.organization_memberships
     set status = 'REVOKED', revoked_at = now(), version = version + 1
   where user_id = p_staff_id and status <> 'REVOKED';
  get diagnostics v_memb = row_count;

  -- 3) gỡ vai trò legacy
  delete from public.roles where user_id = p_staff_id;

  -- 4) bump cache quyền của mọi tổ chức liên quan
  update public.organizations o
     set authorization_version = o.authorization_version + 1
   where exists (select 1 from public.organization_memberships m
                  where m.organization_id = o.id and m.user_id = p_staff_id);

  if v_sa = 0 and v_memb = 0 then
    raise exception 'Không tìm thấy nhân viên để gỡ (hoặc đã được gỡ trước đó)'
      using errcode = 'P0002';
  end if;
end;
$$;








--
-- Name: delete_utility_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_utility_account(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bld   uuid;
  v_owner uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT building_id INTO v_bld FROM building_utility_accounts WHERE id = p_id AND deleted_at IS NULL;
  IF v_bld IS NULL THEN RAISE EXCEPTION 'Không tìm thấy đồng hồ'; END IF;
  SELECT b.user_id INTO v_owner FROM buildings b WHERE b.id = v_bld;
  IF NOT (public.can_access_building(v_bld) OR public.ie_all_buildings_scope(v_bld)
          OR v_owner = auth.uid() OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên toà này' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM income_expenses WHERE utility_account_id = p_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Đồng hồ đã có phiếu chi, không thể xoá';
  END IF;
  UPDATE building_utility_accounts SET deleted_at = now() WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;








