--
-- Name: distribute_shareholder_profit_v1(uuid, numeric, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribute_shareholder_profit_v1(p_shareholder_id uuid, p_amount numeric, p_account_id uuid, p_voucher_date date, p_note text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_org uuid;
  v_building uuid;
  v_owner uuid;
  v_type uuid;
  v_membership uuid;
  v_subject_name text;
  v_authz boolean;
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_route text;
  v_voucher uuid;
  v_request uuid;
  v_name text;
  v_response json;
  v_remaining numeric;
  v_available numeric;
  v_take numeric;
  v_allocation record;
  v_reservations jsonb := '[]'::jsonb;
  c_operation constant text := 'shareholder_profit.distribute.v2';
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'
      USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount = 'NaN'::numeric
     OR p_amount <= 0 OR round(p_amount, 2) <> p_amount THEN
    RAISE EXCEPTION 'Số tiền chia lợi nhuận không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF p_account_id IS NULL OR p_voucher_date IS NULL THEN
    RAISE EXCEPTION 'Thiếu sổ quỹ hoặc ngày chi' USING ERRCODE = '22023';
  END IF;

  SELECT shareholder.organization_id,
         COALESCE(NULLIF(btrim(shareholder.name), ''), 'Cổ đông')
    INTO v_org, v_subject_name
  FROM public.shareholders shareholder
  WHERE shareholder.id = p_shareholder_id
    AND shareholder.deleted_at IS NULL
    AND shareholder.is_active
  FOR SHARE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy cổ đông trong tổ chức hợp lệ'
      USING ERRCODE = '42501';
  END IF;

  SELECT building.id, building.user_id
    INTO v_building, v_owner
  FROM public.buildings building
  JOIN public.organizations organization
    ON organization.id = building.organization_id AND organization.status = 'ACTIVE'
  WHERE building.organization_id = v_org
    AND building.is_virtual
    AND building.deleted_at IS NULL
  ORDER BY building.created_at
  LIMIT 1
  FOR SHARE OF building, organization;
  IF v_building IS NULL THEN
    RAISE EXCEPTION 'Tổ chức chưa có tòa ảo để hạch toán chia lợi nhuận'
      USING ERRCODE = '55000';
  END IF;

  PERFORM 1 FROM public.accounts account_row
  WHERE account_row.id = p_account_id
    AND account_row.organization_id = v_org
    AND account_row.deleted_at IS NULL
    AND NOT account_row.is_virtual
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sổ quỹ tiền thật không hợp lệ hoặc không thuộc tổ chức'
      USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'shareholder_profit.distribute', v_building, p_account_id
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Không có quyền chia lợi nhuận'
      USING ERRCODE = '42501';
  END IF;

  SELECT membership.id INTO v_membership
  FROM public.organization_memberships membership
  WHERE membership.user_id = v_actor
    AND membership.organization_id = v_org
    AND membership.status = 'ACTIVE'
    AND membership.valid_from <= clock_timestamp()
    AND (membership.valid_to IS NULL OR membership.valid_to > clock_timestamp())
  LIMIT 1
  FOR SHARE;
  IF v_membership IS NULL THEN
    RAISE EXCEPTION 'Không còn là thành viên tổ chức' USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'shareholder_id', p_shareholder_id,
    'amount', round(p_amount, 2),
    'account_id', p_account_id,
    'voucher_date', p_voucher_date,
    'note', NULLIF(btrim(COALESCE(p_note, '')), ''),
    'organization_id', v_org
  )::text);

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, c_operation, p_shareholder_id::text, v_actor, v_key, v_hash
  )
  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
  DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = c_operation
    AND operation_row.subject_scope = p_shareholder_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key đã dùng với nội dung khác'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload::json;
  END IF;

  v_route := app_private.evaluate_feature_route(c_operation, v_org);
  IF v_route = 'FROZEN' THEN
    RAISE EXCEPTION 'Writer chia lợi nhuận đang bị đóng băng'
      USING ERRCODE = '55000';
  ELSIF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Writer chia lợi nhuận chưa bật' USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_profit_payout_sources_v2();

  v_remaining := p_amount;
  FOR v_allocation IN
    SELECT pa.id, pa.amount, pm.period_month, pm.building_id
    FROM public.profit_allocations pa
    JOIN public.profit_monthly pm ON pm.id = pa.profit_monthly_id
    WHERE pa.organization_id = v_org
      AND pa.shareholder_id = p_shareholder_id
      AND pa.amount > 0
      AND pm.status = 'LOCKED'
      AND NOT pm.is_stale
      AND pm.period_month <= date_trunc('month', p_voucher_date)::date
      AND app_private.profit_monthly_source_is_current_v1(pm.id)
    ORDER BY pm.period_month, pm.building_id, pa.id
    FOR UPDATE OF pa, pm
  LOOP
    EXIT WHEN v_remaining < 0.01;
    v_available := GREATEST(
      v_allocation.amount - public._profit_allocation_reserved_v2(v_allocation.id),
      0
    );
    IF v_available < 0.01 THEN
      CONTINUE;
    END IF;

    v_take := LEAST(v_remaining, v_available);
    v_reservations := v_reservations || jsonb_build_array(jsonb_build_object(
      'profit_allocation_id', v_allocation.id,
      'period_month', v_allocation.period_month,
      'building_id', v_allocation.building_id,
      'amount', v_take
    ));
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining >= 0.01 THEN
    RAISE EXCEPTION 'Số tiền chi vượt lợi nhuận đã chốt còn khả dụng: thiếu %', v_remaining
      USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.claim_feature_operation_v1(
    c_operation,
    v_org,
    p_shareholder_id::text,
    v_actor,
    v_key,
    round(p_amount, 2)
  );

  SELECT COALESCE(NULLIF(btrim(profile.full_name), ''),
                  NULLIF(btrim(profile.email), ''), 'Người dùng')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_actor;

  SELECT type_row.id INTO v_type
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'expense'
    AND type_row.name = 'Chia lợi nhuận cổ đông'
  ORDER BY type_row.created_at
  LIMIT 1;
  IF v_type IS NULL THEN
    INSERT INTO public.income_expense_types (
      user_id, organization_id, name, type, category,
      is_default, is_deposit, description
    ) VALUES (
      v_owner, v_org, 'Chia lợi nhuận cổ đông', 'expense', 'Chia lợi nhuận',
      false, false, 'Chi từ lợi nhuận đã chốt; không tính lại vào KQKD'
    ) RETURNING id INTO v_type;
  END IF;

  v_name := COALESCE(
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    'Chia lợi nhuận: ' || v_subject_name
  );
  PERFORM app_private.begin_accounting_chain_write_v1();

  INSERT INTO public.income_expenses (
    user_id, organization_id, creator_name, type, name,
    building_id, account_id, shareholder_id,
    business_result_accounting, approval_status, voucher_date,
    attachments, repeat_cycle, repeat_infinity, repeat_count, repeat_remaining,
    source_payload_hash, system_source, idempotency_key
  ) VALUES (
    v_owner, v_org, COALESCE(v_actor_name, 'Người dùng'), 'EXPENSE', v_name,
    v_building, p_account_id, p_shareholder_id,
    false, 'UNAPPROVED', p_voucher_date,
    '[]'::jsonb, 'NONE', false, 0, 0,
    v_hash, 'profit.distribution', v_key
  ) RETURNING id INTO v_voucher;

  INSERT INTO public.income_expense_items (
    income_expense_id, organization_id, income_expense_type_id,
    description, quantity, unit_price, amount, start_date, end_date,
    accounting_class
  ) VALUES (
    v_voucher, v_org, v_type,
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    1, round(p_amount, 2), round(p_amount, 2),
    p_voucher_date, p_voucher_date, 'INTERNAL'
  );

  INSERT INTO app_private.income_expense_flow_ownership (
    income_expense_id, organization_id, flow_kind, flow_version,
    lifecycle_owner, lifecycle_state, writer_operation,
    payload_hash_scheme, payload_hash_value, maker_user_id,
    claimed_by_user_id, correlation_id
  ) VALUES (
    v_voucher, v_org, 'SHAREHOLDER_PROFIT_PAYOUT_V2', 2,
    'APPROVAL_ENGINE_V2', 'DRAFT', c_operation,
    'PG_MD5_JSONB_TEXT_V1', v_hash, v_actor,
    v_actor, v_voucher
  );

  -- Reserve before submission so AUTO_POST cannot approve an uncovered payout.
  INSERT INTO public.profit_payout_reservations (
    organization_id, profit_allocation_id, shareholder_id,
    payout_voucher_id, approval_request_id, amount,
    reservation_source, source_payload_hash, created_by
  )
  SELECT
    v_org,
    (entry.value->>'profit_allocation_id')::uuid,
    p_shareholder_id,
    v_voucher,
    NULL,
    (entry.value->>'amount')::numeric,
    'CANONICAL_V1',
    v_hash,
    v_actor
  FROM jsonb_array_elements(v_reservations) entry(value);

  v_request := app_private.submit_financial_request_v1(
    v_voucher, v_membership, v_actor, v_key || '-sub'
  );

  UPDATE public.profit_payout_reservations reservation
     SET approval_request_id = v_request
   WHERE reservation.payout_voucher_id = v_voucher
     AND reservation.reservation_source = 'CANONICAL_V1'
     AND reservation.approval_request_id IS NULL;

  PERFORM app_private.assert_profit_payout_linkage_v2(
    v_voucher, false, true
  );

  v_response := json_build_object(
    'profit_voucher_id', v_voucher,
    'approval_request_id', v_request,
    'shareholder_id', p_shareholder_id,
    'reserved_allocations', v_reservations,
    'state', 'PENDING_APPROVAL'
  );

  UPDATE app_private.canonical_write_operations
     SET subject_id = v_voucher,
         response_payload = to_jsonb(v_response),
         completed_at = clock_timestamp()
   WHERE organization_id = v_org
     AND operation = c_operation
     AND subject_scope = p_shareholder_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;

  PERFORM app_private.end_accounting_chain_write_v1();
  RETURN v_response;
END
$_$;








--
-- Name: effective_perms_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effective_perms_v2(p_user uuid, p_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH mem AS (
    SELECT id FROM public.organization_memberships
    WHERE user_id = p_user AND organization_id = p_org AND status = 'ACTIVE'
  ),
  role_keys AS (
    SELECT DISTINCT rp.permission_key AS key
    FROM mem
    JOIN public.role_bindings rb
      ON rb.membership_id = mem.id AND (rb.valid_to IS NULL OR rb.valid_to > now())
    JOIN public.role_permissions rp
      ON rp.organization_id = p_org AND rp.role_id = rb.role_id AND rp.effect = 'ALLOW'
  ),
  allow_ov AS (
    SELECT o.permission_key AS key FROM public.member_permission_overrides o
    JOIN mem ON o.membership_id = mem.id
    WHERE o.effect = 'ALLOW' AND (o.expires_at IS NULL OR o.expires_at > now())
  ),
  deny_ov AS (
    SELECT o.permission_key AS key FROM public.member_permission_overrides o
    JOIN mem ON o.membership_id = mem.id
    WHERE o.effect = 'DENY' AND (o.expires_at IS NULL OR o.expires_at > now())
  ),
  effective AS (
    SELECT key FROM (SELECT key FROM role_keys UNION SELECT key FROM allow_ov) u
    WHERE key NOT IN (SELECT key FROM deny_ov)
  )
  SELECT COALESCE(jsonb_object_agg(resource, actions), '{}'::jsonb)
  FROM (
    SELECT pd.resource, jsonb_object_agg(pd.action, true) AS actions
    FROM effective e JOIN public.permission_definitions pd ON pd.key = e.key
    GROUP BY pd.resource
  ) g;
$$;








--
-- Name: emergency_approve_request_v1(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emergency_approve_request_v1(p_request_id uuid, p_reason text, p_reauth_fresh boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_req public.approval_requests;
  v_memb uuid;
  v_posting uuid;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;

  select * into v_req from public.approval_requests where id = p_request_id;
  if not found then raise exception 'Không tìm thấy yêu cầu duyệt' using errcode='P0002'; end if;

  -- membership OWNER đang hoạt động của actor trong org của yêu cầu
  select m.id into v_memb from public.organization_memberships m
   where m.user_id = v_actor and m.organization_id = v_req.organization_id
     and m.status = 'ACTIVE' and m.member_type = 'OWNER'
   limit 1;
  if v_memb is null then
    raise exception 'Duyệt khẩn cấp yêu cầu tư cách CHỦ SỞ HỮU đang hoạt động' using errcode='42501';
  end if;

  -- inner fn tự kiểm: not-maker + approvals.emergency_override + reason>=20 +
  -- reauth + version + log emergency_override_events + BYPASS steps + post.
  v_posting := app_private.emergency_approve_financial_v1(
    p_request_id, v_req.version, v_memb, v_actor, p_reason, coalesce(p_reauth_fresh, false));

  return json_build_object('request_id', p_request_id, 'posting_id', v_posting, 'emergency', true);
end;
$$;








--
-- Name: ensure_room_deposit_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_room_deposit_type() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Ban chua dang nhap' USING ERRCODE = '42501';
  END IF;
  v_id := public._termination_ensure_type(auth.uid(), 'income', 'Tiền cọc');
  UPDATE income_expense_types
     SET is_deposit = TRUE
   WHERE id = v_id AND is_deposit IS DISTINCT FROM TRUE;
  RETURN v_id;
END;
$$;








--
-- Name: ensure_single_default_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_single_default_template() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- If setting a template as default, unset all other defaults for same category and user
  IF NEW.is_default = TRUE THEN
    UPDATE document_templates
    SET is_default = FALSE
    WHERE user_id = NEW.user_id
      AND category = NEW.category
      AND id != NEW.id
      AND is_default = TRUE
      AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: estimate_termination_costs(uuid, date, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estimate_termination_costs(p_contract_id uuid, p_move_out_date date, p_damage_fee numeric DEFAULT 0, p_cleaning_fee numeric DEFAULT 0, p_early_termination_fee numeric DEFAULT 0) RETURNS TABLE(outstanding_debt numeric, prorated_rent numeric, prorated_services numeric, total_fees numeric, total_deposit numeric, refund_amount numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_contract RECORD;
  v_outstanding DECIMAL(15,2);
  v_prorated_rent DECIMAL(15,2);
  v_prorated_services DECIMAL(15,2);
  v_days_in_month INTEGER;
  v_daily_rate DECIMAL(15,2);
  v_prorated_days INTEGER;
BEGIN
  -- Get contract
  SELECT c.rent_price, c.total_deposit
  INTO v_contract
  FROM contracts c
  WHERE c.id = p_contract_id;

  -- Calculate outstanding (handle missing deleted_at column)
  SELECT COALESCE(SUM(remaining_amount), 0)
  INTO v_outstanding
  FROM invoices
  WHERE contract_id = p_contract_id
    AND status NOT IN ('PAID', 'CANCELLED');

  -- Calculate prorated rent
  v_days_in_month := EXTRACT(DAY FROM (
    DATE_TRUNC('month', p_move_out_date) + INTERVAL '1 month - 1 day'
  ));
  v_daily_rate := v_contract.rent_price / v_days_in_month;
  v_prorated_days := EXTRACT(DAY FROM p_move_out_date);

  IF v_prorated_days < v_days_in_month THEN
    v_prorated_rent := v_daily_rate * v_prorated_days;
  ELSE
    v_prorated_rent := 0;
  END IF;

  -- Estimate services (simplified)
  v_prorated_services := 0; -- Could be enhanced

  -- Return results
  RETURN QUERY SELECT
    v_outstanding,
    v_prorated_rent,
    v_prorated_services,
    p_damage_fee + p_cleaning_fee + p_early_termination_fee,
    v_contract.total_deposit,
    v_contract.total_deposit - (
      v_outstanding + v_prorated_rent + v_prorated_services +
      p_damage_fee + p_cleaning_fee + p_early_termination_fee
    );
END;
$$;








--
-- Name: FUNCTION estimate_termination_costs(p_contract_id uuid, p_move_out_date date, p_damage_fee numeric, p_cleaning_fee numeric, p_early_termination_fee numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.estimate_termination_costs(p_contract_id uuid, p_move_out_date date, p_damage_fee numeric, p_cleaning_fee numeric, p_early_termination_fee numeric) IS 'Returns estimated termination costs for a contract - useful for showing preview before creating termination';








--
-- Name: explain_authorization_v1(uuid, text[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explain_authorization_v1(p_membership uuid, p_permission_keys text[] DEFAULT NULL::text[], p_building uuid DEFAULT NULL::uuid, p_cashbook uuid DEFAULT NULL::uuid) RETURNS TABLE(permission_key text, resource text, action text, sensitivity text, duoc_phep boolean, ly_do_ma text, ly_do text, nguon text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_org   uuid;
  v_user  uuid;
  v_hong  text;
begin
  if v_actor is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  if p_membership is null then
    raise exception 'Thiếu thành viên cần xem quyền.' using errcode = '22023';
  end if;

  select m.organization_id, m.user_id into v_org, v_user
    from public.organization_memberships m
   where m.id = p_membership;
  if v_org is null then
    raise exception 'Không tìm thấy thành viên này.' using errcode = 'P0002';
  end if;

  -- Hợp đồng writer của evaluator (điểm 4 ở header): khoá tổ chức ở statement trước.
  perform app_private.lock_org_for_decision_v1(v_org);

  -- Quyền xem: phải là thành viên cùng tổ chức và có users.view.
  -- Ai cũng được tự xem quyền của CHÍNH MÌNH (rất hữu ích: "vì sao tôi không bấm
  -- được nút này"), nhưng KHÔNG kèm lý do ngoại lệ của người khác.
  if v_user <> v_actor and not app_private.can_v3('users.view') then
    raise exception 'Bạn không có quyền xem phân quyền của người khác.'
      using errcode = '42501';
  end if;

  -- Mục tiêu phải cùng tổ chức, nếu không cả 219 dòng đều nói "khác tổ chức".
  if p_building is not null and not exists (
       select 1 from public.buildings b
        where b.id = p_building and b.organization_id = v_org and b.deleted_at is null) then
    raise exception 'Toà nhà không thuộc tổ chức của thành viên này.' using errcode = '22023';
  end if;
  if p_cashbook is not null and not exists (
       select 1 from public.accounts a
        where a.id = p_cashbook and a.organization_id = v_org and a.deleted_at is null) then
    raise exception 'Sổ quỹ không thuộc tổ chức của thành viên này.' using errcode = '22023';
  end if;

  -- Điểm 5 ở header: ngoại lệ hỏng làm evaluator RAISE và giết cả bảng kết quả.
  -- Bắt trước, báo bằng tiếng Việt chỉ đúng chỗ hỏng.
  select string_agg(distinct o.permission_key, ', ')
    into v_hong
    from public.member_permission_overrides o
   where o.membership_id = p_membership
     and o.revoked_at is null
     and (o.expires_at is null or o.expires_at > now())
     and not exists (select 1 from public.member_override_scopes s where s.override_id = o.id);
  if v_hong is not null then
    raise exception 'Dữ liệu phân quyền của thành viên này bị hỏng: ngoại lệ "%" không có phạm vi nào. Hãy sửa hoặc gỡ ngoại lệ đó trước.', v_hong
      using errcode = '23514';
  end if;

  return query
  with keys as (
    select pd.key, pd.resource, pd.action, pd.sensitivity
      from public.permission_definitions pd
     where pd.permission_domain = 'TENANT'
       and pd.is_active
       and (p_permission_keys is null or pd.key = any(p_permission_keys))
  ),
  quyet_dinh as (
    select k.*, d.allowed, d.decision_reason
      from keys k
      cross join lateral app_private.authorize_tenant_action_v3(
        v_user, v_org, k.key, p_building, p_cashbook) d
  )
  select
    q.key, q.resource, q.action, q.sensitivity, q.allowed, q.decision_reason,
    case q.decision_reason
      when 'ORGANIZATION_INACTIVE_OR_MISSING' then 'Tổ chức đang không hoạt động'
      when 'PERMISSION_INACTIVE_OR_MISSING'   then 'Quyền này không còn được dùng'
      when 'REQUIRED_DIMENSION_MISSING'       then 'Chưa chọn toà nhà hoặc sổ quỹ nên chưa xét được'
      when 'MEMBERSHIP_INACTIVE_OR_MISSING'   then 'Người này không còn là thành viên đang hoạt động'
      when 'TARGET_CROSS_ORG_OR_MISSING'      then 'Toà nhà hoặc sổ quỹ không thuộc tổ chức này'
      when 'EMERGENCY_DENY'                   then 'Đang bị lệnh cấm khẩn cấp của tổ chức'
      when 'MEMBER_DENY'                      then 'Bị chặn bởi ngoại lệ riêng của người này'
      when 'ROLE_DENY'                        then 'Bị chặn bởi vai trò đang gán'
      when 'POSSESSION_MISSING'               then 'Không giữ sổ quỹ này nên không thao tác được'
      when 'MEMBER_ALLOW'                     then 'Được phép nhờ ngoại lệ riêng'
      when 'ROLE_ALLOW'                       then 'Được phép nhờ vai trò'
      else                                         'Không có vai trò hay ngoại lệ nào cấp quyền này'
    end,
    -- Nguồn cụ thể: chỉ tra khi có ý nghĩa, và chỉ cho người có users.view.
    case
      when q.decision_reason = 'ROLE_ALLOW' then coalesce((
        select 'Vai trò: ' || string_agg(distinct r.name, ', ')
          from public.role_bindings rb
          join public.organization_roles r on r.id = rb.role_id
          join public.role_permissions rp
            on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
           and rp.permission_key = q.key and rp.effect = 'ALLOW'
         where rb.membership_id = p_membership and rb.valid_to is null), 'Vai trò')
      when q.decision_reason = 'ROLE_DENY' then coalesce((
        select 'Vai trò chặn: ' || string_agg(distinct r.name, ', ')
          from public.role_bindings rb
          join public.organization_roles r on r.id = rb.role_id
          join public.role_permissions rp
            on rp.role_id = rb.role_id and rp.organization_id = rb.organization_id
           and rp.permission_key = q.key and rp.effect = 'DENY'
         where rb.membership_id = p_membership and rb.valid_to is null), 'Vai trò')
      when q.decision_reason in ('MEMBER_ALLOW','MEMBER_DENY') then coalesce((
        select 'Ngoại lệ riêng' ||
               case when v_user = v_actor then ''
                    else coalesce(' — lý do: ' || nullif(btrim(o.reason), ''), '') end
          from public.member_permission_overrides o
         where o.membership_id = p_membership and o.permission_key = q.key
           and o.revoked_at is null and (o.expires_at is null or o.expires_at > now())
         limit 1), 'Ngoại lệ riêng')
      when q.decision_reason = 'POSSESSION_MISSING' then 'Cần được giao giữ sổ quỹ'
      else null
    end
  from quyet_dinh q
  order by q.resource, q.action;
end
$$;








--
-- Name: FUNCTION explain_authorization_v1(p_membership uuid, p_permission_keys text[], p_building uuid, p_cashbook uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.explain_authorization_v1(p_membership uuid, p_permission_keys text[], p_building uuid, p_cashbook uuid) IS 'Giải thích quyền hiệu lực của một thành viên kèm NGUỒN quyết định. Ruột của tab "Quyền hiệu lực". Ai cũng tự xem được của mình; xem người khác cần users.view.';








--
-- Name: fa_accrual_allocations(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_accrual_allocations(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, voucher_id uuid, building_id uuid, building_name text, is_virtual boolean, side text, type_id uuid, type_name text, category text, amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH allowed AS (
    SELECT b.id, b.name, b.is_virtual
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  win AS (
    SELECT date_trunc('month', p_start_date)::date AS w_start,
           date_trunc('month', p_end_date)::date AS w_end
  ),
  vouchers AS (
    SELECT voucher.id, voucher.type::text AS side, voucher.voucher_date,
           allowed.id AS bid, allowed.name AS bname, allowed.is_virtual,
           voucher.total_amount, voucher.business_result_accounting AS override,
           CASE
             WHEN voucher.invoice_id IS NOT NULL AND invoice.billing_month ~ '^\d{4}-\d{2}$'
             THEN to_date(invoice.billing_month, 'YYYY-MM')
           END AS inv_month
    FROM allowed
    JOIN public.income_expenses voucher ON voucher.building_id = allowed.id
    LEFT JOIN public.invoices invoice
      ON invoice.id = voucher.invoice_id AND invoice.deleted_at IS NULL
    WHERE voucher.deleted_at IS NULL
      AND voucher.approval_status = 'APPROVED'
      AND voucher.business_result_accounting IS DISTINCT FROM false
  ),
  invoice_items AS (
    SELECT vouchers.inv_month AS m, vouchers.id, vouchers.bid, vouchers.bname,
           vouchers.is_virtual, vouchers.side, type_row.id AS tid,
           type_row.name AS tname, type_row.category,
           COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amt
    FROM vouchers
    JOIN public.income_expense_items item ON item.income_expense_id = vouchers.id
    JOIN public.income_expense_types type_row ON type_row.id = item.income_expense_type_id
    WHERE vouchers.inv_month IS NOT NULL
      AND (vouchers.override IS TRUE OR item.accounting_class = 'PNL')
  ),
  invoice_no_item AS (
    SELECT vouchers.inv_month AS m, vouchers.id, vouchers.bid, vouchers.bname,
           vouchers.is_virtual, vouchers.side, NULL::uuid AS tid,
           'Không có hạng mục'::text AS tname, NULL::text AS category,
           vouchers.total_amount AS amt
    FROM vouchers
    WHERE vouchers.inv_month IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.income_expense_items item WHERE item.income_expense_id = vouchers.id
      )
  ),
  period_items AS (
    SELECT (date_trunc('month', item.start_date) + (series.i || ' month')::interval)::date AS m,
           vouchers.id, vouchers.bid, vouchers.bname, vouchers.is_virtual, vouchers.side,
           type_row.id AS tid, type_row.name AS tname, type_row.category,
           (round(COALESCE(item.amount, item.unit_price * item.quantity) * (series.i + 1) / count_months.n)
            - round(COALESCE(item.amount, item.unit_price * item.quantity) * series.i / count_months.n))::numeric AS amt
    FROM vouchers
    JOIN public.income_expense_items item ON item.income_expense_id = vouchers.id
    JOIN public.income_expense_types type_row ON type_row.id = item.income_expense_type_id
    CROSS JOIN LATERAL (
      SELECT GREATEST(
        extract(year FROM item.end_date)::int * 12 + extract(month FROM item.end_date)::int
        - extract(year FROM item.start_date)::int * 12 - extract(month FROM item.start_date)::int + 1,
        1
      ) AS n
    ) count_months
    CROSS JOIN LATERAL generate_series(0, count_months.n - 1) AS series(i)
    WHERE vouchers.inv_month IS NULL
      AND (vouchers.override IS TRUE OR item.accounting_class = 'PNL')
      AND item.start_date IS NOT NULL
      AND item.end_date IS NOT NULL
      AND item.end_date >= item.start_date
  ),
  invalid_period_items AS (
    SELECT date_trunc('month', item.start_date)::date AS m,
           vouchers.id, vouchers.bid, vouchers.bname, vouchers.is_virtual, vouchers.side,
           type_row.id AS tid, type_row.name AS tname, type_row.category,
           COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amt
    FROM vouchers
    JOIN public.income_expense_items item ON item.income_expense_id = vouchers.id
    JOIN public.income_expense_types type_row ON type_row.id = item.income_expense_type_id
    WHERE vouchers.inv_month IS NULL
      AND (vouchers.override IS TRUE OR item.accounting_class = 'PNL')
      AND item.start_date IS NOT NULL
      AND item.end_date IS NOT NULL
      AND item.end_date < item.start_date
  ),
  no_period_items AS (
    SELECT date_trunc('month', vouchers.voucher_date)::date AS m,
           vouchers.id, vouchers.bid, vouchers.bname, vouchers.is_virtual, vouchers.side,
           type_row.id AS tid, type_row.name AS tname, type_row.category,
           COALESCE(item.amount, item.unit_price * item.quantity)::numeric AS amt
    FROM vouchers
    JOIN public.income_expense_items item ON item.income_expense_id = vouchers.id
    JOIN public.income_expense_types type_row ON type_row.id = item.income_expense_type_id
    WHERE vouchers.inv_month IS NULL
      AND (vouchers.override IS TRUE OR item.accounting_class = 'PNL')
      AND (item.start_date IS NULL OR item.end_date IS NULL)
  ),
  no_item AS (
    SELECT date_trunc('month', vouchers.voucher_date)::date AS m,
           vouchers.id, vouchers.bid, vouchers.bname, vouchers.is_virtual, vouchers.side,
           NULL::uuid AS tid, 'Không có hạng mục'::text AS tname,
           NULL::text AS category, vouchers.total_amount AS amt
    FROM vouchers
    WHERE vouchers.inv_month IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.income_expense_items item WHERE item.income_expense_id = vouchers.id
      )
  ),
  unioned AS (
    SELECT * FROM invoice_items
    UNION ALL SELECT * FROM invoice_no_item
    UNION ALL SELECT * FROM period_items
    UNION ALL SELECT * FROM invalid_period_items
    UNION ALL SELECT * FROM no_period_items
    UNION ALL SELECT * FROM no_item
  )
  SELECT unioned.m, unioned.id, unioned.bid, unioned.bname, unioned.is_virtual,
         unioned.side, unioned.tid, unioned.tname, unioned.category, unioned.amt
  FROM unioned, win
  WHERE unioned.m BETWEEN win.w_start AND win.w_end;
$_$;








--
-- Name: FUNCTION fa_accrual_allocations(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_accrual_allocations(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Canonical re-perioded ledger allocations using immutable item accounting_class snapshots.';








--
-- Name: fa_invoice_collection(text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_invoice_collection(p_start_month text, p_end_month text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(billing_month text, building_id uuid, building_name text, billed numeric, collected numeric, remaining numeric, invoice_count bigint, draft_count bigint, pending_count bigint, approved_count bigint, paid_count bigint, partial_count bigint, overdue_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  )
  SELECT
    i.billing_month,
    a.id,
    a.name,
    COALESCE(SUM(i.total_amount), 0)::numeric,
    COALESCE(SUM(i.paid_amount), 0)::numeric,
    COALESCE(SUM(GREATEST(i.remaining_amount, 0)), 0)::numeric,
    COUNT(*),
    COUNT(*) FILTER (WHERE i.status = 'DRAFT'),
    COUNT(*) FILTER (WHERE i.status = 'PENDING_APPROVAL'),
    COUNT(*) FILTER (WHERE i.status = 'APPROVED'),
    COUNT(*) FILTER (WHERE i.status = 'PAID'),
    COUNT(*) FILTER (WHERE i.status = 'PARTIAL_PAID'),
    COUNT(*) FILTER (WHERE i.status = 'OVERDUE')
  FROM public.invoices i
  JOIN allowed a ON a.id = i.building_id
  WHERE i.deleted_at IS NULL
    AND i.status <> 'CANCELLED'
    AND i.billing_month >= p_start_month
    AND i.billing_month <= p_end_month
  GROUP BY i.billing_month, a.id, a.name
  ORDER BY i.billing_month, a.name;
$$;








--
-- Name: FUNCTION fa_invoice_collection(p_start_month text, p_end_month text, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_invoice_collection(p_start_month text, p_end_month text, p_building_ids uuid[]) IS 'Thu hồi hoá đơn theo billing_month (''YYYY-MM'') × toà: tổng phát hành / đã thu / còn lại + đếm theo status (loại CANCELLED). FE scaffold tháng trống.';








--
-- Name: fa_lease_events(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_lease_events(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, new_contracts bigint, renewals bigint, terminations bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  ev AS (
    SELECT date_trunc('month', c.signed_date)::date AS m, r.building_id AS bid, 'NEW' AS kind
    FROM public.contracts c
    JOIN public.rooms r ON r.id = c.room_id
    JOIN allowed a ON a.id = r.building_id
    WHERE c.deleted_at IS NULL
      AND c.status <> 'DRAFT'
      AND c.signed_date >= p_start_date
      AND c.signed_date < p_end_date + 1
    UNION ALL
    SELECT date_trunc('month', ce.extension_date)::date, r.building_id, 'RENEW'
    FROM public.contract_extensions ce
    JOIN public.contracts c ON c.id = ce.contract_id AND c.deleted_at IS NULL
    JOIN public.rooms r ON r.id = c.room_id
    JOIN allowed a ON a.id = r.building_id
    WHERE ce.status IN ('APPROVED', 'COMPLETED')
      AND ce.extension_date >= p_start_date
      AND ce.extension_date < p_end_date + 1
    UNION ALL
    SELECT date_trunc('month', ct.termination_date)::date, r.building_id, 'TERM'
    FROM public.contract_terminations ct
    JOIN public.contracts c ON c.id = ct.contract_id AND c.deleted_at IS NULL
    JOIN public.rooms r ON r.id = c.room_id
    JOIN allowed a ON a.id = r.building_id
    WHERE ct.status = 'COMPLETED'
      AND ct.termination_date >= p_start_date
      AND ct.termination_date < p_end_date + 1
  )
  SELECT ev.m, a.id, a.name,
         COUNT(*) FILTER (WHERE ev.kind = 'NEW'),
         COUNT(*) FILTER (WHERE ev.kind = 'RENEW'),
         COUNT(*) FILTER (WHERE ev.kind = 'TERM')
  FROM ev
  JOIN allowed a ON a.id = ev.bid
  GROUP BY ev.m, a.id, a.name
  ORDER BY ev.m, a.name;
$$;








--
-- Name: FUNCTION fa_lease_events(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_lease_events(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Sự kiện HĐ theo tháng × toà: ký mới (signed_date, non-DRAFT), gia hạn (contract_extensions APPROVED/COMPLETED), thanh lý (contract_terminations COMPLETED). Chỉ trả tháng có sự kiện — FE scaffold.';








--
-- Name: fa_monthly_pnl(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_monthly_pnl(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, is_virtual boolean, revenue numeric, expense numeric, net numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name, b.is_virtual
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  )
  SELECT
    date_trunc('month', ie.voucher_date)::date,
    a.id,
    a.name,
    a.is_virtual,
    COALESCE(SUM(ie.kqkd_amount) FILTER (WHERE ie.type = 'INCOME'),  0)::numeric,
    COALESCE(SUM(ie.kqkd_amount) FILTER (WHERE ie.type = 'EXPENSE'), 0)::numeric,
    (COALESCE(SUM(ie.kqkd_amount) FILTER (WHERE ie.type = 'INCOME'),  0)
   - COALESCE(SUM(ie.kqkd_amount) FILTER (WHERE ie.type = 'EXPENSE'), 0))::numeric
  FROM allowed a
  JOIN public.income_expenses ie ON ie.building_id = a.id
  WHERE ie.deleted_at IS NULL
    AND ie.approval_status = 'APPROVED'
    AND ie.kqkd_amount > 0
    AND ie.voucher_date >= p_start_date
    AND ie.voucher_date <= p_end_date
  GROUP BY 1, a.id, a.name, a.is_virtual
  ORDER BY 1, a.name;
$$;








--
-- Name: FUNCTION fa_monthly_pnl(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_monthly_pnl(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'P&L KQKD theo tháng × toà — cộng kqkd_amount (item-level: phiếu trộn chỉ tính phần không-cọc). Chỉ trả tháng/toà CÓ dữ liệu — FE tự scaffold tháng trống.';








--
-- Name: fa_monthly_pnl_accrual(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_monthly_pnl_accrual(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, is_virtual boolean, revenue numeric, expense numeric, net numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    al.month, al.building_id, al.building_name, al.is_virtual,
    COALESCE(SUM(al.amount) FILTER (WHERE al.side = 'INCOME'),  0)::numeric,
    COALESCE(SUM(al.amount) FILTER (WHERE al.side = 'EXPENSE'), 0)::numeric,
    (COALESCE(SUM(al.amount) FILTER (WHERE al.side = 'INCOME'),  0)
   - COALESCE(SUM(al.amount) FILTER (WHERE al.side = 'EXPENSE'), 0))::numeric
  FROM public.fa_accrual_allocations(p_start_date, p_end_date, p_building_ids) al
  GROUP BY al.month, al.building_id, al.building_name, al.is_virtual
  ORDER BY al.month, al.building_name;
$$;








--
-- Name: FUNCTION fa_monthly_pnl_accrual(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_monthly_pnl_accrual(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'P&L DỒN TÍCH theo tháng × toà (cùng shape fa_monthly_pnl). Phân bổ item theo kỳ áp dụng / billing_month — khớp Phân bổ lợi nhuận. FE tự scaffold tháng trống.';








--
-- Name: fa_occupancy_monthly(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_occupancy_monthly(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, building_id uuid, building_name text, total_rooms integer, occupied_rooms integer, occupancy_pct numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  months AS (
    SELECT gs::date AS m
    FROM generate_series(
      date_trunc('month', p_start_date),
      date_trunc('month', p_end_date),
      interval '1 month'
    ) gs
  ),
  room_totals AS (
    SELECT r.building_id AS bid, COUNT(*)::int AS total
    FROM public.rooms r
    JOIN allowed a ON a.id = r.building_id
    WHERE r.deleted_at IS NULL
    GROUP BY r.building_id
  ),
  occ AS (
    SELECT mo.m, r.building_id AS bid, COUNT(DISTINCT r.id)::int AS occupied
    FROM months mo
    JOIN public.rooms r ON r.deleted_at IS NULL
    JOIN allowed a ON a.id = r.building_id
    WHERE EXISTS (
      SELECT 1
      FROM public.contracts c
      WHERE c.room_id = r.id
        AND c.deleted_at IS NULL
        AND c.status <> 'DRAFT'
        AND c.start_date <= (mo.m + interval '1 month - 1 day')::date
        AND COALESCE(c.actual_end_date, c.end_date) >= mo.m
    )
    GROUP BY mo.m, r.building_id
  )
  SELECT
    mo.m,
    a.id,
    a.name,
    COALESCE(rt.total, 0),
    COALESCE(o.occupied, 0),
    CASE WHEN COALESCE(rt.total, 0) = 0 THEN 0
         ELSE ROUND(COALESCE(o.occupied, 0) * 100.0 / rt.total, 1)
    END::numeric
  FROM months mo
  CROSS JOIN allowed a
  LEFT JOIN room_totals rt ON rt.bid = a.id
  LEFT JOIN occ o ON o.m = mo.m AND o.bid = a.id
  ORDER BY mo.m, a.name;
$$;








--
-- Name: FUNCTION fa_occupancy_monthly(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_occupancy_monthly(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Lấp đầy theo tháng × toà (loại toà ảo). occupied = HĐ non-DRAFT giao tháng theo [start_date, COALESCE(actual_end_date,end_date)]. total_rooms = phòng hiện tại (xấp xỉ cho quá khứ). Đủ mọi tháng trong khoảng (scaffold server-side).';








--
-- Name: fa_snapshot_kpis(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_snapshot_kpis(p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(building_id uuid, building_name text, total_rooms integer, rooms_available integer, rooms_occupied integer, rooms_reserved integer, rooms_maintenance integer, rooms_unavailable integer, vacancy_loss_month numeric, active_contracts bigint, avg_rent numeric, deposit_held numeric, receivable_total numeric, aging_not_due numeric, aging_1_30 numeric, aging_31_60 numeric, aging_61_90 numeric, aging_over_90 numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  room_stats AS (
    SELECT r.building_id AS bid,
           COUNT(*)::int                                          AS total_r,
           COUNT(*) FILTER (WHERE r.status = 'AVAILABLE')::int    AS avail,
           COUNT(*) FILTER (WHERE r.status = 'OCCUPIED')::int     AS occ,
           COUNT(*) FILTER (WHERE r.status = 'RESERVED')::int     AS resv,
           COUNT(*) FILTER (WHERE r.status = 'MAINTENANCE')::int  AS maint,
           COUNT(*) FILTER (WHERE r.status = 'UNAVAILABLE')::int  AS unavail,
           COALESCE(SUM(r.rent_price) FILTER (WHERE r.status = 'AVAILABLE'), 0)::numeric AS vacancy_loss
    FROM public.rooms r
    JOIN allowed a ON a.id = r.building_id
    WHERE r.deleted_at IS NULL
    GROUP BY r.building_id
  ),
  contract_stats AS (
    SELECT r.building_id AS bid,
           COUNT(*)                                  AS actives,
           AVG(c.rent_price)::numeric                AS avg_rent_b,
           COALESCE(SUM(c.deposit_paid), 0)::numeric AS dep_held
    FROM public.contracts c
    JOIN public.rooms r ON r.id = c.room_id
    JOIN allowed a ON a.id = r.building_id
    WHERE c.deleted_at IS NULL
      AND c.status = 'ACTIVE'
    GROUP BY r.building_id
  ),
  receivables AS (
    SELECT i.building_id AS bid,
           COALESCE(SUM(i.remaining_amount), 0)::numeric AS total_recv,
           COALESCE(SUM(i.remaining_amount) FILTER (
             WHERE i.due_date IS NULL OR i.due_date >= public.org_today_v1(NULL)), 0)::numeric AS not_due,
           COALESCE(SUM(i.remaining_amount) FILTER (
             WHERE public.org_today_v1(NULL) - i.due_date BETWEEN 1  AND 30), 0)::numeric AS d1_30,
           COALESCE(SUM(i.remaining_amount) FILTER (
             WHERE public.org_today_v1(NULL) - i.due_date BETWEEN 31 AND 60), 0)::numeric AS d31_60,
           COALESCE(SUM(i.remaining_amount) FILTER (
             WHERE public.org_today_v1(NULL) - i.due_date BETWEEN 61 AND 90), 0)::numeric AS d61_90,
           COALESCE(SUM(i.remaining_amount) FILTER (
             WHERE public.org_today_v1(NULL) - i.due_date > 90), 0)::numeric AS d90p
    FROM public.invoices i
    JOIN allowed a ON a.id = i.building_id
    WHERE i.deleted_at IS NULL
      AND i.status IN ('APPROVED', 'PARTIAL_PAID', 'OVERDUE')
      AND i.remaining_amount > 0
    GROUP BY i.building_id
  )
  SELECT
    a.id, a.name,
    COALESCE(rs.total_r, 0), COALESCE(rs.avail, 0), COALESCE(rs.occ, 0),
    COALESCE(rs.resv, 0), COALESCE(rs.maint, 0), COALESCE(rs.unavail, 0),
    COALESCE(rs.vacancy_loss, 0),
    COALESCE(cs.actives, 0),
    COALESCE(cs.avg_rent_b, 0),
    COALESCE(cs.dep_held, 0),
    COALESCE(rc.total_recv, 0),
    COALESCE(rc.not_due, 0), COALESCE(rc.d1_30, 0), COALESCE(rc.d31_60, 0),
    COALESCE(rc.d61_90, 0), COALESCE(rc.d90p, 0)
  FROM allowed a
  LEFT JOIN room_stats     rs ON rs.bid = a.id
  LEFT JOIN contract_stats cs ON cs.bid = a.id
  LEFT JOIN receivables    rc ON rc.bid = a.id
  ORDER BY a.name;
$$;








--
-- Name: FUNCTION fa_snapshot_kpis(p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_snapshot_kpis(p_building_ids uuid[]) IS 'KPI thời điểm × toà (loại toà ảo): trạng thái phòng, vacancy loss/tháng, HĐ ACTIVE + ARPU, cọc đang giữ (Σ deposit_paid HĐ ACTIVE), phải thu + aging theo due_date (not_due/1-30/31-60/61-90/>90).';








--
-- Name: fa_type_breakdown(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_type_breakdown(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, side text, type_id uuid, type_name text, category text, total_amount numeric, voucher_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  base AS (
    SELECT voucher.id, voucher.type, voucher.total_amount,
           voucher.business_result_accounting AS override,
           date_trunc('month', voucher.voucher_date)::date AS m
    FROM public.income_expenses voucher
    JOIN allowed a ON a.id = voucher.building_id
    WHERE voucher.deleted_at IS NULL
      AND voucher.approval_status = 'APPROVED'
      AND voucher.business_result_accounting IS DISTINCT FROM false
      AND voucher.voucher_date BETWEEN p_start_date AND p_end_date
  )
  SELECT base.m, base.type::text, type_row.id, type_row.name, type_row.category,
         SUM(COALESCE(item.amount, item.unit_price * item.quantity))::numeric,
         COUNT(DISTINCT base.id)
  FROM base
  JOIN public.income_expense_items item ON item.income_expense_id = base.id
  JOIN public.income_expense_types type_row ON type_row.id = item.income_expense_type_id
  WHERE base.override IS TRUE OR item.accounting_class = 'PNL'
  GROUP BY base.m, base.type, type_row.id, type_row.name, type_row.category
  UNION ALL
  SELECT base.m, base.type::text, NULL::uuid, 'Không có hạng mục'::text, NULL::text,
         SUM(base.total_amount)::numeric, COUNT(*)
  FROM base
  WHERE NOT EXISTS (
    SELECT 1 FROM public.income_expense_items item WHERE item.income_expense_id = base.id
  )
  GROUP BY base.m, base.type
  ORDER BY 1, 2, 6 DESC;
$$;








--
-- Name: FUNCTION fa_type_breakdown(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_type_breakdown(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Cơ cấu thu/chi KQKD theo tháng × hạng mục (item-level: loại item is_deposit trừ khi phiếu ép TRUE). Σ total_amount == Σ fa_monthly_pnl cùng kỳ.';








--
-- Name: fa_type_breakdown_accrual(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fa_type_breakdown_accrual(p_start_date date, p_end_date date, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(month date, side text, type_id uuid, type_name text, category text, total_amount numeric, voucher_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    al.month, al.side, al.type_id, al.type_name, al.category,
    SUM(al.amount)::numeric, COUNT(DISTINCT al.voucher_id)
  FROM public.fa_accrual_allocations(p_start_date, p_end_date, p_building_ids) al
  GROUP BY al.month, al.side, al.type_id, al.type_name, al.category
  ORDER BY al.month, al.side, SUM(al.amount) DESC;
$$;








--
-- Name: FUNCTION fa_type_breakdown_accrual(p_start_date date, p_end_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fa_type_breakdown_accrual(p_start_date date, p_end_date date, p_building_ids uuid[]) IS 'Cơ cấu thu/chi DỒN TÍCH theo tháng × hạng mục (cùng shape fa_type_breakdown). Σ total_amount == Σ fa_monthly_pnl_accrual cùng kỳ.';








--
-- Name: fee_type_matches(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fee_type_matches(p_category_key text, p_cat text, p_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE p_category_key
    WHEN 'internet'  THEN (public.nrm_vn(p_cat) = 'internet' OR public.nrm_vn(p_name) LIKE '%internet%')
    WHEN 'rac'       THEN (public.nrm_vn(p_name) LIKE '%rac%')
    WHEN 'cong_an'   THEN (public.nrm_vn(p_cat) = 'ca' OR public.nrm_vn(p_name) LIKE '%cong an%')
    WHEN 've_sinh'   THEN ((public.nrm_vn(p_cat) = 've sinh' OR public.nrm_vn(p_name) LIKE '%ve sinh toa nha%')
                             AND public.nrm_vn(p_name) NOT LIKE '%rac%')
    WHEN 'thang_may' THEN (public.nrm_vn(p_name) LIKE '%thang may%')
    WHEN 'dien'      THEN (public.nrm_vn(p_cat) = 'dien' OR public.nrm_vn(p_name) LIKE '%tien dien%')
    WHEN 'nuoc'      THEN (public.nrm_vn(p_cat) = 'nuoc' OR public.nrm_vn(p_name) LIKE '%tien nuoc%')
    WHEN 'tien_nha'  THEN (public.nrm_vn(p_cat) = 'tien nha' OR public.nrm_vn(p_name) LIKE '%tien nha%')
    -- A1: phí quản lý KHÔNG phải tiền lương. Loại 'Lương quản lý',
    -- 'Ứng lương quản lý' và mọi type có category CHỨA 'luong' ('Lương',
    -- 'Lương thưởng', 'Lương nhân viên'…). Vế category phải là NOT LIKE — không
    -- phải `<> 'luong'` — để khớp ĐÚNG bản mirror TypeScript
    -- (src/lib/feeCategories.ts: `!c.includes('luong')`); xem ghi chú A1 đầu file.
    WHEN 'quan_ly'   THEN (public.nrm_vn(p_name) LIKE '%quan ly%'
                             AND public.nrm_vn(p_name) NOT LIKE '%luong%'
                             AND public.nrm_vn(p_cat)  NOT LIKE '%luong%')
    ELSE false
  END
$$;








--
-- Name: FUNCTION fee_type_matches(p_category_key text, p_cat text, p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fee_type_matches(p_category_key text, p_cat text, p_name text) IS 'Matcher hạng mục phí cố định (9 kind) dùng chung cho resolve_fixed_expense_type / pay_period_fee / cancel_period_fee / get_period_fee_status. Slice −1 A1: nhánh quan_ly loại tiền lương (name CHỨA "luong", hoặc category CHỨA "luong") — trước đó 34.206.744đ lương của org thật bị cộng vào ô phí Quản Lý và DEMO thì không có type Quản Lý nên khoản chi quản lý bị ghi vào type lương.';








--
-- Name: finalize_ai_usage(uuid, integer, integer, integer, integer, numeric, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_ai_usage(p_id uuid, p_prompt_tokens integer, p_completion_tokens integer, p_total_tokens integer, p_cached_tokens integer, p_cost_usd numeric, p_latency_ms integer, p_status text, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.ai_usage_logs SET
    prompt_tokens     = COALESCE(p_prompt_tokens, 0),
    completion_tokens = COALESCE(p_completion_tokens, 0),
    total_tokens      = COALESCE(p_total_tokens, 0),
    cached_tokens     = COALESCE(p_cached_tokens, 0),
    cost_usd          = p_cost_usd,
    latency_ms        = p_latency_ms,
    status            = COALESCE(p_status, 'ok'),
    error_detail      = p_error
  WHERE id = p_id;
END $$;








--
-- Name: finalize_finance_evidence_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_finance_evidence_v2(p_evidence_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_row public.finance_evidence_objects%ROWTYPE;
  v_meta jsonb;
BEGIN
  SELECT * INTO v_row FROM public.finance_evidence_objects
  WHERE id = p_evidence_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence không tồn tại' USING ERRCODE = 'P0002'; END IF;
  IF v_row.uploader_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Chỉ người tạo intent được finalize chứng từ này' USING ERRCODE = '42501';
  END IF;
  IF v_row.state = 'FINALIZED' THEN
    RETURN jsonb_build_object('evidence_id', v_row.id, 'state', 'FINALIZED'); -- idempotent
  END IF;
  IF v_row.state <> 'UPLOAD_INTENT' THEN
    RAISE EXCEPTION 'Evidence ở trạng thái % — không finalize được', v_row.state USING ERRCODE = '55000';
  END IF;

  SELECT o.metadata INTO v_meta
  FROM storage.objects o
  WHERE o.bucket_id = v_row.bucket_id AND o.name = v_row.object_name
    AND o.owner = auth.uid();
  IF v_meta IS NULL THEN
    RAISE EXCEPTION 'Chưa thấy file upload đúng path/owner — hãy upload trước khi finalize'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.finance_evidence_objects
     SET state = 'FINALIZED', finalized_at = now(),
         byte_size = NULLIF(v_meta->>'size','')::bigint,
         mime_type = v_meta->>'mimetype'
   WHERE id = p_evidence_id;

  -- Shield đọc storage (PS03): member org xem lại được ảnh chứng từ.
  INSERT INTO app_private.storage_object_links (bucket_id, object_name, organization_id, owner_user_id, derivation)
  VALUES (v_row.bucket_id, v_row.object_name, v_row.organization_id, auth.uid(), 'FINANCE_V2_EVIDENCE')
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('evidence_id', v_row.id, 'state', 'FINALIZED');
END
$$;








--
-- Name: finance_v2_pending_kqkd_blockers(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_v2_pending_kqkd_blockers(p_org uuid, p_period date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_period date;
  v_result jsonb;
BEGIN
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'finance_v2_pending_kqkd_blockers: organization is required' USING ERRCODE = '22023';
  END IF;
  IF p_period IS NULL THEN
    RAISE EXCEPTION 'finance_v2_pending_kqkd_blockers: period is required' USING ERRCODE = '22023';
  END IF;
  IF NOT (p_org = ANY (public.my_org_ids())) THEN
    RAISE EXCEPTION 'finance_v2_pending_kqkd_blockers: not a member of organization %', p_org
      USING ERRCODE = '42501';
  END IF;

  v_period := date_trunc('month', p_period)::date;

  WITH c AS (
    SELECT ec.source_voucher_id,
           ec.source_approval_status,
           ec.source_review_state,
           ec.signed_kqkd_amount,
           ie.posting_mode,
           ie.posting_status
    FROM app_private.effective_profit_contributions_v2(p_org, v_period) ec
    LEFT JOIN public.income_expenses ie
      ON ie.id = ec.source_voucher_id AND ie.organization_id = p_org
    WHERE ec.signed_kqkd_amount <> 0
  ),
  pend AS (
    SELECT * FROM c WHERE c.source_approval_status = 'UNAPPROVED'
  ),
  appr AS (
    SELECT * FROM c
    WHERE c.source_approval_status = 'APPROVED'
      AND c.posting_mode = 'CASHBOOK'
      AND c.posting_status = 'UNPOSTED'
  )
  SELECT jsonb_build_object(
    'organization_id',          p_org,
    'target_period',            v_period,
    'pending_kqkd_count',       (SELECT COUNT(DISTINCT source_voucher_id) FROM pend),
    'pending_kqkd_amount',      COALESCE((SELECT SUM(signed_kqkd_amount) FROM pend), 0),
    'changes_requested_count',  (SELECT COUNT(DISTINCT source_voucher_id) FROM pend WHERE source_review_state = 'CHANGES_REQUESTED'),
    'disputed_count',           (SELECT COUNT(DISTINCT source_voucher_id) FROM pend WHERE source_review_state = 'DISPUTED'),
    'approved_unposted_count',  (SELECT COUNT(DISTINCT source_voucher_id) FROM appr),
    'approved_unposted_amount', COALESCE((SELECT SUM(signed_kqkd_amount) FROM appr), 0),
    'blocking_voucher_ids',     COALESCE((SELECT jsonb_agg(DISTINCT source_voucher_id) FROM pend), '[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END
$$;








--
-- Name: FUNCTION finance_v2_pending_kqkd_blockers(p_org uuid, p_period date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finance_v2_pending_kqkd_blockers(p_org uuid, p_period date) IS 'Plan §11.4: close-preview blockers computed from effective_profit_contributions_v2 for the period being closed (pending UNAPPROVED KQKD count/amount + changes_requested/disputed subsets + informational approved_unposted). Tenant-scoped.';








