$$;








--
-- Name: gen_contract_public_code(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_contract_public_code(len integer DEFAULT 6) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  alphabet text := '23456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ';
  alen int := length(alphabet);          -- 57
  raw text := '';
  bytes bytea;
  result text := '';
  i int;
BEGIN
  -- Gom đủ byte ngẫu nhiên: mỗi uuid = 16 byte = 32 ký tự hex.
  WHILE length(raw) < len * 2 LOOP
    raw := raw || replace(gen_random_uuid()::text, '-', '');
  END LOOP;
  bytes := decode(substr(raw, 1, len * 2), 'hex');
  FOR i IN 0..len - 1 LOOP
    result := result || substr(alphabet, (get_byte(bytes, i) % alen) + 1, 1);
  END LOOP;
  RETURN result;
END;
$$;








--
-- Name: generate_code(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_code(p_user_id uuid, p_object_type text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_config RECORD;
  v_next_seq INTEGER;
  v_code TEXT;
  v_date_part TEXT;
  v_need_reset BOOLEAN := false;
BEGIN
  -- Get config
  SELECT * INTO v_config
  FROM code_sequences
  WHERE user_id = p_user_id AND object_type = p_object_type;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Code configuration not found for %', p_object_type;
  END IF;

  -- Check if need reset
  IF v_config.reset_period = 'DAILY' AND
     v_config.last_reset_at < public.org_today_v1(NULL) THEN
    v_need_reset := true;
  ELSIF v_config.reset_period = 'MONTHLY' AND
        DATE_TRUNC('month', v_config.last_reset_at) < DATE_TRUNC('month', public.org_today_v1(NULL)) THEN
    v_need_reset := true;
  ELSIF v_config.reset_period = 'YEARLY' AND
        DATE_TRUNC('year', v_config.last_reset_at) < DATE_TRUNC('year', public.org_today_v1(NULL)) THEN
    v_need_reset := true;
  END IF;

  -- Reset or increment
  IF v_need_reset THEN
    v_next_seq := 1;
  ELSE
    v_next_seq := v_config.current_sequence + 1;
  END IF;

  -- Generate date part
  IF v_config.date_format IS NOT NULL THEN
    v_date_part := TO_CHAR(public.org_today_v1(NULL), v_config.date_format);
  END IF;

  -- Build code
  v_code := v_config.prefix;

  IF v_date_part IS NOT NULL THEN
    v_code := v_code || v_config.separator || v_date_part;
  END IF;

  v_code := v_code || v_config.separator ||
            LPAD(v_next_seq::TEXT, v_config.sequence_length, '0');

  -- Update sequence
  UPDATE code_sequences
  SET current_sequence = v_next_seq,
      last_reset_at = CASE WHEN v_need_reset THEN public.org_today_v1(NULL) ELSE last_reset_at END,
      updated_at = NOW()
  WHERE user_id = p_user_id AND object_type = p_object_type;

  RETURN v_code;
END;
$$;








--
-- Name: FUNCTION generate_code(p_user_id uuid, p_object_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_code(p_user_id uuid, p_object_type text) IS 'Generate auto-incrementing codes for various entity types';








--
-- Name: generate_contract_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_contract_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prefix TEXT;
  v_counter INTEGER;
  v_new_number TEXT;
BEGIN
  IF NEW.contract_number IS NULL THEN
    -- Get user's contract prefix from settings (default: 'HD')
    SELECT COALESCE(value->>'contract_prefix', 'HD')
    INTO v_prefix
    FROM settings
    WHERE user_id = NEW.user_id AND key = 'contract_number_format';

    -- If no setting, use default
    IF v_prefix IS NULL THEN
      v_prefix := 'HD';
    END IF;

    -- Get next counter for this year
    SELECT COUNT(*) + 1
    INTO v_counter
    FROM contracts
    WHERE user_id = NEW.user_id
      AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NOW());

    -- Generate: HD-2024-00001
    v_new_number := v_prefix || '-' ||
                    TO_CHAR(NOW(), 'YYYY') || '-' ||
                    LPAD(v_counter::TEXT, 5, '0');

    NEW.contract_number := v_new_number;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: generate_invoice_number_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoice_number_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prefix TEXT;
  v_year   TEXT;
  v_seq    INTEGER;
BEGIN
  IF NEW.invoice_number IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_year := TO_CHAR(NOW(), 'YYYY');

  SELECT COALESCE(value->>'invoice_prefix', 'INV')
    INTO v_prefix
    FROM settings
   WHERE user_id = NEW.user_id AND key = 'invoice_number_format';

  IF v_prefix IS NULL OR v_prefix = '' THEN
    v_prefix := 'INV';
  END IF;

  -- Serialize concurrent inserts sharing the same prefix+year so MAX+1 cannot race.
  PERFORM pg_advisory_xact_lock(hashtext('invoice_number:' || v_prefix || ':' || v_year));

  -- GLOBAL max over "<prefix>-<year>-<digits>" (constraint is global, not per-user).
  SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '(\d+)$') AS INTEGER)), 0) + 1
    INTO v_seq
    FROM invoices
   WHERE invoice_number LIKE (v_prefix || '-' || v_year || '-%')
     AND invoice_number ~ ('^' || v_prefix || '-' || v_year || '-\d+$');

  NEW.invoice_number := v_prefix || '-' || v_year || '-' || LPAD(v_seq::TEXT, 5, '0');
  RETURN NEW;
END;
$_$;








--
-- Name: generate_invoices_for_building(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoices_for_building(p_user_id uuid, p_building_id uuid, p_billing_month text, p_invoice_type text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_contract RECORD;
  v_service RECORD;
  v_invoice_id UUID;
  v_created_count INT := 0;
  v_skipped_contracts JSON[] := ARRAY[]::JSON[];
  v_subtotal DECIMAL(15, 2);
  v_item_amount DECIMAL(15, 2);
  v_sort_order INT;
BEGIN
  IF p_invoice_type NOT IN ('rent_only', 'service_only', 'both') THEN
    RAISE EXCEPTION 'Invalid invoice_type: %. Must be rent_only, service_only, or both', p_invoice_type;
  END IF;

  IF p_billing_month !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Invalid billing_month format: %. Must be YYYY-MM', p_billing_month;
  END IF;

  FOR v_contract IN
    SELECT c.id AS contract_id, c.user_id, c.room_id, c.rent_price, r.building_id
    FROM contracts c
    JOIN rooms r ON r.id = c.room_id
    WHERE c.user_id = p_user_id
      AND r.building_id = p_building_id
      AND c.status = 'ACTIVE'
      AND c.deleted_at IS NULL
  LOOP
    IF EXISTS (
      SELECT 1 FROM invoices
      WHERE contract_id = v_contract.contract_id
        AND billing_month = p_billing_month
        AND deleted_at IS NULL
        AND kind = 'MONTHLY'
    ) THEN
      v_skipped_contracts := array_append(
        v_skipped_contracts,
        json_build_object('contract_id', v_contract.contract_id, 'reason', 'Invoice already exists')
      );
      CONTINUE;
    END IF;

    INSERT INTO invoices (
      user_id, contract_id, building_id, room_id,
      billing_month, issue_date, due_date,
      status, approved_at, approved_by,
      subtotal, total_amount
    ) VALUES (
      p_user_id, v_contract.contract_id, v_contract.building_id,
      v_contract.room_id,
      p_billing_month, public.org_today_v1(NULL), public.org_today_v1(NULL) + INTERVAL '5 days',
      'APPROVED', NOW(), p_user_id,
      0, 0
    )
    RETURNING id INTO v_invoice_id;

    v_subtotal := 0;
    v_sort_order := 0;

    IF p_invoice_type IN ('rent_only', 'both') THEN
      v_item_amount := v_contract.rent_price;
      v_sort_order := v_sort_order + 1;

      INSERT INTO invoice_items (
        invoice_id, type, description, unit_price, quantity, coefficient, amount, sort_order
      ) VALUES (
        v_invoice_id, 'RENT', 'Tiền thuê phòng',
        v_contract.rent_price, 1, 1, v_item_amount, v_sort_order
      );

      v_subtotal := v_subtotal + v_item_amount;
    END IF;

    IF p_invoice_type IN ('service_only', 'both') THEN
      FOR v_service IN
        SELECT cs.service_id, cs.unit_price, s.name AS service_name, s.type AS service_type
        FROM contract_services cs
        JOIN services s ON s.id = cs.service_id
        WHERE cs.contract_id = v_contract.contract_id
      LOOP
        v_sort_order := v_sort_order + 1;
        v_item_amount := v_service.unit_price;

        INSERT INTO invoice_items (
          invoice_id, service_id, type, description,
          unit_price, quantity, coefficient, amount, sort_order
        ) VALUES (
          v_invoice_id, v_service.service_id, 'SERVICE', v_service.service_name,
          v_service.unit_price, 1, 1, v_item_amount, v_sort_order
        );

        v_subtotal := v_subtotal + v_item_amount;
      END LOOP;
    END IF;

    UPDATE invoices
    SET subtotal = v_subtotal, total_amount = v_subtotal
    WHERE id = v_invoice_id;

    v_created_count := v_created_count + 1;
  END LOOP;

  RETURN json_build_object(
    'created_count', v_created_count,
    'skipped_contracts', to_json(v_skipped_contracts)
  );
END;
$_$;








