COMMENT ON FUNCTION public.generate_invoices_for_building(p_user_id uuid, p_building_id uuid, p_billing_month text, p_invoice_type text) IS 'Generate invoices for all active contracts in a building for a given billing month. Defaults to APPROVED status.';








--
-- Name: generate_invoices_for_building_v2(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoices_for_building_v2(p_building_id uuid, p_billing_month text, p_invoice_type text DEFAULT 'RENT'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF NOT public.can_do_on_building('invoices','create', p_building_id) THEN
    RAISE EXCEPTION 'Access denied for building %', p_building_id;
  END IF;

  -- Delegate to v1 — v1 dùng p_user_id để INSERT; trigger auto sẽ override user_id = auth.uid()
  -- nhưng v1 còn dùng p_user_id ở nhiều chỗ filter. Để an toàn không thay đổi logic v1,
  -- ta gọi v1 với p_user_id = building owner (lookup buildings.user_id).
  RETURN public.generate_invoices_for_building(
    (SELECT user_id FROM buildings WHERE id = p_building_id),
    p_building_id, p_billing_month, p_invoice_type
  );
END;
$$;








