--
-- Name: generate_job_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_job_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today TEXT := TO_CHAR(NOW(), 'YYYYMMDD');
  v_lock_key BIGINT;
  v_next INT;
BEGIN
  -- Khoá theo "ngày" để 2 INSERT đồng thời trong cùng ngày phải xếp hàng.
  -- hashtext trả về int4 → cast sang bigint cho pg_advisory_xact_lock.
  v_lock_key := hashtext('jobs_code:' || v_today)::BIGINT;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  SELECT COALESCE(MAX(CAST(SUBSTRING(code FROM 'JOB-\d{8}-(\d+)') AS INTEGER)), 0) + 1
    INTO v_next
    FROM public.jobs
   WHERE code LIKE 'JOB-' || v_today || '-%';

  NEW.code := 'JOB-' || v_today || '-' || LPAD(v_next::TEXT, 4, '0');
  RETURN NEW;
END;
$$;








--
-- Name: generate_next_code(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_next_code(p_user_id uuid, p_object_type character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  seq_record RECORD;
  next_seq INTEGER;
  current_period VARCHAR;
  new_code VARCHAR;
BEGIN
  -- Lock and get sequence record
  SELECT * INTO seq_record
  FROM code_sequences
  WHERE user_id = p_user_id AND object_type = p_object_type
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Create default sequence if not exists
    INSERT INTO code_sequences (user_id, object_type, prefix, date_format, separator, sequence_length, reset_period, current_sequence)
    VALUES (p_user_id, p_object_type, SUBSTRING(p_object_type FROM 1 FOR 2), 'YYMM', '-', 4, 'MONTHLY', 1)
    RETURNING * INTO seq_record;
  END IF;

  -- Get current period
  current_period := TO_CHAR(public.org_today_v1(NULL), seq_record.date_format);

  -- Check if we need to reset sequence
  IF seq_record.reset_period = 'MONTHLY' AND
     (seq_record.last_reset_at IS NULL OR
      TO_CHAR(seq_record.last_reset_at, 'YYMM') != current_period) THEN
    next_seq := 1;
    UPDATE code_sequences
    SET current_sequence = 2, last_reset_at = CURRENT_TIMESTAMP
    WHERE id = seq_record.id;
  ELSIF seq_record.reset_period = 'YEARLY' AND
        (seq_record.last_reset_at IS NULL OR
         TO_CHAR(seq_record.last_reset_at, 'YY') != TO_CHAR(public.org_today_v1(NULL), 'YY')) THEN
    next_seq := 1;
    UPDATE code_sequences
    SET current_sequence = 2, last_reset_at = CURRENT_TIMESTAMP
    WHERE id = seq_record.id;
  ELSE
    next_seq := COALESCE(seq_record.current_sequence, 1);
    UPDATE code_sequences
    SET current_sequence = next_seq + 1
    WHERE id = seq_record.id;
  END IF;

  -- Build code
  new_code := seq_record.prefix || seq_record.separator || current_period || seq_record.separator ||
              LPAD(next_seq::TEXT, seq_record.sequence_length, '0');

  RETURN new_code;
END;
$$;








--
-- Name: generate_recurring_vouchers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_recurring_vouchers(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(parent_id uuid, child_id uuid, voucher_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  parent   RECORD;
  v_child  uuid;
  v_target date;
  k        int;
  v_total  int;
BEGIN
  FOR parent IN
    SELECT *
    FROM income_expenses ie
    WHERE ie.repeat_cycle <> 'NONE'
      AND ie.deleted_at IS NULL
      AND ie.repeat_parent_id IS NULL
      AND ie.approval_status = 'APPROVED'
      AND (p_user_id IS NULL OR ie.user_id = p_user_id)
      AND (ie.repeat_infinity OR ie.repeat_count > 0)
  LOOP
    k := 1;
    LOOP
      v_target := public.add_cycle(parent.voucher_date, parent.repeat_cycle, k);

      EXIT WHEN v_target > public.org_today_v1(NULL);
      EXIT WHEN (NOT parent.repeat_infinity) AND k > parent.repeat_count;
      EXIT WHEN k > 240;

      IF NOT EXISTS (
        SELECT 1 FROM income_expenses c
        WHERE c.repeat_parent_id = parent.id
          AND c.voucher_date = v_target
          AND c.deleted_at IS NULL
      ) THEN
        BEGIN
          INSERT INTO income_expenses (
            user_id, type, name, building_id, room_id, tenant_id,
            contract_id, account_id, payer_name,
            approval_status, approved_at, approved_by,
            business_result_accounting, counts_in_business_result,
            attachments, notes,
            receive_bank_name, receive_bank_account,
            creator_name,
            voucher_date, invoice_id, repeat_parent_id,
            repeat_cycle, repeat_infinity, repeat_count, repeat_remaining
          ) VALUES (
            parent.user_id, parent.type,
            parent.name || ' (tự động lập)',
            parent.building_id, parent.room_id, parent.tenant_id,
            NULL,
            -- DRAFT MODE: sổ trống + NHÁP, điền sổ/ảnh khi thanh toán thật
            CASE WHEN parent.repeat_auto_approve THEN parent.account_id ELSE NULL END,
            parent.payer_name,
            CASE WHEN parent.repeat_auto_approve THEN 'APPROVED' ELSE 'UNAPPROVED' END,
            CASE WHEN parent.repeat_auto_approve THEN now() ELSE NULL END,
            CASE WHEN parent.repeat_auto_approve THEN parent.user_id ELSE NULL END,
            parent.business_result_accounting, parent.counts_in_business_result,
            parent.attachments, parent.notes,
            parent.receive_bank_name, parent.receive_bank_account,
            parent.creator_name,
            v_target, NULL, parent.id,
            'NONE', false, 0, 0
          ) RETURNING id INTO v_child;

          INSERT INTO income_expense_items (
            income_expense_id, income_expense_type_id,
            description, quantity, unit_price, start_date, end_date
          )
          SELECT v_child, ii.income_expense_type_id,
                 ii.description, ii.quantity, ii.unit_price, v_target, v_target
          FROM income_expense_items ii
          WHERE ii.income_expense_id = parent.id;

          RETURN QUERY SELECT parent.id, v_child, v_target;
        EXCEPTION WHEN OTHERS THEN
          RAISE NOTICE 'recurring child skipped parent=% date=%: %', parent.id, v_target, SQLERRM;
        END;
      END IF;

      k := k + 1;
    END LOOP;

    SELECT count(*) INTO v_total
    FROM income_expenses c
    WHERE c.repeat_parent_id = parent.id AND c.deleted_at IS NULL;

    BEGIN
      UPDATE income_expenses
      SET repeat_remaining = CASE
            WHEN parent.repeat_infinity THEN 0
            ELSE GREATEST(0, parent.repeat_count - v_total)
          END,
          repeat_next_date = CASE
            WHEN parent.repeat_infinity OR v_total < parent.repeat_count
              THEN public.add_cycle(parent.voucher_date, parent.repeat_cycle, v_total + 1)
            ELSE NULL
          END
      WHERE id = parent.id;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'recurring bookkeeping skipped parent=%: %', parent.id, SQLERRM;
    END;
  END LOOP;
END;
$$;








--
-- Name: FUNCTION generate_recurring_vouchers(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_recurring_vouchers(p_user_id uuid) IS 'Sinh phiếu con cho các phiếu GỐC (repeat_parent_id NULL, APPROVED, repeat_cycle<>NONE). Phiếu gốc = kỳ #1; con sinh từ kỳ kế tiếp (add_cycle neo ngày, chống drift). Idempotent (dedup theo (repeat_parent_id, voucher_date)); cô lập lỗi từng con. p_user_id NULL = mọi owner (dùng cho job nền pg_cron).';








--
-- Name: generate_recurring_vouchers_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_recurring_vouchers_v2() RETURNS TABLE(parent_id uuid, child_id uuid, voucher_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner_ids uuid[];
  v_owner uuid;
BEGIN
  -- Lấy danh sách owner mà caller có quyền (super_admin → all owners; staff → các owner mình thuộc)
  IF public.is_super_admin() THEN
    SELECT array_agg(DISTINCT user_id) INTO v_owner_ids FROM buildings WHERE deleted_at IS NULL;
  ELSE
    SELECT array_agg(DISTINCT sa.user_id) INTO v_owner_ids
    FROM staff_assignments sa WHERE sa.staff_id = auth.uid();
  END IF;

  IF v_owner_ids IS NULL OR array_length(v_owner_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_owner IN ARRAY v_owner_ids LOOP
    RETURN QUERY SELECT * FROM public.generate_recurring_vouchers(v_owner);
  END LOOP;
END;
$$;








--
-- Name: FUNCTION generate_recurring_vouchers_v2(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_recurring_vouchers_v2() IS 'RBAC wrapper: gọi v1 cho từng owner caller có quyền (super_admin = all, staff = các owner mình thuộc).';








--
-- Name: generate_special_fees_v1(text, uuid[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_special_fees_v1(p_period text, p_building_ids uuid[], p_idempotency_key text, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_m0    date;
  v_m1    date;
  v_route text;
  v_key   text := btrim(COALESCE(p_idempotency_key,''));
  r       record;
  v_type  uuid;
  v_ie    uuid;
  v_code  text;
  v_n     int := 0;
  v_sum   numeric := 0;
  v_ids   uuid[] := '{}';
  v_label text;
  -- SPECIAL_FEE_AUTOPOST_V1
  v_acc      uuid;
  v_posted   int := 0;
  v_rule     jsonb;
BEGIN
  -- Sổ quỹ (tuỳ chọn): có thì máy duyệt hộ + ghi sổ; không có thì y như cũ.
  IF p_account_id IS NOT NULL THEN
    SELECT a.id INTO v_acc FROM public.accounts a
     WHERE a.id = p_account_id AND a.deleted_at IS NULL
       AND NOT COALESCE(a.is_virtual, false);
    IF v_acc IS NULL THEN
      RAISE EXCEPTION 'Sổ quỹ không hợp lệ hoặc là SỔ ẢO — phí cố định là tiền thật ra khỏi két'
        USING ERRCODE = '22023';
    END IF;
  END IF;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_period !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Kỳ không hợp lệ (cần YYYY-MM)' USING ERRCODE='22023';
  END IF;
  IF char_length(v_key) < 8 OR char_length(v_key) > 200
     OR v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII an toàn' USING ERRCODE='22023';
  END IF;
  IF p_building_ids IS NULL OR array_length(p_building_ids,1) IS NULL THEN
    RAISE EXCEPTION 'Phải chọn ít nhất một toà' USING ERRCODE='22023';
  END IF;

  v_m0 := to_date(p_period || '-01','YYYY-MM-DD');
  v_m1 := (date_trunc('month', v_m0) + interval '1 month - 1 day')::date;

  SELECT b.organization_id INTO v_org FROM buildings b
   WHERE b.id = p_building_ids[1] AND b.deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='22023'; END IF;

  -- Mọi toà phải cùng org — không cho một lượt sinh chéo tổ chức.
  IF EXISTS (SELECT 1 FROM buildings b
              WHERE b.id = ANY(p_building_ids)
                AND (b.deleted_at IS NOT NULL OR b.organization_id IS DISTINCT FROM v_org)) THEN
    RAISE EXCEPTION 'Danh sách toà có toà đã xoá hoặc thuộc tổ chức khác' USING ERRCODE='42501';
  END IF;

  -- ROUTE OFF: cỗ máy này tự đẻ phiếu hàng loạt nên phải có công tắc riêng.
  v_route := app_private.evaluate_feature_route('special_fee.generate.v1', v_org);
  IF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION
      'Tính năng sinh phiếu phí cố định hàng loạt chưa được bật cho tổ chức này (route %). Bật cờ special_fee.generate.v1 rồi thử lại.',
      v_route USING ERRCODE = '55000';
  END IF;

  -- Khoá theo (org, kỳ): hai người bấm cùng lúc thì xếp hàng, không đẻ hai lượt.
  PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended('special_fee:'||v_org::text||':'||p_period, 0));

  FOR r IN
    SELECT * FROM public.preview_special_fees_v1(p_period, p_building_ids)
     WHERE status = 'SẼ_SINH'
  LOOP
    -- Quyền theo từng toà — preview đã lọc, nhưng writer không tin preview.
    IF NOT (public.can_access_building(r.building_id)
         OR public.ie_all_buildings_scope(r.building_id)
         OR public.is_admin() OR public.is_super_admin()) THEN
      CONTINUE;
    END IF;
    IF r.fee_category = 'quan_ly' AND NOT public.can_create_restricted_ie() THEN
      CONTINUE;   -- hạng mục hạn chế: bỏ qua thay vì làm hỏng cả lượt
    END IF;

    v_label := CASE r.fee_category
                 WHEN 'tien_nha' THEN 'Tiền nhà'   WHEN 'dien' THEN 'Tiền điện'
                 WHEN 'nuoc' THEN 'Tiền nước'      WHEN 'internet' THEN 'Internet'
                 WHEN 'quan_ly' THEN 'Quản Lý'     WHEN 've_sinh' THEN 'Vệ sinh định kỳ'
                 WHEN 'cong_an' THEN 'Công An'     WHEN 'rac' THEN 'Rác'
                 ELSE 'Thang máy' END;

    v_type := app_private.ensure_income_expense_type_v1(
                v_org, v_actor, v_label, 'expense', NULL, NULL, false, false,
                (r.fee_category = 'quan_ly'), false, false, false);

    INSERT INTO income_expenses
      (user_id, organization_id, type, name, building_id, voucher_date,
       total_amount, approval_status, system_source, notes)
    VALUES
      (v_actor, v_org, 'EXPENSE',
       v_label || ' ' || r.building_name || ' kỳ ' || p_period,
       r.building_id, public.org_today_v1(v_org),
       r.amount, 'UNAPPROVED', 'special_fee.v1',
       'Sinh tự động cho kỳ ' || p_period)
    RETURNING id, code INTO v_ie, v_code;

    INSERT INTO income_expense_items
      (income_expense_id, income_expense_type_id, accounting_class,
       description, quantity, unit_price, amount, start_date, end_date)
    VALUES
      (v_ie, v_type, 'PNL', 'Kỳ ' || p_period, 1, r.amount, r.amount, v_m0, v_m1);

    INSERT INTO special_fee_claims
      (organization_id, building_id, fee_category, period_month, amount,
       voucher_id, generated_by, batch_key)
    VALUES (v_org, r.building_id, r.fee_category, v_m0, r.amount, v_ie, v_actor, v_key);

    IF v_acc IS NOT NULL THEN
      UPDATE income_expenses SET account_id = v_acc WHERE id = v_ie;
      v_rule := app_private.special_fee_rule_check_v1(
                  v_org, r.building_id, r.fee_category, v_m0, v_m1, r.amount);
      IF (v_rule->>'verdict') IN ('VALID', 'CONFIG_REQUIRED') THEN
        PERFORM app_private.special_fee_approve_and_post_v1(v_ie, 'SPECIAL_PAGE_FEE');
        v_posted := v_posted + 1;
      END IF;
    END IF;

    v_n := v_n + 1; v_sum := v_sum + r.amount; v_ids := v_ids || v_ie;
  END LOOP;

  RETURN jsonb_build_object(
    'period', p_period, 'organizationId', v_org, 'batchKey', v_key,
    'created', v_n, 'totalAmount', v_sum, 'voucherIds', to_jsonb(v_ids),
    'posted', v_posted,
    'note', CASE WHEN v_acc IS NULL
      THEN 'Phiếu sinh ra ở trạng thái CHỜ DUYỆT — máy đề xuất, người duyệt.'
      ELSE v_posted || '/' || v_n || ' phiếu đã tự duyệt và vào sổ; phần còn lại chờ duyệt vì lệch giá đã công bố.'
    END);
END;
$_$;








--
-- Name: generate_template_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_template_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_month TEXT;
  v_sequence INTEGER;
BEGIN
  IF NEW.code IS NOT NULL AND NEW.code != '' THEN
    RETURN NEW;
  END IF;

  v_month := TO_CHAR(public.org_today_v1(NULL), 'YYMM');

  PERFORM pg_advisory_xact_lock(hashtext('MT' || v_month || COALESCE(NEW.user_id::text, '')));

  SELECT COALESCE(MAX(
    CASE
      WHEN code ~ ('^MT\d{4}\d+$')
        AND SUBSTRING(code FROM 3 FOR 4) = v_month
      THEN CAST(SUBSTRING(code FROM 7) AS INTEGER)
      ELSE 0
    END
  ), 0) + 1
  INTO v_sequence
  FROM income_expense_templates
  WHERE user_id = NEW.user_id
    AND code LIKE 'MT' || v_month || '%';

  NEW.code := 'MT' || v_month || LPAD(v_sequence::TEXT, 3, '0');
  RETURN NEW;
END;
$_$;








--
-- Name: get_acceptance_geofence_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acceptance_geofence_config() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_caller UUID := auth.uid();
  v_owner  UUID;
  v_value  JSONB;
  v_enabled BOOLEAN := TRUE;
  v_radius  INTEGER := 70;
BEGIN
  IF v_caller IS NULL THEN
    RETURN json_build_object('enabled', true, 'radius_m', 70);
  END IF;

  -- Resolve owner: super-admin/owner = chính mình; staff = chủ workspace.
  IF EXISTS (SELECT 1 FROM super_admins WHERE user_id = v_caller) THEN
    v_owner := v_caller;
  ELSE
    SELECT sa.user_id INTO v_owner
    FROM staff_assignments sa
    WHERE sa.staff_id = v_caller AND sa.user_id <> v_caller
    LIMIT 1;
    IF v_owner IS NULL THEN
      v_owner := v_caller;
    END IF;
  END IF;

  SELECT s.value INTO v_value
  FROM settings s
  WHERE s.user_id = v_owner AND s.key = 'acceptance_geofence'
  LIMIT 1;

  IF v_value IS NOT NULL THEN
    IF jsonb_typeof(v_value -> 'enabled') = 'boolean' THEN
      v_enabled := (v_value ->> 'enabled')::boolean;
    END IF;
    IF (v_value ->> 'radius_m') ~ '^\d+$' THEN
      v_radius := (v_value ->> 'radius_m')::integer;
    END IF;
  END IF;

  RETURN json_build_object('enabled', v_enabled, 'radius_m', v_radius);
END;
$_$;








--
-- Name: FUNCTION get_acceptance_geofence_config(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_acceptance_geofence_config() IS 'Trả {enabled, radius_m} của cấu hình geo-fence nghiệm thu (đọc settings của owner). SECURITY DEFINER để staff dùng chung. Mặc định enabled=true, radius_m=70.';








--
-- Name: get_approval_request_detail_compat_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_approval_request_detail_compat_v2(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  r           public.approval_requests;
  v_mem       uuid;
  v_is_super  boolean;
  v_is_maker  boolean := false;
  v_can_decide boolean := false;
  v_steps     jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO r FROM public.approval_requests WHERE id = p_request_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_is_super := public.is_super_admin();

  -- Actor phải là ACTIVE member của org request (member thường: không cross-org).
  SELECT m.id INTO v_mem
  FROM public.organization_memberships m
  WHERE m.user_id = v_uid
    AND m.organization_id = r.organization_id
    AND m.status = 'ACTIVE'
  LIMIT 1;

  IF v_mem IS NULL AND NOT v_is_super THEN
    RETURN NULL;
  END IF;

  v_is_maker := (v_mem IS NOT NULL AND r.maker_membership_id = v_mem);

  -- Được xem nếu: super_admin, maker, hoặc từng là candidate (bất kỳ step/generation).
  IF NOT (
    v_is_super
    OR v_is_maker
    OR (v_mem IS NOT NULL AND EXISTS (
         SELECT 1
         FROM public.approval_request_steps st
         JOIN public.approval_request_step_candidates c
           ON c.request_step_id = st.id
          AND c.organization_id = st.organization_id
         WHERE st.request_id = r.id
           AND st.organization_id = r.organization_id
           AND c.membership_id = v_mem
       ))
  ) THEN
    RETURN NULL;
  END IF;

  -- Actor có thể duyệt ngay bây giờ? (candidate current generation, step PENDING, không phải maker)
  v_can_decide := r.state = 'PENDING_APPROVAL'
    AND NOT v_is_maker
    AND v_mem IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.approval_request_steps st
      JOIN public.approval_request_step_candidates c
        ON c.request_step_id = st.id
       AND c.organization_id = st.organization_id
      WHERE st.request_id = r.id
        AND st.organization_id = r.organization_id
        AND st.status = 'PENDING'
        AND c.membership_id = v_mem
        AND c.generation = st.current_generation
        AND (c.valid_to IS NULL OR c.valid_to > now())
    );

  -- Tóm tắt step (KHÔNG kèm danh tính candidate / decision / audit).
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'step_no',            st.step_no,
           'status',             st.status,
           'mode',               st.mode,
           'min_approvals',      st.min_approvals,
           'current_generation', st.current_generation,
           'candidate_count',    st.candidate_count
         ) ORDER BY st.step_no), '[]'::jsonb)
    INTO v_steps
  FROM public.approval_request_steps st
  WHERE st.request_id = r.id
    AND st.organization_id = r.organization_id;

  RETURN jsonb_build_object(
    'id',            r.id,
    'subject_type',  r.subject_type,
    'subject_id',    r.subject_id,
    'state',         r.state,
    'amount',        r.amount,
    'system_source', r.system_source,
    'cashbook_id',   r.cashbook_id,
    'building_id',   r.building_id,
    'submitted_at',  r.submitted_at,
    'posted_at',     r.posted_at,
    'rule_effect',   r.rule_effect,
    'version',       r.version,
    'is_maker',      v_is_maker,
    'can_decide',    v_can_decide,
    'steps',         v_steps
  );
END;
$$;








--
-- Name: FUNCTION get_approval_request_detail_compat_v2(p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_approval_request_detail_compat_v2(p_request_id uuid) IS 'Thu Chi V2 §9.4/§10(1019) containment: chi tiết 1 approval request scoped cho actor (maker/candidate/super_admin). Không payload_snapshot/candidate identities/audit.';








--
-- Name: get_authorization_context_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_authorization_context_v1(p_organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_org   uuid;
  v_memb  record;
  v_ket   jsonb;
begin
  if v_actor is null then
    raise exception 'Bạn chưa đăng nhập. Hãy đăng nhập lại rồi thử lại.'
      using errcode = '42501';
  end if;

  -- Chọn tổ chức. Thứ tự ổn định (điểm 1 + 2 ở header): org được chỉ định trước,
  -- rồi tới org thật (không phải demo), rồi tới tham gia sớm nhất, cuối cùng bám
  -- id để không bao giờ hoà.
  select m.organization_id into v_org
    from public.organization_memberships m
    join public.organizations o on o.id = m.organization_id and o.status = 'ACTIVE'
   where m.user_id = v_actor
     and m.status = 'ACTIVE'
     and coalesce(m.valid_from, '-infinity'::timestamptz) <= now()
     and (m.valid_to is null or m.valid_to > now())
     and (p_organization_id is null or m.organization_id = p_organization_id)
   order by coalesce(o.is_demo, false) asc,
            coalesce(m.activated_at, m.valid_from, 'infinity'::timestamptz) asc,
            m.organization_id asc
   limit 1;

  -- Không có membership nào (chưa mời / chưa kích hoạt / đã thu hồi), hoặc org chỉ
  -- định không phải của mình: trả gói rỗng, KHÔNG raise và KHÔNG tiết lộ tổ chức
  -- đó có tồn tại hay không.
  if v_org is null then
    return jsonb_build_object(
      'organizationId', null, 'membershipId', null, 'memberType', null,
      'authorizationVersion', null, 'nearestDeadline', null,
      'isPlatformAdmin', exists (select 1 from public.super_admins s where s.user_id = v_actor),
      'isOffboarded', app_private.is_actor_offboarded_v1(),
      'organizations', '[]'::jsonb,
      'permissions', '{}'::jsonb, 'scopeSets', '[]'::jsonb, 'scopes', '{}'::jsonb);
  end if;

  select m.id, m.member_type, o.authorization_version
    into v_memb
    from public.organization_memberships m
    join public.organizations o on o.id = m.organization_id
   where m.user_id = v_actor and m.organization_id = v_org and m.status = 'ACTIVE'
   order by coalesce(m.activated_at, m.valid_from, 'infinity'::timestamptz) asc, m.id asc
   limit 1;

  -- Chỉ liệt kê quyền ĐƯỢC PHÉP, và GOM PHẠM VI TRÙNG NHAU.
  --
  -- Bản đầu trả nguyên tập phạm vi cho từng quyền: 214 quyền x 21 mã toà nhà lặp
  -- lại => 342 kB cho chủ sở hữu. Frontend gọi mỗi phiên nên không chấp nhận được.
  -- Thực tế chỉ có vài tập phạm vi KHÁC NHAU (org-wide, theo toà, theo sổ quỹ...),
  -- nên tách thành `scopeSets` + `scopes[key]` trỏ CHỈ SỐ vào đó.
  --
  -- Thêm: khi org_wide = true thì KHÔNG liệt kê toà nữa — nó có nghĩa "mọi toà",
  -- liệt kê ra chỉ lặp lại danh sách toà mà frontend vốn đã có.
  with q as (
    select pd.key,
           s.org_wide,
           case when s.org_wide then '{}'::uuid[] else coalesce(s.building_ids,'{}'::uuid[]) end as building_ids,
           coalesce(s.cashbook_ids,'{}'::uuid[]) as cashbook_ids
      from public.permission_definitions pd
      cross join lateral app_private.authorized_scope_v3(pd.key, v_org) s
     where pd.permission_domain = 'TENANT'
       and pd.is_active
       and (s.org_wide
            or coalesce(array_length(s.building_ids, 1), 0) > 0
            or coalesce(array_length(s.cashbook_ids, 1), 0) > 0)
  ),
  tap as (
    select distinct org_wide, building_ids, cashbook_ids from q
  ),
  tap_so as (
    select row_number() over (order by org_wide desc, building_ids, cashbook_ids) - 1 as idx,
           org_wide, building_ids, cashbook_ids
      from tap
  )
  select jsonb_build_object(
           'permissions', coalesce((select jsonb_object_agg(q.key, true) from q), '{}'::jsonb),
           'scopeSets', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'orgWide', t.org_wide,
                      'buildingIds', to_jsonb(t.building_ids),
                      'cashbookIds', to_jsonb(t.cashbook_ids)) order by t.idx)
               from tap_so t), '[]'::jsonb),
           'scopes', coalesce((
             select jsonb_object_agg(q.key, t.idx)
               from q join tap_so t
                 on t.org_wide = q.org_wide
                and t.building_ids = q.building_ids
                and t.cashbook_ids = q.cashbook_ids), '{}'::jsonb))
    into v_ket;

  return jsonb_build_object(
    'organizationId', v_org,
    'membershipId', v_memb.id,
    'memberType', v_memb.member_type,
    'authorizationVersion', v_memb.authorization_version,
    'isPlatformAdmin', exists (select 1 from public.super_admins s where s.user_id = v_actor),
    'isOffboarded', app_private.is_actor_offboarded_v1(),
    -- Danh bạ tổ chức để frontend dựng bộ chọn khi một người thuộc nhiều tổ chức.
    'organizations', coalesce((
      select jsonb_agg(jsonb_build_object('id', o2.id, 'name', o2.name,
                                          'isDemo', coalesce(o2.is_demo, false),
                                          'memberType', m2.member_type)
                       order by coalesce(o2.is_demo, false), o2.name)
        from public.organization_memberships m2
        join public.organizations o2 on o2.id = m2.organization_id and o2.status = 'ACTIVE'
       where m2.user_id = v_actor and m2.status = 'ACTIVE'), '[]'::jsonb)
  ) || coalesce(v_ket, jsonb_build_object('permissions','{}'::jsonb,'scopeSets','[]'::jsonb,'scopes','{}'::jsonb));
end
$$;








--
-- Name: FUNCTION get_authorization_context_v1(p_organization_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_authorization_context_v1(p_organization_id uuid) IS 'Gói quyền của chính người gọi cho frontend: quyền + PHẠM VI + phiên bản phân quyền. Thay dần get_my_permissions(). Không có membership -> trả gói rỗng, không raise.';








--
-- Name: get_cashbook_access_admin_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cashbook_access_admin_v2(p_cashbook_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.accounts
  WHERE id = p_cashbook_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cashbook not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT COALESCE((SELECT z.allowed FROM app_private.authorize_tenant_action_v3(
           auth.uid(), v_org, 'cashbooks.share', NULL, p_cashbook_id) z LIMIT 1), false) THEN
    RAISE EXCEPTION 'cashbooks.share required for cashbook access administration'
      USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'cashbook_id', p_cashbook_id,
    'cashbook_name', (SELECT name FROM public.accounts WHERE id = p_cashbook_id),
    'revision', COALESCE((SELECT revision FROM app_private.cashbook_access_states
                          WHERE organization_id = v_org AND cashbook_id = p_cashbook_id), 0),
    'custodians', COALESCE((SELECT jsonb_agg(jsonb_build_object('membership_id', b.membership_id, 'user_id', m.user_id))
                            FROM public.cashbook_possession_bindings b
                            JOIN public.organization_memberships m ON m.id = b.membership_id
                            WHERE b.organization_id = v_org AND b.cashbook_id = p_cashbook_id
                              AND b.possession_kind = 'CUSTODIAN' AND b.valid_to IS NULL), '[]'::jsonb),
    'knowers', COALESCE((SELECT jsonb_agg(jsonb_build_object('membership_id', b.membership_id, 'user_id', m.user_id))
                         FROM public.cashbook_possession_bindings b
                         JOIN public.organization_memberships m ON m.id = b.membership_id
                         WHERE b.organization_id = v_org AND b.cashbook_id = p_cashbook_id
                           AND b.possession_kind = 'KNOWER' AND b.valid_to IS NULL), '[]'::jsonb),
    'eligible_memberships', COALESCE((SELECT jsonb_agg(jsonb_build_object('membership_id', m.id, 'user_id', m.user_id))
                                      FROM public.organization_memberships m
                                      WHERE m.organization_id = v_org AND m.status = 'ACTIVE'), '[]'::jsonb));
END
$$;








--
-- Name: get_change_breakdown_v2(uuid, uuid, public.invoice_status, date, date, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_change_breakdown_v2(p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid, p_status public.invoice_status DEFAULT NULL::public.invoice_status, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_billing_month text DEFAULT NULL::text, p_payment_status text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(account_id uuid, account_name text, billing_month text, building_name text, room_name text, payer_name text, voucher_date date, change_amount numeric, code text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ie.change_account_id, COALESCE(ca.name,'(chưa gán sổ thối)'),
    i.billing_month, b.name, r.name,
    COALESCE(NULLIF(ie.payer_name,''), NULLIF(ie.creator_name,''), ''),
    ie.voucher_date, ie.change_amount, ie.code
  FROM income_expenses ie
  JOIN invoices i ON i.id = ie.invoice_id
  LEFT JOIN accounts ca ON ca.id = ie.change_account_id
  LEFT JOIN buildings b ON b.id = i.building_id
  LEFT JOIN rooms r ON r.id = i.room_id
  WHERE ie.deleted_at IS NULL AND ie.type='INCOME' AND ie.change_amount > 0
    AND i.deleted_at IS NULL
    -- scope set-based (thay can_access_building(i.building_id) per-row):
    AND (
      ( (SELECT public.has_full_building_scope())
        AND NOT (i.building_id = ANY (((SELECT public.demo_building_ids()))::uuid[])) )
      OR i.building_id IN (SELECT public.accessible_building_ids())
    )
    AND (p_building_id IS NULL OR i.building_id = p_building_id)
    AND (p_building_ids IS NULL OR i.building_id = ANY(p_building_ids))
    AND (p_room_id IS NULL OR i.room_id = p_room_id)
    AND (p_status IS NULL OR i.status = p_status)
    AND (p_start_date IS NULL OR i.issue_date >= p_start_date)
    AND (p_end_date IS NULL OR i.issue_date <= p_end_date)
    AND (p_billing_month IS NULL OR i.billing_month = p_billing_month)
    AND (p_payment_status IS NULL
      OR (p_payment_status='paid' AND i.status='PAID')
      OR (p_payment_status='partial' AND i.status='PARTIAL_PAID')
      OR (p_payment_status='unpaid' AND i.status NOT IN ('PAID','PARTIAL_PAID')))
  ORDER BY ca.name, i.billing_month, b.name, r.name;
$$;








--
-- Name: get_commission_tiers_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_commission_tiers_v1(p_building_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, building_id uuid, building_name text, min_months integer, max_months integer, rate_percent numeric, effective_from text, note text, can_edit boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  RETURN QUERY
  SELECT v.id, v.building_id, b.name,
         v.min_months, v.max_months, v.rate_percent,
         to_char(v.effective_from_month,'YYYY-MM'), v.note,
         (public.is_super_admin() OR app_private.is_org_owner_v1(v.organization_id, v_actor))
    FROM app_private.commission_tier_versions v
    LEFT JOIN public.buildings b ON b.id = v.building_id
   WHERE v.status = 'PUBLISHED'
     AND (p_building_id IS NULL OR v.building_id = p_building_id OR v.building_id IS NULL)
     AND (v.building_id IS NULL
          OR public.can_access_building(v.building_id)
          OR public.ie_all_buildings_scope(v.building_id)
          OR public.is_admin() OR public.is_super_admin())
   ORDER BY b.name NULLS FIRST, v.min_months;
END;
$$;








--
-- Name: get_contract_extension_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contract_extension_count(p_contract_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  SELECT COUNT(*)
  INTO v_count
  FROM contract_extensions
  WHERE contract_id = p_contract_id
    AND status = 'COMPLETED';

  RETURN v_count;
END;
$$;








