--
-- Name: get_contract_stats(uuid[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contract_stats(p_building_ids uuid[] DEFAULT NULL::uuid[], p_today date DEFAULT NULL::date, p_in30 date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select c.status::text as status, c.end_date, c.expected_move_out_date
    from contracts c
    where c.deleted_at is null
      and (
        p_building_ids is null
        or exists (
          select 1 from rooms r
          where r.id = c.room_id
            and r.building_id = any(p_building_ids)
        )
      )
  )
  select jsonb_build_object(
    'total', count(*),
    'expiring', count(*) filter (
      where status not in ('TERMINATED','TRANSFERRED','DRAFT')
        and expected_move_out_date is null
        and end_date >= p_today
        and end_date <= p_in30
    ),
    'expired', count(*) filter (
      where status not in ('TERMINATED','TRANSFERRED','DRAFT')
        and expected_move_out_date is null
        and end_date < p_today
    ),
    'terminated', count(*) filter (where status = 'TERMINATED')
  )
  from base;
$$;








--
-- Name: get_customer_credit_balance_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_credit_balance_v1(p_contract_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_building_id uuid;
  v_authz boolean;
  v_balance numeric(15,2);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT contract_row.organization_id, room_row.building_id
    INTO v_org, v_building_id
  FROM public.contracts contract_row
  JOIN public.rooms room_row
    ON room_row.id = contract_row.room_id AND room_row.deleted_at IS NULL
  JOIN public.buildings building_row
    ON building_row.id = room_row.building_id
   AND building_row.organization_id = contract_row.organization_id
   AND building_row.deleted_at IS NULL
  JOIN public.organizations organization_row
    ON organization_row.id = contract_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Contract is outside an active organization'
      USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'excess_amounts.view', v_building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Missing permission to view customer credit'
      USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.excess_amounts excess
    WHERE excess.contract_id = p_contract_id
      AND excess.credit_lot_id IS NULL
      AND excess.amount <> 0
  ) THEN
    RAISE EXCEPTION 'Legacy customer credit requires manual reconciliation'
      USING ERRCODE = '55000';
  END IF;

  PERFORM 1
  FROM public.customer_credit_lots lot
  WHERE lot.organization_id = v_org
    AND lot.contract_id = p_contract_id
    AND lot.status = 'ACTIVE'
    AND lot.remaining_amount > 0
  ORDER BY lot.created_at, lot.id
  FOR SHARE;

  SELECT COALESCE(sum(lot.remaining_amount), 0)::numeric(15,2)
    INTO v_balance
  FROM public.customer_credit_lots lot
  WHERE lot.organization_id = v_org
    AND lot.contract_id = p_contract_id
    AND lot.status = 'ACTIVE'
    AND lot.remaining_amount > 0;

  RETURN v_balance;
END;
$$;








--
-- Name: get_customer_stats(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_stats(p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with loc_ids as (
    select distinct cc.customer_id
    from contracts c
    join rooms r on r.id = c.room_id
    join contract_customers cc on cc.contract_id = c.id
    where c.deleted_at is null
      and c.status::text = 'ACTIVE'
      and (p_room_id is null or c.room_id = p_room_id)
      and (p_building_id is null or r.building_id = p_building_id)
  ),
  base as (
    select cu.customer_type::text as customer_type, cu.is_foreign
    from customers cu
    where cu.deleted_at is null
      and (p_status is null or cu.status_v2::text = p_status)
      and (
        (p_building_id is null and p_room_id is null)
        or cu.id in (select customer_id from loc_ids)
      )
      and (
        p_search is null or btrim(p_search) = ''
        or cu.full_name ilike '%' || p_search || '%'
        or cu.phone ilike '%' || p_search || '%'
        or cu.email ilike '%' || p_search || '%'
        or cu.id_number ilike '%' || p_search || '%'
      )
  )
  select jsonb_build_object(
    'total', count(*),
    'individual', count(*) filter (where customer_type = 'INDIVIDUAL'),
    'organization', count(*) filter (where customer_type = 'ORGANIZATION'),
    'foreign', count(*) filter (where is_foreign = true)
  )
  from base;
$$;








--
-- Name: get_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_summary(p_building_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  -- Mốc thời gian theo giờ VN (khớp JS chạy trên máy user VN)
  v_vn_now        timestamp   := now() AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_month_start   timestamptz := date_trunc('month', now() AT TIME ZONE 'Asia/Ho_Chi_Minh') AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_next_month    timestamptz := (date_trunc('month', now() AT TIME ZONE 'Asia/Ho_Chi_Minh') + interval '1 month') AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_today         date;
  v_month_start_d date;
  v_in30          date;
  v_bids          uuid[];
  v_scoped        boolean;

  r_total_rooms   int := 0;
  r_occupied      int := 0;
  r_reserved      int := 0;
  r_revenue       numeric := 0;
  r_debt          numeric := 0;
  r_new_contracts int := 0;
  r_issues        int := 0;
  l_total int := 0; l_converted int := 0; l_new int := 0;
  d_total int := 0; d_moved int := 0; d_new int := 0;
  c_active int := 0; c_new int := 0; c_expiring int := 0; c_terminated int := 0;
BEGIN
  v_today         := v_vn_now::date;
  v_month_start_d := date_trunc('month', v_vn_now)::date;
  v_in30          := v_today + 30;
  v_scoped        := p_building_id IS NOT NULL;

  -- getBuildingIds(): buildingId cụ thể → [id]; không → mọi tòa visible chưa xoá
  IF v_scoped THEN
    v_bids := ARRAY[p_building_id];
  ELSE
    SELECT COALESCE(array_agg(id), '{}'::uuid[]) INTO v_bids
    FROM buildings WHERE deleted_at IS NULL;
  END IF;

  -- ===== useDashboardStats =====
  IF cardinality(v_bids) > 0 THEN
    SELECT count(*) INTO r_total_rooms
    FROM rooms WHERE building_id = ANY(v_bids) AND deleted_at IS NULL;

    SELECT count(*) INTO r_reserved
    FROM rooms WHERE building_id = ANY(v_bids) AND deleted_at IS NULL AND status = 'RESERVED';
  END IF;

  -- occupied: HĐ ACTIVE có phòng; lọc theo tòa CHỈ khi v_bids không rỗng (như cũ)
  SELECT count(*) INTO r_occupied
  FROM contracts c
  JOIN rooms r ON r.id = c.room_id
  WHERE c.status = 'ACTIVE' AND c.room_id IS NOT NULL
    AND (cardinality(v_bids) = 0 OR r.building_id = ANY(v_bids));

  -- revenue tháng: lọc tòa CHỈ khi chọn tòa cụ thể (như cũ — không chọn = mọi payment visible).
  -- QUIRK GIỮ NGUYÊN: payment_date là DATE; client cũ gửi ISO-UTC nên PostgREST
  -- cast '2026-06-30T17:00:00Z'::date = ngày CUỐI tháng trước (VN=UTC+7) →
  -- khoảng thật là [cuối-tháng-trước .. cuối-tháng-này]. Sao chép để khớp 100%;
  -- muốn sửa quirk thì đổi CẢ hai nơi sau (ngoài phạm vi refactor này).
  DECLARE
    v_pay_from date := v_month_start_d;
    v_pay_to   date := (v_month_start_d + interval '1 month - 1 day')::date;
  BEGIN
    IF v_scoped THEN
      SELECT COALESCE(sum(entry.pnl_amount), 0) INTO r_revenue
      FROM public.invoice_pnl_cash_entries entry
      WHERE entry.building_id = p_building_id
        AND entry.revenue_date >= v_pay_from
        AND entry.revenue_date <= v_pay_to;
    ELSE
      SELECT COALESCE(sum(entry.pnl_amount), 0) INTO r_revenue
      FROM public.invoice_pnl_cash_entries entry
      WHERE entry.revenue_date >= v_pay_from
        AND entry.revenue_date <= v_pay_to;
    END IF;
  END;

  -- công nợ: lọc tòa khi v_bids không rỗng (như cũ)
  SELECT COALESCE(sum(COALESCE(total_amount,0) - COALESCE(paid_amount,0)), 0) INTO r_debt
  FROM invoices
  WHERE status IN ('APPROVED','PARTIAL_PAID') AND deleted_at IS NULL
    AND (cardinality(v_bids) = 0 OR building_id = ANY(v_bids));

  -- HĐ mới trong tháng: như cũ — KHÔNG lọc deleted_at, KHÔNG lọc tòa
  SELECT count(*) INTO r_new_contracts
  FROM contracts
  WHERE created_at >= v_month_start AND created_at < v_next_month;

  -- công việc chưa xử lý: như cũ — không lọc gì thêm
  SELECT count(*) INTO r_issues
  FROM issues WHERE status NOT IN ('RESOLVED','CLOSED');

  -- ===== OperationsSummary: leads + deposits (toàn bộ visible, như useLeads/useDeposits) =====
  SELECT count(*),
         count(*) FILTER (WHERE status = 'CONVERTED'),
         count(*) FILTER (WHERE created_at >= v_month_start)
    INTO l_total, l_converted, l_new
  FROM leads;

  SELECT count(*),
         count(*) FILTER (WHERE status = 'CONVERTED'),
         count(*) FILTER (WHERE created_at >= v_month_start)
    INTO d_total, d_moved, d_new
  FROM deposits;

  -- ===== useContractDashboardCounts (deleted_at IS NULL; scope qua PHÒNG khi chọn tòa) =====
  IF v_scoped THEN
    SELECT
      count(*) FILTER (WHERE c.status = 'ACTIVE'),
      count(*) FILTER (WHERE c.start_date >= v_month_start_d),
      count(*) FILTER (WHERE c.status = 'ACTIVE' AND c.end_date >= v_today AND c.end_date <= v_in30),
      count(*) FILTER (WHERE c.status = 'TERMINATED' AND c.end_date >= v_month_start_d)
      INTO c_active, c_new, c_expiring, c_terminated
    FROM contracts c
    JOIN rooms r ON r.id = c.room_id AND r.building_id = p_building_id
    WHERE c.deleted_at IS NULL;
  ELSE
    SELECT
      count(*) FILTER (WHERE c.status = 'ACTIVE'),
      count(*) FILTER (WHERE c.start_date >= v_month_start_d),
      count(*) FILTER (WHERE c.status = 'ACTIVE' AND c.end_date >= v_today AND c.end_date <= v_in30),
      count(*) FILTER (WHERE c.status = 'TERMINATED' AND c.end_date >= v_month_start_d)
      INTO c_active, c_new, c_expiring, c_terminated
    FROM contracts c
    WHERE c.deleted_at IS NULL;
  END IF;

  RETURN jsonb_build_object(
    'total_rooms', r_total_rooms,
    'occupied_rooms', r_occupied,
    'reserved_rooms', r_reserved,
    'revenue_this_month', r_revenue,
    'total_debt', r_debt,
    'new_contracts_this_month', r_new_contracts,
    'unresolved_issues', r_issues,
    'leads_total', l_total,
    'leads_converted', l_converted,
    'leads_new_month', l_new,
    'deposits_total', d_total,
    'deposits_moved_in', d_moved,
    'deposits_new_month', d_new,
    'contracts_active', c_active,
    'contracts_new_month', c_new,
    'contracts_expiring_soon', c_expiring,
    'contracts_terminated_month', c_terminated
  );
END;
$$;








--
-- Name: get_deposit_breakdown_v2(uuid, uuid, date, date, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deposit_breakdown_v2(p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_billing_month text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(building_id uuid, building_name text, room_id uuid, room_name text, contract_id uuid, contract_number text, total_deposit numeric, deposit_paid numeric, deposit_remaining numeric, deposit_debt_mode text, voucher_id uuid, code text, voucher_date date, amount numeric, account_name text, notes text, invoice_id uuid, invoice_number text, invoice_total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ie.building_id, b.name, ie.room_id, r.name,
    ie.contract_id, c.contract_number,
    c.total_deposit, c.deposit_paid, c.deposit_remaining, c.deposit_debt_mode,
    ie.id, ie.code, ie.voucher_date,
    dep.amount,
    COALESCE(a.name,''), ie.notes,
    inv.id, inv.invoice_number, inv.total_amount
  FROM income_expenses ie
  JOIN LATERAL (
    SELECT COALESCE(SUM(it.amount), 0) AS amount
    FROM income_expense_items it
    JOIN income_expense_types t ON t.id = it.income_expense_type_id
    WHERE it.income_expense_id = ie.id AND t.is_deposit = TRUE
  ) dep ON dep.amount > 0
  LEFT JOIN buildings b ON b.id = ie.building_id
  LEFT JOIN rooms r ON r.id = ie.room_id
  LEFT JOIN contracts c ON c.id = ie.contract_id
  LEFT JOIN accounts a ON a.id = ie.account_id
  LEFT JOIN invoices inv ON inv.id = ie.invoice_id AND inv.deleted_at IS NULL
  WHERE ie.deleted_at IS NULL AND ie.type='INCOME' AND ie.approval_status='APPROVED'
    -- scope set-based (thay can_access_building(ie.building_id) per-row);
    -- đặt TRƯỚC các filter khác về mặt logic — planner sẽ lọc scope bằng
    -- InitPlan trước khi chạy LATERAL SUM cho dòng ngoài phạm vi.
    AND (
      ( (SELECT public.has_full_building_scope())
        AND NOT (ie.building_id = ANY (((SELECT public.demo_building_ids()))::uuid[])) )
      OR ie.building_id IN (SELECT public.accessible_building_ids())
    )
    AND (p_building_id IS NULL OR ie.building_id = p_building_id)
    AND (p_building_ids IS NULL OR ie.building_id = ANY(p_building_ids))
    AND (p_room_id IS NULL OR ie.room_id = p_room_id)
    AND (p_start_date IS NULL OR ie.voucher_date >= p_start_date)
    AND (p_end_date IS NULL OR ie.voucher_date <= p_end_date)
    AND (p_billing_month IS NULL OR to_char(ie.voucher_date,'YYYY-MM') = p_billing_month)
  ORDER BY b.name, r.name, ie.voucher_date;
$$;








--
-- Name: get_deposits_report_summary(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deposits_report_summary(p_status text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT d.status::text AS st, COALESCE(d.amount, 0) AS amount
    FROM public.deposits d
    LEFT JOIN public.rooms r ON r.id = d.room_id
    WHERE d.deleted_at IS NULL
      AND (p_status IS NULL OR d.status::text = p_status)
      AND (p_building_ids IS NULL OR r.building_id = ANY(p_building_ids))
  )
  SELECT jsonb_build_object(
    'total', COALESCE(SUM(amount), 0),
    'count', COALESCE(COUNT(*), 0),
    'holding_total', COALESCE(SUM(amount) FILTER (WHERE st IN ('PENDING','CONFIRMED')), 0),
    'in_invoice_total', COALESCE(SUM(amount) FILTER (WHERE st = 'CONVERTED'), 0)
  ) FROM base;
$$;








--
-- Name: get_fee_config_matrix_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_fee_config_matrix_v1(p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(building_id uuid, building_name text, fee_category text, provider_code text, account_holder text, default_amount numeric, default_account_id uuid, default_account_name text, not_applicable boolean, is_declared boolean, last_voucher_date date, voucher_count integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH kinds(k, ord) AS (
    VALUES ('tien_nha',1),('dien',2),('nuoc',3),('internet',4),('quan_ly',5),
           ('ve_sinh',6),('cong_an',7),('rac',8),('thang_may',9)
  ),
  b AS (
    SELECT bb.id, bb.name, COALESCE(bb.hidden_fixed_expenses,'{}') AS hidden
      FROM buildings bb
     WHERE bb.deleted_at IS NULL
       AND (p_building_ids IS NULL OR bb.id = ANY(p_building_ids))
       AND app_private.building_org_visible_v1(bb.id)
       AND (public.can_access_building(bb.id)
         OR public.ie_all_buildings_scope(bb.id)
         OR bb.user_id = auth.uid()
         OR public.is_admin() OR public.is_super_admin())
  ),
  -- Lần đóng gần nhất theo (toà, hạng mục): cho chủ biết ô nào đang thực sự chạy
  -- và ô nào khai rồi mà chưa bao giờ dùng.
  used AS (
    SELECT ie.building_id AS bid, k.k AS kk,
           max(ie.voucher_date) AS last_date,
           count(DISTINCT ie.id)::int AS cnt
      FROM income_expense_items it
      JOIN income_expense_types t ON t.id = it.income_expense_type_id AND t.type='expense'
      JOIN income_expenses ie ON ie.id = it.income_expense_id
                             AND ie.type='EXPENSE'
                             AND ie.approval_status='APPROVED'
                             AND ie.deleted_at IS NULL
      CROSS JOIN kinds k
     WHERE public.fee_type_matches(k.k, t.category, t.name)
     GROUP BY 1,2
  )
  SELECT b.id, b.name, k.k,
         f.provider_code, f.account_holder, f.default_amount,
         f.default_account_id, a.name,
         (k.k = ANY(b.hidden))            AS not_applicable,
         (f.building_id IS NOT NULL)      AS is_declared,
         u.last_date, COALESCE(u.cnt, 0)
    FROM b
    CROSS JOIN kinds k
    LEFT JOIN building_fee_accounts f
      ON f.building_id = b.id AND f.fee_category = k.k AND f.deleted_at IS NULL
    LEFT JOIN accounts a ON a.id = f.default_account_id AND a.deleted_at IS NULL
    LEFT JOIN used u ON u.bid = b.id AND u.kk = k.k
   ORDER BY b.name, k.ord;
$$;








--
-- Name: FUNCTION get_fee_config_matrix_v1(p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_fee_config_matrix_v1(p_building_ids uuid[]) IS 'Ma trận cấu hình phí cố định (toà × 9 hạng mục) cho trang Cài đặt. Trả CẢ ô CHƯA khai (is_declared=false) để thấy được phần còn nợ — đo 30/07/2026: org thật 53/162 ô chưa khai. not_applicable đọc từ buildings.hidden_fixed_expenses (nguồn duy nhất). Kèm last_voucher_date/voucher_count để phân biệt ô đang chạy thật với ô khai rồi chưa dùng. VOLATILE vì nhánh phân quyền có thể lấy khoá dòng.';








--
-- Name: get_finance_v2_client_flags_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_finance_v2_client_flags_v1() RETURNS TABLE(organization_id uuid, read_semantics_route text, workflow_route text, posting_route text, access_route text, accounting_standard_strict boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT m.organization_id,
         app_private.finance_v2_route_pure_v1('income_expense.read_semantics.v2', m.organization_id),
         app_private.finance_v2_route_pure_v1('income_expense.workflow.v2', m.organization_id),
         app_private.finance_v2_route_pure_v1('income_expense.posting.v2', m.organization_id),
         app_private.finance_v2_route_pure_v1('cashbook.access.v2', m.organization_id),
         app_private.ie_accounting_strict_v1(m.organization_id)
