  WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE';
$$;








--
-- Name: get_held_deposit_summary(uuid[], numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_held_deposit_summary(p_building_ids uuid[] DEFAULT NULL::uuid[], p_threshold numeric DEFAULT 10000) RETURNS TABLE(building_id uuid, building_name text, contract_count bigint, expected numeric, held numeric, shortfall_all numeric, shortfall_short numeric, full_count bigint, short_count bigint, first_invoice_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT r.building_id AS bid,
           COALESCE(c.total_deposit, 0) AS td,
           COALESCE(c.deposit_paid, 0) AS dp,
           COALESCE(c.deposit_remaining, COALESCE(c.total_deposit,0) - COALESCE(c.deposit_paid,0)) AS rem,
           c.deposit_debt_mode AS ddm
    FROM public.contracts c
    JOIN public.rooms r ON r.id = c.room_id
    WHERE c.deleted_at IS NULL AND c.status = 'ACTIVE'
      AND (p_building_ids IS NULL OR r.building_id = ANY(p_building_ids))
  ),
  tagged AS (
    SELECT *, CASE WHEN rem < p_threshold THEN 'FULL'
                   WHEN ddm = 'FIRST_INVOICE' THEN 'FIRST_INVOICE'
                   ELSE 'SHORT' END AS st
    FROM base
  )
  SELECT t.bid, b.name, COUNT(*),
         SUM(td), SUM(dp),
         SUM(GREATEST(0, rem)),
         SUM(GREATEST(0, rem)) FILTER (WHERE st = 'SHORT'),
         COUNT(*) FILTER (WHERE st = 'FULL'),
         COUNT(*) FILTER (WHERE st = 'SHORT'),
         COUNT(*) FILTER (WHERE st = 'FIRST_INVOICE')
  FROM tagged t
  JOIN public.buildings b ON b.id = t.bid
  GROUP BY t.bid, b.name
  ORDER BY b.name;
$$;








--
-- Name: get_ie_auto_approve_threshold_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ie_auto_approve_threshold_v1() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_cnt int; v_owner_org uuid;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  select count(distinct m.organization_id), min(m.organization_id::text)::uuid
    into v_cnt, v_org
    from public.organization_memberships m
   where m.user_id = v_actor and m.status = 'ACTIVE';
  if coalesce(v_cnt,0) = 0 then raise exception 'Không thuộc tổ chức nào' using errcode='42501'; end if;
  if v_cnt > 1 then
    select rb.organization_id into v_owner_org
      from public.role_bindings rb
      join public.organization_memberships m
        on m.id = rb.membership_id and m.organization_id = rb.organization_id
       and m.user_id = v_actor and m.status = 'ACTIVE'
      join public.organization_roles r
        on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
     limit 1;
    if v_owner_org is not null then v_org := v_owner_org; end if;
  end if;
  return (select c.threshold from app_private.ie_auto_approve_config c
           where c.organization_id = v_org);
end;
$$;








--
-- Name: get_income_expense_detail_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_detail_v2(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT to_jsonb(ie.*) - 'idempotency_key' - 'source_payload_hash'
         || jsonb_build_object(
              'items', COALESCE((SELECT jsonb_agg(to_jsonb(it.*))
                                 FROM public.income_expense_items it
                                 WHERE it.income_expense_id = ie.id), '[]'::jsonb))
  FROM app_private.finance_v2_visible_vouchers() ie
  WHERE ie.id = p_id;
$$;








--
-- Name: get_income_expense_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_history(p_id uuid) RETURNS TABLE(id uuid, action text, actor_id uuid, actor_name text, old_status text, new_status text, note text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
