--
-- Name: get_income_expense_layer_stats(uuid[], uuid[], uuid, text, date, date, text, uuid, numeric, numeric, text, uuid[], uuid[], text[], boolean, text[], boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_layer_stats(p_building_ids uuid[] DEFAULT NULL::uuid[], p_room_ids uuid[] DEFAULT NULL::uuid[], p_account_id uuid DEFAULT NULL::uuid, p_type text DEFAULT NULL::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_approval text DEFAULT 'ALL_ACTIVE'::text, p_creator_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT NULL::numeric, p_amount_tol numeric DEFAULT 5000, p_verified text DEFAULT NULL::text, p_item_type_ids uuid[] DEFAULT NULL::uuid[], p_voucher_ids uuid[] DEFAULT NULL::uuid[], p_sources text[] DEFAULT NULL::text[], p_source_manual boolean DEFAULT false, p_internal_sources text[] DEFAULT NULL::text[], p_kqkd_only boolean DEFAULT false, p_posting text DEFAULT NULL::text) RETURNS TABLE(cash_income numeric, cash_expense numeric, internal_count integer, internal_income numeric, internal_expense numeric, pending_count integer, pending_total numeric, pending_income numeric, pending_expense numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
WITH base AS (
  SELECT ie.type, ie.total_amount, ie.kqkd_amount, ie.approval_status,
         ie.account_id, ie.system_source,
         COALESCE(a.is_virtual, FALSE) AS acc_virtual
  FROM public.income_expenses ie
  LEFT JOIN public.accounts a ON a.id = ie.account_id
  WHERE ie.deleted_at IS NULL
    AND (p_posting IS NULL
         OR (p_posting = 'POSTED'   AND ie.posting_status = 'POSTED')
         OR (p_posting = 'REVERSED' AND ie.posting_status = 'REVERSED')
         OR (p_posting = 'UNPOSTED' AND ie.approval_status = 'APPROVED'
             AND COALESCE(ie.posting_status, 'UNPOSTED') = 'UNPOSTED'))
    AND (CASE
           WHEN p_approval IS NULL OR p_approval = 'ALL_ACTIVE'
             THEN ie.approval_status IN ('APPROVED', 'UNAPPROVED')
           ELSE ie.approval_status = p_approval
         END)
    AND (p_building_ids IS NULL OR ie.building_id = ANY (p_building_ids))
    AND (p_room_ids     IS NULL OR ie.room_id     = ANY (p_room_ids))
    AND (p_account_id   IS NULL
         OR ie.account_id = p_account_id
         OR ie.change_account_id = p_account_id)
    AND (p_type       IS NULL OR ie.type = p_type)
    AND (p_start_date IS NULL OR ie.voucher_date >= p_start_date)
    AND (p_end_date   IS NULL OR ie.voucher_date <= p_end_date)
    AND (p_creator_id IS NULL OR ie.user_id = p_creator_id)
    AND (p_amount     IS NULL
         OR ie.total_amount BETWEEN p_amount - p_amount_tol
                                AND p_amount + p_amount_tol)
    AND (p_verified IS NULL
         OR (p_verified = 'VERIFIED'   AND ie.verified_at IS NOT NULL)
         OR (p_verified = 'UNVERIFIED' AND ie.verified_at IS NULL))
    AND (p_voucher_ids IS NULL OR ie.id = ANY (p_voucher_ids))
    AND (p_item_type_ids IS NULL OR EXISTS (
           SELECT 1 FROM public.income_expense_items iti
           WHERE iti.income_expense_id = ie.id
             AND iti.income_expense_type_id = ANY (p_item_type_ids)))
    AND (NOT p_source_manual OR ie.system_source IS NULL)
    AND (p_sources IS NULL OR ie.system_source = ANY (p_sources))
    AND (NOT p_kqkd_only OR ie.kqkd_amount > 0)
),
cls AS (
  SELECT *,
    CASE
      WHEN approval_status = 'UNAPPROVED' OR account_id IS NULL THEN 'PENDING'
      WHEN acc_virtual
           OR (p_internal_sources IS NOT NULL
               AND system_source = ANY (p_internal_sources)) THEN 'INTERNAL'
      ELSE 'CASH'
    END AS layer
  FROM base
  WHERE p_kqkd_only OR approval_status <> 'CANCELLED'
)
SELECT
  COALESCE(SUM(CASE WHEN p_kqkd_only AND type = 'INCOME' THEN kqkd_amount
                    WHEN NOT p_kqkd_only AND layer = 'CASH' AND type = 'INCOME' THEN total_amount
               END), 0)::numeric AS cash_income,
  COALESCE(SUM(CASE WHEN p_kqkd_only AND type = 'EXPENSE' THEN kqkd_amount
                    WHEN NOT p_kqkd_only AND layer = 'CASH' AND type = 'EXPENSE' THEN total_amount
               END), 0)::numeric AS cash_expense,
  COALESCE(COUNT(*) FILTER (WHERE NOT p_kqkd_only AND layer = 'INTERNAL'), 0)::integer AS internal_count,
  COALESCE(SUM(total_amount) FILTER (WHERE NOT p_kqkd_only AND layer = 'INTERNAL' AND type = 'INCOME'), 0)::numeric AS internal_income,
  COALESCE(SUM(total_amount) FILTER (WHERE NOT p_kqkd_only AND layer = 'INTERNAL' AND type = 'EXPENSE'), 0)::numeric AS internal_expense,
  COALESCE(COUNT(*) FILTER (WHERE NOT p_kqkd_only AND layer = 'PENDING'), 0)::integer AS pending_count,
  COALESCE(SUM(total_amount) FILTER (WHERE NOT p_kqkd_only AND layer = 'PENDING'), 0)::numeric AS pending_total,
  COALESCE(SUM(total_amount) FILTER (WHERE NOT p_kqkd_only AND layer = 'PENDING' AND type = 'INCOME'), 0)::numeric AS pending_income,
  COALESCE(SUM(total_amount) FILTER (WHERE NOT p_kqkd_only AND layer = 'PENDING' AND type = 'EXPENSE'), 0)::numeric AS pending_expense
FROM cls;
$$;








--
-- Name: get_income_expense_stats_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_stats_v2(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT jsonb_build_object(
    'count', count(*),
    'income_total', COALESCE(sum(ie.total_amount) FILTER (WHERE ie.type = 'INCOME' AND ie.posting_status = 'POSTED'), 0),
    'expense_total', COALESCE(sum(ie.total_amount) FILTER (WHERE ie.type = 'EXPENSE' AND ie.posting_status = 'POSTED'), 0),
    'pending_count', count(*) FILTER (WHERE ie.approval_status = 'UNAPPROVED'),
    'approved_unposted_count', count(*) FILTER (WHERE ie.approval_status = 'APPROVED' AND ie.posting_status = 'UNPOSTED'),
    'posted_count', count(*) FILTER (WHERE ie.posting_status = 'POSTED')
  )
  FROM app_private.finance_v2_visible_vouchers() ie
  WHERE (p_filters->>'type' IS NULL OR ie.type = p_filters->>'type')
    AND (p_filters->>'accountId' IS NULL OR ie.account_id = (p_filters->>'accountId')::uuid)
    AND (p_filters->>'fromDate' IS NULL OR ie.voucher_date >= (p_filters->>'fromDate')::date)
    AND (p_filters->>'toDate' IS NULL OR ie.voucher_date <= (p_filters->>'toDate')::date);
$$;








--
-- Name: get_invoice_statistics_v2(uuid, uuid, public.invoice_status, date, date, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_statistics_v2(p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid, p_status public.invoice_status DEFAULT NULL::public.invoice_status, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_billing_month text DEFAULT NULL::text, p_payment_status text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_paid        DECIMAL(15, 2) := 0;
  v_total_remaining   DECIMAL(15, 2) := 0;
  v_total_amount      DECIMAL(15, 2) := 0;
  v_total_refunded    DECIMAL(15, 2) := 0;
  v_total_count       BIGINT         := 0;
  v_rent_amount       DECIMAL(15, 2) := 0;
  v_electric_amount   DECIMAL(15, 2) := 0;
  v_water_amount      DECIMAL(15, 2) := 0;
  v_pdv_amount        DECIMAL(15, 2) := 0;
  v_total_collected   DECIMAL(15, 2) := 0;
  v_payment_tm        DECIMAL(15, 2) := 0;
  v_payment_tk        DECIMAL(15, 2) := 0;
  v_payment_tt        DECIMAL(15, 2) := 0;
  v_change_amount     DECIMAL(15, 2) := 0;
  v_deposit_collected DECIMAL(15, 2) := 0;
  v_payment_ct        DECIMAL(15, 2) := 0;
  v_priv              BOOLEAN        := FALSE;  -- thấy mọi toà
  v_bids              uuid[]         := NULL;   -- tập toà được phép (khi không priv)
BEGIN
  -- Tính phạm vi toà MỘT lần (thay can_access_building per-row).
  IF public.is_super_admin() OR public.is_admin()
     OR EXISTS (
       SELECT 1 FROM public.staff_assignments sa
       WHERE sa.staff_id = auth.uid() AND sa.building_id IS NULL AND sa.area_id IS NULL
     ) THEN
    v_priv := TRUE;
  ELSE
    SELECT array_agg(DISTINCT b) INTO v_bids
    FROM (
      SELECT sa.building_id AS b
      FROM public.staff_assignments sa
      WHERE sa.staff_id = auth.uid() AND sa.building_id IS NOT NULL
      UNION
      SELECT ab.building_id
      FROM public.staff_assignments sa2
      JOIN public.area_buildings ab ON ab.area_id = sa2.area_id
      WHERE sa2.staff_id = auth.uid() AND sa2.area_id IS NOT NULL
      UNION
      SELECT pmsb.building_id
      FROM public.profit_manager_salary_buildings pmsb
      JOIN public.profit_manager_salaries pms ON pms.id = pmsb.salary_id
      JOIN public.profit_managers pm ON pm.id = pms.manager_id
      WHERE pm.auth_user_id = auth.uid() AND pm.deleted_at IS NULL
    ) q;
  END IF;

  -- [DEMO-DOCS] Đặc quyền không bao gồm tòa demo sandbox: hạ v_priv xuống
  -- danh sách "MỌI tòa TRỪ demo" (kể cả tòa đã soft-delete — giữ nguyên hành vi
  -- cũ với hoá đơn thuộc tòa đã xoá mềm) để thống kê không lẫn số liệu demo.
  IF v_priv THEN
    v_priv := FALSE;
    SELECT array_agg(id) INTO v_bids
    FROM public.buildings
    WHERE app_private.building_org_visible_v1(id);
  END IF;

  WITH filtered_invoices AS (
    SELECT i.id, i.total_amount, i.paid_amount, i.remaining_amount
    FROM public.invoices i
    WHERE i.deleted_at IS NULL
      AND (v_priv OR i.building_id = ANY(v_bids))
      AND (p_building_id   IS NULL OR i.building_id   = p_building_id)
      AND (p_building_ids  IS NULL OR i.building_id   = ANY(p_building_ids))
      AND (p_room_id       IS NULL OR i.room_id       = p_room_id)
      AND (p_status        IS NULL OR i.status        = p_status)
      -- [A1] Hoá đơn đã HUỶ không còn là công nợ: loại khỏi mọi tổng, TRỪ khi
      -- caller hỏi ĐÍCH DANH p_status=CANCELLED (view "Đã huỷ" trang hoá đơn).
      AND (p_status IS NOT DISTINCT FROM 'CANCELLED'::invoice_status
           OR i.status <> 'CANCELLED')
      AND (p_start_date    IS NULL OR i.issue_date    >= p_start_date)
      AND (p_end_date      IS NULL OR i.issue_date    <= p_end_date)
      AND (p_billing_month IS NULL OR i.billing_month = p_billing_month)
      AND (
        p_payment_status IS NULL
        OR (p_payment_status = 'paid'    AND i.status = 'PAID')
        OR (p_payment_status = 'partial' AND i.status = 'PARTIAL_PAID')
        OR (p_payment_status = 'unpaid'  AND i.status NOT IN ('PAID','PARTIAL_PAID'))
      )
  )
  SELECT
    COALESCE(SUM(total_amount), 0),
    COALESCE(SUM(paid_amount), 0),
    COALESCE(SUM(GREATEST(remaining_amount, 0)), 0),
    COALESCE(SUM(GREATEST(-remaining_amount, 0)), 0),
    COUNT(*)
  INTO v_total_amount, v_total_paid, v_total_remaining, v_total_refunded, v_total_count
  FROM filtered_invoices;

  SELECT
    COALESCE(SUM(CASE WHEN ii.type = 'RENT' THEN ii.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE
      WHEN ii.type NOT IN ('RENT','DISCOUNT')
        AND LOWER(COALESCE(ii.description, '')) LIKE '%điện%'
      THEN ii.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE
      WHEN ii.type NOT IN ('RENT','DISCOUNT')
        AND LOWER(COALESCE(ii.description, '')) LIKE '%nước%'
      THEN ii.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE
      WHEN ii.type NOT IN ('RENT','DISCOUNT')
        AND LOWER(COALESCE(ii.description, '')) NOT LIKE '%điện%'
        AND LOWER(COALESCE(ii.description, '')) NOT LIKE '%nước%'
      THEN ii.amount ELSE 0 END), 0)
  INTO v_rent_amount, v_electric_amount, v_water_amount, v_pdv_amount
  FROM public.invoices i
  JOIN public.invoice_items ii ON ii.invoice_id = i.id
  WHERE i.deleted_at IS NULL
    AND (v_priv OR i.building_id = ANY(v_bids))
    AND (p_building_id   IS NULL OR i.building_id   = p_building_id)
    AND (p_building_ids  IS NULL OR i.building_id   = ANY(p_building_ids))
    AND (p_room_id       IS NULL OR i.room_id       = p_room_id)
    AND (p_status        IS NULL OR i.status        = p_status)
    -- [A1] Hoá đơn đã HUỶ không còn là công nợ: loại khỏi mọi tổng, TRỪ khi
    -- caller hỏi ĐÍCH DANH p_status=CANCELLED (view "Đã huỷ" trang hoá đơn).
    AND (p_status IS NOT DISTINCT FROM 'CANCELLED'::invoice_status
         OR i.status <> 'CANCELLED')
    AND (p_start_date    IS NULL OR i.issue_date    >= p_start_date)
    AND (p_end_date      IS NULL OR i.issue_date    <= p_end_date)
    AND (p_billing_month IS NULL OR i.billing_month = p_billing_month)
    AND (
      p_payment_status IS NULL
      OR (p_payment_status = 'paid'    AND i.status = 'PAID')
      OR (p_payment_status = 'partial' AND i.status = 'PARTIAL_PAID')
      OR (p_payment_status = 'unpaid'  AND i.status NOT IN ('PAID','PARTIAL_PAID'))
    );

  SELECT
    COALESCE(SUM(p.collected_amount), 0),
    COALESCE(SUM(CASE WHEN p.payment_method = 'TM' THEN p.collected_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN p.payment_method = 'TK' THEN p.collected_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN p.payment_method = 'TT' THEN p.collected_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN p.payment_method = 'CT' THEN p.collected_amount ELSE 0 END), 0)
  INTO v_total_collected, v_payment_tm, v_payment_tk, v_payment_tt, v_payment_ct
  FROM public.active_payment_receipts p
  JOIN public.invoices i ON i.id = p.invoice_id
  WHERE i.deleted_at IS NULL
    AND (v_priv OR i.building_id = ANY(v_bids))
    AND (p_building_id   IS NULL OR i.building_id   = p_building_id)
    AND (p_building_ids  IS NULL OR i.building_id   = ANY(p_building_ids))
    AND (p_room_id       IS NULL OR i.room_id       = p_room_id)
    AND (p_status        IS NULL OR i.status        = p_status)
    -- [A1] Hoá đơn đã HUỶ không còn là công nợ: loại khỏi mọi tổng, TRỪ khi
    -- caller hỏi ĐÍCH DANH p_status=CANCELLED (view "Đã huỷ" trang hoá đơn).
    AND (p_status IS NOT DISTINCT FROM 'CANCELLED'::invoice_status
         OR i.status <> 'CANCELLED')
    AND (p_start_date    IS NULL OR i.issue_date    >= p_start_date)
    AND (p_end_date      IS NULL OR i.issue_date    <= p_end_date)
    AND (p_billing_month IS NULL OR i.billing_month = p_billing_month)
    AND (
      p_payment_status IS NULL
      OR (p_payment_status = 'paid'    AND i.status = 'PAID')
      OR (p_payment_status = 'partial' AND i.status = 'PARTIAL_PAID')
      OR (p_payment_status = 'unpaid'  AND i.status NOT IN ('PAID','PARTIAL_PAID'))
    );

  SELECT COALESCE(SUM(ie.change_amount), 0)
  INTO v_change_amount
  FROM public.income_expenses ie
  JOIN public.invoices i ON i.id = ie.invoice_id
  WHERE ie.deleted_at IS NULL
    AND ie.type = 'INCOME'
    AND (
      ie.payment_collection_id IS NULL
      OR EXISTS (
        SELECT 1 FROM public.invoice_payment_collections active_collection
        WHERE active_collection.id = ie.payment_collection_id
          AND active_collection.status = 'ACTIVE'
      )
    )
    AND (
      ie.payment_id IS NULL
      OR EXISTS (
        SELECT 1 FROM public.active_payments active_payment
        WHERE active_payment.id = ie.payment_id
      )
    )
    AND ie.change_amount > 0
    AND i.deleted_at IS NULL
    AND (v_priv OR i.building_id = ANY(v_bids))
    AND (p_building_id   IS NULL OR i.building_id   = p_building_id)
    AND (p_building_ids  IS NULL OR i.building_id   = ANY(p_building_ids))
    AND (p_room_id       IS NULL OR i.room_id       = p_room_id)
    AND (p_status        IS NULL OR i.status        = p_status)
    -- [A1] Hoá đơn đã HUỶ không còn là công nợ: loại khỏi mọi tổng, TRỪ khi
    -- caller hỏi ĐÍCH DANH p_status=CANCELLED (view "Đã huỷ" trang hoá đơn).
    AND (p_status IS NOT DISTINCT FROM 'CANCELLED'::invoice_status
         OR i.status <> 'CANCELLED')
    AND (p_start_date    IS NULL OR i.issue_date    >= p_start_date)
    AND (p_end_date      IS NULL OR i.issue_date    <= p_end_date)
    AND (p_billing_month IS NULL OR i.billing_month = p_billing_month)
    AND (
      p_payment_status IS NULL
      OR (p_payment_status = 'paid'    AND i.status = 'PAID')
      OR (p_payment_status = 'partial' AND i.status = 'PARTIAL_PAID')
      OR (p_payment_status = 'unpaid'  AND i.status NOT IN ('PAID','PARTIAL_PAID'))
    );

  -- Cọc đã thu — Σ ITEM cọc (phiếu trộn chỉ tính phần cọc, không lôi cả total).
  SELECT COALESCE(SUM(it.amount), 0)
  INTO v_deposit_collected
  FROM public.income_expenses ie
  JOIN public.income_expense_items it ON it.income_expense_id = ie.id
  JOIN public.income_expense_types t  ON t.id = it.income_expense_type_id AND t.is_deposit = TRUE
  WHERE ie.deleted_at IS NULL
    AND ie.type = 'INCOME'
    AND (
      ie.payment_collection_id IS NULL
      OR EXISTS (
        SELECT 1 FROM public.invoice_payment_collections active_collection
        WHERE active_collection.id = ie.payment_collection_id
          AND active_collection.status = 'ACTIVE'
      )
    )
    AND (
      ie.payment_id IS NULL
      OR EXISTS (
        SELECT 1 FROM public.active_payments active_payment
        WHERE active_payment.id = ie.payment_id
      )
    )
    AND ie.approval_status = 'APPROVED'
    AND (v_priv OR ie.building_id = ANY(v_bids))
    AND (p_building_id   IS NULL OR ie.building_id   = p_building_id)
    AND (p_building_ids  IS NULL OR ie.building_id   = ANY(p_building_ids))
    AND (p_room_id       IS NULL OR ie.room_id       = p_room_id)
    AND (p_start_date    IS NULL OR ie.voucher_date  >= p_start_date)
    AND (p_end_date      IS NULL OR ie.voucher_date  <= p_end_date)
    AND (p_billing_month IS NULL OR to_char(ie.voucher_date, 'YYYY-MM') = p_billing_month);

  RETURN json_build_object(
    'total_amount',       v_total_amount,
    'total_paid',         v_total_paid,
    'total_remaining',    v_total_remaining,
    'total_refunded',     v_total_refunded,
    'total_count',        v_total_count,
    'rent_amount',        v_rent_amount,
    'electric_amount',    v_electric_amount,
    'water_amount',       v_water_amount,
    'pdv_amount',         v_pdv_amount,
    'total_collected',    v_total_collected,
    'payment_tm',         v_payment_tm,
    'payment_tk',         v_payment_tk,
    'payment_tt',         v_payment_tt,
    'payment_ct',         v_payment_ct,
    'change_amount',      v_change_amount,
    'deposit_collected',  v_deposit_collected
  );
END;
$$;








--
-- Name: get_member_authorization_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_member_authorization_v1(p_membership uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
  v_m   public.organization_memberships%rowtype;
  v_out jsonb;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền xem phân quyền thành viên.' using errcode = '42501';
  end if;
  select * into v_m from public.organization_memberships
   where id = p_membership and organization_id = v_org;
  if not found then
    raise exception 'Không tìm thấy thành viên này trong tổ chức của bạn.' using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'membershipId', v_m.id,
    'userId',       v_m.user_id,
    'email',        coalesce(p.email, u.email),
    'fullName',     p.full_name,
    'memberType',   v_m.member_type,
    'status',       v_m.status,
    'version',      v_m.version,
    'isSelf',       (v_m.user_id = (select auth.uid())),
    'roleBindings', coalesce((
      select jsonb_agg(jsonb_build_object(
               'bindingId', rb.id,
               'roleId',    rb.role_id,
               'roleName',  orl.name,
               'scopeIds',  coalesce((select jsonb_agg(rbs.scope_id)
                                        from public.role_binding_scopes rbs
                                       where rbs.role_binding_id = rb.id), '[]'::jsonb))
             order by orl.name)
        from public.role_bindings rb
        join public.organization_roles orl on orl.id = rb.role_id
       where rb.membership_id = v_m.id and rb.valid_to is null), '[]'::jsonb),
    'overrides', coalesce((
      select jsonb_agg(jsonb_build_object(
               'overrideId',    o.id,
               'permissionKey', o.permission_key,
               'effect',        o.effect,
               'scopeMode',     o.scope_mode,
               'reason',        o.reason,
               'expiresAt',     o.expires_at,
               'createdAt',     o.created_at,
               'scopeIds', coalesce((select jsonb_agg(mos.scope_id)
                                       from public.member_override_scopes mos
                                      where mos.override_id = o.id), '[]'::jsonb))
             order by o.permission_key)
        from public.member_permission_overrides o
       where o.membership_id = v_m.id and o.revoked_at is null
         and (o.expires_at is null or o.expires_at > now())), '[]'::jsonb),
    'cashbooksHeld', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cashbookId', cp.cashbook_id, 'name', cb.name, 'kind', cp.possession_kind))
        from public.cashbook_possession_bindings cp
        left join public.accounts cb on cb.id = cp.cashbook_id
       where cp.membership_id = v_m.id and cp.valid_from <= now()
         and (cp.valid_to is null or cp.valid_to > now())), '[]'::jsonb),
    -- Tab "Quyền hiệu lực": danh sách khoá thực sự dùng được, ở BẤT KỲ phạm vi.
    'effectiveKeys', to_jsonb(app_private.allowed_keys_for_membership_v3(v_m.id))
  ) into v_out
  from (select 1) z
  left join public.profiles p on p.id = v_m.user_id
  left join auth.users u      on u.id = v_m.user_id;

  return v_out;
end
$$;








--
-- Name: get_meter_reading_stats(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_meter_reading_stats(p_building_id uuid DEFAULT NULL::uuid, p_month text DEFAULT NULL::text) RETURNS TABLE(total_readings bigint, unapproved_count bigint, approved_count bigint, electricity_consumption numeric, water_consumption numeric, gas_consumption numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT AS total_readings,
    COUNT(*) FILTER (WHERE mr.status = 'UNAPPROVED')::BIGINT AS unapproved_count,
    COUNT(*) FILTER (WHERE mr.status = 'APPROVED')::BIGINT AS approved_count,
    COALESCE(SUM(mr.consumption) FILTER (WHERE mr.meter_type = 'ELECTRICITY'), 0)::DECIMAL AS electricity_consumption,
    COALESCE(SUM(mr.consumption) FILTER (WHERE mr.meter_type = 'WATER'), 0)::DECIMAL AS water_consumption,
    COALESCE(SUM(mr.consumption) FILTER (WHERE mr.meter_type = 'GAS'), 0)::DECIMAL AS gas_consumption
  FROM meter_readings mr
  WHERE mr.user_id = auth.uid()
    AND mr.deleted_at IS NULL
    AND (p_building_id IS NULL OR mr.building_id = p_building_id)
    AND (p_month IS NULL OR mr.settlement_month = p_month);
END;
$$;








--
-- Name: get_meters_without_readings(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_meters_without_readings(p_user_id uuid, p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid, p_meter_type text DEFAULT NULL::text, p_month text DEFAULT NULL::text) RETURNS TABLE(meter_id uuid, meter_code text, meter_name text, room_name text, meter_type_value text, last_reading numeric, last_reading_date date)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id AS meter_id,
    m.code AS meter_code,
    m.name AS meter_name,
    r.name AS room_name,
    m.meter_type::TEXT AS meter_type_value,
    -- last_reading: most recent current_reading, or initial_reading
    COALESCE(
      (SELECT mr.current_reading
       FROM meter_readings mr
       WHERE mr.meter_id = m.id AND mr.deleted_at IS NULL
       ORDER BY mr.reading_date DESC, mr.created_at DESC
       LIMIT 1),
      m.initial_reading
    ) AS last_reading,
    -- last_reading_date: date of most recent reading
    (SELECT mr.reading_date
     FROM meter_readings mr
     WHERE mr.meter_id = m.id AND mr.deleted_at IS NULL
     ORDER BY mr.reading_date DESC, mr.created_at DESC
     LIMIT 1) AS last_reading_date
  FROM meters m
  LEFT JOIN rooms r ON r.id = m.room_id
  WHERE m.user_id = p_user_id
    AND m.deleted_at IS NULL
    AND m.status = 'ACTIVE'
    AND (p_building_id IS NULL OR m.building_id = p_building_id)
    AND (p_room_id IS NULL OR m.room_id = p_room_id)
    AND (p_meter_type IS NULL OR m.meter_type = p_meter_type::meter_type)
    AND (p_month IS NULL OR NOT EXISTS (
      SELECT 1
      FROM meter_readings mr
      WHERE mr.meter_id = m.id
        AND mr.settlement_month = p_month
        AND mr.deleted_at IS NULL
    ))
  ORDER BY r.name, m.meter_type;
END;
$$;








--
-- Name: get_meters_without_readings_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_meters_without_readings_v2(p_building_id uuid DEFAULT NULL::uuid, p_room_id uuid DEFAULT NULL::uuid, p_meter_type text DEFAULT NULL::text, p_month text DEFAULT NULL::text) RETURNS TABLE(meter_id uuid, code text, name text, room_name text, meter_type text, last_reading numeric, last_reading_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  -- Single-org: caller có quyền access building → lấy owner của building đó qua FK
  -- Cách simple nhất: delegate v1 với p_user_id của 1 owner mà caller thấy được
  IF p_building_id IS NOT NULL THEN
    IF NOT public.can_access_building(p_building_id) THEN
      RAISE EXCEPTION 'Access denied for building %', p_building_id;
    END IF;
    SELECT user_id INTO v_owner FROM buildings WHERE id = p_building_id;
  ELSE
    -- Pick first owner visible to caller
    IF public.is_super_admin() THEN
      SELECT user_id INTO v_owner FROM buildings WHERE deleted_at IS NULL LIMIT 1;
    ELSE
      SELECT DISTINCT sa.user_id INTO v_owner FROM staff_assignments sa
       WHERE sa.staff_id = auth.uid() LIMIT 1;
    END IF;
  END IF;

  IF v_owner IS NULL THEN RETURN; END IF;

  RETURN QUERY SELECT * FROM public.get_meters_without_readings(v_owner, p_building_id, p_room_id, p_meter_type, p_month);
END;
$$;








--
-- Name: FUNCTION get_meters_without_readings_v2(p_building_id uuid, p_room_id uuid, p_meter_type text, p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_meters_without_readings_v2(p_building_id uuid, p_room_id uuid, p_meter_type text, p_month text) IS 'RBAC wrapper: kiểm tra can_access_building, lookup owner và delegate v1.';








--
-- Name: get_my_assignments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_assignments() RETURNS TABLE(user_id uuid, building_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Row toà lẻ + row full-scope thật (building_id NULL, area_id NULL)
  SELECT sa.user_id, sa.building_id
  FROM public.staff_assignments sa
  WHERE sa.staff_id = auth.uid()
    AND sa.area_id IS NULL
  UNION
  -- Row nhóm: bung LIVE thành các building_id thuộc khu
  SELECT sa.user_id, ab.building_id
  FROM public.staff_assignments sa
  JOIN public.area_buildings ab ON ab.area_id = sa.area_id
  WHERE sa.staff_id = auth.uid()
    AND sa.area_id IS NOT NULL;
$$;








--
-- Name: get_my_available_rooms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_available_rooms() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_owner   uuid;
  v_soon    int;
  v_hotline uuid;
  v_result  jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT sa.user_id INTO v_owner
  FROM public.staff_assignments sa
  WHERE sa.staff_id = v_caller AND sa.user_id <> v_caller
  LIMIT 1;
  IF v_owner IS NULL THEN
    v_owner := v_caller;
  END IF;

  SELECT soon_days, hotline_id INTO v_soon, v_hotline
  FROM public.public_room_settings
  WHERE owner_id = v_owner;
  IF v_soon IS NULL THEN v_soon := 30; END IF;

  WITH rms AS (
    SELECT
      rm.id,
      rm.building_id,
      rm.floor,
      rm.name,
      rm.code,
      rm.area,
      rm.rent_price,
      rm.deposit_amount,
      rm.max_occupants,
      COALESCE(rm.amenities, '[]'::jsonb) AS amenities,
      COALESCE(rm.images,    '[]'::jsonb) AS images,
      rm.description,
      rm.sale_note,
      rm.sale_bonus_note,
      rm.room_type,
      -- Phòng khách nhờ sale (overlay). Khi contact_manager → che SĐT/tên khách.
      CASE WHEN pl.contact_manager THEN NULL ELSE pl.contact_name  END AS pass_contact_name,
      CASE WHEN pl.contact_manager THEN NULL ELSE pl.contact_phone END AS pass_contact_phone,
      pl.sale_policy   AS pass_sale_policy,
      pl.pass_price    AS pass_price,
      pl.avail_date    AS pass_avail_date,
      COALESCE(pl.contact_manager, false) AS pass_contact_manager,
      CASE
        WHEN pl.id IS NOT NULL THEN 'pass'
        -- Đã có cọc giữ chỗ chưa gắn HĐ → phòng bị KHOÁ (xem RPC public ở trên).
        WHEN public.room_has_holding_deposit(rm.id) THEN 'rented'
        WHEN EXISTS (
          SELECT 1 FROM public.contracts c
          WHERE c.room_id = rm.id
            AND c.deleted_at IS NULL
            AND c.status IN ('ACTIVE','EXTENDED')
            AND (
              (c.expected_move_out_date IS NOT NULL
                AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon)
              OR COALESCE(c.actual_end_date, c.end_date)
                   BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
            )
        ) THEN 'soon'
        WHEN EXISTS (
          SELECT 1 FROM public.contracts c
          WHERE c.room_id = rm.id
            AND c.deleted_at IS NULL
            AND c.status IN ('ACTIVE','EXTENDED')
        ) THEN 'rented'
        WHEN rm.status = 'AVAILABLE' THEN 'free'
        ELSE 'rented'
      END AS status_public,
      (
        SELECT MIN(
          CASE
            WHEN c.expected_move_out_date IS NOT NULL
              AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
              THEN c.expected_move_out_date
            ELSE COALESCE(c.actual_end_date, c.end_date)
          END
        )
        FROM public.contracts c
        WHERE c.room_id = rm.id
          AND c.deleted_at IS NULL
          AND c.status IN ('ACTIVE','EXTENDED')
          AND (
            (c.expected_move_out_date IS NOT NULL
              AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon)
            OR COALESCE(c.actual_end_date, c.end_date)
                 BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
          )
      ) AS avail_date
    FROM public.rooms rm
    JOIN public.buildings b ON b.id = rm.building_id
    LEFT JOIN public.room_pass_listings pl
      ON pl.room_id = rm.id AND pl.user_id = v_owner AND pl.active = true
    WHERE b.user_id = v_owner
      AND b.is_virtual = false
      AND b.deleted_at IS NULL
      AND rm.deleted_at IS NULL
  ),
  bld_ids AS (
    SELECT DISTINCT building_id FROM rms WHERE status_public IN ('free','soon','pass')
  ),
  rooms_j AS (
    SELECT jsonb_agg(to_jsonb(rms) ORDER BY rms.floor DESC, rms.name) AS j
    FROM rms
    WHERE rms.building_id IN (SELECT building_id FROM bld_ids)
  ),
  blds_j AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id',           b.id,
      'name',         b.name,
      'code',         b.code,
      'area_ids',     COALESCE((
                        SELECT jsonb_agg(ab.area_id)
                        FROM public.area_buildings ab
                        JOIN public.areas a ON a.id = ab.area_id
                        WHERE ab.building_id = b.id AND a.deleted_at IS NULL
                      ), '[]'::jsonb),
      'district',     b.district,
      'ward',         b.ward,
      'address',      CASE
                        WHEN b.street_address IS NOT NULL AND b.street_address LIKE '%,%'
                          THEN b.street_address
                        ELSE concat_ws(', ',
                               NULLIF(b.street_address, ''),
                               NULLIF(b.ward, ''),
                               NULLIF(b.district, ''),
                               NULLIF(b.province, ''))
                      END,
      'total_floors', b.total_floors,
      'floor_layouts', b.floor_layouts,
      'images',        COALESCE(b.images, '[]'::jsonb),
      'public_contact_name',  b.public_contact_name,
      'public_contact_phone', b.public_contact_phone,
      'public_map_url',       b.public_map_url,
      'public_lift_type',     b.public_lift_type,
      'elec_rate', (
        SELECT COALESCE(bs.unit_price_override, s.unit_price)
        FROM public.building_services bs
        JOIN public.services s ON s.id = bs.service_id
        WHERE bs.building_id = b.id
          AND bs.is_active = true
          AND s.deleted_at IS NULL
          AND s.unit ILIKE 'kwh'
        ORDER BY (s.type = 'FIXED') DESC, s.unit_price
        LIMIT 1
      )
    ) ORDER BY b.name) AS j
    FROM public.buildings b
    WHERE b.id IN (SELECT building_id FROM bld_ids)
  ),
  areas_j AS (
    SELECT jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name) ORDER BY a.name) AS j
    FROM public.areas a
    WHERE a.user_id = v_owner AND a.deleted_at IS NULL
  ),
  contact_j AS (
    SELECT jsonb_build_object('name', h.name, 'phone', h.phone_number) AS j
    FROM public.hotlines h
    WHERE h.user_id = v_owner
      AND COALESCE(h.is_active, true) = true
      AND (v_hotline IS NULL OR h.id = v_hotline)
    ORDER BY (h.id = v_hotline) DESC NULLS LAST, h.created_at
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'areas',     COALESCE((SELECT j FROM areas_j), '[]'::jsonb),
    'buildings', COALESCE((SELECT j FROM blds_j), '[]'::jsonb),
    'rooms',     COALESCE((SELECT j FROM rooms_j), '[]'::jsonb),
    'contact',   (SELECT j FROM contact_j)
  ) INTO v_result;

  RETURN v_result;
END;
$$;








