--
-- Name: get_my_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_context() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller          UUID := auth.uid();
  v_is_super        BOOLEAN := FALSE;
  v_owner           UUID;
  v_username        TEXT;
  v_default_area_id UUID;
BEGIN
  IF v_caller IS NULL THEN
    RETURN json_build_object(
      'is_super', false, 'is_staff', false,
      'owner_id', NULL, 'default_area_id', NULL
    );
  END IF;

  SELECT EXISTS (SELECT 1 FROM super_admins WHERE user_id = v_caller)
    INTO v_is_super;

  IF v_is_super THEN
    RETURN json_build_object(
      'is_super', true, 'is_staff', false,
      'owner_id', v_caller, 'default_area_id', NULL
    );
  END IF;

  SELECT sa.user_id INTO v_owner
  FROM staff_assignments sa
  WHERE sa.staff_id = v_caller AND sa.user_id <> v_caller
  LIMIT 1;

  IF v_owner IS NOT NULL THEN
    -- Lấy username của staff từ auth.users (raw_user_meta_data.username
    -- hoặc phần local của email).
    SELECT COALESCE(
      LOWER(NULLIF(raw_user_meta_data ->> 'username', '')),
      LOWER(SPLIT_PART(email, '@', 1))
    )
    INTO v_username
    FROM auth.users
    WHERE id = v_caller;

    IF v_username IS NOT NULL AND length(v_username) > 0 THEN
      SELECT a.id INTO v_default_area_id
      FROM areas a
      WHERE a.user_id = v_owner
        AND a.deleted_at IS NULL
        AND LOWER(a.name) = v_username
      LIMIT 1;
    END IF;

    RETURN json_build_object(
      'is_super', false, 'is_staff', true,
      'owner_id', v_owner, 'default_area_id', v_default_area_id
    );
  END IF;

  RETURN json_build_object(
    'is_super', false, 'is_staff', false,
    'owner_id', v_caller, 'default_area_id', NULL
  );
END;
$$;








--
-- Name: FUNCTION get_my_context(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_context() IS 'Phân loại caller hiện tại: is_super / is_staff / owner_id. SECURITY DEFINER để bypass RLS của staff_assignments.';








--
-- Name: get_my_day_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_day_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_today DATE := public.vn_local_date(now());
  v_month DATE := date_trunc('month', v_today)::date;
  v_cfg JSONB := public.get_salary_v5_config();
  v_sad public.salary_attendance_day;
  v_streak JSONB;
  v_n INT; v_rate NUMERIC; v_ticked INT;
  v_pending JSONB;
  v_quota INT; v_used INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập'; END IF;

  SELECT * INTO v_sad FROM public.salary_attendance_day WHERE user_id = v_uid AND work_date = v_today;
  v_streak := public.v5_recompute_streak(v_uid, v_month); -- lazy-touch: luôn tươi khi mở màn

  v_n := public.v5_n_chuan(v_month, v_uid);
  v_rate := CASE WHEN v_n > 0 THEN (v_cfg->'attendance_v5'->>'budget')::numeric / v_n ELSE 0 END;
  SELECT COUNT(*) INTO v_ticked FROM public.salary_attendance_day
  WHERE user_id = v_uid AND status = 'ticked' AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;

  -- các toà đang nợ check-sau-thu-tiền hôm nay
  SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object('building_id', e->>'building_id',
           'building_name', (SELECT name FROM public.buildings b WHERE b.id = (e->>'building_id')::uuid))), '[]'::jsonb)
    INTO v_pending
  FROM public.salary_attendance_day sad, jsonb_array_elements(sad.evidence) e
  WHERE sad.user_id = v_uid AND sad.work_date = v_today AND sad.status = 'pending_check'
    AND e->>'kind' = 'pending_check';

  v_quota := COALESCE((v_cfg->'attendance_v5'->>'paid_leave_days_per_month')::int, 1);
  SELECT COUNT(*) INTO v_used FROM public.salary_attendance_day
  WHERE user_id = v_uid AND status IN ('leave_approved','pending_leave')
    AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;

  RETURN jsonb_build_object(
    'today', jsonb_build_object('date', v_today, 'status', COALESCE(v_sad.status, 'pending'),
                                'tick_source', v_sad.tick_source),
    'attend', jsonb_build_object('n_chuan', v_n, 'day_rate', ROUND(v_rate),
                                 'ticked_days', v_ticked,
                                 'tam_tinh', ROUND(v_rate * LEAST(v_ticked, v_n)),
                                 'budget', (v_cfg->'attendance_v5'->>'budget')::numeric),
    'streak', v_streak,
    'pending_checks', v_pending,
    'leave', jsonb_build_object('quota', v_quota, 'used', v_used, 'left', GREATEST(v_quota - v_used, 0)),
    'stage', v_cfg->'system_v5'->>'stage',
    'as_of', now()
  );
END; $$;








--
-- Name: get_my_notification_preferences_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_notification_preferences_v1(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_uid uuid;
begin
  v_uid := (select auth.uid());
  if v_uid is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  perform app_private.assert_notification_membership_v1(p_organization_id);

  return jsonb_build_object(
    'organization_id', p_organization_id,
    'user_id',         v_uid,
    'preferences',     app_private.notification_prefs_read_v1(v_uid, p_organization_id));
end
$$;








