--
-- Name: get_my_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_permissions() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_keys  text[];
  v_out   jsonb;
begin
  if v_actor is null then
    return '{}'::jsonb;                       -- fail closed
  end if;

  -- Quản trị nền tảng: giữ sentinel vì giao diện hiện dựa vào nó.
  if exists (select 1 from public.super_admins s where s.user_id = v_actor) then
    return '{"__superadmin": true}'::jsonb;
  end if;

  v_keys := app_private.all_allowed_keys_v3();
  if coalesce(array_length(v_keys, 1), 0) = 0 then
    return '{}'::jsonb;                       -- không thành viên / bị thu hồi
  end if;

  select coalesce(jsonb_object_agg(g.resource, g.actions), '{}'::jsonb)
    into v_out
    from (
      select pd.resource, jsonb_object_agg(pd.action, true) as actions
        from public.permission_definitions pd
       where pd.key = any (v_keys)
       group by pd.resource
    ) g;

  return coalesce(v_out, '{}'::jsonb);
end
$$;








--
-- Name: FUNCTION get_my_permissions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_permissions() IS 'Trả permissions JSONB của caller hiện tại. Ưu tiên staff_assignments.permissions (override per-staff), fallback roles.permissions. Super_admin và owner thật trả sentinel {__superadmin:true}.';








--
-- Name: get_my_share_buildings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_share_buildings() RETURNS TABLE(id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT b.id, b.name
  FROM public.buildings b
  WHERE b.deleted_at IS NULL
    AND (
      EXISTS (
        SELECT 1 FROM public.building_shareholders bs
        JOIN public.shareholders s ON s.id = bs.shareholder_id
        WHERE s.auth_user_id = auth.uid() AND s.deleted_at IS NULL
          AND bs.building_id = b.id
      )
      OR EXISTS (
        SELECT 1 FROM public.profit_manager_salary_buildings pmsb
        JOIN public.profit_manager_salaries pms ON pms.id = pmsb.salary_id
        JOIN public.profit_managers pm ON pm.id = pms.manager_id
        WHERE pm.auth_user_id = auth.uid() AND pm.deleted_at IS NULL
          AND pmsb.building_id = b.id
      )
    );
$$;








--
-- Name: get_notification_org_config_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_org_config_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_org uuid;
  v_row app_private.notification_org_config%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;

  v_org := app_private.current_admin_org_v1();
  if v_org is null then
    -- current_admin_org_v1() trả NULL khi không có users.view và không phải super admin.
    raise exception 'Không xác định được tổ chức quản trị. current_admin_org_v1() cần quyền users.view '
      '(hoặc super admin) — settings.view một mình là chưa đủ.' using errcode = '42501';
  end if;
  perform app_private.require_perm_v1(v_org, 'settings.view', 'xem cấu hình thông báo của tổ chức');

  select * into v_row
    from app_private.notification_org_config
   where organization_id = v_org;

  if not found then
    return jsonb_build_object(
      'organization_id', v_org,
      'configured',      false,
      'events',          app_private.notification_events_normalize_v1(null),
      'quiet_start',     21,
      'quiet_end',       7,
      'quiet_timezone',  'Asia/Ho_Chi_Minh',
      'updated_by',      null,
      'updated_at',      null);
  end if;

  return jsonb_build_object(
    'organization_id', v_row.organization_id,
    'configured',      true,
    'events',          app_private.notification_events_normalize_v1(v_row.events),
    'quiet_start',     v_row.quiet_start,
    'quiet_end',       v_row.quiet_end,
    'quiet_timezone',  'Asia/Ho_Chi_Minh',
    'updated_by',      v_row.updated_by,
    'updated_at',      v_row.updated_at);
end
$$;








--
-- Name: FUNCTION get_notification_org_config_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_notification_org_config_v1() IS 'Đọc khoá mở thông báo của tổ chức quản trị hiện tại. Cổng: settings.view qua require_perm_v1. quiet_start/quiet_end là GIỜ VN (Asia/Ho_Chi_Minh).';








--
-- Name: get_or_create_deposit_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_deposit_account() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc uuid;
BEGIN
  -- 1. Sổ "%Thu" mặc định của chính người gọi.
  SELECT id INTO v_acc FROM accounts
  WHERE user_id = auth.uid() AND deleted_at IS NULL AND NOT is_virtual
    AND name ILIKE '%thu' AND is_default
  ORDER BY created_at LIMIT 1;
  IF v_acc IS NOT NULL THEN RETURN v_acc; END IF;

  -- 2. Sổ "%Thu" bất kỳ của người gọi.
  SELECT id INTO v_acc FROM accounts
  WHERE user_id = auth.uid() AND deleted_at IS NULL AND NOT is_virtual
    AND name ILIKE '%thu'
  ORDER BY created_at LIMIT 1;
  IF v_acc IS NOT NULL THEN RETURN v_acc; END IF;

  -- 3. Sổ mặc định bất kỳ của người gọi.
  SELECT id INTO v_acc FROM accounts
  WHERE user_id = auth.uid() AND deleted_at IS NULL AND NOT is_virtual
    AND is_default
  ORDER BY created_at LIMIT 1;
  IF v_acc IS NOT NULL THEN RETURN v_acc; END IF;

  -- 4. Sổ thật đầu tiên của người gọi.
  SELECT id INTO v_acc FROM accounts
  WHERE user_id = auth.uid() AND deleted_at IS NULL AND NOT is_virtual
  ORDER BY created_at LIMIT 1;
  IF v_acc IS NOT NULL THEN RETURN v_acc; END IF;

  RAISE EXCEPTION 'Bạn chưa có sổ quỹ nào — tạo sổ "%% Thu" trong Tài chính → Sổ quỹ trước khi thu cọc';
END;
$$;








--
-- Name: get_organization_profile_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_organization_profile_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
  v_o   public.organizations%rowtype;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền xem thông tin tổ chức.' using errcode = '42501';
  end if;
  select * into v_o from public.organizations where id = v_org;

  return jsonb_build_object(
    'organizationId', v_o.id,
    'name',    v_o.name,
    'slug',    v_o.slug,
    'status',  v_o.status,
    'isDemo',  coalesce(v_o.is_demo, false),
    'createdAt', v_o.created_at,
    'authorizationVersion', v_o.authorization_version,
    'canEdit', public.is_super_admin() or app_private.has_any_scope_v3('settings.edit'),
    'counts', jsonb_build_object(
      'members',   (select count(*) from public.organization_memberships m
                     where m.organization_id = v_org and m.status = 'ACTIVE'),
      'owners',    (select count(*) from public.organization_memberships m
                     where m.organization_id = v_org and m.status = 'ACTIVE'
                       and m.member_type = 'OWNER'),
      'roles',     (select count(*) from public.organization_roles r
                     where r.organization_id = v_org and coalesce(r.status,'ACTIVE') = 'ACTIVE'),
      'buildings', (select count(*) from public.authorization_scopes s
                     where s.organization_id = v_org and s.scope_type = 'BUILDING'),
      'areas',     (select count(*) from public.authorization_scopes s
                     where s.organization_id = v_org and s.scope_type = 'AREA'),
      'cashbooks', (select count(*) from public.authorization_scopes s
                     where s.organization_id = v_org and s.scope_type = 'CASHBOOK'),
      'pendingInvitations', (select count(*) from public.organization_invitations i
                              where i.organization_id = v_org and i.status = 'PENDING'
                                and i.expires_at > now()),
      'activeOverrides', (select count(*) from public.member_permission_overrides o
                           where o.organization_id = v_org and o.revoked_at is null
                             and (o.expires_at is null or o.expires_at > now()))),
    'invitations', coalesce((
      select jsonb_agg(jsonb_build_object(
               'invitationId', i.id, 'email', i.email_normalized,
               'memberType', i.intended_member_type, 'status', i.status,
               'expiresAt', i.expires_at, 'createdAt', i.created_at,
               'roleName', r.name,
               'isExpired', (i.status = 'PENDING' and i.expires_at <= now()))
             order by i.created_at desc)
        from public.organization_invitations i
        left join public.organization_roles r on r.id = i.intended_role_id
       where i.organization_id = v_org
         and i.created_at > now() - interval '90 days'), '[]'::jsonb),
    'auditTrail', coalesce((
      select jsonb_agg(jsonb_build_object(
               'eventId', e.id, 'occurredAt', e.occurred_at, 'eventType', e.event_type,
               'resourceType', e.resource_type, 'resourceId', e.resource_id,
               'reason', e.reason,
               'actorEmail', coalesce(pa.email, ua.email),
               'actorName', pa.full_name,
               'newState', e.new_state)
             order by e.occurred_at desc)
        from (select * from public.authorization_audit_events ae
               where ae.organization_id = v_org
               order by ae.occurred_at desc limit 50) e
        left join public.profiles pa on pa.id = e.actor_user_id
        left join auth.users ua      on ua.id = e.actor_user_id), '[]'::jsonb));
end
$$;








--
-- Name: get_overpayment_summary(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overpayment_summary(p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'total', COALESCE(SUM(paid_amount - total_amount) FILTER (WHERE paid_amount > total_amount), 0),
    'count', COALESCE(COUNT(*) FILTER (WHERE paid_amount > total_amount), 0)
  )
  FROM public.invoices
  WHERE paid_amount > 0
    AND deleted_at IS NULL           -- vá luôn latent: không tính hoá đơn đã xoá
    AND (p_building_ids IS NULL OR building_id = ANY(p_building_ids));
$$;








--
-- Name: get_period_commissions(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_period_commissions(p_period_month text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(contract_id uuid, contract_number text, building_id uuid, building_name text, room_id uuid, room_name text, tenant_name text, signed_date date, months integer, tier_percent numeric, expected_amount numeric, voucher_id uuid, voucher_amount numeric, voucher_account_name text, account_is_empty boolean, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_start date;
  v_end   date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_period_month !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Kỳ không hợp lệ (cần YYYY-MM)';
  END IF;
  v_start := to_date(p_period_month || '-01', 'YYYY-MM-DD');
  v_end   := (date_trunc('month', v_start) + interval '1 month - 1 day')::date;

  RETURN QUERY
  WITH bld AS (
    SELECT b.id, b.name, b.commission_tiers
      FROM buildings b
     WHERE (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
       AND b.deleted_at IS NULL
       AND app_private.building_org_visible_v1(b.id)
       AND (public.can_access_building(b.id)
            OR public.ie_all_buildings_scope(b.id)
            OR b.user_id = auth.uid()
            OR public.is_admin() OR public.is_super_admin())
  ),
  ct AS (
    SELECT c.id, c.contract_number, c.signed_date, c.rent_price,
           r.id AS room_id, r.name AS room_name,
           bld.id AS building_id, bld.name AS building_name, bld.commission_tiers,
           GREATEST(
             (EXTRACT(YEAR FROM age(c.end_date, c.start_date)) * 12
              + EXTRACT(MONTH FROM age(c.end_date, c.start_date)))::int, 0) AS months
      FROM contracts c
      JOIN rooms r ON r.id = c.room_id
      JOIN bld ON bld.id = r.building_id
     WHERE c.deleted_at IS NULL
       AND c.signed_date >= v_start AND c.signed_date <= v_end
  )
  SELECT
    ct.id, ct.contract_number, ct.building_id, ct.building_name,
    ct.room_id, ct.room_name,
    COALESCE(rep.full_name, ''),
    ct.signed_date, ct.months,
    tier.rate,
    ROUND(ct.rent_price * COALESCE(tier.rate, 0) / 100.0)::numeric,
    v.voucher_id,
    v.voucher_amount,
    v.voucher_account_name,
    COALESCE(v.acc_empty, false),
    CASE WHEN v.voucher_id IS NULL THEN 'unpaid'
         WHEN v.approval_status = 'APPROVED' THEN 'paid'
         ELSE 'draft' END
  FROM ct
  LEFT JOIN LATERAL (
    SELECT cust.full_name
      FROM contract_customers cc
      JOIN customers cust ON cust.id = cc.customer_id
     WHERE cc.contract_id = ct.id
     ORDER BY cc.is_representative DESC NULLS LAST
     LIMIT 1
  ) rep ON true
  LEFT JOIN LATERAL (
    SELECT COALESCE(
      (SELECT (t->>'rate_percent')::numeric
         FROM jsonb_array_elements(COALESCE(ct.commission_tiers, '[]'::jsonb)) t
        WHERE ct.months >= (t->>'min_months')::int AND ct.months <= (t->>'max_months')::int
        ORDER BY (t->>'min_months')::int LIMIT 1),
      (SELECT (t->>'rate_percent')::numeric
         FROM jsonb_array_elements(COALESCE(ct.commission_tiers, '[]'::jsonb)) t
        WHERE ct.months > (t->>'max_months')::int
        ORDER BY (t->>'max_months')::int DESC LIMIT 1)
    ) AS rate
  ) tier ON true
  LEFT JOIN LATERAL (
    SELECT ie.id                AS voucher_id,
           ie.total_amount      AS voucher_amount,
           ie.approval_status,
           a.name               AS voucher_account_name,
           (ie.account_id IS NULL) AS acc_empty
      FROM income_expenses ie
      LEFT JOIN accounts a ON a.id = ie.account_id
     WHERE ie.contract_id = ct.id
       AND ie.type = 'EXPENSE' AND ie.deleted_at IS NULL
       AND ie.approval_status <> 'CANCELLED'
       AND (ie.commission_kind = 'broker'
            OR (ie.commission_kind IS NULL AND EXISTS (
                  SELECT 1 FROM income_expense_items it
                  JOIN income_expense_types tp ON tp.id = it.income_expense_type_id
                 WHERE it.income_expense_id = ie.id
                   AND public.nrm_vn(tp.name) LIKE '%hoa hong%')))
     ORDER BY (ie.approval_status = 'APPROVED') DESC, ie.created_at DESC
     LIMIT 1
  ) v ON true
  ORDER BY ct.signed_date DESC, ct.contract_number;
END;
$_$;








--
-- Name: get_period_fee_status(text, text, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_period_fee_status(p_period_start text, p_period_end text, p_building_ids uuid[], p_category_keys text[]) RETURNS TABLE(building_id uuid, category_key text, paid_amount numeric, draft_amount numeric, covered_start date, covered_end date, voucher_ids uuid[], vouchers jsonb, has_receipt boolean, account_name text, account_is_empty boolean, expected_amount numeric, not_applicable boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_start          date;
  v_end            date;
  v_can_restricted boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_period_start !~ '^\d{4}-\d{2}$' OR p_period_end !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Kỳ không hợp lệ (cần YYYY-MM)';
  END IF;
  v_start := to_date(p_period_start || '-01', 'YYYY-MM-DD');
  v_end   := (date_trunc('month', to_date(p_period_end || '-01', 'YYYY-MM-DD')) + interval '1 month - 1 day')::date;
  v_can_restricted := public.can_view_restricted_ie();

  RETURN QUERY
  WITH bld AS (
    SELECT b.id, b.hidden_fixed_expenses AS hidden
      FROM buildings b
     WHERE b.id = ANY(p_building_ids) AND b.deleted_at IS NULL
       AND app_private.building_org_visible_v1(b.id)
       AND (public.can_access_building(b.id)
            OR public.ie_all_buildings_scope(b.id)
            OR b.user_id = auth.uid()
            OR public.is_admin() OR public.is_super_admin())
  ),
  -- DISTINCT: p_category_keys trùng lặp không được nhân đôi tổng item (A2).
  cat AS (
    SELECT DISTINCT k FROM unnest(p_category_keys) AS k
     WHERE k IN ('tien_nha','dien','nuoc','internet','quan_ly','ve_sinh','cong_an','rac','thang_may')
  ),
  pairs AS (
    SELECT bld.id AS building_id, cat.k AS category_key,
           cat.k = ANY(bld.hidden) AS is_na
      FROM bld CROSS JOIN cat
  ),
  -- DISTINCT: một kind có thể khớp nhiều type; mỗi (kind, type) chỉ được một dòng.
  typed AS (
    SELECT DISTINCT c.k AS category_key, t.id AS type_id
      FROM cat c
      JOIN income_expense_types t
        ON t.type = 'expense'
       AND public.fee_type_matches(c.k, t.category, t.name)
     WHERE (NOT t.is_restricted OR v_can_restricted)
  ),
  vperv AS (
    SELECT p.building_id, p.category_key,
           ie.id            AS vid,
           -- A2: TỔNG HẠNG MỤC KHỚP kind này, KHÔNG phải tổng cả phiếu.
           SUM(it.amount)   AS amount,
           ie.total_amount  AS vtotal,
           ie.approval_status AS st,
           ie.posting_status  AS pstatus,
           ie.system_source AS source,
           ie.voucher_date  AS vdate,
           ie.account_id    AS acc_id,
           a.name           AS acc_name,
           ie.attachments   AS atts,
           ie.notes         AS vnotes,
           ie.creator_name  AS vcreator,
           (ie.repeat_parent_id IS NOT NULL
             OR public.nrm_vn(ie.name) LIKE '%tu dong%') AS is_auto,
           EXISTS (SELECT 1 FROM income_expense_batch_items bi WHERE bi.income_expense_id = ie.id) AS in_batch,
           -- A2: phiếu có chủ luồng ⇒ guard_income_expense_owned_payload chặn
           -- UPDATE deleted_at bằng 55000 ⇒ KHÔNG được coi là huỷ được.
           EXISTS (SELECT 1 FROM app_private.income_expense_flow_ownership o
                    WHERE o.income_expense_id = ie.id) AS flow_owned,
           min(it.start_date) AS cstart,
           max(it.end_date)   AS cend,
           count(it.id)       AS item_cnt
      FROM pairs p
      JOIN typed ty ON ty.category_key = p.category_key
      JOIN income_expense_items it ON it.income_expense_type_id = ty.type_id
      JOIN income_expenses ie ON ie.id = it.income_expense_id
                             AND ie.building_id = p.building_id
                             AND ie.type = 'EXPENSE'
                             AND ie.approval_status IN ('APPROVED','UNAPPROVED')
                             AND ie.deleted_at IS NULL
                             -- A1/§−1.3 lưới hai: tiền lương không phải phí cố định.
                             AND COALESCE(ie.system_source, '') NOT LIKE 'salary.%'
      LEFT JOIN accounts a ON a.id = ie.account_id
     WHERE it.start_date <= v_end AND it.end_date >= v_start
     GROUP BY p.building_id, p.category_key, ie.id, ie.total_amount, ie.approval_status,
              ie.posting_status, ie.system_source, ie.voucher_date, ie.account_id, a.name,
              ie.attachments, ie.notes, ie.creator_name, ie.name, ie.repeat_parent_id
  )
  SELECT
    p.building_id,
    p.category_key,
    COALESCE(SUM(v.amount) FILTER (WHERE v.st = 'APPROVED'), 0)                    AS paid_amount,
    COALESCE(SUM(v.amount) FILTER (WHERE v.st = 'UNAPPROVED'), 0)                  AS draft_amount,
    MIN(v.cstart) FILTER (WHERE v.st = 'APPROVED')                                 AS covered_start,
    MAX(v.cend)   FILTER (WHERE v.st = 'APPROVED')                                 AS covered_end,
    COALESCE(array_agg(v.vid ORDER BY v.vdate DESC, v.vid) FILTER (WHERE v.vid IS NOT NULL), '{}'::uuid[]) AS voucher_ids,
    COALESCE(jsonb_agg(jsonb_build_object(
        'id', v.vid,
        -- 'amount' = phần thuộc hạng mục này (A2). 'voucher_total' = cả phiếu.
        'amount', v.amount,
        'voucher_total', v.vtotal,
        'status', v.st,
        'posting_status', v.pstatus,
        'date', v.vdate,
        'source', v.source,
        'is_auto', v.is_auto,
        'in_batch', v.in_batch,
        'flow_owned', v.flow_owned,
        'cancellable', (NOT v.in_batch AND NOT v.flow_owned),
        'cancel_blocked_reason', CASE WHEN v.in_batch THEN 'IN_BATCH'
                                      WHEN v.flow_owned THEN 'FLOW_OWNED'
                                      ELSE NULL END,
        'account_id', v.acc_id,
        'account_name', v.acc_name,
        'attachments', COALESCE(v.atts, '[]'::jsonb),
        'notes', v.vnotes,
        'item_count', v.item_cnt,
        'start', v.cstart,
        'end', v.cend,
        'creator_name', v.vcreator
      ) ORDER BY v.vdate DESC, v.vid) FILTER (WHERE v.vid IS NOT NULL), '[]'::jsonb) AS vouchers,
    COALESCE(bool_or(jsonb_typeof(v.atts) = 'array' AND jsonb_array_length(v.atts) > 0), false) AS has_receipt,
    (array_agg(v.acc_name ORDER BY v.vdate DESC) FILTER (WHERE v.st = 'APPROVED' AND v.acc_name IS NOT NULL))[1] AS account_name,
    COALESCE(bool_or(v.st = 'APPROVED' AND v.acc_id IS NULL), false)               AS account_is_empty,
    CASE WHEN p.category_key = 'quan_ly' AND NOT v_can_restricted THEN NULL
         ELSE MAX(fa.default_amount) END                                           AS expected_amount,
    p.is_na                                                                        AS not_applicable
  FROM pairs p
  LEFT JOIN vperv v ON v.building_id = p.building_id AND v.category_key = p.category_key
  LEFT JOIN building_fee_accounts fa ON fa.building_id = p.building_id
                                    AND fa.fee_category = p.category_key
                                    AND fa.deleted_at IS NULL
  GROUP BY p.building_id, p.category_key, p.is_na;
END;
$_$;








--
-- Name: FUNCTION get_period_fee_status(p_period_start text, p_period_end text, p_building_ids uuid[], p_category_keys text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_period_fee_status(p_period_start text, p_period_end text, p_building_ids uuid[], p_category_keys text[]) IS 'Trạng thái đã/chưa đóng phí cố định theo toà × hạng mục × kỳ. Slice −1 A2: paid/draft cộng TỔNG HẠNG MỤC KHỚP (không phải total_amount cả phiếu, vốn làm phiếu đa-hạng-mục bị đếm hai lần); cancellable loại phiếu in-batch VÀ phiếu flow-owned (guard payload ném 55000); phiếu system_source salary.* bị loại khỏi read model.';








--
-- Name: get_period_maintenance(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_period_maintenance(p_period_month text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(batch_id uuid, payer_name text, voucher_id uuid, building_id uuid, building_name text, subtype text, amount numeric, account_name text, has_receipt boolean, voucher_date date, is_standalone boolean, approval_status text, posting_status text, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_start date;
  v_end   date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_period_month !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Kỳ không hợp lệ (cần YYYY-MM)';
  END IF;
  v_start := to_date(p_period_month || '-01', 'YYYY-MM-DD');
  v_end   := (date_trunc('month', v_start) + interval '1 month - 1 day')::date;

  RETURN QUERY
  WITH bld AS (
    SELECT b.id, b.name
      FROM buildings b
     WHERE (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
       AND b.deleted_at IS NULL
       AND app_private.building_org_visible_v1(b.id)
       AND (public.can_access_building(b.id)
            OR public.ie_all_buildings_scope(b.id)
            OR b.user_id = auth.uid()
            OR public.is_admin() OR public.is_super_admin())
  ),
  v AS (
    SELECT ie.id AS voucher_id, ie.building_id, ie.account_id, ie.voucher_date,
           ie.attachments, ie.approval_status, ie.posting_status,
           CASE WHEN public.nrm_vn(tp.name) LIKE '%may giat%' THEN 'mg' ELSE 'ml' END AS subtype,
           -- A3/A2: tổng hạng mục bảo trì khớp, không phải tổng cả phiếu.
           SUM(it.amount) AS amount
      FROM income_expenses ie
      JOIN bld ON bld.id = ie.building_id
      JOIN income_expense_items it ON it.income_expense_id = ie.id
      JOIN income_expense_types tp ON tp.id = it.income_expense_type_id
     WHERE ie.type = 'EXPENSE'
       -- A3: phơi cả phiếu CHỜ DUYỆT (ie_compat_insert_v2 luôn tạo UNAPPROVED).
       AND ie.approval_status IN ('APPROVED','UNAPPROVED')
       AND ie.deleted_at IS NULL
       AND (public.nrm_vn(tp.name) LIKE '%bao tri may lanh%'
            OR public.nrm_vn(tp.name) LIKE '%bao tri may giat%'
            OR public.nrm_vn(tp.name) LIKE '%may lanh%'
            OR public.nrm_vn(tp.name) LIKE '%may giat%')
       AND it.start_date <= v_end AND it.end_date >= v_start
     GROUP BY ie.id, ie.building_id, ie.account_id, ie.voucher_date, ie.attachments,
              ie.approval_status, ie.posting_status,
              CASE WHEN public.nrm_vn(tp.name) LIKE '%may giat%' THEN 'mg' ELSE 'ml' END
  )
  SELECT
    bi.batch_id,
    bt.payer_name,
    v.voucher_id, v.building_id, bld.name,
    v.subtype, v.amount,
    a.name,
    (jsonb_typeof(v.attachments) = 'array' AND jsonb_array_length(v.attachments) > 0),
    v.voucher_date::date,
    (bi.batch_id IS NULL),
    v.approval_status,
    v.posting_status,
    (CASE WHEN v.approval_status = 'UNAPPROVED'   THEN 'PENDING_APPROVAL'
          WHEN v.posting_status  = 'POSTED'       THEN 'POSTED'
          ELSE 'APPROVED_UNPOSTED' END)::text
  FROM v
  JOIN bld ON bld.id = v.building_id
  LEFT JOIN accounts a ON a.id = v.account_id
  LEFT JOIN income_expense_batch_items bi ON bi.income_expense_id = v.voucher_id
  LEFT JOIN income_expense_batches bt ON bt.id = bi.batch_id
  ORDER BY bi.batch_id NULLS LAST, bld.name;
END;
$_$;








--
-- Name: FUNCTION get_period_maintenance(p_period_month text, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_period_maintenance(p_period_month text, p_building_ids uuid[]) IS 'Phiếu bảo trì máy lạnh/máy giặt đã có trong kỳ. Slice −1 A3: phơi cả phiếu UNAPPROVED kèm cột state (PENDING_APPROVAL/APPROVED_UNPOSTED/POSTED) để tab Bảo trì hiện "đã tạo, chờ duyệt" thay vì "chưa có phiếu" rồi mời tạo lại; amount cộng theo hạng mục bảo trì khớp và gộp theo (phiếu, subtype).';








--
-- Name: get_public_available_rooms(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_available_rooms(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner   uuid;
  v_soon    int;
  v_hotline uuid;
  v_result  jsonb;
BEGIN
  IF p_token IS NULL OR p_token = '' THEN
    RETURN NULL;
  END IF;

  SELECT owner_id INTO v_owner
  FROM public.public_room_share_tokens
  WHERE token = p_token AND revoked = false;

  IF v_owner IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT soon_days, hotline_id INTO v_soon, v_hotline
  FROM public.public_room_settings
  WHERE owner_id = v_owner;
  IF v_soon IS NULL THEN v_soon := 30; END IF;

  WITH rms AS (
    SELECT
      rm.id,
      rm.building_id,
      rm.floor,
      rm.name,
      rm.code,
      rm.area,
      rm.rent_price,
      rm.deposit_amount,
      rm.max_occupants,
      COALESCE(rm.amenities, '[]'::jsonb) AS amenities,
      COALESCE(rm.images,    '[]'::jsonb) AS images,
      rm.description,
      rm.sale_note,
      rm.sale_bonus_note,
      rm.room_type,
      -- Phòng khách nhờ sale (overlay). Khi contact_manager → che SĐT/tên khách.
      CASE WHEN pl.contact_manager THEN NULL ELSE pl.contact_name  END AS pass_contact_name,
      CASE WHEN pl.contact_manager THEN NULL ELSE pl.contact_phone END AS pass_contact_phone,
      pl.sale_policy   AS pass_sale_policy,
      pl.pass_price    AS pass_price,
      pl.avail_date    AS pass_avail_date,
      COALESCE(pl.contact_manager, false) AS pass_contact_manager,
      CASE
        WHEN pl.id IS NOT NULL THEN 'pass'
        -- Đã có cọc giữ chỗ chưa gắn HĐ → phòng bị KHOÁ, không chào khách nữa.
        -- Đặt TRƯỚC nhánh 'soon' vì phòng sắp trống vẫn còn HĐ hiệu lực nên
        -- rooms.status không thể là RESERVED (reconcile bỏ qua phòng có HĐ).
        WHEN public.room_has_holding_deposit(rm.id) THEN 'rented'
        WHEN EXISTS (
          SELECT 1 FROM public.contracts c
          WHERE c.room_id = rm.id
            AND c.deleted_at IS NULL
            AND c.status IN ('ACTIVE','EXTENDED')
            AND (
              (c.expected_move_out_date IS NOT NULL
                AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon)
              OR COALESCE(c.actual_end_date, c.end_date)
                   BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
            )
        ) THEN 'soon'
        WHEN EXISTS (
          SELECT 1 FROM public.contracts c
          WHERE c.room_id = rm.id
            AND c.deleted_at IS NULL
            AND c.status IN ('ACTIVE','EXTENDED')
        ) THEN 'rented'
        WHEN rm.status = 'AVAILABLE' THEN 'free'
        ELSE 'rented'
      END AS status_public,
      (
        SELECT MIN(
          CASE
            WHEN c.expected_move_out_date IS NOT NULL
              AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
              THEN c.expected_move_out_date
            ELSE COALESCE(c.actual_end_date, c.end_date)
          END
        )
        FROM public.contracts c
        WHERE c.room_id = rm.id
          AND c.deleted_at IS NULL
          AND c.status IN ('ACTIVE','EXTENDED')
          AND (
            (c.expected_move_out_date IS NOT NULL
              AND c.expected_move_out_date BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon)
            OR COALESCE(c.actual_end_date, c.end_date)
                 BETWEEN public.org_today_v1(NULL) AND public.org_today_v1(NULL) + v_soon
          )
      ) AS avail_date
    FROM public.rooms rm
    JOIN public.buildings b ON b.id = rm.building_id
    LEFT JOIN public.room_pass_listings pl
      ON pl.room_id = rm.id AND pl.user_id = v_owner AND pl.active = true
    WHERE b.user_id = v_owner
      AND b.is_virtual = false
      AND b.deleted_at IS NULL
      AND rm.deleted_at IS NULL
  ),
  bld_ids AS (
    SELECT DISTINCT building_id FROM rms WHERE status_public IN ('free','soon','pass')
  ),
  rooms_j AS (
    SELECT jsonb_agg(to_jsonb(rms) ORDER BY rms.floor DESC, rms.name) AS j
    FROM rms
    WHERE rms.building_id IN (SELECT building_id FROM bld_ids)
  ),
  blds_j AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id',           b.id,
      'name',         b.name,
      'code',         b.code,
      'area_ids',     COALESCE((
                        SELECT jsonb_agg(ab.area_id)
                        FROM public.area_buildings ab
                        JOIN public.areas a ON a.id = ab.area_id
                        WHERE ab.building_id = b.id AND a.deleted_at IS NULL
                      ), '[]'::jsonb),
      'district',     b.district,
      'ward',         b.ward,
      'address',      CASE
                        WHEN b.street_address IS NOT NULL AND b.street_address LIKE '%,%'
                          THEN b.street_address
                        ELSE concat_ws(', ',
                               NULLIF(b.street_address, ''),
                               NULLIF(b.ward, ''),
                               NULLIF(b.district, ''),
                               NULLIF(b.province, ''))
                      END,
      'total_floors', b.total_floors,
      'floor_layouts', b.floor_layouts,
      'images',        COALESCE(b.images, '[]'::jsonb),
      'public_contact_name',  b.public_contact_name,
      'public_contact_phone', b.public_contact_phone,
      'public_map_url',       b.public_map_url,
      'public_lift_type',     b.public_lift_type,
      'elec_rate', (
        SELECT COALESCE(bs.unit_price_override, s.unit_price)
        FROM public.building_services bs
        JOIN public.services s ON s.id = bs.service_id
        WHERE bs.building_id = b.id
          AND bs.is_active = true
          AND s.deleted_at IS NULL
          AND s.unit ILIKE 'kwh'
        ORDER BY (s.type = 'FIXED') DESC, s.unit_price
        LIMIT 1
      )
    ) ORDER BY b.name) AS j
    FROM public.buildings b
    WHERE b.id IN (SELECT building_id FROM bld_ids)
  ),
  areas_j AS (
    SELECT jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name) ORDER BY a.name) AS j
    FROM public.areas a
    WHERE a.user_id = v_owner AND a.deleted_at IS NULL
  ),
  contact_j AS (
    SELECT jsonb_build_object('name', h.name, 'phone', h.phone_number) AS j
    FROM public.hotlines h
    WHERE h.user_id = v_owner
      AND COALESCE(h.is_active, true) = true
      AND (v_hotline IS NULL OR h.id = v_hotline)
    ORDER BY (h.id = v_hotline) DESC NULLS LAST, h.created_at
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'areas',     COALESCE((SELECT j FROM areas_j), '[]'::jsonb),
    'buildings', COALESCE((SELECT j FROM blds_j), '[]'::jsonb),
    'rooms',     COALESCE((SELECT j FROM rooms_j), '[]'::jsonb),
    'contact',   (SELECT j FROM contact_j)
  ) INTO v_result;

  RETURN v_result;
END;
$$;








--
-- Name: FUNCTION get_public_available_rooms(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_available_rooms(p_token text) IS 'Public read API trang "Phòng trống" (/r/:token). Token -> owner; trả jsonb
{areas, buildings, rooms, contact}, chỉ toà có phòng free/soon. soon_days theo
public_room_settings (mặc định 30). buildings có floor_layouts + images. Trả NULL
nếu token sai/đã thu hồi. Không expose user_id/hợp đồng/khách thuê.';








--
-- Name: get_public_latest_invoice_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_latest_invoice_by_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_code IS NULL OR p_code = '' THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_id
  FROM public.contracts
  WHERE public_code = p_code
    AND deleted_at IS NULL;

  IF v_id IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN public.get_public_latest_invoice_by_contract(v_id);
END;
$$;








--
-- Name: FUNCTION get_public_latest_invoice_by_code(p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_latest_invoice_by_code(p_code text) IS 'Public read API cho khách quét QR theo mã ngắn (contracts.public_code). Resolve mã → contract.id rồi gọi get_public_latest_invoice_by_contract. Trả NULL nếu mã sai / HĐ đã thanh lý / bị xoá.';








--
-- Name: get_public_latest_invoice_by_contract(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_latest_invoice_by_contract(p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract RECORD;
  v_invoice_id uuid;
  v_result jsonb;
BEGIN
  -- Hợp đồng phải tồn tại, chưa xoá, và chưa thanh lý.
  SELECT id, status, room_id, deleted_at
  INTO v_contract
  FROM public.contracts
  WHERE id = p_contract_id;

  IF v_contract.id IS NULL
     OR v_contract.deleted_at IS NOT NULL
     OR v_contract.status = 'TERMINATED' THEN
    RETURN NULL;
  END IF;

  -- Hoá đơn mới nhất của hợp đồng (bỏ DRAFT/CANCELLED).
  SELECT id INTO v_invoice_id
  FROM public.invoices
  WHERE contract_id = p_contract_id
    AND deleted_at IS NULL
    AND status <> 'CANCELLED'
    AND status <> 'DRAFT'
  ORDER BY billing_month DESC, created_at DESC
  LIMIT 1;

  IF v_invoice_id IS NULL THEN
    SELECT jsonb_build_object(
      'invoice', NULL,
      'room', CASE WHEN r.id IS NOT NULL
        THEN jsonb_build_object('id', r.id, 'name', r.name, 'code', r.code)
        ELSE NULL END,
      'building', CASE WHEN b.id IS NOT NULL
        THEN jsonb_build_object('id', b.id, 'name', b.name)
        ELSE NULL END,
      'bed', NULL,
      'customer', CASE WHEN c.full_name IS NOT NULL
        THEN jsonb_build_object('full_name', c.full_name, 'phone', c.phone)
        ELSE NULL END
    )
    INTO v_result
    FROM public.contracts ct
    LEFT JOIN public.rooms r ON r.id = ct.room_id
    LEFT JOIN public.buildings b ON b.id = r.building_id
    LEFT JOIN LATERAL (
      SELECT cust.full_name, cust.phone
      FROM public.contract_customers cc
      JOIN public.customers cust ON cust.id = cc.customer_id
      WHERE cc.contract_id = ct.id
      ORDER BY cc.is_representative DESC NULLS LAST
      LIMIT 1
    ) c ON TRUE
    WHERE ct.id = p_contract_id;

    RETURN v_result;
  END IF;

  SELECT jsonb_build_object(
    'invoice', jsonb_build_object(
      'id', i.id,
      'invoice_number', i.invoice_number,
      'billing_month', i.billing_month,
      'issue_date', i.issue_date,
      'due_date', i.due_date,
      'status', i.status,
      'subtotal', i.subtotal,
      'discount_amount', i.discount_amount,
      'total_amount', i.total_amount,
      'paid_amount', i.paid_amount,
      'remaining_amount', i.remaining_amount,
      'previous_debt', i.previous_debt,
      'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', it.id,
          'type', it.type,
          'description', it.description,
          'unit_price', it.unit_price,
          'quantity', it.quantity,
          'coefficient', it.coefficient,
          'amount', it.amount,
          'previous_reading', it.previous_reading,
          'current_reading', it.current_reading,
          'from_date', it.from_date,
          'to_date', it.to_date
        ) ORDER BY it.sort_order NULLS LAST, it.created_at)
        FROM public.invoice_items it
        WHERE it.invoice_id = i.id
      ), '[]'::jsonb)
    ),
    'room', CASE WHEN r.id IS NOT NULL
      THEN jsonb_build_object('id', r.id, 'name', r.name, 'code', r.code)
      ELSE NULL END,
    'building', CASE WHEN b.id IS NOT NULL
      THEN jsonb_build_object('id', b.id, 'name', b.name)
      ELSE NULL END,
    'bed', NULL,
    'customer', CASE WHEN c.full_name IS NOT NULL
      THEN jsonb_build_object('full_name', c.full_name, 'phone', c.phone)
      ELSE NULL END
  )
  INTO v_result
  FROM public.invoices i
  LEFT JOIN public.rooms r ON r.id = i.room_id
  LEFT JOIN public.buildings b ON b.id = i.building_id
  LEFT JOIN LATERAL (
    SELECT cust.full_name, cust.phone
    FROM public.contract_customers cc
    JOIN public.customers cust ON cust.id = cc.customer_id
    WHERE cc.contract_id = i.contract_id
    ORDER BY cc.is_representative DESC NULLS LAST
    LIMIT 1
  ) c ON TRUE
  WHERE i.id = v_invoice_id;

  RETURN v_result;
END;
$$;








--
-- Name: FUNCTION get_public_latest_invoice_by_contract(p_contract_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_latest_invoice_by_contract(p_contract_id uuid) IS 'Public read API cho khách quét QR theo hợp đồng. Trả NULL nếu hợp đồng đã thanh lý / bị xoá. Bypass RLS có kiểm soát, không expose notes/contract_id/user_id.';








--
-- Name: get_refund_forfeit_summary(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_refund_forfeit_summary(p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT t.id                        AS term_id,
           t.contract_id               AS contract_id,
           t.termination_type          AS tt,
           t.status                    AS tstatus,
           COALESCE(t.total_deposit, 0) AS td,
           COALESCE(t.refund_amount, 0) AS ra
    FROM public.contract_terminations t
    JOIN public.contracts c ON c.id = t.contract_id
    JOIN public.rooms r ON r.id = c.room_id
    WHERE (p_building_ids IS NULL OR r.building_id = ANY(p_building_ids))
  ),
  -- Phiếu hoàn cọc còn sống (kể cả CHƯA DUYỆT — chúng là "chờ chi", phải đếm
  -- vào refund_pending_*; CANCELLED thì loại hẳn). `is_posted` = tiền ĐÃ RA KÉT.
  rv AS (
    SELECT ie.id, ie.contract_id, ie.building_id, ie.total_amount,
           (ie.approval_status = 'APPROVED'
             AND ie.posting_status = 'POSTED'
             AND ie.active_posting_id_v2 IS NOT NULL) AS is_posted
    FROM public.income_expenses ie
    WHERE ie.system_source = 'termination.refund'
      AND ie.type = 'EXPENSE'
      AND ie.deleted_at IS NULL
      AND ie.approval_status IN ('APPROVED','UNAPPROVED')
  ),
  -- Gộp theo từng hồ sơ thanh lý để `td`/`ra` không bị nhân bản khi một HĐ
  -- mang nhiều phiếu hoàn.
  per_term AS (
    SELECT b.*,
           COALESCE(SUM(rv.total_amount) FILTER (WHERE rv.is_posted), 0)     AS posted_amount,
           COUNT(rv.id)                 FILTER (WHERE rv.is_posted)          AS posted_vouchers,
           COALESCE(SUM(rv.total_amount) FILTER (WHERE NOT rv.is_posted), 0) AS unposted_amount,
           COUNT(rv.id)                 FILTER (WHERE NOT rv.is_posted)      AS unposted_vouchers
    FROM base b
    LEFT JOIN rv ON rv.contract_id = b.contract_id
    GROUP BY b.term_id, b.contract_id, b.tt, b.tstatus, b.td, b.ra
  ),
  -- Phiếu hoàn ĐÃ GHI SỔ nhưng KHÔNG có hồ sơ thanh lý nào — chỉ để GHI NHẬN.
  orphan AS (
    SELECT COALESCE(SUM(rv.total_amount), 0) AS amount, COUNT(*) AS cnt
    FROM rv
    WHERE rv.is_posted
      AND (p_building_ids IS NULL OR rv.building_id = ANY(p_building_ids))
      AND NOT EXISTS (SELECT 1 FROM public.contract_terminations t2
                       WHERE t2.contract_id = rv.contract_id)
  ),
  -- QUYẾT ĐỊNH CỦA CHỦ 30/07: KPI "Đã hoàn cọc" phải là TIỀN THẬT ĐÃ RA KHỎI KÉT,
  -- tức MỌI phiếu hoàn đã ghi sổ — kể cả phiếu không nối được hồ sơ thanh lý.
  -- Lý do: nếu chỉ lấy phần nối được hồ sơ (4.302.000đ) thì khai THIẾU 23.737.100đ
  -- tiền đã chi thật, tức đổi lỗi khai thừa hôm nay thành lỗi khai thiếu.
  -- Đối chiếu: refund_total = refund_linked_total + refund_posted_orphan_total.
  posted_all AS (
    SELECT COALESCE(SUM(rv.total_amount), 0) AS amount, COUNT(*) AS cnt
    FROM rv
    WHERE rv.is_posted
      AND (p_building_ids IS NULL OR rv.building_id = ANY(p_building_ids))
  )
  SELECT jsonb_build_object(
    -- ── Bốn khoá CŨ, giữ nguyên tên (frontend đang đọc) ──
    -- Tiền hoàn ĐÃ RA KÉT = TẤT CẢ phiếu hoàn POSTED (org thật: 28.039.100đ / 10).
    -- KHÔNG dùng cột GENERATED, và KHÔNG giới hạn theo hồ sơ thanh lý.
    'refund_total',  (SELECT amount FROM posted_all),
    'refund_count',  (SELECT cnt    FROM posted_all),

    -- Phần nối được hồ sơ thanh lý — đây là phần khớp đúng BẢNG bên dưới KPI
    -- (org thật: 4.302.000đ / 2 hồ sơ). Chênh lệch với refund_total chính là
    -- refund_posted_orphan_total, phải hiện thành một dòng cảnh báo trên UI.
    -- ⚠ ĐƠN VỊ: refund_linked_count đếm HỒ SƠ THANH LÝ (một hồ sơ có thể mang
    -- nhiều phiếu hoàn), KHÁC ĐƠN VỊ với refund_count / refund_posted_orphan_count
    -- (đếm PHIẾU). Cần số phiếu của phần nối được thì dùng refund_voucher_count
    -- ở dưới — đừng trộn hai đơn vị vào một phép trừ/cộng.
    'refund_linked_total', (SELECT COALESCE(SUM(posted_amount), 0) FROM per_term WHERE tt <> 'FORFEIT'),
    'refund_linked_count', (SELECT COUNT(*)                        FROM per_term WHERE tt <> 'FORFEIT' AND posted_vouchers > 0),
    'forfeit_total', (SELECT COALESCE(SUM(td), 0)                 FROM per_term WHERE tt =  'FORFEIT'),
    'forfeit_count', (SELECT COUNT(*)                             FROM per_term WHERE tt =  'FORFEIT'),

    -- ── Khoá MỚI (WS-D dùng; client cũ bỏ qua an toàn) ──
    -- Số PHIẾU hoàn đã ghi sổ NỐI ĐƯỢC hồ sơ thanh lý non-FORFEIT — tức cùng đơn
    -- vị với refund_count/refund_posted_orphan_count, và luôn ≤ refund_count
    -- (refund_count đã đếm MỌI phiếu POSTED, kể cả phiếu mồ côi). Nó có thể lớn
    -- hơn refund_linked_count khi một hồ sơ mang nhiều phiếu hoàn — đó là lý do
    -- khoá này tồn tại. (Ghi chú cũ nói "có thể > refund_count" là SAI đơn vị.)
    'refund_voucher_count',        (SELECT COALESCE(SUM(posted_vouchers), 0)  FROM per_term WHERE tt <> 'FORFEIT'),
    -- Đã tạo phiếu hoàn nhưng CHƯA ghi sổ ⇒ "chờ chi", không phải "đã hoàn".
    'refund_pending_total',        (SELECT COALESCE(SUM(unposted_amount), 0)  FROM per_term WHERE tt <> 'FORFEIT'),
    'refund_pending_count',        (SELECT COUNT(*)                           FROM per_term WHERE tt <> 'FORFEIT' AND unposted_vouchers > 0),
    -- "Net quyết toán lịch sử" = ĐÚNG công thức CŨ (cột GENERATED), giữ lại để
    -- đối chiếu chứ KHÔNG dùng làm KPI tiền ra két. Org thật = 8.290.000đ / 3.
    'refund_net_settlement_total', (SELECT COALESCE(SUM(GREATEST(0, ra)), 0)  FROM per_term WHERE tt <> 'FORFEIT'),
    'refund_net_settlement_count', (SELECT COUNT(*)                           FROM per_term WHERE tt <> 'FORFEIT'),
    -- refund_amount ÂM = khách còn nợ, phải hiện "Khách còn nợ", tuyệt đối
    -- không hiện "Đã hoàn 0đ" (2 HĐ DEMO đang bị vậy, −2.241.000đ mỗi HĐ).
    'customer_debt_total',         (SELECT COALESCE(SUM(-ra), 0)              FROM per_term WHERE tt <> 'FORFEIT' AND ra < 0),
    'customer_debt_count',         (SELECT COUNT(*)                           FROM per_term WHERE tt <> 'FORFEIT' AND ra < 0),
    -- GHI NHẬN (không sửa): phiếu hoàn đã ghi sổ mà không có hồ sơ thanh lý.
    -- Org thật hôm nay: 23.737.100đ / 8 phiếu (đo lại 30/07).
    --
    -- ĐỐI CHIẾU — PHẢI VIẾT ĐÚNG ĐƠN VỊ (sửa 30/07 sau rà vòng 2):
    --   • theo TIỀN  : refund_linked_total (4.302.000) + refund_posted_orphan_total
    --                  (23.737.100) = refund_total (28.039.100)  ← đẳng thức UI dùng
    --   • theo PHIẾU : refund_voucher_count (2) + refund_posted_orphan_count (8)
    --                  = refund_count (10)
    -- KHÔNG viết "2 + 8 = 10 phiếu" với số 2 lấy từ refund_linked_count: khoá đó
    -- đếm HỒ SƠ. Hôm nay hai số trùng nhau (2 hồ sơ mang đúng 2 phiếu) nên đẳng
    -- thức sai đơn vị vẫn "đúng" — nó vỡ ngay lần đầu một hồ sơ mang 2 phiếu hoàn.
    -- Đẳng thức theo phiếu cũng chỉ đúng khi (đo prod 30/07, cả hai = 0):
    -- phiếu hoàn POSTED gắn hồ sơ FORFEIT = 0, và HĐ có >1 hồ sơ thanh lý = 0
    -- (idx_terminations_unique_contract giữ điều thứ hai). Nếu về sau một trong
    -- hai khác 0 thì phần dư nằm ngoài cả linked lẫn orphan — phải bổ sung khoá,
    -- đừng chỉnh con số cho khớp.
    'refund_posted_orphan_total',  (SELECT amount FROM orphan),
    'refund_posted_orphan_count',  (SELECT cnt    FROM orphan)
  );
$$;








--
-- Name: FUNCTION get_refund_forfeit_summary(p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_refund_forfeit_summary(p_building_ids uuid[]) IS 'KPI "Đã hoàn cọc / Bỏ cọc" của /deposits. Slice −1 A4: refund_total/refund_count lái bằng PHIẾU HOÀN ĐÃ GHI SỔ (system_source=termination.refund, APPROVED, posting_status=POSTED, active_posting_id_v2 IS NOT NULL) thay cho cột GENERATED contract_terminations.refund_amount — trước đó org thật hiện 8.290.000đ/3 lần. QUYẾT ĐỊNH CỦA CHỦ 30/07: refund_total là TIỀN THẬT ĐÃ RA KÉT nên gồm CẢ phiếu không nối được hồ sơ thanh lý (org thật 28.039.100đ/10 PHIẾU). Phần nối được hồ sơ — tức phần khớp đúng bảng bên dưới — ở refund_linked_* (4.302.000đ / 2 HỒ SƠ = 2 phiếu, số phiếu ở refund_voucher_count), phần chưa nối ở refund_posted_orphan_* (23.737.100đ / 8 PHIẾU) và UI PHẢI hiện nó thành một dòng cảnh báo để KPI và bảng đối chiếu được — theo TIỀN: refund_linked_total + refund_posted_orphan_total = refund_total; theo PHIẾU: refund_voucher_count + refund_posted_orphan_count = refund_count. refund_linked_count là số HỒ SƠ, đừng dùng nó trong phép đối chiếu phiếu. Công thức GENERATED cũ giữ ở refund_net_settlement_* chỉ để tham chiếu lịch sử.';








--
-- Name: get_reservation_deposit_summary(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reservation_deposit_summary(p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH vouchers AS (
    SELECT ie.id, ie.approval_status, ie.total_amount,
           (SELECT COALESCE(SUM(it.amount), 0)
              FROM public.income_expense_items it
              JOIN public.income_expense_types t ON t.id = it.income_expense_type_id
             WHERE it.income_expense_id = ie.id AND t.is_deposit = true) AS dep_sum
    FROM public.income_expenses ie
    WHERE ie.contract_id IS NULL AND ie.deleted_at IS NULL AND ie.type = 'INCOME'
      AND ie.approval_status IN ('APPROVED','UNAPPROVED','CANCELLED')
      AND (p_building_ids IS NULL OR ie.building_id = ANY(p_building_ids))
      AND EXISTS (SELECT 1 FROM public.income_expense_items it
                  JOIN public.income_expense_types t ON t.id = it.income_expense_type_id
                  WHERE it.income_expense_id = ie.id AND t.is_deposit = true)
  ),
  amt AS (
    SELECT id, approval_status,
           CASE WHEN dep_sum <> 0 THEN dep_sum ELSE total_amount END AS amount
    FROM vouchers
  )
  SELECT jsonb_build_object(
    'holding_amount', COALESCE(SUM(amount) FILTER (WHERE approval_status = 'APPROVED'), 0),
    'approved_count', COALESCE(COUNT(*) FILTER (WHERE approval_status = 'APPROVED'), 0),
    'unapproved_count', COALESCE(COUNT(*) FILTER (WHERE approval_status = 'UNAPPROVED'), 0),
    'cancelled_count', COALESCE(COUNT(*) FILTER (WHERE approval_status = 'CANCELLED'), 0)
  ) FROM amt;
$$;








--
-- Name: get_room_residence_conflicts_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_room_residence_conflicts_v1(p_contract_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(contract_id uuid, contract_number text, diagnostic text, seg_count integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT s.contract_id, s.contract_number, min(s.diagnostic), count(*)::int
    FROM public.get_room_residence_segments_v1(p_contract_ids) s
   WHERE NOT s.trusted
   GROUP BY s.contract_id, s.contract_number
   ORDER BY s.contract_number NULLS LAST;
$$;








--
-- Name: FUNCTION get_room_residence_conflicts_v1(p_contract_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_room_residence_conflicts_v1(p_contract_ids uuid[]) IS 'Đợt 2 Task 0: chỉ liệt kê hợp đồng có chuỗi cư trú KHÔNG tin được, kèm lý do. Dùng để rà tay; production 30/07/2026 phải trả 0 dòng (3/3 transfer đều đủ).';








--
-- Name: get_room_residence_segments_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_room_residence_segments_v1(p_contract_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(contract_id uuid, contract_number text, seg_index integer, room_id uuid, room_name text, from_date date, to_date date, source_path text, transfer_id uuid, trusted boolean, diagnostic text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH c AS (
    SELECT ct.id, ct.contract_number, ct.room_id AS cur_room,
           ct.start_date, ct.status::text AS c_status, ct.parent_contract_id
      FROM contracts ct
      LEFT JOIN rooms r ON r.id = ct.room_id
     WHERE ct.deleted_at IS NULL
       AND (p_contract_ids IS NULL OR ct.id = ANY(p_contract_ids))
       -- Cổng quyền: không có quyền trên toà ⇒ không thấy gì. Segments là tiện
       -- ích đọc, KHÔNG được thành kênh soi lịch sử toà mình không được xem.
       AND (r.building_id IS NULL
         OR public.can_access_building(r.building_id)
         OR public.ie_all_buildings_scope(r.building_id)
         OR public.is_admin() OR public.is_super_admin())
  ),
  -- Bước chuyển hợp lệ. CỐ Ý loại TENANT_CHANGE (đổi người, không đổi phòng),
  -- DRAFT (chưa duyệt) và CANCELLED (đã bỏ) — chúng KHÔNG cắt đoạn phòng.
  t AS (
    SELECT tr.contract_id,
           tr.id            AS transfer_id,
           tr.old_room_id,
           tr.new_room_id,
           COALESCE(tr.move_out_date, tr.transfer_date) AS eff_out,
           COALESCE(tr.move_in_date,  tr.transfer_date) AS eff_in,
           tr.transfer_date,
           CASE tr.status WHEN 'COMPLETED' THEN 'TRANSFER_ROOM_COMPLETED'
                          WHEN 'APPROVED'  THEN 'TRIGGER_APPROVED'
                          ELSE 'UNKNOWN' END AS source_path,
           row_number() OVER (PARTITION BY tr.contract_id
                              ORDER BY COALESCE(tr.move_in_date, tr.transfer_date),
                                       tr.transfer_date, tr.id) AS rn,
           count(*)    OVER (PARTITION BY tr.contract_id) AS n_tr
      FROM contract_transfers tr
      JOIN c ON c.id = tr.contract_id
     WHERE tr.transfer_type IN ('ROOM_CHANGE','BOTH_CHANGE')
       AND tr.status IN ('COMPLETED','APPROVED')
  ),
  -- Chẩn đoán ở mức HỢP ĐỒNG. Bất kỳ mâu thuẫn nào ⇒ cả chuỗi mất tin cậy.
  diag AS (
    SELECT c.id AS contract_id,
           CASE
             -- Có bằng chứng từng chuyển (dữ liệu lịch sử đường B) mà không có dòng nào
             WHEN (c.c_status = 'TRANSFERRED' OR c.parent_contract_id IS NOT NULL)
                  AND NOT EXISTS (SELECT 1 FROM t WHERE t.contract_id = c.id)
               THEN 'SEGMENT_HISTORY_INCOMPLETE: hợp đồng mang dấu vết đã chuyển (status/parent) nhưng không có dòng contract_transfers nào'
             -- Bước chuyển đầu tiên thiếu phòng cũ ⇒ không neo được đoạn đầu
             WHEN EXISTS (SELECT 1 FROM t WHERE t.contract_id=c.id AND t.rn=1 AND t.old_room_id IS NULL)
               THEN 'SEGMENT_HISTORY_INCOMPLETE: bước chuyển đầu tiên thiếu old_room_id'
             -- Thiếu mốc ngày
             WHEN EXISTS (SELECT 1 FROM t WHERE t.contract_id=c.id
                            AND (t.eff_in IS NULL OR t.eff_out IS NULL))
               THEN 'SEGMENT_HISTORY_INCOMPLETE: có bước chuyển thiếu mốc ngày (move_in/move_out/transfer_date đều rỗng)'
             -- Thiếu phòng mới
             WHEN EXISTS (SELECT 1 FROM t WHERE t.contract_id=c.id AND t.new_room_id IS NULL)
               THEN 'SEGMENT_HISTORY_INCOMPLETE: có bước chuyển thiếu new_room_id'
             -- ⚠ THỨ TỰ HAI PHÉP KIỂM DƯỚI ĐÂY LÀ CÓ CHỦ Ý — tôi từng để ngược và
             -- test bắt được: khi hai bước chuyển TRÙNG NGÀY hiệu lực thì
             -- row_number() xếp chúng theo `(eff_in, transfer_date, id)`, mà id là
             -- tuỳ ý ⇒ THỨ TỰ đã không đáng tin. Mọi kết luận của phép kiểm
             -- "chuỗi có nối" đều dựa trên thứ tự đó, nên nếu chạy trước nó sẽ báo
             -- "chuỗi không nối" — đúng là AMBIGUOUS nhưng SAI NGUYÊN NHÂN, khiến
             -- người rà tay đi tìm lỗi nối trong khi lỗi thật là trùng ngày.
             -- Chẩn đoán gốc phải nói trước.
             WHEN EXISTS (
               SELECT 1 FROM t a JOIN t b
                 ON b.contract_id=a.contract_id AND b.transfer_id <> a.transfer_id
                AND b.eff_in = a.eff_in
                WHERE a.contract_id=c.id)
               THEN 'SEGMENT_HISTORY_AMBIGUOUS: hai bước chuyển cùng ngày hiệu lực — không xác định được thứ tự'
             -- Chuỗi không nối: phòng cũ của bước n phải là phòng mới của bước n−1
             WHEN EXISTS (
               SELECT 1 FROM t a JOIN t b ON b.contract_id=a.contract_id AND b.rn=a.rn-1
                WHERE a.contract_id=c.id AND a.old_room_id IS DISTINCT FROM b.new_room_id)
               THEN 'SEGMENT_HISTORY_AMBIGUOUS: chuỗi chuyển phòng không nối (phòng cũ của bước sau khác phòng mới của bước trước)'
             -- Phòng hiện tại phải bằng phòng mới của bước cuối
             WHEN EXISTS (SELECT 1 FROM t WHERE t.contract_id=c.id)
                  AND c.cur_room IS DISTINCT FROM
                      (SELECT t2.new_room_id FROM t t2
                        WHERE t2.contract_id=c.id ORDER BY t2.rn DESC LIMIT 1)
               THEN 'SEGMENT_HISTORY_AMBIGUOUS: contracts.room_id không khớp phòng cuối chuỗi chuyển'
             ELSE NULL
           END AS diagnostic
      FROM c
  ),
  -- Đoạn ĐẦU = phòng cũ của bước chuyển thứ nhất; nếu không có transfer thì là
  -- phòng hiện tại.
  head AS (
    SELECT c.id AS contract_id, c.contract_number, 0 AS seg_index,
           COALESCE((SELECT t.old_room_id FROM t WHERE t.contract_id=c.id AND t.rn=1),
                    c.cur_room) AS room_id,
           -- Step 4: CHỈ tin start_date khi hợp đồng không có transfer và không
           -- mang dấu vết đã chuyển. Ngược lại trả NULL = "chưa biết", KHÔNG bịa.
           CASE WHEN NOT EXISTS (SELECT 1 FROM t WHERE t.contract_id=c.id)
                     AND c.c_status <> 'TRANSFERRED'
                     AND c.parent_contract_id IS NULL
                THEN c.start_date ELSE NULL END AS from_date,
           (SELECT t.eff_out FROM t WHERE t.contract_id=c.id AND t.rn=1) AS to_date,
           'CONTRACT_START'::text AS source_path,
           NULL::uuid AS transfer_id
      FROM c
  ),
  -- Mỗi bước chuyển mở một đoạn mới ở phòng mới.
  tail AS (
    SELECT t.contract_id, c.contract_number, t.rn::int AS seg_index,
           t.new_room_id AS room_id,
           t.eff_in AS from_date,
           (SELECT n.eff_out FROM t n
             WHERE n.contract_id=t.contract_id AND n.rn=t.rn+1) AS to_date,
           t.source_path, t.transfer_id
      FROM t JOIN c ON c.id = t.contract_id
  ),
  allseg AS (SELECT * FROM head UNION ALL SELECT * FROM tail)
  SELECT s.contract_id, s.contract_number, s.seg_index, s.room_id,
         r.name AS room_name, s.from_date, s.to_date, s.source_path, s.transfer_id,
         (d.diagnostic IS NULL) AS trusted,
         d.diagnostic
    FROM allseg s
    JOIN diag d ON d.contract_id = s.contract_id
    LEFT JOIN rooms r ON r.id = s.room_id
   ORDER BY s.contract_number NULLS LAST, s.contract_id, s.seg_index;
$$;








--
-- Name: FUNCTION get_room_residence_segments_v1(p_contract_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_room_residence_segments_v1(p_contract_ids uuid[]) IS 'Đợt 2 Task 0 Steps 3–4: dựng đoạn cư trú [from,to) theo phòng cho từng hợp đồng từ contract_transfers, phủ CẢ hai đường (status COMPLETED = RPC transfer_room, APPROVED = duyệt tay qua trigger). KHÔNG fallback im lặng: chỉ tin contracts.start_date khi hợp đồng không có transfer và không mang dấu vết đã chuyển (start_date đúng là cột trigger đường B từng ghi đè), ngược lại from_date NULL = chưa biết. Mọi mâu thuẫn chuỗi ⇒ trusted=false cho TOÀN BỘ đoạn của hợp đồng đó kèm diagnostic INCOMPLETE/AMBIGUOUS — không trả nửa tin nửa không. Lọc theo quyền toà. VOLATILE vì nhánh authz có thể lấy khoá dòng.';








--
-- Name: get_salary_progress_v5(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_salary_progress_v5(p_month date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_month DATE := date_trunc('month', COALESCE(p_month, public.vn_local_date(now())))::date;
  v_days JSONB;
BEGIN
  PERFORM public.v5_recompute_streak(v_uid, v_month);
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'date', d.d, 'is_workday', (EXTRACT(dow FROM d.d) <> 0
        AND NOT EXISTS (SELECT 1 FROM public.salary_holidays h
              WHERE h.user_id=(SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1)
                AND h.holiday_date=d.d)),
    'status', COALESCE(sad.status, 'pending'), 'source', sad.tick_source
  ) ORDER BY d.d), '[]'::jsonb) INTO v_days
  FROM generate_series(v_month, (v_month + INTERVAL '1 month')::date - 1, INTERVAL '1 day') d(d)
  LEFT JOIN public.salary_attendance_day sad ON sad.user_id = v_uid AND sad.work_date = d.d
  WHERE d.d <= public.vn_local_date(now());

  RETURN public.v5_month_money(v_uid, v_month) || jsonb_build_object('days', v_days);
END; $$;








--
-- Name: get_salary_v5_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_salary_v5_config() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner UUID;
  v_rules JSONB;
  v_pending JSONB;
  v_eff JSONB;
BEGIN
  SELECT user_id INTO v_owner FROM public.super_admins ORDER BY created_at LIMIT 1;
  SELECT rules INTO v_rules FROM public.salary_bonus_rules WHERE user_id = v_owner;
  IF v_rules IS NULL OR NOT (v_rules ? 'system_v5') THEN
    RETURN NULL; -- chưa seed v5
  END IF;

  v_eff := jsonb_build_object(
    'attendance_v5', v_rules->'attendance_v5',
    'streak_v5',     v_rules->'streak_v5',
    'coverage_v5',   v_rules->'coverage_v5',
    'system_v5',     v_rules->'system_v5'
  );

  -- áp pending key 💰 nếu đã tới tháng hiệu lực
  v_pending := v_rules->'system_v5'->'pending_money_patch';
  IF v_pending IS NOT NULL AND jsonb_typeof(v_pending) = 'object'
     AND (v_pending->>'effective_month')::date <= date_trunc('month', public.vn_local_date(now()))::date THEN
    v_eff := v_eff || COALESCE(v_pending->'patch', '{}'::jsonb);
  END IF;

  RETURN v_eff || jsonb_build_object(
    'version', v_rules->'system_v5'->'config_version',
    'as_of', public.vn_local_date(now())
  );
END;
$$;








--
-- Name: get_special_fee_prices_v1(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_special_fee_prices_v1(p_building_ids uuid[] DEFAULT NULL::uuid[], p_month text DEFAULT NULL::text) RETURNS TABLE(building_id uuid, building_name text, fee_category text, amount numeric, effective_from text, source text, can_edit boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_month date;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_month IS NULL THEN
    v_month := date_trunc('month', public.org_today_v1(NULL))::date;
  ELSE
    IF p_month !~ '^\d{4}-\d{2}$' THEN
      RAISE EXCEPTION 'Tháng phải dạng YYYY-MM' USING ERRCODE = '22023';
    END IF;
    v_month := to_date(p_month || '-01', 'YYYY-MM-DD');
  END IF;

  RETURN QUERY
  WITH k(kind) AS (
    VALUES ('tien_nha'),('dien'),('nuoc'),('internet'),('quan_ly'),
           ('ve_sinh'),('cong_an'),('rac'),('thang_may')
  ), b AS (
    SELECT bb.id, bb.name, bb.organization_id
      FROM public.buildings bb
     WHERE bb.deleted_at IS NULL
       AND (p_building_ids IS NULL OR bb.id = ANY(p_building_ids))
       AND (public.can_access_building(bb.id) OR public.ie_all_buildings_scope(bb.id)
         OR public.is_admin() OR public.is_super_admin())
  )
  SELECT b.id, b.name, k.kind,
         v.amount,
         to_char(v.effective_from_month, 'YYYY-MM'),
         v.source,
         (public.is_super_admin() OR app_private.is_org_owner_v1(b.organization_id, v_actor))
    FROM b CROSS JOIN k
    LEFT JOIN LATERAL (
      SELECT pv.amount, pv.effective_from_month, pv.source
        FROM app_private.special_fee_price_versions pv
       WHERE pv.organization_id = b.organization_id
         AND pv.building_id = b.id
         AND pv.fee_category = k.kind
         AND pv.status = 'PUBLISHED'
         AND pv.effective_from_month <= v_month
       ORDER BY pv.effective_from_month DESC
       LIMIT 1
    ) v ON true
   ORDER BY b.name, k.kind;
END;
$_$;








--
-- Name: FUNCTION get_special_fee_prices_v1(p_building_ids uuid[], p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_special_fee_prices_v1(p_building_ids uuid[], p_month text) IS 'Giá phí cố định đang có hiệu lực cho THÁNG chỉ định, đủ cả ô chưa khai (amount NULL). can_edit cho giao diện biết có hiện nút sửa hay không. VOLATILE vì chuỗi quyền chạm khoá dòng.';








--
-- Name: get_voucher_cancellation_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_voucher_cancellation_v1(p_voucher uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_out jsonb;
BEGIN
  SELECT ie.organization_id INTO v_org FROM public.income_expenses ie WHERE ie.id = p_voucher;
  IF v_org IS NULL THEN RETURN NULL; END IF;
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
     WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
  ) THEN RETURN NULL; END IF;

  SELECT jsonb_build_object(
    'cancelled_at', c.cancelled_at,
    'cancelled_by', c.cancelled_by,
    'cancelled_by_name', p.full_name,
    'cancel_reason', c.cancel_reason,
    'cancellation_kind', c.cancellation_kind,
    'created_at', c.created_at_snap,
    'approved_at', c.approved_at_snap,
    'amount', c.amount_snap
  ) INTO v_out
  FROM app_private.income_expense_cancellations c
  LEFT JOIN public.profiles p ON p.id = c.cancelled_by
  WHERE c.income_expense_id = p_voucher;

  RETURN v_out;
END
$$;








--
-- Name: get_voucher_change_log_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_voucher_change_log_v1(p_voucher uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE v_org uuid; v_out jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT ie.organization_id INTO v_org FROM public.income_expenses ie WHERE ie.id = p_voucher;
  IF v_org IS NULL THEN RETURN '[]'::jsonb; END IF;
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
     WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'at', l.changed_at, 'actor_id', l.actor_id, 'actor_name', p.full_name,
           'scope', l.scope, 'op', l.op, 'cols', l.changed_cols,
           'before', l.before, 'after', l.after
         ) ORDER BY l.changed_at DESC, l.id DESC), '[]'::jsonb)
    INTO v_out
  FROM app_private.income_expense_change_log l
  LEFT JOIN public.profiles p ON p.id = l.actor_id
  WHERE l.income_expense_id = p_voucher;

  RETURN v_out;
END
$$;








--
-- Name: get_voucher_slot_warning_v1(uuid, uuid[], date, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_voucher_slot_warning_v1(p_building_id uuid, p_type_ids uuid[], p_start date, p_end date, p_type text DEFAULT 'EXPENSE'::text, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS TABLE(voucher_id uuid, code text, voucher_name text, total_amount numeric, matched_amount numeric, voucher_date date, approval_status text, created_at timestamp with time zone, creator_name text, type_names text, same_amount boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH guard AS (
    -- Không có quyền trên toà ⇒ không trả gì. Cảnh báo là tiện ích, KHÔNG được
    -- thành kênh soi phiếu của toà mình không được xem.
    SELECT 1
      FROM buildings b
     WHERE b.id = p_building_id
       AND b.deleted_at IS NULL
       AND (public.can_access_building(b.id)
         OR public.ie_all_buildings_scope(b.id)
         OR b.user_id = auth.uid()
         OR public.is_admin() OR public.is_super_admin())
  ),
  hit AS (
    SELECT ie.id,
           ie.code,
           ie.name,
           ie.total_amount,
           SUM(it.amount)                          AS matched_amount,
           ie.voucher_date,
           ie.approval_status,
           ie.created_at,
           ie.user_id,
           string_agg(DISTINCT t.name, ', ' )      AS type_names
      FROM income_expense_items it
      JOIN income_expense_types t ON t.id = it.income_expense_type_id
      JOIN income_expenses ie ON ie.id = it.income_expense_id
     WHERE EXISTS (SELECT 1 FROM guard)
       AND ie.building_id = p_building_id
       AND ie.type = p_type
       AND ie.deleted_at IS NULL
       AND ie.approval_status <> 'CANCELLED'
       AND (p_exclude_id IS NULL OR ie.id <> p_exclude_id)
       AND it.income_expense_type_id = ANY(p_type_ids)
       -- Kỳ chồng lấn, chịu được item có start_date không phải ngày 1.
       AND it.start_date IS NOT NULL AND it.end_date IS NOT NULL
       AND it.start_date <= p_end AND it.end_date >= p_start
     GROUP BY ie.id, ie.code, ie.name, ie.total_amount, ie.voucher_date,
              ie.approval_status, ie.created_at, ie.user_id
  )
  SELECT h.id, h.code, h.name, h.total_amount, h.matched_amount, h.voucher_date,
         h.approval_status, h.created_at,
         COALESCE(NULLIF(btrim(p.full_name), ''), p.email, '(không rõ)'),
         h.type_names,
         false                                     -- FE tự so với số đang gõ
    FROM hit h
    LEFT JOIN profiles p ON p.id = h.user_id
   ORDER BY h.created_at DESC;
$$;








--
-- Name: FUNCTION get_voucher_slot_warning_v1(p_building_id uuid, p_type_ids uuid[], p_start date, p_end date, p_type text, p_exclude_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_voucher_slot_warning_v1(p_building_id uuid, p_type_ids uuid[], p_start date, p_end date, p_type text, p_exclude_id uuid) IS 'Trả phiếu ĐÃ CÓ cùng (toà, loại phiếu, kỳ chồng lấn) để form tạo phiếu cảnh báo TRƯỚC khi người thứ hai tạo trùng. Đếm cả UNAPPROVED (phiếu chờ duyệt là phiếu người khác không thấy — chính là nguyên nhân tạo lại); loại phiếu đã huỷ. CHỈ CẢNH BÁO, không chặn: 20/24 ô trùng trên production có số tiền khác nhau và đều hợp lệ, chặn cứng là chặn oan 20/24. Lọc theo quyền toà nên không thành kênh soi phiếu toà khác. VOLATILE vì nhánh authz có thể lấy khoá dòng.';








--
-- Name: guard_contract_deposit_paid_derived(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_contract_deposit_paid_derived() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.deposit_paid IS DISTINCT FROM OLD.deposit_paid
     AND current_user IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION
      'Không sửa tay được "Cọc đã thu" (% đ → % đ). Số này được TÍNH từ phiếu thu/chi cọc của hợp đồng. Muốn đổi thì thêm/sửa/huỷ phiếu cọc (hạng mục có cờ "là cọc"), hệ thống sẽ tự tính lại.',
      round(COALESCE(OLD.deposit_paid, 0))::bigint,
      round(COALESCE(NEW.deposit_paid, 0))::bigint
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: guard_contract_termination_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_contract_termination_settlement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_frozen text := NULL;
BEGIN
  -- Chỉ soi đường REST của trình duyệt. Writer SECURITY DEFINER chạy dưới
  -- postgres, edge function chạy dưới service_role — cả hai đi thẳng.
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  -- ── INSERT: không cho khai sinh một hồ sơ ĐÃ quyết toán từ trình duyệt.
  -- UNIQUE(contract_id) chỉ chặn được hợp đồng ĐÃ có hồ sơ; hợp đồng chưa có
  -- thì client tự INSERT một dòng status='COMPLETED' với total_deposit tuỳ ý
  -- là xong — không writer nào, không bút toán nào.
  IF TG_OP = 'INSERT' THEN
    -- Qua hàm SECURITY DEFINER ở 3.1bis — KHÔNG SELECT thẳng app_private, xem
    -- lý do ở đó (authenticated không có USAGE ⇒ 42501 ngay lúc khởi động câu).
    IF public.has_contract_termination_write_v1(NEW.id) THEN
      RETURN NEW;
    END IF;

    IF COALESCE(NEW.status, '') IN ('APPROVED', 'COMPLETED') THEN
      RAISE EXCEPTION
        '[TERMINATION_APPROVE_VIA_RPC] Không tạo hồ sơ thanh lý ở trạng thái % từ giao diện. Hồ sơ phải do RPC thanh lý sinh ra (trả phòng / bỏ cọc), hoặc tạo ở trạng thái DRAFT rồi duyệt bằng approve_contract_termination_v1.',
        NEW.status
        USING ERRCODE = '42501';
    END IF;
    IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION
        '[TERMINATION_APPROVE_VIA_RPC] approved_by / approved_at do RPC duyệt đóng dấu — không ghi tay từ giao diện.'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  -- ── UPDATE ─────────────────────────────────────────────────────────
  -- Cửa writer (3.1) — hôm nay chưa writer nào dùng, xem ghi chú ở 3.1.
  -- Đọc qua hàm SECURITY DEFINER ở 3.1bis (lý do: 42501 schema app_private).
  IF public.has_contract_termination_write_v1(OLD.id) THEN
    RETURN NEW;
  END IF;

  -- (1) Hồ sơ ĐÃ quyết toán ⇒ đông cứng đầu vào tiền + mốc nhận diện.
  -- refund_amount và total_deductions là cột SINH TỰ ĐỘNG (stored generated)
  -- từ đúng các cột dưới đây, nên sửa một cột là đổi số tiền phải hoàn mà
  -- không sinh phiếu nào, không để lại vết nào.
  IF COALESCE(OLD.status, '') IN ('APPROVED', 'COMPLETED') THEN
    IF    NEW.total_deposit         IS DISTINCT FROM OLD.total_deposit         THEN v_frozen := 'total_deposit';
    ELSIF NEW.outstanding_debt      IS DISTINCT FROM OLD.outstanding_debt      THEN v_frozen := 'outstanding_debt';
    ELSIF NEW.early_termination_fee IS DISTINCT FROM OLD.early_termination_fee THEN v_frozen := 'early_termination_fee';
    ELSIF NEW.notice_violation_fee  IS DISTINCT FROM OLD.notice_violation_fee  THEN v_frozen := 'notice_violation_fee';
    ELSIF NEW.damage_fee            IS DISTINCT FROM OLD.damage_fee            THEN v_frozen := 'damage_fee';
    ELSIF NEW.cleaning_fee          IS DISTINCT FROM OLD.cleaning_fee          THEN v_frozen := 'cleaning_fee';
    ELSIF NEW.other_fees            IS DISTINCT FROM OLD.other_fees            THEN v_frozen := 'other_fees';
    ELSIF NEW.prorated_rent         IS DISTINCT FROM OLD.prorated_rent         THEN v_frozen := 'prorated_rent';
    ELSIF NEW.prorated_services     IS DISTINCT FROM OLD.prorated_services     THEN v_frozen := 'prorated_services';
    ELSIF NEW.prorated_days         IS DISTINCT FROM OLD.prorated_days         THEN v_frozen := 'prorated_days';
    ELSIF NEW.contract_id           IS DISTINCT FROM OLD.contract_id           THEN v_frozen := 'contract_id';
    ELSIF NEW.termination_type      IS DISTINCT FROM OLD.termination_type      THEN v_frozen := 'termination_type';
    ELSIF NEW.actual_move_out_date  IS DISTINCT FROM OLD.actual_move_out_date  THEN v_frozen := 'actual_move_out_date';
    ELSIF NEW.termination_date      IS DISTINCT FROM OLD.termination_date      THEN v_frozen := 'termination_date';
    ELSIF NEW.refund_date           IS DISTINCT FROM OLD.refund_date           THEN v_frozen := 'refund_date';
    END IF;

    IF v_frozen IS NOT NULL THEN
      RAISE EXCEPTION
        '[TERMINATION_SETTLED] Hồ sơ thanh lý đã ở trạng thái % — không sửa được cột "%" từ giao diện. Số tiền phải hoàn (refund_amount) do các cột này SINH RA, sửa một cột là đổi tiền mà không sinh phiếu nào. Sai sót phát hiện sau quyết toán phải xử lý bằng phiếu điều chỉnh.',
        OLD.status, v_frozen
        USING ERRCODE = '55000';
    END IF;

    -- Không cho hạ trạng thái để "mở băng" rồi sửa vòng hai.
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      RAISE EXCEPTION
        '[TERMINATION_SETTLED] Hồ sơ thanh lý đã ở trạng thái % — không đổi trạng thái từ giao diện. Mọi thay đổi phải đi qua RPC thanh lý.',
        OLD.status
        USING ERRCODE = '55000';
    END IF;
  END IF;

  -- (2) Không nhảy thẳng sang APPROVED/COMPLETED từ trình duyệt.
  -- Đặt status='APPROVED' kích trigger update_contract_on_termination_approved
  -- ⇒ hợp đồng thành TERMINATED, phòng đổi trạng thái, mà KHÔNG một bút toán
  -- tiền nào được ghi. Đây đúng là việc mà fallback client đã chết
  -- (useApproveTermination → INSERT public.cash_book, bảng KHÔNG tồn tại) làm.
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('APPROVED', 'COMPLETED') THEN
    RAISE EXCEPTION
      '[TERMINATION_APPROVE_VIA_RPC] Duyệt/hoàn tất thanh lý phải gọi approve_contract_termination_v1. Đặt status = % trực tiếp sẽ khiến hợp đồng thành TERMINATED mà không sinh bút toán tiền nào.',
      NEW.status
      USING ERRCODE = '42501';
  END IF;

  -- (3) Dấu duyệt do server đóng, không nhận từ client (mọi trạng thái).
  IF NEW.approved_by IS DISTINCT FROM OLD.approved_by
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION
      '[TERMINATION_APPROVE_VIA_RPC] approved_by / approved_at do RPC duyệt đóng dấu — không ghi tay từ giao diện.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END
$$;








--
-- Name: FUNCTION guard_contract_termination_settlement(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_contract_termination_settlement() IS 'Slice −1 B4: chặn REST sửa đầu vào quyết toán của hồ sơ thanh lý đã APPROVED/COMPLETED, chặn nhảy status sang APPROVED/COMPLETED và chặn khai sinh hồ sơ đã quyết toán ngoài RPC. SECURITY INVOKER bắt buộc (guard kiểm current_user).';








--
-- Name: guard_invoice_derived_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invoice_derived_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF NEW.paid_amount IS DISTINCT FROM OLD.paid_amount THEN
    RAISE EXCEPTION
      'invoices.paid_amount là cột dẫn xuất — chỉ recompute_invoice_for_id được ghi. Ghi tay sẽ làm hoá đơn lệch với sổ thu tiền.'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;








--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_full_name TEXT;
  v_phone     TEXT;
  v_email     TEXT;
BEGIN
  v_full_name := COALESCE(
    NULLIF(NEW.raw_user_meta_data->>'full_name', ''),
    NULLIF(NEW.raw_user_meta_data->>'username',  ''),
    NULLIF(split_part(NEW.email, '@', 1), ''),
    'User'
  );

  v_phone := NULLIF(NEW.raw_user_meta_data->>'phone', '');
  IF v_phone IS NOT NULL AND v_phone !~ '^[0-9]{10,11}$' THEN
    v_phone := NULL;
  END IF;

  v_email := NULLIF(NEW.raw_user_meta_data->>'email', '');
  IF v_email IS NULL
     AND NEW.email IS NOT NULL
     AND NEW.email NOT LIKE '%@%.ihomecrm.local'
  THEN
    v_email := NEW.email;
  END IF;

  INSERT INTO public.profiles (
    id, full_name, phone, email,
    department, job_title, employee_code, is_active
  )
  VALUES (
    NEW.id,
    v_full_name,
    v_phone,
    v_email,
    NULLIF(NEW.raw_user_meta_data->>'department',    ''),
    NULLIF(NEW.raw_user_meta_data->>'job_title',     ''),
    NULLIF(NEW.raw_user_meta_data->>'employee_code', ''),
    COALESCE((NEW.raw_user_meta_data->>'is_active')::boolean, TRUE)
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$_$;








--
-- Name: has_contract_termination_write_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_contract_termination_write_v1(p_termination uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM app_private.contract_termination_writer_xids w
     WHERE w.transaction_id = pg_current_xact_id()
       AND w.backend_pid    = pg_backend_pid()
       AND w.termination_id = p_termination
  );
$$;








--
-- Name: FUNCTION has_contract_termination_write_v1(p_termination uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_contract_termination_write_v1(p_termination uuid) IS 'Cửa writer hồ sơ thanh lý CÓ MỞ trong transaction+backend hiện tại cho đúng hồ sơ này? SECURITY DEFINER vì guard gọi nó là SECURITY INVOKER và role authenticated KHÔNG có USAGE trên schema app_private (đọc thẳng bảng ⇒ 42501 permission denied for schema app_private, chết mọi INSERT/UPDATE REST trước khi tới được mã lỗi tiếng Việt). VOLATILE: đọc trạng thái transaction (pg_current_xact_id) và tránh án lệ 20260730280000 về hàm STABLE chạm khoá dòng.';








