--
-- Name: ie_annotate_scope_delta_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_annotate_scope_delta_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
BEGIN
  -- Chỉ soi khi CHÍNH transaction này đã mở năng lực ANNOTATE cho phiếu này.
  IF NOT EXISTS (
    SELECT 1 FROM app_private.ie_flex_writer_xids w
     WHERE w.income_expense_id = OLD.id
       AND w.transaction_id = pg_current_xact_id()
       AND w.backend_pid = pg_backend_pid()
       AND w.scope = 'ANNOTATE'
  ) THEN
    RETURN NEW;
  END IF;

  IF (to_jsonb(OLD) - ARRAY['attachments','notes','updated_at'])
     IS DISTINCT FROM
     (to_jsonb(NEW) - ARRAY['attachments','notes','updated_at']) THEN
    RAISE EXCEPTION
      'Năng lực ANNOTATE chỉ được đổi ảnh chứng từ và ghi chú của phiếu % — phát hiện đổi cột khác.',
      OLD.id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;








--
-- Name: ie_compat_cancel_v2(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_compat_cancel_v2(p_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_id uuid;
  v_row public.income_expenses%ROWTYPE;
  v_actor record;
  v_done integer := 0;
BEGIN
  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT * INTO v_row FROM public.income_expenses WHERE id = v_id AND deleted_at IS NULL FOR UPDATE;
    CONTINUE WHEN NOT FOUND;
    SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_row.organization_id);
    IF v_actor.membership_id IS NULL THEN
      RAISE EXCEPTION 'Không có membership active trong organization phiếu' USING ERRCODE='42501';
    END IF;
    IF COALESCE(v_row.posting_status,'UNPOSTED') = 'POSTED' THEN
      RAISE EXCEPTION 'Phiếu % đã ghi sổ — dùng reversal, không hủy trực tiếp', v_id USING ERRCODE='55000';
    END IF;
    IF app_private.ie_flow_system_owned_v2(v_id) THEN
      RAISE EXCEPTION 'Phiếu % thuộc writer hệ thống', v_id USING ERRCODE='42501';
    END IF;

    -- Cổng quyền: người TẠO phiếu, hoặc người GIỮ SỔ (kèm quyền huỷ), hoặc
    -- chủ tổ chức / super admin. Trước đây hàm này chỉ kiểm membership nên
    -- bất kỳ ai cũng huỷ hàng loạt phiếu chưa ghi sổ của người khác.
    IF NOT public.is_super_admin()
       AND NOT app_private.is_org_owner_v1(v_row.organization_id, auth.uid())
       AND v_row.user_id IS DISTINCT FROM auth.uid() THEN
      DECLARE v_ok boolean;
      BEGIN
        SELECT allowed INTO v_ok FROM app_private.authorize_tenant_action_v3(
          auth.uid(), v_row.organization_id, 'income_expenses.cancel',
          v_row.building_id, v_row.account_id);
        IF NOT COALESCE(v_ok, false) THEN
          RAISE EXCEPTION 'Không có quyền huỷ phiếu % ', v_id USING ERRCODE='42501';
        END IF;
        IF v_row.account_id IS NOT NULL THEN
          PERFORM app_private.assert_cashbook_access_v2(
            v_row.organization_id, v_row.account_id, 'CUSTODIAN', v_actor.membership_id);
        END IF;
      END;
    END IF;
    -- WP2_COMPAT_RESTRICTED_GATE: huỷ một thứ mình không được phép ĐỌC là lỗ.
    -- Người có income_expenses.cancel trên toà nhưng không có
    -- can_view_restricted_ie vẫn huỷ được phiếu lương của người khác.
    -- Người TẠO phiếu thì luôn huỷ được phiếu của chính mình.
    IF COALESCE(v_row.has_restricted_item, false)
       AND v_row.user_id IS DISTINCT FROM auth.uid()
       AND NOT public.can_view_restricted_ie()
       AND NOT public.is_super_admin() THEN
      RAISE EXCEPTION 'Phiếu % chứa hạng mục hạn chế — không có quyền huỷ', v_id
        USING ERRCODE = '42501';
    END IF;

    -- Token per-xid: guard freeze đòi trước khi cho transition (7u).
    INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
    VALUES (v_id, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
    ON CONFLICT (income_expense_id) DO UPDATE
      SET xid = EXCLUDED.xid, purpose = EXCLUDED.purpose, granted_at = now();
    UPDATE public.income_expenses SET
      approval_status='CANCELLED', review_state='RESOLVED',
      cancellation_kind=COALESCE(cancellation_kind,'COMPAT_BATCH_CANCEL'),
      notes = CASE WHEN p_reason IS NULL THEN notes ELSE COALESCE(notes,'') || E'\n[Hủy] ' || p_reason END
    WHERE id = v_id;
    INSERT INTO app_private.income_expense_cancellations
      (income_expense_id, organization_id, cancelled_by, cancel_reason,
       cancellation_kind, created_at_snap, approved_at_snap, amount_snap, cashbook_snap)
    VALUES (v_id, v_row.organization_id, auth.uid(),
            COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), '(huỷ cả đợt, không ghi lý do)'),
            'COMPAT_BATCH_CANCEL', v_row.created_at, v_row.approved_at,
            v_row.total_amount, v_row.account_id)
    ON CONFLICT (income_expense_id) DO NOTHING;

    v_done := v_done + 1;
  END LOOP;
  RETURN jsonb_build_object('cancelled', v_done);
END
$$;








--
-- Name: ie_compat_insert_v2(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_compat_insert_v2(p_row jsonb, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_colrec record;
  v_defj jsonb;
  v_actor record;
  v_id uuid;
  v_clean jsonb;
  v_item jsonb;
BEGIN
  v_org := COALESCE(
    (SELECT a.organization_id FROM public.accounts a WHERE a.id = (p_row->>'account_id')::uuid),
    (SELECT b.organization_id FROM public.buildings b WHERE b.id = (p_row->>'building_id')::uuid),
    (p_row->>'organization_id')::uuid);
  IF v_org IS NULL THEN
    SELECT m.organization_id INTO v_org FROM public.organization_memberships m
    WHERE m.user_id = auth.uid() AND m.status='ACTIVE' LIMIT 1;
  END IF;
  SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_org);
  IF v_actor.membership_id IS NULL THEN
    RAISE EXCEPTION 'Không có membership active trong organization phiếu' USING ERRCODE='42501';
  END IF;

  -- §9.2 possession: có chọn sổ thì phải giữ/biết sổ đó (KNOWER chỉ Phiếu thu).
  IF (p_row->>'account_id') IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.cashbook_possession_bindings b
      WHERE b.organization_id = v_org
        AND b.cashbook_id = (p_row->>'account_id')::uuid
        AND b.membership_id = v_actor.membership_id
        AND b.valid_to IS NULL
        AND (b.possession_kind = 'CUSTODIAN'
             OR (b.possession_kind = 'KNOWER' AND COALESCE(p_row->>'type','') = 'INCOME'))
    ) THEN
      RAISE EXCEPTION 'Bạn không phải Người giữ sổ của sổ này (Người biết sổ chỉ tạo Phiếu thu). Chọn sổ khác hoặc để trống sổ.'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Blacklist: client không được set trạng thái duyệt/posting/actor server-owned (§9.3).
  v_clean := (p_row - 'approval_status' - 'approved_by' - 'approved_at' - 'posting_id'
              - 'posted_at_v2' - 'posting_mode' - 'posting_status' - 'active_posting_id_v2'
              - 'reversed_by_posting_id' - 'deleted_at' - 'maker_user_id' - 'maker_membership_id'
              - 'birth_operation_id' - 'birth_txid' - 'review_state' - 'organization_id' - 'user_id')
             || jsonb_build_object(
                  'organization_id', v_org,
                  'user_id', COALESCE((p_row->>'user_id')::uuid, auth.uid()),
                  -- ĐỢT B: phiếu THU tự duyệt ngay khi tạo (quyết định #5 của
                  -- chủ 01/08/2026), kéo theo cầu a85b tự ghi sổ trong cùng
                  -- transaction. Phiếu CHI giữ nguyên hàng chờ duyệt.
                  -- ĐỢT B (siết sau audit): phiếu ĐỊNH KỲ vẫn phải chờ duyệt.
                  -- Phiếu định kỳ là lớp DUY NHẤT buộc đi đường compat, và
                  -- generate_recurring_vouchers (cron 18:00 hằng ngày) lấy
                  -- phiếu mẹ theo approval_status='APPROVED' rồi sinh phiếu con
                  -- APPROVED + auto-post cho MỌI kỳ đã trôi qua. Cho phiếu mẹ
                  -- ra APPROVED ngay = mở vòi in tiền qua đêm cho các kỳ quá
                  -- khứ. Người lập phải xác nhận trước khi bật vòi.
                  'approval_status',
                    CASE WHEN COALESCE(p_row->>'type','') = 'INCOME'
                          AND COALESCE(p_row->>'repeat_cycle','NONE') = 'NONE'
                         THEN 'APPROVED' ELSE 'UNAPPROVED' END,
                  'review_state',
                    CASE WHEN COALESCE(p_row->>'type','') = 'INCOME'
                          AND COALESCE(p_row->>'repeat_cycle','NONE') = 'NONE'
                         THEN 'RESOLVED' ELSE 'PENDING' END,
                  'approved_by',
                    CASE WHEN COALESCE(p_row->>'type','') = 'INCOME'
                          AND COALESCE(p_row->>'repeat_cycle','NONE') = 'NONE'
                         THEN to_jsonb(auth.uid()) ELSE 'null'::jsonb END,
                  'approved_at',
                    CASE WHEN COALESCE(p_row->>'type','') = 'INCOME'
                          AND COALESCE(p_row->>'repeat_cycle','NONE') = 'NONE'
                         THEN to_jsonb(now()) ELSE 'null'::jsonb END,
                  'posting_mode', 'CASHBOOK',
                  'posting_status', 'UNPOSTED',
                  'maker_user_id', auth.uid(),
                  'maker_membership_id', v_actor.membership_id);
  IF p_row ? 'id' THEN v_clean := v_clean || jsonb_build_object('id', (p_row->>'id')::uuid); END IF;

  -- compat_total_fix: populate_record sinh NULL tường minh → default 0 không áp.
  IF (v_clean->>'total_amount') IS NULL THEN
    v_clean := v_clean || jsonb_build_object('total_amount', COALESCE((
      SELECT SUM(COALESCE((i->>'amount')::numeric,
                          COALESCE((i->>'quantity')::numeric,1)
                          * COALESCE((i->>'unit_price')::numeric,0)))
      FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) i), 0));
  END IF;
  -- compat_defaults_fix: bù MỌI cột NOT NULL có default còn thiếu (generic).
  FOR v_colrec IN
    SELECT c.column_name, c.column_default
    FROM information_schema.columns c
    WHERE c.table_schema='public' AND c.table_name='income_expenses'
      AND c.is_nullable='NO' AND c.column_default IS NOT NULL
  LOOP
    IF (v_clean->>v_colrec.column_name) IS NULL THEN
      EXECUTE format('SELECT to_jsonb(%s)', v_colrec.column_default) INTO v_defj;
      v_clean := v_clean || jsonb_build_object(v_colrec.column_name, v_defj);
    END IF;
  END LOOP;
  INSERT INTO public.income_expenses
  SELECT * FROM jsonb_populate_record(NULL::public.income_expenses, v_clean)
  RETURNING id INTO v_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) LOOP
    -- compat_item_defaults_fix: populate_record đè default → bù cột thiếu.
    v_item := (v_item - 'income_expense_id')
              || jsonb_build_object('income_expense_id', v_id);
    FOR v_colrec IN
      SELECT c.column_name, c.column_default
      FROM information_schema.columns c
      WHERE c.table_schema='public' AND c.table_name='income_expense_items'
        AND c.is_nullable='NO' AND c.column_default IS NOT NULL
    LOOP
      IF (v_item->>v_colrec.column_name) IS NULL THEN
        EXECUTE format('SELECT to_jsonb(%s)', v_colrec.column_default) INTO v_defj;
        v_item := v_item || jsonb_build_object(v_colrec.column_name, v_defj);
      END IF;
    END LOOP;
    INSERT INTO public.income_expense_items
    SELECT * FROM jsonb_populate_record(NULL::public.income_expense_items, v_item);
  END LOOP;

  INSERT INTO app_private.finance_v2_semantic_event_log (organization_id, event_kind, source_table, source_id, source_kind, actor, txid)
  VALUES (v_org, 'COMPAT_INSERT', 'income_expenses', v_id, 'V2_WRITE', auth.uid(), pg_current_xact_id());
  RETURN jsonb_build_object('id', v_id, 'approval_status',
    (SELECT approval_status FROM public.income_expenses WHERE id = v_id));
END
$$;








--
-- Name: ie_compat_update_pending_v2(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_compat_update_pending_v2(p_id uuid, p_patch jsonb, p_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_row public.income_expenses%ROWTYPE;
  v_actor record;
  v_money_keys text[] := ARRAY['account_id','change_account_id','rounding_account_id',
    'payer_name','receive_bank_name','receive_bank_account',
    'repeat_cycle','repeat_count','repeat_infinity','repeat_auto_approve',
    'total_amount','change_amount','rounding_amount','type','voucher_date','building_id',
    'shareholder_id','contract_id','invoice_id','room_id','tenant_id','business_result_accounting'];
  v_meta_keys text[] := ARRAY['name','notes','attachments'];
  -- Cột item client được phép đặt. CỐ Ý bỏ: id, organization_id, amount
  -- (cột dẫn xuất), created_at và ĐẶC BIỆT là accounting_class — trigger
  -- set_ie_item_accounting_class chỉ suy ra khi giá trị NULL, nên client
  -- gửi 'PNL' cho một hạng mục CỌC là đủ để rút contracts.deposit_paid
  -- và thổi KQKD. FE (accountingClass.ts) vốn tính đúng công thức
  -- `is_deposit ? DEPOSIT : PNL` của trigger, nên bỏ đi là BẤT BIẾN
  -- hành vi cho người gọi hợp lệ.
  v_item_keys text[] := ARRAY['income_expense_type_id','description',
    'quantity','unit_price','start_date','end_date'];
  v_key text;
  v_touch_money boolean := false;
  v_clean jsonb := '{}'::jsonb;
  v_item jsonb;
  v_item_clean jsonb;
  v_can_replace_attachments boolean;
  v_new_account uuid;
BEGIN
  SELECT * INTO v_row FROM public.income_expenses WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_row.organization_id);
  IF v_actor.membership_id IS NULL THEN
    RAISE EXCEPTION 'Không có membership active trong organization phiếu' USING ERRCODE='42501';
  END IF;
  IF v_row.approval_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Phiếu đã hủy — không sửa' USING ERRCODE='55000';
  END IF;

  -- Hạng mục hạn chế: RPC là SECURITY DEFINER nên KHÔNG được hưởng
  -- policy RESTRICTIVE income_expenses_restricted_* — phải tự kiểm.
  IF COALESCE(v_row.has_restricted_item, false)
     AND v_row.user_id IS DISTINCT FROM auth.uid()
     AND NOT public.can_view_restricted_ie()
     AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Phiếu chứa hạng mục hạn chế — không có quyền sửa' USING ERRCODE='42501';
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_patch) LOOP
    IF v_key = ANY (v_money_keys) THEN
      v_touch_money := true;
      v_clean := v_clean || jsonb_build_object(v_key, p_patch->v_key);
    ELSIF v_key = ANY (v_meta_keys) THEN
      v_clean := v_clean || jsonb_build_object(v_key, p_patch->v_key);
    END IF;
  END LOOP;

  IF (v_touch_money OR p_items IS NOT NULL) THEN
    IF v_row.approval_status <> 'UNAPPROVED' OR COALESCE(v_row.posting_status,'UNPOSTED') = 'POSTED' THEN
      RAISE EXCEPTION 'Trục tiền chỉ sửa được khi phiếu Chờ duyệt (V2 §12.8); phiếu đã duyệt/ghi sổ dùng reversal'
        USING ERRCODE='55000';
    END IF;
    IF app_private.ie_flow_system_owned_v2(p_id) THEN
      RAISE EXCEPTION 'Phiếu thuộc writer hệ thống — sửa qua luồng nguồn' USING ERRCODE='42501';
    END IF;

    -- SIẾT MỚI: trục tiền đòi quyền sửa thật trên TOÀ, không phải chỉ
    -- "có chân trong tổ chức".
    IF NOT app_private.ie_can_edit_money_axis_v1(v_row.organization_id, v_row.building_id) THEN
      RAISE EXCEPTION 'Không có quyền sửa trục tiền của phiếu trên toà nhà này' USING ERRCODE='42501';
    END IF;

    -- SIẾT MỚI: đổi sổ quỹ đòi GIỮ SỔ cả bên đi lẫn bên đến.
    IF v_clean ? 'account_id' THEN
      v_new_account := NULLIF(v_clean->>'account_id','')::uuid;
      IF v_new_account IS DISTINCT FROM v_row.account_id THEN
        IF v_row.account_id IS NOT NULL THEN
          PERFORM app_private.assert_cashbook_access_v2(
            v_row.organization_id, v_row.account_id, 'CUSTODIAN', v_actor.membership_id);
        END IF;
        IF v_new_account IS NOT NULL THEN
          PERFORM app_private.assert_cashbook_access_v2(
            v_row.organization_id, v_new_account, 'CUSTODIAN', v_actor.membership_id);
        END IF;
      END IF;
    END IF;
  ELSE
    -- Nhánh CHỈ-METADATA: giữ nguyên tập người gọi cũ (người tạo phiếu
    -- vẫn dán được ảnh chứng từ) nhưng không còn là cửa hậu sửa tiền,
    -- vì `notes` bị canh dấu và `attachments` chỉ nối thêm.
    IF NOT (
         v_row.user_id = auth.uid()
      OR app_private.ie_can_edit_money_axis_v1(v_row.organization_id, v_row.building_id)
      OR app_private.ie_has_cashbook_possession_v1(
           v_row.organization_id, v_row.account_id, v_actor.membership_id)
    ) THEN
      RAISE EXCEPTION 'Không có quyền sửa thông tin phiếu này' USING ERRCODE='42501';
    END IF;
  END IF;

  -- SIẾT MỚI: cấm thêm/gỡ dấu hiệu tiền trong ghi chú, ở MỌI trạng thái.
  IF v_clean ? 'notes' THEN
    PERFORM app_private.assert_notes_markers_unchanged_v1(v_row.notes, v_clean->>'notes');
  END IF;

  -- Ảnh: phiếu Chờ duyệt & chưa ghi sổ thì thay cả mảng (gỡ ảnh dán
  -- nhầm trên nháp). Phiếu đã duyệt/ghi sổ thì CHỈ NỐI THÊM — bằng
  -- chứng đã hạch toán không được biến mất trong im lặng.
  v_can_replace_attachments := (
    v_row.approval_status = 'UNAPPROVED'
    AND COALESCE(v_row.posting_status,'UNPOSTED') <> 'POSTED'
  );

  IF v_clean <> '{}'::jsonb THEN
    UPDATE public.income_expenses ie SET
      account_id          = CASE WHEN v_clean ? 'account_id' THEN NULLIF(v_clean->>'account_id','')::uuid ELSE ie.account_id END,
      change_account_id   = CASE WHEN v_clean ? 'change_account_id' THEN NULLIF(v_clean->>'change_account_id','')::uuid ELSE ie.change_account_id END,
      rounding_account_id = CASE WHEN v_clean ? 'rounding_account_id' THEN NULLIF(v_clean->>'rounding_account_id','')::uuid ELSE ie.rounding_account_id END,
      total_amount        = CASE WHEN v_clean ? 'total_amount' THEN NULLIF(v_clean->>'total_amount','')::numeric ELSE ie.total_amount END,
      change_amount       = CASE WHEN v_clean ? 'change_amount' THEN NULLIF(v_clean->>'change_amount','')::numeric ELSE ie.change_amount END,
      rounding_amount     = CASE WHEN v_clean ? 'rounding_amount' THEN NULLIF(v_clean->>'rounding_amount','')::numeric ELSE ie.rounding_amount END,
      type                = CASE WHEN v_clean ? 'type' THEN COALESCE(NULLIF(v_clean->>'type',''), ie.type) ELSE ie.type END,
      voucher_date        = CASE WHEN v_clean ? 'voucher_date' THEN COALESCE(NULLIF(v_clean->>'voucher_date','')::date, ie.voucher_date) ELSE ie.voucher_date END,
      building_id         = CASE WHEN v_clean ? 'building_id' THEN NULLIF(v_clean->>'building_id','')::uuid ELSE ie.building_id END,
      shareholder_id      = CASE WHEN v_clean ? 'shareholder_id' THEN NULLIF(v_clean->>'shareholder_id','')::uuid ELSE ie.shareholder_id END,
      contract_id         = CASE WHEN v_clean ? 'contract_id' THEN NULLIF(v_clean->>'contract_id','')::uuid ELSE ie.contract_id END,
      invoice_id          = CASE WHEN v_clean ? 'invoice_id' THEN NULLIF(v_clean->>'invoice_id','')::uuid ELSE ie.invoice_id END,
      room_id             = CASE WHEN v_clean ? 'room_id' THEN NULLIF(v_clean->>'room_id','')::uuid ELSE ie.room_id END,
      tenant_id           = CASE WHEN v_clean ? 'tenant_id' THEN NULLIF(v_clean->>'tenant_id','')::uuid ELSE ie.tenant_id END,
      business_result_accounting = CASE WHEN v_clean ? 'business_result_accounting' THEN COALESCE((v_clean->>'business_result_accounting')::boolean, ie.business_result_accounting) ELSE ie.business_result_accounting END,
      name                = CASE WHEN v_clean ? 'name' THEN COALESCE(NULLIF(v_clean->>'name',''), ie.name) ELSE ie.name END,
      notes               = CASE WHEN v_clean ? 'notes' THEN v_clean->>'notes' ELSE ie.notes END,
      -- attachments là JSONB: giữ nguyên jsonb, không đổi sang text[] (fix 42804)
      attachments         = CASE
                              WHEN NOT (v_clean ? 'attachments') THEN ie.attachments
                              WHEN v_can_replace_attachments
                                THEN COALESCE(v_clean->'attachments', '[]'::jsonb)
                              ELSE app_private.ie_attachments_union_v1(ie.attachments, v_clean->'attachments')
                            END,
      payer_name          = CASE WHEN v_clean ? 'payer_name' THEN v_clean->>'payer_name' ELSE ie.payer_name END,
      receive_bank_name   = CASE WHEN v_clean ? 'receive_bank_name' THEN v_clean->>'receive_bank_name' ELSE ie.receive_bank_name END,
      receive_bank_account= CASE WHEN v_clean ? 'receive_bank_account' THEN v_clean->>'receive_bank_account' ELSE ie.receive_bank_account END,
      repeat_cycle        = CASE WHEN v_clean ? 'repeat_cycle' THEN v_clean->>'repeat_cycle' ELSE ie.repeat_cycle END,
      repeat_count        = CASE WHEN v_clean ? 'repeat_count' THEN NULLIF(v_clean->>'repeat_count','')::integer ELSE ie.repeat_count END,
      repeat_infinity     = CASE WHEN v_clean ? 'repeat_infinity' THEN COALESCE((v_clean->>'repeat_infinity')::boolean, ie.repeat_infinity) ELSE ie.repeat_infinity END,
      repeat_auto_approve = CASE WHEN v_clean ? 'repeat_auto_approve' THEN COALESCE((v_clean->>'repeat_auto_approve')::boolean, ie.repeat_auto_approve) ELSE ie.repeat_auto_approve END
    WHERE ie.id = p_id;
  END IF;

  IF p_items IS NOT NULL THEN
    DELETE FROM public.income_expense_items WHERE income_expense_id = p_id;
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      SELECT COALESCE(jsonb_object_agg(k, v_item->k), '{}'::jsonb)
        INTO v_item_clean
      FROM unnest(v_item_keys) AS k
      WHERE v_item ? k;

      INSERT INTO public.income_expense_items
      SELECT * FROM jsonb_populate_record(NULL::public.income_expense_items,
        v_item_clean || jsonb_build_object('income_expense_id', p_id));
    END LOOP;
  END IF;

  INSERT INTO app_private.finance_v2_semantic_event_log (organization_id, event_kind, source_table, source_id, source_kind, actor, txid)
  VALUES (v_row.organization_id, 'COMPAT_UPDATE', 'income_expenses', p_id, 'V2_WRITE', auth.uid(), pg_current_xact_id());
  RETURN jsonb_build_object('id', p_id);
END
$$;








--
-- Name: ie_form_buildings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_form_buildings() RETURNS TABLE(id uuid, name text, code text, is_virtual boolean, user_id uuid, managed boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT b.id, b.name, b.code, b.is_virtual, b.user_id,
         public.can_access_building(b.id) AS managed
  FROM public.buildings b
  WHERE b.deleted_at IS NULL
    AND (
      public.can_access_building(b.id)
      OR public.ie_all_buildings_scope(b.id)
    )
    -- ORG_ISOLATION_V1: hai mệnh đề RESTRICTIVE của RLS trên public.buildings.
    AND NOT (public.is_super_admin()
             AND b.organization_id = ANY(public.sandbox_org_ids()))
    AND NOT ((public.is_super_admin() OR public.is_admin())
             AND b.user_id = ANY(public.demo_user_ids()));
$$;








--
-- Name: FUNCTION ie_form_buildings(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ie_form_buildings() IS 'Danh sách toà cho form thu chi và trang Thanh toán. Từ 01/08/2026 áp thêm hai mệnh đề RESTRICTIVE của RLS — trước đó hàm trả 21 toà trong khi đọc thẳng bảng chỉ ra 18, tức toà của tổ chức khác lọt vào ô chọn.';








--
-- Name: room_sort_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_sort_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT (CASE WHEN n LIKE 'MB%' THEN '0'
               WHEN n LIKE 'G%'  THEN '1'
               WHEN n LIKE 'L%'  THEN '2'
               ELSE '3' END) || '|' || public.natural_sort_key(n)
  FROM (SELECT upper(trim(COALESCE(p_name, ''))) AS n) s;
$$;








--
-- Name: rooms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rooms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    building_id uuid NOT NULL,
    name text NOT NULL,
    code text,
    floor integer DEFAULT 1 NOT NULL,
    status public.room_status DEFAULT 'AVAILABLE'::public.room_status NOT NULL,
    area numeric(10,2),
    max_occupants integer DEFAULT 1,
    rent_price numeric(15,2) NOT NULL,
    deposit_amount numeric(15,2) NOT NULL,
    description text,
    images jsonb DEFAULT '[]'::jsonb,
    amenities jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    invoice_template_id uuid,
    lease_template_id uuid,
    sale_note text,
    room_type text,
    sale_bonus_note text,
    name_sort text GENERATED ALWAYS AS (public.room_sort_key(name)) STORED,
    organization_id uuid,
    openclaw_availability_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT rooms_area_positive CHECK (((area IS NULL) OR (area > (0)::numeric))),
    CONSTRAINT rooms_deposit_amount_non_negative CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT rooms_floor_positive CHECK ((floor > 0)),
    CONSTRAINT rooms_max_occupants_positive CHECK ((max_occupants > 0)),
    CONSTRAINT rooms_name_not_empty CHECK ((char_length(name) > 0)),
    CONSTRAINT rooms_openclaw_availability_revision_check CHECK ((openclaw_availability_revision > 0)),
    CONSTRAINT rooms_rent_price_non_negative CHECK ((rent_price >= (0)::numeric))
);








--
-- Name: TABLE rooms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rooms IS 'Rooms/apartments within buildings';








--
-- Name: ie_form_rooms(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_form_rooms(_building_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.rooms
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT r.*
  FROM public.rooms r
  WHERE r.deleted_at IS NULL
    AND (_building_id IS NULL OR r.building_id = _building_id)
    AND (
      public.can_access_building(r.building_id)
      OR public.ie_all_buildings_scope(r.building_id)
    )
    -- ORG_ISOLATION_V1: cùng hai mệnh đề, tra qua toà của phòng.
    AND EXISTS (
      SELECT 1 FROM public.buildings b
       WHERE b.id = r.building_id
         AND NOT (public.is_super_admin()
                  AND b.organization_id = ANY(public.sandbox_org_ids()))
         AND NOT ((public.is_super_admin() OR public.is_admin())
                  AND b.user_id = ANY(public.demo_user_ids()))
    );
$$;








--
-- Name: FUNCTION ie_form_rooms(_building_id uuid); Type: COMMENT; Schema: public; Owner: -
--

