--
-- Name: ie_handover_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_handover_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code text;
  v_allow_handover_change boolean := false;
BEGIN
  -- (a) phiếu GỐC đang nằm trong phiên chưa CANCELLED
  IF OLD.handover_id IS NOT NULL THEN
    SELECT code INTO v_code FROM cash_handovers
     WHERE id = OLD.handover_id AND status <> 'CANCELLED';
  END IF;
  -- (b) cặp phiếu chuyển LEGACY (1 cặp) của phiên CONFIRMED.
  -- Phiếu THU chuyển ("Nhận bàn giao") được đổi handover_id để bàn giao tiếp
  -- — cùng ngữ nghĩa nhánh (c); phiếu CHI chuyển khoá cả handover_id.
  IF v_code IS NULL THEN
    SELECT code, (transfer_income_id = OLD.id)
      INTO v_code, v_allow_handover_change
      FROM cash_handovers
     WHERE status = 'CONFIRMED'
       AND (transfer_expense_id = OLD.id OR transfer_income_id = OLD.id)
     LIMIT 1;
    v_allow_handover_change := COALESCE(v_allow_handover_change, false);
  END IF;
  -- (c) phiếu chuyển LẺ (mới) do 1 phiên chưa CANCELLED tạo ra
  IF v_code IS NULL AND OLD.handover_transfer_id IS NOT NULL THEN
    SELECT code INTO v_code FROM cash_handovers
     WHERE id = OLD.handover_transfer_id AND status <> 'CANCELLED';
    IF v_code IS NOT NULL THEN
      v_allow_handover_change := true;  -- cho phép set handover_id để bàn giao tiếp (chain)
    END IF;
  END IF;

  IF v_code IS NOT NULL THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION '[HANDOVER_LOCKED] Phiếu thuộc phiên bàn giao % — hủy phiên (2 bên xác nhận) trước khi xoá.', v_code;
    END IF;
    IF (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL)
       OR NEW.approval_status      IS DISTINCT FROM OLD.approval_status
       OR NEW.account_id           IS DISTINCT FROM OLD.account_id
       OR NEW.total_amount         IS DISTINCT FROM OLD.total_amount
       OR NEW.voucher_date         IS DISTINCT FROM OLD.voucher_date
       OR NEW.handover_transfer_id IS DISTINCT FROM OLD.handover_transfer_id
       OR (NOT v_allow_handover_change AND NEW.handover_id IS DISTINCT FROM OLD.handover_id) THEN
      RAISE EXCEPTION '[HANDOVER_LOCKED] Phiếu thuộc phiên bàn giao % — hủy phiên (2 bên xác nhận) trước khi hoàn tác/sửa.', v_code;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;








--
-- Name: ie_has_deposit_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_has_deposit_item(p_ie_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM income_expense_items it
    JOIN income_expense_types t ON t.id = it.income_expense_type_id
    WHERE it.income_expense_id = p_ie_id
      AND t.is_deposit = TRUE
  );
$$;








--
-- Name: ie_item_restricted_visible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_item_restricted_visible(_ie_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.income_expenses ie
    WHERE ie.id = _ie_id
      AND (
        ie.has_restricted_item = false
        OR ie.user_id = auth.uid()
        OR public.can_view_restricted_ie()
      )
  );
$$;








--
-- Name: ie_recompute_commission_kind(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ie_recompute_commission_kind(p_ie_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row  record;
  v_kind text;
BEGIN
  IF p_ie_id IS NULL THEN RETURN; END IF;

  SELECT id, type, contract_id, deleted_at, approval_status, commission_kind
    INTO v_row
    FROM income_expenses WHERE id = p_ie_id;
  IF NOT FOUND OR v_row.type <> 'EXPENSE' THEN RETURN; END IF;

  SELECT CASE WHEN bool_or(public.nrm_vn(tp.name) = 'thuong nong sale') THEN 'sale'
              WHEN bool_or(public.nrm_vn(tp.name) = 'hoa hong moi gioi') THEN 'broker' END
    INTO v_kind
    FROM income_expense_items it
    JOIN income_expense_types tp ON tp.id = it.income_expense_type_id
   WHERE it.income_expense_id = p_ie_id
     AND public.nrm_vn(tp.name) IN ('hoa hong moi gioi','thuong nong sale');

  IF v_kind IS DISTINCT FROM v_row.commission_kind THEN
    -- Phiếu SỐNG chuyển thành phiếu hoa hồng mà không gắn HĐ → chặn ngay
    IF v_kind IS NOT NULL AND v_row.contract_id IS NULL
       AND v_row.deleted_at IS NULL AND v_row.approval_status <> 'CANCELLED' THEN
      RAISE EXCEPTION 'Hạng mục "Hoa hồng môi giới"/"Thưởng nóng Sale" chỉ dùng cho phiếu gắn hợp đồng (chi qua flow ký HĐ hoặc Thu tiền → Chi HH). Chi hoa hồng cho đối tác ngoài vui lòng dùng hạng mục khác, vd "Hoa hồng đối tác".'
        USING ERRCODE = 'P0001';
    END IF;
    -- UPDATE này đi qua uq_ie_commission_per_contract → phiếu tay gắn HĐ
    -- đã có phiếu HH sẽ fail 23505 tại đây (chống trùng đường nhập tay).
    UPDATE income_expenses SET commission_kind = v_kind WHERE id = p_ie_id;
  END IF;
END;
$$;








