--
-- Name: income_expense_items_check_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.income_expense_items_check_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_parent uuid;
  v_row record;
  v_lock date;
  v_name text;
BEGIN
  FOREACH v_parent IN ARRAY ARRAY[
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.income_expense_id END,
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.income_expense_id END
  ] LOOP
    CONTINUE WHEN v_parent IS NULL;
    FOR v_row IN
      SELECT unnest(ARRAY[ie.account_id, ie.change_account_id, ie.rounding_account_id]) AS acct,
             ie.voucher_date AS vdate
      FROM public.income_expenses ie WHERE ie.id = v_parent
    LOOP
      CONTINUE WHEN v_row.acct IS NULL OR v_row.vdate IS NULL;
      v_lock := app_private.cashbook_closed_through_v1(v_row.acct);
      IF v_lock IS NOT NULL AND v_row.vdate <= v_lock THEN
        SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = v_row.acct;
        RAISE EXCEPTION
          '[CASHBOOK_CLOSED] Sổ quỹ "%" đã chốt tới ngày % — không sửa được hạng mục của phiếu trong kỳ đã chốt.',
          COALESCE(v_name, v_row.acct::text), v_lock
          USING ERRCODE = 'P0001';
      END IF;
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;








--
-- Name: income_expense_items_check_profit_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.income_expense_items_check_profit_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_parent uuid;
  v_row record;
  v_locked timestamptz;
  v_month date;
BEGIN
  IF v_actor IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  FOREACH v_parent IN ARRAY ARRAY[
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.income_expense_id END,
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.income_expense_id END
  ] LOOP
    CONTINUE WHEN v_parent IS NULL;
    FOR v_row IN
      SELECT ie.building_id AS bld, ie.voucher_date AS vdate, ie.organization_id AS org,
             (COALESCE(ie.business_result_accounting, true) OR ie.system_source IS NULL) AS canh
      FROM public.income_expenses ie WHERE ie.id = v_parent
    LOOP
      CONTINUE WHEN v_row.bld IS NULL OR v_row.vdate IS NULL OR NOT v_row.canh;
      IF public.is_super_admin() OR app_private.is_org_owner_v1(v_row.org, v_actor) THEN
        CONTINUE;
      END IF;
      v_month := date_trunc('month', v_row.vdate)::date;
      SELECT pm.locked_at INTO v_locked FROM public.profit_monthly pm
       WHERE pm.building_id = v_row.bld AND pm.period_month = v_month
         AND pm.locked_at IS NOT NULL LIMIT 1;
      IF v_locked IS NOT NULL THEN
        RAISE EXCEPTION
          '[PROFIT_LOCKED] Kỳ tháng % của toà này đã chốt — không sửa hạng mục của phiếu trong tháng đó.',
          to_char(v_month, 'MM/YYYY') USING ERRCODE = 'P0001';
      END IF;
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END
$$;








--
-- Name: income_expense_posting_lines_check_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.income_expense_posting_lines_check_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_acct uuid;
  v_posting uuid;
  v_kind text;
  v_on date;
  v_lock date;
  v_name text;
BEGIN
  v_acct   := COALESCE(NEW.account_id, OLD.account_id);
  v_posting := COALESCE(NEW.posting_id, OLD.posting_id);
  IF v_acct IS NULL OR v_posting IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT p.event_kind,
         CASE
           -- Bút toán ĐẢO luôn mang ngày hôm nay. Nếu xét theo ngày của chính
           -- nó thì chốt sổ tới HÔM NAY sẽ khoá luôn cả ngày hôm đó và không
           -- ai đảo được gì nữa. Kỳ bị đụng thật sự là kỳ của bút toán GỐC.
           WHEN p.event_kind = 'REVERSAL' AND p.reversal_of_id IS NOT NULL
             THEN (SELECT o.posted_on FROM public.income_expense_postings o WHERE o.id = p.reversal_of_id)
           ELSE p.posted_on
         END
    INTO v_kind, v_on
  FROM public.income_expense_postings p WHERE p.id = v_posting;

  IF v_on IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  v_lock := app_private.cashbook_closed_through_v1(v_acct);
  IF v_lock IS NOT NULL AND v_on <= v_lock THEN
    SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = v_acct;
    RAISE EXCEPTION
      '[CASHBOOK_CLOSED] Sổ quỹ "%" đã chốt tới ngày % — không ghi thêm bút toán vào kỳ đã chốt.',
      COALESCE(v_name, v_acct::text), v_lock
      USING ERRCODE = 'P0001';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;








