--
-- Name: income_expenses_check_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.income_expenses_check_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_pairs record;
  v_lock date;
  v_name text;
BEGIN
  -- Ngoại lệ ANNOTATE (quyết định #8): sau khi chốt vẫn bổ sung được ảnh
  -- chứng từ / ghi chú. Guard TỰ KIỂM delta chứ không tin lời writer — phiếu
  -- không flow-owned không có lớp kiểm cột nào khác.
  IF TG_OP = 'UPDATE' AND EXISTS (
    SELECT 1 FROM app_private.ie_flex_writer_xids w
     WHERE w.income_expense_id = OLD.id
       AND w.transaction_id = pg_current_xact_id()
       AND w.backend_pid = pg_backend_pid()
       AND w.scope = 'ANNOTATE'
  ) AND (to_jsonb(OLD) - ARRAY['attachments','notes','updated_at'])
        IS NOT DISTINCT FROM
        (to_jsonb(NEW) - ARRAY['attachments','notes','updated_at']) THEN
    RETURN NEW;
  END IF;

  -- Mọi cặp (sổ, ngày) mà thao tác này CHẠM tới — cả phía cũ lẫn phía mới, và
  -- cả sổ Thối / sổ Làm tròn, vì tồn quỹ cộng theo account của từng DÒNG posting.
  FOR v_pairs IN
    SELECT acct, vdate FROM (
      SELECT CASE WHEN TG_OP <> 'INSERT' THEN OLD.account_id END          AS acct,
             CASE WHEN TG_OP <> 'INSERT' THEN OLD.voucher_date END        AS vdate
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'INSERT' THEN OLD.change_account_id END,
             CASE WHEN TG_OP <> 'INSERT' THEN OLD.voucher_date END
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'INSERT' THEN OLD.rounding_account_id END,
             CASE WHEN TG_OP <> 'INSERT' THEN OLD.voucher_date END
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'DELETE' THEN NEW.account_id END,
             CASE WHEN TG_OP <> 'DELETE' THEN NEW.voucher_date END
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'DELETE' THEN NEW.change_account_id END,
             CASE WHEN TG_OP <> 'DELETE' THEN NEW.voucher_date END
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'DELETE' THEN NEW.rounding_account_id END,
             CASE WHEN TG_OP <> 'DELETE' THEN NEW.voucher_date END
    ) s
    WHERE acct IS NOT NULL AND vdate IS NOT NULL
  LOOP
    -- FOR KEY SHARE: giao dịch ghi phiếu giữ khoá dòng trên `accounts`, nên
    -- giao dịch đang CHỐT SỔ (FOR UPDATE) phải chờ. Không có nó thì trigger
    -- đọc lock_date bằng SELECT trần và hai bên không bao giờ đụng nhau —
    -- một phiếu vẫn lọt vào kỳ vừa bị đóng băng vĩnh viễn.
    PERFORM 1 FROM public.accounts a WHERE a.id = v_pairs.acct FOR KEY SHARE;

    v_lock := app_private.cashbook_closed_through_v1(v_pairs.acct);
    IF v_lock IS NOT NULL AND v_pairs.vdate <= v_lock THEN
      SELECT a.name INTO v_name FROM public.accounts a WHERE a.id = v_pairs.acct;
      RAISE EXCEPTION
        '[CASHBOOK_CLOSED] Sổ quỹ "%" đã chốt & bàn giao tới ngày % — phiếu có ngày phát sinh ≤ ngày này không sửa/huỷ/xoá được nữa.',
        COALESCE(v_name, v_pairs.acct::text), v_lock
        USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$$;








--
-- Name: income_expenses_check_profit_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.income_expenses_check_profit_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_row record;
  v_locked timestamptz;
  v_month date;
BEGIN
  IF v_actor IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Cửa ANNOTATE (quyết định #8): vẫn bổ sung được ảnh chứng từ / ghi chú.
  IF TG_OP = 'UPDATE' AND EXISTS (
    SELECT 1 FROM app_private.ie_flex_writer_xids w
     WHERE w.income_expense_id = OLD.id
       AND w.transaction_id = pg_current_xact_id()
       AND w.backend_pid = pg_backend_pid()
       AND w.scope = 'ANNOTATE'
  ) AND (to_jsonb(OLD) - ARRAY['attachments','notes','updated_at'])
        IS NOT DISTINCT FROM
        (to_jsonb(NEW) - ARRAY['attachments','notes','updated_at']) THEN
    RETURN NEW;
  END IF;

  v_org := COALESCE(NEW.organization_id, OLD.organization_id);

  IF public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  FOR v_row IN
    SELECT bld, vdate FROM (
      SELECT CASE WHEN TG_OP <> 'INSERT' THEN OLD.building_id END AS bld,
             CASE WHEN TG_OP <> 'INSERT' THEN OLD.voucher_date END AS vdate,
             -- Chặn khi: phiếu TRONG KQKD (bất kể nguồn) HOẶC phiếu ngoài KQKD
             -- do NGƯỜI DÙNG tự tạo (không có system_source).
             CASE WHEN TG_OP <> 'INSERT' THEN
               (COALESCE(OLD.business_result_accounting, true) OR OLD.system_source IS NULL)
             END AS canh
      UNION ALL
      SELECT CASE WHEN TG_OP <> 'DELETE' THEN NEW.building_id END,
             CASE WHEN TG_OP <> 'DELETE' THEN NEW.voucher_date END,
             CASE WHEN TG_OP <> 'DELETE' THEN
               (COALESCE(NEW.business_result_accounting, true) OR NEW.system_source IS NULL)
             END
    ) s
    WHERE bld IS NOT NULL AND vdate IS NOT NULL AND canh
  LOOP
    v_month := date_trunc('month', v_row.vdate)::date;
    SELECT pm.locked_at INTO v_locked
    FROM public.profit_monthly pm
    WHERE pm.building_id = v_row.bld
      AND pm.period_month = v_month
      AND pm.locked_at IS NOT NULL
    LIMIT 1;

    IF v_locked IS NOT NULL THEN
      RAISE EXCEPTION
        '[PROFIT_LOCKED] Kỳ tháng % của toà này đã chốt lợi nhuận — không ghi thêm/sửa phiếu của tháng đó, kể cả phiếu ngoài kết quả kinh doanh. Hãy lập phiếu ở tháng hiện tại, hoặc nhờ chủ tổ chức mở khoá tháng.',
        to_char(v_month, 'MM/YYYY')
        USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END
$$;








--
-- Name: invite_organization_member_v1(text, text, uuid, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_organization_member_v1(p_email text, p_member_type text DEFAULT 'STAFF'::text, p_role_id uuid DEFAULT NULL::uuid, p_scope_ids uuid[] DEFAULT NULL::uuid[], p_expires_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private', 'extensions'
    AS $_$
declare
  v_actor uuid := (select auth.uid());
  v_org   uuid;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_type  text := upper(btrim(coalesce(p_member_type, 'STAFF')));
  v_token text;
  v_id    uuid := gen_random_uuid();
  v_days  int  := coalesce(p_expires_days, 7);
begin
  if v_actor is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  if v_email = '' or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Địa chỉ email không hợp lệ.' using errcode = '22023';
  end if;
  if v_type not in ('OWNER','STAFF','SHAREHOLDER','PARTNER','SERVICE') then
    raise exception 'Loại thành viên "%" không hợp lệ. Chọn: Chủ sở hữu, Nhân sự, Cổ đông, Đối tác hoặc Dịch vụ.', p_member_type
      using errcode = '22023';
  end if;
  if v_days < 1 or v_days > 30 then
    raise exception 'Hạn lời mời phải từ 1 đến 30 ngày.' using errcode = '22023';
  end if;

  select m.organization_id into v_org
    from public.organization_memberships m
    join public.organizations o on o.id = m.organization_id and o.status = 'ACTIVE'
   where m.user_id = v_actor and m.status = 'ACTIVE'
   order by coalesce(o.is_demo,false), m.organization_id limit 1;
  if v_org is null then
    raise exception 'Bạn không thuộc tổ chức nào đang hoạt động.' using errcode = '42501';
  end if;

  perform app_private.require_perm_v1(v_org, 'users.create', 'mời thành viên');

  if p_role_id is not null and not exists (
       select 1 from public.organization_roles r where r.id = p_role_id and r.organization_id = v_org) then
    raise exception 'Vai trò không thuộc tổ chức này.' using errcode = '22023';
  end if;
  if p_scope_ids is not null and exists (
       select 1 from unnest(p_scope_ids) as t(sid)
        where not exists (select 1 from public.authorization_scopes s
                           where s.id = t.sid and s.organization_id = v_org)) then
    raise exception 'Có phạm vi không thuộc tổ chức này.' using errcode = '22023';
  end if;
  if exists (select 1 from public.organization_memberships m
               join auth.users u on u.id = m.user_id
              where m.organization_id = v_org and m.status = 'ACTIVE' and lower(u.email) = v_email) then
    raise exception 'Người này đã là thành viên của tổ chức.' using errcode = '23505';
  end if;

  -- Lời mời cũ còn hiệu lực: thu hồi rồi phát cái mới, tránh hai token cùng sống.
  update public.organization_invitations
     set status = 'REVOKED', revoked_at = now()
   where organization_id = v_org and email_normalized = v_email and status = 'PENDING';

  v_token := encode(extensions.gen_random_bytes(32), 'hex');

  insert into public.organization_invitations
    (id, organization_id, email_normalized, token_hash, intended_member_type,
     intended_role_id, intended_scope_ids, invited_by, status, expires_at, created_at)
  values (v_id, v_org, v_email, encode(extensions.digest(v_token, 'sha256'), 'hex'), v_type,
          p_role_id, coalesce(p_scope_ids, '{}'::uuid[]), v_actor, 'PENDING',
          now() + make_interval(days => v_days), now());

  perform app_private.append_authz_audit_v1(
    v_org, 'MEMBER_INVITED', 'organization_invitation', v_id, null,
    jsonb_build_object('member_type', v_type, 'role_id', p_role_id, 'expires_days', v_days), null);

  -- Token thô chỉ xuất hiện ở đây, đúng một lần.
  return jsonb_build_object('invitationId', v_id, 'token', v_token,
    'expiresAt', now() + make_interval(days => v_days),
    'note', 'Hệ thống chưa có chỗ gửi email — hãy gửi đường dẫn này cho người được mời.');
end
$_$;








--
-- Name: invoice_active_payment_methods(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_active_payment_methods(p_invoice_ids uuid[]) RETURNS TABLE(invoice_id uuid, payment_methods text[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT
    receipt.invoice_id,
    array_agg(
      DISTINCT receipt.payment_method::text
      ORDER BY receipt.payment_method::text
    ) AS payment_methods
  FROM public.active_payment_receipts receipt
  WHERE receipt.invoice_id = ANY(p_invoice_ids)
    AND receipt.collected_amount > 0
  GROUP BY receipt.invoice_id;
$$;








--
-- Name: FUNCTION invoice_active_payment_methods(p_invoice_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invoice_active_payment_methods(p_invoice_ids uuid[]) IS 'Active retained receipt methods for a bounded invoice page; one aggregate row per invoice.';








--
-- Name: invoice_payment_method_drilldown(public.payment_method); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_payment_method_drilldown(p_payment_method public.payment_method) RETURNS SETOF public.invoices
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT invoice_row.*
  FROM public.invoices invoice_row
  WHERE EXISTS (
    SELECT 1
    FROM public.active_payment_receipts receipt
    WHERE receipt.invoice_id = invoice_row.id
      AND receipt.organization_id = invoice_row.organization_id
      AND receipt.payment_method = p_payment_method
      AND receipt.collected_amount > 0
  );
$$;








--
-- Name: FUNCTION invoice_payment_method_drilldown(p_payment_method public.payment_method); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invoice_payment_method_drilldown(p_payment_method public.payment_method) IS 'Security-invoker invoice source for active receipt-method drill-down with server-side filtering and pagination.';








