-- Name: job_photo_ok(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_photo_ok(p_completion jsonb, p_attachments jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (jsonb_typeof(COALESCE(p_completion, '[]'::jsonb)) = 'array'
          AND jsonb_array_length(COALESCE(p_completion, '[]'::jsonb)) > 0)
      OR (jsonb_typeof(COALESCE(p_attachments, '[]'::jsonb)) = 'array'
          AND jsonb_array_length(COALESCE(p_attachments, '[]'::jsonb)) > 0);
$$;








--
-- Name: FUNCTION job_photo_ok(p_completion jsonb, p_attachments jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.job_photo_ok(p_completion jsonb, p_attachments jsonb) IS 'Bang chung anh hoan thanh: FE tung ghi vao `attachments` thay vi `completion_attachments` nen phai chap nhan ca hai (xem 20260720180000).';








--
-- Name: jobs_stamp_completion_time(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_stamp_completion_time() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin  BOOLEAN := public.is_admin() OR public.is_super_admin();
  v_old_pm DATE;
  v_new_pm DATE;
BEGIN
  -- Chuyen SANG hoan thanh (insert thang COMPLETED cung tinh)
  IF NEW.status = 'COMPLETED' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'COMPLETED') THEN
    -- Admin duoc phep khai gio hoan thanh (lui ngay nghiep vu); nguoi thuong thi KHONG.
    IF NOT v_admin OR NEW.completion_time IS NULL THEN
      NEW.completion_time := now();
    END IF;
    -- Chan gio tuong lai trong moi truong hop — khong ai hoan thanh viec o thi tuong lai.
    IF NEW.completion_time > now() + INTERVAL '1 minute' THEN
      RAISE EXCEPTION 'Thoi gian hoan thanh khong duoc o tuong lai (%).', NEW.completion_time
        USING HINT = 'completion_time do server dong dau; kiem tra dong ho thiet bi.';
    END IF;
    RETURN NEW;
  END IF;

  -- Sua completion_time tren dong DA hoan thanh
  IF TG_OP = 'UPDATE' AND OLD.status = 'COMPLETED'
     AND NEW.completion_time IS DISTINCT FROM OLD.completion_time THEN
    IF NOT v_admin THEN
      RAISE EXCEPTION 'Khong duoc sua thoi gian hoan thanh cua cong viec da xong.'
        USING HINT = 'Lien he quan ly neu can dieu chinh — thao tac nay co kiem soat.';
    END IF;
    -- Admin: van chan neu ky luong (cu HOAC moi) da CHOT — tranh tra hai lan.
    v_old_pm := date_trunc('month', public.vn_local_date(OLD.completion_time))::date;
    v_new_pm := date_trunc('month', public.vn_local_date(NEW.completion_time))::date;
    IF EXISTS (
      SELECT 1 FROM public.salary_monthly sm
      WHERE sm.staff_id = OLD.assignee_id
        AND sm.period_month IN (v_old_pm, v_new_pm)
        AND sm.locked_at IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'Ky luong lien quan da chot — khong the doi thoi gian hoan thanh.'
        USING HINT = 'Mo khoa ky luong truoc, hoac dung phieu dieu chinh.';
    END IF;
  END IF;

  RETURN NEW;
END; $$;








--
-- Name: list_authorization_catalog_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_authorization_catalog_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
begin
  if v_org is null then
    raise exception 'Bạn không có quyền xem danh mục phân quyền.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'scopes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'scopeId',    s.id,
               'scopeType',  s.scope_type,
               'label',      app_private.scope_label_v1(s.id),
               'buildingId', s.building_id,
               'areaId',     s.area_id,
               'cashbookId', s.cashbook_id)
             order by case s.scope_type when 'ORGANIZATION' then 0 when 'AREA' then 1
                                        when 'BUILDING' then 2 else 3 end,
                      app_private.scope_label_v1(s.id))
        from public.authorization_scopes s
       where s.organization_id = v_org), '[]'::jsonb),
    'permissions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'key',            pd.key,
               'resource',       pd.resource,
               'action',         pd.action,
               'sensitivity',    pd.sensitivity,
               'scopeKinds',     to_jsonb(pd.scope_kinds),
               'requiredDimensions', to_jsonb(coalesce(pd.required_dimensions, '{}'::text[])),
               'requiresCashbookPossession', pd.requires_cashbook_possession)
             order by pd.key)
        from public.permission_definitions pd
       where pd.permission_domain = 'TENANT' and pd.is_active), '[]'::jsonb));
end
$$;








--
-- Name: list_cashbook_closings_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cashbook_closings_v1(p_cashbook uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE v_out jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;

  SELECT jsonb_build_object(
    'pending', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'request_id', r.id, 'cashbook_id', r.cashbook_id, 'cashbook_name', a.name,
        'closed_through', r.closed_through, 'counted_balance', r.counted_balance,
        'system_balance', r.system_balance,
        'difference', r.counted_balance - r.system_balance,
        'note', r.note, 'created_at', r.created_at,
        'proposed_by', r.proposed_by, 'proposed_by_name', pp.full_name,
        'confirmer_user_id', r.confirmer_user_id, 'confirmer_name', cp.full_name,
        'is_mine_to_confirm', (r.confirmer_user_id = auth.uid())
      ) ORDER BY r.created_at DESC)
      FROM app_private.cashbook_closure_requests r
      JOIN public.accounts a ON a.id = r.cashbook_id
      LEFT JOIN public.profiles pp ON pp.id = r.proposed_by
      LEFT JOIN public.profiles cp ON cp.id = r.confirmer_user_id
      WHERE r.status = 'PENDING'
        AND (p_cashbook IS NULL OR r.cashbook_id = p_cashbook)
        AND (public.is_super_admin() OR EXISTS (
          SELECT 1 FROM public.organization_memberships m
           WHERE m.user_id = auth.uid() AND m.organization_id = r.organization_id
             AND m.status = 'ACTIVE'))
    ), '[]'::jsonb),
    'closures', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'closure_id', c.id, 'cashbook_id', c.cashbook_id, 'cashbook_name', a.name,
        'closed_through', c.closed_through, 'counted_balance', c.counted_balance,
        'system_balance', c.system_balance,
        'difference', c.counted_balance - c.system_balance,
        'basis', c.basis, 'confirmed_at', c.confirmed_at,
        'proposed_by_name', pp.full_name, 'confirmed_by_name', cp.full_name
      ) ORDER BY c.closed_through DESC, c.id DESC)
      FROM app_private.cashbook_closures c
      JOIN public.accounts a ON a.id = c.cashbook_id
      LEFT JOIN public.profiles pp ON pp.id = c.proposed_by
      LEFT JOIN public.profiles cp ON cp.id = c.confirmed_by
      WHERE (p_cashbook IS NULL OR c.cashbook_id = p_cashbook)
        AND (public.is_super_admin() OR EXISTS (
          SELECT 1 FROM public.organization_memberships m
           WHERE m.user_id = auth.uid() AND m.organization_id = c.organization_id
             AND m.status = 'ACTIVE'))
    ), '[]'::jsonb)
  ) INTO v_out;

  RETURN v_out;
END
$$;








--
-- Name: list_cashbook_visibility_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cashbook_visibility_v2() RETURNS TABLE(cashbook_id uuid, balance_visible boolean, can_manage boolean, can_delete boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT a.id,
         CASE
           WHEN app_private.finance_v2_route_pure_v1(
                  'income_expense.read_semantics.v2', a.organization_id)
                IN ('CANONICAL', 'FROZEN')
             THEN app_private.finance_v2_can_read_posting_v1(a.organization_id, a.id)
           ELSE true
         END,
         (SELECT public.is_super_admin())
           OR a.user_id = auth.uid()
           OR public.staff_can('cashbooks', 'edit', a.user_id),
         (SELECT public.is_super_admin())
           OR a.user_id = auth.uid()
           OR public.staff_can('cashbooks', 'delete', a.user_id)
  FROM public.accounts a
  WHERE a.deleted_at IS NULL
    AND (a.organization_id IS NULL
         OR a.organization_id IN (SELECT unnest(public.my_org_ids())));
$$;








--
-- Name: list_cashbooks_for_expense_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cashbooks_for_expense_v2() RETURNS TABLE(id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
