-- Name: list_cashbooks_with_balance_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cashbooks_with_balance_v2() RETURNS TABLE(id uuid, name text, current_amount numeric)
