--
-- Name: list_finance_execution_queue_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_finance_execution_queue_v2() RETURNS TABLE(scope_id uuid, organization_id uuid, execution_subject_kind text, execution_subject_id uuid, parent_voucher_id uuid, state text, assigned_cashbook_id uuid, revision bigint, my_candidate_cashbooks uuid[])
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  WITH me AS (
    SELECT m.id AS membership_id, m.organization_id
    FROM public.organization_memberships m
    WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE'
  ),
  my_custodian AS (
    SELECT b.organization_id, b.cashbook_id
    FROM public.cashbook_possession_bindings b
    JOIN me ON me.membership_id = b.membership_id
    WHERE b.possession_kind = 'CUSTODIAN' AND b.valid_to IS NULL
  )
  SELECT s.id, s.organization_id, s.execution_subject_kind, s.execution_subject_id,
         s.parent_voucher_id, s.state, s.assigned_cashbook_id, s.revision,
         ARRAY(SELECT c.cashbook_id
               FROM app_private.finance_execution_cashbook_candidates c
               JOIN my_custodian mc ON mc.cashbook_id = c.cashbook_id
               WHERE c.execution_scope_id = s.id) AS my_candidate_cashbooks
  FROM app_private.finance_execution_scopes s
  JOIN me ON me.organization_id = s.organization_id
  WHERE s.state IN ('UNASSIGNED', 'ASSIGNED')
    AND (
      -- CUSTODIAN of an exact candidate/assigned cashbook sees the safe payable row
      EXISTS (SELECT 1 FROM app_private.finance_execution_cashbook_candidates c
              JOIN my_custodian mc ON mc.cashbook_id = c.cashbook_id
              WHERE c.execution_scope_id = s.id)
      OR EXISTS (SELECT 1 FROM my_custodian mc WHERE mc.cashbook_id = s.assigned_cashbook_id)
      -- assigner (cashbooks.share covering the org) sees the Chờ phân sổ queue
      OR COALESCE((SELECT z.allowed FROM app_private.authorize_tenant_action_v3(
           auth.uid(), s.organization_id, 'cashbooks.share', NULL, NULL) z LIMIT 1), false)
    );
$$;








--
-- Name: list_ie_accounting_standard_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_ie_accounting_standard_v1() RETURNS TABLE(organization_id uuid, organization_name text, strict_mode boolean, can_manage boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT o.id,
         o.name,
         app_private.ie_accounting_strict_v1(o.id),
         app_private.is_org_owner_v1(o.id, auth.uid()) OR public.is_super_admin()
  FROM public.organizations o
  JOIN public.organization_memberships m
    ON m.organization_id = o.id
   AND m.user_id = auth.uid()
   AND m.status = 'ACTIVE'
  ORDER BY o.name;
$$;








--
-- Name: list_income_expenses_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_income_expenses_v2(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id uuid, organization_id uuid, type text, name text, notes text, total_amount numeric, approval_status text, review_state text, posting_mode text, posting_status text, account_id uuid, voucher_date date, recognition_date date, system_source text, maker_user_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT ie.id, ie.organization_id, ie.type, ie.name, ie.notes,
         ie.total_amount, ie.approval_status, ie.review_state,
         ie.posting_mode, ie.posting_status, ie.account_id,
         ie.voucher_date, ie.recognition_date, ie.system_source,
         ie.maker_user_id, ie.created_at
  FROM app_private.finance_v2_visible_vouchers() ie
  WHERE (p_filters->>'type' IS NULL OR ie.type = p_filters->>'type')
    AND (p_filters->>'approvalStatus' IS NULL OR ie.approval_status = p_filters->>'approvalStatus')
    AND (p_filters->>'postingStatus' IS NULL OR ie.posting_status = p_filters->>'postingStatus')
    AND (p_filters->>'accountId' IS NULL OR ie.account_id = (p_filters->>'accountId')::uuid)
    AND (p_filters->>'fromDate' IS NULL OR ie.voucher_date >= (p_filters->>'fromDate')::date)
    AND (p_filters->>'toDate' IS NULL OR ie.voucher_date <= (p_filters->>'toDate')::date)
  ORDER BY ie.voucher_date DESC, ie.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE((p_filters->>'limit')::int, 100), 1), 200)
  OFFSET GREATEST(COALESCE((p_filters->>'offset')::int, 0), 0);
$$;








--
-- Name: list_my_cashbook_access_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_cashbook_access_v2() RETURNS TABLE(cashbook_id uuid, cashbook_name text, possession_kind text, since timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  SELECT b.cashbook_id, a.name, b.possession_kind, b.valid_from
  FROM public.cashbook_possession_bindings b
  JOIN public.organization_memberships m ON m.id = b.membership_id
  JOIN public.accounts a ON a.id = b.cashbook_id
  WHERE m.user_id = auth.uid() AND m.status = 'ACTIVE' AND b.valid_to IS NULL;
$$;








--
-- Name: list_my_pending_approvals_compat_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_pending_approvals_compat_v2() RETURNS TABLE(id uuid, subject_type text, subject_id uuid, state text, amount numeric, system_source text, cashbook_id uuid, building_id uuid, submitted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
  WITH actor AS (
    SELECT a.organization_id, a.membership_id
    FROM app_private.resolve_approval_actor_v2() a
  )
  SELECT DISTINCT
    r.id, r.subject_type, r.subject_id, r.state,
    r.amount, r.system_source, r.cashbook_id, r.building_id, r.submitted_at
  FROM public.approval_requests r
  JOIN actor a ON a.organization_id = r.organization_id
  WHERE r.state = 'PENDING_APPROVAL'
    AND (
      r.maker_membership_id = a.membership_id
      OR EXISTS (
        SELECT 1
        FROM public.approval_request_steps st
        JOIN public.approval_request_step_candidates c
          ON c.request_step_id = st.id
         AND c.organization_id = st.organization_id
        WHERE st.request_id = r.id
          AND st.organization_id = r.organization_id
          AND st.status = 'PENDING'
          AND c.membership_id = a.membership_id
          AND c.generation = st.current_generation
          AND (c.valid_to IS NULL OR c.valid_to > now())
      )
    )
  ORDER BY r.submitted_at;
$$;








--
-- Name: FUNCTION list_my_pending_approvals_compat_v2(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_my_pending_approvals_compat_v2() IS 'Thu Chi V2 §9.4/§10(1019) containment: approval inbox scoped (maker/eligible-approver, current generation). Không lộ payload/candidate list.';








--
-- Name: list_my_pending_approvals_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_pending_approvals_v1() RETURNS TABLE(request_id uuid, submission_no bigint, submitted_at timestamp with time zone, amount numeric, voucher_id uuid, voucher_code text, voucher_name text, voucher_type text, maker_name text, step_no integer, request_version bigint, organization_id uuid, approval_version bigint, posting_version bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  select ar.id, ar.submission_no, ar.submitted_at,
         ar.amount, ie.id, ie.code, ie.name, ie.type::text,
         coalesce(ie.creator_name, '—'), s.step_no, ar.version,
         ar.organization_id,
         coalesce(ie.approval_version, 1), coalesce(ie.posting_version, 1)
    from public.approval_requests ar
    join public.approval_request_steps s
      on s.request_id = ar.id and s.status = 'PENDING'
    join public.approval_request_step_candidates c
      on c.request_step_id = s.id
     and c.generation = s.current_generation
     and c.valid_to is null
    join public.organization_memberships m
      on m.id = c.membership_id and m.status = 'ACTIVE'
    left join public.income_expenses ie on ie.id = ar.subject_id
   where ar.state = 'PENDING_APPROVAL'
     and ar.subject_type = 'FINANCIAL_VOUCHER'
     and m.user_id = auth.uid()
   order by ar.submitted_at asc;
$$;








--
-- Name: list_organization_members_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_organization_members_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
  v_out jsonb;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền xem danh sách thành viên.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'organizationId', v_org,
    'members', coalesce(jsonb_agg(x.row order by x.sort_key, x.email), '[]'::jsonb))
    into v_out
  from (
    select
      -- Chủ sở hữu lên đầu, rồi tới nhân sự, rồi các loại còn lại.
      case m.member_type when 'OWNER' then 0 when 'STAFF' then 1 else 2 end as sort_key,
      coalesce(p.email, u.email, '') as email,
      jsonb_build_object(
        'membershipId', m.id,
        'userId',       m.user_id,
        'email',        coalesce(p.email, u.email),
        'fullName',     p.full_name,
        'memberType',   m.member_type,
        'status',       m.status,
        'version',      m.version,
        'isSelf',       (m.user_id = (select auth.uid())),
        'roles', coalesce((
          select jsonb_agg(jsonb_build_object(
                   'bindingId', rb.id,
                   'roleId',    orl.id,
                   'roleName',  orl.name,
                   'isSystem',  orl.is_system,
                   'scopes', coalesce((
                     select jsonb_agg(jsonb_build_object(
                              'scopeId',   s.id,
                              'scopeType', s.scope_type,
                              'label',     app_private.scope_label_v1(s.id))
                            order by s.scope_type, app_private.scope_label_v1(s.id))
                       from public.role_binding_scopes rbs
                       join public.authorization_scopes s on s.id = rbs.scope_id
                      where rbs.role_binding_id = rb.id), '[]'::jsonb))
                 order by orl.name)
            from public.role_bindings rb
            join public.organization_roles orl on orl.id = rb.role_id
           where rb.membership_id = m.id and rb.valid_to is null), '[]'::jsonb),
        'overrideAllow', (select count(*) from public.member_permission_overrides o
                           where o.membership_id = m.id and o.revoked_at is null
                             and o.effect = 'ALLOW'
                             and (o.expires_at is null or o.expires_at > now())),
        'overrideDeny',  (select count(*) from public.member_permission_overrides o
                           where o.membership_id = m.id and o.revoked_at is null
                             and o.effect = 'DENY'
                             and (o.expires_at is null or o.expires_at > now())),
        'cashbooksHeld', (select count(*) from public.cashbook_possession_bindings cp
                           where cp.membership_id = m.id and cp.valid_from <= now()
                             and (cp.valid_to is null or cp.valid_to > now())),
        'permissionCount',
          coalesce(array_length(app_private.allowed_keys_for_membership_v3(m.id), 1), 0)
      ) as row
    from public.organization_memberships m
    left join public.profiles p on p.id = m.user_id
    left join auth.users u      on u.id = m.user_id
   where m.organization_id = v_org
     and m.status <> 'REVOKED'
  ) x;

  return v_out;
end
$$;








--
-- Name: list_organization_roles_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_organization_roles_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
  v_out jsonb;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền xem mẫu vai trò.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'roleId',   r.id,
           'name',     r.name,
           'isSystem', r.is_system,
           'status',   coalesce(r.status, 'ACTIVE'),
           'version',  r.version,
           'memberCount', (select count(distinct rb.membership_id)
                             from public.role_bindings rb
                            where rb.role_id = r.id and rb.valid_to is null),
           'allowKeys', coalesce((select jsonb_agg(rp.permission_key order by rp.permission_key)
                                    from public.role_permissions rp
                                   where rp.role_id = r.id and rp.effect = 'ALLOW'), '[]'::jsonb),
           'denyKeys',  coalesce((select jsonb_agg(rp.permission_key order by rp.permission_key)
                                    from public.role_permissions rp
                                   where rp.role_id = r.id and rp.effect = 'DENY'), '[]'::jsonb))
         order by r.is_system desc, r.name), '[]'::jsonb)
    into v_out
    from public.organization_roles r
   where r.organization_id = v_org and coalesce(r.status, 'ACTIVE') <> 'ARCHIVED';

  return v_out;
end
$$;








--
-- Name: lock_cashbook_period_v1(uuid, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_cashbook_period_v1(p_cashbook_id uuid, p_lock_date date, p_unlock boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_acct record; v_org uuid; v_authz boolean; v_route text; v_new date;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;

  -- Đợt 3: MỞ KHOÁ KHÔNG CÒN LÀ MỘT KHÁI NIỆM (quyết định #7 của chủ).
  if p_unlock then
    raise exception
      '[CASHBOOK_CLOSED] Không mở khoá kỳ đã chốt. Sai sót phát hiện sau khi bàn giao phải xử lý bằng phiếu điều chỉnh ở kỳ hiện tại.'
      using errcode='55000';
  end if;

  select a.id, a.organization_id, a.lock_date into v_acct
    from public.accounts a where a.id=p_cashbook_id and a.deleted_at is null for update;
  if not found then raise exception 'Không tìm thấy sổ quỹ' using errcode='42501'; end if;
  v_org := v_acct.organization_id;
  if v_org is null then raise exception 'Sổ quỹ chưa gắn tổ chức' using errcode='23514'; end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'cashbooks.edit', null, p_cashbook_id);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền khoá sổ (cashbooks.edit)' using errcode='42501'; end if;

  v_route := app_private.evaluate_feature_route('cashbook.lock_period.v1', v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer khoá sổ chưa bật' using errcode='55000'; end if;

  if p_lock_date is null then raise exception 'Ngày khoá trống'; end if;
  if v_acct.lock_date is not null and p_lock_date < v_acct.lock_date then
    raise exception 'Không thể lùi ngày khoá sổ' using errcode='55000'; end if;
  v_new := p_lock_date;

  update public.accounts set lock_date = v_new where id = p_cashbook_id;
  return json_build_object('cashbook_id', p_cashbook_id, 'lock_date', v_new);
end;
$$;








--
-- Name: FUNCTION lock_cashbook_period_v1(p_cashbook_id uuid, p_lock_date date, p_unlock boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lock_cashbook_period_v1(p_cashbook_id uuid, p_lock_date date, p_unlock boolean) IS 'DI SẢN. Khoá kỳ giờ đi qua nghi thức hai bên: propose_cashbook_closing_v1 → confirm_cashbook_closing_v1. Đã REVOKE khỏi authenticated vì cashbooks.edit không đòi đang-giữ-sổ, nên hàm này từng là cửa sau một-cú-gọi.';








--
-- Name: lock_profit_month_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_profit_month_v1(p_period_month text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_authz boolean;
  v_row jsonb;
  v_building uuid;
  v_pm_id uuid;
  v_pm_ids uuid[] := '{}';
  v_alloc jsonb;
  v_locked int := 0;
  v_allocs int := 0;
  v_period date;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  if p_period_month is null or p_period_month !~ '^\d{4}-\d{2}(-\d{2})?$' then
    raise exception 'period_month phải dạng YYYY-MM hoặc YYYY-MM-DD';
  end if;
  -- Cột period_month là DATE — chuẩn hoá YYYY-MM về ngày đầu tháng.
  v_period := (case when length(p_period_month) = 7
                    then p_period_month || '-01' else p_period_month end)::date;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'Không có dữ liệu để chốt';
  end if;

  -- Org suy từ building đầu tiên; mọi building phải cùng org ACTIVE.
  select b.organization_id into v_org
    from public.buildings b
   where b.id = (p_rows->0->>'building_id')::uuid and b.deleted_at is null;
  if v_org is null then
    raise exception 'Toà nhà không hợp lệ hoặc chưa có tổ chức';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_rows) r
    left join public.buildings b on b.id = (r->>'building_id')::uuid and b.deleted_at is null
    where b.id is null or b.organization_id is distinct from v_org
  ) then
    raise exception 'Danh sách toà chứa toà không thuộc cùng tổ chức' using errcode = '42501';
  end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'shareholder_profit.lock', null, null);
  if not coalesce(v_authz, false) then
    raise exception 'Không có quyền chốt lợi nhuận (shareholder_profit.lock)' using errcode = '42501';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_building := (v_row->>'building_id')::uuid;

    insert into public.profit_monthly as pm
      (user_id, building_id, period_month, computed_profit, adjusted_profit,
       management_salary, status, locked_at, locked_by, organization_id)
    values
      (v_actor, v_building, v_period,
       coalesce((v_row->>'computed_profit')::numeric, 0),
       coalesce((v_row->>'adjusted_profit')::numeric, 0),
       coalesce((v_row->>'management_salary')::numeric, 0),
       'LOCKED', now(), v_actor, v_org)
    on conflict (building_id, period_month) do update
      set computed_profit  = excluded.computed_profit,
          adjusted_profit  = excluded.adjusted_profit,
          management_salary = excluded.management_salary,
          status = 'LOCKED', locked_at = now(), locked_by = v_actor,
          organization_id = v_org
    returning pm.id into v_pm_id;

    v_pm_ids := v_pm_ids || v_pm_id;
    v_locked := v_locked + 1;
  end loop;

  delete from public.profit_allocations where profit_monthly_id = any (v_pm_ids);
  delete from public.profit_manager_allocations where profit_monthly_id = any (v_pm_ids);

  for v_row in select * from jsonb_array_elements(p_rows) loop
    select pm.id into v_pm_id from public.profit_monthly pm
     where pm.building_id = (v_row->>'building_id')::uuid
       and pm.period_month = v_period;

    for v_alloc in select * from jsonb_array_elements(coalesce(v_row->'allocations', '[]'::jsonb)) loop
      insert into public.profit_allocations
        (user_id, profit_monthly_id, shareholder_id, percent, amount, organization_id)
      values (v_actor, v_pm_id, (v_alloc->>'shareholder_id')::uuid,
              coalesce((v_alloc->>'percent')::numeric, 0),
              coalesce((v_alloc->>'amount')::numeric, 0), v_org);
      v_allocs := v_allocs + 1;
    end loop;

    for v_alloc in select * from jsonb_array_elements(coalesce(v_row->'manager_allocations', '[]'::jsonb)) loop
      continue when coalesce((v_alloc->>'amount')::numeric, 0) = 0;
      insert into public.profit_manager_allocations
        (user_id, profit_monthly_id, manager_id, amount, organization_id)
      values (v_actor, v_pm_id, (v_alloc->>'manager_id')::uuid,
              (v_alloc->>'amount')::numeric, v_org);
    end loop;
  end loop;

  return jsonb_build_object('locked', v_locked, 'allocations', v_allocs);
end;
$_$;








--
-- Name: lock_salary_month_v1(date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_salary_month_v1(p_period_month date, p_managers jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_building uuid;
  v_authz boolean;
  v_key text;
  v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  c_op constant text := 'salary.lock.v1';
  v_now timestamptz := now();
  v_mgr jsonb;
  v_staff uuid;
  v_owner uuid;
  v_monthly_id uuid;
  v_cur_status text;
  v_ledger jsonb;
  v_vid uuid;
  v_v_status text;
  v_v_owned boolean;
  v_locked_count int := 0;
  v_approved_count int := 0;
  v_resp json;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;

  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_period_month is null then raise exception 'Kỳ lương trống'; end if;
  if p_managers is null or jsonb_typeof(p_managers) <> 'array' then
    raise exception 'p_managers phải là JSON array'; end if;

  -- R3-FIX: org SUBJECT-DERIVED (không global-scan toà ảo — sai đa tenant). Org =
  -- tổ chức của nhân viên ĐẦU TIÊN trong p_managers (qua manager_salary_config →
  -- fallback organization_memberships); MỌI nhân viên phải cùng org đó.
  declare
    v_first_staff uuid := nullif(p_managers->0->>'staff_id','')::uuid;
  begin
    if v_first_staff is null then raise exception 'p_managers rỗng hoặc thiếu staff_id'; end if;
    select organization_id into v_org from public.manager_salary_config
     where staff_id = v_first_staff and organization_id is not null
     order by is_active desc, created_at desc limit 1;
    if v_org is null then
      select organization_id into v_org from public.organization_memberships
       where user_id = v_first_staff and status='ACTIVE' limit 1;
    end if;
    if v_org is null then raise exception 'Không xác định được tổ chức của nhân viên'; end if;
    -- mọi staff còn lại phải cùng org
    if exists (
      select 1 from jsonb_array_elements(p_managers) mg
      where nullif(mg->>'staff_id','')::uuid is not null
        and not exists (
          select 1 from public.organization_memberships m2
           where m2.user_id = (mg->>'staff_id')::uuid and m2.organization_id = v_org and m2.status='ACTIVE')
    ) then
      raise exception 'Danh sách nhân viên chứa người khác tổ chức' using errcode='42501';
    end if;
  end;
  -- toà ảo của CHÍNH org đó (tham số scope cho authorize)
  select b.id into v_building
    from public.buildings b join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.organization_id = v_org and b.is_virtual=true and b.deleted_at is null
   order by b.created_at limit 1 for share of o,b;

  perform app_private.lock_org_for_decision_v1(v_org);

  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'salary.lock', v_building, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền chốt lương (salary.lock)' using errcode='42501'; end if;

  -- idempotency toàn-mẻ (mirror salary_payout_v1)
  v_hash := md5(jsonb_build_object('period',p_period_month,'org',v_org,'managers',p_managers)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_period_month::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_period_month::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then
    raise exception 'Writer chốt lương chưa bật' using errcode='55000'; end if;

  -- ═══ D2b — GUARD 1: LỢI NHUẬN THÁNG PHẢI CHỐT TRƯỚC (insight owner) ═══
  -- Phần "đầu tư" trong lương lấy từ chốt lợi nhuận tháng; nếu tháng đó còn
  -- profit_monthly ở DRAFT thì số đầu tư chưa chuẩn → CHẶN, buộc chốt LN trước.
  -- Chỉ áp khi org CÓ dữ liệu lợi nhuận cho kỳ (không có → bỏ qua, org không dùng).
  if exists (
    select 1 from public.profit_monthly pm
     where pm.organization_id = v_org
       and pm.period_month = p_period_month
       and pm.status <> 'LOCKED'
  ) then
    raise exception 'Phải CHỐT LỢI NHUẬN tháng % trước khi chốt lương (phần đầu tư trong lương lấy từ đó)',
      to_char(p_period_month, 'MM/YYYY') using errcode = '55000';
  end if;

  -- ═══ D2b — GUARD 2: PHIẾU HOA HỒNG THIẾU SỔ QUỸ (liệt kê rõ) ═══
  -- Duyệt hoa hồng qua writer chuẩn ĐÒI sổ quỹ. Thay vì fail giữa chừng khó hiểu,
  -- quét trước MỌI phiếu HH sẽ-được-duyệt còn thiếu account_id → báo danh sách mã
  -- phiếu để kế toán bổ sung, KHÔNG chốt tới khi đủ.
  declare
    v_missing text;
  begin
    select string_agg(coalesce(ie.code, left(ie.id::text,8)), ', ' order by ie.code)
      into v_missing
      from public.income_expenses ie
     where ie.deleted_at is null
       and ie.approval_status = 'UNAPPROVED'
       and ie.account_id is null
       and ie.id in (
         select e.value::uuid
           from jsonb_array_elements(p_managers) as mgr(value)
                cross join lateral
                  jsonb_array_elements_text(coalesce(mgr.value->'commission_voucher_ids','[]'::jsonb)) as e(value)
         where e.value is not null and e.value <> ''
       );
    if v_missing is not null then
      raise exception 'Các phiếu hoa hồng sau CHƯA CHỌN SỔ QUỸ — bổ sung rồi mới chốt được: %', v_missing
        using errcode = '55000';
    end if;
  end;

  -- 1) Duyệt phiếu hoa hồng (dedupe toàn bộ managers) — QUA writer, KHÔNG raw UPDATE.
  for v_vid in
    select distinct e.value::uuid
      from jsonb_array_elements(p_managers) as mgr(value)
           cross join lateral
             jsonb_array_elements_text(coalesce(mgr.value->'commission_voucher_ids','[]'::jsonb)) as e(value)
  loop
    if v_vid is null then continue; end if;
    select ie.approval_status, app_private.is_income_expense_flow_owned(ie.id)
      into v_v_status, v_v_owned
      from public.income_expenses ie
     where ie.id = v_vid and ie.deleted_at is null;
    if not found then
      -- TODO-REVIEW R5: phiếu không tồn tại/đã xoá → bỏ qua (legacy .in() cũng no-op).
      continue;
    end if;
    if v_v_status in ('APPROVED','CANCELLED') then
      continue; -- chỉ duyệt UNAPPROVED (bỏ qua đã duyệt / đã huỷ — xem R5)
    end if;

    -- Branch theo CHÍNH predicate mà approve_income_expense_v1 dùng nội bộ
    -- (is_income_expense_flow_owned) — deterministic, không dựa vào so khớp chuỗi
    -- thông báo lỗi. Row canonical → writer canonical; row legacy → approve_voucher.
    -- Mọi lỗi quyền/sổ-quỹ từ 2 writer con đều PROPAGATE (fail-closed) — xem R4.
    if v_v_owned then
      perform public.approve_income_expense_v1(v_vid);
    else
      perform public.approve_voucher(v_vid);
    end if;
    v_approved_count := v_approved_count + 1;
  end loop;

  -- 2) Đóng băng từng quản lý: guard DRAFT→LOCKED, upsert LOCKED, re-snapshot.
  for v_mgr in select value from jsonb_array_elements(p_managers) loop
    v_staff := nullif(v_mgr->>'staff_id','')::uuid;
    if v_staff is null then raise exception 'Thiếu staff_id trong p_managers'; end if;

    -- owner (mirror hook ownerId). TODO-REVIEW R2.
    select user_id into v_owner
      from public.manager_salary_config
     where staff_id = v_staff and is_active = true
       and effective_from <= p_period_month
       and (effective_to is null or effective_to >= p_period_month)
     order by created_at limit 1;
    if v_owner is null then
      select user_id into v_owner from public.super_admins order by created_at limit 1;
    end if;
    if v_owner is null then
      raise exception 'Không xác định được chủ bảng lương cho nhân viên %', v_staff; end if;

    -- guard DRAFT→LOCKED (idempotent: đã LOCKED → bỏ qua)
    select id, status into v_monthly_id, v_cur_status
      from public.salary_monthly
     where staff_id = v_staff and period_month = p_period_month
     for update;
    if v_cur_status = 'LOCKED' then
      continue; -- TODO-REVIEW: re-lock có cần re-snapshot lại không? Hiện no-op.
    end if;

    -- upsert LOCKED — MIRROR cột hook (R1: tin số client; R7: paid clobber; R6: org).
    insert into public.salary_monthly (
      user_id, staff_id, period_month, status, base_salary, work_bonus,
      contract_bonus, commission_total, investment_profit, adjustments_total,
      advances_total, room_rent, gross_total, take_home, paid,
      locked_at, locked_by, organization_id
    ) values (
      v_owner, v_staff, p_period_month, 'LOCKED',
      coalesce((v_mgr->>'base_salary')::numeric, 0),
      coalesce((v_mgr->>'work_bonus')::numeric, 0),
      coalesce((v_mgr->>'contract_bonus')::numeric, 0),
      coalesce((v_mgr->>'commission_total')::numeric, 0),
      coalesce((v_mgr->>'investment_profit')::numeric, 0),
      coalesce((v_mgr->>'adjustments_total')::numeric, 0),
      coalesce((v_mgr->>'advances_total')::numeric, 0),
      coalesce((v_mgr->>'room_rent')::numeric, 0),
      coalesce((v_mgr->>'gross_total')::numeric, 0),
      coalesce((v_mgr->>'take_home')::numeric, 0),
      coalesce((v_mgr->>'paid')::numeric, 0),
      v_now, v_actor, v_org
    )
    on conflict (staff_id, period_month) do update set
      user_id           = excluded.user_id,
      status            = 'LOCKED',
      base_salary       = excluded.base_salary,
      work_bonus        = excluded.work_bonus,
      contract_bonus    = excluded.contract_bonus,
      commission_total  = excluded.commission_total,
      investment_profit = excluded.investment_profit,
      adjustments_total = excluded.adjustments_total,
      advances_total    = excluded.advances_total,
      room_rent         = excluded.room_rent,
      gross_total       = excluded.gross_total,
      take_home         = excluded.take_home,
      paid              = excluded.paid,   -- TODO-REVIEW R7
      locked_at         = v_now,
      locked_by         = v_actor,
      organization_id   = coalesce(public.salary_monthly.organization_id, excluded.organization_id)
    returning id into v_monthly_id;

    -- re-snapshot bảng kê (xoá cũ + ghi lại) — MIRROR cột hook.
    delete from public.salary_work_ledger_snapshot where salary_monthly_id = v_monthly_id;
    v_ledger := coalesce(v_mgr->'ledger', '[]'::jsonb);
    if jsonb_typeof(v_ledger) = 'array' and jsonb_array_length(v_ledger) > 0 then
      insert into public.salary_work_ledger_snapshot (
        user_id, salary_monthly_id, staff_id, item_type, source_id, occurred_date,
        day_label, content, place, job_type_name, is_repair, is_contract,
        base_amount, weekend_amount, after_amount, cash_amount, has_photo,
        bonus_amount, reason, organization_id
      )
      select
        v_owner, v_monthly_id, v_staff,
        r->>'item_type',                              -- NOT NULL: client luôn cấp (R1)
        nullif(r->>'source_id','')::uuid,
        nullif(r->>'occurred_date','')::date,
        r->>'day_label', r->>'content', r->>'place', r->>'job_type_name',
        (r->>'is_repair')::boolean, (r->>'is_contract')::boolean,
        nullif(r->>'base_amount','')::numeric,
        nullif(r->>'weekend_amount','')::numeric,
        nullif(r->>'after_amount','')::numeric,
        nullif(r->>'cash_amount','')::numeric,
        (r->>'has_photo')::boolean,
        nullif(r->>'bonus_amount','')::numeric,
        r->>'reason', v_org
      from jsonb_array_elements(v_ledger) as t(r);
    end if;

    v_locked_count := v_locked_count + 1;
  end loop;

  v_resp := json_build_object(
    'period_month', p_period_month,
    'locked_count', v_locked_count,
    'commission_approved', v_approved_count,
    'state', 'LOCKED');
  -- Ledger-guard đòi set subject_id+response_payload+completed_at CÙNG LÚC.
  -- subject_id = bản ghi lương cuối cùng đã khoá (đại diện; luôn ≥1 do guard).
  update app_private.canonical_write_operations
     set subject_id = coalesce(v_monthly_id, v_actor),
         response_payload = to_jsonb(v_resp), completed_at = now()
   where organization_id=v_org and operation=c_op and subject_scope=p_period_month::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: log_contract_price_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_contract_price_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_building_id     uuid;
  v_room_rent       numeric;
  v_source          text;
  v_rent_before     numeric;
  v_deposit_before  numeric;
  v_rent_changed    boolean;
  v_deposit_changed boolean;
BEGIN
  -- HĐ theo giường (bed_id) không gắn giá phòng → bỏ qua.
  IF NEW.room_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT r.building_id, r.rent_price
    INTO v_building_id, v_room_rent
  FROM public.rooms r
  WHERE r.id = NEW.room_id;

  IF v_building_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_source         := 'CONTRACT_CREATE';
    v_rent_before    := v_room_rent;       -- giá niêm yết của phòng
    v_deposit_before := NEW.rent_price;    -- cọc mặc định = tiền thuê HĐ
  ELSE
    v_source         := 'CONTRACT_EDIT';
    v_rent_before    := OLD.rent_price;
    v_deposit_before := OLD.total_deposit;
  END IF;

  v_rent_changed :=
    COALESCE(NEW.rent_price, 0) IS DISTINCT FROM COALESCE(v_rent_before, 0);
  v_deposit_changed :=
    COALESCE(NEW.total_deposit, 0) IS DISTINCT FROM COALESCE(v_deposit_before, 0);

  IF NOT v_rent_changed AND NOT v_deposit_changed THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.room_price_history (
    room_id, building_id, source, contract_id,
    rent_price_before, rent_price_after,
    deposit_before, deposit_after,
    note, changed_by
  ) VALUES (
    NEW.room_id, v_building_id, v_source, NEW.id,
    v_rent_before, NEW.rent_price,
    v_deposit_before, NEW.total_deposit,
    CASE
      WHEN v_source = 'CONTRACT_CREATE' AND v_rent_changed AND v_deposit_changed
        THEN 'Ký HĐ — giá thuê khác giá phòng & điều chỉnh cọc'
      WHEN v_source = 'CONTRACT_CREATE' AND v_rent_changed
        THEN 'Ký HĐ — giá thuê khác giá mặc định của phòng'
      WHEN v_source = 'CONTRACT_CREATE'
        THEN 'Ký HĐ — điều chỉnh tiền cọc so với tiền thuê'
      WHEN v_rent_changed AND v_deposit_changed
        THEN 'Sửa HĐ — đổi giá thuê & tiền cọc'
      WHEN v_rent_changed
        THEN 'Sửa HĐ — đổi giá thuê'
      ELSE 'Sửa HĐ — đổi tiền cọc'
    END,
    auth.uid()
  );

  RETURN NEW;
END;
$$;








--
-- Name: log_income_expense_action(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_income_expense_action(p_id uuid, p_action text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid;
  v_actor uuid := auth.uid();
  v_actor_name text;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  select organization_id into v_org
    from public.income_expenses where id = p_id;
  if v_org is null then
    raise exception 'Không tìm thấy phiếu hoặc phiếu chưa có tổ chức'
      using errcode = 'P0002';
  end if;
  -- client action allowlist: this RPC must not forge lifecycle semantics
  if p_action not in ('NOTE','CANCELLED_NOTE','MANUAL_LOG') then
    raise exception 'Hành động không được phép qua RPC này' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.email), ''), 'Người dùng')
    into v_actor_name from public.profiles p where p.id = v_actor;
  perform app_private.append_income_expense_event_v1(
    v_org, p_id, p_action, v_actor,
    coalesce(v_actor_name, 'Người dùng'), null, null, p_note);
end;
$$;








--
-- Name: log_issue_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_issue_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO issue_status_history (issue_id, user_id, old_status, new_status, changed_by)
    VALUES (NEW.id, NEW.user_id, OLD.status::text, NEW.status::text, auth.uid());

    -- Update resolved_at if status is RESOLVED or CLOSED
    -- Using actual issue_status enum: NEW, ASSIGNED, IN_PROGRESS, RESOLVED, CLOSED, CANCELLED
    IF NEW.status::text IN ('RESOLVED', 'CLOSED') AND OLD.status::text NOT IN ('RESOLVED', 'CLOSED') THEN
      NEW.resolved_at := CURRENT_TIMESTAMP;
    END IF;

    -- Update first_response_at if moving from NEW to any active status
    IF NEW.status::text IN ('IN_PROGRESS', 'ASSIGNED') AND OLD.status::text = 'NEW' AND NEW.first_response_at IS NULL THEN
      NEW.first_response_at := CURRENT_TIMESTAMP;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: log_public_room_events(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_public_room_events(p_token text, p_events jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_owner   uuid;
  v_count   int;
  v_allowed CONSTANT text[] := ARRAY[
    'session','impression','building_select','view_mode','room_open','image_view',
    'floorplan_view','contact_click','share','download','directions','favorite',
    'deposit_dialog','error'
  ];
BEGIN
  IF p_token IS NULL OR p_token = '' THEN
    RETURN 0;
  END IF;

  -- Token phải tồn tại & chưa thu hồi → resolve owner_id phía server.
  SELECT owner_id INTO v_owner
  FROM public.public_room_share_tokens
  WHERE token = p_token AND revoked = false;
  IF v_owner IS NULL THEN
    RETURN 0;  -- token sai/thu hồi: no-op im lặng
  END IF;

  IF p_events IS NULL
     OR jsonb_typeof(p_events) <> 'array'
     OR jsonb_array_length(p_events) = 0 THEN
    RETURN 0;
  END IF;

  WITH raw AS (
    SELECT t.e
    FROM jsonb_array_elements(p_events) WITH ORDINALITY AS t(e, ord)
    WHERE t.ord <= 50                            -- cắt cứng 50 sự kiện / batch
      AND jsonb_typeof(t.e) = 'object'
  ),
  ins AS (
    INSERT INTO public.public_room_events (
      token, owner_id, session_id, event_type,
      room_id, room_name, room_code, building_id, building_name,
      duration_ms, dwell_ms, metadata, created_at
    )
    SELECT
      p_token,
      v_owner,                                   -- server-resolved; bỏ qua client owner_id
      left(NULLIF(r.e->>'session_id',''), 64),
      r.e->>'event_type',
      CASE WHEN (r.e->>'room_id')     ~ '^[0-9a-fA-F-]{36}$' THEN (r.e->>'room_id')::uuid     END,
      left(r.e->>'room_name', 200),
      left(r.e->>'room_code', 64),
      CASE WHEN (r.e->>'building_id') ~ '^[0-9a-fA-F-]{36}$' THEN (r.e->>'building_id')::uuid END,
      left(r.e->>'building_name', 200),
      CASE WHEN jsonb_typeof(r.e->'duration_ms')='number'
           THEN LEAST(GREATEST((r.e->>'duration_ms')::numeric::int, 0), 86400000) END,
      CASE WHEN jsonb_typeof(r.e->'dwell_ms')='number'
           THEN LEAST(GREATEST((r.e->>'dwell_ms')::numeric::int, 0), 86400000) END,
      CASE
        WHEN r.e->'metadata' IS NULL OR jsonb_typeof(r.e->'metadata') <> 'object'
          THEN '{}'::jsonb
        WHEN length((r.e->'metadata')::text) > 8192
          THEN jsonb_build_object('_truncated', true)
        ELSE r.e->'metadata'
      END,
      now()                                      -- tin đồng hồ server; bỏ qua client created_at
    FROM raw r
    WHERE NULLIF(r.e->>'session_id','') IS NOT NULL
      AND r.e->>'event_type' = ANY(v_allowed)    -- lọc bỏ event_type lạ (tránh CHECK abort)
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM ins;

  RETURN COALESCE(v_count, 0);
EXCEPTION
  WHEN others THEN
    RETURN 0;  -- không bao giờ lộ nội bộ cho anon
END;
$_$;








--
-- Name: FUNCTION log_public_room_events(p_token text, p_events jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_public_room_events(p_token text, p_events jsonb) IS 'Anon batch logger cho /r/:token. Validate token (chưa revoke), resolve owner_id
server-side, cắt batch ≤50, clamp string/duration/metadata, lọc event_type lạ.
Trả số dòng ghi. KHÔNG tin owner_id/created_at từ client.';








--
-- Name: log_room_price_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_room_price_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rent_changed    boolean;
  v_deposit_changed boolean;
BEGIN
  v_rent_changed :=
    COALESCE(NEW.rent_price, 0) IS DISTINCT FROM COALESCE(OLD.rent_price, 0);
  v_deposit_changed :=
    COALESCE(NEW.deposit_amount, 0) IS DISTINCT FROM COALESCE(OLD.deposit_amount, 0);

  IF NOT v_rent_changed AND NOT v_deposit_changed THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.room_price_history (
    room_id, building_id, source, contract_id,
    rent_price_before, rent_price_after,
    deposit_before, deposit_after,
    note, changed_by
  ) VALUES (
    NEW.id, NEW.building_id, 'ROOM_EDIT', NULL,
    OLD.rent_price, NEW.rent_price,
    OLD.deposit_amount, NEW.deposit_amount,
    CASE
      WHEN v_rent_changed AND v_deposit_changed THEN 'Sửa phòng — đổi giá thuê & tiền cọc mặc định'
      WHEN v_rent_changed THEN 'Sửa phòng — đổi giá thuê mặc định'
      ELSE 'Sửa phòng — đổi tiền cọc mặc định'
    END,
    auth.uid()
  );

  RETURN NEW;
END;
$$;








--
-- Name: lucky_admin_add_team_v1(uuid, text, integer, integer, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_add_team_v1(p_event uuid, p_name text, p_deals integer DEFAULT 1, p_top_rank integer DEFAULT NULL::integer, p_top_prize numeric DEFAULT NULL::numeric, p_in_wheel boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_row public.lucky_event_teams;
begin
  perform public.lucky_admin_assert_event_v1(p_event);
  if p_name is null or btrim(p_name) = '' then
    raise exception 'Tên đội không được rỗng.' using errcode = '22023';
  end if;

  insert into public.lucky_event_teams (event_id, name, deals, top_rank, top_prize_amount, in_wheel)
  values (p_event, btrim(p_name), coalesce(p_deals, 1), p_top_rank, p_top_prize, coalesce(p_in_wheel, true))
  returning * into v_row;

  return jsonb_build_object('ok', true, 'teamId', v_row.id, 'code', v_row.code);
end;
$$;








--
-- Name: lucky_admin_assert_event_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_assert_event_v1(p_event uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_org uuid := public.lucky_admin_org_v1();
begin
  if v_org is null then
    raise exception 'Bạn không có quyền quản trị sự kiện.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.lucky_events where id = p_event and organization_id = v_org) then
    raise exception 'Sự kiện không thuộc tổ chức của bạn.' using errcode = '42501';
  end if;
  return v_org;
end;
$$;








--
-- Name: lucky_admin_delete_team_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_delete_team_v1(p_team uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event uuid;
begin
  select event_id into v_event from public.lucky_event_teams where id = p_team;
  if v_event is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  perform public.lucky_admin_assert_event_v1(v_event);

  -- Đội đang là winner → FK on delete set null tự gỡ khỏi lucky_events.
  delete from public.lucky_event_teams where id = p_team;
  return jsonb_build_object('ok', true);
end;
$$;








--
-- Name: lucky_admin_force_draw_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_force_draw_v1(p_event uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_status text;
  v_winner uuid;
begin
  perform public.lucky_admin_assert_event_v1(p_event);

  select status into v_status from public.lucky_events where id = p_event for update;
  if v_status = 'drawn' then
    return public.lucky_event_payload_v1(p_event);
  end if;
  if v_status <> 'open' then
    return jsonb_build_object('ok', false, 'reason', 'closed');
  end if;

  select id into v_winner
  from public.lucky_event_teams
  where event_id = p_event and in_wheel and checked_in_at is not null
  order by gen_random_uuid()
  limit 1;

  if v_winner is null then
    return jsonb_build_object('ok', false, 'reason', 'no_checked_in_teams');
  end if;

  update public.lucky_events
     set status = 'drawn', winner_team_id = v_winner,
         drawn_at = now(), updated_at = now()
   where id = p_event;

  return public.lucky_event_payload_v1(p_event);
end;
$$;








--
-- Name: lucky_admin_get_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_get_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_org uuid := public.lucky_admin_org_v1();
  v_out jsonb;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền quản trị sự kiện.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(ev order by (ev->>'createdAt') desc), '[]'::jsonb) into v_out
  from (
    select jsonb_build_object(
      'id', e.id,
      'slug', e.slug,
      'title', e.title,
      'prizeLabel', e.prize_label,
      'prizeAmount', e.prize_amount,
      'drawAt', e.draw_at,
      'status', e.status,
      'drawnAt', e.drawn_at,
      'winnerTeamId', e.winner_team_id,
      'createdAt', e.created_at,
      'serverNow', now(),
      'teams', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', t.id, 'name', t.name, 'deals', t.deals, 'code', t.code,
          'topRank', t.top_rank, 'topPrizeAmount', t.top_prize_amount,
          'inWheel', t.in_wheel,
          'checkedIn', t.checked_in_at is not null, 'checkedInAt', t.checked_in_at,
          'payoutAccount', t.payout_account,
          'payoutBank', t.payout_bank,
          'payoutHolder', t.payout_holder,
          'proofs', t.proofs,
          'proofUploadedAt', t.proof_uploaded_at
        ) order by coalesce(t.top_rank, 99), t.created_at)
        from public.lucky_event_teams t where t.event_id = e.id), '[]'::jsonb)
    ) as ev
    from public.lucky_events e
    where e.organization_id = v_org
  ) s;

  return jsonb_build_object('ok', true, 'organizationId', v_org, 'events', v_out);
end;
$$;








--
-- Name: lucky_admin_org_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_org_v1() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_org uuid;
begin
  if (select auth.uid()) is null then return null; end if;
  select m.organization_id into v_org
    from public.organization_memberships m
    join public.organizations o on o.id = m.organization_id and o.status = 'ACTIVE'
   where m.user_id = (select auth.uid())
     and m.status = 'ACTIVE'
     and m.member_type in ('OWNER', 'STAFF')
   order by coalesce(o.is_demo, false), m.organization_id
   limit 1;
  return v_org;
end;
$$;








--
-- Name: lucky_admin_reset_draw_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_reset_draw_v1(p_event uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  perform public.lucky_admin_assert_event_v1(p_event);
  update public.lucky_events
     set status = 'open', winner_team_id = null, drawn_at = null, updated_at = now()
   where id = p_event;
  return jsonb_build_object('ok', true);
end;
$$;








--
-- Name: lucky_admin_update_team_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_update_team_v1(p_team uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event uuid;
  v_code text;
begin
  select event_id into v_event from public.lucky_event_teams where id = p_team;
  if v_event is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  perform public.lucky_admin_assert_event_v1(v_event);

  update public.lucky_event_teams set
    name             = coalesce(nullif(btrim(p->>'name'), ''), name),
    deals            = coalesce((p->>'deals')::int, deals),
    top_rank         = case when p ? 'topRank' then nullif(p->>'topRank', '')::int else top_rank end,
    top_prize_amount = case when p ? 'topPrizeAmount' then nullif(p->>'topPrizeAmount', '')::numeric else top_prize_amount end,
    in_wheel         = coalesce((p->>'inWheel')::boolean, in_wheel),
    checked_in_at    = case
                         when p ? 'checkedIn' and (p->>'checkedIn')::boolean then coalesce(checked_in_at, now())
                         when p ? 'checkedIn' then null
                         else checked_in_at
                       end,
    code             = case when coalesce((p->>'regenCode')::boolean, false) then public.lucky_gen_code() else code end
  where id = p_team
  returning code into v_code;

  return jsonb_build_object('ok', true, 'teamId', p_team, 'code', v_code);
end;
$$;








--
-- Name: lucky_admin_upsert_event_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_admin_upsert_event_v1(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_org uuid := public.lucky_admin_org_v1();
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_slug text := lower(btrim(coalesce(p->>'slug', '')));
begin
  if v_org is null then
    raise exception 'Bạn không có quyền quản trị sự kiện.' using errcode = '42501';
  end if;

  if v_slug <> '' and (v_slug !~ '^[a-z0-9][a-z0-9-]{1,31}$' or v_slug = 'admin') then
    raise exception 'Đường dẫn chỉ gồm chữ thường, số và gạch ngang (2–32 ký tự), không được là "admin".'
      using errcode = '22023';
  end if;
  if v_slug <> '' and exists (
    select 1 from public.lucky_events where slug = v_slug and (v_id is null or id <> v_id)
  ) then
    raise exception 'Đường dẫn "%" đã có sự kiện khác dùng rồi.', v_slug using errcode = '23505';
  end if;

  if v_id is null then
    insert into public.lucky_events (organization_id, title, prize_label, prize_amount, draw_at, slug)
    values (
      v_org,
      coalesce(nullif(p->>'title', ''), 'IHOME · Trao thưởng'),
      coalesce(nullif(p->>'prizeLabel', ''), 'Giải may mắn'),
      coalesce((p->>'prizeAmount')::numeric, 500000),
      nullif(p->>'drawAt', '')::timestamptz,
      nullif(v_slug, '')
    )
    returning id into v_id;
  else
    perform public.lucky_admin_assert_event_v1(v_id);
    update public.lucky_events set
      title        = coalesce(nullif(p->>'title', ''), title),
      prize_label  = coalesce(nullif(p->>'prizeLabel', ''), prize_label),
      prize_amount = coalesce((p->>'prizeAmount')::numeric, prize_amount),
      slug         = case when v_slug <> '' then v_slug else slug end,
      draw_at      = case when p ? 'drawAt' then nullif(p->>'drawAt', '')::timestamptz else draw_at end,
      status       = case when p ? 'status' and (p->>'status') in ('open', 'closed') then p->>'status' else status end,
      updated_at   = now()
    where id = v_id;
  end if;

  return jsonb_build_object('ok', true, 'eventId', v_id,
                            'slug', (select slug from public.lucky_events where id = v_id));
end;
$_$;








--
-- Name: lucky_checkin_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_checkin_v1(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_team uuid;
  v_event uuid;
  v_status text;
  v_draw_at timestamptz;
  v_checked timestamptz;
begin
  if p_code is null or p_code = '' then
    return jsonb_build_object('ok', false, 'reason', 'bad_code');
  end if;

  select t.id, t.event_id, e.status, e.draw_at, t.checked_in_at
    into v_team, v_event, v_status, v_draw_at, v_checked
  from public.lucky_event_teams t
  join public.lucky_events e on e.id = t.event_id
  where t.code = p_code and e.status <> 'closed'
  order by e.created_at desc
  limit 1
  for update of t;

  if v_team is null then
    return jsonb_build_object('ok', false, 'reason', 'bad_code');
  end if;

  -- Cửa đã đóng: đã quay xong, HOẶC đã qua giờ hẹn mở thưởng.
  if v_checked is null
     and (v_status = 'drawn' or (v_draw_at is not null and now() >= v_draw_at)) then
    return jsonb_build_object('ok', false, 'reason', 'too_late');
  end if;

  update public.lucky_event_teams
     set checked_in_at = coalesce(checked_in_at, now())
   where id = v_team;

  return public.lucky_event_payload_v1(v_event, v_team);
end;
$$;








--
-- Name: FUNCTION lucky_checkin_v1(p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lucky_checkin_v1(p_code text) IS 'Điểm danh bằng mã 6 số. Trả too_late nếu đội CHƯA điểm danh mà đã qua draw_at hoặc sự kiện đã quay; đội đã điểm danh trước đó vẫn vào xem được.';








--
-- Name: lucky_draw_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_draw_v1(p_event uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_status text;
  v_draw_at timestamptz;
  v_winner uuid;
begin
  select status, draw_at into v_status, v_draw_at
  from public.lucky_events
  where id = p_event
  for update;

  if v_status is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_status = 'drawn' then
    return public.lucky_event_payload_v1(p_event);  -- idempotent: trả kết quả đã chốt
  end if;
  if v_status <> 'open' then
    return jsonb_build_object('ok', false, 'reason', 'closed');
  end if;
  -- draw_at NULL = quay tay, cho phép. Có hẹn giờ thì phải tới giờ.
  if v_draw_at is not null and now() < v_draw_at then
    return jsonb_build_object('ok', false, 'reason', 'not_time');
  end if;

  select id into v_winner
  from public.lucky_event_teams
  where event_id = p_event and in_wheel and checked_in_at is not null
  order by gen_random_uuid()
  limit 1;

  if v_winner is null then
    return jsonb_build_object('ok', false, 'reason', 'no_checked_in_teams');
  end if;

  update public.lucky_events
     set status = 'drawn', winner_team_id = v_winner,
         drawn_at = now(), updated_at = now()
   where id = p_event;

  return public.lucky_event_payload_v1(p_event);
end;
$$;








--
-- Name: FUNCTION lucky_draw_v1(p_event uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lucky_draw_v1(p_event uuid) IS 'Chốt đội trúng MỘT LẦN. draw_at NULL = quay tay (màn quay công khai bấm được); có draw_at thì phải tới giờ. Gọi lại khi đã drawn chỉ trả kết quả cũ.';








--
-- Name: lucky_event_open_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_event_open_v1(p_folder text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_id uuid;
begin
  if p_folder is null or p_folder = '' then
    return false;
  end if;
  begin
    v_id := p_folder::uuid;
  exception when others then
    return false;                      -- thư mục rác, không phải uuid
  end;
  return exists (
    select 1 from public.lucky_events
    where id = v_id and status <> 'closed'
  );
end;
$$;








