--
-- Name: lucky_event_payload_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_event_payload_v1(p_event uuid, p_viewer_team uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event jsonb;
  v_teams jsonb;
begin
  select jsonb_build_object(
    'id', e.id,
    'slug', e.slug,
    'title', e.title,
    'prizeLabel', e.prize_label,
    'prizeAmount', e.prize_amount,
    'drawAt', e.draw_at,
    'status', e.status,
    'drawnAt', e.drawn_at,
    'winnerTeamId', e.winner_team_id,
    'serverNow', now()
  ) into v_event
  from public.lucky_events e
  where e.id = p_event;

  if v_event is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', t.id,
    'name', t.name,
    'deals', t.deals,
    'topRank', t.top_rank,
    'topPrizeAmount', t.top_prize_amount,
    'inWheel', t.in_wheel,
    'checkedIn', t.checked_in_at is not null,
    'checkedInAt', t.checked_in_at,
    'isMine', t.id = p_viewer_team,
    'payoutAccount', case when t.id = p_viewer_team then t.payout_account end,
    'payoutBank',    case when t.id = p_viewer_team then t.payout_bank end,
    'payoutHolder',  case when t.id = p_viewer_team then t.payout_holder end,
    'proofs',        case when t.id = p_viewer_team then t.proofs else '[]'::jsonb end,
    'proofCount',    jsonb_array_length(t.proofs)
  ) order by coalesce(t.top_rank, 99), t.created_at), '[]'::jsonb)
  into v_teams
  from public.lucky_event_teams t
  where t.event_id = p_event;

  return jsonb_build_object('ok', true, 'event', v_event, 'teams', v_teams);
end;
$$;








--
-- Name: lucky_gen_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_gen_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  candidate text;
  tries int := 0;
begin
  loop
    -- 6 chữ số, cho phép 0 dẫn đầu ("042919" hợp lệ).
    candidate := lpad((floor(random() * 1000000))::int::text, 6, '0');
    exit when not exists (select 1 from public.lucky_event_teams where code = candidate);
    tries := tries + 1;
    if tries >= 20 then
      -- Không gian 10^6 gần cạn (không bao giờ xảy ra với vài chục đội) → nới 8 số.
      candidate := lpad((floor(random() * 100000000))::int::text, 8, '0');
      exit;
    end if;
  end loop;
  return candidate;
end;
$$;








--
-- Name: lucky_gen_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_gen_slug() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  alphabet text := 'abcdefghijkmnpqrstuvwxyz23456789';   -- bỏ o/l/0/1 dễ nhầm
  alen int := length(alphabet);
  candidate text;
  raw text;
  bytes bytea;
  i int;
  tries int := 0;
begin
  loop
    raw := '';
    while length(raw) < 12 loop
      raw := raw || replace(gen_random_uuid()::text, '-', '');
    end loop;
    bytes := decode(substr(raw, 1, 12), 'hex');
    candidate := '';
    for i in 0..5 loop
      candidate := candidate || substr(alphabet, (get_byte(bytes, i) % alen) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.lucky_events where slug = candidate);
    tries := tries + 1;
    exit when tries >= 20;
  end loop;
  return candidate;
end;
$$;








--
-- Name: lucky_public_state_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_public_state_v1(p_event uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_slug text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event uuid := p_event;
  v_team uuid;
begin
  -- Slug → event id (ưu tiên thấp hơn p_event nếu cả hai cùng gửi).
  if v_event is null and p_slug is not null and p_slug <> '' then
    select id into v_event from public.lucky_events where slug = lower(btrim(p_slug));
    if v_event is null then
      return jsonb_build_object('ok', false, 'reason', 'not_found');
    end if;
  end if;

  if p_code is not null and p_code <> '' then
    select t.event_id, t.id into v_event, v_team
    from public.lucky_event_teams t
    join public.lucky_events e on e.id = t.event_id
    where t.code = p_code and e.status <> 'closed'
    order by e.created_at desc
    limit 1;
    if v_team is null then
      return jsonb_build_object('ok', false, 'reason', 'bad_code');
    end if;
    -- Mã thuộc sự kiện khác với link đang mở → link thắng, mã bị từ chối.
    if v_event is not null and p_event is not null and v_event <> p_event then
      return jsonb_build_object('ok', false, 'reason', 'code_other_event');
    end if;
  end if;

  if v_event is null then
    return jsonb_build_object('ok', false, 'reason', 'missing_event');
  end if;

  return public.lucky_event_payload_v1(v_event, v_team);
end;
$$;








--
-- Name: lucky_save_payout_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_save_payout_v1(p_code text, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_team uuid;
  v_event uuid;
  v_checked timestamptz;
  v_proofs jsonb;
begin
  if p_code is null or p_code = '' then
    return jsonb_build_object('ok', false, 'reason', 'bad_code');
  end if;

  select t.id, t.event_id, t.checked_in_at
    into v_team, v_event, v_checked
  from public.lucky_event_teams t
  join public.lucky_events e on e.id = t.event_id
  where t.code = p_code and e.status <> 'closed'
  order by e.created_at desc
  limit 1
  for update of t;

  if v_team is null then
    return jsonb_build_object('ok', false, 'reason', 'bad_code');
  end if;
  if v_checked is null then
    return jsonb_build_object('ok', false, 'reason', 'not_checked_in');
  end if;

  -- Lọc danh sách gửi lên: chỉ giữ file nằm ĐÚNG thư mục của sự kiện này
  -- (chặn trỏ sang giấy cọc của sự kiện/đội khác), tối đa 10 tấm.
  if p ? 'proofs' and jsonb_typeof(p->'proofs') = 'array' then
    select coalesce(jsonb_agg(x order by ord), '[]'::jsonb) into v_proofs
    from (
      select jsonb_build_object(
               'path', el->>'path',
               'name', left(coalesce(nullif(btrim(el->>'name'), ''), 'giay-coc'), 120),
               'at',   coalesce(el->>'at', now()::text)) as x,
             ord
      from jsonb_array_elements(p->'proofs') with ordinality as t2(el, ord)
      where el->>'path' like v_event::text || '/%'
      limit 10
    ) s;
  else
    v_proofs := null;
  end if;

  update public.lucky_event_teams set
    payout_account = case when p ? 'payoutAccount' then nullif(btrim(p->>'payoutAccount'), '') else payout_account end,
    payout_bank    = case when p ? 'payoutBank'    then nullif(btrim(p->>'payoutBank'), '')    else payout_bank end,
    payout_holder  = case when p ? 'payoutHolder'  then nullif(btrim(p->>'payoutHolder'), '')  else payout_holder end,
    proofs         = coalesce(v_proofs, proofs),
    -- Giữ 2 cột cũ đồng bộ với tấm đầu tiên cho dữ liệu/báo cáo cũ.
    proof_path     = case when v_proofs is null then proof_path else v_proofs->0->>'path' end,
    proof_name     = case when v_proofs is null then proof_name else v_proofs->0->>'name' end,
    proof_uploaded_at = case
                          when v_proofs is null then proof_uploaded_at
                          when jsonb_array_length(v_proofs) = 0 then null
                          else now()
                        end
  where id = v_team;

  return public.lucky_event_payload_v1(v_event, v_team);
end;
$$;








--
-- Name: FUNCTION lucky_save_payout_v1(p_code text, p jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lucky_save_payout_v1(p_code text, p jsonb) IS 'Đội tự nộp hồ sơ nhận thưởng. `proofs` là NGUYÊN danh sách giấy cọc (thay thế toàn bộ, tối đa 10 tấm); mọi path phải nằm trong thư mục của đúng sự kiện.';








--
-- Name: lucky_set_event_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_set_event_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.slug is null or btrim(new.slug) = '' then
    new.slug := public.lucky_gen_slug();
  else
    new.slug := lower(btrim(new.slug));
  end if;
  return new;
end;
$$;








--
-- Name: lucky_set_team_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lucky_set_team_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.code is null or new.code = '' then
    new.code := public.lucky_gen_code();
  end if;
  return new;
end;
$$;








--
-- Name: manager_collection_cycle_report(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_collection_cycle_report(p_manager_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mgr        uuid;
  v_mgr_name   text;
  v_full       boolean;
  v_bids       uuid[];
  v_billed     numeric;
  v_outstanding numeric;
  v_collected_all numeric;
  v_collected_period numeric;
  v_handed     numeric;
  v_buildings  jsonb;
  v_timeline   jsonb := '[]'::jsonb;
  v_prev       date;
  v_this       date;
  v_seg        numeric;
  v_ar         numeric;
  rec          record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  v_mgr := COALESCE(p_manager_id, auth.uid());
  IF v_mgr <> auth.uid() AND NOT (public.is_super_admin() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền xem báo cáo của người khác';
  END IF;
  p_from := COALESCE(p_from, date_trunc('month', public.org_today_v1(NULL))::date);
  p_to   := COALESCE(p_to, public.org_today_v1(NULL));

  SELECT COALESCE(full_name, '') INTO v_mgr_name FROM profiles WHERE id = v_mgr;

  -- ── Phạm vi tòa của quản lý ──
  v_full := EXISTS (SELECT 1 FROM staff_assignments sa
                     WHERE sa.staff_id = v_mgr AND sa.building_id IS NULL AND sa.area_id IS NULL)
            OR EXISTS (SELECT 1 FROM super_admins s WHERE s.user_id = v_mgr);
  IF v_full THEN
    v_bids := ARRAY(SELECT id FROM buildings WHERE deleted_at IS NULL);
  ELSE
    v_bids := ARRAY(
      SELECT DISTINCT bid FROM (
        SELECT sa.building_id AS bid FROM staff_assignments sa
         WHERE sa.staff_id = v_mgr AND sa.building_id IS NOT NULL
        UNION
        SELECT ab.building_id FROM staff_assignments sa
          JOIN area_buildings ab ON ab.area_id = sa.area_id
         WHERE sa.staff_id = v_mgr AND sa.area_id IS NOT NULL
      ) x WHERE bid IS NOT NULL
    );
  END IF;
  -- Chỉ giữ tòa THẬT còn tồn tại (bỏ assignment trỏ tòa đã xóa/mồ côi + tòa ảo "Chung").
  v_bids := ARRAY(SELECT b.id FROM buildings b
                   WHERE b.id = ANY(v_bids) AND b.deleted_at IS NULL
                     AND NOT COALESCE(b.is_virtual, false)
                     AND app_private.building_org_visible_v1(b.id));
  IF v_bids IS NULL THEN v_bids := ARRAY[]::uuid[]; END IF;

  -- ── Tổng hiện tại (chỉ HĐ đã chốt: bỏ DRAFT/PENDING/CANCELLED) ──
  SELECT COALESCE(sum(total_amount), 0), COALESCE(sum(remaining_amount), 0), COALESCE(sum(paid_amount), 0)
    INTO v_billed, v_outstanding, v_collected_all
    FROM invoices
   WHERE building_id = ANY(v_bids) AND deleted_at IS NULL
     AND status NOT IN ('DRAFT','PENDING_APPROVAL','CANCELLED');

  -- ── Đã thu trong kỳ (public.active_payments của tòa) ──
  SELECT COALESCE(sum(p.collected_amount), 0) INTO v_collected_period
    FROM (
      SELECT * FROM public.payment_receipt_events
      WHERE payment_method <> 'CT'
    ) p JOIN invoices i ON i.id = p.invoice_id
   WHERE i.building_id = ANY(v_bids) AND i.deleted_at IS NULL
     AND p.payment_date BETWEEN p_from AND p_to;

  -- ── Đã bàn giao trong kỳ (net, giver = quản lý) ──
  SELECT COALESCE(sum(total_amount), 0) INTO v_handed
    FROM cash_handovers
   WHERE giver_id = v_mgr AND status = 'CONFIRMED'
     AND confirmed_at::date BETWEEN p_from AND p_to;

  -- ── Theo từng tòa (hiện tại) ──
  SELECT jsonb_agg(jsonb_build_object(
           'building_id', b.id, 'name', b.name,
           'total_billed', bs.billed, 'collected', bs.paid,
           'outstanding', bs.remaining, 'unpaid_count', bs.unpaid
         ) ORDER BY bs.remaining DESC NULLS LAST, b.name)
    INTO v_buildings
    FROM buildings b
    JOIN LATERAL (
      SELECT COALESCE(sum(i.total_amount), 0) AS billed,
             COALESCE(sum(i.paid_amount), 0) AS paid,
             COALESCE(sum(i.remaining_amount), 0) AS remaining,
             count(*) FILTER (WHERE i.remaining_amount > 0) AS unpaid
        FROM invoices i
       WHERE i.building_id = b.id AND i.deleted_at IS NULL
         AND i.status NOT IN ('DRAFT','PENDING_APPROVAL','CANCELLED')
    ) bs ON true
   WHERE b.id = ANY(v_bids) AND b.deleted_at IS NULL;

  -- ── Timeline: từng mốc bàn giao (tăng dần) + chốt CHƯA THU point-in-time ──
  v_prev := p_from - 1;   -- để đoạn đầu = [p_from, mốc1]
  FOR rec IN
    SELECT ch.code, ch.confirmed_at, ch.total_amount AS net, fa.name AS from_account
      FROM cash_handovers ch
      LEFT JOIN accounts fa ON fa.id = ch.from_account_id
     WHERE ch.giver_id = v_mgr AND ch.status = 'CONFIRMED'
       AND ch.confirmed_at::date BETWEEN p_from AND p_to
     ORDER BY ch.confirmed_at ASC
  LOOP
    v_this := rec.confirmed_at::date;
    SELECT COALESCE(sum(p.collected_amount), 0) INTO v_seg
      FROM (
        SELECT * FROM public.payment_receipt_events
        WHERE payment_method <> 'CT'
      ) p JOIN invoices i ON i.id = p.invoice_id
     WHERE i.building_id = ANY(v_bids) AND i.deleted_at IS NULL
       AND p.payment_date > v_prev AND p.payment_date <= v_this;
    -- Chưa thu TẠI NGÀY v_this: HĐ tồn tại (issue_date ≤ v_this), trừ public.active_payments ≤ v_this.
    -- Cộng RÒNG (không floor 0) để đồng quy ước với remaining_amount ("chưa thu hiện tại"):
    -- HĐ trả dư cấn trừ HĐ nợ khác, khớp cách app tính công nợ.
    SELECT COALESCE(sum(i.total_amount - COALESCE(pp.paid, 0)), 0) INTO v_ar
      FROM invoices i
      LEFT JOIN LATERAL (
        SELECT sum(p.applied_amount) AS paid
        FROM public.payment_receipt_events p
         WHERE p.invoice_id = i.id AND p.payment_date <= v_this
      ) pp ON true
     WHERE i.building_id = ANY(v_bids) AND i.deleted_at IS NULL
       AND i.status NOT IN ('DRAFT','PENDING_APPROVAL','CANCELLED')
       AND i.issue_date <= v_this;
    v_timeline := v_timeline || jsonb_build_object(
      'type', 'HANDOVER', 'code', rec.code, 'confirmed_at', rec.confirmed_at,
      'net', rec.net, 'from_account', rec.from_account,
      'collected_in_segment', v_seg, 'outstanding_as_of', v_ar);
    v_prev := v_this;
  END LOOP;

  -- ── Đoạn hiện tại (từ mốc cuối → p_to) ──
  SELECT COALESCE(sum(p.collected_amount), 0) INTO v_seg
      FROM (
        SELECT * FROM public.payment_receipt_events
        WHERE payment_method <> 'CT'
      ) p JOIN invoices i ON i.id = p.invoice_id
   WHERE i.building_id = ANY(v_bids) AND i.deleted_at IS NULL
     AND p.payment_date > v_prev AND p.payment_date <= p_to;
  v_timeline := v_timeline || jsonb_build_object(
    'type', 'CURRENT', 'confirmed_at', NULL, 'code', NULL, 'net', NULL, 'from_account', NULL,
    'collected_in_segment', v_seg, 'outstanding_as_of', v_outstanding);

  RETURN jsonb_build_object(
    'manager', jsonb_build_object('id', v_mgr, 'name', v_mgr_name),
    'from', p_from, 'to', p_to,
    'building_count', COALESCE(array_length(v_bids, 1), 0),
    'summary', jsonb_build_object(
      'collected_period', v_collected_period,
      'handed_over_period', v_handed,
      'outstanding_current', v_outstanding,
      'total_billed_current', v_billed,
      'collected_all', v_collected_all),
    'buildings', COALESCE(v_buildings, '[]'::jsonb),
    'timeline', v_timeline);
END;
$$;








--
-- Name: manager_salary_payout_v1(uuid, numeric, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_salary_payout_v1(p_manager_id uuid, p_amount numeric, p_account_id uuid, p_voucher_date date, p_note text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_org uuid; v_building uuid; v_type uuid; v_membership uuid;
  v_subject_name text;
  v_authz boolean; v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype; v_route text;
  v_voucher uuid; v_req uuid; v_name text; v_resp json;
  c_op constant text := 'shareholder_profit.pay_manager.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;

  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_amount is null or p_amount <= 0 or round(p_amount,2) <> p_amount then
    raise exception 'Số tiền lương điều hành không hợp lệ'; end if;
  if p_account_id is null then
    raise exception 'Thiếu sổ quỹ để chi lương điều hành' using errcode='42501'; end if;

  -- [D1] Org resolve từ SUBJECT (quản lý). profit_managers.organization_id org_null=0.
  select m.organization_id, coalesce(nullif(btrim(m.name),''), 'Quản lý')
    into v_org, v_subject_name
    from public.profit_managers m
   where m.id = p_manager_id and m.deleted_at is null
   for share;
  if not found or v_org is null then
    raise exception 'Không tìm thấy quản lý hoặc quản lý chưa gán tổ chức' using errcode='42501';
  end if;

  select b.id into v_building
    from public.buildings b
    join public.organizations o on o.id = b.organization_id and o.status = 'ACTIVE'
   where b.organization_id = v_org and b.is_virtual = true and b.deleted_at is null
   order by b.created_at limit 1
   for share of o, b;
  if v_building is null then
    raise exception 'Tổ chức chưa có toà ảo (Chung) để hạch toán phiếu lương điều hành' using errcode='55000';
  end if;

  -- FORK B: quyền RIÊNG shareholder_profit.pay_manager.
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'shareholder_profit.pay_manager', v_building, p_account_id);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền chi lương quản lý (shareholder_profit.pay_manager)' using errcode='42501'; end if;
  select m.id into v_membership from public.organization_memberships m
   where m.user_id=v_actor and m.organization_id=v_org and m.status='ACTIVE' limit 1 for share;
  if v_membership is null then raise exception 'Không còn là thành viên tổ chức' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object(
    'manager', p_manager_id, 'amount', round(p_amount,2),
    'account', p_account_id, 'voucher_date', p_voucher_date, 'org', v_org)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_manager_id::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_manager_id::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer lương điều hành chưa bật' using errcode='55000'; end if;

  select coalesce(nullif(btrim(full_name),''), nullif(btrim(email),''), 'Người dùng')
    into v_actor_name from public.profiles where id = v_actor;

  -- Hạng mục 'Lương điều hành' (category 'Chia lợi nhuận' — mirror client hook).
  select id into v_type from public.income_expense_types
   where organization_id = v_org and lower(type) = 'expense' and name = 'Lương điều hành'
   order by created_at limit 1;
  if v_type is null then
    insert into public.income_expense_types
      (user_id, organization_id, name, type, category, is_default, is_deposit)
    values (v_actor, v_org, 'Lương điều hành', 'expense', 'Chia lợi nhuận', false, false)
    returning id into v_type;
  end if;

  v_name := coalesce(nullif(btrim(coalesce(p_note,'')),''), 'Lương điều hành: ' || v_subject_name);

  insert into public.income_expenses (
    user_id, organization_id, creator_name, type, name,
    building_id, account_id, profit_manager_id,
    business_result_accounting, approval_status, voucher_date,
    attachments, repeat_cycle, repeat_infinity, repeat_count, repeat_remaining,
    source_payload_hash
  ) values (
    v_actor, v_org, coalesce(v_actor_name,'Người dùng'), 'EXPENSE', v_name,
    v_building, p_account_id, p_manager_id,
    false, 'UNAPPROVED', p_voucher_date,
    '[]'::jsonb, 'NONE', false, 0, 0,
    v_hash
  ) returning id into v_voucher;

  insert into public.income_expense_items (
    income_expense_id, organization_id, income_expense_type_id,
    description, quantity, unit_price, start_date, end_date
  ) values (
    v_voucher, v_org, v_type,
    nullif(btrim(coalesce(p_note,'')),''), 1, round(p_amount,2), p_voucher_date, p_voucher_date
  );

  v_req := app_private.submit_financial_request_v1(v_voucher, v_membership, v_actor, v_key || '-sub');

  v_resp := json_build_object(
    'manager_salary_voucher_id', v_voucher, 'approval_request_id', v_req,
    'manager_id', p_manager_id, 'state', 'PENDING_APPROVAL');
  update app_private.canonical_write_operations
     set subject_id=v_voucher, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op and subject_scope=p_manager_id::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: mark_income_expense_disputed_v2(uuid, bigint, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_income_expense_disputed_v2(p_voucher uuid, p_expected_review_version bigint, p_owner_membership uuid, p_reason text, p_deadline timestamp with time zone, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'o', p_owner_membership, 'r', p_reason, 'd', p_deadline)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_owner_membership IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) = 0 OR p_deadline IS NULL THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: owner, reason and deadline are required' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.mark_disputed.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: approver capability required in scope' USING ERRCODE = '42501';
  END IF;

  IF v_ie.approval_status <> 'UNAPPROVED' OR v_ie.review_state NOT IN ('PENDING','CHANGES_REQUESTED') THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: voucher not in a disputable state (%, %)',
      v_ie.approval_status, v_ie.review_state USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'mark_income_expense_disputed_v2: review_version mismatch' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET review_state = 'DISPUTED', review_owner_membership_id = p_owner_membership,
         review_reason = p_reason, review_deadline = p_deadline,
         review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  UPDATE public.approval_requests ar
     SET state = 'DISPUTED', outcome_kind = 'DISPUTE', outcome_reason = p_reason,
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'UNAPPROVED',
                               'reviewState', 'DISPUTED', 'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.mark_disputed.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'DISPUTE', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.mark_disputed.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION mark_income_expense_disputed_v2(p_voucher uuid, p_expected_review_version bigint, p_owner_membership uuid, p_reason text, p_deadline timestamp with time zone, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_income_expense_disputed_v2(p_voucher uuid, p_expected_review_version bigint, p_owner_membership uuid, p_reason text, p_deadline timestamp with time zone, p_idempotency_key text) IS 'Plan §5.3/§7.4: disputed -> UNAPPROVED+DISPUTED (owner+reason+deadline); keep recognition; close request DISPUTED.';








--
-- Name: mark_overdue_invoices_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_overdue_invoices_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_count integer;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  update public.invoices i
     set status = 'OVERDUE'
   where i.deleted_at is null
     and i.status in ('APPROVED', 'PARTIAL_PAID')
     and i.due_date < public.org_today_v1(NULL)
     and app_private.can_edit_invoice_building_v1(i.building_id);
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;








--
-- Name: material_items_after_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.material_items_after_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM recompute_material_stock(COALESCE(NEW.material_id, OLD.material_id));
  RETURN NULL;
END;
$$;








--
-- Name: material_purchase_recompute_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.material_purchase_recompute_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pid UUID;
BEGIN
  v_pid := COALESCE(NEW.purchase_id, OLD.purchase_id);
  UPDATE material_purchases
    SET total = COALESCE((SELECT SUM(line_total) FROM material_purchase_items WHERE purchase_id = v_pid), 0)
    WHERE id = v_pid;
  RETURN NULL;
END;
$$;








--
-- Name: monthly_building_profit(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.monthly_building_profit(p_start date, p_end date, p_building_id uuid DEFAULT NULL::uuid) RETURNS TABLE(building_id uuid, building_name text, total_income numeric, total_expense numeric, net_profit numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  v_owner := COALESCE(
    (SELECT sa.user_id FROM public.super_admins sa WHERE sa.user_id = auth.uid()),
    (SELECT b.user_id FROM public.buildings b
      WHERE b.user_id = auth.uid() AND b.deleted_at IS NULL LIMIT 1),
    (SELECT sa.user_id FROM public.staff_assignments sa
      WHERE sa.staff_id = auth.uid() LIMIT 1),
    (SELECT sa.user_id FROM public.super_admins sa ORDER BY sa.created_at LIMIT 1)
  );

  RETURN QUERY
  SELECT
    b.id,
    b.name,
    COALESCE(i.total, 0)::numeric,
    COALESCE(e.total, 0)::numeric,
    (COALESCE(i.total, 0) - COALESCE(e.total, 0))::numeric
  FROM public.buildings b
  LEFT JOIN (
    SELECT ie.building_id, SUM(ie.kqkd_amount) AS total
    FROM public.income_expenses ie
    WHERE ie.user_id = v_owner
      AND ie.type = 'INCOME'
      AND ie.kqkd_amount > 0
      AND ie.approval_status = 'APPROVED'
      AND ie.deleted_at IS NULL
      AND ie.voucher_date BETWEEN p_start AND p_end
    GROUP BY ie.building_id
  ) i ON i.building_id = b.id
  LEFT JOIN (
    SELECT ie.building_id, SUM(ie.kqkd_amount) AS total
    FROM public.income_expenses ie
    WHERE ie.user_id = v_owner
      AND ie.type = 'EXPENSE'
      AND ie.kqkd_amount > 0
      AND ie.approval_status = 'APPROVED'
      AND ie.deleted_at IS NULL
      AND ie.voucher_date BETWEEN p_start AND p_end
    GROUP BY ie.building_id
  ) e ON e.building_id = b.id
  WHERE b.user_id = v_owner
    AND b.is_virtual = false
    AND b.deleted_at IS NULL
    AND (p_building_id IS NULL OR b.id = p_building_id)
  ORDER BY b.name;
END;
$$;








--
-- Name: move_income_voucher_cashbook_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_income_voucher_cashbook_v1(p_voucher uuid, p_new_account uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v public.income_expenses%ROWTYPE;
  v_actor uuid := auth.uid();
  v_is_super boolean;
  v_bypass boolean;
  v_membership uuid;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_flow text;
  v_old_acc public.accounts%ROWTYPE;
  v_new_acc public.accounts%ROWTYPE;
  v_to_kind text;
  v_after public.income_expenses%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF char_length(v_reason) < 8 THEN
    RAISE EXCEPTION 'Phải ghi lý do đổi sổ quỹ (ít nhất 8 ký tự) để còn đối soát về sau.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v FROM public.income_expenses
   WHERE id = p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Phiếu không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  v_is_super := public.is_super_admin();
  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = v.organization_id
     AND m.status = 'ACTIVE' LIMIT 1;
  IF v_membership IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'Không thuộc tổ chức của phiếu' USING ERRCODE = '42501';
  END IF;

  IF v.type <> 'INCOME' THEN
    RAISE EXCEPTION 'Cửa này chỉ đổi sổ quỹ cho phiếu THU.' USING ERRCODE = 'P0001';
  END IF;
  IF v.approval_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Phiếu đã huỷ — không đổi sổ quỹ được nữa.' USING ERRCODE = 'P0001';
  END IF;
  IF v.account_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu chưa có sổ quỹ — dùng chức năng duyệt để chọn sổ lần đầu.'
      USING ERRCODE = 'P0001';
  END IF;
  IF p_new_account IS NULL OR p_new_account = v.account_id THEN
    RAISE EXCEPTION 'Hãy chọn một sổ quỹ khác sổ hiện tại.' USING ERRCODE = '22023';
  END IF;

  -- Phiếu do luồng NGHIỆP VỤ khác sở hữu: sổ quỹ đi theo nghiệp vụ nguồn.
  -- CANONICAL_INCOME_EXPENSE (phiếu thủ công tạo qua writer canonical) KHÔNG
  -- thuộc nhóm này — nó chính là phiếu mà chức năng này phục vụ.
  SELECT o.flow_kind INTO v_flow
  FROM app_private.income_expense_flow_ownership o
  WHERE o.income_expense_id = p_voucher;
  IF v_flow IS NOT NULL AND v_flow <> 'CANONICAL_INCOME_EXPENSE' THEN
    RAISE EXCEPTION 'Phiếu thu này gắn với nghiệp vụ % nên sổ quỹ đi theo nghiệp vụ đó. Muốn đổi sổ thì huỷ khoản thu rồi thu lại vào đúng sổ.',
      v_flow USING ERRCODE = 'P0001';
  END IF;
  IF v.payment_collection_id IS NOT NULL THEN
    RAISE EXCEPTION 'Phiếu thu này thuộc một đợt thu hoá đơn — sổ quỹ đi theo đợt thu. Muốn đổi sổ thì huỷ khoản thu rồi thu lại vào đúng sổ.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Phải ĐANG ghi sổ thì mới có gì để chuyển. Không có hai chặn dưới đây thì
  -- phiếu UNPOSTED/NOT_APPLICABLE (điển hình: phiếu nằm trên SỔ ẢO) đi qua cửa
  -- này sẽ SINH TIỀN: nhánh (a) của cầu a85 không chạy vì không có bút toán để
  -- đảo, còn nhánh (b) thấy phiếu APPROVED + sổ mới là sổ thật nên ghi một
  -- POSTING mới ⇒ sổ quỹ thật tăng đúng total_amount mà không đồng nào vào két.
  -- Đo trên prod: 109 phiếu THU đang nằm sổ ảo đủ điều kiện đi cửa này.
  IF COALESCE(v.posting_status, 'UNPOSTED') <> 'POSTED' OR v.active_posting_id_v2 IS NULL THEN
    RAISE EXCEPTION 'Phiếu chưa ghi sổ nên không có bút toán nào để chuyển. Muốn ghi nhận tiền vào sổ quỹ thì lập phiếu thu thật.'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_old_acc FROM public.accounts WHERE id = v.account_id;
  IF COALESCE(v_old_acc.is_virtual, false) THEN
    RAISE EXCEPTION 'Phiếu đang ghi trên sổ nội bộ (sổ ảo) — chuyển sang sổ quỹ thật ở đây là ghi nhận tiền mới, không phải đổi sổ. Hãy lập phiếu thu thật.'
      USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_new_acc FROM public.accounts WHERE id = p_new_account;
  IF v_new_acc.id IS NULL
     OR v_new_acc.organization_id IS DISTINCT FROM v.organization_id
     OR v_new_acc.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Sổ quỹ đích không tồn tại trong tổ chức này.' USING ERRCODE = '22023';
  END IF;
  -- Sổ ẢO không có bút toán tiền mặt: cầu a85 sẽ đảo sổ cũ rồi KHÔNG ghi lại,
  -- phiếu rơi vào trạng thái lửng. Chặn thẳng thay vì để lệch âm thầm.
  IF COALESCE(v_new_acc.is_virtual, false) THEN
    RAISE EXCEPTION 'Không chuyển phiếu đã ghi sổ sang sổ ảo được — chọn một sổ quỹ thật.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Quyền (quyết định #10): rút tiền KHỎI sổ nào thì phải đang GIỮ sổ đó;
  -- sổ nhận chỉ cần GIỮ hoặc BIẾT. Chủ tổ chức / super admin đi thẳng.
  -- Hai lớp, cố ý KHÔNG bọc BEGIN...EXCEPTION quanh assert (bọc sẽ nuốt cả lỗi
  -- hệ thống — deadlock, 25006 — rồi báo nhầm thành "thiếu quyền"):
  --   lớp 1  đọc thẳng possession để có câu tiếng Việt nêu đích danh tên sổ;
  --   lớp 2  assert_cashbook_access_v2 để lớp DENY phủ (thu hồi quyền tường
  --          minh) vẫn có tiếng nói — kind truyền vào là kind mình THỰC SỰ có
  --          nên hàm không bao giờ ném vì lý do "sai kind".
  v_bypass := v_is_super OR app_private.is_org_owner_v1(v.organization_id, v_actor);
  IF NOT v_bypass THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.cashbook_possession_bindings b
      WHERE b.organization_id = v.organization_id
        AND b.cashbook_id = v.account_id
        AND b.membership_id = v_membership
        AND b.valid_to IS NULL
        AND b.possession_kind = 'CUSTODIAN'
    ) THEN
      RAISE EXCEPTION 'Bạn không phải người giữ sổ "%" nên không chuyển tiền ra khỏi sổ đó được.',
        COALESCE(v_old_acc.name, 'không rõ') USING ERRCODE = '42501';
    END IF;
    PERFORM app_private.assert_cashbook_access_v2(
      v.organization_id, v.account_id, 'CUSTODIAN', v_membership);

    SELECT b.possession_kind INTO v_to_kind
    FROM public.cashbook_possession_bindings b
    WHERE b.organization_id = v.organization_id
      AND b.cashbook_id = p_new_account
      AND b.membership_id = v_membership
      AND b.valid_to IS NULL
      AND b.possession_kind IN ('CUSTODIAN', 'KNOWER')
    ORDER BY (b.possession_kind = 'CUSTODIAN') DESC
    LIMIT 1;
    IF v_to_kind IS NULL THEN
      RAISE EXCEPTION 'Sổ quỹ "%" không nằm trong các sổ bạn giữ hoặc biết — nhờ người giữ sổ chia sẻ sổ cho bạn trước.',
        COALESCE(v_new_acc.name, 'không rõ') USING ERRCODE = '42501';
    END IF;
    PERFORM app_private.assert_cashbook_access_v2(
      v.organization_id, p_new_account, v_to_kind, v_membership);
  END IF;

  -- Ba khoá thời gian, xét trên trạng thái HIỆN TẠI (sổ đi). Trigger
  -- income_expenses_check_lock sẽ xét lại cả sổ ĐẾN khi UPDATE chạy.
  PERFORM app_private.assert_period_open_for_edit_v1(p_voucher, 'đổi sổ quỹ');

  -- Năng lực hẹp: qua được trigger đóng băng nhưng KHÔNG tắt cầu a85, để
  -- chính a85 đảo bút toán sổ cũ rồi ghi generation mới ở sổ mới (kèm đủ dòng
  -- MAIN/CHANGE/ROUNDING). Xem migration này phần (2).
  PERFORM app_private.begin_ie_flex_write_v1(p_voucher, 'CASHBOOK_MOVE');

  UPDATE public.income_expenses
     SET account_id = p_new_account,
         updated_at = now()
   WHERE id = p_voucher;

  PERFORM app_private.end_ie_flex_write_v1(p_voucher);

  SELECT * INTO v_after FROM public.income_expenses WHERE id = p_voucher;

  -- Hậu điều kiện: tiền phải rời hẳn sổ cũ và có mặt đủ ở sổ mới.
  IF COALESCE(v.posting_status, 'UNPOSTED') = 'POSTED'
     AND COALESCE(v_after.posting_status, '') <> 'POSTED' THEN
    RAISE EXCEPTION 'Đổi sổ nhưng phiếu không ghi sổ lại được (trạng thái %) — dừng lại, báo quản trị.',
      COALESCE(v_after.posting_status, 'không rõ') USING ERRCODE = '55000';
  END IF;
  IF COALESCE((
       SELECT sum(l.signed_amount) FROM public.income_expense_posting_lines l
       JOIN public.income_expense_postings p ON p.id = l.posting_id
       WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher
         AND l.account_id = v.account_id), 0) <> 0 THEN
    RAISE EXCEPTION 'Đổi sổ nhưng sổ quỹ cũ vẫn còn số dư của phiếu này — dừng lại, báo quản trị.'
      USING ERRCODE = '55000';
  END IF;
  IF COALESCE((
       SELECT sum(l.signed_amount) FROM public.income_expense_posting_lines l
       JOIN public.income_expense_postings p ON p.id = l.posting_id
       WHERE p.posting_subject_kind = 'VOUCHER' AND p.posting_subject_id = p_voucher
         AND l.account_id = p_new_account), 0) = 0 THEN
    RAISE EXCEPTION 'Đổi sổ nhưng sổ quỹ mới không nhận được khoản nào — dừng lại, báo quản trị.'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.append_income_expense_event_v1(
    v.organization_id, p_voucher, 'CASHBOOK_MOVED', v_actor, NULL,
    COALESCE(v_old_acc.name, v.account_id::text),
    COALESCE(v_new_acc.name, p_new_account::text),
    v_reason);

  RETURN jsonb_build_object(
    'id', p_voucher, 'changed', true,
    'from_account_id', v.account_id, 'from_account_name', v_old_acc.name,
    'to_account_id', p_new_account, 'to_account_name', v_new_acc.name,
    'posting_status', v_after.posting_status);
END
$$;








--
-- Name: FUNCTION move_income_voucher_cashbook_v1(p_voucher uuid, p_new_account uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.move_income_voucher_cashbook_v1(p_voucher uuid, p_new_account uuid, p_reason text) IS 'ĐỢT C: đổi sổ quỹ phiếu THU đã ghi sổ. Sổ đi cần CUSTODIAN, sổ đến CUSTODIAN∪KNOWER. Bút toán do cầu a85 tự đảo + ghi lại (kể cả dòng tiền thối/làm tròn).';








--
-- Name: my_org_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_org_ids() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE(array_agg(organization_id), '{}'::uuid[])
  FROM public.organization_memberships
  WHERE user_id = auth.uid() AND status = 'ACTIVE';
$$;








--
-- Name: natural_sort_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.natural_sort_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(string_agg(
    CASE WHEN t.m[1] ~ '^\d' THEN lpad(t.m[1], 12, '0') ELSE t.m[1] END,
    '' ORDER BY t.ord), '')
  FROM regexp_matches(upper(trim(COALESCE(p_name, ''))), '\d+|\D+', 'g')
       WITH ORDINALITY AS t(m, ord);
$$;








--
-- Name: network_center_ack_incident_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_ack_incident_v1(p_incident_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_building_id uuid;
  v_scope record;
  v_incident public.network_incidents%ROWTYPE;
  v_hash text;
  v_replay jsonb;
  v_result jsonb;
BEGIN
  IF p_incident_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Incident and request identifiers are required' USING ERRCODE = '22023';
  END IF;
  SELECT incident.building_id INTO v_building_id
  FROM public.network_incidents incident WHERE incident.id = p_incident_id;
  IF v_building_id IS NULL THEN RAISE EXCEPTION 'Incident not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_execute_v1(v_building_id);
  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'ack_incident', 'incidentId', p_incident_id
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash, 'acknowledge_incident'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT incident.* INTO v_incident
  FROM public.network_incidents incident
  WHERE incident.organization_id = v_scope.organization_id
    AND incident.building_id = v_building_id AND incident.id = p_incident_id
  FOR UPDATE;
  IF NOT FOUND OR v_incident.status = 'RESOLVED' THEN
    RAISE EXCEPTION 'Active incident not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_incident.acknowledged_at IS NULL THEN
    UPDATE public.network_incidents
    SET status = 'ACKNOWLEDGED', acknowledged_at = clock_timestamp(),
        acknowledged_by = v_scope.actor_id, version = version + 1
    WHERE id = p_incident_id;
    INSERT INTO public.network_incident_events (
      organization_id, building_id, incident_id, event_seq, event_kind,
      severity, occurred_at, actor_id, details
    ) VALUES (
      v_scope.organization_id, v_building_id, p_incident_id,
      coalesce((SELECT max(event.event_seq) + 1 FROM public.network_incident_events event
        WHERE event.incident_id = p_incident_id), 1),
      'ACKNOWLEDGED', v_incident.severity, clock_timestamp(), v_scope.actor_id,
      jsonb_build_object('previousStatus', v_incident.status)
    );
  END IF;

  SELECT jsonb_build_object(
    'incidentId', incident.id, 'status', incident.status,
    'acknowledgedAt', incident.acknowledged_at, 'acknowledgedBy', incident.acknowledged_by
  ) INTO v_result FROM public.network_incidents incident WHERE incident.id = p_incident_id;
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, v_building_id, v_scope.actor_id,
    'acknowledge_incident', 'incident', p_incident_id,
    jsonb_build_object('buildingName', v_scope.building_name, 'incidentTitle', v_incident.title),
    'Acknowledge network incident', jsonb_build_object('permission', 'network_center.execute'),
    v_result, 'SUCCEEDED', NULL, p_request_id, v_hash
  );
  INSERT INTO public.network_outbox_events (
    organization_id, building_id, event_type, aggregate_type, aggregate_id, payload, occurred_at
  ) VALUES (
    v_scope.organization_id, v_building_id, 'network.incident.acknowledged',
    'incident', p_incident_id, jsonb_build_object('incidentId', p_incident_id), clock_timestamp()
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_admin_enroll_access_port_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_enroll_access_port_v1(p_interface_id uuid, p_confirm_immutable_key text, p_reason text, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_confirm text := btrim(coalesce(p_confirm_immutable_key, ''));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_row record;
  v_after record;
BEGIN
  IF p_interface_id IS NULL
     OR v_confirm !~* '^ether([2-9]|[1-9][0-9])$'
     OR char_length(v_reason) NOT BETWEEN 8 AND 500
     OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Invalid Network Center access-port enrollment request'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    interface.organization_id AS organization_id,
    interface.building_id AS building_id,
    interface.device_id AS device_id,
    interface.id AS interface_id,
    interface.is_protected AS interface_protected,
    resource.id AS resource_id,
    resource.stable_key AS stable_key,
    resource.enrollment_state AS enrollment_state,
    resource.protected AS resource_protected,
    building.name AS building_name
  INTO v_row
  FROM public.network_interfaces interface
  JOIN public.network_managed_resources resource
    ON resource.organization_id = interface.organization_id
   AND resource.building_id = interface.building_id
   AND resource.device_id = interface.device_id
   AND resource.id = interface.managed_resource_id
  LEFT JOIN public.buildings building
    ON building.organization_id = interface.organization_id
   AND building.id = interface.building_id
  WHERE interface.id = p_interface_id
    AND resource.resource_kind = 'INTERFACE';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Managed access interface not found' USING ERRCODE = 'P0002';
  END IF;

  -- Typed confirmation of the IMMUTABLE key, not of the display name. RouterOS
  -- lets an operator rename ether4 to anything; the default-name is what the
  -- router-side cycle actually targets, so that is what must be typed.
  IF v_row.stable_key IS DISTINCT FROM v_confirm THEN
    RAISE EXCEPTION 'Access-port confirmation does not match the immutable key'
      USING ERRCODE = '22023',
        DETAIL = format(
          'confirmed=%s actual=%s interfaceId=%s',
          v_confirm, v_row.stable_key, p_interface_id
        );
  END IF;

  -- Idempotent. A repeated enrollment of an already-enrolled, already
  -- unprotected port is a no-op that reports changed=false, not a refusal: an
  -- operator retrying after a lost response must not be told the port is
  -- ineligible.
  IF v_row.enrollment_state = 'ENROLLED'
     AND NOT v_row.resource_protected
     AND NOT v_row.interface_protected THEN
    RETURN jsonb_build_object(
      'organizationId', v_row.organization_id,
      'buildingId', v_row.building_id,
      'deviceId', v_row.device_id,
      'interfaceId', v_row.interface_id,
      'managedResourceId', v_row.resource_id,
      'immutableKey', v_row.stable_key,
      'enrollmentState', v_row.enrollment_state,
      'resourceProtected', v_row.resource_protected,
      'interfaceProtected', v_row.interface_protected,
      'changed', false
    );
  END IF;

  -- The door itself. Every precondition -- DISCOVERED, ACCESS, protected,
  -- eligibleAccess, ether2..N, ETHERNET, managed, enabled, key identity -- lives
  -- inside it and is NOT duplicated here, so there is exactly one definition of
  -- what may be enrolled. It raises 42501 naming the resource when refused.
  PERFORM app_private.network_center_enroll_access_interface_v1(v_row.resource_id);

  SELECT resource.enrollment_state AS enrollment_state,
    resource.protected AS resource_protected,
    interface.is_protected AS interface_protected
  INTO v_after
  FROM public.network_managed_resources resource
  JOIN public.network_interfaces interface
    ON interface.managed_resource_id = resource.id
  WHERE resource.id = v_row.resource_id;

  -- Read back rather than assume. A trigger between here and there could have
  -- re-protected the row, and reporting an enrollment that did not stick would
  -- send an operator to cycle a port that is still protected.
  IF v_after.enrollment_state <> 'ENROLLED'
     OR v_after.resource_protected
     OR v_after.interface_protected THEN
    RAISE EXCEPTION 'Access-port enrollment did not take effect'
      USING ERRCODE = '55000',
        DETAIL = format(
          'enrollmentState=%s resourceProtected=%s interfaceProtected=%s',
          v_after.enrollment_state, v_after.resource_protected,
          v_after.interface_protected
        );
  END IF;

  INSERT INTO public.network_audit_events (
    organization_id, building_id, actor_type, action, target_type, target_id,
    target_display, reason, validation, result, outcome, request_id, occurred_at
  ) VALUES (
    v_row.organization_id,
    v_row.building_id,
    'SYSTEM',
    'admin.enroll_access_port',
    'interface',
    v_row.interface_id,
    jsonb_build_object(
      'buildingName', v_row.building_name,
      'deviceId', v_row.device_id,
      'immutableKey', v_row.stable_key
    ),
    v_reason,
    jsonb_build_object(
      'confirmedImmutableKey', v_confirm,
      'previousEnrollmentState', v_row.enrollment_state,
      'previousResourceProtected', v_row.resource_protected,
      'previousInterfaceProtected', v_row.interface_protected
    ),
    jsonb_build_object(
      'managedResourceId', v_row.resource_id,
      'enrollmentState', v_after.enrollment_state,
      'resourceProtected', v_after.resource_protected,
      'interfaceProtected', v_after.interface_protected
    ),
    'SUCCEEDED',
    p_request_id,
    clock_timestamp()
  );

  RETURN jsonb_build_object(
    'organizationId', v_row.organization_id,
    'buildingId', v_row.building_id,
    'deviceId', v_row.device_id,
    'interfaceId', v_row.interface_id,
    'managedResourceId', v_row.resource_id,
    'immutableKey', v_row.stable_key,
    'enrollmentState', v_after.enrollment_state,
    'resourceProtected', v_after.resource_protected,
    'interfaceProtected', v_after.interface_protected,
    'changed', true
  );
END;
$_$;








--
-- Name: FUNCTION network_center_admin_enroll_access_port_v1(p_interface_id uuid, p_confirm_immutable_key text, p_reason text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_enroll_access_port_v1(p_interface_id uuid, p_confirm_immutable_key text, p_reason text, p_request_id uuid) IS 'Service-role-only deliberate enrollment of one physical access port (ether2..N) so it becomes cyclable. Requires the immutable key typed back as confirmation and a reason, delegates every eligibility rule to app_private.network_center_enroll_access_interface_v1, reads the result back before reporting success, and writes a network_audit_events row. This is the only caller of that door.';








--
-- Name: network_center_admin_finalize_worker_compatibility_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_finalize_worker_compatibility_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_worker_id uuid;
  v_already_finalized boolean := false;
BEGIN
  SELECT state.worker_id, state.finalized_at IS NOT NULL
  INTO v_worker_id, v_already_finalized
  FROM app_private.network_worker_compatibility_state state
  WHERE state.singleton
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker compatibility state not found'
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_already_finalized THEN
    UPDATE app_private.network_worker_compatibility_state
    SET finalized_at = v_now, expires_at = LEAST(expires_at, v_now)
    WHERE singleton;
    UPDATE public.network_workers worker
    SET status = 'DISABLED', version = worker.version + 1,
        updated_at = v_now
    WHERE worker.id = v_worker_id;
    UPDATE public.network_worker_assignments assignment
    SET active_until = greatest(
          v_now, assignment.active_from + INTERVAL '1 microsecond'
        ),
        assignment_version = assignment.assignment_version + 1,
        updated_by = 'worker-compatibility-finalizer',
        updated_at = v_now
    WHERE assignment.worker_id = v_worker_id
      AND (assignment.active_until IS NULL OR assignment.active_until > v_now);
  END IF;

  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_heartbeat_v1(text,text,text[],text,integer,jsonb,timestamp with time zone) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_list_connections_v1(text,integer) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_claim_v1(text,integer,integer) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_renew_v1(text,uuid,uuid,integer) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_ingest_v1(text,jsonb) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_inventory_v1(text,jsonb) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_command_event_v1(text,uuid,uuid,text,jsonb) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_complete_v1(text,uuid,uuid,text,jsonb,jsonb,integer) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_upsert_incident_v1(text,jsonb) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_snapshot_v1(text,jsonb) FROM service_role';
  EXECUTE 'REVOKE EXECUTE ON FUNCTION public.network_center_worker_maintenance_v1(text,timestamp with time zone) FROM service_role';

  RETURN jsonb_build_object(
    'finalized', true,
    'alreadyFinalized', v_already_finalized,
    'finalizedAt', coalesce((
      SELECT state.finalized_at
      FROM app_private.network_worker_compatibility_state state
      WHERE state.singleton
    ), v_now)
  );
END;
$$;








--
-- Name: network_center_admin_list_access_ports_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_list_access_ports_v1(p_building_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_ports jsonb;
BEGIN
  -- No FOR UPDATE / FOR SHARE anywhere in this body: PostgREST runs a STABLE
  -- function inside a READ ONLY transaction, where a row lock raises 25006 and
  -- the call works from SQL but fails from the client.
  WITH candidate AS (
    SELECT
      resource.organization_id,
      resource.building_id,
      building.name AS building_name,
      resource.device_id,
      interface.id AS interface_id,
      resource.id AS managed_resource_id,
      interface.interface_key,
      resource.stable_key,
      interface.display_name,
      interface.interface_kind,
      interface.interface_role,
      interface.is_enabled,
      interface.is_protected,
      interface.is_managed,
      resource.enrollment_state,
      resource.enrolled_role,
      resource.protected,
      coalesce(
        (resource.metadata->>'eligibleAccess')::boolean, false
      ) AS eligible_access
    FROM public.network_managed_resources resource
    JOIN public.network_interfaces interface
      ON interface.organization_id = resource.organization_id
     AND interface.building_id = resource.building_id
     AND interface.device_id = resource.device_id
     AND interface.managed_resource_id = resource.id
    LEFT JOIN public.buildings building
      ON building.organization_id = resource.organization_id
     AND building.id = resource.building_id
    WHERE resource.resource_kind = 'INTERFACE'
      AND (p_building_id IS NULL OR resource.building_id = p_building_id)
  ), evaluated AS (
    -- blocked_by mirrors app_private.network_center_enroll_access_interface_v1
    -- clause for clause and in its order, so an operator reading this list is
    -- reading the same predicate the door will evaluate, not a paraphrase.
    SELECT candidate.*,
      (
        CASE WHEN candidate.enrollment_state = 'DISCOVERED'
          THEN ARRAY[]::text[] ELSE ARRAY['enrollmentState<>DISCOVERED'] END
        || CASE WHEN candidate.enrolled_role = 'ACCESS'
          THEN ARRAY[]::text[] ELSE ARRAY['enrolledRole<>ACCESS'] END
        || CASE WHEN candidate.protected
          THEN ARRAY[]::text[] ELSE ARRAY['resourceAlreadyUnprotected'] END
        || CASE WHEN candidate.eligible_access
          THEN ARRAY[]::text[] ELSE ARRAY['eligibleAccess<>true'] END
        || CASE WHEN candidate.stable_key ~* '^ether([2-9]|[1-9][0-9])$'
          THEN ARRAY[]::text[] ELSE ARRAY['stableKeyIsNotAPhysicalAccessPort'] END
        || CASE WHEN candidate.interface_kind = 'ETHERNET'
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceKind<>ETHERNET'] END
        || CASE WHEN candidate.interface_role = 'ACCESS'
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceRole<>ACCESS'] END
        || CASE WHEN candidate.is_protected
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceAlreadyUnprotected'] END
        || CASE WHEN candidate.is_managed
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceNotManaged'] END
        || CASE WHEN candidate.is_enabled
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceDisabled'] END
        || CASE WHEN candidate.interface_key = candidate.stable_key
          THEN ARRAY[]::text[] ELSE ARRAY['interfaceKey<>stableKey'] END
      ) AS blocked_by
    FROM candidate
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'organizationId', evaluated.organization_id,
    'buildingId', evaluated.building_id,
    'buildingName', evaluated.building_name,
    'deviceId', evaluated.device_id,
    'interfaceId', evaluated.interface_id,
    'managedResourceId', evaluated.managed_resource_id,
    'interfaceKey', evaluated.interface_key,
    'immutableKey', evaluated.stable_key,
    'displayName', evaluated.display_name,
    'interfaceKind', evaluated.interface_kind,
    'interfaceRole', evaluated.interface_role,
    'isEnabled', evaluated.is_enabled,
    'interfaceProtected', evaluated.is_protected,
    'enrollmentState', evaluated.enrollment_state,
    'resourceProtected', evaluated.protected,
    'eligibleAccess', evaluated.eligible_access,
    'enrollable', cardinality(evaluated.blocked_by) = 0,
    'blockedBy', to_jsonb(evaluated.blocked_by)
  ) ORDER BY evaluated.building_name, evaluated.stable_key), '[]'::jsonb)
  INTO v_ports
  FROM evaluated;

  RETURN jsonb_build_object('ports', v_ports);
END;
$_$;








--
-- Name: FUNCTION network_center_admin_list_access_ports_v1(p_building_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_list_access_ports_v1(p_building_id uuid) IS 'Service-role-only listing of every managed RouterOS interface resource with its enrollment state and, for the ones that are not enrollable, the exact preconditions that block them -- mirroring app_private.network_center_enroll_access_interface_v1 clause for clause.';








--
-- Name: network_center_admin_provision_connection_v1(uuid, text, inet, integer, text, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_provision_connection_v1(p_device_id uuid, p_transport text, p_management_ip inet, p_management_port integer, p_credential_ref text, p_host_key_fingerprint text, p_poll_interval_seconds integer DEFAULT 60, p_connect_timeout_ms integer DEFAULT 8000, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_identity record;
  v_building record;
  v_settings record;
  v_device record;
  v_connection_id uuid;
BEGIN
  IF p_device_id IS NULL
     OR upper(btrim(coalesce(p_transport, ''))) <> 'ROUTEROS_SSH'
     OR p_management_ip IS NULL
     OR p_management_port NOT BETWEEN 1 AND 65535
     OR p_credential_ref IS NULL
     OR p_credential_ref !~ '^router/[A-Za-z0-9][A-Za-z0-9._/-]{1,127}$'
     OR p_host_key_fingerprint IS NULL
     OR p_host_key_fingerprint !~ '^SHA256:[A-Za-z0-9+/]{20,}={0,2}$'
     OR p_poll_interval_seconds NOT BETWEEN 30 AND 3600
     OR p_connect_timeout_ms NOT BETWEEN 1000 AND 30000
     OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Invalid Network Center connection provision request'
      USING ERRCODE = '22023';
  END IF;

  -- Resolve identity without trusting caller-supplied tenant/building fields, then
  -- take locks in the global order: building -> settings -> device -> connections.
  SELECT device.organization_id, device.building_id
  INTO v_identity
  FROM public.network_devices device
  WHERE device.id = p_device_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network device not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT building.organization_id, building.id, building.name
  INTO v_building
  FROM public.buildings building
  WHERE building.organization_id = v_identity.organization_id
    AND building.id = v_identity.building_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network building not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT settings.id, settings.version, settings.rollout_state
  INTO v_settings
  FROM public.network_site_settings settings
  WHERE settings.organization_id = v_building.organization_id
    AND settings.building_id = v_building.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network settings not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_settings.rollout_state = 'EXECUTE' THEN
    RAISE EXCEPTION 'Disable Network Center execution before changing connection metadata'
      USING ERRCODE = '55000';
  END IF;

  SELECT device.id, device.organization_id, device.building_id, device.device_kind
  INTO v_device
  FROM public.network_devices device
  WHERE device.id = p_device_id
    AND device.organization_id = v_building.organization_id
    AND device.building_id = v_building.id
  FOR UPDATE;
  IF NOT FOUND OR v_device.device_kind <> 'MIKROTIK' THEN
    RAISE EXCEPTION 'Connection target must be the scoped MikroTik device'
      USING ERRCODE = '22023';
  END IF;

  PERFORM connection.id
  FROM public.network_device_connections connection
  WHERE connection.organization_id = v_building.organization_id
    AND connection.building_id = v_building.id
    AND connection.device_id = v_device.id
  ORDER BY connection.id
  FOR UPDATE;

  UPDATE public.network_device_connections connection
  SET is_enabled = false,
      updated_at = clock_timestamp()
  WHERE connection.organization_id = v_building.organization_id
    AND connection.building_id = v_building.id
    AND connection.device_id = v_device.id
    AND connection.is_enabled;

  INSERT INTO public.network_device_connections (
    organization_id,
    building_id,
    device_id,
    transport,
    management_ip,
    management_port,
    credential_ref,
    host_key_fingerprint,
    poll_interval_seconds,
    connect_timeout_ms,
    is_enabled
  ) VALUES (
    v_building.organization_id,
    v_building.id,
    v_device.id,
    'ROUTEROS_SSH',
    p_management_ip,
    p_management_port,
    p_credential_ref,
    p_host_key_fingerprint,
    p_poll_interval_seconds,
    p_connect_timeout_ms,
    true
  )
  ON CONFLICT (device_id, transport, management_ip, management_port)
  DO UPDATE SET
    credential_ref = EXCLUDED.credential_ref,
    host_key_fingerprint = EXCLUDED.host_key_fingerprint,
    poll_interval_seconds = EXCLUDED.poll_interval_seconds,
    connect_timeout_ms = EXCLUDED.connect_timeout_ms,
    is_enabled = true,
    updated_at = clock_timestamp()
  RETURNING id INTO v_connection_id;

  INSERT INTO public.network_audit_events (
    organization_id,
    building_id,
    actor_type,
    action,
    target_type,
    target_id,
    target_display,
    reason,
    validation,
    result,
    outcome,
    request_id,
    occurred_at
  ) VALUES (
    v_building.organization_id,
    v_building.id,
    'SYSTEM',
    'admin.provision_connection',
    'connection',
    v_connection_id,
    jsonb_build_object(
      'buildingName', v_building.name,
      'deviceId', v_device.id,
      'transport', 'ROUTEROS_SSH'
    ),
    'Provision pinned Network Center connection metadata',
    jsonb_build_object(
      'settingsVersion', v_settings.version,
      'managementIp', host(p_management_ip),
      'managementPort', p_management_port
    ),
    jsonb_build_object(
      'credentialRef', p_credential_ref,
      'hostKeyFingerprint', p_host_key_fingerprint,
      'enabled', true
    ),
    'SUCCEEDED',
    p_request_id,
    clock_timestamp()
  );

  RETURN jsonb_build_object(
    'connectionId', v_connection_id,
    'organizationId', v_building.organization_id,
    'buildingId', v_building.id,
    'deviceId', v_device.id,
    'transport', 'ROUTEROS_SSH',
    'managementIp', host(p_management_ip),
    'managementPort', p_management_port,
    'credentialRef', p_credential_ref,
    'hostKeyFingerprint', p_host_key_fingerprint,
    'enabled', true
  );
END;
$_$;








--
-- Name: FUNCTION network_center_admin_provision_connection_v1(p_device_id uuid, p_transport text, p_management_ip inet, p_management_port integer, p_credential_ref text, p_host_key_fingerprint text, p_poll_interval_seconds integer, p_connect_timeout_ms integer, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_provision_connection_v1(p_device_id uuid, p_transport text, p_management_ip inet, p_management_port integer, p_credential_ref text, p_host_key_fingerprint text, p_poll_interval_seconds integer, p_connect_timeout_ms integer, p_request_id uuid) IS 'Service-role-only pinned RouterOS SSH connection provisioning; accepts opaque credential references, never credential material.';








--
-- Name: network_center_admin_provision_worker_v1(text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_provision_worker_v1(p_worker_key text, p_display_name text, p_secret_digest text, p_fingerprint text, p_expires_at timestamp with time zone, p_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_worker_id uuid;
  v_assignment_count integer;
BEGIN
  IF p_worker_key IS NULL
     OR p_worker_key !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
     OR p_display_name IS NULL
     OR char_length(btrim(p_display_name)) NOT BETWEEN 1 AND 128
     OR p_secret_digest IS NULL
     OR p_secret_digest !~ '^[a-f0-9]{64}$'
     OR p_fingerprint IS NULL
     OR p_fingerprint !~ '^sha256:[a-f0-9]{12,64}$'
     OR p_expires_at IS NULL
     OR p_expires_at <= v_now + INTERVAL '5 minutes'
     OR p_expires_at > v_now + INTERVAL '90 days' THEN
    RAISE EXCEPTION 'Invalid worker provision request' USING ERRCODE = '22023';
  END IF;
  IF p_assignments IS NULL
     OR jsonb_typeof(p_assignments) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_assignments) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Worker assignments must contain between 1 and 100 items'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.network_workers (
    worker_key,
    display_name,
    capabilities
  ) VALUES (
    p_worker_key,
    btrim(p_display_name),
    ARRAY[
      'HEARTBEAT', 'POLL', 'TELEMETRY', 'INVENTORY',
      'EXECUTE', 'INCIDENT', 'SNAPSHOT', 'MAINTENANCE'
    ]::text[]
  )
  RETURNING id INTO v_worker_id;

  INSERT INTO public.network_worker_credentials (
    worker_id,
    secret_digest,
    fingerprint,
    not_before,
    expires_at
  ) VALUES (
    v_worker_id,
    p_secret_digest::character(64),
    p_fingerprint,
    v_now,
    p_expires_at
  );

  v_assignment_count := app_private.network_center_replace_worker_assignments_v1(
    v_worker_id,
    p_assignments,
    false,
    'service_role:provision'
  );

  RETURN jsonb_build_object(
    'workerId', v_worker_id,
    'workerKey', p_worker_key,
    'status', 'ACTIVE',
    'credentialFingerprint', p_fingerprint,
    'assignmentCount', v_assignment_count
  );
END;
$_$;








--
-- Name: network_center_admin_release_status_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_release_status_v1(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_release_heartbeats jsonb;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Network Center release status limit must be between 1 and 200'
      USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_release_heartbeats
  FROM (
    SELECT worker.worker_key AS "workerKey",
      worker.display_name AS "displayName",
      heartbeat.worker_version AS "workerVersion",
      heartbeat.status,
      heartbeat.heartbeat_at AS "heartbeatAt",
      heartbeat.started_at AS "startedAt",
      heartbeat.assigned_building_count AS "assignedBuildingCount",
      heartbeat.connection_count AS "connectionCount",
      heartbeat.successful_poll_count AS "successfulPollCount",
      heartbeat.failed_poll_count AS "failedPollCount",
      heartbeat.poll_observed_at AS "pollObservedAt"
    FROM app_private.network_worker_release_heartbeats heartbeat
    JOIN public.network_workers worker ON worker.id = heartbeat.worker_id
    ORDER BY heartbeat.heartbeat_at DESC, worker.worker_key,
      heartbeat.worker_version
    LIMIT p_limit
  ) row_data;

  RETURN jsonb_build_object('releaseHeartbeats', v_release_heartbeats);
END;
$$;








--
-- Name: FUNCTION network_center_admin_release_status_v1(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_release_status_v1(p_limit integer) IS 'Service-role-only bounded release heartbeat readback; excludes credentials and caller metadata.';








--
-- Name: network_center_admin_revoke_worker_credential_v1(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_revoke_worker_credential_v1(p_worker_key text, p_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_worker_id uuid;
  v_credential_id uuid;
BEGIN
  IF p_worker_key IS NULL OR p_fingerprint IS NULL
     OR p_fingerprint !~ '^sha256:[a-f0-9]{12,64}$' THEN
    RAISE EXCEPTION 'Invalid worker credential revoke request'
      USING ERRCODE = '22023';
  END IF;

  SELECT worker.id
  INTO v_worker_id
  FROM public.network_workers worker
  WHERE worker.worker_key = p_worker_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.network_worker_credentials credential
  SET revoked_at = clock_timestamp()
  WHERE credential.worker_id = v_worker_id
    AND credential.fingerprint = p_fingerprint
    AND credential.revoked_at IS NULL
  RETURNING credential.id INTO v_credential_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active worker credential not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.network_workers worker
  SET version = worker.version + 1
  WHERE worker.id = v_worker_id;

  RETURN jsonb_build_object(
    'workerId', v_worker_id,
    'workerKey', p_worker_key,
    'credentialFingerprint', p_fingerprint,
    'revoked', true
  );
END;
$_$;








--
-- Name: network_center_admin_rotate_worker_credential_v1(text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_rotate_worker_credential_v1(p_worker_key text, p_secret_digest text, p_fingerprint text, p_not_before timestamp with time zone, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_worker_id uuid;
  v_overlap_count integer;
BEGIN
  IF p_worker_key IS NULL
     OR p_secret_digest IS NULL
     OR p_secret_digest !~ '^[a-f0-9]{64}$'
     OR p_fingerprint IS NULL
     OR p_fingerprint !~ '^sha256:[a-f0-9]{12,64}$'
     OR p_not_before IS NULL
     OR p_not_before < v_now - INTERVAL '5 minutes'
     OR p_not_before > v_now + INTERVAL '24 hours'
     OR p_expires_at IS NULL
     OR p_expires_at <= p_not_before
     OR p_expires_at > p_not_before + INTERVAL '90 days' THEN
    RAISE EXCEPTION 'Invalid worker credential rotation request'
      USING ERRCODE = '22023';
  END IF;

  SELECT worker.id
  INTO v_worker_id
  FROM public.network_workers worker
  WHERE worker.worker_key = p_worker_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker not found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.network_worker_credentials credential
    WHERE credential.worker_id = v_worker_id
      AND credential.revoked_at IS NULL
      AND credential.not_before > p_not_before
  ) THEN
    RAISE EXCEPTION 'Cannot rotate before an already scheduled credential'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer
  INTO v_overlap_count
  FROM public.network_worker_credentials credential
  WHERE credential.worker_id = v_worker_id
    AND credential.revoked_at IS NULL
    AND credential.not_before <= p_not_before
    AND credential.not_before < p_expires_at
    AND credential.expires_at > p_not_before;
  IF v_overlap_count > 1 THEN
    RAISE EXCEPTION 'Credential rotation would overlap more than two versions'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.network_worker_credentials credential
  SET expires_at = least(
    credential.expires_at,
    p_not_before + INTERVAL '24 hours'
  )
  WHERE credential.worker_id = v_worker_id
    AND credential.revoked_at IS NULL
    AND credential.not_before <= p_not_before
    AND credential.not_before < p_expires_at
    AND credential.expires_at > p_not_before;

  INSERT INTO public.network_worker_credentials (
    worker_id,
    secret_digest,
    fingerprint,
    not_before,
    expires_at,
    created_by
  ) VALUES (
    v_worker_id,
    p_secret_digest::character(64),
    p_fingerprint,
    p_not_before,
    p_expires_at,
    'service_role:rotate'
  );

  UPDATE public.network_workers worker
  SET version = worker.version + 1
  WHERE worker.id = v_worker_id;

  RETURN jsonb_build_object(
    'workerId', v_worker_id,
    'workerKey', p_worker_key,
    'credentialFingerprint', p_fingerprint,
    'notBefore', p_not_before,
    'expiresAt', p_expires_at
  );
END;
$_$;








--
-- Name: network_center_admin_set_rollout_v1(uuid, text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_set_rollout_v1(p_building_id uuid, p_rollout_state text, p_expected_version bigint, p_reason text, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_building record;
  v_settings record;
  v_target text := upper(btrim(coalesce(p_rollout_state, '')));
  v_new_version bigint;
BEGIN
  IF p_building_id IS NULL
     OR v_target NOT IN ('OFF', 'READ_ONLY', 'EXECUTE')
     OR p_expected_version IS NULL
     OR p_expected_version < 1
     OR p_reason IS NULL
     OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 500
     OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Invalid Network Center rollout request' USING ERRCODE = '22023';
  END IF;

  SELECT building.organization_id, building.id, building.name
  INTO v_building
  FROM public.buildings building
  WHERE building.id = p_building_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network building not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT settings.id, settings.rollout_state, settings.version
  INTO v_settings
  FROM public.network_site_settings settings
  WHERE settings.organization_id = v_building.organization_id
    AND settings.building_id = v_building.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network settings not found' USING ERRCODE = 'P0002';
  END IF;
  -- =====================================================================
  -- A CAS REFUSAL IS NOT A SERIALIZATION FAILURE (20260729148000).
  --
  -- This was ERRCODE '40001' (serialization_failure), a code whose entire
  -- contract is "this was transient, retrying may succeed". A stale
  -- p_expected_version is the opposite: it is deterministic, and every
  -- retry of the identical request will fail identically. Spelling it
  -- '40001' invited the layer in front of PostgREST to retry it, and it
  -- did: measured in production 2026-08-03, `network-center-admin.mjs
  -- set-rollout` with a stale --expected-version did not return at all --
  -- two multi-minute timeouts, then HTTP 504 -- while the identical call
  -- issued through the Management API answered instantly with the refusal.
  -- So the one refusal an operator is most likely to hit (someone else
  -- moved the rollout since they read the status) was the one the supported
  -- tool could not report.
  --
  -- 55000 (object_not_in_prerequisite_state) is this codebase's existing
  -- idiom for a state precondition that was not met -- the same code the
  -- changes_paused refusal and the managed-resource immutability guards
  -- use -- and it is outside class 40, so nothing treats it as retryable.
  -- The message text is unchanged so existing operator runbooks and log
  -- greps still match; only the class changes, plus DETAIL/HINT, which
  -- PostgREST surfaces as `details` and `hint` so the operator learns the
  -- version they should have sent WITHOUT a second round trip.
  --
  -- Scope: this function is REVOKEd from anon/authenticated and granted only
  -- to service_role, and its sole caller is scripts/network-center-admin.mjs.
  -- No browser code keys on its SQLSTATE. The unrelated user-facing CAS in
  -- network_center_update_settings_v1 -- which src/lib/network-center/
  -- supabaseRepository.ts DOES key on as '40001' -- is untouched.
  -- =====================================================================
  IF v_settings.version <> p_expected_version THEN
    RAISE EXCEPTION 'Network rollout changed; reload status before updating'
      USING ERRCODE = '55000',
        DETAIL = format(
          'buildingId=%s expectedVersion=%s actualVersion=%s rolloutState=%s',
          v_building.id, p_expected_version, v_settings.version,
          v_settings.rollout_state
        ),
        HINT = 'Re-read network_center_admin_status_v1 and retry set-rollout with the version it reports.';
  END IF;

  -- Upward transitions must pass OFF -> READ_ONLY -> EXECUTE. Downward transitions
  -- are always fail-safe. Executions that already recorded EXECUTION_STARTED may
  -- complete; the worker admission gates reject every new execution after commit.
  IF v_settings.rollout_state = 'OFF' AND v_target = 'EXECUTE' THEN
    RAISE EXCEPTION 'Network rollout must pass through READ_ONLY before EXECUTE'
      USING ERRCODE = '22023';
  END IF;
  IF v_settings.rollout_state = 'OFF' AND v_target NOT IN ('OFF', 'READ_ONLY') THEN
    RAISE EXCEPTION 'Invalid Network rollout transition' USING ERRCODE = '22023';
  END IF;
  IF v_settings.rollout_state = 'READ_ONLY'
     AND v_target NOT IN ('OFF', 'READ_ONLY', 'EXECUTE') THEN
    RAISE EXCEPTION 'Invalid Network rollout transition' USING ERRCODE = '22023';
  END IF;

  IF v_settings.rollout_state = v_target THEN
    RETURN jsonb_build_object(
      'organizationId', v_building.organization_id,
      'buildingId', v_building.id,
      'rolloutState', v_target,
      'previousRolloutState', v_settings.rollout_state,
      'version', v_settings.version,
      'changed', false
    );
  END IF;

  UPDATE public.network_site_settings settings
  SET rollout_state = v_target,
      version = settings.version + 1,
      updated_at = clock_timestamp()
  WHERE settings.id = v_settings.id
  RETURNING settings.version INTO v_new_version;

  INSERT INTO public.network_audit_events (
    organization_id,
    building_id,
    actor_type,
    action,
    target_type,
    target_id,
    target_display,
    reason,
    validation,
    result,
    outcome,
    request_id,
    occurred_at
  ) VALUES (
    v_building.organization_id,
    v_building.id,
    'SYSTEM',
    'admin.set_rollout',
    'building',
    v_building.id,
    jsonb_build_object('buildingName', v_building.name),
    btrim(p_reason),
    jsonb_build_object(
      'expectedVersion', p_expected_version,
      'previousRolloutState', v_settings.rollout_state
    ),
    jsonb_build_object(
      'rolloutState', v_target,
      'version', v_new_version
    ),
    'SUCCEEDED',
    p_request_id,
    clock_timestamp()
  );

  RETURN jsonb_build_object(
    'organizationId', v_building.organization_id,
    'buildingId', v_building.id,
    'rolloutState', v_target,
    'previousRolloutState', v_settings.rollout_state,
    'version', v_new_version,
    'changed', true
  );
END;
$$;








--
-- Name: FUNCTION network_center_admin_set_rollout_v1(p_building_id uuid, p_rollout_state text, p_expected_version bigint, p_reason text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_set_rollout_v1(p_building_id uuid, p_rollout_state text, p_expected_version bigint, p_reason text, p_request_id uuid) IS 'Service-role-only CAS rollout transition with durable SYSTEM audit.';








--
-- Name: network_center_admin_set_worker_assignments_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_set_worker_assignments_v1(p_worker_key text, p_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_worker_id uuid;
  v_assignment_count integer;
BEGIN
  IF p_worker_key IS NULL OR p_worker_key !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
     OR p_assignments IS NULL
     OR jsonb_typeof(p_assignments) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_assignments) > 100 THEN
    RAISE EXCEPTION 'Invalid worker assignment update request'
      USING ERRCODE = '22023';
  END IF;

  SELECT worker.id
  INTO v_worker_id
  FROM public.network_workers worker
  WHERE worker.worker_key = p_worker_key
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Worker not found' USING ERRCODE = 'P0002';
  END IF;

  v_assignment_count := app_private.network_center_replace_worker_assignments_v1(
    v_worker_id,
    p_assignments,
    true,
    'service_role:assign'
  );

  UPDATE public.network_workers worker
  SET version = worker.version + 1
  WHERE worker.id = v_worker_id;

  RETURN jsonb_build_object(
    'workerId', v_worker_id,
    'workerKey', p_worker_key,
    'assignmentCount', v_assignment_count
  );
END;
$_$;








--
-- Name: network_center_admin_status_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_status_v1(p_building_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_settings jsonb;
  v_connections jsonb;
  v_workers jsonb;
  v_credentials jsonb;
  v_assignments jsonb;
  v_compatibility jsonb;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Network Center status limit must be between 1 and 200'
      USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_settings
  FROM (
    SELECT settings.organization_id AS "organizationId",
      settings.building_id AS "buildingId",
      settings.rollout_state AS "rolloutState",
      settings.changes_paused AS "changesPaused",
      settings.monitoring_enabled AS "monitoringEnabled",
      settings.version,
      settings.updated_at AS "updatedAt"
    FROM public.network_site_settings settings
    WHERE p_building_id IS NULL OR settings.building_id = p_building_id
    ORDER BY settings.organization_id, settings.building_id
    LIMIT p_limit
  ) row_data;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_connections
  FROM (
    SELECT connection.organization_id AS "organizationId",
      connection.building_id AS "buildingId",
      connection.device_id AS "deviceId",
      connection.id AS "connectionId",
      connection.transport,
      host(connection.management_ip) AS "managementIp",
      connection.management_port AS "managementPort",
      connection.credential_ref AS "credentialRef",
      connection.host_key_fingerprint AS "hostKeyFingerprint",
      connection.is_enabled AS enabled,
      connection.updated_at AS "updatedAt"
    FROM public.network_device_connections connection
    WHERE p_building_id IS NULL OR connection.building_id = p_building_id
    ORDER BY connection.organization_id, connection.building_id, connection.id
    LIMIT p_limit
  ) row_data;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_workers
  FROM (
    SELECT worker.id AS "workerId", worker.worker_key AS "workerKey",
      worker.display_name AS "displayName", worker.status,
      worker.capabilities, worker.version, worker.updated_at AS "updatedAt"
    FROM public.network_workers worker
    WHERE p_building_id IS NULL OR EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      WHERE assignment.worker_id = worker.id
        AND assignment.building_id = p_building_id
        AND assignment.active_until IS NULL
    )
    ORDER BY worker.worker_key
    LIMIT p_limit
  ) row_data;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_credentials
  FROM (
    SELECT worker.worker_key AS "workerKey",
      credential.fingerprint,
      credential.not_before AS "notBefore",
      credential.expires_at AS "expiresAt",
      credential.revoked_at AS "revokedAt",
      credential.last_used_at AS "lastUsedAt"
    FROM public.network_worker_credentials credential
    JOIN public.network_workers worker ON worker.id = credential.worker_id
    WHERE p_building_id IS NULL OR EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      WHERE assignment.worker_id = worker.id
        AND assignment.building_id = p_building_id
        AND assignment.active_until IS NULL
    )
    ORDER BY worker.worker_key, credential.not_before DESC, credential.id
    LIMIT p_limit
  ) row_data;

  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_assignments
  FROM (
    SELECT worker.worker_key AS "workerKey",
      assignment.organization_id AS "organizationId",
      assignment.building_id AS "buildingId",
      assignment.device_id AS "deviceId",
      assignment.can_poll AS "canPoll",
      assignment.can_inventory AS "canInventory",
      assignment.can_execute AS "canExecute",
      assignment.active_from AS "activeFrom",
      assignment.active_until AS "activeUntil",
      assignment.assignment_version AS "assignmentVersion"
    FROM public.network_worker_assignments assignment
    JOIN public.network_workers worker ON worker.id = assignment.worker_id
    WHERE p_building_id IS NULL OR assignment.building_id = p_building_id
    ORDER BY worker.worker_key, assignment.organization_id,
      assignment.building_id, assignment.device_id
    LIMIT p_limit
  ) row_data;

  -- Forward fix. `enabled` is the live compatibility window, expressed with the
  -- same predicate the compatibility admission helpers use, and
  -- `cutoverFinalizedAt` is the one-way finalize stamp.
  SELECT coalesce(jsonb_agg(to_jsonb(row_data)), '[]'::jsonb)
  INTO v_compatibility
  FROM (
    SELECT worker.worker_key AS "workerKey",
      (
        state.finalized_at IS NULL
        AND state.expires_at > clock_timestamp()
      ) AS enabled,
      state.finalized_at AS "cutoverFinalizedAt"
    FROM app_private.network_worker_compatibility_state state
    JOIN public.network_workers worker ON worker.id = state.worker_id
    ORDER BY worker.worker_key
    LIMIT p_limit
  ) row_data;

  RETURN jsonb_build_object(
    'settings', v_settings,
    'connections', v_connections,
    'workers', v_workers,
    'credentialWindows', v_credentials,
    'assignments', v_assignments,
    'compatibility', v_compatibility
  );
END;
$$;








--
-- Name: FUNCTION network_center_admin_status_v1(p_building_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_status_v1(p_building_id uuid, p_limit integer) IS 'Service-role-only bounded redacted Network Center control-plane status.';








--
-- Name: network_center_admin_worker_credential_status_v1(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_worker_credential_status_v1(p_worker_key text, p_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_status jsonb;
BEGIN
  IF p_worker_key IS NULL
     OR p_worker_key !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
     OR p_fingerprint IS NULL
     OR p_fingerprint !~ '^sha256:[a-f0-9]{12,64}$' THEN
    RAISE EXCEPTION 'Invalid worker credential status request'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'found', true,
    'workerKey', worker.worker_key,
    'credentialFingerprint', credential.fingerprint,
    'notBefore', credential.not_before,
    'expiresAt', credential.expires_at,
    'revokedAt', credential.revoked_at
  )
  INTO v_status
  FROM public.network_worker_credentials credential
  JOIN public.network_workers worker ON worker.id = credential.worker_id
  WHERE worker.worker_key = p_worker_key
    AND credential.fingerprint = p_fingerprint;

  IF v_status IS NULL THEN
    RETURN jsonb_build_object(
      'found', false,
      'workerKey', p_worker_key,
      'credentialFingerprint', p_fingerprint
    );
  END IF;

  RETURN v_status;
END;
$_$;








--
-- Name: FUNCTION network_center_admin_worker_credential_status_v1(p_worker_key text, p_fingerprint text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_worker_credential_status_v1(p_worker_key text, p_fingerprint text) IS 'Service-role-only exact worker and fingerprint readback for ambiguous admin mutations.';








--
-- Name: network_center_admin_worker_release_status_v1(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_admin_worker_release_status_v1(p_worker_key text, p_worker_version text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_release_heartbeat jsonb;
  v_now timestamptz := statement_timestamp();
BEGIN
  IF p_worker_key IS NULL
     OR p_worker_key !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
     OR p_worker_version IS NULL
     OR octet_length(p_worker_version) <> 40
     OR p_worker_version !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'Invalid worker release status request'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'schemaVersion', 1,
    'workerKey', worker.worker_key,
    'displayName', worker.display_name,
    'workerVersion', heartbeat.worker_version,
    'status', heartbeat.status,
    'heartbeatAt', heartbeat.heartbeat_at,
    'startedAt', heartbeat.started_at,
    'assignedBuildingCount', heartbeat.assigned_building_count,
    'activeAssignedBuildingCount',
      assignment_evidence.active_assigned_building_count,
    'activeAssignmentCount', assignment_evidence.active_assignment_count,
    'activeAssignmentHash', assignment_evidence.active_assignment_hash,
    'expectedConnectionCount',
      app_private.network_center_worker_expected_connections_v1(
        worker.id, v_now
      ),
    'connectionCount', heartbeat.connection_count,
    'successfulPollCount', heartbeat.successful_poll_count,
    'failedPollCount', heartbeat.failed_poll_count,
    'pollObservedAt', heartbeat.poll_observed_at
  )
  INTO v_release_heartbeat
  FROM app_private.network_worker_release_heartbeats heartbeat
  JOIN public.network_workers worker ON worker.id = heartbeat.worker_id
  CROSS JOIN LATERAL (
    WITH effective_assignments AS MATERIALIZED (
      SELECT assignment.organization_id,
        assignment.building_id,
        concat_ws(
          '|',
          'network-worker-assignment-v1',
          assignment.id::text,
          assignment.worker_id::text,
          assignment.organization_id::text,
          assignment.building_id::text,
          assignment.device_id::text,
          assignment.device_kind,
          assignment.assignment_version::text,
          CASE WHEN assignment.can_poll THEN '1' ELSE '0' END,
          CASE WHEN assignment.can_inventory THEN '1' ELSE '0' END,
          CASE WHEN assignment.can_execute THEN '1' ELSE '0' END,
          to_char(
            assignment.active_from AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
          ),
          coalesce(
            to_char(
              assignment.active_until AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            ),
            '-'
          )
        ) AS canonical_row
      FROM public.network_worker_assignments assignment
      WHERE assignment.worker_id = worker.id
        AND worker.status IN ('ACTIVE', 'DRAINING')
        AND 'HEARTBEAT' = ANY(worker.capabilities)
        AND assignment.active_from <= v_now
        AND (
          assignment.active_until IS NULL
          OR assignment.active_until > v_now
        )
        AND (
          assignment.can_poll OR assignment.can_inventory
          OR assignment.can_execute
        )
    )
    SELECT count(DISTINCT (organization_id, building_id))::integer
        AS active_assigned_building_count,
      count(*)::integer AS active_assignment_count,
      encode(
        extensions.digest(
          convert_to(
            coalesce(string_agg(
              canonical_row,
              E'\n' ORDER BY canonical_row COLLATE "C"
            ), ''),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ) AS active_assignment_hash
    FROM effective_assignments
  ) assignment_evidence
  WHERE worker.worker_key = p_worker_key
    AND heartbeat.worker_version = p_worker_version;

  RETURN v_release_heartbeat;
END;
$_$;








--
-- Name: FUNCTION network_center_admin_worker_release_status_v1(p_worker_key text, p_worker_version text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_admin_worker_release_status_v1(p_worker_key text, p_worker_version text) IS 'Service-role-only exact worker and release readback with canonical active-assignment evidence and the server-derived expected pollable connection count the deployment gate compares the reported poll evidence against. The expectation comes from app_private.network_center_worker_expected_connections_v1, the same predicate the heartbeat honesty guard uses.';








--
-- Name: network_center_cancel_maintenance_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_cancel_maintenance_v1(p_building_id uuid, p_maintenance_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_window public.network_maintenance_windows%ROWTYPE;
  v_hash text;
  v_replay jsonb;
  v_result jsonb;
BEGIN
  IF p_maintenance_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Maintenance and request identifiers are required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_execute_v1(p_building_id);
  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'cancel_maintenance', 'buildingId', p_building_id,
    'maintenanceId', p_maintenance_id
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash, 'cancel_maintenance'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT maintenance.* INTO v_window
  FROM public.network_maintenance_windows maintenance
  WHERE maintenance.organization_id = v_scope.organization_id
    AND maintenance.building_id = p_building_id AND maintenance.id = p_maintenance_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Maintenance window not found' USING ERRCODE = 'P0002'; END IF;
  IF v_window.status NOT IN ('CANCELLED', 'COMPLETED') THEN
    UPDATE public.network_maintenance_windows
    SET status = 'CANCELLED', cancelled_at = clock_timestamp(),
        cancelled_by = v_scope.actor_id,
        cancellation_reason = 'Cancelled from Network Center', version = version + 1
    WHERE id = p_maintenance_id;
  END IF;
  SELECT jsonb_build_object(
    'id', maintenance.id, 'status', maintenance.status,
    'cancelledAt', maintenance.cancelled_at
  ) INTO v_result FROM public.network_maintenance_windows maintenance
  WHERE maintenance.id = p_maintenance_id;
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_building_id, v_scope.actor_id,
    'cancel_maintenance', 'maintenance', p_maintenance_id,
    jsonb_build_object('buildingName', v_scope.building_name),
    'Cancel maintenance window', '{}'::jsonb, v_result,
    'SUCCEEDED', NULL, p_request_id, v_hash
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_compare_snapshots_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_compare_snapshots_v1(p_building_id uuid, p_from_snapshot_id uuid, p_to_snapshot_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_scope record; v_from jsonb; v_to jsonb; v_result jsonb;
BEGIN
  SELECT * INTO v_scope FROM app_private.network_center_require_view_v1(p_building_id);
  SELECT snapshot.redacted_lines INTO v_from
  FROM public.network_config_snapshots snapshot
  WHERE snapshot.organization_id = v_scope.organization_id
    AND snapshot.building_id = p_building_id AND snapshot.id = p_from_snapshot_id;
  SELECT snapshot.redacted_lines INTO v_to
  FROM public.network_config_snapshots snapshot
  WHERE snapshot.organization_id = v_scope.organization_id
    AND snapshot.building_id = p_building_id AND snapshot.id = p_to_snapshot_id;
  IF v_from IS NULL OR v_to IS NULL THEN
    RAISE EXCEPTION 'Snapshot not found' USING ERRCODE = 'P0002';
  END IF;

  WITH old_lines AS (
    SELECT ordinality AS line_no, value AS line
    FROM jsonb_array_elements_text(v_from) WITH ORDINALITY
  ), new_lines AS (
    SELECT ordinality AS line_no, value AS line
    FROM jsonb_array_elements_text(v_to) WITH ORDINALITY
  ), diff AS (
    SELECT old_lines.line_no, 0 AS position,
      CASE WHEN old_lines.line IS NOT DISTINCT FROM new_lines.line THEN 'context' ELSE 'removed' END AS kind,
      old_lines.line AS text
    FROM old_lines FULL JOIN new_lines USING (line_no)
    WHERE old_lines.line IS NOT NULL
    UNION ALL
    SELECT new_lines.line_no, 1 AS position, 'added', new_lines.line
    FROM new_lines LEFT JOIN old_lines USING (line_no)
    WHERE new_lines.line IS DISTINCT FROM old_lines.line
  )
  SELECT jsonb_build_object(
    'fromRevisionId', p_from_snapshot_id,
    'toRevisionId', p_to_snapshot_id,
    'changeCount', count(*) FILTER (WHERE kind <> 'context'),
    'lines', coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'text', text)
      ORDER BY line_no, position), '[]'::jsonb)
  ) INTO v_result FROM diff;
  RETURN v_result;
END;
$$;








--
-- Name: network_center_create_maintenance_v1(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_create_maintenance_v1(p_building_id uuid, p_duration_minutes integer, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_hash text;
  v_existing public.network_maintenance_windows%ROWTYPE;
  v_window public.network_maintenance_windows%ROWTYPE;
  v_result jsonb;
BEGIN
  IF p_request_id IS NULL OR p_duration_minutes NOT BETWEEN 5 AND 480
     OR char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'Invalid maintenance request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_execute_v1(p_building_id);
  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'create_maintenance', 'buildingId', p_building_id,
    'durationMinutes', p_duration_minutes, 'reason', v_reason
  )::text, 'sha256'), 'hex');

  SELECT maintenance.* INTO v_existing
  FROM public.network_maintenance_windows maintenance
  WHERE maintenance.organization_id = v_scope.organization_id
    AND maintenance.created_by = v_scope.actor_id
    AND maintenance.idempotency_key = p_request_id::text
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.request_hash IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION 'Idempotency key reused with different maintenance input' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'id', v_existing.id, 'reason', v_existing.reason,
      'startsAt', v_existing.starts_at, 'endsAt', v_existing.ends_at,
      'status', v_existing.status
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.network_maintenance_windows maintenance
    WHERE maintenance.organization_id = v_scope.organization_id
      AND maintenance.building_id = p_building_id
      AND maintenance.status IN ('SCHEDULED', 'ACTIVE')
      AND maintenance.ends_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'A maintenance window is already active for this building'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.network_maintenance_windows (
    organization_id, building_id, status, starts_at, ends_at, reason,
    created_by, request_hash, idempotency_key
  ) VALUES (
    v_scope.organization_id, p_building_id, 'ACTIVE', clock_timestamp(),
    clock_timestamp() + make_interval(mins => p_duration_minutes), v_reason,
    v_scope.actor_id, v_hash, p_request_id::text
  ) RETURNING * INTO v_window;
  v_result := jsonb_build_object(
    'id', v_window.id, 'reason', v_window.reason,
    'startsAt', v_window.starts_at, 'endsAt', v_window.ends_at,
    'status', v_window.status
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_building_id, v_scope.actor_id,
    'create_maintenance', 'maintenance', v_window.id,
    jsonb_build_object('buildingName', v_scope.building_name), v_reason,
    jsonb_build_object('durationMinutes', p_duration_minutes), v_result,
    'SUCCEEDED', NULL, p_request_id, v_hash
  );
  INSERT INTO public.network_outbox_events (
    organization_id, building_id, event_type, aggregate_type, aggregate_id, payload, occurred_at
  ) VALUES (
    v_scope.organization_id, p_building_id, 'network.maintenance.started',
    'maintenance', v_window.id, jsonb_build_object('endsAt', v_window.ends_at), clock_timestamp()
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_execute_action_v1(uuid, text, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_execute_action_v1(p_device_id uuid, p_action_type text, p_reason text, p_parameters jsonb, p_confirmation text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_device public.network_devices%ROWTYPE;
  v_scope record;
  v_action text := upper(btrim(coalesce(p_action_type, '')));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_parameters jsonb := coalesce(p_parameters, '{}'::jsonb);
  v_sanitized jsonb := '{}'::jsonb;
  v_interface public.network_interfaces%ROWTYPE;
  v_interface_id uuid;
  v_duration integer;
  v_identity text;
  v_hash text;
  v_replay jsonb;
  v_target jsonb;
  v_command_id uuid;
  v_result jsonb;
BEGIN
  IF p_device_id IS NULL OR p_request_id IS NULL
     OR v_action NOT IN (
       'FLUSH_DNS_CACHE', 'RENEW_DHCP_LEASE',
       'CYCLE_ACCESS_PORT', 'REBOOT_ROUTER'
     )
     OR char_length(v_reason) NOT BETWEEN 8 AND 1000
     OR jsonb_typeof(v_parameters) <> 'object'
     OR octet_length(v_parameters::text) > 16384 THEN
    RAISE EXCEPTION 'Invalid Network Center action request'
      USING ERRCODE = '22023';
  END IF;

  IF v_action = 'CYCLE_ACCESS_PORT' THEN
    IF coalesce(v_parameters->>'interfaceId', '') !~
         '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       OR coalesce(v_parameters->>'durationSeconds', '') !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Invalid access-port parameters' USING ERRCODE = '22023';
    END IF;
    v_interface_id := (v_parameters->>'interfaceId')::uuid;
    v_duration := (v_parameters->>'durationSeconds')::integer;
    IF v_duration NOT BETWEEN 5 AND 30 THEN
      RAISE EXCEPTION 'Access-port cycle must be between 5 and 30 seconds'
        USING ERRCODE = '22023';
    END IF;
    v_sanitized := jsonb_build_object('durationSeconds', v_duration);
  ELSIF v_parameters <> '{}'::jsonb THEN
    RAISE EXCEPTION 'This action does not accept parameters'
      USING ERRCODE = '22023';
  END IF;

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', v_action,
    'deviceId', p_device_id,
    'interfaceId', v_interface_id,
    'reason', v_reason,
    'parameters', v_sanitized
  )::text, 'sha256'), 'hex');

  SELECT device.* INTO v_device
  FROM public.network_devices device
  WHERE device.id = p_device_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Writable MikroTik not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_scope
  FROM app_private.network_center_require_execute_v1(v_device.building_id);

  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash,
    lower(v_action)
  );
  IF v_replay IS NOT NULL THEN
    RETURN v_replay;
  END IF;

  SELECT device.* INTO v_device
  FROM public.network_devices device
  WHERE device.id = p_device_id
    AND device.organization_id = v_scope.organization_id
    AND device.device_kind = 'MIKROTIK'
    AND device.is_active
    AND device.write_capability
    AND device.lifecycle_status IN ('ONLINE', 'OFFLINE')
    AND EXISTS (
      SELECT 1
      FROM public.network_device_connections connection
      WHERE connection.organization_id = device.organization_id
        AND connection.building_id = device.building_id
        AND connection.device_id = device.id
        AND connection.is_enabled
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Writable MikroTik not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.network_site_settings settings
    WHERE settings.organization_id = v_scope.organization_id
      AND settings.building_id = v_device.building_id
      AND NOT settings.changes_paused
  ) THEN
    RAISE EXCEPTION 'Network changes are paused for this building'
      USING ERRCODE = '55000';
  END IF;

  SELECT coalesce(current_state.identity_name, v_device.display_name)
  INTO v_identity
  FROM public.network_device_current current_state
  WHERE current_state.device_id = v_device.id;
  v_identity := coalesce(v_identity, v_device.display_name);

  IF v_action IN ('CYCLE_ACCESS_PORT', 'REBOOT_ROUTER')
     AND p_confirmation IS DISTINCT FROM v_identity THEN
    RAISE EXCEPTION 'Router confirmation does not match the current identity'
      USING ERRCODE = '22023';
  END IF;

  IF v_action = 'CYCLE_ACCESS_PORT' THEN
    SELECT interface.* INTO v_interface
    FROM public.network_interfaces interface
    WHERE interface.organization_id = v_scope.organization_id
      AND interface.building_id = v_device.building_id
      AND interface.device_id = v_device.id
      AND interface.id = v_interface_id
      AND interface.interface_role = 'ACCESS'
      AND NOT interface.is_protected
      AND interface.is_enabled
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Access port is invalid or protected'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_target := jsonb_build_object(
    'buildingId', v_device.building_id,
    'buildingName', v_scope.building_name,
    'deviceId', v_device.id,
    'routerIdentity', v_identity,
    'interfaceId', v_interface_id,
    'interfaceName', v_interface.display_name
  );
  v_command_id := app_private.network_center_enqueue_command_v1(
    v_scope.organization_id, v_device.building_id, v_device.id, v_interface_id,
    v_action, v_reason, v_sanitized, v_target, v_scope.actor_id,
    v_hash, p_request_id::text, clock_timestamp()
  );
  INSERT INTO public.network_command_events (
    organization_id, building_id, command_id, event_seq, event_kind,
    occurred_at, actor_id, payload
  ) VALUES (
    v_scope.organization_id, v_device.building_id, v_command_id, 1, 'QUEUED',
    clock_timestamp(), v_scope.actor_id,
    jsonb_build_object('actionType', v_action)
  ) ON CONFLICT (command_id, event_seq) DO NOTHING;
  v_result := jsonb_build_object(
    'commandId', v_command_id,
    'status', 'QUEUED',
    'actionType', v_action,
    'reason', v_reason,
    'parameters', v_sanitized,
    'target', v_target
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, v_device.building_id, v_scope.actor_id,
    lower(v_action), 'device', v_device.id, v_target, v_reason,
    jsonb_build_object(
      'permission', 'network_center.execute',
      'confirmationValidated', true
    ),
    v_result, 'ACCEPTED', v_command_id, p_request_id, v_hash
  );
  INSERT INTO public.network_outbox_events (
    organization_id, building_id, event_type, aggregate_type, aggregate_id,
    payload, occurred_at
  ) VALUES (
    v_scope.organization_id, v_device.building_id, 'network.command.queued',
    'command', v_command_id, jsonb_build_object('actionType', v_action),
    clock_timestamp()
  );
  RETURN v_result;
END;
$_$;








--
-- Name: network_center_get_building_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_get_building_v1(p_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_payload jsonb;
  v_rollout_state text;
BEGIN
  v_payload := app_private.network_center_get_building_base_v1(p_building_id);
  SELECT coalesce(settings.rollout_state, 'OFF')
  INTO v_rollout_state
  FROM public.network_site_settings settings
  WHERE settings.building_id = p_building_id;

  RETURN v_payload || jsonb_build_object(
    'rolloutState', coalesce(v_rollout_state, 'OFF')
  );
END;
$$;








--
-- Name: network_center_get_command_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_get_command_v1(p_building_id uuid, p_command_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_command public.network_commands%ROWTYPE;
  v_scope record;
BEGIN
  IF p_building_id IS NULL
     OR ((p_command_id IS NULL) = (p_request_id IS NULL)) THEN
    RAISE EXCEPTION 'Exactly one command or request identity is required'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope
  FROM app_private.network_center_require_view_v1(p_building_id);
  SELECT command.* INTO v_command
  FROM public.network_commands command
  WHERE command.organization_id = v_scope.organization_id
    AND command.building_id = p_building_id
    AND (
      (p_command_id IS NOT NULL AND command.id = p_command_id)
      OR (
        p_request_id IS NOT NULL
        AND command.idempotency_key = p_request_id::text
        AND command.requested_by = auth.uid()
      )
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network Center command not found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object(
    'id', v_command.id,
    'requestId', v_command.idempotency_key,
    'actionType', v_command.action_type,
    'reason', v_command.reason,
    'parameters', v_command.sanitized_parameters,
    'target', v_command.target_display,
    'requestedBy', v_command.requested_by,
    'status', v_command.status,
    'attemptCount', v_command.attempt_count,
    'result', v_command.result,
    'rollback', v_command.rollback,
    'reconciliationState', v_command.reconciliation_state,
    'transitionVersion', v_command.transition_version,
    'createdAt', v_command.created_at,
    'startedAt', v_command.started_at,
    'finishedAt', v_command.finished_at
  );
END;
$$;








--
-- Name: network_center_list_aruba_v1(uuid, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_list_aruba_v1(p_building_id uuid, p_after_sort_order integer DEFAULT NULL::integer, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_result jsonb;
BEGIN
  IF p_limit IS NULL
     OR p_limit NOT BETWEEN 1 AND 250
     OR ((p_after_sort_order IS NULL) <> (p_after_id IS NULL)) THEN
    RAISE EXCEPTION 'Invalid Aruba cursor' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope
  FROM app_private.network_center_require_view_v1(p_building_id);

  WITH page AS (
    SELECT
      device.id, device.sort_order, device.display_name, device.model,
      device.external_key, device.lifecycle_status,
      current_state.reachable, current_state.health_status,
      current_state.last_seen_at,
      coalesce(
        (
          SELECT host(connection.management_ip)
          FROM public.network_device_connections connection
          WHERE connection.device_id = device.id AND connection.is_enabled
          ORDER BY connection.id
          LIMIT 1
        ),
        nullif(device.inventory_metadata->>'managementAddress', '')
      ) AS management_address
    FROM public.network_devices device
    LEFT JOIN public.network_device_current current_state
      ON current_state.device_id = device.id
    WHERE device.organization_id = v_scope.organization_id
      AND device.building_id = p_building_id
      AND device.device_kind = 'ARUBA'
      AND device.is_active
      AND (
        p_after_id IS NULL
        OR ROW(device.sort_order, device.id) >
           ROW(p_after_sort_order, p_after_id)
      )
    ORDER BY device.sort_order, device.id
    LIMIT p_limit + 1
  ), items AS (
    SELECT * FROM page ORDER BY sort_order, id LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', item.id,
        'name', item.display_name,
        'model', item.model,
        'externalKey', item.external_key,
        'lifecycleStatus', item.lifecycle_status,
        'reachable', coalesce(item.reachable, false),
        'healthStatus', item.health_status,
        'lastSeenAt', item.last_seen_at,
        'address', item.management_address
      ) ORDER BY item.sort_order, item.id)
      FROM items item
    ), '[]'::jsonb),
    'nextCursor', CASE WHEN (SELECT count(*) FROM page) > p_limit THEN (
      SELECT jsonb_build_object('sortOrder', item.sort_order, 'id', item.id)
      FROM items item
      ORDER BY item.sort_order DESC, item.id DESC
      LIMIT 1
    ) ELSE NULL END
  ) INTO v_result;
  RETURN v_result;
END;
$$;








--
-- Name: network_center_list_audit_v1(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_list_audit_v1(p_building_id uuid, p_before_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_scope record; v_result jsonb;
BEGIN
  IF p_limit NOT BETWEEN 1 AND 100
     OR ((p_before_occurred_at IS NULL) <> (p_before_id IS NULL)) THEN
    RAISE EXCEPTION 'Invalid audit cursor' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_view_v1(p_building_id);
  WITH page AS (
    SELECT audit.* FROM public.network_audit_events audit
    WHERE audit.organization_id = v_scope.organization_id
      AND audit.building_id = p_building_id
      AND (p_before_id IS NULL OR ROW(audit.occurred_at, audit.id) < ROW(p_before_occurred_at, p_before_id))
    ORDER BY audit.occurred_at DESC, audit.id DESC LIMIT p_limit + 1
  ), items AS (
    SELECT * FROM page ORDER BY occurred_at DESC, id DESC LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'items', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', item.id, 'at', item.occurred_at, 'actorType', item.actor_type,
      'actorId', item.actor_id, 'workerId', item.worker_id,
      'action', item.action, 'targetType', item.target_type,
      'targetId', item.target_id, 'target', item.target_display,
      'reason', item.reason, 'validation', item.validation,
      'result', item.result, 'outcome', item.outcome, 'commandId', item.command_id
    ) ORDER BY item.occurred_at DESC, item.id DESC) FROM items item), '[]'::jsonb),
    'nextCursor', CASE WHEN (SELECT count(*) FROM page) > p_limit THEN (
      SELECT jsonb_build_object('occurredAt', item.occurred_at, 'id', item.id)
      FROM items item ORDER BY item.occurred_at, item.id LIMIT 1
    ) ELSE NULL END
  ) INTO v_result;
  RETURN v_result;
END;
$$;








--
-- Name: network_center_list_clients_v1(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_list_clients_v1(p_building_id uuid, p_before_seen_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_scope record; v_result jsonb;
BEGIN
  IF p_limit NOT BETWEEN 1 AND 100
     OR ((p_before_seen_at IS NULL) <> (p_before_id IS NULL)) THEN
    RAISE EXCEPTION 'Invalid client cursor' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_view_v1(p_building_id);

  WITH page AS (
    SELECT client.*, link.room_id, link.contract_id, link.customer_id,
           room.name AS room_name, customer.full_name AS customer_name
    FROM public.network_client_current client
    LEFT JOIN LATERAL (
      SELECT candidate.room_id, candidate.contract_id, candidate.customer_id
      FROM public.network_client_links candidate
      WHERE candidate.organization_id = client.organization_id
        AND candidate.building_id = client.building_id
        AND candidate.client_fingerprint = client.client_fingerprint
        AND candidate.valid_from <= client.observed_at
        AND (candidate.valid_to IS NULL OR candidate.valid_to > client.observed_at)
      ORDER BY candidate.confidence DESC, candidate.valid_from DESC, candidate.id DESC
      LIMIT 1
    ) link ON true
    LEFT JOIN public.rooms room ON room.id = link.room_id
    LEFT JOIN public.customers customer ON customer.id = link.customer_id
    WHERE client.organization_id = v_scope.organization_id
      AND client.building_id = p_building_id
       AND client.expires_at > statement_timestamp()
      AND (p_before_id IS NULL OR ROW(client.last_seen_at, client.id) < ROW(p_before_seen_at, p_before_id))
    ORDER BY client.last_seen_at DESC, client.id DESC
    LIMIT p_limit + 1
  ), items AS (
    SELECT * FROM page ORDER BY last_seen_at DESC, id DESC LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'items', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', item.id, 'hostname', item.hostname, 'address', host(item.observed_ip),
      'macAddress', item.observed_mac::text, 'sessionType', item.session_type,
      'connectionType', item.connection_type, 'roomHint', coalesce(item.room_name, item.room_hint),
      'customerName', item.customer_name, 'roomId', item.room_id,
      'contractId', item.contract_id, 'customerId', item.customer_id,
      'rxBps', item.rx_bps, 'txBps', item.tx_bps,
      'randomizedMac', item.randomized_mac, 'sessionIdentity', item.session_key,
      'lastSeenAt', item.last_seen_at, 'expiresAt', item.expires_at
    ) ORDER BY item.last_seen_at DESC, item.id DESC) FROM items item), '[]'::jsonb),
    'nextCursor', CASE WHEN (SELECT count(*) FROM page) > p_limit THEN (
      SELECT jsonb_build_object('seenAt', item.last_seen_at, 'id', item.id)
      FROM items item ORDER BY item.last_seen_at, item.id LIMIT 1
    ) ELSE NULL END
  ) INTO v_result;
  RETURN v_result;
END;
$$;








--
-- Name: network_center_list_commands_v1(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_list_commands_v1(p_building_id uuid, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_scope record; v_result jsonb;
BEGIN
  IF p_limit NOT BETWEEN 1 AND 100
     OR ((p_before_created_at IS NULL) <> (p_before_id IS NULL)) THEN
    RAISE EXCEPTION 'Invalid command cursor' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_view_v1(p_building_id);
  WITH page AS (
    SELECT command.* FROM public.network_commands command
    WHERE command.organization_id = v_scope.organization_id
      AND command.building_id = p_building_id
      AND (p_before_id IS NULL OR ROW(command.created_at, command.id) < ROW(p_before_created_at, p_before_id))
    ORDER BY command.created_at DESC, command.id DESC LIMIT p_limit + 1
  ), items AS (
    SELECT * FROM page ORDER BY created_at DESC, id DESC LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'items', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', item.id, 'actionType', item.action_type, 'reason', item.reason,
      'parameters', item.sanitized_parameters, 'target', item.target_display,
      'requestedBy', item.requested_by, 'status', item.status,
      'attemptCount', item.attempt_count, 'result', item.result,
      'rollback', item.rollback, 'reconciliationState', item.reconciliation_state,
      'createdAt', item.created_at, 'startedAt', item.started_at, 'finishedAt', item.finished_at
    ) ORDER BY item.created_at DESC, item.id DESC) FROM items item), '[]'::jsonb),
    'nextCursor', CASE WHEN (SELECT count(*) FROM page) > p_limit THEN (
      SELECT jsonb_build_object('createdAt', item.created_at, 'id', item.id)
      FROM items item ORDER BY item.created_at, item.id LIMIT 1
    ) ELSE NULL END
  ) INTO v_result;
  RETURN v_result;
END;
$$;








--
-- Name: network_center_list_fleet_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_list_fleet_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  WITH base AS (
    SELECT app_private.network_center_list_fleet_base_v1() AS payload
  ), items AS (
    SELECT entry.item, entry.ordinality
    FROM base
    CROSS JOIN LATERAL jsonb_array_elements(base.payload->'items')
      WITH ORDINALITY AS entry(item, ordinality)
  )
  SELECT jsonb_build_object(
    'items', coalesce(jsonb_agg(
      items.item || jsonb_build_object(
        'rolloutState', coalesce(settings.rollout_state, 'OFF')
      ) ORDER BY items.ordinality
    ), '[]'::jsonb)
  )
  FROM items
  LEFT JOIN public.network_site_settings settings
    ON settings.building_id = (items.item->>'buildingId')::uuid;
$$;








--
-- Name: network_center_pause_organization_v1(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_pause_organization_v1(p_anchor_building_id uuid, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_now timestamptz := clock_timestamp();
  v_hash text;
  v_replay jsonb;
  v_gate public.network_org_mutation_gates%ROWTYPE;
  v_result jsonb;
BEGIN
  IF p_anchor_building_id IS NULL OR p_request_id IS NULL
     OR char_length(v_reason) NOT BETWEEN 8 AND 500 THEN
    RAISE EXCEPTION 'Invalid Network Center organization pause request'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_scope
  FROM app_private.network_center_require_execute_permission_v1(
    p_anchor_building_id
  );

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'pause_organization',
    'buildingId', p_anchor_building_id,
    'reason', v_reason
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash,
    'pause_organization'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  INSERT INTO public.network_org_mutation_gates (
    organization_id, mutations_paused, paused_reason, paused_at, paused_by,
    version, updated_at
  ) VALUES (
    v_scope.organization_id, true, v_reason, v_now, v_scope.actor_id, 1, v_now
  )
  ON CONFLICT (organization_id) DO UPDATE SET
    mutations_paused = true,
    paused_reason = EXCLUDED.paused_reason,
    paused_at = EXCLUDED.paused_at,
    paused_by = EXCLUDED.paused_by,
    version = public.network_org_mutation_gates.version + 1,
    updated_at = EXCLUDED.updated_at
  RETURNING * INTO v_gate;

  v_result := jsonb_build_object(
    'organizationId', v_gate.organization_id,
    'mutationsPaused', v_gate.mutations_paused,
    'pausedAt', v_gate.paused_at,
    'version', v_gate.version
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_anchor_building_id, v_scope.actor_id,
    'pause_organization', 'organization', v_scope.organization_id,
    jsonb_build_object('buildingName', v_scope.building_name),
    v_reason,
    jsonb_build_object('permission', 'network_center.execute'),
    v_result, 'SUCCEEDED', NULL, p_request_id, v_hash
  );
  RETURN v_result;
END;
$$;








--
-- Name: FUNCTION network_center_pause_organization_v1(p_anchor_building_id uuid, p_reason text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_pause_organization_v1(p_anchor_building_id uuid, p_reason text, p_request_id uuid) IS 'Fleet-wide Network Center kill switch; execute-scoped and usable while paused.';








--
-- Name: network_center_request_snapshot_v1(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_request_snapshot_v1(p_device_id uuid, p_label text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_device public.network_devices%ROWTYPE;
  v_scope record;
  v_label text := btrim(coalesce(p_label, ''));
  v_hash text;
  v_replay jsonb;
  v_command_id uuid;
  v_target jsonb;
  v_result jsonb;
BEGIN
  IF p_device_id IS NULL OR p_request_id IS NULL
     OR char_length(v_label) NOT BETWEEN 3 AND 160 THEN
    RAISE EXCEPTION 'Invalid snapshot request' USING ERRCODE = '22023';
  END IF;

  SELECT device.* INTO v_device
  FROM public.network_devices device
  WHERE device.id = p_device_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active MikroTik not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_scope
  FROM app_private.network_center_require_execute_v1(v_device.building_id);

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'request_snapshot', 'deviceId', p_device_id, 'label', v_label
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash,
    'capture_configuration'
  );
  IF v_replay IS NOT NULL THEN
    RETURN v_replay;
  END IF;

  SELECT device.* INTO v_device
  FROM public.network_devices device
  WHERE device.id = p_device_id
    AND device.organization_id = v_scope.organization_id
    AND device.device_kind = 'MIKROTIK'
    AND device.is_active
    AND device.write_capability
    AND device.lifecycle_status IN ('ONLINE', 'OFFLINE')
    AND EXISTS (
      SELECT 1
      FROM public.network_device_connections connection
      WHERE connection.organization_id = device.organization_id
        AND connection.building_id = device.building_id
        AND connection.device_id = device.id
        AND connection.is_enabled
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active MikroTik not found' USING ERRCODE = 'P0002';
  END IF;

  v_target := jsonb_build_object(
    'buildingId', v_device.building_id,
    'buildingName', v_scope.building_name,
    'deviceId', v_device.id,
    'routerIdentity', v_device.display_name
  );
  v_command_id := app_private.network_center_enqueue_command_v1(
    v_scope.organization_id, v_device.building_id, v_device.id, NULL,
    'CAPTURE_SNAPSHOT', 'Capture configuration: ' || v_label,
    jsonb_build_object('label', v_label), v_target, v_scope.actor_id,
    v_hash, p_request_id::text, clock_timestamp()
  );
  INSERT INTO public.network_command_events (
    organization_id, building_id, command_id, event_seq, event_kind,
    occurred_at, actor_id, payload
  ) VALUES (
    v_scope.organization_id, v_device.building_id, v_command_id, 1, 'QUEUED',
    clock_timestamp(), v_scope.actor_id, jsonb_build_object('label', v_label)
  ) ON CONFLICT (command_id, event_seq) DO NOTHING;
  v_result := jsonb_build_object(
    'commandId', v_command_id,
    'status', 'QUEUED',
    'label', v_label
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, v_device.building_id, v_scope.actor_id,
    'capture_configuration', 'device', v_device.id, v_target,
    'Capture configuration: ' || v_label,
    jsonb_build_object('permission', 'network_center.execute'), v_result,
    'ACCEPTED', v_command_id, p_request_id, v_hash
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_resume_organization_v1(uuid, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_resume_organization_v1(p_anchor_building_id uuid, p_expected_version bigint, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_now timestamptz := clock_timestamp();
  v_hash text;
  v_replay jsonb;
  v_gate public.network_org_mutation_gates%ROWTYPE;
  v_result jsonb;
BEGIN
  IF p_anchor_building_id IS NULL OR p_request_id IS NULL
     OR p_expected_version IS NULL OR p_expected_version < 1
     OR char_length(v_reason) NOT BETWEEN 8 AND 500 THEN
    RAISE EXCEPTION 'Invalid Network Center organization resume request'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_scope
  FROM app_private.network_center_require_execute_permission_v1(
    p_anchor_building_id
  );

  -- Resuming the fleet is the dangerous direction, so it is owner-only. Pausing
  -- deliberately is not: a fail-safe stop must never wait for an owner.
  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_memberships membership
    WHERE membership.organization_id = v_scope.organization_id
      AND membership.user_id = v_scope.actor_id
      AND membership.member_type = 'OWNER'
      AND membership.status = 'ACTIVE'
      AND coalesce(membership.valid_from, '-infinity'::timestamptz) <= v_now
      AND (membership.valid_to IS NULL OR membership.valid_to > v_now)
  ) THEN
    RAISE EXCEPTION 'NETWORK_CENTER_ORG_RESUME_REQUIRES_OWNER'
      USING ERRCODE = '42501';
  END IF;

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'resume_organization',
    'buildingId', p_anchor_building_id,
    'expectedVersion', p_expected_version,
    'reason', v_reason
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash,
    'resume_organization'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT gate.* INTO v_gate
  FROM public.network_org_mutation_gates gate
  WHERE gate.organization_id = v_scope.organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Network Center organization gate not found'
      USING ERRCODE = 'P0002';
  END IF;
  IF v_gate.version <> p_expected_version THEN
    RAISE EXCEPTION 'Network organization gate changed; reload before resuming'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.network_org_mutation_gates gate
  SET mutations_paused = false,
      paused_reason = NULL,
      paused_at = NULL,
      paused_by = NULL,
      resumed_reason = v_reason,
      resumed_at = v_now,
      resumed_by = v_scope.actor_id,
      version = gate.version + 1,
      updated_at = v_now
  WHERE gate.organization_id = v_scope.organization_id
  RETURNING * INTO v_gate;

  v_result := jsonb_build_object(
    'organizationId', v_gate.organization_id,
    'mutationsPaused', v_gate.mutations_paused,
    'resumedAt', v_gate.resumed_at,
    'version', v_gate.version
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_anchor_building_id, v_scope.actor_id,
    'resume_organization', 'organization', v_scope.organization_id,
    jsonb_build_object('buildingName', v_scope.building_name),
    v_reason,
    jsonb_build_object(
      'permission', 'network_center.execute',
      'requiredMemberType', 'OWNER',
      'expectedVersion', p_expected_version
    ),
    v_result, 'SUCCEEDED', NULL, p_request_id, v_hash
  );
  RETURN v_result;
END;
$$;








--
-- Name: FUNCTION network_center_resume_organization_v1(p_anchor_building_id uuid, p_expected_version bigint, p_reason text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_resume_organization_v1(p_anchor_building_id uuid, p_expected_version bigint, p_reason text, p_request_id uuid) IS 'Owner-only CAS resume of the fleet-wide Network Center kill switch.';








--
-- Name: network_center_retire_uncertain_command_v1(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_retire_uncertain_command_v1(p_building_id uuid, p_command_id uuid, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_scope record;
  v_command public.network_commands%ROWTYPE;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_now timestamptz := clock_timestamp();
  v_hash text;
  v_replay jsonb;
  v_attempt_id uuid;
  v_result jsonb;
  v_command_result jsonb;
BEGIN
  IF p_building_id IS NULL OR p_command_id IS NULL OR p_request_id IS NULL
     OR char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'Invalid Network Center retire request'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_scope
  FROM app_private.network_center_require_execute_v1(p_building_id);

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'retire_uncertain_command',
    'buildingId', p_building_id,
    'commandId', p_command_id,
    'reason', v_reason
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash,
    'retire_uncertain_command'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- The building comes from the caller, but it is never authority: the command
  -- must live in the tenant the guard resolved, and the guard resolved it from
  -- the caller's own permission on that building.
  SELECT command.* INTO v_command
  FROM public.network_commands command
  WHERE command.id = p_command_id
    AND command.organization_id = v_scope.organization_id
    AND command.building_id = p_building_id
    AND command.status = 'UNCERTAIN'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unresolved Network Center command not found'
      USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.network_device_leases lease
    WHERE lease.device_id = v_command.device_id
      AND lease.expires_at > v_now
  ) THEN
    RAISE EXCEPTION 'Device is leased; retry after the lease expires'
      USING ERRCODE = '55000';
  END IF;

  v_command_result := coalesce(v_command.result, '{}'::jsonb)
    || jsonb_build_object(
      'code', 'OPERATOR_RETIRED_UNCERTAIN',
      'retiredAt', v_now,
      'retiredBy', v_scope.actor_id,
      'retirementReason', v_reason
    );

  SELECT attempt.id INTO v_attempt_id
  FROM public.network_command_attempts attempt
  WHERE attempt.command_id = v_command.id
  ORDER BY attempt.attempt_no DESC
  LIMIT 1;

  UPDATE public.network_command_attempts attempt
  SET outcome = 'PERMANENT_FAILURE',
      retryable = false,
      error_code = 'OPERATOR_RETIRED_UNCERTAIN',
      error_message = left(v_reason, 2000),
      finished_at = v_now
  WHERE attempt.id = v_attempt_id
    AND attempt.finished_at IS NULL;

  INSERT INTO public.network_command_events (
    organization_id, building_id, command_id, attempt_id, event_seq,
    event_kind, occurred_at, actor_id, payload
  ) VALUES (
    v_command.organization_id, v_command.building_id, v_command.id,
    v_attempt_id,
    coalesce((
      SELECT max(event.event_seq) + 1
      FROM public.network_command_events event
      WHERE event.command_id = v_command.id
    ), 1),
    'FAILED', v_now, v_scope.actor_id,
    jsonb_build_object(
      'code', 'OPERATOR_RETIRED_UNCERTAIN',
      'previousStatus', v_command.status,
      'previousReconciliationState', v_command.reconciliation_state
    )
  );

  UPDATE public.network_commands command
  SET status = 'FAILED',
      reconciliation_state = 'UNKNOWN',
      result = v_command_result,
      started_at = coalesce(command.started_at, v_now),
      finished_at = v_now,
      updated_at = v_now
  WHERE command.id = v_command.id;

  v_result := jsonb_build_object(
    'commandId', v_command.id,
    'status', 'FAILED',
    'reconciliationState', 'UNKNOWN',
    'code', 'OPERATOR_RETIRED_UNCERTAIN'
  );
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_building_id, v_scope.actor_id,
    'retire_uncertain_command', 'command', v_command.id,
    jsonb_build_object(
      'buildingName', v_scope.building_name,
      'deviceId', v_command.device_id,
      'actionType', v_command.action_type
    ),
    v_reason,
    jsonb_build_object(
      'permission', 'network_center.execute',
      'previousStatus', v_command.status,
      'previousReconciliationState', v_command.reconciliation_state
    ),
    v_result, 'FAILED', v_command.id, p_request_id, v_hash
  );
  INSERT INTO public.network_outbox_events (
    organization_id, building_id, event_type, aggregate_type, aggregate_id,
    payload, occurred_at
  ) VALUES (
    v_command.organization_id, v_command.building_id,
    'network.command.completed', 'command', v_command.id,
    jsonb_build_object('status', 'FAILED'), v_now
  );
  RETURN v_result;
END;
$$;








--
-- Name: FUNCTION network_center_retire_uncertain_command_v1(p_building_id uuid, p_command_id uuid, p_reason text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_retire_uncertain_command_v1(p_building_id uuid, p_command_id uuid, p_reason text, p_request_id uuid) IS 'Execute-scoped operator recovery for an UNCERTAIN command; writes the append-only USER audit trail and can only reach FAILED, never SUCCEEDED.';








--
-- Name: network_center_update_settings_v1(uuid, jsonb, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_update_settings_v1(p_building_id uuid, p_settings jsonb, p_expected_version bigint, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_scope record;
  v_current public.network_site_settings%ROWTYPE;
  v_hash text;
  v_replay jsonb;
  v_result jsonb;
  v_poll integer;
  v_backup text;
  v_alert text;
BEGIN
  IF p_request_id IS NULL OR p_expected_version IS NULL OR p_expected_version < 1
     OR p_settings IS NULL OR jsonb_typeof(p_settings) <> 'object'
     OR octet_length(p_settings::text) > 16384
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_settings) key
       WHERE key NOT IN ('pollingSeconds', 'backupHour', 'alertSensitivity', 'dependencyGrouping', 'changesPaused')
     ) THEN
    RAISE EXCEPTION 'Invalid Network Center settings request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_scope FROM app_private.network_center_require_execute_v1(p_building_id);
  SELECT settings.* INTO v_current
  FROM public.network_site_settings settings
  WHERE settings.organization_id = v_scope.organization_id AND settings.building_id = p_building_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Network settings not found' USING ERRCODE = 'P0002'; END IF;

  IF p_settings ? 'pollingSeconds' THEN
    IF (p_settings->>'pollingSeconds') !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Polling seconds must be an integer' USING ERRCODE = '22023';
    END IF;
    v_poll := (p_settings->>'pollingSeconds')::integer;
    IF v_poll NOT BETWEEN 30 AND 300 THEN
      RAISE EXCEPTION 'Polling seconds must be between 30 and 300' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_settings ? 'backupHour' THEN
    v_backup := p_settings->>'backupHour';
    IF v_backup !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RAISE EXCEPTION 'Backup hour must use HH:MM' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_settings ? 'alertSensitivity' THEN
    v_alert := upper(p_settings->>'alertSensitivity');
    IF v_alert NOT IN ('STANDARD', 'STRICT') THEN
      RAISE EXCEPTION 'Invalid alert sensitivity' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF (p_settings ? 'dependencyGrouping' AND jsonb_typeof(p_settings->'dependencyGrouping') <> 'boolean')
     OR (p_settings ? 'changesPaused' AND jsonb_typeof(p_settings->'changesPaused') <> 'boolean') THEN
    RAISE EXCEPTION 'Invalid boolean Network Center setting' USING ERRCODE = '22023';
  END IF;

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', 'update_settings', 'buildingId', p_building_id,
    'expectedVersion', p_expected_version, 'settings', p_settings
  )::text, 'sha256'), 'hex');
  v_replay := app_private.network_center_request_replay_v1(
    v_scope.organization_id, v_scope.actor_id, p_request_id, v_hash, 'update_settings'
  );
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  IF v_current.version <> p_expected_version THEN
    RAISE EXCEPTION 'Network settings changed; reload before saving' USING ERRCODE = '40001';
  END IF;

  UPDATE public.network_site_settings settings
  SET poll_interval_seconds = coalesce(v_poll, settings.poll_interval_seconds),
      backup_time_local = coalesce(v_backup::time, settings.backup_time_local),
      alert_sensitivity = coalesce(v_alert, settings.alert_sensitivity),
      dependency_grouping = CASE WHEN p_settings ? 'dependencyGrouping'
        THEN (p_settings->>'dependencyGrouping')::boolean ELSE settings.dependency_grouping END,
      changes_paused = CASE WHEN p_settings ? 'changesPaused'
        THEN (p_settings->>'changesPaused')::boolean ELSE settings.changes_paused END,
      version = settings.version + 1
  WHERE settings.id = v_current.id
  RETURNING jsonb_build_object(
    'pollingSeconds', settings.poll_interval_seconds,
    'backupHour', to_char(settings.backup_time_local, 'HH24:MI'),
    'alertSensitivity', lower(settings.alert_sensitivity),
    'dependencyGrouping', settings.dependency_grouping,
    'changesPaused', settings.changes_paused,
    'version', settings.version
  ) INTO v_result;
  PERFORM app_private.network_center_append_user_audit_v1(
    v_scope.organization_id, p_building_id, v_scope.actor_id,
    'update_settings', 'building', p_building_id,
    jsonb_build_object('buildingName', v_scope.building_name),
    'Update Network Center settings', jsonb_build_object('expectedVersion', p_expected_version),
    v_result, 'SUCCEEDED', NULL, p_request_id, v_hash
  );
  RETURN v_result;
END;
$_$;








--
-- Name: network_center_watchdog_liveness_v1(integer, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_watchdog_liveness_v1(p_stale_after_seconds integer DEFAULT 300, p_now timestamp with time zone DEFAULT clock_timestamp(), p_registration_grace_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  -- One fingerprint for the whole subsystem, deliberately carrying no worker
  -- key. `network_incidents_one_active_fingerprint_uidx` is
  -- (organization_id, building_id, fingerprint) WHERE status <> 'RESOLVED', so
  -- this yields exactly one active incident per building no matter how often the
  -- sweep runs or how many workers serve that building - and it leaks no worker
  -- identity into a tenant-readable row.
  c_fingerprint constant text := 'network-center:worker-heartbeat-stale';
  c_incident_type constant text := 'WORKER_HEARTBEAT_STALE';
  c_actor constant text := 'network-center-watchdog';
  -- How stale an already-open incident may get before it is touched again. Keeps
  -- a two-minute schedule from writing to a Realtime-published table 720 times a
  -- day for one unresolved outage.
  c_refresh_interval constant interval := INTERVAL '5 minutes';
  v_started timestamptz := clock_timestamp();
  v_now timestamptz := p_now;
  v_report jsonb;
  v_state app_private.network_center_watchdog_state;
  v_monitored_workers integer := 0;
  v_monitored_buildings integer := 0;
  v_stale_workers integer := 0;
  v_stale_buildings integer := 0;
  v_opened integer := 0;
  v_refreshed integer := 0;
  v_resolved integer := 0;
  v_stale_worker_detail jsonb := '[]'::jsonb;
BEGIN
  IF p_stale_after_seconds IS NULL
     OR p_stale_after_seconds NOT BETWEEN 30 AND 86400
     OR p_registration_grace_seconds IS NULL
     OR p_registration_grace_seconds NOT BETWEEN 0 AND 86400
     OR v_now IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - v_now))) > 3600 THEN
    RAISE EXCEPTION 'Invalid Network Center watchdog request'
      USING ERRCODE = '22023';
  END IF;

  -- Concurrency safety. Two schedulers (pg_cron and an external HTTP cron) may
  -- legitimately be enabled at once, and a slow run may still be in flight when
  -- the next tick arrives. The loser must not double-write incidents, and must
  -- not report "healthy" either - it reports the last COMPLETED assessment, so a
  -- caller that maps the payload to an alert cannot be silenced by contention.
  IF NOT pg_try_advisory_xact_lock(20260729139001::bigint) THEN
    SELECT state.* INTO v_state
    FROM app_private.network_center_watchdog_state state
    WHERE state.singleton;
    RETURN jsonb_build_object(
      'schemaVersion', 1,
      'job', 'LIVENESS',
      'at', v_now,
      'skipped', true,
      'skipReason', 'CONCURRENT_RUN',
      'thresholdSeconds', coalesce(
        v_state.liveness_threshold_seconds, p_stale_after_seconds
      ),
      'assessedAt', v_state.liveness_assessed_at,
      'monitoredWorkers', coalesce(v_state.monitored_worker_count, 0),
      'monitoredBuildings', coalesce(v_state.monitored_building_count, 0),
      'staleWorkers', coalesce(v_state.stale_worker_count, 0),
      'staleBuildings', coalesce(v_state.stale_building_count, 0),
      'incidentsOpened', 0,
      'incidentsRefreshed', 0,
      'incidentsResolved', 0,
      'staleWorkerDetail', '[]'::jsonb
    );
  END IF;

  -- Evidence that STOPPED arriving (20260729148000). The ingest promotes a
  -- router to ONLINE from a poll it just accepted, and demotes it to OFFLINE
  -- from a poll that failed -- but it cannot see the case where no poll
  -- happens at all, because in that case it is not called. That is exactly
  -- what this sweep is for, and why the demotion belongs here rather than in
  -- the hourly maintenance job: this runs on the same two-minute schedule
  -- that opens WORKER_HEARTBEAT_STALE, so the incident and the router's
  -- lifecycle stop telling different stories about the same outage.
  -- Held under the same advisory lock as the rest of the sweep, and
  -- deliberately NOT reported into v_report: the liveness report is written
  -- verbatim into app_private.network_center_watchdog_runs, whose contract
  -- is asserted key-by-key elsewhere.
  PERFORM app_private.network_center_reconcile_device_lifecycle_v1(v_now);

  -- The scan is re-evaluated per statement rather than materialized into a temp
  -- table: `CREATE TEMPORARY TABLE` would make a second call inside the same
  -- transaction fail with 42P07, and a scheduler that batches both watchdog jobs
  -- into one transaction is a perfectly reasonable thing for an operator to
  -- write. The function is STABLE over tables this sweep never writes, so every
  -- re-evaluation inside one transaction sees the same rows.
  SELECT count(DISTINCT scan.worker_id),
    count(DISTINCT (scan.organization_id, scan.building_id)),
    count(DISTINCT scan.worker_id) FILTER (WHERE scan.stale),
    count(DISTINCT (scan.organization_id, scan.building_id))
      FILTER (WHERE scan.stale)
  INTO v_monitored_workers, v_monitored_buildings, v_stale_workers,
    v_stale_buildings
  FROM app_private.network_center_watchdog_liveness_scan_v1(
    v_now, p_stale_after_seconds, p_registration_grace_seconds
  ) scan;

  -- Operator-facing only: this value is returned to the service-role caller and
  -- never written to a tenant-readable row. Bounded so a large fleet cannot make
  -- the payload unbounded.
  SELECT coalesce(jsonb_agg(to_jsonb(detail) ORDER BY detail."workerKey"), '[]'::jsonb)
  INTO v_stale_worker_detail
  FROM (
    SELECT scan.worker_key AS "workerKey",
      max(scan.last_heartbeat_at) AS "lastHeartbeatAt",
      count(DISTINCT (scan.organization_id, scan.building_id))::integer
        AS "buildingCount"
    FROM app_private.network_center_watchdog_liveness_scan_v1(
    v_now, p_stale_after_seconds, p_registration_grace_seconds
  ) scan
    WHERE scan.stale
    GROUP BY scan.worker_key
    ORDER BY scan.worker_key
    LIMIT 20
  ) detail;

  -- Open or refresh one incident per building that has lost every one of its
  -- pollers. `xmax = 0` distinguishes a genuine INSERT from a conflict update,
  -- and the DO UPDATE WHERE means an unchanged, already-open incident yields no
  -- row at all - so an outage lasting days appends exactly one incident event.
  WITH stale_building AS (
    SELECT scan.organization_id,
      scan.building_id,
      (array_agg(scan.device_id ORDER BY scan.device_id))[1] AS device_id,
      max(scan.last_heartbeat_at) AS last_heartbeat_at
    FROM app_private.network_center_watchdog_liveness_scan_v1(
    v_now, p_stale_after_seconds, p_registration_grace_seconds
  ) scan
    WHERE scan.stale
    GROUP BY scan.organization_id, scan.building_id
  ), upserted AS (
    INSERT INTO public.network_incidents (
      organization_id, building_id, device_id, interface_id, fingerprint,
      incident_type, severity, status, title, summary, availability_impact,
      opened_at, last_observed_at, occurrence_count, observed_values
    )
    SELECT stale_building.organization_id,
      stale_building.building_id,
      stale_building.device_id,
      NULL::uuid,
      c_fingerprint,
      c_incident_type,
      'CRITICAL',
      'OPEN',
      'Hệ thống giám sát mạng ngừng báo cáo',
      'Không nhận được nhịp tim từ tiến trình thu thập dữ liệu mạng của tòa nhà'
        || ' trong hơn ' || p_stale_after_seconds::text || ' giây.'
        || ' Số liệu đang hiển thị có thể đã cũ và các lệnh mới sẽ không được'
        || ' thực thi cho tới khi tiến trình hoạt động trở lại.',
      true,
      v_now,
      v_now,
      1,
      jsonb_build_object(
        'thresholdSeconds', p_stale_after_seconds,
        'lastHeartbeatAt', stale_building.last_heartbeat_at,
        'detectedBy', 'watchdog'
      )
    FROM stale_building
    ON CONFLICT (organization_id, building_id, fingerprint)
      WHERE status <> 'RESOLVED'
    DO UPDATE SET
      severity = 'CRITICAL',
      last_observed_at = greatest(
        public.network_incidents.last_observed_at, EXCLUDED.last_observed_at
      ),
      occurrence_count = public.network_incidents.occurrence_count + 1,
      observed_values = EXCLUDED.observed_values,
      version = public.network_incidents.version + 1
    WHERE public.network_incidents.last_observed_at
      < EXCLUDED.last_observed_at - c_refresh_interval
    RETURNING id, organization_id, building_id, device_id, opened_at,
      (xmax = 0) AS newly_opened
  ), opened_event AS (
    INSERT INTO public.network_incident_events (
      organization_id, building_id, incident_id, event_seq, event_kind,
      severity, occurred_at, worker_id, details
    )
    SELECT upserted.organization_id, upserted.building_id, upserted.id,
      coalesce((
        SELECT max(event.event_seq) + 1
        FROM public.network_incident_events event
        WHERE event.incident_id = upserted.id
      ), 1),
      'OPENED', 'CRITICAL', v_now, c_actor,
      jsonb_build_object(
        'thresholdSeconds', p_stale_after_seconds,
        'detectedBy', 'watchdog'
      )
    FROM upserted
    WHERE upserted.newly_opened
    RETURNING incident_id
  ), opened_audit AS (
    INSERT INTO public.network_audit_events (
      organization_id, building_id, actor_type, action, target_type, target_id,
      target_display, reason, validation, result, outcome, occurred_at
    )
    SELECT upserted.organization_id, upserted.building_id, 'SYSTEM',
      'system.watchdog_worker_stale', 'building', upserted.building_id,
      jsonb_build_object('deviceId', upserted.device_id),
      'Watchdog ngoài luồng phát hiện tiến trình giám sát ngừng báo cáo',
      jsonb_build_object('thresholdSeconds', p_stale_after_seconds),
      jsonb_build_object('incidentId', upserted.id),
      'OBSERVED', v_now
    FROM upserted
    WHERE upserted.newly_opened
    RETURNING id
  ), opened_outbox AS (
    INSERT INTO public.network_outbox_events (
      organization_id, building_id, event_type, aggregate_type, aggregate_id,
      payload, occurred_at
    )
    SELECT upserted.organization_id, upserted.building_id,
      'network.worker.heartbeat_stale', 'building', upserted.building_id,
      jsonb_build_object(
        'incidentId', upserted.id,
        'incidentType', c_incident_type,
        'thresholdSeconds', p_stale_after_seconds
      ),
      v_now
    FROM upserted
    WHERE upserted.newly_opened
    RETURNING id
  )
  SELECT (count(*) FILTER (WHERE upserted.newly_opened))::integer,
    (count(*) FILTER (WHERE NOT upserted.newly_opened))::integer
  INTO v_opened, v_refreshed
  FROM upserted;

  -- Clear down. Only for buildings this sweep still monitors and now finds
  -- healthy: a building whose assignment was removed entirely keeps its open
  -- incident, because "the thing I was watching disappeared" must not read as
  -- "the thing I was watching recovered".
  WITH healthy_building AS (
    SELECT scan.organization_id, scan.building_id
    FROM app_private.network_center_watchdog_liveness_scan_v1(
    v_now, p_stale_after_seconds, p_registration_grace_seconds
  ) scan
    GROUP BY scan.organization_id, scan.building_id
    HAVING bool_and(NOT scan.stale)
  ), cleared AS (
    UPDATE public.network_incidents incident
    SET status = 'RESOLVED',
      resolved_at = v_now,
      recovered_at = coalesce(incident.recovered_at, v_now),
      last_observed_at = greatest(incident.last_observed_at, v_now),
      version = incident.version + 1
    FROM healthy_building
    WHERE incident.organization_id = healthy_building.organization_id
      AND incident.building_id = healthy_building.building_id
      AND incident.fingerprint = c_fingerprint
      AND incident.status <> 'RESOLVED'
    RETURNING incident.id, incident.organization_id, incident.building_id,
      incident.device_id
  ), cleared_event AS (
    INSERT INTO public.network_incident_events (
      organization_id, building_id, incident_id, event_seq, event_kind,
      severity, occurred_at, worker_id, details
    )
    SELECT cleared.organization_id, cleared.building_id, cleared.id,
      coalesce((
        SELECT max(event.event_seq) + 1
        FROM public.network_incident_events event
        WHERE event.incident_id = cleared.id
      ), 1),
      'RESOLVED', 'INFO', v_now, c_actor,
      jsonb_build_object('detectedBy', 'watchdog')
    FROM cleared
    RETURNING incident_id
  ), cleared_audit AS (
    INSERT INTO public.network_audit_events (
      organization_id, building_id, actor_type, action, target_type, target_id,
      target_display, reason, validation, result, outcome, occurred_at
    )
    SELECT cleared.organization_id, cleared.building_id, 'SYSTEM',
      'system.watchdog_worker_recovered', 'building', cleared.building_id,
      jsonb_build_object('deviceId', cleared.device_id),
      'Watchdog ngoài luồng ghi nhận tiến trình giám sát đã báo cáo trở lại',
      jsonb_build_object('thresholdSeconds', p_stale_after_seconds),
      jsonb_build_object('incidentId', cleared.id),
      'OBSERVED', v_now
    FROM cleared
    RETURNING id
  ), cleared_outbox AS (
    INSERT INTO public.network_outbox_events (
      organization_id, building_id, event_type, aggregate_type, aggregate_id,
      payload, occurred_at
    )
    SELECT cleared.organization_id, cleared.building_id,
      'network.worker.heartbeat_recovered', 'building', cleared.building_id,
      jsonb_build_object(
        'incidentId', cleared.id,
        'incidentType', c_incident_type
      ),
      v_now
    FROM cleared
    RETURNING id
  )
  SELECT count(*)::integer INTO v_resolved FROM cleared;

  UPDATE app_private.network_center_watchdog_state state
  SET liveness_assessed_at = v_now,
    liveness_threshold_seconds = p_stale_after_seconds,
    monitored_worker_count = v_monitored_workers,
    monitored_building_count = v_monitored_buildings,
    stale_worker_count = v_stale_workers,
    stale_building_count = v_stale_buildings,
    updated_at = clock_timestamp()
  WHERE state.singleton;

  v_report := jsonb_build_object(
    'schemaVersion', 1,
    'job', 'LIVENESS',
    'at', v_now,
    'skipped', false,
    'skipReason', NULL,
    'thresholdSeconds', p_stale_after_seconds,
    'assessedAt', v_now,
    'monitoredWorkers', v_monitored_workers,
    'monitoredBuildings', v_monitored_buildings,
    'staleWorkers', v_stale_workers,
    'staleBuildings', v_stale_buildings,
    'incidentsOpened', v_opened,
    'incidentsRefreshed', v_refreshed,
    'incidentsResolved', v_resolved,
    'staleWorkerDetail', v_stale_worker_detail
  );

  PERFORM app_private.network_center_watchdog_record_run_v1(
    'LIVENESS',
    v_now,
    (extract(epoch FROM (clock_timestamp() - v_started)) * 1000)::integer,
    v_report - 'staleWorkerDetail'
  );

  RETURN v_report;
END;
$$;








--
-- Name: FUNCTION network_center_watchdog_liveness_v1(p_stale_after_seconds integer, p_now timestamp with time zone, p_registration_grace_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_watchdog_liveness_v1(p_stale_after_seconds integer, p_now timestamp with time zone, p_registration_grace_seconds integer) IS 'Service-role-only out-of-band worker liveness sweep. Reads app_private.network_worker_release_heartbeats (the source behind network_center_admin_worker_release_status_v1), opens one deduped CRITICAL WORKER_HEARTBEAT_STALE incident per affected building, resolves it when the worker reports again, holds no worker credential and writes no worker identity into any tenant-readable row.';








--
-- Name: network_center_watchdog_maintenance_v1(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_watchdog_maintenance_v1(p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_started timestamptz := clock_timestamp();
  v_now timestamptz := p_now;
  v_day date;
  v_daily_done boolean := false;
  v_reclaimed integer := 0;
  v_expired_clients bigint := 0;
  v_windows_updated bigint := 0;
  v_retention jsonb := NULL;
  v_report jsonb;
BEGIN
  IF v_now IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - v_now))) > 3600 THEN
    RAISE EXCEPTION 'Invalid Network Center watchdog maintenance request'
      USING ERRCODE = '22023';
  END IF;

  IF NOT pg_try_advisory_xact_lock(20260729139002::bigint) THEN
    RETURN jsonb_build_object(
      'schemaVersion', 1,
      'job', 'MAINTENANCE',
      'at', v_now,
      'skipped', true,
      'skipReason', 'CONCURRENT_RUN'
    );
  END IF;

  v_day := (v_now AT TIME ZONE 'UTC')::date;

  -- The 31-day horizon matches both the bootstrap in 20260729020000 and the
  -- re-creation inside network_center_retention_v1, so ingest keeps a month of
  -- head-room even if this job stops.
  PERFORM app_private.network_center_ensure_raw_partitions_v1(
    v_day - 1, v_day + 31
  );

  PERFORM app_private.network_center_rollup_hourly_v1(
    date_trunc('hour', v_now) - INTERVAL '1 hour'
  );

  v_reclaimed := app_private.network_center_reclaim_expired_commands_v1(v_now);

  DELETE FROM public.network_client_current client
  WHERE client.expires_at <= v_now;
  GET DIAGNOSTICS v_expired_clients = ROW_COUNT;

  UPDATE public.network_maintenance_windows maintenance
  SET status = CASE
    WHEN maintenance.ends_at <= v_now THEN 'COMPLETED' ELSE 'ACTIVE'
  END
  WHERE maintenance.status IN ('SCHEDULED', 'ACTIVE')
    AND (
      maintenance.starts_at <= v_now OR maintenance.ends_at <= v_now
    );
  GET DIAGNOSTICS v_windows_updated = ROW_COUNT;

  -- Once per UTC day, taken under the same advisory lock, so a second caller in
  -- the same day observes the committed marker and does nothing.
  IF NOT EXISTS (
    SELECT 1
    FROM app_private.network_center_watchdog_state state
    WHERE state.singleton
      AND state.daily_maintenance_day = v_day
  ) THEN
    PERFORM app_private.network_center_rollup_sla_daily_v1(
      (v_now - INTERVAL '1 day')::date
    );
    v_retention := app_private.network_center_retention_v1(v_now);
    v_daily_done := true;
  END IF;

  UPDATE app_private.network_center_watchdog_state state
  SET maintenance_ran_at = v_now,
    daily_maintenance_day = CASE
      WHEN v_daily_done THEN v_day ELSE state.daily_maintenance_day
    END,
    updated_at = clock_timestamp()
  WHERE state.singleton;

  v_report := jsonb_build_object(
    'schemaVersion', 1,
    'job', 'MAINTENANCE',
    'at', v_now,
    'skipped', false,
    'skipReason', NULL,
    'partitionHorizonThrough', v_day + 31,
    'reclaimedCommands', v_reclaimed,
    'expiredClients', v_expired_clients,
    'maintenanceWindowsUpdated', v_windows_updated,
    'dailyMaintenanceRan', v_daily_done,
    'retention', v_retention
  );

  PERFORM app_private.network_center_watchdog_record_run_v1(
    'MAINTENANCE',
    v_now,
    (extract(epoch FROM (clock_timestamp() - v_started)) * 1000)::integer,
    v_report
  );

  RETURN v_report;
END;
$$;








--
-- Name: FUNCTION network_center_watchdog_maintenance_v1(p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_watchdog_maintenance_v1(p_now timestamp with time zone) IS 'Service-role-only fleet-global maintenance scheduler: raw partition pre-creation, hourly rollup, expired lease reclamation, expired client purge and maintenance-window transitions every run, plus the daily SLA rollup and retention once per UTC day. network_center_worker_maintenance_v2 deliberately stopped doing this work and named a trusted scheduler as its owner; this function is that owner.';








--
-- Name: network_center_worker_claim_v1(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_claim_v1(p_worker_id text, p_limit integer DEFAULT 5, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  IF p_limit NOT BETWEEN 1 AND 20
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid command claim request' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('items', '[]'::jsonb);
END;
$$;








--
-- Name: network_center_worker_claim_v2(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_claim_v2(p_credential_digest text, p_limit integer DEFAULT 5, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  -- See app_private.network_center_claim_commands_v1 for why a claim needs
  -- headroom rather than a bare "deadline is still in the future".
  c_claim_min_remaining constant interval := INTERVAL '5 seconds';
  -- A reconciliation that keeps failing must not burn the whole observation
  -- window in a claim loop. Past this cap the command waits for the deadline
  -- sweeper (or an operator) instead of taking the device lease again.
  c_max_reconciliation_attempts constant integer := 3;
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_now timestamptz := clock_timestamp();
  v_candidate public.network_commands%ROWTYPE;
  v_command public.network_commands%ROWTYPE;
  v_lease public.network_device_leases%ROWTYPE;
  v_attempt_id uuid;
  v_event_seq bigint;
  v_items jsonb := '[]'::jsonb;
  v_claimed integer := 0;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_limit NOT BETWEEN 1 AND 20
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid command claim request' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_reclaim_expired_commands_v2(
    v_worker_id, v_now
  );
  -- Runs before any admission decision so a doomed command is settled honestly
  -- rather than merely skipped and left to accumulate.
  PERFORM app_private.network_center_sweep_expired_commands_v1(v_now);

  -- Assignment and managed-resource admission happen in the candidate query,
  -- before any lease mutation. Revocation/protection committed before this lock
  -- makes the command ineligible rather than globally claiming then rejecting.
  FOR v_candidate IN
    SELECT command.*
    FROM public.network_commands command
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = v_worker_id
     AND assignment.organization_id = command.organization_id
     AND assignment.building_id = command.building_id
     AND assignment.device_id = command.device_id
     AND assignment.can_execute
     AND assignment.active_from <= v_now
     AND (
       assignment.active_until IS NULL
       OR assignment.active_until > v_now
     )
    JOIN public.network_workers worker
      ON worker.id = assignment.worker_id
     AND worker.status = 'ACTIVE'
     AND 'EXECUTE' = ANY(worker.capabilities)
    JOIN public.network_site_settings settings
      ON settings.organization_id = command.organization_id
     AND settings.building_id = command.building_id
     AND settings.rollout_state = 'EXECUTE'
    WHERE command.status IN ('QUEUED', 'RETRY_WAIT')
      AND command.available_at <= v_now
      AND command.attempt_count < command.max_attempts
      -- A command whose observation window has closed can never record its
      -- result, so executing it would mutate a real router with no way to
      -- write down what happened.
      AND command.observation_deadline > v_now + c_claim_min_remaining
      AND NOT app_private.network_center_org_mutations_paused_v1(
        command.organization_id
      )
      AND (
        command.action_type = 'CAPTURE_SNAPSHOT'
        OR NOT settings.changes_paused
      )
      AND (
        command.action_type <> 'CYCLE_ACCESS_PORT'
        OR EXISTS (
          SELECT 1
          FROM public.network_interfaces interface
          JOIN public.network_managed_resources resource
            ON resource.organization_id = interface.organization_id
           AND resource.building_id = interface.building_id
           AND resource.device_id = interface.device_id
           AND resource.id = interface.managed_resource_id
          WHERE interface.organization_id = command.organization_id
            AND interface.building_id = command.building_id
            AND interface.device_id = command.device_id
            AND interface.id = command.interface_id
            AND interface.interface_role = 'ACCESS'
            AND NOT interface.is_protected
            AND resource.resource_kind = 'INTERFACE'
            AND resource.enrolled_role = 'ACCESS'
            AND resource.enrollment_state = 'ENROLLED'
            AND resource.protected = false
            AND resource.last_verified_at IS NOT NULL
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.network_device_leases active_lease
        WHERE active_lease.device_id = command.device_id
          AND active_lease.expires_at > v_now
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.network_commands unresolved
        WHERE unresolved.device_id = command.device_id
          AND unresolved.status = 'UNCERTAIN'
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.network_commands earlier
        WHERE earlier.device_id = command.device_id
          AND earlier.status IN ('QUEUED', 'RETRY_WAIT')
          AND earlier.available_at <= v_now
          AND earlier.attempt_count < earlier.max_attempts
          AND earlier.observation_deadline > v_now + c_claim_min_remaining
          AND (
            earlier.priority > command.priority
            OR (
              earlier.priority = command.priority
              AND ROW(earlier.available_at, earlier.created_at, earlier.id)
                < ROW(command.available_at, command.created_at, command.id)
            )
          )
      )
    ORDER BY command.priority DESC, command.available_at,
      command.created_at, command.id
    FOR UPDATE OF command, assignment, worker, settings SKIP LOCKED
    LIMIT p_limit
  LOOP
    IF v_candidate.action_type = 'CYCLE_ACCESS_PORT' THEN
      PERFORM 1
      FROM public.network_interfaces interface
      JOIN public.network_managed_resources resource
        ON resource.organization_id = interface.organization_id
       AND resource.building_id = interface.building_id
       AND resource.device_id = interface.device_id
       AND resource.id = interface.managed_resource_id
      WHERE interface.organization_id = v_candidate.organization_id
        AND interface.building_id = v_candidate.building_id
        AND interface.device_id = v_candidate.device_id
        AND interface.id = v_candidate.interface_id
        AND interface.interface_role = 'ACCESS'
        AND NOT interface.is_protected
        AND resource.resource_kind = 'INTERFACE'
        AND resource.enrolled_role = 'ACCESS'
        AND resource.enrollment_state = 'ENROLLED'
        AND resource.protected = false
        AND resource.last_verified_at IS NOT NULL
      FOR UPDATE OF interface, resource;
      IF NOT FOUND THEN CONTINUE; END IF;
    END IF;

    INSERT INTO public.network_device_leases (
      device_id, organization_id, building_id, command_id, lease_token,
      lease_owner, acquired_at, heartbeat_at, expires_at, generation
    ) VALUES (
      v_candidate.device_id, v_candidate.organization_id,
      v_candidate.building_id, v_candidate.id, gen_random_uuid(),
      v_worker_key, v_now, v_now,
      v_now + make_interval(secs => p_lease_seconds), 1
    )
    ON CONFLICT (device_id) DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      building_id = EXCLUDED.building_id,
      command_id = EXCLUDED.command_id,
      lease_token = EXCLUDED.lease_token,
      lease_owner = EXCLUDED.lease_owner,
      acquired_at = EXCLUDED.acquired_at,
      heartbeat_at = EXCLUDED.heartbeat_at,
      expires_at = EXCLUDED.expires_at,
      generation = public.network_device_leases.generation + 1
    WHERE public.network_device_leases.expires_at <= v_now
    RETURNING * INTO v_lease;
    IF NOT FOUND THEN CONTINUE; END IF;

    UPDATE public.network_commands command
    SET status = 'LEASED', lease_token = v_lease.lease_token,
        lease_owner = v_worker_key, lease_expires_at = v_lease.expires_at,
        attempt_count = command.attempt_count + 1,
        started_at = coalesce(command.started_at, v_now), updated_at = v_now
    WHERE command.id = v_candidate.id
    RETURNING * INTO v_command;

    INSERT INTO public.network_command_attempts (
      organization_id, building_id, command_id, device_id, attempt_no,
      worker_id, lease_token, outcome, started_at
    ) VALUES (
      v_command.organization_id, v_command.building_id, v_command.id,
      v_command.device_id, v_command.attempt_count, v_worker_key,
      v_command.lease_token, 'STARTED', v_now
    ) RETURNING id INTO v_attempt_id;

    SELECT coalesce(max(event.event_seq) + 1, 1)
    INTO v_event_seq
    FROM public.network_command_events event
    WHERE event.command_id = v_command.id;
    INSERT INTO public.network_command_events (
      organization_id, building_id, command_id, attempt_id, event_seq,
      event_kind, occurred_at, worker_id, payload
    ) VALUES (
      v_command.organization_id, v_command.building_id, v_command.id,
      v_attempt_id, v_event_seq, 'LEASED', v_now, v_worker_key,
      jsonb_build_object(
        'attemptNo', v_command.attempt_count,
        'leaseExpiresAt', v_command.lease_expires_at
      )
    );

    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'commandId', v_command.id,
      'organizationId', v_command.organization_id,
      'buildingId', v_command.building_id,
      'deviceId', v_command.device_id,
      'interfaceId', v_command.interface_id,
      'actionType', v_command.action_type,
      'reason', v_command.reason,
      'parameters', v_command.sanitized_parameters,
      'attemptNo', v_command.attempt_count,
      'leaseToken', v_command.lease_token,
      'leaseExpiresAt', v_command.lease_expires_at,
      'reconciliation', false,
      'intentType', v_command.intent_type,
      'managedTarget', v_command.managed_target,
      'preObservation', v_command.pre_observation,
      'expectedPostcondition', v_command.expected_postcondition,
      'observationDeadline', v_command.observation_deadline,
      'transitionVersion', v_command.transition_version,
      'fencingGeneration', v_lease.generation
    ));
    v_claimed := v_claimed + 1;
  END LOOP;

  IF v_claimed < p_limit THEN
    FOR v_candidate IN
      SELECT command.*
      FROM public.network_commands command
      JOIN public.network_worker_assignments assignment
        ON assignment.worker_id = v_worker_id
       AND assignment.organization_id = command.organization_id
       AND assignment.building_id = command.building_id
       AND assignment.device_id = command.device_id
       AND assignment.can_execute
       AND assignment.active_from <= v_now
       AND (
         assignment.active_until IS NULL
         OR assignment.active_until > v_now
       )
      JOIN public.network_workers worker
        ON worker.id = assignment.worker_id
       AND worker.status = 'ACTIVE'
       AND 'EXECUTE' = ANY(worker.capabilities)
      WHERE command.status = 'UNCERTAIN'
        AND command.reconciliation_state = 'REQUIRED'
        -- Past the deadline a reconciliation can never record an observation,
        -- so re-leasing the device would only wedge it for longer.
        AND command.observation_deadline > v_now + c_claim_min_remaining
        AND command.reconciliation_attempt_count
          < c_max_reconciliation_attempts
        AND NOT app_private.network_center_org_mutations_paused_v1(
          command.organization_id
        )
        AND (
          command.action_type <> 'CYCLE_ACCESS_PORT'
          OR EXISTS (
            SELECT 1
            FROM public.network_interfaces interface
            JOIN public.network_managed_resources resource
              ON resource.id = interface.managed_resource_id
             AND resource.organization_id = interface.organization_id
             AND resource.building_id = interface.building_id
             AND resource.device_id = interface.device_id
            WHERE interface.id = command.interface_id
              AND interface.device_id = command.device_id
              AND interface.interface_role = 'ACCESS'
              AND NOT interface.is_protected
              AND resource.enrollment_state = 'ENROLLED'
              AND resource.protected = false
          )
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.network_device_leases active_lease
          WHERE active_lease.device_id = command.device_id
            AND active_lease.expires_at > v_now
        )
      ORDER BY command.updated_at, command.id
      FOR UPDATE OF command, assignment, worker SKIP LOCKED
      LIMIT (p_limit - v_claimed)
    LOOP
      IF v_candidate.action_type = 'CYCLE_ACCESS_PORT' THEN
        PERFORM 1
        FROM public.network_interfaces interface
        JOIN public.network_managed_resources resource
          ON resource.organization_id = interface.organization_id
         AND resource.building_id = interface.building_id
         AND resource.device_id = interface.device_id
         AND resource.id = interface.managed_resource_id
        WHERE interface.organization_id = v_candidate.organization_id
          AND interface.building_id = v_candidate.building_id
          AND interface.device_id = v_candidate.device_id
          AND interface.id = v_candidate.interface_id
          AND interface.interface_role = 'ACCESS'
          AND NOT interface.is_protected
          AND resource.resource_kind = 'INTERFACE'
          AND resource.enrolled_role = 'ACCESS'
          AND resource.enrollment_state = 'ENROLLED'
          AND resource.protected = false
          AND resource.last_verified_at IS NOT NULL
        FOR UPDATE OF interface, resource;
        IF NOT FOUND THEN CONTINUE; END IF;
      END IF;

      INSERT INTO public.network_device_leases (
        device_id, organization_id, building_id, command_id, lease_token,
        lease_owner, acquired_at, heartbeat_at, expires_at, generation
      ) VALUES (
        v_candidate.device_id, v_candidate.organization_id,
        v_candidate.building_id, v_candidate.id, gen_random_uuid(),
        v_worker_key, v_now, v_now,
        v_now + make_interval(secs => p_lease_seconds), 1
      )
      ON CONFLICT (device_id) DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        building_id = EXCLUDED.building_id,
        command_id = EXCLUDED.command_id,
        lease_token = EXCLUDED.lease_token,
        lease_owner = EXCLUDED.lease_owner,
        acquired_at = EXCLUDED.acquired_at,
        heartbeat_at = EXCLUDED.heartbeat_at,
        expires_at = EXCLUDED.expires_at,
        generation = public.network_device_leases.generation + 1
      WHERE public.network_device_leases.expires_at <= v_now
      RETURNING * INTO v_lease;
      IF NOT FOUND THEN CONTINUE; END IF;

      UPDATE public.network_commands command
      SET status = 'RECONCILING', reconciliation_state = 'IN_PROGRESS',
          reconciliation_attempt_count =
            command.reconciliation_attempt_count + 1,
          lease_token = v_lease.lease_token, lease_owner = v_worker_key,
          lease_expires_at = v_lease.expires_at, updated_at = v_now
      WHERE command.id = v_candidate.id
      RETURNING * INTO v_command;

      SELECT attempt.id INTO v_attempt_id
      FROM public.network_command_attempts attempt
      WHERE attempt.command_id = v_command.id
      ORDER BY attempt.attempt_no DESC LIMIT 1;
      SELECT coalesce(max(event.event_seq) + 1, 1)
      INTO v_event_seq FROM public.network_command_events event
      WHERE event.command_id = v_command.id;
      INSERT INTO public.network_command_events (
        organization_id, building_id, command_id, attempt_id, event_seq,
        event_kind, occurred_at, worker_id, payload
      ) VALUES (
        v_command.organization_id, v_command.building_id, v_command.id,
        v_attempt_id, v_event_seq, 'RECONCILIATION_STARTED', v_now,
        v_worker_key, jsonb_build_object(
          'leaseExpiresAt', v_command.lease_expires_at,
          'reconciliationAttempt', v_command.reconciliation_attempt_count
        )
      );

      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'commandId', v_command.id,
        'organizationId', v_command.organization_id,
        'buildingId', v_command.building_id,
        'deviceId', v_command.device_id,
        'interfaceId', v_command.interface_id,
        'actionType', v_command.action_type,
        'reason', v_command.reason,
        'parameters', v_command.sanitized_parameters,
        'attemptNo', v_command.attempt_count,
        'leaseToken', v_command.lease_token,
        'leaseExpiresAt', v_command.lease_expires_at,
        'reconciliation', true,
        'reconciliationAttempt', v_command.reconciliation_attempt_count,
        'intentType', v_command.intent_type,
        'managedTarget', v_command.managed_target,
        'preObservation', v_command.pre_observation,
        'expectedPostcondition', v_command.expected_postcondition,
        'observationDeadline', v_command.observation_deadline,
        'transitionVersion', v_command.transition_version,
        'fencingGeneration', v_lease.generation
      ));
      v_claimed := v_claimed + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('items', v_items);
END;
$$;








--
-- Name: network_center_worker_command_event_v1(text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_command_event_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_event_kind text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_compat_worker_id uuid; v_compat_worker_key text;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  RAISE EXCEPTION 'Legacy compatibility cannot write command events'
    USING ERRCODE = '42501';
END;
$$;








--
-- Name: network_center_worker_command_event_v2(text, uuid, uuid, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_command_event_v2(p_credential_digest text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_event_kind text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_command public.network_commands%ROWTYPE;
  v_rollout_state text;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.command_id = command.id
   AND lease.organization_id = command.organization_id
   AND lease.building_id = command.building_id
   AND lease.device_id = command.device_id
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = v_worker_key
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
    AND lease.lease_token = p_lease_token
    AND lease.lease_owner = v_worker_key
    AND lease.generation = p_fencing_generation
    AND lease.expires_at > clock_timestamp()
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active fenced command lease not found'
      USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.network_center_worker_can_access_device_v2(
    v_worker_id, v_command.organization_id, v_command.building_id,
    v_command.device_id, 'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'Worker is not assigned to command target'
      USING ERRCODE = '42501';
  END IF;
  IF upper(btrim(coalesce(p_event_kind, ''))) = 'EXECUTION_STARTED' THEN
    SELECT settings.rollout_state
    INTO v_rollout_state
    FROM public.network_site_settings settings
    WHERE settings.organization_id = v_command.organization_id
      AND settings.building_id = v_command.building_id
    FOR UPDATE;

    IF v_rollout_state = 'READ_ONLY' THEN
      RAISE EXCEPTION 'NETWORK_CENTER_READ_ONLY' USING ERRCODE = '42501';
    END IF;
    IF v_rollout_state IS DISTINCT FROM 'EXECUTE' THEN
      RAISE EXCEPTION 'NETWORK_CENTER_OFF' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN app_private.network_center_worker_command_event_legacy_impl_v1(
    v_worker_key, p_command_id, p_lease_token, p_event_kind, p_payload
  );
END;
$$;








--
-- Name: network_center_worker_complete_v1(text, uuid, uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_complete_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb DEFAULT NULL::jsonb, p_retry_delay_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF current_setting('app.network_center_transition_authority', true)
       IS DISTINCT FROM p_command_id::text THEN
    RAISE EXCEPTION 'Legacy compatibility cannot complete commands'
      USING ERRCODE = '42501';
  END IF;
  RETURN app_private.network_center_complete_command_internal_v2(
    p_worker_id,
    p_command_id,
    p_lease_token,
    p_outcome,
    p_result,
    p_rollback,
    p_retry_delay_seconds
  );
END;
$$;








--
-- Name: FUNCTION network_center_worker_complete_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb, p_retry_delay_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_worker_complete_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_outcome text, p_result jsonb, p_rollback jsonb, p_retry_delay_seconds integer) IS 'Legacy endpoint remains fail-closed; only an in-transaction private transition authority can reach the completion sink.';








--
-- Name: network_center_worker_complete_v2(text, uuid, uuid, bigint, bigint, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_complete_v2(p_credential_digest text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_transition_version bigint, p_outcome text, p_result jsonb, p_rollback jsonb DEFAULT NULL::jsonb, p_retry_delay_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_command public.network_commands%ROWTYPE;
  v_outcome text := upper(btrim(coalesce(p_outcome, '')));
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF v_outcome NOT IN (
    'EVALUATE_POSTCONDITION', 'RETRYABLE_FAILURE', 'FAILED',
    'UNCERTAIN', 'CANCELLED_BY_KILL_SWITCH'
  ) THEN
    RAISE EXCEPTION 'Worker cannot author an authoritative success outcome'
      USING ERRCODE = '22023';
  END IF;
  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.command_id = command.id
   AND lease.device_id = command.device_id
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = v_worker_key
    AND lease.lease_token = p_lease_token
    AND lease.lease_owner = v_worker_key
    AND lease.generation = p_fencing_generation
    AND lease.expires_at > clock_timestamp()
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active fenced completion lease not found'
      USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.network_center_worker_can_access_device_v2(
    v_worker_id, v_command.organization_id, v_command.building_id,
    v_command.device_id, 'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'Worker is not assigned to completion target'
      USING ERRCODE = '42501';
  END IF;
  RETURN app_private.network_center_transition_command_v1(
    v_worker_key, p_command_id, p_lease_token, p_fencing_generation,
    p_transition_version, v_outcome, p_result, p_rollback,
    p_retry_delay_seconds
  );
END;
$$;








--
-- Name: network_center_worker_heartbeat_v1(text, text, text[], text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_heartbeat_v1(p_worker_id text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
  v_now timestamptz := clock_timestamp();
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_count integer;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  IF char_length(btrim(coalesce(p_worker_version, ''))) NOT BETWEEN 1 AND 100
     OR cardinality(coalesce(p_capabilities, ARRAY[]::text[])) > 32
     OR v_status NOT IN ('ONLINE', 'DEGRADED', 'PAUSED', 'STOPPING')
     OR p_queue_age_seconds NOT BETWEEN 0 AND 31536000
     OR p_safe_metadata IS NULL OR jsonb_typeof(p_safe_metadata) <> 'object'
     OR p_started_at IS NULL OR p_started_at > v_now THEN
    RAISE EXCEPTION 'Invalid worker heartbeat' USING ERRCODE = '22023';
  END IF;
  PERFORM app_private.network_center_assert_safe_json_v1(
    p_safe_metadata, 'worker heartbeat metadata'
  );

  WITH snapshot_assignments AS MATERIALIZED (
    SELECT assignment.organization_id, assignment.building_id
    FROM app_private.network_worker_compatibility_state state
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = state.worker_id
    WHERE state.singleton AND state.worker_id = v_compat_worker_id
      AND state.finalized_at IS NULL AND state.expires_at > v_now
      AND assignment.can_poll
      AND assignment.active_from <= v_now
      AND assignment.active_until > v_now
      AND state.assignment_snapshot @> jsonb_build_array(jsonb_build_object(
        'assignmentId', assignment.id,
        'organizationId', assignment.organization_id,
        'buildingId', assignment.building_id,
        'deviceId', assignment.device_id
      ))
  ), upserted AS (
    INSERT INTO public.network_worker_building_status (
      organization_id, building_id, status, heartbeat_at,
      queue_age_seconds, started_at, updated_at
    )
    SELECT DISTINCT organization_id, building_id, v_status, v_now,
      p_queue_age_seconds, p_started_at, v_now
    FROM snapshot_assignments
    ON CONFLICT (organization_id, building_id) DO UPDATE SET
      status = EXCLUDED.status, heartbeat_at = EXCLUDED.heartbeat_at,
      queue_age_seconds = EXCLUDED.queue_age_seconds,
      started_at = EXCLUDED.started_at, updated_at = EXCLUDED.updated_at
    RETURNING building_id
  ) SELECT count(*) INTO v_count FROM upserted;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'Legacy compatibility has no active snapshot assignment'
      USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'status', v_status, 'heartbeatAt', v_now,
    'assignedBuildingCount', v_count
  );
END;
$$;








--
-- Name: network_center_worker_heartbeat_v2(text, text, text[], text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_heartbeat_v2(p_credential_digest text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  -- Retention bounds. `c_rollback_reachable_releases` is the number of most
  -- recently active releases per worker that stay immune to age-based expiry
  -- because the host may still name them as a rollback target; it must stay
  -- strictly below `c_release_retention_limit` so the hard cap can never evict
  -- a reachable target either.
  c_rollback_reachable_releases constant integer := 5;
  c_release_retention_limit constant integer := 20;
  c_release_retention_max_age constant interval := INTERVAL '30 days';
  v_result jsonb;
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_registry_capabilities text[];
  v_now timestamptz := clock_timestamp();
  v_worker_version text := p_worker_version;
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_assigned_building_count integer;
  v_connection_count integer;
  v_successful_poll_count integer;
  v_failed_poll_count integer;
  v_poll_observed_at timestamptz;
  v_retained_failed_poll_count integer;
  v_retained_successful_poll_count integer;
  v_expected_connection_count integer;
BEGIN
  -- Validate the raw release identity before calling the mutation-capable core.
  -- Trimming or case-folding would let a different deploy artifact claim proof.
  IF p_worker_version IS NULL
     OR octet_length(p_worker_version) <> 40
     OR p_worker_version !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'Invalid worker release version' USING ERRCODE = '22023';
  END IF;

  -- Poll-evidence parsing runs BEFORE the core now, because the effective
  -- status is derived from it and the core is what writes the building status
  -- an operator reads. The block itself is unchanged from 20260729136000; only
  -- its position moved. It stays fail-closed, and it now also fails closed
  -- earlier, before any building-status row is touched.
  IF p_safe_metadata ?| ARRAY[
    'connections', 'successfulPolls', 'failedPolls'
  ] THEN
    -- `?|`/`?&` test key EXISTENCE and ignore the value, so a JSON null passes
    -- both. Left unguarded, `->>` then yields SQL NULL, the integer casts below
    -- raise nothing, and the range comparison evaluates to NULL rather than TRUE
    -- (`NULL NOT BETWEEN ...` is NULL), so PL/pgSQL takes the ELSE branch and
    -- stamps poll_observed_at as if fresh evidence had been supplied. Only the
    -- all-or-nothing poll metrics CHECK then stops the write, and it does so as
    -- an opaque 23514 from inside the INSERT rather than the documented 22023 -
    -- so validation correctness would rest entirely on a storage constraint
    -- that is not part of this guard. Reject JSON null here instead, with the
    -- same clear error as a missing key.
    IF NOT (p_safe_metadata ?& ARRAY[
      'connections', 'successfulPolls', 'failedPolls'
    ])
       OR p_safe_metadata->>'connections' IS NULL
       OR p_safe_metadata->>'successfulPolls' IS NULL
       OR p_safe_metadata->>'failedPolls' IS NULL THEN
      RAISE EXCEPTION 'Incomplete worker poll evidence'
        USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_connection_count := (p_safe_metadata->>'connections')::integer;
      v_successful_poll_count := (p_safe_metadata->>'successfulPolls')::integer;
      v_failed_poll_count := (p_safe_metadata->>'failedPolls')::integer;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'Invalid worker poll evidence'
          USING ERRCODE = '22023';
    END;
    -- Fail closed on any residual NULL: a three-way comparison result is not
    -- TRUE and must never be read as "the range check passed".
    IF v_connection_count IS NULL
       OR v_successful_poll_count IS NULL
       OR v_failed_poll_count IS NULL
       OR v_connection_count NOT BETWEEN 0 AND 500
       OR v_successful_poll_count NOT BETWEEN 0 AND 500
       OR v_failed_poll_count NOT BETWEEN 0 AND 500
       OR v_successful_poll_count + v_failed_poll_count <> v_connection_count THEN
      RAISE EXCEPTION 'Invalid worker poll evidence'
        USING ERRCODE = '22023';
    END IF;
    v_poll_observed_at := v_now;
  END IF;

  -- The worker principal stays derived server-side from the credential digest.
  -- Deriving it here rather than after the core call is what lets the retained
  -- evidence be consulted before the building status is written; the core
  -- authenticates again with the same digest, so the trust boundary is
  -- unchanged and a bad digest still raises 28000 before anything is written.
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_registry_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'Invalid worker release heartbeat result'
      USING ERRCODE = '22023';
  END IF;

  -- Retained evidence for THIS release. A heartbeat that carries no poll
  -- evidence of its own - the 60 s periodic one - is measured against it.
  SELECT retained.failed_poll_count, retained.successful_poll_count
  INTO v_retained_failed_poll_count, v_retained_successful_poll_count
  FROM app_private.network_worker_release_heartbeats retained
  WHERE retained.worker_id = v_worker_id
    AND retained.worker_version = v_worker_version;

  -- Downgrade only, never upgrade. `coalesce` prefers this heartbeat's own
  -- count, so recovery is reported immediately and only a heartbeat that
  -- brought no evidence inherits the stored verdict.
  IF v_status = 'ONLINE'
     AND coalesce(v_failed_poll_count, v_retained_failed_poll_count, 0) > 0 THEN
    v_status := 'DEGRADED';
  END IF;

  -- Coverage. Failures the worker never attempted are failures it cannot
  -- report, so the claim is also measured against the number of connections
  -- PostgreSQL itself would serve this worker. The expectation is only computed
  -- on the ONLINE path: PAUSED, STOPPING and an already-DEGRADED heartbeat are
  -- never relabelled, and the query is not worth running for them.
  --
  -- Fail closed on a NULL expectation. `0 < NULL` is NULL, PL/pgSQL would take
  -- the ELSE branch, and a guard that cannot compute its own expectation would
  -- silently wave the claim through - the precise failure mode this migration
  -- exists to remove.
  IF v_status = 'ONLINE' THEN
    v_expected_connection_count :=
      app_private.network_center_worker_expected_connections_v1(
        v_worker_id, v_now
      );
    IF v_expected_connection_count IS NULL
       OR coalesce(
         v_successful_poll_count, v_retained_successful_poll_count, 0
       ) < v_expected_connection_count THEN
      v_status := 'DEGRADED';
    END IF;
  END IF;

  -- The private core performs validation, authentication, assignment locking and
  -- the scoped building-status upsert. If it fails, no release row is written.
  -- It is handed the EFFECTIVE status, so public.network_worker_building_status
  -- - the row the UI and Realtime read - can never show ONLINE while this
  -- release's own poll evidence records failures, nor while that evidence falls
  -- short of the connections the server would serve it.
  v_result := app_private.network_center_worker_heartbeat_core_v2(
    p_credential_digest,
    p_worker_version,
    p_capabilities,
    v_status,
    p_queue_age_seconds,
    p_safe_metadata,
    p_started_at
  );

  v_assigned_building_count := nullif(
    v_result->>'assignedBuildingCount', ''
  )::integer;
  -- If the core returned an unusable shape, refuse rather than let a NOT NULL /
  -- CHECK violation decide the outcome.
  IF v_status NOT IN ('ONLINE', 'DEGRADED', 'PAUSED', 'STOPPING')
     OR p_started_at IS NULL
     OR p_started_at > v_now
     OR v_assigned_building_count IS NULL
     OR v_assigned_building_count NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'Invalid worker release heartbeat result'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO app_private.network_worker_release_heartbeats (
    worker_id,
    worker_version,
    status,
    heartbeat_at,
    started_at,
    assigned_building_count,
    connection_count,
    successful_poll_count,
    failed_poll_count,
    poll_observed_at,
    updated_at
  ) VALUES (
    v_worker_id,
    v_worker_version,
    v_status,
    v_now,
    p_started_at,
    v_assigned_building_count,
    v_connection_count,
    v_successful_poll_count,
    v_failed_poll_count,
    v_poll_observed_at,
    v_now
  )
  ON CONFLICT (worker_id, worker_version) DO UPDATE SET
    status = EXCLUDED.status,
    heartbeat_at = EXCLUDED.heartbeat_at,
    started_at = LEAST(
      app_private.network_worker_release_heartbeats.started_at,
      EXCLUDED.started_at
    ),
    assigned_building_count = EXCLUDED.assigned_building_count,
    connection_count = coalesce(
      EXCLUDED.connection_count,
      app_private.network_worker_release_heartbeats.connection_count
    ),
    successful_poll_count = coalesce(
      EXCLUDED.successful_poll_count,
      app_private.network_worker_release_heartbeats.successful_poll_count
    ),
    failed_poll_count = coalesce(
      EXCLUDED.failed_poll_count,
      app_private.network_worker_release_heartbeats.failed_poll_count
    ),
    poll_observed_at = coalesce(
      EXCLUDED.poll_observed_at,
      app_private.network_worker_release_heartbeats.poll_observed_at
    ),
    updated_at = EXCLUDED.updated_at;

  -- Age-based expiry, but never for a release that is still a reachable
  -- rollback target. rollback-vultr.ps1 reads back BOTH the current and the
  -- previous release sha through network_center_admin_worker_release_status_v1
  -- and refuses the rollback when either row is missing. A superseded release
  -- stops heartbeating the instant it is replaced, so its heartbeat_at freezes
  -- at the promotion moment: a plain `heartbeat_at < now - 30 days` purge
  -- deletes the documented recovery evidence 30 days after promotion even
  -- though the host still holds the image and still names it as `previous`,
  -- silently disarming rollback. Ranking by heartbeat_at DESC is exactly
  -- promotion recency, so the newest releases per worker are retained
  -- regardless of age and only releases already displaced beyond the reachable
  -- rollback depth may expire by age. Growth stays bounded by the per-worker
  -- cap below, which evicts by the same rank order and therefore also never
  -- reaches a still-reachable target.
  DELETE FROM app_private.network_worker_release_heartbeats heartbeat
  USING (
    SELECT ranked.worker_id AS worker_id,
      ranked.worker_version AS worker_version,
      row_number() OVER (
        PARTITION BY ranked.worker_id
        ORDER BY ranked.heartbeat_at DESC, ranked.worker_version
      ) AS release_rank
    FROM app_private.network_worker_release_heartbeats ranked
  ) reachable
  WHERE reachable.worker_id = heartbeat.worker_id
    AND reachable.worker_version = heartbeat.worker_version
    AND reachable.release_rank > c_rollback_reachable_releases
    AND heartbeat.heartbeat_at < v_now - c_release_retention_max_age;

  DELETE FROM app_private.network_worker_release_heartbeats heartbeat
  WHERE heartbeat.worker_id = v_worker_id
    AND (heartbeat.worker_id, heartbeat.worker_version) IN (
      SELECT ranked.worker_id, ranked.worker_version
      FROM app_private.network_worker_release_heartbeats ranked
      WHERE ranked.worker_id = v_worker_id
      ORDER BY ranked.heartbeat_at DESC, ranked.worker_version
      OFFSET c_release_retention_limit
    );

  RETURN v_result || jsonb_build_object('workerVersion', v_worker_version);
END;
$_$;








--
-- Name: FUNCTION network_center_worker_heartbeat_v2(p_credential_digest text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.network_center_worker_heartbeat_v2(p_credential_digest text, p_worker_version text, p_capabilities text[], p_status text, p_queue_age_seconds integer, p_safe_metadata jsonb, p_started_at timestamp with time zone) IS 'Worker heartbeat with bounded release readback. Status is downgrade-only: an ONLINE claim is stored and forwarded as DEGRADED whenever this heartbeat''s own poll evidence, or the retained evidence for the same release, records failed polls, or whenever its successful poll count falls short of the server-derived count of connections PostgreSQL would serve this worker.';








--
-- Name: network_center_worker_ingest_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_ingest_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
  v_target_count integer;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR jsonb_typeof(coalesce(p_payload->'devices', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'interfaces', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'clients', '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Invalid telemetry payload' USING ERRCODE = '22023';
  END IF;
  v_target_count := jsonb_array_length(coalesce(p_payload->'devices', '[]'::jsonb))
    + jsonb_array_length(coalesce(p_payload->'interfaces', '[]'::jsonb))
    + jsonb_array_length(coalesce(p_payload->'clients', '[]'::jsonb));
  IF v_target_count = 0 OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'devices', '[]'::jsonb)) item
    LEFT JOIN public.network_devices device
      ON device.id = nullif(item->>'deviceId', '')::uuid
    LEFT JOIN public.network_devices router
      ON router.id = CASE WHEN device.device_kind = 'MIKROTIK'
        THEN device.id ELSE device.parent_device_id END
    WHERE router.id IS NULL OR NOT
      app_private.network_center_compatibility_can_access_device_v1(
        v_compat_worker_id, router.organization_id, router.building_id,
        router.id, 'can_poll'
      )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'interfaces', '[]'::jsonb)) item
    LEFT JOIN public.network_interfaces interface
      ON interface.id = nullif(item->>'interfaceId', '')::uuid
    LEFT JOIN public.network_devices device ON device.id = interface.device_id
    LEFT JOIN public.network_devices router
      ON router.id = CASE WHEN device.device_kind = 'MIKROTIK'
        THEN device.id ELSE device.parent_device_id END
    WHERE router.id IS NULL OR NOT
      app_private.network_center_compatibility_can_access_device_v1(
        v_compat_worker_id, router.organization_id, router.building_id,
        router.id, 'can_poll'
      )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'clients', '[]'::jsonb)) item
    LEFT JOIN public.network_devices device
      ON device.id = nullif(item->>'deviceId', '')::uuid
    LEFT JOIN public.network_devices router
      ON router.id = CASE WHEN device.device_kind = 'MIKROTIK'
        THEN device.id ELSE device.parent_device_id END
    WHERE router.id IS NULL OR NOT
      app_private.network_center_compatibility_can_access_device_v1(
        v_compat_worker_id, router.organization_id, router.building_id,
        router.id, 'can_poll'
      )
  ) THEN
    RAISE EXCEPTION 'Legacy telemetry target is outside compatibility snapshot'
      USING ERRCODE = '42501';
  END IF;
  RETURN app_private.network_center_worker_ingest_legacy_impl_v1(
    v_compat_worker_key, p_payload
  );
END;
$$;








--
-- Name: network_center_worker_ingest_v2(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_ingest_v2(p_credential_digest text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_target_count integer;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR jsonb_typeof(coalesce(p_payload->'devices', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'interfaces', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_payload->'clients', '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Invalid telemetry payload' USING ERRCODE = '22023';
  END IF;

  v_target_count := jsonb_array_length(coalesce(p_payload->'devices', '[]'::jsonb))
    + jsonb_array_length(coalesce(p_payload->'interfaces', '[]'::jsonb))
    + jsonb_array_length(coalesce(p_payload->'clients', '[]'::jsonb));
  IF v_target_count = 0 THEN
    RAISE EXCEPTION 'Telemetry payload requires an assigned target'
      USING ERRCODE = '42501';
  END IF;

  -- All arrays are checked before the legacy all-or-nothing writer is entered.
  -- A single unknown or unassigned target aborts the transaction, so a mixed
  -- authorized/unauthorized batch cannot partially persist.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'devices', '[]'::jsonb)) item
    LEFT JOIN public.network_devices device
      ON device.id = nullif(item->>'deviceId', '')::uuid
    LEFT JOIN public.network_devices assigned_router
      ON assigned_router.id = CASE
        WHEN device.device_kind = 'MIKROTIK' THEN device.id
        ELSE device.parent_device_id
      END
     AND assigned_router.organization_id = device.organization_id
     AND assigned_router.building_id = device.building_id
     AND assigned_router.device_kind = 'MIKROTIK'
    WHERE assigned_router.id IS NULL
       OR NOT app_private.network_center_worker_can_access_device_v2(
         v_worker_id, assigned_router.organization_id,
         assigned_router.building_id, assigned_router.id, 'TELEMETRY'
       )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'interfaces', '[]'::jsonb)) item
    LEFT JOIN public.network_interfaces interface
      ON interface.id = nullif(item->>'interfaceId', '')::uuid
    LEFT JOIN public.network_devices device ON device.id = interface.device_id
    LEFT JOIN public.network_devices assigned_router
      ON assigned_router.id = CASE
        WHEN device.device_kind = 'MIKROTIK' THEN device.id
        ELSE device.parent_device_id
      END
     AND assigned_router.organization_id = interface.organization_id
     AND assigned_router.building_id = interface.building_id
     AND assigned_router.device_kind = 'MIKROTIK'
    WHERE assigned_router.id IS NULL
       OR NOT app_private.network_center_worker_can_access_device_v2(
         v_worker_id, assigned_router.organization_id,
         assigned_router.building_id, assigned_router.id, 'TELEMETRY'
       )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_payload->'clients', '[]'::jsonb)) item
    LEFT JOIN public.network_devices device
      ON device.id = nullif(item->>'deviceId', '')::uuid
    LEFT JOIN public.network_devices assigned_router
      ON assigned_router.id = CASE
        WHEN device.device_kind = 'MIKROTIK' THEN device.id
        ELSE device.parent_device_id
      END
     AND assigned_router.organization_id = device.organization_id
     AND assigned_router.building_id = device.building_id
     AND assigned_router.device_kind = 'MIKROTIK'
    LEFT JOIN public.network_interfaces interface
      ON nullif(item->>'interfaceId', '') IS NOT NULL
     AND interface.id = nullif(item->>'interfaceId', '')::uuid
     AND interface.organization_id = device.organization_id
     AND interface.building_id = device.building_id
     AND interface.device_id = device.id
    WHERE assigned_router.id IS NULL
       OR (
         nullif(item->>'interfaceId', '') IS NOT NULL
         AND interface.id IS NULL
       )
       OR NOT app_private.network_center_worker_can_access_device_v2(
         v_worker_id, assigned_router.organization_id,
         assigned_router.building_id, assigned_router.id, 'TELEMETRY'
       )
  ) THEN
    RAISE EXCEPTION 'Unauthorized telemetry target in mixed payload'
      USING ERRCODE = '42501';
  END IF;

  RETURN app_private.network_center_worker_ingest_legacy_impl_v1(
    v_worker_key, p_payload
  );
END;
$$;








--
-- Name: network_center_worker_inventory_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_inventory_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
  v_router public.network_devices%ROWTYPE;
  v_result jsonb;
  v_mapping jsonb;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  SELECT router.* INTO v_router FROM public.network_devices router
  WHERE router.id = nullif(p_payload->>'routerDeviceId', '')::uuid
    AND router.device_kind = 'MIKROTIK' AND router.is_active
  FOR UPDATE;
  IF NOT FOUND OR NOT
    app_private.network_center_compatibility_can_access_device_v1(
      v_compat_worker_id, v_router.organization_id, v_router.building_id,
      v_router.id, 'can_inventory'
    ) THEN
    RAISE EXCEPTION 'Legacy inventory target is outside compatibility snapshot'
      USING ERRCODE = '42501';
  END IF;
  v_result := app_private.network_center_worker_inventory_legacy_impl_v1(
    v_compat_worker_key, p_payload
  );
  v_mapping := app_private.network_center_managed_interface_mapping_v1(v_router.id);
  v_result := jsonb_set(v_result, '{interfaces}', v_mapping, true);
  v_result := jsonb_set(
    v_result, '{interfaceCount}', to_jsonb(jsonb_array_length(v_mapping)), true
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_worker_inventory_v2(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_inventory_v2(p_credential_digest text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_router public.network_devices%ROWTYPE;
  v_result jsonb;
  v_mapping jsonb;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'Invalid inventory payload' USING ERRCODE = '22023';
  END IF;
  SELECT router.* INTO v_router
  FROM public.network_devices router
  WHERE router.id = nullif(p_payload->>'routerDeviceId', '')::uuid
    AND router.device_kind = 'MIKROTIK'
    AND router.is_active
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory router not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT app_private.network_center_worker_can_access_device_v2(
    v_worker_id, v_router.organization_id, v_router.building_id,
    v_router.id, 'INVENTORY'
  ) THEN
    RAISE EXCEPTION 'Worker is not assigned to inventory target'
      USING ERRCODE = '42501';
  END IF;

  v_result := app_private.network_center_worker_inventory_legacy_impl_v1(
    v_worker_key, p_payload
  );
  v_mapping := app_private.network_center_managed_interface_mapping_v1(
    v_router.id
  );
  -- Keep Task 9's Aruba/quarantine fields byte-for-byte and replace only the
  -- interface authorization mapping with Task 10's private authoritative data.
  v_result := jsonb_set(v_result, '{interfaces}', v_mapping, true);
  v_result := jsonb_set(
    v_result, '{interfaceCount}', to_jsonb(jsonb_array_length(v_mapping)), true
  );
  RETURN v_result;
END;
$$;








--
-- Name: network_center_worker_list_connections_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_list_connections_v1(p_worker_id text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  IF p_limit NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'Invalid worker connection request'
      USING ERRCODE = '22023';
  END IF;
  SELECT jsonb_build_object('items', coalesce(jsonb_agg(item ORDER BY
    organization_id, building_id, device_id
  ), '[]'::jsonb)) INTO v_result
  FROM (
    SELECT connection.organization_id, connection.building_id,
      connection.device_id, jsonb_build_object(
        'connectionId', connection.id,
        'organizationId', connection.organization_id,
        'buildingId', connection.building_id,
        'deviceId', connection.device_id,
        'deviceKind', device.device_kind,
        'externalKey', device.external_key,
        'displayName', device.display_name,
        'transport', connection.transport,
        'managementIp', host(connection.management_ip),
        'managementPort', connection.management_port,
        'credentialRef', connection.credential_ref,
        'hostKeyFingerprint', connection.host_key_fingerprint,
        'pollIntervalSeconds', coalesce(
          settings.poll_interval_seconds, connection.poll_interval_seconds
        ),
        'connectTimeoutMs', connection.connect_timeout_ms,
        'monitoringEnabled', coalesce(settings.monitoring_enabled, true),
        'changesPaused', coalesce(settings.changes_paused, false)
      ) AS item
    FROM public.network_device_connections connection
    JOIN public.network_devices device ON device.id = connection.device_id
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = v_compat_worker_id
     AND assignment.organization_id = connection.organization_id
     AND assignment.building_id = connection.building_id
     AND assignment.device_id = connection.device_id
     AND assignment.can_poll
     AND assignment.active_from <= v_now
     AND assignment.active_until > v_now
    JOIN app_private.network_worker_compatibility_state state
      ON state.worker_id = assignment.worker_id
     AND state.singleton AND state.finalized_at IS NULL
     AND state.expires_at > v_now
     AND state.assignment_snapshot @> jsonb_build_array(jsonb_build_object(
       'assignmentId', assignment.id,
       'organizationId', assignment.organization_id,
       'buildingId', assignment.building_id,
       'deviceId', assignment.device_id
     ))
    LEFT JOIN public.network_site_settings settings
      ON settings.organization_id = connection.organization_id
     AND settings.building_id = connection.building_id
    WHERE connection.is_enabled AND device.is_active
    ORDER BY connection.organization_id, connection.building_id,
      connection.device_id
    LIMIT p_limit
  ) scoped_connections;
  RETURN coalesce(v_result, jsonb_build_object('items', '[]'::jsonb));
END;
$$;








--
-- Name: network_center_worker_list_connections_v2(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_list_connections_v2(p_credential_digest text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_limit NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'Invalid worker connection request'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'items', coalesce(jsonb_agg(row.item ORDER BY
      row.organization_id, row.building_id, row.device_id
    ), '[]'::jsonb)
  ) INTO v_result
  FROM (
    SELECT DISTINCT ON (connection.id)
      connection.organization_id, connection.building_id,
      connection.device_id, connection.id,
      jsonb_build_object(
        'connectionId', connection.id,
        'organizationId', connection.organization_id,
        'buildingId', connection.building_id,
        'deviceId', connection.device_id,
        'deviceKind', device.device_kind,
        'externalKey', device.external_key,
        'displayName', device.display_name,
        'transport', connection.transport,
        'managementIp', host(connection.management_ip),
        'managementPort', connection.management_port,
        'credentialRef', connection.credential_ref,
        'hostKeyFingerprint', connection.host_key_fingerprint,
        'pollIntervalSeconds', coalesce(
          settings.poll_interval_seconds, connection.poll_interval_seconds
        ),
        'connectTimeoutMs', connection.connect_timeout_ms,
        'monitoringEnabled', coalesce(settings.monitoring_enabled, true),
        'changesPaused', coalesce(settings.changes_paused, false)
      ) AS item
    FROM public.network_device_connections connection
    JOIN public.network_devices device
      ON device.organization_id = connection.organization_id
     AND device.building_id = connection.building_id
     AND device.id = connection.device_id
    JOIN public.network_worker_assignments assignment
      ON assignment.worker_id = v_worker_id
     AND assignment.organization_id = connection.organization_id
     AND assignment.building_id = connection.building_id
     AND assignment.device_id = connection.device_id
     AND assignment.can_poll
     AND assignment.active_from <= v_now
     AND (
       assignment.active_until IS NULL
       OR assignment.active_until > v_now
     )
    JOIN public.network_workers worker
      ON worker.id = assignment.worker_id
     AND worker.status IN ('ACTIVE', 'DRAINING')
     AND 'POLL' = ANY(worker.capabilities)
    LEFT JOIN public.network_site_settings settings
      ON settings.organization_id = connection.organization_id
     AND settings.building_id = connection.building_id
    WHERE connection.is_enabled AND device.is_active
    ORDER BY connection.id, assignment.active_from DESC
    LIMIT p_limit
  ) row;
  RETURN coalesce(v_result, jsonb_build_object('items', '[]'::jsonb));
END;
$$;








--
-- Name: network_center_worker_maintenance_v1(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_maintenance_v1(p_worker_id text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_compat_worker_id uuid;
  v_compat_worker_key text;
  v_expired_clients bigint := 0;
  v_windows_updated bigint := 0;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  IF p_now IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - p_now))) > 3600 THEN
    RAISE EXCEPTION 'Invalid worker maintenance request'
      USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.network_client_current client
  WHERE client.expires_at <= p_now
    AND EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      JOIN app_private.network_worker_compatibility_state state
        ON state.worker_id = assignment.worker_id
       AND state.singleton AND state.finalized_at IS NULL
       AND state.expires_at > p_now
      JOIN public.network_devices device ON device.id = client.device_id
      WHERE assignment.worker_id = v_compat_worker_id
        AND assignment.organization_id = client.organization_id
        AND assignment.building_id = client.building_id
        AND assignment.device_id = CASE WHEN device.device_kind = 'MIKROTIK'
          THEN device.id ELSE device.parent_device_id END
        AND assignment.can_poll
        AND assignment.active_from <= p_now
        AND assignment.active_until > p_now
        AND state.assignment_snapshot @> jsonb_build_array(jsonb_build_object(
          'assignmentId', assignment.id,
          'organizationId', assignment.organization_id,
          'buildingId', assignment.building_id,
          'deviceId', assignment.device_id
        ))
    );
  GET DIAGNOSTICS v_expired_clients = ROW_COUNT;
  UPDATE public.network_maintenance_windows maintenance
  SET status = CASE WHEN maintenance.ends_at <= p_now
    THEN 'COMPLETED' ELSE 'ACTIVE' END
  WHERE maintenance.status IN ('SCHEDULED', 'ACTIVE')
    AND (maintenance.starts_at <= p_now OR maintenance.ends_at <= p_now)
    AND EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      JOIN app_private.network_worker_compatibility_state state
        ON state.worker_id = assignment.worker_id
       AND state.singleton AND state.finalized_at IS NULL
       AND state.expires_at > p_now
      WHERE assignment.worker_id = v_compat_worker_id
        AND assignment.organization_id = maintenance.organization_id
        AND assignment.building_id = maintenance.building_id
        AND assignment.can_poll
        AND assignment.active_from <= p_now
        AND assignment.active_until > p_now
        AND state.assignment_snapshot @> jsonb_build_array(jsonb_build_object(
          'assignmentId', assignment.id,
          'organizationId', assignment.organization_id,
          'buildingId', assignment.building_id,
          'deviceId', assignment.device_id
        ))
    );
  GET DIAGNOSTICS v_windows_updated = ROW_COUNT;
  RETURN jsonb_build_object(
    'at', p_now, 'expiredClients', v_expired_clients,
    'maintenanceWindowsUpdated', v_windows_updated,
    'reclaimedCommands', 0
  );
END;
$$;








--
-- Name: network_center_worker_maintenance_v2(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_maintenance_v2(p_credential_digest text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_expired_clients bigint := 0;
  v_windows_updated bigint := 0;
  v_building_count integer := 0;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_now IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - p_now))) > 3600 THEN
    RAISE EXCEPTION 'Invalid worker maintenance request'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_building_count
  FROM (
    SELECT DISTINCT assignment.organization_id, assignment.building_id
    FROM public.network_worker_assignments assignment
    WHERE assignment.worker_id = v_worker_id
      AND assignment.can_poll
      AND assignment.active_from <= p_now
      AND (
        assignment.active_until IS NULL
        OR assignment.active_until > p_now
      )
      AND app_private.network_center_worker_can_access_building_v2(
        v_worker_id, assignment.organization_id,
        assignment.building_id, 'MAINTENANCE', p_now
      )
  ) assigned_building;
  IF v_building_count = 0 THEN
    RAISE EXCEPTION 'Worker has no maintenance assignment'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.network_client_current client
  WHERE client.expires_at <= p_now
    AND EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      JOIN public.network_devices client_device
        ON client_device.organization_id = client.organization_id
       AND client_device.building_id = client.building_id
       AND client_device.id = client.device_id
      WHERE assignment.worker_id = v_worker_id
        AND assignment.organization_id = client.organization_id
        AND assignment.building_id = client.building_id
        AND assignment.device_id = CASE
          WHEN client_device.device_kind = 'MIKROTIK' THEN client_device.id
          ELSE client_device.parent_device_id
        END
        AND assignment.can_poll
        AND assignment.active_from <= p_now
        AND (
          assignment.active_until IS NULL
          OR assignment.active_until > p_now
        )
    );
  GET DIAGNOSTICS v_expired_clients = ROW_COUNT;

  UPDATE public.network_maintenance_windows maintenance
  SET status = CASE
    WHEN maintenance.ends_at <= p_now THEN 'COMPLETED' ELSE 'ACTIVE'
  END
  WHERE maintenance.status IN ('SCHEDULED', 'ACTIVE')
    AND (
      maintenance.starts_at <= p_now OR maintenance.ends_at <= p_now
    )
    AND EXISTS (
      SELECT 1
      FROM public.network_worker_assignments assignment
      WHERE assignment.worker_id = v_worker_id
        AND assignment.organization_id = maintenance.organization_id
        AND assignment.building_id = maintenance.building_id
        AND assignment.can_poll
        AND assignment.active_from <= p_now
        AND (
          assignment.active_until IS NULL
          OR assignment.active_until > p_now
        )
    );
  GET DIAGNOSTICS v_windows_updated = ROW_COUNT;

  -- Fleet-global partition, retention, rollup and command reclamation remain a
  -- separate trusted scheduler responsibility; worker auth never invokes them.
  RETURN jsonb_build_object(
    'at', p_now,
    'assignedBuildings', v_building_count,
    'expiredClients', v_expired_clients,
    'maintenanceWindowsUpdated', v_windows_updated,
    'reclaimedCommands', 0
  );
END;
$$;








--
-- Name: network_center_worker_observe_v2(text, uuid, uuid, bigint, bigint, uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_observe_v2(p_credential_digest text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_transition_version bigint, p_observation_id uuid, p_observation_kind text, p_observed_at timestamp with time zone, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_command public.network_commands%ROWTYPE;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.command_id = command.id
   AND lease.device_id = command.device_id
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = v_worker_key
    AND lease.lease_token = p_lease_token
    AND lease.lease_owner = v_worker_key
    AND lease.generation = p_fencing_generation
    AND lease.expires_at > clock_timestamp()
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active fenced observation lease not found'
      USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.network_center_worker_can_access_device_v2(
    v_worker_id, v_command.organization_id, v_command.building_id,
    v_command.device_id, 'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'Worker is not assigned to observation target'
      USING ERRCODE = '42501';
  END IF;
  RETURN app_private.network_center_record_command_observation_v1(
    v_worker_key, p_command_id, p_lease_token, p_fencing_generation,
    p_transition_version, p_observation_id, p_observation_kind,
    p_observed_at, p_evidence
  );
END;
$$;








--
-- Name: network_center_worker_renew_v1(text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_renew_v1(p_worker_id text, p_command_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_compat_worker_id uuid; v_compat_worker_key text;
BEGIN
  SELECT compatibility.worker_id, compatibility.worker_key
  INTO v_compat_worker_id, v_compat_worker_key
  FROM app_private.network_center_compatibility_worker_v1() compatibility;
  RAISE EXCEPTION 'Legacy compatibility cannot renew command leases'
    USING ERRCODE = '42501';
END;
$$;








--
-- Name: network_center_worker_renew_v2(text, uuid, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_renew_v2(p_credential_digest text, p_command_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_worker_id uuid;
  v_worker_key text;
  v_worker_status text;
  v_capabilities text[];
  v_command public.network_commands%ROWTYPE;
BEGIN
  SELECT authenticated.worker_id, authenticated.worker_key,
    authenticated.worker_status, authenticated.capabilities
  INTO v_worker_id, v_worker_key, v_worker_status, v_capabilities
  FROM app_private.network_center_authenticate_worker_v2(
    p_credential_digest
  ) authenticated;
  IF p_command_id IS NULL OR p_lease_token IS NULL
     OR p_fencing_generation < 1
     OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
    RAISE EXCEPTION 'Invalid lease renewal request' USING ERRCODE = '22023';
  END IF;

  SELECT command.* INTO v_command
  FROM public.network_commands command
  JOIN public.network_device_leases lease
    ON lease.organization_id = command.organization_id
   AND lease.building_id = command.building_id
   AND lease.device_id = command.device_id
   AND lease.command_id = command.id
  WHERE command.id = p_command_id
    AND command.lease_token = p_lease_token
    AND command.lease_owner = v_worker_key
    AND command.status IN ('LEASED', 'RUNNING', 'RECONCILING')
    AND lease.lease_token = p_lease_token
    AND lease.lease_owner = v_worker_key
    AND lease.generation = p_fencing_generation
    AND lease.expires_at > clock_timestamp()
  FOR UPDATE OF command, lease;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active fenced command lease not found'
      USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.network_center_worker_can_access_device_v2(
    v_worker_id, v_command.organization_id, v_command.building_id,
    v_command.device_id, 'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'Worker is not assigned to target device'
      USING ERRCODE = '42501';
  END IF;
  RETURN app_private.network_center_worker_renew_legacy_impl_v1(
    v_worker_key, p_command_id, p_lease_token, p_lease_seconds
  );
END;
$$;








--
-- Name: network_center_worker_snapshot_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.network_center_worker_snapshot_v1(p_worker_id text, p_payload jsonb) RETURNS jsonb
