--
-- Name: nrm_vn(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nrm_vn(s text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT trim(replace(
    lower(regexp_replace(normalize(coalesce(s, ''), NFD), '[̀-ͯ]', '', 'g')),
    'đ', 'd'
  ))
$$;








--
-- Name: occupancy_snapshot_v2(date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.occupancy_snapshot_v2(p_as_of_date date DEFAULT CURRENT_DATE, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(building_id uuid, building_name text, total integer, occupied integer, reserved integer, maintenance integer, unavailable integer, available integer, occupancy_pct numeric, committed_pct numeric, missed_revenue numeric, generated_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  classified AS (
    SELECT
      r.building_id AS bid,
      r.rent_price,
      CASE
        WHEN EXISTS (
          SELECT 1 FROM public.contracts c
          WHERE c.room_id = r.id
            AND c.deleted_at IS NULL
            AND c.status = 'ACTIVE'
            AND c.start_date <= p_as_of_date
            AND (c.actual_end_date IS NULL OR c.actual_end_date >= p_as_of_date)
        ) THEN 'occupied'
        WHEN r.status = 'RESERVED'    THEN 'reserved'
        WHEN r.status = 'MAINTENANCE' THEN 'maintenance'
        WHEN r.status = 'AVAILABLE'   THEN 'available'
        -- UNAVAILABLE + mọi trạng thái bất thường (VD OCCUPIED mồ côi HĐ):
        ELSE 'unavailable'
      END AS grp
    FROM public.rooms r
    JOIN allowed a ON a.id = r.building_id
    WHERE r.deleted_at IS NULL
  ),
  agg AS (
    SELECT
      bid,
      COUNT(*)::int                                   AS total,
      COUNT(*) FILTER (WHERE grp = 'occupied')::int    AS occupied,
      COUNT(*) FILTER (WHERE grp = 'reserved')::int    AS reserved,
      COUNT(*) FILTER (WHERE grp = 'maintenance')::int AS maintenance,
      COUNT(*) FILTER (WHERE grp = 'unavailable')::int AS unavailable,
      COUNT(*) FILTER (WHERE grp = 'available')::int   AS available,
      COALESCE(SUM(GREATEST(rent_price, 0)) FILTER (WHERE grp = 'available'), 0)::numeric
        AS missed_revenue
    FROM classified
    GROUP BY bid
  )
  SELECT
    a.id,
    a.name,
    COALESCE(g.total, 0),
    COALESCE(g.occupied, 0),
    COALESCE(g.reserved, 0),
    COALESCE(g.maintenance, 0),
    COALESCE(g.unavailable, 0),
    COALESCE(g.available, 0),
    CASE WHEN COALESCE(g.total, 0) = 0 THEN 0
         ELSE ROUND(g.occupied * 100.0 / g.total, 1) END::numeric,
    CASE WHEN COALESCE(g.total, 0) = 0 THEN 0
         ELSE ROUND((g.occupied + g.reserved) * 100.0 / g.total, 1) END::numeric,
    COALESCE(g.missed_revenue, 0),
    now()
  FROM allowed a
  LEFT JOIN agg g ON g.bid = a.id
  ORDER BY a.name;
$$;








--
-- Name: FUNCTION occupancy_snapshot_v2(p_as_of_date date, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.occupancy_snapshot_v2(p_as_of_date date, p_building_ids uuid[]) IS 'Snapshot lấp đầy theo toà tại p_as_of_date. occupied = HĐ ACTIVE start<=as_of chưa actual_end (KHÔNG cắt end_date — quá hạn chưa thanh lý vẫn là đang ở). 5 nhóm phân hoạch đủ total; trạng thái lạ vào unavailable, KHÔNG vào available. missed_revenue = Σ GREATEST(rent_price,0) nhóm available. INVOKER + can_access_building; p_building_ids chỉ thu hẹp.';








--
-- Name: occupancy_upcoming_vacancy_v2(date, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.occupancy_upcoming_vacancy_v2(p_as_of_date date DEFAULT CURRENT_DATE, p_window_days integer DEFAULT 60, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(contract_id uuid, contract_number text, building_id uuid, building_name text, room_id uuid, room_name text, effective_end_date date, days_remaining integer, rent_price numeric, extension_applied boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH allowed AS (
    SELECT b.id, b.name
    FROM public.buildings b
    WHERE b.deleted_at IS NULL
      AND b.is_virtual = false
      AND (p_building_ids IS NULL OR b.id = ANY(p_building_ids))
      AND public.can_access_building(b.id)
  ),
  eff AS (
    -- 1 dòng / HĐ ACTIVE đang hiệu lực tại as_of, kèm effective_end_date
    SELECT
      c.id,
      c.contract_number,
      c.room_id,
      GREATEST(
        c.end_date,
        COALESCE((
          SELECT MAX(ce.new_end_date::date)
          FROM public.contract_extensions ce
          WHERE ce.contract_id = c.id
            AND ce.status IN ('APPROVED', 'COMPLETED')
        ), c.end_date)
      )::date AS eff_end,
      EXISTS (
        SELECT 1 FROM public.contract_extensions ce
        WHERE ce.contract_id = c.id
          AND ce.status IN ('APPROVED', 'COMPLETED')
          AND ce.new_end_date::date > c.end_date
      ) AS ext_applied
    FROM public.contracts c
    WHERE c.deleted_at IS NULL
      AND c.status = 'ACTIVE'
      AND c.start_date <= p_as_of_date
      AND (c.actual_end_date IS NULL OR c.actual_end_date >= p_as_of_date)
  ),
  per_room AS (
    -- 1 phòng chỉ xuất hiện 1 lần: lấy HĐ có effective_end xa nhất
    SELECT DISTINCT ON (e.room_id)
      e.id, e.contract_number, e.room_id, e.eff_end, e.ext_applied
    FROM eff e
    ORDER BY e.room_id, e.eff_end DESC, e.id
  )
  SELECT
    p.id,
    p.contract_number,
    a.id,
    a.name,
    r.id,
    r.name,
    p.eff_end,
    (p.eff_end - p_as_of_date)::int,
    r.rent_price::numeric,
    p.ext_applied
  FROM per_room p
  JOIN public.rooms r ON r.id = p.room_id AND r.deleted_at IS NULL
  JOIN allowed a ON a.id = r.building_id
  WHERE (p.eff_end - p_as_of_date) BETWEEN 0 AND GREATEST(p_window_days, 0)
  ORDER BY p.eff_end, a.name, r.name;
$$;








--
-- Name: FUNCTION occupancy_upcoming_vacancy_v2(p_as_of_date date, p_window_days integer, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.occupancy_upcoming_vacancy_v2(p_as_of_date date, p_window_days integer, p_building_ids uuid[]) IS 'Phòng sắp trống trong [0..p_window_days] ngày kể từ p_as_of_date. effective_end = GREATEST(end_date, MAX new_end_date của extension APPROVED|COMPLETED) — không dùng status EXTENDED. 1 phòng 1 dòng (HĐ end xa nhất). Chỉ HĐ ACTIVE đang hiệu lực. INVOKER + can_access_building; p_building_ids chỉ thu hẹp.';








--
-- Name: openclaw_acknowledge_disclosure_v1(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openclaw_acknowledge_disclosure_v1(p_request jsonb, p_client_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := (select app_private.openclaw_actor_id_v1());
  v_org uuid := (p_request->>'organizationId')::uuid;
  v_operation jsonb;
  v_request_hash text;
  v_account public.openclaw_accounts%rowtype;
  v_acknowledged_at timestamptz;
  v_result jsonb;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','organizationId','accountId','disclosureVersion'],
    array['version','organizationId','accountId','disclosureVersion']
  );
  if v_actor is null or p_request->>'version'<>'1'
     or jsonb_typeof(p_request->'disclosureVersion')<>'number'
     or (p_request->>'disclosureVersion')::integer<1
  then
    raise exception 'disclosure acknowledgement invalid' using errcode='22023';
  end if;
  perform app_private.lock_org_for_decision_v1(v_org);
  perform app_private.require_perm_v1(
    v_org,'openclaw_zalo.manage_connections','xac nhan cong bo OpenClaw Zalo'
  );
  v_operation:=app_private.openclaw_begin_client_operation_v1(
    v_org,v_actor,'openclaw_acknowledge_disclosure_v1',p_client_operation_id,p_request
  );
  if coalesce((v_operation->>'conflict')::boolean,false) then return v_operation; end if;
  if coalesce((v_operation->>'isReplay')::boolean,false) then
    return (v_operation->'safeResult') || jsonb_build_object('idempotentReplay',true);
  end if;
  v_request_hash:=v_operation->>'requestHash';
  select account.* into strict v_account
  from public.openclaw_accounts account
  where account.organization_id=v_org
    and account.id=(p_request->>'accountId')::uuid
  for update;
  if v_account.disclosure_version<>(p_request->>'disclosureVersion')::integer then
    raise exception 'disclosure version mismatch' using errcode='40001';
  end if;
  update public.openclaw_accounts account set
    disclosure_acknowledged_version=v_account.disclosure_version,
    disclosure_acknowledged_at=statement_timestamp(),
    updated_at=statement_timestamp()
  where account.organization_id=v_org and account.id=v_account.id
  returning account.disclosure_acknowledged_at into v_acknowledged_at;
  v_result:=jsonb_build_object(
    'version',1,'organizationId',v_org,'accountId',v_account.id,
    'disclosureAcknowledgedVersion',v_account.disclosure_version,
    'disclosureAcknowledgedAt',v_acknowledged_at,
    'idempotentReplay',false
  );
  return app_private.openclaw_finish_browser_write_v1(
    v_org,v_actor,'openclaw_acknowledge_disclosure_v1',p_client_operation_id,
    v_request_hash,'OPENCLAW_DISCLOSURE_ACKNOWLEDGED',v_result
  );
end;
$$;








--
-- Name: openclaw_acknowledge_risk_v1(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openclaw_acknowledge_risk_v1(p_request jsonb, p_client_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := (select app_private.openclaw_actor_id_v1()); v_org uuid := (p_request ->> 'organizationId')::uuid;
  v_operation jsonb; v_request_hash text; v_account public.openclaw_accounts%rowtype;
  v_result jsonb;
begin
  perform app_private.openclaw_assert_strict_object_v1(
    p_request,
    array['version','organizationId','accountId','expectedRiskState','acknowledgedRiskState','evidenceHash'],
    array['version','organizationId','accountId','expectedRiskState','acknowledgedRiskState','evidenceHash']
  );
  if v_actor is null then raise exception 'authentication required' using errcode = '42501'; end if;
  perform app_private.lock_org_for_decision_v1(v_org);
  perform app_private.require_perm_v1(v_org, 'openclaw_zalo.manage_connections', 'xác nhận rủi ro OpenClaw Zalo');
  v_operation := app_private.openclaw_begin_client_operation_v1(
    v_org, v_actor, 'openclaw_acknowledge_risk_v1', p_client_operation_id, p_request
  );
  if coalesce((v_operation ->> 'conflict')::boolean, false) then return v_operation; end if;
  if coalesce((v_operation ->> 'isReplay')::boolean, false) then return v_operation -> 'safeResult'; end if;
  v_request_hash := v_operation ->> 'requestHash';
  select account.* into strict v_account from public.openclaw_accounts account
  where account.organization_id = v_org and account.id = (p_request ->> 'accountId')::uuid
  for update;
  if v_account.session_risk_state is distinct from p_request ->> 'expectedRiskState'
     or p_request ->> 'acknowledgedRiskState' not in ('HEALTHY','DEGRADED')
     or (p_request ->> 'evidenceHash') !~ '^[0-9a-f]{64}$'
  then
    raise exception 'risk acknowledgement CAS failed' using errcode = '40001';
  end if;
  update public.openclaw_accounts
  set session_risk_state = p_request ->> 'acknowledgedRiskState',
      effective_mode = 'DRAFT_ONLY', updated_at = statement_timestamp()
  where organization_id = v_org and id = v_account.id;
  v_result := jsonb_build_object(
    'version', 1, 'organizationId', v_org, 'accountId', v_account.id,
    'sessionRiskState', p_request ->> 'acknowledgedRiskState',
    'effectiveMode', 'DRAFT_ONLY'
  );
  return app_private.openclaw_finish_browser_write_v1(
    v_org, v_actor, 'openclaw_acknowledge_risk_v1', p_client_operation_id,
    v_request_hash, 'OPENCLAW_RISK_ACKNOWLEDGED', v_result
  );
end;
$_$;








