--
-- Name: pra_by_token(date, date, text, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_by_token(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false) RETURNS TABLE(token text, label text, revoked boolean, sessions bigint, views bigint, room_opens bigint, contact_clicks bigint, errors bigint, avg_session_ms numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ev AS (
    SELECT e.* FROM public.public_room_events e
    WHERE (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
            BETWEEN p_start_date AND p_end_date
      AND (p_token IS NULL OR e.token = p_token)
      AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
      AND ( e.owner_id = ANY (public.current_visible_owner_ids())
         OR public.is_super_admin() OR public.is_admin() )
  ),
  sess AS (
    SELECT DISTINCT session_id FROM ev
    WHERE p_building_ids IS NULL OR building_id = ANY(p_building_ids)
  ),
  evf AS (SELECT e.* FROM ev e JOIN sess s ON s.session_id = e.session_id)
  SELECT
    evf.token,
    t.label,
    t.revoked,
    COUNT(DISTINCT evf.session_id),
    COUNT(DISTINCT evf.session_id),
    COUNT(*) FILTER (WHERE evf.event_type='room_open'),
    COUNT(*) FILTER (WHERE evf.event_type='contact_click'),
    COUNT(*) FILTER (WHERE evf.event_type='error'),
    COALESCE((
      SELECT AVG(mx) FROM (
        SELECT MAX(e2.duration_ms) AS mx FROM evf e2
        WHERE e2.token = evf.token
          AND e2.event_type='session' AND e2.duration_ms IS NOT NULL
        GROUP BY e2.session_id
      ) d
    ), 0)::numeric
  FROM evf
  LEFT JOIN public.public_room_share_tokens t ON t.token = evf.token
  GROUP BY evf.token, t.label, t.revoked
  ORDER BY COUNT(DISTINCT evf.session_id) DESC;
$$;








--
-- Name: pra_errors(date, date, text, uuid[], boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_errors(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS TABLE(created_at timestamp with time zone, token text, session_id text, kind text, message text, context text, user_agent text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e.created_at,
    e.token,
    e.session_id,
    e.metadata->>'kind',
    e.metadata->>'msg',
    e.metadata->>'where',
    e.metadata->>'ua'
  FROM public.public_room_events e
  WHERE e.event_type = 'error'
    AND (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
          BETWEEN p_start_date AND p_end_date
    AND (p_token IS NULL OR e.token = p_token)
    AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
    AND ( e.owner_id = ANY (public.current_visible_owner_ids())
       OR public.is_super_admin() OR public.is_admin() )
  ORDER BY e.created_at DESC
  LIMIT GREATEST(LEAST(p_limit, 500), 1);
$$;








--
-- Name: pra_funnel(date, date, text, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_funnel(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false) RETURNS TABLE(sessions bigint, sessions_impression bigint, sessions_opened_room bigint, sessions_contacted bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ev AS (
    SELECT e.* FROM public.public_room_events e
    WHERE (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
            BETWEEN p_start_date AND p_end_date
      AND (p_token IS NULL OR e.token = p_token)
      AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
      AND ( e.owner_id = ANY (public.current_visible_owner_ids())
         OR public.is_super_admin() OR public.is_admin() )
  ),
  sess AS (
    SELECT DISTINCT session_id FROM ev
    WHERE p_building_ids IS NULL OR building_id = ANY(p_building_ids)
  ),
  evf AS (SELECT e.* FROM ev e JOIN sess s ON s.session_id = e.session_id)
  SELECT
    COUNT(DISTINCT session_id),
    COUNT(DISTINCT session_id) FILTER (WHERE event_type='impression'),
    COUNT(DISTINCT session_id) FILTER (WHERE event_type='room_open'),
    COUNT(DISTINCT session_id) FILTER (WHERE event_type='contact_click')
  FROM evf;
$$;








--
-- Name: pra_summary(date, date, text, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_summary(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false) RETURNS TABLE(total_sessions bigint, total_views bigint, room_opens bigint, impressions bigint, contact_clicks bigint, favorites bigint, deposit_dialogs bigint, errors bigint, avg_session_ms numeric, unique_rooms_seen bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ev AS (
    SELECT e.* FROM public.public_room_events e
    WHERE (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
            BETWEEN p_start_date AND p_end_date
      AND (p_token IS NULL OR e.token = p_token)
      AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
      AND ( e.owner_id = ANY (public.current_visible_owner_ids())
         OR public.is_super_admin() OR public.is_admin() )
  ),
  sess AS (  -- lọc theo toà: phiên có ≥1 event chạm toà được chọn
    SELECT DISTINCT session_id FROM ev
    WHERE p_building_ids IS NULL OR building_id = ANY(p_building_ids)
  ),
  evf AS (
    SELECT e.* FROM ev e JOIN sess s ON s.session_id = e.session_id
  )
  SELECT
    COUNT(DISTINCT session_id),
    COUNT(DISTINCT session_id),
    COUNT(*) FILTER (WHERE event_type = 'room_open'),
    COUNT(*) FILTER (WHERE event_type = 'impression'),
    COUNT(*) FILTER (WHERE event_type = 'contact_click'),
    COUNT(*) FILTER (WHERE event_type = 'favorite'),
    COUNT(*) FILTER (WHERE event_type = 'deposit_dialog'),
    COUNT(*) FILTER (WHERE event_type = 'error'),
    COALESCE((
      SELECT AVG(mx) FROM (
        SELECT MAX(duration_ms) AS mx FROM evf
        WHERE event_type='session' AND duration_ms IS NOT NULL
        GROUP BY session_id
      ) d
    ), 0)::numeric,
    COUNT(DISTINCT room_id) FILTER (WHERE room_id IS NOT NULL)
  FROM evf;
$$;








--
-- Name: pra_timeseries(date, date, text, uuid[], boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_timeseries(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false, p_bucket text DEFAULT 'day'::text) RETURNS TABLE(bucket timestamp with time zone, sessions bigint, events bigint, room_opens bigint, contact_clicks bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ev AS (
    SELECT e.*,
           date_trunc(CASE WHEN p_bucket='hour' THEN 'hour' ELSE 'day' END,
                      (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')) AS b
    FROM public.public_room_events e
    WHERE (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
            BETWEEN p_start_date AND p_end_date
      AND (p_token IS NULL OR e.token = p_token)
      AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
      AND ( e.owner_id = ANY (public.current_visible_owner_ids())
         OR public.is_super_admin() OR public.is_admin() )
  ),
  sess AS (
    SELECT DISTINCT session_id FROM ev
    WHERE p_building_ids IS NULL OR building_id = ANY(p_building_ids)
  ),
  evf AS (SELECT e.* FROM ev e JOIN sess s ON s.session_id = e.session_id)
  SELECT
    b,
    COUNT(DISTINCT session_id),
    COUNT(*),
    COUNT(*) FILTER (WHERE event_type='room_open'),
    COUNT(*) FILTER (WHERE event_type='contact_click')
  FROM evf
  GROUP BY b
  ORDER BY b;
$$;








--
-- Name: pra_top_rooms(date, date, text, uuid[], boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pra_top_rooms(p_start_date date, p_end_date date, p_token text DEFAULT NULL::text, p_building_ids uuid[] DEFAULT NULL::uuid[], p_exclude_staff boolean DEFAULT false, p_limit integer DEFAULT 50) RETURNS TABLE(room_id uuid, room_name text, room_code text, building_name text, open_count bigint, impression_count bigint, total_dwell_ms numeric, avg_dwell_ms numeric, contact_clicks bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ev AS (
    SELECT e.* FROM public.public_room_events e
    WHERE (e.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
            BETWEEN p_start_date AND p_end_date
      AND e.room_id IS NOT NULL
      AND (p_token IS NULL OR e.token = p_token)
      AND (p_building_ids IS NULL OR e.building_id = ANY(p_building_ids))
      AND (NOT p_exclude_staff OR COALESCE(e.metadata->>'is_staff','') <> 'true')
      AND ( e.owner_id = ANY (public.current_visible_owner_ids())
         OR public.is_super_admin() OR public.is_admin() )
  )
  SELECT
    room_id,
    (array_agg(room_name     ORDER BY created_at DESC) FILTER (WHERE room_name     IS NOT NULL))[1],
    (array_agg(room_code     ORDER BY created_at DESC) FILTER (WHERE room_code     IS NOT NULL))[1],
    (array_agg(building_name ORDER BY created_at DESC) FILTER (WHERE building_name IS NOT NULL))[1],
    COUNT(*) FILTER (WHERE event_type='room_open'),
    COUNT(*) FILTER (WHERE event_type='impression'),
    COALESCE(SUM(dwell_ms) FILTER (WHERE event_type='room_open'), 0)::numeric,
    COALESCE(AVG(dwell_ms) FILTER (WHERE event_type='room_open' AND dwell_ms IS NOT NULL), 0)::numeric,
    COUNT(*) FILTER (WHERE event_type='contact_click')
  FROM ev
  GROUP BY room_id
  ORDER BY COUNT(*) FILTER (WHERE event_type='room_open') DESC,
           COUNT(*) FILTER (WHERE event_type='impression') DESC,
           SUM(dwell_ms) FILTER (WHERE event_type='room_open') DESC NULLS LAST
  LIMIT GREATEST(LEAST(p_limit, 200), 1);
$$;








--
-- Name: preview_maintenance_rule_v1(uuid, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_maintenance_rule_v1(p_building_id uuid, p_room_id uuid, p_service_kind text, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  SELECT b.organization_id INTO v_org FROM public.buildings b WHERE b.id = p_building_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='P0002'; END IF;
  IF NOT (public.can_access_building(p_building_id) OR public.ie_all_buildings_scope(p_building_id)
       OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền xem toà này' USING ERRCODE='42501';
  END IF;
  RETURN app_private.maintenance_rule_check_v1(
    v_org, p_building_id, p_room_id, p_service_kind,
    public.org_today_v1(v_org), p_amount);
END;
$$;








--
-- Name: preview_special_fees_v1(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_special_fees_v1(p_period text, p_building_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(building_id uuid, building_name text, fee_category text, amount numeric, provider_code text, status text, reason text, existing_code text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH k(kind) AS (
    VALUES ('tien_nha'),('dien'),('nuoc'),('internet'),('quan_ly'),
           ('ve_sinh'),('cong_an'),('rac'),('thang_may')
  ),
  p AS (SELECT to_date(p_period || '-01','YYYY-MM-DD') AS m0,
               (date_trunc('month', to_date(p_period || '-01','YYYY-MM-DD'))
                 + interval '1 month - 1 day')::date AS m1),
  b AS (
    SELECT bb.id, bb.name, bb.organization_id,
           COALESCE(bb.hidden_fixed_expenses,'{}') AS hidden
      FROM buildings bb
     WHERE bb.deleted_at IS NULL
       AND (p_building_ids IS NULL OR bb.id = ANY(p_building_ids))
       AND app_private.building_org_visible_v1(bb.id)
       AND (public.can_access_building(bb.id) OR public.ie_all_buildings_scope(bb.id)
         OR public.is_admin() OR public.is_super_admin())
  )
  SELECT b.id, b.name, k.kind,
         f.default_amount, f.provider_code,
         CASE
           WHEN k.kind = ANY(b.hidden)                       THEN 'KHÔNG_ÁP_DỤNG'
           WHEN cl.id IS NOT NULL                            THEN 'ĐÃ_SINH'
           WHEN ex.code IS NOT NULL                          THEN 'ĐÃ_CÓ_PHIẾU'
           WHEN COALESCE(f.default_amount,0) <= 0            THEN 'THIẾU_GIÁ'
           ELSE 'SẼ_SINH'
         END,
         CASE
           WHEN k.kind = ANY(b.hidden)            THEN 'Toà này đã tắt hạng mục'
           WHEN cl.id IS NOT NULL                 THEN 'Đã sinh phiếu ở lượt trước'
           WHEN ex.code IS NOT NULL               THEN 'Kỳ này đã có phiếu chi được duyệt'
           WHEN COALESCE(f.default_amount,0) <= 0 THEN 'Chưa khai giá ở Cài đặt → Phí cố định'
           ELSE NULL
         END,
         ex.code
    FROM b CROSS JOIN k CROSS JOIN p
    LEFT JOIN building_fee_accounts f
      ON f.building_id = b.id AND f.fee_category = k.kind AND f.deleted_at IS NULL
    LEFT JOIN special_fee_claims cl
      ON cl.organization_id = b.organization_id AND cl.building_id = b.id
     AND cl.fee_category = k.kind AND cl.period_month = p.m0 AND cl.status = 'GENERATED'
    -- Ô đã có phiếu chi ĐÃ DUYỆT: dùng đúng khoá ô của pay_period_fee.
    LEFT JOIN LATERAL (
      SELECT ie.code
        FROM income_expense_items it
        JOIN income_expense_types t ON t.id = it.income_expense_type_id AND t.type='expense'
                                   AND public.fee_type_matches(k.kind, t.category, t.name)
        JOIN income_expenses ie ON ie.id = it.income_expense_id
                               AND ie.building_id = b.id AND ie.type='EXPENSE'
                               -- SPECIAL_FEE_DUP_SEES_PENDING: đếm CẢ phiếu chờ duyệt.
                               -- Phiếu lệch giá nằm lại ở chờ duyệt; nếu ô này
                               -- vẫn báo SẼ_SINH thì máy đẻ thêm phiếu thứ hai
                               -- rồi tự duyệt nó — đo được 1.500.000đ ra két
                               -- cho một tháng giá công bố 500.000đ.
                               AND ie.approval_status <> 'CANCELLED' AND ie.deleted_at IS NULL
       WHERE it.start_date <= p.m1 AND it.end_date >= p.m0
       LIMIT 1) ex ON true
   ORDER BY b.name, k.kind;
$$;








--
-- Name: FUNCTION preview_special_fees_v1(p_period text, p_building_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_special_fees_v1(p_period text, p_building_ids uuid[]) IS 'Đợt 3: xem trước lượt sinh phiếu phí cố định của một kỳ. CHỈ ĐỌC, chạy được cả khi route OFF. Năm trạng thái: SẼ_SINH / ĐÃ_SINH (đã có claim) / ĐÃ_CÓ_PHIẾU (ô đã có phiếu duyệt) / KHÔNG_ÁP_DỤNG (toà tắt hạng mục) / THIẾU_GIÁ.';








--
-- Name: preview_termination_refund_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_termination_refund_v1(p_termination_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
DECLARE
  v_t   public.contract_terminations;
  v_org uuid;
  v_b   jsonb;
  v_real numeric; v_hist numeric; v_req numeric;
  v_status text; v_warn text;
BEGIN
  -- Thử theo id hồ sơ trước; không có thì hiểu là id HỢP ĐỒNG và lấy hồ sơ mới nhất.
  SELECT * INTO v_t FROM contract_terminations WHERE id = p_termination_id;
  IF NOT FOUND THEN
    SELECT * INTO v_t FROM contract_terminations
     WHERE contract_id = p_termination_id
     ORDER BY created_at DESC LIMIT 1;
  END IF;
  IF v_t.id IS NULL THEN
    RAISE EXCEPTION 'Hợp đồng này chưa có hồ sơ thanh lý — chưa tính được tiền hoàn.'
      USING ERRCODE='P0002';
  END IF;
  v_org := v_t.organization_id;

  IF NOT (EXISTS (SELECT 1 FROM organization_memberships m
                   WHERE m.organization_id=v_org AND m.user_id=auth.uid() AND m.status='ACTIVE')
          OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không thuộc tổ chức này' USING ERRCODE='42501';
  END IF;

  v_b := app_private.resolve_signed_contract_deposit_basis_v1(v_org, v_t.contract_id);
  v_real := (v_b->>'netHeld')::numeric;
  v_hist := (v_b->>'recognizedHistoricalIn')::numeric;
  v_req  := COALESCE(v_t.refund_amount, 0);

  -- "chưa từng vào két" nặng hơn "vượt cọc" — xét trước.
  IF v_req > 0 AND v_real <= 0 AND v_hist > 0 THEN
    v_status := 'CHUA_TUNG_VAO_KET';
    v_warn := format('Cọc %sđ của hợp đồng này chỉ được GHI NHẬN trên sổ ảo, chưa từng vào két thật. Hoàn %sđ tiền mặt là chi một khoản chưa hề thu.',
                     round(v_hist)::bigint, round(v_req)::bigint);
  ELSIF v_req > v_real THEN
    v_status := 'VUOT_COC_THAT';
    v_warn := format('Số hoàn %sđ LỚN HƠN cọc thật đang giữ %sđ (chênh %sđ).',
                     round(v_req)::bigint, round(v_real)::bigint, round(v_req - v_real)::bigint);
  ELSE
    v_status := 'OK';
  END IF;

  RETURN jsonb_build_object(
    'terminationId', v_t.id,
    'contractId', v_t.contract_id,
    'organizationId', v_org,
    'requestedAmount', v_req,
    'realHeld', v_real,
    'recognizedOnly', v_hist,
    'basisStatus', v_b->>'basisStatus',
    'basisFingerprint', v_b->>'fingerprint',
    'obligationStatus', v_status,
    'warning', v_warn,
    'basis', v_b);
END;
$$;








--
-- Name: FUNCTION preview_termination_refund_v1(p_termination_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_termination_refund_v1(p_termination_id uuid) IS 'Đợt 7: xem trước nghĩa vụ hoàn — đối chiếu số nhập tay ở hồ sơ thanh lý với cọc THẬT đã thu. CHỈ ĐỌC. Ba trạng thái: OK / VUOT_COC_THAT / CHUA_TUNG_VAO_KET (nặng nhất — không đồng nào từng vào két nên hoàn bao nhiêu cũng là chi khoản chưa thu).';








--
-- Name: profit_close_preview_v2(uuid, date, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profit_close_preview_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[] DEFAULT NULL::uuid[], p_adjustments jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_building_ids uuid[] := p_building_ids;
  v_permission text := 'shareholder_profit.view';
  v_preview jsonb;
BEGIN
  IF p_period_month IS NULL
     OR p_period_month <> date_trunc('month', p_period_month)::date THEN
    RAISE EXCEPTION 'period_month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.authorize_v2(
       'shareholder_profit.view', p_organization_id, 'ORGANIZATION', NULL
     )
     AND public.authorize_v2(
       'shareholder_profit.lock', p_organization_id, 'ORGANIZATION', NULL
     ) THEN
    v_permission := 'shareholder_profit.lock';
  END IF;

  IF v_building_ids IS NULL THEN
    SELECT array_agg(b.id ORDER BY b.id)
    INTO v_building_ids
    FROM public.buildings b
    WHERE b.organization_id = p_organization_id
      AND b.deleted_at IS NULL
      AND b.is_virtual = false;
  END IF;

  v_preview := public._profit_close_preview_core_v2(
    p_organization_id, p_period_month, v_building_ids,
    p_adjustments, v_permission, false
  );
  RETURN public._profit_enrich_unallocated_v3(v_preview, p_adjustments);
END
$$;








--
-- Name: FUNCTION profit_close_preview_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[], p_adjustments jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.profit_close_preview_v2(p_organization_id uuid, p_period_month date, p_building_ids uuid[], p_adjustments jsonb) IS 'Returns {algorithm_version,organization_id,period_month,source_hash,source_captured_at,source_snapshot,buildings[],totals}. Each building includes canonical totals, explicit adjustment, manager/shareholder allocations, and current_* snapshot/stale fields.';








--
-- Name: profit_close_scopes_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profit_close_scopes_v2() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_super_admin boolean;
  v_organizations jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  v_is_super_admin := public.is_super_admin();

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'organization_id', scoped.organization_id,
      'organization_name', scoped.organization_name,
      'organization_slug', scoped.organization_slug,
      'can_lock', scoped.can_lock,
      'can_unlock', scoped.can_unlock
    ) ORDER BY scoped.organization_name, scoped.organization_id
  ), '[]'::jsonb)
  INTO v_organizations
  FROM (
    SELECT
      o.id AS organization_id,
      o.name AS organization_name,
      o.slug AS organization_slug,
      (
        v_is_super_admin OR public.authorize_v2(
          'shareholder_profit.lock', o.id, 'ORGANIZATION', NULL
        )
      ) AS can_lock,
      (
        v_is_super_admin OR public.authorize_v2(
          'shareholder_profit.unlock', o.id, 'ORGANIZATION', NULL
        )
      ) AS can_unlock
    FROM public.organizations o
    JOIN public.organization_memberships m
      ON m.organization_id = o.id
     AND m.user_id = v_actor
     AND m.status = 'ACTIVE'
     AND m.valid_from <= clock_timestamp()
     AND (m.valid_to IS NULL OR m.valid_to > clock_timestamp())
    WHERE o.status = 'ACTIVE'
  ) scoped
  WHERE scoped.can_lock OR scoped.can_unlock;

  RETURN jsonb_build_object('organizations', v_organizations);
END
$$;








--
-- Name: FUNCTION profit_close_scopes_v2(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.profit_close_scopes_v2() IS 'Lists active organizations where the caller can lock or unlock profit snapshots.';








--
-- Name: profit_close_state_v2(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profit_close_state_v2(p_organization_id uuid, p_period_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_can_lock boolean;
  v_can_unlock boolean;
  v_state jsonb;
BEGIN
  IF p_period_month IS NULL
     OR p_period_month <> date_trunc('month', p_period_month)::date THEN
    RAISE EXCEPTION 'period_month must be the first day of a month'
      USING ERRCODE = '22023';
  END IF;

  v_can_lock := public.is_super_admin() OR public.authorize_v2(
    'shareholder_profit.lock', p_organization_id, 'ORGANIZATION', NULL
  );
  v_can_unlock := public.is_super_admin() OR public.authorize_v2(
    'shareholder_profit.unlock', p_organization_id, 'ORGANIZATION', NULL
  );

  IF v_can_lock THEN
    PERFORM public._profit_assert_authorized_v2(
      p_organization_id, 'shareholder_profit.lock'
    );
  ELSE
    PERFORM public._profit_assert_authorized_v2(
      p_organization_id, 'shareholder_profit.unlock'
    );
  END IF;

  v_state := public._profit_current_state_v2(p_organization_id, p_period_month);
  RETURN public._profit_enrich_state_v3(
    (v_state - 'before' - 'building_ids') || jsonb_build_object(
      'can_lock', v_can_lock,
      'can_unlock', v_can_unlock
    )
  );
END
$$;








