--
-- Name: propose_cashbook_closing_v1(uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_cashbook_closing_v1(p_cashbook uuid, p_counted_balance numeric, p_confirmer uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_membership uuid;
  v_today date := public.org_today_v1(NULL);
  v_system numeric;
  v_blockers text;
  v_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  IF p_counted_balance = 'NaN'::numeric THEN
    RAISE EXCEPTION 'Số tiền đếm không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF p_counted_balance IS NULL THEN
    RAISE EXCEPTION 'Phải nhập số tiền thực đếm' USING ERRCODE = '22023';
  END IF;
  IF p_confirmer IS NULL OR p_confirmer = v_actor THEN
    RAISE EXCEPTION 'Phải chọn NGƯỜI KHÁC để xác nhận nhận bàn giao — chốt sổ cần cả hai bên.'
      USING ERRCODE = '22023';
  END IF;

  -- FOR UPDATE trên sổ: đua với trigger khoá của Đợt 3 (nó giữ FOR KEY SHARE
  -- khi ghi phiếu), nên phiếu đang chèn dở sẽ đụng độ thật thay vì lọt vào kỳ
  -- vừa bị đóng băng.
  SELECT a.organization_id INTO v_org
  FROM public.accounts a WHERE a.id = p_cashbook AND a.deleted_at IS NULL FOR UPDATE;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy sổ quỹ' USING ERRCODE = '42501'; END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);

  SELECT m.id INTO v_membership FROM public.organization_memberships m
   WHERE m.user_id = v_actor AND m.organization_id = v_org AND m.status = 'ACTIVE' LIMIT 1;

  IF NOT public.is_super_admin() THEN
    IF NOT COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
         v_actor, v_org, 'cashbooks.close', NULL, p_cashbook)), false) THEN
      RAISE EXCEPTION 'Không có quyền đề nghị chốt sổ quỹ này' USING ERRCODE = '42501';
    END IF;
    -- Người ĐANG GIỮ sổ mới đếm được tiền trong két.
    PERFORM app_private.assert_cashbook_access_v2(v_org, p_cashbook, 'CUSTODIAN', v_membership);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m
     WHERE m.user_id = p_confirmer AND m.organization_id = v_org AND m.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Người xác nhận không thuộc tổ chức này' USING ERRCODE = '22023';
  END IF;
  IF NOT COALESCE((SELECT allowed FROM app_private.authorize_tenant_action_v3(
       p_confirmer, v_org, 'cashbooks.close_confirm', NULL, p_cashbook)), false) THEN
    RAISE EXCEPTION 'Người được chọn không có quyền xác nhận nhận bàn giao sổ này'
      USING ERRCODE = '42501';
  END IF;

  SELECT string_agg(b.detail, ' | ') INTO v_blockers
  FROM public.cashbook_closing_blockers_v1(p_cashbook) b WHERE b.blocking;
  IF v_blockers IS NOT NULL THEN
    RAISE EXCEPTION 'Chưa chốt được: %', v_blockers USING ERRCODE = '55000';
  END IF;

  -- closed_through ÉP = HÔM NAY. Đếm tiền là đếm BÂY GIỜ; đem so với số dư một
  -- ngày quá khứ thì phần chênh chính là giao dịch ở giữa, và hệ thống sẽ ghi
  -- nhầm thành thừa/thiếu quỹ rồi khoá vĩnh viễn con số sai đó.
  v_system := app_private.cashbook_balance_as_of_v1(p_cashbook, v_today);

  INSERT INTO app_private.cashbook_closure_requests
    (organization_id, cashbook_id, closed_through, counted_balance, system_balance,
     note, proposed_by, proposed_by_membership, confirmer_user_id)
  VALUES
    (v_org, p_cashbook, v_today, round(p_counted_balance, 2), round(v_system, 2),
     nullif(btrim(COALESCE(p_note, '')), ''), v_actor, v_membership, p_confirmer)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'request_id', v_id,
    'cashbook_id', p_cashbook,
    'closed_through', v_today,
    'counted_balance', round(p_counted_balance, 2),
    'system_balance', round(v_system, 2),
    'difference', round(p_counted_balance - v_system, 2),
    'basis', 'POSTING_TRUTH_BY_POSTED_ON',
    'status', 'PENDING'
  );
END
$$;








--
-- Name: propose_reconciliation(uuid, date, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_reconciliation(p_account_id uuid, p_as_of date, p_counted_balance numeric, p_counterparty_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner    uuid;
  v_sys      numeric;
  v_status   text;
  v_cp       uuid;      -- counterparty thực sự lưu
  v_id       uuid;
  v_is_boss  boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;

  SELECT user_id INTO v_owner FROM accounts WHERE id = p_account_id AND deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'Không tìm thấy sổ quỹ'; END IF;

  -- Quyền đối soát: chủ sổ / super admin / đồng đội của chủ sổ.
  IF NOT (v_owner = auth.uid() OR public.is_super_admin() OR public.same_team(v_owner)) THEN
    RAISE EXCEPTION 'Bạn không có quyền đối soát sổ này';
  END IF;

  -- Số dư hệ thống TÍNH ĐẾN NGÀY as_of (khớp nhãn as_of_date). Bằng
  -- current_amount khi as_of = hôm nay. Bao gồm cả điều chỉnh thối/làm tròn.
  SELECT COALESCE(a.initial_amount, 0)
       + COALESCE((SELECT sum(ie.total_amount) FROM income_expenses ie
                    WHERE ie.account_id = a.id AND ie.type = 'INCOME'
                      AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
                      AND ie.voucher_date <= p_as_of), 0)
       - COALESCE((SELECT sum(ie.total_amount) FROM income_expenses ie
                    WHERE ie.account_id = a.id AND ie.type = 'EXPENSE'
                      AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
                      AND ie.voucher_date <= p_as_of), 0)
       + COALESCE((SELECT sum(ie.change_amount) FROM income_expenses ie
                    WHERE ie.change_account_id = a.id
                      AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
                      AND ie.voucher_date <= p_as_of), 0)
       + COALESCE((SELECT sum(ie.rounding_amount) FROM income_expenses ie
                    WHERE ie.rounding_account_id = a.id
                      AND ie.approval_status = 'APPROVED' AND ie.deleted_at IS NULL
                      AND ie.voucher_date <= p_as_of), 0)
    INTO v_sys
    FROM accounts a WHERE a.id = p_account_id;
  v_sys := COALESCE(v_sys, 0);

  v_is_boss := (v_owner = auth.uid() OR public.is_super_admin());

  -- Xác định trạng thái + người xác nhận:
  IF p_counterparty_id IS NOT NULL AND p_counterparty_id <> auth.uid() THEN
    v_status := 'PENDING'; v_cp := p_counterparty_id;              -- có người đối ứng rõ ràng
  ELSIF v_is_boss THEN
    v_status := 'CONFIRMED'; v_cp := NULL;                         -- chủ/super tự chốt
  ELSE
    v_status := 'PENDING'; v_cp := v_owner;                        -- đồng đội đề xuất → CHỦ xác nhận
  END IF;

  INSERT INTO cashbook_reconciliations
    (account_id, as_of_date, system_balance, counted_balance, diff, status, note,
     proposed_by, counterparty_id, confirmed_by, confirmed_at)
  VALUES
    (p_account_id, p_as_of, v_sys, COALESCE(p_counted_balance, v_sys),
     COALESCE(p_counted_balance, v_sys) - v_sys, v_status, NULLIF(btrim(p_note), ''),
     auth.uid(), v_cp,
     CASE WHEN v_status = 'CONFIRMED' THEN auth.uid() END,
     CASE WHEN v_status = 'CONFIRMED' THEN now() END)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'status', v_status,
                            'system_balance', v_sys,
                            'diff', COALESCE(p_counted_balance, v_sys) - v_sys);
END;
$$;








--
-- Name: public_v5_effective_milestones(jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_v5_effective_milestones(p_miles jsonb, p_deltas jsonb, p_n integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_out JSONB := '[]'::jsonb;
  v_cut NUMERIC := 0;
  i INT;
  v_m TEXT; v_delta NUMERIC;
BEGIN
  FOR i IN 0 .. jsonb_array_length(p_miles) - 1 LOOP
    v_m := p_miles->>i; v_delta := (p_deltas->>i)::numeric;
    IF v_m = 'full_month' THEN
      CONTINUE;
    ELSIF v_m::int <= p_n THEN
      v_out := v_out || jsonb_build_array(jsonb_build_object('milestone', v_m::int, 'delta', v_delta));
    ELSE
      v_cut := v_cut + v_delta;
    END IF;
  END LOOP;
  -- full_month luôn còn, delta dồn phần bị cắt
  FOR i IN 0 .. jsonb_array_length(p_miles) - 1 LOOP
    IF p_miles->>i = 'full_month' THEN
      v_out := v_out || jsonb_build_array(jsonb_build_object('milestone', 'full_month',
                                                             'delta', (p_deltas->>i)::numeric + v_cut));
    END IF;
  END LOOP;
  RETURN v_out;
END; $$;








--
-- Name: recompute_contract_deposit_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_contract_deposit_paid(p_contract_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric(15,2) := 0;
  v_count_any integer := 0;
BEGIN
  IF p_contract_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COUNT(*)
    INTO v_count_any
    FROM public.income_expenses voucher
    JOIN public.income_expense_items item
      ON item.income_expense_id = voucher.id
     AND item.accounting_class = 'DEPOSIT'
    LEFT JOIN public.contract_deposit_links link_row
      ON link_row.income_expense_id = voucher.id
     AND link_row.contract_id = p_contract_id
   WHERE voucher.contract_id = p_contract_id OR link_row.id IS NOT NULL;

  IF v_count_any = 0 THEN
    RETURN;
  END IF;

  v_total := public.contract_deposit_paid_derived(p_contract_id);

  UPDATE public.contracts
     SET deposit_paid = v_total,
         updated_at = now()
   WHERE id = p_contract_id
     AND deleted_at IS NULL
     AND deposit_paid IS DISTINCT FROM v_total;
END;
$$;








--
-- Name: recompute_ie_business_result(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_ie_business_result(p_ie_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_override       boolean;
  v_total          numeric;
  v_item_count     integer;
  v_pnl_sum        numeric;
  v_has_deposit    boolean;
  v_has_restricted boolean;
  v_result         boolean;
  v_kqkd           numeric;
BEGIN
  SELECT business_result_accounting, COALESCE(total_amount, 0)
    INTO v_override, v_total
    FROM public.income_expenses
   WHERE id = p_ie_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COALESCE(SUM(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'PNL'), 0),
    COALESCE(bool_or(item.accounting_class = 'DEPOSIT'), false),
    COALESCE(bool_or(type_row.is_restricted), false)
  INTO v_item_count, v_pnl_sum, v_has_deposit, v_has_restricted
  FROM public.income_expense_items item
  LEFT JOIN public.income_expense_types type_row
    ON type_row.id = item.income_expense_type_id
  WHERE item.income_expense_id = p_ie_id;

  v_kqkd := CASE
    WHEN v_override IS TRUE THEN v_total
    WHEN v_override IS FALSE THEN 0
    WHEN v_item_count = 0 THEN v_total
    ELSE GREATEST(LEAST(v_pnl_sum, v_total), 0)
  END;
  v_result := v_kqkd > 0;

  UPDATE public.income_expenses
     SET counts_in_business_result = v_result,
         has_restricted_item = v_has_restricted,
         kqkd_amount = v_kqkd
   WHERE id = p_ie_id
     AND (
       counts_in_business_result IS DISTINCT FROM v_result
       OR has_restricted_item IS DISTINCT FROM v_has_restricted
       OR kqkd_amount IS DISTINCT FROM v_kqkd
     );
END;
$$;








--
-- Name: recompute_invoice_after_item_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_after_item_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice_id UUID;
BEGIN
  SELECT invoice_id INTO v_invoice_id
  FROM income_expenses
  WHERE id = COALESCE(NEW.income_expense_id, OLD.income_expense_id);
  IF v_invoice_id IS NOT NULL THEN
    PERFORM recompute_invoice_for_id(v_invoice_id);
  END IF;
  RETURN NULL;
END;
$$;








--
-- Name: recompute_invoice_after_payment_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_after_payment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM recompute_invoice_for_id(COALESCE(NEW.invoice_id, OLD.invoice_id));
  RETURN NULL;
END;
$$;








--
-- Name: recompute_invoice_after_voucher_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_after_voucher_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.invoice_id IS NOT NULL THEN
      PERFORM recompute_invoice_for_id(OLD.invoice_id);
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.invoice_id IS NOT NULL THEN
    PERFORM recompute_invoice_for_id(NEW.invoice_id);
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.invoice_id IS DISTINCT FROM NEW.invoice_id
     AND OLD.invoice_id IS NOT NULL THEN
    PERFORM recompute_invoice_for_id(OLD.invoice_id);
  END IF;
  RETURN NULL;
END;
$$;








--
-- Name: recompute_invoice_for_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_for_id(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric(15,2);
  v_paid numeric(15,2);
  v_rounding numeric(15,2);
  v_legacy_rounding numeric(15,2);
  v_legacy_refunded numeric(15,2);
  v_settlement_refunded numeric(15,2);
  v_has_v5_payment boolean;
  v_existing_status public.invoice_status;
  v_status public.invoice_status;
  v_paid_date date;
  v_due_date date;
  v_carried_raw numeric(15,2);
  v_carried numeric(15,2);
BEGIN
  IF p_invoice_id IS NULL THEN
    RETURN;
  END IF;

  SELECT total_amount, status, due_date
    INTO v_total, v_existing_status, v_due_date
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(sum(amount), 0), max(payment_date),
         COALESCE(sum(rounding_amount), 0),
         COALESCE(bool_or(collection_id IS NOT NULL), false)
    INTO v_paid, v_paid_date, v_rounding, v_has_v5_payment
  FROM public.payments
  WHERE invoice_id = p_invoice_id
    AND reversed_at IS NULL;

  -- Legacy writers stored cash change as a separate expense while keeping the
  -- gross amount in payments. V5 payments already store only the applied
  -- amount, so subtract change only from pre-collection vouchers.
  SELECT COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity)), 0)
    INTO v_legacy_refunded
  FROM public.income_expenses voucher
  JOIN public.income_expense_items item
    ON item.income_expense_id = voucher.id
  JOIN public.income_expense_types type_row
    ON type_row.id = item.income_expense_type_id
  WHERE voucher.invoice_id = p_invoice_id
    AND voucher.payment_collection_id IS NULL
    AND voucher.type = 'EXPENSE'
    AND voucher.approval_status = 'APPROVED'
    AND voucher.deleted_at IS NULL
    AND lower(btrim(type_row.name)) = 'tiền thối';

  v_paid := v_paid - v_legacy_refunded;

  SELECT COALESCE(sum(voucher.rounding_amount), 0)
    INTO v_legacy_rounding
  FROM public.income_expenses voucher
  WHERE voucher.invoice_id = p_invoice_id
    AND voucher.payment_collection_id IS NULL
    AND voucher.type = 'INCOME'
    AND voucher.approval_status = 'APPROVED'
    AND voucher.deleted_at IS NULL;

  SELECT COALESCE(sum(voucher.total_amount), 0)
    INTO v_settlement_refunded
  FROM public.income_expenses voucher
  WHERE voucher.invoice_id = p_invoice_id
    AND voucher.type = 'EXPENSE'
    AND voucher.approval_status = 'APPROVED'
    AND voucher.deleted_at IS NULL
    AND voucher.notes LIKE '[Hoàn trả thanh lý]%';

  v_paid := v_paid - v_settlement_refunded;
  v_rounding := v_rounding + v_legacy_rounding;

  IF v_existing_status = 'CANCELLED' THEN
    UPDATE public.invoices
       SET paid_amount = v_paid
     WHERE id = p_invoice_id;
    RETURN;
  END IF;
  -- [B1] Phan cong no da duoc hoa don SAU ganh ho (previous_debt_sources).
  -- Truoc day settle_previous_debt_sources ghi THANG paid_amount/status len hoa
  -- don nguon ma khong tao dong payments; ham nay lai DAN XUAT paid_amount tu
  -- payments, nen moi lan recompute chay lai la khoan no da tra SONG DAY.
  -- Nay suy ra tai cho: nguon su that duy nhat van la ham nay.
  --
  -- Dat SAU nhanh CANCELLED: hoa don da huy khong phai cong no; cong vao do se
  -- day paid_amount vuot total va de ra khoan "thu thua" ao.
  SELECT COALESCE(sum((src->>'amount')::numeric), 0)
    INTO v_carried_raw
  FROM public.invoices carrier
  CROSS JOIN LATERAL jsonb_array_elements(carrier.previous_debt_sources) AS src
  WHERE carrier.deleted_at IS NULL
    AND carrier.status = 'PAID'
    AND carrier.id <> p_invoice_id
    AND jsonb_typeof(carrier.previous_debt_sources) = 'array'
    AND src->>'type' = 'invoice'
    AND NULLIF(src->>'id', '') IS NOT NULL
    AND (src->>'id')::uuid = p_invoice_id;

  -- CHAN TREN bat buoc: so trong previous_debt_sources[].amount la ANH CHUP du
  -- no luc phat hanh hoa don ganh. Neu sau do khach tra them truc tiep vao hoa
  -- don nguon, cong thang se vuot total va tao hoan tien ao. Phan suy ra chi
  -- duoc LAP DAY khoang thieu, khong bao gio vuot.
  -- COALESCE la load-bearing: LEAST(NULL, gap) trong Postgres tra ve gap.
  v_carried := LEAST(COALESCE(v_carried_raw, 0), GREATEST(v_total - v_paid, 0));
  v_paid := v_paid + v_carried;

  IF v_total > 0 THEN
    IF v_paid >= v_total OR v_paid + v_rounding >= v_total
       OR (
         NOT v_has_v5_payment
         AND v_paid > 0
         AND v_total - v_paid > 0
         AND v_total - v_paid < 10000
       ) THEN
      v_status := 'PAID';
    ELSIF v_paid > 0 AND v_due_date < public.org_today_v1(NULL) THEN
      v_status := 'OVERDUE';
      v_paid_date := NULL;
    ELSIF v_paid > 0 THEN
      v_status := 'PARTIAL_PAID';
      v_paid_date := NULL;
    ELSIF v_due_date < public.org_today_v1(NULL) THEN
      v_status := 'OVERDUE';
      v_paid_date := NULL;
    ELSE
      v_status := 'APPROVED';
      v_paid_date := NULL;
    END IF;
  ELSIF v_total < 0 THEN
    IF v_paid <= v_total THEN
      v_status := 'PAID';
    ELSIF v_paid < 0 AND v_due_date < public.org_today_v1(NULL) THEN
      v_status := 'OVERDUE';
      v_paid_date := NULL;
    ELSIF v_paid < 0 THEN
      v_status := 'PARTIAL_PAID';
      v_paid_date := NULL;
    ELSIF v_due_date < public.org_today_v1(NULL) THEN
      v_status := 'OVERDUE';
      v_paid_date := NULL;
    ELSE
      v_status := 'APPROVED';
      v_paid_date := NULL;
    END IF;
  ELSE
    v_status := CASE
      WHEN v_paid <> 0 THEN 'PAID'::public.invoice_status
      ELSE 'APPROVED'::public.invoice_status
    END;
    IF v_paid = 0 THEN
      v_paid_date := NULL;
    END IF;
  END IF;

  UPDATE public.invoices
     SET paid_amount = v_paid,
         status = v_status,
         paid_date = v_paid_date,
         updated_at = now()
   WHERE id = p_invoice_id;
END;
$$;








--
-- Name: recompute_material_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_material_stock(_material_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_in NUMERIC := 0;
  v_in_cost NUMERIC := 0;
  v_out NUMERIC := 0;
  v_adj_in NUMERIC := 0;
  v_adj_out NUMERIC := 0;
  v_avg NUMERIC := 0;
BEGIN
  SELECT COALESCE(SUM(quantity),0), COALESCE(SUM(line_total),0)
    INTO v_in, v_in_cost
    FROM material_purchase_items WHERE material_id = _material_id;

  SELECT COALESCE(SUM(quantity),0) INTO v_out
    FROM material_usage_items WHERE material_id = _material_id;

  SELECT COALESCE(SUM(ai.quantity),0) INTO v_adj_in
    FROM material_adjustment_items ai
    JOIN material_adjustments a ON a.id = ai.adjustment_id
    WHERE ai.material_id = _material_id AND a.type = 'IN';

  SELECT COALESCE(SUM(ai.quantity),0) INTO v_adj_out
    FROM material_adjustment_items ai
    JOIN material_adjustments a ON a.id = ai.adjustment_id
    WHERE ai.material_id = _material_id AND a.type = 'OUT';

  IF v_in > 0 THEN
    v_avg := v_in_cost / v_in;
  ELSE
    v_avg := 0;
  END IF;

  UPDATE materials
  SET on_hand = v_in - v_out + v_adj_in - v_adj_out,
      avg_unit_cost = v_avg,
      updated_at = now()
  WHERE id = _material_id;
END;
$$;








--
-- Name: FUNCTION recompute_material_stock(_material_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recompute_material_stock(_material_id uuid) IS 'Tính lại on_hand + avg_unit_cost (MAC) cho 1 material từ tất cả movement. Gọi bởi trigger AFTER trên *_items.';








--
-- Name: recompute_room_reservation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_room_reservation(p_room_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status      text;
  v_has_active  boolean;
  v_has_holding boolean;
BEGIN
  IF p_room_id IS NULL THEN
    RETURN;
  END IF;

  SELECT status INTO v_status
  FROM rooms
  WHERE id = p_room_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- HĐ đang hiệu lực sở hữu OCCUPIED → reconcile cọc không can thiệp.
  SELECT EXISTS (
    SELECT 1 FROM contracts c
    WHERE c.room_id = p_room_id
      AND c.deleted_at IS NULL
      AND c.status IN ('ACTIVE','EXTENDED')
  ) INTO v_has_active;
  IF v_has_active THEN
    RETURN;
  END IF;

  v_has_holding := public.room_has_holding_deposit(p_room_id);

  IF v_status = 'AVAILABLE' AND v_has_holding THEN
    UPDATE rooms SET status = 'RESERVED', updated_at = NOW() WHERE id = p_room_id;
  ELSIF v_status = 'RESERVED' AND NOT v_has_holding THEN
    UPDATE rooms SET status = 'AVAILABLE', updated_at = NOW() WHERE id = p_room_id;
  END IF;
END;
$$;








--
-- Name: FUNCTION recompute_room_reservation(p_room_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recompute_room_reservation(p_room_id uuid) IS 'Đồng bộ cờ "cọc giữ chỗ": AVAILABLE<->RESERVED theo việc phòng có cọc chưa-HĐ hay
không. Bỏ qua nếu phòng đang có HĐ hiệu lực (OCCUPIED do HĐ sở hữu). Không đụng
MAINTENANCE/UNAVAILABLE. Idempotent — gọi lại nhiều lần an toàn.';








--
-- Name: record_invoice_collection_v5(uuid, date, jsonb, text, boolean, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_collection_v5(p_invoice_id uuid, p_collection_date date, p_tenders jsonb, p_overpay_action text, p_allow_rounding boolean, p_notes text, p_receipt_image_url text, p_expected_paid_amount numeric, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_collector_membership uuid;
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_invoice public.invoices%ROWTYPE;
  v_org uuid;
  v_owner uuid;
  v_authz boolean;
  v_route text;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_collection_id uuid;
  v_tender jsonb;
  v_tender_id uuid;
  v_payment_id uuid;
  v_voucher_id uuid;
  v_item_id uuid;
  v_credit_lot_id uuid;
  v_credit_tender_count integer;
  v_excess_id uuid;
  v_account_id uuid;
  v_change_account_id uuid;
  v_rounding_account_id uuid;
  v_method public.payment_method;
  v_gross numeric;
  v_gross_total numeric := 0;
  v_tm_total numeric := 0;
  v_remaining numeric;
  v_applied_total numeric;
  v_change_total numeric := 0;
  v_credit_total numeric := 0;
  v_rounding_total numeric := 0;
  v_retained_total numeric;
  v_remaining_apply numeric;
  v_change_left numeric;
  v_credit_left numeric;
  v_line_left numeric;
  v_line_change numeric;
  v_line_credit numeric;
  v_line_retained numeric;
  v_line_applied numeric;
  v_line_revenue numeric;
  v_line_internal numeric;
  v_line_deposit numeric;
  v_later_tm_total numeric;
  v_later_gross_total numeric;
  v_revenue_due numeric;
  v_internal_due numeric := 0;
  v_deposit_due numeric := 0;
  v_revenue_covered numeric := 0;
  v_internal_covered numeric := 0;
  v_deposit_covered numeric := 0;
  v_projected_revenue numeric;
  v_projected_internal numeric;
  v_projected_deposit numeric;
  v_projection_left numeric;
  v_idx integer := 0;
  v_last_tm_idx integer := -1;
  v_last_line_idx integer;
  v_revenue_type_id uuid;
  v_deposit_type_id uuid;
  v_credit_type_id uuid;
  v_response jsonb;
  v_tender_results jsonb := '[]'::jsonb;
  v_creator_name text;
  v_rounding_target_account uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'
      USING ERRCODE = '22023';
  END IF;
  IF p_collection_date IS NULL OR jsonb_typeof(p_tenders) <> 'array'
     OR jsonb_array_length(p_tenders) = 0 THEN
    RAISE EXCEPTION 'Ngày thu hoặc danh sách phương thức không hợp lệ'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy hóa đơn' USING ERRCODE = '42501';
  END IF;

  SELECT building_row.organization_id, v_invoice.user_id
    INTO v_org, v_owner
  FROM public.buildings building_row
  JOIN public.organizations org_row
    ON org_row.id = building_row.organization_id AND org_row.status = 'ACTIVE'
  WHERE building_row.id = v_invoice.building_id
    AND building_row.deleted_at IS NULL
  FOR SHARE OF building_row, org_row;
  IF v_org IS NULL OR v_invoice.organization_id <> v_org THEN
    RAISE EXCEPTION 'Hóa đơn không thuộc tổ chức hợp lệ' USING ERRCODE = '42501';
  END IF;

  -- Membership của người thu — dùng cho chốt possession trên sổ nhận tiền.
  SELECT m.id INTO v_collector_membership
  FROM public.organization_memberships m
  WHERE m.user_id = v_actor AND m.organization_id = v_org AND m.status = 'ACTIVE'
  LIMIT 1;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.collect', v_invoice.building_id, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Không có quyền thu tiền hóa đơn' USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'invoice_id', p_invoice_id,
    'collection_date', p_collection_date,
    'tenders', p_tenders,
    'overpay_action', upper(COALESCE(p_overpay_action, 'REJECT')),
    'allow_rounding', COALESCE(p_allow_rounding, false),
    'notes', p_notes,
    'receipt_image_url', p_receipt_image_url
  )::text);

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash
  ) VALUES (
    v_org, 'invoice.collection.v5', p_invoice_id::text, v_actor, v_key, v_hash
  ) ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
    DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'invoice.collection.v5'
    AND operation_row.subject_scope = p_invoice_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key đã dùng với nội dung khác' USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM app_private.canonical_write_operations compat_operation
    WHERE compat_operation.organization_id = v_org
      AND compat_operation.operation = 'invoice.collection.compat.v4'
      AND compat_operation.subject_scope = p_invoice_id::text
      AND compat_operation.actor_id = v_actor
      AND compat_operation.idempotency_key = v_key
      AND compat_operation.completed_at IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.income_expenses legacy_voucher
    WHERE legacy_voucher.organization_id = v_org
      AND legacy_voucher.idempotency_key = v_key
      AND legacy_voucher.payment_collection_id IS NULL
      AND legacy_voucher.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'idempotency_key đã hoàn tất ở đường payment tương thích'
      USING ERRCODE = '23505';
  END IF;

  v_route := app_private.evaluate_feature_route('invoice.collection.v5', v_org);
  IF v_route = 'FROZEN' THEN
    RAISE EXCEPTION 'Writer invoice.collection.v5 đang bị đóng băng'
      USING ERRCODE = '55000';
  ELSIF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Writer invoice.collection.v5 chưa bật' USING ERRCODE = '55000';
  END IF;

  IF v_invoice.status NOT IN ('APPROVED', 'PARTIAL_PAID', 'OVERDUE') THEN
    RAISE EXCEPTION 'Trạng thái hóa đơn không cho phép thu tiền: %', v_invoice.status
      USING ERRCODE = '55000';
  END IF;
  IF p_expected_paid_amount IS NULL
     OR p_expected_paid_amount = 'NaN'::numeric
     OR abs(COALESCE(v_invoice.paid_amount, 0) - p_expected_paid_amount) >= 0.01 THEN
    RAISE EXCEPTION 'Số đã thu vừa thay đổi; vui lòng tải lại hóa đơn'
      USING ERRCODE = '40001';
  END IF;

  FOR v_tender IN SELECT value FROM jsonb_array_elements(p_tenders) LOOP
    v_gross := COALESCE((v_tender->>'gross_amount')::numeric, 0);
    IF v_gross = 'NaN'::numeric
       OR v_gross <= 0 OR round(v_gross, 2) <> v_gross THEN
      RAISE EXCEPTION 'Mỗi dòng thanh toán phải lớn hơn 0 và tối đa 2 số lẻ'
        USING ERRCODE = '22023';
    END IF;
    v_method := (v_tender->>'payment_method')::public.payment_method;
    v_account_id := NULLIF(v_tender->>'account_id', '')::uuid;
    IF v_account_id IS NULL THEN
      RAISE EXCEPTION 'Mỗi dòng thanh toán phải có sổ quỹ' USING ERRCODE = '22023';
    END IF;

    PERFORM 1 FROM public.accounts account_row
    WHERE account_row.id = v_account_id
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sổ nhận tiền phải là sổ tiền thật của tổ chức'
        USING ERRCODE = '42501';
    END IF;
    SELECT allowed INTO v_authz
    FROM app_private.authorize_tenant_action_v3(
      v_actor, v_org, 'thu_tien.collect', v_invoice.building_id, v_account_id
    );
    IF NOT COALESCE(v_authz, false) THEN
      RAISE EXCEPTION 'Không có quyền ghi vào một sổ quỹ đã chọn' USING ERRCODE = '42501';
    END IF;

    -- CHỐT POSSESSION TRÊN SỔ NHẬN TIỀN (02/08/2026).
    -- 'thu_tien.collect' khai requires_cashbook_possession = false và
    -- required_dimensions = [], nên tham số p_cashbook_id ở trên bị BỎ QUA: đo
    -- trên prod, một người thu được ở toà là server cho ghi vào CẢ 16/16 sổ của
    -- tổ chức, kể cả sổ chưa từng được cấp quyền gì. Trước đây chỉ có danh sách
    -- trên giao diện vô tình gác cổng; gọi thẳng API thì không còn gì chặn.
    --
    -- KHÔNG bật requires_cashbook_possession cho 'thu_tien.collect' để vá:
    -- authorize_tenant_action_v3 khi đó đòi cạnh ALLOW phải là scope CASHBOOK,
    -- mà vai trò "Quản Lý Tòa" chỉ có binding scope BUILDING (18 binding/org)
    -- ⇒ bật lên là chặn sạch mọi người thu. Vì vậy kiểm possession TRỰC TIẾP.
    --
    -- CUSTODIAN hoặc KNOWER đều hợp lệ (helper đã khai đúng vậy): người thu chỉ
    -- đạo tiền vào tài khoản ngân hàng của chủ thì là "người biết sổ", không
    -- phải người giữ tiền. Đo lịch sử 120 ngày: 0/31 lần thu bị chốt này chặn.
    IF v_collector_membership IS NULL
       OR NOT app_private.ie_has_cashbook_possession_v1(v_org, v_account_id, v_collector_membership) THEN
      RAISE EXCEPTION 'Bạn không được giao sổ quỹ này (cần là Người giữ sổ hoặc Người biết sổ). Chọn sổ khác.'
        USING ERRCODE = '42501';
    END IF;

    v_gross_total := v_gross_total + v_gross;
    IF v_method = 'TM' THEN
      v_tm_total := v_tm_total + v_gross;
      v_last_tm_idx := v_idx;
    END IF;
    v_idx := v_idx + 1;
  END LOOP;

  v_last_line_idx := v_idx - 1;
  v_remaining := GREATEST(v_invoice.total_amount - COALESCE(v_invoice.paid_amount, 0), 0);
  v_applied_total := LEAST(v_gross_total, v_remaining);

  IF v_gross_total > v_remaining THEN
    CASE upper(COALESCE(p_overpay_action, 'REJECT'))
      WHEN 'REFUND' THEN v_change_total := v_gross_total - v_remaining;
      WHEN 'CREDIT' THEN
        IF v_invoice.contract_id IS NULL THEN
          RAISE EXCEPTION 'Không thể giữ credit cho hóa đơn không có hợp đồng'
            USING ERRCODE = '22023';
        END IF;
        v_credit_total := v_gross_total - v_remaining;
      ELSE
        RAISE EXCEPTION 'Số thu vượt còn phải thu; chọn thối lại hoặc giữ credit'
          USING ERRCODE = '22023';
    END CASE;
    IF v_change_total > 0
       AND (v_last_tm_idx < 0 OR v_tm_total < v_change_total) THEN
      RAISE EXCEPTION 'Phần hoàn tiền phải nằm trong dòng tiền mặt TM của lần thu hiện tại'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_applied_total <= 0 THEN
    RAISE EXCEPTION 'Hóa đơn không còn số tiền có thể thu' USING ERRCODE = '55000';
  END IF;

  IF COALESCE(p_allow_rounding, false)
     AND v_remaining - v_applied_total > 0
     AND v_remaining - v_applied_total < 10000 THEN
    v_rounding_total := v_remaining - v_applied_total;
  END IF;

  v_retained_total := v_gross_total - v_change_total;

  SELECT COALESCE(sum(item.amount), 0)
    INTO v_deposit_due
  FROM public.invoice_items item
  WHERE item.invoice_id = p_invoice_id
    AND item.accounting_class = 'DEPOSIT';

  SELECT v_deposit_due + COALESCE(sum((source_row->>'amount')::numeric), 0)
    INTO v_deposit_due
  FROM jsonb_array_elements(COALESCE(v_invoice.previous_debt_sources, '[]'::jsonb)) source_row
  WHERE source_row->>'type' = 'deposit';
  v_deposit_due := COALESCE(v_deposit_due, 0);
  SELECT COALESCE(sum(item.amount), 0)
    INTO v_internal_due
  FROM public.invoice_items item
  WHERE item.invoice_id = p_invoice_id
    AND item.accounting_class = 'NON_PNL';

  v_internal_due := COALESCE(v_internal_due, 0);
  v_revenue_due := GREATEST(
    v_invoice.total_amount - v_deposit_due - v_internal_due,
    0
  );
  IF v_deposit_due = 'NaN'::numeric
     OR v_internal_due = 'NaN'::numeric
     OR v_invoice.total_amount = 'NaN'::numeric
     OR v_deposit_due + v_internal_due - v_invoice.total_amount >= 0.01 THEN
    RAISE EXCEPTION 'Dữ liệu cọc/NON_PNL vượt tổng phải thu; cần review kế toán'
      USING ERRCODE = '55000';
  END IF;

  SELECT
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'PNL'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'DEPOSIT'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'INTERNAL'), 0)
  INTO v_revenue_covered, v_deposit_covered, v_internal_covered
  FROM public.income_expenses voucher
  JOIN public.income_expense_items item
    ON item.income_expense_id = voucher.id
  LEFT JOIN public.invoice_payment_collections source_collection
    ON source_collection.id = voucher.payment_collection_id
  LEFT JOIN public.payments source_payment
    ON source_payment.id = voucher.payment_id
  WHERE voucher.invoice_id = p_invoice_id
    AND voucher.type = 'INCOME'
    AND voucher.approval_status = 'APPROVED'
    AND voucher.deleted_at IS NULL
    AND (
      voucher.payment_collection_id IS NULL
      OR source_collection.status = 'ACTIVE'
    )
    AND (voucher.payment_id IS NULL OR source_payment.reversed_at IS NULL);

  IF v_revenue_covered - v_revenue_due >= 0.01
     OR v_deposit_covered - v_deposit_due >= 0.01
     OR v_internal_covered - v_internal_due >= 0.01 THEN
    RAISE EXCEPTION 'Bút toán đã ghi vượt semantic của hóa đơn; cần review kế toán'
      USING ERRCODE = '55000';
  END IF;
  IF abs(
    v_revenue_covered + v_deposit_covered + v_internal_covered
    - COALESCE(v_invoice.paid_amount, 0)
  ) >= 0.01 THEN
    RAISE EXCEPTION 'Số đã thu không khớp bút toán semantic; cần đối soát trước'
      USING ERRCODE = '55000';
  END IF;
  v_revenue_covered := GREATEST(LEAST(v_revenue_covered, v_revenue_due), 0);
  v_deposit_covered := GREATEST(LEAST(v_deposit_covered, v_deposit_due), 0);
  v_internal_covered := GREATEST(LEAST(v_internal_covered, v_internal_due), 0);

  v_projection_left := v_applied_total;
  v_projected_revenue := v_revenue_covered + LEAST(
    v_projection_left,
    GREATEST(v_revenue_due - v_revenue_covered, 0)
  );
  v_projection_left := v_projection_left - (v_projected_revenue - v_revenue_covered);
  v_projected_deposit := v_deposit_covered + LEAST(
    v_projection_left,
    GREATEST(v_deposit_due - v_deposit_covered, 0)
  );
  v_projection_left := v_projection_left - (v_projected_deposit - v_deposit_covered);
  v_projected_internal := v_internal_covered + LEAST(
    v_projection_left,
    GREATEST(v_internal_due - v_internal_covered, 0)
  );
  v_projection_left := v_projection_left - (v_projected_internal - v_internal_covered);
  IF abs(v_projection_left) >= 0.01 THEN
    RAISE EXCEPTION 'Không thể phân bổ số thu vào semantic hóa đơn'
      USING ERRCODE = '55000';
  END IF;

  IF v_rounding_total > 0 AND (
    v_deposit_due - v_projected_deposit >= 0.01
    OR v_internal_due - v_projected_internal >= 0.01
  ) THEN
    RAISE EXCEPTION 'Không được làm tròn bỏ qua cọc hoặc khoản NON_PNL còn thiếu'
      USING ERRCODE = '22023';
  END IF;

  SELECT type_row.id INTO v_revenue_type_id
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'income'
    AND NOT type_row.is_deposit
  ORDER BY type_row.is_default DESC,
           CASE WHEN lower(btrim(type_row.name)) IN ('thu tiền hoá đơn', 'thu tiền hóa đơn') THEN 0 ELSE 1 END,
           type_row.created_at
  LIMIT 1 FOR SHARE;

  SELECT type_row.id INTO v_deposit_type_id
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'income'
    AND type_row.is_deposit
  ORDER BY CASE WHEN lower(btrim(type_row.name)) = 'tiền cọc' THEN 0 ELSE 1 END,
           type_row.created_at
  LIMIT 1 FOR SHARE;

  SELECT type_row.id INTO v_credit_type_id
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_org
    AND lower(type_row.type) = 'income'
    AND lower(btrim(type_row.name)) = 'tiền khách trả thừa'
  LIMIT 1 FOR SHARE;

  IF v_revenue_type_id IS NULL THEN
    RAISE EXCEPTION 'Tổ chức chưa có loại thu hóa đơn' USING ERRCODE = '55000';
  END IF;
  IF v_deposit_due > 0 AND v_deposit_type_id IS NULL THEN
    RAISE EXCEPTION 'Tổ chức chưa có loại thu cọc' USING ERRCODE = '55000';
  END IF;
  IF v_credit_total > 0 AND v_credit_type_id IS NULL THEN
    INSERT INTO public.income_expense_types (
      organization_id, user_id, name, type, description, is_default, is_deposit
    ) VALUES (
      v_org, v_owner, 'Tiền khách trả thừa', 'income',
      'Khoản khách trả dư giữ lại để cấn kỳ sau; ngoài KQKD', false, false
    ) RETURNING id INTO v_credit_type_id;
  END IF;

  v_creator_name := COALESCE(
    auth.jwt()->'user_metadata'->>'full_name',
    auth.jwt()->'user_metadata'->>'name',
    auth.jwt()->>'email',
    'Người dùng'
  );

  PERFORM app_private.claim_feature_operation_v1(
    'invoice.collection.v5',
    v_org,
    p_invoice_id::text,
    v_actor,
    v_key,
    v_retained_total
  );

  PERFORM app_private.begin_accounting_chain_write_v1();

  INSERT INTO public.invoice_payment_collections (
    organization_id, invoice_id, contract_id, status, collection_date,
    actor_id, idempotency_key, payload_hash, expected_paid_amount,
    gross_amount, retained_amount, applied_amount, change_amount,
    credit_amount, rounding_amount, notes, receipt_image_url
  ) VALUES (
    v_org, p_invoice_id, v_invoice.contract_id, 'ACTIVE', p_collection_date,
    v_actor, v_key, v_hash, p_expected_paid_amount,
    v_gross_total, v_retained_total, v_applied_total, v_change_total,
    v_credit_total, v_rounding_total, NULLIF(btrim(p_notes), ''), p_receipt_image_url
  ) RETURNING id INTO v_collection_id;

  v_remaining_apply := v_applied_total;
  v_change_left := v_change_total;
  v_credit_left := v_credit_total;
  v_idx := 0;

  FOR v_tender IN SELECT value FROM jsonb_array_elements(p_tenders) LOOP
    v_payment_id := NULL;
    v_voucher_id := NULL;
    v_gross := (v_tender->>'gross_amount')::numeric;
    v_method := (v_tender->>'payment_method')::public.payment_method;
    v_account_id := (v_tender->>'account_id')::uuid;
    v_change_account_id := NULLIF(v_tender->>'change_account_id', '')::uuid;
    v_rounding_account_id := NULLIF(v_tender->>'rounding_account_id', '')::uuid;
    v_line_change := 0;
    v_line_credit := 0;
    v_line_revenue := 0;
    v_line_deposit := 0;
    v_line_internal := 0;

    IF v_method = 'TM' AND v_change_left > 0 THEN
      SELECT COALESCE(sum((later.value->>'gross_amount')::numeric), 0)
        INTO v_later_tm_total
      FROM jsonb_array_elements(p_tenders) WITH ORDINALITY later(value, ord)
      WHERE later.ord - 1 > v_idx
        AND later.value->>'payment_method' = 'TM';

      v_line_change := LEAST(
        v_gross,
        GREATEST(v_change_total - v_later_tm_total, 0)
      );
      v_change_left := v_change_left - v_line_change;
    END IF;

    IF v_credit_left > 0 THEN
      SELECT COALESCE(sum((later.value->>'gross_amount')::numeric), 0)
        INTO v_later_gross_total
      FROM jsonb_array_elements(p_tenders) WITH ORDINALITY later(value, ord)
      WHERE later.ord - 1 > v_idx;

      v_line_credit := LEAST(
        v_gross - v_line_change,
        GREATEST(v_credit_total - v_later_gross_total, 0)
      );
      v_credit_left := v_credit_left - v_line_credit;
    END IF;

    IF v_line_change > 0 THEN
      IF v_change_account_id IS NULL THEN
        RAISE EXCEPTION 'Thiếu sổ quỹ tiền thối' USING ERRCODE = '22023';
      END IF;
      PERFORM 1 FROM public.accounts account_row
      WHERE account_row.id = v_change_account_id
        AND account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND account_row.is_virtual
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Sổ tiền thối phải là sổ ảo của tổ chức'
          USING ERRCODE = '42501';
      END IF;
      SELECT allowed INTO v_authz
      FROM app_private.authorize_tenant_action_v3(
        v_actor, v_org, 'thu_tien.collect', v_invoice.building_id, v_change_account_id
      );
      IF NOT COALESCE(v_authz, false) THEN
        RAISE EXCEPTION 'Không có quyền ghi tiền thối vào sổ đã chọn'
          USING ERRCODE = '42501';
      END IF;
    END IF;

    v_line_retained := v_gross - v_line_change;
    v_line_applied := LEAST(v_line_retained - v_line_credit, v_remaining_apply);
    v_remaining_apply := v_remaining_apply - v_line_applied;

    v_line_left := v_line_applied;
    v_line_revenue := LEAST(
      v_line_left,
      GREATEST(v_revenue_due - v_revenue_covered, 0)
    );
    v_revenue_covered := v_revenue_covered + v_line_revenue;
    v_line_left := v_line_left - v_line_revenue;

    v_line_deposit := LEAST(
      v_line_left,
      GREATEST(v_deposit_due - v_deposit_covered, 0)
    );
    v_deposit_covered := v_deposit_covered + v_line_deposit;
    v_line_left := v_line_left - v_line_deposit;

    v_line_internal := LEAST(
      v_line_left,
      GREATEST(v_internal_due - v_internal_covered, 0)
    );
    v_internal_covered := v_internal_covered + v_line_internal;
    v_line_left := v_line_left - v_line_internal;
    IF abs(v_line_left) >= 0.01 THEN
      RAISE EXCEPTION 'Dòng thanh toán không phân bổ hết vào semantic hóa đơn'
        USING ERRCODE = '55000';
    END IF;

    IF v_idx = v_last_line_idx AND v_rounding_total > 0 THEN
      IF v_rounding_account_id IS NULL THEN
        RAISE EXCEPTION 'Thiếu sổ quỹ làm tròn' USING ERRCODE = '22023';
      END IF;
      PERFORM 1 FROM public.accounts account_row
      WHERE account_row.id = v_rounding_account_id
        AND account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND account_row.is_virtual
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Sổ làm tròn phải là sổ ảo của tổ chức'
          USING ERRCODE = '42501';
      END IF;
      SELECT allowed INTO v_authz
      FROM app_private.authorize_tenant_action_v3(
        v_actor, v_org, 'thu_tien.collect', v_invoice.building_id, v_rounding_account_id
      );
      IF NOT COALESCE(v_authz, false) THEN
        RAISE EXCEPTION 'Không có quyền dùng sổ làm tròn đã chọn'
          USING ERRCODE = '42501';
      END IF;
      v_rounding_target_account := v_rounding_account_id;
    END IF;

    INSERT INTO public.invoice_payment_tenders (
      organization_id, collection_id, line_index, payment_method, account_id,
      change_account_id, rounding_account_id, gross_amount, retained_amount,
      applied_amount, change_amount, credit_amount, rounding_amount, receipt_number
    ) VALUES (
      v_org, v_collection_id, v_idx, v_method, v_account_id,
      v_change_account_id, v_rounding_account_id, v_gross, v_line_retained,
      v_line_applied, v_line_change, v_line_credit,
      CASE WHEN v_idx = v_last_line_idx THEN v_rounding_total ELSE 0 END,
      NULLIF(v_tender->>'receipt_number', '')
    ) RETURNING id INTO v_tender_id;

    IF v_line_applied > 0 THEN
      INSERT INTO public.payments (
        organization_id, user_id, invoice_id, receipt_number, amount,
        received_amount, credit_amount, change_amount, rounding_amount,
        payment_method, payment_date, notes, receipt_image_url,
        collection_id, tender_id
      ) VALUES (
        v_org, v_owner, p_invoice_id, NULLIF(v_tender->>'receipt_number', ''),
        v_line_applied, v_line_retained, v_line_credit, v_line_change,
        CASE WHEN v_idx = v_last_line_idx THEN v_rounding_total ELSE 0 END,
        v_method, p_collection_date, NULLIF(btrim(p_notes), ''),
        CASE WHEN v_idx = 0 THEN p_receipt_image_url END,
        v_collection_id, v_tender_id
      ) RETURNING id INTO v_payment_id;
    ELSE
      v_payment_id := NULL;
    END IF;

    IF v_line_retained > 0
       OR v_line_change > 0
       OR (v_idx = v_last_line_idx AND v_rounding_total > 0) THEN
      INSERT INTO public.income_expenses (
        user_id, organization_id, type, name, building_id, room_id, contract_id,
        account_id, invoice_id, payment_id, payment_collection_id, voucher_date,
        payer_name, notes, attachments, total_amount, approval_status,
        approved_by, approved_at, business_result_accounting, creator_name,
        change_amount, change_account_id, rounding_amount, rounding_account_id,
        system_source, idempotency_key
      ) VALUES (
        v_owner, v_org, 'INCOME', 'Thu tiền theo HĐ ' || COALESCE(v_invoice.invoice_number, ''),
        v_invoice.building_id, v_invoice.room_id, v_invoice.contract_id,
        v_account_id, p_invoice_id, v_payment_id, v_collection_id, p_collection_date,
        NULL, NULLIF(btrim(p_notes), ''),
        CASE WHEN v_idx = 0 AND p_receipt_image_url IS NOT NULL
          THEN jsonb_build_array(p_receipt_image_url) ELSE '[]'::jsonb END,
        v_line_retained, 'APPROVED', v_actor, clock_timestamp(), NULL,
        v_creator_name, v_line_change, v_change_account_id,
        CASE WHEN v_idx = v_last_line_idx THEN v_rounding_total ELSE 0 END,
        CASE WHEN v_idx = v_last_line_idx THEN v_rounding_account_id END,
        'invoice.collection.v5', v_key || ':tender:' || v_idx
      ) RETURNING id INTO v_voucher_id;

      IF v_line_revenue > 0 THEN
        INSERT INTO public.income_expense_items (
          income_expense_id, organization_id, income_expense_type_id, description,
          quantity, unit_price, amount, start_date, end_date, accounting_class
        ) VALUES (
          v_voucher_id, v_org, v_revenue_type_id,
          'Thanh toán HĐ ' || COALESCE(v_invoice.invoice_number, ''),
          1, v_line_revenue, v_line_revenue, p_collection_date, p_collection_date, 'PNL'
        ) RETURNING id INTO v_item_id;
        INSERT INTO public.invoice_payment_allocations (
          organization_id, collection_id, tender_id, voucher_id,
          income_expense_item_id, accounting_class, amount
        ) VALUES (
          v_org, v_collection_id, v_tender_id, v_voucher_id,
          v_item_id, 'PNL', v_line_revenue
        );
      END IF;

      IF v_line_deposit > 0 THEN
        INSERT INTO public.income_expense_items (
          income_expense_id, organization_id, income_expense_type_id, description,
          quantity, unit_price, amount, start_date, end_date, accounting_class
        ) VALUES (
          v_voucher_id, v_org, v_deposit_type_id,
          'Tiền cọc theo HĐ ' || COALESCE(v_invoice.invoice_number, ''),
          1, v_line_deposit, v_line_deposit, p_collection_date, p_collection_date, 'DEPOSIT'
        ) RETURNING id INTO v_item_id;
        INSERT INTO public.invoice_payment_allocations (
          organization_id, collection_id, tender_id, voucher_id,
          income_expense_item_id, accounting_class, amount
        ) VALUES (
          v_org, v_collection_id, v_tender_id, v_voucher_id,
          v_item_id, 'DEPOSIT', v_line_deposit
        );
      END IF;

      IF v_line_internal > 0 THEN
        INSERT INTO public.income_expense_items (
          income_expense_id, organization_id, income_expense_type_id, description,
          quantity, unit_price, amount, start_date, end_date, accounting_class
        ) VALUES (
          v_voucher_id, v_org, v_revenue_type_id,
          'Khoản ngoài KQKD theo HĐ ' || COALESCE(v_invoice.invoice_number, ''),
          1, v_line_internal, v_line_internal,
          p_collection_date, p_collection_date, 'INTERNAL'
        ) RETURNING id INTO v_item_id;
        INSERT INTO public.invoice_payment_allocations (
          organization_id, collection_id, tender_id, voucher_id,
          income_expense_item_id, accounting_class, amount
        ) VALUES (
          v_org, v_collection_id, v_tender_id, v_voucher_id,
          v_item_id, 'INTERNAL', v_line_internal
        );
      END IF;

      IF v_line_credit > 0 THEN
        INSERT INTO public.income_expense_items (
          income_expense_id, organization_id, income_expense_type_id, description,
          quantity, unit_price, amount, start_date, end_date, accounting_class
        ) VALUES (
          v_voucher_id, v_org, v_credit_type_id,
          'Tiền khách trả thừa từ HĐ ' || COALESCE(v_invoice.invoice_number, ''),
          1, v_line_credit, v_line_credit, p_collection_date, p_collection_date,
          'CUSTOMER_CREDIT'
        ) RETURNING id INTO v_item_id;
        INSERT INTO public.invoice_payment_allocations (
          organization_id, collection_id, tender_id, voucher_id,
          income_expense_item_id, accounting_class, amount
        ) VALUES (
          v_org, v_collection_id, v_tender_id, v_voucher_id,
          v_item_id, 'CUSTOMER_CREDIT', v_line_credit
        );
      END IF;

      INSERT INTO app_private.income_expense_flow_ownership (
        income_expense_id, organization_id, flow_kind, flow_version,
        lifecycle_owner, lifecycle_state, writer_operation,
        payload_hash_scheme, payload_hash_value, maker_user_id,
        claimed_by_user_id, correlation_id
      ) VALUES (
        v_voucher_id, v_org, 'INVOICE_COLLECTION_V5', 5,
        'INVOICE_COLLECTION_V5', 'APPROVED', 'invoice.collection.v5',
        'PG_MD5_JSONB_TEXT_V1', v_hash, v_actor, v_actor, v_collection_id
      ) ON CONFLICT (income_expense_id) DO NOTHING;
    END IF;

    UPDATE public.invoice_payment_tenders
       SET payment_id = v_payment_id, voucher_id = v_voucher_id
     WHERE id = v_tender_id;

    v_tender_results := v_tender_results || jsonb_build_array(jsonb_build_object(
      'tender_id', v_tender_id,
      'payment_id', v_payment_id,
      'voucher_id', v_voucher_id,
      'applied_amount', v_line_applied,
      'revenue_amount', v_line_revenue,
      'internal_amount', v_line_internal,
      'deposit_amount', v_line_deposit,
      'credit_amount', v_line_credit,
      'change_amount', v_line_change
    ));
    v_idx := v_idx + 1;
  END LOOP;

  IF v_remaining_apply <> 0 OR v_change_left <> 0 OR v_credit_left <> 0 THEN
    RAISE EXCEPTION 'Phân bổ collection không cân bằng' USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.invoice_payment_tenders tender
    LEFT JOIN public.invoice_payment_allocations allocation
      ON allocation.tender_id = tender.id
    WHERE tender.collection_id = v_collection_id
    GROUP BY tender.id, tender.retained_amount
    HAVING abs(
      tender.retained_amount - COALESCE(sum(allocation.amount), 0)
    ) >= 0.01
  ) THEN
    RAISE EXCEPTION 'Tổng allocation không khớp số tiền giữ lại của tender'
      USING ERRCODE = '55000';
  END IF;

  IF v_credit_total > 0 THEN
    SELECT count(*) INTO v_credit_tender_count
    FROM public.invoice_payment_tenders
    WHERE collection_id = v_collection_id AND credit_amount > 0;
    IF v_credit_tender_count = 1 THEN
      SELECT id, payment_id INTO v_tender_id, v_payment_id
      FROM public.invoice_payment_tenders
      WHERE collection_id = v_collection_id AND credit_amount > 0;
    ELSE
      v_tender_id := NULL;
      v_payment_id := NULL;
    END IF;

    INSERT INTO public.customer_credit_lots (
      organization_id, contract_id, source_collection_id, source_tender_id,
      source_payment_id, amount, remaining_amount, status
    ) VALUES (
      v_org, v_invoice.contract_id, v_collection_id, v_tender_id,
      v_payment_id, v_credit_total, v_credit_total, 'ACTIVE'
    ) RETURNING id INTO v_credit_lot_id;

    INSERT INTO public.excess_amounts (
      organization_id, user_id, contract_id, amount, description,
      source_invoice_id, source_payment_id, credit_lot_id
    ) VALUES (
      v_org, v_owner, v_invoice.contract_id, v_credit_total,
      'Tiền thừa từ hóa đơn ' || COALESCE(v_invoice.invoice_number, ''),
      p_invoice_id, v_payment_id, v_credit_lot_id
    ) RETURNING id INTO v_excess_id;

    UPDATE public.customer_credit_lots
       SET source_excess_amount_id = v_excess_id
     WHERE id = v_credit_lot_id;
  END IF;

  PERFORM public.recompute_invoice_for_id(p_invoice_id);
  PERFORM public.recompute_contract_deposit_paid(v_invoice.contract_id);

  SELECT jsonb_build_object(
    'collection_id', v_collection_id,
    'invoice_id', p_invoice_id,
    'gross_amount', v_gross_total,
    'applied_amount', v_applied_total,
    'change_amount', v_change_total,
    'credit_amount', v_credit_total,
    'rounding_amount', v_rounding_total,
    'credit_lot_id', v_credit_lot_id,
    'tenders', v_tender_results,
    'invoice', to_jsonb(invoice_row)
  ) INTO v_response
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;

  UPDATE app_private.canonical_write_operations
     SET subject_id = v_collection_id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'invoice.collection.v5'
     AND subject_scope = p_invoice_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;

  PERFORM app_private.end_accounting_chain_write_v1();
  RETURN v_response;
END;
$_$;








--
-- Name: FUNCTION record_invoice_collection_v5(p_invoice_id uuid, p_collection_date date, p_tenders jsonb, p_overpay_action text, p_allow_rounding boolean, p_notes text, p_receipt_image_url text, p_expected_paid_amount numeric, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_invoice_collection_v5(p_invoice_id uuid, p_collection_date date, p_tenders jsonb, p_overpay_action text, p_allow_rounding boolean, p_notes text, p_receipt_image_url text, p_expected_paid_amount numeric, p_idempotency_key text) IS 'Canonical multi-tender collection. REFUND is TM-only; CREDIT may retain overpay from TM/TK/TT.';








--
-- Name: record_invoice_payment_v2(uuid, numeric, public.payment_method, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_payment_v2(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_notes text DEFAULT NULL::text, p_receipt_image_url text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_payment_id uuid;
  v_new_paid_amount decimal(15,2);
  v_remaining decimal(15,2);
  v_excess decimal(15,2);
  v_new_status invoice_status;
  v_paid_date date;
  v_caller uuid := auth.uid();
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be positive';
  END IF;

  -- Lookup invoice + check RBAC qua can_access_building
  SELECT id, user_id, building_id, contract_id, total_amount, paid_amount, remaining_amount, status
  INTO v_invoice
  FROM invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
    AND public.can_do_on_building('invoices','edit', building_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice not found or access denied';
  END IF;

  -- Insert payment (trigger set_user_id_audit auto-fill user_id = auth.uid())
  INSERT INTO payments (invoice_id, amount, payment_method, payment_date, notes, receipt_image_url)
  VALUES (p_invoice_id, p_amount, p_payment_method, p_payment_date, p_notes, p_receipt_image_url)
  RETURNING id INTO v_payment_id;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  v_remaining := v_invoice.total_amount - v_new_paid_amount;

  IF v_new_paid_amount >= v_invoice.total_amount THEN
    v_new_status := 'PAID';
    v_paid_date := p_payment_date;
    v_excess := v_new_paid_amount - v_invoice.total_amount;

    IF v_excess > 0 THEN
      INSERT INTO excess_amounts (contract_id, amount, description, source_invoice_id, source_payment_id)
      VALUES (
        v_invoice.contract_id, v_excess,
        'Tiền thừa từ hoá đơn ' || (SELECT invoice_number FROM invoices WHERE id = p_invoice_id),
        p_invoice_id, v_payment_id
      );
    END IF;
  ELSE
    v_new_status := 'PARTIAL_PAID';
    v_paid_date := NULL;
    v_excess := 0;
  END IF;

  UPDATE invoices
  SET paid_amount = v_new_paid_amount,
      status = v_new_status,
      paid_date = v_paid_date
  WHERE id = p_invoice_id;

  RETURN json_build_object(
    'payment_id', v_payment_id,
    'new_paid_amount', v_new_paid_amount,
    'new_status', v_new_status,
    'excess_amount', v_excess
  );
END;
$$;








--
-- Name: FUNCTION record_invoice_payment_v2(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_notes text, p_receipt_image_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_invoice_payment_v2(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_notes text, p_receipt_image_url text) IS 'RBAC version of record_invoice_payment. Caller phải có quyền edit invoices trên building tương ứng.';








--
-- Name: record_invoice_payment_v3(uuid, numeric, public.payment_method, date, text, uuid, text, text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_payment_v3(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_receipt_image_url text DEFAULT NULL::text, p_voucher jsonb DEFAULT NULL::jsonb, p_items jsonb DEFAULT NULL::jsonb, p_receipt_number text DEFAULT NULL::text, p_voucher_owner_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.record_invoice_payment_v4(
    p_invoice_id, p_amount, p_payment_method, p_payment_date, p_idempotency_key,
    p_account_id, p_notes, p_receipt_image_url, p_voucher, p_items,
    p_receipt_number, p_voucher_owner_id
  );
$$;








--
-- Name: record_invoice_payment_v4(uuid, numeric, public.payment_method, date, text, uuid, text, text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_payment_v4(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_receipt_image_url text DEFAULT NULL::text, p_voucher jsonb DEFAULT NULL::jsonb, p_items jsonb DEFAULT NULL::jsonb, p_receipt_number text DEFAULT NULL::text, p_voucher_owner_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_invoice public.invoices%ROWTYPE;
  v_org uuid;
  v_authz boolean;
  v_remaining numeric;
  v_deposit_due numeric := 0;
  v_internal_due numeric := 0;
  v_revenue_due numeric := 0;
  v_revenue_covered numeric := 0;
  v_deposit_covered numeric := 0;
  v_internal_covered numeric := 0;
  v_expected_revenue numeric := 0;
  v_expected_deposit numeric := 0;
  v_left numeric := 0;
  v_result jsonb;
  v_payment_id uuid;
  v_voucher_id uuid;
  v_compat_operation app_private.canonical_write_operations%ROWTYPE;
  v_hash text;
  v_actual_revenue numeric := 0;
  v_actual_deposit numeric := 0;
  v_actual_other numeric := 0;
  v_credit numeric := 0;
  v_change numeric := 0;
  v_change_account uuid;
  v_rounding numeric := 0;
  v_rounding_account uuid;
  v_validate_semantics boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount = 'NaN'::numeric
     OR p_amount <= 0 OR round(p_amount, 2) <> p_amount THEN
    RAISE EXCEPTION 'Số tiền thanh toán không hợp lệ' USING ERRCODE = '22023';
  END IF;
  v_validate_semantics := p_account_id IS NOT NULL
    AND p_voucher IS NOT NULL
    AND CASE
      WHEN jsonb_typeof(p_items) = 'array' THEN jsonb_array_length(p_items) > 0
      ELSE false
    END;
  v_change := COALESCE((p_voucher->>'change_amount')::numeric, 0);
  v_rounding := COALESCE((p_voucher->>'rounding_amount')::numeric, 0);
  v_change_account := NULLIF(p_voucher->>'change_account_id', '')::uuid;
  v_rounding_account := NULLIF(p_voucher->>'rounding_account_id', '')::uuid;
  IF v_change = 'NaN'::numeric OR v_rounding = 'NaN'::numeric
     OR v_change < 0 OR v_rounding < 0
     OR round(v_change, 2) <> v_change
     OR round(v_rounding, 2) <> v_rounding THEN
    RAISE EXCEPTION 'Payment change/rounding metadata is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy hóa đơn' USING ERRCODE = '42501';
  END IF;

  SELECT building_row.organization_id INTO v_org
  FROM public.buildings building_row
  JOIN public.organizations organization_row
    ON organization_row.id = building_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE building_row.id = v_invoice.building_id
    AND building_row.deleted_at IS NULL
    AND building_row.organization_id = v_invoice.organization_id
  FOR SHARE OF building_row, organization_row;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Hóa đơn không thuộc tổ chức hợp lệ' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.collect', v_invoice.building_id, p_account_id
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Không có quyền thu tiền hóa đơn' USING ERRCODE = '42501';
  END IF;

  IF p_account_id IS NOT NULL THEN
    PERFORM 1
    FROM public.accounts account_row
    WHERE account_row.id = p_account_id
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sổ nhận tiền phải là sổ tiền thật của tổ chức'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- V5 used a different operation namespace. Replaying a completed V5 call
  -- after this cutover must return its stored response, never create a second
  -- legacy payment with the same idempotency key.
  v_hash := md5(jsonb_build_object(
    'invoice_id', p_invoice_id,
    'amount', p_amount,
    'payment_method', p_payment_method,
    'payment_date', p_payment_date,
    'account_id', p_account_id,
    'notes', p_notes,
    'receipt_image_url', p_receipt_image_url,
    'voucher', p_voucher,
    'items', p_items,
    'receipt_number', p_receipt_number,
    'voucher_owner_id', p_voucher_owner_id
  )::text);
  SELECT * INTO v_compat_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'invoice.collection.compat.v4'
    AND operation_row.subject_scope = p_invoice_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_compat_operation.payload_hash <> v_hash THEN
      RAISE EXCEPTION 'idempotency_key was reused with a different payload'
        USING ERRCODE = '23505';
    END IF;
    IF v_compat_operation.completed_at IS NOT NULL THEN
      RETURN v_compat_operation.response_payload::json;
    END IF;
  END IF;

  IF v_change > 0 THEN
    PERFORM 1
    FROM public.accounts account_row
    WHERE account_row.id = v_change_account
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Change account must be a virtual account in the invoice organization'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_rounding > 0 THEN
    PERFORM 1
    FROM public.accounts account_row
    WHERE account_row.id = v_rounding_account
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Rounding account must be a virtual account in the invoice organization'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- A completed replay must be evaluated by the original V4 payload hash, not
  -- against the invoice balance after the first successful write.
  IF EXISTS (
    SELECT 1
    FROM app_private.canonical_write_operations operation_row
    WHERE operation_row.organization_id = v_org
      AND operation_row.operation = 'invoice.record_payment.v1'
      AND operation_row.subject_scope = p_invoice_id::text
      AND operation_row.actor_id = v_actor
      AND operation_row.idempotency_key = v_key
      AND operation_row.completed_at IS NOT NULL
  ) THEN
    RETURN public._record_invoice_payment_v4_legacy(
      p_invoice_id, p_amount, p_payment_method, p_payment_date, v_key,
      p_account_id, p_notes, p_receipt_image_url, p_voucher, p_items,
      p_receipt_number, p_voucher_owner_id
    );
  END IF;

  v_remaining := GREATEST(
    v_invoice.total_amount - COALESCE(v_invoice.paid_amount, 0),
    0
  );

  SELECT
    COALESCE(sum(item.amount) FILTER (WHERE item.accounting_class = 'DEPOSIT'), 0),
    COALESCE(sum(item.amount) FILTER (WHERE item.accounting_class = 'NON_PNL'), 0)
    INTO v_deposit_due, v_internal_due
  FROM public.invoice_items item
  WHERE item.invoice_id = p_invoice_id;

  SELECT v_deposit_due + COALESCE(sum((source_row->>'amount')::numeric), 0)
    INTO v_deposit_due
  FROM jsonb_array_elements(
    COALESCE(v_invoice.previous_debt_sources, '[]'::jsonb)
  ) source_row
  WHERE source_row->>'type' = 'deposit';

  v_deposit_due := COALESCE(v_deposit_due, 0);
  v_internal_due := COALESCE(v_internal_due, 0);

  IF p_amount > v_remaining + 0.009 THEN
    RAISE EXCEPTION 'Customer-credit creation is quarantined; invoice overpayment is not allowed'
      USING ERRCODE = '55000';
  END IF;
  IF v_rounding > 0 AND (
    v_rounding >= 10000
    OR v_remaining - p_amount <= 0
    OR abs(v_rounding - (v_remaining - p_amount)) >= 0.01
  ) THEN
    RAISE EXCEPTION 'Rounding must exactly close a positive invoice residual below 10000'
      USING ERRCODE = '22023';
  END IF;

  -- Invoice-linked cash must always carry a real account, voucher and items.
  -- The generic cashbook form cannot provide those semantics, so it must use
  -- the invoice payment screen rather than creating an irreversible payment.
  IF NOT v_validate_semantics THEN
    RAISE EXCEPTION 'Invoice payments require the invoice payment screen with full accounting semantics'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) input_item
    LEFT JOIN public.income_expense_types type_row
      ON type_row.id = NULLIF(input_item->>'income_expense_type_id', '')::uuid
    WHERE type_row.id IS NULL
      OR type_row.organization_id IS DISTINCT FROM v_org
      OR lower(type_row.type) <> 'income'
  ) THEN
    RAISE EXCEPTION 'Payment item type must be an income type in the invoice organization'
      USING ERRCODE = '42501';
  END IF;
  v_revenue_due := GREATEST(
    v_invoice.total_amount - v_deposit_due - v_internal_due,
    0
  );

  IF v_deposit_due + v_internal_due - v_invoice.total_amount >= 0.01 THEN
    RAISE EXCEPTION 'Dữ liệu cọc/NON_PNL vượt tổng hóa đơn; cần đối soát'
      USING ERRCODE = '55000';
  END IF;
  IF v_internal_due >= 0.01 THEN
    RAISE EXCEPTION 'Writer tương thích chưa hỗ trợ hóa đơn có NON_PNL'
      USING ERRCODE = '55000';
  END IF;

  SELECT
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'PNL'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'DEPOSIT'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'INTERNAL'), 0)
    INTO v_revenue_covered, v_deposit_covered, v_internal_covered
  FROM public.income_expenses voucher
  JOIN public.income_expense_items item
    ON item.income_expense_id = voucher.id
  LEFT JOIN public.invoice_payment_collections source_collection
    ON source_collection.id = voucher.payment_collection_id
  LEFT JOIN public.payments source_payment
    ON source_payment.id = voucher.payment_id
  WHERE voucher.invoice_id = p_invoice_id
    AND voucher.type = 'INCOME'
    AND voucher.approval_status = 'APPROVED'
    AND voucher.deleted_at IS NULL
    AND (
      voucher.payment_collection_id IS NULL
      OR source_collection.status = 'ACTIVE'
    )
    AND (voucher.payment_id IS NULL OR source_payment.reversed_at IS NULL);

  IF abs(
    v_revenue_covered + v_deposit_covered + v_internal_covered
    - COALESCE(v_invoice.paid_amount, 0)
  ) >= 0.01 THEN
    RAISE EXCEPTION 'Số đã thu không khớp bút toán semantic; cần đối soát trước'
      USING ERRCODE = '55000';
  END IF;

  v_left := p_amount;
  v_expected_revenue := LEAST(
    v_left,
    GREATEST(v_revenue_due - v_revenue_covered, 0)
  );
  v_left := v_left - v_expected_revenue;
  v_expected_deposit := LEAST(
    v_left,
    GREATEST(v_deposit_due - v_deposit_covered, 0)
  );
  v_left := v_left - v_expected_deposit;
  IF abs(v_left) >= 0.01 THEN
    RAISE EXCEPTION 'Không thể phân bổ khoản thu vào doanh thu/cọc của hóa đơn'
      USING ERRCODE = '55000';
  END IF;

  v_result := public._record_invoice_payment_v4_legacy(
    p_invoice_id, p_amount, p_payment_method, p_payment_date, v_key,
    p_account_id, p_notes, p_receipt_image_url, p_voucher, p_items,
    p_receipt_number, p_voucher_owner_id
  )::jsonb;

  v_payment_id := NULLIF(v_result->>'payment_id', '')::uuid;
  v_voucher_id := NULLIF(v_result->>'voucher_id', '')::uuid;
  IF v_payment_id IS NULL OR v_voucher_id IS NULL THEN
    RAISE EXCEPTION 'Writer tương thích không trả đủ payment/voucher'
      USING ERRCODE = '55000';
  END IF;

  v_credit := GREATEST(COALESCE((v_result->>'excess_amount')::numeric, 0), 0);
  -- New legacy-compatible payments need explicit receipt semantics so the
  -- compensating reversal adapter can verify and copy their accounting classes.
  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.payments payment_row
     SET received_amount = p_amount,
          credit_amount = v_credit,
          change_amount = v_change,
          rounding_amount = 0,
         updated_at = clock_timestamp()
   WHERE payment_row.id = v_payment_id
     AND payment_row.invoice_id = p_invoice_id;
  UPDATE public.income_expenses voucher_row
     SET change_amount = v_change,
         change_account_id = CASE WHEN v_change > 0 THEN v_change_account ELSE NULL END,
         rounding_amount = v_rounding,
         rounding_account_id = CASE WHEN v_rounding > 0 THEN v_rounding_account ELSE NULL END
   WHERE voucher_row.id = v_voucher_id
     AND voucher_row.payment_id = v_payment_id
     AND voucher_row.invoice_id = p_invoice_id;
  PERFORM app_private.end_accounting_chain_write_v1();

  SELECT
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'PNL'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class = 'DEPOSIT'), 0),
    COALESCE(sum(COALESCE(item.amount, item.unit_price * item.quantity))
      FILTER (WHERE item.accounting_class NOT IN ('PNL', 'DEPOSIT')), 0)
    INTO v_actual_revenue, v_actual_deposit, v_actual_other
  FROM public.income_expense_items item
  WHERE item.income_expense_id = v_voucher_id;

  IF abs(v_actual_revenue - v_expected_revenue) >= 0.01
     OR abs(v_actual_deposit - v_expected_deposit) >= 0.01
     OR abs(v_actual_other) >= 0.01
     OR abs(v_actual_revenue + v_actual_deposit - p_amount) >= 0.01 THEN
    RAISE EXCEPTION
      'Phân bổ phiếu thu không khớp semantic hóa đơn (PNL %/%; cọc %/%)',
      v_actual_revenue, v_expected_revenue,
      v_actual_deposit, v_expected_deposit
      USING ERRCODE = '55000';
  END IF;

  PERFORM public.recompute_ie_business_result(v_voucher_id);
  IF v_invoice.contract_id IS NOT NULL THEN
    PERFORM public.recompute_contract_deposit_paid(v_invoice.contract_id);
  END IF;

  RETURN v_result::json;
END;
$_$;








--
-- Name: FUNCTION record_invoice_payment_v4(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid, p_notes text, p_receipt_image_url text, p_voucher jsonb, p_items jsonb, p_receipt_number text, p_voucher_owner_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_invoice_payment_v4(p_invoice_id uuid, p_amount numeric, p_payment_method public.payment_method, p_payment_date date, p_idempotency_key text, p_account_id uuid, p_notes text, p_receipt_image_url text, p_voucher jsonb, p_items jsonb, p_receipt_number text, p_voucher_owner_id uuid) IS 'Single-payment compatibility writer for the narrowed L03 rollout. Validates PNL/DEPOSIT allocation server-side and does not create V5 collections.';








--
-- Name: record_payment_gps(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_gps(p_income_expense_id uuid, p_lat numeric, p_lng numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_ie public.income_expenses;
  v_bld UUID;
  v_b public.buildings;
  v_geo JSONB;
  v_dist INT; v_status TEXT;
  v_today DATE := public.vn_local_date(now());
  v_checked BOOLEAN;
  v_sad public.salary_attendance_day;
  v_tick JSONB;
BEGIN
  SELECT * INTO v_ie FROM public.income_expenses WHERE id = p_income_expense_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('action','none','reason','ie_not_found'); END IF;
  IF v_ie.user_id <> v_uid AND NOT public.is_admin() THEN
    RETURN jsonb_build_object('action','none','reason','not_owner_of_receipt');
  END IF;
  v_bld := COALESCE(v_ie.building_id, (SELECT building_id FROM public.rooms WHERE id = v_ie.room_id));
  IF v_bld IS NULL THEN RETURN jsonb_build_object('action','none','reason','no_building'); END IF;

  SELECT * INTO v_b FROM public.buildings WHERE id = v_bld;
  v_geo := public.get_acceptance_geofence_config();
  IF p_lat IS NULL OR p_lng IS NULL THEN v_status := 'gps_denied'; v_dist := NULL;
  ELSIF v_b.latitude IS NULL OR v_b.longitude IS NULL THEN v_status := 'ok'; v_dist := NULL;
  ELSE
    v_dist := public.v5_distance_m(p_lat, p_lng, v_b.latitude, v_b.longitude);
    v_status := CASE WHEN v_dist <= COALESCE((v_geo->>'radius_m')::int, 70) THEN 'ok' ELSE 'out_of_range' END;
  END IF;

  UPDATE public.income_expenses SET collect_lat = p_lat, collect_lng = p_lng,
    collect_distance_m = v_dist, collect_geofence_status = v_status
  WHERE id = p_income_expense_id;

  IF v_status <> 'ok' THEN
    -- GPS lệch toà (thu hộ từ xa) / denied: không dấu chân, phiếu vẫn nguyên
    RETURN jsonb_build_object('action','none','geofence_status', v_status, 'distance_m', v_dist);
  END IF;

  -- toà ĐÃ được mình check hôm nay? → tick luôn
  SELECT EXISTS (SELECT 1 FROM public.inspection_sessions
    WHERE user_id = v_uid AND building_id = v_bld AND session_date = v_today
      AND status IN ('passed','quick_done')) INTO v_checked;

  SELECT * INTO v_sad FROM public.salary_attendance_day WHERE user_id = v_uid AND work_date = v_today;

  IF v_checked THEN
    v_tick := public.v5_tick_attendance(v_uid, v_today, 'PAYMENT', p_income_expense_id, 'thu tiền + đã check');
    RETURN jsonb_build_object('action','ticked','geofence_status',v_status,'tick',v_tick);
  END IF;

  IF FOUND AND v_sad.status = 'ticked' THEN
    -- C14: ngày ĐÃ ticked → KHÔNG sinh treo; gợi ý piggyback thay thế
    RETURN jsonb_build_object('action','piggyback_prompt','geofence_status',v_status,'building_id',v_bld);
  END IF;

  -- chưa check + ngày chưa tick → SAD pending_check + thông báo TREO (dedup toà+ngày)
  INSERT INTO public.salary_attendance_day (user_id, work_date, status, evidence)
  VALUES (v_uid, v_today, 'pending_check',
          jsonb_build_array(jsonb_build_object('at', now(), 'kind', 'pending_check',
            'building_id', v_bld, 'ref_id', p_income_expense_id)))
  ON CONFLICT (user_id, work_date) DO UPDATE SET
    status = CASE WHEN salary_attendance_day.status = 'pending' THEN 'pending_check' ELSE salary_attendance_day.status END,
    evidence = salary_attendance_day.evidence || jsonb_build_array(jsonb_build_object(
      'at', now(), 'kind', 'pending_check', 'building_id', v_bld, 'ref_id', p_income_expense_id)),
    updated_at = now();

  BEGIN
    INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
    VALUES (v_uid, 'CUSTOM', 'IN_APP', 'PENDING',
      'Cần check nhà sau khi thu tiền',
      'Cần check nhà ' || COALESCE(v_b.name,'') || ' sau khi thu tiền — hoàn thành để chốt ngày công hôm nay',
      jsonb_build_object('v5','pending_check','building_id', v_bld, 'date', v_today, 'url', '/my-day'));
  EXCEPTION WHEN unique_violation THEN NULL; -- 1 thông báo/toà/ngày
  END;

  RETURN jsonb_build_object('action','pending_check','geofence_status',v_status,'building_id',v_bld);
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, source_id, error_text, payload)
  VALUES (v_uid, 'record_payment_gps', p_income_expense_id, SQLERRM, NULL);
  RETURN jsonb_build_object('action','none','reason','error_logged');
END; $$;








--
-- Name: record_termination_refund_obligation_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_termination_refund_obligation_v1(p_termination_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
DECLARE
  v_p jsonb; v_org uuid; v_ct uuid; v_tm uuid; v_ver int; v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;

  v_p   := public.preview_termination_refund_v1(p_termination_id);
  v_tm  := (v_p->>'terminationId')::uuid;   -- id ĐÃ phân giải
  v_org := (v_p->>'organizationId')::uuid;
  v_ct  := (v_p->>'contractId')::uuid;

  PERFORM 1 FROM contract_terminations WHERE id = v_tm FOR UPDATE;

  SELECT COALESCE(max(version),0) + 1 INTO v_ver
    FROM termination_refund_obligations
   WHERE organization_id=v_org AND termination_id=v_tm;

  INSERT INTO termination_refund_obligations
    (organization_id, termination_id, contract_id, version,
     requested_amount, real_held, recognized_only, basis_status, basis_fingerprint,
     obligation_status, warning, snapshot, created_by)
  VALUES
    (v_org, v_tm, v_ct, v_ver,
     (v_p->>'requestedAmount')::numeric, (v_p->>'realHeld')::numeric,
     (v_p->>'recognizedOnly')::numeric, v_p->>'basisStatus', v_p->>'basisFingerprint',
     v_p->>'obligationStatus', v_p->>'warning', v_p, auth.uid())
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('obligationId', v_id, 'version', v_ver,
                            'terminationId', v_tm,
                            'obligationStatus', v_p->>'obligationStatus',
                            'warning', v_p->>'warning');
END;
$$;








--
-- Name: FUNCTION record_termination_refund_obligation_v1(p_termination_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_termination_refund_obligation_v1(p_termination_id uuid) IS 'Đợt 7: chốt nghĩa vụ hoàn thành một dòng BẤT BIẾN (sửa thì tăng version, không UPDATE). Khoá hồ sơ FOR UPDATE trước khi chụp cơ sở để cơ sở đứng yên. Lưu cả fingerprint của cơ sở cọc — đổi một nguồn là fingerprint đổi, biết ngay cơ sở đã trôi.';








--
-- Name: reject_cancel_handover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_cancel_handover(p_handover_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h cash_handovers%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_h FROM cash_handovers WHERE id = p_handover_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên bàn giao'; END IF;
  IF auth.uid() NOT IN (v_h.giver_id, v_h.receiver_id) THEN
    RAISE EXCEPTION 'Chỉ người giao hoặc người nhận mới thao tác được';
  END IF;
  IF v_h.cancel_requested_by IS NULL THEN
    RAISE EXCEPTION 'Phiên % không có yêu cầu hủy', v_h.code;
  END IF;
  IF v_h.status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Phiên % đã hủy rồi', v_h.code;
  END IF;

  UPDATE cash_handovers
     SET cancel_requested_by = NULL, cancel_reason = NULL, cancel_requested_at = NULL
   WHERE id = p_handover_id;

  RETURN jsonb_build_object('id', p_handover_id, 'code', v_h.code);
END;
$$;








--
-- Name: reject_contract_termination_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_contract_termination_v1(p_termination_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_term public.contract_terminations%rowtype;
  v_building uuid;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;

  select * into v_term from public.contract_terminations
   where id = p_termination_id for update;
  if not found then
    raise exception 'Không tìm thấy yêu cầu thanh lý hoặc bạn không có quyền' using errcode = '42501';
  end if;

  v_building := public.building_of_contract(v_term.contract_id);
  if not (public.is_super_admin()
          or public.can_do_on_building('contracts', 'edit', v_building)) then
    raise exception 'Không có quyền từ chối yêu cầu thanh lý này' using errcode = '42501';
  end if;

  if v_term.status = 'COMPLETED' then
    raise exception 'Yêu cầu đã hoàn tất thanh lý — không thể từ chối';
  end if;

  -- Mirror legacy: trả về DRAFT (không phải REJECTED) + prefix lý do vào notes.
  update public.contract_terminations
     set status = 'DRAFT',
         notes = case when nullif(btrim(coalesce(p_reason, '')), '') is not null
                      then '[Từ chối] ' || btrim(p_reason)
                      else notes end
   where id = v_term.id;
end;
$$;








--
-- Name: reject_invalid_income_expense_v2(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_invalid_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'r', p_reason)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: reason is required' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.reject_invalid.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: approver capability required in scope' USING ERRCODE = '42501';
  END IF;

  IF v_ie.approval_status <> 'UNAPPROVED' OR v_ie.posting_status = 'POSTED' THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: only an unposted UNAPPROVED voucher can be rejected (%, %)',
      v_ie.approval_status, v_ie.posting_status USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'reject_invalid_income_expense_v2: review_version mismatch' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET approval_status = 'CANCELLED', review_state = 'RESOLVED',
         cancellation_kind = 'REJECTED_INVALID', review_reason = p_reason,
         posting_status = CASE WHEN v_ie.posting_mode = 'NON_CASH' THEN 'NOT_APPLICABLE' ELSE 'UNPOSTED' END,
         review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  UPDATE public.approval_requests ar
     SET state = 'REJECTED', outcome_kind = 'INVALID_OR_DUPLICATE', outcome_reason = p_reason,
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'CANCELLED',
                               'reviewState', 'RESOLVED', 'cancellationKind', 'REJECTED_INVALID',
                               'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.reject_invalid.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'INVALID_OR_DUPLICATE', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.reject_invalid.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION reject_invalid_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reject_invalid_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_idempotency_key text) IS 'Plan §5.3/§7.4: reject-invalid -> CANCELLED + terminal posting state per mode; close request REJECTED.';








--
-- Name: renew_contract(uuid, date, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_contract(p_contract_id uuid, p_new_end_date date, p_new_rent_price numeric DEFAULT NULL::numeric, p_new_deposit numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_room uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  SELECT room_id INTO v_room FROM public.contracts
   WHERE id = p_contract_id AND deleted_at IS NULL;
  IF NOT (
    public.is_super_admin()
    OR (v_room IS NOT NULL AND public.can_do_on_building('contracts','edit',
          (SELECT building_id FROM public.rooms WHERE id = v_room)))
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên hợp đồng này' USING ERRCODE = '42501';
  END IF;
  RETURN public.renew_contract_impl(p_contract_id, p_new_end_date, p_new_rent_price, p_new_deposit, p_notes);
END $$;








--
-- Name: renew_contract_impl(uuid, date, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_contract_impl(p_contract_id uuid, p_new_end_date date, p_new_rent_price numeric DEFAULT NULL::numeric, p_new_deposit numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract RECORD;
  v_months   int;
BEGIN
  SELECT * INTO v_contract FROM contracts WHERE id = p_contract_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hợp đồng không tồn tại';
  END IF;

  IF v_contract.status NOT IN ('ACTIVE', 'EXTENDED') THEN
    RAISE EXCEPTION 'Chỉ gia hạn được hợp đồng đang hiệu lực (status hiện tại: %)', v_contract.status;
  END IF;

  IF p_new_end_date IS NULL OR p_new_end_date <= v_contract.end_date THEN
    RAISE EXCEPTION 'Ngày kết thúc mới phải sau ngày kết thúc hiện tại (%)', v_contract.end_date;
  END IF;

  -- Gia hạn = CẬP NHẬT tại chỗ; GIỮ status='ACTIVE' (không đổi EXTENDED).
  UPDATE contracts
     SET end_date     = p_new_end_date,
         rent_price   = COALESCE(p_new_rent_price, rent_price),
         total_deposit= COALESCE(p_new_deposit,    total_deposit),
         notes        = CASE
                          WHEN p_notes IS NULL OR length(btrim(p_notes)) = 0 THEN notes
                          WHEN notes  IS NULL OR length(btrim(notes))  = 0 THEN p_notes
                          ELSE notes || E'\n[Gia hạn] ' || p_notes
                        END,
         updated_at   = NOW()
   WHERE id = p_contract_id;

  -- Số tháng gia hạn (cột extension_months NOT NULL), tối thiểu 1.
  v_months := GREATEST(1, (EXTRACT(YEAR  FROM age(p_new_end_date, v_contract.end_date)) * 12
                         + EXTRACT(MONTH FROM age(p_new_end_date, v_contract.end_date)))::int);

  -- Bản ghi gia hạn = NGUỒN SỰ THẬT của "đã gia hạn" (KHÔNG nuốt lỗi).
  INSERT INTO contract_extensions (
    user_id, contract_id, extension_type, extension_date,
    old_end_date, new_end_date, extension_months,
    new_rent_price, rent_price_changed,
    new_deposit,    deposit_changed,
    notes, status
  ) VALUES (
    v_contract.user_id, p_contract_id, 'UPDATE_EXISTING', public.org_today_v1(NULL),
    v_contract.end_date, p_new_end_date, v_months,
    p_new_rent_price, (p_new_rent_price IS NOT NULL AND p_new_rent_price <> v_contract.rent_price),
    p_new_deposit,    (p_new_deposit    IS NOT NULL AND p_new_deposit    <> v_contract.total_deposit),
    p_notes, 'COMPLETED'
  );

  RETURN p_contract_id;
END;
$$;








--
-- Name: report_device_issue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_device_issue(p_session uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_sess public.inspection_sessions;
  v_owner UUID := (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1);
BEGIN
  SELECT * INTO v_sess FROM public.inspection_sessions WHERE id = p_session;
  IF NOT FOUND OR v_sess.user_id <> v_uid THEN RAISE EXCEPTION 'Phiên không hợp lệ'; END IF;
  UPDATE public.inspection_sessions SET
    device_issue = jsonb_build_object('reported_at', now(), 'reason', p_reason),
    updated_at = now()
  WHERE id = p_session;
  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES (v_owner, 'CUSTOM', 'IN_APP', 'PENDING', 'Báo sự cố thiết bị (kiểm tra nhà)',
    (SELECT COALESCE(full_name,'Nhân viên') FROM public.profiles WHERE id = v_uid) || ' báo sự cố tại toà ' ||
    (SELECT name FROM public.buildings WHERE id = v_sess.building_id) || ': ' || p_reason,
    jsonb_build_object('v5','device_issue','session_id', p_session, 'staff_id', v_uid));
  RETURN jsonb_build_object('reported', true);
END; $$;








--
-- Name: request_cancel_handover(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_cancel_handover(p_handover_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h cash_handovers%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_h FROM cash_handovers WHERE id = p_handover_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên bàn giao'; END IF;
  IF auth.uid() NOT IN (v_h.giver_id, v_h.receiver_id) THEN
    RAISE EXCEPTION 'Chỉ người giao hoặc người nhận mới được yêu cầu hủy';
  END IF;
  IF v_h.status NOT IN ('PENDING', 'CONFIRMED') THEN
    RAISE EXCEPTION 'Phiên % đã hủy rồi', v_h.code;
  END IF;
  IF v_h.cancel_requested_by IS NOT NULL THEN
    RAISE EXCEPTION 'Phiên % đã có yêu cầu hủy đang chờ xác nhận', v_h.code;
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'Vui lòng nhập lý do hủy';
  END IF;

  UPDATE cash_handovers
     SET cancel_requested_by = auth.uid(),
         cancel_reason = btrim(p_reason),
         cancel_requested_at = now()
   WHERE id = p_handover_id;

  RETURN jsonb_build_object('id', p_handover_id, 'code', v_h.code);
END;
$$;








--
-- Name: request_income_expense_changes_v2(uuid, bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_income_expense_changes_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_field_mask jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'r', p_reason, 'm', p_field_mask)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: reason is required' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.request_changes.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.approve', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: approver capability required in scope' USING ERRCODE = '42501';
  END IF;

  IF v_ie.approval_status <> 'UNAPPROVED' OR v_ie.review_state NOT IN ('PENDING','DISPUTED') THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: voucher not in a requestable state (%, %)',
      v_ie.approval_status, v_ie.review_state USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'request_income_expense_changes_v2: review_version mismatch' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET review_state = 'CHANGES_REQUESTED', review_reason = p_reason,
         change_field_mask = p_field_mask, review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  UPDATE public.approval_requests ar
     SET state = 'CHANGES_REQUESTED', outcome_kind = 'REQUEST_CHANGES', outcome_reason = p_reason,
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'UNAPPROVED',
                               'reviewState', 'CHANGES_REQUESTED', 'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.request_changes.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'REQUEST_CHANGES', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.request_changes.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION request_income_expense_changes_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_field_mask jsonb, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_income_expense_changes_v2(p_voucher uuid, p_expected_review_version bigint, p_reason text, p_field_mask jsonb, p_idempotency_key text) IS 'Plan §5.3/§7.4: UNAPPROVED->CHANGES_REQUESTED (reason+field mask); close current request CHANGES_REQUESTED.';








--
-- Name: request_opening_balance_adjustment_v1(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_opening_balance_adjustment_v1(p_cashbook_id uuid, p_delta numeric, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_acct record;
  v_authz boolean;
  v_holds boolean;
  v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  v_type uuid; v_voucher uuid;
  v_resp json;
  c_op constant text := 'cashbook.opening_adjust.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if char_length(v_key) < 8 or char_length(v_key) > 200
     or v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_delta is null or p_delta = 0 or round(p_delta,2) <> p_delta then
    raise exception 'Giá trị điều chỉnh không hợp lệ'; end if;
  if coalesce(length(btrim(p_reason)),0) < 5 then raise exception 'Lý do điều chỉnh quá ngắn'; end if;

  select a.id, a.organization_id, a.initial_date, a.lock_date, a.quick_default_building_id
    into v_acct from public.accounts a
   where a.id=p_cashbook_id and a.deleted_at is null for update;
  if not found then raise exception 'Không tìm thấy sổ quỹ' using errcode='42501'; end if;
  v_org := v_acct.organization_id;
  if v_org is null then raise exception 'Sổ quỹ chưa gắn tổ chức' using errcode='23514'; end if;
  -- income_expenses.building_id is NOT NULL; an adjustment must be attributed to
  -- a building. Use the cashbook's default building, else the org's first one.
  if v_acct.quick_default_building_id is null then
    select id into v_acct.quick_default_building_id from public.buildings
     where organization_id=v_org and deleted_at is null order by created_at limit 1;
    if v_acct.quick_default_building_id is null then
      raise exception 'Không có toà nhà để ghi phiếu điều chỉnh' using errcode='55000'; end if;
  end if;

  -- exact permission cashbooks.post (requires possession) on this cashbook.
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'cashbooks.post', null, p_cashbook_id);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền điều chỉnh sổ quỹ (cashbooks.post + possession)' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object('cb',p_cashbook_id,'org',v_org,'delta',p_delta)::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_cashbook_id::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_cashbook_id::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer điều chỉnh sổ quỹ chưa bật' using errcode='55000'; end if;

  -- get-or-create the adjustment type; post a compensating voucher.
  select id into v_type from public.income_expense_types
   where organization_id=v_org and name='Điều chỉnh số dư đầu kỳ'
     and lower(coalesce(type,'income')) = case when p_delta > 0 then 'income' else 'expense' end
   limit 1;
  if v_type is null then
    insert into public.income_expense_types (organization_id, name, type)
    values (v_org, 'Điều chỉnh số dư đầu kỳ', case when p_delta>0 then 'income' else 'expense' end)
    returning id into v_type;
  end if;

  insert into public.income_expenses
    (user_id, organization_id, type, name, account_id, building_id, voucher_date,
     approval_status, approved_by, approved_at, notes)
  values (v_actor, v_org, case when p_delta>0 then 'INCOME' else 'EXPENSE' end,
          'Điều chỉnh số dư đầu kỳ', p_cashbook_id, v_acct.quick_default_building_id,
          greatest(v_acct.initial_date, coalesce(v_acct.lock_date, v_acct.initial_date) + 1),
          'APPROVED', v_actor, now(), 'Điều chỉnh: ' || p_reason)
  returning id into v_voucher;
  insert into public.income_expense_items
    (income_expense_id, organization_id, income_expense_type_id, description, quantity, unit_price)
  values (v_voucher, v_org, v_type, 'Điều chỉnh số dư đầu kỳ', 1, abs(p_delta));

  v_resp := json_build_object('adjustment_voucher_id', v_voucher, 'delta', p_delta);
  update app_private.canonical_write_operations
     set subject_id=v_voucher, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op and subject_scope=p_cashbook_id::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: request_paid_leave(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_paid_leave(p_date date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cfg JSONB := public.get_salary_v5_config();
  v_month DATE := date_trunc('month', p_date)::date;
  v_quota INT := COALESCE((v_cfg->'attendance_v5'->>'paid_leave_days_per_month')::int, 1);
  v_used INT;
  v_owner UUID := (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1);
  v_cur TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập'; END IF;
  IF p_date < public.vn_local_date(now()) THEN
    RAISE EXCEPTION 'Chỉ xin phép cho hôm nay hoặc ngày tới';
  END IF;
  IF EXTRACT(dow FROM p_date) = 0 THEN
    RAISE EXCEPTION 'Chủ nhật đã là ngày nghỉ — không cần xin phép';
  END IF;
  SELECT COUNT(*) INTO v_used FROM public.salary_attendance_day
  WHERE user_id = v_uid AND status IN ('leave_approved','pending_leave')
    AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;
  IF v_used >= v_quota THEN
    RAISE EXCEPTION 'Đã dùng hết % ngày phép có lương của tháng này', v_quota;
  END IF;

  SELECT status INTO v_cur FROM public.salary_attendance_day WHERE user_id = v_uid AND work_date = p_date;
  IF v_cur = 'ticked' THEN RAISE EXCEPTION 'Ngày này đã có ngày công rồi'; END IF;
  IF v_cur IN ('leave_approved','pending_leave') THEN
    RETURN jsonb_build_object('status', v_cur, 'date', p_date); -- idempotent
  END IF;

  INSERT INTO public.salary_attendance_day (user_id, work_date, status, evidence, audit)
  VALUES (v_uid, p_date, 'pending_leave',
          jsonb_build_array(jsonb_build_object('at', now(), 'kind', 'leave_request', 'reason', p_reason)),
          jsonb_build_array(jsonb_build_object('at', now(), 'by', v_uid, 'action', 'request_leave')))
  ON CONFLICT (user_id, work_date) DO UPDATE SET
    status = 'pending_leave',
    evidence = salary_attendance_day.evidence || jsonb_build_array(jsonb_build_object('at', now(), 'kind', 'leave_request', 'reason', p_reason)),
    audit = salary_attendance_day.audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', v_uid, 'action', 'request_leave')),
    updated_at = now();

  -- báo chủ (auto-nhắc lại sau 24h do digest đảm nhiệm)
  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES (v_owner, 'CUSTOM', 'IN_APP', 'PENDING', 'Xin phép nghỉ có lương',
          (SELECT COALESCE(full_name, 'Nhân viên') FROM public.profiles WHERE id = v_uid) || ' xin phép ngày ' || to_char(p_date, 'DD/MM') || COALESCE(' — ' || p_reason, ''),
          jsonb_build_object('v5', 'leave_request', 'staff_id', v_uid, 'date', p_date));

  RETURN jsonb_build_object('status', 'pending_leave', 'date', p_date, 'quota_left', v_quota - v_used - 1);
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, error_text, payload)
  VALUES (v_uid, 'request_paid_leave', SQLERRM, jsonb_build_object('date', p_date));
  RAISE;
END; $$;








--
-- Name: reserve_ai_usage(uuid, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_ai_usage(p_user_id uuid, p_feature text, p_provider text, p_model text, p_task_id text, p_est_cost_usd numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_day date := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_settings public.ai_copilot_settings%ROWTYPE;
  v_ent public.ai_copilot_entitlements%ROWTYPE;
  v_perms jsonb;
  v_owner uuid;
  v_sum numeric;
  v_id uuid;
  v_est numeric := GREATEST(COALESCE(p_est_cost_usd, 0), 0);
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'not_entitled'; END IF;
  IF p_feature NOT IN ('chat','ui_control') THEN RAISE EXCEPTION 'copilot_disabled'; END IF;

  -- Serialize mọi reservation trong ngày (VN) → cap user/tenant/global chính xác
  PERFORM pg_advisory_xact_lock(hashtext('ai_usage_reserve_' || v_day::text));

  -- a. Kill switch global
  SELECT * INTO v_settings FROM public.ai_copilot_settings WHERE id = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'copilot_disabled'; END IF;
  IF p_feature = 'chat' AND NOT v_settings.chat_enabled THEN RAISE EXCEPTION 'copilot_disabled'; END IF;
  IF p_feature = 'ui_control' AND NOT v_settings.ui_control_enabled THEN RAISE EXCEPTION 'copilot_disabled'; END IF;

  -- b. Entitlement opt-in (không có dòng = không được dùng)
  SELECT * INTO v_ent FROM public.ai_copilot_entitlements WHERE user_id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_entitled'; END IF;
  IF p_feature = 'chat' AND NOT v_ent.chat_enabled THEN RAISE EXCEPTION 'not_entitled'; END IF;
  IF p_feature = 'ui_control' AND NOT v_ent.ui_control_enabled THEN RAISE EXCEPTION 'not_entitled'; END IF;

  -- c. Permission (granular cho staff; owner sentinel pass — entitlement mới là gate thật)
  v_perms := public.ai_copilot_perms_for(p_user_id);
  IF NOT (v_perms ? '__superadmin') THEN
    IF p_feature = 'chat' AND COALESCE(v_perms->'ai_copilot'->>'view','') <> 'true' THEN
      RAISE EXCEPTION 'not_permitted';
    END IF;
    IF p_feature = 'ui_control' AND COALESCE(v_perms->'ai_copilot'->>'ui_control','') <> 'true' THEN
      RAISE EXCEPTION 'not_permitted';
    END IF;
  END IF;

  -- d. Mark expired: pending quá 5' → 'expired' (VẪN tính quota đến hết ngày)
  UPDATE public.ai_usage_logs SET status = 'expired'
  WHERE status = 'pending' AND created_at < now() - interval '5 minutes';

  -- e. Rate limit theo user (mọi request 60s gần nhất, kể cả lỗi)
  IF (SELECT count(*) FROM public.ai_usage_logs
      WHERE user_id = p_user_id AND created_at > now() - interval '60 seconds')
     >= v_settings.rate_per_min THEN
    RAISE EXCEPTION 'rate_limited';
  END IF;

  -- f. Resolve owner (tenant): staff → owner đầu tiên (full-scope ưu tiên); owner → chính mình
  SELECT sa.user_id INTO v_owner
  FROM public.staff_assignments sa
  WHERE sa.staff_id = p_user_id AND sa.user_id <> p_user_id
  ORDER BY (sa.building_id IS NULL) DESC, sa.created_at ASC
  LIMIT 1;
  IF v_owner IS NULL THEN v_owner := p_user_id; END IF;

  -- g. Quota 3 cấp (ngày VN; cost = COALESCE(cost thật, reserved); pending+expired đều tính; so sánh >=)
  SELECT COALESCE(sum(COALESCE(cost_usd, reserved_cost_usd)), 0) INTO v_sum
  FROM public.ai_usage_logs
  WHERE user_id = p_user_id AND (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_day;
  IF v_sum + v_est >= v_settings.daily_usd_cap_user AND v_settings.daily_usd_cap_user > 0 THEN
    RAISE EXCEPTION 'daily_quota';
  END IF;

  SELECT COALESCE(sum(COALESCE(cost_usd, reserved_cost_usd)), 0) INTO v_sum
  FROM public.ai_usage_logs
  WHERE owner_id = v_owner AND (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_day;
  IF v_sum + v_est >= v_settings.daily_usd_cap_tenant AND v_settings.daily_usd_cap_tenant > 0 THEN
    RAISE EXCEPTION 'daily_quota';
  END IF;

  SELECT COALESCE(sum(COALESCE(cost_usd, reserved_cost_usd)), 0) INTO v_sum
  FROM public.ai_usage_logs
  WHERE (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_day;
  IF v_sum + v_est >= v_settings.daily_usd_cap_global AND v_settings.daily_usd_cap_global > 0 THEN
    RAISE EXCEPTION 'daily_quota';
  END IF;

  -- h. Insert pending reservation
  INSERT INTO public.ai_usage_logs
    (user_id, owner_id, provider, model, feature, task_id, reserved_cost_usd, status)
  VALUES
    (p_user_id, v_owner, p_provider, p_model, p_feature, p_task_id, v_est, 'pending')
  RETURNING id INTO v_id;

  RETURN v_id;
END $$;








--
-- Name: resolve_fixed_expense_type(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_fixed_expense_type(p_owner uuid, p_category_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_type uuid;
  v_name text;
  v_category text;
  v_organization_id uuid;
BEGIN
  IF p_category_key NOT IN (
    'tien_nha', 'dien', 'nuoc', 'internet', 'quan_ly',
    've_sinh', 'cong_an', 'rac', 'thang_may'
  ) THEN
    RAISE EXCEPTION 'Hạng mục phí không hợp lệ: %', p_category_key
      USING ERRCODE = '23514';
  END IF;

  v_organization_id := app_private.resolve_ie_type_org_for_user_v1(p_owner);

  SELECT type_row.id
    INTO v_type
  FROM public.income_expense_types type_row
  WHERE type_row.organization_id = v_organization_id
    AND lower(btrim(type_row.type)) = 'expense'
    AND public.fee_type_matches(
      p_category_key,
      type_row.category,
      type_row.name
    )
  ORDER BY
    COALESCE(type_row.is_default, false) DESC,
    type_row.created_at,
    type_row.id
  LIMIT 1;

  IF v_type IS NOT NULL THEN
    RETURN v_type;
  END IF;

  v_name := CASE p_category_key
    WHEN 'tien_nha'  THEN 'Tiền nhà'
    WHEN 'dien'      THEN 'Đóng tiền điện'
    WHEN 'nuoc'      THEN 'Đóng tiền nước'
    WHEN 'internet'  THEN 'Internet'
    WHEN 'quan_ly'   THEN 'Quản Lý'
    WHEN 've_sinh'   THEN 'Vệ sinh tòa nhà định kỳ'
    WHEN 'cong_an'   THEN 'Công an'
    WHEN 'rac'       THEN 'Tiền rác'
    WHEN 'thang_may' THEN 'Bảo trì thang máy'
  END;
  v_category := CASE p_category_key
    WHEN 'tien_nha'  THEN 'Tiền nhà'
    WHEN 'dien'      THEN 'Điện'
    WHEN 'nuoc'      THEN 'Nước'
    WHEN 'internet'  THEN 'Internet'
    WHEN 'quan_ly'   THEN 'Quản Lý'
    WHEN 've_sinh'   THEN 'Vệ sinh'
    WHEN 'cong_an'   THEN 'Công an'
    WHEN 'rac'       THEN 'Rác'
    WHEN 'thang_may' THEN 'Bảo Trì Thang Máy'
  END;

  RETURN app_private.ensure_income_expense_type_v1(
    p_organization_id => v_organization_id,
    p_user_id => p_owner,
    p_name => v_name,
    p_type => 'expense',
    p_category => v_category,
    p_is_restricted => (p_category_key = 'quan_ly')
  );
END
$$;








--
-- Name: restore_income_expense(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_income_expense(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_rec record; v_amount numeric(15,2); v_payment_id uuid;
  v_existing_payment uuid; v_actor_name text; v_note text; v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'Bạn chưa đăng nhập' using errcode='42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Chỉ Super Admin mới được khôi phục phiếu đã huỷ' using errcode='42501';
  end if;
  select id, type, invoice_id, payment_id, approval_status,
         voucher_date, total_amount, user_id, organization_id
    into v_rec from public.income_expenses where id = p_id;
  if not found then raise exception 'Không tìm thấy phiếu' using errcode='P0002'; end if;
  if exists (select 1 from public.income_expenses x where x.id = p_id and x.cancellation_kind = 'CANCELLED_AFTER_POSTING') then
    raise exception 'Phiếu đã chi rồi mới huỷ — không khôi phục được vì bút toán đã đảo về sổ. Hãy lập phiếu mới.' using errcode = '55000';
  end if;
  if v_rec.approval_status <> 'CANCELLED' then
    raise exception 'Phiếu không ở trạng thái Đã huỷ' using errcode='P0001'; end if;
  v_org := v_rec.organization_id;

  update public.income_expenses
     set approval_status='APPROVED', approved_by=auth.uid(), approved_at=now()
   where id = p_id;

  if v_rec.type='INCOME' and v_rec.invoice_id is not null and v_rec.payment_id is null then
    v_amount := coalesce(v_rec.total_amount,0);
    select id into v_existing_payment from public.payments
     where invoice_id=v_rec.invoice_id and amount=v_amount and payment_date=v_rec.voucher_date
     limit 1;
    if v_existing_payment is not null then
      v_payment_id := v_existing_payment;
    elsif v_amount > 0 then
      insert into public.payments (user_id, invoice_id, amount, payment_method, payment_date, notes)
      values (v_rec.user_id, v_rec.invoice_id, v_amount, 'TM', v_rec.voucher_date,
              'Khôi phục từ phiếu thu đã huỷ')
      returning id into v_payment_id;
    end if;
    if v_payment_id is not null then
      update public.income_expenses set payment_id=v_payment_id where id=p_id;
    end if;
  end if;

  select full_name into v_actor_name from public.profiles where id=auth.uid();
  v_note := case when v_payment_id is not null
                 then 'Khôi phục phiếu + phục hồi thanh toán hoá đơn'
                 else 'Khôi phục phiếu' end;
  -- chained audit (was a direct INSERT that the monopoly guard now rejects)
  if v_org is not null then
    perform app_private.append_income_expense_event_v1(
      v_org, p_id, 'RESTORED', auth.uid(), coalesce(v_actor_name,'Người dùng'),
      'CANCELLED', 'APPROVED', v_note);
  end if;

  return jsonb_build_object('id', p_id, 'restored_payment_id', v_payment_id);
end;
$$;








--
-- Name: restore_invoice_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_invoice_v1(p_invoice_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to restore invoice'
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = p_invoice_id
  ) THEN
    RAISE EXCEPTION 'Use restore_invoice_with_credit_v1 for this invoice'
      USING ERRCODE = '55000';
  END IF;
  IF v_invoice.status <> 'CANCELLED' THEN
    RAISE EXCEPTION 'Only cancelled invoices can be restored'
      USING ERRCODE = '55000';
  END IF;
  UPDATE public.invoices
     SET status = 'APPROVED',
         approved_at = clock_timestamp(),
         approved_by = v_actor
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  RETURN v_invoice;
END;
$$;








--
-- Name: restore_invoice_with_credit_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_invoice_with_credit_v1(p_invoice_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_active_count integer;
  v_restore_amount numeric(15,2);
  v_restore_fingerprint text;
  v_apply_key text;
  v_credit jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to restore invoice'
      USING ERRCODE = '42501';
  END IF;
  IF v_invoice.status = 'APPROVED' THEN
    RETURN jsonb_build_object(
      'invoice', to_jsonb(v_invoice),
      'credit', NULL,
      'noop', true
    );
  END IF;
  IF v_invoice.status <> 'CANCELLED' THEN
    RAISE EXCEPTION 'Only cancelled invoices can be restored'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_active_count
  FROM public.customer_credit_applications application_row
  WHERE application_row.invoice_id = p_invoice_id
    AND application_row.reversed_at IS NULL;

  SELECT COALESCE(sum(application_row.amount), 0)::numeric(15,2),
         md5(COALESCE(string_agg(
           application_row.id::text, ',' ORDER BY application_row.id
         ), ''))
    INTO v_restore_amount, v_restore_fingerprint
  FROM public.customer_credit_applications application_row
  WHERE application_row.invoice_id = p_invoice_id
    AND application_row.reversed_at IS NOT NULL
    AND application_row.restored_at IS NULL;

  IF v_active_count > 0 AND v_restore_amount > 0 THEN
    RAISE EXCEPTION 'Invoice has mixed active and pending-restoration credit applications'
      USING ERRCODE = '55000';
  END IF;

  IF v_restore_amount > 0 THEN
    IF v_contract_id IS NULL THEN
      RAISE EXCEPTION 'Credit invoice has no contract' USING ERRCODE = '55000';
    END IF;
    v_apply_key := left(v_key, 150) || ':cycle:' || v_restore_fingerprint;
    v_credit := app_private.apply_customer_credit_fifo_v1(
      v_actor, v_contract_id, v_restore_amount, p_invoice_id,
      'INVOICE_DISCOUNT',
      'Reapply customer credit while restoring invoice', v_apply_key
    );
  ELSE
    v_credit := jsonb_build_object(
      'invoice_id', p_invoice_id,
      'applied_amount', 0,
      'applications', '[]'::jsonb
    );
  END IF;

  PERFORM app_private.begin_accounting_chain_write_v1();
  IF v_restore_amount > 0 THEN
    UPDATE public.customer_credit_applications
       SET restored_at = clock_timestamp(),
           restored_by = v_actor,
           restoration_idempotency_key = v_apply_key
     WHERE invoice_id = p_invoice_id
       AND reversed_at IS NOT NULL
       AND restored_at IS NULL;
  END IF;

  UPDATE public.invoices
     SET status = 'APPROVED',
         approved_at = clock_timestamp(),
         approved_by = v_actor
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice', to_jsonb(v_invoice),
    'credit', v_credit,
    'noop', false
  );
END;
$_$;








--
-- Name: resubmit_income_expense_v2(uuid, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resubmit_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_patch jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'p', p_patch)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.resubmit.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');

  -- Only the original maker resubmits after changes were requested.
  IF v_ie.maker_user_id IS NULL OR v_ie.maker_user_id <> v_uid THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: only the original maker may resubmit' USING ERRCODE = '42501';
  END IF;
  IF v_ie.approval_status <> 'UNAPPROVED' OR v_ie.review_state <> 'CHANGES_REQUESTED' THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: only a CHANGES_REQUESTED voucher can be resubmitted (%, %)',
      v_ie.approval_status, v_ie.review_state USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: review_version mismatch' USING ERRCODE = '55000';
  END IF;
  -- Guard: no PENDING request may remain open before a fresh submission.
  IF EXISTS (SELECT 1 FROM public.approval_requests ar
             WHERE ar.organization_id = v_ie.organization_id
               AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
               AND ar.state = 'PENDING_APPROVAL') THEN
    RAISE EXCEPTION 'resubmit_income_expense_v2: an open approval request already exists' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET review_state = 'PENDING', review_reason = NULL, change_field_mask = NULL,
         review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'UNAPPROVED',
                               'reviewState', 'PENDING', 'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.resubmit.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'RESUBMITTED', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.resubmit.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION resubmit_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_patch jsonb, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resubmit_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_patch jsonb, p_idempotency_key text) IS 'Plan §5.3/§7.4: resubmit after CHANGES_REQUESTED -> new review submission back to PENDING.';








--
-- Name: revenue_by_month(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_by_month(p_start date, p_end date, p_building_id uuid DEFAULT NULL::uuid) RETURNS TABLE(month_start date, revenue numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT
    date_trunc('month', entry.revenue_date)::date AS month_start,
    COALESCE(sum(entry.pnl_amount), 0) AS revenue
  FROM public.invoice_pnl_cash_entries entry
  WHERE entry.revenue_date >= p_start
    AND entry.revenue_date <= p_end
    AND (p_building_id IS NULL OR entry.building_id = p_building_id)
  GROUP BY 1
  ORDER BY 1;
$$;








--
-- Name: FUNCTION revenue_by_month(p_start date, p_end date, p_building_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revenue_by_month(p_start date, p_end date, p_building_id uuid) IS 'Doanh thu P&L gắn hoá đơn gộp theo tháng (chart Dashboard) — security invoker, RLS như đường fetch cũ.';








