--
-- Name: reverse_invoice_collection_v5(uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_invoice_collection_v5(p_collection_id uuid, p_reversal_date date, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_collection public.invoice_payment_collections%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_org uuid;
  v_authz boolean;
  v_route text;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_tender public.invoice_payment_tenders%ROWTYPE;
  v_allocation record;
  v_reversal_voucher_id uuid;
  v_reversal_item_id uuid;
  v_expense_type_id uuid;
  v_credit_lot public.customer_credit_lots%ROWTYPE;
  v_response jsonb;
  v_reversal_vouchers jsonb := '[]'::jsonb;
  -- Đợt 5
  v_in_place boolean := false;
  v_membership uuid;
  v_block text;
  v_rev_posting uuid;
  v_mode text;
  -- WP2_UNDO_VISIBLE_BOOK: chủ tổ chức / super admin đi thẳng, người còn
  -- lại phải có ÍT NHẤT quan hệ "được nhìn sổ" với từng sổ quỹ nguồn.
  v_book_bypass boolean := false;
  v_tender_building uuid;
  v_book_name text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'idempotency_key không hợp lệ' USING ERRCODE = '22023';
  END IF;
  IF p_reversal_date IS NULL OR char_length(v_reason) NOT BETWEEN 8 AND 1000 THEN
    RAISE EXCEPTION 'Ngày hoàn tác hoặc lý do 8-1000 ký tự không hợp lệ'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_collection
  FROM public.invoice_payment_collections
  WHERE id = p_collection_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy collection' USING ERRCODE = '42501';
  END IF;
  IF p_reversal_date < v_collection.collection_date THEN
    RAISE EXCEPTION 'Reversal date cannot be earlier than collection date'
      USING ERRCODE = '22023';
  END IF;
  -- Cận TRÊN: ngày hoàn tác nằm ở tương lai sẽ đóng băng một con số chưa
  -- xảy ra vào invoice_payment_collections.reversal_date và làm mọi báo cáo
  -- theo kỳ đọc sai. 2099-12-31 từng được nhận.
  IF p_reversal_date > CURRENT_DATE THEN
    RAISE EXCEPTION 'Ngày hoàn tác không được ở tương lai (hôm nay là %)', to_char(CURRENT_DATE, 'DD/MM/YYYY')
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = v_collection.invoice_id
  FOR UPDATE;

  SELECT building_row.organization_id INTO v_org
  FROM public.buildings building_row
  JOIN public.organizations organization_row
    ON organization_row.id = building_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE building_row.id = v_invoice.building_id
    AND building_row.deleted_at IS NULL
  FOR SHARE OF building_row, organization_row;
  IF v_org IS NULL
     OR v_invoice.organization_id <> v_org
     OR v_collection.organization_id <> v_org THEN
    RAISE EXCEPTION 'Collection không thuộc tổ chức hợp lệ' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);

  -- ĐỢT A (vá sau audit): gate 'thu_tien.undo' bị bỏ kéo theo việc mất luôn
  -- cửa kiểm THÀNH VIÊN, vì authorize_tenant_action_v3 vốn từ chối bằng
  -- MEMBERSHIP_INACTIVE_OR_MISSING. Hệ quả: nhân viên đã bị gỡ khỏi tổ chức
  -- vẫn khớp nhánh "chính người đã thu" (user_id trên phiếu cũ không đổi) và
  -- hoàn tác được khoản thu cũ — JWT Supabase không bị thu hồi khi gỡ
  -- membership. Khôi phục ĐÚNG điều kiện "còn là người của tổ chức", không
  -- khôi phục gate quyền (giữ quyết định #8).
  IF NOT public.is_super_admin() AND NOT EXISTS (
    SELECT 1 FROM public.organization_memberships m0
     WHERE m0.user_id = v_actor AND m0.organization_id = v_org
       AND m0.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Bạn không còn thuộc tổ chức này nên không hoàn tác được khoản thu.'
      USING ERRCODE = '42501';
  END IF;
  -- ĐỢT A: luật huỷ thống nhất (quyết định #8 của chủ 01/08/2026) — huỷ
  -- khoản thu KHÔNG còn hỏi quyền 'thu_tien.undo'. Điều kiện duy nhất là
  -- CHÍNH NGƯỜI ĐÃ THU (hoặc chủ tổ chức / super admin), kiểm ở vòng tender
  -- bên dưới. Cùng một luật cho cả trang Thu tiền lẫn trang Thu chi.

  v_hash := md5(jsonb_build_object(
    'collection_id', p_collection_id,
    'reversal_date', p_reversal_date,
    'reason', v_reason
  )::text);

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash
  ) VALUES (
    v_org, 'invoice.collection.reverse.v5',
    p_collection_id::text, v_actor, v_key, v_hash
  ) ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
    DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'invoice.collection.reverse.v5'
    AND operation_row.subject_scope = p_collection_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;

  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key đã dùng với nội dung khác' USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  v_route := app_private.evaluate_feature_route('invoice.collection.reverse.v5', v_org);
  IF v_route = 'FROZEN' THEN
    RAISE EXCEPTION 'Writer hoàn tác invoice.collection.v5 đang bị đóng băng'
      USING ERRCODE = '55000';
  ELSIF v_route <> 'CANONICAL' THEN
    RAISE EXCEPTION 'Writer hoàn tác invoice.collection.v5 chưa bật'
      USING ERRCODE = '55000';
  END IF;

  IF v_collection.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'Collection đã được hoàn tác' USING ERRCODE = '23505';
  END IF;

  -- Allocation is revenue-first then deposit. Reversing an older collection
  -- would leave newer allocation rows attached to the wrong accounting class.
  IF abs(
    COALESCE(v_invoice.paid_amount, 0)
    - (v_collection.expected_paid_amount + v_collection.applied_amount)
  ) >= 0.01 THEN
    RAISE EXCEPTION 'Phải hoàn tác khoản thu mới hơn trước (thứ tự LIFO)'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_credit_lot
  FROM public.customer_credit_lots lot
  WHERE lot.source_collection_id = p_collection_id
  FOR UPDATE;
  IF FOUND AND v_credit_lot.remaining_amount <> v_credit_lot.amount THEN
    RAISE EXCEPTION 'Credit của collection đã được sử dụng; phải unwind trước khi hoàn tác'
      USING ERRCODE = '55000';
  END IF;

  -- ══ ĐỢT 5: chọn đường ═════════════════════════════════════════════
  -- Chế độ linh hoạt → huỷ tại chỗ. Nhưng kỳ đã đóng thì DỪNG HẲN, không
  -- lặng lẽ rơi về đường sinh phiếu đối ứng: một khoản tiền rời khỏi tháng đã
  -- chia lợi nhuận cho cổ đông phải là quyết định có người ký.
  v_in_place := true;  -- ĐỢT A: phiếu thu luôn huỷ tại chỗ (quyết định #3)

  -- KIỂM KỲ CHO CẢ HAI CHẾ ĐỘ: kỳ đã đóng thì KHÔNG đường nào được đụng,
  -- kể cả đường sinh phiếu đối ứng của chế độ Chuẩn kế toán.
  SELECT m.id INTO v_membership FROM public.organization_memberships m
     WHERE m.user_id = v_actor AND m.organization_id = v_org AND m.status = 'ACTIVE'
     LIMIT 1;
  v_book_bypass := public.is_super_admin()
                   OR app_private.is_org_owner_v1(v_org, v_actor);

    FOR v_tender IN
      SELECT * FROM public.invoice_payment_tenders
      WHERE collection_id = p_collection_id
      ORDER BY line_index
    LOOP
      CONTINUE WHEN v_tender.voucher_id IS NULL;
      v_block := app_private.period_block_code_v1(v_tender.voucher_id);
      IF v_block IS NOT NULL THEN
        RAISE EXCEPTION '%',
          CASE v_block
            WHEN 'PROFIT_LOCKED' THEN
              '[PROFIT_LOCKED] Lợi nhuận của tháng chứa khoản thu này đã chốt và đã chia cho cổ đông — hệ thống không tự huỷ khoản thu của tháng đó. Nếu thật sự cần điều chỉnh, hãy liên hệ quản trị để lập phiếu chi đối ứng ở kỳ hiện tại.'
            WHEN 'CASHBOOK_CLOSED' THEN
              '[CASHBOOK_CLOSED] Sổ quỹ chứa khoản thu này đã chốt & bàn giao — kỳ đó khoá vĩnh viễn. Nếu thật sự cần điều chỉnh, hãy liên hệ quản trị để lập phiếu chi đối ứng ở kỳ hiện tại.'
            WHEN 'HANDOVER_LOCKED' THEN
              '[HANDOVER_LOCKED] Phiếu thu này nằm trong một phiên bàn giao đã xác nhận — phải huỷ phiên đó trước (cần cả hai bên đồng ý).'
            ELSE
              '[PERIOD_CLOSED] Kỳ kế toán của khoản thu này đã đóng nên không huỷ được. Nếu thật sự cần điều chỉnh, hãy liên hệ quản trị để lập phiếu chi đối ứng ở kỳ hiện tại.'
          END
          USING ERRCODE = 'P0001';
      END IF;
    END LOOP;

  -- Đường CŨ cần hạng mục "Hoàn tác thu tiền"; đường huỷ tại chỗ thì không,
  -- và cố ý KHÔNG tạo hạng mục rác cho tổ chức chưa từng dùng nó.
  IF NOT v_in_place THEN
    SELECT type_row.id INTO v_expense_type_id
    FROM public.income_expense_types type_row
    WHERE type_row.organization_id = v_collection.organization_id
      AND lower(type_row.type) = 'expense'
      AND lower(btrim(type_row.name)) = 'hoàn tác thu tiền'
    LIMIT 1 FOR SHARE;
    IF v_expense_type_id IS NULL THEN
      INSERT INTO public.income_expense_types (
        organization_id, user_id, name, type, description, is_default, is_deposit
      ) VALUES (
        v_collection.organization_id, v_invoice.user_id,
        'Hoàn tác thu tiền', 'expense',
        'Bút toán đối ứng cho collection đã hoàn tác', false, false
      ) RETURNING id INTO v_expense_type_id;
    END IF;
  END IF;

  PERFORM app_private.begin_accounting_chain_write_v1();

  FOR v_tender IN
    SELECT * FROM public.invoice_payment_tenders
    WHERE collection_id = p_collection_id
    ORDER BY line_index
    FOR UPDATE
  LOOP
    IF v_tender.voucher_id IS NULL THEN
      CONTINUE;
    END IF;

    -- B: toà của CHÍNH tender này (phiếu thu của tender), không phải toà
    -- của hoá đơn. Một collection nhiều tender có thể bắc qua nhiều toà.
    SELECT tender_voucher.building_id INTO v_tender_building
    FROM public.income_expenses tender_voucher WHERE tender_voucher.id = v_tender.voucher_id;
    v_tender_building := COALESCE(v_tender_building, v_invoice.building_id);

    -- ĐỢT A: bỏ gate quyền theo sổ quỹ nguồn (quyết định #8).

    -- A (WP2_UNDO_VISIBLE_BOOK): quyền thôi chưa đủ. Một override cấp
    -- ORGANIZATION phủ MỌI sổ, kể cả sổ người này không giữ, không biết,
    -- không được chia sẻ. Chủ chốt "với việc thu chỉ cần biết sổ là được".
    -- ĐỢT A: bỏ gate "sổ được nhìn" (quyết định #8) — danh tính người thu
    -- đã là điều kiện đủ; không bắt thêm quan hệ với sổ quỹ.

    -- Chỉ CHÍNH NGƯỜI ĐÃ THU được hoàn tác khoản thu đó (yêu cầu của chủ
    -- 30/07). Chủ tổ chức / super admin giữ cửa phụ, nếu không thì khoản
    -- thu của nhân viên đã nghỉ là bất khả hoàn tác vĩnh viễn.
    IF NOT public.is_super_admin()
       AND NOT app_private.is_org_owner_v1(v_collection.organization_id, v_actor)
       AND NOT EXISTS (SELECT 1 FROM public.income_expenses src
                        WHERE src.id = v_tender.voucher_id AND src.user_id = v_actor) THEN
      RAISE EXCEPTION 'Chỉ người đã thu khoản này mới hoàn tác được. Nhờ người thu hoặc chủ tổ chức thực hiện.'
        USING ERRCODE = '42501';
    END IF;

    IF v_in_place THEN
      -- ── HUỶ TẠI CHỖ: không sinh phiếu nào ──────────────────────────
      v_rev_posting := app_private.cancel_collection_voucher_in_place_v1(
        v_tender.voucher_id, v_reason, v_actor, v_membership);
      v_reversal_voucher_id := v_tender.voucher_id;

      v_reversal_vouchers := v_reversal_vouchers || jsonb_build_array(jsonb_build_object(
        'source_voucher_id', v_tender.voucher_id,
        'reversal_voucher_id', NULL,
        'reversal_posting_id', v_rev_posting,
        'mode', 'IN_PLACE_CANCEL',
        'account_id', v_tender.account_id,
        'amount', v_tender.retained_amount
      ));
    ELSE
      -- ── ĐƯỜNG CŨ: sinh phiếu chi đối ứng (chế độ Chuẩn kế toán) ────
      INSERT INTO public.income_expenses (
        user_id, organization_id, type, name, building_id, room_id, contract_id,
        account_id, invoice_id, payment_collection_id, reversal_of_income_expense_id,
        voucher_date, total_amount, approval_status, approved_by, approved_at,
        notes, business_result_accounting, creator_name, system_source,
        idempotency_key, change_amount, change_account_id,
        rounding_amount, rounding_account_id
      ) VALUES (
        v_invoice.user_id, v_collection.organization_id, 'EXPENSE',
        'Hoàn tác thu tiền ' || COALESCE(v_invoice.invoice_number, ''),
        v_invoice.building_id, v_invoice.room_id, v_invoice.contract_id,
        v_tender.account_id, NULL, p_collection_id, v_tender.voucher_id,
        p_reversal_date, v_tender.retained_amount, 'APPROVED', v_actor,
        clock_timestamp(), v_reason, NULL, 'Invoice Collection V5',
        'invoice.collection.reverse.v5', v_key || ':tender:' || v_tender.line_index,
        -v_tender.change_amount, v_tender.change_account_id,
        -v_tender.rounding_amount, v_tender.rounding_account_id
      ) RETURNING id INTO v_reversal_voucher_id;

      FOR v_allocation IN
        SELECT allocation.accounting_class, allocation.amount
        FROM public.invoice_payment_allocations allocation
        WHERE allocation.tender_id = v_tender.id
        ORDER BY allocation.id
      LOOP
        INSERT INTO public.income_expense_items (
          income_expense_id, organization_id, income_expense_type_id, description,
          quantity, unit_price, amount, start_date, end_date, accounting_class
        ) VALUES (
          v_reversal_voucher_id, v_collection.organization_id, v_expense_type_id,
          CASE v_allocation.accounting_class
            WHEN 'PNL' THEN 'Hoàn tác doanh thu hóa đơn'
            WHEN 'DEPOSIT' THEN 'Hoàn tác tiền cọc'
            WHEN 'CUSTOMER_CREDIT' THEN 'Hoàn tác credit khách hàng'
            ELSE 'Hoàn tác khoản ngoài KQKD'
          END,
          1, v_allocation.amount, v_allocation.amount,
          p_reversal_date, p_reversal_date, v_allocation.accounting_class
        ) RETURNING id INTO v_reversal_item_id;
      END LOOP;

      INSERT INTO app_private.income_expense_flow_ownership (
        income_expense_id, organization_id, flow_kind, flow_version,
        lifecycle_owner, lifecycle_state, writer_operation,
        payload_hash_scheme, payload_hash_value, maker_user_id,
        claimed_by_user_id, correlation_id
      ) VALUES (
        v_reversal_voucher_id, v_collection.organization_id,
        'INVOICE_COLLECTION_REVERSAL_V5', 5,
        'INVOICE_COLLECTION_V5', 'APPROVED', 'invoice.collection.reverse.v5',
        'PG_MD5_JSONB_TEXT_V1', v_hash, v_actor, v_actor, p_collection_id
      ) ON CONFLICT (income_expense_id) DO NOTHING;

      v_reversal_vouchers := v_reversal_vouchers || jsonb_build_array(jsonb_build_object(
        'source_voucher_id', v_tender.voucher_id,
        'reversal_voucher_id', v_reversal_voucher_id,
        'mode', 'COUNTER_VOUCHER',
        'account_id', v_tender.account_id,
        'amount', v_tender.retained_amount
      ));
    END IF;

    -- Hai lệnh dưới đây gánh TIỀN THẬT và phải chạy ở CẢ HAI đường:
    -- recompute_invoice_for_id đọc public.payments (reversed_at IS NULL) chứ
    -- không đọc approval_status của phiếu.
    IF v_tender.payment_id IS NOT NULL THEN
      UPDATE public.payments
         SET reversed_at = clock_timestamp(),
             reversed_by_collection_id = p_collection_id,
             updated_at = now()
       WHERE id = v_tender.payment_id;

      INSERT INTO app_private.payment_reversals (
        original_payment_id, reversal_voucher_id, organization_id, actor_id, reason,
        reversal_kind
      ) VALUES (
        v_tender.payment_id, v_reversal_voucher_id,
        v_collection.organization_id, v_actor, v_reason,
        CASE WHEN v_in_place THEN 'IN_PLACE_CANCEL' ELSE 'COUNTER_VOUCHER' END
      ) ON CONFLICT (original_payment_id) DO NOTHING;
    END IF;
  END LOOP;

  IF v_credit_lot.id IS NOT NULL THEN
    UPDATE public.customer_credit_lots
       SET remaining_amount = 0, status = 'REVERSED', reversed_at = clock_timestamp()
     WHERE id = v_credit_lot.id;

    INSERT INTO public.excess_amounts (
      organization_id, user_id, contract_id, amount, description,
      source_invoice_id, source_payment_id, credit_lot_id
    ) VALUES (
      v_collection.organization_id, v_invoice.user_id, v_collection.contract_id,
      -v_credit_lot.amount, 'Hoàn tác credit collection',
      v_invoice.id, v_credit_lot.source_payment_id, v_credit_lot.id
    );
  END IF;

  UPDATE public.invoice_payment_collections
     SET status = 'REVERSED', reversed_at = clock_timestamp(), reversed_by = v_actor,
         reversal_date = p_reversal_date, reversal_reason = v_reason,
         reversal_idempotency_key = v_key
   WHERE id = p_collection_id;

  PERFORM public.recompute_invoice_for_id(v_invoice.id);
  PERFORM public.recompute_contract_deposit_paid(v_invoice.contract_id);

  v_mode := CASE WHEN v_in_place THEN 'IN_PLACE_CANCEL' ELSE 'COUNTER_VOUCHER' END;

  SELECT jsonb_build_object(
    'collection_id', p_collection_id,
    'status', 'REVERSED',
    'reversal_mode', v_mode,
    'reversal_date', p_reversal_date,
    'reversal_vouchers', v_reversal_vouchers,
    'invoice', to_jsonb(invoice_row)
  ) INTO v_response
  FROM public.invoices invoice_row
  WHERE invoice_row.id = v_invoice.id;

  UPDATE app_private.canonical_write_operations
     SET subject_id = p_collection_id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_collection.organization_id
     AND operation = 'invoice.collection.reverse.v5'
     AND subject_scope = p_collection_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;

  PERFORM app_private.end_accounting_chain_write_v1();
  RETURN v_response;
END;
$_$;








--
-- Name: reverse_invoice_payment_v3(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_invoice_payment_v3(p_payment_id uuid, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_collection_id uuid;
  v_org uuid;
  v_payment_date date;
  v_received_amount numeric;
  v_reversal_date date;
  v_tender_count integer;
  v_route text;
  v_result json;
  v_source_count integer;
  v_source_account_count integer;
  v_source_account uuid;
  v_source_voucher uuid;
  v_source_total numeric;
  v_reversal_voucher uuid;
  v_existing_source uuid;
  v_reversal_created_at timestamptz;
  v_reversal_type uuid;
  v_item record;
BEGIN
  SELECT payment.collection_id, building_row.organization_id,
         payment.payment_date, payment.received_amount
    INTO v_collection_id, v_org, v_payment_date, v_received_amount
  FROM public.payments payment
  JOIN public.invoices invoice ON invoice.id = payment.invoice_id
  JOIN public.buildings building_row
    ON building_row.id = invoice.building_id
   AND building_row.deleted_at IS NULL
   AND building_row.organization_id = invoice.organization_id
  JOIN public.organizations organization_row
    ON organization_row.id = building_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE payment.id = p_payment_id
  FOR SHARE OF building_row, organization_row;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy payment' USING ERRCODE = '42501';
  END IF;

  IF v_collection_id IS NULL THEN
    PERFORM app_private.lock_org_for_decision_v1(v_org);
    v_route := app_private.evaluate_feature_route('invoice.collection.reverse.v5', v_org);
    IF v_route = 'FROZEN' THEN
      RAISE EXCEPTION 'Writer hoàn tác thu tiền đang bị đóng băng'
        USING ERRCODE = '55000';
    END IF;
    IF to_regprocedure('public._reverse_invoice_payment_v3_legacy(uuid,text,text)') IS NULL THEN
      RAISE EXCEPTION 'Payment legacy chưa có writer hoàn tác tương thích'
        USING ERRCODE = '55000';
    END IF;

    IF v_received_amount IS NULL THEN
      RAISE EXCEPTION 'Payment legacy chưa được chuẩn hoá ngữ nghĩa thu tiền'
        USING ERRCODE = '55000';
    END IF;
    IF v_received_amount = 0 THEN
      RAISE EXCEPTION 'Đây là bút toán cấn trừ thanh lý, không phải khoản thu tiền để hoàn tác riêng'
        USING ERRCODE = '55000';
    END IF;

    WITH source_vouchers AS (
      SELECT voucher.id, voucher.account_id, voucher.created_at, 0 AS source_rank
      FROM public.income_expenses voucher
      WHERE voucher.payment_id = p_payment_id
        AND voucher.organization_id = v_org
        AND voucher.type = 'INCOME'
        AND voucher.approval_status = 'APPROVED'
        AND voucher.deleted_at IS NULL

      UNION ALL

      SELECT voucher.id, voucher.account_id, voucher.created_at, 1 AS source_rank
      FROM public.income_expenses voucher
      WHERE voucher.payment_id IS NULL
        AND voucher.organization_id = v_org
        AND voucher.type = 'INCOME'
        AND voucher.approval_status = 'APPROVED'
        AND voucher.deleted_at IS NULL
        AND voucher.notes = '[THU TACH COC ' || p_payment_id::text || ']'

      UNION ALL

      SELECT voucher.id, voucher.account_id, voucher.created_at, 2 AS source_rank
      FROM public.income_expenses voucher
      WHERE p_payment_id = '5b32cb16-b579-4427-bebf-108c5195a279'::uuid
        AND voucher.id = '2ea26ca0-92c6-4896-a7b5-a5ee7031b2cc'::uuid
        AND voucher.organization_id = v_org
        AND voucher.type = 'INCOME'
        AND voucher.approval_status = 'APPROVED'
        AND voucher.deleted_at IS NULL
    ), distinct_sources AS (
      SELECT DISTINCT ON (source.id)
        source.id, source.account_id, source.created_at, source.source_rank
      FROM source_vouchers source
      ORDER BY source.id, source.source_rank
    )
    SELECT
      count(*)::integer,
      count(DISTINCT source.account_id)::integer,
      (array_agg(source.account_id ORDER BY source.source_rank, source.created_at, source.id))[1],
      (array_agg(source.id ORDER BY source.source_rank, source.created_at, source.id))[1],
      COALESCE(sum(item.amount) FILTER (
        WHERE item.accounting_class IN ('PNL', 'DEPOSIT', 'CUSTOMER_CREDIT')
      ), 0)
      INTO v_source_count, v_source_account_count, v_source_account,
           v_source_voucher, v_source_total
    FROM distinct_sources source
    LEFT JOIN public.income_expense_items item
      ON item.income_expense_id = source.id;

    IF v_source_count < 1
       OR v_source_account_count <> 1
       OR v_source_account IS NULL
       OR abs(v_source_total - v_received_amount) >= 0.01 THEN
      RAISE EXCEPTION 'Nguồn kế toán payment legacy không đầy đủ hoặc không cân (% / %)',
        v_source_total, v_received_amount USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.accounts account_row
      WHERE account_row.id = v_source_account
        AND account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND NOT account_row.is_virtual
    ) THEN
      RAISE EXCEPTION 'Sổ nguồn payment legacy không hợp lệ hoặc là sổ ảo'
        USING ERRCODE = '55000';
    END IF;

    EXECUTE 'SELECT public._reverse_invoice_payment_v3_legacy($1,$2,$3)'
      INTO v_result USING p_payment_id, p_reason, p_idempotency_key;

    v_reversal_voucher := NULLIF(v_result->>'reversal_voucher_id', '')::uuid;
    IF v_reversal_voucher IS NULL THEN
      RAISE EXCEPTION 'Writer legacy không trả về reversal_voucher_id'
        USING ERRCODE = '55000';
    END IF;

    SELECT reversal.created_at, voucher.reversal_of_income_expense_id,
           voucher.voucher_date
      INTO v_reversal_created_at, v_existing_source, v_reversal_date
    FROM app_private.payment_reversals reversal
    JOIN public.income_expenses voucher
      ON voucher.id = reversal.reversal_voucher_id
    WHERE reversal.original_payment_id = p_payment_id
      AND reversal.reversal_voucher_id = v_reversal_voucher
    FOR UPDATE OF voucher;

    IF v_reversal_created_at IS NULL THEN
      RAISE EXCEPTION 'Không tìm thấy ledger hoàn tác payment legacy'
        USING ERRCODE = '55000';
    END IF;

    -- A replay keeps the date and classified items committed by the first call.
    IF v_existing_source IS NOT NULL THEN
      IF v_existing_source <> v_source_voucher THEN
        RAISE EXCEPTION 'Nguồn hoàn tác payment legacy đã thay đổi'
          USING ERRCODE = '55000';
      END IF;
      RETURN v_result;
    END IF;

    v_reversal_date := GREATEST(
      v_payment_date,
      public.vn_local_date(v_reversal_created_at)
    );

    PERFORM app_private.begin_accounting_chain_write_v1();

    SELECT type_row.id INTO v_reversal_type
    FROM public.income_expense_types type_row
    WHERE type_row.organization_id = v_org
      AND lower(type_row.type) = 'expense'
      AND lower(btrim(type_row.name)) = 'hoàn tác thu tiền'
    ORDER BY type_row.created_at, type_row.id
    LIMIT 1;

    IF v_reversal_type IS NULL THEN
      INSERT INTO public.income_expense_types (
        organization_id, user_id, name, type, description,
        is_default, is_deposit
      )
      SELECT
        v_org, invoice.user_id, 'Hoàn tác thu tiền', 'expense',
        'Bút toán đối ứng cho khoản thu đã hoàn tác', false, false
      FROM public.invoices invoice
      JOIN public.payments payment ON payment.invoice_id = invoice.id
      WHERE payment.id = p_payment_id
      RETURNING id INTO v_reversal_type;
    END IF;

    UPDATE public.income_expenses
       SET account_id = v_source_account,
           voucher_date = v_reversal_date,
           reversal_of_income_expense_id = v_source_voucher
     WHERE id = v_reversal_voucher;

    UPDATE public.income_expense_items
       SET accounting_class = 'INTERNAL', unit_price = 0, amount = 0
     WHERE income_expense_id = v_reversal_voucher;

    FOR v_item IN
      WITH source_vouchers AS (
        SELECT voucher.id
        FROM public.income_expenses voucher
        WHERE voucher.payment_id = p_payment_id
          AND voucher.organization_id = v_org
          AND voucher.type = 'INCOME'
          AND voucher.approval_status = 'APPROVED'
          AND voucher.deleted_at IS NULL
        UNION
        SELECT voucher.id
        FROM public.income_expenses voucher
        WHERE voucher.payment_id IS NULL
          AND voucher.organization_id = v_org
          AND voucher.type = 'INCOME'
          AND voucher.approval_status = 'APPROVED'
          AND voucher.deleted_at IS NULL
          AND voucher.notes = '[THU TACH COC ' || p_payment_id::text || ']'
        UNION
        SELECT '2ea26ca0-92c6-4896-a7b5-a5ee7031b2cc'::uuid
        WHERE p_payment_id = '5b32cb16-b579-4427-bebf-108c5195a279'::uuid
      )
      SELECT item.accounting_class, sum(item.amount) AS amount
      FROM source_vouchers source
      JOIN public.income_expense_items item ON item.income_expense_id = source.id
      WHERE item.accounting_class IN ('PNL', 'DEPOSIT', 'CUSTOMER_CREDIT')
      GROUP BY item.accounting_class
      ORDER BY item.accounting_class
    LOOP
      INSERT INTO public.income_expense_items (
        income_expense_id, organization_id, income_expense_type_id,
        description, quantity, unit_price, amount, start_date, end_date,
        accounting_class
      ) VALUES (
        v_reversal_voucher, v_org, v_reversal_type,
        'Hoàn tác payment legacy ' || v_item.accounting_class,
        1, v_item.amount, v_item.amount,
        v_reversal_date, v_reversal_date, v_item.accounting_class
      );
    END LOOP;

    UPDATE public.payments payment
       SET reversed_at = v_reversal_created_at,
           updated_at = now()
     WHERE payment.id = p_payment_id
       AND payment.reversed_at IS NULL;

    PERFORM public.recompute_ie_business_result(v_reversal_voucher);
    PERFORM public.recompute_invoice_for_id((
      SELECT payment.invoice_id FROM public.payments payment
      WHERE payment.id = p_payment_id
    ));
    PERFORM public.recompute_contract_deposit_paid((
      SELECT invoice.contract_id
      FROM public.payments payment
      JOIN public.invoices invoice ON invoice.id = payment.invoice_id
      WHERE payment.id = p_payment_id
    ));
    PERFORM app_private.end_accounting_chain_write_v1();

    RETURN v_result;
  END IF;

  SELECT count(*) INTO v_tender_count
  FROM public.invoice_payment_tenders tender
  WHERE tender.collection_id = v_collection_id;
  IF v_tender_count <> 1 THEN
    RAISE EXCEPTION 'Collection nhiều phương thức phải hoàn tác ở cấp collection'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(
           collection.reversal_date,
           GREATEST(
             collection.collection_date,
             public.vn_local_date(clock_timestamp())
           )
         )
    INTO v_reversal_date
  FROM public.invoice_payment_collections collection
  WHERE collection.id = v_collection_id
  FOR SHARE;
  IF v_reversal_date IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy collection cần hoàn tác'
      USING ERRCODE = '42501';
  END IF;

  RETURN public.reverse_invoice_collection_v5(
    v_collection_id,
    v_reversal_date,
    p_reason,
    p_idempotency_key
  )::json;
END;
$_$;








--
-- Name: reverse_posted_income_expense_v2(uuid, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_posted_income_expense_v2(p_voucher uuid, p_cashbook uuid, p_posted_on date, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_orig public.income_expense_postings;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'cb', p_cashbook, 'on', p_posted_on, 'r', p_reason)::text);
  v_op app_private.canonical_write_operations;
  v_rev_id uuid := gen_random_uuid();
  v_line record;
  v_new_post bigint;
  v_resp jsonb;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: reason is required' USING ERRCODE = '22023';
  END IF;
  IF p_cashbook IS NULL OR p_posted_on IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: cashbook, postedOn and idempotency key are required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.reverse.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');

  -- Reverse capability + CUSTODIAN of the exact cashbook.
  IF NOT (SELECT allowed FROM app_private.authorize_tenant_action_v3(
            v_uid, v_ie.organization_id, 'income_expenses.reverse', v_ie.building_id, NULL)) THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: income_expenses.reverse required in scope' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.accounts a WHERE a.id = p_cashbook AND a.organization_id = v_ie.organization_id
    AND a.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: cashbook % not found', p_cashbook USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.assert_cashbook_access_v2(v_ie.organization_id, p_cashbook, 'CUSTODIAN', v_mid);

  IF v_ie.approval_status <> 'APPROVED' OR v_ie.posting_status <> 'POSTED' OR v_ie.active_posting_id_v2 IS NULL THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: only an APPROVED+POSTED voucher can be reversed (%, %)',
      v_ie.approval_status, v_ie.posting_status USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.finance_v2_is_cashbook_period_open(v_ie.organization_id, p_cashbook, p_posted_on) THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: posted_on % is inside a locked cashbook period', p_posted_on USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_orig FROM public.income_expense_postings p WHERE p.id = v_ie.active_posting_id_v2 FOR UPDATE;
  IF NOT FOUND OR v_orig.event_kind <> 'POSTING' THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: active posting not found for voucher %', p_voucher USING ERRCODE = '55000';
  END IF;
  IF v_orig.account_id <> p_cashbook THEN
    RAISE EXCEPTION 'reverse_posted_income_expense_v2: cashbook does not match the original posting' USING ERRCODE = '55000';
  END IF;

  -- New REVERSAL event (original is never mutated).
  INSERT INTO public.income_expense_postings (
    id, organization_id, voucher_id, posting_subject_kind, posting_subject_id,
    direction, account_id, gross_amount, voucher_amount_snapshot, amount_basis,
    net_cash_effect, posted_on, posted_by_membership_id, posted_by_user_id,
    approval_version, event_kind, idempotency_key, source_kind, posting_generation,
    reversal_of_id, reversal_reason, created_at
  ) VALUES (
    v_rev_id, v_orig.organization_id, v_orig.voucher_id, v_orig.posting_subject_kind, v_orig.posting_subject_id,
    v_orig.direction, v_orig.account_id, v_orig.gross_amount, v_orig.voucher_amount_snapshot, v_orig.amount_basis,
    -v_orig.net_cash_effect, p_posted_on, v_mid, v_uid,
    v_orig.approval_version, 'REVERSAL', p_idempotency_key || ':reversal', 'MANUAL', v_orig.posting_generation,
    v_orig.id, p_reason, now()
  );

  -- Opposing signed lines for every original line.
  FOR v_line IN
    SELECT * FROM public.income_expense_posting_lines l WHERE l.posting_id = v_orig.id
  LOOP
    INSERT INTO public.income_expense_posting_lines (
      id, organization_id, posting_id, account_id, line_kind, signed_amount, created_at
    ) VALUES (
      gen_random_uuid(), v_line.organization_id, v_rev_id, v_line.account_id, 'REVERSAL', -v_line.signed_amount, now()
    );
  END LOOP;

  v_new_post := v_ie.posting_version + 1;
  UPDATE public.income_expenses ie
     SET active_posting_id_v2 = NULL, posting_status = 'REVERSED',
         reversed_by_posting_id = v_rev_id, posting_version = v_new_post, updated_at = now()
   WHERE ie.id = p_voucher;

  v_resp := jsonb_build_object('voucherId', p_voucher, 'reversalPostingId', v_rev_id,
                               'postingStatus', 'REVERSED', 'postingVersion', v_new_post);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.reverse.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'REVERSED', v_ie.review_version, v_ie.approval_version, v_new_post);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.reverse.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION reverse_posted_income_expense_v2(p_voucher uuid, p_cashbook uuid, p_posted_on date, p_reason text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reverse_posted_income_expense_v2(p_voucher uuid, p_cashbook uuid, p_posted_on date, p_reason text, p_idempotency_key text) IS 'Plan §7.2/§6.2: reverse a POSTED voucher via a new REVERSAL event with opposing lines; never mutate the original.';








--
-- Name: revoke_organization_invitation_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_organization_invitation_v1(p_invitation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org uuid := app_private.current_admin_org_v1();
  v_i   public.organization_invitations%rowtype;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền thu hồi lời mời.' using errcode = '42501';
  end if;
  perform app_private.require_perm_v1(v_org, 'users.create', 'thu hồi lời mời');

  select * into v_i from public.organization_invitations
   where id = p_invitation and organization_id = v_org for update;
  if not found then
    raise exception 'Không tìm thấy lời mời này.' using errcode = 'P0002';
  end if;
  if v_i.status <> 'PENDING' then
    raise exception 'Lời mời này không còn ở trạng thái chờ.' using errcode = '55000';
  end if;

  update public.organization_invitations
     set status = 'REVOKED', revoked_at = now() where id = p_invitation;

  perform app_private.append_authz_audit_v1(
    v_org, 'INVITATION_REVOKED', 'organization_invitation', p_invitation,
    jsonb_build_object('email', v_i.email_normalized, 'status', 'PENDING'),
    jsonb_build_object('status', 'REVOKED'), null);

  return jsonb_build_object('invitationId', p_invitation, 'status', 'REVOKED');
end
$$;








--
-- Name: room_has_holding_deposit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_has_holding_deposit(p_room_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_room_id IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM public.deposits d
      WHERE d.room_id = p_room_id
        AND d.deleted_at IS NULL
        AND d.contract_id IS NULL
        AND d.status IN ('PENDING','CONFIRMED')
    )
    OR EXISTS (
      SELECT 1 FROM public.income_expenses ie
      WHERE ie.room_id = p_room_id
        AND ie.deleted_at IS NULL
        AND ie.contract_id IS NULL
        AND ie.type = 'INCOME'
        AND COALESCE(ie.approval_status, '') <> 'CANCELLED'
        AND public.ie_has_deposit_item(ie.id)
    )
  );
$$;








--
-- Name: FUNCTION room_has_holding_deposit(p_room_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.room_has_holding_deposit(p_room_id uuid) IS 'TRUE nếu phòng đang bị giữ bởi cọc giữ chỗ chưa gắn HĐ (deposits PENDING/CONFIRMED
hoặc phiếu thu IE có item is_deposit, kể cả chưa duyệt; loại CANCELLED/đã xoá).
Predicate DÙNG CHUNG cho recompute_room_reservation (cờ RESERVED) và 2 RPC bảng
phòng trống (ẩn phòng đã cọc, kể cả phòng "sắp trống" còn HĐ hiệu lực).';








--
-- Name: run_recurring_vouchers_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_recurring_vouchers_job() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM public.generate_recurring_vouchers(NULL);
  RAISE NOTICE 'run_recurring_vouchers_job: generated % child voucher(s)', v_n;
END;
$$;








--
-- Name: FUNCTION run_recurring_vouchers_job(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_recurring_vouchers_job() IS 'CHỈ pg_cron. SECURITY DEFINER không có guard actor nên KHÔNG được cấp cho anon/authenticated. Đã thu hồi 2026-07-25 sau khi phát hiện anon gọi được.';








--
-- Name: salary_payout_v1(uuid, date, numeric, uuid, date, text, text, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salary_payout_v1(p_staff_id uuid, p_period_month date, p_take_home numeric, p_account_id uuid, p_voucher_date date, p_note text, p_idempotency_key text, p_rent_invoice_id uuid DEFAULT NULL::uuid, p_rent_amount numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_building uuid; v_type uuid; v_membership uuid;
  v_authz boolean; v_key text; v_hash text;
  v_op app_private.canonical_write_operations%rowtype; v_route text;
  v_voucher uuid; v_req uuid; v_resp json;
  -- rent-offset locals
  v_rent_collect numeric := 0;
  v_inv record;
  v_income_type uuid;
  v_rent_res json := null;
  c_op constant text := 'salary.payout.v1';
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_take_home is null or p_take_home <= 0 or round(p_take_home,2) <> p_take_home then
    raise exception 'Số tiền thực nhận không hợp lệ'; end if;
  if p_period_month is null then raise exception 'Kỳ lương trống'; end if;
  if p_rent_amount is not null and round(p_rent_amount,2) <> p_rent_amount then
    raise exception 'Tiền phòng khấu trừ không hợp lệ'; end if;

  -- R3-FIX (đồng bộ t5_11): org SUBJECT-DERIVED từ nhân viên nhận lương —
  -- KHÔNG global-scan toà ảo (đa tenant sẽ trỏ nhầm org). Toà ảo lấy TRONG org đó.
  select organization_id into v_org from public.manager_salary_config
   where staff_id = p_staff_id and organization_id is not null
   order by is_active desc, created_at desc limit 1;
  if v_org is null then
    select organization_id into v_org from public.organization_memberships
     where user_id = p_staff_id and status='ACTIVE' limit 1;
  end if;
  if v_org is null then raise exception 'Không xác định được tổ chức của nhân viên' using errcode='42501'; end if;
  select b.id into v_building
    from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.organization_id = v_org and b.is_virtual=true and b.deleted_at is null
   order by b.created_at limit 1 for share of o,b;
  if v_building is null then raise exception 'Tổ chức chưa có toà ảo (Chung) để hạch toán phiếu lương' using errcode='55000'; end if;

  -- exact permission salary.distribute; require actor membership.
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'salary.distribute', v_building, p_account_id);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền chi lương (salary.distribute)' using errcode='42501'; end if;
  select m.id into v_membership from public.organization_memberships m
   where m.user_id=v_actor and m.organization_id=v_org and m.status='ACTIVE' limit 1 for share;
  if v_membership is null then raise exception 'Không còn là thành viên tổ chức' using errcode='42501'; end if;

  -- idempotency (mở rộng hash: gồm cả rent để không nhầm "same key khác nội dung").
  v_hash := md5(jsonb_build_object('staff',p_staff_id,'period',p_period_month,
    'take_home',round(p_take_home,2),'org',v_org,
    'rent_invoice',p_rent_invoice_id,'rent_amount',round(coalesce(p_rent_amount,0),2))::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_staff_id::text || '|' || p_period_month::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op
     and o.subject_scope=p_staff_id::text || '|' || p_period_month::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then raise exception 'Writer chi lương chưa bật' using errcode='55000'; end if;

  -- org-scoped "Lương quản lý" expense type.
  select id into v_type from public.income_expense_types
   where organization_id=v_org and lower(type)='expense' and name='Lương quản lý' limit 1;
  if v_type is null then
    insert into public.income_expense_types (organization_id, name, type)
    values (v_org, 'Lương quản lý', 'expense') returning id into v_type; end if;

  -- create the salary EXPENSE voucher UNAPPROVED (force-approval — never self-approve).
  insert into public.income_expenses
    (user_id, organization_id, type, name, building_id, account_id, salary_staff_id,
     voucher_date, approval_status, business_result_accounting, notes, source_payload_hash)
  values (v_actor, v_org, 'EXPENSE', 'Chi lương', v_building, p_account_id, p_staff_id,
          p_voucher_date, 'UNAPPROVED', false, coalesce(p_note,'Chi lương'), v_hash)
  returning id into v_voucher;

  -- item #1: tiền thực nhận (net).
  insert into public.income_expense_items
    (income_expense_id, organization_id, income_expense_type_id, description, quantity, unit_price)
  values (v_voucher, v_org, v_type, 'Tiền thực nhận', 1, round(p_take_home,2));

  -- ── RENT-OFFSET (phương án A) — chuẩn bị + thêm dòng #2 TRƯỚC khi submit ──
  -- (submit_financial_request_v1 chốt snapshot = income_expenses.total_amount, nên
  --  dòng tiền phòng phải có trước để engine thấy đúng GROSS.)
  if p_rent_invoice_id is not null and coalesce(p_rent_amount,0) > 0 then
    -- đọc hoá đơn (record_invoice_payment_v3 sẽ tự re-lock + check quyền — xem P4).
    select id, organization_id, user_id, building_id, total_amount,
           coalesce(remaining_amount, total_amount) as remaining
      into v_inv
      from public.invoices
     where id = p_rent_invoice_id and deleted_at is null;
    if not found then
      raise exception 'Hoá đơn tiền phòng không tồn tại' using errcode='42501'; end if;

    -- P5: clamp về phần còn nợ (mirror legacy; tránh excess ngoài ý muốn).
    v_rent_collect := least(round(p_rent_amount,2), coalesce(v_inv.remaining,0));
    if v_rent_collect <= 0 then
      v_rent_collect := 0;  -- hết nợ → bỏ offset, phiếu chi = net như thường.
    else
      -- item #2: dòng tiền phòng khấu trừ ⇒ phiếu chi = gross.
      insert into public.income_expense_items
        (income_expense_id, organization_id, income_expense_type_id, description, quantity, unit_price)
      values (v_voucher, v_org, v_type, 'Tiền phòng (khấu trừ)', 1, v_rent_collect);
    end if;
  end if;

  -- submit to the approval engine as FORCE-APPROVAL: submit_financial_request_v1
  -- classifies + routes; a salary voucher is never AUTO_POST. It is left PENDING
  -- for a checker to decide (this writer does not approve). Submit fails closed
  -- if no ACTIVE rule set exists — that is a real configuration error, surface it.
  v_req := app_private.submit_financial_request_v1(v_voucher, v_membership, v_actor, v_key || '-sub');

  -- ── RENT-OFFSET: ghi phiếu THU đối ứng qua record_invoice_payment_v3 (chữ ký THẬT).
  -- Nó tạo payments(CT) + income_expenses(INCOME, APPROVED) + cập nhật hoá đơn. Chạy
  -- SAU submit, CÙNG transaction. Xem P3 (bất đối xứng) / P4 (quyền) / P6 (loại thu).
  if v_rent_collect > 0 then
    -- P6: loại thu (không phải cọc) theo ORG CỦA HOÁ ĐƠN.
    select t.id into v_income_type
      from public.income_expense_types t
     where t.organization_id = v_inv.organization_id
       and lower(t.type) = 'income'
       and coalesce(t.is_deposit,false) = false
     order by
       (t.is_default is true) desc,
       (public.nrm_vn(t.name) = 'thu tien hoa don') desc,   -- nrm_vn: đã verify tồn tại (dùng trong submit_financial_request_v1). TODO-REVIEW P6: xác nhận CHUỖI tên loại thu chuẩn của org.
       t.created_at
     limit 1;
    if v_income_type is null then
      raise exception 'Org hoá đơn chưa có loại thu (không phải cọc) cho phiếu đối ứng tiền phòng'
        using errcode='55000'; end if;

    v_rent_res := public.record_invoice_payment_v3(
      p_invoice_id       => p_rent_invoice_id,
      p_amount           => v_rent_collect,
      p_payment_method   => 'CT'::public.payment_method,
      p_payment_date     => p_voucher_date,
      p_idempotency_key  => v_key || '-rent',
      p_account_id       => p_account_id,
      p_notes            => 'Cấn trừ tiền phòng vào lương',
      p_receipt_image_url=> null,
      p_voucher          => jsonb_build_object(
                              'name', 'Thu tiền phòng (khấu trừ lương)',
                              'payer_name', 'Khấu trừ lương',
                              'notes', 'Cấn trừ tiền phòng vào lương',
                              'creator_name', 'Chi lương'),
      p_items            => jsonb_build_array(jsonb_build_object(
                              'income_expense_type_id', v_income_type,
                              'description', 'Thu tiền phòng (khấu trừ lương)',
                              'quantity', 1,
                              'unit_price', v_rent_collect,
                              'start_date', p_voucher_date::text,
                              'end_date', p_voucher_date::text)),
      p_receipt_number   => null,
      p_voucher_owner_id => v_inv.user_id   -- phải = chủ hoá đơn (writer tự assert).
    );
  end if;

  -- salary_monthly bookkeeping.
  --  • ensure row tồn tại (như bản gốc).
  --  • STAMP payout_voucher_id = phiếu chi vừa tạo (link xác định — xem P2).
  --  • paid: KHÔNG đụng ở đây (tiền chưa POST). Cơ chế accrual paid khi POST chưa
  --    tồn tại trong engine — xem P1. KHÔNG bịa.
  insert into public.salary_monthly (user_id, staff_id, period_month, payout_voucher_id, organization_id)
  values (v_actor, p_staff_id, p_period_month, v_voucher, v_org)
  on conflict (staff_id, period_month) do update set
    payout_voucher_id = excluded.payout_voucher_id,
    organization_id   = coalesce(public.salary_monthly.organization_id, excluded.organization_id);

  v_resp := json_build_object('salary_voucher_id', v_voucher, 'approval_request_id', v_req,
    'state', 'PENDING_APPROVAL',
    'rent_offset', case when v_rent_collect > 0
                        then json_build_object('collected', v_rent_collect, 'result', v_rent_res)
                        else null end);
  update app_private.canonical_write_operations
     set subject_id=v_voucher, response_payload=to_jsonb(v_resp), completed_at=now()
   where organization_id=v_org and operation=c_op
     and subject_scope=p_staff_id::text || '|' || p_period_month::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: salary_staff_months(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salary_staff_months() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cand AS (
    SELECT 1 AS pri, 0::bigint AS w, sa.user_id
      FROM public.super_admins sa
     WHERE sa.user_id = auth.uid()
    UNION ALL
    SELECT 2, 0::bigint, b.user_id
      FROM public.buildings b
     WHERE b.user_id = auth.uid() AND b.deleted_at IS NULL
    UNION ALL
    SELECT 3, count(*), sa.user_id
      FROM public.staff_assignments sa
     WHERE sa.staff_id = auth.uid()
     GROUP BY sa.user_id
    UNION ALL
    SELECT 4, 0::bigint, auth.uid()
  )
  SELECT COALESCE(
    (
      SELECT r.rules -> 'staffMonths'
        FROM cand c
        JOIN public.salary_bonus_rules r ON r.user_id = c.user_id
       ORDER BY c.pri, c.w DESC, c.user_id
       LIMIT 1
    ),
    '{}'::jsonb
  );
$$;








--
-- Name: salary_work_ledger(date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salary_work_ledger(p_period_month date, p_staff_id uuid DEFAULT NULL::uuid) RETURNS TABLE(staff_id uuid, item_type text, source_id uuid, occurred_date date, day_label text, content text, place text, job_type_name text, is_repair boolean, is_contract boolean, base_amount numeric, weekend_amount numeric, after_amount numeric, cash_amount numeric, has_photo boolean, bonus_amount numeric, reason text, excluded boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner   uuid;
  v_start   date;
  v_end     date;
  v_staff   uuid := p_staff_id;
  v_rules   jsonb;
  v_weekend int[];
  v_cutoff  time;
  v_wk_day  numeric;
  v_photo   boolean;
BEGIN
  v_owner := (SELECT sa.user_id FROM public.super_admins sa ORDER BY sa.created_at LIMIT 1);
  IF NOT (public.is_admin() OR public.is_super_admin()) THEN
    v_staff := auth.uid();
  END IF;

  v_start := date_trunc('month', p_period_month)::date;
  v_end   := (v_start + INTERVAL '1 month - 1 day')::date;

  SELECT r.rules INTO v_rules FROM public.salary_bonus_rules r WHERE r.user_id = v_owner;
  v_rules   := COALESCE(v_rules, '{}'::jsonb);
  v_wk_day  := COALESCE((v_rules->>'weekendRepair')::numeric, 20000);
  v_cutoff  := COALESCE((v_rules->>'afterHourMark'), '18:00')::time;
  v_photo   := COALESCE((v_rules->>'requirePhoto')::boolean, false);
  SELECT COALESCE(array_agg((e)::int), ARRAY[0]) INTO v_weekend
  FROM jsonb_array_elements_text(COALESCE(v_rules->'weekendDays', '[0]'::jsonb)) e;

  RETURN QUERY
  -- (A) JOB: viec ky HD (is_contract) chi +thuong khi sau gio/CN-Le;
  --     viec co exclude_from_salary → van hien dong nhung thuong = 0
  SELECT
    j.assignee_id,
    'JOB'::text,
    j.id,
    public.vn_local_date(j.completion_time),
    CASE
      WHEN EXISTS (SELECT 1 FROM public.salary_holidays h WHERE h.user_id = v_owner AND h.holiday_date = public.vn_local_date(j.completion_time)) THEN 'Lễ'
      WHEN public.vn_local_dow(j.completion_time) = ANY(v_weekend) THEN 'CN'
      ELSE ''
    END,
    j.title,
    COALESCE(b.code, b.name, '') || COALESCE(' · ' || r.name, ''),
    jt.name,
    COALESCE(jt.is_repair, false),
    COALESCE(jt.is_contract, false),
    COALESCE(jt.bonus_amount, 0),
    0::numeric,
    0::numeric,
    NULL::numeric,
    public.job_photo_ok(j.completion_attachments, j.attachments),
    CASE
      WHEN COALESCE(jt.counts_for_salary, true)
       AND NOT COALESCE(j.exclude_from_salary, false)
       AND (NOT v_photo OR public.job_photo_ok(j.completion_attachments, j.attachments))
       AND (NOT COALESCE(jt.is_contract, false)
            OR public.vn_local_time(j.completion_time) >= v_cutoff
            OR public.vn_local_dow(j.completion_time) = ANY(v_weekend)
            OR EXISTS (SELECT 1 FROM public.salary_holidays h WHERE h.user_id = v_owner AND h.holiday_date = public.vn_local_date(j.completion_time)))
      THEN COALESCE(jt.bonus_amount, 0) ELSE 0
    END,
    COALESCE(jt.name, 'Việc'),
    COALESCE(j.exclude_from_salary, false)
  FROM public.jobs j
  JOIN public.job_types jt ON jt.id = j.job_type_id
  LEFT JOIN public.buildings b ON b.id = j.building_id
  LEFT JOIN public.rooms r ON r.id = j.room_id
  WHERE j.status = 'COMPLETED'
    AND COALESCE(jt.counts_for_salary, true)
    AND (COALESCE(jt.bonus_amount, 0) > 0 OR COALESCE(jt.is_repair, false))
    AND j.assignee_id IS NOT NULL
    AND (v_staff IS NOT NULL AND j.assignee_id = v_staff
         OR v_staff IS NULL AND j.assignee_id IN (SELECT c.staff_id FROM public.manager_salary_config c WHERE c.user_id = v_owner AND c.is_active))
    AND public.vn_local_date(j.completion_time) BETWEEN v_start AND v_end

  UNION ALL
  -- (B) DAY_BONUS: viec bi loai-tru KHONG kich hoat phu cap CN/Le
  SELECT
    d.staff_id, 'DAY_BONUS'::text, NULL::uuid, d.ld,
    CASE WHEN d.is_holiday THEN 'Lễ' ELSE 'CN' END,
    CASE WHEN d.is_holiday THEN 'Ngày lễ có làm việc' ELSE 'Chủ nhật có làm việc' END,
    ''::text, NULL::text, true, false, 0::numeric, v_wk_day, 0::numeric, NULL::numeric, NULL::boolean,
    v_wk_day, 'CN/Lễ có sửa chữa hoặc ký HĐ'::text, false
  FROM (
    SELECT DISTINCT
      j.assignee_id AS staff_id,
      public.vn_local_date(j.completion_time) AS ld,
      EXISTS (SELECT 1 FROM public.salary_holidays h WHERE h.user_id = v_owner AND h.holiday_date = public.vn_local_date(j.completion_time)) AS is_holiday
    FROM public.jobs j
    JOIN public.job_types jt ON jt.id = j.job_type_id
    WHERE j.status = 'COMPLETED'
      AND (COALESCE(jt.is_repair, false) OR COALESCE(jt.is_contract, false))
      AND NOT COALESCE(j.exclude_from_salary, false)
      AND j.assignee_id IS NOT NULL
      AND (v_staff IS NOT NULL AND j.assignee_id = v_staff
           OR v_staff IS NULL AND j.assignee_id IN (SELECT c.staff_id FROM public.manager_salary_config c WHERE c.user_id = v_owner AND c.is_active))
      AND public.vn_local_date(j.completion_time) BETWEEN v_start AND v_end
      AND (public.vn_local_dow(j.completion_time) = ANY(v_weekend)
           OR EXISTS (SELECT 1 FROM public.salary_holidays h WHERE h.user_id = v_owner AND h.holiday_date = public.vn_local_date(j.completion_time)))
  ) d

  UNION ALL
  -- (D) CASH: thu tien mat — hien thi minh bach, KHONG thuong
  SELECT
    ie.salary_staff_id, 'CASH'::text, ie.id, ie.voucher_date,
    ''::text,
    'Thu tiền mặt' || COALESCE(' ' || r.name, ''),
    COALESCE(b.code, b.name, '') || COALESCE(' · ' || r.name, ''),
    NULL::text, false, false, 0::numeric, 0::numeric, 0::numeric, ie.total_amount, NULL::boolean,
    NULL::numeric, 'Không tính thưởng'::text, false
  FROM public.income_expenses ie
  LEFT JOIN public.rooms r ON r.id = ie.room_id
  LEFT JOIN public.buildings b ON b.id = ie.building_id
  WHERE ie.type = 'INCOME'
    AND ie.salary_role = 'CASH_COLLECTION'
    AND ie.deleted_at IS NULL
    AND ie.salary_staff_id IS NOT NULL
    AND (v_staff IS NULL OR ie.salary_staff_id = v_staff)
    AND ie.voucher_date BETWEEN v_start AND v_end;
END;
$$;








--
-- Name: sale_bonus_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_bonus_status_v1(p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_org uuid; v_bld uuid; v_row record; v_cap numeric; v_money text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT c.organization_id, r.building_id INTO v_org, v_bld
    FROM public.contracts c
    LEFT JOIN public.rooms r ON r.id = c.room_id
   WHERE c.id = p_contract_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy hợp đồng' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (public.can_access_building(v_bld) OR public.ie_all_buildings_scope(v_bld)
       OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền xem hợp đồng của toà này' USING ERRCODE = '42501';
  END IF;

  v_cap := app_private.sale_bonus_cap_for_v1(v_org, v_bld, public.org_today_v1(v_org));

  SELECT ie.id, ie.code, ie.total_amount, ie.voucher_date, ie.approval_status,
         ie.created_at, 'CONTRACT'::text AS via
    INTO v_row
    FROM public.income_expenses ie
   WHERE ie.contract_id = p_contract_id AND ie.commission_kind = 'sale'
     AND ie.deleted_at IS NULL AND ie.approval_status <> 'CANCELLED'
     AND NOT COALESCE(ie.commission_legacy_dup, false)
   ORDER BY ie.created_at LIMIT 1;

  IF v_row.id IS NULL THEN
    SELECT bon.id, bon.code, bon.total_amount, bon.voucher_date, bon.approval_status,
           bon.created_at, 'DEPOSIT'::text AS via
      INTO v_row
      FROM app_private.sale_bonus_claims sbc
      JOIN public.income_expenses dep ON dep.id = sbc.deposit_voucher_id
      JOIN public.income_expenses bon ON bon.id = sbc.bonus_voucher_id
     WHERE dep.contract_id = p_contract_id
       AND bon.deleted_at IS NULL AND bon.approval_status <> 'CANCELLED'
     ORDER BY bon.created_at LIMIT 1;
  END IF;

  v_money := CASE WHEN v_row.id IS NULL THEN NULL
    ELSE replace(to_char(round(v_row.total_amount), 'FM999G999G999G999'), ',', '.') END;

  RETURN jsonb_build_object(
    'contractId',  p_contract_id,
    'alreadyPaid', (v_row.id IS NOT NULL),
    'voucherId',   v_row.id,
    'code',        v_row.code,
    'amount',      v_row.total_amount,
    'voucherDate', v_row.voucher_date,
    'createdAt',   v_row.created_at,
    'status',      v_row.approval_status,
    'via',         v_row.via,
    'capAmount',   v_cap,
    'note', CASE
      WHEN v_row.id IS NULL THEN 'Hợp đồng này chưa được thưởng Sale.'
      ELSE 'Đã thưởng ' || v_money || 'đ ngày ' || to_char(v_row.voucher_date, 'DD/MM/YYYY')
           || ' (phiếu ' || COALESCE(v_row.code, '—') || ')'
           || CASE WHEN v_row.via = 'DEPOSIT' THEN ' — thưởng từ phiếu cọc.' ELSE '.' END
    END);
END;
$$;








--
-- Name: FUNCTION sale_bonus_status_v1(p_contract_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sale_bonus_status_v1(p_contract_id uuid) IS 'Hợp đồng này đã được thưởng Sale chưa, bao nhiêu, khi nào. Kiểm CẢ HAI đường: phiếu thưởng gắn thẳng hợp đồng, và phiếu thưởng gắn phiếu cọc mà phiếu cọc đó nay đã thuộc hợp đồng. Giao diện dùng để tô xám ô nhập thưởng.';








--
-- Name: same_team(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.same_team(_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.team_members a
    JOIN public.team_members b ON a.team_id = b.team_id
    WHERE a.member_id = auth.uid()
      AND b.member_id = _target
  );
$$;








