--
-- Name: set_cashbook_access_v2(uuid, uuid[], uuid[], bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_cashbook_access_v2(p_cashbook_id uuid, p_custodians uuid[], p_knowers uuid[], p_expected_revision bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_org uuid;
  v_actor_membership uuid;
  v_payload_hash text;
  v_existing app_private.cashbook_access_mutation_requests%ROWTYPE;
  v_revision bigint;
  v_before text[];
  v_after text[];
  v_result jsonb;
BEGIN
  SELECT organization_id INTO v_org FROM public.accounts
  WHERE id = p_cashbook_id AND deleted_at IS NULL FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cashbook not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT COALESCE((SELECT z.allowed FROM app_private.authorize_tenant_action_v3(
           auth.uid(), v_org, 'cashbooks.share', NULL, p_cashbook_id) z LIMIT 1), false) THEN
    RAISE EXCEPTION 'cashbooks.share required to change cashbook access' USING ERRCODE = '42501';
  END IF;

  SELECT m.id INTO v_actor_membership FROM public.organization_memberships m
  WHERE m.user_id = auth.uid() AND m.organization_id = v_org AND m.status = 'ACTIVE'
  LIMIT 1;
  IF v_actor_membership IS NULL THEN
    RAISE EXCEPTION 'No active membership in cashbook organization' USING ERRCODE = '42501';
  END IF;

  -- Membership sanity: every target must be an ACTIVE membership of the same org.
  IF EXISTS (
    SELECT 1 FROM unnest(COALESCE(p_custodians, '{}') || COALESCE(p_knowers, '{}')) t(mid)
    WHERE NOT EXISTS (SELECT 1 FROM public.organization_memberships m
                      WHERE m.id = t.mid AND m.organization_id = v_org AND m.status = 'ACTIVE')
  ) THEN
    RAISE EXCEPTION 'Target membership is not an active member of this organization'
      USING ERRCODE = '23514';
  END IF;

  v_payload_hash := md5(p_cashbook_id::text || ':' ||
    COALESCE(array_to_string(ARRAY(SELECT unnest(p_custodians) ORDER BY 1), ','), '') || '|' ||
    COALESCE(array_to_string(ARRAY(SELECT unnest(p_knowers) ORDER BY 1), ','), '') || ':' ||
    p_expected_revision::text);

  -- Idempotency (same key + same payload => replay stored result; different payload => conflict).
  SELECT * INTO v_existing FROM app_private.cashbook_access_mutation_requests
  WHERE organization_id = v_org AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing.payload_hash = v_payload_hash THEN
      RETURN v_existing.result_snapshot;
    END IF;
    RAISE EXCEPTION 'Idempotency key reused with a different payload' USING ERRCODE = '23505';
  END IF;

  -- CAS on the access revision.
  INSERT INTO app_private.cashbook_access_states (organization_id, cashbook_id, revision)
  VALUES (v_org, p_cashbook_id, 0)
  ON CONFLICT (organization_id, cashbook_id) DO NOTHING;
  SELECT revision INTO v_revision FROM app_private.cashbook_access_states
  WHERE organization_id = v_org AND cashbook_id = p_cashbook_id FOR UPDATE;
  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Stale access revision (expected %, current %)', p_expected_revision, v_revision
      USING ERRCODE = '55000';
  END IF;

  -- No self-role change through the normal RPC (§2.5): actor's own kind-set must be
  -- identical before and after; self changes go through a break-glass workflow.
  SELECT COALESCE(array_agg(DISTINCT b.possession_kind ORDER BY b.possession_kind), '{}')
    INTO v_before
  FROM public.cashbook_possession_bindings b
  WHERE b.organization_id = v_org AND b.cashbook_id = p_cashbook_id
    AND b.membership_id = v_actor_membership
    AND b.possession_kind IN ('CUSTODIAN', 'KNOWER') AND b.valid_to IS NULL;
  v_after := '{}';
  IF v_actor_membership = ANY (COALESCE(p_custodians, '{}')) THEN v_after := v_after || 'CUSTODIAN'::text; END IF; -- 7ad: array-element append (không ép ::text thì '||' thành array‖array → 22P02)
  IF v_actor_membership = ANY (COALESCE(p_knowers, '{}')) THEN v_after := v_after || 'KNOWER'::text; END IF;
  v_after := ARRAY(SELECT unnest(v_after) ORDER BY 1);
  IF v_before IS DISTINCT FROM v_after THEN
    RAISE EXCEPTION 'Self role change is not allowed through the normal share RPC'
      USING ERRCODE = '42501';
  END IF;

  -- Close bindings that fall out of the target lists (append-only history: close, never delete).
  UPDATE public.cashbook_possession_bindings b
    SET valid_to = now()
  WHERE b.organization_id = v_org AND b.cashbook_id = p_cashbook_id AND b.valid_to IS NULL
    AND ((b.possession_kind = 'CUSTODIAN' AND NOT (b.membership_id = ANY (COALESCE(p_custodians, '{}'))))
      OR (b.possession_kind = 'KNOWER' AND NOT (b.membership_id = ANY (COALESCE(p_knowers, '{}')))));

  -- Open missing bindings. OPERATOR rows are compatibility-only and never touched here.
  INSERT INTO public.cashbook_possession_bindings
    (organization_id, cashbook_id, membership_id, possession_kind, granted_by, reason)
  SELECT v_org, p_cashbook_id, t.mid, t.kind, auth.uid(), 'set_cashbook_access_v2'
  FROM (
    SELECT unnest(COALESCE(p_custodians, '{}')) AS mid, 'CUSTODIAN'::text AS kind
    UNION ALL
    SELECT unnest(COALESCE(p_knowers, '{}')), 'KNOWER'
  ) t
  WHERE NOT EXISTS (
    SELECT 1 FROM public.cashbook_possession_bindings b
    WHERE b.organization_id = v_org AND b.cashbook_id = p_cashbook_id
      AND b.membership_id = t.mid AND b.possession_kind = t.kind AND b.valid_to IS NULL
  );

  UPDATE app_private.cashbook_access_states
    SET revision = revision + 1, updated_by = auth.uid(), updated_at = now()
  WHERE organization_id = v_org AND cashbook_id = p_cashbook_id;

  v_result := jsonb_build_object(
    'cashbook_id', p_cashbook_id,
    'revision', v_revision + 1,
    'custodian_count', COALESCE(array_length(p_custodians, 1), 0),
    'knower_count', COALESCE(array_length(p_knowers, 1), 0));

  INSERT INTO app_private.cashbook_access_mutation_requests
    (organization_id, idempotency_key, payload_hash, expected_revision,
     resulting_revision, actor_membership_id, result_snapshot)
  VALUES (v_org, p_idempotency_key, v_payload_hash, p_expected_revision,
          v_revision + 1, v_actor_membership, v_result);

  INSERT INTO app_private.finance_v2_semantic_event_log
    (organization_id, event_kind, source_table, source_id, source_kind, actor, txid)
  VALUES (v_org, 'CASHBOOK_ACCESS_MUTATION', 'cashbook_possession_bindings', p_cashbook_id,
          'V2_WRITE', auth.uid(), pg_current_xact_id());

  RETURN v_result;
END
$$;








--
-- Name: set_commission_tier_v1(integer, integer, numeric, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_commission_tier_v1(p_min_months integer, p_max_months integer, p_rate_percent numeric, p_building_id uuid DEFAULT NULL::uuid, p_effective_from_month text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid; v_month date; v_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_min_months IS NULL OR p_max_months IS NULL OR p_max_months < p_min_months THEN
    RAISE EXCEPTION 'Khoảng tháng không hợp lệ' USING ERRCODE='22023';
  END IF;
  IF p_rate_percent IS NULL OR p_rate_percent < 0 OR p_rate_percent > 200 THEN
    RAISE EXCEPTION 'Tỉ lệ hoa hồng phải trong khoảng 0-200%%' USING ERRCODE='22023';
  END IF;

  IF p_building_id IS NOT NULL THEN
    SELECT b.organization_id INTO v_org FROM public.buildings b
     WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='P0002'; END IF;
  ELSE
    v_org := p_organization_id;
    IF v_org IS NULL THEN
      SELECT m.organization_id INTO v_org FROM public.organization_memberships m
       WHERE m.user_id = v_actor AND m.status = 'ACTIVE' LIMIT 1;
    END IF;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không xác định được tổ chức' USING ERRCODE='22023'; END IF;
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION
      'Chỉ chủ tổ chức mới công bố được bậc hoa hồng — bậc này quyết định phiếu nào tự chi.'
      USING ERRCODE='42501';
  END IF;

  IF p_effective_from_month IS NULL THEN
    v_month := date_trunc('month', public.org_today_v1(v_org))::date;
  ELSE
    IF p_effective_from_month !~ '^\d{4}-\d{2}$' THEN
      RAISE EXCEPTION 'Tháng hiệu lực phải dạng YYYY-MM' USING ERRCODE='22023';
    END IF;
    v_month := to_date(p_effective_from_month || '-01','YYYY-MM-DD');
  END IF;

  UPDATE app_private.commission_tier_versions
     SET status='RETIRED', retired_at=now()
   WHERE organization_id = v_org
     AND COALESCE(building_id,'00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_building_id,'00000000-0000-0000-0000-000000000000'::uuid)
     AND effective_from_month = v_month
     AND min_months = p_min_months AND max_months = p_max_months
     AND status='PUBLISHED';

  INSERT INTO app_private.commission_tier_versions
    (organization_id, building_id, effective_from_month, min_months, max_months,
     rate_percent, note, created_by)
  VALUES (v_org, p_building_id, v_month, p_min_months, p_max_months,
          p_rate_percent, NULLIF(btrim(COALESCE(p_note,'')),''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id,
    'minMonths', p_min_months, 'maxMonths', p_max_months, 'ratePercent', p_rate_percent,
    'buildingId', p_building_id, 'effectiveFrom', to_char(v_month,'YYYY-MM'),
    'note', 'Hợp đồng ' || p_min_months || '-' || p_max_months || ' tháng: '
            || p_rate_percent || '% tiền thuê, áp dụng từ tháng ' || to_char(v_month,'MM/YYYY')
            || '. Phiếu đúng mức này sẽ tự duyệt khi hợp đồng còn hiệu lực, đã thu đủ cọc và qua 7 ngày.');
END;
$_$;








--
-- Name: set_contract_public_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contract_public_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  candidate text;
  tries int := 0;
BEGIN
  IF NEW.public_code IS NOT NULL AND NEW.public_code <> '' THEN
    RETURN NEW;
  END IF;
  LOOP
    candidate := public.gen_contract_public_code(6);
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.contracts WHERE public_code = candidate);
    tries := tries + 1;
    IF tries >= 10 THEN
      candidate := public.gen_contract_public_code(8);
      EXIT;
    END IF;
  END LOOP;
  NEW.public_code := candidate;
  RETURN NEW;
END;
$$;








--
-- Name: set_ie_accounting_standard_v1(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ie_accounting_standard_v1(p_organization_id uuid, p_strict boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_membership uuid;
  v_current boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Thiếu tổ chức — không suy đoán tổ chức để tránh đổi nhầm org thật'
      USING ERRCODE = '22023';
  END IF;
  IF p_strict IS NULL THEN
    RAISE EXCEPTION 'Thiếu giá trị chế độ' USING ERRCODE = '22023';
  END IF;

  SELECT m.id INTO v_membership
  FROM public.organization_memberships m
  WHERE m.user_id = v_actor
    AND m.organization_id = p_organization_id
    AND m.status = 'ACTIVE'
    AND COALESCE(m.valid_from, '-infinity'::timestamptz) <= now()
    AND (m.valid_to IS NULL OR m.valid_to > now())
  LIMIT 1;

  IF v_membership IS NULL AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Không thuộc tổ chức này' USING ERRCODE = '42501';
  END IF;

  -- Quyền chủ kiểm TRONG ĐÚNG ORG được truyền vào.
  IF NOT (app_private.is_org_owner_v1(p_organization_id, v_actor)
          OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Chỉ Chủ sở hữu tổ chức được đổi chế độ Chuẩn kế toán'
      USING ERRCODE = '42501';
  END IF;

  v_current := app_private.ie_accounting_strict_v1(p_organization_id);

  -- Không ghi dòng rác khi bấm lại đúng giá trị đang chạy.
  IF v_current IS NOT DISTINCT FROM p_strict THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'strict_mode', v_current,
      'changed', false
    );
  END IF;

  INSERT INTO app_private.org_accounting_mode
    (organization_id, strict_mode, actor_user_id, actor_membership_id, reason)
  VALUES
    (p_organization_id, p_strict, v_actor, v_membership, NULLIF(btrim(COALESCE(p_reason,'')), ''));

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'strict_mode', p_strict,
    'changed', true
  );
END
$$;








--
-- Name: set_ie_auto_approve_threshold_v1(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ie_auto_approve_threshold_v1(p_threshold numeric) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_cnt int; v_owner_org uuid; v_is_owner boolean;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  if p_threshold is not null and (p_threshold <= 0 or round(p_threshold,2) <> p_threshold) then
    raise exception 'Ngưỡng không hợp lệ (phải > 0)' using errcode='22023';
  end if;
  select count(distinct m.organization_id), min(m.organization_id::text)::uuid
    into v_cnt, v_org
    from public.organization_memberships m
   where m.user_id = v_actor and m.status = 'ACTIVE';
  if coalesce(v_cnt,0) = 0 then raise exception 'Không thuộc tổ chức nào' using errcode='42501'; end if;
  if v_cnt > 1 then
    select rb.organization_id into v_owner_org
      from public.role_bindings rb
      join public.organization_memberships m
        on m.id = rb.membership_id and m.organization_id = rb.organization_id
       and m.user_id = v_actor and m.status = 'ACTIVE'
      join public.organization_roles r
        on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
     limit 1;
    if v_owner_org is not null then v_org := v_owner_org; end if;
  end if;

  select exists (
    select 1 from public.role_bindings rb
      join public.organization_memberships m
        on m.id = rb.membership_id and m.organization_id = rb.organization_id
       and m.user_id = v_actor and m.status = 'ACTIVE'
      join public.organization_roles r
        on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
     where rb.organization_id = v_org
  ) into v_is_owner;
  if not (coalesce(v_is_owner,false) or coalesce(public.is_super_admin(),false)) then
    raise exception 'Chỉ Chủ sở hữu tổ chức được đặt ngưỡng tự duyệt' using errcode='42501';
  end if;

  insert into app_private.ie_auto_approve_config (organization_id, threshold, updated_by, updated_at)
  values (v_org, p_threshold, v_actor, now())
  on conflict (organization_id)
  do update set threshold = excluded.threshold,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at;

  return json_build_object('organization_id', v_org, 'threshold', p_threshold);
end;
$$;








--
-- Name: set_ie_item_accounting_class(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ie_item_accounting_class() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_deposit boolean;
BEGIN
  IF NEW.accounting_class IS NULL
     OR (
       TG_OP = 'UPDATE'
       AND NEW.income_expense_type_id IS DISTINCT FROM OLD.income_expense_type_id
       AND NEW.accounting_class IS NOT DISTINCT FROM OLD.accounting_class
       AND OLD.accounting_class IN ('PNL', 'DEPOSIT')
     ) THEN
    SELECT t.is_deposit
      INTO v_is_deposit
      FROM public.income_expense_types t
     WHERE t.id = NEW.income_expense_type_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unknown income_expense_type_id %', NEW.income_expense_type_id
        USING ERRCODE = '23503';
    END IF;

    NEW.accounting_class := CASE WHEN v_is_deposit THEN 'DEPOSIT' ELSE 'PNL' END;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: set_issue_sla(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_issue_sla() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  sla_config RECORD;
BEGIN
  -- Get SLA config for this priority (cast enum to text for comparison)
  SELECT * INTO sla_config
  FROM sla_configs
  WHERE user_id = NEW.user_id
    AND priority = NEW.priority::text
    AND is_active = TRUE;

  IF FOUND THEN
    NEW.sla_response_time_minutes := sla_config.response_time_minutes;
    NEW.sla_resolution_time_minutes := sla_config.resolution_time_minutes;
    NEW.sla_due_date := NEW.created_at + (sla_config.resolution_time_minutes || ' minutes')::INTERVAL;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: set_maintenance_rule_v1(text, numeric, numeric, integer, boolean, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_maintenance_rule_v1(p_service_kind text, p_standard_amount numeric DEFAULT NULL::numeric, p_ceiling_amount numeric DEFAULT NULL::numeric, p_min_months_between integer DEFAULT NULL::integer, p_counts_history boolean DEFAULT false, p_enforcement text DEFAULT 'WARN'::text, p_building_id uuid DEFAULT NULL::uuid, p_effective_from_month text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_month date; v_id uuid; v_locked int;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_service_kind NOT IN ('AIR_CONDITIONER','WASHING_MACHINE') THEN
    RAISE EXCEPTION 'Hạng mục chỉ nhận AIR_CONDITIONER hoặc WASHING_MACHINE' USING ERRCODE='22023';
  END IF;
  IF p_enforcement NOT IN ('WARN','BLOCK') THEN
    RAISE EXCEPTION 'enforcement chỉ nhận WARN hoặc BLOCK' USING ERRCODE='22023';
  END IF;

  IF p_building_id IS NOT NULL THEN
    SELECT b.organization_id INTO v_org FROM public.buildings b
     WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='P0002'; END IF;
  ELSE
    v_org := COALESCE(p_organization_id,
      (SELECT m.organization_id FROM public.organization_memberships m
        WHERE m.user_id = v_actor AND m.status='ACTIVE' LIMIT 1));
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không xác định được tổ chức' USING ERRCODE='22023'; END IF;
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION 'Chỉ chủ tổ chức mới đặt được luật bảo trì' USING ERRCODE='42501';
  END IF;

  v_month := CASE WHEN p_effective_from_month IS NULL
    THEN date_trunc('month', public.org_today_v1(v_org))::date
    ELSE to_date(p_effective_from_month || '-01','YYYY-MM-DD') END;

  UPDATE app_private.maintenance_rule_versions
     SET status='RETIRED', retired_at=now()
   WHERE organization_id=v_org AND service_kind=p_service_kind
     AND COALESCE(building_id,'00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_building_id,'00000000-0000-0000-0000-000000000000'::uuid)
     AND effective_from_month=v_month AND status='PUBLISHED';

  INSERT INTO app_private.maintenance_rule_versions
    (organization_id, building_id, service_kind, effective_from_month,
     standard_amount, ceiling_amount, min_months_between, counts_history,
     enforcement, note, created_by)
  VALUES (v_org, p_building_id, p_service_kind, v_month,
          p_standard_amount, p_ceiling_amount, p_min_months_between,
          COALESCE(p_counts_history,false), p_enforcement,
          NULLIF(btrim(COALESCE(p_note,'')),''), v_actor)
  RETURNING id INTO v_id;

  -- Nếu chủ bật tính-cả-lịch-sử thì ĐẾM THẬT xem sẽ khoá bao nhiêu phòng/toà
  -- và trả về ngay, để chủ thấy hệ quả bằng con số chứ không phải lời hứa.
  v_locked := 0;
  IF COALESCE(p_counts_history,false) AND p_min_months_between IS NOT NULL THEN
    SELECT count(DISTINCT COALESCE(ie.room_id, ie.building_id)) INTO v_locked
      FROM public.income_expenses ie
      JOIN public.income_expense_items it ON it.income_expense_id = ie.id
      JOIN public.income_expense_types t  ON t.id = it.income_expense_type_id
     WHERE ie.organization_id = v_org AND ie.deleted_at IS NULL
       AND ie.approval_status <> 'CANCELLED' AND ie.type='EXPENSE'
       AND public.nrm_vn(t.category) LIKE 'bao tri%'
       AND (CASE WHEN p_service_kind='AIR_CONDITIONER'
                 THEN public.nrm_vn(t.category) LIKE '%may lanh%'
                 ELSE public.nrm_vn(t.category) LIKE '%may giat%' END)
       AND (p_building_id IS NULL OR ie.building_id = p_building_id)
       AND ie.voucher_date > (public.org_today_v1(v_org) - (p_min_months_between * 31));
  END IF;

  RETURN jsonb_build_object('id', v_id, 'serviceKind', p_service_kind,
    'standardAmount', p_standard_amount, 'ceilingAmount', p_ceiling_amount,
    'minMonthsBetween', p_min_months_between, 'countsHistory', COALESCE(p_counts_history,false),
    'enforcement', p_enforcement, 'effectiveFrom', to_char(v_month,'YYYY-MM'),
    'wouldLockNow', v_locked,
    'note', CASE
      WHEN COALESCE(p_counts_history,false) AND v_locked > 0
        THEN 'CẢNH BÁO: tính cả lịch sử ⇒ ' || v_locked
             || ' phòng/toà đã bảo trì gần đây đang bị khoá cho tới khi đủ '
             || p_min_months_between || ' tháng.'
      WHEN p_min_months_between IS NOT NULL
        THEN 'Chỉ tính các lần bảo trì TỪ tháng ' || to_char(v_month,'MM/YYYY')
             || ' trở đi — không khoá phòng nào vì việc đã làm trước đó.'
      ELSE 'Đã đặt mức giá. Chưa áp luật giãn cách.'
    END);
END;
$$;








--
-- Name: set_material_adjustment_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_material_adjustment_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_day TEXT;
BEGIN
  IF NEW.code IS NULL OR NEW.code = '' THEN
    v_day := to_char(now(), 'YYYYMMDD');
    PERFORM pg_advisory_xact_lock(hashtext('MA-' || v_day));
    NEW.code := 'MA-' || v_day || '-' || LPAD(
      (SELECT COALESCE(MAX(CAST(SUBSTRING(code FROM 'MA-\d{8}-(\d+)') AS INTEGER)), 0) + 1
       FROM public.material_adjustments
       WHERE code LIKE 'MA-' || v_day || '-%')::TEXT,
      4, '0');
  END IF;
  RETURN NEW;
END;
$$;








