--
-- Name: set_membership_status_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_membership_status_v1(p_user_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org uuid; v_memb uuid; v_owner_cnt int; v_sa_deleted int := 0;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  if p_status not in ('ACTIVE','SUSPENDED','REVOKED') then
    raise exception 'Trạng thái không hợp lệ (ACTIVE/SUSPENDED/REVOKED)' using errcode='22023';
  end if;
  if p_user_id = v_actor then
    raise exception 'Không thể tự đổi trạng thái của chính mình' using errcode='42501';
  end if;

  -- org: nơi người thao tác giữ role Chủ sở hữu tổ chức và đối tượng là thành viên
  select m.organization_id, m.id into v_org, v_memb
    from public.organization_memberships m
   where m.user_id = p_user_id
     and (
       public.is_super_admin()
       or exists (
         select 1 from public.role_bindings rb
           join public.organization_memberships om
             on om.id = rb.membership_id and om.organization_id = rb.organization_id
            and om.user_id = v_actor and om.status = 'ACTIVE'
           join public.organization_roles r
             on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
          where rb.organization_id = m.organization_id
            and (rb.valid_to is null or rb.valid_to > now())
       )
     )
   order by (m.status = 'ACTIVE') desc
   limit 1;
  if v_memb is null then
    raise exception 'Không có quyền đổi trạng thái thành viên này' using errcode='42501';
  end if;

  -- không hạ cấp người chủ sở hữu cuối cùng
  if p_status <> 'ACTIVE' then
    select count(*) into v_owner_cnt
      from public.role_bindings rb
      join public.organization_memberships om
        on om.id = rb.membership_id and om.organization_id = rb.organization_id
       and om.status = 'ACTIVE'
      join public.organization_roles r
        on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
     where rb.organization_id = v_org
       and (rb.valid_to is null or rb.valid_to > now())
       and om.user_id <> p_user_id;
    if v_owner_cnt = 0 and exists (
      select 1 from public.role_bindings rb
        join public.organization_memberships om
          on om.id = rb.membership_id and om.organization_id = rb.organization_id
         and om.user_id = p_user_id
        join public.organization_roles r
          on r.id = rb.role_id and r.name = 'Chủ sở hữu tổ chức'
       where rb.organization_id = v_org and (rb.valid_to is null or rb.valid_to > now())
    ) then
      raise exception 'Không thể đình chỉ/thu hồi CHỦ SỞ HỮU CUỐI CÙNG của tổ chức' using errcode='42501';
    end if;
  end if;

  update public.organization_memberships
     set status = p_status,
         revoked_at = case when p_status = 'REVOKED' then now() else null end,
         activated_at = case when p_status = 'ACTIVE' then coalesce(activated_at, now()) else activated_at end,
         version = version + 1
   where id = v_memb;

  -- THU HỒI: gỡ luôn assignment legacy (trigger a80 đóng role_binding).
  if p_status = 'REVOKED' then
    delete from public.staff_assignments
     where staff_id = p_user_id and organization_id = v_org;
    get diagnostics v_sa_deleted = row_count;
  end if;

  update public.organizations
     set authorization_version = authorization_version + 1
   where id = v_org;

  return json_build_object('user_id', p_user_id, 'organization_id', v_org,
                           'status', p_status, 'assignments_removed', v_sa_deleted,
                           'reason', nullif(btrim(coalesce(p_reason,'')),''));
end;
$$;








--
-- Name: set_my_notification_preferences_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_notification_preferences_v1(p_organization_id uuid, p_prefs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_uid   uuid;
  v_norm  jsonb;
  k       text;
  v       jsonb;
begin
  v_uid := (select auth.uid());
  if v_uid is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  perform app_private.assert_notification_membership_v1(p_organization_id);

  v_norm := app_private.notification_prefs_normalize_v1(p_prefs);

  for k in select jsonb_object_keys(v_norm) loop
    v := v_norm -> k;
    -- Field vắng ⇒ normalize phát `null` ⇒ INSERT lấy mặc định cột, UPDATE GIỮ NGUYÊN giá trị cũ.
    -- Không có coalesce ở đây thì `{"E1":{"in_app":false}}` sẽ set push=NULL rồi vi phạm NOT NULL,
    -- hoặc (bản nháp) ghi đè push=true — bật lại thứ người dùng vừa tắt.
    insert into public.notification_preferences
      (user_id, organization_id, event_key, in_app, push, cadence, updated_at)
    values
      (v_uid, p_organization_id, k,
       coalesce((v ->> 'in_app')::boolean, true),
       coalesce((v ->> 'push')::boolean, true),
       coalesce(v ->> 'cadence', 'IMMEDIATE'),
       now())
    -- ⚠ Dùng THẲNG biến plpgsql `v`, KHÔNG dùng `excluded.*`: mệnh đề VALUES ở trên đã coalesce
    -- nên `excluded.in_app` không bao giờ NULL và vế coalesce sẽ vô hiệu. `v` giữ đúng JSON gốc,
    -- nên `(v->>'in_app')::boolean` là NULL khi client KHÔNG gửi field đó.
    on conflict (user_id, organization_id, event_key) do update
      set in_app     = coalesce((v ->> 'in_app')::boolean, public.notification_preferences.in_app),
          push       = coalesce((v ->> 'push')::boolean,   public.notification_preferences.push),
          cadence    = coalesce(v ->> 'cadence',           public.notification_preferences.cadence),
          updated_at = now();
  end loop;

  return jsonb_build_object(
    'organization_id', p_organization_id,
    'user_id',         v_uid,
    'preferences',     app_private.notification_prefs_read_v1(v_uid, p_organization_id));
end
$$;








--
-- Name: FUNCTION set_my_notification_preferences_v1(p_organization_id uuid, p_prefs jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_my_notification_preferences_v1(p_organization_id uuid, p_prefs jsonb) IS 'Lưu sở thích thông báo của CHÍNH MÌNH. p_prefs = {"E1":{"in_app":bool,"push":bool,"cadence":"IMMEDIATE|DIGEST|OFF"},…}; chỉ những họ được gửi lên mới bị ghi đè. Cổng: membership ACTIVE.';








--
-- Name: set_my_ui_preference(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_ui_preference(p_key text, p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_preferences JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  IF p_key IS NULL OR btrim(p_key) = '' OR length(p_key) > 100 THEN
    RAISE EXCEPTION 'INVALID_UI_PREFERENCE_KEY';
  END IF;

  UPDATE public.profiles p
  SET ui_preferences = jsonb_set(
        COALESCE(p.ui_preferences, '{}'::jsonb),
        ARRAY[p_key],
        COALESCE(p_value, 'null'::jsonb),
        true
      )
  WHERE p.id = auth.uid()
  RETURNING p.ui_preferences INTO v_preferences;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND';
  END IF;

  RETURN v_preferences;
END;
$$;








--
-- Name: set_notification_org_config_v1(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_org_config_v1(p_events jsonb DEFAULT NULL::jsonb, p_quiet_start integer DEFAULT NULL::integer, p_quiet_end integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
declare
  v_uid    uuid;
  v_org    uuid;
  v_cur    app_private.notification_org_config%rowtype;
  v_events jsonb;
  v_merged jsonb;
  v_k      text;
  v_start  smallint;
  v_end    smallint;
  v_row    app_private.notification_org_config%rowtype;
begin
  v_uid := (select auth.uid());
  if v_uid is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;

  v_org := app_private.current_admin_org_v1();
  if v_org is null then
    raise exception 'Không xác định được tổ chức quản trị. current_admin_org_v1() cần quyền users.view '
      '(hoặc super admin) — settings.edit một mình là chưa đủ.' using errcode = '42501';
  end if;
  perform app_private.require_perm_v1(v_org, 'settings.edit', 'sửa cấu hình thông báo của tổ chức');

  select * into v_cur
    from app_private.notification_org_config
   where organization_id = v_org
   for update;

  -- NULL = "giữ nguyên", không phải "đặt lại mặc định".
  -- 🔴 GHI ĐÈ THEO HỌ, KHÔNG THAY CẢ CỤM. Bản nháp normalize p_events rồi ghi đè toàn bộ cột
  -- `events` ⇒ chủ gạt một công tắc là 4 họ kia bị lên đạn lại về mặc định và min_amount bị xoá,
  -- không lỗi, không cảnh báo. Đo thật: {"E5":{"enabled":false}} → E5 off ✓ ;
  -- rồi {"E1":{"enabled":false}} → E5 QUAY LẠI enabled=true, min_amount của E1 → null.
  -- Nay: chuẩn hoá cấu hình HIỆN TẠI làm nền, rồi merge nông từng họ được gửi lên đè lên nền đó.
  -- ⚠ normalize() LUÔN điền đủ 5 họ (foreach trên v_keys), nên merge SAU khi chuẩn hoá là vô nghĩa.
  -- Phải merge trên JSON THÔ rồi mới chuẩn hoá một lần ở cuối.
  if p_events is null then
    v_events := app_private.notification_events_normalize_v1(v_cur.events);
  else
    -- (1) validate hình dạng + khoá lạ của p_events, ném lỗi tiếng Việt nếu sai.
    perform app_private.notification_events_normalize_v1(p_events);
    -- (2) merge SÂU tới cấp field: họ không gửi lên thì giữ nguyên; trong một họ, field không gửi
    --     lên cũng giữ nguyên (vd gửi {"E1":{"enabled":false}} KHÔNG xoá min_amount của E1).
    v_merged := coalesce(v_cur.events, '{}'::jsonb);
    for v_k in select jsonb_object_keys(p_events) loop
      v_merged := jsonb_set(
                    v_merged, array[v_k],
                    coalesce(v_merged -> v_k, '{}'::jsonb) || (p_events -> v_k),
                    true);
    end loop;
    v_events := app_private.notification_events_normalize_v1(v_merged);
  end if;

  v_start := coalesce(p_quiet_start, v_cur.quiet_start, 21)::smallint;
  v_end   := coalesce(p_quiet_end,   v_cur.quiet_end,   7)::smallint;

  -- Kiểm trước CHECK để lỗi ra tiếng Việt thay vì 23514 khó hiểu.
  if v_start < 0 or v_start > 23 then
    raise exception 'Giờ bắt đầu yên phải trong khoảng 0..23 (giờ VN).' using errcode = '22023';
  end if;
  if v_end < 0 or v_end > 23 then
    raise exception 'Giờ kết thúc yên phải trong khoảng 0..23 (giờ VN).' using errcode = '22023';
  end if;

  insert into app_private.notification_org_config
    (organization_id, events, quiet_start, quiet_end, updated_by, updated_at)
  values
    (v_org, v_events, v_start, v_end, v_uid, now())
  on conflict (organization_id) do update
    set events      = excluded.events,
        quiet_start = excluded.quiet_start,
        quiet_end   = excluded.quiet_end,
        updated_by  = excluded.updated_by,
        updated_at  = now()
  returning * into v_row;

  return jsonb_build_object(
    'organization_id', v_row.organization_id,
    'configured',      true,
    'events',          v_row.events,
    'quiet_start',     v_row.quiet_start,
    'quiet_end',       v_row.quiet_end,
    'quiet_timezone',  'Asia/Ho_Chi_Minh',
    'updated_by',      v_row.updated_by,
    'updated_at',      v_row.updated_at);
end
$$;








--
-- Name: FUNCTION set_notification_org_config_v1(p_events jsonb, p_quiet_start integer, p_quiet_end integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_notification_org_config_v1(p_events jsonb, p_quiet_start integer, p_quiet_end integer) IS 'Lưu khoá mở thông báo của tổ chức quản trị hiện tại. Cổng: settings.edit qua require_perm_v1. Tham số NULL = giữ nguyên giá trị cũ. quiet_start/quiet_end là GIỜ VN (Asia/Ho_Chi_Minh).';








