--
-- Name: TABLE room_pass_listings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.room_pass_listings IS 'Phòng khách nhờ sale/pass: overlay lên phòng đang có khách để hiển thị trên kênh công khai. KHÔNG đụng rooms.status/HĐ.';








--
-- Name: COLUMN room_pass_listings.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.room_pass_listings.user_id IS 'Owner của tòa (buildings.user_id) — để trang public match buildings.user_id = owner-của-token.';








--
-- Name: COLUMN room_pass_listings.contact_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.room_pass_listings.contact_name IS 'Tên KHÁCH — EXPOSE CÓ Ý qua RPC public (opt-in).';








--
-- Name: COLUMN room_pass_listings.contact_phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.room_pass_listings.contact_phone IS 'SĐT của KHÁCH — EXPOSE CÓ Ý qua RPC public (opt-in). Ngoại lệ so với quy tắc anon không thấy khách thuê.';








--
-- Name: COLUMN room_pass_listings.avail_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.room_pass_listings.avail_date IS 'Ngày dự kiến trống phòng (tuỳ chọn) — hiển thị "trống từ …" trên trang công khai.';








--
-- Name: COLUMN room_pass_listings.contact_manager; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.room_pass_listings.contact_manager IS 'TRUE = khách nhờ "gọi cho quản lý", ẩn SĐT/tên khách trên trang công khai (RPC public không trả contact_phone/contact_name). SĐT khách vẫn ghi nội bộ.';








--
-- Name: set_room_pass_listing_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_room_pass_listing_active(p_id uuid, p_active boolean) RETURNS public.room_pass_listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.room_pass_listings;
BEGIN
  SELECT * INTO v_row FROM public.room_pass_listings WHERE id = p_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Listing không tồn tại';
  END IF;
  IF NOT public.can_manage_pass_listing(v_row.building_id, v_row.user_id) THEN
    RAISE EXCEPTION 'Không có quyền quản lý phòng khách nhờ sale cho tòa này';
  END IF;

  UPDATE public.room_pass_listings
    SET active = p_active, updated_at = now()
  WHERE id = p_id
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;








--
-- Name: set_salary_v5_config(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_salary_v5_config(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner UUID;
  v_rules JSONB;
  v_money JSONB := '{}'::jsonb;
  v_now   JSONB := '{}'::jsonb;
  v_key   TEXT;
  v_audit JSONB;
  v_next_month DATE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Chỉ chủ được đổi cấu hình lương v5';
  END IF;
  SELECT user_id INTO v_owner FROM public.super_admins ORDER BY created_at LIMIT 1;
  SELECT rules INTO v_rules FROM public.salary_bonus_rules WHERE user_id = v_owner FOR UPDATE;

  FOR v_key IN SELECT jsonb_object_keys(p_patch) LOOP
    IF v_key IN ('attendance_v5','streak_v5') THEN
      v_money := v_money || jsonb_build_object(v_key, (COALESCE(v_rules->v_key,'{}'::jsonb)) || (p_patch->v_key));
    ELSIF v_key IN ('coverage_v5','system_v5') THEN
      v_now := v_now || jsonb_build_object(v_key, (COALESCE(v_rules->v_key,'{}'::jsonb)) || (p_patch->v_key));
    ELSE
      RAISE EXCEPTION 'Block không hợp lệ: %', v_key;
    END IF;
  END LOOP;

  -- validate bất biến: Σ deltas = streak budget (nếu đổi streak_v5)
  IF v_money ? 'streak_v5' THEN
    IF (SELECT COALESCE(SUM(value::numeric),0) FROM jsonb_array_elements_text(v_money->'streak_v5'->'deltas'))
       <> (v_money->'streak_v5'->>'budget')::numeric THEN
      RAISE EXCEPTION 'Σ deltas phải bằng streak budget';
    END IF;
  END IF;
  IF v_money ? 'attendance_v5' THEN
    IF (v_money->'attendance_v5'->>'paid_leave_days_per_month')::int NOT BETWEEN 0 AND 4 THEN
      RAISE EXCEPTION 'paid_leave_days_per_month phải trong [0,4]';
    END IF;
  END IF;

  v_next_month := (date_trunc('month', public.vn_local_date(now())) + INTERVAL '1 month')::date;
  v_audit := COALESCE(v_rules->'system_v5'->'audit', '[]'::jsonb);
  v_audit := (v_audit || jsonb_build_array(jsonb_build_object(
    'at', now(), 'by', auth.uid(), 'patch', p_patch,
    'money_effective', CASE WHEN v_money <> '{}'::jsonb THEN to_jsonb(v_next_month) ELSE NULL END
  )));
  -- giữ tối đa 50 entry audit
  IF jsonb_array_length(v_audit) > 50 THEN
    v_audit := (SELECT jsonb_agg(e) FROM (
      SELECT e FROM jsonb_array_elements(v_audit) WITH ORDINALITY t(e, i)
      ORDER BY i DESC LIMIT 50) s);
  END IF;

  v_rules := v_rules || v_now; -- áp ngay coverage/system
  IF v_money <> '{}'::jsonb THEN
    v_rules := jsonb_set(v_rules, '{system_v5,pending_money_patch}',
      jsonb_build_object('patch', v_money, 'effective_month', v_next_month));
  END IF;
  v_rules := jsonb_set(v_rules, '{system_v5,audit}', v_audit);
  v_rules := jsonb_set(v_rules, '{system_v5,config_version}',
    to_jsonb(COALESCE((v_rules->'system_v5'->>'config_version')::int, 1) + 1));

  UPDATE public.salary_bonus_rules SET rules = v_rules, updated_at = now() WHERE user_id = v_owner;
  RETURN public.get_salary_v5_config();
END;
$$;








--
-- Name: set_sale_bonus_cap_v1(numeric, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sale_bonus_cap_v1(p_cap_amount numeric, p_building_id uuid DEFAULT NULL::uuid, p_effective_from_month text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_month date;
  v_id    uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_cap_amount IS NULL OR p_cap_amount <= 0 THEN
    RAISE EXCEPTION 'Trần thưởng phải lớn hơn 0' USING ERRCODE = '22023';
  END IF;

  IF p_building_id IS NOT NULL THEN
    SELECT b.organization_id INTO v_org FROM public.buildings b
     WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE = 'P0002'; END IF;
  ELSE
    v_org := p_organization_id;
    IF v_org IS NULL THEN
      SELECT m.organization_id INTO v_org FROM public.organization_memberships m
       WHERE m.user_id = v_actor AND m.status = 'ACTIVE' LIMIT 1;
    END IF;
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'Không xác định được tổ chức' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION
      'Chỉ chủ tổ chức mới đặt được trần thưởng Sale — con số này chặn tiền ra két.'
      USING ERRCODE = '42501';
  END IF;

  IF p_effective_from_month IS NULL THEN
    v_month := date_trunc('month', public.org_today_v1(v_org))::date;
  ELSE
    IF p_effective_from_month !~ '^\d{4}-\d{2}$' THEN
      RAISE EXCEPTION 'Tháng hiệu lực phải dạng YYYY-MM' USING ERRCODE = '22023';
    END IF;
    v_month := to_date(p_effective_from_month || '-01', 'YYYY-MM-DD');
  END IF;

  UPDATE app_private.sale_bonus_cap_versions
     SET status = 'RETIRED', retired_at = now()
   WHERE organization_id = v_org
     AND COALESCE(building_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_building_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND effective_from_month = v_month
     AND status = 'PUBLISHED';

  INSERT INTO app_private.sale_bonus_cap_versions
    (organization_id, building_id, effective_from_month, cap_amount, note, created_by)
  VALUES (v_org, p_building_id, v_month, round(p_cap_amount, 2),
          NULLIF(btrim(COALESCE(p_note,'')), ''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id, 'capAmount', round(p_cap_amount, 2),
    'buildingId', p_building_id,
    'effectiveFrom', to_char(v_month, 'YYYY-MM'),
    'note', CASE WHEN p_building_id IS NULL
      THEN 'Trần chung cho cả tổ chức, áp dụng từ tháng ' || to_char(v_month, 'MM/YYYY') || '.'
      ELSE 'Trần riêng của toà này, áp dụng từ tháng ' || to_char(v_month, 'MM/YYYY') || '. Trần riêng thắng trần chung.'
    END);
END;
$_$;








--
-- Name: set_special_fee_price_v1(uuid, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_special_fee_price_v1(p_building_id uuid, p_fee_category text, p_amount numeric, p_effective_from_month text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_month date;
  v_id    uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_fee_category NOT IN ('tien_nha','dien','nuoc','internet','quan_ly',
                            've_sinh','cong_an','rac','thang_may') THEN
    RAISE EXCEPTION 'Hạng mục phí không hợp lệ: %', p_fee_category USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Giá công bố phải lớn hơn 0' USING ERRCODE = '22023';
  END IF;

  SELECT b.organization_id INTO v_org FROM public.buildings b
   WHERE b.id = p_building_id AND b.deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION
      'Chỉ chủ tổ chức mới công bố được giá phí cố định. Giá này quyết định phiếu nào được tự duyệt, nên không mở cho người khác.'
      USING ERRCODE = '42501';
  END IF;

  IF p_effective_from_month IS NULL THEN
    v_month := date_trunc('month', public.org_today_v1(v_org))::date;
  ELSE
    IF p_effective_from_month !~ '^\d{4}-\d{2}$' THEN
      RAISE EXCEPTION 'Tháng hiệu lực phải dạng YYYY-MM' USING ERRCODE = '22023';
    END IF;
    v_month := to_date(p_effective_from_month || '-01', 'YYYY-MM-DD');
  END IF;

  -- Công bố lại cho CÙNG tháng hiệu lực: cho bản cũ nghỉ, không xoá.
  UPDATE app_private.special_fee_price_versions
     SET status = 'RETIRED', retired_at = now()
   WHERE organization_id = v_org AND building_id = p_building_id
     AND fee_category = p_fee_category AND effective_from_month = v_month
     AND status = 'PUBLISHED';

  INSERT INTO app_private.special_fee_price_versions
    (organization_id, building_id, fee_category, effective_from_month,
     amount, source, note, created_by)
  VALUES (v_org, p_building_id, p_fee_category, v_month,
          round(p_amount, 2), 'OWNER', NULLIF(btrim(COALESCE(p_note,'')), ''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id, 'buildingId', p_building_id, 'feeCategory', p_fee_category,
    'amount', round(p_amount, 2), 'effectiveFrom', to_char(v_month, 'YYYY-MM'),
    'note', 'Giá áp dụng từ tháng ' || to_char(v_month, 'MM/YYYY') || '. Phiếu các tháng trước giữ nguyên giá cũ.');
END;
$_$;








--
-- Name: FUNCTION set_special_fee_price_v1(p_building_id uuid, p_fee_category text, p_amount numeric, p_effective_from_month text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_special_fee_price_v1(p_building_id uuid, p_fee_category text, p_amount numeric, p_effective_from_month text, p_note text) IS 'Chủ tổ chức công bố giá phí cố định cho một toà × hạng mục, áp dụng TỪ THÁNG chỉ định. Đổi giá = thêm bản mới, bản cũ chuyển RETIRED chứ không xoá, nên phiếu tháng trước vẫn đối chiếu được. Cố ý chỉ mở cho chủ: giá này quyết định phiếu nào được tự duyệt.';








--
-- Name: set_termination_forfeit_status_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_termination_forfeit_status_v1(p_voucher_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_authorization app_private.termination_forfeit_authorizations%ROWTYPE;
  v_building uuid;
  v_allowed boolean;
  v_core_writer boolean;
  v_opened_writer boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF upper(COALESCE(p_status, '')) NOT IN (
    'APPROVED', 'UNAPPROVED', 'CANCELLED'
  ) THEN
    RAISE EXCEPTION 'Unsupported forfeit voucher status'
      USING ERRCODE = '22023';
  END IF;

  SELECT auth_row.*
    INTO v_authorization
  FROM app_private.termination_forfeit_authorizations auth_row
  WHERE auth_row.revenue_voucher_id = p_voucher_id
     OR auth_row.offset_voucher_id = p_voucher_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Voucher is not a termination forfeit pair'
      USING ERRCODE = '55000';
  END IF;

  -- Lock both legs before changing either one so opposite-leg requests cannot
  -- acquire the pair in a conflicting order.
  PERFORM 1
  FROM public.income_expenses voucher
  WHERE voucher.id IN (
    v_authorization.revenue_voucher_id,
    v_authorization.offset_voucher_id
  )
  ORDER BY voucher.id
  FOR UPDATE;

  SELECT room_row.building_id
    INTO v_building
  FROM public.contracts contract_row
  JOIN public.rooms room_row ON room_row.id = contract_row.room_id
  WHERE contract_row.id = v_authorization.contract_id
    AND contract_row.organization_id = v_authorization.organization_id;

  PERFORM app_private.lock_org_for_decision_v1(
    v_authorization.organization_id
  );
  SELECT decision.allowed
    INTO v_allowed
  FROM app_private.authorize_tenant_action_v3(
    v_actor,
    v_authorization.organization_id,
    'income_expenses.approve',
    v_building,
    NULL
  ) decision;
  IF NOT (public.is_super_admin() OR COALESCE(v_allowed, false)) THEN
    RAISE EXCEPTION 'Missing elevated permission to change forfeit voucher status'
      USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.assert_no_engine_request_v1(
    v_authorization.revenue_voucher_id
  );
  PERFORM app_private.assert_no_engine_request_v1(
    v_authorization.offset_voucher_id
  );

  IF upper(p_status) <> 'CANCELLED' AND EXISTS (
    SELECT 1
    FROM public.income_expenses voucher
    WHERE voucher.id IN (
      v_authorization.revenue_voucher_id,
      v_authorization.offset_voucher_id
    )
      AND voucher.approval_status = 'CANCELLED'
  ) THEN
    RAISE EXCEPTION 'Cancelled forfeit vouchers are terminal'
      USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;
  IF NOT v_core_writer THEN
    PERFORM app_private.begin_accounting_chain_write_v1();
    v_opened_writer := true;
  END IF;

  BEGIN
    INSERT INTO app_private.ie_transition_authorization (
      income_expense_id, xid, purpose
    ) VALUES
      (
        v_authorization.revenue_voucher_id,
        pg_current_xact_id(),
        upper(p_status)
      ),
      (
        v_authorization.offset_voucher_id,
        pg_current_xact_id(),
        upper(p_status)
      );

    UPDATE public.income_expenses voucher
       SET approval_status = upper(p_status),
           approved_by = CASE
             WHEN upper(p_status) = 'APPROVED' THEN v_actor
             ELSE NULL
           END,
           approved_at = CASE
             WHEN upper(p_status) = 'APPROVED' THEN now()
             ELSE NULL
           END,
           -- Cùng luật với nút Huỷ duyệt: hạ về UNAPPROVED thì phải mở lại
           -- vòng duyệt, không thì phiếu thanh lý kẹt y hệt PC2607005.
           review_state = CASE
             WHEN upper(p_status) = 'UNAPPROVED' THEN 'PENDING'
             ELSE 'RESOLVED'
           END,
           review_version = voucher.review_version + 1,
           updated_at = now()
     WHERE voucher.id = v_authorization.revenue_voucher_id
       AND voucher.deleted_at IS NULL
       AND voucher.approval_status IS DISTINCT FROM upper(p_status);

    DELETE FROM app_private.ie_transition_authorization transition_row
    WHERE transition_row.income_expense_id IN (
      v_authorization.revenue_voucher_id,
      v_authorization.offset_voucher_id
    )
      AND transition_row.xid = pg_current_xact_id();
  EXCEPTION WHEN OTHERS THEN
    DELETE FROM app_private.ie_transition_authorization transition_row
    WHERE transition_row.income_expense_id IN (
      v_authorization.revenue_voucher_id,
      v_authorization.offset_voucher_id
    )
      AND transition_row.xid = pg_current_xact_id();
    IF v_opened_writer THEN
      PERFORM app_private.end_accounting_chain_write_v1();
    END IF;
    RAISE;
  END;

  IF v_opened_writer THEN
    PERFORM app_private.end_accounting_chain_write_v1();
  END IF;
END;
$$;








--
-- Name: set_user_id_from_auth(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_id_from_auth() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.user_id IS NULL THEN
    NEW.user_id := auth.uid();
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION set_user_id_from_auth(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_user_id_from_auth() IS 'BEFORE INSERT trigger: nếu NEW.user_id NULL thì gán auth.uid(). Dùng cho audit; không tham gia access control.';








--
-- Name: set_utility_ceiling_v1(text, numeric, numeric, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_utility_ceiling_v1(p_utility_type text, p_ceiling_amount numeric DEFAULT NULL::numeric, p_max_ratio_to_billed numeric DEFAULT NULL::numeric, p_building_id uuid DEFAULT NULL::uuid, p_effective_from_month text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_month date; v_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_utility_type NOT IN ('ELECTRIC','WATER') THEN
    RAISE EXCEPTION 'Loại chỉ nhận ELECTRIC hoặc WATER' USING ERRCODE='22023';
  END IF;
  IF p_ceiling_amount IS NULL AND p_max_ratio_to_billed IS NULL THEN
    RAISE EXCEPTION 'Phải đặt ít nhất một trong hai: trần tiền, hoặc tỉ lệ so với tiền đã thu'
      USING ERRCODE='22023';
  END IF;

  IF p_building_id IS NOT NULL THEN
    SELECT b.organization_id INTO v_org FROM public.buildings b
     WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='P0002'; END IF;
  ELSE
    v_org := COALESCE(p_organization_id,
      (SELECT m.organization_id FROM public.organization_memberships m
        WHERE m.user_id = v_actor AND m.status='ACTIVE' LIMIT 1));
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không xác định được tổ chức' USING ERRCODE='22023'; END IF;
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION 'Chỉ chủ tổ chức mới đặt được trần chi' USING ERRCODE='42501';
  END IF;

  v_month := CASE WHEN p_effective_from_month IS NULL
    THEN date_trunc('month', public.org_today_v1(v_org))::date
    ELSE to_date(p_effective_from_month || '-01','YYYY-MM-DD') END;

  UPDATE app_private.utility_ceiling_versions
     SET status='RETIRED', retired_at=now()
   WHERE organization_id=v_org AND utility_type=p_utility_type
     AND COALESCE(building_id,'00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_building_id,'00000000-0000-0000-0000-000000000000'::uuid)
     AND effective_from_month=v_month AND status='PUBLISHED';

  INSERT INTO app_private.utility_ceiling_versions
    (organization_id, building_id, utility_type, effective_from_month,
     ceiling_amount, max_ratio_to_billed, note, created_by)
  VALUES (v_org, p_building_id, p_utility_type, v_month,
          p_ceiling_amount, p_max_ratio_to_billed,
          NULLIF(btrim(COALESCE(p_note,'')),''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'utilityType', p_utility_type,
    'ceilingAmount', p_ceiling_amount, 'maxRatio', p_max_ratio_to_billed,
    'effectiveFrom', to_char(v_month,'YYYY-MM'),
    'note','Vượt trần thì phiếu vẫn tạo được nhưng nằm chờ duyệt kèm lý do.');
END;
$$;








--
-- Name: settle_previous_debt_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_previous_debt_sources() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  src       jsonb;
  src_type  text;
  src_id    uuid;
  src_amt   numeric;
  c_id      uuid;
  v_marker  text;
BEGIN
  IF NEW.status <> 'PAID' THEN RETURN NEW; END IF;
  IF OLD.status = 'PAID' THEN RETURN NEW; END IF;
  IF NEW.previous_debt_sources IS NULL
     OR jsonb_typeof(NEW.previous_debt_sources) <> 'array'
     OR jsonb_array_length(NEW.previous_debt_sources) = 0 THEN
    RETURN NEW;
  END IF;

  v_marker := '[Tự động tất toán qua HĐ '
              || COALESCE(NEW.invoice_number, NEW.id::text) || ']';

  FOR src IN SELECT * FROM jsonb_array_elements(NEW.previous_debt_sources) LOOP
    src_type := src->>'type';
    src_amt  := COALESCE((src->>'amount')::numeric, 0);
    IF src_amt <= 0 THEN CONTINUE; END IF;

    IF src_type = 'invoice' THEN
      src_id := NULLIF(src->>'id', '')::uuid;
      IF src_id IS NULL THEN CONTINUE; END IF;

      -- [B1] CHỈ ghi chú. KHÔNG còn ghi paid_amount/status/paid_date — số tiền
      -- do recompute_invoice_for_id suy ra, nên nó bền trước mọi lần tính lại.
      -- Phải chạy TRƯỚC recompute vì điều kiện là status <> 'PAID'.
      UPDATE public.invoices
         SET notes = CASE
                       WHEN notes IS NULL OR notes = '' THEN v_marker
                       ELSE notes || E'\n' || v_marker
                     END
       WHERE id = src_id
         AND status <> 'PAID'
         AND deleted_at IS NULL
         AND COALESCE(notes, '') NOT LIKE '%' || v_marker || '%';

      PERFORM public.recompute_invoice_for_id(src_id);

    ELSIF src_type = 'deposit' THEN
      -- CỐ Ý GIỮ NGUYÊN: nhánh cọc ghi thẳng contracts.deposit_paid. Đây là
      -- vấn đề riêng (cùng lớp lỗi) và cần chủ quyết định — không gộp vào đây.
      c_id := NULLIF(src->>'contract_id', '')::uuid;
      IF c_id IS NULL THEN CONTINUE; END IF;
      UPDATE public.contracts
         SET deposit_paid = LEAST(COALESCE(total_deposit, 0),
                                  COALESCE(deposit_paid, 0) + src_amt)
       WHERE id = c_id;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;








