--
-- Name: soft_delete_customer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_customer(p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE customers
  SET deleted_at = NOW()
  WHERE id = p_customer_id
    AND (user_id = auth.uid() OR public.is_super_admin())
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Customer not found or not authorized';
  END IF;
END;
$$;








--
-- Name: soft_delete_invoice_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_invoice_v1(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to delete invoice'
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = p_invoice_id
  ) THEN
    RAISE EXCEPTION 'Use soft_delete_invoice_with_credit_v1 for this invoice'
      USING ERRCODE = '55000';
  END IF;
  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  IF v_invoice.status NOT IN ('DRAFT', 'APPROVED')
     OR COALESCE(v_invoice.paid_amount, 0) <> 0 THEN
    RAISE EXCEPTION 'Invoice cannot be deleted in its current state'
      USING ERRCODE = '55000';
  END IF;
  UPDATE public.invoices
     SET deleted_at = clock_timestamp()
   WHERE id = p_invoice_id;
END;
$$;








--
-- Name: soft_delete_invoice_with_credit_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_invoice_with_credit_v1(p_invoice_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_credit jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF v_invoice.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'invoice_id', p_invoice_id,
      'credit', NULL,
      'noop', true
    );
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to delete invoice'
      USING ERRCODE = '42501';
  END IF;
  IF v_invoice.status NOT IN ('DRAFT', 'APPROVED')
     OR COALESCE(v_invoice.paid_amount, 0) <> 0 THEN
    RAISE EXCEPTION 'Invoice cannot be deleted in its current state'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  v_credit := app_private.reverse_invoice_customer_credit_v1(
    v_actor, p_invoice_id, 'Delete invoice and restore applied customer credit', v_key
  );

  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.invoices
     SET deleted_at = clock_timestamp()
   WHERE id = p_invoice_id;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'credit', v_credit,
    'noop', false
  );
END;
$_$;








--
-- Name: staff_building_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_building_scope(owner_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN bool_or(building_id IS NULL) THEN NULL
    ELSE COALESCE(array_agg(building_id), ARRAY[]::uuid[])
  END
  FROM public.staff_assignments
  WHERE staff_id = auth.uid() AND user_id = owner_id;
$$;








--
-- Name: staff_can(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_can(_table text, _action text, _owner uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
  select public.is_super_admin()
      or (_owner = any (public.current_visible_owner_ids())
          and app_private.has_any_scope_v3(_table || '.' || _action));
$$;








--
-- Name: staff_in_building(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_in_building(_owner uuid, _building_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.uid() = _owner
    OR public.is_admin()
    OR EXISTS (
      SELECT 1 FROM public.staff_assignments
      WHERE staff_id = auth.uid()
        AND user_id = _owner
        AND building_id IS NULL
        AND area_id IS NULL
    )
    OR (
      _building_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.staff_assignments
        WHERE staff_id = auth.uid()
          AND user_id = _owner
          AND building_id = _building_id
      )
    )
    OR (
      _building_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.staff_assignments sa
        JOIN public.area_buildings ab ON ab.area_id = sa.area_id
        WHERE sa.staff_id = auth.uid()
          AND sa.user_id = _owner
          AND ab.building_id = _building_id
      )
    );
$$;








--
-- Name: start_inspection(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_inspection(p_building uuid, p_type text DEFAULT 'FULL'::text, p_paired_income_expense_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_today DATE := public.vn_local_date(now());
  v_sess public.inspection_sessions;
  v_reqs JSONB;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập'; END IF;
  IF p_type NOT IN ('FULL','QUICK') THEN RAISE EXCEPTION 'type không hợp lệ'; END IF;
  IF NOT COALESCE(public.can_access_building(p_building), false) THEN
    RAISE EXCEPTION 'Không có quyền truy cập tòa nhà'
      USING ERRCODE = '42501';
  END IF;
  IF p_paired_income_expense_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.income_expenses ie
    WHERE ie.id = p_paired_income_expense_id
      AND ie.deleted_at IS NULL
      AND ie.building_id = p_building
      AND ie.collect_geofence_status = 'ok'
      AND (ie.user_id = v_uid OR public.is_admin())
  ) THEN
    RAISE EXCEPTION 'Phiếu thu ghép không hợp lệ'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('v5_insp' || v_uid::text || p_building::text || v_today::text));

  -- RESUME đúng phiên đang dở cùng ngày cùng toà (open/presence) — không tạo phiên mới
  SELECT * INTO v_sess FROM public.inspection_sessions
  WHERE user_id = v_uid AND building_id = p_building AND session_date = v_today
    AND status IN ('open','presence')
    AND (type = p_type OR p_type = 'FULL')  -- "Nâng cấp lên FULL": resume phiên QUICK thành FULL
  ORDER BY started_at DESC LIMIT 1;

  IF FOUND THEN
    IF v_sess.type = 'QUICK' AND p_type = 'FULL' THEN
      UPDATE public.inspection_sessions
      SET type = 'FULL', checklist = public.v5_checklist_for_building(p_building, v_today, 'FULL'),
          paired_income_expense_id = COALESCE(p_paired_income_expense_id, paired_income_expense_id),
          status = 'open', updated_at = now()
      WHERE id = v_sess.id RETURNING * INTO v_sess;
    ELSIF p_paired_income_expense_id IS NOT NULL AND v_sess.paired_income_expense_id IS NULL THEN
      UPDATE public.inspection_sessions SET paired_income_expense_id = p_paired_income_expense_id,
          status = 'open', updated_at = now()
      WHERE id = v_sess.id RETURNING * INTO v_sess;
    ELSIF v_sess.status = 'presence' THEN
      UPDATE public.inspection_sessions SET status = 'open', updated_at = now()
      WHERE id = v_sess.id RETURNING * INTO v_sess;
    END IF;
  ELSE
    INSERT INTO public.inspection_sessions
      (user_id, building_id, type, session_date, checklist, paired_income_expense_id,
       random_item_key)
    VALUES (v_uid, p_building, p_type, v_today,
            public.v5_checklist_for_building(p_building, v_today, p_type),
            p_paired_income_expense_id,
            NULL)
    RETURNING * INTO v_sess;
  END IF;

  v_reqs := public.v5_building_reqs(p_building);
  RETURN jsonb_build_object(
    'session_id', v_sess.id, 'type', v_sess.type, 'status', v_sess.status,
    'session_date', v_sess.session_date, 'checklist', v_sess.checklist,
    'reqs', v_reqs, 'photos_count', v_sess.photos_count, 'dwell_seconds', v_sess.dwell_seconds,
    'started_at', v_sess.started_at,
    'slot_counts', COALESCE(
      (SELECT jsonb_object_agg(t.slot, t.n)
       FROM (SELECT slot, COUNT(*)::int AS n FROM public.inspection_photos
             WHERE session_id = v_sess.id GROUP BY slot) t),
      '{}'::jsonb)
  );
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, source_id, error_text, payload)
  VALUES (v_uid, 'start_inspection', p_building, SQLERRM, jsonb_build_object('type', p_type));
  RAISE;
END;
$$;








