--
-- Name: submit_financial_voucher(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_financial_voucher(p_voucher uuid, p_idempotency_key text DEFAULT NULL::text, p_system_source text DEFAULT NULL::text, p_txn_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v record;
  v_org uuid; v_mem uuid; v_amount numeric;
  v_rule record; v_req uuid; v_state text; v_step uuid; v_cand int;
  v_existing uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;
  SELECT * INTO v FROM public.income_expenses WHERE id=p_voucher AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE='P0002'; END IF;
  v_org := v.organization_id; v_amount := COALESCE(v.total_amount,0);

  SELECT id INTO v_mem FROM public.organization_memberships
   WHERE user_id=v_uid AND organization_id=v_org AND status='ACTIVE' LIMIT 1;
  IF v_mem IS NULL AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Bạn không thuộc tổ chức của phiếu' USING ERRCODE='42501';
  END IF;
  IF v_mem IS NULL THEN
    SELECT id INTO v_mem FROM public.organization_memberships WHERE organization_id=v_org AND member_type='OWNER' LIMIT 1;
  END IF;

  -- Idempotency / one-open-request: nếu đã có request OPEN cho subject, trả lại.
  SELECT id INTO v_existing FROM public.approval_requests
   WHERE organization_id=v_org AND subject_type='FINANCIAL_VOUCHER' AND subject_id=p_voucher
     AND state IN ('PENDING_APPROVAL','POSTED') LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'request_id',v_existing,'idempotent',true);
  END IF;

  SELECT * INTO v_rule FROM public._eval_approval_rule(v_org, v_amount, p_txn_type, p_system_source, NULL, v.account_id, v.building_id);
  IF v_rule.rule_id IS NULL THEN
    RAISE EXCEPTION 'Không có rule set ACTIVE — fail closed' USING ERRCODE='42501';
  END IF;

  v_state := CASE v_rule.effect WHEN 'AUTO_POST' THEN 'POSTED' WHEN 'DENY' THEN 'DENIED' ELSE 'PENDING_APPROVAL' END;

  INSERT INTO public.approval_requests (organization_id, subject_type, subject_id, state,
      maker_membership_id, maker_user_id, rule_set_id, rule_set_version, matched_rule_id, rule_effect,
      payload_snapshot, payload_hash, amount, cashbook_id, building_id, system_source)
  VALUES (v_org, 'FINANCIAL_VOUCHER', p_voucher, v_state, v_mem, v_uid,
      v_rule.rule_set_id, v_rule.version, v_rule.rule_id, v_rule.effect,
      to_jsonb(v), md5(to_jsonb(v)::text), v_amount, v.account_id, v.building_id, p_system_source)
  RETURNING id INTO v_req;

  IF v_rule.effect='AUTO_POST' THEN
    PERFORM public._post_financial_voucher(p_voucher, v_req, v_uid);
  ELSIF v_rule.effect='REQUIRE_APPROVAL' THEN
    -- create step 1 + candidates (PERMISSION income_expenses.approve, exclude maker).
    INSERT INTO public.approval_request_steps (organization_id, request_id, step_no, status, mode, min_approvals, candidate_count)
    VALUES (v_org, v_req, 1, 'PENDING', 'ANY', 1, 0) RETURNING id INTO v_step;
    INSERT INTO public.approval_request_step_candidates (organization_id, request_step_id, membership_id, generation, source_kind)
    SELECT v_org, v_step, m.id, 1, 'PERMISSION'
    FROM public.organization_memberships m
    WHERE m.organization_id=v_org AND m.status='ACTIVE' AND m.id <> v_mem
      AND (m.member_type='OWNER'
           OR EXISTS(SELECT 1 FROM public.super_admins s WHERE s.user_id=m.user_id)
           OR (public.effective_perms_v2(m.user_id, v_org) -> 'income_expenses' ->> 'approve')='true');
    GET DIAGNOSTICS v_cand = ROW_COUNT;
    UPDATE public.approval_request_steps SET candidate_count=v_cand WHERE id=v_step;
    IF v_cand < 1 THEN
      RAISE EXCEPTION 'Không có người duyệt đủ điều kiện (fail closed)' USING ERRCODE='42501';
    END IF;
  END IF;

  RETURN jsonb_build_object('ok',true,'request_id',v_req,'effect',v_rule.effect,'state',v_state);
END; $$;








--
-- Name: submit_inspection_photo(uuid, text, text, text, numeric, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_inspection_photo(p_session uuid, p_slot text, p_storage_path text, p_sha256 text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_exif_time timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_sess public.inspection_sessions;
  v_b public.buildings;
  v_geo JSONB;
  v_dist INT;
  v_status TEXT;
  v_dup_day BOOLEAN;
  v_first TIMESTAMPTZ; v_last TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_sess FROM public.inspection_sessions WHERE id = p_session;
  IF NOT FOUND OR v_sess.user_id <> v_uid THEN RAISE EXCEPTION 'Phiên không hợp lệ'; END IF;
  IF v_sess.status NOT IN ('open','presence') THEN RAISE EXCEPTION 'Phiên đã đóng'; END IF;

  -- ảnh trùng hash trong CÙNG NGÀY của user (mọi phiên) → không tính (chống nộp lại/chụp hộ)
  SELECT EXISTS (
    SELECT 1 FROM public.inspection_photos ph
    JOIN public.inspection_sessions s2 ON s2.id = ph.session_id
    WHERE s2.user_id = v_uid AND s2.session_date = v_sess.session_date AND ph.sha256_hash = p_sha256
  ) INTO v_dup_day;
  IF v_dup_day THEN
    RETURN jsonb_build_object('accepted', false, 'reason', 'duplicate_hash',
      'message', 'Ảnh này đã dùng hôm nay — chụp ảnh mới tại chỗ nhé');
  END IF;

  SELECT * INTO v_b FROM public.buildings WHERE id = v_sess.building_id;
  v_geo := public.get_acceptance_geofence_config(); -- 1 nguồn sự thật bán kính (B11)
  IF p_lat IS NULL OR p_lng IS NULL THEN v_status := 'gps_denied'; v_dist := NULL;
  ELSIF v_b.latitude IS NULL OR v_b.longitude IS NULL THEN v_status := 'ok'; v_dist := NULL; -- toà chưa gắn toạ độ: không phạt oan
  ELSE
    v_dist := public.v5_distance_m(p_lat, p_lng, v_b.latitude, v_b.longitude);
    v_status := CASE WHEN v_dist <= COALESCE((v_geo->>'radius_m')::int, 70) THEN 'ok' ELSE 'out_of_range' END;
  END IF;

  INSERT INTO public.inspection_photos (session_id, slot, storage_path, sha256_hash, exif_time, lat, lng, distance_m, geofence_status)
  VALUES (p_session, p_slot, p_storage_path, p_sha256, COALESCE(p_exif_time, now()), p_lat, p_lng, v_dist, v_status)
  ON CONFLICT (session_id, sha256_hash) DO NOTHING;

  -- cập nhật checklist done + dwell (span ảnh đầu→cuối trong phiên) + photos_count
  SELECT MIN(created_at), MAX(created_at) INTO v_first, v_last
  FROM public.inspection_photos WHERE session_id = p_session;
  UPDATE public.inspection_sessions SET
    photos_count = (SELECT COUNT(*) FROM public.inspection_photos WHERE session_id = p_session),
    dwell_seconds = GREATEST(dwell_seconds, COALESCE(EXTRACT(EPOCH FROM (v_last - v_first))::int, 0)),
    checklist = (
      SELECT jsonb_agg(CASE WHEN item->>'key' = p_slot THEN item || '{"done":true}'::jsonb ELSE item END)
      FROM jsonb_array_elements(checklist) item),
    updated_at = now()
  WHERE id = p_session;

  RETURN jsonb_build_object('accepted', true, 'geofence_status', v_status, 'distance_m', v_dist);
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, source_id, error_text, payload)
  VALUES (v_uid, 'submit_inspection_photo', p_session, SQLERRM, jsonb_build_object('slot', p_slot));
  RAISE;
END; $$;








--
-- Name: super_admin_force_cancel_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.super_admin_force_cancel_invoice(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status invoice_status;
  v_deleted TIMESTAMPTZ;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Chỉ super admin được phép xoá hoá đơn ở trạng thái này';
  END IF;

  SELECT status, deleted_at INTO v_status, v_deleted
  FROM invoices
  WHERE id = p_invoice_id;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Hoá đơn không tồn tại';
  END IF;
  IF v_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'Hoá đơn đã bị xoá trước đó';
  END IF;
  IF v_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Hoá đơn đã ở trạng thái Đã huỷ';
  END IF;

  -- 1. Xoá excess_amounts gốc từ HĐ này (overpayment credit)
  DELETE FROM excess_amounts WHERE source_invoice_id = p_invoice_id;

  -- 2. Hard-delete payments. FK ON DELETE RESTRICT bị bypass nhờ
  --    SECURITY DEFINER chạy với quyền của owner function.
  --    Trigger trg_payments_recompute_invoice sẽ chạy AFTER DELETE và
  --    reset invoices.paid_amount=0, status='APPROVED'.
  DELETE FROM payments WHERE invoice_id = p_invoice_id;

  -- 3. Override status về CANCELLED (sau khi trigger đã chạy)
  UPDATE invoices SET status = 'CANCELLED' WHERE id = p_invoice_id;
END;
$$;








--
-- Name: super_admin_force_cancel_invoice_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.super_admin_force_cancel_invoice_v2(p_invoice_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%ROWTYPE;
  v_active_payments integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins may force-cancel invoices'
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF v_invoice.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Invoice was already deleted' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_credit_applications application_row
    WHERE application_row.invoice_id = p_invoice_id
  ) THEN
    RAISE EXCEPTION 'Use super_admin_force_cancel_invoice_with_credit_v1'
      USING ERRCODE = '55000';
  END IF;
  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  IF v_invoice.status = 'CANCELLED' THEN
    RETURN json_build_object(
      'invoice_id', p_invoice_id, 'status', 'CANCELLED', 'noop', true
    );
  END IF;
  SELECT count(*) INTO v_active_payments
  FROM public.payments payment
  WHERE payment.invoice_id = p_invoice_id
    AND payment.reversed_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM app_private.payment_reversals reversal
      WHERE reversal.original_payment_id = payment.id
    );
  IF v_active_payments > 0 THEN
    RAISE EXCEPTION 'Invoice still has % active payments; reverse them first',
      v_active_payments USING ERRCODE = '55000';
  END IF;
  UPDATE public.invoices
     SET status = 'CANCELLED'
   WHERE id = p_invoice_id;
  RETURN json_build_object(
    'invoice_id', p_invoice_id, 'status', 'CANCELLED', 'noop', false
  );
END;
$$;








--
-- Name: super_admin_force_cancel_invoice_with_credit_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.super_admin_force_cancel_invoice_with_credit_v1(p_invoice_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_active_payments integer;
  v_credit jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins may force-cancel invoices'
      USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF v_invoice.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Invoice was already deleted' USING ERRCODE = '55000';
  END IF;
  IF v_invoice.status = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'invoice_id', p_invoice_id,
      'status', 'CANCELLED',
      'credit', NULL,
      'noop', true
    );
  END IF;

  SELECT count(*) INTO v_active_payments
  FROM public.payments payment
  WHERE payment.invoice_id = p_invoice_id
    AND payment.reversed_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM app_private.payment_reversals reversal
      WHERE reversal.original_payment_id = payment.id
    );
  IF v_active_payments > 0 THEN
    RAISE EXCEPTION 'Invoice still has % active payments; reverse them first',
      v_active_payments USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  v_credit := app_private.reverse_invoice_customer_credit_v1(
    v_actor, p_invoice_id,
    'Force-cancel invoice and restore applied customer credit', v_key
  );

  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.invoices
     SET status = 'CANCELLED'
   WHERE id = p_invoice_id;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'status', 'CANCELLED',
    'credit', v_credit,
    'noop', false
  );
END;
$_$;








--
-- Name: terminate_contract_forfeit(uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_forfeit(p_contract_id uuid, p_forfeit_date date, p_extra_charges jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_room uuid;
  v_org uuid;
  v_core_writer boolean;
  v_opened_writer boolean := false;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT contract_row.room_id, contract_row.organization_id
    INTO v_room, v_org
  FROM public.contracts contract_row
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE OF contract_row;

  IF NOT (
    public.is_super_admin()
    OR (
      v_room IS NOT NULL
      AND public.can_do_on_building(
        'contracts', 'edit',
        (SELECT room_row.building_id
         FROM public.rooms room_row
         WHERE room_row.id = v_room)
      )
    )
  ) THEN
    RAISE EXCEPTION 'Missing permission to terminate contract'
      USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;

  IF NOT v_core_writer THEN
    PERFORM app_private.assert_contract_has_no_customer_credit_v1(
      p_contract_id, v_org
    );
    PERFORM app_private.begin_accounting_chain_write_v1();
    v_opened_writer := true;
  END IF;

  BEGIN
    v_result := public.terminate_contract_forfeit_impl(
      p_contract_id, p_forfeit_date, COALESCE(p_extra_charges, '[]'::jsonb)
    );
  EXCEPTION WHEN OTHERS THEN
    IF v_opened_writer THEN
      PERFORM app_private.end_accounting_chain_write_v1();
    END IF;
    RAISE;
  END;

  IF v_opened_writer THEN
    PERFORM app_private.end_accounting_chain_write_v1();
  END IF;
  RETURN v_result;
END;
$$;








--
-- Name: terminate_contract_forfeit_impl(uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_forfeit_impl(p_contract_id uuid, p_forfeit_date date, p_extra_charges jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract       RECORD;
  v_building_id    uuid;
  v_invoice_id     uuid;
  v_extra_inv      uuid;
  v_extra          numeric(15,2) := 0;
  v_deposit        numeric(15,2);
  v_billing        text;
  v_cnumber        text;
  v_marker         text;
  v_acc_int        uuid;
  v_type_off       uuid;
  v_type_inc       uuid;
  v_chi_id         uuid;
  v_thu_id         uuid;
  v_kept_paid      numeric(15,2);
  v_paid_cnt       integer;
  v_unpaid_cnt     integer;
  v_cancelled_cnt  integer;
BEGIN
  SELECT * INTO v_contract
    FROM contracts
   WHERE id = p_contract_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hợp đồng không tồn tại';
  END IF;
  IF v_contract.status IN ('TERMINATED','EXPIRED') THEN
    RAISE EXCEPTION 'Hợp đồng đã thanh lý/hết hạn';
  END IF;
  IF v_contract.room_id IS NULL THEN
    RAISE EXCEPTION 'Hợp đồng chưa gán phòng — không thể thanh lý';
  END IF;
  IF p_forfeit_date < v_contract.start_date THEN
    RAISE EXCEPTION 'Ngày bỏ cọc (%) không được trước ngày bắt đầu hợp đồng (%)',
      to_char(p_forfeit_date,'DD/MM/YYYY'), to_char(v_contract.start_date,'DD/MM/YYYY');
  END IF;
  SELECT building_id INTO v_building_id FROM rooms WHERE id = v_contract.room_id;
  IF v_building_id IS NULL THEN
    RAISE EXCEPTION 'Không xác định được toà nhà của hợp đồng';
  END IF;

  -- Cọc forfeit = cọc THỰC đã thu (nguồn sự thật: contracts.deposit_paid).
  -- [A9] Cọc đã thu > cọc theo hợp đồng ⇒ DỪNG, không đoán.
  -- Công thức LEAST() bên dưới lấy số NHỎ hơn, nên khi ô "Tiền cọc" trên hợp
  -- đồng khai 0 mà thực đã thu (vd HĐT-062953: 0 / 4.000.000) thì v_deposit = 0
  -- và TOÀN BỘ khối doanh thu bị bỏ qua trong im lặng: không hoá đơn, không
  -- phiếu, 0đ doanh thu trên tiền đang giữ trong két.
  --
  -- KHÔNG sửa thành COALESCE(deposit_paid,0): đo được 3/4 hợp đồng dôi ra là do
  -- phiếu "[Accounting repair] Contract deposit" ĐẾM TRÙNG với phiếu thu cọc
  -- tường minh (2.000.000 + 1.500.000 + 300.000 = 3.800.000đ). Lấy thẳng
  -- deposit_paid sẽ ghi KHỐNG đúng số đó vào KQKD rồi chảy sang chia lợi nhuận.
  IF COALESCE(v_contract.deposit_paid, 0) > COALESCE(v_contract.total_deposit, 0) THEN
    RAISE EXCEPTION 'Không thanh lý được: cọc ĐÃ THU (% đ) lớn hơn cọc THEO HỢP ĐỒNG (% đ), dôi % đ. Hệ thống không tự đoán số nào đúng. Hãy kiểm tra sổ cọc của hợp đồng: nếu có phiếu cọc bị ĐẾM TRÙNG thì huỷ/điều chỉnh phiếu đó; nếu ô "Tiền cọc" trên hợp đồng khai thiếu thì sửa lại cho khớp số THỰC NHẬN. Đừng nâng "Tiền cọc" chỉ để chạy được lệnh — làm vậy sẽ ghi khống phần dôi thành doanh thu.',
      round(COALESCE(v_contract.deposit_paid, 0))::bigint,
      round(COALESCE(v_contract.total_deposit, 0))::bigint,
      round(COALESCE(v_contract.deposit_paid,0) - COALESCE(v_contract.total_deposit,0))::bigint
      USING ERRCODE = '55000';
  END IF;
  v_deposit := LEAST(COALESCE(v_contract.total_deposit, 0), COALESCE(v_contract.deposit_paid, 0));
  v_billing := to_char(COALESCE(p_forfeit_date, public.org_today_v1(NULL)), 'YYYY-MM');
  v_cnumber := COALESCE(v_contract.contract_number, p_contract_id::text);
  v_marker  := '[CẤN CỌC BỎ CỌC ' || p_contract_id::text || ']';

  v_acc_int := public._internal_settlement_account(v_contract.user_id);

  SELECT COALESCE(SUM(paid_amount), 0)
    INTO v_kept_paid
    FROM invoices
   WHERE contract_id = p_contract_id
     AND deleted_at  IS NULL
     AND status      IN ('APPROVED','OVERDUE','PARTIAL_PAID')
     AND COALESCE(paid_amount, 0) > 0;

  UPDATE invoices
     SET status       = 'CANCELLED',
         total_amount = COALESCE(paid_amount, 0),
         notes        = CASE
                        WHEN notes IS NULL OR length(btrim(notes)) = 0
                          THEN '[Huỷ — thanh lý bỏ cọc ngày '
                               || to_char(p_forfeit_date,'DD/MM/YYYY')
                               || '; giữ lại ' || round(COALESCE(paid_amount,0))::bigint
                               || 'đ đã thu làm doanh thu, huỷ phần nợ '
                               || round(COALESCE(remaining_amount,0))::bigint || 'đ]'
                        ELSE notes
                             || E'\n[Huỷ — thanh lý bỏ cọc ngày '
                             || to_char(p_forfeit_date,'DD/MM/YYYY')
                             || '; giữ lại ' || round(COALESCE(paid_amount,0))::bigint
                             || 'đ đã thu làm doanh thu, huỷ phần nợ '
                             || round(COALESCE(remaining_amount,0))::bigint || 'đ]'
                      END,
         updated_at = NOW()
   WHERE contract_id = p_contract_id
     AND deleted_at  IS NULL
     AND status      IN ('APPROVED','OVERDUE','PARTIAL_PAID')
     AND COALESCE(paid_amount, 0) > 0;
  GET DIAGNOSTICS v_paid_cnt = ROW_COUNT;

  UPDATE invoices
     SET status       = 'CANCELLED',
         total_amount = 0,
         notes        = CASE
                        WHEN notes IS NULL OR length(btrim(notes)) = 0
                          THEN '[Huỷ tự động — thanh lý bỏ cọc ngày '
                               || to_char(p_forfeit_date,'DD/MM/YYYY') || ']'
                        ELSE notes
                             || E'\n[Huỷ tự động — thanh lý bỏ cọc ngày '
                             || to_char(p_forfeit_date,'DD/MM/YYYY') || ']'
                      END,
         updated_at   = NOW()
   WHERE contract_id = p_contract_id
     AND deleted_at  IS NULL
     AND status      IN ('APPROVED','OVERDUE','PARTIAL_PAID')
     AND COALESCE(paid_amount, 0) = 0;
  GET DIAGNOSTICS v_unpaid_cnt = ROW_COUNT;

  v_cancelled_cnt := COALESCE(v_paid_cnt, 0) + COALESCE(v_unpaid_cnt, 0);

  IF v_deposit > 0 THEN
    -- v4: hoá đơn bù cọc mang ĐÚNG kỳ tháng bỏ cọc (kind='SETTLEMENT' —
    -- partial unique không còn chặn; thôi mượn slot tháng trống).
    INSERT INTO invoices (
      user_id, contract_id, building_id, room_id,
      kind, billing_month, issue_date, due_date,
      status, subtotal, discount_amount, total_amount,
      notes
    ) VALUES (
      v_contract.user_id, p_contract_id,
      v_building_id, v_contract.room_id,
      'SETTLEMENT', v_billing, p_forfeit_date, p_forfeit_date,
      'APPROVED'::invoice_status, v_deposit, 0, v_deposit,
      'Hoá đơn thanh lý — khách bỏ cọc ngày ' || to_char(p_forfeit_date,'DD/MM/YYYY')
        || CASE WHEN v_cancelled_cnt > 0
                  THEN E'\n(Đã huỷ ' || v_cancelled_cnt || ' hoá đơn còn nợ'
                       || CASE WHEN v_kept_paid > 0
                                 THEN '; giữ lại ' || round(v_kept_paid)::bigint
                                      || 'đ đã thu làm doanh thu'
                                 ELSE '' END
                       || ')'
                  ELSE '' END
    )
    RETURNING id INTO v_invoice_id;

    INSERT INTO invoice_items (
      invoice_id, type, description,
      unit_price, quantity, coefficient, amount, sort_order
    ) VALUES (
      v_invoice_id, 'PENALTY',
      'Phí phạt khách bỏ cọc (giữ tiền cọc đã thu)',
      v_deposit, 1, 1, v_deposit, 1
    );

    -- Cặp bút toán nội bộ TỰ DUYỆT — CẢ 2 CHÂN trên sổ nội bộ (net 0).
    v_type_off := public._termination_ensure_type(v_contract.user_id, 'expense', 'Cấn cọc chuyển doanh thu');
    UPDATE income_expense_types SET is_deposit = TRUE  WHERE id = v_type_off AND is_deposit IS DISTINCT FROM TRUE;
    v_type_inc := public._termination_ensure_type(v_contract.user_id, 'income', 'Doanh thu bỏ cọc');
    UPDATE income_expense_types SET is_deposit = FALSE WHERE id = v_type_inc AND is_deposit IS DISTINCT FROM FALSE;

    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'EXPENSE', 'Cấn cọc bỏ cọc → chuyển doanh thu — HĐ ' || v_cnumber,
            v_building_id, v_contract.room_id, p_contract_id, v_acc_int, p_forfeit_date, v_deposit, 'UNAPPROVED',
            v_marker || ' Bút toán nội bộ: cọc khách bỏ chuyển thành doanh thu (tự duyệt; không phải tiền thật — không vào sổ quỹ).',
            'termination.forfeit_offset')
    RETURNING id INTO v_chi_id;
    INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
    VALUES (v_chi_id, v_type_off, 'Cấn cọc bỏ cọc chuyển doanh thu', 1, v_deposit, p_forfeit_date, p_forfeit_date);

    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, invoice_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'INCOME', 'Doanh thu bỏ cọc — HĐ ' || v_cnumber,
            v_building_id, v_contract.room_id, p_contract_id, v_acc_int, v_invoice_id, p_forfeit_date, v_deposit, 'UNAPPROVED',
            v_marker || ' Bút toán nội bộ: doanh thu bỏ cọc (tự duyệt → tất toán hoá đơn thanh lý; KQKD đếm theo hạng mục).',
            'termination.forfeit_revenue')
    RETURNING id INTO v_thu_id;
    INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
    VALUES (v_thu_id, v_type_inc, 'Doanh thu bỏ cọc (cọc khách bỏ)', 1, v_deposit, p_forfeit_date, p_forfeit_date);

    -- 7af: cặp bút toán nội bộ TỰ DUYỆT ngay trong writer (hướng A).
    -- Đóng dấu bản chất trước — Finance V2 hết coi đây là phiếu tiền thật.
    -- 7b1: review_state đi CÙNG cú duyệt, KHÔNG đi trước. Ở nhịp này cả 2
    -- chân còn UNAPPROVED, mà ie_unapproved_review_state_ck cấm cặp
    -- (UNAPPROVED, RESOLVED) — đặt ở đây là 23514, chặn cứng thanh lý.
    UPDATE public.income_expenses
       SET posting_mode   = 'NON_CASH',
           posting_status = 'NOT_APPLICABLE'
     WHERE id IN (v_chi_id, v_thu_id);

    -- Token cho CẢ HAI chân: chân doanh thu do lệnh dưới đổi, chân đối ứng do
    -- cascade trg_forfeit_settle_on_approve đổi — guard a05 đòi token từng phiếu.
    INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
    VALUES (v_thu_id, pg_current_xact_id(), 'APPROVED'),
           (v_chi_id, pg_current_xact_id(), 'APPROVED');

    -- Duyệt chân doanh thu → cascade duyệt chân đối ứng + tất toán hoá đơn.
    UPDATE public.income_expenses
       SET approval_status = 'APPROVED',
           approved_by     = COALESCE(auth.uid(), v_contract.user_id),
           approved_at     = now(),
           review_state    = 'RESOLVED',
           review_version  = income_expenses.review_version + 1
     WHERE id = v_thu_id;

    DELETE FROM app_private.ie_transition_authorization
     WHERE income_expense_id IN (v_thu_id, v_chi_id)
       AND xid = pg_current_xact_id();
  END IF;

  IF jsonb_typeof(COALESCE(p_extra_charges, '[]'::jsonb)) = 'array' THEN
    SELECT COALESCE(SUM((j->>'amount')::numeric), 0) INTO v_extra
      FROM jsonb_array_elements(p_extra_charges) AS t(j)
     WHERE (j->>'amount') IS NOT NULL AND (j->>'amount') <> ''
       AND (j->>'amount')::numeric > 0;
  END IF;

  IF v_extra > 0 THEN
    -- v4: hoá đơn thu thêm cũng mang ĐÚNG kỳ tháng bỏ cọc, kind='SETTLEMENT'.
    INSERT INTO invoices (user_id, contract_id, building_id, room_id, kind, billing_month, issue_date, due_date, status, subtotal, discount_amount, total_amount, notes)
    VALUES (v_contract.user_id, p_contract_id, v_building_id, v_contract.room_id, 'SETTLEMENT', v_billing, p_forfeit_date, p_forfeit_date,
            'APPROVED'::invoice_status, 0, 0, 0,
            'Hoá đơn thu thêm khi thanh lý — khách bỏ cọc ngày ' || to_char(p_forfeit_date,'DD/MM/YYYY')
              || ' (thu riêng — không liên quan hoá đơn bù cọc).')
    RETURNING id INTO v_extra_inv;
    PERFORM public._termination_apply_extra_charges(v_extra_inv, p_extra_charges, p_forfeit_date, v_contract.user_id, p_contract_id);
    PERFORM public.recompute_invoice_for_id(v_extra_inv);
  END IF;

  UPDATE contracts
     SET status          = 'TERMINATED',
         actual_end_date = p_forfeit_date,
         notes           = CASE
                             WHEN notes IS NULL OR length(btrim(notes)) = 0
                               THEN '[Thanh lý — khách bỏ cọc ' || to_char(p_forfeit_date,'DD/MM/YYYY') || ']'
                             ELSE notes || E'\n[Thanh lý — khách bỏ cọc ' || to_char(p_forfeit_date,'DD/MM/YYYY') || ']'
                           END,
         updated_at      = NOW()
   WHERE id = p_contract_id;

  BEGIN
    INSERT INTO contract_terminations (
      user_id, contract_id, termination_date, actual_move_out_date,
      termination_type,
      outstanding_debt, early_termination_fee, prorated_rent, prorated_days, prorated_services,
      total_deposit, status, approved_by, approved_at, notes
    ) VALUES (
      v_contract.user_id, p_contract_id, p_forfeit_date, p_forfeit_date,
      'FORFEIT',
      0, v_deposit, 0, 0, 0,
      v_deposit, 'COMPLETED', auth.uid(), NOW(),
      'Khách bỏ cọc — đã tạo phiếu thu "Doanh thu bỏ cọc" (chờ duyệt) cho phần cọc thực thu ' || round(v_deposit)::bigint || 'đ.'
        || CASE WHEN v_kept_paid > 0
                  THEN ' Đã giữ lại ' || round(v_kept_paid)::bigint
                       || 'đ đã thu làm doanh thu.'
                  ELSE '' END
        || CASE WHEN v_extra > 0
                  THEN ' Hoá đơn thu thêm riêng ' || round(v_extra)::bigint || 'đ (chờ thu).'
                  ELSE '' END
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'terminate_contract_forfeit_impl: audit insert failed for %: %', p_contract_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'contract_id',                p_contract_id,
    'invoice_id',                 v_invoice_id,
    'settlement_invoice_id',      v_invoice_id,
    'extra_invoice_id',           v_extra_inv,
    'extra_charges_total',        v_extra,
    'forfeit_amount',             v_deposit,
    'cancelled_invoices',         v_cancelled_cnt,
    'kept_paid_amount',           v_kept_paid,
    'pending_income_voucher_id',  v_thu_id,
    'pending_expense_voucher_id', v_chi_id,
    'acc_internal',               v_acc_int
  );
END;
$$;








--
-- Name: terminate_contract_forfeit_with_credit_v1(uuid, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_forfeit_with_credit_v1(p_contract_id uuid, p_forfeit_date date, p_extra_charges jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_org uuid;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_credit_balance numeric(15,2);
  v_termination jsonb;
  v_credit jsonb;
  v_response jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT contract_row.organization_id INTO v_org
  FROM public.contracts contract_row
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Contract not found' USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'contract_id', p_contract_id,
    'forfeit_date', p_forfeit_date,
    'extra_charges', COALESCE(p_extra_charges, '[]'::jsonb)
  )::text);
  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, 'contract.terminate.forfeit.credit.v1', p_contract_id::text,
    v_actor, v_key, v_hash
  ) ON CONFLICT (
    organization_id, operation, subject_scope, actor_id, idempotency_key
  ) DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'contract.terminate.forfeit.credit.v1'
    AND operation_row.subject_scope = p_contract_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key was reused with a different payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  v_credit_balance := app_private.contract_customer_credit_balance_v1(
    p_contract_id, v_org
  );
  PERFORM app_private.begin_accounting_chain_write_v1();
  v_termination := public.terminate_contract_forfeit(
    p_contract_id, p_forfeit_date, COALESCE(p_extra_charges, '[]'::jsonb)
  );
  PERFORM app_private.end_accounting_chain_write_v1();
  IF v_credit_balance > 0
     AND app_private.evaluate_feature_route('customer.credit.apply.v1', v_org) = 'CANONICAL' THEN
    v_credit := app_private.apply_customer_credit_fifo_v1(
      v_actor, p_contract_id, NULL, NULL, 'FORFEIT',
      'Forfeit remaining customer credit on contract termination', v_key
    );
  ELSIF v_credit_balance > 0 THEN
    -- Tính năng xử lý "tiền khách trả dư" chưa bật (route <> CANONICAL): KHÔNG
    -- chặn thanh lý. Gác khoản dư lại, đánh dấu deferred để xử lý riêng (hoàn/cấn
    -- trừ thủ công) sau. Trước đây nhánh này gọi apply_customer_credit_fifo_v1 vô
    -- điều kiện → ném 55000 "Customer credit writer is not enabled" làm gãy cả
    -- thao tác thanh lý bỏ cọc.
    v_credit := jsonb_build_object(
      'contract_id', p_contract_id,
      'invoice_id', NULL,
      'application_kind', 'FORFEIT',
      'applied_amount', 0,
      'remaining_amount', v_credit_balance,
      'applications', '[]'::jsonb,
      'deferred', true,
      'deferred_reason', 'customer_credit_writer_not_enabled'
    );
  ELSE
    v_credit := jsonb_build_object(
      'contract_id', p_contract_id,
      'invoice_id', NULL,
      'application_kind', 'FORFEIT',
      'applied_amount', 0,
      'remaining_amount', 0,
      'applications', '[]'::jsonb
    );
  END IF;
  v_response := jsonb_build_object(
    'termination', v_termination,
    'credit', v_credit
  );

  UPDATE app_private.canonical_write_operations
     SET subject_id = p_contract_id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'contract.terminate.forfeit.credit.v1'
     AND subject_scope = p_contract_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;
  RETURN v_response;
END;
$_$;








--
-- Name: terminate_contract_move_out(uuid, date, numeric, numeric, numeric, numeric, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_move_out(p_contract_id uuid, p_move_out_date date, p_deposit_refund numeric DEFAULT 0, p_penalty_fee numeric DEFAULT 0, p_excess_rent numeric DEFAULT 0, p_outstanding_debt numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_extra_charges jsonb DEFAULT '[]'::jsonb, p_shortfall_mode text DEFAULT 'PAID'::text, p_receipt_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_room uuid;
  v_org uuid;
  v_owner uuid;
  v_building uuid;
  v_deposit_paid numeric;
  v_extra numeric := 0;
  v_cash_shortfall numeric := 0;
  v_receipt_account uuid;
  v_cash_authz boolean;
  v_core_writer boolean;
  v_opened_writer boolean := false;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT
    contract_row.room_id,
    contract_row.organization_id,
    contract_row.user_id,
    room_row.building_id,
    contract_row.deposit_paid
    INTO v_room, v_org, v_owner, v_building, v_deposit_paid
  FROM public.contracts contract_row
  LEFT JOIN public.rooms room_row ON room_row.id = contract_row.room_id
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE OF contract_row;

  IF NOT (
    public.is_super_admin()
    OR (
      v_room IS NOT NULL
      AND public.can_do_on_building(
        'contracts', 'edit',
        (SELECT room_row.building_id
         FROM public.rooms room_row
         WHERE room_row.id = v_room)
      )
    )
  ) THEN
    RAISE EXCEPTION 'Missing permission to terminate contract'
      USING ERRCODE = '42501';
  END IF;

  IF p_receipt_account_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.accounts account_row
    WHERE account_row.id = p_receipt_account_id
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
  ) THEN
    RAISE EXCEPTION 'Receipt account is outside the contract organization or is not a real active cashbook'
      USING ERRCODE = '42501';
  END IF;

  IF jsonb_typeof(COALESCE(p_extra_charges, '[]'::jsonb)) = 'array' THEN
    SELECT COALESCE(sum((entry->>'amount')::numeric), 0)
      INTO v_extra
    FROM jsonb_array_elements(COALESCE(p_extra_charges, '[]'::jsonb)) item(entry)
    WHERE NULLIF(entry->>'amount', '') IS NOT NULL
      AND (entry->>'amount')::numeric > 0;
  END IF;

  v_cash_shortfall := GREATEST(
    COALESCE(p_outstanding_debt, 0)
      + COALESCE(p_penalty_fee, 0)
      + v_extra
      - LEAST(
          GREATEST(COALESCE(p_deposit_refund, 0), 0),
          COALESCE(v_deposit_paid, 0)
        )
      - GREATEST(COALESCE(p_excess_rent, 0), 0),
    0
  );

  IF upper(COALESCE(p_shortfall_mode, 'PAID')) = 'PAID'
     AND v_cash_shortfall > 0 THEN
    v_receipt_account := COALESCE(
      p_receipt_account_id,
      public._collector_thu_account(auth.uid()),
      public._termination_pick_account(v_owner, v_building)
    );

    IF v_receipt_account IS NULL THEN
      RAISE EXCEPTION 'Cannot resolve an active real receipt account in the contract organization'
        USING ERRCODE = '42501';
    END IF;
    PERFORM 1
    FROM public.accounts account_row
    WHERE account_row.id = v_receipt_account
      AND account_row.organization_id = v_org
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Cannot resolve an active real receipt account in the contract organization'
        USING ERRCODE = '42501';
    END IF;

    PERFORM app_private.lock_org_for_decision_v1(v_org);
    SELECT decision.allowed
      INTO v_cash_authz
    FROM app_private.authorize_tenant_action_v3(
      auth.uid(), v_org, 'thu_tien.collect', v_building, v_receipt_account
    ) decision;
    IF NOT COALESCE(v_cash_authz, false) THEN
      RAISE EXCEPTION 'Missing receipt permission or cashbook possession for termination collection'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    v_receipt_account := p_receipt_account_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM app_private.accounting_chain_writer_xids capability
    WHERE capability.transaction_id = txid_current()
      AND capability.backend_pid = pg_backend_pid()
  ) INTO v_core_writer;

  IF NOT v_core_writer THEN
    PERFORM app_private.assert_contract_has_no_customer_credit_v1(
      p_contract_id, v_org
    );
    PERFORM app_private.begin_accounting_chain_write_v1();
    v_opened_writer := true;
  END IF;

  INSERT INTO app_private.termination_move_out_writer_context (
    transaction_id, backend_pid, organization_id, user_id,
    contract_id, building_id, room_id, move_out_date, opened_at
  ) VALUES (
    txid_current(), pg_backend_pid(), v_org, v_owner,
    p_contract_id, v_building, v_room, p_move_out_date, clock_timestamp()
  ) ON CONFLICT (transaction_id, backend_pid) DO UPDATE
  SET organization_id = EXCLUDED.organization_id,
      user_id = EXCLUDED.user_id,
      contract_id = EXCLUDED.contract_id,
      building_id = EXCLUDED.building_id,
      room_id = EXCLUDED.room_id,
      move_out_date = EXCLUDED.move_out_date,
      opened_at = EXCLUDED.opened_at;

  BEGIN
    v_result := public.terminate_contract_move_out_impl(
      p_contract_id, p_move_out_date, COALESCE(p_deposit_refund, 0),
      COALESCE(p_penalty_fee, 0), COALESCE(p_excess_rent, 0),
      COALESCE(p_outstanding_debt, 0), p_notes,
      COALESCE(p_extra_charges, '[]'::jsonb),
      COALESCE(p_shortfall_mode, 'PAID'), v_receipt_account
    );
  EXCEPTION WHEN OTHERS THEN
    DELETE FROM app_private.termination_move_out_writer_context
    WHERE transaction_id = txid_current()
      AND backend_pid = pg_backend_pid();
    IF v_opened_writer THEN
      PERFORM app_private.end_accounting_chain_write_v1();
    END IF;
    RAISE;
  END;

  DELETE FROM app_private.termination_move_out_writer_context
  WHERE transaction_id = txid_current()
    AND backend_pid = pg_backend_pid();

  IF v_opened_writer THEN
    PERFORM app_private.end_accounting_chain_write_v1();
  END IF;
  RETURN v_result;
END;
$$;








--
-- Name: terminate_contract_move_out_impl(uuid, date, numeric, numeric, numeric, numeric, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_move_out_impl(p_contract_id uuid, p_move_out_date date, p_deposit_refund numeric DEFAULT 0, p_penalty_fee numeric DEFAULT 0, p_excess_rent numeric DEFAULT 0, p_outstanding_debt numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_extra_charges jsonb DEFAULT '[]'::jsonb, p_shortfall_mode text DEFAULT 'PAID'::text, p_receipt_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract  RECORD;
  v_building  uuid;
  v_acc_op    uuid;   -- sổ vận hành (fallback nhận tiền thật)
  v_acc_int   uuid;   -- sổ bút toán nội bộ (cả 2 chân cấn cọc)
  v_acc_rcpt  uuid;   -- sổ NHẬN "khách trả thêm" (tiền thật)
  v_billing   text;
  v_cnumber   text;
  v_deposit   numeric(15,2);
  v_penalty   numeric(15,2) := COALESCE(p_penalty_fee,    0);
  v_excess    numeric(15,2) := COALESCE(p_excess_rent,    0);
  v_debt      numeric(15,2) := COALESCE(p_outstanding_debt, 0);
  v_extra     numeric(15,2) := 0;
  v_charges   numeric(15,2);
  v_pool      numeric(15,2);
  v_applied   numeric(15,2);
  v_applied_dep numeric(15,2);
  v_refund_dep  numeric(15,2);
  v_refund_exc  numeric(15,2);
  v_S         numeric(15,2);
  v_budget    numeric(15,2);
  v_pay       numeric(15,2);
  v_settle_inv uuid;
  v_next_sort integer;
  v_type_inc  uuid;
  v_type_off  uuid;
  v_type_dep  uuid;
  v_type_excr uuid;
  v_voucher   uuid;
  v_refund_voucher uuid;
  v_breakdown text;
  rec         RECORD;
BEGIN
  IF p_shortfall_mode NOT IN ('PAID', 'DEBT') THEN
    RAISE EXCEPTION 'p_shortfall_mode phải là PAID hoặc DEBT';
  END IF;

  SELECT * INTO v_contract FROM contracts WHERE id = p_contract_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Hợp đồng không tồn tại'; END IF;
  IF v_contract.status IN ('TERMINATED','EXPIRED') THEN RAISE EXCEPTION 'Hợp đồng đã thanh lý/hết hạn'; END IF;
  IF v_contract.room_id IS NULL THEN RAISE EXCEPTION 'Hợp đồng chưa gán phòng — không thể thanh lý'; END IF;
  IF p_move_out_date < v_contract.start_date THEN
    RAISE EXCEPTION 'Ngày chuyển đi (%) không được trước ngày bắt đầu hợp đồng (%)',
      to_char(p_move_out_date,'DD/MM/YYYY'), to_char(v_contract.start_date,'DD/MM/YYYY');
  END IF;
  SELECT building_id INTO v_building FROM rooms WHERE id = v_contract.room_id;
  IF v_building IS NULL THEN RAISE EXCEPTION 'Không xác định được toà nhà của hợp đồng'; END IF;

  v_billing := to_char(COALESCE(p_move_out_date, public.org_today_v1(NULL)), 'YYYY-MM');
  v_cnumber := COALESCE(v_contract.contract_number, p_contract_id::text);
  v_acc_op  := public._termination_pick_account(v_contract.user_id, v_building);
  v_acc_int := public._internal_settlement_account(v_contract.user_id);

  -- Sổ NHẬN "khách trả thêm" (tiền thật): form chọn > sổ %Thu của người bấm > sổ vận hành toà.
  v_acc_rcpt := COALESCE(p_receipt_account_id, public._collector_thu_account(auth.uid()), v_acc_op);
  IF p_receipt_account_id IS NOT NULL THEN
    PERFORM 1 FROM accounts a WHERE a.id = p_receipt_account_id AND a.deleted_at IS NULL AND a.is_virtual = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sổ nhận tiền không hợp lệ (không tồn tại hoặc là sổ ảo)';
    END IF;
  END IF;

  -- A1: hoàn/cấn cọc tối đa bằng cọc THỰC THU (deposit_paid).
  v_deposit := LEAST(GREATEST(COALESCE(p_deposit_refund, 0), 0), COALESCE(v_contract.deposit_paid, 0));

  IF jsonb_typeof(COALESCE(p_extra_charges, '[]'::jsonb)) = 'array' THEN
    SELECT COALESCE(SUM((j->>'amount')::numeric), 0) INTO v_extra
      FROM jsonb_array_elements(p_extra_charges) AS t(j)
     WHERE (j->>'amount') IS NOT NULL AND (j->>'amount') <> ''
       AND (j->>'amount')::numeric > 0;
  END IF;

  v_charges     := v_debt + v_penalty + v_extra;
  v_pool        := v_deposit + v_excess;
  v_applied     := LEAST(v_pool, v_charges);
  v_applied_dep := LEAST(v_deposit, v_charges);
  v_refund_dep  := v_deposit - v_applied_dep;
  v_refund_exc  := v_excess - LEAST(v_excess, GREATEST(v_charges - v_deposit, 0));
  v_S           := v_pool - v_charges;

  v_breakdown :=
       'QUYẾT TOÁN THANH LÝ ' || to_char(p_move_out_date,'DD/MM/YYYY') || ' — HĐ ' || v_cnumber
    || E'\n• Cọc đã thu: ' || to_char(v_deposit, 'FM999G999G999G990') || 'đ'
    || E'\n• Khấu trừ: công nợ ' || to_char(v_debt, 'FM999G999G999G990') || 'đ'
    || CASE WHEN v_penalty > 0 THEN ' + phí phạt ' || to_char(v_penalty, 'FM999G999G999G990') || 'đ' ELSE '' END
    || CASE WHEN v_extra   > 0 THEN ' + thu thêm ' || to_char(v_extra, 'FM999G999G999G990') || 'đ' ELSE '' END
    || ' = ' || to_char(v_charges, 'FM999G999G999G990') || 'đ'
    || E'\n• Cọc cấn vào khấu trừ: ' || to_char(v_applied_dep, 'FM999G999G999G990') || 'đ (bút toán nội bộ, không đụng sổ tiền thật)'
    || CASE WHEN v_excess > 0 THEN E'\n• Tiền thừa (credit) áp dụng: ' || to_char(v_excess, 'FM999G999G999G990') || 'đ (cấn ' || to_char(v_excess - v_refund_exc, 'FM999G999G999G990') || 'đ, hoàn ' || to_char(v_refund_exc, 'FM999G999G999G990') || 'đ)' ELSE '' END
    || E'\n• Hoàn cọc lại khách: ' || to_char(v_refund_dep, 'FM999G999G999G990') || 'đ'
    || CASE WHEN v_S < 0 THEN E'\n• Khách còn phải trả: ' || to_char(-v_S, 'FM999G999G999G990') || 'đ ('
         || CASE WHEN p_shortfall_mode = 'PAID' THEN 'đã thu ngay khi thanh lý' ELSE 'GHI NỢ — chờ thu' END || ')'
       ELSE '' END
    || CASE WHEN v_refund_dep + v_refund_exc > 0 THEN E'\n• Tổng chi hoàn khách: ' || to_char(v_refund_dep + v_refund_exc, 'FM999G999G999G990') || 'đ (phiếu chi chờ duyệt — chọn sổ quỹ khi duyệt)' ELSE '' END;

  -- 1. HOÁ ĐƠN THANH LÝ RIÊNG (kind='SETTLEMENT', ĐÚNG kỳ tháng trả phòng).
  --    v4: KHÔNG đụng hoá đơn tháng nữa — dù nó chưa/đã PAID. Công nợ của nó
  --    vẫn được gạch ở bước 2 bằng payments 'CT' (không sửa nội dung hoá đơn).
  IF v_penalty > 0 OR v_extra > 0 THEN
    INSERT INTO invoices (user_id, contract_id, building_id, room_id, kind, billing_month, issue_date, due_date, status, subtotal, total_amount, notes)
    VALUES (v_contract.user_id, p_contract_id, v_building, v_contract.room_id, 'SETTLEMENT',
      v_billing, p_move_out_date, p_move_out_date, 'APPROVED'::invoice_status, 0, 0,
      'Hoá đơn thanh lý — khách rời phòng ngày ' || to_char(p_move_out_date,'DD/MM/YYYY') || COALESCE(E'\n' || p_notes, ''))
    RETURNING id INTO v_settle_inv;
  END IF;

  IF v_penalty > 0 THEN
    SELECT COALESCE(MAX(sort_order),0)+1 INTO v_next_sort FROM invoice_items WHERE invoice_id = v_settle_inv;
    INSERT INTO invoice_items (invoice_id, type, description, unit_price, quantity, coefficient, amount, sort_order)
    VALUES (v_settle_inv, 'PENALTY', 'Phí phạt thanh lý', v_penalty, 1, 1, v_penalty, v_next_sort);
    UPDATE invoices SET subtotal = COALESCE(subtotal,0)+v_penalty, total_amount = COALESCE(total_amount,0)+v_penalty, updated_at = NOW() WHERE id = v_settle_inv;
  END IF;

  IF v_extra > 0 THEN
    PERFORM public._termination_apply_extra_charges(v_settle_inv, p_extra_charges, p_move_out_date, v_contract.user_id, p_contract_id);
  END IF;

  IF v_settle_inv IS NOT NULL THEN
    UPDATE invoices
       SET notes = COALESCE(notes || E'\n\n', '') || v_breakdown,
           updated_at = NOW()
     WHERE id = v_settle_inv;
  END IF;

  -- 2. Quyết toán hoá đơn còn nợ bằng CẤN TRỪ 'CT' (PAID: gạch hết; DEBT: trong pool).
  v_budget := CASE WHEN p_shortfall_mode = 'DEBT' THEN v_applied ELSE NULL END;
  FOR rec IN
    SELECT id, (total_amount - paid_amount) AS remaining FROM invoices
     WHERE contract_id = p_contract_id AND deleted_at IS NULL AND status <> 'CANCELLED'
       AND (total_amount - paid_amount) > 0
     ORDER BY billing_month, created_at
  LOOP
    v_pay := rec.remaining;
    IF v_budget IS NOT NULL THEN
      EXIT WHEN v_budget <= 0;
      v_pay := LEAST(v_pay, v_budget);
      v_budget := v_budget - v_pay;
    END IF;
    IF v_pay > 0 THEN
      INSERT INTO payments (user_id, invoice_id, amount, payment_method, payment_date, notes)
      VALUES (v_contract.user_id, rec.id, v_pay, 'CT'::payment_method, p_move_out_date,
              'Quyết toán khi thanh lý ' || to_char(p_move_out_date,'DD/MM/YYYY'));
    END IF;
  END LOOP;

  -- 3. CẶP BÚT TOÁN NỘI BỘ (cấn cọc → doanh thu) — CẢ 2 CHÂN trên sổ nội bộ,
  --    net 0/thương vụ; KHÔNG đụng sổ tiền thật (mô hình chốt 04/07).
  IF v_applied_dep > 0 THEN
    v_type_off := public._termination_ensure_type(v_contract.user_id, 'expense', 'Cấn cọc chuyển doanh thu');
    UPDATE income_expense_types SET is_deposit = TRUE  WHERE id = v_type_off AND is_deposit IS DISTINCT FROM TRUE;
    v_type_inc := public._termination_ensure_type(v_contract.user_id, 'income', 'Doanh thu thanh lý');
    UPDATE income_expense_types SET is_deposit = FALSE WHERE id = v_type_inc AND is_deposit IS DISTINCT FROM FALSE;

    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'EXPENSE', 'Cấn cọc → chuyển doanh thu — HĐ ' || v_cnumber, v_building, v_contract.room_id, p_contract_id, v_acc_int, p_move_out_date, v_applied_dep, 'APPROVED',
      '[CHUYỂN KHOẢN] Bút toán nội bộ: cọc cấn công nợ/phạt (không phải tiền thật).' || E'\n\n' || v_breakdown,
      'termination.offset')
    RETURNING id INTO v_voucher;
    INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
    VALUES (v_voucher, v_type_off, 'Cấn cọc chuyển doanh thu', 1, v_applied_dep, p_move_out_date, p_move_out_date);

    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, invoice_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'INCOME', 'Doanh thu thanh lý — HĐ ' || v_cnumber, v_building, v_contract.room_id, p_contract_id, v_acc_int, v_settle_inv, p_move_out_date, v_applied_dep, 'APPROVED',
      '[CHUYỂN KHOẢN] Bút toán nội bộ: ghi nhận doanh thu thanh lý từ cọc cấn nợ/phạt (KQKD đếm theo hạng mục).',
      'termination.revenue')
    RETURNING id INTO v_voucher;
    INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
    VALUES (v_voucher, v_type_inc, 'Doanh thu thanh lý (cấn cọc)', 1, v_applied_dep, p_move_out_date, p_move_out_date);
  END IF;

  -- 4. HOÀN KHÁCH = TIỀN THẬT: 1 phiếu chi NHÁP, SỔ TRỐNG (chọn khi duyệt).
  IF v_refund_dep > 0 OR v_refund_exc > 0 THEN
    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'EXPENSE', 'Trả khách thanh lý — HĐ ' || v_cnumber, v_building, v_contract.room_id, p_contract_id, NULL, p_move_out_date, v_refund_dep + v_refund_exc, 'UNAPPROVED',
      '[HOÀN KHÁCH THANH LÝ] Phiếu chi hoàn khách (tiền thật). CHỌN SỔ QUỸ chi tiền (Sửa phiếu) rồi mới duyệt được.' || E'\n\n' || v_breakdown || COALESCE(E'\n' || p_notes, ''),
      'termination.refund')
    RETURNING id INTO v_refund_voucher;

    IF v_refund_dep > 0 THEN
      v_type_dep := public._termination_ensure_type(v_contract.user_id, 'expense', 'Hoàn cọc thanh lý');
      UPDATE income_expense_types SET is_deposit = TRUE WHERE id = v_type_dep AND is_deposit IS DISTINCT FROM TRUE;
      INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
      VALUES (v_refund_voucher, v_type_dep, 'Trả lại khách (cọc sau khấu trừ)', 1, v_refund_dep, p_move_out_date, p_move_out_date);
    END IF;

    IF v_refund_exc > 0 THEN
      v_type_excr := public._termination_ensure_type(v_contract.user_id, 'expense', 'Hoàn tiền thừa thanh lý');
      UPDATE income_expense_types SET is_deposit = FALSE WHERE id = v_type_excr AND is_deposit IS DISTINCT FROM FALSE;
      INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
      VALUES (v_refund_voucher, v_type_excr, 'Hoàn tiền thừa khi thanh lý', 1, v_refund_exc, p_move_out_date, p_move_out_date);
    END IF;
  END IF;

  -- 4c. Khách trả thêm (TIỀN THẬT) — chế độ PAID: vào SỔ NHẬN đã chọn.
  IF v_S < 0 AND p_shortfall_mode = 'PAID' THEN
    v_type_inc := public._termination_ensure_type(v_contract.user_id, 'income', 'Thu thanh lý (khách trả thêm)');
    UPDATE income_expense_types SET is_deposit = FALSE WHERE id = v_type_inc AND is_deposit IS DISTINCT FROM FALSE;
    INSERT INTO income_expenses (user_id, type, name, building_id, room_id, contract_id, account_id, invoice_id, voucher_date, total_amount, approval_status, notes, system_source)
    VALUES (v_contract.user_id, 'INCOME', 'Khách trả thêm khi thanh lý — HĐ ' || v_cnumber, v_building, v_contract.room_id, p_contract_id, v_acc_rcpt, v_settle_inv, p_move_out_date, -v_S, 'APPROVED',
      'Khách trả thêm phần công nợ vượt tiền cọc khi thanh lý (tiền thật vào sổ nhận).' || COALESCE(E'\n' || p_notes, ''),
      'termination.extra_receipt')
    RETURNING id INTO v_voucher;
    INSERT INTO income_expense_items (income_expense_id, income_expense_type_id, description, quantity, unit_price, start_date, end_date)
    VALUES (v_voucher, v_type_inc, 'Khách trả thêm khi thanh lý', 1, -v_S, p_move_out_date, p_move_out_date);
  END IF;

  -- 5. Recompute hoá đơn quyết toán.
  IF v_settle_inv IS NOT NULL THEN PERFORM public.recompute_invoice_for_id(v_settle_inv); END IF;

  -- 6. Thanh lý hợp đồng (ghi chú kèm bản quyết toán đầy đủ).
  UPDATE contracts
     SET status = 'TERMINATED', actual_end_date = p_move_out_date,
         notes = CASE WHEN notes IS NULL OR length(btrim(notes)) = 0
                        THEN '[Thanh lý ' || to_char(p_move_out_date,'DD/MM/YYYY') || ']' || COALESCE(E'\n' || p_notes, '') || E'\n' || v_breakdown
                        ELSE notes || E'\n[Thanh lý ' || to_char(p_move_out_date,'DD/MM/YYYY') || ']' || COALESCE(E'\n' || p_notes, '') || E'\n' || v_breakdown END,
         updated_at = NOW()
   WHERE id = p_contract_id;

  -- 7. Audit.
  BEGIN
    INSERT INTO contract_terminations (
      user_id, contract_id, termination_date, actual_move_out_date, termination_type,
      outstanding_debt, early_termination_fee, prorated_rent, prorated_days, prorated_services,
      total_deposit, refund_method, status, approved_by, approved_at, notes)
    VALUES (
      v_contract.user_id, p_contract_id, p_move_out_date, p_move_out_date, 'NORMAL',
      v_debt, v_penalty + v_extra, 0, 0, 0,
      v_deposit,
      CASE WHEN v_refund_dep > 0 OR v_refund_exc > 0 THEN 'TM'::payment_method ELSE NULL END,
      'COMPLETED', auth.uid(), NOW(),
      COALESCE(p_notes || E'\n', '') || v_breakdown);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'terminate_contract_move_out_impl: audit insert failed for %: %', p_contract_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'contract_id', p_contract_id, 'settlement_invoice_id', v_settle_inv,
    'charges', v_charges, 'extra_charges_total', v_extra,
    'applied', v_applied, 'applied_deposit', v_applied_dep,
    'refund_deposit', v_refund_dep, 'refund_excess', v_refund_exc,
    'refund_voucher_id', v_refund_voucher,
    'net_settlement', v_S, 'shortfall_mode', p_shortfall_mode,
    'receipt_account_id', CASE WHEN v_S < 0 AND p_shortfall_mode = 'PAID' THEN v_acc_rcpt END,
    'acc_op', v_acc_op, 'acc_internal', v_acc_int
  );
END $$;








--
-- Name: terminate_contract_move_out_with_credit_v1(uuid, date, numeric, numeric, numeric, numeric, text, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_contract_move_out_with_credit_v1(p_contract_id uuid, p_move_out_date date, p_deposit_refund numeric, p_penalty_fee numeric, p_excess_rent numeric, p_outstanding_debt numeric, p_notes text, p_extra_charges jsonb, p_shortfall_mode text, p_receipt_account_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_credit_amount numeric(15,2) := round(COALESCE(p_excess_rent, 0), 2);
  v_org uuid;
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_termination jsonb;
  v_credit jsonb;
  v_response jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF p_excess_rent = 'NaN'::numeric
     OR COALESCE(p_excess_rent, 0) < 0
     OR COALESCE(p_excess_rent, 0) IS DISTINCT FROM round(
       COALESCE(p_excess_rent, 0), 2
     ) THEN
    RAISE EXCEPTION 'Move-out credit amount must be non-negative with at most two decimals'
      USING ERRCODE = '22023';
  END IF;

  SELECT contract_row.organization_id INTO v_org
  FROM public.contracts contract_row
  WHERE contract_row.id = p_contract_id
    AND contract_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Contract not found' USING ERRCODE = '42501';
  END IF;

  v_hash := md5(jsonb_build_object(
    'contract_id', p_contract_id,
    'move_out_date', p_move_out_date,
    'deposit_refund', p_deposit_refund,
    'penalty_fee', p_penalty_fee,
    'excess_rent', p_excess_rent,
    'outstanding_debt', p_outstanding_debt,
    'notes', p_notes,
    'extra_charges', COALESCE(p_extra_charges, '[]'::jsonb),
    'shortfall_mode', p_shortfall_mode,
    'receipt_account_id', p_receipt_account_id
  )::text);
  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, 'contract.terminate.move_out.credit.v1', p_contract_id::text,
    v_actor, v_key, v_hash
  ) ON CONFLICT (
    organization_id, operation, subject_scope, actor_id, idempotency_key
  ) DO NOTHING;

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = 'contract.terminate.move_out.credit.v1'
    AND operation_row.subject_scope = p_contract_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'idempotency_key was reused with a different payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  -- [A2] Tính năng áp credit chưa bật ⇒ CHẶN SỚM, trước khi ghi bất cứ thứ gì.
  -- Không sao chép nhánh deferred của forfeit sang đây: terminate_contract_move_out
  -- đã TIÊU credit trên trục tiền (cấn nợ CT + phiếu hoàn) NGAY trong lệnh dưới,
  -- nên hoãn burn-down = chi HAI LẦN. Chặn trước là cách duy nhất đúng.
  IF v_credit_amount > 0
     AND app_private.evaluate_feature_route('customer.credit.apply.v1', v_org)
         IS DISTINCT FROM 'CANONICAL' THEN
    RAISE EXCEPTION 'Tính năng áp tiền trả dư (credit) vào quyết toán chưa được kích hoạt, nên không thể thanh lý kèm % đ tiền thừa. Hãy để ô "Tiền phòng thừa" bằng 0 rồi thanh lý; khoản dư giữ nguyên trên sổ và xử lý riêng.',
      round(v_credit_amount)::bigint
      USING ERRCODE = '55000';
  END IF;
  PERFORM app_private.begin_accounting_chain_write_v1();
  v_termination := public.terminate_contract_move_out(
    p_contract_id, p_move_out_date, COALESCE(p_deposit_refund, 0),
    COALESCE(p_penalty_fee, 0), COALESCE(p_excess_rent, 0),
    COALESCE(p_outstanding_debt, 0), p_notes,
    COALESCE(p_extra_charges, '[]'::jsonb),
    COALESCE(p_shortfall_mode, 'PAID'), p_receipt_account_id
  );
  PERFORM app_private.end_accounting_chain_write_v1();

  IF v_credit_amount > 0 THEN
    v_credit := app_private.apply_customer_credit_fifo_v1(
      v_actor, p_contract_id, v_credit_amount, NULL, 'MOVE_OUT',
      'Apply customer credit during move-out settlement', v_key
    );
  ELSE
    v_credit := jsonb_build_object(
      'contract_id', p_contract_id,
      'application_kind', 'MOVE_OUT',
      'applied_amount', 0,
      'applications', '[]'::jsonb
    );
  END IF;

  v_response := jsonb_build_object(
    'termination', v_termination,
    'credit', v_credit
  );
  UPDATE app_private.canonical_write_operations
     SET subject_id = p_contract_id,
         completed_at = clock_timestamp(),
         response_payload = v_response
   WHERE organization_id = v_org
     AND operation = 'contract.terminate.move_out.credit.v1'
     AND subject_scope = p_contract_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;
  RETURN v_response;
END;
$_$;








--
-- Name: transfer_contract(uuid, uuid, numeric, numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_contract(p_contract_id uuid, p_new_customer_id uuid, p_new_rent_price numeric DEFAULT NULL::numeric, p_new_deposit numeric DEFAULT NULL::numeric, p_transfer_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_room uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  SELECT room_id INTO v_room FROM public.contracts
   WHERE id = p_contract_id AND deleted_at IS NULL;
  IF NOT (
    public.is_super_admin()
    OR (v_room IS NOT NULL AND public.can_do_on_building('contracts','edit',
          (SELECT building_id FROM public.rooms WHERE id = v_room)))
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên hợp đồng này' USING ERRCODE = '42501';
  END IF;
  RETURN public.transfer_contract_impl(p_contract_id, p_new_customer_id, p_new_rent_price, p_new_deposit, p_transfer_date, p_notes);
END $$;








--
-- Name: transfer_contract_impl(uuid, uuid, numeric, numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_contract_impl(p_contract_id uuid, p_new_customer_id uuid, p_new_rent_price numeric DEFAULT NULL::numeric, p_new_deposit numeric DEFAULT NULL::numeric, p_transfer_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract     RECORD;
  v_existing     uuid;
  v_old_customer uuid;
BEGIN
  SELECT * INTO v_contract
    FROM contracts
   WHERE id = p_contract_id
     AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hợp đồng không tồn tại';
  END IF;

  IF v_contract.status NOT IN ('ACTIVE','EXTENDED') THEN
    RAISE EXCEPTION 'Chỉ nhượng được khi hợp đồng đang hiệu lực';
  END IF;

  IF p_new_customer_id IS NULL THEN
    RAISE EXCEPTION 'Thiếu khách hàng mới';
  END IF;

  -- Báo lỗi tiếng Việt thay vì để FK 23503 thô nổ ở cuối hàm.
  IF NOT EXISTS (SELECT 1 FROM customers WHERE id = p_new_customer_id) THEN
    RAISE EXCEPTION 'Khách hàng mới không tồn tại';
  END IF;

  -- (a) CHỐT bên nhượng TRƯỚC khi hạ đại diện. Đọc sau lệnh UPDATE bên dưới
  --     sẽ luôn ra NULL (không còn ai is_representative) hoặc mới->mới.
  SELECT cc.customer_id INTO v_old_customer
    FROM contract_customers cc
   WHERE cc.contract_id = p_contract_id
     AND cc.is_representative
   LIMIT 1;

  -- Demote everyone, promote/insert the new representative.
  UPDATE contract_customers
     SET is_representative = false,
         updated_at = NOW()
   WHERE contract_id = p_contract_id;

  SELECT id INTO v_existing
    FROM contract_customers
   WHERE contract_id = p_contract_id
     AND customer_id = p_new_customer_id
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE contract_customers
       SET is_representative = true,
           updated_at = NOW()
     WHERE id = v_existing;
  ELSE
    INSERT INTO contract_customers (contract_id, customer_id, is_representative, notes)
    VALUES (p_contract_id, p_new_customer_id, true,
            CASE WHEN p_notes IS NULL OR length(btrim(p_notes))=0 THEN NULL
                 ELSE '[Nhượng HĐ] ' || p_notes
            END);
  END IF;

  -- Giá / cọc / ghi chú trên HĐ (KHÔNG đụng deposit_paid; KHÔNG nêu tên
  -- deposit_remaining vì là cột GENERATED -> 428C9).
  UPDATE contracts
     SET rent_price    = COALESCE(p_new_rent_price, rent_price),
         total_deposit = COALESCE(p_new_deposit,    total_deposit),
         notes         = CASE
                           WHEN p_notes IS NULL OR length(btrim(p_notes))=0 THEN notes
                           WHEN notes  IS NULL OR length(btrim(notes)) = 0 THEN p_notes
                           ELSE notes || E'\n[Nhượng HĐ ' || to_char(p_transfer_date,'DD/MM/YYYY') || '] ' || p_notes
                         END,
         updated_at    = NOW()
   WHERE id = p_contract_id;

  -- (b)(c)(d) Audit row — KHÔNG còn EXCEPTION WHEN OTHERS THEN NULL.
  INSERT INTO contract_transfers (
    user_id, contract_id, transfer_type, transfer_date,
    old_tenant_id, new_tenant_id,
    new_rent_price, new_deposit,
    reason, status, approved_at
  ) VALUES (
    COALESCE(auth.uid(), v_contract.user_id),
    p_contract_id, 'TENANT_CHANGE', p_transfer_date,
    v_old_customer, p_new_customer_id,
    p_new_rent_price, p_new_deposit,
    p_notes, 'COMPLETED', NOW()
  );

  RETURN p_contract_id;
END;
$$;








--
-- Name: transfer_room(uuid, uuid, numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_room(p_contract_id uuid, p_new_room_id uuid, p_new_rent_price numeric DEFAULT NULL::numeric, p_transfer_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract   RECORD;
  v_old_room   uuid;
  v_old_bld    uuid;
  v_new_bld    uuid;
  v_new_org    uuid;
  v_lock_a     uuid;
  v_lock_b     uuid;
BEGIN
  -- 1) Quyền (giữ đúng như trước) -------------------------------------------
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  IF p_new_room_id IS NULL THEN
    RAISE EXCEPTION 'Thiếu phòng mới';
  END IF;
  IF p_transfer_date IS NULL THEN
    -- Audit phải có mốc ngày, kẻo projection không dựng được đoạn.
    RAISE EXCEPTION 'Thiếu ngày chuyển phòng' USING ERRCODE = '22023';
  END IF;

  -- ══ KHOÁ PHÒNG TRƯỚC KHI ĐỌC ═══════════════════════════════════════
  -- Lỗ 3: kiểm "phòng đích còn trống" là SELECT trần nên hai hợp đồng cùng
  -- chuyển vào một phòng thì cả hai đều lọt. Khoá tư vấn theo TỪNG phòng và lấy
  -- theo THỨ TỰ ID TĂNG DẦN — hai phiên có chung một phòng sẽ xếp hàng, và không
  -- thể chờ chéo nhau (điều kiện đủ để tránh deadlock: mọi phiên khoá cùng thứ tự).
  -- Phải khoá TRƯỚC khi SELECT contract, vì phòng cũ chỉ biết được sau khi đọc
  -- contract ⇒ đọc contract "trần" một lần để lấy phòng cũ, khoá, rồi ĐỌC LẠI
  -- dưới FOR UPDATE và kiểm lại mọi tiền đề trên dữ liệu sau khoá.
  SELECT c.room_id INTO v_old_room
    FROM public.contracts c
   WHERE c.id = p_contract_id AND c.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hợp đồng không tồn tại';
  END IF;

  v_lock_a := LEAST(COALESCE(v_old_room, p_new_room_id), p_new_room_id);
  v_lock_b := GREATEST(COALESCE(v_old_room, p_new_room_id), p_new_room_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended('room:' || v_lock_a::text, 0));
  IF v_lock_b IS DISTINCT FROM v_lock_a THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
              pg_catalog.hashtextextended('room:' || v_lock_b::text, 0));
  END IF;

  -- Lỗ 2: nay khoá dòng hợp đồng. Đọc LẠI sau khoá phòng để thấy trạng thái mới
  -- nhất (phiên trước có thể vừa đổi room_id).
  SELECT * INTO v_contract
    FROM public.contracts
   WHERE id = p_contract_id AND deleted_at IS NULL
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hợp đồng không tồn tại';
  END IF;
  v_old_room := v_contract.room_id;

  IF NOT (
    public.is_super_admin()
    OR (v_contract.room_id IS NOT NULL AND public.can_do_on_building(
          'contracts', 'edit',
          (SELECT building_id FROM public.rooms WHERE id = v_contract.room_id)))
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên hợp đồng này' USING ERRCODE = '42501';
  END IF;

  -- 2) Tiền điều kiện — kiểm LẠI sau khoá ------------------------------------
  IF v_contract.status NOT IN ('ACTIVE', 'EXTENDED') THEN
    RAISE EXCEPTION 'Chỉ chuyển phòng được khi hợp đồng đang hiệu lực';
  END IF;
  IF p_new_room_id = v_contract.room_id THEN
    RAISE EXCEPTION 'Phòng mới trùng phòng hiện tại';
  END IF;

  -- Lỗ 4: phòng mới phải cùng TOÀ và cùng ORG với phòng hiện tại. Không có mệnh
  -- đề này thì chuyển được hợp đồng sang toà khác — kể cả tổ chức khác.
  SELECT r.building_id, b.organization_id INTO v_new_bld, v_new_org
    FROM public.rooms r
    LEFT JOIN public.buildings b ON b.id = r.building_id
   WHERE r.id = p_new_room_id AND r.deleted_at IS NULL;
  IF v_new_bld IS NULL THEN
    RAISE EXCEPTION 'Phòng mới không tồn tại';
  END IF;

  IF v_old_room IS NOT NULL THEN
    SELECT r.building_id INTO v_old_bld
      FROM public.rooms r WHERE r.id = v_old_room;
    IF v_old_bld IS DISTINCT FROM v_new_bld THEN
      RAISE EXCEPTION
        'Phòng mới thuộc toà khác — chuyển phòng chỉ trong cùng một toà. Muốn đổi toà thì thanh lý hợp đồng rồi tạo hợp đồng mới.'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Kiểm phòng đích SAU KHI đã giữ khoá ⇒ kết quả không thể lỗi thời.
  IF EXISTS (
    SELECT 1 FROM public.contracts
     WHERE room_id = p_new_room_id
       AND id <> p_contract_id
       AND status IN ('ACTIVE','EXTENDED')
       AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Phòng mới đã có hợp đồng đang hiệu lực';
  END IF;

  -- 3) AUDIT TRƯỚC, KHÔNG BỌC EXCEPTION -------------------------------------
  -- Lỗ 1: trước đây khối này nằm CUỐI và bọc `EXCEPTION WHEN OTHERS THEN NULL`,
  -- nên chuyển phòng xong mà mất dấu vết là chuyện có thể xảy ra êm ru. Nay ghi
  -- TRƯỚC mọi tác dụng phụ: audit lỗi ⇒ chưa có gì bị đổi, cả transaction rollback.
  -- status='COMPLETED' để KHÔNG kích trigger đường B (giữ đúng ý định cũ).
  INSERT INTO public.contract_transfers (
    user_id, contract_id, transfer_type, transfer_date,
    old_room_id, new_room_id, new_rent_price,
    move_out_date, move_in_date, reason, notes, status, approved_at, approved_by
  ) VALUES (
    v_contract.user_id, p_contract_id, 'ROOM_CHANGE', p_transfer_date,
    v_old_room, p_new_room_id, p_new_rent_price,
    p_transfer_date, p_transfer_date, p_notes, p_notes, 'COMPLETED', NOW(), auth.uid()
  );

  -- 4) Chuyển phòng (GIỮ status ACTIVE/EXTENDED, KHÔNG đụng kỳ hạn) ----------
  UPDATE public.contracts
     SET room_id    = p_new_room_id,
         rent_price = COALESCE(p_new_rent_price, rent_price),
         notes      = CASE
                        WHEN p_notes IS NULL OR length(btrim(p_notes)) = 0 THEN notes
                        WHEN notes  IS NULL OR length(btrim(notes))  = 0 THEN p_notes
                        ELSE notes || E'\n[Chuyển phòng ' || to_char(p_transfer_date,'DD/MM/YYYY') || '] ' || p_notes
                      END,
         updated_at = NOW()
   WHERE id = p_contract_id;

  -- 5) Đồng bộ trạng thái phòng --------------------------------------------
  IF v_old_room IS NOT NULL AND v_old_room <> p_new_room_id THEN
    UPDATE public.rooms SET status = 'AVAILABLE', updated_at = NOW()
     WHERE id = v_old_room
       AND NOT EXISTS (
         SELECT 1 FROM public.contracts
          WHERE room_id = v_old_room
            AND id <> p_contract_id
            AND status IN ('ACTIVE','EXTENDED')
            AND deleted_at IS NULL
       );
  END IF;

  UPDATE public.rooms SET status = 'OCCUPIED', updated_at = NOW() WHERE id = p_new_room_id;

  RETURN p_contract_id;
END;
$$;








--
-- Name: FUNCTION transfer_room(p_contract_id uuid, p_new_room_id uuid, p_new_rent_price numeric, p_transfer_date date, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transfer_room(p_contract_id uuid, p_new_room_id uuid, p_new_rent_price numeric, p_transfer_date date, p_notes text) IS 'Chuyển phòng trong CÙNG một toà, giữ hợp đồng ACTIVE/EXTENDED và KHÔNG đụng kỳ hạn. Đợt 2 Task 0: audit contract_transfers ghi TRƯỚC và KHÔNG bọc EXCEPTION (trước đây best-effort ⇒ chuyển phòng xong mà mất dấu vết trong im lặng); khoá dòng hợp đồng FOR UPDATE; khoá tư vấn theo từng phòng lấy theo thứ tự id tăng dần nên hai hợp đồng cùng vào một phòng phải xếp hàng và không chờ chéo; kiểm phòng mới cùng toà. status audit = COMPLETED để không kích trigger đường B.';








--
-- Name: trg_contract_link_orphan_deposits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_contract_link_orphan_deposits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_voucher uuid;
BEGIN
  IF current_setting('app.contract_create_v2', true) = 'on' OR NEW.room_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_voucher IN
    SELECT voucher.id
      FROM public.income_expenses voucher
     WHERE voucher.contract_id IS NULL
       AND voucher.organization_id = NEW.organization_id
       AND voucher.deleted_at IS NULL
       AND voucher.approval_status = 'APPROVED'
       AND voucher.type = 'INCOME'
       AND voucher.room_id = NEW.room_id
       AND voucher.voucher_date BETWEEN NEW.start_date - interval '30 days'
                                    AND NEW.start_date + interval '7 days'
       AND EXISTS (
         SELECT 1
         FROM public.income_expense_items item
         WHERE item.income_expense_id = voucher.id
           AND item.accounting_class = 'DEPOSIT'
       )
  LOOP
    -- Cửa hẹp LINK_CONTRACT: guard chỉ cho contract_id đi NULL → NOT NULL,
    -- mọi cột khác bất biến. Phiếu legacy (không flow-owned) không cần cửa
    -- nhưng mở cũng vô hại — giữ một đường ghi duy nhất.
    PERFORM app_private.begin_ie_flex_write_v1(v_voucher, 'LINK_CONTRACT');
    UPDATE public.income_expenses
       SET contract_id = NEW.id,
           updated_at = now()
     WHERE id = v_voucher
       AND contract_id IS NULL;
    PERFORM app_private.end_ie_flex_write_v1(v_voucher);
  END LOOP;

  PERFORM public.recompute_contract_deposit_paid(NEW.id);
  RETURN NEW;
END;
$$;








--
-- Name: trg_deposit_reconcile_room(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_deposit_reconcile_room() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM recompute_room_reservation(OLD.room_id);
    RETURN NULL;
  END IF;
  PERFORM recompute_room_reservation(NEW.room_id);
  IF TG_OP = 'UPDATE' AND OLD.room_id IS DISTINCT FROM NEW.room_id THEN
    PERFORM recompute_room_reservation(OLD.room_id);
  END IF;
  RETURN NULL;
END; $$;








--
-- Name: trg_forfeit_settle_on_approve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_forfeit_settle_on_approve() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_pay_note text;
  v_payment_id uuid;
  v_existing_count integer;
  v_core_writer boolean;
  v_opened_writer boolean := false;
  v_authorization app_private.termination_forfeit_authorizations%ROWTYPE;
BEGIN
  SELECT auth_row.*
    INTO v_authorization
  FROM app_private.termination_forfeit_authorizations auth_row
  WHERE auth_row.revenue_voucher_id = NEW.id
     OR auth_row.offset_voucher_id = NEW.id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT validated.*
    INTO v_authorization
  FROM app_private.require_termination_forfeit_authorization_v1(
    NEW.id, false, false
  ) validated;

  IF NEW.approval_status = 'APPROVED'
     AND COALESCE(OLD.approval_status, '') <> 'APPROVED'
     AND NEW.deleted_at IS NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM app_private.accounting_chain_writer_xids capability
      WHERE capability.transaction_id = txid_current()
        AND capability.backend_pid = pg_backend_pid()
    ) INTO v_core_writer;
    IF NOT v_core_writer THEN
      PERFORM app_private.begin_accounting_chain_write_v1();
      v_opened_writer := true;
    END IF;

    BEGIN
      -- 7b1: nhánh duyệt cũng chốt review của chân đối ứng, nếu không nó
      -- ở lại (APPROVED, PENDING) — đã duyệt mà vòng review còn treo.
      UPDATE public.income_expenses
         SET approval_status = 'APPROVED',
             approved_by = NEW.approved_by,
             approved_at = NEW.approved_at,
             review_state = 'RESOLVED',
             review_version = income_expenses.review_version + 1,
             updated_at = now()
       WHERE id = CASE
           WHEN NEW.id = v_authorization.revenue_voucher_id
             THEN v_authorization.offset_voucher_id
           ELSE v_authorization.revenue_voucher_id
         END
         AND deleted_at IS NULL
         AND approval_status IS DISTINCT FROM 'APPROVED';

      SELECT validated.*
        INTO v_authorization
      FROM app_private.require_termination_forfeit_authorization_v1(
        NEW.id, true, false
      ) validated;

      IF NEW.id = v_authorization.revenue_voucher_id THEN
        v_pay_note := '[CẤN CỌC BỎ CỌC PAYMENT '
          || v_authorization.revenue_voucher_id::text || ']';

        IF v_authorization.payment_id IS NOT NULL THEN
          PERFORM app_private.require_termination_forfeit_payment_v1(
            v_authorization.revenue_voucher_id
          );
        ELSE
          PERFORM 1
          FROM public.payments payment
          WHERE payment.invoice_id = v_authorization.invoice_id
            AND payment.notes = v_pay_note
          FOR UPDATE;

          SELECT count(*)::integer,
                 (array_agg(payment.id ORDER BY payment.id))[1]
            INTO v_existing_count, v_payment_id
          FROM public.payments payment
          WHERE payment.invoice_id = v_authorization.invoice_id
            AND payment.notes = v_pay_note;

          IF v_existing_count > 1 THEN
            RAISE EXCEPTION 'Duplicate forfeit settlement payment markers detected'
              USING ERRCODE = '55000';
          ELSIF v_existing_count = 1 THEN
            UPDATE app_private.termination_forfeit_authorizations auth_row
               SET payment_id = v_payment_id
             WHERE auth_row.revenue_voucher_id =
               v_authorization.revenue_voucher_id
               AND auth_row.payment_id IS NULL;
            PERFORM app_private.require_termination_forfeit_payment_v1(
              v_authorization.revenue_voucher_id
            );
          ELSE
            IF EXISTS (
              SELECT 1
              FROM public.payments payment
              WHERE payment.invoice_id = v_authorization.invoice_id
                AND payment.reversed_at IS NULL
                AND NOT EXISTS (
                  SELECT 1
                  FROM app_private.payment_reversals reversal
                  WHERE reversal.original_payment_id = payment.id
                )
            ) OR NOT EXISTS (
              SELECT 1
              FROM public.invoices invoice
              WHERE invoice.id = v_authorization.invoice_id
                AND invoice.deleted_at IS NULL
                AND invoice.total_amount = v_authorization.amount
                AND COALESCE(invoice.paid_amount, 0) = 0
                AND COALESCE(invoice.remaining_amount, invoice.total_amount)
                  = v_authorization.amount
            ) THEN
              RAISE EXCEPTION 'Forfeit invoice already has settlement activity'
                USING ERRCODE = '55000';
            END IF;

            INSERT INTO public.payments (
              user_id, organization_id, invoice_id, amount, payment_method,
              payment_date, notes, received_amount, credit_amount,
              change_amount, rounding_amount
            )
            SELECT
              revenue.user_id, v_authorization.organization_id,
              v_authorization.invoice_id, v_authorization.amount,
              'CT'::public.payment_method,
              v_authorization.voucher_date, v_pay_note,
              0, 0, 0, 0
            FROM public.income_expenses revenue
            WHERE revenue.id = v_authorization.revenue_voucher_id
              AND revenue.approval_status = 'APPROVED'
              AND revenue.deleted_at IS NULL
            RETURNING id INTO v_payment_id;

            IF v_payment_id IS NULL THEN
              RAISE EXCEPTION 'Forfeit payment writer did not create a payment'
                USING ERRCODE = '55000';
            END IF;

            UPDATE app_private.termination_forfeit_authorizations auth_row
               SET payment_id = v_payment_id
             WHERE auth_row.revenue_voucher_id =
               v_authorization.revenue_voucher_id
               AND auth_row.payment_id IS NULL;
            PERFORM app_private.require_termination_forfeit_payment_v1(
              v_authorization.revenue_voucher_id
            );
          END IF;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      IF v_opened_writer THEN
        PERFORM app_private.end_accounting_chain_write_v1();
      END IF;
      RAISE;
    END;

    IF v_opened_writer THEN
      PERFORM app_private.end_accounting_chain_write_v1();
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.approval_status IN ('UNAPPROVED', 'CANCELLED')
     AND NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    SELECT EXISTS (
      SELECT 1
      FROM app_private.accounting_chain_writer_xids capability
      WHERE capability.transaction_id = txid_current()
        AND capability.backend_pid = pg_backend_pid()
    ) INTO v_core_writer;
    IF NOT v_core_writer THEN
      PERFORM app_private.begin_accounting_chain_write_v1();
      v_opened_writer := true;
    END IF;

    BEGIN
      SELECT auth_row.payment_id
        INTO v_payment_id
      FROM app_private.termination_forfeit_authorizations auth_row
      WHERE auth_row.revenue_voucher_id =
        v_authorization.revenue_voucher_id
      FOR UPDATE;

      IF v_payment_id IS NOT NULL THEN
        PERFORM app_private.require_termination_forfeit_payment_v1(
          v_authorization.revenue_voucher_id
        );
        UPDATE app_private.termination_forfeit_authorizations auth_row
           SET payment_id = NULL
         WHERE auth_row.revenue_voucher_id =
           v_authorization.revenue_voucher_id
           AND auth_row.payment_id = v_payment_id;
        DELETE FROM public.payments payment
        WHERE payment.id = v_payment_id;
      END IF;

      UPDATE public.income_expenses
         SET approval_status = NEW.approval_status,
             approved_by = NULL,
             approved_at = NULL,
             -- Chân đối ứng phải theo cùng luật, nếu không nó kẹt một mình.
             review_state = CASE
               WHEN NEW.approval_status = 'UNAPPROVED' THEN 'PENDING'
               ELSE 'RESOLVED'
             END,
             review_version = income_expenses.review_version + 1,
             updated_at = now()
       WHERE id = CASE
           WHEN NEW.id = v_authorization.revenue_voucher_id
             THEN v_authorization.offset_voucher_id
           ELSE v_authorization.revenue_voucher_id
         END
         AND deleted_at IS NULL
         AND approval_status IS DISTINCT FROM NEW.approval_status;
    EXCEPTION WHEN OTHERS THEN
      IF v_opened_writer THEN
        PERFORM app_private.end_accounting_chain_write_v1();
      END IF;
      RAISE;
    END;

    IF v_opened_writer THEN
      PERFORM app_private.end_accounting_chain_write_v1();
    END IF;
    RETURN NULL;
  END IF;

  RETURN NULL;
END;
$$;








--
-- Name: trg_ie_commission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_commission_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_new_violates boolean;
  v_old_violates boolean;
BEGIN
  v_new_violates := NEW.commission_kind IS NOT NULL AND NEW.type = 'EXPENSE'
                    AND NEW.contract_id IS NULL AND NEW.deleted_at IS NULL
                    AND NEW.approval_status <> 'CANCELLED';
  IF NOT v_new_violates THEN RETURN NEW; END IF;

  -- SALE_BONUS_DEPOSIT_ANCHOR: phiếu thưởng Sale neo vào PHIẾU CỌC (hợp đồng chưa
  -- tồn tại lúc thưởng). Không trôi nổi — quan hệ nằm ở app_private.sale_bonus_claims.
  -- Cửa chỉ mở trong đúng transaction + đúng backend của writer definer, và
  -- writer đóng lại ngay sau lệnh INSERT.
  IF EXISTS (
    SELECT 1 FROM app_private.ie_flex_writer_xids w
     WHERE w.income_expense_id = NEW.id
       AND w.transaction_id = pg_current_xact_id()
       AND w.backend_pid = pg_backend_pid()
       AND w.scope = 'SALE_BONUS_DEPOSIT'
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_old_violates := OLD.commission_kind IS NOT NULL AND OLD.type = 'EXPENSE'
                      AND OLD.contract_id IS NULL AND OLD.deleted_at IS NULL
                      AND OLD.approval_status <> 'CANCELLED';
    IF v_old_violates THEN RETURN NEW; END IF; -- legacy giữ nguyên hiện trạng
    IF OLD.contract_id IS NOT NULL THEN
      RAISE EXCEPTION 'Không thể gỡ hợp đồng khỏi phiếu hoa hồng/thưởng Sale. Nếu phiếu tạo sai, hãy hủy phiếu rồi tạo lại.'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RAISE EXCEPTION 'Hạng mục "Hoa hồng môi giới"/"Thưởng nóng Sale" chỉ dùng cho phiếu gắn hợp đồng (chi qua flow ký HĐ hoặc Thu tiền → Chi HH). Chi hoa hồng cho đối tác ngoài vui lòng dùng hạng mục khác, vd "Hoa hồng đối tác".'
    USING ERRCODE = 'P0001';
END;
$$;








--
-- Name: trg_ie_items_commission_kind(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_items_commission_kind() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.ie_recompute_commission_kind(COALESCE(NEW.income_expense_id, OLD.income_expense_id));
  IF TG_OP = 'UPDATE' AND OLD.income_expense_id IS DISTINCT FROM NEW.income_expense_id THEN
    PERFORM public.ie_recompute_commission_kind(OLD.income_expense_id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;








--
-- Name: trg_ie_items_recompute_business_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_items_recompute_business_result() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recompute_ie_business_result(OLD.income_expense_id);
    RETURN OLD;
  END IF;

  PERFORM public.recompute_ie_business_result(NEW.income_expense_id);
  IF TG_OP = 'UPDATE' AND NEW.income_expense_id IS DISTINCT FROM OLD.income_expense_id THEN
    PERFORM public.recompute_ie_business_result(OLD.income_expense_id);
  END IF;
  RETURN NEW;
END;
$$;








--
-- Name: trg_ie_items_recompute_contract_deposit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_items_recompute_contract_deposit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract_id UUID;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT contract_id INTO v_contract_id
    FROM income_expenses
    WHERE id = OLD.income_expense_id;
  ELSE
    SELECT contract_id INTO v_contract_id
    FROM income_expenses
    WHERE id = NEW.income_expense_id;
  END IF;

  IF v_contract_id IS NOT NULL THEN
    PERFORM recompute_contract_deposit_paid(v_contract_id);
  END IF;

  RETURN NULL;
END;
$$;








--
-- Name: trg_ie_items_reconcile_room(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_items_reconcile_room() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_room_id uuid;
BEGIN
  SELECT room_id INTO v_room_id FROM income_expenses
  WHERE id = CASE WHEN TG_OP='DELETE' THEN OLD.income_expense_id ELSE NEW.income_expense_id END;
  PERFORM recompute_room_reservation(v_room_id);
  RETURN NULL;
END; $$;








--
-- Name: trg_ie_recompute_business_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_recompute_business_result() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.recompute_ie_business_result(NEW.id);
  RETURN NEW;
END;
$$;








--
-- Name: trg_ie_recompute_contract_deposit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_recompute_contract_deposit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.contract_id IS NOT NULL AND ie_has_deposit_item(OLD.id) THEN
      PERFORM recompute_contract_deposit_paid(OLD.contract_id);
    END IF;
    RETURN NULL;
  END IF;

  -- INSERT / UPDATE: recompute contract mới (nếu có item cọc)
  IF NEW.contract_id IS NOT NULL AND ie_has_deposit_item(NEW.id) THEN
    PERFORM recompute_contract_deposit_paid(NEW.contract_id);
  END IF;

  -- UPDATE đổi contract_id → cũng recompute contract cũ
  IF TG_OP = 'UPDATE'
     AND OLD.contract_id IS DISTINCT FROM NEW.contract_id
     AND OLD.contract_id IS NOT NULL
     AND ie_has_deposit_item(OLD.id) THEN
    PERFORM recompute_contract_deposit_paid(OLD.contract_id);
  END IF;

  RETURN NULL;
END;
$$;








--
-- Name: trg_ie_reconcile_room(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_reconcile_room() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM recompute_room_reservation(OLD.room_id);
    RETURN NULL;
  END IF;
  PERFORM recompute_room_reservation(NEW.room_id);
  IF TG_OP = 'UPDATE' AND OLD.room_id IS DISTINCT FROM NEW.room_id THEN
    PERFORM recompute_room_reservation(OLD.room_id);
  END IF;
  RETURN NULL;
END; $$;








--
-- Name: trg_ie_type_recompute_restricted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ie_type_recompute_restricted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE income_expenses ie
     SET has_restricted_item = sub.has_r
  FROM (
    SELECT it.income_expense_id, bool_or(t.is_restricted) AS has_r
    FROM income_expense_items it
    JOIN income_expense_types t ON t.id = it.income_expense_type_id
    WHERE it.income_expense_id IN (
      SELECT income_expense_id FROM income_expense_items
      WHERE income_expense_type_id = NEW.id
    )
    GROUP BY it.income_expense_id
  ) sub
  WHERE ie.id = sub.income_expense_id
    AND ie.has_restricted_item IS DISTINCT FROM sub.has_r;
  RETURN NEW;
END;
$$;








--
-- Name: trg_room_status_reconcile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_room_status_reconcile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_final public.rooms%rowtype;
  v_snapshot jsonb;
begin
  perform public.recompute_room_reservation(NEW.id);
  select room.* into v_final
  from public.rooms room
  where room.id = NEW.id and room.deleted_at is null;
  if found
     and v_final.status = 'AVAILABLE'
     and OLD.status is distinct from 'AVAILABLE'
  then
    if v_final.organization_id is null then
      raise exception 'room organization_id is required for OpenClaw CRM occurrence' using errcode = '23502';
    end if;
    v_snapshot := jsonb_build_object(
      'version',1,
      'eventType','room_became_available',
      'eventSubtype','FINAL_STATUS_AVAILABLE',
      'sourceTable','rooms',
      'sourceId',v_final.id,
      'sourceVersion',v_final.openclaw_availability_revision,
      'payload',jsonb_build_object(
        'roomId',v_final.id,
        'organizationId',v_final.organization_id,
        'buildingId',v_final.building_id,
        'name',v_final.name,
        'code',v_final.code,
        'status',v_final.status,
        'updatedAt',to_char(
          v_final.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        )
      )
    );
    perform app_private.openclaw_insert_crm_occurrence_v1(
      v_final.organization_id,'room_became_available','FINAL_STATUS_AVAILABLE',
      'rooms',v_final.id,v_final.openclaw_availability_revision,v_snapshot,v_final.updated_at
    );
  end if;
  return null;
end;
$$;








--
-- Name: unapprove_invoice_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unapprove_invoice_v1(p_invoice_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.invoices%rowtype;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  select * into v_row from public.invoices
   where id = p_invoice_id and deleted_at is null for update;
  if not found then
    raise exception 'Không tìm thấy hoá đơn hoặc bạn không có quyền' using errcode = '42501';
  end if;
  if not app_private.can_edit_invoice_building_v1(v_row.building_id) then
    raise exception 'Không có quyền bỏ duyệt hoá đơn này' using errcode = '42501';
  end if;
  if v_row.status = 'DRAFT' then
    return v_row; -- idempotent no-op
  end if;
  if v_row.status <> 'APPROVED' then
    raise exception 'Chỉ bỏ duyệt được hoá đơn Đã duyệt (trạng thái hiện tại: %)', v_row.status;
  end if;
  update public.invoices
     set status = 'DRAFT', approved_at = null, approved_by = null
   where id = v_row.id
   returning * into v_row;
  return v_row;
end;
$$;








--
-- Name: unapprove_meter_reading_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unapprove_meter_reading_v1(p_id uuid) RETURNS public.meter_readings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_row public.meter_readings; v_building uuid;
begin
  select * into v_row from public.meter_readings where id = p_id and deleted_at is null;
  if not found then raise exception 'Không tìm thấy chỉ số' using errcode='42501'; end if;
  select building_id into v_building from public.meters where id = v_row.meter_id;
  if not public.can_do_on_building('meter_readings','edit',v_building) then
    raise exception 'Không có quyền bỏ duyệt chỉ số cho toà này' using errcode='42501'; end if;
  if v_row.status = 'UNAPPROVED' then return v_row; end if; -- idempotent
  update public.meter_readings
     set status='UNAPPROVED', approved_by=null, approved_at=null
   where id = p_id returning * into v_row;
  return v_row;
end;
$$;








--
-- Name: unapprove_voucher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unapprove_voucher(voucher_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  -- t5_26: phiếu thuộc engine → không lùi trạng thái ngoài engine
  PERFORM app_private.assert_no_engine_request_v1(voucher_id);

  UPDATE income_expenses ie
  SET
    approval_status = 'UNAPPROVED',
    approved_by = NULL,
    approved_at = NULL,
    -- Trả phiếu về ĐÚNG đầu quy trình duyệt. Thiếu ba dòng này thì phiếu
    -- kẹt ở (UNAPPROVED, RESOLVED) và approve_income_expense_v2 từ chối
    -- vĩnh viễn — không đường nào cứu được từ giao diện.
    review_state = 'PENDING',
    review_version = ie.review_version + 1,
    review_reason = NULL,
    updated_at = now()
  WHERE ie.id = voucher_id
    AND ie.deleted_at IS NULL
    AND (
      ie.user_id = auth.uid()
      OR public.is_super_admin()
      OR (
        ie.building_id IS NOT NULL
        AND public.can_do_on_building('income_expenses', 'approve', ie.building_id)
      )
    );
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'Không thể huỷ duyệt phiếu: phiếu không tồn tại hoặc bạn không có quyền'
      USING ERRCODE = '42501';
  END IF;
END;
$$;








--
-- Name: undo_invoice_payment_compat_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_invoice_payment_compat_v1(p_payment_id uuid, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_hash text;
  v_operation app_private.canonical_write_operations%ROWTYPE;
  v_org uuid;
  v_building uuid;
  v_invoice uuid;
  v_collection uuid;
  v_tender uuid;
  v_reversed_at timestamptz;
  v_has_pair boolean := false;
  v_authz boolean;
  v_marker text := '[THU TACH COC ' || p_payment_id::text || ']';
  v_deleted integer := 0;
  v_reverse jsonb;
  v_response jsonb;
  c_operation constant text := 'invoice.legacy_split.delete.compat.v1';
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency key' USING ERRCODE = '22023';
  END IF;
  v_hash := md5(jsonb_build_object(
    'payment_id', p_payment_id,
    'reason', NULLIF(btrim(COALESCE(p_reason, '')), '')
  )::text);

  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.operation = c_operation
    AND operation_row.subject_scope = p_payment_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_operation.payload_hash <> v_hash THEN
      RAISE EXCEPTION 'Idempotency key reused with a different undo payload'
        USING ERRCODE = '23505';
    END IF;
    IF v_operation.completed_at IS NOT NULL THEN
      RETURN v_operation.response_payload;
    END IF;
  END IF;

  SELECT payment_row.organization_id, invoice_row.building_id, invoice_row.id,
         payment_row.collection_id, payment_row.tender_id, payment_row.reversed_at
    INTO v_org, v_building, v_invoice, v_collection, v_tender, v_reversed_at
  FROM public.payments payment_row
  JOIN public.invoices invoice_row
    ON invoice_row.id = payment_row.invoice_id
   AND invoice_row.deleted_at IS NULL
   AND invoice_row.organization_id = payment_row.organization_id
  JOIN public.buildings building_row
    ON building_row.id = invoice_row.building_id
   AND building_row.organization_id = invoice_row.organization_id
   AND building_row.deleted_at IS NULL
  JOIN public.organizations organization_row
    ON organization_row.id = invoice_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE payment_row.id = p_payment_id
  FOR UPDATE OF payment_row, invoice_row;
  IF v_org IS NULL THEN
    SELECT * INTO v_operation
    FROM app_private.canonical_write_operations operation_row
    WHERE operation_row.operation = c_operation
      AND operation_row.subject_scope = p_payment_id::text
      AND operation_row.actor_id = v_actor
      AND operation_row.idempotency_key = v_key
      AND operation_row.completed_at IS NOT NULL;
    IF FOUND AND v_operation.payload_hash = v_hash THEN
      RETURN v_operation.response_payload;
    END IF;
    RAISE EXCEPTION 'Payment not found in an active organization'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.income_expenses voucher_row
  WHERE voucher_row.organization_id = v_org
    AND voucher_row.deleted_at IS NULL
    AND (
      voucher_row.payment_id = p_payment_id
      OR position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
    )
  ORDER BY voucher_row.id
  FOR UPDATE;
  SELECT EXISTS (
    SELECT 1
    FROM public.income_expenses voucher_row
    WHERE voucher_row.organization_id = v_org
      AND voucher_row.deleted_at IS NULL
      AND position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
  ) INTO v_has_pair;

  IF NOT v_has_pair THEN
    v_reverse := public.reverse_invoice_payment_v3(
      p_payment_id, p_reason, v_key
    )::jsonb;
    RETURN jsonb_build_object(
      'payment_id', p_payment_id,
      'mode', 'REVERSED',
      'result', v_reverse
    );
  END IF;
  IF v_collection IS NOT NULL OR v_tender IS NOT NULL OR v_reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Legacy split cleanup cannot delete a canonical or reversed payment'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.undo', v_building, NULL
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Not authorized to undo this payment'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO app_private.canonical_write_operations (
    organization_id, operation, subject_scope, actor_id,
    idempotency_key, payload_hash
  ) VALUES (
    v_org, c_operation, p_payment_id::text, v_actor, v_key, v_hash
  )
  ON CONFLICT (organization_id, operation, subject_scope, actor_id, idempotency_key)
  DO NOTHING;
  SELECT * INTO v_operation
  FROM app_private.canonical_write_operations operation_row
  WHERE operation_row.organization_id = v_org
    AND operation_row.operation = c_operation
    AND operation_row.subject_scope = p_payment_id::text
    AND operation_row.actor_id = v_actor
    AND operation_row.idempotency_key = v_key
  FOR UPDATE;
  IF v_operation.payload_hash <> v_hash THEN
    RAISE EXCEPTION 'Idempotency key reused with a different undo payload'
      USING ERRCODE = '23505';
  END IF;
  IF v_operation.completed_at IS NOT NULL THEN
    RETURN v_operation.response_payload;
  END IF;

  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.income_expenses voucher_row
     SET deleted_at = clock_timestamp(),
         updated_at = clock_timestamp()
   WHERE voucher_row.organization_id = v_org
     AND voucher_row.deleted_at IS NULL
     AND (
       voucher_row.payment_id = p_payment_id
       OR position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
     );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  DELETE FROM public.excess_amounts excess_row
  WHERE excess_row.source_payment_id = p_payment_id;
  DELETE FROM public.payments payment_row
  WHERE payment_row.id = p_payment_id
    AND payment_row.organization_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment changed concurrently' USING ERRCODE = '40001';
  END IF;
  PERFORM app_private.end_accounting_chain_write_v1();

  v_response := jsonb_build_object(
    'payment_id', p_payment_id,
    'invoice_id', v_invoice,
    'mode', 'DELETED',
    'deleted_voucher_count', v_deleted
  );
  UPDATE app_private.canonical_write_operations
     SET subject_id = p_payment_id,
         response_payload = v_response,
         completed_at = clock_timestamp()
   WHERE organization_id = v_org
     AND operation = c_operation
     AND subject_scope = p_payment_id::text
     AND actor_id = v_actor
     AND idempotency_key = v_key;
  RETURN v_response;
END;
$_$;








--
-- Name: unlock_profit_month_v1(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_profit_month_v1(p_period_month text, p_building_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_authz boolean;
  v_pm_ids uuid[];
  v_count int;
  v_period date;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;
  if p_building_ids is null or array_length(p_building_ids, 1) is null then
    return 0;
  end if;
  if p_period_month is null or p_period_month !~ '^\d{4}-\d{2}(-\d{2})?$' then
    raise exception 'period_month phải dạng YYYY-MM hoặc YYYY-MM-DD';
  end if;
  v_period := (case when length(p_period_month) = 7
                    then p_period_month || '-01' else p_period_month end)::date;

  select b.organization_id into v_org
    from public.buildings b where b.id = p_building_ids[1] and b.deleted_at is null;
  if v_org is null then
    raise exception 'Toà nhà không hợp lệ';
  end if;
  if exists (
    select 1 from unnest(p_building_ids) bid
    left join public.buildings b on b.id = bid and b.deleted_at is null
    where b.id is null or b.organization_id is distinct from v_org
  ) then
    raise exception 'Danh sách toà chứa toà không thuộc cùng tổ chức' using errcode = '42501';
  end if;

  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'shareholder_profit.unlock', null, null);
  if not coalesce(v_authz, false) then
    raise exception 'Không có quyền mở khoá lợi nhuận (shareholder_profit.unlock)' using errcode = '42501';
  end if;

  select array_agg(id) into v_pm_ids from public.profit_monthly
   where period_month = v_period and building_id = any (p_building_ids);
  if v_pm_ids is null then return 0; end if;

  delete from public.profit_allocations where profit_monthly_id = any (v_pm_ids);
  delete from public.profit_manager_allocations where profit_monthly_id = any (v_pm_ids);
  update public.profit_monthly
     set status = 'DRAFT', management_salary = 0, locked_at = null, locked_by = null,
         organization_id = coalesce(organization_id, v_org)
   where id = any (v_pm_ids);
  get diagnostics v_count = row_count;
  return v_count;
end;
$_$;








--
-- Name: unlock_salary_month_v1(date, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_salary_month_v1(p_period_month date, p_staff_ids uuid[], p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_building uuid;
  v_authz boolean;
  v_key text;
  v_hash text;
  v_op app_private.canonical_write_operations%rowtype;
  v_route text;
  c_op constant text := 'salary.unlock.v1';
  v_ids uuid[];
  v_unlocked_count int := 0;
  v_resp json;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;

  v_key := btrim(coalesce(p_idempotency_key,''));
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'idempotency_key phải dài 8-200 ký tự ASCII an toàn'; end if;
  if p_period_month is null then raise exception 'Kỳ lương trống'; end if;
  if p_staff_ids is null or array_length(p_staff_ids,1) is null then
    raise exception 'Danh sách nhân viên trống'; end if;

  -- R3-FIX: org subject-derived từ nhân viên đầu tiên (đồng bộ lock).
  select organization_id into v_org from public.organization_memberships
   where user_id = p_staff_ids[1] and status='ACTIVE' limit 1;
  if v_org is null then
    select organization_id into v_org from public.manager_salary_config
     where staff_id = p_staff_ids[1] and organization_id is not null order by created_at desc limit 1;
  end if;
  if v_org is null then raise exception 'Không xác định được tổ chức của nhân viên'; end if;
  select b.id into v_building from public.buildings b
    join public.organizations o on o.id=b.organization_id and o.status='ACTIVE'
   where b.organization_id = v_org and b.is_virtual=true and b.deleted_at is null
   order by b.created_at limit 1 for share of o,b;

  perform app_private.lock_org_for_decision_v1(v_org);

  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'salary.unlock', v_building, null);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền mở khoá lương (salary.unlock)' using errcode='42501'; end if;

  v_hash := md5(jsonb_build_object('period',p_period_month,'org',v_org,
                                   'staff', to_jsonb(p_staff_ids))::text);
  insert into app_private.canonical_write_operations
    (organization_id, operation, subject_scope, actor_id, idempotency_key, payload_hash)
  values (v_org, c_op, p_period_month::text, v_actor, v_key, v_hash)
  on conflict (organization_id, operation, subject_scope, actor_id, idempotency_key) do nothing;
  select * into v_op from app_private.canonical_write_operations o
   where o.organization_id=v_org and o.operation=c_op and o.subject_scope=p_period_month::text
     and o.actor_id=v_actor and o.idempotency_key=v_key for update;
  if v_op.payload_hash <> v_hash then
    raise exception 'idempotency_key đã dùng với nội dung khác' using errcode='23505'; end if;
  if v_op.completed_at is not null then return v_op.response_payload::json; end if;

  v_route := app_private.evaluate_feature_route(c_op, v_org);
  if v_route <> 'CANONICAL' then
    raise exception 'Writer mở khoá lương chưa bật' using errcode='55000'; end if;

  -- Chỉ mở các dòng đang LOCKED cho (kỳ, staff_ids) — guard LOCKED→DRAFT.
  -- (array_agg + FOR UPDATE không đi cùng → lock rows ở statement riêng trước.)
  perform 1 from public.salary_monthly
   where period_month = p_period_month and staff_id = any(p_staff_ids) and status = 'LOCKED'
   for update;
  select array_agg(id) into v_ids
    from public.salary_monthly
   where period_month = p_period_month
     and staff_id = any(p_staff_ids)
     and status = 'LOCKED';

  if v_ids is not null and array_length(v_ids,1) is not null then
    delete from public.salary_work_ledger_snapshot where salary_monthly_id = any(v_ids);
    update public.salary_monthly
       set status = 'DRAFT', locked_at = null, locked_by = null
     where id = any(v_ids);
    v_unlocked_count := array_length(v_ids,1);
  end if;
  -- CỐ Ý: KHÔNG đảo ngược duyệt hoa hồng (xem header). Không đụng income_expenses.

  v_resp := json_build_object(
    'period_month', p_period_month,
    'unlocked_count', v_unlocked_count,
    'state', 'DRAFT');
  update app_private.canonical_write_operations
     set subject_id = coalesce(v_ids[1], v_actor),
         response_payload = to_jsonb(v_resp), completed_at = now()
   where organization_id=v_org and operation=c_op and subject_scope=p_period_month::text
     and actor_id=v_actor and idempotency_key=v_key;
  return v_resp;
end;
$_$;








--
-- Name: update_asset_status_on_contract_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_asset_status_on_contract_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- assets không có status field — trigger này không cần làm gì.
  -- Giữ trigger để không phải drop trigger DDL trên contracts (tránh churn).
  RETURN NEW;
END;
$$;








--
-- Name: update_building_total_rooms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_building_total_rooms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE buildings
  SET total_rooms = (
    SELECT COUNT(*)
    FROM rooms
    WHERE building_id = COALESCE(NEW.building_id, OLD.building_id)
      AND deleted_at IS NULL
  )
  WHERE id = COALESCE(NEW.building_id, OLD.building_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;








--
-- Name: update_cashbook_metadata_v1(uuid, text, text, numeric, date, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cashbook_metadata_v1(p_cashbook_id uuid, p_name text, p_description text, p_initial_amount numeric, p_initial_date date, p_quick_default_building_id uuid, p_is_default boolean, p_owner_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare v_actor uuid := auth.uid(); v_org uuid; v_authz boolean; v_owner uuid;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  select organization_id into v_org from public.accounts where id=p_cashbook_id and deleted_at is null;
  if v_org is null then raise exception 'Không tìm thấy sổ quỹ' using errcode='42501'; end if;
  perform app_private.lock_org_for_decision_v1(v_org);
  select allowed into v_authz from app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'cashbooks.edit', null, p_cashbook_id);
  if not coalesce(v_authz,false) then
    raise exception 'Không có quyền sửa sổ quỹ (cashbooks.edit)' using errcode='42501'; end if;
  if p_name is not null and length(btrim(p_name))=0 then raise exception 'Tên sổ quỹ trống'; end if;

  v_owner := p_owner_user_id;
  if v_owner is not null and v_owner <> (select user_id from public.accounts where id=p_cashbook_id) then
    perform 1 from public.organization_memberships m
      where m.user_id=v_owner and m.organization_id=v_org and m.status='ACTIVE';
    if not found then raise exception 'Người phụ trách không thuộc tổ chức' using errcode='42501'; end if;
  end if;

  if coalesce(p_is_default,false) then
    update public.accounts set is_default=false
     where organization_id=v_org and is_default=true and deleted_at is null and id<>p_cashbook_id;
  end if;

  update public.accounts set
    name = coalesce(nullif(btrim(p_name),''), name),
    description = case when p_description is null then description else nullif(btrim(p_description),'') end,
    initial_amount = coalesce(p_initial_amount, initial_amount),
    initial_date = coalesce(p_initial_date, initial_date),
    quick_default_building_id = p_quick_default_building_id,
    is_default = coalesce(p_is_default, is_default),
    user_id = coalesce(v_owner, user_id),
    updated_at = now()
  where id = p_cashbook_id;
  return json_build_object('cashbook_id', p_cashbook_id);
end;
$$;








--
-- Name: update_contract_on_termination_approved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contract_on_termination_approved() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- When termination is approved, update the contract
  IF TG_OP = 'UPDATE' AND OLD.status != 'APPROVED' AND NEW.status = 'APPROVED' THEN
    UPDATE contracts
    SET
      status = 'TERMINATED',
      actual_end_date = NEW.actual_move_out_date,
      updated_at = NOW()
    WHERE id = NEW.contract_id;

    -- Record approval timestamp
    NEW.approved_by := auth.uid();
    NEW.approved_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: FUNCTION update_contract_on_termination_approved(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_contract_on_termination_approved() IS 'Updates contract status to TERMINATED when termination record is approved';








--
-- Name: update_income_expense_quick(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_income_expense_quick(p_id uuid, p_account_id uuid, p_attachments jsonb, p_notes text) RETURNS public.income_expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app_private', 'public'
    AS $$
DECLARE
  v_row public.income_expenses;
  v_before public.income_expenses%ROWTYPE;
  v_actor record;
  v_posted boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_before
  FROM public.income_expenses
  WHERE id = p_id AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu hoặc bạn không có quyền sửa'
      USING ERRCODE = '42501';
  END IF;

  -- Tập người gọi GIỮ NGUYÊN như trước bản vá (chỉ siết thêm bên dưới).
  IF NOT (v_before.user_id = auth.uid() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu hoặc bạn không có quyền sửa'
      USING ERRCODE = '42501';
  END IF;

  IF v_before.approval_status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Phiếu đã hủy — không sửa' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_actor FROM app_private.ie_compat_actor_v2(v_before.organization_id);
  v_posted := COALESCE(v_before.posting_status, 'UNPOSTED') = 'POSTED';

  -- SIẾT MỚI (LỖ B): `account_id` nằm trong `UPDATE OF` của cầu a85.
  -- Đổi sổ trên phiếu ĐÃ GHI SỔ khiến cầu đảo posting ở sổ cũ và ghi
  -- posting ở sổ mới — tiền rời két người khác. Cấm thẳng.
  IF p_account_id IS DISTINCT FROM v_before.account_id THEN
    IF v_posted THEN
      RAISE EXCEPTION 'Phiếu đã ghi sổ — không đổi sổ quỹ ở đây. Hoàn tác rồi lập lại phiếu.'
        USING ERRCODE = '55000';
    END IF;
    IF v_actor.membership_id IS NULL THEN
      RAISE EXCEPTION 'Không có membership active trong organization phiếu' USING ERRCODE='42501';
    END IF;
    IF v_before.account_id IS NOT NULL THEN
      PERFORM app_private.assert_cashbook_access_v2(
        v_before.organization_id, v_before.account_id, 'CUSTODIAN', v_actor.membership_id);
    END IF;
    IF p_account_id IS NOT NULL THEN
      PERFORM app_private.assert_cashbook_access_v2(
        v_before.organization_id, p_account_id, 'CUSTODIAN', v_actor.membership_id);
    END IF;
  END IF;

  -- SIẾT MỚI: dấu hiệu tiền trong ghi chú (xem LỖ A).
  PERFORM app_private.assert_notes_markers_unchanged_v1(v_before.notes, COALESCE(p_notes, v_before.notes));

  UPDATE public.income_expenses
  SET
    account_id  = p_account_id,
    -- Phiếu đã ghi sổ: ảnh chỉ nối thêm, không gỡ bằng chứng.
    attachments = CASE
                    WHEN v_posted
                      THEN app_private.ie_attachments_union_v1(attachments, p_attachments)
                    ELSE COALESCE(p_attachments, '[]'::jsonb)
                  END,
    notes       = COALESCE(p_notes, notes)
  WHERE id = p_id
    AND deleted_at IS NULL
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu hoặc bạn không có quyền sửa'
      USING ERRCODE = '42501';
  END IF;

  -- SIẾT MỚI: thao tác này trước đây KHÔNG để lại dấu vết nào.
  PERFORM app_private.append_income_expense_event_v1(
    v_row.organization_id,
    p_id,
    'MANUAL_LOG',
    auth.uid(),
    NULL,
    v_before.approval_status,
    v_row.approval_status,
    'Sửa nhanh: sổ quỹ/ảnh/ghi chú'
  );

  RETURN v_row;
END
$$;








--
-- Name: update_invoice_payment_method_v1(uuid, public.payment_method); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoice_payment_method_v1(p_payment_id uuid, p_new_method public.payment_method) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_payment_user uuid;
  v_current_method public.payment_method;
  v_collection uuid;
  v_tender uuid;
  v_reversed_at timestamptz;
  v_org uuid;
  v_building uuid;
  v_building_name text;
  v_default_tt uuid;
  v_default_tk uuid;
  v_account uuid;
  v_authz boolean;
  v_voucher_count integer := 0;
  v_marker text := '[THU TACH COC ' || p_payment_id::text || ']';
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_new_method IS NULL OR p_new_method::text NOT IN ('TM', 'TT', 'TK') THEN
    RAISE EXCEPTION 'Unsupported editable payment method' USING ERRCODE = '22023';
  END IF;

  SELECT payment_row.user_id, payment_row.payment_method,
         payment_row.collection_id, payment_row.tender_id, payment_row.reversed_at,
         invoice_row.organization_id, invoice_row.building_id,
         building_row.name, building_row.default_account_id_tt,
         building_row.default_account_id_tk
    INTO v_payment_user, v_current_method, v_collection, v_tender, v_reversed_at,
         v_org, v_building, v_building_name, v_default_tt, v_default_tk
  FROM public.payments payment_row
  JOIN public.invoices invoice_row
    ON invoice_row.id = payment_row.invoice_id
   AND invoice_row.deleted_at IS NULL
   AND invoice_row.organization_id = payment_row.organization_id
  JOIN public.buildings building_row
    ON building_row.id = invoice_row.building_id
   AND building_row.organization_id = invoice_row.organization_id
   AND building_row.deleted_at IS NULL
  JOIN public.organizations organization_row
    ON organization_row.id = invoice_row.organization_id
   AND organization_row.status = 'ACTIVE'
  WHERE payment_row.id = p_payment_id
  FOR UPDATE OF payment_row, invoice_row;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Payment not found in an active organization'
      USING ERRCODE = '42501';
  END IF;
  IF v_reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'A reversed payment cannot change method'
      USING ERRCODE = '55000';
  END IF;
  IF v_collection IS NOT NULL OR v_tender IS NOT NULL THEN
    RAISE EXCEPTION 'Collection-based payments must be edited at collection level'
      USING ERRCODE = '55000';
  END IF;
  IF v_current_method = p_new_method THEN
    RETURN jsonb_build_object(
      'payment_id', p_payment_id,
      'new_method', p_new_method,
      'skipped', true
    );
  END IF;

  IF p_new_method = 'TM'::public.payment_method THEN
    SELECT account_row.id INTO v_account
    FROM public.accounts account_row
    WHERE account_row.organization_id = v_org
      AND account_row.user_id = v_payment_user
      AND account_row.deleted_at IS NULL
      AND NOT account_row.is_virtual
      AND right(lower(btrim(account_row.name)), 3) = 'thu'
    ORDER BY account_row.is_default DESC, account_row.created_at, account_row.id
    LIMIT 1
    FOR SHARE;
    IF v_account IS NULL THEN
      SELECT account_row.id INTO v_account
      FROM public.accounts account_row
      WHERE account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND NOT account_row.is_virtual
        AND lower(btrim(account_row.name)) = 'chung'
      ORDER BY account_row.is_default DESC, account_row.created_at, account_row.id
      LIMIT 1
      FOR SHARE;
    END IF;
  ELSE
    v_account := CASE
      WHEN p_new_method = 'TT'::public.payment_method THEN v_default_tt
      ELSE v_default_tk
    END;
    IF v_account IS NOT NULL THEN
      PERFORM 1
      FROM public.accounts account_row
      WHERE account_row.id = v_account
        AND account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND NOT account_row.is_virtual
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Configured building cashbook is invalid for this organization'
          USING ERRCODE = '55000';
      END IF;
    ELSIF NULLIF(btrim(v_building_name), '') IS NOT NULL THEN
      SELECT account_row.id INTO v_account
      FROM public.accounts account_row
      WHERE account_row.organization_id = v_org
        AND account_row.deleted_at IS NULL
        AND NOT account_row.is_virtual
        AND account_row.name = v_building_name
      ORDER BY account_row.is_default DESC, account_row.created_at, account_row.id
      LIMIT 1
      FOR SHARE;
    END IF;
  END IF;
  IF v_account IS NULL THEN
    RAISE EXCEPTION 'No real cashbook is configured for the selected payment method'
      USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_org_for_decision_v1(v_org);
  SELECT allowed INTO v_authz
  FROM app_private.authorize_tenant_action_v3(
    v_actor, v_org, 'thu_tien.collect', v_building, v_account
  );
  IF NOT COALESCE(v_authz, false) THEN
    RAISE EXCEPTION 'Not authorized to edit this payment'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.income_expenses voucher_row
  WHERE voucher_row.deleted_at IS NULL
    AND (
      voucher_row.payment_id = p_payment_id
      OR position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
    )
  ORDER BY voucher_row.id
  FOR UPDATE;
  IF EXISTS (
    SELECT 1
    FROM public.income_expenses voucher_row
    WHERE voucher_row.deleted_at IS NULL
      AND (
        voucher_row.payment_id = p_payment_id
        OR position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
      )
      AND voucher_row.organization_id IS DISTINCT FROM v_org
  ) THEN
    RAISE EXCEPTION 'Payment source voucher crosses organization boundary'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.income_expenses voucher_row
     SET account_id = v_account,
         updated_at = clock_timestamp()
   WHERE voucher_row.organization_id = v_org
     AND voucher_row.deleted_at IS NULL
     AND (
       voucher_row.payment_id = p_payment_id
       OR position(v_marker IN COALESCE(voucher_row.notes, '')) > 0
     );
  GET DIAGNOSTICS v_voucher_count = ROW_COUNT;

  UPDATE public.payments payment_row
     SET payment_method = p_new_method,
         updated_at = clock_timestamp()
   WHERE payment_row.id = p_payment_id
     AND payment_row.organization_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment changed concurrently' USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object(
    'payment_id', p_payment_id,
    'new_method', p_new_method,
    'new_account_id', v_account,
    'voucher_count', v_voucher_count,
    'voucher_found', v_voucher_count > 0,
    'skipped', false
  );
END;
$$;








--
-- Name: update_invoice_v1(uuid, uuid, uuid, uuid, text, date, date, numeric, numeric, numeric, numeric, jsonb, numeric, text, boolean, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoice_v1(p_invoice_id uuid, p_contract_id uuid, p_building_id uuid, p_room_id uuid, p_billing_month text, p_issue_date date, p_due_date date, p_subtotal numeric, p_discount_amount numeric, p_total_amount numeric, p_previous_debt numeric, p_items jsonb, p_prepaid_amount numeric DEFAULT 0, p_discount_notes text DEFAULT NULL::text, p_electricity_prev_overridden boolean DEFAULT false, p_previous_debt_sources jsonb DEFAULT '[]'::jsonb, p_template_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.invoices%rowtype;
  v_org uuid;
  it jsonb; v_idx int := 0;
  v_total_calc numeric(15,2);
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  if p_items is not null and jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items phải là JSON array'; end if;

  select * into v_row from public.invoices
   where id = p_invoice_id and deleted_at is null for update;
  if not found then
    raise exception 'Không tìm thấy hoá đơn hoặc bạn không có quyền' using errcode='42501'; end if;
  v_org := v_row.organization_id;

  -- SERVER mirror canEditInvoice: (DRAFT|APPROVED) AND paid_amount=0. Dùng errcode
  -- mặc định (P0001, KHÔNG fallback) → lỗi hiện thẳng như legacy hook, không rơi
  -- xuống đường legacy để lách guard.
  if v_row.status not in ('DRAFT'::invoice_status, 'APPROVED'::invoice_status)
     or coalesce(v_row.paid_amount,0) <> 0 then
    raise exception 'Không thể chỉnh sửa hoá đơn ở trạng thái này';
  end if;

  -- quyền edit theo toà HIỆN TẠI của hoá đơn.
  if not app_private.can_edit_invoice_building_v1(v_row.building_id) then
    raise exception 'Không có quyền chỉnh sửa hoá đơn này' using errcode='42501'; end if;

  -- Nếu ĐỔI toà → chặn cross-org + đòi quyền edit trên toà đích. (Đổi phòng cũng
  -- verify thuộc toà đích/cùng org, mirror ràng buộc create.)
  if p_building_id is distinct from v_row.building_id then
    perform 1 from public.buildings b
     where b.id=p_building_id and b.deleted_at is null and b.organization_id=v_org;
    if not found then
      raise exception 'Toà đích không thuộc tổ chức của hoá đơn' using errcode='42501'; end if;
    if not app_private.can_edit_invoice_building_v1(p_building_id) then
      raise exception 'Không có quyền chỉnh sửa sang toà này' using errcode='42501'; end if;
  end if;
  if p_room_id is not null then
    perform 1 from public.rooms r
     where r.id=p_room_id and r.deleted_at is null
       and r.building_id=p_building_id and r.organization_id=v_org;
    if not found then
      raise exception 'Phòng không thuộc toà/tổ chức' using errcode='42501'; end if;
  end if;

  -- recalc total + assert (làm tròn trên p_subtotal, giống create).
  v_total_calc := app_private.round_invoice_total_v1(
    coalesce(p_subtotal,0) - coalesce(p_discount_amount,0) + coalesce(p_previous_debt,0));

  if v_total_calc is distinct from p_total_amount then
    raise exception
      'Tổng tiền client (%) khác tổng server làm tròn (%) [subtotal=%, discount=%, nợ cũ=%]',
      p_total_amount, v_total_calc, coalesce(p_subtotal,0),
      coalesce(p_discount_amount,0), coalesce(p_previous_debt,0)
      using errcode='22000';
  end if;

  update public.invoices
     set contract_id                 = p_contract_id,
         building_id                 = p_building_id,
         room_id                     = p_room_id,
         billing_month               = p_billing_month,
         issue_date                  = p_issue_date,
         due_date                    = p_due_date,
         subtotal                    = coalesce(p_subtotal,0),
         discount_amount             = coalesce(p_discount_amount,0),
         discount_notes              = p_discount_notes,
         electricity_prev_overridden = coalesce(p_electricity_prev_overridden,false),
         total_amount                = p_total_amount,
         prepaid_amount              = coalesce(p_prepaid_amount,0),
         previous_debt               = coalesce(p_previous_debt,0),
         previous_debt_sources       = coalesce(p_previous_debt_sources,'[]'::jsonb),
         notes                       = p_notes,
         template_id                 = p_template_id
   where id = p_invoice_id
   returning * into v_row;

  -- replace items (delete-all rồi insert lại, mirror legacy).
  delete from public.invoice_items where invoice_id = p_invoice_id;
  if p_items is not null then
    for it in select value from jsonb_array_elements(p_items) loop
      v_idx := v_idx + 1;
      insert into public.invoice_items
        (invoice_id, organization_id, service_id, type, description, unit_price,
         quantity, coefficient, amount, previous_reading, current_reading,
         from_date, to_date, sort_order)
      values (
        p_invoice_id, v_org,
        nullif(it->>'service_id','')::uuid,
        coalesce(nullif(it->>'type','')::invoice_item_type, 'OTHER'::invoice_item_type),
        it->>'description',
        coalesce((it->>'unit_price')::numeric,0),
        coalesce((it->>'quantity')::numeric,1),
        coalesce((it->>'coefficient')::numeric,1),
        coalesce((it->>'amount')::numeric,
          coalesce((it->>'unit_price')::numeric,0)
          * coalesce((it->>'quantity')::numeric,1)
          * coalesce((it->>'coefficient')::numeric,1)),
        nullif(it->>'previous_reading','')::numeric,
        nullif(it->>'current_reading','')::numeric,
        nullif(it->>'from_date','')::date,
        nullif(it->>'to_date','')::date,
        coalesce((it->>'sort_order')::int, v_idx)
      );
    end loop;
  end if;

  return v_row;
end;
$$;








--
-- Name: update_lead_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_lead_score() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  score INTEGER := 0;
BEGIN
  -- Budget score (0-30 points)
  IF NEW.budget_max IS NOT NULL THEN
    score := score + 30;
  ELSIF NEW.budget_min IS NOT NULL THEN
    score := score + 15;
  END IF;

  -- Appointment date (0-25 points)
  IF NEW.appointment_date IS NOT NULL THEN
    IF NEW.appointment_date >= public.org_today_v1(NULL) THEN
      score := score + 25;
    ELSE
      score := score + 10;
    END IF;
  END IF;

  -- Source quality (0-20 points)
  CASE NEW.source::text
    WHEN 'REFERRAL' THEN score := score + 20;
    WHEN 'WALK_IN' THEN score := score + 18;
    WHEN 'WEBSITE' THEN score := score + 15;
    WHEN 'FACEBOOK' THEN score := score + 12;
    WHEN 'ZALO' THEN score := score + 12;
    WHEN 'PHONE' THEN score := score + 10;
    ELSE score := score + 5;
  END CASE;

  -- Status progression (0-20 points)
  CASE NEW.status::text
    WHEN 'CONVERTED' THEN score := score + 20;
    WHEN 'B3_CONSULTATION' THEN score := score + 15;
    WHEN 'B2_APPOINTMENT' THEN score := score + 10;
    WHEN 'B1_LEAD' THEN score := score + 5;
    WHEN 'FAILED' THEN score := score + 0;
    ELSE score := score + 0;
  END CASE;

  -- Email provided (0-5 points)
  IF NEW.email IS NOT NULL THEN
    score := score + 5;
  END IF;

  -- Move-in date soon (0-5 points)
  IF NEW.move_in_date IS NOT NULL AND NEW.move_in_date <= public.org_today_v1(NULL) + INTERVAL '30 days' THEN
    score := score + 5;
  END IF;

  NEW.lead_score := score;
  RETURN NEW;
END;
$$;








--
-- Name: update_member_authorization_v1(uuid, bigint, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_member_authorization_v1(p_membership uuid, p_expected_version bigint, p_role_bindings jsonb DEFAULT NULL::jsonb, p_overrides jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor    uuid := (select auth.uid());
  v_org      uuid;
  v_user     uuid;
  v_ver      bigint;
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_truoc    text[];
  v_sau      text[];
  v_them     text[];
  v_mat      text[];
  v_b        jsonb;
  v_o        jsonb;
  v_id       uuid;
  v_n_bind   int := 0;
  v_n_ov     int := 0;
begin
  if v_actor is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  if p_membership is null or p_expected_version is null then
    raise exception 'Thiếu thành viên hoặc số phiên bản. Hãy tải lại trang rồi thử lại.'
      using errcode = '22023';
  end if;
  if p_role_bindings is null and p_overrides is null then
    raise exception 'Không có gì để lưu.' using errcode = '22023';
  end if;
  if v_reason is null then
    raise exception 'Hãy ghi lý do thay đổi phân quyền.' using errcode = '22023';
  end if;

  select m.organization_id, m.user_id into v_org, v_user
    from public.organization_memberships m where m.id = p_membership;
  if v_org is null then
    raise exception 'Không tìm thấy thành viên này.' using errcode = 'P0002';
  end if;

  -- So bằng user_id, KHÔNG bằng membership_id: người có nhiều hồ sơ thành viên
  -- trong cùng tổ chức sẽ lách được nếu chỉ so membership.
  if v_user = v_actor then
    raise exception 'Bạn không thể tự sửa quyền của chính mình. Hãy nhờ chủ sở hữu thực hiện.'
      using errcode = '42501';
  end if;

  perform app_private.require_perm_v1(v_org, 'users.edit', 'sửa phân quyền thành viên');

  -- Khoá dòng RỒI mới so phiên bản (đọc trước khi khoá là sai — hai người cùng
  -- lưu có thể cùng đọc đúng version rồi cùng ghi).
  select m.version into v_ver
    from public.organization_memberships m where m.id = p_membership for update;
  if v_ver <> p_expected_version then
    raise exception 'Có người vừa đổi phân quyền của thành viên này. Hãy tải lại trang để xem thay đổi mới nhất.'
      using errcode = '40001';
  end if;

  -- Ảnh chụp quyền TRƯỚC, để trả về "mất gì / được thêm gì".
  v_truoc := app_private.allowed_keys_for_membership_v3(p_membership);

  -- ---- Lớp VAI TRÒ ----
  if p_role_bindings is not null then
    -- role_bindings_check đòi valid_to > valid_from NGHIÊM NGẶT. now() là mốc đầu
    -- giao dịch, nên nếu một binding vừa được tạo rồi bị đóng TRONG CÙNG giao dịch
    -- (lưu hai lần liên tiếp, hoặc kịch bản kiểm thử) thì hai mốc bằng nhau và
    -- ràng buộc nổ. Đẩy thêm 1 micro giây để luôn hợp lệ.
    update public.role_bindings
       set valid_to = greatest(now(), valid_from + interval '1 microsecond'),
           version = version + 1
     where membership_id = p_membership and valid_to is null;

    for v_b in select * from jsonb_array_elements(p_role_bindings) loop
      if not exists (select 1 from public.organization_roles r
                      where r.id = (v_b->>'role_id')::uuid and r.organization_id = v_org) then
        raise exception 'Vai trò không thuộc tổ chức này.' using errcode = '22023';
      end if;
      v_id := gen_random_uuid();
      insert into public.role_bindings (id, organization_id, membership_id, role_id, valid_from, version)
      values (v_id, v_org, p_membership, (v_b->>'role_id')::uuid, now(), 1);

      insert into public.role_binding_scopes (organization_id, role_binding_id, scope_id)
      select v_org, v_id, s.id
        from jsonb_array_elements_text(coalesce(v_b->'scope_ids', '[]'::jsonb)) as t(sid)
        join public.authorization_scopes s on s.id = t.sid::uuid and s.organization_id = v_org;

      if not exists (select 1 from public.role_binding_scopes x where x.role_binding_id = v_id) then
        raise exception 'Vai trò phải kèm ít nhất một phạm vi (toàn tổ chức, khu vực hoặc toà nhà).'
          using errcode = '22023';
      end if;
      v_n_bind := v_n_bind + 1;
    end loop;
  end if;

  -- ---- Lớp NGOẠI LỆ ----
  if p_overrides is not null then
    -- Thu hồi bằng revoked_at, KHÔNG xoá dòng: giữ dấu vết ai từng được cấp gì.
    update public.member_permission_overrides
       set revoked_at = now()
     where membership_id = p_membership and revoked_at is null;

    for v_o in select * from jsonb_array_elements(p_overrides) loop
      if nullif(btrim(coalesce(v_o->>'reason','')), '') is null then
        raise exception 'Ngoại lệ "%": phải ghi lý do.', v_o->>'permission_key'
          using errcode = '22023';
      end if;
      if not exists (select 1 from public.permission_definitions pd
                      where pd.key = v_o->>'permission_key' and pd.is_active
                        and pd.permission_domain = 'TENANT') then
        raise exception 'Quyền "%" không tồn tại hoặc không dùng được.', v_o->>'permission_key'
          using errcode = '22023';
      end if;

      v_id := gen_random_uuid();
      insert into public.member_permission_overrides
        (id, organization_id, membership_id, permission_key, effect, reason,
         expires_at, created_by, created_at, scope_mode)
      values (v_id, v_org, p_membership, v_o->>'permission_key',
              upper(coalesce(v_o->>'effect','ALLOW')), btrim(v_o->>'reason'),
              nullif(v_o->>'expires_at','')::timestamptz, v_actor, now(),
              upper(coalesce(v_o->>'scope_mode','ORGANIZATION')));

      insert into public.member_override_scopes (organization_id, override_id, scope_id)
      select v_org, v_id, s.id
        from jsonb_array_elements_text(coalesce(v_o->'scope_ids','[]'::jsonb)) as t(sid)
        join public.authorization_scopes s on s.id = t.sid::uuid and s.organization_id = v_org;

      -- Kiểm hình dạng ở ĐÂY để báo lỗi tiếng Việt, thay vì để ràng buộc ném lỗi
      -- thô lúc COMMIT (lúc đó người dùng chỉ thấy mã 23514 khó hiểu).
      if upper(coalesce(v_o->>'scope_mode','ORGANIZATION')) = 'ORGANIZATION' then
        if (select count(*) from public.member_override_scopes x
             join public.authorization_scopes s2 on s2.id = x.scope_id
            where x.override_id = v_id and s2.scope_type = 'ORGANIZATION') <> 1
           or (select count(*) from public.member_override_scopes x where x.override_id = v_id) <> 1 then
          raise exception 'Ngoại lệ "%" áp cho toàn tổ chức thì chỉ được chọn đúng phạm vi "toàn tổ chức".',
            v_o->>'permission_key' using errcode = '22023';
        end if;
      else
        if (select count(*) from public.member_override_scopes x where x.override_id = v_id) = 0 then
          raise exception 'Ngoại lệ "%" phải chọn ít nhất một toà nhà, khu vực hoặc sổ quỹ.',
            v_o->>'permission_key' using errcode = '22023';
        end if;
        if exists (select 1 from public.member_override_scopes x
                    join public.authorization_scopes s2 on s2.id = x.scope_id
                   where x.override_id = v_id and s2.scope_type = 'ORGANIZATION') then
          raise exception 'Ngoại lệ "%" theo phạm vi hẹp thì không được chọn "toàn tổ chức".',
            v_o->>'permission_key' using errcode = '22023';
        end if;
      end if;
      v_n_ov := v_n_ov + 1;
    end loop;
  end if;

  update public.organization_memberships
     set version = version + 1
   where id = p_membership;

  -- Ảnh chụp quyền SAU.
  v_sau := app_private.allowed_keys_for_membership_v3(p_membership);

  select coalesce(array_agg(k order by k), '{}'::text[]) into v_them
    from (select unnest(v_sau) except select unnest(v_truoc)) t(k);
  select coalesce(array_agg(k order by k), '{}'::text[]) into v_mat
    from (select unnest(v_truoc) except select unnest(v_sau)) t(k);

  perform app_private.append_authz_audit_v1(
    v_org, 'MEMBER_AUTHORIZATION_UPDATED', 'organization_membership', p_membership,
    jsonb_build_object('permissions', to_jsonb(v_truoc), 'version', v_ver),
    jsonb_build_object('permissions', to_jsonb(v_sau), 'version', v_ver + 1,
                       'role_bindings', v_n_bind, 'overrides', v_n_ov),
    v_reason);

  return jsonb_build_object(
    'membershipId', p_membership, 'version', v_ver + 1,
    'roleBindings', v_n_bind, 'overrides', v_n_ov,
    'permissionsBefore', coalesce(array_length(v_truoc, 1), 0),
    'permissionsAfter', coalesce(array_length(v_sau, 1), 0),
    'gained', to_jsonb(v_them), 'lost', to_jsonb(v_mat));
end
$$;








--
-- Name: update_meter_reading_v1(uuid, numeric, date, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_meter_reading_v1(p_id uuid, p_current_reading numeric DEFAULT NULL::numeric, p_reading_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_meter_image_url text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.meter_readings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_r RECORD;
  v_row public.meter_readings;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Chưa đăng nhập' USING ERRCODE='42501'; END IF;

  SELECT id, building_id, organization_id, updated_at INTO v_r
  FROM public.meter_readings WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy chỉ số' USING ERRCODE='42501'; END IF;
  IF v_r.building_id IS NULL THEN RAISE EXCEPTION 'Chỉ số chưa gắn toà nhà'; END IF;

  IF NOT (v_r.organization_id IS NULL
          OR public.is_super_admin()
          OR v_r.organization_id = ANY(public.my_org_ids())) THEN
    RAISE EXCEPTION 'Chỉ số thuộc tổ chức khác' USING ERRCODE='42501';
  END IF;
  IF NOT public.can_do_on_building('meter_readings','edit', v_r.building_id) THEN
    RAISE EXCEPTION 'Không có quyền sửa chỉ số cho toà này' USING ERRCODE='42501';
  END IF;
  -- LƯU Ý: KHÔNG chặn edit khi APPROVED — giữ parity với đường cũ (form hiện sửa
  -- được chỉ số đã duyệt; chỉ số mới luôn tạo APPROVED). Chặn sẽ là đổi hành vi.
  -- Quyền đã được can_do_on_building enforce; đây không phải chứng từ tiền như invoice.
  IF p_expected_updated_at IS NOT NULL AND v_r.updated_at <> p_expected_updated_at THEN
    RAISE EXCEPTION 'Chỉ số đã bị thay đổi bởi người khác (version mismatch)' USING ERRCODE='40001';
  END IF;
  IF p_current_reading IS NOT NULL AND p_current_reading < 0 THEN
    RAISE EXCEPTION 'Chỉ số không hợp lệ';
  END IF;

  BEGIN
    UPDATE public.meter_readings SET
      current_reading = COALESCE(p_current_reading, current_reading),
      reading_date    = COALESCE(p_reading_date, reading_date),
      notes           = COALESCE(p_notes, notes),
      meter_image_url = COALESCE(p_meter_image_url, meter_image_url)
    WHERE id = p_id AND deleted_at IS NULL
    RETURNING * INTO v_row;
  EXCEPTION WHEN check_violation THEN
    RAISE EXCEPTION 'Chỉ số mới không hợp lệ (phải ≥ chỉ số kỳ trước)' USING ERRCODE='23514';
  END;

  RETURN v_row;
END;
$$;








--
-- Name: update_organization_profile_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_organization_profile_v1(p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_org  uuid := app_private.current_admin_org_v1();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_cu   text;
begin
  if v_org is null then
    raise exception 'Bạn không có quyền sửa thông tin tổ chức.' using errcode = '42501';
  end if;
  perform app_private.require_perm_v1(v_org, 'settings.edit', 'sửa thông tin tổ chức');
  if v_name is null then
    raise exception 'Tên tổ chức không được để trống.' using errcode = '22023';
  end if;
  if length(v_name) > 200 then
    raise exception 'Tên tổ chức tối đa 200 ký tự.' using errcode = '22023';
  end if;

  select name into v_cu from public.organizations where id = v_org;
  update public.organizations set name = v_name, updated_at = now() where id = v_org;

  perform app_private.append_authz_audit_v1(
    v_org, 'ORGANIZATION_UPDATED', 'organization', v_org,
    jsonb_build_object('name', v_cu), jsonb_build_object('name', v_name), null);

  return jsonb_build_object('organizationId', v_org, 'name', v_name);
end
$$;








--
-- Name: update_period_fee(uuid, uuid, jsonb, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_period_fee(p_voucher_id uuid, p_account_id uuid DEFAULT NULL::uuid, p_attachments jsonb DEFAULT NULL::jsonb, p_amount numeric DEFAULT NULL::numeric, p_period_start text DEFAULT NULL::text, p_period_end text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_bld      uuid;
  v_owner    uuid;
  v_del      timestamptz;
  v_creator  uuid;
  v_cur_acc  uuid;
  v_is_admin boolean;
  v_can_edit boolean;
  v_acc      uuid;
  v_items    int;
  v_ps       date;
  v_pe       date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;

  SELECT ie.building_id, ie.deleted_at, ie.user_id, ie.account_id
    INTO v_bld, v_del, v_creator, v_cur_acc
    FROM income_expenses ie
   WHERE ie.id = p_voucher_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002'; END IF;
  IF v_del IS NOT NULL THEN RAISE EXCEPTION 'Phiếu đã bị hủy'; END IF;

  SELECT b.user_id INTO v_owner FROM buildings b WHERE b.id = v_bld;

  v_is_admin := public.is_admin() OR public.is_super_admin() OR v_owner = auth.uid();
  v_can_edit := v_is_admin
                OR v_creator = auth.uid()
                OR (v_bld IS NOT NULL AND public.can_do_on_building('income_expenses', 'edit', v_bld));
  IF NOT v_can_edit THEN
    RAISE EXCEPTION 'Bạn không có quyền sửa phiếu này' USING ERRCODE = '42501';
  END IF;

  IF p_account_id IS NOT NULL THEN
    IF NOT v_is_admin AND v_cur_acc IS NOT NULL THEN
      RAISE EXCEPTION 'Chỉ được gán sổ quỹ khi phiếu chưa có sổ' USING ERRCODE = '42501';
    END IF;
    SELECT id INTO v_acc FROM accounts
     WHERE id = p_account_id AND deleted_at IS NULL
       AND (user_id = auth.uid() OR v_is_admin);
    IF v_acc IS NULL THEN
      RAISE EXCEPTION 'Sổ quỹ không hợp lệ hoặc bạn không có quyền ghi chi vào sổ này' USING ERRCODE = '42501';
    END IF;
    UPDATE income_expenses SET account_id = v_acc WHERE id = p_voucher_id;
  END IF;

  IF p_attachments IS NOT NULL THEN
    UPDATE income_expenses SET attachments = p_attachments WHERE id = p_voucher_id;
  END IF;

  IF v_is_admin THEN
    IF p_notes IS NOT NULL THEN
      UPDATE income_expenses SET notes = p_notes WHERE id = p_voucher_id;
    END IF;

    IF (p_amount IS NOT NULL AND p_amount > 0)
       OR (p_period_start ~ '^\d{4}-\d{2}$' AND p_period_end ~ '^\d{4}-\d{2}$') THEN
      SELECT count(*) INTO v_items FROM income_expense_items WHERE income_expense_id = p_voucher_id;
      IF v_items > 1 THEN
        RAISE EXCEPTION 'Phiếu có nhiều dòng hạng mục — sửa số tiền/kỳ ở trang Thu chi';
      END IF;
    END IF;

    IF p_amount IS NOT NULL AND p_amount > 0 THEN
      UPDATE income_expense_items
         SET unit_price = p_amount, quantity = 1
       WHERE income_expense_id = p_voucher_id;
    END IF;
    IF p_period_start ~ '^\d{4}-\d{2}$' AND p_period_end ~ '^\d{4}-\d{2}$'
       AND p_period_start <= p_period_end THEN
      v_ps := to_date(p_period_start || '-01', 'YYYY-MM-DD');
      v_pe := (date_trunc('month', to_date(p_period_end || '-01', 'YYYY-MM-DD')) + interval '1 month - 1 day')::date;
      UPDATE income_expense_items
         SET start_date = v_ps, end_date = v_pe
       WHERE income_expense_id = p_voucher_id;
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'voucher_id', p_voucher_id);
END;
$_$;








--
-- Name: update_room_status_on_contract_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_room_status_on_contract_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- INSERT: HĐ mới đang hiệu lực → phòng OCCUPIED
  IF TG_OP = 'INSERT' AND NEW.status IN ('ACTIVE','EXTENDED') THEN
    IF NEW.room_id IS NOT NULL THEN
      UPDATE rooms SET status = 'OCCUPIED', updated_at = NOW() WHERE id = NEW.room_id;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    -- Rời active-set → phòng AVAILABLE nếu không còn HĐ đang hiệu lực khác
    IF OLD.status IN ('ACTIVE','EXTENDED') AND NEW.status NOT IN ('ACTIVE','EXTENDED') THEN
      IF NEW.room_id IS NOT NULL THEN
        UPDATE rooms SET status = 'AVAILABLE', updated_at = NOW()
        WHERE id = NEW.room_id
          AND NOT EXISTS (
            SELECT 1 FROM contracts
            WHERE room_id = NEW.room_id
              AND deleted_at IS NULL
              AND status IN ('ACTIVE','EXTENDED')
              AND id <> NEW.id
          );
      END IF;
    END IF;

    -- Vào active-set → phòng OCCUPIED
    IF OLD.status NOT IN ('ACTIVE','EXTENDED') AND NEW.status IN ('ACTIVE','EXTENDED') THEN
      IF NEW.room_id IS NOT NULL THEN
        UPDATE rooms SET status = 'OCCUPIED', updated_at = NOW() WHERE id = NEW.room_id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;








--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;








--
-- Name: upsert_building_fee_account(uuid, text, text, text, numeric, uuid, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_building_fee_account(p_building_id uuid, p_fee_category text, p_provider_code text DEFAULT NULL::text, p_account_holder text DEFAULT NULL::text, p_default_amount numeric DEFAULT NULL::numeric, p_default_account_id uuid DEFAULT NULL::uuid, p_not_applicable boolean DEFAULT NULL::boolean, p_clear_amount boolean DEFAULT false, p_clear_provider boolean DEFAULT false, p_clear_account boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_id    uuid;
  v_na    boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_fee_category NOT IN ('tien_nha','dien','nuoc','internet','quan_ly','ve_sinh','cong_an','rac','thang_may') THEN
    RAISE EXCEPTION 'Hạng mục phí không hợp lệ: %', p_fee_category;
  END IF;
  IF p_default_amount IS NOT NULL AND p_default_amount < 0 THEN
    RAISE EXCEPTION 'Giá mặc định không được âm' USING ERRCODE = '22023';
  END IF;

  SELECT b.user_id INTO v_owner FROM buildings b
   WHERE b.id = p_building_id AND b.deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà'; END IF;
  IF NOT (public.can_access_building(p_building_id)
          OR public.ie_all_buildings_scope(p_building_id)
          OR v_owner = auth.uid()
          OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền cấu hình toà này' USING ERRCODE = '42501';
  END IF;

  -- Cờ "Không áp dụng" — NGUỒN DUY NHẤT là buildings.hidden_fixed_expenses.
  -- Làm TRƯỚC phần upsert để giá trị cuối cùng của nó dùng được ngay bên dưới
  -- khi đồng bộ cột không_áp_dụng của chính dòng cấu hình.
  IF p_not_applicable IS TRUE THEN
    UPDATE buildings
       SET hidden_fixed_expenses = (
         SELECT array(SELECT DISTINCT k FROM unnest(COALESCE(hidden_fixed_expenses,'{}') || ARRAY[p_fee_category]) k))
     WHERE id = p_building_id;
  ELSIF p_not_applicable IS FALSE THEN
    UPDATE buildings
       SET hidden_fixed_expenses = array_remove(COALESCE(hidden_fixed_expenses,'{}'), p_fee_category)
     WHERE id = p_building_id;
  END IF;

  SELECT p_fee_category = ANY(COALESCE(b.hidden_fixed_expenses,'{}'))
    INTO v_na
    FROM buildings b WHERE b.id = p_building_id;

  INSERT INTO building_fee_accounts
    (building_id, fee_category, provider_code, account_holder,
     default_amount, default_account_id, not_applicable, user_id)
  VALUES
    (p_building_id, p_fee_category,
     CASE WHEN p_clear_provider THEN NULL ELSE NULLIF(btrim(p_provider_code), '') END,
     CASE WHEN p_clear_provider THEN NULL ELSE NULLIF(btrim(p_account_holder), '') END,
     CASE WHEN p_clear_amount   THEN NULL ELSE p_default_amount END,
     CASE WHEN p_clear_account  THEN NULL ELSE p_default_account_id END,
     COALESCE(v_na, false), v_owner)
  ON CONFLICT (building_id, fee_category) WHERE deleted_at IS NULL
  DO UPDATE SET
    -- Mỗi cột: cờ xoá thắng → NULL; không thì giữ nguyên nghĩa cũ
    -- (giá trị mới nếu có, ngược lại giữ giá trị đang có).
    provider_code = CASE WHEN p_clear_provider THEN NULL
                         ELSE COALESCE(NULLIF(btrim(EXCLUDED.provider_code), ''),
                                       building_fee_accounts.provider_code) END,
    account_holder = CASE WHEN p_clear_provider THEN NULL
                          ELSE COALESCE(NULLIF(btrim(EXCLUDED.account_holder), ''),
                                        building_fee_accounts.account_holder) END,
    default_amount = CASE WHEN p_clear_amount THEN NULL
                          ELSE COALESCE(EXCLUDED.default_amount,
                                        building_fee_accounts.default_amount) END,
    default_account_id = CASE WHEN p_clear_account THEN NULL
                              ELSE COALESCE(building_fee_accounts.default_account_id,
                                            EXCLUDED.default_account_id) END,
    -- Luôn kéo về khớp nguồn duy nhất, kể cả khi caller không truyền cờ.
    not_applicable = COALESCE(v_na, false),
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;








--
-- Name: FUNCTION upsert_building_fee_account(p_building_id uuid, p_fee_category text, p_provider_code text, p_account_holder text, p_default_amount numeric, p_default_account_id uuid, p_not_applicable boolean, p_clear_amount boolean, p_clear_provider boolean, p_clear_account boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_building_fee_account(p_building_id uuid, p_fee_category text, p_provider_code text, p_account_holder text, p_default_amount numeric, p_default_account_id uuid, p_not_applicable boolean, p_clear_amount boolean, p_clear_provider boolean, p_clear_account boolean) IS 'Khai/sửa cấu hình phí cố định của (toà × hạng mục). Tham số giá trị giữ nghĩa "NULL = giữ nguyên" để pay_period_fee học cấu hình mà không xoá cột nó không truyền; muốn XOÁ thì dùng p_clear_amount / p_clear_provider / p_clear_account (cờ xoá thắng giá trị truyền kèm). Cờ "Không áp dụng" ghi vào buildings.hidden_fixed_expenses (nguồn duy nhất) và luôn được đồng bộ xuống cột building_fee_accounts.not_applicable — trước 30/07/2026 cột đó không ai ghi (0/109 dòng true) nên giao diện hiện sai "đang áp dụng" cho ô đã tắt.';








--
-- Name: upsert_building_utility_account(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_building_utility_account(p_building_id uuid, p_utility_type text, p_provider_code text DEFAULT NULL::text, p_account_holder text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_utility_type NOT IN ('ELECTRIC','WATER') THEN
    RAISE EXCEPTION 'Loại tiện ích không hợp lệ';
  END IF;

  SELECT b.user_id INTO v_owner FROM buildings b
   WHERE b.id = p_building_id AND b.deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà'; END IF;
  IF NOT (public.can_access_building(p_building_id)
          OR public.ie_all_buildings_scope(p_building_id)
          OR v_owner = auth.uid()
          OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Bạn không có quyền thao tác trên toà này' USING ERRCODE = '42501';
  END IF;

  INSERT INTO building_utility_accounts
    (building_id, utility_type, provider_code, account_holder, user_id)
  VALUES
    (p_building_id, p_utility_type,
     NULLIF(btrim(p_provider_code), ''), NULLIF(btrim(p_account_holder), ''), v_owner)
  ON CONFLICT (building_id, utility_type) WHERE deleted_at IS NULL
  DO UPDATE SET
    provider_code  = COALESCE(NULLIF(btrim(EXCLUDED.provider_code), ''),  building_utility_accounts.provider_code),
    account_holder = COALESCE(NULLIF(btrim(EXCLUDED.account_holder), ''), building_utility_accounts.account_holder),
    updated_at = now();

  RETURN jsonb_build_object('ok', true);
END;
$$;








--
-- Name: upsert_organization_role_v1(uuid, text, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_organization_role_v1(p_role_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_permissions jsonb DEFAULT NULL::jsonb, p_expected_version bigint DEFAULT NULL::bigint, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_org   uuid;
  v_id    uuid := p_role_id;
  v_row   public.organization_roles%rowtype;
  v_name  text := nullif(btrim(coalesce(p_name, '')), '');
  v_tao   boolean := (p_role_id is null);
  v_xau   text;
  v_nguoi int;
  v_cu    jsonb;
begin
  if v_actor is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;

  if v_tao then
    -- Tổ chức của người tạo (thứ tự ổn định vì không có UNIQUE(org,user)).
    select m.organization_id into v_org
      from public.organization_memberships m
      join public.organizations o on o.id = m.organization_id and o.status = 'ACTIVE'
     where m.user_id = v_actor and m.status = 'ACTIVE'
     order by coalesce(o.is_demo,false), m.organization_id limit 1;
    if v_org is null then
      raise exception 'Bạn không thuộc tổ chức nào đang hoạt động.' using errcode = '42501';
    end if;
    if v_name is null then
      raise exception 'Hãy đặt tên cho vai trò.' using errcode = '22023';
    end if;
    if p_permissions is null then
      raise exception 'Vai trò mới phải chọn ít nhất một quyền (hoặc gửi danh sách rỗng nếu cố ý).'
        using errcode = '22023';
    end if;
  else
    select * into v_row from public.organization_roles where id = p_role_id;
    if not found then
      raise exception 'Không tìm thấy vai trò này.' using errcode = 'P0002';
    end if;
    v_org := v_row.organization_id;
  end if;

  perform app_private.require_perm_v1(v_org, 'users.edit', 'quản lý mẫu vai trò');

  if not v_tao then
    select * into v_row from public.organization_roles where id = p_role_id for update;
    if v_row.is_system then
      raise exception 'Vai trò hệ thống "%" không sửa được. Hãy nhân bản rồi sửa bản sao.', v_row.name
        using errcode = '42501';
    end if;
    if p_expected_version is null or v_row.version <> p_expected_version then
      raise exception 'Có người vừa đổi vai trò này. Hãy tải lại trang.' using errcode = '40001';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('permission_key', rp.permission_key, 'effect', rp.effect)
                              order by rp.permission_key), '[]'::jsonb)
      into v_cu from public.role_permissions rp where rp.role_id = p_role_id;
  end if;

  -- Kiểm khoá quyền TRƯỚC khi ghi, để báo lỗi rõ thay vì để FK/trigger ném lỗi thô.
  if p_permissions is not null then
    select string_agg(x.k, ', ') into v_xau
      from (select e->>'permission_key' as k from jsonb_array_elements(p_permissions) e) x
     where not exists (select 1 from public.permission_definitions pd
                        where pd.key = x.k and pd.is_active and pd.permission_domain = 'TENANT');
    if v_xau is not null then
      raise exception 'Các quyền sau không dùng được: %', v_xau using errcode = '22023';
    end if;
  end if;

  if v_tao then
    v_id := gen_random_uuid();
    insert into public.organization_roles (id, organization_id, name, is_system, version, created_at, status)
    values (v_id, v_org, v_name, false, 1, now(), 'ACTIVE');
  else
    update public.organization_roles
       set name = coalesce(v_name, name), version = version + 1
     where id = v_id;
  end if;

  if p_permissions is not null then
    delete from public.role_permissions where role_id = v_id;
    insert into public.role_permissions (organization_id, role_id, permission_key, effect)
    select distinct v_org, v_id, e->>'permission_key', upper(coalesce(e->>'effect','ALLOW'))
      from jsonb_array_elements(p_permissions) e;
  end if;

  select count(distinct rb.membership_id) into v_nguoi
    from public.role_bindings rb where rb.role_id = v_id and rb.valid_to is null;

  perform app_private.append_authz_audit_v1(
    v_org, case when v_tao then 'ROLE_CREATED' else 'ROLE_UPDATED' end,
    'organization_role', v_id, v_cu,
    jsonb_build_object('name', coalesce(v_name, v_row.name), 'permissions', p_permissions,
                       'affected_members', v_nguoi),
    nullif(btrim(coalesce(p_reason,'')), ''));

  return jsonb_build_object('roleId', v_id, 'created', v_tao,
    'version', (select version from public.organization_roles where id = v_id),
    'permissions', coalesce(jsonb_array_length(p_permissions), 0),
    'affectedMembers', v_nguoi);
end
$$;








--
-- Name: upsert_room_pass_listing(uuid, uuid, text, text, text, numeric, boolean, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_room_pass_listing(p_id uuid, p_room_id uuid, p_contact_name text, p_contact_phone text, p_sale_policy text, p_pass_price numeric, p_active boolean, p_avail_date date DEFAULT NULL::date, p_contact_manager boolean DEFAULT false) RETURNS public.room_pass_listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner    uuid;
  v_building uuid;
  v_row      public.room_pass_listings;
BEGIN
  SELECT r.building_id, b.user_id
    INTO v_building, v_owner
  FROM public.rooms r
  JOIN public.buildings b ON b.id = r.building_id
  WHERE r.id = p_room_id AND r.deleted_at IS NULL AND b.deleted_at IS NULL;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Phòng không tồn tại hoặc đã xoá';
  END IF;

  IF NOT public.can_manage_pass_listing(v_building, v_owner) THEN
    RAISE EXCEPTION 'Không có quyền quản lý phòng khách nhờ sale cho tòa này';
  END IF;

  IF p_id IS NULL THEN
    SELECT id INTO p_id FROM public.room_pass_listings
    WHERE room_id = p_room_id AND active LIMIT 1;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.room_pass_listings (
      user_id, building_id, room_id, contact_name, contact_phone,
      sale_policy, pass_price, avail_date, contact_manager, active, created_by
    ) VALUES (
      v_owner, v_building, p_room_id, p_contact_name, p_contact_phone,
      p_sale_policy, p_pass_price, p_avail_date, COALESCE(p_contact_manager, false),
      COALESCE(p_active, true), auth.uid()
    )
    RETURNING * INTO v_row;
  ELSE
    UPDATE public.room_pass_listings SET
      user_id         = v_owner,
      building_id     = v_building,
      room_id         = p_room_id,
      contact_name    = p_contact_name,
      contact_phone   = p_contact_phone,
      sale_policy     = p_sale_policy,
      pass_price      = p_pass_price,
      avail_date      = p_avail_date,
      contact_manager = COALESCE(p_contact_manager, false),
      active          = COALESCE(p_active, active),
      updated_at      = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END;
$$;








--
-- Name: v5_appeal(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_appeal(p_date date, p_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  UPDATE public.salary_attendance_day SET
    audit = audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', v_uid, 'action', 'appeal', 'text', p_text)),
    updated_at = now()
  WHERE user_id = v_uid AND work_date = p_date AND status = 'flagged';
  IF NOT FOUND THEN RAISE EXCEPTION 'Không có nghi án đang mở ở ngày này'; END IF;
  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES ((SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1),
    'CUSTOM','IN_APP','PENDING','Kháng nghị nghi án',
    (SELECT COALESCE(full_name,'Nhân viên') FROM public.profiles WHERE id = v_uid) || ' phản hồi ngày ' || to_char(p_date,'DD/MM') || ': ' || p_text,
    jsonb_build_object('v5','appeal','staff_id', v_uid, 'date', p_date));
  RETURN jsonb_build_object('appealed', true);
END; $$;








--
-- Name: v5_apply_lock_adjustments(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_apply_lock_adjustments(p_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month DATE := date_trunc('month', p_month)::date;
  v_cfg JSONB := public.get_salary_v5_config();
  v_owner UUID := (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1);
  v_row RECORD; v_m JSONB; v_sm UUID;
  v_n INT := 0;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ được chốt tiền v5'; END IF;
  -- ASSERT CẤM ghi tiền trong shadow (US-6.1): chỉ khi flag v5_money = true
  IF NOT COALESCE((v_cfg->'system_v5'->'feature_flags'->>'v5_money')::boolean, false) THEN
    RAISE EXCEPTION 'v5_money đang TẮT (shadow) — không được ghi tiền v5 vào lương';
  END IF;

  FOR v_row IN SELECT * FROM public.v5_lock_assert(v_month) LOOP
    IF NOT v_row.all_ok THEN
      RAISE EXCEPTION 'CHẶN LOCK: % chưa qua đủ 3 ASSERT (caps=%, flags=%, payment_join=%)',
        v_row.staff_name, v_row.a1_caps_ok, v_row.a2_no_open_flags, v_row.a3_payment_join_ok;
    END IF;
  END LOOP;

  FOR v_row IN SELECT * FROM public.v5_lock_assert(v_month) LOOP
    -- đảm bảo salary_monthly (DRAFT) tồn tại
    SELECT id INTO v_sm FROM public.salary_monthly WHERE staff_id = v_row.staff_id AND period_month = v_month;
    IF v_sm IS NULL THEN
      INSERT INTO public.salary_monthly (user_id, staff_id, period_month, status)
      VALUES (v_owner, v_row.staff_id, v_month, 'DRAFT') RETURNING id INTO v_sm;
    END IF;
    -- idempotent: xoá dòng v5 cũ của kỳ rồi ghi lại
    DELETE FROM public.salary_adjustments WHERE salary_monthly_id = v_sm AND source IN ('ATTEND_V5','STREAK_V5');
    IF v_row.attend_amount > 0 THEN
      INSERT INTO public.salary_adjustments (salary_monthly_id, user_id, kind, label, amount, source)
      VALUES (v_sm, v_owner, 'BONUS', 'Chuyên cần v5 (' || v_row.ticked_days || '/' || v_row.n_chuan || ' ngày công)', v_row.attend_amount, 'ATTEND_V5');
    END IF;
    IF v_row.streak_amount > 0 THEN
      INSERT INTO public.salary_adjustments (salary_monthly_id, user_id, kind, label, amount, source)
      VALUES (v_sm, v_owner, 'BONUS', 'Thưởng chuỗi v5 (mốc đã khoá)', v_row.streak_amount, 'STREAK_V5');
    END IF;
    v_n := v_n + 1;
  END LOOP;
  RETURN jsonb_build_object('month', v_month, 'staff_applied', v_n);
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, error_text, payload)
  VALUES (auth.uid(), 'v5_apply_lock_adjustments', SQLERRM, jsonb_build_object('month', p_month));
  RAISE;
END; $$;








--
-- Name: v5_building_reqs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_building_reqs(p_building uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg JSONB := public.get_salary_v5_config();
  v_rooms INT;
  v_idx INT;
  v_breaks JSONB := v_cfg->'coverage_v5'->'size_breaks';
BEGIN
  SELECT COUNT(*) INTO v_rooms FROM public.rooms WHERE building_id = p_building;
  v_idx := CASE WHEN v_rooms <= (v_breaks->>0)::int THEN 0
                WHEN v_rooms <= (v_breaks->>1)::int THEN 1
                ELSE 2 END;
  RETURN jsonb_build_object(
    'rooms', v_rooms, 'size_idx', v_idx,
    'photos_min', (v_cfg->'coverage_v5'->'photos_min'->>v_idx)::int,
    -- Lời hứa với nhân viên: tối đa 15 phút tại toà kể từ lúc bấm Kiểm tra
    'dwell_min_seconds', LEAST(((v_cfg->'coverage_v5'->'dwell_min_minutes'->>v_idx)::numeric * 60)::int, 900)
  );
END; $$;








--
-- Name: v5_checklist_for_building(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_checklist_for_building(p_building uuid, p_date date, p_type text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vacant INT;
  v_seed BIGINT;
  v_pool TEXT[] := ARRAY['san_thuong','may_bom','khu_rac','hanh_lang_khac'];
  v_rand TEXT;
  v_rand_label TEXT;
  v_floor_candidates INT[];
  v_floor INT;
  v_items JSONB;
BEGIN
  IF p_type = 'QUICK' THEN
    RETURN jsonb_build_array(
      jsonb_build_object('key','pccc','label','PCCC — bình + lối thoát','required',true,'done',false),
      jsonb_build_object('key','tu_dien','label','Tủ điện tổng','required',true,'done',false)
    );
  END IF;

  SELECT COUNT(*) FILTER (WHERE r.status = 'AVAILABLE')
  INTO v_vacant
  FROM public.rooms r
  WHERE r.building_id = p_building
    AND r.deleted_at IS NULL;

  SELECT array_agg(floor_number ORDER BY floor_number)
  INTO v_floor_candidates
  FROM (
    SELECT DISTINCT r.floor AS floor_number
    FROM public.rooms r
    WHERE r.building_id = p_building
      AND r.deleted_at IS NULL
      AND r.floor > 0
    UNION
    SELECT DISTINCT f.floor_number
    FROM public.floors f
    WHERE f.building_id = p_building
      AND COALESCE(f.status, 'active') = 'active'
      AND f.floor_number > 0
  ) actual_floors;

  v_seed := ('x' || substr(md5(p_building::text || p_date::text), 1, 8))::bit(32)::bigint;
  v_rand := v_pool[1 + (v_seed % cardinality(v_pool))::int];
  v_rand_label := CASE v_rand
    WHEN 'san_thuong' THEN 'Sân thượng / mái'
    WHEN 'may_bom' THEN 'Máy bơm và khu kỹ thuật nước'
    WHEN 'khu_rac' THEN 'Khu rác và vệ sinh chung'
    ELSE 'Một hành lang khác'
  END;
  IF cardinality(v_floor_candidates) > 0 THEN
    v_floor := v_floor_candidates[
      1 + ((v_seed / 7) % cardinality(v_floor_candidates))::int
    ];
  END IF;

  v_items := jsonb_build_array(
    jsonb_build_object('key','tu_dien','label','Tủ điện tổng / CB','required',true,'done',false),
    jsonb_build_object('key','pccc','label','PCCC — bình (tem/kim) + lối thoát','required',true,'done',false)
  );

  v_items := v_items || jsonb_build_array(
    CASE
      WHEN v_floor IS NULL THEN
        jsonb_build_object('key','hanh_lang','label','Hành lang / lối đi chung','required',true,'done',false)
      ELSE
        jsonb_build_object('key','hanh_lang','label','Hành lang tầng ' || v_floor,'required',true,'done',false,'floor',v_floor)
    END,
    jsonb_build_object('key','nuoc','label','Nước — bơm/bồn/đồng hồ tổng','required',true,'done',false),
    jsonb_build_object('key','random_' || v_rand,'label','Mục sâu hôm nay: ' || v_rand_label,'required',true,'done',false,'random',true)
  );

  IF v_vacant > 0 THEN
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key','phong_trong',
      'label','PHÒNG TRỐNG — mở cửa vào trong (' || v_vacant || ' phòng đang chào)',
      'required',true,
      'done',false
    ));
  END IF;

  RETURN v_items;
END;
$$;








--
-- Name: v5_close_period(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_close_period(p_new_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev DATE := (date_trunc('month', p_new_month) - INTERVAL '1 month')::date;
  v_new DATE := date_trunc('month', p_new_month)::date;
  v_cfg JSONB;
  v_owner UUID := (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1);
  v_rules JSONB;
  v_pending JSONB;
  v_staff RECORD;
  v_sss public.salary_streak_state;
  v_n INT; v_miles JSONB; v_fm JSONB;
  v_earn INT; v_reserve INT;
  v_processed INT := 0;
BEGIN
  PERFORM public.v5_expire_stale(v_new);

  -- vật chất hoá pending money patch (đọc-hiệu-lực đã áp; đây là bước ghi cứng)
  SELECT rules INTO v_rules FROM public.salary_bonus_rules WHERE user_id = v_owner FOR UPDATE;
  v_pending := v_rules->'system_v5'->'pending_money_patch';
  IF v_pending IS NOT NULL AND jsonb_typeof(v_pending) = 'object'
     AND (v_pending->>'effective_month')::date <= v_new THEN
    v_rules := v_rules || COALESCE(v_pending->'patch', '{}'::jsonb);
    v_rules := jsonb_set(v_rules, '{system_v5,pending_money_patch}', 'null'::jsonb);
    UPDATE public.salary_bonus_rules SET rules = v_rules, updated_at = now() WHERE user_id = v_owner;
  END IF;
  v_cfg := public.get_salary_v5_config();

  FOR v_staff IN SELECT DISTINCT staff_id FROM public.staff_assignments WHERE building_id IS NOT NULL LOOP
    -- chốt tháng cũ
    PERFORM public.v5_recompute_streak(v_staff.staff_id, v_prev);
    SELECT * INTO v_sss FROM public.salary_streak_state WHERE user_id = v_staff.staff_id AND period_month = v_prev;
    IF FOUND THEN
      v_n := public.v5_n_chuan(v_prev, v_staff.staff_id);
      v_miles := public.public_v5_effective_milestones(v_cfg->'streak_v5'->'milestones', v_cfg->'streak_v5'->'deltas', v_n);
      SELECT m INTO v_fm FROM jsonb_array_elements(v_miles) m WHERE m->>'milestone' = 'full_month';
      -- TRỌN THÁNG: đứt-không-phép = 0 (khiên cứu vẫn tính là lỡ — phải sạch tuyệt đối)
      IF v_sss.breaks_no_leave = 0 AND v_fm IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_sss.milestones_banked) b WHERE b->>'milestone' = 'full_month') THEN
        UPDATE public.salary_streak_state
        SET milestones_banked = milestones_banked || jsonb_build_array(jsonb_build_object(
              'milestone','full_month','delta',(v_fm->>'delta')::numeric,'banked_at', now())),
            updated_at = now()
        WHERE user_id = v_staff.staff_id AND period_month = v_prev;
      END IF;
      -- khiên dự trữ tháng mới: carry + earn (đứt-không-phép ≤ 1 → +1), cap tồn
      v_earn := CASE WHEN v_sss.breaks_no_leave <= COALESCE((v_cfg->'streak_v5'->'shield_earn'->>'max_breaks_no_leave')::int,1)
                     THEN COALESCE((v_cfg->'streak_v5'->'shield_earn'->>'gain')::int,1) ELSE 0 END;
      v_reserve := LEAST(COALESCE((v_cfg->'streak_v5'->>'reserve_cap')::int,2),
                         GREATEST(v_sss.shields_reserve - v_sss.shields_reserve_used, 0) + v_earn);
    ELSE
      v_reserve := 0;
    END IF;
    INSERT INTO public.salary_streak_state (user_id, period_month, shields_free_left, shields_reserve)
    VALUES (v_staff.staff_id, v_new, COALESCE((v_cfg->'streak_v5'->>'shields_free')::int,3), v_reserve)
    ON CONFLICT (user_id, period_month) DO UPDATE SET shields_reserve = EXCLUDED.shields_reserve, updated_at = now();
    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('prev_month', v_prev, 'new_month', v_new, 'staff_processed', v_processed);
END; $$;








--
-- Name: v5_cron_finish(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_cron_finish(p_job text, p_idem text, p_rows integer, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.cron_runs SET finished_at = now(), rows_affected = p_rows, error = p_error
  WHERE job = p_job AND idem_key = p_idem;
$$;








--
-- Name: v5_cron_start(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_cron_start(p_job text, p_idem text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.cron_runs(job, idem_key) VALUES (p_job, p_idem);
  RETURN true;
EXCEPTION WHEN unique_violation THEN
  RETURN false; -- đã chạy (idempotent) — caller bỏ qua
END; $$;








--
-- Name: v5_daily_missions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_daily_missions(p_user uuid) RETURNS TABLE(building_id uuid, building_name text, cluster_id text, days_since_touch integer, days_since_full integer, vacant_rooms bigint, score numeric, color text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.building_id,
    c.building_name,
    c.cluster_id,
    c.days_since_touch,
    c.days_since_full,
    c.vacant_rooms,
    c.score,
    c.color,
    c.reason
  FROM public.v5_route_candidates(p_user) c
  ORDER BY
    c.priority_bucket,
    CASE WHEN c.priority_bucket = 0 THEN c.days_since_full ELSE c.days_since_touch END DESC NULLS FIRST,
    c.score DESC,
    c.building_name,
    c.building_id;
$$;








--
-- Name: v5_daily_missions_self(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_daily_missions_self() RETURNS TABLE(building_id uuid, building_name text, cluster_id text, days_since_touch integer, days_since_full integer, vacant_rooms bigint, score numeric, color text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.v5_daily_missions(auth.uid());
$$;








--
-- Name: v5_distance_m(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN NULL
  ELSE ROUND(6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
  )))::int END;
$$;








--
-- Name: v5_expire_stale(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_expire_stale(p_before date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n INT;
BEGIN
  UPDATE public.inspection_sessions SET status='expired', updated_at=now()
  WHERE status IN ('open','presence') AND session_date < p_before
    AND now() - started_at > INTERVAL '4 hours';  -- ân hạn qua nửa đêm (20260720190000)
  GET DIAGNOSTICS v_n = ROW_COUNT;
  UPDATE public.salary_attendance_day SET status='expired', updated_at=now()
  WHERE status IN ('pending','pending_check') AND work_date < p_before;
  RETURN v_n;
END; $$;








--
-- Name: v5_flag_day(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_flag_day(p_user uuid, p_date date, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ được gắn nghi án'; END IF;
  UPDATE public.salary_attendance_day SET
    status = 'flagged',
    audit = audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', auth.uid(),
            'action', 'flag', 'reason', p_reason, 'appeal_deadline', now() + INTERVAL '48 hours')),
    updated_at = now()
  WHERE user_id = p_user AND work_date = p_date AND status IN ('ticked','pending_check','presence','pending');
  IF NOT FOUND THEN RAISE EXCEPTION 'Ngày này không ở trạng thái gắn nghi án được'; END IF;
  INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
  VALUES (p_user, 'CUSTOM', 'IN_APP', 'PENDING', 'Ngày công đang được xem lại',
    'Ngày ' || to_char(p_date,'DD/MM') || ' đang được chủ xem lại bằng chứng — bạn có 48h để phản hồi trong app',
    jsonb_build_object('v5','flagged','date', p_date, 'url', '/my-day'));
  RETURN jsonb_build_object('flagged', true, 'date', p_date);
END; $$;








--
-- Name: v5_lock_assert(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_lock_assert(p_month date) RETURNS TABLE(staff_id uuid, staff_name text, n_chuan integer, ticked_days integer, attend_amount numeric, streak_amount numeric, total numeric, a1_caps_ok boolean, a2_no_open_flags boolean, a3_payment_join_ok boolean, all_ok boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month DATE := date_trunc('month', p_month)::date;
  v_staff RECORD; v_m JSONB;
  v_flags INT; v_badpay INT;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ xem đối soát'; END IF;
  FOR v_staff IN SELECT DISTINCT sa.staff_id, p.full_name FROM public.staff_assignments sa
                 JOIN public.profiles p ON p.id = sa.staff_id WHERE sa.building_id IS NOT NULL LOOP
    v_m := public.v5_month_money(v_staff.staff_id, v_month);
    SELECT COUNT(*) INTO v_flags FROM public.salary_attendance_day
    WHERE user_id = v_staff.staff_id AND status = 'flagged'
      AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;
    -- ASSERT 3: 100% tick nguồn PAYMENT join ngược phiếu thu thật có GPS ok
    SELECT COUNT(*) INTO v_badpay
    FROM public.salary_attendance_day sad
    WHERE sad.user_id = v_staff.staff_id AND sad.status='ticked' AND sad.tick_source='PAYMENT'
      AND sad.work_date >= v_month AND sad.work_date < (v_month + INTERVAL '1 month')::date
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(sad.evidence) e
        JOIN public.income_expenses ie ON ie.id = NULLIF(e->>'ref_id','')::uuid
        WHERE ie.collect_geofence_status = 'ok'
      )
      -- tick PAYMENT qua phiên check-nhanh: evidence ref là session — chấp nhận nếu phiên có paired ie hợp lệ
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(sad.evidence) e
        JOIN public.inspection_sessions s ON s.id = NULLIF(e->>'ref_id','')::uuid
        LEFT JOIN public.income_expenses ie2 ON ie2.id = s.paired_income_expense_id
        WHERE s.status IN ('quick_done','passed')
          AND (ie2.collect_geofence_status = 'ok' OR EXISTS (
            SELECT 1 FROM public.income_expenses ie3
            WHERE ie3.user_id = v_staff.staff_id AND ie3.building_id = s.building_id
              AND ie3.collect_geofence_status = 'ok'
              AND public.vn_local_date(ie3.created_at) = s.session_date))
      );

    staff_id := v_staff.staff_id; staff_name := v_staff.full_name;
    n_chuan := (v_m->>'n_chuan')::int; ticked_days := (v_m->>'ticked_days')::int;
    attend_amount := (v_m->>'attend_amount')::numeric; streak_amount := (v_m->>'streak_amount')::numeric;
    total := (v_m->>'total')::numeric;
    a1_caps_ok := attend_amount <= (v_m->>'attend_budget')::numeric AND streak_amount <= (v_m->>'streak_budget')::numeric;
    a2_no_open_flags := v_flags = 0;
    a3_payment_join_ok := v_badpay = 0;
    all_ok := a1_caps_ok AND a2_no_open_flags AND a3_payment_join_ok;
    RETURN NEXT;
  END LOOP;
END; $$;








--
-- Name: v5_month_money(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_month_money(p_user uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg JSONB := public.get_salary_v5_config();
  v_month DATE := date_trunc('month', p_month)::date;
  v_n INT; v_rate NUMERIC; v_ticked INT;
  v_budget NUMERIC := (v_cfg->'attendance_v5'->>'budget')::numeric;
  v_sbudget NUMERIC := (v_cfg->'streak_v5'->>'budget')::numeric;
  v_soft JSONB := v_cfg->'attendance_v5'->'soft_floor';
  v_attend NUMERIC; v_streak NUMERIC;
  v_banked JSONB;
BEGIN
  v_n := public.v5_n_chuan(v_month, p_user);
  v_rate := CASE WHEN v_n > 0 THEN v_budget / v_n ELSE 0 END;
  SELECT COUNT(*) INTO v_ticked FROM public.salary_attendance_day
  WHERE user_id = p_user AND status = 'ticked'
    AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;

  v_attend := ROUND(v_rate * LEAST(v_ticked, v_n));
  -- sàn mềm (tuỳ chọn config): ≥ at_days ngày → tối thiểu amount
  IF COALESCE((v_soft->>'enabled')::boolean, false) AND v_ticked >= (v_soft->>'at_days')::int THEN
    v_attend := GREATEST(v_attend, (v_soft->>'amount')::numeric);
  END IF;
  v_attend := LEAST(v_attend, v_budget); -- ASSERT trần 6tr

  SELECT COALESCE(milestones_banked, '[]'::jsonb) INTO v_banked
  FROM public.salary_streak_state WHERE user_id = p_user AND period_month = v_month;
  v_banked := COALESCE(v_banked, '[]'::jsonb);
  SELECT COALESCE(SUM((b->>'delta')::numeric), 0) INTO v_streak FROM jsonb_array_elements(v_banked) b;
  v_streak := LEAST(v_streak, v_sbudget); -- ASSERT trần 3tr

  RETURN jsonb_build_object(
    'month', v_month, 'n_chuan', v_n, 'day_rate', ROUND(v_rate),
    'ticked_days', v_ticked,
    'attend_amount', v_attend, 'attend_budget', v_budget,
    'streak_amount', v_streak, 'streak_budget', v_sbudget,
    'banked', v_banked,
    'total', v_attend + v_streak
  );
END; $$;








--
-- Name: v5_n_chuan(date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_n_chuan(p_month date, p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT (SELECT COUNT(*) FROM public.vn_workdays(p_month))::int
       - (SELECT COUNT(*) FROM public.salary_attendance_day sad
          WHERE sad.user_id = p_user
            AND sad.status = 'leave_approved'
            AND sad.work_date >= date_trunc('month', p_month)::date
            AND sad.work_date <  (date_trunc('month', p_month) + INTERVAL '1 month')::date)::int;
$$;








--
-- Name: v5_recompute_streak(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_recompute_streak(p_user uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg JSONB := public.get_salary_v5_config();
  v_today DATE := public.vn_local_date(now());
  v_start DATE := date_trunc('month', p_month)::date;
  v_month_end DATE := (v_start + INTERVAL '1 month')::date - 1;
  v_end DATE := LEAST((v_start + INTERVAL '1 month')::date - 1, v_today);
  v_reset DATE;
  v_free_cap INT := COALESCE((v_cfg->'streak_v5'->>'shields_free')::int, 3);
  v_spend_cap INT := COALESCE((v_cfg->'streak_v5'->>'spend_cap')::int, 1);
  v_reserve INT;
  v_free INT; v_res_used INT := 0;
  v_cur INT := 0; v_best INT := 0; v_breaks INT := 0;
  v_cur2 INT := 0; v_best2 INT := 0; v_free2 INT; v_res2 INT; v_res_used2 INT := 0; -- sim cap 2
  v_d DATE;
  v_status TEXT;
  v_is_workday BOOLEAN;
  v_owner UUID := (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1);
  v_n INT;
  v_miles JSONB;
  v_deltas JSONB := v_cfg->'streak_v5'->'deltas';
  v_banked JSONB := '[]'::jsonb;
  v_prev_banked JSONB;
  v_last_active DATE;
  v_fm JSONB;
  v_milestone JSONB;
  i INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('v5_sss' || p_user::text || v_start::text));
  SELECT milestones_banked, shields_reserve, reset_from_date
    INTO v_prev_banked, v_reserve, v_reset
  FROM public.salary_streak_state WHERE user_id = p_user AND period_month = v_start;
  v_prev_banked := COALESCE(v_prev_banked, '[]'::jsonb);
  v_reserve := COALESCE(v_reserve, 0);
  v_free := v_free_cap; v_free2 := v_free_cap; v_res2 := v_reserve;

  v_n := public.v5_n_chuan(v_start, p_user);
  v_miles := public_v5_effective_milestones(v_cfg->'streak_v5'->'milestones', v_deltas, v_n);

  v_d := v_start;
  WHILE v_d <= v_end LOOP
    IF v_reset IS NOT NULL AND v_d < v_reset THEN
      v_cur := 0; v_cur2 := 0; -- trước mốc reset (án gian lận): trung tính, không tích
      v_d := v_d + 1; CONTINUE;
    END IF;
    v_is_workday := EXTRACT(dow FROM v_d) <> 0
      AND NOT EXISTS (SELECT 1 FROM public.salary_holidays h WHERE h.user_id = v_owner AND h.holiday_date = v_d);
    SELECT status INTO v_status FROM public.salary_attendance_day
      WHERE user_id = p_user AND work_date = v_d;

    IF NOT v_is_workday OR v_status IN ('leave_approved','pending_leave') THEN
      NULL; -- bắc cầu: CN / lễ / phép (kể cả phép đang chờ — bridge tạm US-2.6)
    ELSIF v_status = 'ticked' THEN
      v_cur := v_cur + 1; v_best := GREATEST(v_best, v_cur);
      v_cur2 := v_cur2 + 1; v_best2 := GREATEST(v_best2, v_cur2);
      v_last_active := v_d;
    ELSIF v_d < v_today THEN
      -- ngày-làm quá khứ không tick, không phép → lỡ
      v_breaks := v_breaks + 1;
      IF v_free > 0 THEN v_free := v_free - 1;               -- khiên miễn phí: bắc cầu
      ELSIF v_reserve - v_res_used > 0 AND v_res_used < v_spend_cap THEN v_res_used := v_res_used + 1;
      ELSE v_cur := 0; END IF;                                -- đứt
      IF v_free2 > 0 THEN v_free2 := v_free2 - 1;
      ELSIF v_res2 - v_res_used2 > 0 AND v_res_used2 < 2 THEN v_res_used2 := v_res_used2 + 1;
      ELSE v_cur2 := 0; END IF;
    END IF;
    v_d := v_d + 1;
  END LOOP;

  -- bank mốc theo best (full_month xử riêng bên dưới)
  FOR i IN 0 .. jsonb_array_length(v_miles) - 1 LOOP
    v_milestone := v_miles->i;
    IF (v_milestone->>'milestone') <> 'full_month' AND (v_milestone->>'milestone')::int <= v_best THEN
      v_banked := v_banked || jsonb_build_array(jsonb_build_object(
        'milestone', (v_milestone->>'milestone')::int, 'delta', (v_milestone->>'delta')::numeric,
        'banked_at', COALESCE((SELECT (b->>'banked_at') FROM jsonb_array_elements(v_prev_banked) b
                               WHERE b->>'milestone' = v_milestone->>'milestone' LIMIT 1), now()::text)));
    END IF;
  END LOOP;

  -- TRỌN THÁNG (20260720190000): đánh giá NGAY TẠI ĐÂY thay vì chỉ ở v5_close_period.
  -- Trước đây close_period bank một lần duy nhất sáng mùng 1 và bị idem_key theo
  -- THÁNG chặn chạy lại → duyệt phép / tick bù sự cố thiết bị sau ngày 1 không bao
  -- giờ được tính. Giờ mỗi lần recompute (tick, duyệt phép, admin bấm) đều phản ánh
  -- dữ liệu mới nhất. Gate: tháng đã trôi hết + sạch tuyệt đối + không án gian lận.
  SELECT milestone_item.value
  INTO v_fm
  FROM jsonb_array_elements(v_miles) AS milestone_item(value)
  WHERE milestone_item.value->>'milestone' = 'full_month';
  IF v_month_end < v_today THEN
    IF v_fm IS NOT NULL AND v_breaks = 0 AND v_reset IS NULL THEN
      v_banked := v_banked || jsonb_build_array(jsonb_build_object(
        'milestone', 'full_month', 'delta', (v_fm->>'delta')::numeric,
        'banked_at', COALESCE((SELECT (b->>'banked_at') FROM jsonb_array_elements(v_prev_banked) b
                               WHERE b->>'milestone' = 'full_month' LIMIT 1), now()::text)));
    END IF;
    -- tháng đã hết mà không sạch → KHÔNG giữ mốc cũ (đánh giá lại cả hai chiều)
  ELSE
    -- tháng đang chạy: giữ nguyên nếu close_period đã bank trước đó
    v_banked := v_banked || COALESCE(
      (SELECT jsonb_agg(b) FROM jsonb_array_elements(v_prev_banked) b WHERE b->>'milestone' = 'full_month'),
      '[]'::jsonb);
  END IF;

  INSERT INTO public.salary_streak_state AS s
    (user_id, period_month, current_streak, best_streak, milestones_banked, breaks_no_leave,
     shields_free_left, shields_reserve, shields_reserve_used, sim_cap2, last_active_date, reset_from_date, updated_at)
  VALUES (p_user, v_start, v_cur, v_best, v_banked, v_breaks,
          v_free, v_reserve, v_res_used,
          jsonb_build_object('best_streak', v_best2, 'reserve_used', v_res_used2),
          v_last_active, v_reset, now())
  ON CONFLICT (user_id, period_month) DO UPDATE SET
    current_streak = EXCLUDED.current_streak,
    best_streak = EXCLUDED.best_streak,
    milestones_banked = EXCLUDED.milestones_banked,
    breaks_no_leave = EXCLUDED.breaks_no_leave,
    shields_free_left = EXCLUDED.shields_free_left,
    shields_reserve_used = EXCLUDED.shields_reserve_used,
    sim_cap2 = EXCLUDED.sim_cap2,
    last_active_date = EXCLUDED.last_active_date,
    updated_at = now();

  RETURN jsonb_build_object(
    'current', v_cur, 'best', v_best, 'breaks_no_leave', v_breaks,
    'shields_free_left', v_free, 'shields_reserve_left', v_reserve - v_res_used,
    'banked', v_banked,
    'next', (SELECT jsonb_build_object('milestone', (mm->>'milestone')::int, 'delta', (mm->>'delta')::numeric,
                                       'days_to_go', (mm->>'milestone')::int - v_cur)
             FROM jsonb_array_elements(v_miles) mm
             WHERE mm->>'milestone' <> 'full_month' AND (mm->>'milestone')::int > v_best
             ORDER BY (mm->>'milestone')::int LIMIT 1)
  );
END;
$$;








--
-- Name: v5_route_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_route_candidates(p_user uuid) RETURNS TABLE(building_id uuid, building_name text, cluster_id text, latitude double precision, longitude double precision, street_address text, ward text, district text, province text, public_map_url text, last_touch_date date, last_full_date date, days_since_touch integer, days_since_full integer, vacant_rooms bigint, rooms_total bigint, expiring_contracts bigint, open_jobs bigint, score numeric, priority_bucket integer, priority_label text, touch_sla_days integer, full_interval_days integer, checked_today boolean, last_full_by_name text, color text, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg JSONB := public.get_salary_v5_config();
  v_sla INT := COALESCE((v_cfg->'coverage_v5'->>'sla_days')::int, 4);
  v_sla_hot INT := COALESCE((v_cfg->'coverage_v5'->>'sla_hot_days')::int, 3);
  v_full_interval INT := COALESCE((v_cfg->'coverage_v5'->>'full_interval_days')::int, 7);
  v_today DATE := public.vn_local_date(now());
BEGIN
  RETURN QUERY
  WITH scope AS (
    SELECT sa.building_id
    FROM public.staff_assignments sa
    WHERE sa.staff_id = p_user
      AND sa.building_id IS NOT NULL
    UNION
    SELECT ab.building_id
    FROM public.staff_assignments sa
    JOIN public.area_buildings ab ON ab.area_id = sa.area_id
    WHERE sa.staff_id = p_user
      AND sa.area_id IS NOT NULL
    UNION
    SELECT b.id
    FROM public.staff_assignments sa
    JOIN public.buildings b ON b.user_id = sa.user_id
    WHERE sa.staff_id = p_user
      AND sa.building_id IS NULL
      AND sa.area_id IS NULL
  ), base AS (
    SELECT
      bc.building_id,
      bc.building_name,
      bc.cluster_id,
      b.latitude::double precision AS latitude,
      b.longitude::double precision AS longitude,
      b.street_address,
      b.ward,
      b.district,
      b.province,
      b.public_map_url,
      bc.last_touch_date,
      bc.last_full_date,
      bc.days_since_touch::int AS d_touch,
      bc.days_since_full::int AS d_full,
      CASE
        WHEN jsonb_typeof(
          v_cfg->'coverage_v5'->'building_overrides'->bc.building_id::text
        ) = 'object'
        THEN v_cfg->'coverage_v5'->'building_overrides'->bc.building_id::text
        ELSE '{}'::jsonb
      END AS building_override,
      bc.vacant_rooms,
      bc.rooms_total,
      (SELECT COUNT(*)
       FROM public.contracts c
       JOIN public.rooms r ON r.id = c.room_id
       WHERE r.building_id = bc.building_id
         AND r.deleted_at IS NULL
         AND c.status = 'ACTIVE'
         AND c.deleted_at IS NULL
         AND c.end_date BETWEEN v_today AND v_today + 30) AS expiring,
      (SELECT COUNT(*)
       FROM public.jobs j
       WHERE j.building_id = bc.building_id
         AND j.status = 'IN_PROGRESS') AS open_jobs,
      lf.full_by_name
    FROM public.building_coverage bc
    JOIN scope s ON s.building_id = bc.building_id
    JOIN public.buildings b ON b.id = bc.building_id
    LEFT JOIN LATERAL (
      SELECT p.full_name AS full_by_name
      FROM public.inspection_sessions ins
      LEFT JOIN public.profiles p ON p.id = ins.user_id
      WHERE ins.building_id = bc.building_id
        AND ins.type = 'FULL'
        AND ins.status = 'passed'
      ORDER BY ins.session_date DESC, ins.ended_at DESC NULLS LAST,
               ins.started_at DESC, ins.id DESC
      LIMIT 1
    ) lf ON true
    WHERE bc.rooms_total > 0
      AND b.deleted_at IS NULL
      AND COALESCE(b.is_virtual, false) = false
      AND b.status = 'ACTIVE'
  ), resolved AS (
    SELECT
      x.*,
      CASE
        WHEN jsonb_typeof(x.building_override->'is_hot') = 'boolean'
        THEN (x.building_override->>'is_hot')::boolean
        ELSE x.vacant_rooms > 0
      END AS is_hot,
      CASE
        WHEN jsonb_typeof(x.building_override->'sla_days') = 'number' THEN
          CASE
            WHEN (x.building_override->>'sla_days')::numeric >= 1
              AND (x.building_override->>'sla_days')::numeric <= 2147483647
              AND trunc((x.building_override->>'sla_days')::numeric)
                = (x.building_override->>'sla_days')::numeric
            THEN (x.building_override->>'sla_days')::int
          END
      END AS override_sla
    FROM base x
  ), classified AS (
    SELECT
      x.*,
      COALESCE(
        x.override_sla,
        CASE WHEN x.is_hot THEN v_sla_hot ELSE v_sla END
      ) AS effective_sla,
      ROUND(
        LEAST(COALESCE(x.d_touch, 999), 60) * (1 + x.rooms_total / 20.0)
        + CASE WHEN x.is_hot THEN 10 ELSE 0 END
        + LEAST(5 * x.expiring, 10)
        + CASE WHEN x.open_jobs > 0 THEN 15 ELSE 0 END,
        1
      ) AS risk_score
    FROM resolved x
  ), prioritized AS (
    SELECT
      c.*,
      CASE
        WHEN c.last_full_date = v_today THEN 4
        WHEN c.last_full_date IS NULL OR c.d_full >= v_full_interval THEN 0
        WHEN c.last_touch_date IS NULL OR c.d_touch >= c.effective_sla THEN 1
        WHEN c.d_full >= GREATEST(v_full_interval - 1, 0)
          OR c.d_touch >= GREATEST(c.effective_sla - 1, 0) THEN 2
        ELSE 3
      END AS bucket
    FROM classified c
  )
  SELECT
    p.building_id,
    p.building_name,
    p.cluster_id,
    p.latitude,
    p.longitude,
    p.street_address,
    p.ward,
    p.district,
    p.province,
    p.public_map_url,
    p.last_touch_date,
    p.last_full_date,
    p.d_touch,
    p.d_full,
    p.vacant_rooms,
    p.rooms_total,
    p.expiring,
    p.open_jobs,
    p.risk_score,
    p.bucket,
    CASE p.bucket
      WHEN 0 THEN CASE WHEN p.last_full_date IS NULL THEN 'never_full' ELSE 'full_overdue' END
      WHEN 1 THEN 'visit_due'
      WHEN 2 THEN 'due_soon'
      WHEN 4 THEN 'checked_today'
      ELSE 'fresh'
    END,
    p.effective_sla,
    v_full_interval,
    COALESCE(p.last_full_date = v_today, false),
    p.full_by_name,
    CASE WHEN p.bucket IN (0, 1) THEN 'red' WHEN p.bucket = 2 THEN 'yellow' ELSE 'green' END,
    TRIM(BOTH ' ·' FROM CONCAT_WS(' · ',
      CASE WHEN p.last_full_date IS NULL THEN 'Chưa từng kiểm tra FULL'
           ELSE p.d_full || ' ngày chưa kiểm tra FULL' END,
      CASE WHEN p.last_touch_date IS NULL THEN 'Chưa có lần ghé được ghi nhận'
           WHEN p.last_touch_date IS DISTINCT FROM p.last_full_date
             THEN p.d_touch || ' ngày từ lần ghé gần nhất' END,
      CASE WHEN p.vacant_rooms > 0 THEN p.vacant_rooms || ' phòng đang chào khách' END,
      CASE WHEN p.expiring > 0 THEN p.expiring || ' HĐ sắp đáo hạn' END,
      CASE WHEN p.open_jobs > 0 THEN 'có việc đang mở' END
    ))
  FROM prioritized p
  ORDER BY
    p.bucket,
    CASE WHEN p.bucket = 0 THEN p.d_full ELSE p.d_touch END DESC NULLS FIRST,
    p.risk_score DESC,
    p.building_name,
    p.building_id;
END;
$$;








--
-- Name: v5_route_candidates_self(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_route_candidates_self() RETURNS TABLE(building_id uuid, building_name text, cluster_id text, latitude double precision, longitude double precision, street_address text, ward text, district text, province text, public_map_url text, last_touch_date date, last_full_date date, days_since_touch integer, days_since_full integer, vacant_rooms bigint, rooms_total bigint, expiring_contracts bigint, open_jobs bigint, score numeric, priority_bucket integer, priority_label text, touch_sla_days integer, full_interval_days integer, checked_today boolean, last_full_by_name text, color text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.v5_route_candidates(auth.uid());
$$;








--
-- Name: v5_run_digest(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_run_digest() RETURNS TABLE(user_id uuid, title text, body text, url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today DATE := public.vn_local_date(now());
  v_staff RECORD; v_m RECORD;
  v_lines TEXT; v_cnt INT;
BEGIN
  IF EXTRACT(dow FROM v_today) = 0 THEN RETURN; END IF; -- CN nghỉ, không digest
  FOR v_staff IN SELECT DISTINCT sa.staff_id FROM public.staff_assignments sa WHERE sa.building_id IS NOT NULL LOOP
    -- ngày phép-duyệt: im lặng
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.salary_attendance_day d
      WHERE d.user_id = v_staff.staff_id AND d.work_date = v_today AND d.status IN ('leave_approved','pending_leave'));
    v_lines := ''; v_cnt := 0;
    FOR v_m IN SELECT * FROM public.v5_daily_missions(v_staff.staff_id) WHERE color IN ('red','yellow') LIMIT 3 LOOP
      v_cnt := v_cnt + 1;
      v_lines := v_lines || CASE WHEN v_lines = '' THEN '' ELSE E'\n' END || '• ' || v_m.building_name || ' — ' || v_m.reason;
    END LOOP;
    CONTINUE WHEN v_cnt = 0;
    BEGIN
      INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
      VALUES (v_staff.staff_id, 'CUSTOM', 'IN_APP', 'PENDING',
        'Tuyến hôm nay: ' || v_cnt || ' toà nên ghé', v_lines,
        jsonb_build_object('v5','digest','date', v_today, 'url', '/my-day'));
    EXCEPTION WHEN unique_violation THEN CONTINUE; -- đã digest hôm nay
    END;
    user_id := v_staff.staff_id;
    title := 'Tuyến hôm nay: ' || v_cnt || ' toà nên ghé';
    body := v_lines;
    url := '/my-day';
    RETURN NEXT;
  END LOOP;
END; $$;








--
-- Name: v5_run_job(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_run_job(p_job text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_job = 'tier' THEN RETURN public.v5_run_tier();
  ELSIF p_job = 'score' THEN RETURN public.v5_run_score();
  ELSIF p_job = 'close_period' THEN RETURN public.v5_close_period(date_trunc('month', public.vn_local_date(now()))::date);
  ELSE RAISE EXCEPTION 'job không hợp lệ: %', p_job;
  END IF;
END; $$;








--
-- Name: v5_run_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_run_score() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n INT := 0; v_staff RECORD;
BEGIN
  FOR v_staff IN SELECT DISTINCT staff_id FROM public.staff_assignments WHERE building_id IS NOT NULL LOOP
    v_n := v_n + (SELECT COUNT(*) FROM public.v5_daily_missions(v_staff.staff_id));
  END LOOP;
  RETURN jsonb_build_object('mission_rows', v_n);
END; $$;








--
-- Name: v5_run_tier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_run_tier() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_expired INT;
BEGIN
  v_expired := public.v5_expire_stale(public.vn_local_date(now()));
  RETURN jsonb_build_object('expired_sessions', v_expired);
END; $$;








--
-- Name: v5_shadow_report(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_shadow_report(p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month DATE := date_trunc('month', p_month)::date;
  v_rows JSONB := '[]'::jsonb;
  v_staff RECORD; v_m JSONB; v_sss public.salary_streak_state;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ xem shadow report'; END IF;
  FOR v_staff IN SELECT DISTINCT sa.staff_id, p.full_name FROM public.staff_assignments sa
                 JOIN public.profiles p ON p.id = sa.staff_id WHERE sa.building_id IS NOT NULL LOOP
    v_m := public.v5_month_money(v_staff.staff_id, v_month);
    SELECT * INTO v_sss FROM public.salary_streak_state WHERE user_id = v_staff.staff_id AND period_month = v_month;
    v_rows := v_rows || jsonb_build_array(v_m || jsonb_build_object(
      'staff_id', v_staff.staff_id, 'staff_name', v_staff.full_name,
      'best_streak', COALESCE(v_sss.best_streak, 0),
      'breaks_no_leave', COALESCE(v_sss.breaks_no_leave, 0),
      'shields_used', COALESCE((SELECT COUNT(*)::int FROM public.salary_attendance_day sad
        WHERE sad.user_id = v_staff.staff_id AND sad.work_date >= v_month
          AND sad.work_date < (v_month + INTERVAL '1 month')::date AND sad.status='ticked'), 0),
      'sim_cap2', COALESCE(v_sss.sim_cap2, '{}'::jsonb)
    ));
  END LOOP;
  RETURN jsonb_build_object('month', v_month, 'rows', v_rows,
    'coverage', (SELECT jsonb_agg(jsonb_build_object('b', building_name, 'd', days_since_touch, 'full_d', days_since_full))
                 FROM public.building_coverage WHERE rooms_total > 0));
END; $$;








--
-- Name: v5_tick_attendance(uuid, date, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_tick_attendance(p_user uuid, p_date date, p_source text, p_ref uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg JSONB;
  v_month DATE := date_trunc('month', p_date)::date;
  v_already BOOLEAN := false;
  v_n INT;
  v_rate NUMERIC;
  v_ticked INT;
  v_streak JSONB;
BEGIN
  IF p_source NOT IN ('JOB','FULL','PAYMENT','MANUAL_DEVICE_ISSUE') THEN
    RAISE EXCEPTION 'tick_source không hợp lệ: %', p_source;
  END IF;
  -- Clamp ngày (20260720190000): ngày công không được ở tương lai, và không
  -- được ghi vào kỳ lương đã chốt (snapshot đã đóng băng → sẽ lệch sổ).
  IF p_date IS NULL THEN
    RAISE EXCEPTION 'Ngày chấm công không được rỗng.';
  END IF;
  IF p_date > public.vn_local_date(now()) THEN
    RAISE EXCEPTION 'Không thể chấm công cho ngày tương lai (%).', p_date;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.salary_monthly sm
    WHERE sm.staff_id = p_user AND sm.period_month = v_month AND sm.locked_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Kỳ lương % đã chốt — không thể thêm ngày công.', to_char(v_month, 'MM/YYYY');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('v5_tick' || p_user::text || p_date::text));

  INSERT INTO public.salary_attendance_day (user_id, work_date, status, tick_source, evidence)
  VALUES (p_user, p_date, 'ticked', p_source,
          jsonb_build_array(jsonb_build_object('at', now(), 'source', p_source, 'ref_id', p_ref, 'note', p_note)))
  ON CONFLICT (user_id, work_date) DO UPDATE SET
    -- ngày đã ticked: chỉ append evidence (binary — không double);
    -- pending*/neutral → nâng thành ticked; voided/flagged/expired/leave_approved GIỮ NGUYÊN (xử qua đường riêng)
    status = CASE WHEN salary_attendance_day.status IN ('pending','pending_check','pending_leave','neutral')
                  THEN 'ticked' ELSE salary_attendance_day.status END,
    tick_source = CASE WHEN salary_attendance_day.status IN ('pending','pending_check','pending_leave','neutral')
                       THEN p_source ELSE salary_attendance_day.tick_source END,
    evidence = salary_attendance_day.evidence ||
               jsonb_build_array(jsonb_build_object('at', now(), 'source', p_source, 'ref_id', p_ref, 'note', p_note)),
    updated_at = now();

  SELECT status <> 'ticked' OR tick_source <> p_source INTO v_already
  FROM public.salary_attendance_day WHERE user_id = p_user AND work_date = p_date;

  -- gỡ thông báo treo pending_check của ngày này (nếu có) khi đã tick
  UPDATE public.notifications SET status = 'READ'
  WHERE user_id = p_user AND (metadata->>'v5') = 'pending_check' AND (metadata->>'date') = p_date::text
    AND status <> 'READ';

  -- cập nhật chuỗi (recompute từ SAD — nguồn sự thật duy nhất)
  v_streak := public.v5_recompute_streak(p_user, v_month);

  v_cfg := public.get_salary_v5_config();
  v_n := public.v5_n_chuan(v_month, p_user);
  v_rate := CASE WHEN v_n > 0 THEN (v_cfg->'attendance_v5'->>'budget')::numeric / v_n ELSE 0 END;
  SELECT COUNT(*) INTO v_ticked FROM public.salary_attendance_day
  WHERE user_id = p_user AND status = 'ticked'
    AND work_date >= v_month AND work_date < (v_month + INTERVAL '1 month')::date;

  RETURN jsonb_build_object(
    'ticked', true,
    'already_ticked_today', (SELECT status = 'ticked' FROM public.salary_attendance_day
                             WHERE user_id = p_user AND work_date = p_date) AND v_ticked > 0,
    'work_date', p_date, 'source', p_source,
    'n_chuan', v_n, 'day_rate', ROUND(v_rate), 'ticked_days', v_ticked,
    'attend_tam_tinh', ROUND(v_rate * LEAST(v_ticked, v_n)),
    'streak', v_streak
  );
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.salary_award_errors(staff_id, fn_name, source_id, error_text, payload)
  VALUES (p_user, 'v5_tick_attendance', p_ref, SQLERRM,
          jsonb_build_object('date', p_date, 'source', p_source));
  RAISE;
END; $$;








--
-- Name: v5_tick_from_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_tick_from_job(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_j public.jobs;
BEGIN
  SELECT * INTO v_j FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND OR v_j.status <> 'COMPLETED' OR v_j.assignee_id <> v_uid THEN
    RETURN jsonb_build_object('ticked', false, 'reason', 'job_not_eligible');
  END IF;
  -- bằng chứng ảnh: chấp nhận cả attachments (nơi ảnh được merge) lẫn completion_attachments
  IF NOT public.job_photo_ok(v_j.completion_attachments, v_j.attachments) THEN
    RETURN jsonb_build_object('ticked', false, 'reason', 'no_photo_evidence');
  END IF;
  -- completion_time NOT NULL được bảo đảm bởi CHECK jobs_completed_needs_completion_time
  RETURN public.v5_tick_attendance(v_uid, public.vn_local_date(v_j.completion_time), 'JOB', p_job_id, v_j.title);
END; $$;








--
-- Name: v5_verdict(uuid, date, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v5_verdict(p_user uuid, p_date date, p_confirm boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_month DATE := date_trunc('month', p_date)::date;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Chỉ chủ được kết án'; END IF;
  IF p_confirm THEN
    UPDATE public.salary_attendance_day SET
      status = 'voided', voided_reason = COALESCE(p_note, 'Gian lận dữ liệu ảnh (đã kết án)'),
      audit = audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', auth.uid(), 'action', 'verdict_confirm', 'note', p_note)),
      updated_at = now()
    WHERE user_id = p_user AND work_date = p_date AND status = 'flagged';
    IF NOT FOUND THEN RAISE EXCEPTION 'Ngày này không ở trạng thái nghi án'; END IF;
    -- tước toàn bộ mốc banked THÁNG hiện hành + tính lại từ ngày kế (C2)
    UPDATE public.salary_streak_state SET
      milestones_banked = '[]'::jsonb, reset_from_date = p_date + 1, updated_at = now()
    WHERE user_id = p_user AND period_month = v_month;
    PERFORM public.v5_recompute_streak(p_user, v_month);
    INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
    VALUES (p_user, 'CUSTOM', 'IN_APP', 'PENDING', 'Kết luận xem xét ngày ' || to_char(p_date,'DD/MM'),
      'Ngày ' || to_char(p_date,'DD/MM') || ' không được tính công sau khi xem xét bằng chứng. Các ngày làm thật khác giữ nguyên. Chuỗi tính lại từ ' || to_char(p_date + 1,'DD/MM') || '.',
      jsonb_build_object('v5','verdict','date', p_date, 'confirmed', true));
  ELSE
    UPDATE public.salary_attendance_day SET
      status = 'ticked',
      audit = audit || jsonb_build_array(jsonb_build_object('at', now(), 'by', auth.uid(), 'action', 'verdict_clear', 'note', p_note)),
      updated_at = now()
    WHERE user_id = p_user AND work_date = p_date AND status = 'flagged';
    IF NOT FOUND THEN RAISE EXCEPTION 'Ngày này không ở trạng thái nghi án'; END IF;
    PERFORM public.v5_recompute_streak(p_user, v_month);
    INSERT INTO public.notifications (user_id, type, channel, status, subject, content, metadata)
    VALUES (p_user, 'CUSTOM', 'IN_APP', 'PENDING', 'Ngày công đã được xác nhận lại ✅',
      'Ngày ' || to_char(p_date,'DD/MM') || ' đã được xác nhận hợp lệ — cảm ơn bạn đã phản hồi.',
      jsonb_build_object('v5','verdict','date', p_date, 'confirmed', false));
  END IF;
  RETURN jsonb_build_object('confirmed', p_confirm, 'date', p_date);
END; $$;








--
-- Name: verify_income_expense(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_income_expense(p_id uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_voucher record;
  v_can_see boolean;
  v_full_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Phải đăng nhập';
  END IF;

  SELECT id, building_id, account_id, verified_at, verified_by, verified_by_name
    INTO v_voucher
    FROM public.income_expenses
   WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu';
  END IF;

  -- Caller phải có quyền xem phiếu (đồng bộ với policy SELECT)
  SELECT (
    public.is_super_admin()
    OR public.is_admin()
    OR (v_voucher.building_id IS NOT NULL AND public.can_access_building(v_voucher.building_id))
    OR (v_voucher.account_id IS NOT NULL
        AND v_voucher.account_id IN (SELECT app_private.my_possessed_cashbook_ids_v1()))
  ) INTO v_can_see;
  IF NOT v_can_see THEN
    RAISE EXCEPTION 'Không có quyền xem phiếu này';
  END IF;

  -- Đã có người kiểm trước đó → toggle bỏ kiểm (chỉ chủ kiểm hoặc super admin).
  IF v_voucher.verified_at IS NOT NULL THEN
    IF v_voucher.verified_by = v_uid OR public.is_super_admin() THEN
      UPDATE public.income_expenses
         SET verified_at = NULL,
             verified_by = NULL,
             verified_by_name = NULL,
             verified_note = NULL
       WHERE id = p_id;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Phiếu đã được % kiểm — chỉ super admin hoặc người kiểm mới bỏ được', COALESCE(v_voucher.verified_by_name, 'người khác');
    END IF;
  END IF;

  SELECT COALESCE(full_name, email, 'Người dùng') INTO v_full_name
    FROM public.profiles WHERE id = v_uid;

  UPDATE public.income_expenses
     SET verified_at = now(),
         verified_by = v_uid,
         verified_by_name = v_full_name,
         verified_note = NULLIF(BTRIM(COALESCE(p_note, '')), '')
   WHERE id = p_id;
END;
$$;








--
-- Name: verify_income_expense_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_income_expense_v1(p_id uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.income_expenses%rowtype;
  v_can_see boolean;
  v_full_name text;
  v_rows integer;
begin
  if v_actor is null then
    raise exception 'Phải đăng nhập' using errcode = '42501';
  end if;

  select * into v_row from public.income_expenses
   where id = p_id
   for update;
  if not found then
    raise exception 'Không tìm thấy phiếu';
  end if;

  if not app_private.is_income_expense_flow_owned(v_row.id) then
    raise exception 'Phiếu chưa thuộc luồng canonical — dùng đường legacy'
      using errcode = '55000';
  end if;

  -- Parity verify legacy: caller phải có quyền xem phiếu.
  select (
    public.is_super_admin()
    or public.is_admin()
    or (v_row.building_id is not null and public.can_access_building(v_row.building_id))
    or (v_row.account_id is not null
        and v_row.account_id in (select app_private.my_possessed_cashbook_ids_v1()))
  ) into v_can_see;
  if not v_can_see then
    raise exception 'Không có quyền xem phiếu này' using errcode = '42501';
  end if;

  if v_row.verified_at is not null then
    -- toggle bỏ kiểm: chỉ chủ kiểm hoặc super admin (parity legacy).
    if v_row.verified_by = v_actor or public.is_super_admin() then
      insert into app_private.ie_transition_authorization (income_expense_id, xid, purpose)
      values (v_row.id, pg_current_xact_id(), 'UNVERIFY');

      update public.income_expenses
         set verified_at = null, verified_by = null,
             verified_by_name = null, verified_note = null
       where id = v_row.id;
      get diagnostics v_rows = row_count;

      delete from app_private.ie_transition_authorization
       where income_expense_id = v_row.id and xid = pg_current_xact_id();

      if v_rows <> 1 then
        raise exception 'unverify affected % rows (expected 1)', v_rows using errcode = '55000';
      end if;

      perform app_private.append_income_expense_event_v1(
        v_row.organization_id, v_row.id, 'UNVERIFIED', v_actor,
        app_private.ie_actor_display_name_v1(v_actor),
        v_row.approval_status, v_row.approval_status, null);
      return;
    else
      raise exception 'Phiếu đã được % kiểm — chỉ super admin hoặc người kiểm mới bỏ được',
        coalesce(v_row.verified_by_name, 'người khác');
    end if;
  end if;

  select coalesce(full_name, email, 'Người dùng') into v_full_name
    from public.profiles where id = v_actor;

  insert into app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  values (v_row.id, pg_current_xact_id(), 'VERIFY');

  update public.income_expenses
     set verified_at = now(), verified_by = v_actor,
         verified_by_name = v_full_name,
         verified_note = nullif(btrim(coalesce(p_note, '')), '')
   where id = v_row.id;
  get diagnostics v_rows = row_count;

  delete from app_private.ie_transition_authorization
   where income_expense_id = v_row.id and xid = pg_current_xact_id();

  if v_rows <> 1 then
    raise exception 'verify affected % rows (expected 1)', v_rows using errcode = '55000';
  end if;

  perform app_private.append_income_expense_event_v1(
    v_row.organization_id, v_row.id, 'VERIFIED', v_actor,
    coalesce(v_full_name, 'Người dùng'),
    v_row.approval_status, v_row.approval_status,
    nullif(btrim(coalesce(p_note, '')), ''));
end;
$$;








