--
-- Name: vn_workdays(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vn_workdays(p_month date) RETURNS SETOF date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d::date
  FROM generate_series(date_trunc('month', p_month),
                       date_trunc('month', p_month) + INTERVAL '1 month - 1 day',
                       INTERVAL '1 day') AS g(d)
  WHERE EXTRACT(dow FROM d) <> 0                     -- bỏ CN
    AND d::date NOT IN (
      SELECT h.holiday_date FROM public.salary_holidays h
      WHERE h.user_id = (SELECT user_id FROM public.super_admins ORDER BY created_at LIMIT 1)
    );
$$;








--
-- Name: withdraw_financial_request_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_financial_request_v1(p_request_id uuid, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_req public.approval_requests%rowtype;
begin
  if v_actor is null then raise exception 'Chưa đăng nhập' using errcode='42501'; end if;
  select * into v_req from public.approval_requests
   where id = p_request_id for update;
  if not found then raise exception 'Không tìm thấy yêu cầu duyệt'; end if;
  if v_req.state <> 'PENDING_APPROVAL' then
    raise exception 'Yêu cầu không còn ở trạng thái chờ duyệt (%).', v_req.state;
  end if;
  if not (v_req.maker_user_id = v_actor or public.is_super_admin()) then
    raise exception 'Chỉ người lập (hoặc super admin) được rút yêu cầu' using errcode='42501';
  end if;

  update public.approval_requests
     set state = 'CANCELLED', version = version + 1
   where id = p_request_id;

  return json_build_object('request_id', p_request_id, 'state', 'CANCELLED');
end;
$$;








--
-- Name: withdraw_income_expense_v2(uuid, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app_private'
    AS $$
DECLARE
  v_uid uuid; v_mid uuid; v_ie public.income_expenses;
  v_hash text := md5(jsonb_build_object('v', p_voucher, 'erv', p_expected_review_version, 'eav', p_expected_approval_version)::text);
  v_op app_private.canonical_write_operations; v_new_rev bigint; v_resp jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ie FROM public.income_expenses ie WHERE ie.id = p_voucher FOR UPDATE;
  IF NOT FOUND OR v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: voucher % not found', p_voucher USING ERRCODE = 'P0002';
  END IF;
  SELECT r.user_id, r.membership_id INTO v_uid, v_mid FROM app_private.resolve_finance_actor_v2(v_ie.organization_id) r;

  v_op := app_private.finance_v2_begin_canonical_op(
    v_ie.organization_id, 'income_expense.withdraw.v2', p_voucher::text, v_uid, v_mid,
    p_idempotency_key, v_hash, p_voucher);
  IF v_op.completed_at IS NOT NULL THEN RETURN COALESCE(v_op.response_payload, '{}'::jsonb); END IF;

  PERFORM app_private.assert_income_expense_flow_owner_v2(p_voucher, 'CANONICAL_INCOME_EXPENSE');

  -- Only the original human maker may withdraw their own voucher; system-generated
  -- vouchers have no maker_user_id and are refused.
  IF v_ie.maker_user_id IS NULL OR v_ie.maker_user_id <> v_uid THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: only the original maker may withdraw this voucher' USING ERRCODE = '42501';
  END IF;
  IF v_ie.approval_status <> 'UNAPPROVED' OR v_ie.posting_status <> 'UNPOSTED'
     OR v_ie.review_state NOT IN ('PENDING','CHANGES_REQUESTED') THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: only UNAPPROVED+UNPOSTED PENDING/CHANGES_REQUESTED can be withdrawn (%, %, %)',
      v_ie.approval_status, v_ie.posting_status, v_ie.review_state USING ERRCODE = '55000';
  END IF;
  IF v_ie.review_version <> p_expected_review_version OR v_ie.approval_version <> p_expected_approval_version THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: version mismatch' USING ERRCODE = '55000';
  END IF;
  IF NOT app_private.finance_v2_is_recognition_period_open(v_ie.organization_id, COALESCE(v_ie.recognition_date, v_ie.voucher_date)) THEN
    RAISE EXCEPTION 'withdraw_income_expense_v2: recognition period is locked; use reopen/adjustment workflow' USING ERRCODE = '55000';
  END IF;

  v_new_rev := v_ie.review_version + 1;
  UPDATE public.income_expenses ie
     SET approval_status = 'CANCELLED', review_state = 'RESOLVED',
         cancellation_kind = 'WITHDRAWN_BY_MAKER', review_version = v_new_rev, updated_at = now()
   WHERE ie.id = p_voucher;

  -- Close a still-open PENDING request as WITHDRAWN; a terminal CHANGES_REQUESTED
  -- request is kept immutable (only the withdrawal audit is appended).
  UPDATE public.approval_requests ar
     SET state = 'WITHDRAWN', outcome_kind = 'MAKER_WITHDRAW',
         closed_by_membership_id = v_mid, closed_at = now()
   WHERE ar.organization_id = v_ie.organization_id
     AND ar.subject_type = 'INCOME_EXPENSE' AND ar.subject_id = p_voucher
     AND ar.state = 'PENDING_APPROVAL';

  v_resp := jsonb_build_object('voucherId', p_voucher, 'approvalStatus', 'CANCELLED',
                               'reviewState', 'RESOLVED', 'cancellationKind', 'WITHDRAWN_BY_MAKER',
                               'reviewVersion', v_new_rev);
  PERFORM app_private.finance_v2_finish_canonical_op(
    v_ie.organization_id, 'income_expense.withdraw.v2', p_voucher::text, v_uid, p_idempotency_key,
    p_voucher, v_resp, 'MAKER_WITHDRAW', v_new_rev, v_ie.approval_version, v_ie.posting_version);
  PERFORM app_private.finance_v2_log_event(v_ie.organization_id, 'income_expense.withdraw.v2', p_voucher, v_uid, p_idempotency_key);
  RETURN v_resp;
END
$$;








--
-- Name: FUNCTION withdraw_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.withdraw_income_expense_v2(p_voucher uuid, p_expected_review_version bigint, p_expected_approval_version bigint, p_idempotency_key text) IS 'Plan §5.3/§7.4: maker withdraw of an UNAPPROVED+UNPOSTED voucher -> CANCELLED+RESOLVED, WITHDRAWN_BY_MAKER.';








--
-- Name: zalo_broadcast(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_broadcast(p_conversation_ids uuid[], p_body text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c        public.zalo_conversations;
  v_msg_id uuid;
  v_count  int := 0;
  v_channel text;
  v_cid    uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  IF p_body IS NULL OR btrim(p_body) = '' THEN RAISE EXCEPTION 'Nội dung trống'; END IF;
  IF p_conversation_ids IS NULL OR array_length(p_conversation_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Chưa chọn hội thoại nào';
  END IF;

  FOREACH v_cid IN ARRAY p_conversation_ids LOOP
    SELECT * INTO c FROM public.zalo_conversations WHERE id = v_cid;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF NOT (c.user_id = auth.uid() OR public.zalo_can('send')) THEN CONTINUE; END IF;

    INSERT INTO public.zalo_messages(user_id, conversation_id, account_id, direction, msg_type, body, status, sent_by, sent_at)
    VALUES (c.user_id, c.id, c.account_id, 'out', 'text', p_body, 'pending', auth.uid(), now())
    RETURNING id INTO v_msg_id;

    UPDATE public.zalo_conversations
       SET last_message_text = p_body, last_message_at = now(), last_message_dir = 'out', updated_at = now()
     WHERE id = c.id;

    SELECT COALESCE(kind, 'personal') INTO v_channel FROM public.zalo_accounts WHERE id = c.account_id;
    INSERT INTO public.zalo_send_queue(user_id, conversation_id, message_id, account_id, channel, payload, status)
    VALUES (c.user_id, c.id, v_msg_id, c.account_id, COALESCE(v_channel, 'personal'),
            jsonb_build_object('type', 'text', 'body', p_body), 'queued');

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;








--
-- Name: zalo_can(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_can(_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_super_admin() OR public.is_admin() OR EXISTS (
    SELECT 1
    FROM public.staff_assignments sa
    LEFT JOIN public.roles r ON r.id = sa.role_id
    WHERE sa.staff_id = auth.uid()
      AND COALESCE((COALESCE(sa.permissions, r.permissions) -> 'chat_zalo' ->> _action)::boolean, false)
  );
$$;








--
-- Name: zalo_disconnect_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_disconnect_account(p_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  UPDATE public.zalo_accounts
     SET status='disconnected', qr_data=NULL, qr_expires_at=NULL, updated_at=now()
   WHERE id = p_account_id
     AND (user_id = auth.uid() OR public.is_super_admin() OR public.is_admin());
END;
$$;








--
-- Name: zalo_load_history(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_load_history(p_conversation_id uuid, p_count integer DEFAULT 50) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.zalo_conversations;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT * INTO c FROM public.zalo_conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Hội thoại không tồn tại'; END IF;
  IF c.thread_type <> 'group' THEN RAISE EXCEPTION 'Chỉ tải thêm được tin cũ của NHÓM'; END IF;
  IF NOT (c.user_id = auth.uid() OR public.zalo_can('view')) THEN
    RAISE EXCEPTION 'Bạn không có quyền' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.zalo_send_queue(user_id, conversation_id, account_id, channel, payload, status)
  VALUES (c.user_id, c.id, c.account_id, 'personal',
    jsonb_build_object('action','load_history','thread_id',c.thread_id,'thread_type',c.thread_type,'count',LEAST(COALESCE(p_count,50),200)),
    'queued');
END; $$;








--
-- Name: zalo_mark_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_mark_read(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  UPDATE public.zalo_conversations
     SET unread_count = 0, updated_at = now()
   WHERE id = p_conversation_id
     AND (user_id = auth.uid() OR assigned_staff_id = auth.uid() OR public.is_super_admin() OR public.is_admin());
END;
$$;








--
-- Name: zalo_react_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_react_message(p_message_id uuid, p_emoji text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE m public.zalo_messages; c public.zalo_conversations;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT * INTO m FROM public.zalo_messages WHERE id = p_message_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tin nhắn không tồn tại'; END IF;
  SELECT * INTO c FROM public.zalo_conversations WHERE id = m.conversation_id;
  IF NOT (c.user_id = auth.uid() OR public.zalo_can('send')) THEN
    RAISE EXCEPTION 'Bạn không có quyền' USING ERRCODE = '42501';
  END IF;
  UPDATE public.zalo_messages SET reaction_emoji = p_emoji WHERE id = p_message_id;
  INSERT INTO public.zalo_send_queue(user_id, conversation_id, account_id, channel, payload, status)
  VALUES (c.user_id, c.id, c.account_id, 'personal',
    jsonb_build_object('action','react','emoji',p_emoji,'target_msg_id',m.zalo_msg_id,'target_cli_msg_id',m.cli_msg_id,'thread_id',c.thread_id,'thread_type',c.thread_type),
    'queued');
END; $$;








--
-- Name: zalo_recall_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zalo_recall_message(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE m public.zalo_messages; c public.zalo_conversations;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501'; END IF;
  SELECT * INTO m FROM public.zalo_messages WHERE id = p_message_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tin nhắn không tồn tại'; END IF;
  IF m.direction <> 'out' THEN RAISE EXCEPTION 'Chỉ thu hồi được tin do bạn gửi'; END IF;
  SELECT * INTO c FROM public.zalo_conversations WHERE id = m.conversation_id;
  IF NOT (c.user_id = auth.uid() OR public.zalo_can('send')) THEN
    RAISE EXCEPTION 'Bạn không có quyền' USING ERRCODE = '42501';
  END IF;
  UPDATE public.zalo_messages SET body = '(Tin đã được thu hồi)', msg_type = 'sys', reaction_emoji = NULL WHERE id = p_message_id;
  INSERT INTO public.zalo_send_queue(user_id, conversation_id, account_id, channel, payload, status)
  VALUES (c.user_id, c.id, c.account_id, 'personal',
    jsonb_build_object('action','recall','target_msg_id',m.zalo_msg_id,'target_cli_msg_id',m.cli_msg_id,'thread_id',c.thread_id,'thread_type',c.thread_type),
    'queued');
END; $$;








