    CONSTRAINT zalo_messages_direction_check CHECK ((direction = ANY (ARRAY['in'::text, 'out'::text]))),
    CONSTRAINT zalo_messages_msg_type_check CHECK ((msg_type = ANY (ARRAY['text'::text, 'image'::text, 'file'::text, 'sticker'::text, 'sys'::text, 'video'::text]))),
