--
-- Name: cashbook_possession_candidates; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.cashbook_possession_candidates (
    candidate_key text NOT NULL,
    organization_id uuid NOT NULL,
    cashbook_id uuid NOT NULL,
    membership_id uuid,
    proposed_kind text NOT NULL,
    source_kind text NOT NULL,
    source_relation text NOT NULL,
    source_row_id uuid,
    source_user_id uuid,
    status text DEFAULT 'PENDING_REVIEW'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_reason text,
    materialized_binding_id uuid,
    version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT cashbook_possession_candidates_check CHECK ((((status = 'PENDING_REVIEW'::text) AND (reviewed_at IS NULL)) OR ((status = 'AMBIGUOUS'::text) AND (reviewed_at IS NOT NULL) AND (review_reason IS NOT NULL)) OR ((status = ANY (ARRAY['APPROVED'::text, 'REJECTED'::text])) AND (reviewed_at IS NOT NULL) AND (reviewed_by IS NOT NULL) AND (review_reason IS NOT NULL)))),
    CONSTRAINT cashbook_possession_candidates_check1 CHECK (((status <> 'APPROVED'::text) OR (membership_id IS NOT NULL))),
    CONSTRAINT cashbook_possession_candidates_check2 CHECK (((reviewed_by IS NULL) OR (source_user_id IS NULL) OR (reviewed_by <> source_user_id))),
    CONSTRAINT cashbook_possession_candidates_proposed_kind_check CHECK ((proposed_kind = ANY (ARRAY['CUSTODIAN'::text, 'OPERATOR'::text, 'KNOWER'::text]))),
    CONSTRAINT cashbook_possession_candidates_status_check CHECK ((status = ANY (ARRAY['PENDING_REVIEW'::text, 'APPROVED'::text, 'REJECTED'::text, 'AMBIGUOUS'::text])))
);








