--
-- Name: accounts_with_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.accounts_with_balance WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    name,
    bank_name,
    account_number,
    is_default,
    created_at,
    updated_at,
    deleted_at,
    code,
    description,
    bank_account_holder,
    initial_amount,
    initial_date,
    lock_date,
    branch,
    is_virtual,
    (initial_amount + COALESCE(( SELECT sum(l.signed_amount) AS sum
           FROM (public.income_expense_posting_lines l
             JOIN public.income_expense_postings p ON ((p.id = l.posting_id)))
          WHERE ((l.account_id = a.id) AND (l.organization_id = a.organization_id) AND (p.event_kind = ANY (ARRAY['POSTING'::text, 'REVERSAL'::text])))), (0)::numeric)) AS current_amount
   FROM public.accounts a
  WHERE (deleted_at IS NULL);








--
-- Name: accounts_with_balance_v2; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.accounts_with_balance_v2 WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    name,
    bank_name,
    account_number,
    is_default,
    created_at,
    updated_at,
    deleted_at,
    code,
    description,
    bank_account_holder,
    initial_amount,
    initial_date,
    lock_date,
    branch,
    is_virtual,
    organization_id,
    (COALESCE(initial_amount, (0)::numeric) + COALESCE(( SELECT sum(pl.signed_amount) AS sum
           FROM (public.income_expense_posting_lines pl
             JOIN public.income_expense_postings p ON (((p.id = pl.posting_id) AND (p.organization_id = pl.organization_id))))
          WHERE ((pl.organization_id = a.organization_id) AND (pl.account_id = a.id) AND (p.event_kind = ANY (ARRAY['POSTING'::text, 'REVERSAL'::text])))), (0)::numeric)) AS current_amount
   FROM public.accounts a
  WHERE (deleted_at IS NULL);








--
-- Name: VIEW accounts_with_balance_v2; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.accounts_with_balance_v2 IS 'Plan §11.2: cash balance from canonical posting lines (initial_amount + SUM signed_amount over POSTING/REVERSAL events, composite org/account, no approval filter). Additive; legacy accounts_with_balance untouched. security_invoker=true.';








--
-- Name: finance_v2_balance_parity_v1; Type: VIEW; Schema: app_private; Owner: -
--

CREATE VIEW app_private.finance_v2_balance_parity_v1 WITH (security_invoker='true') AS
 SELECT a.organization_id,
    a.id AS account_id,
    a.name AS account_name,
    a.is_virtual,
    legacy.current_amount AS legacy_current_amount,
    v2.current_amount AS v2_current_amount,
    (COALESCE(legacy.current_amount, (0)::numeric) - COALESCE(v2.current_amount, (0)::numeric)) AS diff,
    (abs((COALESCE(legacy.current_amount, (0)::numeric) - COALESCE(v2.current_amount, (0)::numeric))) < 0.01) AS is_match
   FROM ((public.accounts a
     JOIN public.accounts_with_balance legacy ON ((legacy.id = a.id)))
     JOIN public.accounts_with_balance_v2 v2 ON ((v2.id = a.id)))
  WHERE ((a.deleted_at IS NULL) AND (a.is_virtual = false));








--
-- Name: VIEW finance_v2_balance_parity_v1; Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON VIEW app_private.finance_v2_balance_parity_v1 IS 'Plan §10.4/§10.5 SHADOW: per real (non-virtual) account, legacy accounts_with_balance.current_amount vs V2 accounts_with_balance_v2.current_amount, diff, is_match (abs(diff)<0.01). After backfill the two MUST tie out per book; any is_match=false is a cutover blocker. Owner-only; additive.';








