    created_at timestamp with time zone DEFAULT now() NOT NULL,
    start_date date,
    end_date date,
    organization_id uuid,
    accounting_class text NOT NULL,
    CONSTRAINT income_expense_items_accounting_class_check CHECK ((accounting_class = ANY (ARRAY['PNL'::text, 'DEPOSIT'::text, 'CUSTOMER_CREDIT'::text, 'INTERNAL'::text]))),
    CONSTRAINT income_expense_items_quantity_positive CHECK ((quantity > 0)),
    CONSTRAINT income_expense_items_unit_price_non_negative CHECK ((unit_price >= (0)::numeric))
);








