--
-- Name: finance_v2_pnl_parity_v1; Type: VIEW; Schema: app_private; Owner: -
--

CREATE VIEW app_private.finance_v2_pnl_parity_v1 WITH (security_invoker='true') AS
 WITH legacy_base AS (
         SELECT ie.id AS voucher_id,
            ie.organization_id AS org_id,
            ie.type AS vtype,
            ie.voucher_date AS vdate,
            ie.total_amount,
                CASE
                    WHEN ((ie.invoice_id IS NOT NULL) AND (inv.billing_month ~ '^\d{4}-\d{2}$'::text)) THEN to_date(inv.billing_month, 'YYYY-MM'::text)
                    ELSE NULL::date
                END AS inv_month
           FROM ((public.income_expenses ie
             JOIN public.buildings b ON (((b.id = ie.building_id) AND (b.deleted_at IS NULL))))
             LEFT JOIN public.invoices inv ON (((inv.id = ie.invoice_id) AND (inv.deleted_at IS NULL))))
          WHERE ((ie.deleted_at IS NULL) AND (ie.approval_status = 'APPROVED'::text) AND (ie.counts_in_business_result = true))
        ), legacy_alloc AS (
         SELECT v_1.org_id,
            v_1.vtype,
            (date_trunc('month'::text, (v_1.inv_month)::timestamp with time zone))::date AS m,
            (it.amount)::numeric AS amt
           FROM (legacy_base v_1
             JOIN public.income_expense_items it ON ((it.income_expense_id = v_1.voucher_id)))
          WHERE (v_1.inv_month IS NOT NULL)
        UNION ALL
         SELECT v_1.org_id,
            v_1.vtype,
            (date_trunc('month'::text, (v_1.inv_month)::timestamp with time zone))::date AS date_trunc,
            v_1.total_amount
           FROM legacy_base v_1
          WHERE ((v_1.inv_month IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM public.income_expense_items x
                  WHERE (x.income_expense_id = v_1.voucher_id)))))
        UNION ALL
         SELECT v_1.org_id,
            v_1.vtype,
            ((date_trunc('month'::text, (it.start_date)::timestamp with time zone) + ((gs.i || ' month'::text))::interval))::date AS date,
            (round(((it.amount * ((gs.i + 1))::numeric) / (n.n)::numeric)) - round(((it.amount * (gs.i)::numeric) / (n.n)::numeric))) AS "numeric"
           FROM (((legacy_base v_1
             JOIN public.income_expense_items it ON ((it.income_expense_id = v_1.voucher_id)))
             CROSS JOIN LATERAL ( SELECT GREATEST((((((EXTRACT(year FROM it.end_date))::integer * 12) + (EXTRACT(month FROM it.end_date))::integer) - (((EXTRACT(year FROM it.start_date))::integer * 12) + (EXTRACT(month FROM it.start_date))::integer)) + 1), 1) AS n) n)
             CROSS JOIN LATERAL generate_series(0, (n.n - 1)) gs(i))
          WHERE ((v_1.inv_month IS NULL) AND (it.start_date IS NOT NULL) AND (it.end_date IS NOT NULL) AND (it.end_date >= it.start_date))
        UNION ALL
         SELECT v_1.org_id,
            v_1.vtype,
            (date_trunc('month'::text, (it.start_date)::timestamp with time zone))::date AS date_trunc,
            (it.amount)::numeric AS amount
           FROM (legacy_base v_1
             JOIN public.income_expense_items it ON ((it.income_expense_id = v_1.voucher_id)))
          WHERE ((v_1.inv_month IS NULL) AND (it.start_date IS NOT NULL) AND (it.end_date IS NOT NULL) AND (it.end_date < it.start_date))
        UNION ALL
         SELECT v_1.org_id,
            v_1.vtype,
            (date_trunc('month'::text, (v_1.vdate)::timestamp with time zone))::date AS date_trunc,
            (it.amount)::numeric AS amount
           FROM (legacy_base v_1
             JOIN public.income_expense_items it ON ((it.income_expense_id = v_1.voucher_id)))
          WHERE ((v_1.inv_month IS NULL) AND ((it.start_date IS NULL) OR (it.end_date IS NULL)))
        UNION ALL
         SELECT v_1.org_id,
            v_1.vtype,
            (date_trunc('month'::text, (v_1.vdate)::timestamp with time zone))::date AS date_trunc,
            v_1.total_amount
           FROM legacy_base v_1
          WHERE ((v_1.inv_month IS NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM public.income_expense_items x
                  WHERE (x.income_expense_id = v_1.voucher_id)))))
        ), legacy_pnl AS (
         SELECT legacy_alloc.org_id AS organization_id,
            legacy_alloc.m AS period,
            sum(
                CASE
                    WHEN (legacy_alloc.vtype = 'EXPENSE'::text) THEN (- legacy_alloc.amt)
                    ELSE legacy_alloc.amt
                END) AS legacy_pnl
           FROM legacy_alloc
          GROUP BY legacy_alloc.org_id, legacy_alloc.m
        ), v2_pnl AS (
         SELECT ec.organization_id,
            ec.target_period AS period,
            sum(ec.signed_kqkd_amount) AS v2_pnl,
            sum(ec.signed_kqkd_amount) FILTER (WHERE (ec.source_approval_status = 'APPROVED'::text)) AS v2_pnl_approved
           FROM (( SELECT DISTINCT income_expenses.organization_id
                   FROM public.income_expenses
                  WHERE (income_expenses.deleted_at IS NULL)) o
             CROSS JOIN LATERAL app_private.effective_profit_contributions_v2(o.organization_id, NULL::date) ec(organization_id, target_period, contribution_kind, contribution_id, source_voucher_id, source_approval_status, source_review_state, source_version, signed_kqkd_amount, allocation_snapshot, source_payload_hash))
          GROUP BY ec.organization_id, ec.target_period
        )
 SELECT COALESCE(l.organization_id, v.organization_id) AS organization_id,
    COALESCE(l.period, v.period) AS period,
    COALESCE(l.legacy_pnl, (0)::numeric) AS legacy_pnl_accrual,
    COALESCE(v.v2_pnl, (0)::numeric) AS v2_pnl_effective,
    COALESCE(v.v2_pnl_approved, (0)::numeric) AS v2_pnl_approved_basis,
    (COALESCE(l.legacy_pnl, (0)::numeric) - COALESCE(v.v2_pnl, (0)::numeric)) AS diff,
    (COALESCE(l.legacy_pnl, (0)::numeric) - COALESCE(v.v2_pnl_approved, (0)::numeric)) AS diff_approved_basis,
    (abs((COALESCE(l.legacy_pnl, (0)::numeric) - COALESCE(v.v2_pnl, (0)::numeric))) < 0.01) AS is_match,
    (abs((COALESCE(l.legacy_pnl, (0)::numeric) - COALESCE(v.v2_pnl_approved, (0)::numeric))) < 0.01) AS is_match_approved_basis
   FROM (legacy_pnl l
     FULL JOIN v2_pnl v ON (((v.organization_id = l.organization_id) AND (v.period = l.period))));








--
-- Name: VIEW finance_v2_pnl_parity_v1; Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON VIEW app_private.finance_v2_pnl_parity_v1 IS 'Plan §10.4/§10.5 SHADOW: per (org, month), legacy accrual P&L (reproduces fa_monthly_pnl_accrual: APPROVED + counts_in_business_result, accrual allocation, EXPENSE negative, sans can_access_building for cross-org owner reconciliation) vs V2 SUM(signed_kqkd_amount) from effective_profit_contributions_v2. diff/is_match compare the FULL V2 sum (incl. pending + adjustments); diff_approved_basis/is_match_approved_basis compare V2 restricted to APPROVED contributions — the clean tie-out gate. Owner-only; additive.';








