--

CREATE TABLE app_private.maintenance_rule_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid,
    service_kind text NOT NULL,
    effective_from_month date NOT NULL,
    standard_amount numeric(15,2),
    ceiling_amount numeric(15,2),
    min_months_between integer,
    counts_history boolean DEFAULT false NOT NULL,
    enforcement text DEFAULT 'WARN'::text NOT NULL,
    status text DEFAULT 'PUBLISHED'::text NOT NULL,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_at timestamp with time zone,
    CONSTRAINT maintenance_rule_versions_ceiling_amount_check CHECK (((ceiling_amount IS NULL) OR (ceiling_amount > (0)::numeric))),
    CONSTRAINT maintenance_rule_versions_enforcement_check CHECK ((enforcement = ANY (ARRAY['WARN'::text, 'BLOCK'::text]))),
    CONSTRAINT maintenance_rule_versions_min_months_between_check CHECK (((min_months_between IS NULL) OR (min_months_between > 0))),
    CONSTRAINT maintenance_rule_versions_service_kind_check CHECK ((service_kind = ANY (ARRAY['AIR_CONDITIONER'::text, 'WASHING_MACHINE'::text]))),
    CONSTRAINT maintenance_rule_versions_standard_amount_check CHECK (((standard_amount IS NULL) OR (standard_amount > (0)::numeric))),
    CONSTRAINT maintenance_rule_versions_status_check CHECK ((status = ANY (ARRAY['PUBLISHED'::text, 'RETIRED'::text]))),
    CONSTRAINT mrv_ceiling_ge_standard CHECK (((standard_amount IS NULL) OR (ceiling_amount IS NULL) OR (ceiling_amount >= standard_amount))),
    CONSTRAINT mrv_has_rule CHECK (((standard_amount IS NOT NULL) OR (ceiling_amount IS NOT NULL) OR (min_months_between IS NOT NULL))),
    CONSTRAINT mrv_month_first_day CHECK ((effective_from_month = (date_trunc('month'::text, (effective_from_month)::timestamp with time zone))::date)),
    CONSTRAINT mrv_retire_shape CHECK (((status = 'RETIRED'::text) = (retired_at IS NOT NULL)))
);








--
