--
-- Name: network_worker_release_heartbeats; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.network_worker_release_heartbeats (
    worker_id uuid NOT NULL,
    worker_version text NOT NULL,
    status text NOT NULL,
    heartbeat_at timestamp with time zone NOT NULL,
    started_at timestamp with time zone NOT NULL,
    assigned_building_count integer NOT NULL,
    connection_count integer,
    successful_poll_count integer,
    failed_poll_count integer,
    poll_observed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT network_worker_release_heartbeat_poll_metrics_check CHECK ((((connection_count IS NULL) AND (successful_poll_count IS NULL) AND (failed_poll_count IS NULL) AND (poll_observed_at IS NULL)) OR ((connection_count IS NOT NULL) AND (successful_poll_count IS NOT NULL) AND (failed_poll_count IS NOT NULL) AND (poll_observed_at IS NOT NULL) AND ((successful_poll_count + failed_poll_count) = connection_count) AND ((poll_observed_at >= started_at) AND (poll_observed_at <= heartbeat_at))))),
    CONSTRAINT network_worker_release_heartbeat_time_check CHECK ((started_at <= heartbeat_at)),
    CONSTRAINT network_worker_release_heartbeats_assigned_building_count_check CHECK (((assigned_building_count >= 1) AND (assigned_building_count <= 10000))),
    CONSTRAINT network_worker_release_heartbeats_connection_count_check CHECK (((connection_count >= 0) AND (connection_count <= 500))),
    CONSTRAINT network_worker_release_heartbeats_failed_poll_count_check CHECK (((failed_poll_count >= 0) AND (failed_poll_count <= 500))),
    CONSTRAINT network_worker_release_heartbeats_status_check CHECK ((status = ANY (ARRAY['ONLINE'::text, 'DEGRADED'::text, 'PAUSED'::text, 'STOPPING'::text]))),
    CONSTRAINT network_worker_release_heartbeats_successful_poll_count_check CHECK (((successful_poll_count >= 0) AND (successful_poll_count <= 500))),
    CONSTRAINT network_worker_release_heartbeats_worker_version_check CHECK ((octet_length(worker_version) = 40)),
    CONSTRAINT network_worker_release_heartbeats_worker_version_check1 CHECK ((worker_version ~ '^[a-f0-9]{40}$'::text))
);

ALTER TABLE ONLY app_private.network_worker_release_heartbeats FORCE ROW LEVEL SECURITY;








--
-- Name: TABLE network_worker_release_heartbeats; Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON TABLE app_private.network_worker_release_heartbeats IS 'Private bounded release/version heartbeat evidence for blue-green deployment readback; retention keeps the 5 most recently active releases per worker regardless of age so a rollback target is never expired, expires older displaced releases after 30 days, and hard-caps each worker at 20 releases.';








