    CONSTRAINT sfpv_category_chk CHECK ((fee_category = ANY (ARRAY['tien_nha'::text, 'dien'::text, 'nuoc'::text, 'internet'::text, 'quan_ly'::text, 've_sinh'::text, 'cong_an'::text, 'rac'::text, 'thang_may'::text]))),
    CONSTRAINT sfpv_month_first_day CHECK ((effective_from_month = (date_trunc('month'::text, (effective_from_month)::timestamp with time zone))::date)),
    CONSTRAINT sfpv_retire_shape CHECK (((status = 'RETIRED'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT special_fee_price_versions_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT special_fee_price_versions_source_check CHECK ((source = ANY (ARRAY['OWNER'::text, 'SEED_FROM_CONFIG'::text]))),
    CONSTRAINT special_fee_price_versions_status_check CHECK ((status = ANY (ARRAY['PUBLISHED'::text, 'RETIRED'::text])))
);








--
-- Name: TABLE special_fee_price_versions; Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON TABLE app_private.special_fee_price_versions IS 'Giá công bố của phí cố định, CÓ PHIÊN BẢN THEO THÁNG. Cố ý nằm ngoài tầm với của pay_period_fee: building_fee_accounts.default_amount bị đường chi ghi đè mỗi lần chi nên không dùng làm giá chuẩn được (nó là ký ức lần chi gần nhất). Đổi giá = thêm dòng mới với effective_from_month sau, KHÔNG sửa dòng cũ.';








