--
-- Name: utility_ceiling_versions; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.utility_ceiling_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid,
    utility_type text NOT NULL,
    effective_from_month date NOT NULL,
    ceiling_amount numeric(15,2),
    max_ratio_to_billed numeric(6,3),
    status text DEFAULT 'PUBLISHED'::text NOT NULL,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_at timestamp with time zone,
    CONSTRAINT ucv_has_rule CHECK (((ceiling_amount IS NOT NULL) OR (max_ratio_to_billed IS NOT NULL))),
    CONSTRAINT ucv_month_first_day CHECK ((effective_from_month = (date_trunc('month'::text, (effective_from_month)::timestamp with time zone))::date)),
    CONSTRAINT ucv_retire_shape CHECK (((status = 'RETIRED'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT utility_ceiling_versions_ceiling_amount_check CHECK (((ceiling_amount IS NULL) OR (ceiling_amount > (0)::numeric))),
    CONSTRAINT utility_ceiling_versions_max_ratio_to_billed_check CHECK (((max_ratio_to_billed IS NULL) OR (max_ratio_to_billed > (0)::numeric))),
    CONSTRAINT utility_ceiling_versions_status_check CHECK ((status = ANY (ARRAY['PUBLISHED'::text, 'RETIRED'::text]))),
    CONSTRAINT utility_ceiling_versions_utility_type_check CHECK ((utility_type = ANY (ARRAY['ELECTRIC'::text, 'WATER'::text])))
);








--
-- Name: TABLE utility_ceiling_versions; Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON TABLE app_private.utility_ceiling_versions IS 'Trần chi điện/nước. RỖNG lúc tạo ⇒ không trần, hành vi như hôm nay. Điện nước là chi phí theo đồng hồ (đo prod: lệch 9-59% giữa các tháng) nên KHÔNG so bằng tuyệt đối như phí cố định — chỉ có trần.';








