CREATE TABLE public.invoice_payment_collections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    contract_id uuid,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    collection_date date NOT NULL,
    actor_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    payload_hash text NOT NULL,
    expected_paid_amount numeric(15,2) NOT NULL,
    gross_amount numeric(15,2) NOT NULL,
    retained_amount numeric(15,2) NOT NULL,
    applied_amount numeric(15,2) NOT NULL,
    change_amount numeric(15,2) DEFAULT 0 NOT NULL,
    credit_amount numeric(15,2) DEFAULT 0 NOT NULL,
    rounding_amount numeric(15,2) DEFAULT 0 NOT NULL,
    notes text,
    receipt_image_url text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_date date,
    reversal_reason text,
    reversal_idempotency_key text,
    CONSTRAINT invoice_payment_collections_amounts_check CHECK (((expected_paid_amount <> 'NaN'::numeric) AND (gross_amount <> 'NaN'::numeric) AND (retained_amount <> 'NaN'::numeric) AND (applied_amount <> 'NaN'::numeric) AND (change_amount <> 'NaN'::numeric) AND (credit_amount <> 'NaN'::numeric) AND (rounding_amount <> 'NaN'::numeric) AND (gross_amount > (0)::numeric) AND (retained_amount >= (0)::numeric) AND (applied_amount > (0)::numeric) AND (change_amount >= (0)::numeric) AND (credit_amount >= (0)::numeric) AND (rounding_amount >= (0)::numeric) AND (gross_amount = (retained_amount + change_amount)) AND (retained_amount = (applied_amount + credit_amount)))),
    CONSTRAINT invoice_payment_collections_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'REVERSED'::text])))
);








