);








--
-- Name: legacy_payment_receipt_semantics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.legacy_payment_receipt_semantics WITH (security_invoker='true') AS
 WITH returned_change_expenses AS (
         SELECT expense.id,
            expense.organization_id,
            expense.invoice_id,
            expense.voucher_date,
            expense.total_amount AS change_amount
           FROM public.income_expenses expense
          WHERE ((expense.payment_collection_id IS NULL) AND (expense.payment_id IS NULL) AND (expense.type = 'EXPENSE'::text) AND (expense.approval_status = 'APPROVED'::text) AND (expense.deleted_at IS NULL) AND (expense.total_amount > (0)::numeric) AND (lower(btrim(expense.name)) ~~ ANY (ARRAY['tiền thối hoá đơn%'::text, 'tiền thối hóa đơn%'::text])))
        ), change_candidate_base AS (
         SELECT DISTINCT expense.id AS expense_id,
            expense.change_amount,
            payment.id AS payment_id,
                CASE (payment.payment_method)::text
                    WHEN 'TM'::text THEN 0
                    WHEN 'TK'::text THEN 1
                    ELSE 2
                END AS method_priority,
            payment.amount AS payment_amount
           FROM ((returned_change_expenses expense
             JOIN public.income_expenses source_voucher ON (((source_voucher.organization_id = expense.organization_id) AND (source_voucher.invoice_id = expense.invoice_id) AND (source_voucher.voucher_date = expense.voucher_date) AND (source_voucher.type = 'INCOME'::text) AND (source_voucher.deleted_at IS NULL) AND (source_voucher.payment_id IS NOT NULL))))
             JOIN public.payments payment ON (((payment.id = source_voucher.payment_id) AND (payment.organization_id = expense.organization_id) AND (payment.collection_id IS NULL) AND (payment.amount >= expense.change_amount))))
        ), ranked_change_candidates AS (
         SELECT candidate.expense_id,
            candidate.change_amount,
            candidate.payment_id,
            candidate.method_priority,
            candidate.payment_amount,
            dense_rank() OVER (PARTITION BY candidate.expense_id ORDER BY candidate.method_priority, candidate.payment_amount DESC) AS preference_rank,
            count(*) OVER (PARTITION BY candidate.expense_id, candidate.method_priority, candidate.payment_amount) AS preference_peer_count
           FROM change_candidate_base candidate
        ), change_candidate_summary AS (
         SELECT expense.id AS expense_id,
            (count(candidate.payment_id))::integer AS candidate_count,
            (count(candidate.payment_id) FILTER (WHERE (candidate.preference_rank = 1)))::integer AS top_candidate_count
           FROM (returned_change_expenses expense
             LEFT JOIN ranked_change_candidates candidate ON ((candidate.expense_id = expense.id)))
          GROUP BY expense.id
        ), paired_change_expenses AS (
         SELECT candidate.expense_id,
            candidate.payment_id,
            candidate.change_amount
           FROM ranked_change_candidates candidate
          WHERE ((candidate.preference_rank = 1) AND (candidate.preference_peer_count = 1))
        ), paired_change_by_payment AS (
         SELECT pair.payment_id,
            sum(pair.change_amount) AS change_amount,
            (count(*))::integer AS expense_count
           FROM paired_change_expenses pair
          GROUP BY pair.payment_id
        ), unresolved_change_by_invoice_date AS (
         SELECT expense.organization_id,
            expense.invoice_id,
            expense.voucher_date,
            (count(*))::integer AS expense_count
           FROM (returned_change_expenses expense
             JOIN change_candidate_summary summary ON ((summary.expense_id = expense.id)))
          WHERE (summary.top_candidate_count <> 1)
          GROUP BY expense.organization_id, expense.invoice_id, expense.voucher_date
        ), semantic_base AS (
         SELECT payment.id,
            payment.organization_id,
            payment.invoice_id,
            payment.payment_method,
            payment.payment_date,
            payment.receipt_number,
            payment.receipt_image_url,
            payment.created_at,
            payment.reversed_at,
            source_voucher.id AS voucher_id,
            source_voucher.account_id,
            source_voucher.total_amount AS voucher_total_amount,
            source_stats.voucher_count,
            payment.amount AS stored_payment_amount,
            COALESCE(paired_change.change_amount, (0)::numeric) AS gross_era_change_amount,
            COALESCE(paired_change.expense_count, 0) AS gross_era_expense_count,
            COALESCE(unresolved_change.expense_count, 0) AS unresolved_change_expense_count,
            COALESCE(payment.received_amount,
                CASE
                    WHEN ((payment.change_amount > (0)::numeric) OR (COALESCE(source_voucher.change_amount, (0)::numeric) > (0)::numeric)) THEN payment.amount
                    ELSE GREATEST((payment.amount - COALESCE(paired_change.change_amount, (0)::numeric)), (0)::numeric)
                END) AS retained_amount,
            GREATEST(COALESCE(NULLIF(payment.credit_amount, (0)::numeric), NULLIF(credit.total_amount, (0)::numeric), (0)::numeric), (0)::numeric) AS credit_amount,
            GREATEST(COALESCE(NULLIF(payment.change_amount, (0)::numeric), NULLIF(source_voucher.change_amount, (0)::numeric), (0)::numeric), (0)::numeric) AS metadata_change_amount,
            GREATEST(COALESCE(NULLIF(payment.change_amount, (0)::numeric), NULLIF(source_voucher.change_amount, (0)::numeric), NULLIF(paired_change.change_amount, (0)::numeric), (0)::numeric), (0)::numeric) AS change_amount,
            GREATEST(COALESCE(NULLIF(payment.rounding_amount, (0)::numeric), NULLIF(source_voucher.rounding_amount, (0)::numeric), (0)::numeric), (0)::numeric) AS rounding_amount
           FROM (((((public.payments payment
             LEFT JOIN LATERAL ( SELECT (count(*))::integer AS voucher_count,
                    (array_agg(income.id ORDER BY (income.approval_status = 'APPROVED'::text) DESC, income.created_at, income.id))[1] AS voucher_id
                   FROM public.income_expenses income
                  WHERE ((income.payment_id = payment.id) AND (income.organization_id = payment.organization_id) AND (income.type = 'INCOME'::text) AND (income.deleted_at IS NULL))) source_stats ON (true))
             LEFT JOIN public.income_expenses source_voucher ON ((source_voucher.id = source_stats.voucher_id)))
             LEFT JOIN paired_change_by_payment paired_change ON ((paired_change.payment_id = payment.id)))
             LEFT JOIN unresolved_change_by_invoice_date unresolved_change ON (((unresolved_change.organization_id = payment.organization_id) AND (unresolved_change.invoice_id = payment.invoice_id) AND (unresolved_change.voucher_date = payment.payment_date))))
             LEFT JOIN LATERAL ( SELECT COALESCE(sum(GREATEST(excess.amount, (0)::numeric)), (0)::numeric) AS total_amount
                   FROM public.excess_amounts excess
                  WHERE (excess.source_payment_id = payment.id)) credit ON (true))
          WHERE (payment.collection_id IS NULL)
        )
 SELECT id,
    organization_id,
    invoice_id,
    payment_method,
    payment_date,
    (retained_amount + change_amount) AS gross_amount,
    retained_amount,
    GREATEST((retained_amount - credit_amount), (0)::numeric) AS applied_amount,
    credit_amount,
    change_amount,
    rounding_amount,
    receipt_number,
    receipt_image_url,
    created_at,
    reversed_at,
    voucher_id,
    account_id,
    voucher_total_amount,
    voucher_count,
    stored_payment_amount,
    metadata_change_amount,
    gross_era_change_amount,
    gross_era_expense_count,
    unresolved_change_expense_count
   FROM semantic_base semantic;








--
-- Name: VIEW legacy_payment_receipt_semantics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.legacy_payment_receipt_semantics IS 'Normalized legacy receipt semantics: retained metadata rows stay net; only exact live gross-era change vouchers are subtracted.';








--
-- Name: active_payment_receipts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_payment_receipts WITH (security_invoker='true') AS
 SELECT tender.id,
    'COLLECTION_TENDER'::text AS source_kind,
    tender.payment_id,
    collection.id AS collection_id,
    collection.organization_id,
    collection.invoice_id,
    tender.payment_method,
    collection.collection_date AS payment_date,
    tender.gross_amount,
    tender.retained_amount AS collected_amount,
    tender.applied_amount,
    tender.credit_amount,
    tender.change_amount,
    tender.rounding_amount,
    tender.receipt_number,
        CASE
            WHEN (tender.line_index = 0) THEN collection.receipt_image_url
            ELSE NULL::text
        END AS receipt_image_url,
    tender.created_at,
    tender.voucher_id,
    tender.account_id
   FROM (public.invoice_payment_tenders tender
     JOIN public.invoice_payment_collections collection ON (((collection.id = tender.collection_id) AND (collection.organization_id = tender.organization_id))))
  WHERE (collection.status = 'ACTIVE'::text)
UNION ALL
 SELECT legacy.id,
    'LEGACY_PAYMENT'::text AS source_kind,
    legacy.id AS payment_id,
    NULL::uuid AS collection_id,
    legacy.organization_id,
    legacy.invoice_id,
    legacy.payment_method,
    legacy.payment_date,
    legacy.gross_amount,
    legacy.retained_amount AS collected_amount,
    legacy.applied_amount,
    legacy.credit_amount,
    legacy.change_amount,
    legacy.rounding_amount,
    legacy.receipt_number,
    legacy.receipt_image_url,
    legacy.created_at,
    legacy.voucher_id,
    legacy.account_id
   FROM public.legacy_payment_receipt_semantics legacy
  WHERE (legacy.reversed_at IS NULL);








--
-- Name: VIEW active_payment_receipts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.active_payment_receipts IS 'Active cash receipt lines. collected_amount includes customer credit but excludes returned change.';








--
-- Name: active_payments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_payments WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    invoice_id,
    receipt_number,
    amount,
    payment_method,
    payment_date,
    notes,
    receipt_image_url,
    created_at,
    updated_at,
    organization_id,
    collection_id,
    tender_id,
    received_amount,
    credit_amount,
    change_amount,
    rounding_amount,
    reversed_at,
    reversed_by_collection_id
   FROM public.payments payment
  WHERE (reversed_at IS NULL);








