    request_version bigint NOT NULL,
    CONSTRAINT approval_decisions_check1 CHECK (((decision <> 'EMERGENCY_APPROVE'::text) OR ((reason IS NOT NULL) AND (length(btrim(reason)) >= 20)))),
    CONSTRAINT approval_decisions_decision_candidate_check CHECK ((((decision = ANY (ARRAY['APPROVE'::text, 'REJECT'::text])) AND (candidate_id IS NOT NULL)) OR ((decision = ANY (ARRAY['EMERGENCY_APPROVE'::text, 'CHECKER_APPROVE'::text, 'CHECKER_REJECT'::text, 'SELF_APPROVED_WITHIN_LIMIT'::text, 'REVERSAL_POSTED'::text])) AND (candidate_id IS NULL)))),
    CONSTRAINT approval_decisions_decision_check CHECK ((decision = ANY (ARRAY['APPROVE'::text, 'REJECT'::text, 'EMERGENCY_APPROVE'::text, 'CHECKER_APPROVE'::text, 'CHECKER_REJECT'::text, 'SELF_APPROVED_WITHIN_LIMIT'::text, 'REVERSAL_POSTED'::text])))
);








