    CONSTRAINT approval_requests_state_check CHECK ((state = ANY (ARRAY['PENDING_APPROVAL'::text, 'POSTED'::text, 'DENIED'::text, 'REJECTED'::text, 'CANCELLED'::text, 'REVERSED'::text, 'APPROVED'::text, 'WITHDRAWN'::text, 'CHANGES_REQUESTED'::text, 'DISPUTED'::text])))
