    effect text NOT NULL,
    transaction_type text,
    category_id uuid,
    cashbook_id uuid,
    building_id uuid,
    area_id uuid,
    system_source text,
    amount_min numeric(18,2),
    amount_max numeric(18,2),
    is_fallback boolean DEFAULT false NOT NULL,
    force_match boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    CONSTRAINT approval_rules_amount_max_check CHECK (((amount_max IS NULL) OR (amount_max >= (0)::numeric))),
    CONSTRAINT approval_rules_amount_min_check CHECK (((amount_min IS NULL) OR (amount_min >= (0)::numeric))),
    CONSTRAINT approval_rules_check CHECK (((amount_max IS NULL) OR (amount_min IS NULL) OR (amount_max >= amount_min))),
    CONSTRAINT approval_rules_check1 CHECK ((is_fallback OR (transaction_type IS NOT NULL) OR force_match OR (system_source IS NOT NULL) OR (category_id IS NOT NULL))),
    CONSTRAINT approval_rules_check2 CHECK (((NOT is_fallback) OR ((effect = 'REQUIRE_APPROVAL'::text) AND (transaction_type IS NULL) AND (category_id IS NULL) AND (cashbook_id IS NULL) AND (building_id IS NULL) AND (area_id IS NULL) AND (system_source IS NULL) AND (amount_min IS NULL) AND (amount_max IS NULL) AND (NOT force_match)))),
    CONSTRAINT approval_rules_effect_check CHECK ((effect = ANY (ARRAY['AUTO_POST'::text, 'REQUIRE_APPROVAL'::text, 'DENY'::text])))
);








