-- Name: authorization_scopes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.authorization_scopes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    scope_type text NOT NULL,
    area_id uuid,
    building_id uuid,
    cashbook_id uuid,
    CONSTRAINT authorization_scopes_check CHECK ((((scope_type = 'ORGANIZATION'::text) AND (area_id IS NULL) AND (building_id IS NULL) AND (cashbook_id IS NULL)) OR ((scope_type = 'AREA'::text) AND (area_id IS NOT NULL) AND (building_id IS NULL) AND (cashbook_id IS NULL)) OR ((scope_type = 'BUILDING'::text) AND (building_id IS NOT NULL) AND (area_id IS NULL) AND (cashbook_id IS NULL)) OR ((scope_type = 'CASHBOOK'::text) AND (cashbook_id IS NOT NULL) AND (area_id IS NULL) AND (building_id IS NULL)))),
    CONSTRAINT authorization_scopes_scope_type_check CHECK ((scope_type = ANY (ARRAY['ORGANIZATION'::text, 'AREA'::text, 'BUILDING'::text, 'CASHBOOK'::text])))
);








