--
-- Name: building_coverage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.building_coverage WITH (security_invoker='true') AS
 WITH touches AS (
         SELECT j.building_id,
            public.vn_local_date(COALESCE(j.completion_time, j.created_at)) AS d,
            'job'::text AS src
           FROM public.jobs j
          WHERE ((j.status = 'COMPLETED'::text) AND (((jsonb_typeof(COALESCE(j.completion_attachments, '[]'::jsonb)) = 'array'::text) AND (jsonb_array_length(COALESCE(j.completion_attachments, '[]'::jsonb)) > 0)) OR ((jsonb_typeof(COALESCE(j.attachments, '[]'::jsonb)) = 'array'::text) AND (jsonb_array_length(COALESCE(j.attachments, '[]'::jsonb)) > 0))))
        UNION ALL
         SELECT s.building_id,
            s.session_date,
            'inspection'::text AS text
           FROM public.inspection_sessions s
          WHERE (s.status = ANY (ARRAY['passed'::text, 'quick_done'::text, 'presence'::text]))
        UNION ALL
         SELECT ie.building_id,
            public.vn_local_date(ie.created_at) AS vn_local_date,
            'payment'::text AS text
           FROM public.income_expenses ie
          WHERE ((ie.collect_geofence_status = 'ok'::text) AND (ie.building_id IS NOT NULL))
        ), fulls AS (
         SELECT s.building_id,
            max(s.session_date) AS last_full_date
           FROM public.inspection_sessions s
          WHERE ((s.type = 'FULL'::text) AND (s.status = 'passed'::text))
          GROUP BY s.building_id
        ), jobs30 AS (
         SELECT j.building_id,
            count(*) AS jobs_30d
           FROM public.jobs j
          WHERE ((j.status = 'COMPLETED'::text) AND (COALESCE(j.completion_time, j.created_at) >= (now() - '30 days'::interval)))
          GROUP BY j.building_id
        )
 SELECT b.id AS building_id,
    b.name AS building_name,
    b.cluster_id,
    ( SELECT count(*) AS count
           FROM public.rooms r
          WHERE (r.building_id = b.id)) AS rooms_total,
    ( SELECT count(*) AS count
           FROM public.rooms r
          WHERE ((r.building_id = b.id) AND (r.status = 'AVAILABLE'::public.room_status))) AS vacant_rooms,
    COALESCE(j30.jobs_30d, (0)::bigint) AS jobs_30d,
    t.last_touch_date,
    f.last_full_date,
    (public.vn_local_date(now()) - t.last_touch_date) AS days_since_touch,
    (public.vn_local_date(now()) - f.last_full_date) AS days_since_full
   FROM (((public.buildings b
     LEFT JOIN ( SELECT touches.building_id,
            max(touches.d) AS last_touch_date
           FROM touches
          GROUP BY touches.building_id) t ON ((t.building_id = b.id)))
     LEFT JOIN fulls f ON ((f.building_id = b.id)))
     LEFT JOIN jobs30 j30 ON ((j30.building_id = b.id)));








--
-- Name: VIEW building_coverage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.building_coverage IS 'v5: đồng hồ D per toà từ 3 nguồn dấu chân (job/inspection/payment-GPS). VIEW derive — không materialize phase này.';








