    total_deposit numeric(15,2) DEFAULT 0 NOT NULL,
    deposit_paid numeric(15,2) DEFAULT 0,
    deposit_remaining numeric(15,2) GENERATED ALWAYS AS ((total_deposit - COALESCE(deposit_paid, (0)::numeric))) STORED,
    discounts jsonb DEFAULT '[]'::jsonb,
