    parent_contract_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    contract_template_id uuid,
    invoice_template_id uuid,
    expected_move_out_date date,
    start_billing_date date,
    end_billing_date date,
    public_code text NOT NULL,
    deposit_debt_acknowledged boolean DEFAULT false NOT NULL,
    deposit_debt_mode text,
    deposit_debt_reason text,
    deposit_topup_due_date date,
    organization_id uuid,
    CONSTRAINT contracts_dates_valid CHECK ((start_date <= end_date)),
    CONSTRAINT contracts_deposit_debt_mode_check CHECK (((deposit_debt_mode IS NULL) OR (deposit_debt_mode = ANY (ARRAY['DEBT'::text, 'FIRST_INVOICE'::text])))),
    CONSTRAINT contracts_deposit_paid_non_negative CHECK ((deposit_paid >= (0)::numeric)),
    CONSTRAINT contracts_rent_price_non_negative CHECK ((rent_price >= (0)::numeric)),
    CONSTRAINT contracts_total_deposit_non_negative CHECK ((total_deposit >= (0)::numeric))
);








