--
-- Name: contract_extension_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_extension_history WITH (security_invoker='true') AS
 SELECT ce.id AS extension_id,
    ce.contract_id,
    c.contract_number,
    c.tenant_id,
    t.full_name AS tenant_name,
    ce.extension_type,
    ce.extension_date,
    ce.old_end_date,
    ce.new_end_date,
    ce.extension_months,
    ce.rent_price_changed,
    COALESCE(ce.new_rent_price, c.rent_price) AS rent_price,
    ce.status,
    ce.approved_at,
    ce.created_at
   FROM ((public.contract_extensions ce
     JOIN public.contracts c ON ((c.id = ce.contract_id)))
     JOIN public.tenants t ON ((t.id = c.tenant_id)))
  WHERE (ce.status <> 'CANCELLED'::text)
  ORDER BY ce.extension_date DESC;








--
-- Name: VIEW contract_extension_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.contract_extension_history IS 'Summary view of all contract extensions with tenant info';








