--
-- Name: contract_terminations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contract_terminations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    termination_date date DEFAULT CURRENT_DATE NOT NULL,
    actual_move_out_date date NOT NULL,
    notice_date date,
    termination_type text NOT NULL,
    outstanding_debt numeric(15,2) DEFAULT 0,
    prorated_days integer DEFAULT 0,
    prorated_rent numeric(15,2) DEFAULT 0,
    prorated_services numeric(15,2) DEFAULT 0,
    early_termination_fee numeric(15,2) DEFAULT 0,
    notice_violation_fee numeric(15,2) DEFAULT 0,
    damage_fee numeric(15,2) DEFAULT 0,
    damage_description text,
    damage_images jsonb DEFAULT '[]'::jsonb,
    cleaning_fee numeric(15,2) DEFAULT 0,
    other_fees numeric(15,2) DEFAULT 0,
    other_fees_description text,
    total_deposit numeric(15,2) NOT NULL,
    total_deductions numeric(15,2) GENERATED ALWAYS AS ((((((((COALESCE(outstanding_debt, (0)::numeric) + COALESCE(prorated_rent, (0)::numeric)) + COALESCE(prorated_services, (0)::numeric)) + COALESCE(early_termination_fee, (0)::numeric)) + COALESCE(notice_violation_fee, (0)::numeric)) + COALESCE(damage_fee, (0)::numeric)) + COALESCE(cleaning_fee, (0)::numeric)) + COALESCE(other_fees, (0)::numeric))) STORED,
    refund_amount numeric(15,2) GENERATED ALWAYS AS ((total_deposit - (((((((COALESCE(outstanding_debt, (0)::numeric) + COALESCE(prorated_rent, (0)::numeric)) + COALESCE(prorated_services, (0)::numeric)) + COALESCE(early_termination_fee, (0)::numeric)) + COALESCE(notice_violation_fee, (0)::numeric)) + COALESCE(damage_fee, (0)::numeric)) + COALESCE(cleaning_fee, (0)::numeric)) + COALESCE(other_fees, (0)::numeric)))) STORED,
    refund_method public.payment_method,
    refund_date date,
    refund_receipt_url text,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    notes text,
    internal_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid,
    CONSTRAINT contract_terminations_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text, 'COMPLETED'::text]))),
    CONSTRAINT contract_terminations_termination_type_check CHECK ((termination_type = ANY (ARRAY['NORMAL'::text, 'EARLY_TENANT'::text, 'EARLY_OWNER'::text, 'BREACH'::text, 'FORFEIT'::text]))),
    CONSTRAINT terminations_refund_method_required_if_refund CHECK (((refund_amount <= (0)::numeric) OR (refund_method IS NOT NULL)))
);








--
-- Name: TABLE contract_terminations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contract_terminations IS 'Contract termination records with automatic financial calculations';








