CREATE TABLE public.contract_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    transfer_type text NOT NULL,
    transfer_date date DEFAULT CURRENT_DATE NOT NULL,
    old_tenant_id uuid,
    new_tenant_id uuid,
    transfer_fee numeric(15,2) DEFAULT 0,
    old_room_id uuid,
    new_room_id uuid,
    new_rent_price numeric(15,2),
    new_deposit numeric(15,2),
    move_out_date date,
    move_in_date date,
    new_start_date date,
    new_end_date date,
    new_services jsonb DEFAULT '[]'::jsonb,
    deposit_transfer_type text,
    old_tenant_deposit_refund numeric(15,2) DEFAULT 0,
    new_tenant_deposit_paid numeric(15,2) DEFAULT 0,
    old_tenant_outstanding numeric(15,2) DEFAULT 0,
    old_tenant_settlement_amount numeric(15,2) DEFAULT 0,
    old_tenant_settlement_date date,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    reason text,
    notes text,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid,
    CONSTRAINT contract_transfers_deposit_transfer_type_check CHECK ((deposit_transfer_type = ANY (ARRAY['KEEP_EXISTING'::text, 'TRANSFER_TO_NEW'::text, 'REFUND_OLD'::text]))),
    CONSTRAINT contract_transfers_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'APPROVED'::text, 'COMPLETED'::text, 'CANCELLED'::text]))),
    CONSTRAINT contract_transfers_transfer_type_check CHECK ((transfer_type = ANY (ARRAY['TENANT_CHANGE'::text, 'ROOM_CHANGE'::text, 'BOTH_CHANGE'::text]))),
    CONSTRAINT transfers_move_dates_valid CHECK (((move_out_date IS NULL) OR (move_in_date IS NULL) OR (move_out_date <= move_in_date))),
    CONSTRAINT transfers_tenant_change_requires_new_party CHECK (((transfer_type <> 'TENANT_CHANGE'::text) OR (new_tenant_id IS NOT NULL))),
    CONSTRAINT transfers_transfer_fee_non_negative CHECK ((transfer_fee >= (0)::numeric))
);








