    reversal_reason text,
    restored_at timestamp with time zone,
    restored_by uuid,
    restoration_idempotency_key text,
    CONSTRAINT customer_credit_applications_amount_check CHECK (((amount <> 'NaN'::numeric) AND (amount > (0)::numeric))),
    CONSTRAINT customer_credit_applications_kind_check CHECK ((application_kind = ANY (ARRAY['INVOICE_DISCOUNT'::text, 'MOVE_OUT'::text, 'FORFEIT'::text, 'MANUAL'::text, 'LEGACY_BACKFILL'::text]))),
    CONSTRAINT customer_credit_applications_reversal_check CHECK ((((reversed_at IS NULL) AND (reversed_by IS NULL) AND (reversal_excess_amount_id IS NULL) AND (reversal_idempotency_key IS NULL) AND (reversal_reason IS NULL) AND (restored_at IS NULL) AND (restored_by IS NULL) AND (restoration_idempotency_key IS NULL)) OR ((reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL) AND (reversal_excess_amount_id IS NOT NULL) AND (reversal_idempotency_key IS NOT NULL) AND (reversal_reason IS NOT NULL) AND (((restored_at IS NULL) AND (restored_by IS NULL) AND (restoration_idempotency_key IS NULL)) OR ((restored_at IS NOT NULL) AND (restored_by IS NOT NULL) AND (restoration_idempotency_key IS NOT NULL))))))
);








