    CONSTRAINT customer_credit_lots_amount_check CHECK (((amount <> 'NaN'::numeric) AND (remaining_amount <> 'NaN'::numeric) AND (amount > (0)::numeric) AND (remaining_amount >= (0)::numeric) AND (remaining_amount <= amount))),
    CONSTRAINT customer_credit_lots_origin_check CHECK (((source_collection_id IS NOT NULL) OR ((source_collection_id IS NULL) AND (source_tender_id IS NULL) AND (source_excess_amount_id IS NOT NULL)))),
    CONSTRAINT customer_credit_lots_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'CONSUMED'::text, 'REVERSED'::text])))
);








