--
-- Name: finance_month_snapshot_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finance_month_snapshot_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    snapshot_month date NOT NULL,
    as_of_date date,
    as_of_timestamp timestamp with time zone,
    scheduled_for timestamp with time zone NOT NULL,
    captured_at timestamp with time zone,
    finalized_at timestamp with time zone,
    status text DEFAULT 'PROVISIONAL'::text NOT NULL,
    capture_version integer DEFAULT 1 NOT NULL,
    source_timezone text DEFAULT 'Asia/Ho_Chi_Minh'::text NOT NULL,
    is_late boolean DEFAULT false NOT NULL,
    late_reason text,
    room_count integer,
    contract_count integer,
    validation_summary jsonb,
    capture_source text DEFAULT 'CRON'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT finance_month_snapshot_runs_counts_check CHECK ((((room_count IS NULL) OR (room_count >= 0)) AND ((contract_count IS NULL) OR (contract_count >= 0)))),
    CONSTRAINT finance_month_snapshot_runs_month_start_check CHECK ((snapshot_month = (date_trunc('month'::text, (snapshot_month)::timestamp with time zone))::date)),
    CONSTRAINT finance_month_snapshot_runs_source_check CHECK ((capture_source = ANY (ARRAY['ROLLOUT'::text, 'CRON'::text, 'MONITOR'::text]))),
    CONSTRAINT finance_month_snapshot_runs_state_check CHECK ((((status = ANY (ARRAY['PROVISIONAL'::text, 'FINALIZED'::text])) AND (as_of_date IS NOT NULL) AND (as_of_timestamp IS NOT NULL) AND (captured_at IS NOT NULL) AND (room_count IS NOT NULL) AND (contract_count IS NOT NULL) AND (validation_summary IS NOT NULL)) OR ((status = 'MISSED'::text) AND (finalized_at IS NULL) AND (room_count IS NULL) AND (contract_count IS NULL)))),
    CONSTRAINT finance_month_snapshot_runs_status_check CHECK ((status = ANY (ARRAY['PROVISIONAL'::text, 'FINALIZED'::text, 'MISSED'::text]))),
    CONSTRAINT finance_month_snapshot_runs_timezone_check CHECK ((source_timezone = 'Asia/Ho_Chi_Minh'::text))
);








