--
-- Name: invoice_pnl_cash_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.invoice_pnl_cash_entries WITH (security_invoker='true') AS
 SELECT voucher.id,
    voucher.organization_id,
    COALESCE(voucher.invoice_id, source_voucher.invoice_id, collection.invoice_id) AS invoice_id,
    COALESCE(voucher.building_id, source_voucher.building_id, invoice_row.building_id) AS building_id,
    voucher.voucher_date AS revenue_date,
        CASE voucher.type
            WHEN 'INCOME'::text THEN voucher.kqkd_amount
            WHEN 'EXPENSE'::text THEN (- voucher.kqkd_amount)
            ELSE (0)::numeric
        END AS pnl_amount
   FROM (((public.income_expenses voucher
     LEFT JOIN public.income_expenses source_voucher ON ((source_voucher.id = voucher.reversal_of_income_expense_id)))
     LEFT JOIN public.invoice_payment_collections collection ON ((collection.id = voucher.payment_collection_id)))
     LEFT JOIN public.invoices invoice_row ON ((invoice_row.id = COALESCE(voucher.invoice_id, source_voucher.invoice_id, collection.invoice_id))))
  WHERE ((voucher.approval_status = 'APPROVED'::text) AND (voucher.deleted_at IS NULL) AND (voucher.kqkd_amount > (0)::numeric) AND (((voucher.type = 'INCOME'::text) AND (COALESCE(voucher.invoice_id, collection.invoice_id) IS NOT NULL)) OR ((voucher.type = 'EXPENSE'::text) AND (voucher.reversal_of_income_expense_id IS NOT NULL))));








--
-- Name: VIEW invoice_pnl_cash_entries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.invoice_pnl_cash_entries IS 'Signed invoice-linked cash P&L entries. Deposit and customer credit have pnl_amount zero.';








