    building_id uuid,
    room_id uuid,
    appointment_date timestamp with time zone,
    assigned_staff_id uuid,
    status public.lead_status DEFAULT 'B1_LEAD'::public.lead_status,
    deposit_id uuid,
    contract_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lead_score integer DEFAULT 0,
    budget_min numeric(15,2),
    budget_max numeric(15,2),
    move_in_date date,
    num_occupants integer DEFAULT 1,
    preferred_room_type character varying(50),
    last_contact_date timestamp without time zone,
    next_follow_up_date date,
    lost_reason text,
    conversion_date timestamp without time zone,
    deleted_at timestamp without time zone,
    referrer_name text,
    ctv_name text,
    finder_name text,
    organization_id uuid,
    openclaw_assignment_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT leads_customer_name_not_empty CHECK ((char_length(customer_name) > 0)),
    CONSTRAINT leads_openclaw_assignment_revision_check CHECK ((openclaw_assignment_revision > 0)),
    CONSTRAINT leads_phone_format CHECK ((phone ~ '^[0-9]{10,11}$'::text))
);








