--
-- Name: meter_readings_detailed; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.meter_readings_detailed WITH (security_invoker='true') AS
 SELECT mr.id,
    mr.user_id,
    mr.reading_code,
    mr.meter_id,
    m.code AS meter_code,
    m.name AS meter_name,
    mr.contract_id,
    mr.service_id,
    s.name AS service_name,
    mr.building_id,
    b.name AS building_name,
    mr.room_id,
    r.name AS room_name,
    mr.meter_type,
    mr.settlement_month,
    mr.reading_date,
    mr.previous_reading,
    mr.current_reading,
    mr.consumption,
    mr.status,
    mr.approved_by,
    (approver.email)::character varying(255) AS approver_email,
    mr.approved_at,
    mr.recorded_by,
    (recorder.email)::character varying(255) AS recorder_email,
    mr.notes,
    mr.meter_image_url,
    mr.created_at,
    mr.updated_at
   FROM ((((((public.meter_readings mr
     LEFT JOIN public.meters m ON ((m.id = mr.meter_id)))
     LEFT JOIN public.buildings b ON ((b.id = mr.building_id)))
     LEFT JOIN public.rooms r ON ((r.id = mr.room_id)))
     LEFT JOIN public.services s ON ((s.id = mr.service_id)))
     LEFT JOIN public.profiles approver ON ((approver.id = mr.approved_by)))
     LEFT JOIN public.profiles recorder ON ((recorder.id = mr.recorded_by)))
  WHERE (mr.deleted_at IS NULL);








--
-- Name: VIEW meter_readings_detailed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.meter_readings_detailed IS 'Detailed view of meter readings with meter, building, room, and user information';








--
-- Name: meters_with_latest_reading; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.meters_with_latest_reading WITH (security_invoker='true') AS
 SELECT m.id,
    m.user_id,
    m.code,
    m.name,
    m.building_id,
    b.name AS building_name,
    m.room_id,
    r.name AS room_name,
    m.service_id,
    s.name AS service_name,
    m.meter_type,
    m.status,
    m.installation_date,
    m.initial_reading,
    ( SELECT meter_readings.current_reading
           FROM public.meter_readings
          WHERE ((meter_readings.meter_id = m.id) AND (meter_readings.deleted_at IS NULL))
          ORDER BY meter_readings.reading_date DESC, meter_readings.created_at DESC
         LIMIT 1) AS latest_reading,
    ( SELECT meter_readings.reading_date
           FROM public.meter_readings
          WHERE ((meter_readings.meter_id = m.id) AND (meter_readings.deleted_at IS NULL))
          ORDER BY meter_readings.reading_date DESC, meter_readings.created_at DESC
         LIMIT 1) AS latest_reading_date,
    ( SELECT count(*) AS count
           FROM public.meter_readings
          WHERE ((meter_readings.meter_id = m.id) AND (meter_readings.deleted_at IS NULL))) AS total_readings,
    m.location_note,
    m.manufacturer,
    m.model,
    m.serial_number,
    m.notes,
    m.created_at,
    m.updated_at
   FROM (((public.meters m
     LEFT JOIN public.buildings b ON ((b.id = m.building_id)))
     LEFT JOIN public.rooms r ON ((r.id = m.room_id)))
     LEFT JOIN public.services s ON ((s.id = m.service_id)))
  WHERE (m.deleted_at IS NULL)
  ORDER BY b.name, r.name, m.meter_type;








--
-- Name: VIEW meters_with_latest_reading; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.meters_with_latest_reading IS 'Meters with their latest reading information';








