    target_type text NOT NULL,
    target_id uuid,
    target_display jsonb NOT NULL,
    reason text NOT NULL,
    validation jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    outcome text NOT NULL,
    command_id uuid,
    request_id uuid,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    request_hash text,
    CONSTRAINT network_audit_events_action_check CHECK ((action ~ '^[a-z][a-z0-9_.-]{2,99}$'::text)),
    CONSTRAINT network_audit_events_actor_check CHECK ((((actor_type = 'USER'::text) AND (actor_id IS NOT NULL) AND (worker_id IS NULL)) OR ((actor_type = 'WORKER'::text) AND (actor_id IS NULL) AND (worker_id IS NOT NULL)) OR ((actor_type = 'SYSTEM'::text) AND (actor_id IS NULL) AND (worker_id IS NULL)))),
    CONSTRAINT network_audit_events_actor_type_check CHECK ((actor_type = ANY (ARRAY['USER'::text, 'WORKER'::text, 'SYSTEM'::text]))),
    CONSTRAINT network_audit_events_outcome_check CHECK ((outcome = ANY (ARRAY['ACCEPTED'::text, 'REJECTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'UNCERTAIN'::text, 'OBSERVED'::text]))),
    CONSTRAINT network_audit_events_payload_check CHECK (((jsonb_typeof(validation) = 'object'::text) AND (jsonb_typeof(result) = 'object'::text) AND (octet_length((validation)::text) <= 65536) AND (octet_length((result)::text) <= 65536))),
    CONSTRAINT network_audit_events_reason_check CHECK (((char_length(btrim(reason)) >= 3) AND (char_length(btrim(reason)) <= 1000))),
    CONSTRAINT network_audit_events_request_hash_check CHECK (((request_hash IS NULL) OR (request_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT network_audit_events_target_check CHECK ((target_type ~ '^[a-z][a-z0-9_.-]{2,63}$'::text)),
    CONSTRAINT network_audit_events_target_display_check CHECK (((jsonb_typeof(target_display) = 'object'::text) AND (octet_length((target_display)::text) <= 16384))),
    CONSTRAINT network_audit_events_worker_check CHECK (((worker_id IS NULL) OR (worker_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'::text)))
);








