    CONSTRAINT network_client_current_hostname_check CHECK (((hostname IS NULL) OR (char_length(hostname) <= 255))),
    CONSTRAINT network_client_current_rate_check CHECK ((((rx_bps IS NULL) OR (rx_bps >= (0)::numeric)) AND ((tx_bps IS NULL) OR (tx_bps >= (0)::numeric)))),
    CONSTRAINT network_client_current_seq_check CHECK ((update_seq > 0)),
    CONSTRAINT network_client_current_session_check CHECK (((char_length(btrim(session_key)) >= 8) AND (char_length(btrim(session_key)) <= 200))),
    CONSTRAINT network_client_current_session_type_check CHECK ((session_type = ANY (ARRAY['UNKNOWN'::text, 'DHCP'::text, 'HOTSPOT'::text, 'STATIC'::text, 'ARP'::text]))),
    CONSTRAINT network_client_current_signal_check CHECK (((signal_dbm IS NULL) OR ((signal_dbm >= '-150'::integer) AND (signal_dbm <= 20)))),
    CONSTRAINT network_client_current_time_check CHECK (((first_seen_at <= last_seen_at) AND (last_seen_at <= observed_at) AND (expires_at > last_seen_at))),
    CONSTRAINT network_client_current_traffic_check CHECK ((((rx_bytes IS NULL) OR (rx_bytes >= 0)) AND ((tx_bytes IS NULL) OR (tx_bytes >= 0)))),
    CONSTRAINT network_client_current_type_check CHECK ((connection_type = ANY (ARRAY['UNKNOWN'::text, 'ETHERNET'::text, 'WIFI'::text, 'VPN'::text])))
);








