COMMENT ON TABLE public.network_device_samples IS 'Append-only daily-partitioned raw device telemetry retained for 14 days.';








--
-- Name: network_devices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_devices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_kind text NOT NULL,
    external_key text NOT NULL,
    display_name text NOT NULL,
    vendor text NOT NULL,
    model text,
    serial_number text,
    desired_firmware text,
    parent_device_id uuid,
    uplink_interface_key text,
    sort_order integer DEFAULT 0 NOT NULL,
    lifecycle_status text DEFAULT 'UNPROVISIONED'::text NOT NULL,
    write_capability boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    credential_ref text,
    inventory_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    aruba_stable_key text,
    aruba_identity_source text,
    aruba_discovery_state text,
    aruba_discovery_first_seen_at timestamp with time zone,
    aruba_discovery_last_seen_at timestamp with time zone,
    CONSTRAINT network_devices_aruba_display_only CHECK ((((device_kind = 'ARUBA'::text) AND (write_capability = false) AND (credential_ref IS NULL)) OR (device_kind <> 'ARUBA'::text))),
    CONSTRAINT network_devices_aruba_stable_identity_check CHECK ((((device_kind = 'ARUBA'::text) AND (aruba_stable_key IS NOT NULL) AND (aruba_identity_source IS NOT NULL) AND (aruba_discovery_state = ANY (ARRAY['DISCOVERED'::text, 'PINNED'::text])) AND (parent_device_id IS NOT NULL) AND (aruba_discovery_first_seen_at IS NOT NULL) AND (aruba_discovery_last_seen_at IS NOT NULL) AND (aruba_discovery_last_seen_at >= aruba_discovery_first_seen_at) AND (((aruba_identity_source = 'SERIAL'::text) AND (aruba_stable_key ~ '^serial:[A-Z0-9][A-Z0-9._:-]{0,152}$'::text)) OR ((aruba_identity_source = 'HARDWARE_MAC'::text) AND (aruba_stable_key ~ '^mac:[0-9a-f][02468ace](:[0-9a-f]{2}){5}$'::text) AND (aruba_stable_key <> ALL (ARRAY['mac:00:00:00:00:00:00'::text, 'mac:ff:ff:ff:ff:ff:ff'::text]))) OR ((aruba_identity_source = 'LEGACY'::text) AND (aruba_stable_key ~ '^legacy:[a-f0-9]{64}$'::text)))) OR ((device_kind <> 'ARUBA'::text) AND (aruba_stable_key IS NULL) AND (aruba_identity_source IS NULL) AND (aruba_discovery_state IS NULL) AND (aruba_discovery_first_seen_at IS NULL) AND (aruba_discovery_last_seen_at IS NULL)))),
    CONSTRAINT network_devices_credential_ref_check CHECK (((credential_ref IS NULL) OR (((char_length(credential_ref) >= 3) AND (char_length(credential_ref) <= 255)) AND (credential_ref ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]+$'::text)))),
    CONSTRAINT network_devices_desired_firmware_check CHECK (((desired_firmware IS NULL) OR ((char_length(btrim(desired_firmware)) >= 1) AND (char_length(btrim(desired_firmware)) <= 80)))),
    CONSTRAINT network_devices_external_key_check CHECK (((char_length(btrim(external_key)) >= 1) AND (char_length(btrim(external_key)) <= 160))),
    CONSTRAINT network_devices_kind_check CHECK ((device_kind = ANY (ARRAY['MIKROTIK'::text, 'ARUBA'::text]))),
    CONSTRAINT network_devices_lifecycle_check CHECK ((lifecycle_status = ANY (ARRAY['UNPROVISIONED'::text, 'PROVISIONING'::text, 'ONLINE'::text, 'OFFLINE'::text, 'STALE'::text, 'DISABLED'::text]))),
    CONSTRAINT network_devices_metadata_object_check CHECK ((jsonb_typeof(inventory_metadata) = 'object'::text)),
    CONSTRAINT network_devices_name_check CHECK (((char_length(btrim(display_name)) >= 1) AND (char_length(btrim(display_name)) <= 160))),
    CONSTRAINT network_devices_parent_not_self_check CHECK (((parent_device_id IS NULL) OR (parent_device_id <> id))),
    CONSTRAINT network_devices_sort_order_check CHECK ((sort_order >= 0)),
    CONSTRAINT network_devices_uplink_key_check CHECK (((uplink_interface_key IS NULL) OR ((char_length(btrim(uplink_interface_key)) >= 1) AND (char_length(btrim(uplink_interface_key)) <= 160)))),
    CONSTRAINT network_devices_vendor_check CHECK (((char_length(btrim(vendor)) >= 1) AND (char_length(btrim(vendor)) <= 80)))
);








--
-- Name: TABLE network_devices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_devices IS 'Tenant-bound Network Center inventory. One active MikroTik per physical building; Aruba rows are display-only and have no count limit.';








--
-- Name: COLUMN network_devices.credential_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.network_devices.credential_ref IS 'Opaque reference resolved by the dedicated worker; never a credential value.';








--
-- Name: COLUMN network_devices.aruba_stable_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.network_devices.aruba_stable_key IS 'Router-scoped Aruba identity derived from serial first, otherwise validated unicast hardware MAC; never a mutable display alias.';








--
-- Name: network_incident_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_incident_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    incident_id uuid NOT NULL,
    event_seq bigint NOT NULL,
    event_kind text NOT NULL,
    severity text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    actor_id uuid,
    worker_id text,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    external_event_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_incident_events_actor_check CHECK (((actor_id IS NOT NULL) OR (worker_id IS NOT NULL))),
    CONSTRAINT network_incident_events_details_check CHECK (((jsonb_typeof(details) = 'object'::text) AND (octet_length((details)::text) <= 65536))),
    CONSTRAINT network_incident_events_external_key_check CHECK (((external_event_key IS NULL) OR ((char_length(external_event_key) >= 8) AND (char_length(external_event_key) <= 200)))),
    CONSTRAINT network_incident_events_kind_check CHECK ((event_kind = ANY (ARRAY['OPENED'::text, 'OBSERVED'::text, 'ESCALATED'::text, 'ACKNOWLEDGED'::text, 'RECOVERED'::text, 'RESOLVED'::text]))),
    CONSTRAINT network_incident_events_seq_check CHECK ((event_seq > 0)),
    CONSTRAINT network_incident_events_severity_check CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text]))),
    CONSTRAINT network_incident_events_worker_check CHECK (((worker_id IS NULL) OR (worker_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'::text)))
);








--
-- Name: network_incidents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_incidents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    interface_id uuid,
    fingerprint text NOT NULL,
    incident_type text NOT NULL,
    severity text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    title text NOT NULL,
    summary text NOT NULL,
    availability_impact boolean DEFAULT false NOT NULL,
    opened_at timestamp with time zone NOT NULL,
    last_observed_at timestamp with time zone NOT NULL,
    recovered_at timestamp with time zone,
    resolved_at timestamp with time zone,
    acknowledged_at timestamp with time zone,
    acknowledged_by uuid,
    occurrence_count integer DEFAULT 1 NOT NULL,
    observed_values jsonb DEFAULT '{}'::jsonb NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_incidents_ack_check CHECK (((acknowledged_at IS NULL) = (acknowledged_by IS NULL))),
    CONSTRAINT network_incidents_fingerprint_check CHECK (((char_length(btrim(fingerprint)) >= 8) AND (char_length(btrim(fingerprint)) <= 200))),
    CONSTRAINT network_incidents_occurrence_check CHECK ((occurrence_count > 0)),
    CONSTRAINT network_incidents_resolution_check CHECK (((status = 'RESOLVED'::text) = (resolved_at IS NOT NULL))),
    CONSTRAINT network_incidents_severity_check CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text]))),
    CONSTRAINT network_incidents_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RECOVERING'::text, 'RESOLVED'::text]))),
    CONSTRAINT network_incidents_text_check CHECK ((((char_length(btrim(title)) >= 3) AND (char_length(btrim(title)) <= 200)) AND ((char_length(btrim(summary)) >= 3) AND (char_length(btrim(summary)) <= 2000)))),
    CONSTRAINT network_incidents_time_check CHECK (((opened_at <= last_observed_at) AND ((recovered_at IS NULL) OR (recovered_at >= opened_at)) AND ((resolved_at IS NULL) OR (resolved_at >= opened_at)) AND ((acknowledged_at IS NULL) OR (acknowledged_at >= opened_at)))),
    CONSTRAINT network_incidents_type_check CHECK ((incident_type ~ '^[A-Z][A-Z0-9_]{2,63}$'::text)),
    CONSTRAINT network_incidents_values_check CHECK (((jsonb_typeof(observed_values) = 'object'::text) AND (octet_length((observed_values)::text) <= 16384))),
    CONSTRAINT network_incidents_version_check CHECK ((version > 0))
);








--
-- Name: network_interface_current; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_interface_current (
    interface_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    link_state text DEFAULT 'UNKNOWN'::text NOT NULL,
    rx_bps numeric(20,2),
    tx_bps numeric(20,2),
    utilization_pct numeric(7,3),
    rx_bytes bigint,
    tx_bytes bigint,
    error_count bigint,
    discard_count bigint,
    queue_drop_count bigint,
    update_seq bigint DEFAULT 1 NOT NULL,
    CONSTRAINT network_interface_current_counters_check CHECK ((((rx_bytes IS NULL) OR (rx_bytes >= 0)) AND ((tx_bytes IS NULL) OR (tx_bytes >= 0)) AND ((error_count IS NULL) OR (error_count >= 0)) AND ((discard_count IS NULL) OR (discard_count >= 0)) AND ((queue_drop_count IS NULL) OR (queue_drop_count >= 0)))),
    CONSTRAINT network_interface_current_link_check CHECK ((link_state = ANY (ARRAY['UNKNOWN'::text, 'UP'::text, 'DOWN'::text]))),
    CONSTRAINT network_interface_current_rate_check CHECK ((((rx_bps IS NULL) OR (rx_bps >= (0)::numeric)) AND ((tx_bps IS NULL) OR (tx_bps >= (0)::numeric)))),
    CONSTRAINT network_interface_current_seq_check CHECK ((update_seq > 0)),
    CONSTRAINT network_interface_current_utilization_check CHECK (((utilization_pct IS NULL) OR ((utilization_pct >= (0)::numeric) AND (utilization_pct <= (100)::numeric))))
);








--
-- Name: network_interface_samples; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_interface_samples (
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    interface_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    link_up boolean NOT NULL,
    rx_bps numeric(20,2),
    tx_bps numeric(20,2),
    utilization_pct numeric(7,3),
    error_delta bigint,
    discard_delta bigint,
    queue_drop_delta bigint,
    sample jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT network_interface_samples_delta_check CHECK ((((error_delta IS NULL) OR (error_delta >= 0)) AND ((discard_delta IS NULL) OR (discard_delta >= 0)) AND ((queue_drop_delta IS NULL) OR (queue_drop_delta >= 0)))),
    CONSTRAINT network_interface_samples_payload_check CHECK ((jsonb_typeof(sample) = 'object'::text)),
    CONSTRAINT network_interface_samples_rate_check CHECK ((((rx_bps IS NULL) OR (rx_bps >= (0)::numeric)) AND ((tx_bps IS NULL) OR (tx_bps >= (0)::numeric)))),
    CONSTRAINT network_interface_samples_utilization_check CHECK (((utilization_pct IS NULL) OR ((utilization_pct >= (0)::numeric) AND (utilization_pct <= (100)::numeric))))
)
PARTITION BY RANGE (observed_at);








--
-- Name: network_interfaces; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_interfaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    interface_key text NOT NULL,
    display_name text NOT NULL,
    interface_kind text DEFAULT 'OTHER'::text NOT NULL,
    interface_role text DEFAULT 'UNKNOWN'::text NOT NULL,
    mac_address macaddr,
    if_index integer,
    nominal_speed_bps bigint,
    is_protected boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    is_managed boolean DEFAULT false NOT NULL,
    display_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    managed_resource_id uuid,
    CONSTRAINT network_interfaces_if_index_check CHECK (((if_index IS NULL) OR (if_index >= 0))),
    CONSTRAINT network_interfaces_key_check CHECK (((char_length(btrim(interface_key)) >= 1) AND (char_length(btrim(interface_key)) <= 160))),
    CONSTRAINT network_interfaces_kind_check CHECK ((interface_kind = ANY (ARRAY['ETHERNET'::text, 'WIRELESS'::text, 'WIREGUARD'::text, 'BRIDGE'::text, 'VLAN'::text, 'LOOPBACK'::text, 'OTHER'::text]))),
    CONSTRAINT network_interfaces_metadata_object_check CHECK ((jsonb_typeof(display_metadata) = 'object'::text)),
    CONSTRAINT network_interfaces_name_check CHECK (((char_length(btrim(display_name)) >= 1) AND (char_length(btrim(display_name)) <= 160))),
    CONSTRAINT network_interfaces_protected_role_check CHECK (((interface_role <> ALL (ARRAY['WAN'::text, 'UPLINK'::text, 'MANAGEMENT'::text])) OR is_protected)),
    CONSTRAINT network_interfaces_role_check CHECK ((interface_role = ANY (ARRAY['WAN'::text, 'LAN'::text, 'ACCESS'::text, 'UPLINK'::text, 'MANAGEMENT'::text, 'UNKNOWN'::text]))),
    CONSTRAINT network_interfaces_sort_order_check CHECK ((sort_order >= 0)),
    CONSTRAINT network_interfaces_speed_check CHECK (((nominal_speed_bps IS NULL) OR (nominal_speed_bps > 0)))
);








--
-- Name: COLUMN network_interfaces.managed_resource_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.network_interfaces.managed_resource_id IS 'Tenant-bound immutable resource link used for command authorization; display names never authorize.';








--
-- Name: network_maintenance_windows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_maintenance_windows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    status text DEFAULT 'SCHEDULED'::text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    created_by uuid NOT NULL,
    request_hash text NOT NULL,
    idempotency_key text NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancellation_reason text,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_maintenance_windows_cancel_check CHECK ((((status = 'CANCELLED'::text) = (cancelled_at IS NOT NULL)) AND ((cancelled_at IS NULL) = (cancelled_by IS NULL)) AND ((cancellation_reason IS NULL) OR ((char_length(btrim(cancellation_reason)) >= 8) AND (char_length(btrim(cancellation_reason)) <= 1000))))),
    CONSTRAINT network_maintenance_windows_hash_check CHECK ((request_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT network_maintenance_windows_idempotency_check CHECK ((idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'::text)),
    CONSTRAINT network_maintenance_windows_reason_check CHECK (((char_length(btrim(reason)) >= 8) AND (char_length(btrim(reason)) <= 1000))),
    CONSTRAINT network_maintenance_windows_status_check CHECK ((status = ANY (ARRAY['SCHEDULED'::text, 'ACTIVE'::text, 'COMPLETED'::text, 'CANCELLED'::text]))),
    CONSTRAINT network_maintenance_windows_time_check CHECK (((ends_at > starts_at) AND (ends_at <= (starts_at + '30 days'::interval)))),
    CONSTRAINT network_maintenance_windows_version_check CHECK ((version > 0))
);








--
-- Name: network_managed_resources; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_managed_resources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    device_id uuid NOT NULL,
    resource_kind text NOT NULL,
    stable_key text NOT NULL,
    display_name text NOT NULL,
    enrolled_role text,
    protected boolean DEFAULT true NOT NULL,
    ownership_marker text,
    enrollment_state text DEFAULT 'DISCOVERED'::text NOT NULL,
    last_verified_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT network_managed_resources_display_name_check CHECK (((char_length(btrim(display_name)) >= 1) AND (char_length(btrim(display_name)) <= 160))),
    CONSTRAINT network_managed_resources_enrollment_state_check CHECK ((enrollment_state = ANY (ARRAY['DISCOVERED'::text, 'ENROLLED'::text, 'REVOKED'::text]))),
    CONSTRAINT network_managed_resources_kind_fields_check CHECK ((((resource_kind = 'INTERFACE'::text) AND (enrolled_role = ANY (ARRAY['WAN'::text, 'LAN'::text, 'ACCESS'::text, 'UPLINK'::text, 'MANAGEMENT'::text, 'UNKNOWN'::text])) AND (ownership_marker = 'routeros-default-name'::text) AND (stable_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'::text)) OR ((resource_kind = 'MANAGED_USER'::text) AND (enrolled_role IS NULL) AND (ownership_marker ~ '^ihomecrm-network-center:v1:[A-Za-z0-9][A-Za-z0-9._-]{7,63}$'::text)) OR ((resource_kind = 'ROUTER'::text) AND (enrolled_role IS NULL) AND (ownership_marker IS NOT NULL)))),
    CONSTRAINT network_managed_resources_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT network_managed_resources_resource_kind_check CHECK ((resource_kind = ANY (ARRAY['ROUTER'::text, 'INTERFACE'::text, 'MANAGED_USER'::text]))),
    CONSTRAINT network_managed_resources_stable_key_check CHECK (((char_length(btrim(stable_key)) >= 1) AND (char_length(btrim(stable_key)) <= 160)))
);

ALTER TABLE ONLY public.network_managed_resources FORCE ROW LEVEL SECURITY;








--
-- Name: TABLE network_managed_resources; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_managed_resources IS 'Authoritative immutable RouterOS resource identity; browser roles have no direct access.';








--
-- Name: network_metric_hourly; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_metric_hourly (
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    series_kind text NOT NULL,
