    min_value numeric,
    max_value numeric,
    avg_value numeric,
    p95_value numeric,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_metric_hourly_count_check CHECK ((sample_count > 0)),
    CONSTRAINT network_metric_hourly_kind_check CHECK ((series_kind = ANY (ARRAY['DEVICE'::text, 'INTERFACE'::text]))),
    CONSTRAINT network_metric_hourly_name_check CHECK ((metric_name ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT network_metric_hourly_unit_check CHECK (((char_length(unit) >= 1) AND (char_length(unit) <= 32)))
);








--
-- Name: TABLE network_metric_hourly; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_metric_hourly IS 'Repeat-safe hourly Network Center metric rollups retained for 13 months.';








--
-- Name: network_org_mutation_gates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_org_mutation_gates (
    organization_id uuid NOT NULL,
    mutations_paused boolean DEFAULT false NOT NULL,
    paused_reason text,
    paused_at timestamp with time zone,
    paused_by uuid,
    resumed_reason text,
    resumed_at timestamp with time zone,
    resumed_by uuid,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT network_org_mutation_gates_paused_check CHECK (((mutations_paused = false) OR ((paused_at IS NOT NULL) AND (paused_by IS NOT NULL) AND (paused_reason IS NOT NULL) AND ((char_length(btrim(paused_reason)) >= 3) AND (char_length(btrim(paused_reason)) <= 500))))),
    CONSTRAINT network_org_mutation_gates_resume_check CHECK ((((resumed_at IS NULL) = (resumed_by IS NULL)) AND ((resumed_reason IS NULL) OR ((char_length(btrim(resumed_reason)) >= 3) AND (char_length(btrim(resumed_reason)) <= 500))))),
    CONSTRAINT network_org_mutation_gates_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.network_org_mutation_gates FORCE ROW LEVEL SECURITY;








--
-- Name: TABLE network_org_mutation_gates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_org_mutation_gates IS 'Organization-wide Network Center mutation gate; no browser role has direct access and no credential material is stored. Enforced by app_private.network_center_require_execute_v1 and by both worker claim paths.';








--
-- Name: network_outbox_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_outbox_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    outbox_event_id uuid NOT NULL,
    channel text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_token uuid,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    last_error text,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_outbox_deliveries_attempt_check CHECK (((attempt_count >= 0) AND (attempt_count <= 100))),
    CONSTRAINT network_outbox_deliveries_channel_check CHECK ((channel = ANY (ARRAY['IN_APP'::text, 'EMAIL'::text, 'WEBHOOK'::text]))),
    CONSTRAINT network_outbox_deliveries_delivered_check CHECK (((status = 'DELIVERED'::text) = (delivered_at IS NOT NULL))),
    CONSTRAINT network_outbox_deliveries_error_check CHECK (((last_error IS NULL) OR (char_length(last_error) <= 2000))),
    CONSTRAINT network_outbox_deliveries_lease_check CHECK ((((lease_token IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_token IS NOT NULL) AND (lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT network_outbox_deliveries_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'DELIVERING'::text, 'DELIVERED'::text, 'FAILED'::text, 'DEAD'::text])))
);








--
-- Name: network_outbox_events; Type: TABLE; Schema: public; Owner: -
--

