    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    payload jsonb NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_outbox_events_aggregate_check CHECK ((aggregate_type ~ '^[a-z][a-z0-9_.-]{2,63}$'::text)),
    CONSTRAINT network_outbox_events_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 65536))),
    CONSTRAINT network_outbox_events_type_check CHECK ((event_type ~ '^[a-z][a-z0-9_.-]{2,99}$'::text))
);








--
-- Name: TABLE network_outbox_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_outbox_events IS 'Immutable domain event source; delivery retries live in network_outbox_deliveries.';








--
-- Name: network_site_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_site_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    monitoring_enabled boolean DEFAULT true NOT NULL,
    changes_paused boolean DEFAULT false NOT NULL,
    poll_interval_seconds integer DEFAULT 60 NOT NULL,
    offline_after_seconds integer DEFAULT 180 NOT NULL,
    latency_warning_ms integer DEFAULT 150 NOT NULL,
    packet_loss_warning_pct numeric(5,2) DEFAULT 10 NOT NULL,
    backup_max_age_hours integer DEFAULT 168 NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    backup_time_local time without time zone DEFAULT '03:00:00'::time without time zone NOT NULL,
    alert_sensitivity text DEFAULT 'STANDARD'::text NOT NULL,
    dependency_grouping boolean DEFAULT true NOT NULL,
    rollout_state text DEFAULT 'OFF'::text NOT NULL,
    CONSTRAINT network_site_settings_alert_sensitivity_check CHECK ((alert_sensitivity = ANY (ARRAY['STANDARD'::text, 'STRICT'::text]))),
    CONSTRAINT network_site_settings_backup_check CHECK (((backup_max_age_hours >= 1) AND (backup_max_age_hours <= 8760))),
    CONSTRAINT network_site_settings_latency_check CHECK (((latency_warning_ms >= 1) AND (latency_warning_ms <= 60000))),
    CONSTRAINT network_site_settings_loss_check CHECK (((packet_loss_warning_pct >= (0)::numeric) AND (packet_loss_warning_pct <= (100)::numeric))),
    CONSTRAINT network_site_settings_offline_check CHECK (((offline_after_seconds >= 60) AND (offline_after_seconds <= 86400))),
    CONSTRAINT network_site_settings_poll_check CHECK (((poll_interval_seconds >= 30) AND (poll_interval_seconds <= 3600))),
    CONSTRAINT network_site_settings_rollout_state_check CHECK ((rollout_state = ANY (ARRAY['OFF'::text, 'READ_ONLY'::text, 'EXECUTE'::text]))),
    CONSTRAINT network_site_settings_version_check CHECK ((version > 0))
);








--
-- Name: network_sla_daily; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_sla_daily (
    organization_id uuid NOT NULL,
    building_id uuid NOT NULL,
    sla_day date NOT NULL,
    sample_count bigint NOT NULL,
    total_seconds bigint DEFAULT 86400 NOT NULL,
    excluded_maintenance_seconds bigint DEFAULT 0 NOT NULL,
    eligible_seconds bigint DEFAULT 86400 NOT NULL,
    uptime_seconds bigint NOT NULL,
    outage_seconds bigint NOT NULL,
    uptime_pct numeric(7,4) NOT NULL,
    incident_count integer DEFAULT 0 NOT NULL,
    mttr_seconds numeric(14,2),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT network_sla_daily_counts_check CHECK (((sample_count > 0) AND (incident_count >= 0))),
    CONSTRAINT network_sla_daily_mttr_check CHECK (((mttr_seconds IS NULL) OR (mttr_seconds >= (0)::numeric))),
    CONSTRAINT network_sla_daily_pct_check CHECK (((uptime_pct >= (0)::numeric) AND (uptime_pct <= (100)::numeric))),
    CONSTRAINT network_sla_daily_seconds_check CHECK ((((total_seconds >= 1) AND (total_seconds <= 86400)) AND ((excluded_maintenance_seconds >= 0) AND (excluded_maintenance_seconds <= total_seconds)) AND (eligible_seconds = (total_seconds - excluded_maintenance_seconds)) AND ((uptime_seconds >= 0) AND (uptime_seconds <= eligible_seconds)) AND (outage_seconds = (eligible_seconds - uptime_seconds))))
);








--
-- Name: TABLE network_sla_daily; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.network_sla_daily IS 'Repeat-safe daily building SLA retained for 36 months.';








