    CONSTRAINT openclaw_delivery_attempts_claim_generation_check CHECK ((claim_generation > 0)),
    CONSTRAINT openclaw_delivery_attempts_delivery_evidence_hash_check CHECK ((delivery_evidence_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_delivery_attempts_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['OUTBOX_DELIVERY'::text, 'OUTBOX_PRE_HANDOFF'::text]))),
    CONSTRAINT openclaw_delivery_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['SENT'::text, 'FAILED'::text, 'UNKNOWN'::text, 'SAFE_RETRY'::text]))),
    CONSTRAINT openclaw_delivery_attempts_possible_handoff_prefix_length_check CHECK ((possible_handoff_prefix_length >= 0)),
    CONSTRAINT openclaw_delivery_attempts_total_part_count_check CHECK (((total_part_count > 0) AND (total_part_count <= 20)))
);

