CREATE TABLE public.openclaw_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    lifecycle_state text DEFAULT 'DRAFT'::text NOT NULL,
    current_version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT openclaw_policies_current_version_check CHECK ((current_version >= 0)),
    CONSTRAINT openclaw_policies_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text])))
);

ALTER TABLE ONLY public.openclaw_policies FORCE ROW LEVEL SECURITY;








--
-- Name: openclaw_policy_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.openclaw_policy_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    account_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    version bigint NOT NULL,
    lifecycle_state text NOT NULL,
    timezone text NOT NULL,
    quiet_hours_start time without time zone DEFAULT '20:00:00'::time without time zone NOT NULL,
    quiet_hours_end time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    rate_limits jsonb NOT NULL,
    consent_required boolean DEFAULT true NOT NULL,
    disclosure_version integer NOT NULL,
    policy_payload jsonb NOT NULL,
    payload_hash text NOT NULL,
    published_at timestamp with time zone,
    archived_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT openclaw_policy_versions_check CHECK ((((lifecycle_state = 'DRAFT'::text) AND (published_at IS NULL)) OR ((lifecycle_state = ANY (ARRAY['PUBLISHED'::text, 'ARCHIVED'::text])) AND (published_at IS NOT NULL)))),
    CONSTRAINT openclaw_policy_versions_disclosure_version_check CHECK ((disclosure_version > 0)),
    CONSTRAINT openclaw_policy_versions_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT openclaw_policy_versions_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_policy_versions_rate_limits_check CHECK ((jsonb_typeof(rate_limits) = 'object'::text)),
    CONSTRAINT openclaw_policy_versions_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.openclaw_policy_versions FORCE ROW LEVEL SECURITY;








--
-- Name: openclaw_qr_challenges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.openclaw_qr_challenges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    account_id uuid NOT NULL,
    cell_id uuid NOT NULL,
    challenge_version integer DEFAULT 1 NOT NULL,
    challenge_status text DEFAULT 'PENDING'::text NOT NULL,
    active_slot boolean DEFAULT true NOT NULL,
    ciphertext bytea,
    cipher_iv bytea,
    auth_tag bytea,
    actor_id uuid NOT NULL,
    auth_session_hash text NOT NULL,
    browser_nonce_hash text NOT NULL,
    issued_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    runtime_command_id uuid,
    material_version integer DEFAULT 0 NOT NULL,
    material_published_at timestamp with time zone,
    poll_window_started_at timestamp with time zone,
    poll_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT openclaw_qr_challenges_auth_session_hash_check CHECK ((auth_session_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_qr_challenges_auth_tag_check CHECK ((octet_length(auth_tag) = 16)),
    CONSTRAINT openclaw_qr_challenges_browser_nonce_hash_check CHECK ((browser_nonce_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_qr_challenges_challenge_status_check CHECK ((challenge_status = ANY (ARRAY['PENDING'::text, 'CONSUMED'::text, 'EXPIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT openclaw_qr_challenges_challenge_version_check CHECK ((challenge_version > 0)),
    CONSTRAINT openclaw_qr_challenges_check CHECK ((expires_at = (issued_at + '00:02:00'::interval))),
    CONSTRAINT openclaw_qr_challenges_check1 CHECK (((active_slot AND (challenge_status = 'PENDING'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL)) OR (NOT active_slot))),
    CONSTRAINT openclaw_qr_challenges_check2 CHECK (((challenge_status = 'CONSUMED'::text) = (consumed_at IS NOT NULL))),
    CONSTRAINT openclaw_qr_challenges_cipher_iv_check CHECK ((octet_length(cipher_iv) = 12)),
    CONSTRAINT openclaw_qr_material_consistency_check CHECK ((((material_version = 0) AND (ciphertext IS NULL) AND (cipher_iv IS NULL) AND (auth_tag IS NULL) AND (material_published_at IS NULL)) OR ((material_version = 1) AND (ciphertext IS NOT NULL) AND (cipher_iv IS NOT NULL) AND (auth_tag IS NOT NULL) AND (material_published_at IS NOT NULL)))),
    CONSTRAINT openclaw_qr_material_version_check CHECK ((material_version = ANY (ARRAY[0, 1]))),
    CONSTRAINT openclaw_qr_poll_count_check CHECK (((poll_count >= 0) AND (poll_count <= 10))),
    CONSTRAINT openclaw_qr_poll_window_consistency_check CHECK (((poll_count = 0) = (poll_window_started_at IS NULL)))
);

ALTER TABLE ONLY public.openclaw_qr_challenges FORCE ROW LEVEL SECURITY;








