-- Name: openclaw_unknown_resolutions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.openclaw_unknown_resolutions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    account_id uuid NOT NULL,
    outbox_id uuid NOT NULL,
    resolution_version smallint DEFAULT 1 NOT NULL,
    outcome text NOT NULL,
    new_outbox_id uuid,
    authoritative_evidence_domain text DEFAULT 'ihome-openclaw-unknown-authority-v1\0'::text NOT NULL,
    authoritative_evidence_hash text NOT NULL,
    operator_evidence_hash text NOT NULL,
    reason_code text NOT NULL,
    resolved_by uuid NOT NULL,
    resolved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    client_operation_id uuid NOT NULL,
    request_hash text NOT NULL,
    CONSTRAINT openclaw_unknown_resolutions_authoritative_evidence_domai_check CHECK ((authoritative_evidence_domain = 'ihome-openclaw-unknown-authority-v1\0'::text)),
    CONSTRAINT openclaw_unknown_resolutions_authoritative_evidence_hash_check CHECK ((authoritative_evidence_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_unknown_resolutions_check CHECK (((new_outbox_id IS NULL) OR (new_outbox_id <> outbox_id))),
    CONSTRAINT openclaw_unknown_resolutions_check1 CHECK (((outcome = 'NEW_INTENT_CREATED'::text) = (new_outbox_id IS NOT NULL))),
    CONSTRAINT openclaw_unknown_resolutions_operator_evidence_hash_check CHECK ((operator_evidence_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_unknown_resolutions_outcome_check CHECK ((outcome = ANY (ARRAY['CONFIRMED_SENT'::text, 'CONFIRMED_FAILED'::text, 'NEW_INTENT_CREATED'::text]))),
    CONSTRAINT openclaw_unknown_resolutions_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT openclaw_unknown_resolutions_resolution_version_check CHECK ((resolution_version = 1))
);

ALTER TABLE ONLY public.openclaw_unknown_resolutions FORCE ROW LEVEL SECURITY;








