--
-- Name: payment_receipt_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.payment_receipt_events WITH (security_invoker='true') AS
 SELECT tender.id AS source_id,
    'COLLECTION'::text AS event_kind,
    collection.organization_id,
    collection.invoice_id,
    collection.id AS collection_id,
    tender.payment_id,
    tender.payment_method,
    collection.collection_date AS payment_date,
    tender.retained_amount AS collected_amount,
    tender.applied_amount,
    tender.credit_amount,
    tender.created_at
   FROM (public.invoice_payment_tenders tender
     JOIN public.invoice_payment_collections collection ON (((collection.id = tender.collection_id) AND (collection.organization_id = tender.organization_id))))
UNION ALL
 SELECT tender.id AS source_id,
    'COLLECTION_REVERSAL'::text AS event_kind,
    collection.organization_id,
    collection.invoice_id,
    collection.id AS collection_id,
    tender.payment_id,
    tender.payment_method,
    collection.reversal_date AS payment_date,
    (- tender.retained_amount) AS collected_amount,
    (- tender.applied_amount) AS applied_amount,
    (- tender.credit_amount) AS credit_amount,
    collection.reversed_at AS created_at
   FROM (public.invoice_payment_tenders tender
     JOIN public.invoice_payment_collections collection ON (((collection.id = tender.collection_id) AND (collection.organization_id = tender.organization_id))))
  WHERE ((collection.status = 'REVERSED'::text) AND (collection.reversal_date IS NOT NULL))
UNION ALL
 SELECT legacy.id AS source_id,
    'LEGACY_PAYMENT'::text AS event_kind,
    legacy.organization_id,
    legacy.invoice_id,
    NULL::uuid AS collection_id,
    legacy.id AS payment_id,
    legacy.payment_method,
    legacy.payment_date,
    legacy.retained_amount AS collected_amount,
    legacy.applied_amount,
    legacy.credit_amount,
    legacy.created_at
   FROM public.legacy_payment_receipt_semantics legacy
UNION ALL
 SELECT legacy.id AS source_id,
    'LEGACY_REVERSAL'::text AS event_kind,
    legacy.organization_id,
    legacy.invoice_id,
    NULL::uuid AS collection_id,
    legacy.id AS payment_id,
    legacy.payment_method,
    COALESCE(reversal.event_date, (legacy.reversed_at)::date) AS payment_date,
    (- legacy.retained_amount) AS collected_amount,
    (- legacy.applied_amount) AS applied_amount,
    (- legacy.credit_amount) AS credit_amount,
    legacy.reversed_at AS created_at
   FROM (public.legacy_payment_receipt_semantics legacy
     LEFT JOIN LATERAL ( SELECT min(reversal_voucher.voucher_date) AS event_date
           FROM (public.income_expenses source_voucher
             JOIN public.income_expenses reversal_voucher ON (((reversal_voucher.reversal_of_income_expense_id = source_voucher.id) AND (reversal_voucher.deleted_at IS NULL) AND (reversal_voucher.approval_status = 'APPROVED'::text))))
          WHERE (source_voucher.payment_id = legacy.id)) reversal ON (true))
  WHERE (legacy.reversed_at IS NOT NULL);








--
-- Name: VIEW payment_receipt_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.payment_receipt_events IS 'Signed retained/applied receipt events using the economic collection or reversal date.';








--
-- Name: permission_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.permission_definitions (
    key text NOT NULL,
    resource text NOT NULL,
    action text NOT NULL,
    sensitivity text NOT NULL,
    permission_domain text DEFAULT 'TENANT'::text NOT NULL,
    scope_kinds text[] DEFAULT ARRAY['ORGANIZATION'::text] NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    scope_match_mode text DEFAULT 'ANY_MATCH'::text NOT NULL,
    requires_cashbook_possession boolean DEFAULT false NOT NULL,
    accepted_possession_kinds text[] DEFAULT ARRAY[]::text[] NOT NULL,
    required_dimensions text[] DEFAULT ARRAY[]::text[] NOT NULL,
    CONSTRAINT permission_definitions_permission_domain_check CHECK ((permission_domain = ANY (ARRAY['TENANT'::text, 'PLATFORM'::text]))),
    CONSTRAINT permission_definitions_possession_contract_check CHECK ((((NOT requires_cashbook_possession) AND (cardinality(accepted_possession_kinds) = 0)) OR (requires_cashbook_possession AND ('CASHBOOK'::text = ANY (scope_kinds)) AND (cardinality(accepted_possession_kinds) > 0) AND (accepted_possession_kinds <@ ARRAY['CUSTODIAN'::text, 'OPERATOR'::text, 'KNOWER'::text])))),
    CONSTRAINT permission_definitions_required_dimensions_check CHECK ((required_dimensions <@ ARRAY['BUILDING'::text, 'CASHBOOK'::text])),
    CONSTRAINT permission_definitions_scope_match_mode_check CHECK ((scope_match_mode = 'ANY_MATCH'::text)),
    CONSTRAINT permission_definitions_sensitivity_check CHECK ((sensitivity = ANY (ARRAY['VIEW'::text, 'MANAGE'::text, 'ELEVATED'::text, 'PLATFORM'::text])))
);








