--
-- Name: profit_monthly; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profit_monthly (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    building_id uuid NOT NULL,
    period_month date NOT NULL,
    computed_profit numeric(15,2) DEFAULT 0 NOT NULL,
    adjusted_profit numeric(15,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    note text,
    locked_at timestamp with time zone,
    locked_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    management_salary numeric(15,2) DEFAULT 0 NOT NULL,
    organization_id uuid NOT NULL,
    adjustment_amount numeric(15,2) DEFAULT 0 NOT NULL,
    adjustment_reason text,
    adjustment_by uuid,
    adjustment_at timestamp with time zone,
    source_revenue numeric(15,2),
    source_expense numeric(15,2),
    source_net_profit numeric(15,2),
    source_hash text NOT NULL,
    source_captured_at timestamp with time zone NOT NULL,
    is_stale boolean DEFAULT true NOT NULL,
    stale_reason text,
    revision_number bigint DEFAULT 1 NOT NULL,
    shareholder_percent_total numeric(9,4) DEFAULT 0 NOT NULL,
    shareholder_allocated_amount numeric(15,2) DEFAULT 0 NOT NULL,
    unallocated_profit numeric(15,2) DEFAULT 0 NOT NULL,
    unallocated_disposition text,
    unallocated_disposition_reason text,
    CONSTRAINT profit_monthly_adjustment_equation_v2 CHECK ((adjusted_profit = (computed_profit + adjustment_amount))),
    CONSTRAINT profit_monthly_adjustment_reason_v2 CHECK (((adjustment_amount = (0)::numeric) OR ((adjustment_reason IS NOT NULL) AND ((char_length(btrim(adjustment_reason)) >= 8) AND (char_length(btrim(adjustment_reason)) <= 500)) AND (is_stale OR ((adjustment_by IS NOT NULL) AND (adjustment_at IS NOT NULL)))))),
    CONSTRAINT profit_monthly_allocation_amounts_v3 CHECK (((shareholder_percent_total <> 'NaN'::numeric) AND ((shareholder_percent_total >= (0)::numeric) AND (shareholder_percent_total <= (100)::numeric)) AND (shareholder_allocated_amount <> 'NaN'::numeric) AND (unallocated_profit <> 'NaN'::numeric))),
    CONSTRAINT profit_monthly_locked_source_v2 CHECK (((status <> 'LOCKED'::text) OR is_stale OR ((source_revenue IS NOT NULL) AND (source_expense IS NOT NULL) AND (source_net_profit IS NOT NULL)))),
    CONSTRAINT profit_monthly_period_first_day_v2 CHECK ((period_month = (date_trunc('month'::text, (period_month)::timestamp with time zone))::date)),
    CONSTRAINT profit_monthly_revision_positive_v2 CHECK ((revision_number >= 1)),
    CONSTRAINT profit_monthly_source_hash_v2 CHECK ((source_hash ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT profit_monthly_source_totals_v2 CHECK (((source_revenue IS NULL) OR (source_expense IS NULL) OR (source_net_profit IS NULL) OR (source_net_profit = (source_revenue - source_expense)))),
    CONSTRAINT profit_monthly_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'LOCKED'::text]))),
    CONSTRAINT profit_monthly_unallocated_disposition_v3 CHECK (((unallocated_disposition IS NULL) OR (unallocated_disposition = ANY (ARRAY['RETAINED_EARNINGS'::text, 'CARRY_FORWARD'::text, 'LEGACY_RETAINED_UNALLOCATED'::text])))),
    CONSTRAINT profit_monthly_unallocated_reason_v3 CHECK (((unallocated_disposition IS NULL) OR ((unallocated_disposition_reason IS NOT NULL) AND ((char_length(btrim(unallocated_disposition_reason)) >= 8) AND (char_length(btrim(unallocated_disposition_reason)) <= 500)))))
);








--
-- Name: COLUMN profit_monthly.management_salary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.management_salary IS 'Snapshot tổng lương điều hành trừ ở nhà/tháng này. distributable = adjusted_profit - management_salary; cổ đông chia trên distributable.';








--
-- Name: COLUMN profit_monthly.adjustment_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.adjustment_amount IS 'Explicit close adjustment. adjusted_profit = computed_profit + adjustment_amount.';








--
-- Name: COLUMN profit_monthly.source_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.source_hash IS 'MD5 of the canonical accrual/config snapshot used by Profit Close V2.';








--
-- Name: COLUMN profit_monthly.is_stale; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.is_stale IS 'Persisted stale marker for legacy/unlocked rows. Preview additionally derives SOURCE_HASH_MISMATCH from the current canonical per-building hash.';








--
-- Name: COLUMN profit_monthly.unallocated_profit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.unallocated_profit IS 'distributable_profit - shareholder_allocated_amount. Never silently discarded.';








--
-- Name: COLUMN profit_monthly.unallocated_disposition; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profit_monthly.unallocated_disposition IS 'RETAINED_EARNINGS or CARRY_FORWARD for V3 closes; LEGACY_RETAINED_UNALLOCATED marks pre-V3 snapshots.';








