    CONSTRAINT profit_payout_reservations_reservation_state_check CHECK ((reservation_state = ANY (ARRAY['HELD'::text, 'CONSUMED'::text, 'RELEASED'::text, 'REVERSED'::text]))),
    CONSTRAINT profit_payout_reservations_source_check CHECK ((reservation_source = ANY (ARRAY['CANONICAL_V1'::text, 'LEGACY_BACKFILL'::text])))
);








