--
-- Name: v_termination_calculation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_termination_calculation WITH (security_invoker='true') AS
 SELECT ct.id AS termination_id,
    ct.contract_id,
    c.rent_price,
    c.total_deposit,
    ct.actual_move_out_date,
    c.end_date AS original_end_date,
        CASE
            WHEN (ct.actual_move_out_date < c.end_date) THEN (c.end_date - ct.actual_move_out_date)
            ELSE 0
        END AS early_days,
    ct.prorated_rent,
    ct.prorated_services,
    ct.early_termination_fee,
    ct.damage_fee,
    ct.cleaning_fee,
    ct.notice_violation_fee,
    ct.other_fees,
    ct.outstanding_debt,
    ct.total_deductions,
    ct.total_deposit AS deposit_held,
    ct.refund_amount,
    ct.status,
    ct.termination_type
   FROM (public.contract_terminations ct
     JOIN public.contracts c ON ((ct.contract_id = c.id)));








