CREATE POLICY payments_delete_rbac ON public.payments FOR DELETE USING ((( SELECT public.is_super_admin() AS is_super_admin) OR ( SELECT public.is_admin() AS is_admin) OR ( SELECT public.has_perm_full_scope('invoices'::text, 'delete'::text) AS has_perm_full_scope) OR (( SELECT i.building_id
   FROM public.invoices i
  WHERE (i.id = payments.invoice_id)) IN ( SELECT public.permitted_building_ids('invoices'::text, 'delete'::text) AS permitted_building_ids))));








